            COALESCE(item.query_version_id::text, '') || '|' ||
            COALESCE(item.publication_release_id::text, '') || '|' ||
            COALESCE(pg_catalog.encode(item.target_sha256, 'hex'), ''),
            E'\n' ORDER BY item.legacy_endpoint_id
