--
-- Name: analytics_catalog_activation_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_activation_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' OR ROW(
        NEW.projection_receipt_id,NEW.attempt_receipt_id,
        NEW.component_id,NEW.package_id,NEW.package_version,
        NEW.release_id,NEW.content_sha256,NEW.activated_at
    ) IS DISTINCT FROM ROW(
        OLD.projection_receipt_id,OLD.attempt_receipt_id,
        OLD.component_id,OLD.package_id,OLD.package_version,
        OLD.release_id,OLD.content_sha256,OLD.activated_at
    ) OR
       (OLD.superseded_at IS NOT NULL AND NEW IS DISTINCT FROM OLD) OR
       (OLD.superseded_at IS NULL AND NEW.superseded_at IS NOT NULL AND
        NEW.superseded_at<OLD.activated_at) OR
       (OLD.superseded_at IS NULL AND NEW.superseded_at IS NULL AND
        NEW IS DISTINCT FROM OLD) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog activation evidence is immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_activation_guard_v1() OWNER TO harpy_owner;

--
-- Name: analytics_catalog_attempt_evidence_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_attempt_evidence_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog projection attempt is immutable';
    END IF;
    IF ROW(
        NEW.receipt_id,NEW.projection_receipt_id,NEW.actor_id,
        NEW.idempotency_key,NEW.request_sha256,NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.receipt_id,OLD.projection_receipt_id,OLD.actor_id,
        OLD.idempotency_key,OLD.request_sha256,OLD.created_at
    ) OR NEW.updated_at<OLD.updated_at OR
       (OLD.ready_at IS NOT NULL AND NEW IS DISTINCT FROM OLD) OR
       (OLD.ready_at IS NULL AND NEW.ready_at IS NOT NULL AND (
            NEW.ready_at<OLD.updated_at OR NEW.updated_at<>NEW.ready_at
       )) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog projection attempt update differs';
    END IF;
    RETURN NEW;
END;
$$;


