--
-- Name: analytics_catalog_blocker_snapshot_v2(uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_blocker_snapshot_v2(p_component_id uuid, p_reference_epoch bigint, p_generation bigint) RETURNS TABLE(blockers jsonb, zero_digest text, analytics_kind text, root_id uuid, head_version_id uuid, root_reference_epoch bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_component_kind text;
    v_package_id uuid;
    v_package_version text;
    v_release_id uuid;
BEGIN
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_reference_epoch<1 OR p_generation<1 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog blocker snapshot input is invalid';
    END IF;
    SELECT projection.analytics_kind,projection.operational_resource_id,projection.published_version_id,component.component_kind,
        projection.package_id,projection.package_version,projection.release_id
    INTO analytics_kind,root_id,head_version_id,v_component_kind,v_package_id,v_package_version,v_release_id
    FROM analytics_catalog_components AS component
    JOIN analytics_catalog_component_heads AS head
      ON head.component_id=component.component_id
     AND head.content_sha256=component.content_sha256
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=head.projection_receipt_id
     AND projection.component_id=head.component_id
     AND projection.package_id=head.package_id
     AND projection.package_version=head.package_version
     AND projection.release_id=head.release_id
     AND projection.content_sha256=head.content_sha256
    JOIN analytics_catalog_definitions AS definition
      ON definition.component_id=projection.component_id
     AND definition.package_id=projection.package_id
     AND definition.package_version=projection.package_version
     AND definition.release_id=projection.release_id
     AND definition.content_sha256=projection.content_sha256
     AND definition.operational_resource_id=projection.operational_resource_id
     AND definition.published_version_id=projection.published_version_id
    WHERE component.component_id=p_component_id
      AND component.owner_generation=p_generation
      AND component.writer_state='v2'
      AND component.lifecycle_state='RETIRED'
      AND projection.operational_state='ready'
      AND projection.ready_at IS NOT NULL
    FOR SHARE OF component,head,projection,definition;
    IF NOT FOUND OR
       (analytics_kind='endpoint' AND v_component_kind<>'ENDPOINT') OR
       (analytics_kind='dashboard' AND v_component_kind<>'DASHBOARD') THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog blocker target differs';
    END IF;
    IF analytics_kind='endpoint' THEN
        SELECT root.reference_epoch INTO root_reference_epoch
        FROM analytics_saved_queries AS root
        JOIN analytics_saved_query_versions AS version_row
          ON version_row.query_id=root.id
         AND version_row.id=head_version_id
        WHERE root.id=root_id AND root.lifecycle_state='retired'
          AND version_row.version_state IN (
              'published','needs_revalidation','retired'
          )
        FOR SHARE OF root,version_row;
    ELSE
        SELECT root.reference_epoch INTO root_reference_epoch
        FROM analytics_dashboards AS root
        JOIN analytics_dashboard_versions AS version_row
          ON version_row.dashboard_id=root.id
         AND version_row.id=head_version_id
        WHERE root.id=root_id AND root.lifecycle_state='retired'
          AND version_row.version_state IN ('published','retired')
        FOR SHARE OF root,version_row;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog blocker root differs';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:legal-hold',6100
    ));
    WITH root_versions AS (
        SELECT version_row.id,'query'::text AS resource_kind,
            'query_version'::text AS target_kind
        FROM analytics_saved_query_versions AS version_row
        WHERE analytics_kind='endpoint' AND version_row.query_id=root_id
        UNION ALL
        SELECT version_row.id,'dashboard'::text,'dashboard_version'::text
        FROM analytics_dashboard_versions AS version_row
        WHERE analytics_kind='dashboard' AND version_row.dashboard_id=root_id
    ), publication_ids AS (
        SELECT release.id
        FROM analytics_publication_releases AS release
        JOIN root_versions AS version_row
          ON version_row.id=release.resource_version_id
         AND version_row.resource_kind=release.resource_kind
    ), raw_blockers AS (
        SELECT 'ANALYTICS_ACTIVE_INBOUND_REFERENCE'::text AS code,
            reference_row.reference_id::text AS identity
        FROM analytics_inbound_references AS reference_row
        WHERE reference_row.state='active' AND (
            EXISTS (
                SELECT 1 FROM root_versions AS version_row
                WHERE version_row.target_kind=reference_row.target_kind
                  AND version_row.id=reference_row.target_id
            ) OR (
                reference_row.target_kind='publication_release' AND
                reference_row.target_id IN (SELECT id FROM publication_ids)
            )
        )
        UNION ALL
        SELECT 'ANALYTICS_DASHBOARD_WIDGET_REFERENCE',
            widget.dashboard_version_id::text||':'||widget.widget_id::text
        FROM analytics_dashboard_widgets AS widget
        JOIN root_versions AS version_row
          ON version_row.resource_kind='query'
         AND version_row.id=widget.query_version_id
        WHERE NOT analytics_catalog_internal_widget_peer_v2(
            v_package_id,v_package_version,v_release_id,
            widget.dashboard_version_id
        )
        UNION ALL
        SELECT 'ANALYTICS_PUBLICATION_RELEASE_REFERENCE',id::text
        FROM publication_ids
        UNION ALL
        SELECT 'ANALYTICS_LEGAL_HOLD',hold.hold_id::text||':'||
            pg_catalog.encode(hold.reason_sha256,'hex')
        FROM analytics_legal_holds AS hold WHERE hold.state='active'
        UNION ALL
        SELECT blocker.code,blocker.digest
        FROM analytics_catalog_component_blockers AS blocker
        WHERE blocker.component_id=p_component_id
          AND blocker.active
        UNION ALL
        SELECT 'ANALYTICS_CATALOG_CANDIDATE',
            candidate.projection_receipt_id::text||':'||
            candidate.attempt_receipt_id::text
        FROM analytics_catalog_component_candidates AS candidate
        WHERE candidate.component_id=p_component_id
    ), grouped AS (
        SELECT code,pg_catalog.string_agg(
            identity,E'\\000' ORDER BY identity
        ) AS identities
        FROM raw_blockers GROUP BY code
    )
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'Owner','analytics','Code',code,'Digest',
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            'analytics-catalog-blocker.v2'||E'\\000'||p_component_id::text||
            E'\\000'||code||E'\\000'||identities,'UTF8'
        )),'hex')
    ) ORDER BY code),'[]'::jsonb) INTO blockers
    FROM grouped;
    zero_digest:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'analytics-catalog-blockers.v2'||E'\\000'||p_component_id::text||
        E'\\000'||p_reference_epoch::text||E'\\000'||analytics_kind||
        E'\\000'||v_package_id::text||E'\\000'||v_package_version||
        E'\\000'||v_release_id::text||E'\\000'||root_id::text||
        E'\\000'||head_version_id::text||
        E'\\000'||root_reference_epoch::text||E'\\000'||blockers::text,
        'UTF8'
    )),'hex');
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_blocker_snapshot_v2(p_component_id uuid, p_reference_epoch bigint, p_generation bigint) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_candidate_cleanup_v2(name, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_candidate_cleanup_v2(p_scope_schema name, p_component_id uuid, p_operation_id uuid, p_content_sha256 text, p_completed_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_attempt analytics_catalog_projection_attempts%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_content_sha256 IS NULL OR
       p_content_sha256!~'^[0-9a-f]{64}$' OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog cleanup input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT attempt.* INTO v_attempt
    FROM analytics_catalog_component_candidates AS candidate
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=candidate.projection_receipt_id
    JOIN analytics_catalog_projection_attempts AS attempt
      ON attempt.receipt_id=candidate.attempt_receipt_id
     AND attempt.projection_receipt_id=projection.receipt_id
    WHERE candidate.component_id=p_component_id
      AND candidate.content_sha256=p_content_sha256
      AND candidate.staged_operation_id=p_operation_id
    FOR UPDATE OF candidate,projection,attempt;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog cleanup candidate differs';
    END IF;
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=v_attempt.projection_receipt_id;
    IF NOT FOUND OR v_projection.operational_state<>'ready' OR
       v_projection.ready_at IS NULL OR v_attempt.ready_at IS NULL OR
       p_completed_at<v_attempt.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog cleanup candidate differs';
    END IF;
    IF v_projection.analytics_kind='endpoint' THEN
        UPDATE analytics_saved_queries
        SET lifecycle_state='retired',row_revision=row_revision+1,
            reference_epoch=reference_epoch+1,
            updated_by=v_attempt.actor_id,updated_at=p_completed_at
        WHERE id=v_projection.operational_resource_id
          AND lifecycle_state='staged';
    ELSIF v_projection.analytics_kind='dashboard' THEN
        UPDATE analytics_dashboards
        SET lifecycle_state='retired',row_revision=row_revision+1,
            reference_epoch=reference_epoch+1,
            updated_by=v_attempt.actor_id,updated_at=p_completed_at
        WHERE id=v_projection.operational_resource_id
          AND lifecycle_state='staged';
    ELSE
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog cleanup resource kind differs';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog staged resource cleanup differs';
    END IF;
    DELETE FROM analytics_catalog_component_candidates AS candidate
    WHERE candidate.component_id=p_component_id
      AND candidate.projection_receipt_id=v_projection.receipt_id
      AND candidate.attempt_receipt_id=v_attempt.receipt_id
      AND candidate.staged_operation_id=p_operation_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog candidate cleanup differs';
    END IF;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_candidate_cleanup_v2(p_scope_schema name, p_component_id uuid, p_operation_id uuid, p_content_sha256 text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_candidate_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_candidate_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM analytics_catalog_version_projections AS projection
        JOIN analytics_catalog_projection_attempts AS attempt
          ON attempt.receipt_id=NEW.attempt_receipt_id
         AND attempt.projection_receipt_id=projection.receipt_id
        WHERE projection.receipt_id=NEW.projection_receipt_id
          AND projection.component_id=NEW.component_id
          AND projection.package_id=NEW.package_id
          AND projection.package_version=NEW.package_version
          AND projection.release_id=NEW.release_id
          AND projection.owner_generation=NEW.owner_generation
          AND projection.content_sha256=NEW.content_sha256
          AND projection.operational_state='ready'
          AND projection.ready_at IS NOT NULL
          AND attempt.ready_at IS NOT NULL
          AND projection.ready_at<=NEW.prepared_at
          AND attempt.updated_at<=NEW.prepared_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog candidate lacks exact ready evidence';
    END IF;
    IF TG_OP='UPDATE' AND (
        ROW(
            NEW.component_id,NEW.projection_receipt_id,NEW.package_id,
            NEW.package_version,NEW.release_id,NEW.owner_generation,
            NEW.content_sha256
        ) IS DISTINCT FROM ROW(
            OLD.component_id,OLD.projection_receipt_id,OLD.package_id,
            OLD.package_version,OLD.release_id,OLD.owner_generation,
            OLD.content_sha256
        ) OR NEW.prepared_at<OLD.prepared_at OR
        (NEW.attempt_receipt_id=OLD.attempt_receipt_id AND
         OLD.staged_operation_id IS NOT NULL AND
         NEW.staged_operation_id IS DISTINCT FROM OLD.staged_operation_id) OR
        (NEW.attempt_receipt_id<>OLD.attempt_receipt_id AND
         NEW.staged_operation_id IS NOT NULL)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog candidate update differs';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_candidate_guard_v1() OWNER TO harpy_owner;

--
-- Name: analytics_catalog_canonical_json_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_canonical_json_v1(p_value jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_kind text;
    v_result text;
BEGIN
    v_kind:=pg_catalog.jsonb_typeof(p_value);
    IF v_kind='object' THEN
        SELECT '{'||COALESCE(pg_catalog.string_agg(
            pg_catalog.to_json(entry.key)::text||':'||
            analytics_catalog_canonical_json_v1(entry.value),
            ',' ORDER BY entry.key COLLATE "C"
        ),'')||'}' INTO v_result
        FROM pg_catalog.jsonb_each(p_value) AS entry(key,value);
        RETURN v_result;
    ELSIF v_kind='array' THEN
        SELECT '['||COALESCE(pg_catalog.string_agg(
            analytics_catalog_canonical_json_v1(entry.value),
            ',' ORDER BY entry.ordinality
        ),'')||']' INTO v_result
        FROM pg_catalog.jsonb_array_elements(p_value)
            WITH ORDINALITY AS entry(value,ordinality);
        RETURN v_result;
    ELSIF v_kind IN ('string','number','boolean','null') THEN
        RETURN p_value::text;
    END IF;
    RAISE EXCEPTION USING ERRCODE='22023',
        MESSAGE='Analytics Catalog canonical JSON input is invalid';
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_canonical_json_v1(p_value jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_component_apply_core_v2(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_component_apply_core_v2(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component analytics_catalog_components%ROWTYPE;
    v_receipt analytics_catalog_component_receipts%ROWTYPE;
    v_attempt analytics_catalog_projection_attempts%ROWTYPE;
    v_scope_schema text;
    v_has_head boolean;
    v_next text;
BEGIN
    SELECT schema_name INTO STRICT v_scope_schema FROM tenancy_schema_identity WHERE singleton;
    PERFORM analytics_assert_current_authority_v1(v_scope_schema::name);
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_owner IS DISTINCT FROM 'analytics' OR
       p_generation IS NULL OR p_generation<1 OR p_contract IS NULL OR
       p_content_sha256 IS NULL OR p_content_sha256!~'^[0-9a-f]{64}$' OR
       p_action IS NULL OR p_action NOT IN ('stage','cleanup','activate','disable','enable',
           'retire','restore') OR
       p_idempotency_key IS NULL OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog v2 component command is invalid';
    END IF;
    SELECT * INTO v_receipt FROM analytics_catalog_component_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id AND receipt.component_id=p_component_id AND receipt.action=p_action;
    IF FOUND THEN
        IF v_receipt.owner_module IS DISTINCT FROM p_owner OR
           v_receipt.owner_generation IS DISTINCT FROM p_generation OR
           v_receipt.contract IS DISTINCT FROM p_contract OR
           v_receipt.content_sha256 IS DISTINCT FROM p_content_sha256 OR
           v_receipt.idempotency_key IS DISTINCT FROM p_idempotency_key THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='Analytics Catalog v2 component receipt differs';
        END IF;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.owner_module,v_receipt.owner_generation,
            v_receipt.contract,v_receipt.content_sha256,v_receipt.action,
            v_receipt.ready,v_receipt.completed_at;
        RETURN;
    END IF;
    SELECT * INTO v_component FROM analytics_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    IF NOT FOUND OR
       v_component.component_kind NOT IN ('ENDPOINT','DASHBOARD') OR
       v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR
       v_component.contract<>p_contract OR
       p_completed_at<v_component.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog v2 component authority differs';
    END IF;
    IF p_action IN ('disable','enable','retire','restore','purge') THEN
        PERFORM analytics_catalog_component_lifecycle_v2(
            v_scope_schema::name,p_operation_id,p_component_id,p_generation,p_contract,
            p_content_sha256,p_action,p_reference_epoch,p_completed_at);
    ELSE
        SELECT EXISTS(
            SELECT 1 FROM analytics_catalog_component_heads AS head
            WHERE head.component_id=p_component_id
        ) INTO v_has_head;
        IF p_action='cleanup' THEN
            IF NOT EXISTS (
                SELECT 1 FROM analytics_catalog_component_receipts AS stage
                WHERE stage.operation_id=p_operation_id
                  AND stage.component_id=p_component_id
                  AND stage.action='stage'
                  AND stage.content_sha256=p_content_sha256
            ) THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='Analytics Catalog cleanup lacks staged evidence';
            END IF;
            v_next:=CASE
              WHEN NOT v_has_head AND v_component.lifecycle_state='STAGED'
                AND v_component.content_sha256=p_content_sha256
                THEN 'AVAILABLE'
              WHEN v_has_head AND
                   v_component.lifecycle_state IN ('ACTIVE','DISABLED')
                THEN v_component.lifecycle_state
              ELSE NULL END;
            IF v_next IS NOT NULL THEN
                PERFORM analytics_catalog_candidate_cleanup_v2(
                    v_scope_schema::name,p_component_id,p_operation_id,
                    p_content_sha256,p_completed_at
                );
            END IF;
        ELSE
            SELECT attempt.* INTO v_attempt
            FROM analytics_catalog_component_candidates AS candidate
            JOIN analytics_catalog_version_projections AS projection
              ON projection.receipt_id=candidate.projection_receipt_id
             AND projection.component_id=candidate.component_id
             AND projection.package_id=candidate.package_id
             AND projection.package_version=candidate.package_version
             AND projection.release_id=candidate.release_id
             AND projection.owner_generation=candidate.owner_generation
             AND projection.content_sha256=candidate.content_sha256
            JOIN analytics_catalog_projection_attempts AS attempt
              ON attempt.receipt_id=candidate.attempt_receipt_id
             AND attempt.projection_receipt_id=projection.receipt_id
            WHERE candidate.component_id=p_component_id
              AND candidate.owner_generation=p_generation
              AND candidate.content_sha256=p_content_sha256
              AND projection.contract=p_contract
              AND projection.operational_state='ready'
              AND attempt.ready_at IS NOT NULL
              AND attempt.idempotency_key=
                  p_operation_id::text||':'||p_component_id::text||':provision'
              AND ((p_action='stage' AND (
                    candidate.staged_operation_id IS NULL OR
                    candidate.staged_operation_id=p_operation_id
                  )) OR (p_action='activate' AND
                    candidate.staged_operation_id=p_operation_id))
            FOR UPDATE OF candidate,projection,attempt;
            IF NOT FOUND OR p_completed_at<v_attempt.updated_at THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='Analytics Catalog exact candidate is unavailable';
            END IF;
            IF p_action='stage' THEN
                UPDATE analytics_catalog_component_candidates AS candidate
                SET staged_operation_id=p_operation_id,
                    prepared_at=p_completed_at
                WHERE candidate.component_id=p_component_id
                  AND candidate.attempt_receipt_id=v_attempt.receipt_id;
                v_next:=CASE
                  WHEN NOT v_has_head AND
                       v_component.lifecycle_state='AVAILABLE' AND
                       v_component.content_sha256=p_content_sha256
                    THEN 'STAGED'
                  WHEN v_has_head AND
                       v_component.lifecycle_state IN ('ACTIVE','DISABLED')
                    THEN v_component.lifecycle_state
                  ELSE NULL END;
            ELSIF NOT EXISTS (
                SELECT 1 FROM analytics_catalog_component_receipts AS stage
                WHERE stage.operation_id=p_operation_id
                  AND stage.component_id=p_component_id
                  AND stage.action='stage'
                  AND stage.content_sha256=p_content_sha256
            ) THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='Analytics Catalog activation lacks staged evidence';
            ELSE
                v_next:=CASE
                  WHEN NOT v_has_head AND v_component.lifecycle_state='STAGED'
                    THEN 'ACTIVE'
                  WHEN v_has_head AND
                       v_component.lifecycle_state IN ('ACTIVE','DISABLED')
                    THEN v_component.lifecycle_state
                  ELSE NULL END;
                IF v_next IS NOT NULL THEN
                    PERFORM analytics_catalog_projection_activate_v2(
                        v_scope_schema::name,v_attempt.projection_receipt_id,
                        p_operation_id,
                        v_next='ACTIVE',p_completed_at
                    );
                END IF;
            END IF;
        END IF;
        IF v_next IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog v2 component transition is invalid';
        END IF;
        UPDATE analytics_catalog_components AS component
        SET lifecycle_state=v_next,
            content_sha256=CASE WHEN p_action='activate'
                THEN p_content_sha256 ELSE component.content_sha256 END,
            updated_at=CASE WHEN component.lifecycle_state IS DISTINCT FROM v_next
                OR p_action='activate' THEN p_completed_at
                ELSE component.updated_at END
        WHERE component.component_id=p_component_id;
    END IF;
    INSERT INTO analytics_catalog_component_receipts(receipt_id,operation_id,
        component_id,owner_module,owner_generation,contract,content_sha256,
        action,idempotency_key,ready,completed_at) VALUES (p_receipt_id,
        p_operation_id,p_component_id,p_owner,p_generation,p_contract,
        p_content_sha256,p_action,p_idempotency_key,true,p_completed_at)
    RETURNING * INTO v_receipt;
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.owner_module,v_receipt.owner_generation,
        v_receipt.contract,v_receipt.content_sha256,v_receipt.action,
        v_receipt.ready,v_receipt.completed_at;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_component_apply_core_v2(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_component_apply_v1(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_component_apply_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT result.receipt_id,result.operation_id,result.component_id,
           result.owner_module,result.owner_generation,result.contract,
           result.content_sha256,result.action,result.ready,result.completed_at
    FROM analytics_catalog_component_apply_v2(
        p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
        p_contract,p_content_sha256,p_action,p_reference_epoch,
        p_idempotency_key,p_completed_at
    ) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_component_apply_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_component_apply_v2(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_component_apply_v2(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_action='purge' THEN
        RETURN QUERY
        SELECT result.receipt_id,result.operation_id,result.component_id,
            result.owner_module,result.owner_generation,result.contract,
            result.content_sha256,result.action,result.ready,
            result.completed_at
        FROM analytics_catalog_component_purge_v2(
            p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
            p_contract,p_content_sha256,p_action,p_reference_epoch,
            p_idempotency_key,p_completed_at
        ) AS result;
        RETURN;
    END IF;
    RETURN QUERY
    SELECT result.receipt_id,result.operation_id,result.component_id,
        result.owner_module,result.owner_generation,result.contract,
        result.content_sha256,result.action,result.ready,result.completed_at
    FROM analytics_catalog_component_apply_core_v2(
        p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
        p_contract,p_content_sha256,p_action,p_reference_epoch,
        p_idempotency_key,p_completed_at
    ) AS result;
END;
$$;


