--
-- Name: analytics_catalog_component_blockers_v1(uuid, uuid, uuid, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_component_blockers_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_reference_epoch bigint, p_generation bigint, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, reference_epoch bigint, catalog_version text, zero_digest text, blockers jsonb, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_component analytics_catalog_components%ROWTYPE;
    v_receipt analytics_catalog_blocker_receipts%ROWTYPE;
    v_snapshot_blockers jsonb;
    v_snapshot_zero_digest text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_receipt_id=p_operation_id OR p_reference_epoch<1 OR p_generation<1 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog blocker request is invalid';
    END IF;
    SELECT * INTO v_component
    FROM analytics_catalog_components AS component
    WHERE component.component_id=p_component_id
    FOR SHARE;
    IF NOT FOUND OR v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR
       v_component.lifecycle_state<>'RETIRED' OR
       p_completed_at<v_component.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog blocker authority differs';
    END IF;
    SELECT snapshot.blockers,snapshot.zero_digest
    INTO STRICT v_snapshot_blockers,v_snapshot_zero_digest
    FROM analytics_catalog_blocker_snapshot_v2(
        p_component_id,p_reference_epoch,p_generation
    ) AS snapshot;
    SELECT * INTO v_receipt
    FROM analytics_catalog_blocker_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id
      AND receipt.component_id=p_component_id
      AND receipt.reference_epoch=p_reference_epoch
    FOR SHARE;
    IF FOUND THEN
        IF v_receipt.catalog_version IS DISTINCT FROM
               'analytics-catalog-blockers.v2' OR
           v_receipt.zero_digest IS DISTINCT FROM v_snapshot_zero_digest OR
           v_receipt.blockers IS DISTINCT FROM v_snapshot_blockers OR
           v_receipt.completed_at>p_completed_at THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog blocker receipt is stale';
        END IF;
    ELSE
        INSERT INTO analytics_catalog_blocker_receipts(
            receipt_id,operation_id,component_id,reference_epoch,
            catalog_version,zero_digest,blockers,completed_at
        ) VALUES (
            p_receipt_id,p_operation_id,p_component_id,p_reference_epoch,
            'analytics-catalog-blockers.v2',v_snapshot_zero_digest,
            v_snapshot_blockers,p_completed_at
        ) RETURNING * INTO v_receipt;
    END IF;
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.reference_epoch,
        v_receipt.catalog_version,v_receipt.zero_digest,
        v_receipt.blockers,v_receipt.completed_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_component_blockers_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_reference_epoch bigint, p_generation bigint, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_component_head_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_component_head_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF (NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state OR
        NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256) AND
       NEW.lifecycle_state IN ('ACTIVE','DISABLED','RETIRED') AND
       NOT EXISTS (
        SELECT 1
        FROM analytics_catalog_component_heads AS head
        JOIN analytics_catalog_version_projections AS projection
          ON projection.receipt_id=head.projection_receipt_id
        WHERE head.component_id=NEW.component_id
          AND head.content_sha256=NEW.content_sha256
          AND (
            (projection.analytics_kind='endpoint' AND EXISTS (
                SELECT 1 FROM analytics_saved_queries AS root
                WHERE root.id=projection.operational_resource_id
                  AND root.lifecycle_state=CASE
                    WHEN NEW.lifecycle_state='ACTIVE' THEN 'active'
                    ELSE 'retired' END
            )) OR
            (projection.analytics_kind='dashboard' AND EXISTS (
                SELECT 1 FROM analytics_dashboards AS root
                WHERE root.id=projection.operational_resource_id
                  AND root.lifecycle_state=CASE
                    WHEN NEW.lifecycle_state='ACTIVE' THEN 'active'
                    ELSE 'retired' END
            ))
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog component lacks exact visible head';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_component_head_guard_v1() OWNER TO harpy_owner;

--
-- Name: analytics_catalog_component_lifecycle_v2(name, uuid, uuid, bigint, text, text, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_component_lifecycle_v2(p_scope_schema name, p_operation_id uuid, p_component_id uuid, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_completed_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component analytics_catalog_components%ROWTYPE;
    v_next text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_generation IS NULL OR p_generation<1 OR p_contract IS NULL OR
       p_content_sha256 IS NULL OR p_content_sha256!~'^[0-9a-f]{64}$' OR
       p_action IS NULL OR
       p_action NOT IN ('disable','enable','retire','restore','purge') OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog lifecycle input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT * INTO v_component
    FROM analytics_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    IF NOT FOUND OR
       v_component.component_kind NOT IN ('ENDPOINT','DASHBOARD') OR
       v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR
       v_component.contract<>p_contract OR
       v_component.content_sha256<>p_content_sha256 OR
       p_completed_at<v_component.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog lifecycle authority differs';
    END IF;
    v_next:=CASE
      WHEN p_action='disable' AND v_component.lifecycle_state='ACTIVE'
        THEN 'DISABLED'
      WHEN p_action='enable' AND v_component.lifecycle_state='DISABLED'
        THEN 'ACTIVE'
      WHEN p_action='retire' AND
           v_component.lifecycle_state IN ('ACTIVE','DISABLED')
        THEN 'RETIRED'
      WHEN p_action='restore' AND v_component.lifecycle_state='RETIRED'
        THEN 'ACTIVE'
      WHEN p_action='purge' AND v_component.lifecycle_state='RETIRED'
        THEN 'PURGED'
      ELSE NULL END;
    IF v_next IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog lifecycle transition is invalid';
    END IF;
    IF p_action='purge' AND (
        p_reference_epoch<1 OR EXISTS (
            SELECT 1 FROM analytics_catalog_component_candidates AS candidate
            WHERE candidate.component_id=p_component_id
        ) OR NOT EXISTS (
            SELECT 1 FROM analytics_catalog_blocker_receipts AS blocker
            WHERE blocker.operation_id=p_operation_id
              AND blocker.component_id=p_component_id
              AND blocker.reference_epoch=p_reference_epoch
              AND blocker.blockers='[]'::jsonb
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge evidence is unavailable';
    END IF;
    IF p_action IN ('disable','retire') THEN
        PERFORM analytics_catalog_operational_head_visibility_v2(
            p_scope_schema,p_component_id,false,p_completed_at
        );
    ELSIF p_action IN ('enable','restore') THEN
        PERFORM analytics_catalog_operational_head_visibility_v2(
            p_scope_schema,p_component_id,true,p_completed_at
        );
    ELSIF p_action='purge' THEN
        PERFORM analytics_catalog_operational_head_visibility_v2(
            p_scope_schema,p_component_id,false,p_completed_at
        );
    END IF;
    UPDATE analytics_catalog_components AS component
    SET lifecycle_state=v_next,updated_at=p_completed_at
    WHERE component.component_id=p_component_id;
    RETURN v_next;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_component_lifecycle_v2(p_scope_schema name, p_operation_id uuid, p_component_id uuid, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_component_purge_v2(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_component_purge_v2(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component analytics_catalog_components%ROWTYPE;
    v_receipt analytics_catalog_component_receipts%ROWTYPE;
    v_blocker analytics_catalog_blocker_receipts%ROWTYPE;
    v_scope_schema text;
    v_snapshot_blockers jsonb;
    v_snapshot_zero_digest text;
    v_analytics_kind text;
    v_root_id uuid;
    v_head_version_id uuid;
    v_root_reference_epoch bigint;
    v_receipt_count bigint;
    v_changed bigint;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7
       OR pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7
       OR p_owner IS DISTINCT FROM 'analytics' OR p_generation IS NULL
       OR p_generation<1 OR p_contract IS NULL OR p_content_sha256 IS NULL
       OR p_content_sha256!~'^[0-9a-f]{64}$'
       OR p_action IS DISTINCT FROM 'purge' OR p_reference_epoch IS NULL
       OR p_reference_epoch<0 OR p_idempotency_key IS NULL
       OR length(p_idempotency_key) NOT BETWEEN 1 AND 128
       OR p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at)
       OR date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Analytics Catalog purge command is invalid';
    END IF;
    SELECT schema_name INTO STRICT v_scope_schema FROM tenancy_schema_identity
    WHERE singleton;
    PERFORM analytics_assert_current_authority_v1(v_scope_schema::name);
    SELECT * INTO v_receipt
    FROM analytics_catalog_component_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id AND
      receipt.component_id=p_component_id AND receipt.action='purge'
    FOR SHARE;
    IF FOUND THEN
        IF v_receipt.owner_module IS DISTINCT FROM p_owner OR
           v_receipt.owner_generation IS DISTINCT FROM p_generation OR
           v_receipt.contract IS DISTINCT FROM p_contract OR
           v_receipt.content_sha256 IS DISTINCT FROM p_content_sha256 OR
           v_receipt.idempotency_key IS DISTINCT FROM p_idempotency_key OR
           NOT v_receipt.ready OR NOT EXISTS (
               SELECT 1 FROM analytics_catalog_components AS component
               WHERE component.component_id=p_component_id
                 AND component.lifecycle_state='PURGED'
           ) THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='Analytics Catalog purge receipt differs';
        END IF;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.owner_module,v_receipt.owner_generation,
            v_receipt.contract,v_receipt.content_sha256,v_receipt.action,
            v_receipt.ready,v_receipt.completed_at;
        RETURN;
    END IF;
    SELECT * INTO v_component
    FROM analytics_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    IF NOT FOUND OR v_component.component_kind NOT IN ('ENDPOINT','DASHBOARD')
       OR v_component.owner_generation<>p_generation
       OR v_component.writer_state<>'v2'
       OR v_component.lifecycle_state<>'RETIRED'
       OR v_component.contract<>p_contract
       OR v_component.content_sha256<>p_content_sha256
       OR p_completed_at<v_component.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Analytics Catalog purge authority differs';
    END IF;
    SELECT pg_catalog.count(*) INTO v_receipt_count
    FROM analytics_catalog_blocker_receipts AS blocker WHERE
      blocker.operation_id=p_operation_id AND blocker.component_id=p_component_id;
    IF v_receipt_count<>1 THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Analytics Catalog purge blocker receipt is ambiguous';
    END IF;
    SELECT * INTO v_blocker
    FROM analytics_catalog_blocker_receipts AS blocker
    WHERE blocker.operation_id=p_operation_id AND
      blocker.component_id=p_component_id
    FOR SHARE;
    IF v_blocker.blockers<>'[]'::jsonb
       OR v_blocker.completed_at>p_completed_at
       OR (p_reference_epoch=0 AND v_blocker.catalog_version<>
           'analytics-catalog-blockers.v1')
       OR (p_reference_epoch<>0 AND p_reference_epoch<>
           v_blocker.reference_epoch) THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Analytics Catalog purge blocker receipt differs';
    END IF;
    IF v_blocker.catalog_version='analytics-catalog-blockers.v1' THEN
        IF v_blocker.zero_digest IS DISTINCT FROM
           pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            'analytics-catalog-blockers.v1'||E'\\000'||p_component_id::text||
            E'\\000'||v_blocker.reference_epoch::text||E'\\000'||
            v_blocker.blockers::text,'UTF8')),'hex') THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Analytics Catalog legacy blocker proof differs';
        END IF;
    ELSIF v_blocker.catalog_version<>'analytics-catalog-blockers.v2' THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Analytics Catalog blocker version differs';
    END IF;
    SELECT snapshot.blockers,snapshot.zero_digest,
        snapshot.analytics_kind,snapshot.root_id,snapshot.head_version_id,
        snapshot.root_reference_epoch
    INTO STRICT v_snapshot_blockers,v_snapshot_zero_digest,
        v_analytics_kind,v_root_id,v_head_version_id,
        v_root_reference_epoch
    FROM analytics_catalog_blocker_snapshot_v2(
        p_component_id,v_blocker.reference_epoch,p_generation
    ) AS snapshot;
    IF v_snapshot_blockers<>'[]'::jsonb OR
       (v_blocker.catalog_version='analytics-catalog-blockers.v2' AND (
        v_blocker.blockers IS DISTINCT FROM v_snapshot_blockers OR
        v_blocker.zero_digest IS DISTINCT FROM v_snapshot_zero_digest
       )) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge blockers changed';
    END IF;
    IF v_analytics_kind='endpoint' THEN
        PERFORM 1 FROM analytics_saved_queries AS root
        WHERE root.id=v_root_id AND root.lifecycle_state='retired' AND
          root.reference_epoch=v_root_reference_epoch
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE=
                'Analytics Catalog purge query changed';
        END IF;
        PERFORM 1 FROM analytics_saved_query_versions AS version_row
        WHERE version_row.query_id=v_root_id ORDER BY version_row.id FOR UPDATE;
    ELSE
        PERFORM 1 FROM analytics_dashboards AS root
        WHERE root.id=v_root_id AND root.lifecycle_state='retired' AND
          root.reference_epoch=v_root_reference_epoch
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE=
                'Analytics Catalog purge dashboard changed';
        END IF;
        PERFORM 1 FROM analytics_dashboard_versions AS version_row
        WHERE version_row.dashboard_id=v_root_id ORDER BY version_row.id FOR UPDATE;
    END IF;
    UPDATE analytics_catalog_projection_activations AS activation
    SET superseded_at=p_completed_at
    FROM analytics_catalog_component_heads AS head
    WHERE head.component_id=p_component_id AND head.projection_receipt_id=
      activation.projection_receipt_id AND activation.component_id=
      head.component_id AND activation.superseded_at IS NULL;
    GET DIAGNOSTICS v_changed=ROW_COUNT;
    IF v_changed<>1 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge activation differs';
    END IF;
    DELETE FROM analytics_catalog_component_heads AS head
    WHERE head.component_id=p_component_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge head differs';
    END IF;
    INSERT INTO analytics_catalog_component_receipts(
        receipt_id,operation_id,component_id,owner_module,owner_generation,
        contract,content_sha256,action,idempotency_key,ready,completed_at
    ) VALUES (
        p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
        p_contract,p_content_sha256,'purge',p_idempotency_key,true,
        p_completed_at
    ) RETURNING * INTO v_receipt;
    PERFORM analytics_catalog_purge_data_v2(
        v_analytics_kind,v_root_id,p_operation_id,p_completed_at
    );
    UPDATE analytics_catalog_components AS component
    SET lifecycle_state='PURGED',updated_at=p_completed_at
    WHERE component.component_id=p_component_id AND
      component.owner_generation=p_generation AND component.writer_state='v2' AND
      component.lifecycle_state='RETIRED' AND component.contract=p_contract AND
      component.content_sha256=p_content_sha256;
    GET DIAGNOSTICS v_changed=ROW_COUNT;
    IF v_changed<>1 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge final CAS differs';
    END IF;
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.owner_module,v_receipt.owner_generation,
        v_receipt.contract,v_receipt.content_sha256,v_receipt.action,
        v_receipt.ready,v_receipt.completed_at;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_component_purge_v2(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_dashboard_readiness_v2(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_dashboard_readiness_v2(p_scope_schema name, p_projection_receipt_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_plan jsonb;
    v_manifest_material bytea;
    v_manifest bytea;
    v_stored_manifest bytea;
    v_query_version_id uuid;
    v_query_manifest bytea;
    v_count bigint;
BEGIN
    v_manifest_material:=''::bytea;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=p_projection_receipt_id;
    IF NOT FOUND OR v_projection.analytics_kind<>'dashboard' OR
       v_projection.operational_state<>'ready' OR
       v_projection.ready_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog dashboard readiness evidence differs';
    END IF;
    v_plan:=pg_catalog.convert_from(
        v_projection.runtime_plan_bytes,'UTF8'
    )::jsonb;
    IF v_plan->>'contract'
           IS DISTINCT FROM 'analytics.catalog-runtime-plan.v1' OR
       v_plan->>'kind' IS DISTINCT FROM 'dashboard' OR
       v_plan->>'status' IS DISTINCT FROM 'candidate' OR
       pg_catalog.jsonb_typeof(v_plan#>'{dashboard,widgets}')
           IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog dashboard pinned plan differs';
    END IF;
    SELECT version_row.manifest_sha256,pg_catalog.count(widget.widget_id)
    INTO v_stored_manifest,v_count
    FROM analytics_dashboards AS root
    JOIN analytics_dashboard_versions AS version_row
      ON version_row.dashboard_id=root.id
     AND version_row.id=v_projection.published_version_id
    JOIN analytics_dashboard_widgets AS widget
      ON widget.dashboard_version_id=version_row.id
    WHERE root.id=v_projection.operational_resource_id
      AND root.current_draft_version_id=
          v_projection.current_draft_version_id
      AND root.lifecycle_state IN ('staged','retired')
      AND version_row.version_state='published'
    GROUP BY version_row.manifest_sha256;
    IF v_count IS DISTINCT FROM pg_catalog.jsonb_array_length(
        v_plan#>'{dashboard,widgets}'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog dashboard widget evidence differs';
    END IF;
    FOR v_query_version_id IN
        SELECT widget.query_version_id
        FROM analytics_dashboard_widgets AS widget
        WHERE widget.dashboard_version_id=v_projection.published_version_id
        ORDER BY widget.position
    LOOP
        v_query_manifest:=analytics_catalog_resource_manifest_v2(
            p_scope_schema,'query',v_query_version_id
        );
        v_manifest_material:=v_manifest_material||
            pg_catalog.uuid_send(v_query_version_id)||v_query_manifest;
    END LOOP;
    v_manifest:=pg_catalog.sha256(v_manifest_material);
    IF v_stored_manifest IS DISTINCT FROM v_manifest THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog dashboard manifest drifted';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_dashboard_readiness_v2(p_scope_schema name, p_projection_receipt_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_dependencies_manifest_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_dependencies_manifest_v1(p_dependencies jsonb) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_dependency jsonb;
    v_material bytea;
    v_owner text;
    v_kind text;
    v_resource_id uuid;
    v_version_id uuid;
    v_catalog bigint;
    v_query bigint;
    v_policy bigint;
    v_revision text;
    v_digest bytea;
    v_identity text;
    v_previous text;
BEGIN
    v_material := ''::bytea;
    IF pg_catalog.jsonb_typeof(p_dependencies) IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(p_dependencies) NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog dependencies are invalid';
    END IF;
    FOR v_dependency IN
        SELECT item.value FROM pg_catalog.jsonb_array_elements(p_dependencies)
            AS item(value)
        ORDER BY item.value->>'owner_domain',item.value->>'resource_kind',
            item.value->>'resource_id',item.value->>'resource_version_id'
    LOOP
        IF v_dependency->>'owner_domain' <> 'iam' OR
           v_dependency->>'resource_kind' <> 'form' OR
           NOT pg_catalog.pg_input_is_valid(
               v_dependency->>'resource_id','uuid') OR
           NOT pg_catalog.pg_input_is_valid(
               v_dependency->>'resource_version_id','uuid') OR
           v_dependency->>'dependency_sha256'
               OPERATOR(pg_catalog.!~) '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics Catalog dependency is invalid';
        END IF;
        v_owner := v_dependency->>'owner_domain';
        v_kind := v_dependency->>'resource_kind';
        v_resource_id := (v_dependency->>'resource_id')::uuid;
        v_version_id := (v_dependency->>'resource_version_id')::uuid;
        v_catalog := (v_dependency->>'catalog_version')::bigint;
        v_query := (v_dependency->>'query_contract_version')::bigint;
        v_policy := (v_dependency->>'policy_version')::bigint;
        v_revision := v_dependency->>'data_revision_capability';
        v_digest := pg_catalog.decode(
            v_dependency->>'dependency_sha256','hex'
        );
        v_identity := v_owner||'|'||v_kind||'|'||
            v_resource_id::text||'|'||v_version_id::text;
        IF v_identity IS NOT DISTINCT FROM v_previous OR
           pg_catalog.uuid_extract_version(v_resource_id) IS DISTINCT FROM 7 OR
           pg_catalog.uuid_extract_version(v_version_id) IS DISTINCT FROM 7 OR
           v_catalog < 1 OR v_query < 1 OR v_policy < 1 OR
           v_revision IS NULL OR
           pg_catalog.octet_length(v_revision) NOT BETWEEN 0 AND 128 OR
           pg_catalog.octet_length(v_digest) IS DISTINCT FROM 32 THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics Catalog dependency differs';
        END IF;
        v_previous := v_identity;
        v_material := v_material ||
            pg_catalog.int4send(pg_catalog.octet_length(v_owner)) ||
            pg_catalog.convert_to(v_owner,'UTF8') ||
            pg_catalog.int4send(pg_catalog.octet_length(v_kind)) ||
            pg_catalog.convert_to(v_kind,'UTF8') ||
            pg_catalog.int4send(16) || pg_catalog.uuid_send(v_resource_id) ||
            pg_catalog.int4send(16) || pg_catalog.uuid_send(v_version_id) ||
            pg_catalog.int4send(pg_catalog.octet_length(v_revision)) ||
            pg_catalog.convert_to(v_revision,'UTF8') ||
            pg_catalog.int4send(32) || v_digest ||
            pg_catalog.int8send(v_catalog) ||
            pg_catalog.int8send(v_query) ||
            pg_catalog.int8send(v_policy);
    END LOOP;
    RETURN pg_catalog.sha256(v_material);
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_dependencies_manifest_v1(p_dependencies jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_dependency_manifest_v1(uuid, uuid, bigint, bigint, bigint, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_dependency_manifest_v1(p_resource_id uuid, p_resource_version_id uuid, p_catalog_version bigint, p_query_contract_version bigint, p_policy_version bigint, p_data_revision_capability text, p_dependency_sha256 bytea) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_resource_id IS NULL OR p_resource_version_id IS NULL OR
       p_catalog_version < 1 OR p_query_contract_version < 1 OR
       p_policy_version < 1 OR
       p_data_revision_capability IS NULL OR
       pg_catalog.octet_length(p_data_revision_capability) NOT BETWEEN 0 AND 128 OR
       pg_catalog.octet_length(p_dependency_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog dependency manifest input is invalid';
    END IF;
    RETURN pg_catalog.sha256(
        pg_catalog.int4send(3) || pg_catalog.convert_to('iam','UTF8') ||
        pg_catalog.int4send(4) || pg_catalog.convert_to('form','UTF8') ||
        pg_catalog.int4send(16) || pg_catalog.uuid_send(p_resource_id) ||
        pg_catalog.int4send(16) || pg_catalog.uuid_send(p_resource_version_id) ||
        pg_catalog.int4send(pg_catalog.octet_length(p_data_revision_capability)) ||
        pg_catalog.convert_to(p_data_revision_capability,'UTF8') ||
        pg_catalog.int4send(32) || p_dependency_sha256 ||
        pg_catalog.int8send(p_catalog_version) ||
        pg_catalog.int8send(p_query_contract_version) ||
        pg_catalog.int8send(p_policy_version)
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_dependency_manifest_v1(p_resource_id uuid, p_resource_version_id uuid, p_catalog_version bigint, p_query_contract_version bigint, p_policy_version bigint, p_data_revision_capability text, p_dependency_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_endpoint_readiness_v2(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_endpoint_readiness_v2(p_scope_schema name, p_projection_receipt_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_plan jsonb;
    v_current jsonb;
    v_stored jsonb;
    v_manifest bytea;
    v_stored_manifest bytea;
    v_count bigint;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=p_projection_receipt_id;
    IF NOT FOUND OR v_projection.analytics_kind<>'endpoint' OR
       v_projection.operational_state<>'ready' OR
       v_projection.ready_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog endpoint readiness evidence differs';
    END IF;
    v_plan:=pg_catalog.convert_from(
        v_projection.runtime_plan_bytes,'UTF8'
    )::jsonb;
    IF v_plan->>'contract'
           IS DISTINCT FROM 'analytics.catalog-runtime-plan.v1' OR
       v_plan->>'kind' IS DISTINCT FROM 'endpoint' OR
       v_plan->>'status' IS DISTINCT FROM 'candidate' OR
       pg_catalog.jsonb_typeof(v_plan->'sources') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog endpoint pinned plan differs';
    END IF;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'owner_domain','iam','resource_kind','form',
        'resource_id',dependency.definition_id,
        'resource_version_id',dependency.version_id,
        'owner_generation',dependency.owner_generation,
        'catalog_version',dependency.catalog_version,
        'query_contract_version',dependency.query_contract_version,
        'policy_version',dependency.policy_version,
        'data_revision_capability',dependency.data_revision_capability,
        'dependency_sha256',pg_catalog.encode(
            dependency.dependency_sha256,'hex'
        )
    ) ORDER BY source.ordinality),pg_catalog.count(*)
    INTO v_current,v_count
    FROM pg_catalog.jsonb_array_elements_text(v_plan->'sources')
        WITH ORDINALITY AS source(value,ordinality)
    JOIN forms_catalog_analytics_dependency_v1(
        p_scope_schema,source.value
    ) AS dependency ON TRUE;
    IF v_count<>pg_catalog.jsonb_array_length(v_plan->'sources') THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog endpoint dependency is unavailable';
    END IF;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'owner_domain',dependency.owner_domain,
        'resource_kind',dependency.resource_kind,
        'resource_id',dependency.resource_id,
        'resource_version_id',dependency.resource_version_id,
        'owner_generation',dependency.owner_generation,
        'catalog_version',dependency.catalog_version,
        'query_contract_version',dependency.query_contract_version,
        'policy_version',dependency.policy_version,
        'data_revision_capability',dependency.data_revision_capability,
        'dependency_sha256',pg_catalog.encode(
            dependency.dependency_sha256,'hex'
        )
    ) ORDER BY dependency.ordinal),
    version_row.manifest_sha256
    INTO v_stored,v_stored_manifest
    FROM analytics_saved_queries AS root
    JOIN analytics_saved_query_versions AS version_row
      ON version_row.query_id=root.id
     AND version_row.id=v_projection.published_version_id
    JOIN analytics_query_dependencies AS dependency
      ON dependency.query_version_id=version_row.id
    WHERE root.id=v_projection.operational_resource_id
      AND root.current_draft_version_id=
          v_projection.current_draft_version_id
      AND root.lifecycle_state IN ('staged','retired')
      AND version_row.version_state='published'
    GROUP BY version_row.manifest_sha256;
    v_manifest:=analytics_catalog_dependencies_manifest_v1(v_current);
    IF v_stored IS DISTINCT FROM v_current OR
       v_stored_manifest IS DISTINCT FROM v_manifest THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog endpoint pinned dependency drifted';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_endpoint_readiness_v2(p_scope_schema name, p_projection_receipt_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_head_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_head_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM analytics_catalog_version_projections AS projection
        JOIN analytics_catalog_projection_activations AS activation
          ON activation.projection_receipt_id=projection.receipt_id
         AND activation.attempt_receipt_id IS NOT NULL
         AND activation.component_id=projection.component_id
         AND activation.package_id=projection.package_id
         AND activation.package_version=projection.package_version
         AND activation.release_id=projection.release_id
         AND activation.content_sha256=projection.content_sha256
         AND activation.superseded_at IS NULL
        JOIN analytics_catalog_projection_attempts AS attempt
          ON attempt.receipt_id=activation.attempt_receipt_id
         AND attempt.projection_receipt_id=projection.receipt_id
         AND attempt.ready_at IS NOT NULL
        JOIN analytics_catalog_definitions AS definition
          ON definition.component_id=projection.component_id
         AND definition.package_id=projection.package_id
         AND definition.package_version=projection.package_version
         AND definition.release_id=projection.release_id
         AND definition.content_sha256=projection.content_sha256
         AND definition.operational_resource_id=
             projection.operational_resource_id
         AND definition.published_version_id=projection.published_version_id
         AND definition.current_draft_version_id=
             projection.current_draft_version_id
        WHERE projection.receipt_id=NEW.projection_receipt_id
          AND projection.component_id=NEW.component_id
          AND projection.package_id=NEW.package_id
          AND projection.package_version=NEW.package_version
          AND projection.release_id=NEW.release_id
          AND projection.content_sha256=NEW.content_sha256
          AND projection.operational_state='ready'
          AND projection.ready_at<=NEW.activated_at
          AND activation.activated_at=NEW.activated_at
          AND attempt.updated_at<=NEW.activated_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog head lacks exact live activation';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_head_guard_v1() OWNER TO harpy_owner;

--
-- Name: analytics_catalog_internal_widget_peer_v2(uuid, text, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_internal_widget_peer_v2(p_package_id uuid, p_package_version text, p_release_id uuid, p_dashboard_version_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count bigint;
BEGIN
    IF pg_catalog.uuid_extract_version(p_package_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_version_id)
           IS DISTINCT FROM 7 OR p_package_version IS NULL THEN
        RETURN false;
    END IF;
    PERFORM 1
    FROM analytics_catalog_component_heads AS peer_head
    JOIN analytics_catalog_components AS peer_component
      ON peer_component.component_id=peer_head.component_id
     AND peer_component.content_sha256=peer_head.content_sha256
    JOIN analytics_catalog_version_projections AS peer_projection
      ON peer_projection.receipt_id=peer_head.projection_receipt_id
     AND peer_projection.component_id=peer_head.component_id
     AND peer_projection.package_id=peer_head.package_id
     AND peer_projection.package_version=peer_head.package_version
     AND peer_projection.release_id=peer_head.release_id
     AND peer_projection.content_sha256=peer_head.content_sha256
    JOIN analytics_catalog_projection_activations AS activation
      ON activation.projection_receipt_id=peer_head.projection_receipt_id
     AND activation.component_id=peer_head.component_id
     AND activation.package_id=peer_head.package_id
     AND activation.package_version=peer_head.package_version
     AND activation.release_id=peer_head.release_id
     AND activation.content_sha256=peer_head.content_sha256
     AND activation.activated_at=peer_head.activated_at
     AND activation.superseded_at IS NULL
    JOIN analytics_catalog_projection_attempts AS attempt
      ON attempt.receipt_id=activation.attempt_receipt_id
     AND attempt.projection_receipt_id=peer_projection.receipt_id
    JOIN analytics_catalog_definitions AS definition
      ON definition.component_id=peer_projection.component_id
     AND definition.package_id=peer_projection.package_id
     AND definition.package_version=peer_projection.package_version
     AND definition.release_id=peer_projection.release_id
     AND definition.content_sha256=peer_projection.content_sha256
     AND definition.operational_resource_id=
         peer_projection.operational_resource_id
     AND definition.published_version_id=
         peer_projection.published_version_id
     AND definition.current_draft_version_id=
         peer_projection.current_draft_version_id
    JOIN analytics_dashboards AS root
      ON root.id=peer_projection.operational_resource_id
     AND root.lifecycle_state='retired'
    JOIN analytics_dashboard_versions AS owner_version
      ON owner_version.id=p_dashboard_version_id
     AND owner_version.dashboard_id=root.id
    WHERE peer_head.package_id=p_package_id
      AND peer_head.package_version=p_package_version
      AND peer_head.release_id=p_release_id
      AND peer_component.component_kind='DASHBOARD'
      AND peer_component.writer_state='v2'
      AND peer_component.lifecycle_state='RETIRED'
      AND peer_component.owner_generation=peer_projection.owner_generation
      AND peer_component.contract=peer_projection.contract
      AND peer_projection.analytics_kind='dashboard'
      AND peer_projection.component_kind='DASHBOARD'
      AND peer_projection.contract='analytics.catalog-definition.v1'
      AND peer_projection.operational_state='ready'
      AND peer_projection.ready_at IS NOT NULL
      AND attempt.ready_at IS NOT NULL
      AND p_dashboard_version_id IN (
          peer_projection.published_version_id,
          peer_projection.current_draft_version_id
      )
    FOR SHARE OF peer_component,peer_head,peer_projection,activation,
        attempt,definition,root,owner_version;
    GET DIAGNOSTICS v_count=ROW_COUNT;
    RETURN v_count=1;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_internal_widget_peer_v2(p_package_id uuid, p_package_version text, p_release_id uuid, p_dashboard_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_materialize_dashboard_v1(name, uuid, uuid, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_materialize_dashboard_v1(p_scope_schema name, p_component_id uuid, p_actor_id uuid, p_original jsonb, p_plan jsonb, p_occurred_at timestamp with time zone) RETURNS TABLE(operational_state text, blocker_code text, operational_resource_id uuid, published_version_id uuid, current_draft_version_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_dashboard_id uuid;
    v_published_id uuid;
    v_draft_id uuid;
    v_create_operation uuid;
    v_publish_operation uuid;
    v_layout_document bytea;
    v_widgets jsonb;
    v_expected_count bigint;
    v_resolved_count bigint;
    v_unique_count bigint;
    v_manifest_material bytea;
    v_manifest bytea;
    v_item jsonb;
    v_query_version_id uuid;
    v_query_manifest bytea;
    v_read_version uuid;
    v_read_draft uuid;
    v_read_manifest bytea;
    v_read_widgets jsonb;
    v_read_state text;
BEGIN
    v_manifest_material := ''::bytea;
    IF p_plan->>'contract' <> 'analytics.catalog-runtime-plan.v1' OR
       p_plan->>'kind' <> 'dashboard' OR
       p_plan->>'status' NOT IN ('candidate','pending') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog dashboard runtime plan is invalid';
    END IF;
    IF p_plan->>'status' = 'pending' THEN
        RETURN QUERY SELECT 'pending',p_plan->>'blocker_code',
            NULL::uuid,NULL::uuid,NULL::uuid;
        RETURN;
    END IF;
    IF pg_catalog.jsonb_typeof(p_plan->'dashboard') <> 'object' OR
       pg_catalog.jsonb_typeof(p_plan#>'{dashboard,dataSources}') <> 'array' OR
       pg_catalog.jsonb_typeof(p_plan#>'{dashboard,widgets}') <> 'array' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog dashboard candidate is invalid';
    END IF;
    v_expected_count := pg_catalog.jsonb_array_length(
        p_plan#>'{dashboard,widgets}'
    );
    IF v_expected_count NOT BETWEEN 1 AND 30 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog dashboard widget count is invalid';
    END IF;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'widget_id',analytics_catalog_uuid_v7_v1(
            p_component_id,'widget:'||pg_catalog.lpad((widget.ordinality-1)::text,2,'0')
        ),
        'position',widget.ordinality-1,
        'query_version_id',endpoint.published_version_id,
        'parameter_document','7b7d','output_document','7b7d'
    ) ORDER BY widget.ordinality),
    pg_catalog.count(*),pg_catalog.count(DISTINCT endpoint.published_version_id)
    INTO v_widgets,v_resolved_count,v_unique_count
    FROM pg_catalog.jsonb_array_elements(p_plan#>'{dashboard,widgets}')
         WITH ORDINALITY AS widget(value,ordinality)
    JOIN pg_catalog.jsonb_array_elements(p_plan#>'{dashboard,dataSources}')
         AS source(value)
      ON source.value->>'id'=widget.value->>'dataSource'
    JOIN analytics_catalog_definitions AS endpoint
      ON endpoint.slug=source.value->>'endpointSlug'
     AND endpoint.analytics_kind='endpoint'
     AND endpoint.operational_state='ready'
    JOIN analytics_catalog_provisions AS provision
      ON provision.component_id=endpoint.component_id
     AND provision.ready_at IS NOT NULL;
    IF v_resolved_count <> v_expected_count OR
       v_unique_count <> v_expected_count THEN
        RETURN QUERY SELECT 'pending',
            'ANALYTICS_ENDPOINT_DEPENDENCY_NOT_READY',
            NULL::uuid,NULL::uuid,NULL::uuid;
        RETURN;
    END IF;
    v_dashboard_id := analytics_catalog_uuid_v7_v1(
        p_component_id,'dashboard:root'
    );
    v_published_id := analytics_catalog_uuid_v7_v1(
        p_component_id,'dashboard:published'
    );
    v_draft_id := analytics_catalog_uuid_v7_v1(
        p_component_id,'dashboard:draft'
    );
    v_create_operation := analytics_catalog_uuid_v7_v1(
        p_component_id,'dashboard:create-op'
    );
    v_publish_operation := analytics_catalog_uuid_v7_v1(
        p_component_id,'dashboard:publish-op'
    );
    v_layout_document := pg_catalog.convert_to(
        (p_plan->'dashboard')::text,'UTF8'
    );
    FOR v_item IN
        SELECT item.value
        FROM pg_catalog.jsonb_array_elements(v_widgets) AS item(value)
        ORDER BY (item.value->>'position')::integer
    LOOP
        v_query_version_id := (v_item->>'query_version_id')::uuid;
        v_query_manifest := analytics_resource_manifest_v1(
            p_scope_schema,'query',v_query_version_id
        );
        v_manifest_material := v_manifest_material ||
            pg_catalog.uuid_send(v_query_version_id) || v_query_manifest;
    END LOOP;
    v_manifest := pg_catalog.sha256(v_manifest_material);
    PERFORM 1 FROM analytics_dashboard_create_v1(
        p_scope_schema,v_create_operation,p_actor_id,
        'catalog.analytics.'||p_component_id::text||'.dashboard.create',
        pg_catalog.sha256(pg_catalog.convert_to(p_plan::text||':create','UTF8')),
        v_dashboard_id,v_published_id,p_original->>'name','tenant',
        v_layout_document,v_widgets,p_occurred_at
    );
    PERFORM 1 FROM analytics_dashboard_publish_v1(
        p_scope_schema,v_publish_operation,p_actor_id,
        'catalog.analytics.'||p_component_id::text||'.dashboard.publish',
        pg_catalog.sha256(pg_catalog.convert_to(p_plan::text||':publish','UTF8')),
        v_dashboard_id,v_published_id,v_draft_id,1,1,v_manifest,p_occurred_at
    );
    SELECT result.version_id,result.version_state,result.manifest_sha256,
        result.widgets
    INTO v_read_version,v_read_state,v_read_manifest,v_read_widgets
    FROM analytics_dashboard_get_version_v1(
        p_scope_schema,v_dashboard_id,v_published_id
    ) AS result;
    SELECT current_dashboard.version_id INTO v_read_draft
    FROM analytics_dashboard_get_v1(
        p_scope_schema,v_dashboard_id
    ) AS current_dashboard;
    IF v_read_version <> v_published_id OR v_read_state <> 'published' OR
       v_read_draft <> v_draft_id OR v_read_manifest <> v_manifest OR
       v_read_widgets <> v_widgets OR
       analytics_resource_manifest_v1(
           p_scope_schema,'dashboard',v_published_id
       ) <> v_manifest THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog dashboard operational readback differs';
    END IF;
    RETURN QUERY SELECT 'ready',NULL::text,
        v_dashboard_id,v_published_id,v_draft_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_materialize_dashboard_v1(p_scope_schema name, p_component_id uuid, p_actor_id uuid, p_original jsonb, p_plan jsonb, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_materialize_dashboard_v2(name, uuid, uuid, uuid, text, uuid, uuid, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_materialize_dashboard_v2(p_scope_schema name, p_component_id uuid, p_version_seed uuid, p_package_id uuid, p_package_version text, p_release_id uuid, p_actor_id uuid, p_original jsonb, p_plan jsonb, p_occurred_at timestamp with time zone) RETURNS TABLE(operational_state text, blocker_code text, operational_resource_id uuid, published_version_id uuid, current_draft_version_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_dashboard_id uuid;
    v_published_id uuid;
    v_draft_id uuid;
    v_create_operation uuid;
    v_publish_operation uuid;
    v_layout_document bytea;
    v_widgets jsonb;
    v_expected_count bigint;
    v_resolved_count bigint;
    v_manifest_material bytea;
    v_manifest bytea;
    v_item jsonb;
    v_query_version_id uuid;
    v_query_manifest bytea;
    v_read_version uuid;
    v_read_draft uuid;
    v_read_manifest bytea;
    v_read_widgets jsonb;
    v_read_state text;
BEGIN
    v_manifest_material := ''::bytea;
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_version_seed) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_plan->>'contract' <> 'analytics.catalog-runtime-plan.v1' OR
       p_plan->>'kind' <> 'dashboard' OR
       p_plan->>'status' NOT IN ('candidate','pending') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog dashboard v2 plan is invalid';
    END IF;
    IF p_plan->>'status' = 'pending' THEN
        RETURN QUERY SELECT 'pending',p_plan->>'blocker_code',
            NULL::uuid,NULL::uuid,NULL::uuid;
        RETURN;
    END IF;
    IF pg_catalog.jsonb_typeof(p_plan->'dashboard') <> 'object' OR
       pg_catalog.jsonb_typeof(p_plan#>'{dashboard,dataSources}') <> 'array' OR
       pg_catalog.jsonb_typeof(p_plan#>'{dashboard,widgets}') <> 'array' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog dashboard v2 candidate is invalid';
    END IF;
    v_expected_count := pg_catalog.jsonb_array_length(
        p_plan#>'{dashboard,widgets}'
    );
    IF v_expected_count NOT BETWEEN 1 AND 30 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog dashboard v2 widget count is invalid';
    END IF;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'widget_id',analytics_catalog_uuid_v7_v1(
            p_version_seed,'widget:'||
            pg_catalog.lpad((widget.ordinality-1)::text,2,'0')
        ),
        'position',widget.ordinality-1,
        'query_version_id',endpoint.published_version_id,
        'parameter_document','7b7d','output_document','7b7d'
    ) ORDER BY widget.ordinality),pg_catalog.count(*)
    INTO v_widgets,v_resolved_count
    FROM pg_catalog.jsonb_array_elements(p_plan#>'{dashboard,widgets}')
         WITH ORDINALITY AS widget(value,ordinality)
    JOIN pg_catalog.jsonb_array_elements(p_plan#>'{dashboard,dataSources}')
         AS source(value)
      ON source.value->>'id'=widget.value->>'dataSource'
    JOIN analytics_catalog_version_projections AS endpoint
      ON endpoint.package_id=p_package_id
     AND endpoint.package_version=p_package_version
     AND endpoint.release_id=p_release_id
     AND endpoint.semantic_identity=source.value->>'endpointSlug'
     AND endpoint.analytics_kind='endpoint'
     AND endpoint.operational_state='ready'
     AND endpoint.ready_at IS NOT NULL;
    IF v_resolved_count <> v_expected_count THEN
        RETURN QUERY SELECT 'pending',
            'ANALYTICS_ENDPOINT_DEPENDENCY_NOT_READY',
            NULL::uuid,NULL::uuid,NULL::uuid;
        RETURN;
    END IF;
    v_dashboard_id := analytics_catalog_uuid_v7_v1(
        p_version_seed,'dashboard:root'
    );
    v_published_id := analytics_catalog_uuid_v7_v1(
        p_version_seed,'dashboard:published'
    );
    v_draft_id := analytics_catalog_uuid_v7_v1(
        p_version_seed,'dashboard:draft'
    );
    v_create_operation := analytics_catalog_uuid_v7_v1(
        p_version_seed,'dashboard:create-op'
    );
    v_publish_operation := analytics_catalog_uuid_v7_v1(
        p_version_seed,'dashboard:publish-op'
    );
    v_layout_document := pg_catalog.convert_to(
        (p_plan->'dashboard')::text,'UTF8'
    );
    FOR v_item IN
        SELECT item.value
        FROM pg_catalog.jsonb_array_elements(v_widgets) AS item(value)
        ORDER BY (item.value->>'position')::integer
    LOOP
        v_query_version_id := (v_item->>'query_version_id')::uuid;
        v_query_manifest := analytics_catalog_resource_manifest_v2(
            p_scope_schema,'query',v_query_version_id
        );
        v_manifest_material := v_manifest_material ||
            pg_catalog.uuid_send(v_query_version_id) || v_query_manifest;
    END LOOP;
    v_manifest := pg_catalog.sha256(v_manifest_material);
    PERFORM 1 FROM analytics_dashboard_create_v1(
        p_scope_schema,v_create_operation,p_actor_id,
        'catalog.analytics.'||p_version_seed::text||'.dashboard.create',
        pg_catalog.sha256(pg_catalog.convert_to(p_plan::text||':create','UTF8')),
        v_dashboard_id,v_published_id,p_original->>'name','tenant',
        v_layout_document,v_widgets,p_occurred_at
    );
    PERFORM 1 FROM analytics_dashboard_publish_v1(
        p_scope_schema,v_publish_operation,p_actor_id,
        'catalog.analytics.'||p_version_seed::text||'.dashboard.publish',
        pg_catalog.sha256(pg_catalog.convert_to(p_plan::text||':publish','UTF8')),
        v_dashboard_id,v_published_id,v_draft_id,1,1,v_manifest,p_occurred_at
    );
    SELECT result.version_id,result.version_state,result.manifest_sha256,
        result.widgets
    INTO v_read_version,v_read_state,v_read_manifest,v_read_widgets
    FROM analytics_dashboard_get_version_v1(
        p_scope_schema,v_dashboard_id,v_published_id
    ) AS result;
    SELECT current_dashboard.version_id INTO v_read_draft
    FROM analytics_dashboard_get_v1(
        p_scope_schema,v_dashboard_id
    ) AS current_dashboard;
    IF v_read_version <> v_published_id OR v_read_state <> 'published' OR
       v_read_draft <> v_draft_id OR v_read_manifest <> v_manifest OR
       v_read_widgets <> v_widgets OR
       analytics_catalog_resource_manifest_v2(
           p_scope_schema,'dashboard',v_published_id
       ) <> v_manifest THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog dashboard v2 readback differs';
    END IF;
    RETURN QUERY SELECT 'ready',NULL::text,
        v_dashboard_id,v_published_id,v_draft_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_materialize_dashboard_v2(p_scope_schema name, p_component_id uuid, p_version_seed uuid, p_package_id uuid, p_package_version text, p_release_id uuid, p_actor_id uuid, p_original jsonb, p_plan jsonb, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_materialize_endpoint_v1(name, uuid, uuid, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_materialize_endpoint_v1(p_scope_schema name, p_component_id uuid, p_actor_id uuid, p_original jsonb, p_plan jsonb, p_occurred_at timestamp with time zone) RETURNS TABLE(operational_state text, blocker_code text, operational_resource_id uuid, published_version_id uuid, current_draft_version_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_source_count integer;
    v_resolved_count bigint;
    v_dependency_valid boolean;
    v_query_id uuid;
    v_published_id uuid;
    v_draft_id uuid;
    v_create_operation uuid;
    v_publish_operation uuid;
    v_query_document bytea;
    v_parameter_document bytea;
    v_output_document bytea;
    v_dependencies jsonb;
    v_manifest bytea;
    v_read_version uuid;
    v_read_draft uuid;
    v_read_manifest bytea;
    v_read_dependencies jsonb;
BEGIN
    IF p_plan->>'contract' <> 'analytics.catalog-runtime-plan.v1' OR
       p_plan->>'kind' <> 'endpoint' OR
       p_plan->>'status' NOT IN ('candidate','pending') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog endpoint runtime plan is invalid';
    END IF;
    IF p_plan->>'status' = 'pending' THEN
        RETURN QUERY SELECT 'pending', p_plan->>'blocker_code',
            NULL::uuid, NULL::uuid, NULL::uuid;
        RETURN;
    END IF;
    IF pg_catalog.jsonb_typeof(p_plan->'sources') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(p_plan->'sources') NOT BETWEEN 1 AND 4 OR
       pg_catalog.jsonb_typeof(p_plan->'query') IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(p_plan->'parameters') IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(p_plan->'output') IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog endpoint candidate is invalid';
    END IF;
    v_source_count := pg_catalog.jsonb_array_length(p_plan->'sources');
    IF (SELECT pg_catalog.count(DISTINCT source.value)
        FROM pg_catalog.jsonb_array_elements_text(p_plan->'sources')
            AS source(value)) <> v_source_count THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog endpoint sources differ';
    END IF;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'owner_domain','iam','resource_kind','form',
        'resource_id',dependency.definition_id,
        'resource_version_id',dependency.version_id,
        'owner_generation',dependency.owner_generation,
        'catalog_version',dependency.catalog_version,
        'query_contract_version',dependency.query_contract_version,
        'policy_version',dependency.policy_version,
        'data_revision_capability',dependency.data_revision_capability,
        'dependency_sha256',pg_catalog.encode(
            dependency.dependency_sha256,'hex'
        )
    ) ORDER BY source.ordinality),pg_catalog.count(*),pg_catalog.bool_and(
        pg_catalog.uuid_extract_version(dependency.publication_id)=7 AND
        pg_catalog.uuid_extract_version(dependency.definition_id)=7 AND
        pg_catalog.uuid_extract_version(dependency.version_id)=7 AND
        dependency.owner_generation>0 AND dependency.catalog_version>0 AND
        dependency.query_contract_version>0 AND dependency.policy_version>0 AND
        pg_catalog.octet_length(dependency.data_revision_capability)
            BETWEEN 0 AND 128 AND
        pg_catalog.octet_length(dependency.dependency_sha256)=32
    ) INTO v_dependencies,v_resolved_count,v_dependency_valid
    FROM pg_catalog.jsonb_array_elements_text(p_plan->'sources')
        WITH ORDINALITY AS source(value,ordinality)
    JOIN forms_catalog_analytics_dependency_v1(
        p_scope_schema,source.value
    ) AS dependency ON TRUE;
    IF v_resolved_count <> v_source_count THEN
        RETURN QUERY SELECT 'pending',
            'ANALYTICS_FORMS_DEPENDENCY_NOT_READY',
            NULL::uuid,NULL::uuid,NULL::uuid;
        RETURN;
    END IF;
    IF v_dependency_valid IS NOT TRUE THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog endpoint dependency differs';
    END IF;
    v_query_id := analytics_catalog_uuid_v7_v1(p_component_id,'query:root');
    v_published_id := analytics_catalog_uuid_v7_v1(
        p_component_id,'query:published'
    );
    v_draft_id := analytics_catalog_uuid_v7_v1(p_component_id,'query:draft');
    v_create_operation := analytics_catalog_uuid_v7_v1(
        p_component_id,'query:create-op'
    );
    v_publish_operation := analytics_catalog_uuid_v7_v1(
        p_component_id,'query:publish-op'
    );
    v_query_document := pg_catalog.convert_to((p_plan->'query')::text,'UTF8');
    v_parameter_document := pg_catalog.convert_to(
        (p_plan->'parameters')::text,'UTF8'
    );
    v_output_document := pg_catalog.convert_to((p_plan->'output')::text,'UTF8');
    v_manifest := analytics_catalog_dependencies_manifest_v1(v_dependencies);
    PERFORM 1 FROM analytics_query_create_v1(
        p_scope_schema,v_create_operation,p_actor_id,
        'catalog.analytics.'||p_component_id::text||'.create',
        pg_catalog.sha256(pg_catalog.convert_to(p_plan::text||':create','UTF8')),
        v_query_id,v_published_id,p_original->>'name',v_query_document,
        v_parameter_document,v_output_document,p_occurred_at
    );
    PERFORM 1 FROM analytics_query_publish_v1(
        p_scope_schema,v_publish_operation,p_actor_id,
        'catalog.analytics.'||p_component_id::text||'.publish',
        pg_catalog.sha256(pg_catalog.convert_to(p_plan::text||':publish','UTF8')),
        v_query_id,v_published_id,v_draft_id,1,1,v_query_document,
        v_parameter_document,v_output_document,v_dependencies,v_manifest,
        'none',p_occurred_at
    );
    SELECT latest.version_id, latest.manifest_sha256
    INTO v_read_version, v_read_manifest
    FROM analytics_query_latest_published_v1(
        p_scope_schema,v_query_id
    ) AS latest;
    SELECT current_query.version_id INTO v_read_draft
    FROM analytics_query_get_v1(p_scope_schema,v_query_id) AS current_query;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'owner_domain',dependency.owner_domain,
        'resource_kind',dependency.resource_kind,
        'resource_id',dependency.resource_id,
        'resource_version_id',dependency.resource_version_id,
        'owner_generation',dependency.owner_generation,
        'catalog_version',dependency.catalog_version,
        'query_contract_version',dependency.query_contract_version,
        'policy_version',dependency.policy_version,
        'data_revision_capability',dependency.data_revision_capability,
        'dependency_sha256',pg_catalog.encode(
            dependency.dependency_sha256,'hex'
        )
    ) ORDER BY dependency.ordinality) INTO v_read_dependencies
    FROM analytics_query_dependencies_v1(
        p_scope_schema,v_query_id,v_published_id
    ) WITH ORDINALITY AS dependency(
        owner_domain,resource_kind,resource_id,resource_version_id,
        owner_generation,catalog_version,query_contract_version,policy_version,
        data_revision_capability,dependency_sha256,ordinality
    );
    IF v_read_version <> v_published_id OR v_read_draft <> v_draft_id OR
       v_read_manifest <> v_manifest OR
       v_read_dependencies IS DISTINCT FROM v_dependencies THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog endpoint operational readback differs';
    END IF;
    RETURN QUERY SELECT 'ready',NULL::text,
        v_query_id,v_published_id,v_draft_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_materialize_endpoint_v1(p_scope_schema name, p_component_id uuid, p_actor_id uuid, p_original jsonb, p_plan jsonb, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_operational_activate_v2(name, uuid, uuid, boolean, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_operational_activate_v2(p_scope_schema name, p_projection_receipt_id uuid, p_operation_id uuid, p_visible boolean, p_completed_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_attempt analytics_catalog_projection_attempts%ROWTYPE;
    v_old_projection analytics_catalog_version_projections%ROWTYPE;
    v_old_resource_id uuid;
    v_state text;
    v_old_state text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_projection_receipt_id)
           IS DISTINCT FROM 7 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_visible IS NULL OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog operational activation input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT attempt.* INTO v_attempt
    FROM analytics_catalog_component_candidates AS candidate
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=candidate.projection_receipt_id
    JOIN analytics_catalog_projection_attempts AS attempt
      ON attempt.receipt_id=candidate.attempt_receipt_id
     AND attempt.projection_receipt_id=projection.receipt_id
    WHERE candidate.projection_receipt_id=p_projection_receipt_id
      AND candidate.staged_operation_id=p_operation_id
    FOR UPDATE OF candidate,projection,attempt;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog operational candidate differs';
    END IF;
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=v_attempt.projection_receipt_id;
    IF NOT FOUND OR v_projection.operational_state<>'ready' OR
       v_projection.ready_at IS NULL OR
       v_attempt.ready_at IS NULL OR p_completed_at<v_attempt.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog operational candidate differs';
    END IF;
    SELECT previous.* INTO v_old_projection
    FROM analytics_catalog_component_heads AS head
    JOIN analytics_catalog_version_projections AS previous
      ON previous.receipt_id=head.projection_receipt_id
    WHERE head.component_id=v_projection.component_id FOR UPDATE OF head;
    IF FOUND THEN
        v_old_resource_id:=v_old_projection.operational_resource_id;
        IF v_old_projection.analytics_kind<>v_projection.analytics_kind THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog operational kind changed';
        END IF;
    END IF;
    IF v_projection.analytics_kind='endpoint' THEN
        PERFORM 1 FROM analytics_saved_queries AS root
        WHERE root.id IN (
            v_projection.operational_resource_id,v_old_resource_id
        ) ORDER BY root.id FOR UPDATE;
        PERFORM analytics_catalog_endpoint_readiness_v2(
            p_scope_schema,p_projection_receipt_id
        );
        SELECT lifecycle_state INTO v_state
        FROM analytics_saved_queries
        WHERE id=v_projection.operational_resource_id;
        IF v_state IS DISTINCT FROM 'staged' THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog candidate query is not staged';
        END IF;
        IF v_old_resource_id IS NOT NULL AND
           v_old_resource_id<>v_projection.operational_resource_id THEN
            SELECT lifecycle_state INTO v_old_state
            FROM analytics_saved_queries
            WHERE id=v_old_resource_id;
            IF NOT FOUND OR (p_visible AND v_old_state<>'active') OR
               (NOT p_visible AND
                v_old_state NOT IN ('active','retired')) THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='Analytics Catalog previous query visibility differs';
            END IF;
            UPDATE analytics_saved_queries
            SET lifecycle_state='retired',row_revision=row_revision+1,
                reference_epoch=reference_epoch+1,
                updated_by=v_attempt.actor_id,updated_at=p_completed_at
            WHERE id=v_old_resource_id AND lifecycle_state='active';
        END IF;
        UPDATE analytics_saved_queries
        SET lifecycle_state=CASE WHEN p_visible THEN 'active' ELSE 'retired' END,
            row_revision=row_revision+1,
            reference_epoch=reference_epoch+1,
            updated_by=v_attempt.actor_id,updated_at=p_completed_at
        WHERE id=v_projection.operational_resource_id
          AND lifecycle_state='staged';
    ELSIF v_projection.analytics_kind='dashboard' THEN
        PERFORM 1 FROM analytics_dashboards AS root
        WHERE root.id IN (
            v_projection.operational_resource_id,v_old_resource_id
        ) ORDER BY root.id FOR UPDATE;
        PERFORM analytics_catalog_dashboard_readiness_v2(
            p_scope_schema,p_projection_receipt_id
        );
        SELECT lifecycle_state INTO v_state
        FROM analytics_dashboards
        WHERE id=v_projection.operational_resource_id;
        IF v_state IS DISTINCT FROM 'staged' THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog candidate dashboard is not staged';
        END IF;
        IF v_old_resource_id IS NOT NULL AND
           v_old_resource_id<>v_projection.operational_resource_id THEN
            SELECT lifecycle_state INTO v_old_state
            FROM analytics_dashboards
            WHERE id=v_old_resource_id;
            IF NOT FOUND OR (p_visible AND v_old_state<>'active') OR
               (NOT p_visible AND
                v_old_state NOT IN ('active','retired')) THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='Analytics Catalog previous dashboard visibility differs';
            END IF;
            UPDATE analytics_dashboards
            SET lifecycle_state='retired',row_revision=row_revision+1,
                reference_epoch=reference_epoch+1,
                updated_by=v_attempt.actor_id,updated_at=p_completed_at
            WHERE id=v_old_resource_id AND lifecycle_state='active';
        END IF;
        UPDATE analytics_dashboards
        SET lifecycle_state=CASE WHEN p_visible THEN 'active' ELSE 'retired' END,
            row_revision=row_revision+1,
            reference_epoch=reference_epoch+1,
            updated_by=v_attempt.actor_id,updated_at=p_completed_at
        WHERE id=v_projection.operational_resource_id
          AND lifecycle_state='staged';
    ELSE
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog operational kind differs';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog operational activation was not applied';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_operational_activate_v2(p_scope_schema name, p_projection_receipt_id uuid, p_operation_id uuid, p_visible boolean, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_operational_head_visibility_v2(name, uuid, boolean, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_operational_head_visibility_v2(p_scope_schema name, p_component_id uuid, p_visible boolean, p_completed_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_attempt analytics_catalog_projection_attempts%ROWTYPE;
    v_state text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_visible IS NULL OR p_completed_at IS NULL OR
       NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog head visibility input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT attempt.* INTO v_attempt
    FROM analytics_catalog_component_heads AS head
    JOIN analytics_catalog_projection_activations AS activation
      ON activation.projection_receipt_id=head.projection_receipt_id
     AND activation.component_id=head.component_id
     AND activation.package_id=head.package_id
     AND activation.package_version=head.package_version
     AND activation.release_id=head.release_id
     AND activation.content_sha256=head.content_sha256
     AND activation.activated_at=head.activated_at
     AND activation.superseded_at IS NULL
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=activation.projection_receipt_id
    JOIN analytics_catalog_projection_attempts AS attempt
      ON attempt.receipt_id=activation.attempt_receipt_id
     AND attempt.projection_receipt_id=projection.receipt_id
    WHERE head.component_id=p_component_id
    FOR UPDATE OF head,activation,projection,attempt;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog active head is unavailable';
    END IF;
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=v_attempt.projection_receipt_id;
    IF NOT FOUND OR v_projection.operational_state<>'ready' OR
       v_projection.ready_at IS NULL OR v_attempt.ready_at IS NULL OR
       p_completed_at<v_attempt.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog live head evidence differs';
    END IF;
    IF v_projection.analytics_kind='endpoint' THEN
        SELECT root.lifecycle_state INTO v_state
        FROM analytics_saved_queries AS root
        WHERE root.id=v_projection.operational_resource_id FOR UPDATE;
        IF p_visible AND v_state='retired' THEN
            PERFORM analytics_catalog_endpoint_readiness_v2(
                p_scope_schema,v_projection.receipt_id
            );
            UPDATE analytics_saved_queries
            SET lifecycle_state='active',row_revision=row_revision+1,
                reference_epoch=reference_epoch+1,
                updated_by=v_attempt.actor_id,updated_at=p_completed_at
            WHERE id=v_projection.operational_resource_id
              AND lifecycle_state='retired';
        ELSIF NOT p_visible AND v_state='active' THEN
            UPDATE analytics_saved_queries
            SET lifecycle_state='retired',row_revision=row_revision+1,
                reference_epoch=reference_epoch+1,
                updated_by=v_attempt.actor_id,updated_at=p_completed_at
            WHERE id=v_projection.operational_resource_id
              AND lifecycle_state='active';
        ELSIF (p_visible AND v_state<>'active') OR
              (NOT p_visible AND v_state<>'retired') THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog query visibility differs';
        END IF;
    ELSIF v_projection.analytics_kind='dashboard' THEN
        SELECT root.lifecycle_state INTO v_state
        FROM analytics_dashboards AS root
        WHERE root.id=v_projection.operational_resource_id FOR UPDATE;
        IF p_visible AND v_state='retired' THEN
            PERFORM analytics_catalog_dashboard_readiness_v2(
                p_scope_schema,v_projection.receipt_id
            );
            UPDATE analytics_dashboards
            SET lifecycle_state='active',row_revision=row_revision+1,
                reference_epoch=reference_epoch+1,
                updated_by=v_attempt.actor_id,updated_at=p_completed_at
            WHERE id=v_projection.operational_resource_id
              AND lifecycle_state='retired';
        ELSIF NOT p_visible AND v_state='active' THEN
            UPDATE analytics_dashboards
            SET lifecycle_state='retired',row_revision=row_revision+1,
                reference_epoch=reference_epoch+1,
                updated_by=v_attempt.actor_id,updated_at=p_completed_at
            WHERE id=v_projection.operational_resource_id
              AND lifecycle_state='active';
        ELSIF (p_visible AND v_state<>'active') OR
              (NOT p_visible AND v_state<>'retired') THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog dashboard visibility differs';
        END IF;
    ELSE
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog head kind differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_operational_head_visibility_v2(p_scope_schema name, p_component_id uuid, p_visible boolean, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_operational_stage_v2(name, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_operational_stage_v2(p_scope_schema name, p_attempt_receipt_id uuid, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_attempt analytics_catalog_projection_attempts%ROWTYPE;
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_root_state text;
    v_draft_id uuid;
    v_version_state text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_attempt_receipt_id)
           IS DISTINCT FROM 7 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog operational stage input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT attempt.* INTO v_attempt
    FROM analytics_catalog_projection_attempts AS attempt
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=attempt.projection_receipt_id
    WHERE attempt.receipt_id=p_attempt_receipt_id
    FOR UPDATE OF attempt,projection;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog operational stage evidence differs';
    END IF;
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=v_attempt.projection_receipt_id;
    IF NOT FOUND OR v_projection.operational_state<>'ready' OR
       v_projection.ready_at IS NULL OR v_attempt.ready_at IS NULL OR
       p_occurred_at<v_attempt.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog operational stage evidence differs';
    END IF;
    IF EXISTS (
        SELECT 1 FROM analytics_catalog_projection_activations AS activation
        WHERE activation.projection_receipt_id=v_projection.receipt_id
    ) THEN
        RETURN;
    END IF;
    IF v_projection.analytics_kind='endpoint' THEN
        SELECT root.lifecycle_state,root.current_draft_version_id,
            version_row.version_state
        INTO v_root_state,v_draft_id,v_version_state
        FROM analytics_saved_queries AS root
        JOIN analytics_saved_query_versions AS version_row
          ON version_row.id=v_projection.published_version_id
         AND version_row.query_id=root.id
        WHERE root.id=v_projection.operational_resource_id FOR UPDATE OF root;
        IF NOT FOUND OR v_draft_id<>v_projection.current_draft_version_id OR
           v_version_state<>'published' OR
           v_root_state NOT IN ('active','staged','retired') THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog staged query readback differs';
        END IF;
        IF v_root_state<>'staged' THEN
            UPDATE analytics_saved_queries
            SET lifecycle_state='staged',row_revision=row_revision+1,
                reference_epoch=reference_epoch+1,
                updated_by=v_attempt.actor_id,updated_at=p_occurred_at
            WHERE id=v_projection.operational_resource_id;
        END IF;
    ELSIF v_projection.analytics_kind='dashboard' THEN
        SELECT root.lifecycle_state,root.current_draft_version_id,
            version_row.version_state
        INTO v_root_state,v_draft_id,v_version_state
        FROM analytics_dashboards AS root
        JOIN analytics_dashboard_versions AS version_row
          ON version_row.id=v_projection.published_version_id
         AND version_row.dashboard_id=root.id
        WHERE root.id=v_projection.operational_resource_id FOR UPDATE OF root;
        IF NOT FOUND OR v_draft_id<>v_projection.current_draft_version_id OR
           v_version_state<>'published' OR
           v_root_state NOT IN ('active','staged','retired') THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog staged dashboard readback differs';
        END IF;
        IF v_root_state<>'staged' THEN
            UPDATE analytics_dashboards
            SET lifecycle_state='staged',row_revision=row_revision+1,
                reference_epoch=reference_epoch+1,
                updated_by=v_attempt.actor_id,updated_at=p_occurred_at
            WHERE id=v_projection.operational_resource_id;
        END IF;
    ELSE
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog staged resource kind differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_operational_stage_v2(p_scope_schema name, p_attempt_receipt_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_owner_binding_v2(name, uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_owner_binding_v2(p_scope_schema name, p_component_id uuid, p_package_id uuid, p_generation bigint, p_contract text, p_content_sha256 text) RETURNS TABLE(resource_id uuid, version_id uuid, head_id uuid, lifecycle_state text, resource_reference_epoch bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE v_count bigint;
BEGIN
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_package_id) IS DISTINCT FROM 7 OR
       p_generation<1 OR p_contract IS NULL OR
       p_content_sha256!~'^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog owner binding input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT projection.operational_resource_id,
           projection.published_version_id,
           head.projection_receipt_id,component.lifecycle_state,
           root.reference_epoch
    FROM analytics_catalog_components AS component
    JOIN analytics_catalog_component_heads AS head
      ON head.component_id=component.component_id
     AND head.package_id=p_package_id
     AND head.content_sha256=component.content_sha256
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=head.projection_receipt_id
     AND projection.component_id=head.component_id
     AND projection.package_id=head.package_id
     AND projection.package_version=head.package_version
     AND projection.release_id=head.release_id
     AND projection.content_sha256=head.content_sha256
     AND projection.analytics_kind='endpoint'
     AND projection.operational_state='ready'
     AND projection.ready_at IS NOT NULL
    JOIN analytics_saved_queries AS root
      ON root.id=projection.operational_resource_id
    JOIN analytics_saved_query_versions AS version_row
      ON version_row.query_id=root.id
     AND version_row.id=projection.published_version_id
    WHERE component.component_id=p_component_id
      AND component.owner_generation=p_generation
      AND component.contract=p_contract
      AND component.content_sha256=p_content_sha256
      AND component.writer_state='v2'
    UNION ALL
    SELECT projection.operational_resource_id,
           projection.published_version_id,
           head.projection_receipt_id,component.lifecycle_state,
           root.reference_epoch
    FROM analytics_catalog_components AS component
    JOIN analytics_catalog_component_heads AS head
      ON head.component_id=component.component_id
     AND head.package_id=p_package_id
     AND head.content_sha256=component.content_sha256
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=head.projection_receipt_id
     AND projection.component_id=head.component_id
     AND projection.package_id=head.package_id
     AND projection.package_version=head.package_version
     AND projection.release_id=head.release_id
     AND projection.content_sha256=head.content_sha256
     AND projection.analytics_kind='dashboard'
     AND projection.operational_state='ready'
     AND projection.ready_at IS NOT NULL
    JOIN analytics_dashboards AS root
      ON root.id=projection.operational_resource_id
    JOIN analytics_dashboard_versions AS version_row
      ON version_row.dashboard_id=root.id
     AND version_row.id=projection.published_version_id
    WHERE component.component_id=p_component_id
      AND component.owner_generation=p_generation
      AND component.contract=p_contract
      AND component.content_sha256=p_content_sha256
      AND component.writer_state='v2';
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF v_count<>1 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog owner binding differs';
    END IF;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_owner_binding_v2(p_scope_schema name, p_component_id uuid, p_package_id uuid, p_generation bigint, p_contract text, p_content_sha256 text) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_owner_preflight_v2(name, uuid, uuid, bigint, text, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_owner_preflight_v2(p_scope_schema name, p_component_id uuid, p_package_id uuid, p_generation bigint, p_contract text, p_content_sha256 text, p_reference_epoch bigint) RETURNS TABLE(blockers jsonb, resource_id uuid, version_id uuid, head_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_resource_id uuid;
    v_version_id uuid;
    v_head_id uuid;
    v_lifecycle_state text;
    v_resource_reference_epoch bigint;
    v_blockers jsonb;
    v_snapshot_resource_id uuid;
    v_snapshot_version_id uuid;
    v_snapshot_reference_epoch bigint;
BEGIN
    IF p_reference_epoch<1 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog owner preflight input is invalid';
    END IF;
    SELECT binding.resource_id,binding.version_id,binding.head_id,
        binding.lifecycle_state,binding.resource_reference_epoch
    INTO STRICT v_resource_id,v_version_id,v_head_id,
        v_lifecycle_state,v_resource_reference_epoch
    FROM analytics_catalog_owner_binding_v2(
        p_scope_schema,p_component_id,p_package_id,p_generation,
        p_contract,p_content_sha256
    ) AS binding;
    IF v_lifecycle_state<>'RETIRED' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog owner preflight lifecycle differs';
    END IF;
    SELECT snapshot.blockers,snapshot.root_id,
        snapshot.head_version_id,snapshot.root_reference_epoch
    INTO STRICT v_blockers,v_snapshot_resource_id,
        v_snapshot_version_id,v_snapshot_reference_epoch
    FROM analytics_catalog_blocker_snapshot_v2(
        p_component_id,p_reference_epoch,p_generation
    ) AS snapshot;
    IF v_snapshot_resource_id<>v_resource_id OR
       v_snapshot_version_id<>v_version_id OR
       v_snapshot_reference_epoch<>v_resource_reference_epoch THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog owner preflight target differs';
    END IF;
    RETURN QUERY SELECT v_blockers,v_resource_id,v_version_id,v_head_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_owner_preflight_v2(p_scope_schema name, p_component_id uuid, p_package_id uuid, p_generation bigint, p_contract text, p_content_sha256 text, p_reference_epoch bigint) OWNER TO harpy_owner;

