ALTER FUNCTION __tenant_schema__.analytics_catalog_owner_purge_authority_guard_v2() OWNER TO harpy_owner;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: analytics_catalog_owner_purge_authorities_v2; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.analytics_catalog_owner_purge_authorities_v2 (
    operation_id uuid CONSTRAINT analytics_catalog_owner_purge_authorities_operation_id_not_null NOT NULL,
    component_id uuid CONSTRAINT analytics_catalog_owner_purge_authorities_component_id_not_null NOT NULL,
    reference_epoch bigint CONSTRAINT analytics_catalog_owner_purge_authorit_reference_epoch_not_null NOT NULL,
    authority_sha256 text CONSTRAINT analytics_catalog_owner_purge_authori_authority_sha256_not_null NOT NULL,
    resource_id uuid CONSTRAINT analytics_catalog_owner_purge_authorities__resource_id_not_null NOT NULL,
    version_id uuid CONSTRAINT analytics_catalog_owner_purge_authorities_v_version_id_not_null NOT NULL,
    head_id uuid NOT NULL,
    recorded_at timestamp with time zone CONSTRAINT analytics_catalog_owner_purge_authorities__recorded_at_not_null NOT NULL,
    CONSTRAINT analytics_catalog_owner_purge_authoritie_authority_sha256_check CHECK ((authority_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT analytics_catalog_owner_purge_authorities_reference_epoch_check CHECK ((reference_epoch > 0)),
    CONSTRAINT analytics_catalog_owner_purge_authorities_v2_check CHECK (((uuid_extract_version(operation_id) = 7) AND (uuid_extract_version(component_id) = 7) AND (uuid_extract_version(resource_id) = 7) AND (uuid_extract_version(version_id) = 7) AND (uuid_extract_version(head_id) = 7) AND isfinite(recorded_at) AND (date_trunc('microseconds'::text, recorded_at) = recorded_at)))
);


ALTER TABLE __tenant_schema__.analytics_catalog_owner_purge_authorities_v2 OWNER TO harpy_owner;

--
-- Name: analytics_catalog_owner_purge_authority_read_v2(name, uuid, uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_owner_purge_authority_read_v2(p_scope_schema name, p_operation_id uuid, p_component_id uuid, p_package_id uuid, p_generation bigint, p_contract text, p_content_sha256 text) RETURNS SETOF __tenant_schema__.analytics_catalog_owner_purge_authorities_v2
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE v_existing analytics_catalog_owner_purge_authorities_v2%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_package_id) IS DISTINCT FROM 7 OR
       p_generation<1 OR p_contract IS NULL OR
       p_content_sha256!~'^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog purge authority read is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT authority.* INTO v_existing
    FROM analytics_catalog_owner_purge_authorities_v2 AS authority
    JOIN analytics_catalog_components AS component
      ON component.component_id=authority.component_id
     AND component.owner_generation=p_generation
     AND component.contract=p_contract
     AND component.content_sha256=p_content_sha256
     AND component.writer_state='v2'
     AND component.lifecycle_state IN ('RETIRED','PURGED')
    JOIN analytics_catalog_version_projections AS projection
      ON projection.component_id=component.component_id
     AND projection.package_id=p_package_id
     AND projection.operational_resource_id=authority.resource_id
     AND projection.published_version_id=authority.version_id
     AND projection.receipt_id=authority.head_id
    WHERE authority.operation_id=p_operation_id
      AND authority.component_id=p_component_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge authority is unavailable';
    END IF;
    RETURN NEXT v_existing;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_owner_purge_authority_read_v2(p_scope_schema name, p_operation_id uuid, p_component_id uuid, p_package_id uuid, p_generation bigint, p_contract text, p_content_sha256 text) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_owner_purge_authority_v2(name, uuid, uuid, uuid, bigint, text, text, bigint, text, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_owner_purge_authority_v2(p_scope_schema name, p_operation_id uuid, p_component_id uuid, p_package_id uuid, p_generation bigint, p_contract text, p_content_sha256 text, p_reference_epoch bigint, p_authority_sha256 text, p_resource_id uuid, p_version_id uuid, p_head_id uuid, p_recorded_at timestamp with time zone) RETURNS SETOF __tenant_schema__.analytics_catalog_owner_purge_authorities_v2
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_resource_id uuid;
    v_version_id uuid;
    v_head_id uuid;
    v_lifecycle_state text;
    v_existing analytics_catalog_owner_purge_authorities_v2%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_reference_epoch<1 OR
       p_authority_sha256!~'^[0-9a-f]{64}$' OR
       pg_catalog.uuid_extract_version(p_resource_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_version_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_head_id) IS DISTINCT FROM 7 OR
       p_recorded_at IS NULL OR NOT pg_catalog.isfinite(p_recorded_at) OR
       date_trunc('microseconds',p_recorded_at)<>p_recorded_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog purge authority input is invalid';
    END IF;
    SELECT binding.resource_id,binding.version_id,binding.head_id,
        binding.lifecycle_state
    INTO STRICT v_resource_id,v_version_id,v_head_id,v_lifecycle_state
    FROM analytics_catalog_owner_binding_v2(
        p_scope_schema,p_component_id,p_package_id,p_generation,
        p_contract,p_content_sha256
    ) AS binding;
    IF v_lifecycle_state<>'RETIRED' OR
       v_resource_id<>p_resource_id OR
       v_version_id<>p_version_id OR v_head_id<>p_head_id THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge authority target differs';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        p_operation_id::text||':'||p_component_id::text,145408
    ));
    SELECT * INTO v_existing
    FROM analytics_catalog_owner_purge_authorities_v2 AS authority
    WHERE authority.operation_id=p_operation_id
      AND authority.component_id=p_component_id
    FOR SHARE;
    IF FOUND THEN
        IF v_existing.reference_epoch<>p_reference_epoch OR
           v_existing.authority_sha256<>p_authority_sha256 OR
           v_existing.resource_id<>p_resource_id OR
           v_existing.version_id<>p_version_id OR
           v_existing.head_id<>p_head_id OR
           v_existing.recorded_at<>p_recorded_at THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='Analytics Catalog purge authority differs';
        END IF;
    ELSE
        INSERT INTO analytics_catalog_owner_purge_authorities_v2(
            operation_id,component_id,reference_epoch,authority_sha256,
            resource_id,version_id,head_id,recorded_at
        ) VALUES (
            p_operation_id,p_component_id,p_reference_epoch,
            p_authority_sha256,p_resource_id,p_version_id,p_head_id,
            p_recorded_at
        ) RETURNING * INTO v_existing;
    END IF;
    RETURN NEXT v_existing;
END;
$_$;


