--
-- Name: analytics_catalog_project_v1(name, uuid, uuid, text, text, uuid, uuid, bigint, text, text, text, text, text, bytea, integer, integer, bytea, bytea, bytea, uuid, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_project_v1(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, component_kind text, module_slug text, semantic_identity text, semantic_sha256 bytea, item_count integer, auxiliary_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
    v_plan jsonb;
    v_source_contract text;
    v_runtime_plan_bytes bytea;
    v_runtime_plan_sha256 bytea;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    IF p_runtime_plan_bytes IS NULL OR
       pg_catalog.octet_length(p_runtime_plan_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.sha256(p_runtime_plan_bytes)
           IS DISTINCT FROM p_runtime_plan_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog legacy runtime plan digest differs';
    END IF;
    BEGIN
        v_document:=pg_catalog.convert_from(p_document_bytes,'UTF8')::jsonb;
        v_plan:=pg_catalog.convert_from(p_runtime_plan_bytes,'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog legacy runtime plan is invalid';
    END;
    v_source_contract:=v_document->>'source_contract';
    IF pg_catalog.jsonb_typeof(v_document) IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(v_plan) IS DISTINCT FROM 'object' OR
       v_source_contract IS NULL OR
       (v_plan ? 'component_id' AND v_plan->>'component_id'
           IS DISTINCT FROM p_component_id::text) OR
       (v_plan ? 'source_contract' AND v_plan->>'source_contract'
           IS DISTINCT FROM v_source_contract) OR
       (v_plan ? 'document_sha256' AND v_plan->>'document_sha256'
           IS DISTINCT FROM p_content_sha256) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog legacy runtime plan binding differs';
    END IF;
    v_plan:=v_plan||pg_catalog.jsonb_build_object(
        'component_id',p_component_id::text,
        'source_contract',v_source_contract,
        'document_sha256',p_content_sha256
    );
    v_runtime_plan_bytes:=pg_catalog.convert_to(
        analytics_catalog_canonical_json_v1(v_plan),'UTF8'
    );
    v_runtime_plan_sha256:=pg_catalog.sha256(v_runtime_plan_bytes);
    RETURN QUERY
    SELECT result.receipt_id,result.package_id,result.package_slug,
           result.package_version,result.release_id,result.component_id,
           result.owner_generation,result.contract,result.content_sha256,
           result.component_kind,result.module_slug,result.semantic_identity,
           result.semantic_sha256,result.item_count,result.auxiliary_count,
           result.document_bytes,result.idempotency_key,result.request_sha256,
           result.lifecycle_state,result.ready_at,
           result.created_at,result.updated_at
    FROM analytics_catalog_project_v2(
        p_scope_schema,p_receipt_id,p_package_id,p_package_slug,
        p_package_version,p_release_id,p_component_id,p_owner_generation,
        p_contract,p_content_sha256,p_component_kind,p_module_slug,
        p_semantic_identity,p_semantic_sha256,p_item_count,p_auxiliary_count,
        p_document_bytes,v_runtime_plan_bytes,v_runtime_plan_sha256,p_actor_id,
        p_idempotency_key,p_request_sha256,p_occurred_at
    ) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_project_v1(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_project_v2(name, uuid, uuid, text, text, uuid, uuid, bigint, text, text, text, text, text, bytea, integer, integer, bytea, bytea, bytea, uuid, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_project_v2(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, component_kind text, module_slug text, semantic_identity text, semantic_sha256 bytea, item_count integer, auxiliary_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_projection_receipt_id uuid;
    v_attempt_receipt_id uuid;
BEGIN
    v_projection_receipt_id:=analytics_catalog_projection_begin_v2(
        p_scope_schema,p_receipt_id,p_package_id,p_package_slug,
        p_package_version,p_release_id,p_component_id,p_owner_generation,
        p_contract,p_content_sha256,p_component_kind,p_module_slug,
        p_semantic_identity,p_semantic_sha256,p_item_count,p_auxiliary_count,
        p_document_bytes,p_runtime_plan_bytes,p_runtime_plan_sha256,p_actor_id,
        p_idempotency_key,p_request_sha256,p_occurred_at
    );
    v_attempt_receipt_id:=analytics_catalog_projection_attempt_v2(
        p_scope_schema,p_receipt_id,v_projection_receipt_id,p_actor_id,
        p_idempotency_key,p_request_sha256,p_occurred_at
    );
    PERFORM analytics_catalog_projection_materialize_v2(
        p_scope_schema,v_attempt_receipt_id,p_occurred_at
    );
    RETURN QUERY
    SELECT snapshot.receipt_id,snapshot.package_id,snapshot.package_slug,
        snapshot.package_version,snapshot.release_id,snapshot.component_id,
        snapshot.owner_generation,snapshot.contract,snapshot.content_sha256,
        snapshot.component_kind,snapshot.module_slug,
        snapshot.semantic_identity,snapshot.semantic_sha256,
        snapshot.item_count,snapshot.auxiliary_count,snapshot.document_bytes,
        snapshot.idempotency_key,snapshot.request_sha256,
        snapshot.lifecycle_state,snapshot.ready_at,
        snapshot.created_at,snapshot.updated_at
    FROM analytics_catalog_projection_read_v2(
        v_attempt_receipt_id
    ) AS snapshot;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog v2 projection readback differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_project_v2(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_activate_v2(name, uuid, uuid, boolean, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_activate_v2(p_scope_schema name, p_projection_receipt_id uuid, p_operation_id uuid, p_visible boolean, p_completed_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_candidate analytics_catalog_component_candidates%ROWTYPE;
    v_attempt analytics_catalog_projection_attempts%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_projection_receipt_id)
           IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_visible IS NULL OR p_completed_at IS NULL OR
       NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog v2 activation input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT candidate.* INTO v_candidate
    FROM analytics_catalog_component_candidates AS candidate
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=candidate.projection_receipt_id
     AND projection.component_id=candidate.component_id
     AND projection.package_id=candidate.package_id
     AND projection.package_version=candidate.package_version
     AND projection.release_id=candidate.release_id
     AND projection.owner_generation=candidate.owner_generation
     AND projection.content_sha256=candidate.content_sha256
    JOIN analytics_catalog_projection_attempts AS attempt
      ON attempt.receipt_id=candidate.attempt_receipt_id
     AND attempt.projection_receipt_id=projection.receipt_id
    WHERE projection.receipt_id=p_projection_receipt_id
      AND candidate.staged_operation_id=p_operation_id
    FOR UPDATE OF projection,candidate,attempt;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog v2 activation candidate differs';
    END IF;
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=v_candidate.projection_receipt_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog v2 activation candidate differs';
    END IF;
    SELECT * INTO v_attempt
    FROM analytics_catalog_projection_attempts AS attempt
    WHERE attempt.receipt_id=v_candidate.attempt_receipt_id
      AND attempt.projection_receipt_id=v_projection.receipt_id;
    IF NOT FOUND OR v_projection.operational_state<>'ready' OR
       v_projection.blocker_code IS NOT NULL OR
       v_projection.ready_at IS NULL OR v_attempt.ready_at IS NULL OR
       v_candidate.prepared_at>p_completed_at OR
       v_attempt.updated_at>p_completed_at OR
       pg_catalog.uuid_extract_version(
           v_projection.operational_resource_id
       ) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(
           v_projection.published_version_id
       ) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(
           v_projection.current_draft_version_id
       ) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog v2 ready candidate is unavailable';
    END IF;
    PERFORM analytics_catalog_operational_activate_v2(
        p_scope_schema,v_projection.receipt_id,p_operation_id,
        p_visible,p_completed_at
    );
    INSERT INTO analytics_catalog_definitions(
        component_id,analytics_kind,module_slug,slug,name,description,
        legacy_hash,definition_json,definition_sha256,document_bytes,
        content_sha256,semantic_sha256,runtime_plan_bytes,
        runtime_plan_sha256,package_id,package_slug,package_version,
        release_id,operational_state,blocker_code,operational_resource_id,
        published_version_id,current_draft_version_id,installed_at,updated_at
    ) VALUES (
        v_projection.component_id,v_projection.analytics_kind,
        v_projection.module_slug,v_projection.semantic_identity,
        v_projection.name,v_projection.description,v_projection.legacy_hash,
        v_projection.definition_json,v_projection.definition_sha256,
        v_projection.document_bytes,v_projection.content_sha256,
        v_projection.semantic_sha256,v_projection.runtime_plan_bytes,
        v_projection.runtime_plan_sha256,v_projection.package_id,
        v_projection.package_slug,v_projection.package_version,
        v_projection.release_id,'ready',NULL,
        v_projection.operational_resource_id,
        v_projection.published_version_id,
        v_projection.current_draft_version_id,
        v_projection.created_at,p_completed_at
    ) ON CONFLICT (component_id) DO UPDATE SET
        analytics_kind=EXCLUDED.analytics_kind,
        module_slug=EXCLUDED.module_slug,slug=EXCLUDED.slug,
        name=EXCLUDED.name,description=EXCLUDED.description,
        legacy_hash=EXCLUDED.legacy_hash,
        definition_json=EXCLUDED.definition_json,
        definition_sha256=EXCLUDED.definition_sha256,
        document_bytes=EXCLUDED.document_bytes,
        content_sha256=EXCLUDED.content_sha256,
        semantic_sha256=EXCLUDED.semantic_sha256,
        runtime_plan_bytes=EXCLUDED.runtime_plan_bytes,
        runtime_plan_sha256=EXCLUDED.runtime_plan_sha256,
        package_id=EXCLUDED.package_id,package_slug=EXCLUDED.package_slug,
        package_version=EXCLUDED.package_version,
        release_id=EXCLUDED.release_id,
        operational_state='ready',blocker_code=NULL,
        operational_resource_id=EXCLUDED.operational_resource_id,
        published_version_id=EXCLUDED.published_version_id,
        current_draft_version_id=EXCLUDED.current_draft_version_id,
        installed_at=EXCLUDED.installed_at,updated_at=EXCLUDED.updated_at;
    UPDATE analytics_catalog_projection_activations AS activation
    SET superseded_at=p_completed_at
    WHERE activation.component_id=v_projection.component_id
      AND activation.superseded_at IS NULL
      AND activation.projection_receipt_id<>v_projection.receipt_id;
    INSERT INTO analytics_catalog_projection_activations(
        projection_receipt_id,attempt_receipt_id,component_id,
        package_id,package_version,release_id,content_sha256,activated_at
    ) VALUES (
        v_projection.receipt_id,v_attempt.receipt_id,
        v_projection.component_id,v_projection.package_id,
        v_projection.package_version,v_projection.release_id,
        v_projection.content_sha256,p_completed_at
    );
    INSERT INTO analytics_catalog_component_heads(
        component_id,projection_receipt_id,package_id,package_version,
        release_id,content_sha256,activated_at
    ) VALUES (
        v_projection.component_id,v_projection.receipt_id,
        v_projection.package_id,v_projection.package_version,
        v_projection.release_id,v_projection.content_sha256,p_completed_at
    ) ON CONFLICT ON CONSTRAINT analytics_catalog_component_heads_pkey
      DO UPDATE SET
        projection_receipt_id=EXCLUDED.projection_receipt_id,
        package_id=EXCLUDED.package_id,
        package_version=EXCLUDED.package_version,
        release_id=EXCLUDED.release_id,
        content_sha256=EXCLUDED.content_sha256,
        activated_at=EXCLUDED.activated_at;
    DELETE FROM analytics_catalog_component_candidates AS candidate
    WHERE candidate.component_id=v_projection.component_id
      AND candidate.projection_receipt_id=v_projection.receipt_id
      AND candidate.attempt_receipt_id=v_attempt.receipt_id
      AND candidate.staged_operation_id=p_operation_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog activated candidate cleanup differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_activate_v2(p_scope_schema name, p_projection_receipt_id uuid, p_operation_id uuid, p_visible boolean, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_attempt_v2(name, uuid, uuid, uuid, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_attempt_v2(p_scope_schema name, p_receipt_id uuid, p_projection_receipt_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_existing analytics_catalog_projection_attempts%ROWTYPE;
    v_ready_at timestamptz;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_projection_receipt_id)
           IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       p_idempotency_key IS NULL OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_idempotency_key !~ '^[A-Za-z0-9_.:-]+$' OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection attempt input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=p_projection_receipt_id FOR UPDATE;
    IF NOT FOUND OR p_occurred_at<v_projection.created_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog projection artifact is unavailable';
    END IF;
    SELECT * INTO v_existing
    FROM analytics_catalog_projection_attempts AS attempt
    WHERE attempt.projection_receipt_id=p_projection_receipt_id
      AND attempt.idempotency_key=p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.actor_id<>p_actor_id OR
           v_existing.request_sha256<>p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='Analytics Catalog projection attempt differs';
        END IF;
        RETURN v_existing.receipt_id;
    END IF;
    v_ready_at:=CASE WHEN v_projection.operational_state='ready'
        THEN p_occurred_at ELSE NULL END;
    INSERT INTO analytics_catalog_projection_attempts(
        receipt_id,projection_receipt_id,actor_id,idempotency_key,
        request_sha256,ready_at,created_at,updated_at
    ) VALUES (
        p_receipt_id,p_projection_receipt_id,p_actor_id,p_idempotency_key,
        p_request_sha256,v_ready_at,p_occurred_at,p_occurred_at
    );
    RETURN p_receipt_id;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_attempt_v2(p_scope_schema name, p_receipt_id uuid, p_projection_receipt_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_begin_v1(name, uuid, uuid, text, text, uuid, uuid, bigint, text, text, text, text, text, bytea, integer, integer, bytea, bytea, bytea, uuid, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_begin_v1(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_original jsonb;
    v_plan jsonb;
    v_kind text;
    v_auxiliary integer;
    v_blocker text;
    v_existing analytics_catalog_provisions%ROWTYPE;
    v_definition analytics_catalog_definitions%ROWTYPE;
    v_component analytics_catalog_components%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR
       p_package_id='00000000-0000-0000-0000-000000000000'::uuid OR
       p_package_slug !~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$' OR
       p_module_slug IS DISTINCT FROM p_package_slug OR
       p_package_version !~
         '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$' OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_owner_generation < 1 OR
       p_contract IS DISTINCT FROM 'analytics.catalog-definition.v1' OR
       p_content_sha256 !~ '^[0-9a-f]{64}$' OR
       p_component_kind NOT IN ('ENDPOINT','DASHBOARD') OR
       p_semantic_identity !~ '^[a-z][a-z0-9-]{1,62}$' OR
       pg_catalog.octet_length(p_semantic_sha256) IS DISTINCT FROM 32 OR
       p_item_count IS DISTINCT FROM 1 OR p_auxiliary_count < 2 OR
       pg_catalog.octet_length(p_runtime_plan_sha256) IS DISTINCT FROM 32 OR
       p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_idempotency_key !~ '^[A-Za-z0-9_.:-]+$' OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection input is invalid';
    END IF;
    IF pg_catalog.encode(pg_catalog.sha256(p_document_bytes),'hex') <>
           p_content_sha256 OR
       pg_catalog.sha256(p_runtime_plan_bytes) <> p_runtime_plan_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection digest differs';
    END IF;
    BEGIN
        v_original := pg_catalog.convert_from(p_document_bytes,'UTF8')::jsonb;
        v_plan := pg_catalog.convert_from(p_runtime_plan_bytes,'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection document is invalid';
    END;
    v_kind := v_original->>'kind';
    IF pg_catalog.jsonb_typeof(v_original) IS DISTINCT FROM 'object' OR
       v_original->>'contract_version' IS DISTINCT FROM p_contract OR
       v_original->>'component_id' IS DISTINCT FROM p_component_id::text OR
       v_original->>'analytics_id' IS DISTINCT FROM p_component_id::text OR
       v_original->>'slug' IS DISTINCT FROM p_semantic_identity OR
       pg_catalog.octet_length(v_original->>'name') NOT BETWEEN 1 AND 100 OR
       pg_catalog.octet_length(v_original->>'description') NOT BETWEEN 1 AND 2048 OR
       v_original->>'legacy_hash' !~ '^[0-9a-f]{64}$' OR
       v_original->>'legacy_hash' <>
           pg_catalog.encode(p_semantic_sha256,'hex') OR
       v_kind NOT IN ('endpoint','dashboard') OR
       (v_kind='endpoint' AND p_component_kind<>'ENDPOINT') OR
       (v_kind='dashboard' AND p_component_kind<>'DASHBOARD') OR
       pg_catalog.jsonb_typeof(v_original#>'{definition,dataSources}')
           IS DISTINCT FROM 'array' OR
       v_plan->>'contract' IS DISTINCT FROM
           'analytics.catalog-runtime-plan.v1' OR
       v_plan->>'kind' IS DISTINCT FROM v_kind OR
       v_plan->>'status' NOT IN ('candidate','pending') OR
       pg_catalog.jsonb_typeof(v_plan->'sources') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection binding differs';
    END IF;
    IF v_kind='endpoint' THEN
        IF pg_catalog.jsonb_typeof(v_original#>'{definition,fields}')
               IS DISTINCT FROM 'array' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics Catalog endpoint definition is invalid';
        END IF;
        v_auxiliary :=
            pg_catalog.jsonb_array_length(v_original#>'{definition,dataSources}') +
            pg_catalog.jsonb_array_length(v_original#>'{definition,fields}');
    ELSE
        IF pg_catalog.jsonb_typeof(v_original#>'{definition,widgets}')
               IS DISTINCT FROM 'array' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics Catalog dashboard definition is invalid';
        END IF;
        v_auxiliary :=
            pg_catalog.jsonb_array_length(v_original#>'{definition,dataSources}') +
            pg_catalog.jsonb_array_length(v_original#>'{definition,widgets}');
    END IF;
    IF v_auxiliary <> p_auxiliary_count OR
       (v_plan->>'status'='pending' AND
        v_plan->>'blocker_code' !~ '^[A-Z][A-Z0-9_]{0,127}$') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection composition differs';
    END IF;
    v_blocker := CASE WHEN v_plan->>'status'='pending'
        THEN v_plan->>'blocker_code'
        ELSE 'ANALYTICS_DEPENDENCY_NOT_READY' END;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:catalog-project:'||p_component_id::text,6301
    ));
    SELECT * INTO v_existing FROM analytics_catalog_provisions AS provision
    WHERE provision.component_id=p_component_id FOR UPDATE;
    IF FOUND THEN
        SELECT * INTO v_definition FROM analytics_catalog_definitions AS definition
        WHERE definition.component_id=p_component_id;
        IF ROW(v_existing.package_id,v_existing.package_slug,
               v_existing.package_version,v_existing.release_id,
               v_existing.owner_generation,v_existing.contract,
               v_existing.content_sha256,v_existing.component_kind,
               v_existing.module_slug,v_existing.semantic_identity,
               v_existing.semantic_sha256,v_existing.item_count,
               v_existing.auxiliary_count,v_existing.idempotency_key,
               v_existing.request_sha256,v_definition.document_bytes)
           IS DISTINCT FROM
           ROW(p_package_id,p_package_slug,p_package_version,p_release_id,
               p_owner_generation,p_contract,p_content_sha256,p_component_kind,
               p_module_slug,p_semantic_identity,p_semantic_sha256,p_item_count,
               p_auxiliary_count,p_idempotency_key,p_request_sha256,
               p_document_bytes) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='Analytics Catalog projection replay differs';
        END IF;
        IF v_definition.operational_state='pending' AND
           v_definition.runtime_plan_sha256<>p_runtime_plan_sha256 THEN
            UPDATE analytics_catalog_definitions SET runtime_plan_bytes=p_runtime_plan_bytes,
                runtime_plan_sha256=p_runtime_plan_sha256,blocker_code=v_blocker,
                updated_at=p_occurred_at WHERE component_id=p_component_id;
        END IF;
        RETURN v_existing.receipt_id;
    END IF;
    SELECT * INTO v_component FROM analytics_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO analytics_catalog_components(
            component_id,component_kind,contract,content_sha256,
            owner_generation,writer_state,lifecycle_state,updated_at
        ) VALUES (p_component_id,p_component_kind,p_contract,p_content_sha256,
            p_owner_generation,'v2','AVAILABLE',p_occurred_at);
    ELSIF ROW(v_component.component_kind,v_component.contract,
              v_component.content_sha256,v_component.owner_generation,
              v_component.writer_state)
          IS DISTINCT FROM ROW(p_component_kind,p_contract,p_content_sha256,
              p_owner_generation,'v2'::text) OR
          v_component.lifecycle_state NOT IN ('AVAILABLE','STAGED') THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog component authority differs';
    END IF;
    INSERT INTO analytics_catalog_definitions(
        component_id,analytics_kind,module_slug,slug,name,description,
        legacy_hash,definition_json,definition_sha256,document_bytes,
        content_sha256,semantic_sha256,runtime_plan_bytes,runtime_plan_sha256,
        package_id,package_slug,package_version,release_id,
        operational_state,blocker_code,installed_at,updated_at
    ) VALUES (p_component_id,v_kind,p_module_slug,p_semantic_identity,
        v_original->>'name',v_original->>'description',v_original->>'legacy_hash',
        v_original->'definition',pg_catalog.sha256(pg_catalog.convert_to(
            (v_original->'definition')::text,'UTF8')),p_document_bytes,
        p_content_sha256,p_semantic_sha256,p_runtime_plan_bytes,
        p_runtime_plan_sha256,p_package_id,p_package_slug,p_package_version,
        p_release_id,'pending',v_blocker,p_occurred_at,p_occurred_at);
    INSERT INTO analytics_catalog_provisions(
        receipt_id,package_id,package_slug,package_version,release_id,
        component_id,owner_generation,contract,content_sha256,component_kind,
        module_slug,semantic_identity,semantic_sha256,item_count,auxiliary_count,
        actor_id,idempotency_key,request_sha256,created_at,updated_at
    ) VALUES (p_receipt_id,p_package_id,p_package_slug,p_package_version,
        p_release_id,p_component_id,p_owner_generation,p_contract,
        p_content_sha256,p_component_kind,p_module_slug,p_semantic_identity,
        p_semantic_sha256,p_item_count,p_auxiliary_count,p_actor_id,
        p_idempotency_key,p_request_sha256,p_occurred_at,p_occurred_at);
    RETURN p_receipt_id;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_begin_v1(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_begin_v2(name, uuid, uuid, text, text, uuid, uuid, bigint, text, text, text, text, text, bytea, integer, integer, bytea, bytea, bytea, uuid, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_begin_v2(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_analytics_kind text;
    v_name text;
    v_description text;
    v_legacy_hash text;
    v_definition jsonb;
    v_definition_sha256 bytea;
    v_blocker_code text;
    v_existing analytics_catalog_version_projections%ROWTYPE;
    v_component analytics_catalog_components%ROWTYPE;
    v_has_head boolean;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR
       p_package_id='00000000-0000-0000-0000-000000000000'::uuid OR
       p_package_slug IS NULL OR
       p_package_slug !~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$' OR
       p_module_slug IS DISTINCT FROM p_package_slug OR
       p_package_version IS NULL OR p_package_version !~
         '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$' OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_owner_generation<1 OR p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       p_idempotency_key IS NULL OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_idempotency_key !~ '^[A-Za-z0-9_.:-]+$' OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection input is invalid';
    END IF;
    SELECT valid.analytics_kind,valid.name,valid.description,
        valid.legacy_hash,valid.definition_json,valid.definition_sha256,
        valid.blocker_code
    INTO STRICT v_analytics_kind,v_name,v_description,v_legacy_hash,
        v_definition,v_definition_sha256,v_blocker_code
    FROM analytics_catalog_projection_validate_v2(
        p_contract,p_content_sha256,p_component_id,p_component_kind,
        p_module_slug,p_semantic_identity,p_semantic_sha256,p_item_count,
        p_auxiliary_count,p_document_bytes,p_runtime_plan_bytes,
        p_runtime_plan_sha256
    ) AS valid;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:catalog-project:'||p_component_id::text,6301
    ));
    SELECT * INTO v_existing
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.package_id=p_package_id
      AND projection.package_version=p_package_version
      AND projection.component_id=p_component_id FOR UPDATE;
    IF FOUND THEN
        IF ROW(
            v_existing.package_slug,v_existing.release_id,
            v_existing.owner_generation,v_existing.contract,
            v_existing.content_sha256,v_existing.component_kind,
            v_existing.module_slug,v_existing.semantic_identity,
            v_existing.semantic_sha256,v_existing.item_count,
            v_existing.auxiliary_count,v_existing.document_bytes
        ) IS DISTINCT FROM ROW(
            p_package_slug,p_release_id,p_owner_generation,p_contract,
            p_content_sha256,p_component_kind,p_module_slug,
            p_semantic_identity,p_semantic_sha256,p_item_count,
            p_auxiliary_count,p_document_bytes
        ) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='Analytics Catalog projection artifact differs';
        END IF;
        IF v_existing.runtime_plan_sha256<>p_runtime_plan_sha256 THEN
            IF v_existing.operational_state<>'pending' THEN
                RAISE EXCEPTION USING ERRCODE='23505',
                    MESSAGE='Analytics Catalog ready runtime plan differs';
            END IF;
            UPDATE analytics_catalog_version_projections
            SET runtime_plan_bytes=p_runtime_plan_bytes,
                runtime_plan_sha256=p_runtime_plan_sha256,
                blocker_code=v_blocker_code,updated_at=p_occurred_at
            WHERE receipt_id=v_existing.receipt_id;
        END IF;
        RETURN v_existing.receipt_id;
    END IF;
    SELECT * INTO v_component
    FROM analytics_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO analytics_catalog_components(
            component_id,component_kind,contract,content_sha256,
            owner_generation,writer_state,lifecycle_state,updated_at
        ) VALUES (
            p_component_id,p_component_kind,p_contract,p_content_sha256,
            p_owner_generation,'v2','AVAILABLE',p_occurred_at
        );
    ELSE
        SELECT EXISTS(
            SELECT 1 FROM analytics_catalog_component_heads AS head
            WHERE head.component_id=p_component_id
        ) INTO v_has_head;
        IF v_component.component_kind<>p_component_kind OR
           v_component.contract<>p_contract OR
           v_component.owner_generation<>p_owner_generation OR
           v_component.writer_state<>'v2' OR
           v_component.lifecycle_state NOT IN
               ('AVAILABLE','STAGED','ACTIVE','DISABLED','RETIRED') OR
           (NOT v_has_head AND
            v_component.content_sha256<>p_content_sha256) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog component authority differs';
        END IF;
    END IF;
    INSERT INTO analytics_catalog_version_projections(
        receipt_id,package_id,package_slug,package_version,release_id,
        component_id,owner_generation,contract,content_sha256,component_kind,
        analytics_kind,module_slug,semantic_identity,semantic_sha256,
        item_count,auxiliary_count,name,description,legacy_hash,
        definition_json,definition_sha256,document_bytes,runtime_plan_bytes,
        runtime_plan_sha256,operational_state,blocker_code,created_at,updated_at
    ) VALUES (
        p_receipt_id,p_package_id,p_package_slug,p_package_version,p_release_id,
        p_component_id,p_owner_generation,p_contract,p_content_sha256,
        p_component_kind,v_analytics_kind,p_module_slug,
        p_semantic_identity,p_semantic_sha256,p_item_count,p_auxiliary_count,
        v_name,v_description,v_legacy_hash,
        v_definition,v_definition_sha256,p_document_bytes,
        p_runtime_plan_bytes,p_runtime_plan_sha256,'pending',
        v_blocker_code,p_occurred_at,p_occurred_at
    );
    RETURN p_receipt_id;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_begin_v2(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_evidence_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_evidence_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog projection evidence is immutable';
    END IF;
    IF ROW(
        NEW.receipt_id,NEW.package_id,NEW.package_slug,NEW.package_version,
        NEW.release_id,NEW.component_id,NEW.owner_generation,NEW.contract,
        NEW.content_sha256,NEW.component_kind,NEW.analytics_kind,
        NEW.module_slug,NEW.semantic_identity,NEW.semantic_sha256,
        NEW.item_count,NEW.auxiliary_count,NEW.name,NEW.description,
        NEW.legacy_hash,NEW.definition_json,NEW.definition_sha256,
        NEW.document_bytes,NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.receipt_id,OLD.package_id,OLD.package_slug,OLD.package_version,
        OLD.release_id,OLD.component_id,OLD.owner_generation,OLD.contract,
        OLD.content_sha256,OLD.component_kind,OLD.analytics_kind,
        OLD.module_slug,OLD.semantic_identity,OLD.semantic_sha256,
        OLD.item_count,OLD.auxiliary_count,OLD.name,OLD.description,
        OLD.legacy_hash,OLD.definition_json,OLD.definition_sha256,
        OLD.document_bytes,OLD.created_at
    ) OR NEW.updated_at<OLD.updated_at OR
       (OLD.operational_state='ready' AND NEW IS DISTINCT FROM OLD) OR
       (OLD.operational_state='pending' AND
        NEW.operational_state NOT IN ('pending','ready')) OR
       (OLD.operational_state='pending' AND
        NEW.operational_state='pending' AND ROW(
            NEW.operational_resource_id,NEW.published_version_id,
            NEW.current_draft_version_id,NEW.ready_at
        ) IS DISTINCT FROM ROW(
            OLD.operational_resource_id,OLD.published_version_id,
            OLD.current_draft_version_id,OLD.ready_at
        )) OR
       (OLD.operational_state='pending' AND
        NEW.operational_state='ready' AND (
            ROW(NEW.runtime_plan_bytes,NEW.runtime_plan_sha256)
              IS DISTINCT FROM
            ROW(OLD.runtime_plan_bytes,OLD.runtime_plan_sha256) OR
            NEW.ready_at<OLD.updated_at OR NEW.updated_at<>NEW.ready_at
        )) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog projection evidence update differs';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_evidence_guard_v1() OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_materialize_v1(name, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_materialize_v1(p_scope_schema name, p_receipt_id uuid, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_provision analytics_catalog_provisions%ROWTYPE;
    v_definition analytics_catalog_definitions%ROWTYPE;
    v_component analytics_catalog_components%ROWTYPE;
    v_original jsonb;
    v_plan jsonb;
    v_state text;
    v_blocker text;
    v_resource_id uuid;
    v_published_id uuid;
    v_draft_id uuid;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog materialization input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT * INTO v_provision FROM analytics_catalog_provisions AS provision
    WHERE provision.receipt_id=p_receipt_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog provision is unavailable';
    END IF;
    SELECT * INTO v_definition FROM analytics_catalog_definitions AS definition
    WHERE definition.component_id=v_provision.component_id FOR UPDATE;
    SELECT * INTO v_component FROM analytics_catalog_components AS component
    WHERE component.component_id=v_provision.component_id FOR UPDATE;
    IF NOT FOUND OR v_component.owner_generation<>v_provision.owner_generation OR
       v_component.contract<>v_provision.contract OR
       v_component.content_sha256<>v_provision.content_sha256 OR
       v_component.writer_state<>'v2' OR
       v_component.lifecycle_state NOT IN ('AVAILABLE','STAGED','ACTIVE') OR
       p_occurred_at<v_provision.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog materialization authority differs';
    END IF;
    IF v_provision.ready_at IS NOT NULL THEN
        IF v_definition.operational_state<>'ready' OR
           v_definition.operational_resource_id IS NULL OR
           v_definition.published_version_id IS NULL OR
           v_definition.current_draft_version_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog ready evidence differs';
        END IF;
        RETURN;
    END IF;
    v_original := pg_catalog.convert_from(v_definition.document_bytes,'UTF8')::jsonb;
    v_plan := pg_catalog.convert_from(v_definition.runtime_plan_bytes,'UTF8')::jsonb;
    IF v_definition.analytics_kind='endpoint' THEN
        SELECT result.operational_state,result.blocker_code,
            result.operational_resource_id,result.published_version_id,
            result.current_draft_version_id
        INTO v_state,v_blocker,v_resource_id,v_published_id,v_draft_id
        FROM analytics_catalog_materialize_endpoint_v1(
            p_scope_schema,v_definition.component_id,v_provision.actor_id,
            v_original,v_plan,p_occurred_at
        ) AS result;
    ELSIF v_definition.analytics_kind='dashboard' THEN
        SELECT result.operational_state,result.blocker_code,
            result.operational_resource_id,result.published_version_id,
            result.current_draft_version_id
        INTO v_state,v_blocker,v_resource_id,v_published_id,v_draft_id
        FROM analytics_catalog_materialize_dashboard_v1(
            p_scope_schema,v_definition.component_id,v_provision.actor_id,
            v_original,v_plan,p_occurred_at
        ) AS result;
    ELSE
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog materialization kind differs';
    END IF;
    IF v_state='ready' THEN
        IF pg_catalog.uuid_extract_version(v_resource_id) IS DISTINCT FROM 7 OR
           pg_catalog.uuid_extract_version(v_published_id) IS DISTINCT FROM 7 OR
           pg_catalog.uuid_extract_version(v_draft_id) IS DISTINCT FROM 7 OR
           v_blocker IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog ready result is invalid';
        END IF;
        UPDATE analytics_catalog_definitions AS definition
        SET operational_state='ready',blocker_code=NULL,
            operational_resource_id=v_resource_id,
            published_version_id=v_published_id,
            current_draft_version_id=v_draft_id,updated_at=p_occurred_at
        WHERE definition.component_id=v_definition.component_id;
        UPDATE analytics_catalog_provisions AS provision
        SET ready_at=p_occurred_at,updated_at=p_occurred_at
        WHERE provision.receipt_id=p_receipt_id;
    ELSIF v_state='pending' AND
          v_blocker ~ '^[A-Z][A-Z0-9_]{0,127}$' THEN
        UPDATE analytics_catalog_definitions AS definition
        SET blocker_code=v_blocker,updated_at=p_occurred_at
        WHERE definition.component_id=v_definition.component_id;
        UPDATE analytics_catalog_provisions AS provision
        SET updated_at=p_occurred_at
        WHERE provision.receipt_id=p_receipt_id;
    ELSE
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog materialization result is invalid';
    END IF;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_materialize_v1(p_scope_schema name, p_receipt_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_materialize_v2(name, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_materialize_v2(p_scope_schema name, p_attempt_receipt_id uuid, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_attempt analytics_catalog_projection_attempts%ROWTYPE;
    v_projection analytics_catalog_version_projections%ROWTYPE;
    v_component analytics_catalog_components%ROWTYPE;
    v_original jsonb;
    v_plan jsonb;
    v_state text;
    v_blocker text;
    v_resource_id uuid;
    v_published_id uuid;
    v_draft_id uuid;
    v_version_seed uuid;
    v_was_activated boolean;
    v_candidate_projection_id uuid;
BEGIN
    IF pg_catalog.uuid_extract_version(p_attempt_receipt_id)
           IS DISTINCT FROM 7 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog materialization input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT attempt.* INTO v_attempt
    FROM analytics_catalog_projection_attempts AS attempt
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=attempt.projection_receipt_id
    WHERE attempt.receipt_id=p_attempt_receipt_id
    FOR UPDATE OF attempt,projection;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog materialization attempt is unavailable';
    END IF;
    SELECT * INTO v_projection
    FROM analytics_catalog_version_projections AS projection
    WHERE projection.receipt_id=v_attempt.projection_receipt_id;
    IF NOT FOUND OR p_occurred_at<v_attempt.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog materialization attempt is unavailable';
    END IF;
    SELECT * INTO v_component
    FROM analytics_catalog_components AS component
    WHERE component.component_id=v_projection.component_id FOR UPDATE;
    IF NOT FOUND OR
       v_component.owner_generation<>v_projection.owner_generation OR
       v_component.contract<>v_projection.contract OR
       v_component.writer_state<>'v2' OR
       v_component.lifecycle_state NOT IN
           ('AVAILABLE','STAGED','ACTIVE','DISABLED') THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog materialization authority differs';
    END IF;
    IF v_projection.operational_state='ready' THEN
        v_state:='ready';
        v_resource_id:=v_projection.operational_resource_id;
        v_published_id:=v_projection.published_version_id;
        v_draft_id:=v_projection.current_draft_version_id;
    ELSE
        v_original:=pg_catalog.convert_from(
            v_projection.document_bytes,'UTF8'
        )::jsonb;
        v_plan:=pg_catalog.convert_from(
            v_projection.runtime_plan_bytes,'UTF8'
        )::jsonb;
        v_version_seed:=analytics_catalog_projection_seed_v2(
            v_projection.component_id,v_projection.package_id,
            v_projection.package_version,v_projection.release_id,
            v_projection.content_sha256
        );
        IF v_projection.analytics_kind='endpoint' THEN
            SELECT result.operational_state,result.blocker_code,
                result.operational_resource_id,result.published_version_id,
                result.current_draft_version_id
            INTO v_state,v_blocker,v_resource_id,v_published_id,v_draft_id
            FROM analytics_catalog_materialize_endpoint_v1(
                p_scope_schema,v_version_seed,v_attempt.actor_id,
                v_original,v_plan,p_occurred_at
            ) AS result;
        ELSIF v_projection.analytics_kind='dashboard' THEN
            SELECT result.operational_state,result.blocker_code,
                result.operational_resource_id,result.published_version_id,
                result.current_draft_version_id
            INTO v_state,v_blocker,v_resource_id,v_published_id,v_draft_id
            FROM analytics_catalog_materialize_dashboard_v2(
                p_scope_schema,v_projection.component_id,v_version_seed,
                v_projection.package_id,v_projection.package_version,
                v_projection.release_id,v_attempt.actor_id,
                v_original,v_plan,p_occurred_at
            ) AS result;
        ELSE
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog materialization kind differs';
        END IF;
    END IF;
    IF v_state='ready' THEN
        IF pg_catalog.uuid_extract_version(v_resource_id) IS DISTINCT FROM 7 OR
           pg_catalog.uuid_extract_version(v_published_id) IS DISTINCT FROM 7 OR
           pg_catalog.uuid_extract_version(v_draft_id) IS DISTINCT FROM 7 OR
           v_blocker IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog ready result is invalid';
        END IF;
        UPDATE analytics_catalog_version_projections AS projection
        SET operational_state='ready',blocker_code=NULL,
            operational_resource_id=v_resource_id,
            published_version_id=v_published_id,
            current_draft_version_id=v_draft_id,
            ready_at=COALESCE(projection.ready_at,p_occurred_at),
            updated_at=CASE WHEN projection.ready_at IS NULL
                THEN p_occurred_at ELSE projection.updated_at END
        WHERE projection.receipt_id=v_projection.receipt_id;
        UPDATE analytics_catalog_projection_attempts AS attempt
        SET ready_at=COALESCE(attempt.ready_at,p_occurred_at),
            updated_at=CASE WHEN attempt.ready_at IS NULL
                THEN p_occurred_at ELSE attempt.updated_at END
        WHERE attempt.receipt_id=p_attempt_receipt_id;
        SELECT EXISTS(
            SELECT 1 FROM analytics_catalog_projection_activations AS activation
            WHERE activation.projection_receipt_id=v_projection.receipt_id
        ) INTO v_was_activated;
        IF NOT v_was_activated THEN
            SELECT candidate.projection_receipt_id
            INTO v_candidate_projection_id
            FROM analytics_catalog_component_candidates AS candidate
            WHERE candidate.component_id=v_projection.component_id
            FOR UPDATE;
            IF FOUND AND
               v_candidate_projection_id<>v_projection.receipt_id THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='Analytics Catalog component candidate is unresolved';
            END IF;
            PERFORM analytics_catalog_operational_stage_v2(
                p_scope_schema,p_attempt_receipt_id,p_occurred_at
            );
            INSERT INTO analytics_catalog_component_candidates(
                component_id,projection_receipt_id,attempt_receipt_id,
                package_id,package_version,release_id,owner_generation,
                content_sha256,staged_operation_id,prepared_at
            ) VALUES (
                v_projection.component_id,v_projection.receipt_id,
                p_attempt_receipt_id,v_projection.package_id,
                v_projection.package_version,v_projection.release_id,
                v_projection.owner_generation,v_projection.content_sha256,
                NULL,p_occurred_at
            ) ON CONFLICT ON CONSTRAINT
                analytics_catalog_component_candidates_pkey DO UPDATE SET
                projection_receipt_id=EXCLUDED.projection_receipt_id,
                attempt_receipt_id=EXCLUDED.attempt_receipt_id,
                package_id=EXCLUDED.package_id,
                package_version=EXCLUDED.package_version,
                release_id=EXCLUDED.release_id,
                owner_generation=EXCLUDED.owner_generation,
                content_sha256=EXCLUDED.content_sha256,
                staged_operation_id=CASE
                  WHEN analytics_catalog_component_candidates.attempt_receipt_id=
                       EXCLUDED.attempt_receipt_id
                    THEN analytics_catalog_component_candidates.staged_operation_id
                  ELSE NULL END,
                prepared_at=EXCLUDED.prepared_at
              WHERE analytics_catalog_component_candidates.
                    projection_receipt_id=EXCLUDED.projection_receipt_id;
            IF NOT FOUND THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='Analytics Catalog candidate refresh was not applied';
            END IF;
        END IF;
    ELSIF v_state='pending' AND
          v_blocker ~ '^[A-Z][A-Z0-9_]{0,127}$' THEN
        UPDATE analytics_catalog_version_projections
        SET blocker_code=v_blocker,updated_at=p_occurred_at
        WHERE receipt_id=v_projection.receipt_id;
        UPDATE analytics_catalog_projection_attempts
        SET updated_at=p_occurred_at
        WHERE receipt_id=p_attempt_receipt_id;
    ELSE
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog materialization result is invalid';
    END IF;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_materialize_v2(p_scope_schema name, p_attempt_receipt_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_read_v2(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_read_v2(p_receipt_id uuid) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, component_kind text, module_slug text, semantic_identity text, semantic_sha256 bytea, item_count integer, auxiliary_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT attempt.receipt_id,projection.package_id,
        projection.package_slug,projection.package_version,
        projection.release_id,projection.component_id,
        projection.owner_generation,projection.contract,
        projection.content_sha256,projection.component_kind,
        projection.module_slug,projection.semantic_identity,
        projection.semantic_sha256,projection.item_count,
        projection.auxiliary_count,projection.document_bytes,
        attempt.idempotency_key,attempt.request_sha256,
        CASE
          WHEN candidate.attempt_receipt_id=attempt.receipt_id
           AND head.component_id IS NULL
           AND component.lifecycle_state='AVAILABLE'
            THEN 'AVAILABLE'
          ELSE 'STAGED'
        END,
        attempt.ready_at,attempt.created_at,attempt.updated_at
    FROM analytics_catalog_projection_attempts AS attempt
    JOIN analytics_catalog_version_projections AS projection
      ON projection.receipt_id=attempt.projection_receipt_id
    JOIN analytics_catalog_components AS component
      ON component.component_id=projection.component_id
    LEFT JOIN analytics_catalog_component_candidates AS candidate
      ON candidate.component_id=projection.component_id
     AND candidate.projection_receipt_id=projection.receipt_id
    LEFT JOIN analytics_catalog_component_heads AS head
      ON head.component_id=projection.component_id
    WHERE attempt.receipt_id=p_receipt_id
      AND component.lifecycle_state<>'PURGED'
      AND (
        (projection.operational_state='pending'
         AND projection.blocker_code IS NOT NULL
         AND projection.ready_at IS NULL
         AND attempt.ready_at IS NULL)
        OR
        (projection.operational_state='ready'
         AND projection.blocker_code IS NULL
         AND projection.operational_resource_id IS NOT NULL
         AND projection.published_version_id IS NOT NULL
         AND projection.current_draft_version_id IS NOT NULL
         AND projection.ready_at IS NOT NULL
         AND attempt.ready_at IS NOT NULL)
      );
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_read_v2(p_receipt_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_seed_v2(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_seed_v2(p_component_id uuid, p_package_id uuid, p_package_version text, p_release_id uuid, p_content_sha256 text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_bytes bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_package_version) NOT BETWEEN 5 AND 128 OR
       p_content_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection seed input is invalid';
    END IF;
    v_bytes:=pg_catalog.substring(pg_catalog.sha256(
        pg_catalog.convert_to('harpy:analytics:catalog:projection:v2','UTF8')||
        pg_catalog.uuid_send(p_component_id)||
        pg_catalog.uuid_send(p_package_id)||
        pg_catalog.int4send(pg_catalog.octet_length(p_package_version))||
        pg_catalog.convert_to(p_package_version,'UTF8')||
        pg_catalog.uuid_send(p_release_id)||
        pg_catalog.decode(p_content_sha256,'hex')
    ),1,16);
    v_bytes:=pg_catalog.set_byte(
        v_bytes,6,(pg_catalog.get_byte(v_bytes,6)&15)|112
    );
    v_bytes:=pg_catalog.set_byte(
        v_bytes,8,(pg_catalog.get_byte(v_bytes,8)&63)|128
    );
    RETURN pg_catalog.encode(v_bytes,'hex')::uuid;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_seed_v2(p_component_id uuid, p_package_id uuid, p_package_version text, p_release_id uuid, p_content_sha256 text) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_projection_validate_v2(text, text, uuid, text, text, text, bytea, integer, integer, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_projection_validate_v2(p_contract text, p_content_sha256 text, p_component_id uuid, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea) RETURNS TABLE(analytics_kind text, name text, description text, legacy_hash text, definition_json jsonb, definition_sha256 bytea, blocker_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_original jsonb;
    v_plan jsonb;
    v_kind text;
    v_auxiliary integer;
    v_blocker text;
    v_expected_sources jsonb;
    v_valid_sources bigint;
BEGIN
    IF p_contract IS DISTINCT FROM 'analytics.catalog-definition.v1' OR
       p_content_sha256 IS NULL OR
       p_content_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_component_kind IS NULL OR
       p_component_kind NOT IN ('ENDPOINT','DASHBOARD') OR
       p_module_slug IS NULL OR
       p_module_slug !~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$' OR
       p_semantic_identity IS NULL OR
       p_semantic_identity !~ '^[a-z][a-z0-9-]{1,62}$' OR
       pg_catalog.octet_length(p_semantic_sha256) IS DISTINCT FROM 32 OR
       p_item_count IS DISTINCT FROM 1 OR p_auxiliary_count<2 OR
       pg_catalog.octet_length(p_runtime_plan_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.encode(pg_catalog.sha256(p_document_bytes),'hex')
           IS DISTINCT FROM p_content_sha256 OR
       pg_catalog.sha256(p_runtime_plan_bytes)
           IS DISTINCT FROM p_runtime_plan_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection document input is invalid';
    END IF;
    BEGIN
        v_original:=pg_catalog.convert_from(p_document_bytes,'UTF8')::jsonb;
        v_plan:=pg_catalog.convert_from(p_runtime_plan_bytes,'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection document is invalid';
    END;
    v_kind:=v_original->>'kind';
    IF pg_catalog.jsonb_typeof(v_original) IS DISTINCT FROM 'object' OR
       v_original->>'contract_version' IS DISTINCT FROM p_contract OR
       v_original->>'component_id' IS DISTINCT FROM p_component_id::text OR
       v_original->>'analytics_id' IS DISTINCT FROM p_component_id::text OR
       v_original->>'source_contract' IS DISTINCT FROM
           'harpy-v1.enterprise-seed.'||p_module_slug OR
       v_original->>'slug' IS DISTINCT FROM p_semantic_identity OR
       v_original->>'name' IS NULL OR
       pg_catalog.octet_length(v_original->>'name') NOT BETWEEN 1 AND 100 OR
       v_original->>'description' IS NULL OR
       pg_catalog.octet_length(v_original->>'description')
           NOT BETWEEN 1 AND 2048 OR
       v_original->>'legacy_hash' IS NULL OR
       v_original->>'legacy_hash' !~ '^[0-9a-f]{64}$' OR
       v_original->>'legacy_hash'
           IS DISTINCT FROM pg_catalog.encode(p_semantic_sha256,'hex') OR
       v_kind IS NULL OR v_kind NOT IN ('endpoint','dashboard') OR
       (v_kind='endpoint' AND p_component_kind<>'ENDPOINT') OR
       (v_kind='dashboard' AND p_component_kind<>'DASHBOARD') OR
       pg_catalog.jsonb_typeof(v_original#>'{definition,dataSources}')
           IS DISTINCT FROM 'array' OR
       v_plan->>'contract'
           IS DISTINCT FROM 'analytics.catalog-runtime-plan.v1' OR
       v_plan->>'kind' IS DISTINCT FROM v_kind OR
       v_plan->>'component_id' IS DISTINCT FROM p_component_id::text OR
       v_plan->>'source_contract' IS DISTINCT FROM
           v_original->>'source_contract' OR
       v_plan->>'document_sha256' IS DISTINCT FROM p_content_sha256 OR
       v_plan->>'status' IS NULL OR
       v_plan->>'status' NOT IN ('candidate','pending') OR
       pg_catalog.jsonb_typeof(v_plan->'sources') IS DISTINCT FROM 'array' THEN
       RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection binding differs';
    END IF;
    IF v_kind='endpoint' THEN
        IF pg_catalog.jsonb_typeof(v_original#>'{definition,fields}')
               IS DISTINCT FROM 'array' OR
           pg_catalog.jsonb_array_length(
               v_original#>'{definition,dataSources}'
           )<1 OR
           pg_catalog.jsonb_array_length(
               v_original#>'{definition,fields}'
           )<1 THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics Catalog endpoint is invalid';
        END IF;
        SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(
                   source.value->>'formSlug'
               ) ORDER BY source.ordinality),
               pg_catalog.count(*) FILTER (WHERE
                   pg_catalog.jsonb_typeof(source.value)='object' AND
                   source.value->>'formSlug' IS NOT NULL AND
                   source.value->>'formSlug'<>''
               )
        INTO v_expected_sources,v_valid_sources
        FROM pg_catalog.jsonb_array_elements(
            v_original#>'{definition,dataSources}'
        ) WITH ORDINALITY AS source(value,ordinality);
        IF v_expected_sources IS DISTINCT FROM v_plan->'sources' OR
           v_valid_sources<>pg_catalog.jsonb_array_length(
               v_original#>'{definition,dataSources}'
           ) OR pg_catalog.jsonb_typeof(v_plan->'parameters')
               IS DISTINCT FROM 'object' OR
           pg_catalog.jsonb_typeof(v_plan->'output')
               IS DISTINCT FROM 'object' OR
           (v_plan->>'status'='candidate' AND
            pg_catalog.jsonb_typeof(v_plan->'query')
                IS DISTINCT FROM 'object') OR
           (v_plan->>'status'='pending' AND v_plan ? 'query') OR
           v_plan ? 'dashboard' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics Catalog endpoint plan differs';
        END IF;
        v_auxiliary:=
            pg_catalog.jsonb_array_length(v_original#>'{definition,dataSources}')+
            pg_catalog.jsonb_array_length(v_original#>'{definition,fields}');
    ELSE
        IF pg_catalog.jsonb_typeof(v_original#>'{definition,widgets}')
               IS DISTINCT FROM 'array' OR
           pg_catalog.jsonb_array_length(
               v_original#>'{definition,dataSources}'
           )<1 OR
           pg_catalog.jsonb_array_length(
               v_original#>'{definition,widgets}'
           )<1 THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics Catalog dashboard is invalid';
        END IF;
        SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(
                   source.value->>'endpointSlug'
               ) ORDER BY source.ordinality),
               pg_catalog.count(*) FILTER (WHERE
                   pg_catalog.jsonb_typeof(source.value)='object' AND
                   source.value->>'endpointSlug' IS NOT NULL AND
                   source.value->>'endpointSlug'<>''
               )
        INTO v_expected_sources,v_valid_sources
        FROM pg_catalog.jsonb_array_elements(
            v_original#>'{definition,dataSources}'
        ) WITH ORDINALITY AS source(value,ordinality);
        IF v_plan->>'status'<>'candidate' OR
           v_expected_sources IS DISTINCT FROM v_plan->'sources' OR
           v_valid_sources<>pg_catalog.jsonb_array_length(
               v_original#>'{definition,dataSources}'
           ) OR v_plan->'dashboard' IS DISTINCT FROM
               v_original->'definition' OR
           v_plan ? 'query' OR v_plan ? 'parameters' OR v_plan ? 'output' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics Catalog dashboard plan differs';
        END IF;
        v_auxiliary:=
            pg_catalog.jsonb_array_length(v_original#>'{definition,dataSources}')+
            pg_catalog.jsonb_array_length(v_original#>'{definition,widgets}');
    END IF;
    IF v_auxiliary<>p_auxiliary_count OR
       (v_plan->>'status'='pending' AND (
        v_plan->>'blocker_code' IS NULL OR
        v_plan->>'blocker_code' !~ '^[A-Z][A-Z0-9_]{0,127}$'
       )) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog projection composition differs';
    END IF;
    v_blocker:=CASE WHEN v_plan->>'status'='pending'
        THEN v_plan->>'blocker_code'
        ELSE 'ANALYTICS_DEPENDENCY_NOT_READY' END;
    RETURN QUERY SELECT v_kind,v_original->>'name',
        v_original->>'description',v_original->>'legacy_hash',
        v_original->'definition',
        pg_catalog.sha256(pg_catalog.convert_to(
            (v_original->'definition')::text,'UTF8'
        )),v_blocker;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_projection_validate_v2(p_contract text, p_content_sha256 text, p_component_id uuid, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_runtime_plan_bytes bytea, p_runtime_plan_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_purge_data_v2(text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_purge_data_v2(p_analytics_kind text, p_root_id uuid, p_operation_id uuid, p_completed_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_deleted bigint;
BEGIN
    IF p_analytics_kind NOT IN ('endpoint','dashboard') OR
       pg_catalog.uuid_extract_version(p_root_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog purge data input is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:legal-hold',6100
    ));
    IF EXISTS (
        SELECT 1 FROM analytics_legal_holds AS hold
        WHERE hold.state='active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge is under legal hold';
    END IF;
    IF p_analytics_kind='endpoint' THEN
        PERFORM 1 FROM analytics_saved_queries AS root
        WHERE root.id=p_root_id AND root.lifecycle_state='retired'
          AND root.updated_at<=p_completed_at
        FOR UPDATE;
        IF NOT FOUND OR EXISTS (
            SELECT 1 FROM analytics_saved_query_versions AS version_row
            WHERE version_row.query_id=p_root_id
              AND version_row.updated_at>p_completed_at
        ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog purge query differs';
        END IF;
        PERFORM 1 FROM analytics_saved_query_versions AS version_row
        WHERE version_row.query_id=p_root_id
        ORDER BY version_row.id FOR UPDATE;
        UPDATE analytics_saved_query_versions AS version_row
        SET version_state='retired',
            row_revision=version_row.row_revision+1,
            updated_at=p_completed_at
        WHERE version_row.query_id=p_root_id
          AND version_row.version_state IN (
              'published','needs_revalidation'
          );
        UPDATE analytics_saved_queries AS root
        SET current_draft_version_id=NULL,
            row_revision=root.row_revision+1,
            reference_epoch=root.reference_epoch+1,
            updated_at=p_completed_at
        WHERE root.id=p_root_id AND root.lifecycle_state='retired';
    ELSE
        PERFORM 1 FROM analytics_dashboards AS root
        WHERE root.id=p_root_id AND root.lifecycle_state='retired'
          AND root.updated_at<=p_completed_at
        FOR UPDATE;
        IF NOT FOUND OR EXISTS (
            SELECT 1 FROM analytics_dashboard_versions AS version_row
            WHERE version_row.dashboard_id=p_root_id
              AND version_row.updated_at>p_completed_at
        ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Analytics Catalog purge dashboard differs';
        END IF;
        PERFORM 1 FROM analytics_dashboard_versions AS version_row
        WHERE version_row.dashboard_id=p_root_id
        ORDER BY version_row.id FOR UPDATE;
        UPDATE analytics_dashboard_versions AS version_row
        SET version_state='retired',
            row_revision=version_row.row_revision+1,
            updated_at=p_completed_at
        WHERE version_row.dashboard_id=p_root_id
          AND version_row.version_state='published';
        UPDATE analytics_dashboards AS root
        SET current_draft_version_id=NULL,
            row_revision=root.row_revision+1,
            reference_epoch=root.reference_epoch+1,
            updated_at=p_completed_at
        WHERE root.id=p_root_id AND root.lifecycle_state='retired';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge root changed';
    END IF;
    INSERT INTO analytics_retention_contexts(
        backend_pid,transaction_id,job_id,opened_at
    ) VALUES (
        pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id(),
        p_operation_id,p_completed_at
    );
    IF p_analytics_kind='endpoint' THEN
        DELETE FROM analytics_query_dependencies AS dependency
        USING analytics_saved_query_versions AS version_row
        WHERE version_row.query_id=p_root_id
          AND dependency.query_version_id=version_row.id;
        DELETE FROM analytics_saved_query_versions AS version_row
        WHERE version_row.query_id=p_root_id;
        DELETE FROM analytics_saved_queries AS root
        WHERE root.id=p_root_id AND root.lifecycle_state='retired'
          AND root.current_draft_version_id IS NULL;
    ELSE
        DELETE FROM analytics_dashboard_widgets AS widget
        USING analytics_dashboard_versions AS version_row
        WHERE version_row.dashboard_id=p_root_id
          AND widget.dashboard_version_id=version_row.id;
        DELETE FROM analytics_dashboard_acls AS acl
        WHERE acl.dashboard_id=p_root_id;
        DELETE FROM analytics_dashboard_preferences AS preference
        WHERE preference.dashboard_id=p_root_id;
        DELETE FROM analytics_dashboard_versions AS version_row
        WHERE version_row.dashboard_id=p_root_id;
        DELETE FROM analytics_dashboards AS root
        WHERE root.id=p_root_id AND root.lifecycle_state='retired'
          AND root.current_draft_version_id IS NULL;
    END IF;
    GET DIAGNOSTICS v_deleted=ROW_COUNT;
    IF v_deleted<>1 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge root delete differs';
    END IF;
    DELETE FROM analytics_retention_contexts AS context
    WHERE context.backend_pid=pg_catalog.pg_backend_pid()
      AND context.transaction_id=pg_catalog.pg_current_xact_id()
      AND context.job_id=p_operation_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog purge context differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_purge_data_v2(p_analytics_kind text, p_root_id uuid, p_operation_id uuid, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_resource_manifest_v2(name, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_resource_manifest_v2(p_scope_schema name, p_resource_kind text, p_version_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_manifest bytea;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    IF p_resource_kind='query' THEN
        SELECT version_row.manifest_sha256 INTO v_manifest
        FROM analytics_saved_query_versions AS version_row
        JOIN analytics_saved_queries AS root
          ON root.id=version_row.query_id
         AND root.lifecycle_state IN ('active','staged')
        WHERE version_row.id=p_version_id
          AND version_row.version_state='published';
    ELSIF p_resource_kind='dashboard' THEN
        SELECT version_row.manifest_sha256 INTO v_manifest
        FROM analytics_dashboard_versions AS version_row
        JOIN analytics_dashboards AS root
          ON root.id=version_row.dashboard_id
         AND root.lifecycle_state IN ('active','staged')
        WHERE version_row.id=p_version_id
          AND version_row.version_state='published';
    ELSE
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog resource kind is invalid';
    END IF;
    IF pg_catalog.octet_length(v_manifest) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics Catalog immutable resource is unavailable';
    END IF;
    RETURN v_manifest;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_resource_manifest_v2(p_scope_schema name, p_resource_kind text, p_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_catalog_uuid_v7_v1(uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_catalog_uuid_v7_v1(p_component_id uuid, p_label text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_bytes bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_label IS NULL OR
       pg_catalog.octet_length(p_label) NOT BETWEEN 1 AND 100 OR
       p_label OPERATOR(pg_catalog.!~) '^[a-z0-9:-]+$' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics Catalog deterministic identity input is invalid';
    END IF;
    v_bytes := pg_catalog.substring(pg_catalog.sha256(
        pg_catalog.convert_to('harpy:analytics:catalog:v2','UTF8') ||
        pg_catalog.uuid_send(p_component_id) ||
        pg_catalog.decode('00','hex') ||
        pg_catalog.convert_to(p_label,'UTF8')
    ), 1, 16);
    v_bytes := pg_catalog.set_byte(
        v_bytes, 6, (pg_catalog.get_byte(v_bytes, 6) & 15) | 112
    );
    v_bytes := pg_catalog.set_byte(
        v_bytes, 8, (pg_catalog.get_byte(v_bytes, 8) & 63) | 128
    );
    RETURN pg_catalog.encode(v_bytes,'hex')::uuid;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_catalog_uuid_v7_v1(p_component_id uuid, p_label text) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_create_v1(name, uuid, uuid, text, bytea, uuid, uuid, text, text, bytea, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_create_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_version_id uuid, p_name text, p_visibility text, p_layout_document bytea, p_widgets jsonb, p_occurred_at timestamp with time zone) RETURNS TABLE(dashboard_id uuid, version_id uuid, version_no bigint, root_revision bigint, version_revision bigint, lifecycle_state text, version_state text, name text, visibility text, layout_document bytea, layout_sha256 bytea, manifest_sha256 bytea, widgets jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_existing analytics_operations%ROWTYPE; v_manifest bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_version_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_name) NOT BETWEEN 1 AND 100 OR
       p_visibility NOT IN ('private', 'tenant') OR
       pg_catalog.octet_length(p_layout_document) NOT BETWEEN 2 AND 65536 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard create input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:create:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'dashboard_create'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.result_version_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics dashboard replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true FROM analytics_dashboard_get_version_v1(
            p_scope_schema, v_existing.resource_id, v_existing.result_version_id) AS result;
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM analytics_dashboards WHERE id = p_dashboard_id) OR
       EXISTS (SELECT 1 FROM analytics_dashboard_versions WHERE id = p_version_id) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6104', MESSAGE = 'analytics dashboard identity exists';
    END IF;
    v_manifest := pg_catalog.sha256(p_layout_document || pg_catalog.convert_to(p_widgets::text, 'UTF8'));
    SET CONSTRAINTS analytics_dashboards_current_draft_fk DEFERRED;
    INSERT INTO analytics_dashboards VALUES (
        p_dashboard_id, 'active', 1, 1, p_version_id,
        p_actor_id, p_actor_id, p_occurred_at, p_occurred_at);
    INSERT INTO analytics_dashboard_versions (
        id, dashboard_id, version_no, version_state, row_revision, name, visibility,
        layout_document, layout_sha256, manifest_sha256, created_by, updated_by,
        created_at, updated_at
    ) VALUES (p_version_id, p_dashboard_id, 1, 'draft', 1, p_name, p_visibility,
        p_layout_document, pg_catalog.sha256(p_layout_document), v_manifest,
        p_actor_id, p_actor_id, p_occurred_at, p_occurred_at);
    PERFORM analytics_dashboard_widgets_replace_v1(p_version_id, p_widgets, p_occurred_at);
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at,
        result_version_id
    ) VALUES (p_operation_id, p_actor_id, 'dashboard_create', p_idempotency_key,
        p_request_sha256, 'dashboard', p_dashboard_id, 1, v_manifest, p_occurred_at, p_version_id);
    RETURN QUERY SELECT result.*, false FROM analytics_dashboard_get_version_v1(
        p_scope_schema, p_dashboard_id, p_version_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_create_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_version_id uuid, p_name text, p_visibility text, p_layout_document bytea, p_widgets jsonb, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_delete_v1(name, uuid, uuid, text, bytea, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_delete_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_expected_root_revision bigint, p_occurred_at timestamp with time zone) RETURNS TABLE(dashboard_id uuid, version_id uuid, version_no bigint, root_revision bigint, version_revision bigint, lifecycle_state text, version_state text, name text, visibility text, layout_document bytea, layout_sha256 bytea, manifest_sha256 bytea, widgets jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_existing analytics_operations%ROWTYPE; v_version_id uuid; v_manifest bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_expected_root_revision < 1 OR p_occurred_at IS NULL OR
       NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard delete input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:delete:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'dashboard_delete'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.result_version_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics dashboard replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true FROM analytics_dashboard_get_version_v1(
            p_scope_schema, v_existing.resource_id, v_existing.result_version_id) AS result;
        RETURN;
    END IF;
    SELECT root.current_draft_version_id, version_row.manifest_sha256
    INTO v_version_id, v_manifest FROM analytics_dashboards AS root
    JOIN analytics_dashboard_versions AS version_row
      ON version_row.id = root.current_draft_version_id
    WHERE root.id = p_dashboard_id AND root.lifecycle_state = 'active'
      AND root.row_revision = p_expected_root_revision FOR UPDATE OF root, version_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics dashboard root changed';
    END IF;
    UPDATE analytics_dashboards SET lifecycle_state = 'retired',
        row_revision = row_revision + 1, reference_epoch = reference_epoch + 1,
        updated_by = p_actor_id, updated_at = p_occurred_at WHERE id = p_dashboard_id;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at,
        result_version_id
    ) VALUES (p_operation_id, p_actor_id, 'dashboard_delete', p_idempotency_key,
        p_request_sha256, 'dashboard', p_dashboard_id, p_expected_root_revision + 1,
        v_manifest, p_occurred_at, v_version_id);
    RETURN QUERY SELECT result.*, false FROM analytics_dashboard_get_version_v1(
        p_scope_schema, p_dashboard_id, v_version_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_delete_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_expected_root_revision bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_access_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_access_v1(p_actor_id uuid, p_dashboard_id uuid, p_version_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM analytics_dashboards AS root
        JOIN analytics_dashboard_versions AS version_row
          ON version_row.dashboard_id=root.id
        WHERE root.id=p_dashboard_id
          AND version_row.id=p_version_id
          AND (
              version_row.visibility='tenant'
              OR root.created_by=p_actor_id
              OR EXISTS (
                  SELECT 1 FROM analytics_dashboard_acls AS acl
                  WHERE acl.dashboard_id=root.id
                    AND acl.principal_kind='user'
                    AND acl.principal_id=p_actor_id
                    AND acl.access_level IN ('read','edit','publish')
              )
          )
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_access_v1(p_actor_id uuid, p_dashboard_id uuid, p_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_capacity_transition_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_capacity_transition_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_admission bigint;
    v_tenant_running bigint;
    v_principal_admission bigint;
    v_reservation analytics_dashboard_export_capacity_reservations%ROWTYPE;
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'queued' THEN
            RAISE EXCEPTION USING ERRCODE='P6112',
                MESSAGE='Analytics dashboard export admission state is invalid';
        END IF;
        INSERT INTO analytics_dashboard_export_capacity_counters(
            tenant_id,updated_at
        ) VALUES (NEW.tenant_id,NEW.updated_at) ON CONFLICT DO NOTHING;
        SELECT admission_count,running_count
        INTO v_tenant_admission,v_tenant_running
        FROM analytics_dashboard_export_capacity_counters
        WHERE tenant_id=NEW.tenant_id FOR UPDATE;
        IF v_tenant_admission>=20 THEN
            RAISE EXCEPTION USING ERRCODE='P6110',
                MESSAGE='Analytics dashboard export tenant admission is full';
        END IF;
        INSERT INTO analytics_dashboard_export_principal_counters(
            actor_id,updated_at
        ) VALUES (NEW.actor_id,NEW.updated_at) ON CONFLICT DO NOTHING;
        SELECT admission_count INTO v_principal_admission
        FROM analytics_dashboard_export_principal_counters
        WHERE actor_id=NEW.actor_id FOR UPDATE;
        IF v_principal_admission>=5 THEN
            RAISE EXCEPTION USING ERRCODE='P6110',
                MESSAGE='Analytics dashboard export principal admission is full';
        END IF;
        UPDATE analytics_dashboard_export_capacity_counters
        SET admission_count=admission_count+1,revision=revision+1,
            updated_at=GREATEST(updated_at+interval '1 microsecond',NEW.updated_at)
        WHERE tenant_id=NEW.tenant_id;
        UPDATE analytics_dashboard_export_principal_counters
        SET admission_count=admission_count+1,revision=revision+1,
            updated_at=GREATEST(updated_at+interval '1 microsecond',NEW.updated_at)
        WHERE actor_id=NEW.actor_id;
        INSERT INTO analytics_dashboard_export_capacity_reservations(
            export_id,tenant_id,actor_id,admission_held,running_held,
            acquired_at,updated_at
        ) VALUES (
            NEW.export_id,NEW.tenant_id,NEW.actor_id,true,false,
            NEW.created_at,NEW.updated_at
        );
        INSERT INTO analytics_dashboard_export_capacity_receipts(
            export_id,transition_kind,attempt_generation,tenant_id,actor_id,occurred_at
        ) VALUES (
            NEW.export_id,'admission_acquired',0,NEW.tenant_id,
            NEW.actor_id,NEW.updated_at
        );
        RETURN NEW;
    END IF;

    SELECT reservation.* INTO v_reservation
    FROM analytics_dashboard_export_capacity_reservations AS reservation
    WHERE reservation.export_id=NEW.export_id FOR UPDATE;
    IF v_reservation.export_id IS NULL THEN
        IF OLD.state NOT IN ('queued','running') AND
           NEW.state NOT IN ('queued','running') THEN
            RETURN NEW;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6112',
            MESSAGE='Analytics dashboard export capacity reservation is missing';
    END IF;

    IF OLD.state<>'running' AND NEW.state='running' THEN
        SELECT admission_count,running_count
        INTO v_tenant_admission,v_tenant_running
        FROM analytics_dashboard_export_capacity_counters
        WHERE tenant_id=NEW.tenant_id FOR UPDATE;
        IF NOT v_reservation.admission_held OR v_reservation.running_held OR
           v_tenant_running>=2 THEN
            RAISE EXCEPTION USING ERRCODE='P6111',
                MESSAGE='Analytics dashboard export running capacity is full';
        END IF;
        UPDATE analytics_dashboard_export_capacity_counters
        SET running_count=running_count+1,revision=revision+1,
            updated_at=GREATEST(updated_at+interval '1 microsecond',NEW.updated_at)
        WHERE tenant_id=NEW.tenant_id;
        UPDATE analytics_dashboard_export_capacity_reservations
        SET running_held=true,running_generation=NEW.attempt_generation,
            updated_at=NEW.updated_at WHERE export_id=NEW.export_id;
        INSERT INTO analytics_dashboard_export_capacity_receipts(
            export_id,transition_kind,attempt_generation,tenant_id,actor_id,occurred_at
        ) VALUES (
            NEW.export_id,'running_acquired',NEW.attempt_generation,
            NEW.tenant_id,NEW.actor_id,NEW.updated_at
        );
    END IF;

    IF OLD.state='running' AND NEW.state<>'running' THEN
        IF NOT v_reservation.running_held OR
           v_reservation.running_generation<>OLD.attempt_generation THEN
            RAISE EXCEPTION USING ERRCODE='P6112',
                MESSAGE='Analytics dashboard export running reservation differs';
        END IF;
        UPDATE analytics_dashboard_export_capacity_counters
        SET running_count=running_count-1,revision=revision+1,
            updated_at=GREATEST(updated_at+interval '1 microsecond',NEW.updated_at)
        WHERE tenant_id=NEW.tenant_id AND running_count>0;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6112',
                MESSAGE='Analytics dashboard export running counter underflow';
        END IF;
        UPDATE analytics_dashboard_export_capacity_reservations
        SET running_held=false,running_generation=NULL,updated_at=NEW.updated_at
        WHERE export_id=NEW.export_id;
        INSERT INTO analytics_dashboard_export_capacity_receipts(
            export_id,transition_kind,attempt_generation,tenant_id,actor_id,occurred_at
        ) VALUES (
            NEW.export_id,'running_released',OLD.attempt_generation,
            NEW.tenant_id,NEW.actor_id,NEW.updated_at
        );
    END IF;

    IF OLD.state IN ('queued','running') AND
       NEW.state NOT IN ('queued','running') THEN
        IF NOT v_reservation.admission_held THEN
            RAISE EXCEPTION USING ERRCODE='P6112',
                MESSAGE='Analytics dashboard export admission reservation differs';
        END IF;
        UPDATE analytics_dashboard_export_capacity_counters
        SET admission_count=admission_count-1,revision=revision+1,
            updated_at=GREATEST(updated_at+interval '1 microsecond',NEW.updated_at)
        WHERE tenant_id=NEW.tenant_id AND admission_count>0;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6112',
                MESSAGE='Analytics dashboard export tenant admission counter underflow';
        END IF;
        UPDATE analytics_dashboard_export_principal_counters
        SET admission_count=admission_count-1,revision=revision+1,
            updated_at=GREATEST(updated_at+interval '1 microsecond',NEW.updated_at)
        WHERE actor_id=NEW.actor_id AND admission_count>0;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6112',
                MESSAGE='Analytics dashboard export admission counter underflow';
        END IF;
        UPDATE analytics_dashboard_export_capacity_reservations
        SET admission_held=false,updated_at=NEW.updated_at
        WHERE export_id=NEW.export_id;
        INSERT INTO analytics_dashboard_export_capacity_receipts(
            export_id,transition_kind,attempt_generation,tenant_id,actor_id,occurred_at
        ) VALUES (
            NEW.export_id,'admission_released',0,NEW.tenant_id,
            NEW.actor_id,NEW.updated_at
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_capacity_transition_v1() OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_claim_v1(name, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_claim_v1(p_scope_schema name, p_export_id uuid, p_job_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) RETURNS TABLE(disposition text, state text, actor_id uuid, export_id uuid, dashboard_id uuid, dashboard_version_id uuid, job_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, dashboard_manifest_sha256 bytea, pin_sha256 bytea, format text, parameters_document bytea, pinned_widgets jsonb, maximum_rows bigint, maximum_plaintext_bytes bigint, expires_at timestamp with time zone, attempt_generation bigint, lease_owner uuid, effect_started boolean, object_key text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export analytics_dashboard_exports%ROWTYPE;
    v_tenant_id uuid;
    v_disposition text;
    v_release boolean:=false;
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       p_lease_owner IS NULL OR
       p_lease_owner='00000000-0000-0000-0000-000000000000'::uuid OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export claim input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton
      AND identity_row.schema_name=pg_catalog.current_schema();
    SELECT item.* INTO v_export
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.job_id=p_job_id
      AND item.tenant_id=v_tenant_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics dashboard export job was not found';
    END IF;
    IF v_export.state NOT IN ('queued','running') THEN
        RETURN QUERY SELECT * FROM
            analytics_dashboard_export_worker_snapshot_v1(p_export_id,'terminal');
        RETURN;
    END IF;
    IF v_export.expires_at<=p_observed_at OR
       v_export.cancellation_requested_at IS NOT NULL THEN
        v_release:=v_export.effect_started_at IS NULL AND
            v_export.quota_state='held';
        IF v_release THEN
            UPDATE platform.artifact_quota_counters
            SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
                revision=revision+1,updated_at=p_observed_at
            WHERE tenant_id=v_tenant_id
              AND reserved_ciphertext_bytes>=2147483648;
            IF NOT FOUND THEN
                RAISE EXCEPTION USING ERRCODE='P6105',
                    MESSAGE='analytics dashboard export quota release changed';
            END IF;
        END IF;
        UPDATE analytics_dashboard_exports
        SET state=CASE
                WHEN analytics_dashboard_exports.expires_at<=p_observed_at
                     AND effect_started_at IS NULL THEN 'expired'
                WHEN effect_started_at IS NOT NULL THEN 'deleting'
                ELSE 'cancelled'
            END,
            quota_state=CASE WHEN v_release THEN 'released' ELSE quota_state END,
            row_revision=row_revision+1,lease_owner=NULL,lease_until=NULL,
            updated_at=p_observed_at
        WHERE analytics_dashboard_exports.export_id=p_export_id;
        RETURN QUERY SELECT * FROM
            analytics_dashboard_export_worker_snapshot_v1(p_export_id,'terminal');
        RETURN;
    END IF;
    IF v_export.state='running' AND v_export.lease_until>p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='55P03',
            MESSAGE='analytics dashboard export lease is active';
    END IF;
    IF v_export.state='running' AND v_export.effect_started_at IS NOT NULL THEN
        IF v_export.quota_state<>'held' THEN
            RAISE EXCEPTION USING ERRCODE='P6105',
                MESSAGE='analytics dashboard export reconcile quota is missing';
        END IF;
        v_disposition:='reconcile';
    ELSIF v_export.attempt_generation>=3 THEN
        IF v_export.quota_state='held' THEN
            UPDATE platform.artifact_quota_counters
            SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
                revision=revision+1,updated_at=p_observed_at
            WHERE tenant_id=v_tenant_id
              AND reserved_ciphertext_bytes>=2147483648;
            IF NOT FOUND THEN
                RAISE EXCEPTION USING ERRCODE='P6105',
                    MESSAGE='analytics dashboard export terminal quota changed';
            END IF;
        END IF;
        UPDATE analytics_dashboard_exports
        SET state='failed',failure_code='MAX_ATTEMPTS',quota_state='released',
            row_revision=row_revision+1,lease_owner=NULL,lease_until=NULL,
            updated_at=p_observed_at
        WHERE analytics_dashboard_exports.export_id=p_export_id;
        RETURN QUERY SELECT * FROM
            analytics_dashboard_export_worker_snapshot_v1(p_export_id,'terminal');
        RETURN;
    ELSE
        v_disposition:='execute';
    END IF;
    IF v_export.quota_state='none' THEN
        UPDATE platform.artifact_quota_counters
        SET reserved_ciphertext_bytes=reserved_ciphertext_bytes+2147483648,
            revision=revision+1,updated_at=p_observed_at
        WHERE tenant_id=v_tenant_id AND NOT fenced
          AND used_ciphertext_bytes+reserved_ciphertext_bytes+2147483648
              <=21474836480;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6105',
                MESSAGE='analytics dashboard export tenant quota is unavailable';
        END IF;
    ELSIF v_export.quota_state<>'held' THEN
        RAISE EXCEPTION USING ERRCODE='P6105',
            MESSAGE='analytics dashboard export quota state is invalid';
    END IF;
    UPDATE analytics_dashboard_exports
    SET state='running',
        attempt_generation=CASE WHEN v_disposition='execute'
            THEN analytics_dashboard_exports.attempt_generation+1
            ELSE analytics_dashboard_exports.attempt_generation END,
        quota_state='held',lease_owner=p_lease_owner,
        lease_until=p_observed_at+INTERVAL '60 seconds',
        failure_code=NULL,row_revision=row_revision+1,updated_at=p_observed_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN QUERY SELECT * FROM
        analytics_dashboard_export_worker_snapshot_v1(p_export_id,v_disposition);
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_claim_v1(p_scope_schema name, p_export_id uuid, p_job_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_complete_v1(name, uuid, uuid, bigint, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_complete_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_object_version text, p_provider_request_id text, p_uploaded_at timestamp with time zone, p_completed_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export analytics_dashboard_exports%ROWTYPE;
    v_next text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_lease_owner IS NULL OR
       p_lease_owner='00000000-0000-0000-0000-000000000000'::uuid OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.octet_length(p_object_version) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_provider_request_id) NOT BETWEEN 1 AND 512 OR
       p_uploaded_at IS NULL OR NOT pg_catalog.isfinite(p_uploaded_at) OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       p_completed_at<p_uploaded_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export completion input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT item.* INTO v_export
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.state='running'
      AND item.lease_owner=p_lease_owner
      AND item.attempt_generation=p_attempt_generation
      AND item.effect_started_at IS NOT NULL AND item.object_version IS NULL
      AND item.quota_state='held'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export completion changed';
    END IF;
    v_next:=CASE
        WHEN v_export.cancellation_requested_at IS NOT NULL THEN 'deleting'
        WHEN v_export.expires_at<=p_completed_at THEN 'expired'
        ELSE 'ready'
    END;
    UPDATE platform.artifact_quota_counters
    SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
        used_ciphertext_bytes=used_ciphertext_bytes+v_export.ciphertext_bytes,
        revision=revision+1,updated_at=p_completed_at
    WHERE tenant_id=v_export.tenant_id
      AND reserved_ciphertext_bytes>=2147483648
      AND used_ciphertext_bytes+v_export.ciphertext_bytes<=21474836480;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6105',
            MESSAGE='analytics dashboard export completion quota changed';
    END IF;
    UPDATE analytics_dashboard_export_attempt_receipts
    SET outcome='ready',object_version=p_object_version,
        provider_request_id=p_provider_request_id,completed_at=p_completed_at
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation AND outcome='started';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export receipt changed';
    END IF;
    UPDATE analytics_dashboard_exports
    SET state=v_next,quota_state='used',object_version=p_object_version,
        provider_request_id=p_provider_request_id,
        ready_at=CASE WHEN v_next='ready' THEN p_completed_at ELSE NULL END,
        failure_code=NULL,row_revision=row_revision+1,
        lease_owner=NULL,lease_until=NULL,updated_at=p_completed_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN v_next;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_complete_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_object_version text, p_provider_request_id text, p_uploaded_at timestamp with time zone, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_content_v1(name, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_content_v1(p_scope_schema name, p_actor_id uuid, p_dashboard_id uuid, p_export_id uuid, p_observed_at timestamp with time zone) RETURNS TABLE(actor_id uuid, export_id uuid, dashboard_id uuid, dashboard_version_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, dashboard_manifest_sha256 bytea, pin_sha256 bytea, format text, parameters_document bytea, pinned_widgets jsonb, maximum_rows bigint, maximum_plaintext_bytes bigint, expires_at timestamp with time zone, attempt_generation bigint, object_key text, object_version text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text, ready_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export content input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT item.actor_id,item.export_id,item.dashboard_id,
           item.dashboard_version_id,item.token_version,
           item.authorization_version,item.authorization_clock,
           item.dashboard_manifest_sha256,item.pin_sha256,item.format,
           item.parameters_document,item.pinned_widgets,
           item.maximum_rows,item.maximum_plaintext_bytes,item.expires_at,
           item.attempt_generation,item.object_key,item.object_version,
           item.key_id,item.wrapped_dek,item.wrap_nonce,item.header_sha256,
           item.ciphertext_sha256,item.plaintext_sha256,
           item.ciphertext_bytes,item.plaintext_bytes,item.row_count,
           item.content_type,item.filename,item.ready_at
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id
      AND item.dashboard_id=p_dashboard_id
      AND item.state='ready'
      AND item.ready_at IS NOT NULL
      AND item.expires_at>p_observed_at
      AND analytics_dashboard_export_access_v1(
          p_actor_id,item.dashboard_id,item.dashboard_version_id);
    IF NOT FOUND THEN
        IF EXISTS (
            SELECT 1 FROM analytics_dashboard_exports AS item
            WHERE item.export_id=p_export_id
              AND item.dashboard_id=p_dashboard_id
              AND analytics_dashboard_export_access_v1(
                  p_actor_id,item.dashboard_id,item.dashboard_version_id)
        ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='analytics dashboard export content is not ready';
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics dashboard export was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_content_v1(p_scope_schema name, p_actor_id uuid, p_dashboard_id uuid, p_export_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_delete_claim_legacy_v1(name, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_delete_claim_legacy_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) RETURNS TABLE(disposition text, state text, actor_id uuid, export_id uuid, dashboard_id uuid, dashboard_version_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, dashboard_manifest_sha256 bytea, pin_sha256 bytea, format text, parameters_document bytea, pinned_widgets jsonb, maximum_rows bigint, maximum_plaintext_bytes bigint, expires_at timestamp with time zone, attempt_generation bigint, has_artifact boolean, object_key text, object_version text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text, delete_actor_id uuid, delete_job_id uuid, delete_attempt_generation bigint, delete_lease_owner uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export analytics_dashboard_exports%ROWTYPE;
    v_tenant_id uuid;
    v_expiry boolean;
    v_has_artifact_evidence boolean;
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_delete_job_id) IS DISTINCT FROM 7 OR
       p_lease_owner IS NULL OR
       p_lease_owner='00000000-0000-0000-0000-000000000000'::uuid OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export delete claim input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton
      AND identity_row.schema_name=pg_catalog.current_schema();
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=v_tenant_id
      AND (item.delete_job_id=p_delete_job_id OR
           item.expiry_job_id=p_delete_job_id)
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics dashboard export delete job was not found';
    END IF;
    v_expiry:=v_export.expiry_job_id=p_delete_job_id;
    IF v_expiry AND p_observed_at<v_export.expires_at THEN
        RAISE EXCEPTION USING ERRCODE='55P03',
            MESSAGE='analytics dashboard export expiry is not due';
    END IF;
    IF p_observed_at<v_export.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export delete clock is stale';
    END IF;
    IF v_expiry AND v_export.delete_operation_id IS NULL THEN
        UPDATE analytics_dashboard_exports AS target
        SET delete_operation_id=p_delete_job_id,delete_job_id=p_delete_job_id,
            delete_actor_id=target.actor_id,
            delete_idempotency_key='analytics-expiry:'||target.export_id::text,
            delete_request_sha256=pg_catalog.sha256(pg_catalog.convert_to(
                'analytics-expiry:'||target.export_id::text,'UTF8')),
            row_revision=target.row_revision+1,updated_at=p_observed_at
        WHERE target.export_id=p_export_id;
        SELECT item.* INTO STRICT v_export
        FROM analytics_dashboard_exports AS item
        WHERE item.export_id=p_export_id;
    ELSIF v_expiry AND v_export.delete_job_id<>p_delete_job_id THEN
        RETURN QUERY SELECT * FROM analytics_dashboard_export_delete_snapshot_v1(
            p_export_id,'terminal');
        RETURN;
    END IF;
    IF v_export.delete_actor_id IS NULL OR
       v_export.delete_job_id IS DISTINCT FROM p_delete_job_id THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics dashboard export delete job was not found';
    END IF;
    IF v_export.state='deleted' THEN
        RETURN QUERY SELECT * FROM analytics_dashboard_export_delete_snapshot_v1(
            p_export_id,'terminal');
        RETURN;
    END IF;
    IF ((v_export.state='running' AND v_export.lease_until>p_observed_at) OR
        (v_export.state='deleting' AND
         v_export.delete_lease_until>p_observed_at)) THEN
        RAISE EXCEPTION USING ERRCODE='55P03',
            MESSAGE='analytics dashboard export delete lease is active';
    END IF;
    v_has_artifact_evidence:=v_export.effect_started_at IS NOT NULL OR
        v_export.object_version IS NOT NULL OR v_export.quota_state='used' OR
        v_export.state IN ('ready','deleting');
    IF v_expiry AND NOT v_has_artifact_evidence THEN
        IF v_export.quota_state='held' THEN
            UPDATE platform.artifact_quota_counters
            SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
                revision=revision+1,updated_at=p_observed_at
            WHERE tenant_id=v_tenant_id
              AND reserved_ciphertext_bytes>=2147483648;
            IF NOT FOUND THEN
                RAISE EXCEPTION USING ERRCODE='P6105',
                    MESSAGE='analytics dashboard export expiry quota changed';
            END IF;
        END IF;
        UPDATE analytics_dashboard_exports AS target
        SET state=CASE WHEN target.state IN ('queued','running') THEN 'expired'
                       ELSE target.state END,
            quota_state=CASE WHEN target.quota_state IN ('none','held')
                             THEN 'released' ELSE target.quota_state END,
            lease_owner=NULL,lease_until=NULL,row_revision=target.row_revision+1,
            updated_at=p_observed_at
        WHERE target.export_id=p_export_id;
        RETURN QUERY SELECT * FROM analytics_dashboard_export_delete_snapshot_v1(
            p_export_id,'terminal');
        RETURN;
    END IF;
    IF NOT v_has_artifact_evidence THEN
        RETURN QUERY SELECT * FROM analytics_dashboard_export_delete_snapshot_v1(
            p_export_id,'terminal');
        RETURN;
    END IF;
    UPDATE analytics_dashboard_exports
    SET state='deleting',delete_attempt_generation=LEAST(
            analytics_dashboard_exports.delete_attempt_generation+1,3),
        delete_lease_owner=p_lease_owner,
        delete_lease_until=p_observed_at+INTERVAL '60 seconds',
        lease_owner=NULL,lease_until=NULL,row_revision=row_revision+1,
        updated_at=p_observed_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN QUERY SELECT * FROM analytics_dashboard_export_delete_snapshot_v1(
        p_export_id,'execute');
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_delete_claim_legacy_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_delete_claim_unfenced_v1(name, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_delete_claim_unfenced_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) RETURNS TABLE(disposition text, state text, actor_id uuid, export_id uuid, dashboard_id uuid, dashboard_version_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, dashboard_manifest_sha256 bytea, pin_sha256 bytea, format text, parameters_document bytea, pinned_widgets jsonb, maximum_rows bigint, maximum_plaintext_bytes bigint, expires_at timestamp with time zone, attempt_generation bigint, has_artifact boolean, object_key text, object_version text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text, delete_actor_id uuid, delete_job_id uuid, delete_attempt_generation bigint, delete_lease_owner uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_export analytics_dashboard_exports%ROWTYPE;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT item.* INTO STRICT v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id
      AND (item.delete_job_id=p_delete_job_id OR
           item.expiry_job_id=p_delete_job_id) FOR UPDATE;
    IF v_export.state='running' OR v_export.quota_state='held' OR
       v_export.failure_code='ARTIFACT_OUTCOME_UNKNOWN' OR EXISTS (
        SELECT 1 FROM analytics_dashboard_export_platform_attempts AS attempt
        WHERE attempt.export_id=p_export_id AND attempt.outcome='unknown'
          AND attempt.resolution_receipt_id IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export dedicated render cleanup owns artifact';
    END IF;
    IF p_delete_job_id=v_export.expiry_job_id AND
       v_export.delete_operation_id IS DISTINCT FROM p_delete_job_id THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export expiry control is required';
    END IF;
    RETURN QUERY SELECT *
    FROM analytics_dashboard_export_delete_claim_legacy_v1(
        p_scope_schema,p_export_id,p_delete_job_id,p_lease_owner,p_observed_at
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_delete_claim_unfenced_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_delete_claim_v1(name, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_delete_claim_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) RETURNS TABLE(disposition text, state text, actor_id uuid, export_id uuid, dashboard_id uuid, dashboard_version_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, dashboard_manifest_sha256 bytea, pin_sha256 bytea, format text, parameters_document bytea, pinned_widgets jsonb, maximum_rows bigint, maximum_plaintext_bytes bigint, expires_at timestamp with time zone, attempt_generation bigint, has_artifact boolean, object_key text, object_version text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text, delete_actor_id uuid, delete_job_id uuid, delete_attempt_generation bigint, delete_lease_owner uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_platform_kind text;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_expected_kind text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_delete_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner) IS DISTINCT FROM 5 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export delete claim input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton
      AND identity_row.schema_name=pg_catalog.current_schema();
    v_platform_kind:=
        platform.platform_async_analytics_dashboard_export_maintenance_effect_owner_v1(
            v_tenant_id,p_export_id,p_delete_job_id,p_lease_owner,p_observed_at);
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=v_tenant_id
      AND (item.delete_job_id=p_delete_job_id OR item.expiry_job_id=p_delete_job_id)
    FOR UPDATE;
    v_expected_kind:=CASE WHEN v_export.expiry_job_id=p_delete_job_id THEN
        'analytics.dashboard.export.expire' ELSE
        'analytics.dashboard.export.delete' END;
    IF v_export.export_id IS NULL OR
       v_platform_kind IS DISTINCT FROM v_expected_kind OR
       v_export.maintenance_unknown_job_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export delete effect owner changed';
    END IF;
    RETURN QUERY SELECT * FROM analytics_dashboard_export_delete_claim_unfenced_v1(
        p_scope_schema,p_export_id,p_delete_job_id,p_lease_owner,p_observed_at);
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_delete_claim_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_delete_complete_unfenced_v1(name, uuid, uuid, uuid, bigint, text, text, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_delete_complete_unfenced_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_delete_generation bigint, p_object_version text, p_provider_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_verified_at timestamp with time zone, p_completed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_export analytics_dashboard_exports%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_delete_job_id) IS DISTINCT FROM 7 OR
       p_lease_owner IS NULL OR
       p_lease_owner='00000000-0000-0000-0000-000000000000'::uuid OR
       p_delete_generation NOT BETWEEN 1 AND 3 OR
       (p_object_version IS NOT NULL AND
        pg_catalog.octet_length(p_object_version) NOT BETWEEN 1 AND 512) OR
       (p_provider_request_id IS NOT NULL AND
        pg_catalog.octet_length(p_provider_request_id) NOT BETWEEN 1 AND 512) OR
       (p_delete_response_sha256 IS NOT NULL AND
        pg_catalog.octet_length(p_delete_response_sha256)<>32) OR
       (p_absence_sha256 IS NOT NULL AND
        pg_catalog.octet_length(p_absence_sha256)<>32) OR
       p_verified_at IS NULL OR NOT pg_catalog.isfinite(p_verified_at) OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       p_completed_at<p_verified_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export delete completion input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.state='deleting'
      AND item.delete_job_id=p_delete_job_id
      AND item.delete_lease_owner=p_lease_owner
      AND item.delete_attempt_generation=p_delete_generation FOR UPDATE;
    IF NOT FOUND OR (v_export.effect_started_at IS NOT NULL AND
       (p_provider_request_id IS NULL OR p_absence_sha256 IS NULL)) OR
       (v_export.object_version IS NOT NULL AND
        p_delete_response_sha256 IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export delete completion changed';
    END IF;
    IF v_export.quota_state='held' THEN
        UPDATE platform.artifact_quota_counters
        SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
            revision=revision+1,updated_at=p_completed_at
        WHERE tenant_id=v_export.tenant_id
          AND reserved_ciphertext_bytes>=2147483648;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6105',
                MESSAGE='analytics dashboard export reserved quota changed';
        END IF;
    ELSIF v_export.quota_state='used' THEN
        UPDATE platform.artifact_quota_counters
        SET used_ciphertext_bytes=used_ciphertext_bytes-v_export.ciphertext_bytes,
            revision=revision+1,updated_at=p_completed_at
        WHERE tenant_id=v_export.tenant_id
          AND used_ciphertext_bytes>=v_export.ciphertext_bytes;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6105',
                MESSAGE='analytics dashboard export used quota changed';
        END IF;
    ELSIF v_export.quota_state NOT IN ('none','released') THEN
        RAISE EXCEPTION USING ERRCODE='P6105',
            MESSAGE='analytics dashboard export delete quota is invalid';
    END IF;
    UPDATE analytics_dashboard_export_attempt_receipts
    SET outcome='deleted',object_version=COALESCE(object_version,p_object_version),
        completed_at=p_completed_at
    WHERE export_id=p_export_id AND outcome='started';
    UPDATE analytics_dashboard_exports
    SET state='deleted',quota_state='released',
        object_version=COALESCE(object_version,p_object_version),
        delete_provider_request_id=p_provider_request_id,
        delete_response_sha256=p_delete_response_sha256,
        delete_absence_sha256=p_absence_sha256,
        delete_verified_at=p_verified_at,deleted_at=p_completed_at,
        delete_lease_owner=NULL,delete_lease_until=NULL,
        row_revision=row_revision+1,updated_at=p_completed_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_delete_complete_unfenced_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_delete_generation bigint, p_object_version text, p_provider_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_verified_at timestamp with time zone, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_delete_complete_v1(name, uuid, uuid, uuid, bigint, text, text, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_delete_complete_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_delete_generation bigint, p_object_version text, p_provider_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_verified_at timestamp with time zone, p_completed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_platform_kind text;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_expected_kind text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_delete_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner) IS DISTINCT FROM 5 OR
       p_delete_generation NOT BETWEEN 1 AND 3 OR
       (p_object_version IS NOT NULL AND
        pg_catalog.octet_length(p_object_version) NOT BETWEEN 1 AND 512) OR
       (p_provider_request_id IS NOT NULL AND
        pg_catalog.octet_length(p_provider_request_id) NOT BETWEEN 1 AND 512) OR
       (p_delete_response_sha256 IS NOT NULL AND
        pg_catalog.octet_length(p_delete_response_sha256) IS DISTINCT FROM 32) OR
       (p_absence_sha256 IS NOT NULL AND
        pg_catalog.octet_length(p_absence_sha256) IS DISTINCT FROM 32) OR
       p_verified_at IS NULL OR NOT pg_catalog.isfinite(p_verified_at) OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       p_completed_at<p_verified_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export delete completion input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton
      AND identity_row.schema_name=pg_catalog.current_schema();
    v_platform_kind:=
        platform.platform_async_analytics_dashboard_export_maintenance_effect_owner_v1(
            v_tenant_id,p_export_id,p_delete_job_id,p_lease_owner,p_completed_at);
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=v_tenant_id
      AND item.state='deleting' AND item.delete_job_id=p_delete_job_id
      AND item.delete_lease_owner=p_lease_owner
      AND item.delete_attempt_generation=p_delete_generation
    FOR UPDATE;
    v_expected_kind:=CASE WHEN v_export.expiry_job_id=p_delete_job_id THEN
        'analytics.dashboard.export.expire' ELSE
        'analytics.dashboard.export.delete' END;
    IF v_export.export_id IS NULL OR
       v_platform_kind IS DISTINCT FROM v_expected_kind OR
       v_export.maintenance_unknown_job_id IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export delete completion owner changed';
    END IF;
    RETURN analytics_dashboard_export_delete_complete_unfenced_v1(
        p_scope_schema,p_export_id,p_delete_job_id,p_lease_owner,
        p_delete_generation,p_object_version,p_provider_request_id,
        p_delete_response_sha256,p_absence_sha256,p_verified_at,p_completed_at);
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_delete_complete_v1(p_scope_schema name, p_export_id uuid, p_delete_job_id uuid, p_lease_owner uuid, p_delete_generation bigint, p_object_version text, p_provider_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_verified_at timestamp with time zone, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_delete_snapshot_v1(uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_delete_snapshot_v1(p_export_id uuid, p_disposition text) RETURNS TABLE(disposition text, state text, actor_id uuid, export_id uuid, dashboard_id uuid, dashboard_version_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, dashboard_manifest_sha256 bytea, pin_sha256 bytea, format text, parameters_document bytea, pinned_widgets jsonb, maximum_rows bigint, maximum_plaintext_bytes bigint, expires_at timestamp with time zone, attempt_generation bigint, has_artifact boolean, object_key text, object_version text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text, delete_actor_id uuid, delete_job_id uuid, delete_attempt_generation bigint, delete_lease_owner uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT p_disposition,item.state,item.actor_id,item.export_id,
        item.dashboard_id,item.dashboard_version_id,item.token_version,
        item.authorization_version,item.authorization_clock,
        item.dashboard_manifest_sha256,item.pin_sha256,item.format,
        item.parameters_document,item.pinned_widgets,item.maximum_rows,
        item.maximum_plaintext_bytes,item.expires_at,item.attempt_generation,
        item.effect_started_at IS NOT NULL,COALESCE(item.object_key,''),
        COALESCE(item.object_version,''),COALESCE(item.key_id,''),
        COALESCE(item.wrapped_dek,''::bytea),COALESCE(item.wrap_nonce,''::bytea),
        COALESCE(item.header_sha256,''::bytea),
        COALESCE(item.ciphertext_sha256,''::bytea),
        COALESCE(item.plaintext_sha256,''::bytea),
        COALESCE(item.ciphertext_bytes,0),COALESCE(item.plaintext_bytes,0),
        COALESCE(item.row_count,0),COALESCE(item.content_type,''),
        COALESCE(item.filename,''),item.delete_actor_id,item.delete_job_id,
        item.delete_attempt_generation,COALESCE(item.delete_lease_owner,
            '00000000-0000-0000-0000-000000000000'::uuid)
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_delete_snapshot_v1(p_export_id uuid, p_disposition text) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_delete_v1(name, uuid, uuid, uuid, text, bytea, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_delete_v1(p_scope_schema name, p_operation_id uuid, p_delete_job_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_export_id uuid, p_occurred_at timestamp with time zone) RETURNS TABLE(export_id uuid, dashboard_id uuid, dashboard_version_id uuid, job_id uuid, effective_state text, stored_state text, format text, filename text, content_type text, failure_code text, row_count bigint, plaintext_bytes bigint, cancellation_requested boolean, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, replayed boolean, schedule_delete boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export analytics_dashboard_exports%ROWTYPE;
    v_control_state text;
    v_control_changed_at timestamptz;
    v_update_at timestamptz;
    v_schedule boolean:=false;
    v_immediate_delete boolean:=false;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_delete_job_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 16 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics dashboard export delete input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.dashboard_id=p_dashboard_id;
    IF NOT FOUND OR NOT analytics_dashboard_export_access_v1(
        p_actor_id,p_dashboard_id,v_export.dashboard_version_id) THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='Analytics dashboard export was not found';
    END IF;
    SELECT control.control_state,control.changed_at
    INTO STRICT v_control_state,v_control_changed_at
    FROM platform.platform_async_analytics_dashboard_export_control_v1(
        v_export.tenant_id,p_export_id,v_export.job_id,p_occurred_at
    ) AS control;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:export:delete:'||p_export_id::text,6100));
    SELECT item.* INTO STRICT v_export
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.dashboard_id=p_dashboard_id
      AND item.tenant_id=v_export.tenant_id AND item.job_id=v_export.job_id
    FOR UPDATE;
    IF NOT analytics_dashboard_export_access_v1(
        p_actor_id,p_dashboard_id,v_export.dashboard_version_id) THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='Analytics dashboard export was not found';
    END IF;
    IF v_export.delete_operation_id IS NOT NULL THEN
        IF v_export.expiry_job_id IS NOT NULL AND
           v_export.delete_operation_id=v_export.expiry_job_id AND
           v_export.delete_job_id=v_export.expiry_job_id THEN
            RETURN QUERY SELECT result.*,false,false
            FROM analytics_dashboard_export_snapshot_v1(
                p_scope_schema,p_actor_id,p_dashboard_id,p_export_id,p_occurred_at
            ) AS result;
            RETURN;
        END IF;
        IF v_export.delete_actor_id IS DISTINCT FROM p_actor_id OR
           v_export.delete_idempotency_key IS DISTINCT FROM p_idempotency_key OR
           v_export.delete_request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='P6103',
                MESSAGE='Analytics dashboard export delete replay differs';
        END IF;
        RETURN QUERY SELECT result.*,true,false
        FROM analytics_dashboard_export_snapshot_v1(
            p_scope_schema,p_actor_id,p_dashboard_id,p_export_id,p_occurred_at
        ) AS result;
        RETURN;
    END IF;
    IF v_control_state='cancelled' THEN
        IF v_export.state NOT IN ('queued','cancelled') OR
           v_export.quota_state NOT IN ('none','released') THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export cancellation differs';
        END IF;
    ELSIF v_control_state='cancellation_requested' THEN
        IF v_export.state IS DISTINCT FROM 'running' OR
           v_export.quota_state IS DISTINCT FROM 'held' OR
           v_export.platform_attempt_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export cancellation request differs';
        END IF;
    ELSIF v_control_state='outcome_unknown' THEN
        IF v_export.state IS DISTINCT FROM 'running' OR
           v_export.quota_state IS DISTINCT FROM 'held' OR
           v_export.failure_code IS DISTINCT FROM 'ARTIFACT_OUTCOME_UNKNOWN' OR
           v_export.lease_owner IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export unknown control differs';
        END IF;
    ELSIF v_control_state='succeeded' THEN
        IF v_export.state NOT IN ('ready','deleting','deleted') OR
           v_export.quota_state NOT IN ('used','released') THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export success control differs';
        END IF;
        v_schedule:=v_export.state='ready' AND v_export.quota_state='used';
    ELSIF v_control_state IN ('dead','unknown_resolved') THEN
        IF v_export.state NOT IN ('failed','cancelled','expired','deleted') OR
           v_export.quota_state IS DISTINCT FROM 'released' THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export terminal control differs';
        END IF;
        v_immediate_delete:=v_export.state IS DISTINCT FROM 'deleted';
    ELSE
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export control state is invalid';
    END IF;
    v_update_at:=GREATEST(
        p_occurred_at,v_control_changed_at,
        v_export.updated_at+interval '1 microsecond'
    );
    UPDATE analytics_dashboard_exports
    SET state=CASE
            WHEN v_control_state='cancelled' THEN 'cancelled'
            WHEN v_schedule THEN 'deleting'
            WHEN v_immediate_delete THEN 'deleted'
            ELSE state END,
        quota_state=CASE
            WHEN v_control_state='cancelled' OR v_immediate_delete
                THEN 'released' ELSE quota_state END,
        cancellation_requested_at=CASE
            WHEN v_control_state IN ('cancellation_requested','outcome_unknown')
                THEN COALESCE(cancellation_requested_at,p_occurred_at)
            ELSE cancellation_requested_at END,
        delete_operation_id=p_operation_id,delete_job_id=p_delete_job_id,
        delete_actor_id=p_actor_id,delete_idempotency_key=p_idempotency_key,
        delete_request_sha256=p_request_sha256,
        deleted_at=CASE WHEN v_immediate_delete THEN v_update_at ELSE deleted_at END,
        row_revision=row_revision+1,updated_at=v_update_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN QUERY SELECT result.*,false,v_schedule
    FROM analytics_dashboard_export_snapshot_v1(
        p_scope_schema,p_actor_id,p_dashboard_id,p_export_id,v_update_at
    ) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_delete_v1(p_scope_schema name, p_operation_id uuid, p_delete_job_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_export_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_effect_start_v1(name, uuid, uuid, bigint, text, text, bytea, bytea, bytea, bytea, bytea, bigint, bigint, bigint, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_effect_start_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_object_key text, p_key_id text, p_wrapped_dek bytea, p_wrap_nonce bytea, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_plaintext_sha256 bytea, p_ciphertext_bytes bigint, p_plaintext_bytes bigint, p_row_count bigint, p_content_type text, p_filename text, p_started_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_format text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_lease_owner IS NULL OR
       p_lease_owner='00000000-0000-0000-0000-000000000000'::uuid OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.octet_length(p_object_key) NOT BETWEEN 10 AND 512 OR
       pg_catalog.octet_length(p_key_id) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_wrapped_dek) IS DISTINCT FROM 48 OR
       pg_catalog.octet_length(p_wrap_nonce) IS DISTINCT FROM 12 OR
       pg_catalog.octet_length(p_header_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_ciphertext_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_plaintext_sha256) IS DISTINCT FROM 32 OR
       p_ciphertext_bytes NOT BETWEEN 35 AND 2147483648 OR
       p_plaintext_bytes NOT BETWEEN 1 AND 67108864 OR p_row_count<0 OR
       pg_catalog.octet_length(p_content_type) NOT BETWEEN 3 AND 128 OR
       pg_catalog.octet_length(p_filename) NOT BETWEEN 5 AND 255 OR
       p_started_at IS NULL OR NOT pg_catalog.isfinite(p_started_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export effect input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT item.format INTO v_format
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.state='running'
      AND item.attempt_generation=p_attempt_generation
      AND item.lease_owner=p_lease_owner AND item.lease_until>p_started_at
      AND item.effect_started_at IS NULL
      AND item.cancellation_requested_at IS NULL
      AND item.expires_at>p_started_at AND item.quota_state='held'
    FOR UPDATE;
    IF NOT FOUND OR
       (v_format='csv' AND p_content_type<>'text/csv; charset=utf-8') OR
       (v_format='xlsx' AND p_content_type<>
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') OR
       (v_format='pdf' AND p_content_type<>'application/pdf') THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export attempt changed';
    END IF;
    UPDATE analytics_dashboard_exports
    SET effect_started_at=p_started_at,object_key=p_object_key,
        key_id=p_key_id,wrapped_dek=p_wrapped_dek,wrap_nonce=p_wrap_nonce,
        header_sha256=p_header_sha256,ciphertext_sha256=p_ciphertext_sha256,
        plaintext_sha256=p_plaintext_sha256,ciphertext_bytes=p_ciphertext_bytes,
        plaintext_bytes=p_plaintext_bytes,row_count=p_row_count,
        content_type=p_content_type,filename=p_filename,
        row_revision=row_revision+1,updated_at=p_started_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    INSERT INTO analytics_dashboard_export_attempt_receipts(
        export_id,attempt_generation,object_key,key_id,wrapped_dek,wrap_nonce,
        header_sha256,ciphertext_sha256,plaintext_sha256,ciphertext_bytes,
        plaintext_bytes,row_count,outcome,started_at
    ) VALUES (p_export_id,p_attempt_generation,p_object_key,p_key_id,
        p_wrapped_dek,p_wrap_nonce,p_header_sha256,p_ciphertext_sha256,
        p_plaintext_sha256,p_ciphertext_bytes,p_plaintext_bytes,p_row_count,
        'started',p_started_at);
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_effect_start_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_object_key text, p_key_id text, p_wrapped_dek bytea, p_wrap_nonce bytea, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_plaintext_sha256 bytea, p_ciphertext_bytes bigint, p_plaintext_bytes bigint, p_row_count bigint, p_content_type text, p_filename text, p_started_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_expired_finalize_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_expired_finalize_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_observed_at timestamp with time zone) RETURNS TABLE(final_state text, finalized_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_attempt analytics_dashboard_export_platform_attempts%ROWTYPE;
    v_final_state text;
    v_finalized_at timestamptz;
    v_failure_sha256 bytea;
    v_outcome text;
    v_domain_state text;
    v_quota_state text;
    v_failure_class text;
    v_failure_code text;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id='00000000-0000-0000-0000-000000000000'::uuid OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export expiry scope is invalid';
    END IF;
    SELECT result.final_state,result.finalized_at,result.failure_sha256
    INTO STRICT v_final_state,v_finalized_at,v_failure_sha256
    FROM platform.platform_async_analytics_dashboard_export_expired_finalize_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_attempt_generation,
        p_lease_owner,p_effect_id,p_effect_request_sha256,p_observed_at
    ) AS result;
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id FOR UPDATE;
    SELECT attempt.* INTO v_attempt
    FROM analytics_dashboard_export_platform_attempts AS attempt
    WHERE attempt.export_id=p_export_id
      AND attempt.attempt_generation=p_attempt_generation
      AND attempt.platform_attempt_id=p_attempt_id
      AND attempt.job_id=p_job_id AND attempt.lease_owner=p_lease_owner
    FOR UPDATE;
    IF v_export.export_id IS NULL OR v_attempt.export_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export expiry evidence is unavailable';
    END IF;
    IF v_final_state='outcome_unknown' THEN
        IF p_effect_id IS NULL OR v_failure_sha256 IS NOT NULL OR
           v_attempt.platform_effect_id IS DISTINCT FROM p_effect_id OR
           v_attempt.platform_effect_request_sha256 IS DISTINCT FROM
                p_effect_request_sha256 OR
           v_attempt.effect_started_at IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export unknown expiry result is invalid';
        END IF;
        IF v_attempt.outcome='unknown' THEN
            IF v_attempt.finished_at IS DISTINCT FROM v_finalized_at OR
               v_export.state IS DISTINCT FROM 'running' OR
               v_export.quota_state IS DISTINCT FROM 'held' OR
               v_export.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
               v_export.platform_effect_id IS DISTINCT FROM p_effect_id OR
               v_export.platform_effect_request_sha256 IS DISTINCT FROM p_effect_request_sha256 OR
               v_export.effect_started_at IS DISTINCT FROM
                    v_attempt.effect_started_at OR
               v_export.lease_owner IS NOT NULL OR
               v_export.failure_code IS DISTINCT FROM 'ARTIFACT_OUTCOME_UNKNOWN' THEN
                RAISE EXCEPTION USING ERRCODE='P6048',
                    MESSAGE='Analytics dashboard export unknown expiry replay differs';
            END IF;
            final_state:=v_final_state;finalized_at:=v_finalized_at;
            RETURN NEXT;RETURN;
        END IF;
        IF v_attempt.outcome IS DISTINCT FROM 'running' OR
           v_export.state IS DISTINCT FROM 'running' OR
           v_export.quota_state IS DISTINCT FROM 'held' OR
           v_export.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
           v_export.attempt_generation IS DISTINCT FROM p_attempt_generation OR
           v_export.lease_owner IS DISTINCT FROM p_lease_owner OR
           v_export.platform_effect_id IS DISTINCT FROM p_effect_id OR
           v_export.platform_effect_request_sha256 IS DISTINCT FROM p_effect_request_sha256 OR
           v_export.effect_started_at IS DISTINCT FROM v_attempt.effect_started_at OR
           v_finalized_at<v_export.updated_at THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export unknown expiry evidence differs';
        END IF;
        UPDATE analytics_dashboard_export_attempt_receipts
        SET outcome='unknown',completed_at=v_finalized_at
        WHERE export_id=p_export_id
          AND attempt_generation=p_attempt_generation AND outcome='started';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export unknown expiry receipt differs';
        END IF;
        UPDATE analytics_dashboard_export_platform_attempts
        SET outcome='unknown',failure_code='JOB_OUTCOME_UNKNOWN',
            finished_at=v_finalized_at
        WHERE export_id=p_export_id AND attempt_generation=p_attempt_generation;
        UPDATE analytics_dashboard_exports
        SET failure_code='ARTIFACT_OUTCOME_UNKNOWN',lease_owner=NULL,
            lease_until=NULL,row_revision=row_revision+1,
            updated_at=v_finalized_at
        WHERE analytics_dashboard_exports.export_id=p_export_id;
        final_state:=v_final_state;finalized_at:=v_finalized_at;
        RETURN NEXT;RETURN;
    END IF;
    v_outcome:=CASE v_final_state WHEN 'queued' THEN 'requeued'
        WHEN 'dead' THEN 'dead' WHEN 'cancelled' THEN 'cancelled' END;
    v_domain_state:=CASE v_final_state WHEN 'queued' THEN 'queued'
        WHEN 'dead' THEN 'failed' WHEN 'cancelled' THEN 'cancelled' END;
    v_quota_state:=CASE WHEN v_final_state='queued' THEN 'none'
        ELSE 'released' END;
    v_failure_class:=CASE WHEN v_final_state='cancelled' THEN 'cancelled'
        ELSE 'transient' END;
    v_failure_code:=CASE WHEN v_final_state='cancelled' THEN 'EXPORT_CANCELLED'
        ELSE 'JOB_LEASE_EXPIRED' END;
    IF v_outcome IS NULL OR p_effect_id IS NOT NULL OR
       pg_catalog.octet_length(v_failure_sha256) IS DISTINCT FROM 32 OR
       v_failure_sha256=pg_catalog.decode(pg_catalog.repeat('00',32),'hex') THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export pre-effect expiry result is invalid';
    END IF;
    IF v_attempt.outcome IS DISTINCT FROM 'running' THEN
        IF v_attempt.outcome IS DISTINCT FROM v_outcome OR
           v_attempt.finished_at IS DISTINCT FROM v_finalized_at OR
           v_attempt.failure_class IS DISTINCT FROM v_failure_class OR
           v_attempt.failure_code IS DISTINCT FROM v_failure_code OR
           v_attempt.failure_sha256 IS DISTINCT FROM v_failure_sha256 OR
           v_attempt.platform_effect_id IS NOT NULL OR
           v_attempt.platform_effect_request_sha256 IS NOT NULL OR
           v_attempt.effect_started_at IS NOT NULL OR
           v_export.state IS DISTINCT FROM v_domain_state OR
           v_export.quota_state IS DISTINCT FROM v_quota_state OR
           v_export.platform_attempt_id IS NOT NULL OR
           v_export.platform_effect_id IS NOT NULL OR
           v_export.platform_effect_request_sha256 IS NOT NULL OR
           v_export.effect_started_at IS NOT NULL OR
           v_export.lease_owner IS NOT NULL OR v_export.lease_until IS NOT NULL OR
           v_export.updated_at IS DISTINCT FROM v_finalized_at THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export expiry replay differs';
        END IF;
        final_state:=v_final_state;finalized_at:=v_finalized_at;
        RETURN NEXT;RETURN;
    END IF;
    IF v_export.state IS DISTINCT FROM 'running' OR
       v_export.quota_state IS DISTINCT FROM 'held' OR
       v_export.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
       v_export.attempt_generation IS DISTINCT FROM p_attempt_generation OR
       v_export.lease_owner IS DISTINCT FROM p_lease_owner OR
       v_attempt.platform_effect_id IS NOT NULL OR
       v_attempt.platform_effect_request_sha256 IS NOT NULL OR
       v_attempt.effect_started_at IS NOT NULL OR
       v_export.effect_started_at IS NOT NULL OR
       v_finalized_at<v_export.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export pre-effect expiry evidence differs';
    END IF;
    UPDATE analytics_dashboard_export_platform_attempts
    SET outcome=v_outcome,failure_class=v_failure_class,
        failure_code=v_failure_code,failure_sha256=v_failure_sha256,
        finished_at=v_finalized_at
    WHERE export_id=p_export_id AND attempt_generation=p_attempt_generation;
    UPDATE analytics_dashboard_exports
    SET state=v_domain_state,quota_state=v_quota_state,
        failure_code=CASE WHEN v_final_state='dead' THEN v_failure_code END,
        lease_owner=NULL,lease_until=NULL,platform_attempt_id=NULL,
        platform_effect_id=NULL,platform_effect_request_sha256=NULL,
        row_revision=row_revision+1,updated_at=v_finalized_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    final_state:=v_final_state;finalized_at:=v_finalized_at;RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_expired_finalize_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_expiry_control_v1(name, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_expiry_control_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_expiry_job_id uuid, p_observed_at timestamp with time zone) RETURNS TABLE(state text, cleanup_required boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_job_id uuid;
    v_control_state text;
    v_control_changed_at timestamptz;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_update_at timestamptz;
    v_replay boolean;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_expiry_job_id) IS DISTINCT FROM 7 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export expiry control scope is invalid';
    END IF;
    SELECT item.job_id INTO v_job_id FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.expiry_job_id=p_expiry_job_id AND item.expires_at<=p_observed_at;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export expiry candidate changed';
    END IF;
    SELECT control.control_state,control.changed_at
    INTO STRICT v_control_state,v_control_changed_at
    FROM platform.platform_async_analytics_dashboard_export_control_v1(
        p_tenant_id,p_export_id,v_job_id,p_observed_at
    ) AS control;
    SELECT item.* INTO STRICT v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=v_job_id AND item.expiry_job_id=p_expiry_job_id
      AND item.expires_at<=p_observed_at FOR UPDATE;
    v_replay:=v_export.delete_operation_id IS NOT DISTINCT FROM p_expiry_job_id AND
        v_export.delete_job_id IS NOT DISTINCT FROM p_expiry_job_id AND
        v_export.delete_actor_id IS NOT DISTINCT FROM v_export.actor_id AND
        v_export.delete_idempotency_key IS NOT DISTINCT FROM
            'analytics-expiry:'||p_export_id::text AND
        v_export.delete_request_sha256 IS NOT DISTINCT FROM pg_catalog.sha256(pg_catalog.convert_to(
            'analytics-expiry:'||p_export_id::text,'UTF8'));
    IF v_export.delete_operation_id IS NOT NULL AND NOT v_replay THEN
        state:=v_export.state;cleanup_required:=false;RETURN NEXT;RETURN;
    END IF;
    IF v_control_state='cancelled' THEN
        IF v_export.state NOT IN ('queued','expired') OR
           v_export.quota_state NOT IN ('none','released') THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export queued expiry differs';
        END IF;
        state:='expired';cleanup_required:=false;
    ELSIF v_control_state IN ('cancellation_requested','outcome_unknown') THEN
        IF v_export.state IS DISTINCT FROM 'running' OR
           v_export.quota_state IS DISTINCT FROM 'held' OR
           v_export.platform_attempt_id IS NULL OR
           (v_control_state='outcome_unknown' AND
            v_export.failure_code IS DISTINCT FROM 'ARTIFACT_OUTCOME_UNKNOWN') THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export active expiry differs';
        END IF;
        state:='expired';cleanup_required:=false;
    ELSIF v_control_state='succeeded' THEN
        IF v_export.state NOT IN ('ready','deleting','deleted') OR
           v_export.quota_state NOT IN ('used','released') THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export ready expiry differs';
        END IF;
        state:=v_export.state;
        cleanup_required:=v_export.state IN ('ready','deleting');
    ELSIF v_control_state IN ('dead','unknown_resolved') THEN
        IF v_export.state NOT IN ('failed','cancelled','expired','deleted') OR
           v_export.quota_state IS DISTINCT FROM 'released' THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export terminal expiry differs';
        END IF;
        state:=v_export.state;cleanup_required:=false;
    ELSE
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export expiry control is invalid';
    END IF;
    IF v_replay THEN RETURN NEXT;RETURN; END IF;
    v_update_at:=GREATEST(p_observed_at,v_control_changed_at,
        v_export.updated_at+interval '1 microsecond');
    UPDATE analytics_dashboard_exports
    SET state=CASE WHEN v_control_state='cancelled' THEN 'expired'
            ELSE analytics_dashboard_exports.state END,
        quota_state=CASE WHEN v_control_state='cancelled'
            THEN 'released' ELSE quota_state END,
        cancellation_requested_at=CASE WHEN v_control_state IN (
            'cancellation_requested','outcome_unknown') THEN
            COALESCE(cancellation_requested_at,p_observed_at)
            ELSE cancellation_requested_at END,
        delete_operation_id=p_expiry_job_id,delete_job_id=p_expiry_job_id,
        delete_actor_id=actor_id,
        delete_idempotency_key='analytics-expiry:'||p_export_id::text,
        delete_request_sha256=pg_catalog.sha256(pg_catalog.convert_to(
            'analytics-expiry:'||p_export_id::text,'UTF8')),
        row_revision=row_revision+1,updated_at=v_update_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_expiry_control_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_expiry_job_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_fail_render_v1(name, uuid, uuid, bigint, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_fail_render_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_failure_code text, p_retryable boolean, p_failed_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export analytics_dashboard_exports%ROWTYPE;
    v_next text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_lease_owner IS NULL OR
       p_lease_owner='00000000-0000-0000-0000-000000000000'::uuid OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.octet_length(p_failure_code) NOT BETWEEN 3 AND 64 OR
       p_retryable IS NULL OR p_failed_at IS NULL OR
       NOT pg_catalog.isfinite(p_failed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export failure input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT item.* INTO v_export
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.state='running'
      AND item.lease_owner=p_lease_owner
      AND item.attempt_generation=p_attempt_generation
      AND item.effect_started_at IS NULL AND item.quota_state='held'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export failure changed';
    END IF;
    v_next:=CASE WHEN p_retryable AND p_attempt_generation<3
                 THEN 'queued' ELSE 'failed' END;
    UPDATE platform.artifact_quota_counters
    SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
        revision=revision+1,updated_at=p_failed_at
    WHERE tenant_id=v_export.tenant_id
      AND reserved_ciphertext_bytes>=2147483648;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6105',
            MESSAGE='analytics dashboard export failure quota changed';
    END IF;
    UPDATE analytics_dashboard_exports
    SET state=v_next,quota_state=CASE WHEN v_next='queued'
            THEN 'none' ELSE 'released' END,
        failure_code=CASE WHEN v_next='failed' THEN p_failure_code ELSE NULL END,
        lease_owner=NULL,lease_until=NULL,row_revision=row_revision+1,
        updated_at=p_failed_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN v_next;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_fail_render_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_failure_code text, p_retryable boolean, p_failed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_maintenance_resolution_digest_v1(text, text, text, text, text, text, bytea, bytea, bytea, bytea, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_maintenance_resolution_digest_v1(p_kind text, p_terminal_state text, p_object_key text, p_object_version text, p_reconcile_request_id text, p_delete_request_id text, p_reconcile_sha256 bytea, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_local_state_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_verified_at timestamp with time zone, p_local_state_at timestamp with time zone, p_resolved_at timestamp with time zone) RETURNS bytea
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
SELECT pg_catalog.sha256(
    pg_catalog.convert_to('analytics-dashboard-export-maintenance-resolution-v1','UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(p_kind)::bigint)||
    pg_catalog.convert_to(p_kind,'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(p_terminal_state)::bigint)||
    pg_catalog.convert_to(p_terminal_state,'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(COALESCE(p_object_key,''))::bigint)||
    pg_catalog.convert_to(COALESCE(p_object_key,''),'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(COALESCE(p_object_version,''))::bigint)||
    pg_catalog.convert_to(COALESCE(p_object_version,''),'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(COALESCE(p_reconcile_request_id,''))::bigint)||
    pg_catalog.convert_to(COALESCE(p_reconcile_request_id,''),'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(COALESCE(p_delete_request_id,''))::bigint)||
    pg_catalog.convert_to(COALESCE(p_delete_request_id,''),'UTF8')||
    COALESCE(p_reconcile_sha256,pg_catalog.decode(pg_catalog.repeat('00',32),'hex'))||
    COALESCE(p_delete_response_sha256,pg_catalog.decode(pg_catalog.repeat('00',32),'hex'))||
    COALESCE(p_absence_sha256,pg_catalog.decode(pg_catalog.repeat('00',32),'hex'))||
    p_local_state_sha256||
    pg_catalog.int8send(COALESCE((EXTRACT(EPOCH FROM p_upload_completed_at)*1000000)::bigint,0))||
    pg_catalog.int8send(COALESCE((EXTRACT(EPOCH FROM p_reconcile_verified_at)*1000000)::bigint,0))||
    pg_catalog.int8send(COALESCE((EXTRACT(EPOCH FROM p_delete_verified_at)*1000000)::bigint,0))||
    pg_catalog.int8send((EXTRACT(EPOCH FROM p_local_state_at)*1000000)::bigint)||
    pg_catalog.int8send((EXTRACT(EPOCH FROM p_resolved_at)*1000000)::bigint)
);
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_maintenance_resolution_digest_v1(p_kind text, p_terminal_state text, p_object_key text, p_object_version text, p_reconcile_request_id text, p_delete_request_id text, p_reconcile_sha256 bytea, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_local_state_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_verified_at timestamp with time zone, p_local_state_at timestamp with time zone, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_exports; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.analytics_dashboard_exports (
    export_id uuid NOT NULL,
    dashboard_id uuid NOT NULL,
    dashboard_version_id uuid NOT NULL,
    job_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    format text NOT NULL,
    state text NOT NULL,
    row_revision bigint NOT NULL,
    idempotency_key text NOT NULL,
    request_sha256 bytea NOT NULL,
    token_version bigint NOT NULL,
    authorization_version bigint NOT NULL,
    authorization_clock bigint NOT NULL,
    dashboard_manifest_sha256 bytea NOT NULL,
    pin_sha256 bytea NOT NULL,
    parameters_document bytea NOT NULL,
    parameters_sha256 bytea NOT NULL,
    pinned_widgets jsonb NOT NULL,
    widget_count smallint NOT NULL,
    maximum_rows bigint NOT NULL,
    maximum_plaintext_bytes bigint NOT NULL,
    attempt_generation bigint DEFAULT 0 NOT NULL,
    lease_owner uuid,
    lease_until timestamp with time zone,
    cancellation_requested_at timestamp with time zone,
    effect_started_at timestamp with time zone,
    object_key text,
    object_version text,
    key_id text,
    wrapped_dek bytea,
    wrap_nonce bytea,
    header_sha256 bytea,
    ciphertext_sha256 bytea,
    plaintext_sha256 bytea,
    ciphertext_bytes bigint,
    plaintext_bytes bigint,
