    CONSTRAINT analytics_dashboard_export_maintenance_cleanup_check CHECK ((((maintenance_unknown_job_id IS NULL) AND (maintenance_cleanup_generation IS NULL) AND (maintenance_cleanup_lease_owner IS NULL) AND (maintenance_cleanup_lease_until IS NULL) AND (maintenance_local_state_sha256 IS NULL) AND (maintenance_local_state_at IS NULL)) OR ((uuid_extract_version(maintenance_unknown_job_id) = 7) AND (maintenance_cleanup_generation >= 1) AND (((maintenance_cleanup_lease_owner IS NULL) AND (maintenance_cleanup_lease_until IS NULL)) OR ((uuid_extract_version(maintenance_cleanup_lease_owner) = 7) AND (maintenance_cleanup_lease_until IS NOT NULL) AND isfinite(maintenance_cleanup_lease_until))) AND (octet_length(maintenance_local_state_sha256) = 32) AND (encode(maintenance_local_state_sha256, 'hex'::text) IS DISTINCT FROM repeat('0'::text, 64)) AND isfinite(maintenance_local_state_at)))),
    CONSTRAINT analytics_dashboard_exports_expiry_job_check CHECK (((expiry_job_id IS NULL) OR (uuid_extract_version(expiry_job_id) = 7))),
    CONSTRAINT analytics_dashboard_exports_expiry_job_separation_check CHECK (((expiry_job_id IS NULL) OR ((expiry_job_id <> export_id) AND (expiry_job_id <> job_id)))),
    CONSTRAINT analytics_dashboard_exports_identity_check CHECK (((uuid_extract_version(export_id) = 7) AND (uuid_extract_version(job_id) = 7) AND (actor_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND ((octet_length(idempotency_key) >= 16) AND (octet_length(idempotency_key) <= 128)) AND (octet_length(request_sha256) = 32))),
    CONSTRAINT analytics_dashboard_exports_pin_check CHECK (((format = ANY (ARRAY['csv'::text, 'xlsx'::text, 'pdf'::text])) AND (octet_length(dashboard_manifest_sha256) = 32) AND (octet_length(pin_sha256) = 32) AND ((octet_length(parameters_document) >= 2) AND (octet_length(parameters_document) <= 65536)) AND (sha256(parameters_document) = parameters_sha256) AND pg_input_is_valid(convert_from(parameters_document, 'UTF8'::name), 'jsonb'::text) AND (jsonb_typeof(pinned_widgets) = 'array'::text) AND (widget_count = jsonb_array_length(pinned_widgets)) AND ((widget_count >= 1) AND (widget_count <= 30)) AND ((maximum_rows >= 1) AND (maximum_rows <= 100000)) AND ((maximum_plaintext_bytes >= 1) AND (maximum_plaintext_bytes <= 67108864)) AND (token_version > 0) AND (authorization_version > 0) AND (authorization_clock > 0))),
    CONSTRAINT analytics_dashboard_exports_platform_evidence_check CHECK ((((platform_attempt_id IS NULL) OR (uuid_extract_version(platform_attempt_id) = 7)) AND ((platform_effect_id IS NULL) OR (uuid_extract_version(platform_effect_id) = 7)) AND ((platform_effect_request_sha256 IS NULL) OR (octet_length(platform_effect_request_sha256) = 32)) AND (((platform_effect_id IS NULL) AND (platform_effect_request_sha256 IS NULL)) OR ((platform_effect_id IS NOT NULL) AND (platform_effect_request_sha256 IS NOT NULL))) AND ((quota_state = 'held'::text) = (platform_attempt_id IS NOT NULL)) AND ((platform_effect_id IS NULL) OR ((platform_attempt_id IS NOT NULL) AND (effect_started_at IS NOT NULL))) AND ((effect_started_at IS NULL) OR (quota_state <> 'held'::text) OR (platform_effect_id IS NOT NULL)))),
