--
-- Name: analytics_dashboard_export_maintenance_unknown_resolve_v1(name, text, uuid, name, uuid, text, bigint, bigint, uuid, uuid, integer, bigint, uuid, uuid, bytea, timestamp with time zone, bigint, uuid, bigint, uuid, uuid, bytea, text, bytea, text, bytea, timestamp with time zone, text, text, text, bytea, timestamp with time zone, timestamp with time zone, text, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_maintenance_unknown_resolve_v1(p_scope_schema name, p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_delete_attempt_generation bigint, p_resolution_receipt_id uuid, p_effect_receipt_id uuid, p_effect_receipt_sha256 bytea, p_resolution_kind text, p_resolution_sha256 bytea, p_terminal_state text, p_local_state_sha256 bytea, p_local_state_at timestamp with time zone, p_object_key text, p_object_version text, p_reconcile_request_id text, p_reconcile_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_delete_verified_at timestamp with time zone, p_resolved_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_tenant_id uuid;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_resolution analytics_dashboard_export_maintenance_unknown_resolutions%ROWTYPE;
    v_platform_replayed boolean;
    v_platform_effect_receipt_id uuid;
    v_platform_state text;
    v_release_bytes bigint:=0;
    v_active boolean:=false;
    v_mode text;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_authority_group_id!~'^[a-z][a-z0-9_]{0,62}$' OR
       p_authority_group_generation<1 OR p_cutover_generation<1 OR
       p_delete_attempt_generation NOT BETWEEN 0 AND 3 OR
       pg_catalog.uuid_extract_version(p_resolution_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_receipt_id) IS DISTINCT FROM 5 OR
       p_unknown_at IS NULL OR NOT pg_catalog.isfinite(p_unknown_at) OR
       p_resolved_at<=p_unknown_at OR
       analytics_dashboard_export_maintenance_resolution_valid_v1(
          p_kind,p_resolution_kind,p_resolution_sha256,p_terminal_state,
          p_local_state_sha256,p_local_state_at,p_object_key,p_object_version,
          p_reconcile_request_id,p_reconcile_sha256,p_upload_completed_at,
          p_reconcile_verified_at,p_delete_request_id,p_delete_response_sha256,
          p_absence_sha256,p_delete_verified_at,p_resolved_at) IS NOT TRUE THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export maintenance resolution scope is invalid';
    END IF;
    SELECT resolved.replayed,resolved.effect_receipt_id,resolved.job_state
    INTO STRICT v_platform_replayed,v_platform_effect_receipt_id,v_platform_state
    FROM platform.platform_async_analytics_dashboard_export_maintenance_unknown_resolve_v1(
        p_kind,p_tenant_id,p_tenant_schema,p_export_id,p_authority_group_id,
        p_authority_group_generation,p_cutover_generation,p_job_id,p_attempt_id,
        p_attempt_number,p_lease_generation,p_original_lease_owner_id,p_effect_id,
        p_request_sha256,p_unknown_at,p_cleanup_generation,p_cleanup_lease_owner_id,
        p_resolution_receipt_id,p_effect_receipt_id,p_effect_receipt_sha256,
        p_terminal_state,p_resolution_sha256,p_resolved_at
    ) AS resolved;
    IF v_platform_effect_receipt_id IS DISTINCT FROM p_effect_receipt_id OR
       v_platform_state IS DISTINCT FROM 'succeeded' THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance platform resolution differs';
    END IF;
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND ((p_kind='analytics.dashboard.export.delete' AND
            item.delete_job_id=p_job_id AND item.expiry_job_id IS DISTINCT FROM p_job_id) OR
           (p_kind='analytics.dashboard.export.expire' AND
            item.expiry_job_id=p_job_id AND item.delete_job_id=p_job_id))
    FOR UPDATE;
    SELECT stored.* INTO v_resolution
    FROM analytics_dashboard_export_maintenance_unknown_resolutions AS stored
    WHERE stored.job_id=p_job_id FOR SHARE;
    IF FOUND THEN
        IF NOT v_platform_replayed OR NOT
           analytics_dashboard_export_maintenance_resolution_replay_matches_v1(
              v_resolution,pg_catalog.jsonb_build_array(
                p_tenant_id,p_tenant_schema,p_kind,p_export_id,p_authority_group_id,
                p_authority_group_generation,p_cutover_generation,p_job_id,p_attempt_id,
                p_attempt_number,p_lease_generation,p_original_lease_owner_id,
                p_effect_id,p_request_sha256,p_unknown_at,p_cleanup_generation,
                p_cleanup_lease_owner_id,p_delete_attempt_generation,
                p_resolution_receipt_id,p_effect_receipt_id,p_effect_receipt_sha256,
                p_resolution_kind,p_resolution_sha256,p_terminal_state,
                p_local_state_sha256,p_local_state_at,p_object_key,p_object_version,
                p_reconcile_request_id,p_reconcile_sha256,p_upload_completed_at,
                p_reconcile_verified_at,p_delete_request_id,p_delete_response_sha256,
                p_absence_sha256,p_delete_verified_at,p_resolved_at)) OR
           v_export.state IS DISTINCT FROM p_terminal_state OR
           v_export.quota_state IS DISTINCT FROM 'released' OR
           v_export.maintenance_unknown_job_id IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export maintenance resolution replay differs';
        END IF;
        RETURN p_terminal_state;
    END IF;
    IF v_export.export_id IS NULL OR v_platform_replayed OR
       v_export.maintenance_unknown_job_id IS DISTINCT FROM p_job_id OR
       v_export.maintenance_cleanup_generation IS DISTINCT FROM p_cleanup_generation OR
       v_export.maintenance_cleanup_lease_owner IS DISTINCT FROM p_cleanup_lease_owner_id OR
       v_export.maintenance_cleanup_lease_until<=pg_catalog.clock_timestamp() OR
       v_export.maintenance_local_state_sha256 IS DISTINCT FROM p_local_state_sha256 OR
       v_export.maintenance_local_state_at IS DISTINCT FROM p_local_state_at OR
       v_export.delete_attempt_generation IS DISTINCT FROM p_delete_attempt_generation OR
       p_resolved_at<v_export.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance lease differs';
    END IF;
    v_mode:=analytics_dashboard_export_maintenance_resolution_mode_v1(
        v_export,p_kind,p_terminal_state,p_resolution_kind,p_object_key,
        p_object_version,p_delete_request_id,p_delete_response_sha256,
        p_absence_sha256,p_delete_verified_at,p_unknown_at,p_local_state_at,
        p_cleanup_lease_owner_id,p_delete_attempt_generation);
    IF v_mode IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export maintenance state differs';
    END IF;
    v_active:=v_mode='active';
    IF v_active THEN
        v_release_bytes:=v_export.ciphertext_bytes;
        UPDATE platform.artifact_quota_counters
        SET used_ciphertext_bytes=used_ciphertext_bytes-v_release_bytes,
            revision=revision+1,updated_at=p_resolved_at
        WHERE tenant_id=p_tenant_id AND used_ciphertext_bytes>=v_release_bytes;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6105',
                MESSAGE='Analytics dashboard export maintenance quota differs';
        END IF;
    END IF;
    INSERT INTO analytics_dashboard_export_maintenance_unknown_resolutions(
        resolution_receipt_id,effect_receipt_id,effect_receipt_sha256,resolution_sha256,
        tenant_id,tenant_schema,kind,export_id,authority_group_id,
        authority_group_generation,cutover_generation,job_id,attempt_id,attempt_number,
        lease_generation,original_lease_owner_id,effect_id,effect_request_sha256,
        original_unknown_at,cleanup_generation,cleanup_lease_owner_id,
        delete_attempt_generation,resolution_kind,terminal_state,local_state_sha256,
        local_state_at,object_key,object_version,reconcile_provider_request_id,
        reconcile_evidence_sha256,upload_completed_at,reconcile_verified_at,
        delete_provider_request_id,delete_response_sha256,absence_sha256,
        delete_verified_at,quota_released_bytes,resolved_at
    ) VALUES (
        p_resolution_receipt_id,p_effect_receipt_id,p_effect_receipt_sha256,
        p_resolution_sha256,p_tenant_id,p_tenant_schema,p_kind,p_export_id,
        p_authority_group_id,p_authority_group_generation,p_cutover_generation,
        p_job_id,p_attempt_id,p_attempt_number,p_lease_generation,
        p_original_lease_owner_id,p_effect_id,p_request_sha256,p_unknown_at,
        p_cleanup_generation,p_cleanup_lease_owner_id,p_delete_attempt_generation,
        p_resolution_kind,p_terminal_state,p_local_state_sha256,p_local_state_at,
        p_object_key,p_object_version,p_reconcile_request_id,p_reconcile_sha256,
        p_upload_completed_at,p_reconcile_verified_at,p_delete_request_id,
        p_delete_response_sha256,p_absence_sha256,p_delete_verified_at,
        v_release_bytes,p_resolved_at
    );
    UPDATE analytics_dashboard_exports
    SET state=CASE WHEN v_active THEN 'deleted' ELSE state END,
        quota_state=CASE WHEN v_active THEN 'released' ELSE quota_state END,
        delete_provider_request_id=CASE WHEN v_active THEN p_delete_request_id
            ELSE delete_provider_request_id END,
        delete_response_sha256=CASE WHEN v_active THEN p_delete_response_sha256
            ELSE delete_response_sha256 END,
        delete_absence_sha256=CASE WHEN v_active THEN p_absence_sha256
            ELSE delete_absence_sha256 END,
        delete_verified_at=CASE WHEN v_active THEN p_delete_verified_at
            ELSE delete_verified_at END,
        deleted_at=CASE WHEN v_active THEN p_resolved_at ELSE deleted_at END,
        delete_lease_owner=NULL,delete_lease_until=NULL,
        maintenance_unknown_job_id=NULL,maintenance_cleanup_generation=NULL,
        maintenance_cleanup_lease_owner=NULL,maintenance_cleanup_lease_until=NULL,
        maintenance_local_state_sha256=NULL,maintenance_local_state_at=NULL,
        row_revision=row_revision+1,updated_at=p_resolved_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN p_terminal_state;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_maintenance_unknown_resolve_v1(p_scope_schema name, p_kind text, p_tenant_id uuid, p_tenant_schema name, p_export_id uuid, p_authority_group_id text, p_authority_group_generation bigint, p_cutover_generation bigint, p_job_id uuid, p_attempt_id uuid, p_attempt_number integer, p_lease_generation bigint, p_original_lease_owner_id uuid, p_effect_id uuid, p_request_sha256 bytea, p_unknown_at timestamp with time zone, p_cleanup_generation bigint, p_cleanup_lease_owner_id uuid, p_delete_attempt_generation bigint, p_resolution_receipt_id uuid, p_effect_receipt_id uuid, p_effect_receipt_sha256 bytea, p_resolution_kind text, p_resolution_sha256 bytea, p_terminal_state text, p_local_state_sha256 bytea, p_local_state_at timestamp with time zone, p_object_key text, p_object_version text, p_reconcile_request_id text, p_reconcile_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_delete_verified_at timestamp with time zone, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_outcome_unknown_v1(name, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_outcome_unknown_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_lease_owner IS NULL OR
       p_lease_owner='00000000-0000-0000-0000-000000000000'::uuid OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export unknown outcome input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    UPDATE analytics_dashboard_exports
    SET failure_code='ARTIFACT_OUTCOME_UNKNOWN',lease_owner=NULL,
        lease_until=NULL,row_revision=row_revision+1,updated_at=p_observed_at
    WHERE export_id=p_export_id AND state='running'
      AND lease_owner=p_lease_owner
      AND attempt_generation=p_attempt_generation
      AND effect_started_at IS NOT NULL AND quota_state='held';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export unknown outcome changed';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_outcome_unknown_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_platform_checkpoint_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_platform_checkpoint_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_observed_at timestamp with time zone) RETURNS TABLE(lease_until timestamp with time zone, cancellation_requested boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_platform_lease timestamptz; v_cancel boolean;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       p_lease_owner IS NULL OR p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export checkpoint scope is invalid';
    END IF;
    SELECT checkpoint.lease_until,checkpoint.cancellation_requested
    INTO v_platform_lease,v_cancel
    FROM platform.platform_async_analytics_dashboard_export_checkpoint_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_attempt_generation,
        p_lease_owner,p_observed_at
    ) AS checkpoint;
    IF v_platform_lease IS NULL OR NOT pg_catalog.isfinite(v_platform_lease) OR
       v_platform_lease<=p_observed_at OR v_cancel IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export checkpoint result is invalid';
    END IF;
    PERFORM 1 FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id AND item.state='running' AND p_observed_at>item.updated_at
      AND item.quota_state='held'
      AND item.platform_attempt_id=p_attempt_id
      AND item.attempt_generation=p_attempt_generation
      AND item.lease_owner=p_lease_owner FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export checkpoint is stale';
    END IF;
    UPDATE analytics_dashboard_exports
    SET lease_until=v_platform_lease,
        cancellation_requested_at=CASE WHEN v_cancel THEN
            COALESCE(cancellation_requested_at,p_observed_at)
            ELSE cancellation_requested_at END,
        row_revision=row_revision+1,
        updated_at=GREATEST(updated_at,p_observed_at)
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    UPDATE analytics_dashboard_export_platform_attempts
    SET lease_until=v_platform_lease
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation
      AND platform_attempt_id=p_attempt_id AND outcome='running';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export checkpoint evidence changed';
    END IF;
    lease_until:=v_platform_lease;cancellation_requested:=v_cancel;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_platform_checkpoint_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_platform_claim_v1(name, uuid, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_platform_claim_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_generation bigint, p_lease_owner uuid) RETURNS TABLE(claim_state text, attempt_id uuid, claimed_at timestamp with time zone, lease_until timestamp with time zone, disposition text, state text, actor_id uuid, export_id uuid, dashboard_id uuid, dashboard_version_id uuid, job_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, dashboard_manifest_sha256 bytea, pin_sha256 bytea, format text, parameters_document bytea, pinned_widgets jsonb, maximum_rows bigint, maximum_plaintext_bytes bigint, expires_at timestamp with time zone, attempt_generation bigint, lease_owner uuid, effect_started boolean, object_key text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_claim_state text;
    v_attempt_id uuid;
    v_claimed_at timestamptz;
    v_lease_until timestamptz;
    v_replay boolean;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton
      AND identity_row.schema_name=pg_catalog.current_schema();
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       p_attempt_generation IS NULL OR p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export claim scope is invalid';
    END IF;
    SELECT platform_claim.claim_state,platform_claim.attempt_id,
           platform_claim.claimed_at,platform_claim.lease_until
    INTO v_claim_state,v_attempt_id,v_claimed_at,v_lease_until
    FROM platform.platform_async_analytics_dashboard_export_claim_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_generation,p_lease_owner
    ) AS platform_claim;
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id FOR UPDATE;
    IF NOT FOUND OR v_export.expires_at<=pg_catalog.clock_timestamp() OR
       v_export.cancellation_requested_at IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export candidate changed';
    END IF;
    v_replay:=v_export.state IS NOT DISTINCT FROM 'running' AND
        v_export.quota_state IS NOT DISTINCT FROM 'held' AND
        v_export.attempt_generation IS NOT DISTINCT FROM p_attempt_generation AND
        v_export.lease_owner IS NOT DISTINCT FROM p_lease_owner AND
        v_export.platform_attempt_id IS NOT NULL;
    IF NOT v_replay AND (
       v_export.state IS DISTINCT FROM 'queued' OR
       v_export.quota_state IS DISTINCT FROM 'none' OR
       v_export.attempt_generation+1 IS DISTINCT FROM p_attempt_generation OR
       v_export.platform_attempt_id IS NOT NULL OR
       v_export.platform_effect_id IS NOT NULL OR
       v_export.effect_started_at IS NOT NULL) THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='Analytics dashboard export candidate changed';
    END IF;
    IF v_claim_state IS NOT DISTINCT FROM 'quota_wait' THEN
        IF v_replay OR v_attempt_id IS NOT NULL OR v_claimed_at IS NOT NULL OR
           v_lease_until IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export claim replay lost quota';
        END IF;
        claim_state:='quota_wait'; RETURN NEXT; RETURN;
    ELSIF v_claim_state IS DISTINCT FROM 'claimed' OR
          pg_catalog.uuid_extract_version(v_attempt_id) IS DISTINCT FROM 7 OR
          v_claimed_at IS NULL OR NOT pg_catalog.isfinite(v_claimed_at) OR
          v_lease_until IS NULL OR NOT pg_catalog.isfinite(v_lease_until) OR
          v_lease_until<=v_claimed_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export platform claim is invalid';
    END IF;
    IF v_replay THEN
        IF v_export.platform_attempt_id IS DISTINCT FROM v_attempt_id OR
           v_export.lease_until IS DISTINCT FROM v_lease_until THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export claim replay differs';
        END IF;
        PERFORM 1 FROM analytics_dashboard_export_platform_attempts AS attempt
        WHERE attempt.export_id=p_export_id
          AND attempt.attempt_generation=p_attempt_generation
          AND attempt.platform_attempt_id=v_attempt_id
          AND attempt.job_id=p_job_id AND attempt.lease_owner=p_lease_owner
          AND attempt.outcome='running' FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export attempt evidence is missing';
        END IF;
    ELSE
        UPDATE analytics_dashboard_exports
        SET state='running',attempt_generation=p_attempt_generation,
            quota_state='held',lease_owner=p_lease_owner,
            lease_until=v_lease_until,platform_attempt_id=v_attempt_id,
            failure_code=NULL,row_revision=row_revision+1,
            updated_at=GREATEST(updated_at,v_claimed_at)
        WHERE analytics_dashboard_exports.export_id=p_export_id;
        INSERT INTO analytics_dashboard_export_platform_attempts(
            export_id,attempt_generation,job_id,platform_attempt_id,lease_owner,
            claimed_at,lease_until,outcome
        ) VALUES (
            p_export_id,p_attempt_generation,p_job_id,v_attempt_id,p_lease_owner,
            v_claimed_at,v_lease_until,'running'
        );
    END IF;
    RETURN QUERY
    SELECT 'claimed'::text,v_attempt_id,v_claimed_at,v_lease_until,snapshot.*
    FROM analytics_dashboard_export_worker_snapshot_v1(
        p_export_id,'execute'
    ) AS snapshot;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_platform_claim_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_generation bigint, p_lease_owner uuid) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_platform_effect_start_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, text, text, bytea, bytea, bytea, bytea, bytea, bigint, bigint, bigint, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_platform_effect_start_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_object_key text, p_key_id text, p_wrapped_dek bytea, p_wrap_nonce bytea, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_plaintext_sha256 bytea, p_ciphertext_bytes bigint, p_plaintext_bytes bigint, p_row_count bigint, p_content_type text, p_filename text, p_started_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid; v_export analytics_dashboard_exports%ROWTYPE;
    v_persisted_at timestamptz; v_exact boolean;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR p_lease_owner IS NULL OR
       pg_catalog.octet_length(p_effect_request_sha256) IS DISTINCT FROM 32 OR
       COALESCE(pg_catalog.octet_length(p_object_key),0) NOT BETWEEN 10 AND 512 OR
       COALESCE(pg_catalog.octet_length(p_key_id),0) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_wrapped_dek) IS DISTINCT FROM 48 OR
       pg_catalog.octet_length(p_wrap_nonce) IS DISTINCT FROM 12 OR
       pg_catalog.octet_length(p_header_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_ciphertext_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_plaintext_sha256) IS DISTINCT FROM 32 OR
       COALESCE(p_ciphertext_bytes,0) NOT BETWEEN 35 AND 2147483648 OR
       COALESCE(p_plaintext_bytes,0) NOT BETWEEN 1 AND 67108864 OR
       COALESCE(p_row_count,-1)<0 OR COALESCE(pg_catalog.octet_length(p_content_type),0) NOT BETWEEN 3 AND 128 OR
       COALESCE(pg_catalog.octet_length(p_filename),0) NOT BETWEEN 5 AND 255 OR
       p_started_at IS NULL OR NOT pg_catalog.isfinite(p_started_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export effect scope is invalid';
    END IF;
    v_persisted_at:=
        platform.platform_async_analytics_dashboard_export_effect_start_v1(
            p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_attempt_generation,
            p_lease_owner,p_effect_id,p_effect_request_sha256,p_started_at);
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id AND item.state='running'
      AND item.quota_state='held' AND item.platform_attempt_id=p_attempt_id
      AND item.attempt_generation=p_attempt_generation
      AND item.lease_owner=p_lease_owner FOR UPDATE;
    IF NOT FOUND OR v_persisted_at IS NULL OR NOT pg_catalog.isfinite(v_persisted_at) OR
       v_export.cancellation_requested_at IS NOT NULL OR v_export.expires_at<=p_started_at OR
       (v_export.effect_started_at IS NULL AND v_persisted_at<=v_export.updated_at) THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export effect lease is stale';
    END IF;
    IF v_export.effect_started_at IS NOT NULL THEN
        SELECT receipt.platform_attempt_id IS NOT DISTINCT FROM p_attempt_id AND
               receipt.platform_effect_id IS NOT DISTINCT FROM p_effect_id AND
               receipt.platform_effect_request_sha256 IS NOT DISTINCT FROM p_effect_request_sha256 AND
               receipt.object_key IS NOT DISTINCT FROM p_object_key AND
               receipt.key_id IS NOT DISTINCT FROM p_key_id AND
               receipt.wrapped_dek IS NOT DISTINCT FROM p_wrapped_dek AND
               receipt.wrap_nonce IS NOT DISTINCT FROM p_wrap_nonce AND
               receipt.header_sha256 IS NOT DISTINCT FROM p_header_sha256 AND
               receipt.ciphertext_sha256 IS NOT DISTINCT FROM p_ciphertext_sha256 AND
               receipt.plaintext_sha256 IS NOT DISTINCT FROM p_plaintext_sha256 AND
               receipt.ciphertext_bytes IS NOT DISTINCT FROM p_ciphertext_bytes AND
               receipt.plaintext_bytes IS NOT DISTINCT FROM p_plaintext_bytes AND
               receipt.row_count IS NOT DISTINCT FROM p_row_count AND
               v_export.content_type IS NOT DISTINCT FROM p_content_type AND
               v_export.filename IS NOT DISTINCT FROM p_filename AND
               receipt.started_at IS NOT DISTINCT FROM v_persisted_at INTO v_exact
        FROM analytics_dashboard_export_attempt_receipts AS receipt
        WHERE receipt.export_id=p_export_id
          AND receipt.attempt_generation=p_attempt_generation FOR UPDATE;
        IF v_export.platform_effect_id IS DISTINCT FROM p_effect_id OR
           v_export.platform_effect_request_sha256 IS DISTINCT FROM p_effect_request_sha256 OR
           v_export.effect_started_at IS DISTINCT FROM v_persisted_at OR
           NOT COALESCE(v_exact,false) THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export effect replay differs';
        END IF;
        RETURN v_persisted_at;
    END IF;
    UPDATE analytics_dashboard_exports
    SET effect_started_at=v_persisted_at,platform_effect_id=p_effect_id,
        platform_effect_request_sha256=p_effect_request_sha256,
        object_key=p_object_key,key_id=p_key_id,wrapped_dek=p_wrapped_dek,
        wrap_nonce=p_wrap_nonce,header_sha256=p_header_sha256,
        ciphertext_sha256=p_ciphertext_sha256,
        plaintext_sha256=p_plaintext_sha256,
        ciphertext_bytes=p_ciphertext_bytes,plaintext_bytes=p_plaintext_bytes,
        row_count=p_row_count,content_type=p_content_type,filename=p_filename,
        row_revision=row_revision+1,updated_at=v_persisted_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    UPDATE analytics_dashboard_export_platform_attempts
    SET platform_effect_id=p_effect_id,
        platform_effect_request_sha256=p_effect_request_sha256,
        effect_started_at=v_persisted_at
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation
      AND platform_attempt_id=p_attempt_id AND outcome='running';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export attempt evidence changed';
    END IF;
    INSERT INTO analytics_dashboard_export_attempt_receipts(
        export_id,attempt_generation,object_key,key_id,wrapped_dek,wrap_nonce,
        header_sha256,ciphertext_sha256,plaintext_sha256,ciphertext_bytes,
        plaintext_bytes,row_count,outcome,started_at,platform_attempt_id,
        platform_effect_id,platform_effect_request_sha256
    ) VALUES (
        p_export_id,p_attempt_generation,p_object_key,p_key_id,p_wrapped_dek,
        p_wrap_nonce,p_header_sha256,p_ciphertext_sha256,p_plaintext_sha256,
        p_ciphertext_bytes,p_plaintext_bytes,p_row_count,'started',
        v_persisted_at,p_attempt_id,p_effect_id,p_effect_request_sha256
    );
    RETURN v_persisted_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_platform_effect_start_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_object_key text, p_key_id text, p_wrapped_dek bytea, p_wrap_nonce bytea, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_plaintext_sha256 bytea, p_ciphertext_bytes bigint, p_plaintext_bytes bigint, p_row_count bigint, p_content_type text, p_filename text, p_started_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_platform_finish_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, text, text, bytea, boolean, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_platform_finish_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_failure_class text, p_failure_code text, p_failure_sha256 bytea, p_retryable boolean, p_provider_reference text, p_finished_at timestamp with time zone) RETURNS TABLE(state text, effect_receipt_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_tenant_id uuid;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_attempt analytics_dashboard_export_platform_attempts%ROWTYPE;
    v_job_state text;
    v_receipt_id uuid;
    v_outcome text;
    v_domain_state text;
    v_quota_state text;
    v_exact boolean;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR p_lease_owner IS NULL OR
       (p_effect_id IS NULL) IS DISTINCT FROM
           (p_effect_request_sha256 IS NULL) OR
       (p_effect_id IS NOT NULL AND
        (pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
         pg_catalog.octet_length(p_effect_request_sha256) IS DISTINCT FROM 32)) OR
       p_failure_class IS NULL OR
       p_failure_class NOT IN ('transient','permanent','conflict','cancelled') OR
       p_failure_code IS NULL OR p_failure_code !~ '^[A-Z][A-Z0-9_]{1,63}$' OR
       pg_catalog.octet_length(p_failure_sha256) IS DISTINCT FROM 32 OR
       p_retryable IS NULL OR
       (p_retryable AND p_failure_class NOT IN ('transient','conflict')) OR
       (p_failure_class='cancelled' AND p_retryable) OR
       (p_provider_reference IS NOT NULL AND
        pg_catalog.octet_length(p_provider_reference) NOT BETWEEN 1 AND 512) OR
       p_finished_at IS NULL OR NOT pg_catalog.isfinite(p_finished_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export finish scope is invalid';
    END IF;
    SELECT finish.job_state,finish.effect_receipt_id
    INTO v_job_state,v_receipt_id
    FROM platform.platform_async_analytics_dashboard_export_finish_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_attempt_generation,
        p_lease_owner,p_failure_class,p_failure_code,p_failure_sha256,
        p_retryable,p_provider_reference,p_finished_at
    ) AS finish;
    v_outcome:=CASE v_job_state WHEN 'queued' THEN 'requeued'
        WHEN 'dead' THEN 'dead' WHEN 'cancelled' THEN 'cancelled' END;
    v_domain_state:=CASE v_job_state WHEN 'queued' THEN 'queued'
        WHEN 'dead' THEN 'failed' WHEN 'cancelled' THEN 'cancelled' END;
    v_quota_state:=CASE WHEN v_job_state='queued' THEN 'none' ELSE 'released' END;
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id FOR UPDATE;
    SELECT attempt.* INTO v_attempt
    FROM analytics_dashboard_export_platform_attempts AS attempt
    WHERE attempt.export_id=p_export_id
      AND attempt.attempt_generation=p_attempt_generation
      AND attempt.platform_attempt_id=p_attempt_id
      AND attempt.job_id=p_job_id AND attempt.lease_owner=p_lease_owner
    FOR UPDATE;
    IF v_export.export_id IS NULL OR v_attempt.export_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export finish attempt is stale';
    END IF;
    IF v_attempt.outcome IN ('requeued','dead','cancelled') THEN
        IF v_outcome IS NULL OR v_attempt.outcome IS DISTINCT FROM v_outcome OR
           v_attempt.platform_effect_receipt_id IS DISTINCT FROM v_receipt_id OR
           v_attempt.platform_effect_id IS DISTINCT FROM p_effect_id OR
           v_attempt.platform_effect_request_sha256 IS DISTINCT FROM
                p_effect_request_sha256 OR
           v_attempt.failure_class IS DISTINCT FROM p_failure_class OR
           v_attempt.failure_code IS DISTINCT FROM p_failure_code OR
           v_attempt.failure_sha256 IS DISTINCT FROM p_failure_sha256 OR
           v_attempt.finished_at IS DISTINCT FROM p_finished_at OR
           v_export.state IS DISTINCT FROM v_domain_state OR
           v_export.quota_state IS DISTINCT FROM v_quota_state OR
           v_export.platform_attempt_id IS NOT NULL OR
           v_export.platform_effect_id IS NOT NULL OR
           v_export.platform_effect_request_sha256 IS NOT NULL OR
           v_export.effect_started_at IS NOT NULL OR
           v_export.lease_owner IS NOT NULL OR v_export.lease_until IS NOT NULL OR
           v_export.updated_at IS DISTINCT FROM p_finished_at OR
           v_export.failure_code IS DISTINCT FROM
               (CASE WHEN v_job_state='dead' THEN p_failure_code END) THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export finish replay differs';
        END IF;
        IF v_attempt.platform_effect_id IS NOT NULL THEN
            SELECT receipt.outcome IS NOT DISTINCT FROM v_outcome AND
                   receipt.provider_request_id IS NOT DISTINCT FROM
                       p_provider_reference AND
                   receipt.completed_at IS NOT DISTINCT FROM p_finished_at AND
                   receipt.platform_effect_receipt_id IS NOT DISTINCT FROM
                       v_receipt_id AND
                   receipt.platform_effect_result_sha256 IS NULL INTO v_exact
            FROM analytics_dashboard_export_attempt_receipts AS receipt
            WHERE receipt.export_id=p_export_id
              AND receipt.attempt_generation=p_attempt_generation FOR UPDATE;
            IF NOT COALESCE(v_exact,false) THEN
                RAISE EXCEPTION USING ERRCODE='P6048',
                    MESSAGE='Analytics dashboard export finish receipt differs';
            END IF;
        END IF;
        state:=v_export.state;effect_receipt_id:=v_receipt_id;
        RETURN NEXT;RETURN;
    END IF;
    IF v_attempt.outcome IS DISTINCT FROM 'running' OR
       v_export.state IS DISTINCT FROM 'running' OR
       v_export.quota_state IS DISTINCT FROM 'held' OR
       v_export.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
       v_export.attempt_generation IS DISTINCT FROM p_attempt_generation OR
       v_export.lease_owner IS DISTINCT FROM p_lease_owner OR
       v_export.platform_effect_id IS DISTINCT FROM p_effect_id OR
       v_export.platform_effect_request_sha256 IS DISTINCT FROM
            p_effect_request_sha256 OR
       ((v_export.effect_started_at IS NULL) IS DISTINCT FROM
            (p_effect_id IS NULL)) OR
       p_finished_at<=v_export.updated_at OR
       (v_export.effect_started_at IS NOT NULL AND
        p_failure_class='cancelled') OR
       (p_failure_class='cancelled' AND
        v_export.cancellation_requested_at IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export finish lease is stale';
    END IF;
    IF v_outcome IS NULL OR
       (v_export.effect_started_at IS NULL AND v_receipt_id IS NOT NULL) OR
       (v_export.effect_started_at IS NOT NULL AND v_receipt_id IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export finish result is invalid';
    END IF;
    IF v_export.effect_started_at IS NOT NULL THEN
        UPDATE analytics_dashboard_export_attempt_receipts
        SET outcome=v_outcome,provider_request_id=p_provider_reference,
            completed_at=p_finished_at,
            platform_effect_receipt_id=v_receipt_id,
            platform_effect_result_sha256=NULL
        WHERE export_id=p_export_id
          AND attempt_generation=p_attempt_generation AND outcome='started';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export failure receipt changed';
        END IF;
    END IF;
    UPDATE analytics_dashboard_export_platform_attempts
    SET outcome=v_outcome,platform_effect_receipt_id=v_receipt_id,
        platform_effect_result_sha256=NULL,failure_class=p_failure_class,
        failure_code=p_failure_code,failure_sha256=p_failure_sha256,
        finished_at=p_finished_at
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation AND outcome='running';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export finish attempt changed';
    END IF;
    UPDATE analytics_dashboard_exports
    SET state=v_domain_state,quota_state=v_quota_state,
        failure_code=CASE WHEN v_job_state='dead' THEN p_failure_code END,
        lease_owner=NULL,lease_until=NULL,platform_attempt_id=NULL,
        platform_effect_id=NULL,platform_effect_request_sha256=NULL,
        effect_started_at=NULL,object_key=NULL,object_version=NULL,key_id=NULL,
        wrapped_dek=NULL,wrap_nonce=NULL,header_sha256=NULL,
        ciphertext_sha256=NULL,plaintext_sha256=NULL,ciphertext_bytes=NULL,
        plaintext_bytes=NULL,row_count=NULL,filename=NULL,content_type=NULL,
        provider_request_id=NULL,row_revision=row_revision+1,
        updated_at=p_finished_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    state:=v_domain_state;effect_receipt_id:=v_receipt_id;
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_platform_finish_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_failure_class text, p_failure_code text, p_failure_sha256 bytea, p_retryable boolean, p_provider_reference text, p_finished_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_platform_spool_active_v1(name, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_platform_spool_active_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_attempt_generation bigint, p_lease_owner uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_attempt analytics_dashboard_export_platform_attempts%ROWTYPE;
    v_state text;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR p_lease_owner IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export spool scope is invalid';
    END IF;
    v_state:=platform.platform_async_analytics_dashboard_export_spool_state_v1(
        p_tenant_id,p_export_id,p_attempt_generation,p_lease_owner);
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id FOR SHARE;
    SELECT attempt.* INTO v_attempt
    FROM analytics_dashboard_export_platform_attempts AS attempt
    WHERE attempt.export_id=p_export_id
      AND attempt.attempt_generation=p_attempt_generation
      AND attempt.lease_owner=p_lease_owner FOR SHARE;
    IF v_export.export_id IS NULL OR v_attempt.export_id IS NULL THEN
        RETURN false;
    END IF;
    IF v_state IS NOT DISTINCT FROM 'running' THEN
        RETURN v_attempt.outcome IS NOT DISTINCT FROM 'running' AND
            v_export.state IS NOT DISTINCT FROM 'running' AND
            v_export.quota_state IS NOT DISTINCT FROM 'held' AND
            v_export.platform_attempt_id IS NOT DISTINCT FROM
                v_attempt.platform_attempt_id AND
            v_export.lease_owner IS NOT DISTINCT FROM p_lease_owner;
    ELSIF v_state IS NOT DISTINCT FROM 'outcome_unknown' THEN
        RETURN v_attempt.outcome IS NOT DISTINCT FROM 'unknown' AND
            v_attempt.resolution_receipt_id IS NULL AND
            v_export.state IS NOT DISTINCT FROM 'running' AND
            v_export.quota_state IS NOT DISTINCT FROM 'held' AND
            v_export.platform_attempt_id IS NOT DISTINCT FROM
                v_attempt.platform_attempt_id AND
            v_export.lease_owner IS NULL;
    ELSIF v_state IS NOT DISTINCT FROM 'inactive' THEN
        RETURN false;
    END IF;
    RAISE EXCEPTION USING ERRCODE='P6048',
        MESSAGE='Analytics dashboard export spool state is invalid';
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_platform_spool_active_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_attempt_generation bigint, p_lease_owner uuid) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_platform_succeed_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, uuid, bytea, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_platform_succeed_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_effect_receipt_id uuid, p_effect_result_sha256 bytea, p_object_version text, p_provider_request_id text, p_uploaded_at timestamp with time zone, p_completed_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_attempt analytics_dashboard_export_platform_attempts%ROWTYPE;
    v_exact boolean;
    v_ciphertext_bytes bigint;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_receipt_id) IS DISTINCT FROM 7 OR
       p_attempt_generation IS NULL OR p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.uuid_extract_version(p_lease_owner) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_effect_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_effect_result_sha256) IS DISTINCT FROM 32 OR
       COALESCE(pg_catalog.octet_length(p_object_version),0) NOT BETWEEN 1 AND 512 OR
       COALESCE(pg_catalog.octet_length(p_provider_request_id),0) NOT BETWEEN 1 AND 512 OR
       p_uploaded_at IS NULL OR NOT pg_catalog.isfinite(p_uploaded_at) OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       p_completed_at<p_uploaded_at THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export success scope is invalid';
    END IF;
    SELECT item.ciphertext_bytes INTO v_ciphertext_bytes
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id;
    IF NOT FOUND OR v_ciphertext_bytes IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export success attempt is stale';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_succeed_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_attempt_generation,
        p_lease_owner,p_effect_id,p_effect_request_sha256,p_effect_receipt_id,
        p_effect_result_sha256,p_provider_request_id,
        v_ciphertext_bytes,p_completed_at);
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id FOR UPDATE;
    SELECT attempt.* INTO v_attempt
    FROM analytics_dashboard_export_platform_attempts AS attempt
    WHERE attempt.export_id=p_export_id
      AND attempt.attempt_generation=p_attempt_generation
      AND attempt.platform_attempt_id=p_attempt_id
      AND attempt.job_id=p_job_id AND attempt.lease_owner=p_lease_owner
    FOR UPDATE;
    IF v_export.export_id IS NULL OR v_attempt.export_id IS NULL OR
       v_export.ciphertext_bytes IS DISTINCT FROM v_ciphertext_bytes THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export success attempt is stale';
    END IF;
    IF v_attempt.outcome='ready' THEN
        SELECT receipt.platform_attempt_id IS NOT DISTINCT FROM p_attempt_id AND
               receipt.platform_effect_id IS NOT DISTINCT FROM p_effect_id AND
               receipt.platform_effect_request_sha256 IS NOT DISTINCT FROM
                   p_effect_request_sha256 AND
               receipt.platform_effect_receipt_id IS NOT DISTINCT FROM
                   p_effect_receipt_id AND
               receipt.platform_effect_result_sha256 IS NOT DISTINCT FROM
                   p_effect_result_sha256 AND
               receipt.object_version IS NOT DISTINCT FROM p_object_version AND
               receipt.provider_request_id IS NOT DISTINCT FROM
                   p_provider_request_id AND
               receipt.uploaded_at IS NOT DISTINCT FROM p_uploaded_at AND
               receipt.completed_at IS NOT DISTINCT FROM p_completed_at INTO v_exact
        FROM analytics_dashboard_export_attempt_receipts AS receipt
        WHERE receipt.export_id=p_export_id
          AND receipt.attempt_generation=p_attempt_generation FOR UPDATE;
        IF v_export.state IS DISTINCT FROM 'ready' OR
           v_export.quota_state IS DISTINCT FROM 'used' OR
           v_export.object_version IS DISTINCT FROM p_object_version OR
           v_export.provider_request_id IS DISTINCT FROM p_provider_request_id OR
           v_export.ready_at IS DISTINCT FROM p_completed_at OR
           v_export.updated_at IS DISTINCT FROM p_completed_at OR
           v_export.lease_owner IS NOT NULL OR v_export.lease_until IS NOT NULL OR
           v_export.platform_attempt_id IS NOT NULL OR
           v_export.platform_effect_id IS NOT NULL OR
           v_export.platform_effect_request_sha256 IS NOT NULL OR
           v_attempt.platform_effect_id IS DISTINCT FROM p_effect_id OR
           v_attempt.platform_effect_request_sha256 IS DISTINCT FROM
               p_effect_request_sha256 OR
           v_attempt.platform_effect_receipt_id IS DISTINCT FROM
               p_effect_receipt_id OR
           v_attempt.platform_effect_result_sha256 IS DISTINCT FROM
               p_effect_result_sha256 OR
           v_attempt.uploaded_at IS DISTINCT FROM p_uploaded_at OR
           v_attempt.finished_at IS DISTINCT FROM p_completed_at OR
           NOT COALESCE(v_exact,false) THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export success replay differs';
        END IF;
        RETURN 'ready';
    END IF;
    IF v_attempt.outcome IS DISTINCT FROM 'running' OR
       v_export.state IS DISTINCT FROM 'running' OR
       v_export.quota_state IS DISTINCT FROM 'held' OR
       v_export.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
       v_export.platform_effect_id IS DISTINCT FROM p_effect_id OR
       v_export.platform_effect_request_sha256 IS DISTINCT FROM
           p_effect_request_sha256 OR
       v_export.attempt_generation IS DISTINCT FROM p_attempt_generation OR
       v_export.lease_owner IS DISTINCT FROM p_lease_owner OR
       v_export.effect_started_at IS NULL OR
       p_uploaded_at<v_export.effect_started_at OR
       v_export.cancellation_requested_at IS NOT NULL OR
       v_export.expires_at<=p_completed_at OR
       p_completed_at<=v_export.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export success lease is stale';
    END IF;
    UPDATE analytics_dashboard_export_attempt_receipts
    SET outcome='ready',object_version=p_object_version,
        provider_request_id=p_provider_request_id,uploaded_at=p_uploaded_at,
        completed_at=p_completed_at,
        platform_effect_receipt_id=p_effect_receipt_id,
        platform_effect_result_sha256=p_effect_result_sha256
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation AND outcome='started';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export success receipt changed';
    END IF;
    UPDATE analytics_dashboard_export_platform_attempts
    SET outcome='ready',platform_effect_receipt_id=p_effect_receipt_id,
        platform_effect_result_sha256=p_effect_result_sha256,
        uploaded_at=p_uploaded_at,finished_at=p_completed_at
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation AND outcome='running';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export success attempt changed';
    END IF;
    UPDATE analytics_dashboard_exports
    SET state='ready',quota_state='used',object_version=p_object_version,
        provider_request_id=p_provider_request_id,ready_at=p_completed_at,
        failure_code=NULL,lease_owner=NULL,lease_until=NULL,
        platform_attempt_id=NULL,platform_effect_id=NULL,
        platform_effect_request_sha256=NULL,row_revision=row_revision+1,
        updated_at=p_completed_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN 'ready';
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_platform_succeed_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_effect_receipt_id uuid, p_effect_result_sha256 bytea, p_object_version text, p_provider_request_id text, p_uploaded_at timestamp with time zone, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_platform_unknown_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_platform_unknown_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_attempt analytics_dashboard_export_platform_attempts%ROWTYPE;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR p_lease_owner IS NULL OR
       pg_catalog.octet_length(p_effect_request_sha256) IS DISTINCT FROM 32 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export unknown scope is invalid';
    END IF;
    PERFORM platform.platform_async_analytics_dashboard_export_unknown_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_attempt_generation,
        p_lease_owner,p_effect_id,p_effect_request_sha256,p_observed_at);
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id FOR UPDATE;
    SELECT attempt.* INTO v_attempt
    FROM analytics_dashboard_export_platform_attempts AS attempt
    WHERE attempt.export_id=p_export_id
      AND attempt.attempt_generation=p_attempt_generation
      AND attempt.platform_attempt_id=p_attempt_id
      AND attempt.job_id=p_job_id AND attempt.lease_owner=p_lease_owner
    FOR UPDATE;
    IF v_export.export_id IS NULL OR v_attempt.export_id IS NULL OR
       v_attempt.platform_effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.platform_effect_request_sha256 IS DISTINCT FROM
           p_effect_request_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export unknown attempt is stale';
    END IF;
    IF v_attempt.outcome='unknown' THEN
        IF v_export.state IS DISTINCT FROM 'running' OR
           v_export.quota_state IS DISTINCT FROM 'held' OR
           v_export.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
           v_export.platform_effect_id IS DISTINCT FROM p_effect_id OR
           v_export.platform_effect_request_sha256 IS DISTINCT FROM
               p_effect_request_sha256 OR
           v_export.attempt_generation IS DISTINCT FROM p_attempt_generation OR
           v_export.lease_owner IS NOT NULL OR
           v_export.lease_until IS NOT NULL OR
           v_export.failure_code IS DISTINCT FROM 'ARTIFACT_OUTCOME_UNKNOWN' OR
           v_export.updated_at IS DISTINCT FROM p_observed_at OR
           v_attempt.failure_class IS NOT NULL OR
           v_attempt.failure_code IS DISTINCT FROM 'JOB_OUTCOME_UNKNOWN' OR
           v_attempt.failure_sha256 IS NOT NULL OR
           v_attempt.finished_at IS DISTINCT FROM p_observed_at THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export unknown replay differs';
        END IF;
        PERFORM 1 FROM analytics_dashboard_export_attempt_receipts AS receipt
        WHERE receipt.export_id=p_export_id
          AND receipt.attempt_generation=p_attempt_generation
          AND receipt.outcome='unknown'
          AND receipt.platform_attempt_id=p_attempt_id
          AND receipt.platform_effect_id=p_effect_id
          AND receipt.platform_effect_request_sha256=p_effect_request_sha256
          AND receipt.completed_at=p_observed_at FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export unknown receipt differs';
        END IF;
        RETURN true;
    END IF;
    IF v_attempt.outcome IS DISTINCT FROM 'running' OR
       v_export.state IS DISTINCT FROM 'running' OR
       v_export.quota_state IS DISTINCT FROM 'held' OR
       v_export.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
       v_export.platform_effect_id IS DISTINCT FROM p_effect_id OR
       v_export.platform_effect_request_sha256 IS DISTINCT FROM
           p_effect_request_sha256 OR
       v_export.attempt_generation IS DISTINCT FROM p_attempt_generation OR
       v_export.lease_owner IS DISTINCT FROM p_lease_owner OR
       v_export.effect_started_at IS NULL OR
       p_observed_at<=v_export.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='Analytics dashboard export unknown lease is stale';
    END IF;
    UPDATE analytics_dashboard_export_attempt_receipts
    SET outcome='unknown',completed_at=p_observed_at
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation AND outcome='started';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export unknown receipt changed';
    END IF;
    UPDATE analytics_dashboard_export_platform_attempts
    SET outcome='unknown',failure_code='JOB_OUTCOME_UNKNOWN',
        finished_at=p_observed_at
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation AND outcome='running';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export unknown attempt changed';
    END IF;
    UPDATE analytics_dashboard_exports
    SET failure_code='ARTIFACT_OUTCOME_UNKNOWN',lease_owner=NULL,
        lease_until=NULL,row_revision=row_revision+1,updated_at=p_observed_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_platform_unknown_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_restart_missing_v1(name, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_restart_missing_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_export analytics_dashboard_exports%ROWTYPE;
BEGIN
    IF p_attempt_generation NOT BETWEEN 1 AND 3 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export restart input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT item.* INTO v_export
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.state='running'
      AND item.lease_owner=p_lease_owner
      AND item.attempt_generation=p_attempt_generation
      AND item.effect_started_at IS NOT NULL AND item.quota_state='held'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export restart changed';
    END IF;
    UPDATE analytics_dashboard_export_attempt_receipts
    SET outcome='missing',completed_at=p_observed_at
    WHERE export_id=p_export_id
      AND attempt_generation=p_attempt_generation AND outcome='started';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics dashboard export missing receipt changed';
    END IF;
    UPDATE platform.artifact_quota_counters
    SET reserved_ciphertext_bytes=reserved_ciphertext_bytes-2147483648,
        revision=revision+1,updated_at=p_observed_at
    WHERE tenant_id=v_export.tenant_id
      AND reserved_ciphertext_bytes>=2147483648;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6105',
            MESSAGE='analytics dashboard export restart quota changed';
    END IF;
    UPDATE analytics_dashboard_exports
    SET state=CASE WHEN attempt_generation>=3 THEN 'failed' ELSE 'queued' END,
        quota_state=CASE WHEN attempt_generation>=3
            THEN 'released' ELSE 'none' END,
        failure_code=CASE WHEN attempt_generation>=3
            THEN 'MAX_ATTEMPTS' ELSE NULL END,
        row_revision=row_revision+1,lease_owner=NULL,lease_until=NULL,
        effect_started_at=NULL,object_key=NULL,object_version=NULL,
        key_id=NULL,wrapped_dek=NULL,wrap_nonce=NULL,header_sha256=NULL,
        ciphertext_sha256=NULL,plaintext_sha256=NULL,
        ciphertext_bytes=NULL,plaintext_bytes=NULL,row_count=NULL,
        filename=NULL,content_type=NULL,provider_request_id=NULL,
        updated_at=p_observed_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_restart_missing_v1(p_scope_schema name, p_export_id uuid, p_lease_owner uuid, p_attempt_generation bigint, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_snapshot_v1(name, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_snapshot_v1(p_scope_schema name, p_actor_id uuid, p_dashboard_id uuid, p_export_id uuid, p_observed_at timestamp with time zone) RETURNS TABLE(export_id uuid, dashboard_id uuid, dashboard_version_id uuid, job_id uuid, effective_state text, stored_state text, format text, filename text, content_type text, failure_code text, row_count bigint, plaintext_bytes bigint, cancellation_requested boolean, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       p_observed_at IS NULL OR NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export read input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT item.export_id,item.dashboard_id,item.dashboard_version_id,item.job_id,
           CASE WHEN item.state='ready' AND item.expires_at<=p_observed_at
                THEN 'expired' ELSE item.state END,
           item.state,item.format,COALESCE(item.filename,''),
           COALESCE(item.content_type,''),COALESCE(item.failure_code,''),
           COALESCE(item.row_count,0),COALESCE(item.plaintext_bytes,0),
           item.cancellation_requested_at IS NOT NULL,
           item.created_at,item.updated_at,item.expires_at
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id
      AND item.dashboard_id=p_dashboard_id
      AND analytics_dashboard_export_access_v1(
          p_actor_id,item.dashboard_id,item.dashboard_version_id);
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics dashboard export was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_snapshot_v1(p_scope_schema name, p_actor_id uuid, p_dashboard_id uuid, p_export_id uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_submit_v1(name, uuid, uuid, text, bytea, uuid, uuid, uuid, text, bytea, bigint, bigint, bigint, bigint, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_submit_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_export_id uuid, p_job_id uuid, p_dashboard_id uuid, p_format text, p_parameters bytea, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_maximum_rows bigint, p_maximum_plaintext_bytes bigint, p_occurred_at timestamp with time zone, p_expires_at timestamp with time zone) RETURNS TABLE(export_id uuid, dashboard_id uuid, dashboard_version_id uuid, job_id uuid, effective_state text, stored_state text, format text, filename text, content_type text, failure_code text, row_count bigint, plaintext_bytes bigint, cancellation_requested boolean, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_dashboard_exports%ROWTYPE;
    v_version analytics_dashboard_versions%ROWTYPE;
    v_tenant_id uuid;
    v_widgets jsonb;
    v_widget_count integer;
    v_pin_sha256 bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 16 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_format NOT IN ('csv','xlsx','pdf') OR
       pg_catalog.octet_length(p_parameters) NOT BETWEEN 2 AND 65536 OR
       NOT pg_catalog.pg_input_is_valid(
           pg_catalog.convert_from(p_parameters,'UTF8'),'jsonb') OR
       p_token_version<1 OR p_authorization_version<1 OR
       p_authorization_clock<1 OR p_maximum_rows NOT BETWEEN 1 AND 100000 OR
       p_maximum_plaintext_bytes NOT BETWEEN 1 AND 67108864 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       p_expires_at IS NULL OR NOT pg_catalog.isfinite(p_expires_at) OR
       p_expires_at<=p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export submit input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton
      AND identity_row.schema_name=pg_catalog.current_schema();
    INSERT INTO platform.artifact_quota_counters(tenant_id)
    VALUES (v_tenant_id) ON CONFLICT (tenant_id) DO NOTHING;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:export:'||p_actor_id::text||':'||
        p_idempotency_key,6100));
    SELECT item.* INTO v_existing
    FROM analytics_dashboard_exports AS item
    WHERE item.actor_id=p_actor_id
      AND item.idempotency_key=p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.tenant_id IS DISTINCT FROM v_tenant_id THEN
            RAISE EXCEPTION USING ERRCODE='P6103',
                MESSAGE='analytics dashboard export replay differs';
        END IF;
        RETURN QUERY
        SELECT result.*,true
        FROM analytics_dashboard_export_snapshot_v1(
            p_scope_schema,p_actor_id,v_existing.dashboard_id,
            v_existing.export_id,p_occurred_at) AS result;
        RETURN;
    END IF;
    SELECT version_row.* INTO v_version
    FROM analytics_dashboards AS root
    JOIN analytics_dashboard_versions AS version_row
      ON version_row.dashboard_id=root.id
    WHERE root.id=p_dashboard_id
      AND root.lifecycle_state='active'
      AND version_row.version_state='published'
    ORDER BY version_row.version_no DESC
    LIMIT 1
    FOR SHARE OF root,version_row;
    IF NOT FOUND OR NOT analytics_dashboard_export_access_v1(
        p_actor_id,p_dashboard_id,v_version.id) THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics published dashboard was not found';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'widget_id',widget.widget_id,
               'position',widget.position,
               'query_version_id',widget.query_version_id,
               'parameters',pg_catalog.encode(widget.parameter_document,'hex'),
               'output',pg_catalog.encode(widget.output_document,'hex')
           ) ORDER BY widget.position),'[]'::jsonb),
           pg_catalog.count(*)::integer
    INTO v_widgets,v_widget_count
    FROM analytics_dashboard_widgets AS widget
    WHERE widget.dashboard_version_id=v_version.id;
    IF v_widget_count NOT BETWEEN 1 AND 30 THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics dashboard export widgets are unavailable';
    END IF;
    v_pin_sha256:=pg_catalog.sha256(pg_catalog.convert_to(
        pg_catalog.jsonb_build_object(
            'dashboard_id',p_dashboard_id,
            'dashboard_version_id',v_version.id,
            'dashboard_manifest_sha256',
                pg_catalog.encode(v_version.manifest_sha256,'hex'),
            'format',p_format,
            'parameters',pg_catalog.encode(p_parameters,'hex'),
            'widgets',v_widgets,
            'maximum_rows',p_maximum_rows,
            'maximum_plaintext_bytes',p_maximum_plaintext_bytes
        )::text,'UTF8'));
    INSERT INTO analytics_dashboard_exports (
        export_id,tenant_id,dashboard_id,dashboard_version_id,job_id,actor_id,
        format,state,row_revision,idempotency_key,request_sha256,
        token_version,authorization_version,authorization_clock,
        dashboard_manifest_sha256,pin_sha256,parameters_document,
        parameters_sha256,pinned_widgets,widget_count,maximum_rows,
        maximum_plaintext_bytes,quota_state,created_at,updated_at,expires_at
    ) VALUES (
        p_export_id,v_tenant_id,p_dashboard_id,v_version.id,p_job_id,p_actor_id,
        p_format,'queued',1,p_idempotency_key,p_request_sha256,
        p_token_version,p_authorization_version,p_authorization_clock,
        v_version.manifest_sha256,v_pin_sha256,p_parameters,
        pg_catalog.sha256(p_parameters),v_widgets,v_widget_count,
        p_maximum_rows,p_maximum_plaintext_bytes,'none',
        p_occurred_at,p_occurred_at,p_expires_at
    );
    RETURN QUERY
    SELECT result.*,false
    FROM analytics_dashboard_export_snapshot_v1(
        p_scope_schema,p_actor_id,p_dashboard_id,p_export_id,p_occurred_at) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_submit_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_export_id uuid, p_job_id uuid, p_dashboard_id uuid, p_format text, p_parameters bytea, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_maximum_rows bigint, p_maximum_plaintext_bytes bigint, p_occurred_at timestamp with time zone, p_expires_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_submit_v2(name, uuid, uuid, text, bytea, uuid, uuid, uuid, uuid, text, bytea, bigint, bigint, bigint, bigint, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_submit_v2(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_export_id uuid, p_job_id uuid, p_expiry_job_id uuid, p_dashboard_id uuid, p_format text, p_parameters bytea, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_maximum_rows bigint, p_maximum_plaintext_bytes bigint, p_occurred_at timestamp with time zone, p_expires_at timestamp with time zone) RETURNS TABLE(export_id uuid, dashboard_id uuid, dashboard_version_id uuid, job_id uuid, effective_state text, stored_state text, format text, filename text, content_type text, failure_code text, row_count bigint, plaintext_bytes bigint, cancellation_requested boolean, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export_id uuid;
    v_replayed boolean;
    v_existing_expiry_job_id uuid;
BEGIN
    IF pg_catalog.uuid_extract_version(p_expiry_job_id) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics dashboard export expiry job is invalid';
    END IF;
    SELECT submitted.export_id,submitted.replayed
    INTO v_export_id,v_replayed
    FROM analytics_dashboard_export_submit_v1(
        p_scope_schema,p_operation_id,p_actor_id,p_idempotency_key,
        p_request_sha256,p_export_id,p_job_id,p_dashboard_id,p_format,
        p_parameters,p_token_version,p_authorization_version,
        p_authorization_clock,p_maximum_rows,p_maximum_plaintext_bytes,
        p_occurred_at,p_expires_at
    ) AS submitted;
    SELECT item.expiry_job_id INTO v_existing_expiry_job_id
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=v_export_id FOR UPDATE;
    IF v_replayed THEN
        IF v_existing_expiry_job_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6105',
                MESSAGE='analytics dashboard export expiry schedule is missing';
        END IF;
    ELSE
        UPDATE analytics_dashboard_exports
        SET expiry_job_id=p_expiry_job_id,row_revision=row_revision+1,
            updated_at=p_occurred_at
        WHERE analytics_dashboard_exports.export_id=v_export_id
          AND expiry_job_id IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='analytics dashboard export expiry schedule changed';
        END IF;
    END IF;
    RETURN QUERY
    SELECT snapshot.*,v_replayed
    FROM analytics_dashboard_export_snapshot_v1(
        p_scope_schema,p_actor_id,p_dashboard_id,v_export_id,p_occurred_at
    ) AS snapshot;
END;
$$;


