--
-- Name: analytics_dashboard_export_unknown_resolution_digest_v1(text, text, text, text, text, bytea, timestamp with time zone, timestamp with time zone, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_unknown_resolution_digest_v1(p_kind text, p_object_key text, p_object_version text, p_reconcile_request_id text, p_delete_request_id text, p_reconcile_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_delete_verified_at timestamp with time zone, p_resolved_at timestamp with time zone) RETURNS bytea
    LANGUAGE sql IMMUTABLE
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
SELECT pg_catalog.sha256(
    pg_catalog.convert_to('analytics-dashboard-export-unknown-resolution-v1','UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(p_kind)::bigint)||
    pg_catalog.convert_to(p_kind,'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(p_object_key)::bigint)||
    pg_catalog.convert_to(p_object_key,'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(COALESCE(p_object_version,''))::bigint)||
    pg_catalog.convert_to(COALESCE(p_object_version,''),'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(p_reconcile_request_id)::bigint)||
    pg_catalog.convert_to(p_reconcile_request_id,'UTF8')||
    pg_catalog.int8send(pg_catalog.octet_length(COALESCE(p_delete_request_id,''))::bigint)||
    pg_catalog.convert_to(COALESCE(p_delete_request_id,''),'UTF8')||
    p_reconcile_sha256||
    pg_catalog.int8send(COALESCE((EXTRACT(EPOCH FROM p_upload_completed_at)*1000000)::bigint,0))||
    pg_catalog.int8send((EXTRACT(EPOCH FROM p_reconcile_verified_at)*1000000)::bigint)||
    COALESCE(p_delete_response_sha256,pg_catalog.decode(pg_catalog.repeat('00',32),'hex'))||
    p_absence_sha256||
    pg_catalog.int8send(COALESCE((EXTRACT(EPOCH FROM p_delete_verified_at)*1000000)::bigint,0))||
    pg_catalog.int8send((EXTRACT(EPOCH FROM p_resolved_at)*1000000)::bigint)
);
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_unknown_resolution_digest_v1(p_kind text, p_object_key text, p_object_version text, p_reconcile_request_id text, p_delete_request_id text, p_reconcile_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_delete_verified_at timestamp with time zone, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_unknown_resolution_evidence_valid_v1(text, bytea, text, text, text, bytea, timestamp with time zone, timestamp with time zone, text, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_unknown_resolution_evidence_valid_v1(p_kind text, p_summary_sha256 bytea, p_object_key text, p_object_version text, p_reconcile_request_id text, p_reconcile_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_delete_verified_at timestamp with time zone, p_resolved_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
SELECT p_kind IN ('deleted','absent')
   AND pg_catalog.octet_length(p_summary_sha256)=32
   AND p_summary_sha256 IS DISTINCT FROM
       pg_catalog.decode(pg_catalog.repeat('00',32),'hex')
   AND pg_catalog.octet_length(p_object_key) BETWEEN 1 AND 1024
   AND pg_catalog.octet_length(p_reconcile_request_id) BETWEEN 1 AND 512
   AND pg_catalog.octet_length(p_reconcile_sha256)=32
   AND p_reconcile_sha256 IS DISTINCT FROM
       pg_catalog.decode(pg_catalog.repeat('00',32),'hex')
   AND pg_catalog.octet_length(p_absence_sha256)=32
   AND p_absence_sha256 IS DISTINCT FROM
       pg_catalog.decode(pg_catalog.repeat('00',32),'hex')
   AND pg_catalog.isfinite(p_reconcile_verified_at)
   AND pg_catalog.isfinite(p_resolved_at) AND p_reconcile_verified_at<=p_resolved_at
   AND ((p_kind='absent' AND p_object_version IS NULL
        AND p_upload_completed_at IS NULL AND p_delete_request_id IS NULL
        AND p_delete_response_sha256 IS NULL AND p_delete_verified_at IS NULL
        AND p_absence_sha256=p_reconcile_sha256) OR
       (p_kind='deleted' AND pg_catalog.octet_length(p_object_version) BETWEEN 1 AND 512
        AND pg_catalog.octet_length(p_delete_request_id) BETWEEN 1 AND 512
        AND pg_catalog.octet_length(p_delete_response_sha256)=32
        AND p_delete_response_sha256 IS DISTINCT FROM
            pg_catalog.decode(pg_catalog.repeat('00',32),'hex')
        AND pg_catalog.isfinite(p_upload_completed_at)
        AND pg_catalog.isfinite(p_delete_verified_at)
        AND p_upload_completed_at<=p_reconcile_verified_at
        AND p_reconcile_verified_at<=p_delete_verified_at
        AND p_delete_verified_at<=p_resolved_at))
   AND p_summary_sha256=analytics_dashboard_export_unknown_resolution_digest_v1(
        p_kind,p_object_key,p_object_version,p_reconcile_request_id,
        p_delete_request_id,p_reconcile_sha256,p_upload_completed_at,
        p_reconcile_verified_at,p_delete_response_sha256,p_absence_sha256,
        p_delete_verified_at,p_resolved_at);
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_unknown_resolution_evidence_valid_v1(p_kind text, p_summary_sha256 bytea, p_object_key text, p_object_version text, p_reconcile_request_id text, p_reconcile_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_delete_verified_at timestamp with time zone, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_unknown_resolve_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea, bigint, uuid, uuid, text, bytea, text, text, text, bytea, timestamp with time zone, timestamp with time zone, text, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_unknown_resolve_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_original_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_cleanup_generation bigint, p_cleanup_lease_owner uuid, p_resolution_receipt_id uuid, p_resolution_kind text, p_resolution_sha256 bytea, p_object_key text, p_object_version text, p_reconcile_provider_request_id text, p_reconcile_evidence_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_provider_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_delete_verified_at timestamp with time zone, p_resolved_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_export analytics_dashboard_exports%ROWTYPE;
    v_attempt analytics_dashboard_export_platform_attempts%ROWTYPE;
    v_resolution analytics_dashboard_export_unknown_resolutions%ROWTYPE;
    v_terminal_state text;
    v_platform boolean;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_resolution_receipt_id) IS DISTINCT FROM 7 OR
       p_resolution_receipt_id IN (
           p_export_id,p_job_id,p_attempt_id,p_original_lease_owner,p_effect_id,
           p_cleanup_lease_owner) OR
       analytics_dashboard_export_unknown_resolution_evidence_valid_v1(
            p_resolution_kind,p_resolution_sha256,p_object_key,p_object_version,
            p_reconcile_provider_request_id,p_reconcile_evidence_sha256,
            p_upload_completed_at,p_reconcile_verified_at,
            p_delete_provider_request_id,p_delete_response_sha256,
            p_absence_sha256,p_delete_verified_at,
            p_resolved_at) IS NOT TRUE THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export unknown resolution scope is invalid';
    END IF;
    v_platform:=platform.platform_async_analytics_dashboard_export_unknown_resolve_v2(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_attempt_generation,
        p_original_lease_owner,p_effect_id,p_effect_request_sha256,
        p_cleanup_generation,p_cleanup_lease_owner,p_resolution_receipt_id,
        p_resolution_kind,p_resolution_sha256,p_resolved_at
    );
    IF NOT v_platform THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export platform resolution is invalid';
    END IF;
    SELECT item.* INTO v_export FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id AND item.tenant_id=p_tenant_id
      AND item.job_id=p_job_id FOR UPDATE;
    SELECT attempt.* INTO v_attempt
    FROM analytics_dashboard_export_platform_attempts AS attempt
    WHERE attempt.export_id=p_export_id
      AND attempt.attempt_generation=p_attempt_generation
      AND attempt.platform_attempt_id=p_attempt_id
      AND attempt.job_id=p_job_id
      AND attempt.lease_owner=p_original_lease_owner FOR UPDATE;
    SELECT resolution.* INTO v_resolution
    FROM analytics_dashboard_export_unknown_resolutions AS resolution
    WHERE resolution.export_id=p_export_id
      AND resolution.attempt_generation=p_attempt_generation FOR SHARE;
    IF FOUND THEN
        IF v_resolution.tenant_id IS DISTINCT FROM p_tenant_id OR
           v_resolution.job_id IS DISTINCT FROM p_job_id OR
           v_resolution.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
           v_resolution.lease_owner IS DISTINCT FROM p_original_lease_owner OR
           v_resolution.platform_effect_id IS DISTINCT FROM p_effect_id OR
           v_resolution.platform_effect_request_sha256 IS DISTINCT FROM p_effect_request_sha256 OR
           v_resolution.cleanup_generation IS DISTINCT FROM p_cleanup_generation OR
           v_resolution.cleanup_lease_owner IS DISTINCT FROM p_cleanup_lease_owner OR
           v_resolution.resolution_receipt_id IS DISTINCT FROM p_resolution_receipt_id OR
           v_resolution.resolution_kind IS DISTINCT FROM p_resolution_kind OR
           v_resolution.resolution_sha256 IS DISTINCT FROM p_resolution_sha256 OR
           v_resolution.object_key IS DISTINCT FROM p_object_key OR
           v_resolution.object_version IS DISTINCT FROM p_object_version OR
           v_resolution.reconcile_provider_request_id IS DISTINCT FROM p_reconcile_provider_request_id OR
           v_resolution.reconcile_evidence_sha256 IS DISTINCT FROM p_reconcile_evidence_sha256 OR
           v_resolution.upload_completed_at IS DISTINCT FROM p_upload_completed_at OR
           v_resolution.reconcile_verified_at IS DISTINCT FROM p_reconcile_verified_at OR
           v_resolution.delete_provider_request_id IS DISTINCT FROM p_delete_provider_request_id OR
           v_resolution.delete_response_sha256 IS DISTINCT FROM p_delete_response_sha256 OR
           v_resolution.absence_sha256 IS DISTINCT FROM p_absence_sha256 OR
           v_resolution.delete_verified_at IS DISTINCT FROM p_delete_verified_at OR
           v_resolution.resolved_at IS DISTINCT FROM p_resolved_at OR
           v_export.state IS DISTINCT FROM v_resolution.terminal_state OR
           v_export.quota_state IS DISTINCT FROM 'released' OR
           v_attempt.resolution_receipt_id IS DISTINCT FROM p_resolution_receipt_id THEN
            RAISE EXCEPTION USING ERRCODE='P6048',
                MESSAGE='Analytics dashboard export resolution replay differs';
        END IF;
        RETURN v_resolution.terminal_state;
    END IF;
    IF v_export.export_id IS NULL OR v_attempt.export_id IS NULL OR
       v_export.state IS DISTINCT FROM 'running' OR
       v_export.quota_state IS DISTINCT FROM 'held' OR
       v_export.platform_attempt_id IS DISTINCT FROM p_attempt_id OR
       v_export.platform_effect_id IS DISTINCT FROM p_effect_id OR
       v_export.platform_effect_request_sha256 IS DISTINCT FROM p_effect_request_sha256 OR
       v_export.lease_owner IS NOT NULL OR
       v_export.failure_code IS DISTINCT FROM 'ARTIFACT_OUTCOME_UNKNOWN' OR
       v_attempt.outcome IS DISTINCT FROM 'unknown' OR
       v_attempt.finished_at IS NULL OR v_attempt.finished_at>=p_resolved_at OR
       p_reconcile_verified_at<v_attempt.finished_at OR
       v_attempt.platform_effect_id IS DISTINCT FROM p_effect_id OR
       v_attempt.platform_effect_request_sha256 IS DISTINCT FROM p_effect_request_sha256 OR
       v_attempt.resolution_receipt_id IS NOT NULL OR
       p_object_key IS DISTINCT FROM v_export.object_key OR
       p_object_key IS DISTINCT FROM (
            SELECT receipt.object_key
            FROM analytics_dashboard_export_attempt_receipts AS receipt
            WHERE receipt.export_id=p_export_id
              AND receipt.attempt_generation=p_attempt_generation
              AND receipt.outcome='unknown'
              AND receipt.platform_attempt_id=p_attempt_id
              AND receipt.platform_effect_id=p_effect_id
              AND receipt.platform_effect_request_sha256=p_effect_request_sha256) OR
       (v_export.object_version IS NOT NULL AND
            p_object_version IS DISTINCT FROM v_export.object_version) OR
       p_resolved_at<v_export.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export resolution evidence differs';
    END IF;
    v_terminal_state:=CASE
        WHEN v_export.cancellation_requested_at IS NOT NULL THEN 'cancelled'
        WHEN v_export.expires_at<=p_resolved_at THEN 'expired'
        ELSE 'failed' END;
    INSERT INTO analytics_dashboard_export_unknown_resolutions(
        tenant_id,export_id,attempt_generation,job_id,platform_attempt_id,
        lease_owner,platform_effect_id,platform_effect_request_sha256,
        resolution_receipt_id,resolution_kind,resolution_sha256,
        object_key,object_version,reconcile_provider_request_id,
        reconcile_evidence_sha256,upload_completed_at,reconcile_verified_at,
        delete_provider_request_id,delete_response_sha256,absence_sha256,
        delete_verified_at,
        terminal_state,quota_released_bytes,resolved_at,
        cleanup_generation,cleanup_lease_owner
    ) VALUES (
        p_tenant_id,p_export_id,p_attempt_generation,p_job_id,p_attempt_id,
        p_original_lease_owner,p_effect_id,p_effect_request_sha256,
        p_resolution_receipt_id,p_resolution_kind,p_resolution_sha256,
        p_object_key,p_object_version,p_reconcile_provider_request_id,
        p_reconcile_evidence_sha256,p_upload_completed_at,p_reconcile_verified_at,
        p_delete_provider_request_id,p_delete_response_sha256,p_absence_sha256,
        p_delete_verified_at,
        v_terminal_state,2147483648,p_resolved_at,
        p_cleanup_generation,p_cleanup_lease_owner
    );
    UPDATE analytics_dashboard_export_platform_attempts
    SET resolution_receipt_id=p_resolution_receipt_id,
        resolution_kind=p_resolution_kind,resolution_sha256=p_resolution_sha256,
        resolved_at=p_resolved_at
    WHERE export_id=p_export_id AND attempt_generation=p_attempt_generation;
    UPDATE analytics_dashboard_exports
    SET state=v_terminal_state,quota_state='released',
        failure_code='ARTIFACT_OUTCOME_UNKNOWN_RESOLVED',
        platform_attempt_id=NULL,platform_effect_id=NULL,
        platform_effect_request_sha256=NULL,effect_started_at=NULL,
        object_key=NULL,object_version=NULL,key_id=NULL,wrapped_dek=NULL,
        wrap_nonce=NULL,header_sha256=NULL,ciphertext_sha256=NULL,
        plaintext_sha256=NULL,ciphertext_bytes=NULL,plaintext_bytes=NULL,
        row_count=NULL,filename=NULL,content_type=NULL,provider_request_id=NULL,
        row_revision=row_revision+1,updated_at=p_resolved_at
    WHERE analytics_dashboard_exports.export_id=p_export_id;
    RETURN v_terminal_state;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_unknown_resolve_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_original_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea, p_cleanup_generation bigint, p_cleanup_lease_owner uuid, p_resolution_receipt_id uuid, p_resolution_kind text, p_resolution_sha256 bytea, p_object_key text, p_object_version text, p_reconcile_provider_request_id text, p_reconcile_evidence_sha256 bytea, p_upload_completed_at timestamp with time zone, p_reconcile_verified_at timestamp with time zone, p_delete_provider_request_id text, p_delete_response_sha256 bytea, p_absence_sha256 bytea, p_delete_verified_at timestamp with time zone, p_resolved_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_unknown_snapshot_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, uuid, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_unknown_snapshot_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea) RETURNS TABLE(format text, object_key text, object_version text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text, provider_request_id text, effect_started_at timestamp with time zone, cancellation_requested boolean, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_tenant_id uuid;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row WHERE identity_row.singleton;
    IF v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       p_attempt_generation NOT BETWEEN 1 AND 3 OR
       pg_catalog.octet_length(p_effect_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.encode(p_effect_request_sha256,'hex')=pg_catalog.repeat('0',64) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics dashboard export unknown snapshot scope is invalid';
    END IF;
    RETURN QUERY
    SELECT item.format,receipt.object_key,item.object_version,receipt.key_id,
           receipt.wrapped_dek,receipt.wrap_nonce,receipt.header_sha256,
           receipt.ciphertext_sha256,receipt.plaintext_sha256,
           receipt.ciphertext_bytes,receipt.plaintext_bytes,receipt.row_count,
           item.content_type,item.filename,item.provider_request_id,
           item.effect_started_at,item.cancellation_requested_at IS NOT NULL,
           item.expires_at
    FROM analytics_dashboard_exports AS item
    JOIN analytics_dashboard_export_platform_attempts AS attempt
      ON attempt.export_id=item.export_id
     AND attempt.attempt_generation=item.attempt_generation
    JOIN analytics_dashboard_export_attempt_receipts AS receipt
      ON receipt.export_id=attempt.export_id
     AND receipt.attempt_generation=attempt.attempt_generation
    WHERE item.tenant_id=p_tenant_id AND item.export_id=p_export_id
      AND item.job_id=p_job_id AND item.state='running'
      AND item.attempt_generation=p_attempt_generation
      AND item.quota_state='held' AND item.platform_attempt_id=p_attempt_id
      AND item.platform_effect_id=p_effect_id
      AND item.platform_effect_request_sha256=p_effect_request_sha256
      AND item.effect_started_at IS NOT NULL
      AND item.lease_owner IS NULL
      AND item.failure_code='ARTIFACT_OUTCOME_UNKNOWN'
      AND attempt.attempt_generation=p_attempt_generation
      AND attempt.job_id=p_job_id AND attempt.platform_attempt_id=p_attempt_id
      AND attempt.lease_owner=p_lease_owner AND attempt.outcome='unknown'
      AND attempt.platform_effect_id=p_effect_id
      AND attempt.platform_effect_request_sha256=p_effect_request_sha256
      AND attempt.resolution_receipt_id IS NULL
      AND receipt.outcome='unknown'
      AND receipt.attempt_generation=p_attempt_generation
      AND receipt.platform_attempt_id=p_attempt_id
      AND receipt.platform_effect_id=p_effect_id
      AND receipt.platform_effect_request_sha256=p_effect_request_sha256
    FOR SHARE OF item,attempt,receipt;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='Analytics dashboard export unknown snapshot differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_unknown_snapshot_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_attempt_generation bigint, p_lease_owner uuid, p_effect_id uuid, p_effect_request_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_export_worker_snapshot_v1(uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_export_worker_snapshot_v1(p_export_id uuid, p_disposition text) RETURNS TABLE(disposition text, state text, actor_id uuid, export_id uuid, dashboard_id uuid, dashboard_version_id uuid, job_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, dashboard_manifest_sha256 bytea, pin_sha256 bytea, format text, parameters_document bytea, pinned_widgets jsonb, maximum_rows bigint, maximum_plaintext_bytes bigint, expires_at timestamp with time zone, attempt_generation bigint, lease_owner uuid, effect_started boolean, object_key text, key_id text, wrapped_dek bytea, wrap_nonce bytea, header_sha256 bytea, ciphertext_sha256 bytea, plaintext_sha256 bytea, ciphertext_bytes bigint, plaintext_bytes bigint, row_count bigint, content_type text, filename text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT p_disposition,item.state,item.actor_id,item.export_id,
           item.dashboard_id,item.dashboard_version_id,item.job_id,
           item.token_version,item.authorization_version,
           item.authorization_clock,item.dashboard_manifest_sha256,
           item.pin_sha256,item.format,item.parameters_document,
           item.pinned_widgets,item.maximum_rows,
           item.maximum_plaintext_bytes,item.expires_at,
           item.attempt_generation,COALESCE(item.lease_owner,
               '00000000-0000-0000-0000-000000000000'::uuid),
           item.effect_started_at IS NOT NULL,COALESCE(item.object_key,''),
           COALESCE(item.key_id,''),COALESCE(item.wrapped_dek,''::bytea),
           COALESCE(item.wrap_nonce,''::bytea),
           COALESCE(item.header_sha256,''::bytea),
           COALESCE(item.ciphertext_sha256,''::bytea),
           COALESCE(item.plaintext_sha256,''::bytea),
           COALESCE(item.ciphertext_bytes,0),
           COALESCE(item.plaintext_bytes,0),COALESCE(item.row_count,0),
           COALESCE(item.content_type,''),COALESCE(item.filename,'')
    FROM analytics_dashboard_exports AS item
    WHERE item.export_id=p_export_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_export_worker_snapshot_v1(p_export_id uuid, p_disposition text) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_get_default_v1(name, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_get_default_v1(p_scope_schema name, p_principal_id uuid, p_surface text) RETURNS TABLE(dashboard_id uuid, version_id uuid, version_no bigint, root_revision bigint, version_revision bigint, lifecycle_state text, version_state text, name text, visibility text, layout_document bytea, layout_sha256 bytea, manifest_sha256 bytea, widgets jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_dashboard_id uuid;
BEGIN
    IF p_principal_id IS NULL OR
       p_principal_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_surface IS NULL OR
       p_surface OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_.-]{0,63}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics dashboard default read input is invalid';
    END IF;

    PERFORM analytics_assert_current_authority_v1(p_scope_schema);

    SELECT preference.dashboard_id
    INTO v_dashboard_id
    FROM analytics_dashboard_preferences AS preference
    WHERE preference.principal_id = p_principal_id
      AND preference.surface = p_surface;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102',
            MESSAGE = 'analytics dashboard default was not found';
    END IF;

    RETURN QUERY
    SELECT *
    FROM analytics_dashboard_get_v1(p_scope_schema, v_dashboard_id);
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_get_default_v1(p_scope_schema name, p_principal_id uuid, p_surface text) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_get_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_get_v1(p_scope_schema name, p_dashboard_id uuid) RETURNS TABLE(dashboard_id uuid, version_id uuid, version_no bigint, root_revision bigint, version_revision bigint, lifecycle_state text, version_state text, name text, visibility text, layout_document bytea, layout_sha256 bytea, manifest_sha256 bytea, widgets jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_version_id uuid;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT current_draft_version_id INTO v_version_id
    FROM analytics_dashboards WHERE id = p_dashboard_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102', MESSAGE = 'analytics dashboard was not found';
    END IF;
    RETURN QUERY SELECT * FROM analytics_dashboard_get_version_v1(
        p_scope_schema, p_dashboard_id, v_version_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_get_v1(p_scope_schema name, p_dashboard_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_get_version_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_get_version_v1(p_scope_schema name, p_dashboard_id uuid, p_version_id uuid) RETURNS TABLE(dashboard_id uuid, version_id uuid, version_no bigint, root_revision bigint, version_revision bigint, lifecycle_state text, version_state text, name text, visibility text, layout_document bytea, layout_sha256 bytea, manifest_sha256 bytea, widgets jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT root.id,version_row.id,version_row.version_no,root.row_revision,
        version_row.row_revision,root.lifecycle_state,
        version_row.version_state,version_row.name,version_row.visibility,
        version_row.layout_document,version_row.layout_sha256,
        version_row.manifest_sha256,
        analytics_dashboard_widgets_v1(version_row.id),
        root.created_at,version_row.updated_at
    FROM analytics_dashboards AS root
    JOIN analytics_dashboard_versions AS version_row
      ON version_row.dashboard_id=root.id
    WHERE root.id=p_dashboard_id AND version_row.id=p_version_id
      AND root.lifecycle_state<>'staged';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics dashboard version was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_get_version_v1(p_scope_schema name, p_dashboard_id uuid, p_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_grant_acl_v1(name, uuid, uuid, text, bytea, uuid, text, uuid, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_grant_acl_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_principal_kind text, p_principal_id uuid, p_access_level text, p_expected_revision bigint, p_occurred_at timestamp with time zone) RETURNS TABLE(dashboard_id uuid, principal_kind text, principal_id uuid, access_level text, row_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_existing analytics_operations%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_principal_kind NOT IN ('user', 'role') OR
       p_principal_id IS NULL OR p_principal_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_access_level NOT IN ('read', 'edit', 'publish') OR p_expected_revision < 0 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard ACL input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:grant-acl:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'dashboard_grant_acl'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics dashboard ACL replay differs';
        END IF;
        RETURN QUERY SELECT acl.dashboard_id, acl.principal_kind, acl.principal_id,
            acl.access_level, acl.row_revision, true FROM analytics_dashboard_acls AS acl
            WHERE acl.dashboard_id = p_dashboard_id AND acl.principal_kind = p_principal_kind
              AND acl.principal_id = p_principal_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics dashboard ACL replay expired';
        END IF;
        RETURN;
    END IF;
    PERFORM 1 FROM analytics_dashboards WHERE id = p_dashboard_id AND lifecycle_state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102', MESSAGE = 'analytics dashboard was not found';
    END IF;
    INSERT INTO analytics_dashboard_acls AS acl (
        dashboard_id, principal_kind, principal_id, access_level,
        row_revision, granted_by, granted_at
    ) VALUES (p_dashboard_id, p_principal_kind, p_principal_id, p_access_level,
        1, p_actor_id, p_occurred_at)
    ON CONFLICT (dashboard_id, principal_kind, principal_id) DO UPDATE
    SET access_level = EXCLUDED.access_level, row_revision = acl.row_revision + 1,
        granted_by = EXCLUDED.granted_by, granted_at = EXCLUDED.granted_at
    WHERE p_expected_revision > 0 AND acl.row_revision = p_expected_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics dashboard ACL changed';
    END IF;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at
    ) VALUES (p_operation_id, p_actor_id, 'dashboard_grant_acl', p_idempotency_key,
        p_request_sha256, 'dashboard', p_dashboard_id, p_expected_revision + 1,
        p_request_sha256, p_occurred_at);
    RETURN QUERY SELECT acl.dashboard_id, acl.principal_kind, acl.principal_id,
        acl.access_level, acl.row_revision, false FROM analytics_dashboard_acls AS acl
        WHERE acl.dashboard_id = p_dashboard_id AND acl.principal_kind = p_principal_kind
          AND acl.principal_id = p_principal_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_grant_acl_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_principal_kind text, p_principal_id uuid, p_access_level text, p_expected_revision bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_list_v1(name, integer, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_list_v1(p_scope_schema name, p_limit integer, p_after uuid) RETURNS TABLE(dashboard_id uuid, version_id uuid, version_no bigint, root_revision bigint, version_revision bigint, lifecycle_state text, version_state text, name text, visibility text, layout_document bytea, layout_sha256 bytea, manifest_sha256 bytea, widgets jsonb, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard list input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT root.id, version_row.id, version_row.version_no, root.row_revision,
           version_row.row_revision, root.lifecycle_state, version_row.version_state,
           version_row.name, version_row.visibility, version_row.layout_document,
           version_row.layout_sha256, version_row.manifest_sha256,
           analytics_dashboard_widgets_v1(version_row.id), root.created_at, root.updated_at
    FROM analytics_dashboards AS root
    JOIN analytics_dashboard_versions AS version_row
      ON version_row.id = root.current_draft_version_id AND version_row.dashboard_id = root.id
    WHERE root.lifecycle_state = 'active' AND (p_after IS NULL OR root.id > p_after)
    ORDER BY root.id LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_list_v1(p_scope_schema name, p_limit integer, p_after uuid) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_publish_v1(name, uuid, uuid, text, bytea, uuid, uuid, uuid, bigint, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_publish_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_draft_version_id uuid, p_next_draft_version_id uuid, p_expected_root_revision bigint, p_expected_draft_revision bigint, p_manifest_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(dashboard_id uuid, version_id uuid, version_no bigint, root_revision bigint, version_revision bigint, lifecycle_state text, version_state text, name text, visibility text, layout_document bytea, layout_sha256 bytea, manifest_sha256 bytea, widgets jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_operations%ROWTYPE;
    v_version analytics_dashboard_versions%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_draft_version_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_next_draft_version_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_expected_root_revision < 1 OR p_expected_draft_revision < 1 OR
       pg_catalog.octet_length(p_manifest_sha256) IS DISTINCT FROM 32 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard publish input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:publish:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'dashboard_publish'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.result_version_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics dashboard replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true FROM analytics_dashboard_get_version_v1(
            p_scope_schema, v_existing.resource_id, v_existing.result_version_id) AS result;
        RETURN;
    END IF;
    SELECT version_row.* INTO v_version FROM analytics_dashboards AS root
    JOIN analytics_dashboard_versions AS version_row
      ON version_row.id = root.current_draft_version_id AND version_row.dashboard_id = root.id
    WHERE root.id = p_dashboard_id AND root.lifecycle_state = 'active'
      AND root.row_revision = p_expected_root_revision
      AND version_row.id = p_draft_version_id AND version_row.version_state = 'draft'
      AND version_row.row_revision = p_expected_draft_revision FOR UPDATE OF root, version_row;
    IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM analytics_dashboard_widgets
        WHERE dashboard_version_id = p_draft_version_id) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics dashboard draft changed';
    END IF;
    IF EXISTS (SELECT 1 FROM analytics_dashboard_versions WHERE id = p_next_draft_version_id) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6104', MESSAGE = 'analytics dashboard version exists';
    END IF;
    UPDATE analytics_dashboard_versions SET version_state = 'published',
        row_revision = row_revision + 1, manifest_sha256 = p_manifest_sha256,
        updated_by = p_actor_id, updated_at = p_occurred_at,
        published_by = p_actor_id, published_at = p_occurred_at
    WHERE id = p_draft_version_id;
    SET CONSTRAINTS analytics_dashboards_current_draft_fk DEFERRED;
    INSERT INTO analytics_dashboard_versions (
        id, dashboard_id, version_no, version_state, row_revision, name, visibility,
        layout_document, layout_sha256, manifest_sha256, created_by, updated_by,
        created_at, updated_at
    ) VALUES (p_next_draft_version_id, p_dashboard_id, v_version.version_no + 1,
        'draft', 1, v_version.name, v_version.visibility, v_version.layout_document,
        v_version.layout_sha256, p_manifest_sha256, p_actor_id, p_actor_id,
        p_occurred_at, p_occurred_at);
    INSERT INTO analytics_dashboard_widgets SELECT p_next_draft_version_id,
        widget_id, position, query_version_id, parameter_document, parameter_sha256,
        output_document, output_sha256, p_occurred_at FROM analytics_dashboard_widgets
        WHERE dashboard_version_id = p_draft_version_id;
    UPDATE analytics_dashboards SET current_draft_version_id = p_next_draft_version_id,
        row_revision = row_revision + 1, updated_by = p_actor_id,
        updated_at = p_occurred_at WHERE id = p_dashboard_id;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at,
        result_version_id
    ) VALUES (p_operation_id, p_actor_id, 'dashboard_publish', p_idempotency_key,
        p_request_sha256, 'dashboard', p_dashboard_id, p_expected_root_revision + 1,
        p_manifest_sha256, p_occurred_at, p_draft_version_id);
    RETURN QUERY SELECT result.*, false FROM analytics_dashboard_get_version_v1(
        p_scope_schema, p_dashboard_id, p_draft_version_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_publish_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_draft_version_id uuid, p_next_draft_version_id uuid, p_expected_root_revision bigint, p_expected_draft_revision bigint, p_manifest_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_revoke_acl_v1(name, uuid, uuid, text, bytea, uuid, text, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_revoke_acl_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_principal_kind text, p_principal_id uuid, p_expected_revision bigint, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_existing analytics_operations%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_principal_kind NOT IN ('user', 'role') OR p_principal_id IS NULL OR
       p_principal_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_expected_revision < 1 OR p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard ACL revoke input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:revoke-acl:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'dashboard_revoke_acl'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics dashboard ACL replay differs';
        END IF;
        RETURN true;
    END IF;
    DELETE FROM analytics_dashboard_acls WHERE dashboard_id = p_dashboard_id
      AND principal_kind = p_principal_kind AND principal_id = p_principal_id
      AND row_revision = p_expected_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics dashboard ACL changed';
    END IF;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at
    ) VALUES (p_operation_id, p_actor_id, 'dashboard_revoke_acl', p_idempotency_key,
        p_request_sha256, 'dashboard', p_dashboard_id, p_expected_revision + 1,
        p_request_sha256, p_occurred_at);
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_revoke_acl_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_principal_kind text, p_principal_id uuid, p_expected_revision bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_set_default_v1(name, uuid, uuid, text, bytea, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_set_default_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_principal_id uuid, p_dashboard_id uuid, p_surface text, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE v_existing analytics_operations%ROWTYPE; v_revision bigint;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_principal_id IS NULL OR p_principal_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_surface IS NULL OR p_surface OPERATOR(pg_catalog.!~) '^[a-z][a-z0-9_.-]{0,63}$' OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard default input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:default:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'dashboard_set_default'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics dashboard default replay differs';
        END IF;
        RETURN true;
    END IF;
    PERFORM 1 FROM analytics_dashboards AS root
    JOIN analytics_dashboard_versions AS version_row ON version_row.dashboard_id = root.id
    WHERE root.id = p_dashboard_id AND root.lifecycle_state = 'active'
      AND version_row.version_state = 'published';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102', MESSAGE = 'published analytics dashboard was not found';
    END IF;
    INSERT INTO analytics_dashboard_preferences AS preference (
        principal_id, surface, dashboard_id, row_revision, updated_by, updated_at
    ) VALUES (p_principal_id, p_surface, p_dashboard_id, 1, p_actor_id, p_occurred_at)
    ON CONFLICT (principal_id, surface) DO UPDATE
    SET dashboard_id = EXCLUDED.dashboard_id, row_revision = preference.row_revision + 1,
        updated_by = EXCLUDED.updated_by, updated_at = EXCLUDED.updated_at
    RETURNING row_revision INTO v_revision;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at
    ) VALUES (p_operation_id, p_actor_id, 'dashboard_set_default', p_idempotency_key,
        p_request_sha256, 'dashboard', p_dashboard_id, v_revision,
        p_request_sha256, p_occurred_at);
    RETURN false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_set_default_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_principal_id uuid, p_dashboard_id uuid, p_surface text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_update_v1(name, uuid, uuid, text, bytea, uuid, bigint, bigint, text, text, bytea, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_update_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_expected_root_revision bigint, p_expected_version_revision bigint, p_name text, p_visibility text, p_layout_document bytea, p_widgets jsonb, p_occurred_at timestamp with time zone) RETURNS TABLE(dashboard_id uuid, version_id uuid, version_no bigint, root_revision bigint, version_revision bigint, lifecycle_state text, version_state text, name text, visibility text, layout_document bytea, layout_sha256 bytea, manifest_sha256 bytea, widgets jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_existing analytics_operations%ROWTYPE; v_version_id uuid; v_manifest bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_dashboard_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_expected_root_revision < 1 OR p_expected_version_revision < 1 OR
       pg_catalog.octet_length(p_name) NOT BETWEEN 1 AND 100 OR
       p_visibility NOT IN ('private', 'tenant') OR
       pg_catalog.octet_length(p_layout_document) NOT BETWEEN 2 AND 65536 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard update input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:dashboard:update:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'dashboard_update'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.result_version_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics dashboard replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true FROM analytics_dashboard_get_version_v1(
            p_scope_schema, v_existing.resource_id, v_existing.result_version_id) AS result;
        RETURN;
    END IF;
    SELECT root.current_draft_version_id INTO v_version_id
    FROM analytics_dashboards AS root
    WHERE root.id = p_dashboard_id AND root.lifecycle_state = 'active'
      AND root.row_revision = p_expected_root_revision FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics dashboard root changed';
    END IF;
    PERFORM 1 FROM analytics_dashboard_versions AS version_row
    WHERE version_row.id = v_version_id AND version_row.dashboard_id = p_dashboard_id
      AND version_row.version_state = 'draft'
      AND version_row.row_revision = p_expected_version_revision FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics dashboard draft changed';
    END IF;
    v_manifest := pg_catalog.sha256(p_layout_document || pg_catalog.convert_to(p_widgets::text, 'UTF8'));
    UPDATE analytics_dashboard_versions SET name = p_name, visibility = p_visibility,
        layout_document = p_layout_document, layout_sha256 = pg_catalog.sha256(p_layout_document),
        manifest_sha256 = v_manifest, row_revision = row_revision + 1,
        updated_by = p_actor_id, updated_at = p_occurred_at WHERE id = v_version_id;
    PERFORM analytics_dashboard_widgets_replace_v1(v_version_id, p_widgets, p_occurred_at);
    UPDATE analytics_dashboards SET row_revision = row_revision + 1,
        updated_by = p_actor_id, updated_at = p_occurred_at WHERE id = p_dashboard_id;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at,
        result_version_id
    ) VALUES (p_operation_id, p_actor_id, 'dashboard_update', p_idempotency_key,
        p_request_sha256, 'dashboard', p_dashboard_id, p_expected_root_revision + 1,
        v_manifest, p_occurred_at, v_version_id);
    RETURN QUERY SELECT result.*, false FROM analytics_dashboard_get_version_v1(
        p_scope_schema, p_dashboard_id, v_version_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_dashboard_update_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_dashboard_id uuid, p_expected_root_revision bigint, p_expected_version_revision bigint, p_name text, p_visibility text, p_layout_document bytea, p_widgets jsonb, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_dashboard_widgets_replace_v1(uuid, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_dashboard_widgets_replace_v1(p_version_id uuid, p_widgets jsonb, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count integer;
BEGIN
    IF pg_catalog.jsonb_typeof(p_widgets) IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(p_widgets) > 30 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard widgets are invalid';
    END IF;
    DELETE FROM analytics_dashboard_widgets WHERE dashboard_version_id = p_version_id;
    INSERT INTO analytics_dashboard_widgets (
        dashboard_version_id, widget_id, position, query_version_id,
        parameter_document, parameter_sha256, output_document, output_sha256, created_at
    )
    SELECT p_version_id, (item.value->>'widget_id')::uuid,
           (item.value->>'position')::smallint, (item.value->>'query_version_id')::uuid,
           pg_catalog.decode(item.value->>'parameter_document', 'hex'),
           pg_catalog.sha256(pg_catalog.decode(item.value->>'parameter_document', 'hex')),
           pg_catalog.decode(item.value->>'output_document', 'hex'),
           pg_catalog.sha256(pg_catalog.decode(item.value->>'output_document', 'hex')),
           p_occurred_at
    FROM pg_catalog.jsonb_array_elements(p_widgets) AS item(value);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count IS DISTINCT FROM pg_catalog.jsonb_array_length(p_widgets) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics dashboard widget count differs';
    END IF;
END;
$$;


