--
-- Name: analytics_legal_hold_place_v1(name, uuid, uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_legal_hold_place_v1(p_scope_schema name, p_hold_id uuid, p_actor_id uuid, p_reason_sha256 bytea, p_placed_at timestamp with time zone) RETURNS TABLE(hold_id uuid, state text, row_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_hold analytics_legal_holds%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_hold_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR
       p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_reason_sha256) IS DISTINCT FROM 32 OR
       p_placed_at IS NULL OR NOT pg_catalog.isfinite(p_placed_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics legal hold placement is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:legal-hold',6100));
    SELECT hold_row.* INTO v_hold FROM analytics_legal_holds AS hold_row
    WHERE hold_row.hold_id = p_hold_id FOR UPDATE;
    IF FOUND THEN
        IF v_hold.reason_sha256 IS DISTINCT FROM p_reason_sha256 OR
           v_hold.placed_by IS DISTINCT FROM p_actor_id THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103',
                MESSAGE = 'analytics legal hold identity was reused';
        END IF;
        RETURN QUERY SELECT v_hold.hold_id,v_hold.state,v_hold.row_revision,true;
        RETURN;
    END IF;
    BEGIN
        INSERT INTO analytics_legal_holds (
            hold_id,reason_sha256,placed_by,placed_at,state,row_revision
        ) VALUES (p_hold_id,p_reason_sha256,p_actor_id,p_placed_at,'active',1);
    EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION USING ERRCODE = 'P6103',
            MESSAGE = 'analytics tenant already has an active legal hold';
    END;
    RETURN QUERY SELECT p_hold_id,'active'::text,1::bigint,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_legal_hold_place_v1(p_scope_schema name, p_hold_id uuid, p_actor_id uuid, p_reason_sha256 bytea, p_placed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_legal_hold_release_v1(name, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_legal_hold_release_v1(p_scope_schema name, p_hold_id uuid, p_actor_id uuid, p_expected_revision bigint, p_released_at timestamp with time zone) RETURNS TABLE(hold_id uuid, state text, row_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_hold analytics_legal_holds%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_hold_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR
       p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_expected_revision < 1 OR p_released_at IS NULL OR
       NOT pg_catalog.isfinite(p_released_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics legal hold release is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT hold_row.* INTO v_hold FROM analytics_legal_holds AS hold_row
    WHERE hold_row.hold_id = p_hold_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102',
            MESSAGE = 'analytics legal hold was not found';
    END IF;
    IF v_hold.state = 'released' THEN
        IF v_hold.released_by IS DISTINCT FROM p_actor_id OR
           v_hold.row_revision IS DISTINCT FROM p_expected_revision + 1 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103',
                MESSAGE = 'analytics legal hold release differs';
        END IF;
        RETURN QUERY SELECT v_hold.hold_id,v_hold.state,v_hold.row_revision,true;
        RETURN;
    END IF;
    IF v_hold.row_revision IS DISTINCT FROM p_expected_revision OR
       p_released_at < v_hold.placed_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'analytics legal hold revision changed';
    END IF;
    UPDATE analytics_legal_holds
    SET state = 'released',row_revision = analytics_legal_holds.row_revision + 1,
        released_by = p_actor_id,released_at = p_released_at
    WHERE analytics_legal_holds.hold_id = p_hold_id;
    RETURN QUERY SELECT p_hold_id,'released'::text,p_expected_revision + 1,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_legal_hold_release_v1(p_scope_schema name, p_hold_id uuid, p_actor_id uuid, p_expected_revision bigint, p_released_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_public_dashboard_root_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_public_dashboard_root_v1(p_scope_schema name, p_release_id uuid, p_dashboard_version_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_dashboard_id uuid;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT version_row.dashboard_id INTO v_dashboard_id
    FROM analytics_publication_releases AS release
    JOIN analytics_dashboard_versions AS version_row
      ON version_row.id = p_dashboard_version_id
     AND version_row.version_state = 'published'
    WHERE release.id = p_release_id
      AND release.lifecycle_state = 'active'
      AND release.audience IN ('public', 'capability')
      AND release.resource_kind = 'dashboard'
      AND release.resource_version_id = p_dashboard_version_id;
    IF v_dashboard_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102',
            MESSAGE = 'analytics public dashboard root was not found';
    END IF;
    RETURN v_dashboard_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_public_dashboard_root_v1(p_scope_schema name, p_release_id uuid, p_dashboard_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_public_query_root_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_public_query_root_v1(p_scope_schema name, p_release_id uuid, p_query_version_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_query_id uuid;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT version_row.query_id INTO v_query_id
    FROM analytics_publication_releases AS release
    JOIN analytics_saved_query_versions AS version_row
      ON version_row.id = p_query_version_id
     AND version_row.version_state = 'published'
    WHERE release.id = p_release_id
      AND release.lifecycle_state = 'active'
      AND release.audience IN ('public', 'capability')
      AND (
          (release.resource_kind = 'query'
           AND release.resource_version_id = p_query_version_id)
          OR
          (release.resource_kind = 'dashboard' AND EXISTS (
              SELECT 1 FROM analytics_dashboard_widgets AS widget
              WHERE widget.dashboard_version_id = release.resource_version_id
                AND widget.query_version_id = p_query_version_id
          ))
      );
    IF v_query_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102',
            MESSAGE = 'analytics public query root was not found';
    END IF;
    RETURN v_query_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_public_query_root_v1(p_scope_schema name, p_release_id uuid, p_query_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_publication_activate_v1(name, uuid, uuid, text, bytea, uuid, bigint, timestamp with time zone, bytea, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_publication_activate_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_expected_revision bigint, p_step_up_at timestamp with time zone, p_public_id bytea, p_capability_sha256 bytea, p_capability_expires_at timestamp with time zone, p_occurred_at timestamp with time zone) RETURNS TABLE(release_id uuid, resource_kind text, resource_version_id uuid, audience text, lifecycle_state text, cache_policy text, manifest_sha256 bytea, requester_id uuid, approver_id uuid, row_revision bigint, generation bigint, public_id bytea, capability_expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_operations%ROWTYPE; v_release analytics_publication_releases%ROWTYPE;
    v_tenant_id uuid;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR p_expected_revision < 1 OR
       p_step_up_at IS NULL OR p_occurred_at IS NULL OR p_step_up_at > p_occurred_at OR
       p_occurred_at - p_step_up_at > interval '10 minutes' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics publication activation input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:publication:activate:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'publication_activate'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics publication activation replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true FROM analytics_publication_get_v1(
            p_scope_schema, v_existing.resource_id) AS result;
        RETURN;
    END IF;
    SELECT release.* INTO v_release FROM analytics_publication_releases AS release
    WHERE release.id = p_release_id AND release.lifecycle_state = 'pending_approval'
      AND release.row_revision = p_expected_revision FOR UPDATE;
    IF NOT FOUND OR (v_release.audience <> 'tenant' AND v_release.approver_id IS NULL) OR
       (v_release.audience = 'tenant' AND (p_public_id IS NOT NULL OR p_capability_sha256 IS NOT NULL
          OR p_capability_expires_at IS NOT NULL)) OR
       (v_release.audience = 'public' AND (pg_catalog.octet_length(p_public_id) IS DISTINCT FROM 16
          OR p_capability_sha256 IS NOT NULL OR p_capability_expires_at IS NOT NULL)) OR
       (v_release.audience = 'capability' AND (pg_catalog.octet_length(p_public_id) IS DISTINCT FROM 16
          OR pg_catalog.octet_length(p_capability_sha256) IS DISTINCT FROM 32
          OR p_capability_expires_at IS NULL OR p_capability_expires_at <= p_occurred_at
          OR p_capability_expires_at - p_occurred_at > interval '30 days')) THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics publication activation changed';
    END IF;
    UPDATE analytics_publication_releases SET lifecycle_state = 'active',
        public_id = p_public_id, capability_expires_at = p_capability_expires_at,
        activated_at = p_occurred_at, row_revision = row_revision + 1,
        updated_at = p_occurred_at WHERE id = p_release_id;
    IF v_release.audience = 'capability' THEN
        INSERT INTO analytics_capability_tokens VALUES (
            p_release_id, p_capability_sha256, p_occurred_at, p_capability_expires_at, NULL);
    END IF;
    IF v_release.audience <> 'tenant' THEN
        SELECT tenant_id INTO STRICT v_tenant_id FROM tenancy_schema_identity
        WHERE singleton AND schema_name = pg_catalog.current_schema();
        PERFORM platform.analytics_public_activate_v1(
            v_tenant_id,p_public_id,p_release_id,v_release.resource_kind,
            v_release.resource_version_id,v_release.audience,v_release.generation,
            p_capability_sha256,p_capability_expires_at,p_occurred_at);
    END IF;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at
    ) VALUES (p_operation_id, p_actor_id, 'publication_activate', p_idempotency_key,
        p_request_sha256, 'publication', p_release_id, p_expected_revision + 1,
        v_release.manifest_sha256, p_occurred_at);
    RETURN QUERY SELECT result.*, false FROM analytics_publication_get_v1(
        p_scope_schema, p_release_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_publication_activate_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_expected_revision bigint, p_step_up_at timestamp with time zone, p_public_id bytea, p_capability_sha256 bytea, p_capability_expires_at timestamp with time zone, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_publication_approve_v1(name, uuid, uuid, text, bytea, uuid, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_publication_approve_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_expected_revision bigint, p_step_up_at timestamp with time zone, p_occurred_at timestamp with time zone) RETURNS TABLE(release_id uuid, resource_kind text, resource_version_id uuid, audience text, lifecycle_state text, cache_policy text, manifest_sha256 bytea, requester_id uuid, approver_id uuid, row_revision bigint, generation bigint, public_id bytea, capability_expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_operations%ROWTYPE;
    v_requester uuid; v_requester_step_up timestamptz; v_manifest bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR p_expected_revision < 1 OR
       p_step_up_at IS NULL OR p_occurred_at IS NULL OR p_step_up_at > p_occurred_at OR
       p_occurred_at - p_step_up_at > interval '10 minutes' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics publication approval input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:publication:approve:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'publication_approve'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics publication approval replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true FROM analytics_publication_get_v1(
            p_scope_schema, v_existing.resource_id) AS result;
        RETURN;
    END IF;
    SELECT requester_id, requester_step_up_at, manifest_sha256
    INTO v_requester, v_requester_step_up, v_manifest
    FROM analytics_publication_releases WHERE id = p_release_id
      AND lifecycle_state = 'pending_approval' AND approver_id IS NULL
      AND row_revision = p_expected_revision FOR UPDATE;
    IF NOT FOUND OR v_requester = p_actor_id OR v_requester_step_up IS NULL OR
       p_occurred_at - v_requester_step_up > interval '10 minutes' THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics publication approval changed';
    END IF;
    INSERT INTO analytics_publication_approvals VALUES (
        p_release_id, v_requester, v_requester_step_up, p_actor_id, p_step_up_at,
        p_occurred_at, pg_catalog.sha256(p_request_sha256 || v_manifest));
    UPDATE analytics_publication_releases SET approver_id = p_actor_id,
        approved_at = p_occurred_at, row_revision = row_revision + 1,
        updated_at = p_occurred_at WHERE id = p_release_id;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at
    ) VALUES (p_operation_id, p_actor_id, 'publication_approve', p_idempotency_key,
        p_request_sha256, 'publication', p_release_id, p_expected_revision + 1,
        v_manifest, p_occurred_at);
    RETURN QUERY SELECT result.*, false FROM analytics_publication_get_v1(
        p_scope_schema, p_release_id) AS result;
END;
$$;


