--
-- Name: analytics_publication_create_v1(name, uuid, uuid, text, bytea, uuid, text, uuid, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_publication_create_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_resource_kind text, p_resource_version_id uuid, p_audience text, p_cache_policy text, p_manifest_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(release_id uuid, resource_kind text, resource_version_id uuid, audience text, lifecycle_state text, cache_policy text, manifest_sha256 bytea, requester_id uuid, approver_id uuid, row_revision bigint, generation bigint, public_id bytea, capability_expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_operations%ROWTYPE;
    v_root_id uuid;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_resource_version_id)
           IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_resource_kind NOT IN ('query','dashboard') OR
       p_audience NOT IN ('tenant','public','capability') OR
       p_cache_policy NOT IN ('none','revision_bound') OR
       pg_catalog.octet_length(p_manifest_sha256) IS DISTINCT FROM 32 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics publication create input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:publication:create:'||p_actor_id::text||':'||
        p_idempotency_key,6100
    ));
    SELECT operation.* INTO v_existing
    FROM analytics_operations AS operation
    WHERE operation.actor_id=p_actor_id
      AND operation.operation_kind='publication_create'
      AND operation.idempotency_key=p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='P6103',
                MESSAGE='analytics publication replay differs';
        END IF;
        RETURN QUERY SELECT result.*,true
        FROM analytics_publication_get_v1(
            p_scope_schema,v_existing.resource_id
        ) AS result;
        RETURN;
    END IF;
    IF EXISTS (
        SELECT 1 FROM analytics_publication_releases
        WHERE id=p_release_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6104',
            MESSAGE='analytics publication identity exists';
    END IF;
    IF p_resource_kind='query' THEN
        SELECT version_row.query_id INTO v_root_id
        FROM analytics_saved_query_versions AS version_row
        WHERE version_row.id=p_resource_version_id;
        PERFORM 1 FROM analytics_saved_queries AS root
        WHERE root.id=v_root_id AND root.lifecycle_state='active'
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6102',
                MESSAGE='analytics publication target is inactive';
        END IF;
        PERFORM 1 FROM analytics_saved_query_versions AS version_row
        WHERE version_row.id=p_resource_version_id
          AND version_row.query_id=v_root_id
          AND version_row.version_state IN ('published','needs_revalidation')
        FOR UPDATE;
    ELSE
        SELECT version_row.dashboard_id INTO v_root_id
        FROM analytics_dashboard_versions AS version_row
        WHERE version_row.id=p_resource_version_id;
        PERFORM 1 FROM analytics_dashboards AS root
        WHERE root.id=v_root_id AND root.lifecycle_state='active'
        FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6102',
                MESSAGE='analytics publication target is inactive';
        END IF;
        PERFORM 1 FROM analytics_dashboard_versions AS version_row
        WHERE version_row.id=p_resource_version_id
          AND version_row.dashboard_id=v_root_id
          AND version_row.version_state='published'
        FOR UPDATE;
    END IF;
    IF NOT FOUND OR v_root_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics publication target is inactive';
    END IF;
    INSERT INTO analytics_publication_releases(
        id,resource_kind,resource_version_id,audience,lifecycle_state,
        cache_policy,manifest_sha256,requester_id,row_revision,generation,
        created_at,updated_at
    ) VALUES (
        p_release_id,p_resource_kind,p_resource_version_id,p_audience,
        'draft',p_cache_policy,p_manifest_sha256,p_actor_id,1,1,
        p_occurred_at,p_occurred_at
    );
    INSERT INTO analytics_operations(
        operation_id,actor_id,operation_kind,idempotency_key,request_sha256,
        resource_kind,resource_id,result_revision,result_sha256,occurred_at,
        result_version_id
    ) VALUES (
        p_operation_id,p_actor_id,'publication_create',p_idempotency_key,
        p_request_sha256,'publication',p_release_id,1,p_manifest_sha256,
        p_occurred_at,p_resource_version_id
    );
    RETURN QUERY SELECT result.*,false
    FROM analytics_publication_get_v1(
        p_scope_schema,p_release_id
    ) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_publication_create_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_resource_kind text, p_resource_version_id uuid, p_audience text, p_cache_policy text, p_manifest_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_publication_get_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_publication_get_v1(p_scope_schema name, p_release_id uuid) RETURNS TABLE(release_id uuid, resource_kind text, resource_version_id uuid, audience text, lifecycle_state text, cache_policy text, manifest_sha256 bytea, requester_id uuid, approver_id uuid, row_revision bigint, generation bigint, public_id bytea, capability_expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY SELECT release.id, release.resource_kind, release.resource_version_id,
        release.audience, release.lifecycle_state, release.cache_policy,
        release.manifest_sha256, release.requester_id, release.approver_id,
        release.row_revision, release.generation, release.public_id,
        release.capability_expires_at, release.created_at, release.updated_at
    FROM analytics_publication_releases AS release WHERE release.id = p_release_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102', MESSAGE = 'analytics publication was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_publication_get_v1(p_scope_schema name, p_release_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_publication_list_v1(name, integer, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_publication_list_v1(p_scope_schema name, p_limit integer, p_after uuid) RETURNS TABLE(release_id uuid, resource_kind text, resource_version_id uuid, audience text, lifecycle_state text, cache_policy text, manifest_sha256 bytea, requester_id uuid, approver_id uuid, row_revision bigint, generation bigint, public_id bytea, capability_expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics publication list input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY SELECT release.id, release.resource_kind, release.resource_version_id,
        release.audience, release.lifecycle_state, release.cache_policy,
        release.manifest_sha256, release.requester_id, release.approver_id,
        release.row_revision, release.generation, release.public_id,
        release.capability_expires_at, release.created_at, release.updated_at
    FROM analytics_publication_releases AS release
    WHERE p_after IS NULL OR release.id > p_after ORDER BY release.id LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_publication_list_v1(p_scope_schema name, p_limit integer, p_after uuid) OWNER TO harpy_owner;

--
-- Name: analytics_publication_repair_v1(name, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_publication_repair_v1(p_scope_schema name, p_release_id uuid, p_expected_generation bigint, p_observed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_release analytics_publication_releases%ROWTYPE;
    v_tenant_id uuid;
    v_capability_sha256 bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_expected_generation < 1 OR p_observed_at IS NULL OR
       NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics publication repair input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT release.* INTO v_release
    FROM analytics_publication_releases AS release
    WHERE release.id=p_release_id
      AND release.generation=p_expected_generation
      AND release.audience IN ('public','capability')
      AND release.lifecycle_state IN ('active','revoked')
      AND release.public_id IS NOT NULL
      AND release.activated_at IS NOT NULL
      AND release.updated_at <= p_observed_at
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='analytics publication repair target changed';
    END IF;
    SELECT tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity
    WHERE singleton AND schema_name=pg_catalog.current_schema();
    IF v_release.audience='capability' THEN
        SELECT token.token_sha256 INTO STRICT v_capability_sha256
        FROM analytics_capability_tokens AS token
        WHERE token.release_id=v_release.id;
    END IF;
    PERFORM platform.analytics_public_repair_v1(
        v_tenant_id,v_release.public_id,v_release.id,v_release.resource_kind,
        v_release.resource_version_id,v_release.audience,
        v_release.lifecycle_state,v_release.generation,v_capability_sha256,
        v_release.capability_expires_at,v_release.activated_at,
        v_release.revoked_at
    );
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_publication_repair_v1(p_scope_schema name, p_release_id uuid, p_expected_generation bigint, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_publication_revoke_v1(name, uuid, uuid, text, bytea, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_publication_revoke_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_expected_revision bigint, p_occurred_at timestamp with time zone) RETURNS TABLE(release_id uuid, resource_kind text, resource_version_id uuid, audience text, lifecycle_state text, cache_policy text, manifest_sha256 bytea, requester_id uuid, approver_id uuid, row_revision bigint, generation bigint, public_id bytea, capability_expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_operations%ROWTYPE;
    v_release analytics_publication_releases%ROWTYPE;
    v_tenant_id uuid;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR p_expected_revision < 1 OR
       p_occurred_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics publication revoke input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:publication:revoke:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'publication_revoke'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics publication revoke replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true FROM analytics_publication_get_v1(
            p_scope_schema, v_existing.resource_id) AS result; RETURN;
    END IF;
    SELECT release.* INTO v_release FROM analytics_publication_releases AS release
    WHERE release.id = p_release_id AND release.lifecycle_state = 'active'
      AND release.row_revision = p_expected_revision FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics publication revoke changed';
    END IF;
    UPDATE analytics_publication_releases SET lifecycle_state = 'revoked',
        generation = generation + 1, revoked_at = p_occurred_at,
        row_revision = row_revision + 1, updated_at = p_occurred_at WHERE id = p_release_id;
    UPDATE analytics_capability_tokens SET revoked_at = p_occurred_at WHERE release_id = p_release_id;
    IF v_release.audience <> 'tenant' THEN
        SELECT tenant_id INTO STRICT v_tenant_id FROM tenancy_schema_identity
        WHERE singleton AND schema_name = pg_catalog.current_schema();
        PERFORM platform.analytics_public_revoke_v1(
            v_tenant_id,p_release_id,v_release.generation,p_occurred_at);
    END IF;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at
    ) VALUES (p_operation_id, p_actor_id, 'publication_revoke', p_idempotency_key,
        p_request_sha256, 'publication', p_release_id, p_expected_revision + 1,
        v_release.manifest_sha256, p_occurred_at);
    RETURN QUERY SELECT result.*, false FROM analytics_publication_get_v1(
        p_scope_schema, p_release_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_publication_revoke_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_expected_revision bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_publication_submit_v1(name, uuid, uuid, text, bytea, uuid, bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_publication_submit_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_expected_revision bigint, p_step_up_at timestamp with time zone, p_occurred_at timestamp with time zone) RETURNS TABLE(release_id uuid, resource_kind text, resource_version_id uuid, audience text, lifecycle_state text, cache_policy text, manifest_sha256 bytea, requester_id uuid, approver_id uuid, row_revision bigint, generation bigint, public_id bytea, capability_expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_existing analytics_operations%ROWTYPE; v_manifest bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR p_expected_revision < 1 OR
       p_step_up_at IS NULL OR p_occurred_at IS NULL OR p_step_up_at > p_occurred_at OR
       p_occurred_at - p_step_up_at > interval '10 minutes' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'analytics publication submit input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:publication:submit:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id AND operation.operation_kind = 'publication_submit'
      AND operation.idempotency_key = p_idempotency_key FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103', MESSAGE = 'analytics publication submit replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true FROM analytics_publication_get_v1(
            p_scope_schema, v_existing.resource_id) AS result;
        RETURN;
    END IF;
    UPDATE analytics_publication_releases SET lifecycle_state = 'pending_approval',
        requester_step_up_at = p_step_up_at, submitted_at = p_occurred_at,
        row_revision = row_revision + 1, updated_at = p_occurred_at
    WHERE id = p_release_id AND requester_id = p_actor_id AND lifecycle_state = 'draft'
      AND row_revision = p_expected_revision RETURNING manifest_sha256 INTO v_manifest;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'analytics publication submit changed';
    END IF;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key, request_sha256,
        resource_kind, resource_id, result_revision, result_sha256, occurred_at
    ) VALUES (p_operation_id, p_actor_id, 'publication_submit', p_idempotency_key,
        p_request_sha256, 'publication', p_release_id, p_expected_revision + 1,
        v_manifest, p_occurred_at);
    RETURN QUERY SELECT result.*, false FROM analytics_publication_get_v1(
        p_scope_schema, p_release_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_publication_submit_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_release_id uuid, p_expected_revision bigint, p_step_up_at timestamp with time zone, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_query_create_v1(name, uuid, uuid, text, bytea, uuid, uuid, text, bytea, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_create_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_query_id uuid, p_version_id uuid, p_name text, p_query_document bytea, p_parameter_document bytea, p_output_document bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(query_id uuid, version_id uuid, version_no bigint, root_revision bigint, reference_epoch bigint, version_revision bigint, lifecycle_state text, version_state text, name text, query_document bytea, parameter_document bytea, output_document bytea, manifest_sha256 bytea, cache_policy text, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_existing analytics_operations%ROWTYPE;
    v_manifest bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_query_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_version_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_idempotency_key IS NULL OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_idempotency_key OPERATOR(pg_catalog.!~) '^[A-Za-z0-9_.:-]+$' OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_name) NOT BETWEEN 1 AND 100 OR
       pg_catalog.octet_length(p_query_document) NOT BETWEEN 2 AND 65536 OR
       pg_catalog.octet_length(p_parameter_document) NOT BETWEEN 2 AND 65536 OR
       pg_catalog.octet_length(p_output_document) NOT BETWEEN 2 AND 65536 OR
       NOT pg_catalog.pg_input_is_valid(pg_catalog.convert_from(p_query_document, 'UTF8'), 'jsonb') OR
       NOT pg_catalog.pg_input_is_valid(pg_catalog.convert_from(p_parameter_document, 'UTF8'), 'jsonb') OR
       NOT pg_catalog.pg_input_is_valid(pg_catalog.convert_from(p_output_document, 'UTF8'), 'jsonb') OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics query create input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:query:create:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing
    FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id
      AND operation.operation_kind = 'query_create'
      AND operation.idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103',
                MESSAGE = 'analytics query idempotency key was reused';
        END IF;
        RETURN QUERY
        SELECT result.*, true
        FROM analytics_query_get_v1(p_scope_schema, v_existing.resource_id) AS result;
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM analytics_saved_queries WHERE id = p_query_id) OR
       EXISTS (SELECT 1 FROM analytics_saved_query_versions WHERE id = p_version_id) OR
       EXISTS (SELECT 1 FROM analytics_operations WHERE operation_id = p_operation_id) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6104',
            MESSAGE = 'analytics query stable identity already exists';
    END IF;
    v_manifest := pg_catalog.sha256(
        p_query_document || p_parameter_document || p_output_document);
    SET CONSTRAINTS analytics_saved_queries_current_draft_fk DEFERRED;
    INSERT INTO analytics_saved_queries (
        id, lifecycle_state, row_revision, reference_epoch,
        current_draft_version_id, created_by, updated_by, created_at, updated_at
    ) VALUES (
        p_query_id, 'active', 1, 1, p_version_id,
        p_actor_id, p_actor_id, p_occurred_at, p_occurred_at
    );
    INSERT INTO analytics_saved_query_versions (
        id, query_id, version_no, version_state, row_revision, name,
        query_document, query_sha256, parameter_document, parameter_sha256,
        output_document, output_sha256, manifest_sha256, cache_policy,
        created_by, updated_by, created_at, updated_at
    ) VALUES (
        p_version_id, p_query_id, 1, 'draft', 1, p_name,
        p_query_document, pg_catalog.sha256(p_query_document),
        p_parameter_document, pg_catalog.sha256(p_parameter_document),
        p_output_document, pg_catalog.sha256(p_output_document),
        v_manifest, 'none', p_actor_id, p_actor_id, p_occurred_at, p_occurred_at
    );
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key,
        request_sha256, resource_kind, resource_id, result_revision,
        result_sha256, occurred_at
    ) VALUES (
        p_operation_id, p_actor_id, 'query_create', p_idempotency_key,
        p_request_sha256, 'query', p_query_id, 1, v_manifest, p_occurred_at
    );
    RETURN QUERY
    SELECT result.*, false
    FROM analytics_query_get_v1(p_scope_schema, p_query_id) AS result;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_query_create_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_query_id uuid, p_version_id uuid, p_name text, p_query_document bytea, p_parameter_document bytea, p_output_document bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_query_delete_v1(name, uuid, uuid, text, bytea, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_delete_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_query_id uuid, p_expected_root_revision bigint, p_occurred_at timestamp with time zone) RETURNS TABLE(query_id uuid, version_id uuid, version_no bigint, root_revision bigint, reference_epoch bigint, version_revision bigint, lifecycle_state text, version_state text, name text, query_document bytea, parameter_document bytea, output_document bytea, manifest_sha256 bytea, cache_policy text, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_operations%ROWTYPE;
    v_manifest bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_idempotency_key IS NULL OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.uuid_extract_version(p_query_id) IS DISTINCT FROM 7 OR
       p_expected_root_revision < 1 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics query delete input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:query:delete:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing
    FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id
      AND operation.operation_kind = 'query_delete'
      AND operation.idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103',
                MESSAGE = 'analytics query idempotency key was reused';
        END IF;
        RETURN QUERY
        SELECT result.*, true
        FROM analytics_query_get_v1(p_scope_schema, v_existing.resource_id) AS result;
        RETURN;
    END IF;
    SELECT version_row.manifest_sha256 INTO v_manifest
    FROM analytics_saved_queries AS root
    JOIN analytics_saved_query_versions AS version_row
      ON version_row.id = root.current_draft_version_id
    WHERE root.id = p_query_id AND root.lifecycle_state = 'active'
      AND root.row_revision = p_expected_root_revision
    FOR UPDATE OF root, version_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'analytics query root revision changed';
    END IF;
    UPDATE analytics_saved_queries
    SET lifecycle_state = 'retired',
        row_revision = row_revision + 1,
        reference_epoch = reference_epoch + 1,
        updated_by = p_actor_id, updated_at = p_occurred_at
    WHERE id = p_query_id;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key,
        request_sha256, resource_kind, resource_id, result_revision,
        result_sha256, occurred_at
    ) VALUES (
        p_operation_id, p_actor_id, 'query_delete', p_idempotency_key,
        p_request_sha256, 'query', p_query_id,
        p_expected_root_revision + 1, v_manifest, p_occurred_at
    );
    RETURN QUERY
    SELECT result.*, false
    FROM analytics_query_get_v1(p_scope_schema, p_query_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_delete_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_query_id uuid, p_expected_root_revision bigint, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_query_dependencies_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_dependencies_v1(p_scope_schema name, p_query_id uuid, p_version_id uuid) RETURNS TABLE(owner_domain text, resource_kind text, resource_id uuid, resource_version_id uuid, owner_generation bigint, catalog_version bigint, query_contract_version bigint, policy_version bigint, data_revision_capability text, dependency_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM 1
    FROM analytics_saved_query_versions AS version_row
    JOIN analytics_saved_queries AS root
      ON root.id=version_row.query_id
     AND root.lifecycle_state<>'staged'
    WHERE version_row.id=p_version_id
      AND version_row.query_id=p_query_id
      AND version_row.version_state='published';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics query version was not found';
    END IF;
    RETURN QUERY
    SELECT dependency.owner_domain,dependency.resource_kind,
        dependency.resource_id,dependency.resource_version_id,
        dependency.owner_generation,dependency.catalog_version,
        dependency.query_contract_version,dependency.policy_version,
        dependency.data_revision_capability,dependency.dependency_sha256
    FROM analytics_query_dependencies AS dependency
    WHERE dependency.query_version_id=p_version_id
    ORDER BY dependency.ordinal;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics query dependencies were not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_dependencies_v1(p_scope_schema name, p_query_id uuid, p_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_query_get_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_get_v1(p_scope_schema name, p_query_id uuid) RETURNS TABLE(query_id uuid, version_id uuid, version_no bigint, root_revision bigint, reference_epoch bigint, version_revision bigint, lifecycle_state text, version_state text, name text, query_document bytea, parameter_document bytea, output_document bytea, manifest_sha256 bytea, cache_policy text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT root.id,version_row.id,version_row.version_no,
        root.row_revision,root.reference_epoch,version_row.row_revision,
        root.lifecycle_state,version_row.version_state,version_row.name,
        version_row.query_document,version_row.parameter_document,
        version_row.output_document,version_row.manifest_sha256,
        version_row.cache_policy,root.created_at,root.updated_at
    FROM analytics_saved_queries AS root
    JOIN analytics_saved_query_versions AS version_row
      ON version_row.id=root.current_draft_version_id
     AND version_row.query_id=root.id
    WHERE root.id=p_query_id AND root.lifecycle_state<>'staged';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics query was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_get_v1(p_scope_schema name, p_query_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_query_get_version_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_get_version_v1(p_scope_schema name, p_query_id uuid, p_version_id uuid) RETURNS TABLE(query_id uuid, version_id uuid, version_no bigint, root_revision bigint, reference_epoch bigint, version_revision bigint, lifecycle_state text, version_state text, name text, query_document bytea, parameter_document bytea, output_document bytea, manifest_sha256 bytea, cache_policy text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT root.id,version_row.id,version_row.version_no,
        root.row_revision,root.reference_epoch,version_row.row_revision,
        root.lifecycle_state,version_row.version_state,version_row.name,
        version_row.query_document,version_row.parameter_document,
        version_row.output_document,version_row.manifest_sha256,
        version_row.cache_policy,root.created_at,version_row.updated_at
    FROM analytics_saved_queries AS root
    JOIN analytics_saved_query_versions AS version_row
      ON version_row.query_id=root.id
    WHERE root.id=p_query_id AND version_row.id=p_version_id
      AND root.lifecycle_state<>'staged';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics query version was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_get_version_v1(p_scope_schema name, p_query_id uuid, p_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_query_latest_published_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_latest_published_v1(p_scope_schema name, p_query_id uuid) RETURNS TABLE(query_id uuid, version_id uuid, version_no bigint, root_revision bigint, reference_epoch bigint, version_revision bigint, lifecycle_state text, version_state text, name text, query_document bytea, parameter_document bytea, output_document bytea, manifest_sha256 bytea, cache_policy text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT root.id, version_row.id, version_row.version_no,
           root.row_revision, root.reference_epoch, version_row.row_revision,
           root.lifecycle_state, version_row.version_state, version_row.name,
           version_row.query_document, version_row.parameter_document,
           version_row.output_document, version_row.manifest_sha256,
           version_row.cache_policy, root.created_at, version_row.updated_at
    FROM analytics_saved_queries AS root
    JOIN LATERAL (
        SELECT candidate.*
        FROM analytics_saved_query_versions AS candidate
        WHERE candidate.query_id = root.id
          AND candidate.version_state IN ('published', 'needs_revalidation')
        ORDER BY candidate.version_no DESC
        LIMIT 1
    ) AS version_row ON true
    WHERE root.id = p_query_id AND root.lifecycle_state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102',
            MESSAGE = 'published analytics query was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_latest_published_v1(p_scope_schema name, p_query_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_query_list_v1(name, integer, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_list_v1(p_scope_schema name, p_limit integer, p_after uuid) RETURNS TABLE(query_id uuid, version_id uuid, version_no bigint, root_revision bigint, reference_epoch bigint, version_revision bigint, lifecycle_state text, version_state text, name text, query_document bytea, parameter_document bytea, output_document bytea, manifest_sha256 bytea, cache_policy text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics query list input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    RETURN QUERY
    SELECT root.id, version_row.id, version_row.version_no,
           root.row_revision, root.reference_epoch, version_row.row_revision,
           root.lifecycle_state, version_row.version_state, version_row.name,
           version_row.query_document, version_row.parameter_document,
           version_row.output_document, version_row.manifest_sha256,
           version_row.cache_policy, root.created_at, root.updated_at
    FROM analytics_saved_queries AS root
    JOIN analytics_saved_query_versions AS version_row
      ON version_row.id = root.current_draft_version_id
     AND version_row.query_id = root.id
    WHERE root.lifecycle_state = 'active'
      AND (p_after IS NULL OR root.id > p_after)
    ORDER BY root.id
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_list_v1(p_scope_schema name, p_limit integer, p_after uuid) OWNER TO harpy_owner;

--
-- Name: analytics_query_publish_core_v1(name, text, uuid, uuid, text, bytea, uuid, uuid, uuid, bigint, bigint, bytea, bytea, bytea, jsonb, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_publish_core_v1(p_scope_schema name, p_operation_kind text, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_query_id uuid, p_draft_version_id uuid, p_next_draft_version_id uuid, p_expected_root_revision bigint, p_expected_draft_revision bigint, p_query_document bytea, p_parameter_document bytea, p_output_document bytea, p_dependencies jsonb, p_manifest_sha256 bytea, p_cache_policy text, p_occurred_at timestamp with time zone) RETURNS TABLE(query_id uuid, version_id uuid, version_no bigint, root_revision bigint, reference_epoch bigint, version_revision bigint, lifecycle_state text, version_state text, name text, query_document bytea, parameter_document bytea, output_document bytea, manifest_sha256 bytea, cache_policy text, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_operations%ROWTYPE;
    v_version_no bigint;
    v_name text;
    v_count integer;
    v_draft_manifest bytea;
BEGIN
    IF p_operation_kind NOT IN ('query_publish', 'query_revalidate') OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_query_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_draft_version_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_next_draft_version_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_expected_root_revision < 1 OR p_expected_draft_revision < 1 OR
       pg_catalog.octet_length(p_query_document) NOT BETWEEN 2 AND 65536 OR
       pg_catalog.octet_length(p_parameter_document) NOT BETWEEN 2 AND 65536 OR
       pg_catalog.octet_length(p_output_document) NOT BETWEEN 2 AND 65536 OR
       pg_catalog.jsonb_typeof(p_dependencies) IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(p_dependencies) NOT BETWEEN 1 AND 32 OR
       pg_catalog.octet_length(p_manifest_sha256) IS DISTINCT FROM 32 OR
       p_cache_policy NOT IN ('none', 'revision_bound') OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics query publish input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:query:publish:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing
    FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id
      AND operation.operation_kind = p_operation_kind
      AND operation.idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.result_version_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103',
                MESSAGE = 'analytics query publish replay differs';
        END IF;
        RETURN QUERY SELECT result.*, true
        FROM analytics_query_get_version_v1(
            p_scope_schema, v_existing.resource_id, v_existing.result_version_id
        ) AS result;
        RETURN;
    END IF;
    SELECT version_row.version_no, version_row.name
    INTO v_version_no, v_name
    FROM analytics_saved_queries AS root
    JOIN analytics_saved_query_versions AS version_row
      ON version_row.id = root.current_draft_version_id
     AND version_row.query_id = root.id
    WHERE root.id = p_query_id AND root.lifecycle_state = 'active'
      AND root.row_revision = p_expected_root_revision
      AND version_row.id = p_draft_version_id
      AND version_row.version_state = 'draft'
      AND version_row.row_revision = p_expected_draft_revision
    FOR UPDATE OF root, version_row;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'analytics query publish revision changed';
    END IF;
    IF EXISTS (SELECT 1 FROM analytics_saved_query_versions
               WHERE id = p_next_draft_version_id) THEN
        RAISE EXCEPTION USING ERRCODE = 'P6104',
            MESSAGE = 'analytics query version identity already exists';
    END IF;
    INSERT INTO analytics_query_dependencies (
        query_version_id, ordinal, owner_domain, resource_kind,
        resource_id, resource_version_id, owner_generation,
        catalog_version, query_contract_version, policy_version,
        data_revision_capability, dependency_sha256, created_at
    )
    SELECT p_draft_version_id, (item.ordinality - 1)::smallint,
        item.value->>'owner_domain', item.value->>'resource_kind',
        (item.value->>'resource_id')::uuid,
        (item.value->>'resource_version_id')::uuid,
        (item.value->>'owner_generation')::bigint,
        (item.value->>'catalog_version')::bigint,
        (item.value->>'query_contract_version')::bigint,
        (item.value->>'policy_version')::bigint,
        COALESCE(item.value->>'data_revision_capability', ''),
        pg_catalog.decode(item.value->>'dependency_sha256', 'hex'),
        p_occurred_at
    FROM pg_catalog.jsonb_array_elements(p_dependencies)
         WITH ORDINALITY AS item(value, ordinality);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count IS DISTINCT FROM pg_catalog.jsonb_array_length(p_dependencies) OR
       (p_cache_policy = 'revision_bound' AND EXISTS (
           SELECT 1 FROM analytics_query_dependencies
           WHERE query_version_id = p_draft_version_id
             AND data_revision_capability = ''
       )) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics query dependency manifest is invalid';
    END IF;
    UPDATE analytics_saved_query_versions
    SET version_state = 'published', row_revision = row_revision + 1,
        query_document = p_query_document, query_sha256 = pg_catalog.sha256(p_query_document),
        parameter_document = p_parameter_document,
        parameter_sha256 = pg_catalog.sha256(p_parameter_document),
        output_document = p_output_document, output_sha256 = pg_catalog.sha256(p_output_document),
        manifest_sha256 = p_manifest_sha256, cache_policy = p_cache_policy,
        updated_by = p_actor_id, updated_at = p_occurred_at,
        published_by = p_actor_id, published_at = p_occurred_at
    WHERE id = p_draft_version_id;
    v_draft_manifest := pg_catalog.sha256(
        p_query_document || p_parameter_document || p_output_document);
    SET CONSTRAINTS analytics_saved_queries_current_draft_fk DEFERRED;
    INSERT INTO analytics_saved_query_versions (
        id, query_id, version_no, version_state, row_revision, name,
        query_document, query_sha256, parameter_document, parameter_sha256,
        output_document, output_sha256, manifest_sha256, cache_policy,
        created_by, updated_by, created_at, updated_at
    ) VALUES (
        p_next_draft_version_id, p_query_id, v_version_no + 1, 'draft', 1, v_name,
        p_query_document, pg_catalog.sha256(p_query_document),
        p_parameter_document, pg_catalog.sha256(p_parameter_document),
        p_output_document, pg_catalog.sha256(p_output_document),
        v_draft_manifest, 'none', p_actor_id, p_actor_id, p_occurred_at, p_occurred_at
    );
    UPDATE analytics_saved_queries
    SET current_draft_version_id = p_next_draft_version_id,
        row_revision = row_revision + 1, updated_by = p_actor_id, updated_at = p_occurred_at
    WHERE id = p_query_id;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key,
        request_sha256, resource_kind, resource_id, result_revision,
        result_sha256, occurred_at, result_version_id
    ) VALUES (
        p_operation_id, p_actor_id, p_operation_kind, p_idempotency_key,
        p_request_sha256, 'query', p_query_id, p_expected_root_revision + 1,
        p_manifest_sha256, p_occurred_at, p_draft_version_id
    );
    RETURN QUERY SELECT result.*, false
    FROM analytics_query_get_version_v1(
        p_scope_schema, p_query_id, p_draft_version_id
    ) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_publish_core_v1(p_scope_schema name, p_operation_kind text, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_query_id uuid, p_draft_version_id uuid, p_next_draft_version_id uuid, p_expected_root_revision bigint, p_expected_draft_revision bigint, p_query_document bytea, p_parameter_document bytea, p_output_document bytea, p_dependencies jsonb, p_manifest_sha256 bytea, p_cache_policy text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

