--
-- Name: analytics_query_root_by_version_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_root_by_version_v1(p_scope_schema name, p_version_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_query_id uuid;
BEGIN
    IF p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_version_id) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics query version identity is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT version_row.query_id
    INTO v_query_id
    FROM analytics_query_versions AS version_row
    JOIN analytics_saved_queries AS root
      ON root.id=version_row.query_id
    WHERE version_row.id=p_version_id
      AND version_row.version_state='published'
      AND root.lifecycle_state='active';
    IF NOT FOUND OR pg_catalog.uuid_extract_version(v_query_id) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics published query version was not found';
    END IF;
    RETURN v_query_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_root_by_version_v1(p_scope_schema name, p_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_query_update_v1(name, uuid, uuid, text, bytea, uuid, bigint, bigint, text, bytea, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_query_update_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_query_id uuid, p_expected_root_revision bigint, p_expected_version_revision bigint, p_name text, p_query_document bytea, p_parameter_document bytea, p_output_document bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(query_id uuid, version_id uuid, version_no bigint, root_revision bigint, reference_epoch bigint, version_revision bigint, lifecycle_state text, version_state text, name text, query_document bytea, parameter_document bytea, output_document bytea, manifest_sha256 bytea, cache_policy text, created_at timestamp with time zone, updated_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing analytics_operations%ROWTYPE;
    v_version_id uuid;
    v_manifest bytea;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_idempotency_key IS NULL OR
       pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.uuid_extract_version(p_query_id) IS DISTINCT FROM 7 OR
       p_expected_root_revision < 1 OR p_expected_version_revision < 1 OR
       pg_catalog.octet_length(p_name) NOT BETWEEN 1 AND 100 OR
       pg_catalog.octet_length(p_query_document) NOT BETWEEN 2 AND 65536 OR
       pg_catalog.octet_length(p_parameter_document) NOT BETWEEN 2 AND 65536 OR
       pg_catalog.octet_length(p_output_document) NOT BETWEEN 2 AND 65536 OR
       NOT pg_catalog.pg_input_is_valid(pg_catalog.convert_from(p_query_document, 'UTF8'), 'jsonb') OR
       NOT pg_catalog.pg_input_is_valid(pg_catalog.convert_from(p_parameter_document, 'UTF8'), 'jsonb') OR
       NOT pg_catalog.pg_input_is_valid(pg_catalog.convert_from(p_output_document, 'UTF8'), 'jsonb') OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics query update input is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:query:update:' || p_actor_id::text || ':' || p_idempotency_key, 6100));
    SELECT operation.* INTO v_existing
    FROM analytics_operations AS operation
    WHERE operation.actor_id = p_actor_id
      AND operation.operation_kind = 'query_update'
      AND operation.idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103',
                MESSAGE = 'analytics query idempotency key was reused';
        END IF;
        RETURN QUERY
        SELECT result.*, true
        FROM analytics_query_get_v1(p_scope_schema, v_existing.resource_id) AS result;
        RETURN;
    END IF;
    SELECT root.current_draft_version_id INTO v_version_id
    FROM analytics_saved_queries AS root
    WHERE root.id = p_query_id AND root.lifecycle_state = 'active'
      AND root.row_revision = p_expected_root_revision
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'analytics query root revision changed';
    END IF;
    PERFORM 1 FROM analytics_saved_query_versions AS version_row
    WHERE version_row.id = v_version_id AND version_row.query_id = p_query_id
      AND version_row.version_state = 'draft'
      AND version_row.row_revision = p_expected_version_revision
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'analytics query draft revision changed';
    END IF;
    v_manifest := pg_catalog.sha256(
        p_query_document || p_parameter_document || p_output_document);
    UPDATE analytics_saved_query_versions
    SET name = p_name, query_document = p_query_document,
        query_sha256 = pg_catalog.sha256(p_query_document),
        parameter_document = p_parameter_document,
        parameter_sha256 = pg_catalog.sha256(p_parameter_document),
        output_document = p_output_document,
        output_sha256 = pg_catalog.sha256(p_output_document),
        manifest_sha256 = v_manifest, cache_policy = 'none',
        row_revision = row_revision + 1,
        updated_by = p_actor_id, updated_at = p_occurred_at
    WHERE id = v_version_id;
    UPDATE analytics_saved_queries
    SET row_revision = row_revision + 1,
        updated_by = p_actor_id, updated_at = p_occurred_at
    WHERE id = p_query_id;
    INSERT INTO analytics_operations (
        operation_id, actor_id, operation_kind, idempotency_key,
        request_sha256, resource_kind, resource_id, result_revision,
        result_sha256, occurred_at
    ) VALUES (
        p_operation_id, p_actor_id, 'query_update', p_idempotency_key,
        p_request_sha256, 'query', p_query_id,
        p_expected_root_revision + 1, v_manifest, p_occurred_at
    );
    RETURN QUERY
    SELECT result.*, false
    FROM analytics_query_get_v1(p_scope_schema, p_query_id) AS result;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_query_update_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_idempotency_key text, p_request_sha256 bytea, p_query_id uuid, p_expected_root_revision bigint, p_expected_version_revision bigint, p_name text, p_query_document bytea, p_parameter_document bytea, p_output_document bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_reference_register_v1(name, uuid, uuid, text, uuid, text, text, uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_reference_register_v1(p_scope_schema name, p_reference_id uuid, p_actor_id uuid, p_target_kind text, p_target_id uuid, p_source_module text, p_source_kind text, p_source_id uuid, p_source_version_id uuid, p_usage text, p_created_at timestamp with time zone) RETURNS TABLE(reference_id uuid, state text, created_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_existing analytics_inbound_references%ROWTYPE;
    v_target_ready boolean;
BEGIN
    IF pg_catalog.uuid_extract_version(p_reference_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR
       p_actor_id='00000000-0000-0000-0000-000000000000'::uuid OR
       p_target_kind NOT IN (
           'query_version','dashboard_version','publication_release'
       ) OR pg_catalog.uuid_extract_version(p_target_id) IS DISTINCT FROM 7 OR
       p_source_module!~'^[a-z][a-z0-9_]{0,63}$' OR
       p_source_kind!~'^[a-z][a-z0-9_.-]{0,63}$' OR
       pg_catalog.uuid_extract_version(p_source_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_source_version_id)
           IS DISTINCT FROM 7 OR
       p_usage NOT IN ('read','write','schema','lifecycle') OR
       p_created_at IS NULL OR NOT pg_catalog.isfinite(p_created_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics reference registration is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'analytics:reference:'||p_target_kind||':'||p_target_id::text,6100
    ));
    SELECT * INTO v_existing
    FROM analytics_inbound_references AS reference_row
    WHERE reference_row.reference_id=p_reference_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing.target_kind IS DISTINCT FROM p_target_kind OR
           v_existing.target_id IS DISTINCT FROM p_target_id OR
           v_existing.source_module IS DISTINCT FROM p_source_module OR
           v_existing.source_kind IS DISTINCT FROM p_source_kind OR
           v_existing.source_id IS DISTINCT FROM p_source_id OR
           v_existing.source_version_id IS DISTINCT FROM p_source_version_id OR
           v_existing.usage IS DISTINCT FROM p_usage THEN
            RAISE EXCEPTION USING ERRCODE='P6103',
                MESSAGE='analytics reference identity was reused';
        END IF;
        RETURN QUERY SELECT v_existing.reference_id,v_existing.state,
            v_existing.created_at,true;
        RETURN;
    END IF;
    v_target_ready:=false;
    IF p_target_kind='query_version' THEN
        SELECT true INTO v_target_ready
        FROM analytics_saved_query_versions AS version_row
        JOIN analytics_saved_queries AS root
          ON root.id=version_row.query_id
         AND root.lifecycle_state='active'
        WHERE version_row.id=p_target_id
          AND version_row.version_state IN ('published','needs_revalidation')
        FOR UPDATE OF root,version_row;
    ELSIF p_target_kind='dashboard_version' THEN
        SELECT true INTO v_target_ready
        FROM analytics_dashboard_versions AS version_row
        JOIN analytics_dashboards AS root
          ON root.id=version_row.dashboard_id
         AND root.lifecycle_state='active'
        WHERE version_row.id=p_target_id
          AND version_row.version_state='published'
        FOR UPDATE OF root,version_row;
    ELSE
        SELECT true INTO v_target_ready
        FROM analytics_publication_releases AS release
        WHERE release.id=p_target_id AND release.lifecycle_state='active'
        FOR UPDATE;
    END IF;
    IF NOT COALESCE(v_target_ready,false) THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics reference target is not active';
    END IF;
    BEGIN
        INSERT INTO analytics_inbound_references(
            reference_id,target_kind,target_id,source_module,source_kind,
            source_id,source_version_id,usage,state,created_at
        ) VALUES (
            p_reference_id,p_target_kind,p_target_id,p_source_module,
            p_source_kind,p_source_id,p_source_version_id,p_usage,
            'active',p_created_at
        );
    EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION USING ERRCODE='P6103',
            MESSAGE='analytics reference already exists';
    END;
    RETURN QUERY SELECT p_reference_id,'active'::text,p_created_at,false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_reference_register_v1(p_scope_schema name, p_reference_id uuid, p_actor_id uuid, p_target_kind text, p_target_id uuid, p_source_module text, p_source_kind text, p_source_id uuid, p_source_version_id uuid, p_usage text, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_reference_release_v1(name, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_reference_release_v1(p_scope_schema name, p_reference_id uuid, p_actor_id uuid, p_released_at timestamp with time zone) RETURNS TABLE(reference_id uuid, state text, released_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_reference analytics_inbound_references%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_reference_id) IS DISTINCT FROM 7 OR
       p_actor_id IS NULL OR
       p_actor_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_released_at IS NULL OR NOT pg_catalog.isfinite(p_released_at) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics reference release is invalid';
    END IF;
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    SELECT reference_row.* INTO v_reference
    FROM analytics_inbound_references AS reference_row
    WHERE reference_row.reference_id = p_reference_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6102',
            MESSAGE = 'analytics reference was not found';
    END IF;
    IF v_reference.state = 'released' THEN
        IF v_reference.released_by IS DISTINCT FROM p_actor_id THEN
            RAISE EXCEPTION USING ERRCODE = 'P6103',
                MESSAGE = 'analytics reference release actor differs';
        END IF;
        RETURN QUERY SELECT v_reference.reference_id,v_reference.state,
            v_reference.released_at,true;
        RETURN;
    END IF;
    IF p_released_at < v_reference.created_at THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'analytics reference release time is invalid';
    END IF;
    UPDATE analytics_inbound_references
    SET state = 'released',released_by = p_actor_id,released_at = p_released_at
    WHERE analytics_inbound_references.reference_id = p_reference_id;
    RETURN QUERY SELECT p_reference_id,'released'::text,p_released_at,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_reference_release_v1(p_scope_schema name, p_reference_id uuid, p_actor_id uuid, p_released_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: analytics_reject_mutation_retention_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_reject_mutation_retention_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' AND analytics_retention_delete_allowed_v1(pg_catalog.pg_backend_pid()) THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'analytics immutable row cannot be changed';
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_reject_mutation_retention_v1() OWNER TO harpy_owner;

