--
-- Name: analytics_resource_manifest_v1(name, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_resource_manifest_v1(p_scope_schema name, p_resource_kind text, p_version_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_manifest bytea;
BEGIN
    PERFORM analytics_assert_current_authority_v1(p_scope_schema);
    IF p_resource_kind='query' THEN
        SELECT version_row.manifest_sha256 INTO v_manifest
        FROM analytics_saved_query_versions AS version_row
        JOIN analytics_saved_queries AS root
          ON root.id=version_row.query_id
         AND root.lifecycle_state='active'
        WHERE version_row.id=p_version_id
          AND version_row.version_state='published';
    ELSIF p_resource_kind='dashboard' THEN
        SELECT version_row.manifest_sha256 INTO v_manifest
        FROM analytics_dashboard_versions AS version_row
        JOIN analytics_dashboards AS root
          ON root.id=version_row.dashboard_id
         AND root.lifecycle_state='active'
        WHERE version_row.id=p_version_id
          AND version_row.version_state='published';
    ELSE
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='analytics resource kind is invalid';
    END IF;
    IF pg_catalog.octet_length(v_manifest) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='analytics immutable resource was not found';
    END IF;
    RETURN v_manifest;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_resource_manifest_v1(p_scope_schema name, p_resource_kind text, p_version_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_retention_delete_allowed_v1(integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_retention_delete_allowed_v1(p_backend_pid integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_backend_pid IS DISTINCT FROM pg_catalog.pg_backend_pid() THEN
        RETURN false;
    END IF;
    RETURN EXISTS (
        SELECT 1 FROM analytics_retention_contexts AS retention_context
        WHERE retention_context.backend_pid = pg_catalog.pg_backend_pid()
          AND retention_context.transaction_id = pg_catalog.pg_current_xact_id()
    ) AND NOT EXISTS (
        SELECT 1 FROM analytics_legal_holds AS legal_hold
        WHERE legal_hold.state = 'active'
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_retention_delete_allowed_v1(p_backend_pid integer) OWNER TO harpy_owner;

--
-- Name: analytics_retention_purge_audits_v1(timestamp with time zone, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_retention_purge_audits_v1(p_execution_cutoff timestamp with time zone, p_audit_cutoff timestamp with time zone, p_capability_cutoff timestamp with time zone, p_limit integer) RETURNS TABLE(executions_purged bigint, audits_purged bigint, capabilities_purged bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_remaining integer;
    v_approval_count bigint;
    v_operation_count bigint;
BEGIN
    IF p_execution_cutoff IS NULL OR NOT pg_catalog.isfinite(p_execution_cutoff) OR
       p_audit_cutoff IS NULL OR NOT pg_catalog.isfinite(p_audit_cutoff) OR
       p_capability_cutoff IS NULL OR NOT pg_catalog.isfinite(p_capability_cutoff) OR
       p_limit NOT BETWEEN 1 AND 100 OR
       NOT analytics_retention_delete_allowed_v1(pg_catalog.pg_backend_pid()) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics audit retention authority is invalid';
    END IF;
    WITH candidates AS MATERIALIZED (
        SELECT execution.execution_id
        FROM analytics_execution_audits AS execution
        WHERE execution.occurred_at <= p_execution_cutoff
        ORDER BY execution.occurred_at,execution.execution_id
        FOR UPDATE SKIP LOCKED LIMIT p_limit
    )
    DELETE FROM analytics_execution_audits AS execution
    USING candidates WHERE execution.execution_id = candidates.execution_id;
    GET DIAGNOSTICS executions_purged = ROW_COUNT;
    v_remaining := p_limit - executions_purged::integer;
    IF v_remaining < 1 THEN
        audits_purged := 0; capabilities_purged := 0;
        RETURN NEXT; RETURN;
    END IF;
    WITH candidates AS MATERIALIZED (
        SELECT approval.release_id
        FROM analytics_publication_approvals AS approval
        WHERE approval.approved_at <= p_audit_cutoff
        ORDER BY approval.approved_at,approval.release_id
        FOR UPDATE SKIP LOCKED LIMIT v_remaining
    )
    DELETE FROM analytics_publication_approvals AS approval
    USING candidates WHERE approval.release_id = candidates.release_id;
    GET DIAGNOSTICS v_approval_count = ROW_COUNT;
    v_remaining := v_remaining - v_approval_count::integer;
    v_operation_count := 0;
    IF v_remaining > 0 THEN
        WITH candidates AS MATERIALIZED (
            SELECT operation.operation_id
            FROM analytics_operations AS operation
            WHERE operation.occurred_at <= p_audit_cutoff
            ORDER BY operation.occurred_at,operation.operation_id
            FOR UPDATE SKIP LOCKED LIMIT v_remaining
        )
        DELETE FROM analytics_operations AS operation
        USING candidates WHERE operation.operation_id = candidates.operation_id;
        GET DIAGNOSTICS v_operation_count = ROW_COUNT;
        v_remaining := v_remaining - v_operation_count::integer;
    END IF;
    audits_purged := v_approval_count + v_operation_count;
    capabilities_purged := 0;
    IF v_remaining > 0 THEN
        WITH candidates AS MATERIALIZED (
            SELECT token.release_id
            FROM analytics_capability_tokens AS token
            WHERE token.revoked_at IS NOT NULL
              AND token.expires_at <= p_capability_cutoff
            ORDER BY token.expires_at,token.release_id
            FOR UPDATE SKIP LOCKED LIMIT v_remaining
        )
        DELETE FROM analytics_capability_tokens AS token
        USING candidates WHERE token.release_id = candidates.release_id;
        GET DIAGNOSTICS capabilities_purged = ROW_COUNT;
    END IF;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_retention_purge_audits_v1(p_execution_cutoff timestamp with time zone, p_audit_cutoff timestamp with time zone, p_capability_cutoff timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: analytics_retention_purge_drafts_v1(timestamp with time zone, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_retention_purge_drafts_v1(p_cutoff timestamp with time zone, p_limit integer) RETURNS TABLE(query_drafts_purged bigint, dashboard_drafts_purged bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_query_versions jsonb;
    v_dashboard_versions jsonb;
    v_remaining integer;
BEGIN
    IF p_cutoff IS NULL OR NOT pg_catalog.isfinite(p_cutoff) OR
       p_limit NOT BETWEEN 1 AND 100 OR
       NOT analytics_retention_delete_allowed_v1(pg_catalog.pg_backend_pid()) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics draft retention authority is invalid';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(candidate.version_id::text),'[]'::jsonb)
    INTO v_query_versions
    FROM (
        SELECT version_row.id AS version_id
        FROM analytics_saved_queries AS root
        JOIN analytics_saved_query_versions AS version_row
          ON version_row.id = root.current_draft_version_id
        WHERE root.lifecycle_state = 'retired' AND root.updated_at <= p_cutoff
          AND version_row.version_state = 'draft'
          AND NOT EXISTS (
              SELECT 1 FROM analytics_inbound_references AS reference_row
              WHERE reference_row.target_kind = 'query_version'
                AND reference_row.target_id = version_row.id
                AND reference_row.state = 'active'
          )
        ORDER BY root.updated_at,root.id
        FOR UPDATE OF root,version_row SKIP LOCKED LIMIT p_limit
    ) AS candidate;
    UPDATE analytics_saved_queries SET current_draft_version_id = NULL
    WHERE v_query_versions ? current_draft_version_id::text;
    DELETE FROM analytics_query_dependencies
    WHERE v_query_versions ? query_version_id::text;
    DELETE FROM analytics_saved_query_versions
    WHERE v_query_versions ? id::text;
    GET DIAGNOSTICS query_drafts_purged = ROW_COUNT;
    DELETE FROM analytics_saved_queries AS root
    WHERE root.lifecycle_state = 'retired' AND root.current_draft_version_id IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM analytics_saved_query_versions AS version_row
          WHERE version_row.query_id = root.id
      );
    v_remaining := p_limit - query_drafts_purged::integer;
    IF v_remaining < 1 THEN
        dashboard_drafts_purged := 0;
        RETURN NEXT;
        RETURN;
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(candidate.version_id::text),'[]'::jsonb)
    INTO v_dashboard_versions
    FROM (
        SELECT version_row.id AS version_id
        FROM analytics_dashboards AS root
        JOIN analytics_dashboard_versions AS version_row
          ON version_row.id = root.current_draft_version_id
        WHERE root.lifecycle_state = 'retired' AND root.updated_at <= p_cutoff
          AND version_row.version_state = 'draft'
          AND NOT EXISTS (
              SELECT 1 FROM analytics_inbound_references AS reference_row
              WHERE reference_row.target_kind = 'dashboard_version'
                AND reference_row.target_id = version_row.id
                AND reference_row.state = 'active'
          )
        ORDER BY root.updated_at,root.id
        FOR UPDATE OF root,version_row SKIP LOCKED LIMIT v_remaining
    ) AS candidate;
    UPDATE analytics_dashboards SET current_draft_version_id = NULL
    WHERE v_dashboard_versions ? current_draft_version_id::text;
    DELETE FROM analytics_dashboard_widgets
    WHERE v_dashboard_versions ? dashboard_version_id::text;
    DELETE FROM analytics_dashboard_versions
    WHERE v_dashboard_versions ? id::text;
    GET DIAGNOSTICS dashboard_drafts_purged = ROW_COUNT;
    DELETE FROM analytics_dashboards AS root
    WHERE root.lifecycle_state = 'retired' AND root.current_draft_version_id IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM analytics_dashboard_versions AS version_row
          WHERE version_row.dashboard_id = root.id
      );
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_retention_purge_drafts_v1(p_cutoff timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: analytics_retention_purge_releases_v1(timestamp with time zone, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_retention_purge_releases_v1(p_cutoff timestamp with time zone, p_limit integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_release_ids jsonb;
    v_eligible_ids jsonb;
    v_release_text text;
    v_tenant_id uuid;
    v_purged bigint;
BEGIN
    IF p_cutoff IS NULL OR NOT pg_catalog.isfinite(p_cutoff) OR
       p_limit NOT BETWEEN 1 AND 100 OR
       NOT analytics_retention_delete_allowed_v1(pg_catalog.pg_backend_pid()) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics release retention authority is invalid';
    END IF;
    SELECT identity_row.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity_row
    WHERE identity_row.singleton
      AND identity_row.schema_name = pg_catalog.current_schema();
    SELECT COALESCE(pg_catalog.jsonb_agg(candidate.release_id::text),'[]'::jsonb)
    INTO v_release_ids
    FROM (
        SELECT release.id AS release_id
        FROM analytics_publication_releases AS release
        WHERE release.lifecycle_state IN ('revoked','retired')
          AND release.revoked_at <= p_cutoff
          AND NOT EXISTS (
              SELECT 1 FROM analytics_inbound_references AS reference_row
              WHERE reference_row.target_kind = 'publication_release'
                AND reference_row.target_id = release.id
                AND reference_row.state = 'active'
          )
          AND NOT EXISTS (
              SELECT 1 FROM analytics_execution_audits AS execution
              WHERE execution.release_id = release.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM analytics_capability_tokens AS token
              WHERE token.release_id = release.id
          )
        ORDER BY release.revoked_at,release.id
        FOR UPDATE OF release SKIP LOCKED LIMIT p_limit
    ) AS candidate;
    v_eligible_ids := '[]'::jsonb;
    FOR v_release_text IN
        SELECT pg_catalog.jsonb_array_elements_text(v_release_ids)
    LOOP
        IF platform.analytics_public_retention_release_v1(
            v_tenant_id,v_release_text::uuid,p_cutoff
        ) THEN
            v_eligible_ids := v_eligible_ids || pg_catalog.jsonb_build_array(v_release_text);
        END IF;
    END LOOP;
    DELETE FROM analytics_publication_releases
    WHERE v_eligible_ids ? id::text;
    GET DIAGNOSTICS v_purged = ROW_COUNT;
    RETURN v_purged;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_retention_purge_releases_v1(p_cutoff timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: analytics_retention_purge_versions_v1(timestamp with time zone, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_retention_purge_versions_v1(p_cutoff timestamp with time zone, p_limit integer) RETURNS TABLE(query_versions_purged bigint, dashboard_versions_purged bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_query_versions jsonb;
    v_dashboard_versions jsonb;
    v_remaining integer;
BEGIN
    IF p_cutoff IS NULL OR NOT pg_catalog.isfinite(p_cutoff) OR
       p_limit NOT BETWEEN 1 AND 100 OR
       NOT analytics_retention_delete_allowed_v1(pg_catalog.pg_backend_pid()) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'analytics version retention authority is invalid';
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(candidate.version_id::text),'[]'::jsonb)
    INTO v_query_versions
    FROM (
        SELECT version_row.id AS version_id
        FROM analytics_saved_query_versions AS version_row
        WHERE version_row.version_state = 'retired' AND version_row.updated_at <= p_cutoff
          AND NOT EXISTS (
              SELECT 1 FROM analytics_inbound_references AS reference_row
              WHERE reference_row.target_kind = 'query_version'
                AND reference_row.target_id = version_row.id
                AND reference_row.state = 'active'
          )
          AND NOT EXISTS (
              SELECT 1 FROM analytics_publication_releases AS release
              WHERE release.resource_kind = 'query'
                AND release.resource_version_id = version_row.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM analytics_dashboard_widgets AS widget
              WHERE widget.query_version_id = version_row.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM analytics_saved_queries AS root
              WHERE root.current_draft_version_id = version_row.id
          )
        ORDER BY version_row.updated_at,version_row.id
        FOR UPDATE OF version_row SKIP LOCKED LIMIT p_limit
    ) AS candidate;
    DELETE FROM analytics_query_dependencies
    WHERE v_query_versions ? query_version_id::text;
    DELETE FROM analytics_saved_query_versions
    WHERE v_query_versions ? id::text;
    GET DIAGNOSTICS query_versions_purged = ROW_COUNT;
    DELETE FROM analytics_saved_queries AS root
    WHERE root.lifecycle_state = 'retired' AND root.current_draft_version_id IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM analytics_saved_query_versions AS version_row
          WHERE version_row.query_id = root.id
      );
    v_remaining := p_limit - query_versions_purged::integer;
    IF v_remaining < 1 THEN
        dashboard_versions_purged := 0;
        RETURN NEXT;
        RETURN;
    END IF;
    SELECT COALESCE(pg_catalog.jsonb_agg(candidate.version_id::text),'[]'::jsonb)
    INTO v_dashboard_versions
    FROM (
        SELECT version_row.id AS version_id
        FROM analytics_dashboard_versions AS version_row
        WHERE version_row.version_state = 'retired' AND version_row.updated_at <= p_cutoff
          AND NOT EXISTS (
              SELECT 1 FROM analytics_inbound_references AS reference_row
              WHERE reference_row.target_kind = 'dashboard_version'
                AND reference_row.target_id = version_row.id
                AND reference_row.state = 'active'
          )
          AND NOT EXISTS (
              SELECT 1 FROM analytics_publication_releases AS release
              WHERE release.resource_kind = 'dashboard'
                AND release.resource_version_id = version_row.id
          )
          AND NOT EXISTS (
              SELECT 1 FROM analytics_dashboards AS root
              WHERE root.current_draft_version_id = version_row.id
          )
        ORDER BY version_row.updated_at,version_row.id
        FOR UPDATE OF version_row SKIP LOCKED LIMIT v_remaining
    ) AS candidate;
    DELETE FROM analytics_dashboard_widgets
    WHERE v_dashboard_versions ? dashboard_version_id::text;
    DELETE FROM analytics_dashboard_versions
    WHERE v_dashboard_versions ? id::text;
    GET DIAGNOSTICS dashboard_versions_purged = ROW_COUNT;
    DELETE FROM analytics_dashboards AS root
    WHERE root.lifecycle_state = 'retired' AND root.current_draft_version_id IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM analytics_dashboard_versions AS version_row
          WHERE version_row.dashboard_id = root.id
      );
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_retention_purge_versions_v1(p_cutoff timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract_id text;
    v_procedure_oid bigint;
    v_procedure_signature text;
    v_expected_signature text;
    v_already_applied boolean;
    v_applied_count bigint;
    v_key_sha text;
    v_state_sha text;
    v_projected_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption composite principal denied';
    END IF;
    v_batch:=analytics_v1_adoption_batch_decode_v1(
      p_change_batch_bytes,p_batch_sha256,p_batch_bytes);
    IF NOT analytics_v1_adoption_batch_assert_v1(
      v_batch,p_operation_id,p_run_id,p_scope_kind,p_scope_id,
      p_relation_ordinal,p_checkpoint_key,p_snapshot_name,
      p_snapshot_lsn,p_received_lsn,p_commit_lsn,p_final_lsn,
      p_source_xid,p_batch_ordinal,p_checkpoint_state,p_last_key
    ) THEN
      RAISE EXCEPTION USING ERRCODE='22000',
        MESSAGE='Analytics V1 adoption batch assertion failed';
    END IF;
    SELECT prepared.procedure_contract_id,prepared.procedure_oid,
      prepared.procedure_signature,prepared.already_applied,
      prepared.applied_count,prepared.key_state_sha256,prepared.state_sha256
    INTO STRICT v_contract_id,v_procedure_oid,v_procedure_signature,
      v_already_applied,v_applied_count,v_key_sha,v_state_sha
    FROM platform.cutover_prepare_batch_v1(
      p_operation_id,p_run_id,p_scope_kind,p_scope_id,
      p_relation_ordinal,p_checkpoint_key,p_batch_ordinal,
      p_commit_lsn,p_source_xid,p_batch_sha256,p_lease_manifest_sha256
    ) AS prepared;
    v_expected_signature:=pg_catalog.format(
      '%I.analytics_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)',
      pg_catalog.current_schema());
    IF v_contract_id IS DISTINCT FROM 'analytics.v1_adoption.v1' OR
       v_procedure_oid IS DISTINCT FROM
        'analytics_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure_signature IS DISTINCT FROM v_expected_signature THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption procedure binding differs';
    END IF;
    IF v_already_applied THEN
      IF v_applied_count IS DISTINCT FROM
           pg_catalog.jsonb_array_length(v_batch->'changes') OR
         v_key_sha!~'^[0-9a-f]{64}$' OR v_state_sha!~'^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22000',
          MESSAGE='Analytics V1 adoption replay result differs';
      END IF;
      RETURN QUERY SELECT v_applied_count,v_key_sha,v_state_sha;
      RETURN;
    END IF;
    SELECT result.applied_count,result.key_state_sha256,result.state_sha256
    INTO STRICT v_applied_count,v_key_sha,v_state_sha
    FROM analytics_v1_adoption_apply_v1(
      p_operation_id,p_run_id,p_scope_kind,p_scope_id,p_relation_ordinal,
      p_checkpoint_key,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
      p_source_xid,p_batch_ordinal,v_batch,p_batch_sha256
    ) AS result;
    IF v_applied_count IS DISTINCT FROM
         pg_catalog.jsonb_array_length(v_batch->'changes') OR
       v_key_sha!~'^[0-9a-f]{64}$' OR v_state_sha!~'^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION USING ERRCODE='22000',
        MESSAGE='Analytics V1 adoption owner result invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
      p_operation_id,p_run_id,p_relation_ordinal,p_checkpoint_key,
      p_snapshot_name,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
      p_final_lsn,p_source_xid,p_batch_ordinal,p_checkpoint_state,
      p_last_key,p_batch_sha256,p_batch_bytes,v_applied_count,
      v_key_sha,v_state_sha);
    IF p_checkpoint_state='complete' THEN
      v_projected_sha:=analytics_v1_adoption_finalize_v1(
        p_operation_id,p_run_id,p_scope_id);
      IF v_projected_sha IS DISTINCT FROM v_state_sha THEN
        RAISE EXCEPTION USING ERRCODE='55000',
          MESSAGE='Analytics V1 adoption projected digest differs';
      END IF;
    END IF;
    RETURN QUERY SELECT v_applied_count,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_change jsonb;
    v_payload jsonb;
    v_lease text;
    v_rows bigint;
    v_applied bigint;
    v_root text;
    v_now timestamptz;
BEGIN
    v_applied:=0;
    v_now:=pg_catalog.date_trunc(
      'microseconds',pg_catalog.transaction_timestamp());
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind IS DISTINCT FROM 'tenant' OR p_relation_ordinal<>1 OR
       p_checkpoint_key IS DISTINCT FROM 'openapi_endpoints' OR
       p_batch_sha256!~'^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics V1 adoption apply principal denied';
    END IF;
    SELECT operation.lease_manifest_sha256 INTO STRICT v_lease
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='analytics' AND operation.domain='analytics'
      AND operation.state IN ('copying','shadow','quiescing')
    FOR SHARE;
    FOR v_change IN
      SELECT item.value FROM pg_catalog.jsonb_array_elements(
        p_change_batch->'changes'
      ) WITH ORDINALITY AS item(value,position) ORDER BY item.position
    LOOP
      v_payload:=CASE v_change->>'kind'
        WHEN 'delete' THEN v_change->'before' ELSE v_change->'after' END;
      INSERT INTO analytics_v1_adoption_stage(
        operation_id,run_id,legacy_endpoint_id,source_sha256,source_document,
        disposition,reason_code,target_document,target_sha256,removed,
        source_xid,commit_lsn,batch_ordinal,change_ordinal,recorded_at
      ) VALUES (
        p_operation_id,p_run_id,
        (v_payload->'source_document'->>'id')::uuid,
        pg_catalog.decode(v_payload->>'source_sha256','hex'),
        v_payload->'source_document',v_payload->>'disposition',
        v_payload->>'reason_code',
        NULLIF(v_payload->'target_document','null'::jsonb),
        CASE WHEN v_payload->'target_sha256'='null'::jsonb THEN NULL
             ELSE pg_catalog.decode(v_payload->>'target_sha256','hex') END,
        v_change->>'kind'='delete',p_source_xid,p_commit_lsn,p_batch_ordinal,
        (v_change->>'ordinal')::smallint,v_now
      ) ON CONFLICT(operation_id,run_id,legacy_endpoint_id) DO UPDATE
      SET source_sha256=EXCLUDED.source_sha256,
        source_document=EXCLUDED.source_document,
        disposition=EXCLUDED.disposition,reason_code=EXCLUDED.reason_code,
        target_document=EXCLUDED.target_document,
        target_sha256=EXCLUDED.target_sha256,removed=EXCLUDED.removed,
        source_xid=EXCLUDED.source_xid,commit_lsn=EXCLUDED.commit_lsn,
        batch_ordinal=EXCLUDED.batch_ordinal,
        change_ordinal=EXCLUDED.change_ordinal,recorded_at=EXCLUDED.recorded_at
      WHERE (analytics_v1_adoption_stage.batch_ordinal,
             analytics_v1_adoption_stage.change_ordinal)
           <(EXCLUDED.batch_ordinal,EXCLUDED.change_ordinal);
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE='55000',
          MESSAGE='Analytics V1 adoption endpoint checkpoint regressed';
      END IF;
      v_applied:=v_applied+1;
      INSERT INTO platform.applied_change_receipts(
        receipt_id,operation_id,run_id,manifest_sha256,source_xid,
        source_commit_lsn,relation_ordinal,change_ordinal,checkpoint_key,
        mutation_kind,mutation_sha256,applied_at
      ) VALUES (
        pg_catalog.gen_random_uuid(),p_operation_id,p_run_id,v_lease,
        p_source_xid,p_commit_lsn,1,
        (((p_batch_ordinal-1)::bigint*1000)+v_applied)::integer,
        'openapi_endpoints',v_change->>'kind',
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
          p_batch_sha256||':'||v_change::text,'UTF8'
        )),'hex'),v_now
      );
    END LOOP;
    SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
      pg_catalog.uuid_send(stage.legacy_endpoint_id)||stage.target_sha256,
      ''::bytea ORDER BY stage.legacy_endpoint_id),''::bytea)),'hex')
    INTO v_root FROM analytics_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed AND stage.disposition='adopted';
    RETURN QUERY SELECT v_applied,v_root,v_root;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_batch_assert_v1(jsonb, uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_count integer;
    v_generation bigint;
    v_evidence text;
BEGIN
    v_count:=pg_catalog.jsonb_array_length(p_batch->'changes');
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics V1 adoption evidence principal denied';
    END IF;
    SELECT operation.cutover_generation INTO v_generation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind=p_scope_kind AND operation.scope_id=p_scope_id
      AND operation.group_id='analytics' AND operation.domain='analytics'
      AND operation.state IN ('copying','shadow','quiescing');
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics V1 adoption operation binding differs';
    END IF;
    IF p_scope_kind IS DISTINCT FROM 'tenant' OR p_relation_ordinal<>1 OR
       p_checkpoint_key IS DISTINCT FROM 'openapi_endpoints' OR
       p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_checkpoint_state NOT IN ('initial_copy','delta','complete') OR
       (p_checkpoint_state='complete') IS DISTINCT FROM (p_final_lsn IS NOT NULL) OR
       (v_count=0 AND (
         p_checkpoint_state<>'complete' OR p_commit_lsn IS DISTINCT FROM p_final_lsn
       )) OR NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS tenant
        WHERE tenant.singleton AND tenant.tenant_id=p_scope_id
          AND tenant.schema_name=pg_catalog.current_schema()
          AND tenant.origin='v1_adopted'
       ) OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS expected
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
          AND expected.relation_ordinal=1
          AND expected.checkpoint_key='openapi_endpoints'
       ) OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_groups AS fence
        WHERE fence.scope_kind='tenant' AND fence.scope_id=p_scope_id
          AND fence.group_id='analytics' AND fence.generation=v_generation
          AND fence.state IN ('shadow','quiescing')
          AND fence.writer=CASE fence.state WHEN 'shadow' THEN 'v1' ELSE 'none' END
       ) OR NOT EXISTS (
        SELECT 1 FROM platform.domain_cutovers AS fence
        WHERE fence.scope_kind='tenant' AND fence.scope_id=p_scope_id
          AND fence.domain='analytics' AND fence.generation=v_generation
          AND fence.state IN ('shadow','quiescing')
          AND fence.writer=CASE fence.state WHEN 'shadow' THEN 'v1' ELSE 'none' END
       ) OR (SELECT pg_catalog.array_agg(member.domain ORDER BY member.ordinal)
             FROM platform.cutover_group_members AS member
             WHERE member.scope_kind='tenant' AND member.scope_id=p_scope_id
               AND member.group_id='analytics')
          IS DISTINCT FROM ARRAY['analytics']::text[] OR
       (p_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (p_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       p_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (p_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       (p_batch->>'relation_ordinal')::smallint IS DISTINCT FROM 1 OR
       p_batch->>'checkpoint_key' IS DISTINCT FROM 'openapi_endpoints' OR
       p_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state OR
       p_batch->'last_key' IS DISTINCT FROM p_last_key OR
       p_batch->'source_position'->>'snapshot_name' IS DISTINCT FROM p_snapshot_name OR
       (p_batch->'source_position'->>'snapshot_lsn')::pg_lsn
         IS DISTINCT FROM p_snapshot_lsn OR
       (p_batch->'source_position'->>'received_lsn')::pg_lsn
         IS DISTINCT FROM p_received_lsn OR
       (p_batch->'source_position'->>'commit_lsn')::pg_lsn
         IS DISTINCT FROM p_commit_lsn OR
       (p_batch->'source_position'->>'final_lsn')::pg_lsn
         IS DISTINCT FROM p_final_lsn OR
       (p_batch->'source_position'->>'source_xid')::xid8
         IS DISTINCT FROM p_source_xid OR
       (p_batch->'source_position'->>'batch_ordinal')::integer
         IS DISTINCT FROM p_batch_ordinal OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change(value)
        WHERE COALESCE(change.value->'after',change.value->'before')
          ->'source_document'->>'tenant_id'<>p_scope_id::text
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics V1 adoption batch evidence differs';
    END IF;
    IF p_checkpoint_state='complete' THEN
        IF pg_catalog.jsonb_typeof(p_last_key) IS DISTINCT FROM 'object' OR
           (SELECT pg_catalog.array_agg(key ORDER BY key)
            FROM pg_catalog.jsonb_object_keys(p_last_key) AS key)
           IS DISTINCT FROM ARRAY[
             'dependency_sha256','evidence_sha256','public_approval_sha256',
             'rollback_sha256','source_count','source_root_sha256',
             'target_count','target_root_sha256','watermark_sha256',
             'zero_hit_sha256'
           ]::text[] OR
           (p_last_key->>'source_count')::bigint<0 OR
           (p_last_key->>'target_count')::bigint<0 OR EXISTS (
            SELECT 1 FROM pg_catalog.jsonb_each_text(p_last_key) AS item
            WHERE item.key NOT IN ('source_count','target_count')
              AND item.value!~'^[0-9a-f]{64}$'
           ) THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics V1 adoption terminal evidence invalid';
        END IF;
        v_evidence:=pg_catalog.encode(pg_catalog.sha256(
          pg_catalog.convert_to('analytics-v1-adoption-evidence.v1','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'source_count','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'source_root_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'target_count','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'target_root_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'dependency_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'public_approval_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'zero_hit_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'rollback_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'watermark_sha256','UTF8')
        ),'hex');
        IF v_evidence IS DISTINCT FROM p_last_key->>'evidence_sha256' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Analytics V1 adoption terminal evidence digest differs';
        END IF;
    END IF;
    RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE='22023',
        MESSAGE='Analytics V1 adoption typed evidence invalid';
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_batch_decode_v1(bytea, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_actual_bytes bigint;
    v_change_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Analytics V1 adoption batch principal denied';
    END IF;
    v_actual_bytes:=pg_catalog.octet_length(p_change_batch_bytes);
    IF p_batch_bytes IS DISTINCT FROM v_actual_bytes OR
       v_actual_bytes NOT BETWEEN 2 AND 8388608 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes),'hex')
         IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics V1 adoption batch digest invalid';
    END IF;
    v_batch:=pg_catalog.convert_from(p_change_batch_bytes,'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_batch) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch) AS key)
       IS DISTINCT FROM ARRAY[
         'changes','checkpoint_key','checkpoint_state','last_key',
         'operation_id','relation_ordinal','run_id','scope_id',
         'scope_kind','source_position'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'source_position') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch->'source_position') AS key)
       IS DISTINCT FROM ARRAY[
         'batch_ordinal','commit_lsn','final_lsn','received_lsn',
         'snapshot_lsn','snapshot_name','source_xid'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'changes') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_batch->'changes')>1000 OR
       pg_catalog.jsonb_typeof(v_batch->'last_key') NOT IN ('object','null') OR
       v_batch->'last_key'='{}'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics V1 adoption batch envelope invalid';
    END IF;
    v_change_count:=pg_catalog.jsonb_array_length(v_batch->'changes');
    IF (SELECT pg_catalog.count(DISTINCT change.value->'key')
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes') AS change(value))
       IS DISTINCT FROM v_change_count::bigint OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_batch->'changes')
          WITH ORDINALITY AS change(value,position)
        WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
          OR (SELECT pg_catalog.array_agg(key ORDER BY key)
              FROM pg_catalog.jsonb_object_keys(change.value) AS key)
             IS DISTINCT FROM ARRAY['after','before','key','kind','ordinal']::text[]
          OR (change.value->>'ordinal')::integer IS DISTINCT FROM change.position::integer
          OR change.value->>'kind' NOT IN ('insert','update','delete')
          OR (change.value->>'kind'='insert' AND (
              change.value->'before'<>'null'::jsonb OR
              NOT analytics_v1_adoption_value_valid_v1(
                change.value->'key',change.value->'after'
              )))
          OR (change.value->>'kind'='update' AND (
              NOT analytics_v1_adoption_value_valid_v1(
                change.value->'key',change.value->'before'
              ) OR NOT analytics_v1_adoption_value_valid_v1(
                change.value->'key',change.value->'after'
              )))
          OR (change.value->>'kind'='delete' AND (
              change.value->'after'<>'null'::jsonb OR
              NOT analytics_v1_adoption_value_valid_v1(
                change.value->'key',change.value->'before'
              )))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Analytics V1 adoption batch change invalid';
    END IF;
    RETURN v_batch;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_dependency_sha256_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_dependency_sha256_v1(p_operation_id uuid, p_run_id uuid, p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_stage analytics_v1_adoption_stage%ROWTYPE;
    v_manifest text;
    v_digest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption dependency evidence denied';
    END IF;
    FOR v_stage IN
      SELECT stage.* FROM analytics_v1_adoption_stage AS stage
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed AND stage.disposition='adopted'
      ORDER BY stage.legacy_endpoint_id
    LOOP
      IF EXISTS (
        SELECT 1 FROM (
          SELECT dependency.value,
            pg_catalog.row_number() OVER (ORDER BY dependency.value->>'owner_domain',
              dependency.value->>'resource_kind',
              (dependency.value->>'resource_id')::uuid,
              (dependency.value->>'resource_version_id')::uuid)-1 AS expected
          FROM pg_catalog.jsonb_array_elements(
            v_stage.target_document->'dependencies'
          ) AS dependency(value)
        ) AS ordered
        WHERE (ordered.value->>'ordinal')::bigint<>ordered.expected OR
          ordered.value->>'dependency_sha256'=repeat('0',64) OR
          ((v_stage.target_document->'published_version'->>'cache_policy')=
            'revision_bound' AND
           pg_catalog.octet_length(
             ordered.value->>'data_revision_capability')=0) OR NOT EXISTS (
            SELECT 1 FROM platform.domain_cutovers AS owner
            WHERE owner.scope_kind='tenant' AND owner.scope_id=p_tenant_id
              AND owner.domain=ordered.value->>'owner_domain'
              AND owner.state='v2' AND owner.writer='v2'
              AND owner.generation=(ordered.value->>'owner_generation')::bigint
          )
      ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
          MESSAGE='Analytics V1 adoption dependency authority differs';
      END IF;
      SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
        pg_catalog.int4send(pg_catalog.octet_length(dependency.value->>'owner_domain'))||
        pg_catalog.convert_to(dependency.value->>'owner_domain','UTF8')||
        pg_catalog.int4send(pg_catalog.octet_length(dependency.value->>'resource_kind'))||
        pg_catalog.convert_to(dependency.value->>'resource_kind','UTF8')||
        pg_catalog.int4send(16)||pg_catalog.uuid_send(
          (dependency.value->>'resource_id')::uuid)||
        pg_catalog.int4send(16)||pg_catalog.uuid_send(
          (dependency.value->>'resource_version_id')::uuid)||
        pg_catalog.int4send(pg_catalog.octet_length(
          dependency.value->>'data_revision_capability'))||
        pg_catalog.convert_to(dependency.value->>'data_revision_capability','UTF8')||
        pg_catalog.int4send(32)||pg_catalog.decode(
          dependency.value->>'dependency_sha256','hex')||
        pg_catalog.int8send((dependency.value->>'catalog_version')::bigint)||
        pg_catalog.int8send((dependency.value->>'query_contract_version')::bigint)||
        pg_catalog.int8send((dependency.value->>'policy_version')::bigint),
        ''::bytea ORDER BY dependency.value->>'owner_domain',
          dependency.value->>'resource_kind',
          (dependency.value->>'resource_id')::uuid,
          (dependency.value->>'resource_version_id')::uuid),''::bytea)),'hex')
      INTO v_manifest FROM pg_catalog.jsonb_array_elements(
        v_stage.target_document->'dependencies'
      ) AS dependency(value);
      IF v_manifest IS DISTINCT FROM
         v_stage.target_document->'published_version'->>'manifest_sha256' OR
         v_manifest IS DISTINCT FROM
         v_stage.target_document->'draft_version'->>'manifest_sha256' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
          MESSAGE='Analytics V1 adoption dependency manifest differs';
      END IF;
    END LOOP;
    SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
      pg_catalog.uuid_send(stage.legacy_endpoint_id)||stage.source_sha256||
      pg_catalog.decode(
        stage.target_document->'published_version'->>'manifest_sha256','hex'),
      ''::bytea ORDER BY stage.legacy_endpoint_id),''::bytea)),'hex')
    INTO v_digest FROM analytics_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed AND stage.disposition='adopted';
    RETURN v_digest;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_dependency_sha256_v1(p_operation_id uuid, p_run_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_evidence_immutable_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_evidence_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption evidence is immutable';
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_evidence_immutable_v1() OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_finalize_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_finalize_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_stage analytics_v1_adoption_stage%ROWTYPE;
    v_generation bigint;
    v_plan text;
    v_transform text;
    v_lease text;
    v_final_lsn pg_lsn;
    v_evidence jsonb;
    v_source_count bigint;
    v_source_root text;
    v_target_count bigint;
    v_target_root text;
    v_dependency text;
    v_public text;
    v_zero_hit text;
    v_rollback text;
    v_watermark text;
    v_old_root bytea;
    v_adopted bigint;
    v_retired bigint;
    v_acceptance text;
    v_now timestamptz;
BEGIN
    v_now:=pg_catalog.date_trunc(
      'microseconds',pg_catalog.transaction_timestamp());
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption finalization principal denied';
    END IF;
    SELECT ready.final_lsn,ready.evidence INTO STRICT v_final_lsn,v_evidence
    FROM analytics_v1_adoption_projection_ready_v1(
      p_operation_id,p_run_id,p_scope_id
    ) AS ready;
    SELECT operation.cutover_generation,operation.plan_sha256,
      operation.transform_manifest_sha256,operation.lease_manifest_sha256
    INTO STRICT v_generation,v_plan,v_transform,v_lease
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
    FOR SHARE;
    IF EXISTS (
      SELECT 1 FROM analytics_v1_adoption_stage AS stage
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed AND stage.disposition='blocked'
    ) THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption has active blockers';
    END IF;
    SELECT root.row_count,root.root_sha256 INTO STRICT v_source_count,v_source_root
    FROM analytics_v1_adoption_source_root_v1(
      p_operation_id,p_run_id,p_scope_id
    ) AS root;
    SELECT pg_catalog.count(*),pg_catalog.encode(pg_catalog.sha256(
      COALESCE(pg_catalog.string_agg(
        pg_catalog.uuid_send(stage.legacy_endpoint_id)||stage.target_sha256,
        ''::bytea ORDER BY stage.legacy_endpoint_id),''::bytea)),'hex')
    INTO v_target_count,v_target_root
    FROM analytics_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed AND stage.disposition='adopted';
    v_dependency:=analytics_v1_adoption_dependency_sha256_v1(
      p_operation_id,p_run_id,p_scope_id);
    IF (v_evidence->>'source_count')::bigint IS DISTINCT FROM v_source_count OR
       v_evidence->>'source_root_sha256' IS DISTINCT FROM v_source_root OR
       (v_evidence->>'target_count')::bigint IS DISTINCT FROM v_target_count OR
       v_evidence->>'target_root_sha256' IS DISTINCT FROM v_target_root OR
       v_evidence->>'dependency_sha256' IS DISTINCT FROM v_dependency THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption terminal inventory differs';
    END IF;
    FOR v_stage IN
      SELECT stage.* FROM analytics_v1_adoption_stage AS stage
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed AND stage.disposition='adopted'
      ORDER BY stage.legacy_endpoint_id
    LOOP
      PERFORM analytics_v1_adoption_project_query_v1(v_stage.target_document);
      PERFORM analytics_v1_adoption_project_dependencies_v1(v_stage.target_document);
      IF (v_stage.source_document->>'is_public')::boolean THEN
        PERFORM analytics_v1_adoption_project_release_v1(v_stage.target_document);
        PERFORM analytics_v1_adoption_project_public_v1(
          p_scope_id,v_stage.legacy_endpoint_id,
          v_stage.source_document,v_stage.target_document);
      END IF;
      PERFORM analytics_v1_adoption_project_differential_v1(
        p_operation_id,p_run_id,v_stage.legacy_endpoint_id,
        v_stage.source_sha256,v_stage.target_document->'differential');
    END LOOP;
    v_public:=analytics_v1_adoption_public_approval_sha256_v1(
      p_operation_id,p_run_id,p_scope_id);
    v_zero_hit:=analytics_v1_adoption_zero_hit_sha256_v1(
      p_operation_id,p_run_id,p_scope_id);
    v_rollback:=analytics_v1_adoption_rollback_sha256_v1(
      p_operation_id,p_run_id);
    v_watermark:=analytics_v1_adoption_watermark_sha256_v1(
      p_operation_id,p_run_id,v_final_lsn);
    IF v_evidence->>'public_approval_sha256' IS DISTINCT FROM v_public OR
       v_evidence->>'zero_hit_sha256' IS DISTINCT FROM v_zero_hit OR
       v_evidence->>'rollback_sha256' IS DISTINCT FROM v_rollback OR
       v_evidence->>'watermark_sha256' IS DISTINCT FROM v_watermark THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption acceptance evidence differs';
    END IF;
    INSERT INTO analytics_v1_adoption_items(
      run_id,legacy_endpoint_id,source_sha256,disposition,reason_code,
      query_id,query_version_id,publication_release_id,target_sha256,created_at
    ) SELECT p_run_id,stage.legacy_endpoint_id,stage.source_sha256,
      stage.disposition,stage.reason_code,
      CASE WHEN stage.disposition='adopted' THEN
        (stage.target_document->'query'->>'id')::uuid END,
      CASE WHEN stage.disposition='adopted' THEN
        (stage.target_document->'published_version'->>'id')::uuid END,
      CASE WHEN stage.disposition='adopted' AND
        (stage.source_document->>'is_public')::boolean THEN
        (stage.target_document->'release'->>'id')::uuid END,
      stage.target_sha256,v_now
    FROM analytics_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed ORDER BY stage.legacy_endpoint_id;
    SELECT pg_catalog.count(*) FILTER(WHERE item.disposition='adopted'),
      pg_catalog.count(*) FILTER(WHERE item.disposition='retired'),
      pg_catalog.sha256(pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
        item.legacy_endpoint_id::text||'|'||pg_catalog.encode(item.source_sha256,'hex')||
        '|'||item.disposition||'|'||COALESCE(item.reason_code,'')||'|'||
        COALESCE(item.query_id::text,'')||'|'||COALESCE(item.query_version_id::text,'')||
        '|'||COALESCE(item.publication_release_id::text,'')||'|'||
        COALESCE(pg_catalog.encode(item.target_sha256,'hex'),''),
        E'\n' ORDER BY item.legacy_endpoint_id),''),'UTF8'))
    INTO v_adopted,v_retired,v_old_root
    FROM analytics_v1_adoption_items AS item WHERE item.run_id=p_run_id;
    INSERT INTO analytics_v1_adoption_acceptance_receipts(
      run_id,tenant_id,cutover_generation,source_count,adopted_count,
      retired_count,root_sha256,accepted_at
    ) VALUES (p_run_id,p_scope_id,v_generation,v_source_count,v_adopted,
      v_retired,v_old_root,v_now);
    v_acceptance:=pg_catalog.encode(pg_catalog.sha256(
      pg_catalog.convert_to('analytics-v1-adoption-acceptance.v1','UTF8')||
      pg_catalog.uuid_send(p_operation_id)||pg_catalog.uuid_send(p_run_id)||
      pg_catalog.uuid_send(p_scope_id)||pg_catalog.int8send(v_generation)||
      pg_catalog.convert_to(v_plan||v_transform||v_lease,'UTF8')||
      pg_catalog.pg_lsn_send(v_final_lsn)||
      pg_catalog.decode(v_evidence->>'evidence_sha256','hex')),'hex');
    INSERT INTO analytics_v1_adoption_receipts(
      operation_id,run_id,tenant_id,cutover_generation,plan_sha256,
      transform_sha256,lease_manifest_sha256,final_lsn,source_count,
      source_root_sha256,target_count,target_root_sha256,dependency_sha256,
      public_approval_sha256,zero_hit_sha256,rollback_sha256,watermark_sha256,
      evidence_sha256,acceptance_sha256,recorded_at
    ) VALUES (p_operation_id,p_run_id,p_scope_id,v_generation,v_plan,v_transform,
      v_lease,v_final_lsn,v_source_count,v_source_root,v_target_count,v_target_root,
      v_dependency,v_public,v_zero_hit,v_rollback,v_watermark,
      v_evidence->>'evidence_sha256',v_acceptance,v_now);
    RETURN v_target_root;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_finalize_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_project_dependencies_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_project_dependencies_v1(p_target jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_version_id uuid;
    v_count bigint;
    v_matched bigint;
BEGIN
    v_version_id:=(p_target->'published_version'->>'id')::uuid;
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.jsonb_typeof(p_target->'dependencies') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(p_target->'dependencies') NOT BETWEEN 1 AND 32
       OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_target->'dependencies')
          WITH ORDINALITY AS dependency(value,position)
        WHERE (SELECT pg_catalog.array_agg(key ORDER BY key)
               FROM pg_catalog.jsonb_object_keys(dependency.value) AS key)
          IS DISTINCT FROM ARRAY[
            'catalog_version','created_at','data_revision_capability',
            'dependency_sha256','ordinal','owner_domain','owner_generation',
            'policy_version','query_contract_version','resource_id',
            'resource_kind','resource_version_id'
          ]::text[]
          OR (dependency.value->>'ordinal')::bigint<>dependency.position-1
          OR dependency.value->>'owner_domain' <> 'iam'
          OR dependency.value->>'dependency_sha256'!~'^[0-9a-f]{64}$'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
          MESSAGE='Analytics V1 adoption dependency projection invalid';
    END IF;
    INSERT INTO analytics_query_dependencies(
      query_version_id,ordinal,owner_domain,resource_kind,resource_id,
      resource_version_id,owner_generation,catalog_version,
      query_contract_version,policy_version,data_revision_capability,
      dependency_sha256,created_at
    ) SELECT v_version_id,(dependency.value->>'ordinal')::smallint,
      dependency.value->>'owner_domain',dependency.value->>'resource_kind',
      (dependency.value->>'resource_id')::uuid,
      (dependency.value->>'resource_version_id')::uuid,
      (dependency.value->>'owner_generation')::bigint,
      (dependency.value->>'catalog_version')::bigint,
      (dependency.value->>'query_contract_version')::bigint,
      (dependency.value->>'policy_version')::bigint,
      dependency.value->>'data_revision_capability',
      pg_catalog.decode(dependency.value->>'dependency_sha256','hex'),
      (dependency.value->>'created_at')::timestamptz
    FROM pg_catalog.jsonb_array_elements(p_target->'dependencies')
      AS dependency(value)
    ON CONFLICT DO NOTHING;
    SELECT pg_catalog.count(*) INTO v_count
    FROM analytics_query_dependencies AS dependency
    WHERE dependency.query_version_id=v_version_id;
    SELECT pg_catalog.count(*) INTO v_matched
    FROM analytics_query_dependencies AS stored
    JOIN pg_catalog.jsonb_array_elements(p_target->'dependencies') AS expected(value)
      ON (expected.value->>'ordinal')::smallint=stored.ordinal
    WHERE stored.query_version_id=v_version_id
      AND stored.owner_domain=expected.value->>'owner_domain'
      AND stored.resource_kind=expected.value->>'resource_kind'
      AND stored.resource_id=(expected.value->>'resource_id')::uuid
      AND stored.resource_version_id=(expected.value->>'resource_version_id')::uuid
      AND stored.owner_generation=(expected.value->>'owner_generation')::bigint
      AND stored.catalog_version=(expected.value->>'catalog_version')::bigint
      AND stored.query_contract_version=(expected.value->>'query_contract_version')::bigint
      AND stored.policy_version=(expected.value->>'policy_version')::bigint
      AND stored.data_revision_capability=expected.value->>'data_revision_capability'
      AND stored.dependency_sha256=pg_catalog.decode(
        expected.value->>'dependency_sha256','hex');
    IF v_count IS DISTINCT FROM
       pg_catalog.jsonb_array_length(p_target->'dependencies')::bigint OR
       v_matched IS DISTINCT FROM v_count THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption dependency projection differs';
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_project_dependencies_v1(p_target jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_project_differential_v1(uuid, uuid, uuid, bytea, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_project_differential_v1(p_operation_id uuid, p_run_id uuid, p_legacy_endpoint_id uuid, p_source_sha256 bytea, p_differential jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_evidence bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_differential) AS key)
       IS DISTINCT FROM ARRAY[
        'compatible_image_sha256','evidence_sha256','reverse_source_sha256',
        'source_result_sha256','target_result_sha256','wire_contract_sha256'
       ]::text[] OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_each_text(p_differential) AS item
        WHERE item.value!~'^[0-9a-f]{64}$' OR item.value=repeat('0',64)
       ) OR p_differential->>'source_result_sha256' IS DISTINCT FROM
            p_differential->>'target_result_sha256' OR
       p_differential->>'reverse_source_sha256' IS DISTINCT FROM
         pg_catalog.encode(p_source_sha256,'hex') THEN
      RAISE EXCEPTION USING ERRCODE='22023',
        MESSAGE='Analytics V1 adoption differential evidence invalid';
    END IF;
    v_evidence:=pg_catalog.sha256(
      pg_catalog.convert_to('analytics-v1-adoption-differential.v1','UTF8')||
      pg_catalog.decode('00','hex')||pg_catalog.uuid_send(p_legacy_endpoint_id)||
      pg_catalog.decode('00','hex')||pg_catalog.decode(
        p_differential->>'source_result_sha256','hex')||
      pg_catalog.decode('00','hex')||pg_catalog.decode(
        p_differential->>'target_result_sha256','hex')||
      pg_catalog.decode('00','hex')||pg_catalog.decode(
        p_differential->>'wire_contract_sha256','hex')||
      pg_catalog.decode('00','hex')||pg_catalog.decode(
        p_differential->>'compatible_image_sha256','hex')||
      pg_catalog.decode('00','hex')||p_source_sha256
    );
    IF pg_catalog.encode(v_evidence,'hex') IS DISTINCT FROM
       p_differential->>'evidence_sha256' THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption differential digest differs';
    END IF;
    INSERT INTO analytics_v1_adoption_differentials(
      operation_id,run_id,legacy_endpoint_id,source_result_sha256,
      target_result_sha256,wire_contract_sha256,compatible_image_sha256,
      reverse_source_sha256,evidence_sha256,recorded_at
    ) VALUES (
      p_operation_id,p_run_id,p_legacy_endpoint_id,
      pg_catalog.decode(p_differential->>'source_result_sha256','hex'),
      pg_catalog.decode(p_differential->>'target_result_sha256','hex'),
      pg_catalog.decode(p_differential->>'wire_contract_sha256','hex'),
      pg_catalog.decode(p_differential->>'compatible_image_sha256','hex'),
      p_source_sha256,v_evidence,
      pg_catalog.date_trunc('microseconds',pg_catalog.transaction_timestamp())
    ) ON CONFLICT DO NOTHING;
    PERFORM 1 FROM analytics_v1_adoption_differentials AS differential
    WHERE differential.operation_id=p_operation_id AND differential.run_id=p_run_id
      AND differential.legacy_endpoint_id=p_legacy_endpoint_id
      AND differential.source_result_sha256=pg_catalog.decode(
        p_differential->>'source_result_sha256','hex')
      AND differential.target_result_sha256=differential.source_result_sha256
      AND differential.reverse_source_sha256=p_source_sha256
      AND differential.evidence_sha256=v_evidence;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption differential replay differs';
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_project_differential_v1(p_operation_id uuid, p_run_id uuid, p_legacy_endpoint_id uuid, p_source_sha256 bytea, p_differential jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_project_public_v1(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_project_public_v1(p_tenant_id uuid, p_legacy_endpoint_id uuid, p_source jsonb, p_target jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_pointer jsonb;
    v_route jsonb;
    v_snapshot jsonb;
BEGIN
    v_pointer:=p_target->'public_pointer';
    v_route:=p_target->'legacy_route';
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_pointer) AS key)
       IS DISTINCT FROM ARRAY[
        'activated_at','audience','capability_expires_at','capability_sha256',
        'generation','public_id','release_id','resource_kind',
        'resource_version_id','revoked_at','state','tenant_id'
       ]::text[] OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_route) AS key)
       IS DISTINCT FROM ARRAY[
        'consumer_inventory_sha256','consumers_acked_at','hit_count','last_hit_at',
        'legacy_endpoint_id','legacy_tenant_identity','method','path','public_id',
        'release_id','remove_after','retired_at','retirement_evidence_sha256',
        'retirement_observed_at','slug','state','tenant_id'
       ]::text[] OR
       (v_pointer->>'tenant_id')::uuid IS DISTINCT FROM p_tenant_id OR
       v_pointer->>'resource_kind'<>'query' OR v_pointer->>'audience'<>'public' OR
       v_pointer->>'state'<>'active' OR
       v_pointer->'capability_sha256'<>'null'::jsonb OR
       v_pointer->'capability_expires_at'<>'null'::jsonb OR
       v_pointer->'revoked_at'<>'null'::jsonb OR
       v_pointer->>'public_id'!~'^[0-9a-f]{32}$' OR
       (v_pointer->>'release_id')::uuid IS DISTINCT FROM
         (p_target->'release'->>'id')::uuid OR
       (v_pointer->>'resource_version_id')::uuid IS DISTINCT FROM
         (p_target->'published_version'->>'id')::uuid OR
       (v_route->>'tenant_id')::uuid IS DISTINCT FROM p_tenant_id OR
       (v_route->>'legacy_endpoint_id')::uuid IS DISTINCT FROM p_legacy_endpoint_id OR
       v_route->>'legacy_tenant_identity' IS DISTINCT FROM p_tenant_id::text OR
       v_route->>'method' IS DISTINCT FROM p_source->>'method' OR
       v_route->>'slug' IS DISTINCT FROM p_source->>'slug' OR
       v_route->>'path' IS DISTINCT FROM p_source->'config_json'->>'path' OR
       v_route->>'public_id' IS DISTINCT FROM v_pointer->>'public_id' OR
       (v_route->>'release_id')::uuid IS DISTINCT FROM
         (v_pointer->>'release_id')::uuid OR
       v_route->>'state'<>'active' OR (v_route->>'hit_count')::bigint<>0 OR
       v_route->'last_hit_at'<>'null'::jsonb OR
       v_route->'consumers_acked_at'='null'::jsonb OR
       v_route->>'consumer_inventory_sha256'!~'^[0-9a-f]{64}$' OR
       v_route->'retirement_evidence_sha256'<>'null'::jsonb OR
       v_route->'retirement_observed_at'<>'null'::jsonb OR
       v_route->'retired_at'<>'null'::jsonb THEN
      RAISE EXCEPTION USING ERRCODE='22023',
        MESSAGE='Analytics V1 adoption public projection invalid';
    END IF;
    v_snapshot:=platform.analytics_v1_adoption_public_bridge_v1(
      'project',p_tenant_id,p_legacy_endpoint_id,p_target);
    IF (v_snapshot->>'publication_exists')::boolean IS NOT TRUE OR
       (v_snapshot->>'route_exists')::boolean IS NOT TRUE OR
       v_snapshot->>'publication_public_id' IS DISTINCT FROM
         v_pointer->>'public_id' OR
       (v_snapshot->>'publication_release_id')::uuid IS DISTINCT FROM
         (v_pointer->>'release_id')::uuid OR
       (v_snapshot->>'publication_resource_version_id')::uuid IS DISTINCT FROM
         (v_pointer->>'resource_version_id')::uuid OR
       v_snapshot->>'publication_audience'<>'public' OR
       v_snapshot->>'publication_state'<>'active' OR
       v_snapshot->>'route_public_id' IS DISTINCT FROM v_route->>'public_id' OR
       (v_snapshot->>'route_release_id')::uuid IS DISTINCT FROM
         (v_route->>'release_id')::uuid OR
       v_snapshot->>'route_state'<>'active' OR
       (v_snapshot->>'hit_count')::bigint<>0 OR
       v_snapshot->'last_hit_at'<>'null'::jsonb OR
       (v_snapshot->>'consumers_acked_at')::timestamptz IS DISTINCT FROM
         (v_route->>'consumers_acked_at')::timestamptz OR
       (v_snapshot->>'remove_after')::timestamptz IS DISTINCT FROM
         (v_route->>'remove_after')::timestamptz OR
       v_snapshot->>'consumer_inventory_sha256' IS DISTINCT FROM
         v_route->>'consumer_inventory_sha256' OR
       v_snapshot->>'legacy_tenant_identity' IS DISTINCT FROM p_tenant_id::text OR
       v_snapshot->>'method' IS DISTINCT FROM v_route->>'method' OR
       v_snapshot->>'path' IS DISTINCT FROM v_route->>'path' OR
       v_snapshot->>'slug' IS DISTINCT FROM v_route->>'slug' THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption public projection differs';
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_project_public_v1(p_tenant_id uuid, p_legacy_endpoint_id uuid, p_source jsonb, p_target jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_project_query_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_project_query_v1(p_target jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_query jsonb;
    v_published jsonb;
    v_draft jsonb;
BEGIN
    v_query:=p_target->'query';
    v_published:=p_target->'published_version';
    v_draft:=p_target->'draft_version';
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_query) AS key)
       IS DISTINCT FROM ARRAY[
        'created_at','created_by','current_draft_version_id','id',
        'lifecycle_state','reference_epoch','row_revision',
        'updated_at','updated_by'
       ]::text[] OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_published) AS key)
       IS DISTINCT FROM ARRAY[
        'cache_policy','created_at','created_by','id','manifest_sha256','name',
        'output_document','parameter_document','published_at','published_by',
        'query_document','query_id','row_revision','updated_at','updated_by',
        'version_no','version_state'
       ]::text[] OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_draft) AS key)
       IS DISTINCT FROM ARRAY[
        'cache_policy','created_at','created_by','id','manifest_sha256','name',
        'output_document','parameter_document','published_at','published_by',
        'query_document','query_id','row_revision','updated_at','updated_by',
        'version_no','version_state'
       ]::text[] OR
       v_query->>'lifecycle_state'<>'active' OR
       v_published->>'version_state'<>'published' OR
       v_draft->>'version_state'<>'draft' OR
       (v_query->>'id')::uuid IS DISTINCT FROM (v_published->>'query_id')::uuid OR
       (v_query->>'id')::uuid IS DISTINCT FROM (v_draft->>'query_id')::uuid OR
       (v_query->>'current_draft_version_id')::uuid
         IS DISTINCT FROM (v_draft->>'id')::uuid OR
       (v_published->>'id')::uuid=(v_draft->>'id')::uuid OR
       v_published->'published_by'='null'::jsonb OR
       v_published->'published_at'='null'::jsonb OR
       v_draft->'published_by'<>'null'::jsonb OR
       v_draft->'published_at'<>'null'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='22023',
          MESSAGE='Analytics V1 adoption query projection invalid';
    END IF;
    SET CONSTRAINTS analytics_saved_queries_current_draft_fk DEFERRED;
    INSERT INTO analytics_saved_queries(
      id,lifecycle_state,row_revision,reference_epoch,current_draft_version_id,
      created_by,updated_by,created_at,updated_at
    ) VALUES (
      (v_query->>'id')::uuid,v_query->>'lifecycle_state',
      (v_query->>'row_revision')::bigint,(v_query->>'reference_epoch')::bigint,
      (v_query->>'current_draft_version_id')::uuid,
      (v_query->>'created_by')::uuid,(v_query->>'updated_by')::uuid,
      (v_query->>'created_at')::timestamptz,(v_query->>'updated_at')::timestamptz
    ) ON CONFLICT DO NOTHING;
    INSERT INTO analytics_saved_query_versions(
      id,query_id,version_no,version_state,row_revision,name,
      query_document,query_sha256,parameter_document,parameter_sha256,
      output_document,output_sha256,manifest_sha256,cache_policy,
      created_by,updated_by,created_at,updated_at,published_by,published_at
    ) SELECT (row->>'id')::uuid,(row->>'query_id')::uuid,
      (row->>'version_no')::bigint,row->>'version_state',
      (row->>'row_revision')::bigint,row->>'name',
      pg_catalog.convert_to((row->'query_document')::text,'UTF8'),
      pg_catalog.sha256(pg_catalog.convert_to((row->'query_document')::text,'UTF8')),
      pg_catalog.convert_to((row->'parameter_document')::text,'UTF8'),
      pg_catalog.sha256(pg_catalog.convert_to((row->'parameter_document')::text,'UTF8')),
      pg_catalog.convert_to((row->'output_document')::text,'UTF8'),
      pg_catalog.sha256(pg_catalog.convert_to((row->'output_document')::text,'UTF8')),
      pg_catalog.decode(row->>'manifest_sha256','hex'),row->>'cache_policy',
      (row->>'created_by')::uuid,(row->>'updated_by')::uuid,
      (row->>'created_at')::timestamptz,(row->>'updated_at')::timestamptz,
      (row->>'published_by')::uuid,(row->>'published_at')::timestamptz
    FROM (VALUES(v_published),(v_draft)) AS value(row)
    ON CONFLICT DO NOTHING;
    PERFORM 1 FROM analytics_saved_queries AS root
    JOIN analytics_saved_query_versions AS published
      ON published.id=(v_published->>'id')::uuid AND published.query_id=root.id
    JOIN analytics_saved_query_versions AS draft
      ON draft.id=root.current_draft_version_id AND draft.query_id=root.id
    WHERE root.id=(v_query->>'id')::uuid
      AND root.row_revision=(v_query->>'row_revision')::bigint
      AND published.manifest_sha256=pg_catalog.decode(
        v_published->>'manifest_sha256','hex')
      AND published.query_document=pg_catalog.convert_to(
        (v_published->'query_document')::text,'UTF8')
      AND published.parameter_document=pg_catalog.convert_to(
        (v_published->'parameter_document')::text,'UTF8')
      AND published.output_document=pg_catalog.convert_to(
        (v_published->'output_document')::text,'UTF8')
      AND draft.version_state='draft';
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption query projection differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_project_query_v1(p_target jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_project_release_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_project_release_v1(p_target jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_release jsonb;
    v_approval jsonb;
BEGIN
    v_release:=p_target->'release';
    v_approval:=p_target->'approval';
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption release projection principal denied';
    END IF;
    IF (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_release) AS key)
       IS DISTINCT FROM ARRAY[
        'activated_at','approved_at','approver_id','audience','cache_policy',
        'capability_expires_at','created_at','generation','id','lifecycle_state',
        'manifest_sha256','public_id','requester_id','requester_step_up_at',
        'resource_kind','resource_version_id','revoked_at','row_revision',
        'submitted_at','updated_at'
       ]::text[] OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_approval) AS key)
       IS DISTINCT FROM ARRAY[
        'approved_at','approver_id','approver_step_up_at','evidence_sha256',
        'release_id','requester_id','requester_step_up_at','request_sha256'
       ]::text[] THEN
      RAISE EXCEPTION USING ERRCODE='22023',
        MESSAGE='Analytics V1 adoption release projection shape invalid';
    END IF;
    IF
       v_release->>'resource_kind'<>'query' OR
       v_release->>'audience'<>'public' OR
       v_release->>'lifecycle_state'<>'active' OR
       v_release->>'cache_policy' NOT IN ('none','revision_bound') OR
       v_release->>'manifest_sha256'!~'^[0-9a-f]{64}$' OR
       v_release->>'public_id'!~'^[0-9a-f]{32}$' OR
       (v_release->>'resource_version_id')::uuid IS DISTINCT FROM
         (p_target->'published_version'->>'id')::uuid OR
       v_release->>'manifest_sha256' IS DISTINCT FROM
         p_target->'published_version'->>'manifest_sha256' OR
       (v_approval->>'release_id')::uuid IS DISTINCT FROM
         (v_release->>'id')::uuid OR
       (v_approval->>'requester_id')::uuid IS DISTINCT FROM
         (v_release->>'requester_id')::uuid OR
       (v_approval->>'approver_id')::uuid IS DISTINCT FROM
         (v_release->>'approver_id')::uuid OR
       v_approval->>'request_sha256'!~'^[0-9a-f]{64}$' OR
       v_approval->>'evidence_sha256'!~'^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION USING ERRCODE='22023',
        MESSAGE='Analytics V1 adoption release projection invalid';
    END IF;
    INSERT INTO analytics_publication_releases(
      id,resource_kind,resource_version_id,audience,lifecycle_state,cache_policy,
      manifest_sha256,requester_id,approver_id,row_revision,generation,public_id,
      capability_expires_at,created_at,updated_at,submitted_at,approved_at,
      requester_step_up_at,
      activated_at,revoked_at
    ) VALUES (
      (v_release->>'id')::uuid,v_release->>'resource_kind',
      (v_release->>'resource_version_id')::uuid,v_release->>'audience',
      v_release->>'lifecycle_state',v_release->>'cache_policy',
      pg_catalog.decode(v_release->>'manifest_sha256','hex'),
      (v_release->>'requester_id')::uuid,(v_release->>'approver_id')::uuid,
      (v_release->>'row_revision')::bigint,(v_release->>'generation')::bigint,
      pg_catalog.decode(v_release->>'public_id','hex'),NULL,
      (v_release->>'created_at')::timestamptz,(v_release->>'updated_at')::timestamptz,
      (v_release->>'submitted_at')::timestamptz,
      (v_release->>'approved_at')::timestamptz,
      (v_release->>'requester_step_up_at')::timestamptz,
      (v_release->>'activated_at')::timestamptz,NULL
    ) ON CONFLICT DO NOTHING;
    INSERT INTO analytics_publication_approvals(
      release_id,requester_id,requester_step_up_at,approver_id,
      approver_step_up_at,approved_at,evidence_sha256
    ) VALUES (
      (v_approval->>'release_id')::uuid,(v_approval->>'requester_id')::uuid,
      (v_approval->>'requester_step_up_at')::timestamptz,
      (v_approval->>'approver_id')::uuid,
      (v_approval->>'approver_step_up_at')::timestamptz,
      (v_approval->>'approved_at')::timestamptz,
      pg_catalog.decode(v_approval->>'evidence_sha256','hex')
    ) ON CONFLICT DO NOTHING;
    PERFORM 1 FROM analytics_publication_releases AS release
    JOIN analytics_publication_approvals AS approval ON approval.release_id=release.id
    WHERE release.id=(v_release->>'id')::uuid
      AND release.resource_version_id=(v_release->>'resource_version_id')::uuid
      AND release.audience='public' AND release.lifecycle_state='active'
      AND release.manifest_sha256=pg_catalog.decode(v_release->>'manifest_sha256','hex')
      AND release.requester_id=(v_release->>'requester_id')::uuid
      AND release.approver_id=(v_release->>'approver_id')::uuid
      AND release.requester_step_up_at=
        (v_approval->>'requester_step_up_at')::timestamptz
      AND release.public_id=pg_catalog.decode(v_release->>'public_id','hex')
      AND approval.requester_id=release.requester_id
      AND approval.approver_id=release.approver_id
      AND approval.evidence_sha256=pg_catalog.decode(
        v_approval->>'evidence_sha256','hex')
      AND approval.evidence_sha256=pg_catalog.sha256(
        pg_catalog.decode(v_approval->>'request_sha256','hex')||
        release.manifest_sha256);
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption release projection differs';
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_project_release_v1(p_target jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_projection_ready_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_projection_ready_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS TABLE(final_lsn pg_lsn, evidence jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_generation bigint;
    v_target_count bigint;
    v_public_counts jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption readiness principal denied';
    END IF;
    SELECT operation.cutover_generation INTO v_generation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='analytics' AND operation.domain='analytics'
      AND operation.state='quiescing'
    FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
      SELECT 1 FROM tenancy_schema_identity AS tenant
      WHERE tenant.singleton AND tenant.tenant_id=p_scope_id
        AND tenant.schema_name=pg_catalog.current_schema()
        AND tenant.origin='v1_adopted'
    ) OR NOT EXISTS (
      SELECT 1 FROM platform.cutover_groups AS fence
      WHERE fence.scope_kind='tenant' AND fence.scope_id=p_scope_id
        AND fence.group_id='analytics' AND fence.generation=v_generation
        AND fence.state='quiescing' AND fence.writer='none'
    ) OR NOT EXISTS (
      SELECT 1 FROM platform.domain_cutovers AS fence
      WHERE fence.scope_kind='tenant' AND fence.scope_id=p_scope_id
        AND fence.domain='analytics' AND fence.generation=v_generation
        AND fence.state='quiescing' AND fence.writer='none'
    ) THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption projection authority not ready';
    END IF;
    IF (SELECT pg_catalog.count(*)
        FROM platform.cutover_operation_checkpoint_keys AS expected
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id)<>
       1 OR NOT EXISTS (
      SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS expected
      WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
        AND expected.relation_ordinal=1 AND expected.ordinal=1
        AND expected.checkpoint_key='openapi_endpoints'
    ) OR NOT EXISTS (
      SELECT 1 FROM platform.cutover_copy_checkpoints AS checkpoint
      WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id
        AND checkpoint.relation_ordinal=1
        AND checkpoint.checkpoint_key='openapi_endpoints'
        AND checkpoint.state='complete' AND checkpoint.final_lsn IS NOT NULL
        AND checkpoint.applied_lsn=checkpoint.final_lsn
        AND pg_catalog.jsonb_typeof(checkpoint.last_key)='object'
    ) THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption checkpoint incomplete';
    END IF;
    v_public_counts:=platform.analytics_v1_adoption_public_bridge_v1(
      'count',p_scope_id,NULL,NULL);
    SELECT
      (SELECT pg_catalog.count(*) FROM analytics_saved_queries)+
      (SELECT pg_catalog.count(*) FROM analytics_saved_query_versions)+
      (SELECT pg_catalog.count(*) FROM analytics_query_dependencies)+
      (SELECT pg_catalog.count(*) FROM analytics_publication_releases)+
      (SELECT pg_catalog.count(*) FROM analytics_publication_approvals)+
      (v_public_counts->>'publication_count')::bigint+
      (v_public_counts->>'route_count')::bigint+
      (SELECT pg_catalog.count(*) FROM analytics_v1_adoption_items
       WHERE run_id=p_run_id)+
      (SELECT pg_catalog.count(*) FROM analytics_v1_adoption_acceptance_receipts
       WHERE run_id=p_run_id)+
      (SELECT pg_catalog.count(*) FROM analytics_v1_adoption_receipts
       WHERE operation_id=p_operation_id AND run_id=p_run_id)
    INTO v_target_count;
    IF v_target_count<>0 THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption inactive target not ready';
    END IF;
    RETURN QUERY SELECT checkpoint.final_lsn,checkpoint.last_key
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id
      AND checkpoint.relation_ordinal=1
      AND checkpoint.checkpoint_key='openapi_endpoints';
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_projection_ready_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_public_approval_sha256_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_public_approval_sha256_v1(p_operation_id uuid, p_run_id uuid, p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_stage analytics_v1_adoption_stage%ROWTYPE;
    v_release jsonb;
    v_approval jsonb;
    v_snapshot jsonb;
    v_evidence bytea;
    v_digest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption public approval evidence denied';
    END IF;
    FOR v_stage IN
      SELECT stage.* FROM analytics_v1_adoption_stage AS stage
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed AND stage.disposition='adopted'
      ORDER BY stage.legacy_endpoint_id
    LOOP
      IF (v_stage.source_document->>'is_public')::boolean IS NOT TRUE THEN
        IF v_stage.target_document->'release'<>'null'::jsonb OR
           v_stage.target_document->'approval'<>'null'::jsonb OR
           v_stage.target_document->'public_pointer'<>'null'::jsonb OR
           v_stage.target_document->'legacy_route'<>'null'::jsonb THEN
          RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Analytics V1 adoption private publication differs';
        END IF;
        CONTINUE;
      END IF;
      v_release:=v_stage.target_document->'release';
      v_approval:=v_stage.target_document->'approval';
      v_evidence:=pg_catalog.sha256(
        pg_catalog.decode(v_approval->>'request_sha256','hex')||
        pg_catalog.decode(v_release->>'manifest_sha256','hex'));
      IF (v_approval->>'requester_id')::uuid=
           (v_approval->>'approver_id')::uuid OR
         v_approval->>'request_sha256'=repeat('0',64) OR
         (v_approval->>'approved_at')::timestamptz-
           (v_approval->>'requester_step_up_at')::timestamptz>
             interval '10 minutes' OR
         (v_approval->>'approved_at')::timestamptz-
           (v_approval->>'approver_step_up_at')::timestamptz>
             interval '10 minutes' OR
         pg_catalog.encode(v_evidence,'hex') IS DISTINCT FROM
           v_approval->>'evidence_sha256' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
          MESSAGE='Analytics V1 adoption public approval differs';
      END IF;
      v_snapshot:=platform.analytics_v1_adoption_public_bridge_v1(
        'inspect',p_tenant_id,v_stage.legacy_endpoint_id,NULL);
      PERFORM 1 FROM analytics_publication_releases AS release
      JOIN analytics_publication_approvals AS approval
        ON approval.release_id=release.id
      WHERE release.id=(v_release->>'id')::uuid
        AND release.resource_version_id=
          (v_stage.target_document->'published_version'->>'id')::uuid
        AND release.audience='public' AND release.lifecycle_state='active'
        AND release.requester_id=(v_approval->>'requester_id')::uuid
        AND release.approver_id=(v_approval->>'approver_id')::uuid
        AND approval.evidence_sha256=v_evidence
        AND (v_snapshot->>'publication_exists')::boolean
        AND v_snapshot->>'publication_public_id'=
          pg_catalog.encode(release.public_id,'hex')
        AND (v_snapshot->>'publication_release_id')::uuid=release.id
        AND (v_snapshot->>'publication_resource_version_id')::uuid=
          release.resource_version_id
        AND v_snapshot->>'publication_audience'='public'
        AND v_snapshot->>'publication_state'='active';
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
          MESSAGE='Analytics V1 adoption stored public approval differs';
      END IF;
    END LOOP;
    SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
      pg_catalog.uuid_send(stage.legacy_endpoint_id)||
      pg_catalog.uuid_send((stage.target_document->'release'->>'id')::uuid)||
      pg_catalog.decode(
        stage.target_document->'approval'->>'evidence_sha256','hex')||
      pg_catalog.decode(
        stage.target_document->'public_pointer'->>'public_id','hex'),
      ''::bytea ORDER BY stage.legacy_endpoint_id),''::bytea)),'hex')
    INTO v_digest FROM analytics_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed AND stage.disposition='adopted'
      AND (stage.source_document->>'is_public')::boolean;
    RETURN v_digest;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_public_approval_sha256_v1(p_operation_id uuid, p_run_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_rollback_sha256_v1(uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_rollback_sha256_v1(p_operation_id uuid, p_run_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_digest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR EXISTS (
      SELECT 1 FROM analytics_v1_adoption_stage AS stage
      LEFT JOIN analytics_v1_adoption_differentials AS differential
        ON differential.operation_id=stage.operation_id
       AND differential.run_id=stage.run_id
       AND differential.legacy_endpoint_id=stage.legacy_endpoint_id
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed AND stage.disposition='adopted' AND (
          differential.legacy_endpoint_id IS NULL OR
          differential.source_result_sha256<>differential.target_result_sha256 OR
          differential.reverse_source_sha256<>stage.source_sha256 OR
          differential.evidence_sha256<>pg_catalog.sha256(
            pg_catalog.convert_to('analytics-v1-adoption-differential.v1','UTF8')||
            pg_catalog.decode('00','hex')||pg_catalog.uuid_send(stage.legacy_endpoint_id)||
            pg_catalog.decode('00','hex')||differential.source_result_sha256||
            pg_catalog.decode('00','hex')||differential.target_result_sha256||
            pg_catalog.decode('00','hex')||differential.wire_contract_sha256||
            pg_catalog.decode('00','hex')||differential.compatible_image_sha256||
            pg_catalog.decode('00','hex')||stage.source_sha256)
        )
    ) OR (SELECT pg_catalog.count(*) FROM analytics_v1_adoption_differentials
          WHERE operation_id=p_operation_id AND run_id=p_run_id)<>
         (SELECT pg_catalog.count(*) FROM analytics_v1_adoption_stage
          WHERE operation_id=p_operation_id AND run_id=p_run_id
            AND NOT removed AND disposition='adopted') THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption rollback evidence differs';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
      pg_catalog.uuid_send(differential.legacy_endpoint_id)||
      differential.source_result_sha256||differential.target_result_sha256||
      differential.wire_contract_sha256||differential.compatible_image_sha256||
      differential.reverse_source_sha256||differential.evidence_sha256,
      ''::bytea ORDER BY differential.legacy_endpoint_id),''::bytea)),'hex')
    INTO v_digest FROM analytics_v1_adoption_differentials AS differential
    WHERE differential.operation_id=p_operation_id AND differential.run_id=p_run_id;
    RETURN v_digest;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_rollback_sha256_v1(p_operation_id uuid, p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_source_root_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_source_root_v1(p_operation_id uuid, p_run_id uuid, p_tenant_id uuid) RETURNS TABLE(row_count bigint, root_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_stage_count bigint;
    v_stage_root text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption source inventory denied';
    END IF;
    SELECT pg_catalog.count(*),pg_catalog.encode(pg_catalog.sha256(
      COALESCE(pg_catalog.string_agg(
        pg_catalog.uuid_send(stage.legacy_endpoint_id)||stage.source_sha256,
        ''::bytea ORDER BY stage.legacy_endpoint_id),''::bytea)),'hex')
    INTO v_stage_count,v_stage_root
    FROM analytics_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed;
    RETURN QUERY
    WITH live AS (
      SELECT endpoint.id,pg_catalog.sha256(pg_catalog.convert_to(
        pg_catalog.to_jsonb(endpoint)::text,'UTF8')) AS source_sha256
      FROM openapi_endpoints AS endpoint WHERE endpoint.tenant_id=p_tenant_id
    ), root AS (
      SELECT pg_catalog.count(*) AS count,
        pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
          pg_catalog.uuid_send(live.id)||live.source_sha256,
          ''::bytea ORDER BY live.id),''::bytea)),'hex') AS digest
      FROM live
    ) SELECT root.count,root.digest FROM root
      WHERE root.count=v_stage_count AND root.digest=v_stage_root;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption live source inventory differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_source_root_v1(p_operation_id uuid, p_run_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_value_valid_v1(jsonb, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_value_valid_v1(p_key jsonb, p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_disposition text;
    v_source jsonb;
    v_target jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.jsonb_typeof(p_key) IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(p_value) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_key) AS key)
         IS DISTINCT FROM ARRAY['legacy_endpoint_id']::text[] OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_value) AS key)
         IS DISTINCT FROM ARRAY[
          'disposition','reason_code','source_document','source_sha256',
          'target_document','target_sha256'
         ]::text[] THEN
        RETURN false;
    END IF;
    v_disposition:=p_value->>'disposition';
    v_source:=p_value->'source_document';
    v_target:=p_value->'target_document';
    IF pg_catalog.jsonb_typeof(v_source) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_source) AS key)
         IS DISTINCT FROM ARRAY[
          'config_json','created_at','created_by','deleted_at','description',
          'id','is_active','is_public','method','name','slug','tenant_id',
          'updated_at','updated_by'
         ]::text[] OR
       (p_key->>'legacy_endpoint_id')::uuid IS DISTINCT FROM
         (v_source->>'id')::uuid OR
       p_value->>'source_sha256' !~ '^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
         v_source::text,'UTF8'
       )),'hex') IS DISTINCT FROM p_value->>'source_sha256' OR
       pg_catalog.jsonb_typeof(v_source->'config_json') IS DISTINCT FROM 'object' OR
       v_source->>'method' NOT IN ('GET','POST') OR
       pg_catalog.octet_length(v_source->>'slug') NOT BETWEEN 1 AND 255 OR
       pg_catalog.octet_length(v_source->>'name') NOT BETWEEN 1 AND 255 THEN
        RETURN false;
    END IF;
    IF v_disposition IN ('blocked','retired') THEN
        RETURN p_value->'target_document'='null'::jsonb AND
          p_value->'target_sha256'='null'::jsonb AND
          p_value->>'reason_code'~'^[A-Z][A-Z0-9_]{0,63}$';
    END IF;
    IF v_disposition IS DISTINCT FROM 'adopted' OR
       p_value->'reason_code'<>'null'::jsonb OR
       v_source->>'is_active'<>'true' OR v_source->'deleted_at'<>'null'::jsonb OR
       pg_catalog.jsonb_typeof(v_target) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_target) AS key)
         IS DISTINCT FROM ARRAY[
          'approval','dependencies','differential','draft_version',
          'legacy_route','public_pointer','published_version','query','release'
         ]::text[] OR
       p_value->>'target_sha256' !~ '^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
         v_target::text,'UTF8'
       )),'hex') IS DISTINCT FROM p_value->>'target_sha256' OR
       pg_catalog.jsonb_typeof(v_target->'query') IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(v_target->'published_version') IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(v_target->'draft_version') IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(v_target->'dependencies') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_target->'dependencies') NOT BETWEEN 1 AND 32 OR
       pg_catalog.jsonb_typeof(v_target->'differential') IS DISTINCT FROM 'object' THEN
        RETURN false;
    END IF;
    RETURN (v_source->>'is_public'='true' AND
            pg_catalog.jsonb_typeof(v_target->'release')='object' AND
            pg_catalog.jsonb_typeof(v_target->'approval')='object' AND
            pg_catalog.jsonb_typeof(v_target->'public_pointer')='object' AND
            pg_catalog.jsonb_typeof(v_target->'legacy_route')='object')
        OR (v_source->>'is_public'='false' AND
            v_target->'release'='null'::jsonb AND
            v_target->'approval'='null'::jsonb AND
            v_target->'public_pointer'='null'::jsonb AND
            v_target->'legacy_route'='null'::jsonb);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RETURN false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_value_valid_v1(p_key jsonb, p_value jsonb) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_watermark_sha256_v1(uuid, uuid, pg_lsn); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_watermark_sha256_v1(p_operation_id uuid, p_run_id uuid, p_final_lsn pg_lsn) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_digest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_final_lsn IS NULL OR EXISTS (
        SELECT 1 FROM analytics_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
          AND stage.commit_lsn>p_final_lsn
       ) OR (SELECT pg_catalog.count(*) FROM platform.applied_change_receipts
             WHERE operation_id=p_operation_id AND run_id=p_run_id
               AND relation_ordinal=1 AND checkpoint_key='openapi_endpoints')<
            (SELECT pg_catalog.count(*) FROM analytics_v1_adoption_stage
             WHERE operation_id=p_operation_id AND run_id=p_run_id) THEN
      RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Analytics V1 adoption watermark evidence differs';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(
      pg_catalog.convert_to('analytics-v1-adoption-watermark.v1','UTF8')||
      pg_catalog.pg_lsn_send(p_final_lsn)||COALESCE(pg_catalog.string_agg(
        pg_catalog.uuid_send(stage.legacy_endpoint_id)||
        pg_catalog.xid8send(stage.source_xid)||pg_catalog.pg_lsn_send(stage.commit_lsn)||
        pg_catalog.int4send(stage.batch_ordinal)||
        pg_catalog.int2send(stage.change_ordinal),
        ''::bytea ORDER BY stage.legacy_endpoint_id),''::bytea)),'hex')
    INTO v_digest FROM analytics_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id;
    RETURN v_digest;
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_watermark_sha256_v1(p_operation_id uuid, p_run_id uuid, p_final_lsn pg_lsn) OWNER TO harpy_owner;

--
-- Name: analytics_v1_adoption_zero_hit_sha256_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.analytics_v1_adoption_zero_hit_sha256_v1(p_operation_id uuid, p_run_id uuid, p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_stage analytics_v1_adoption_stage%ROWTYPE;
    v_snapshot jsonb;
    v_material bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Analytics V1 adoption zero-hit evidence denied';
    END IF;
    v_material:=''::bytea;
    FOR v_stage IN
      SELECT stage.* FROM analytics_v1_adoption_stage AS stage
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed AND stage.disposition='adopted'
        AND (stage.source_document->>'is_public')::boolean
      ORDER BY stage.legacy_endpoint_id
    LOOP
      v_snapshot:=platform.analytics_v1_adoption_public_bridge_v1(
        'inspect',p_tenant_id,v_stage.legacy_endpoint_id,NULL);
      IF (v_snapshot->>'route_exists')::boolean IS NOT TRUE OR
         (v_snapshot->>'publication_exists')::boolean IS NOT TRUE OR
         v_snapshot->>'route_state' IS DISTINCT FROM 'active' OR
         (v_snapshot->>'hit_count')::bigint IS DISTINCT FROM 0 OR
         v_snapshot->'last_hit_at' IS DISTINCT FROM 'null'::jsonb OR
         v_snapshot->'consumers_acked_at' IS NOT DISTINCT FROM 'null'::jsonb OR
         v_snapshot->>'consumer_inventory_sha256' IS NULL OR
         v_snapshot->>'consumer_inventory_sha256'=repeat('0',64) OR
         (v_snapshot->>'remove_after')::timestamptz<=
           (v_snapshot->>'consumers_acked_at')::timestamptz OR
         v_snapshot->>'legacy_tenant_identity' IS DISTINCT FROM p_tenant_id::text OR
         v_snapshot->>'method' IS DISTINCT FROM
           v_stage.source_document->>'method' OR
         v_snapshot->>'path' IS DISTINCT FROM
           v_stage.source_document->'config_json'->>'path' OR
         v_snapshot->>'slug' IS DISTINCT FROM v_stage.source_document->>'slug' OR
         v_snapshot->>'route_public_id' IS DISTINCT FROM
           v_stage.target_document->'public_pointer'->>'public_id' OR
         v_snapshot->>'consumer_inventory_sha256' IS DISTINCT FROM
           v_stage.target_document->'legacy_route'->>'consumer_inventory_sha256' OR
         v_snapshot->>'publication_public_id' IS DISTINCT FROM
           v_snapshot->>'route_public_id' OR
         v_snapshot->>'publication_state' IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE='55000',
          MESSAGE='Analytics V1 adoption legacy route has traffic or no inventory';
      END IF;
      v_material:=v_material||pg_catalog.uuid_send(v_stage.legacy_endpoint_id)||
        pg_catalog.decode(v_snapshot->>'route_public_id','hex')||
        pg_catalog.decode(v_snapshot->>'consumer_inventory_sha256','hex')||
        pg_catalog.timestamptz_send(
          (v_snapshot->>'consumers_acked_at')::timestamptz)||
        pg_catalog.timestamptz_send((v_snapshot->>'remove_after')::timestamptz);
    END LOOP;
    RETURN pg_catalog.encode(pg_catalog.sha256(v_material),'hex');
END;
$$;


ALTER FUNCTION __tenant_schema__.analytics_v1_adoption_zero_hit_sha256_v1(p_operation_id uuid, p_run_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: audit_entries_list_v1(text, text, text, text, text, uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, text, integer, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_entries_list_v1(p_owner_module text, p_entity_type text, p_entity_id text, p_form_slug text, p_action text, p_actor_id uuid, p_organization_id uuid, p_correlation_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_search text, p_page integer, p_limit integer) RETURNS TABLE(id uuid, owner_audit_id uuid, actor_id uuid, organization_id uuid, correlation_id uuid, owner_module text, operation_id text, entity_type text, entity_id text, form_slug text, action text, authorization_version bigint, reason_code text, field_changes jsonb, event_sha256 bytea, occurred_at timestamp with time zone, recorded_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_page NOT BETWEEN 1 AND 1000 OR p_limit NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'AUDIT_PAGE_INVALID';
    END IF;
    RETURN QUERY
    SELECT entries.id, entries.owner_audit_id, entries.actor_id,
           entries.organization_id, entries.correlation_id, entries.owner_module,
           entries.operation_id, entries.entity_type, entries.entity_id,
           entries.form_slug, entries.action, entries.authorization_version,
           entries.reason_code, entries.field_changes, entries.event_sha256,
           entries.occurred_at, entries.recorded_at,
           pg_catalog.count(*) OVER ()::bigint
      FROM audit_entries AS entries
     WHERE (p_owner_module IS NULL OR entries.owner_module = p_owner_module)
       AND (p_entity_type IS NULL OR entries.entity_type = p_entity_type)
       AND (p_entity_id IS NULL OR entries.entity_id = p_entity_id)
       AND (p_form_slug IS NULL OR entries.form_slug = p_form_slug)
       AND (p_action IS NULL OR entries.action = p_action)
       AND (p_actor_id IS NULL OR entries.actor_id = p_actor_id)
       AND (p_organization_id IS NULL OR entries.organization_id = p_organization_id)
       AND (p_correlation_id IS NULL OR entries.correlation_id = p_correlation_id)
       AND (p_start_at IS NULL OR entries.occurred_at >= p_start_at)
       AND (p_end_at IS NULL OR entries.occurred_at <= p_end_at)
       AND (p_search IS NULL OR pg_catalog.strpos(
            pg_catalog.lower(
                entries.entity_id || ' ' || coalesce(entries.form_slug, '') ||
                ' ' || entries.owner_module
            ), pg_catalog.lower(p_search)) > 0)
     ORDER BY entries.occurred_at DESC, entries.id DESC
     OFFSET ((p_page - 1) * p_limit) LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.audit_entries_list_v1(p_owner_module text, p_entity_type text, p_entity_id text, p_form_slug text, p_action text, p_actor_id uuid, p_organization_id uuid, p_correlation_id uuid, p_start_at timestamp with time zone, p_end_at timestamp with time zone, p_search text, p_page integer, p_limit integer) OWNER TO harpy_owner;

--
-- Name: audit_entry_append_v1(uuid, uuid, uuid, uuid, uuid, text, text, text, text, text, text, bigint, text, jsonb, bytea, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_entry_append_v1(p_id uuid, p_owner_audit_id uuid, p_actor_id uuid, p_organization_id uuid, p_correlation_id uuid, p_owner_module text, p_operation_id text, p_entity_type text, p_entity_id text, p_form_slug text, p_action text, p_authorization_version bigint, p_reason_code text, p_field_changes jsonb, p_event_sha256 bytea, p_occurred_at timestamp with time zone, p_recorded_at timestamp with time zone) RETURNS TABLE(id uuid, owner_audit_id uuid, actor_id uuid, organization_id uuid, correlation_id uuid, owner_module text, operation_id text, entity_type text, entity_id text, form_slug text, action text, authorization_version bigint, reason_code text, field_changes jsonb, event_sha256 bytea, occurred_at timestamp with time zone, recorded_at timestamp with time zone, replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_entry audit_entries%ROWTYPE;
    v_rows bigint;
BEGIN
    INSERT INTO audit_entries (
        id, owner_audit_id, actor_id, organization_id, correlation_id,
        owner_module, operation_id, entity_type, entity_id, form_slug,
        action, authorization_version, reason_code, field_changes,
        event_sha256, occurred_at, recorded_at
    ) VALUES (
        p_id, p_owner_audit_id, p_actor_id, p_organization_id, p_correlation_id,
        p_owner_module, p_operation_id, p_entity_type, p_entity_id, p_form_slug,
        p_action, p_authorization_version, p_reason_code, p_field_changes,
        p_event_sha256, p_occurred_at, p_recorded_at
    ) ON CONFLICT ON CONSTRAINT audit_entries_owner_audit_id_key DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;

    SELECT entries.* INTO STRICT v_entry
      FROM audit_entries AS entries
     WHERE entries.owner_audit_id = p_owner_audit_id;
    IF v_entry.event_sha256 IS DISTINCT FROM p_event_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = 'P6802', MESSAGE = 'AUDIT_OWNER_KEY_REUSED';
    END IF;

    RETURN QUERY SELECT
        v_entry.id, v_entry.owner_audit_id, v_entry.actor_id,
        v_entry.organization_id, v_entry.correlation_id, v_entry.owner_module,
        v_entry.operation_id, v_entry.entity_type, v_entry.entity_id,
        v_entry.form_slug, v_entry.action, v_entry.authorization_version,
        v_entry.reason_code, v_entry.field_changes, v_entry.event_sha256,
        v_entry.occurred_at, v_entry.recorded_at, v_rows = 0;
END;
$$;


ALTER FUNCTION __tenant_schema__.audit_entry_append_v1(p_id uuid, p_owner_audit_id uuid, p_actor_id uuid, p_organization_id uuid, p_correlation_id uuid, p_owner_module text, p_operation_id text, p_entity_type text, p_entity_id text, p_form_slug text, p_action text, p_authorization_version bigint, p_reason_code text, p_field_changes jsonb, p_event_sha256 bytea, p_occurred_at timestamp with time zone, p_recorded_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: audit_entry_get_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_entry_get_v1(p_id uuid) RETURNS TABLE(id uuid, owner_audit_id uuid, actor_id uuid, organization_id uuid, correlation_id uuid, owner_module text, operation_id text, entity_type text, entity_id text, form_slug text, action text, authorization_version bigint, reason_code text, field_changes jsonb, event_sha256 bytea, occurred_at timestamp with time zone, recorded_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT entries.id, entries.owner_audit_id, entries.actor_id,
           entries.organization_id, entries.correlation_id, entries.owner_module,
           entries.operation_id, entries.entity_type, entries.entity_id,
           entries.form_slug, entries.action, entries.authorization_version,
           entries.reason_code, entries.field_changes, entries.event_sha256,
           entries.occurred_at, entries.recorded_at
      FROM audit_entries AS entries WHERE entries.id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P6801', MESSAGE = 'AUDIT_ENTRY_NOT_FOUND';
    END IF;
END;
$$;


