--
-- Name: audit_stats_v1(timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_stats_v1(p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
WITH action_groups AS (
    SELECT entries.action AS key, pg_catalog.count(*)::bigint AS value
      FROM audit_entries AS entries GROUP BY entries.action
), entity_groups AS (
    SELECT entries.entity_type AS key, pg_catalog.count(*)::bigint AS value
      FROM audit_entries AS entries GROUP BY entries.entity_type
), actor_groups AS (
    SELECT entries.actor_id, pg_catalog.count(*)::bigint AS value
      FROM audit_entries AS entries GROUP BY entries.actor_id
     ORDER BY value DESC, entries.actor_id LIMIT 10
), active_entities AS (
    SELECT entries.entity_type, entries.entity_id,
           coalesce(entries.form_slug, '') AS form_slug,
           pg_catalog.count(*)::bigint AS value
      FROM audit_entries AS entries
     GROUP BY entries.entity_type, entries.entity_id, entries.form_slug
     ORDER BY value DESC, entries.entity_type, entries.entity_id LIMIT 10
)
SELECT pg_catalog.jsonb_build_object(
    'total', (SELECT pg_catalog.count(*)::bigint FROM audit_entries),
    'last_24_hours', (SELECT pg_catalog.count(*)::bigint FROM audit_entries
                       WHERE occurred_at >= p_now - interval '24 hours'),
    'last_hour', (SELECT pg_catalog.count(*)::bigint FROM audit_entries
                   WHERE occurred_at >= p_now - interval '1 hour'),
    'by_action', coalesce((
        SELECT pg_catalog.jsonb_object_agg(key, value) FROM action_groups
    ), '{}'::jsonb),
    'by_entity', coalesce((
        SELECT pg_catalog.jsonb_object_agg(key, value) FROM entity_groups
    ), '{}'::jsonb),
    'actors', coalesce((
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'actor_id', actor_id, 'count', value) ORDER BY value DESC, actor_id)
          FROM actor_groups
    ), '[]'::jsonb),
    'entities', coalesce((
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'entity_type', entity_type, 'entity_id', entity_id,
            'form_slug', form_slug, 'count', value)
            ORDER BY value DESC, entity_type, entity_id)
          FROM active_entities
    ), '[]'::jsonb)
);
$$;


ALTER FUNCTION __tenant_schema__.audit_stats_v1(p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: audit_v1_adopt_batch_v1(uuid, uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_v1_adopt_batch_v1(p_operation_id uuid, p_run_id uuid, p_limit integer, p_observed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_run audit_v1_adoption_runs%ROWTYPE;
    v_existing audit_v1_adoption_runs%ROWTYPE;
    v_receipt audit_v1_adoption_receipts%ROWTYPE;
    v_relation regclass;
    v_source record;
    v_source_document jsonb;
    v_changes jsonb;
    v_source_sha bytea;
    v_target_sha bytea;
    v_request_sha bytea;
    v_source_hex text := '';
    v_target_hex text := '';
    v_target_id uuid;
    v_owner_id uuid;
    v_actor_id uuid;
    v_org_id uuid;
    v_correlation_id uuid;
    v_owner_module text;
    v_entity_type text;
    v_form_slug text;
    v_operation text;
    v_occurred_at timestamptz;
    v_cursor_at timestamp without time zone;
    v_cursor_id uuid;
    v_source_count bigint;
    v_drift_count bigint;
    v_rows integer := 0;
    v_page bigint;
    v_response jsonb;
BEGIN
    IF pg_catalog.substring(p_operation_id::text,15,1) <> '7'
       OR pg_catalog.substring(p_run_id::text,15,1) <> '7'
       OR p_limit NOT BETWEEN 1 AND 100 OR p_observed_at IS NULL
       OR pg_catalog.date_trunc('microseconds',p_observed_at) <> p_observed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='AUDIT_V1_BATCH_INVALID';
    END IF;
    v_request_sha := pg_catalog.sha256(pg_catalog.uuid_send(p_run_id) ||
        pg_catalog.int4send(p_limit));
    SELECT receipt.* INTO v_receipt FROM audit_v1_adoption_receipts AS receipt
     WHERE receipt.operation_id=p_operation_id;
    IF FOUND THEN
        IF v_receipt.run_id <> p_run_id OR v_receipt.request_sha256 <> v_request_sha THEN
            RAISE EXCEPTION USING ERRCODE='P6802', MESSAGE='AUDIT_V1_OPERATION_REUSED';
        END IF;
        RETURN v_receipt.response_document;
    END IF;

    v_relation := pg_catalog.to_regclass('change_logs');
    SELECT run.* INTO v_existing FROM audit_v1_adoption_runs AS run
     WHERE run.singleton FOR UPDATE;
    IF FOUND AND v_existing.run_id <> p_run_id THEN
        RAISE EXCEPTION USING ERRCODE='P6802', MESSAGE='AUDIT_V1_RUN_ALREADY_EXISTS';
    END IF;
    IF NOT FOUND THEN
        IF v_relation IS NULL THEN
            v_source_count := 0;
        ELSE
            EXECUTE pg_catalog.format('SELECT count(*) FROM %s',v_relation)
               INTO v_source_count;
        END IF;
        INSERT INTO audit_v1_adoption_runs (
            run_id,source_relation_oid,status,source_count,adopted_count,next_page,
            cursor_created_at,cursor_id,started_at
        ) VALUES (
            p_run_id,v_relation::oid,'applying',v_source_count,0,1,
            '-infinity'::timestamp,'00000000-0000-0000-0000-000000000000',p_observed_at
        ) RETURNING * INTO v_run;
    ELSE
        v_run := v_existing;
    END IF;
    IF v_run.source_relation_oid IS DISTINCT FROM v_relation::oid THEN
        RAISE EXCEPTION USING ERRCODE='P6803', MESSAGE='AUDIT_V1_SOURCE_RELATION_DRIFT';
    END IF;
    v_page := v_run.next_page;

    IF v_run.status='applying' AND v_relation IS NOT NULL THEN
        FOR v_source IN EXECUTE pg_catalog.format(
            'SELECT source.* FROM %s AS source '
            'WHERE (coalesce(source.created_at,''-infinity''::timestamp),source.id) > ($1,$2) '
            'ORDER BY coalesce(source.created_at,''-infinity''::timestamp),source.id LIMIT $3',
            v_relation)
            USING v_run.cursor_created_at,v_run.cursor_id,p_limit
        LOOP
            IF v_source.id IS NULL OR v_source.id='00000000-0000-0000-0000-000000000000'::uuid
               OR v_source.entity_id IS NULL OR pg_catalog.octet_length(v_source.entity_id) NOT BETWEEN 1 AND 200 THEN
                RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='AUDIT_V1_SOURCE_ROW_INVALID';
            END IF;
            v_source_document := pg_catalog.to_jsonb(v_source);
            v_source_sha := pg_catalog.sha256(pg_catalog.convert_to(v_source_document::text,'UTF8'));
            v_changes := audit_v1_redacted_changes_v1(
                v_source.old_data,v_source.new_data,v_source.changed_fields);
            v_target_id := audit_v1_derived_id_v1(v_source.id,'entry');
            v_owner_id := audit_v1_derived_id_v1(v_source.id,'owner');
            v_actor_id := CASE WHEN v_source.user_id IS NULL OR
                v_source.user_id='00000000-0000-0000-0000-000000000000'::uuid
                THEN audit_v1_derived_id_v1(
                    '00000000-0000-0000-0000-000000000001'::uuid,'system_actor')
                ELSE v_source.user_id END;
            v_org_id := CASE WHEN v_source.org_id IS NULL OR
                v_source.org_id='00000000-0000-0000-0000-000000000000'::uuid
                THEN NULL ELSE v_source.org_id END;
            v_correlation_id := NULL;
            IF v_source.correlation_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
                v_correlation_id := v_source.correlation_id::uuid;
                IF v_correlation_id='00000000-0000-0000-0000-000000000000'::uuid THEN
                    v_correlation_id := NULL;
                END IF;
            END IF;
            v_owner_module := audit_v1_owner_module_v1(v_source.entity_type);
            v_operation := audit_v1_operation_v1(v_source.entity_type,v_source.action);
            v_entity_type := CASE WHEN pg_catalog.lower(v_source.entity_type) ~
                '^[a-z][a-z0-9_.-]{0,127}$' THEN pg_catalog.lower(v_source.entity_type)
                ELSE 'legacy_entity' END;
            v_form_slug := CASE WHEN pg_catalog.lower(v_source.form_slug) ~
                '^[a-z][a-z0-9_.-]{0,99}$' THEN pg_catalog.lower(v_source.form_slug)
                ELSE NULL END;
            v_occurred_at := coalesce(v_source.created_at,
                p_observed_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
            INSERT INTO audit_entries (
                id,owner_audit_id,actor_id,organization_id,correlation_id,
                owner_module,operation_id,entity_type,entity_id,form_slug,action,
                authorization_version,reason_code,field_changes,event_sha256,
                occurred_at,recorded_at
            ) VALUES (
                v_target_id,v_owner_id,v_actor_id,v_org_id,v_correlation_id,
                v_owner_module,v_operation,v_entity_type,v_source.entity_id,v_form_slug,
                pg_catalog.lower(v_source.action),1,'v1_adopted',v_changes,v_source_sha,
                v_occurred_at,greatest(p_observed_at,v_occurred_at));
            v_target_sha := pg_catalog.sha256(pg_catalog.convert_to(
                pg_catalog.jsonb_build_object(
                    'id',v_target_id,'owner_audit_id',v_owner_id,'actor_id',v_actor_id,
                    'owner_module',v_owner_module,'operation',v_operation,
                    'entity_type',v_entity_type,'entity_id',v_source.entity_id,
                    'field_changes',v_changes,'event_sha256',pg_catalog.encode(v_source_sha,'hex'))::text,
                'UTF8'));
            INSERT INTO audit_v1_adoption_mappings (
                source_id,run_id,target_entry_id,target_owner_audit_id,source_sha256,
                target_sha256,page_number,adopted_at
            ) VALUES (
                v_source.id,p_run_id,v_target_id,v_owner_id,v_source_sha,
                v_target_sha,v_page,p_observed_at);
            v_source_hex := v_source_hex || pg_catalog.encode(v_source_sha,'hex');
            v_target_hex := v_target_hex || pg_catalog.encode(v_target_sha,'hex');
            v_cursor_at := coalesce(v_source.created_at,'-infinity'::timestamp);
            v_cursor_id := v_source.id;
            v_rows := v_rows + 1;
        END LOOP;
    END IF;

    IF v_rows > 0 THEN
        UPDATE audit_v1_adoption_runs AS run SET
            adopted_count=run.adopted_count+v_rows,next_page=run.next_page+1,
            cursor_created_at=v_cursor_at,cursor_id=v_cursor_id
         WHERE run.run_id=p_run_id RETURNING * INTO v_run;
    END IF;
    IF v_run.adopted_count=v_run.source_count AND v_run.status='applying' THEN
        IF v_relation IS NOT NULL THEN
            EXECUTE pg_catalog.format(
                'SELECT count(*) FROM %s AS source LEFT JOIN audit_v1_adoption_mappings AS mapping '
                'ON mapping.source_id=source.id AND mapping.source_sha256='
                'pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.to_jsonb(source)::text,''UTF8'')) '
                'WHERE mapping.source_id IS NULL',v_relation) INTO v_drift_count;
            EXECUTE pg_catalog.format('SELECT count(*) FROM %s',v_relation) INTO v_source_count;
        ELSE
            v_drift_count := 0;
            v_source_count := 0;
        END IF;
        IF v_drift_count <> 0 OR v_source_count <> v_run.source_count THEN
            RAISE EXCEPTION USING ERRCODE='P6803', MESSAGE='AUDIT_V1_SOURCE_DRIFT';
        END IF;
        UPDATE audit_v1_adoption_runs AS run SET status='completed',completed_at=p_observed_at
         WHERE run.run_id=p_run_id RETURNING * INTO v_run;
    END IF;

    v_response := audit_v1_run_document_v1(v_run);
    INSERT INTO audit_v1_adoption_receipts (
        operation_id,run_id,request_sha256,page_number,row_count,
        source_page_sha256,target_page_sha256,response_document,applied_at
    ) VALUES (
        p_operation_id,p_run_id,v_request_sha,v_page,v_rows,
        pg_catalog.sha256(pg_catalog.convert_to(v_source_hex,'UTF8')),
        pg_catalog.sha256(pg_catalog.convert_to(v_target_hex,'UTF8')),
        v_response,p_observed_at);
    RETURN v_response;
END;
$_$;


ALTER FUNCTION __tenant_schema__.audit_v1_adopt_batch_v1(p_operation_id uuid, p_run_id uuid, p_limit integer, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: audit_v1_derived_id_v1(uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_v1_derived_id_v1(p_source_id uuid, p_label text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_digest bytea;
    v_hex text;
BEGIN
    IF p_source_id IS NULL OR p_source_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR p_label !~ '^[a-z0-9_-]{1,64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'AUDIT_V1_IDENTITY_INVALID';
    END IF;
    v_digest := pg_catalog.sha256(
        pg_catalog.convert_to('harpy:audit:v1-adoption:v1','UTF8') ||
        pg_catalog.uuid_send(p_source_id) || '\x00'::bytea ||
        pg_catalog.convert_to(p_label,'UTF8'));
    v_digest := pg_catalog.set_byte(v_digest, 6,
        (pg_catalog.get_byte(v_digest, 6) & 15) | 112);
    v_digest := pg_catalog.set_byte(v_digest, 8,
        (pg_catalog.get_byte(v_digest, 8) & 63) | 128);
    v_hex := pg_catalog.encode(pg_catalog.substring(v_digest, 1, 16), 'hex');
    RETURN (pg_catalog.substring(v_hex,1,8) || '-' || pg_catalog.substring(v_hex,9,4) ||
        '-' || pg_catalog.substring(v_hex,13,4) || '-' ||
        pg_catalog.substring(v_hex,17,4) || '-' || pg_catalog.substring(v_hex,21,12))::uuid;
END;
$_$;


ALTER FUNCTION __tenant_schema__.audit_v1_derived_id_v1(p_source_id uuid, p_label text) OWNER TO harpy_owner;

--
-- Name: audit_v1_operation_v1(text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_v1_operation_v1(p_entity_type text, p_action text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_prefix text;
BEGIN
    IF pg_catalog.lower(p_action) NOT IN ('create','update','delete') THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='AUDIT_V1_ACTION_INVALID';
    END IF;
    v_prefix := CASE pg_catalog.lower(p_entity_type)
        WHEN 'form_record' THEN 'forms.record' WHEN 'form_config' THEN 'forms.definition'
        WHEN 'user' THEN 'iam.user' WHEN 'role' THEN 'iam.role'
        WHEN 'organization' THEN 'iam.organization' WHEN 'permission' THEN 'iam.permission'
        WHEN 'document' THEN 'documents.item' WHEN 'workflow' THEN 'workflow.definition'
        ELSE 'audit.legacy' END;
    RETURN v_prefix || '.' || pg_catalog.lower(p_action);
END;
$$;


ALTER FUNCTION __tenant_schema__.audit_v1_operation_v1(p_entity_type text, p_action text) OWNER TO harpy_owner;

--
-- Name: audit_v1_owner_module_v1(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_v1_owner_module_v1(p_entity_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
SELECT CASE pg_catalog.lower(p_entity_type)
    WHEN 'form_record' THEN 'forms' WHEN 'form_config' THEN 'forms'
    WHEN 'user' THEN 'iam' WHEN 'role' THEN 'iam'
    WHEN 'organization' THEN 'iam' WHEN 'permission' THEN 'iam'
    WHEN 'document' THEN 'documents' WHEN 'workflow' THEN 'workflow'
    ELSE 'audit' END;
$$;


ALTER FUNCTION __tenant_schema__.audit_v1_owner_module_v1(p_entity_type text) OWNER TO harpy_owner;

--
-- Name: audit_v1_redacted_changes_v1(jsonb, jsonb, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_v1_redacted_changes_v1(p_old jsonb, p_new jsonb, p_changed jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_old jsonb := CASE WHEN pg_catalog.jsonb_typeof(p_old)='object' THEN p_old ELSE '{}'::jsonb END;
    v_new jsonb := CASE WHEN pg_catalog.jsonb_typeof(p_new)='object' THEN p_new ELSE '{}'::jsonb END;
    v_changed jsonb := CASE WHEN pg_catalog.jsonb_typeof(p_changed)='array' THEN p_changed ELSE '[]'::jsonb END;
    v_result jsonb := '[]'::jsonb;
    v_seen jsonb := '{}'::jsonb;
    v_field text;
    v_safe text;
    v_item jsonb;
    v_before bytea;
    v_after bytea;
BEGIN
    FOR v_field IN
        SELECT key FROM (
            SELECT key FROM pg_catalog.jsonb_object_keys(v_old) AS old_keys(key)
            UNION SELECT key FROM pg_catalog.jsonb_object_keys(v_new) AS new_keys(key)
            UNION SELECT value->>'field' FROM pg_catalog.jsonb_array_elements(v_changed)
                  WHERE pg_catalog.jsonb_typeof(value)='object' AND value ? 'field'
        ) AS fields WHERE key IS NOT NULL ORDER BY key LIMIT 100
    LOOP
        SELECT value INTO v_item FROM pg_catalog.jsonb_array_elements(v_changed)
         WHERE value->>'field'=v_field LIMIT 1;
        v_before := NULL;
        v_after := NULL;
        IF v_item IS NOT NULL THEN
            IF v_item ? 'old_value' THEN
                v_before := pg_catalog.sha256(pg_catalog.convert_to((v_item->'old_value')::text,'UTF8'));
            END IF;
            IF v_item ? 'new_value' THEN
                v_after := pg_catalog.sha256(pg_catalog.convert_to((v_item->'new_value')::text,'UTF8'));
            END IF;
        ELSE
            IF v_old ? v_field THEN
                v_before := pg_catalog.sha256(pg_catalog.convert_to((v_old->v_field)::text,'UTF8'));
            END IF;
            IF v_new ? v_field THEN
                v_after := pg_catalog.sha256(pg_catalog.convert_to((v_new->v_field)::text,'UTF8'));
            END IF;
        END IF;
        IF v_before IS NULL AND v_after IS NULL OR v_before IS NOT NULL AND v_before=v_after THEN
            CONTINUE;
        END IF;
        v_safe := pg_catalog.lower(pg_catalog.regexp_replace(v_field,'[^a-zA-Z0-9_.-]+','_','g'));
        IF v_safe !~ '^[a-z][a-z0-9_.-]{0,127}$' THEN
            v_safe := 'legacy_' || pg_catalog.substring(pg_catalog.encode(
                pg_catalog.sha256(pg_catalog.convert_to(v_field,'UTF8')),'hex'),1,32);
        ELSE
            v_safe := pg_catalog.substring(v_safe,1,128);
        END IF;
        IF v_seen ? v_safe THEN
            CONTINUE;
        END IF;
        v_seen := v_seen || pg_catalog.jsonb_build_object(v_safe,true);
        v_result := v_result || pg_catalog.jsonb_build_array(pg_catalog.jsonb_strip_nulls(
            pg_catalog.jsonb_build_object(
                'field',v_safe,'classification','confidential',
                'before_sha256',CASE WHEN v_before IS NULL THEN NULL ELSE pg_catalog.encode(v_before,'hex') END,
                'after_sha256',CASE WHEN v_after IS NULL THEN NULL ELSE pg_catalog.encode(v_after,'hex') END)));
    END LOOP;
    RETURN v_result;
END;
$_$;


ALTER FUNCTION __tenant_schema__.audit_v1_redacted_changes_v1(p_old jsonb, p_new jsonb, p_changed jsonb) OWNER TO harpy_owner;

--
-- Name: audit_v1_adoption_runs; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.audit_v1_adoption_runs (
    run_id uuid NOT NULL,
    singleton boolean DEFAULT true NOT NULL,
    source_relation_oid oid,
    status text NOT NULL,
    source_count bigint NOT NULL,
    adopted_count bigint NOT NULL,
    next_page bigint NOT NULL,
    cursor_created_at timestamp without time zone NOT NULL,
    cursor_id uuid NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT audit_v1_adoption_runs_check CHECK (((adopted_count >= 0) AND (adopted_count <= source_count))),
    CONSTRAINT audit_v1_adoption_runs_check1 CHECK ((((status = 'applying'::text) AND (completed_at IS NULL)) OR ((status = 'completed'::text) AND (completed_at IS NOT NULL) AND (adopted_count = source_count)))),
    CONSTRAINT audit_v1_adoption_runs_next_page_check CHECK ((next_page > 0)),
    CONSTRAINT audit_v1_adoption_runs_run_id_check CHECK (("substring"((run_id)::text, 15, 1) = '7'::text)),
    CONSTRAINT audit_v1_adoption_runs_singleton_check CHECK (singleton),
    CONSTRAINT audit_v1_adoption_runs_source_count_check CHECK ((source_count >= 0)),
    CONSTRAINT audit_v1_adoption_runs_status_check CHECK ((status = ANY (ARRAY['applying'::text, 'completed'::text])))
);


ALTER TABLE __tenant_schema__.audit_v1_adoption_runs OWNER TO harpy_owner;

--
-- Name: audit_v1_run_document_v1(__tenant_schema__.audit_v1_adoption_runs); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.audit_v1_run_document_v1(p_run __tenant_schema__.audit_v1_adoption_runs) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
SELECT pg_catalog.jsonb_build_object(
    'run_id',p_run.run_id,'status',p_run.status,'source_count',p_run.source_count,
    'adopted_count',p_run.adopted_count,'next_page',p_run.next_page,
    'cursor_created_at',p_run.cursor_created_at,'cursor_id',p_run.cursor_id,
    'started_at',p_run.started_at,'completed_at',p_run.completed_at);
$$;


ALTER FUNCTION __tenant_schema__.audit_v1_run_document_v1(p_run __tenant_schema__.audit_v1_adoption_runs) OWNER TO harpy_owner;

--
-- Name: catalog_adoption_blocker_sha256_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_adoption_blocker_sha256_v1(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_digest text;
BEGIN
    SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
      pg_catalog.int4send(pg_catalog.octet_length(row.blocker))||
      pg_catalog.convert_to(row.blocker,'UTF8'),
      ''::bytea ORDER BY row.blocker),''::bytea)),'hex')
    INTO v_digest FROM catalog_adoption_blockers_v1(p_tenant_id) AS row;
    RETURN v_digest;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_adoption_blocker_sha256_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: catalog_adoption_blockers_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_adoption_blockers_v1(p_tenant_id uuid) RETURNS TABLE(blocker text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER NOT IN ('harpy_v2_runtime','harpy_adopter') OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS tenant
        WHERE tenant.singleton AND tenant.tenant_id=p_tenant_id
          AND tenant.schema_name=pg_catalog.current_schema()
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog adoption blocker authority denied';
    END IF;
    IF pg_catalog.to_regclass('modules') IS NULL THEN
        RETURN;
    END IF;
    IF pg_catalog.to_regclass('module_dependencies') IS NULL OR
       pg_catalog.to_regclass('module_forms') IS NULL OR
       pg_catalog.to_regclass('module_schema_versions') IS NULL OR
       pg_catalog.to_regclass('module_migration_runs') IS NULL OR
       pg_catalog.to_regclass('menu_configs') IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog adoption legacy inventory is incomplete';
    END IF;
    RETURN QUERY
    SELECT value FROM (
      SELECT 'ORPHAN_DEPENDENCY:'||dependency.id::text AS value
      FROM module_dependencies AS dependency
      LEFT JOIN modules AS owner ON owner.id=dependency.module_id
      LEFT JOIN modules AS wanted ON wanted.id=dependency.depends_on_module_id
      WHERE owner.id IS NULL OR wanted.id IS NULL OR
        owner.tenant_id<>p_tenant_id OR wanted.tenant_id<>p_tenant_id OR
        owner.deleted_at IS NOT NULL OR wanted.deleted_at IS NOT NULL
      UNION ALL
      SELECT 'ORPHAN_FORM:'||form_row.id::text
      FROM module_forms AS form_row
      LEFT JOIN modules AS owner ON owner.id=form_row.module_id
      WHERE owner.id IS NULL OR owner.tenant_id<>p_tenant_id OR
        owner.deleted_at IS NOT NULL OR form_row.form_config_id IS NULL
      UNION ALL
      SELECT 'UNRESOLVED_MENU:'||menu.id::text FROM menu_configs AS menu
      WHERE menu.tenant_id=p_tenant_id AND menu.deleted_at IS NULL
        AND pg_catalog.jsonb_typeof(menu.config) NOT IN ('object','array')
      UNION ALL
      SELECT CASE registry.blocker
        WHEN 'UNKNOWN_PACKAGE' THEN 'UNKNOWN_MODULE'
        ELSE registry.blocker END||':'||module.id::text
      FROM modules AS module
      CROSS JOIN platform.catalog_adoption_registry_blocker_v1(
        module.id,module.slug,module.version,NULL
      ) AS registry(blocker)
      WHERE module.tenant_id=p_tenant_id AND module.deleted_at IS NULL
        AND registry.blocker IS NOT NULL
      UNION ALL
      SELECT CASE registry.blocker
        WHEN 'UNKNOWN_PACKAGE' THEN 'UNKNOWN_MANIFEST_PACKAGE'
        WHEN 'UNKNOWN_VERSION' THEN 'UNKNOWN_MANIFEST_VERSION'
        ELSE registry.blocker END||':'||source.id::text
      FROM module_schema_versions AS source
      CROSS JOIN platform.catalog_adoption_registry_blocker_v1(
        NULL,source.module_slug,source.module_version,source.manifest_hash
      ) AS registry(blocker)
      WHERE source.tenant_id=p_tenant_id AND registry.blocker IS NOT NULL
    ) AS blockers ORDER BY value;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_adoption_blockers_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: catalog_adoption_inventory_root_v1(uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_adoption_inventory_root_v1(p_tenant_id uuid, p_side text) RETURNS TABLE(row_count bigint, root_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_side NOT IN ('source','target') THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog adoption inventory side invalid';
    END IF;
    RETURN QUERY SELECT pg_catalog.count(*),
      pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
        pg_catalog.int4send(pg_catalog.octet_length(row.kind))||
        pg_catalog.convert_to(row.kind,'UTF8')||
        pg_catalog.int4send(pg_catalog.octet_length(row.identity))||
        pg_catalog.convert_to(row.identity,'UTF8')||
        pg_catalog.int4send(pg_catalog.octet_length(row.document))||
        pg_catalog.convert_to(row.document,'UTF8'),
        ''::bytea ORDER BY row.kind,row.identity),''::bytea)),'hex')
    FROM catalog_adoption_inventory_v1(p_tenant_id) AS row
    WHERE row.side=p_side;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_adoption_inventory_root_v1(p_tenant_id uuid, p_side text) OWNER TO harpy_owner;

--
-- Name: catalog_adoption_inventory_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_adoption_inventory_v1(p_tenant_id uuid) RETURNS TABLE(side text, kind text, identity text, document text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER NOT IN ('harpy_v2_runtime','harpy_adopter') OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS tenant
        WHERE tenant.singleton AND tenant.tenant_id=p_tenant_id
          AND tenant.schema_name=pg_catalog.current_schema()
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog adoption inventory authority denied';
    END IF;
    IF (pg_catalog.to_regclass('modules') IS NULL) IS DISTINCT FROM
       (pg_catalog.to_regclass('module_dependencies') IS NULL) OR
       (pg_catalog.to_regclass('modules') IS NULL) IS DISTINCT FROM
       (pg_catalog.to_regclass('module_forms') IS NULL) OR
       (pg_catalog.to_regclass('modules') IS NULL) IS DISTINCT FROM
       (pg_catalog.to_regclass('module_schema_versions') IS NULL) OR
       (pg_catalog.to_regclass('modules') IS NULL) IS DISTINCT FROM
       (pg_catalog.to_regclass('module_migration_runs') IS NULL) OR
       (pg_catalog.to_regclass('modules') IS NULL) IS DISTINCT FROM
       (pg_catalog.to_regclass('menu_configs') IS NULL) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog adoption legacy inventory is incomplete';
    END IF;
    IF pg_catalog.to_regclass('modules') IS NOT NULL THEN
        RETURN QUERY SELECT 'source','module',row.id::text,to_jsonb(row)::text
        FROM modules AS row WHERE row.tenant_id=p_tenant_id
          AND row.deleted_at IS NULL;
    END IF;
    IF pg_catalog.to_regclass('module_dependencies') IS NOT NULL THEN
        RETURN QUERY SELECT 'source','dependency',row.id::text,to_jsonb(row)::text
        FROM module_dependencies AS row JOIN modules AS owner
          ON owner.id=row.module_id
        WHERE owner.tenant_id=p_tenant_id AND owner.deleted_at IS NULL;
    END IF;
    IF pg_catalog.to_regclass('module_forms') IS NOT NULL THEN
        RETURN QUERY SELECT 'source','form',row.id::text,to_jsonb(row)::text
        FROM module_forms AS row JOIN modules AS owner ON owner.id=row.module_id
        WHERE owner.tenant_id=p_tenant_id AND owner.deleted_at IS NULL;
    END IF;
    IF pg_catalog.to_regclass('module_schema_versions') IS NOT NULL THEN
        RETURN QUERY SELECT 'source','schema_version',row.id::text,to_jsonb(row)::text
        FROM module_schema_versions AS row WHERE row.tenant_id=p_tenant_id;
    END IF;
    IF pg_catalog.to_regclass('module_migration_runs') IS NOT NULL THEN
        RETURN QUERY SELECT 'source','migration_run',row.id::text,to_jsonb(row)::text
        FROM module_migration_runs AS row WHERE row.tenant_id=p_tenant_id;
    END IF;
    IF pg_catalog.to_regclass('menu_configs') IS NOT NULL THEN
        RETURN QUERY SELECT 'source','menu',row.id::text,to_jsonb(row)::text
        FROM menu_configs AS row WHERE row.tenant_id=p_tenant_id
          AND row.deleted_at IS NULL;
    END IF;
    RETURN QUERY
    SELECT 'target','installation',row.installation_id::text,to_jsonb(row)::text
      FROM catalog_installations AS row
    UNION ALL SELECT 'target','binding',row.component_id::text,to_jsonb(row)::text
      FROM catalog_component_bindings AS row
    UNION ALL SELECT 'target','dependency',
      row.installation_id::text||':'||row.dependency_package_id::text,to_jsonb(row)::text
      FROM catalog_dependency_resolutions AS row
    UNION ALL SELECT 'target','menu_definition',row.definition_id::text,to_jsonb(row)::text
      FROM catalog_menu_definitions AS row
    UNION ALL SELECT 'target','menu_version',row.version_id::text,to_jsonb(row)::text
      FROM catalog_menu_versions AS row
    UNION ALL SELECT 'target','menu_item',
      row.version_id::text||':'||row.item_id::text,to_jsonb(row)::text
      FROM catalog_menu_items AS row;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_adoption_inventory_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: catalog_catalog_component_apply_v1(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_catalog_component_apply_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component catalog_catalog_components%ROWTYPE;
    v_receipt catalog_catalog_component_receipts%ROWTYPE;
    v_next text;
BEGIN
    SELECT * INTO v_receipt FROM catalog_catalog_component_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id AND receipt.component_id=p_component_id
      AND receipt.action=p_action;
    IF FOUND THEN
        IF v_receipt.owner_generation<>p_generation OR v_receipt.contract<>p_contract
           OR v_receipt.content_sha256<>p_content_sha256
           OR v_receipt.idempotency_key<>p_idempotency_key THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='catalog component receipt differs';
        END IF;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.owner_module,v_receipt.owner_generation,
            v_receipt.contract,v_receipt.content_sha256,v_receipt.action,
            v_receipt.ready,v_receipt.completed_at;
        RETURN;
    END IF;
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_owner IS DISTINCT FROM 'catalog' OR p_generation<1 OR
       p_contract IS NULL OR p_content_sha256!~'^[0-9a-f]{64}$' OR
       p_action NOT IN ('stage','cleanup','activate','disable','enable','retire','restore','purge') OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_completed_at IS NULL OR date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='catalog component command invalid';
    END IF;
    SELECT * INTO v_component FROM catalog_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    IF NOT FOUND OR v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR v_component.contract<>p_contract OR
       v_component.content_sha256<>p_content_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='catalog component authority differs';
    END IF;
    v_next := CASE
      WHEN p_action='stage' AND v_component.lifecycle_state='AVAILABLE' THEN 'STAGED'
      WHEN p_action='cleanup' AND v_component.lifecycle_state='STAGED' THEN 'AVAILABLE'
      WHEN p_action='activate' AND v_component.lifecycle_state='STAGED' THEN 'ACTIVE'
      WHEN p_action='disable' AND v_component.lifecycle_state='ACTIVE' THEN 'DISABLED'
      WHEN p_action='enable' AND v_component.lifecycle_state='DISABLED' THEN 'ACTIVE'
      WHEN p_action='retire' AND v_component.lifecycle_state IN ('ACTIVE','DISABLED') THEN 'RETIRED'
      WHEN p_action='restore' AND v_component.lifecycle_state='RETIRED' THEN 'ACTIVE'
      WHEN p_action='purge' AND v_component.lifecycle_state='RETIRED' THEN 'PURGED'
      ELSE NULL END;
    IF v_next IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='catalog component transition invalid';
    END IF;
    IF p_action='purge' AND (p_reference_epoch<1 OR NOT EXISTS (
        SELECT 1 FROM catalog_catalog_blocker_receipts AS blocker
        WHERE blocker.operation_id=p_operation_id AND blocker.component_id=p_component_id
          AND blocker.reference_epoch=p_reference_epoch AND blocker.blockers='[]'::jsonb
    )) THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='catalog purge receipt unavailable';
    END IF;
    UPDATE catalog_catalog_components SET lifecycle_state=v_next,updated_at=p_completed_at
    WHERE catalog_catalog_components.component_id=p_component_id;
    INSERT INTO catalog_catalog_component_receipts (
        receipt_id,operation_id,component_id,owner_module,owner_generation,
        contract,content_sha256,action,idempotency_key,ready,completed_at
    ) VALUES (p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
        p_contract,p_content_sha256,p_action,p_idempotency_key,true,p_completed_at)
    RETURNING * INTO v_receipt;
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.owner_module,v_receipt.owner_generation,
        v_receipt.contract,v_receipt.content_sha256,v_receipt.action,
        v_receipt.ready,v_receipt.completed_at;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_catalog_component_apply_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: catalog_catalog_component_blockers_v1(uuid, uuid, uuid, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_catalog_component_blockers_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_reference_epoch bigint, p_generation bigint, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, reference_epoch bigint, catalog_version text, zero_digest text, blockers jsonb, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_component catalog_catalog_components%ROWTYPE;
    v_receipt catalog_catalog_blocker_receipts%ROWTYPE;
    v_blockers jsonb;
    v_digest text;
BEGIN
    SELECT * INTO v_receipt FROM catalog_catalog_blocker_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id AND receipt.component_id=p_component_id
      AND receipt.reference_epoch=p_reference_epoch;
    IF FOUND THEN
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.reference_epoch,v_receipt.catalog_version,
            v_receipt.zero_digest,v_receipt.blockers,v_receipt.completed_at;
        RETURN;
    END IF;
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_reference_epoch<1 OR p_generation<1 OR p_completed_at IS NULL OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='catalog blocker request invalid';
    END IF;
    SELECT * INTO v_component FROM catalog_catalog_components AS component
    WHERE component.component_id=p_component_id FOR SHARE;
    IF NOT FOUND OR v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR v_component.lifecycle_state<>'RETIRED' THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='catalog blocker authority differs';
    END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'Owner','catalog','Code',blocker.code,'Digest',blocker.digest
    ) ORDER BY blocker.code),'[]'::jsonb) INTO v_blockers
    FROM catalog_catalog_component_blockers AS blocker
    WHERE blocker.component_id=p_component_id AND blocker.active;
    v_digest := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'catalog-catalog-blockers.v1'||E'\\000'||p_component_id::text||E'\\000'||
        p_reference_epoch::text||E'\\000'||v_blockers::text,'UTF8'
    )),'hex');
    INSERT INTO catalog_catalog_blocker_receipts (
        receipt_id,operation_id,component_id,reference_epoch,catalog_version,
        zero_digest,blockers,completed_at
    ) VALUES (p_receipt_id,p_operation_id,p_component_id,p_reference_epoch,
        'catalog-catalog-blockers.v1',v_digest,v_blockers,p_completed_at)
    RETURNING * INTO v_receipt;
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.reference_epoch,v_receipt.catalog_version,
        v_receipt.zero_digest,v_receipt.blockers,v_receipt.completed_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_catalog_component_blockers_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_reference_epoch bigint, p_generation bigint, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: catalog_consume_purge_approval_v2(name, uuid, uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_consume_purge_approval_v2(p_scope_schema name, p_receipt_id uuid, p_tenant_id uuid, p_package_id uuid, p_operation_id uuid, p_requested_by uuid, p_approved_by uuid, p_backup_receipt_id uuid, p_confirmation_slug text, p_reason text, p_purge_idempotency_key text, p_approval_sha256 text, p_authority_sha256 text, p_consumed_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE v_receipt catalog_purge_approval_receipts_v2%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT EXISTS (SELECT 1 FROM tenancy_schema_identity i WHERE i.singleton
           AND i.schema_name=pg_catalog.current_schema() AND i.tenant_id=p_tenant_id) OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_approval_sha256 !~ '^[0-9a-f]{64}$' OR
       p_authority_sha256 !~ '^[0-9a-f]{64}$' OR NOT isfinite(p_consumed_at) OR
       date_trunc('microseconds',p_consumed_at)<>p_consumed_at THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Catalog purge approval consume authority is invalid';
    END IF;
    SELECT * INTO v_receipt FROM catalog_purge_approval_receipts_v2
    WHERE receipt_id=p_receipt_id FOR UPDATE;
    IF v_receipt.receipt_id IS NULL OR v_receipt.tenant_id<>p_tenant_id OR
       v_receipt.package_id<>p_package_id OR v_receipt.operation_id<>p_operation_id OR
       v_receipt.requested_by<>p_requested_by OR v_receipt.approved_by<>p_approved_by OR
       v_receipt.backup_receipt_id<>p_backup_receipt_id OR
       v_receipt.confirmation_slug<>p_confirmation_slug OR v_receipt.reason<>p_reason OR
       v_receipt.purge_idempotency_key<>p_purge_idempotency_key OR
       v_receipt.approval_sha256<>p_approval_sha256 OR
       p_consumed_at<v_receipt.approved_at OR p_consumed_at>v_receipt.expires_at THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Catalog purge approval consumption differs';
    END IF;
    IF v_receipt.state='CONSUMED' THEN
        IF v_receipt.consumed_operation_id<>p_operation_id OR
           v_receipt.consumed_authority_sha256<>p_authority_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='Catalog purge approval already consumed';
        END IF;
        RETURN v_receipt.approval_sha256;
    END IF;
    UPDATE catalog_purge_approval_receipts_v2 SET state='CONSUMED',
        consumed_operation_id=p_operation_id,consumed_authority_sha256=p_authority_sha256,
        consumed_at=p_consumed_at WHERE receipt_id=p_receipt_id;
    RETURN v_receipt.approval_sha256;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_consume_purge_approval_v2(p_scope_schema name, p_receipt_id uuid, p_tenant_id uuid, p_package_id uuid, p_operation_id uuid, p_requested_by uuid, p_approved_by uuid, p_backup_receipt_id uuid, p_confirmation_slug text, p_reason text, p_purge_idempotency_key text, p_approval_sha256 text, p_authority_sha256 text, p_consumed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: catalog_purge_approval_receipts_v2; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.catalog_purge_approval_receipts_v2 (
    receipt_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    installation_id uuid NOT NULL,
    package_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    requested_by uuid NOT NULL,
    approved_by uuid NOT NULL,
    backup_receipt_id uuid NOT NULL,
    backup_sha256 text NOT NULL,
    confirmation_slug text NOT NULL,
    reason text NOT NULL,
    purge_idempotency_key text CONSTRAINT catalog_purge_approval_receipts__purge_idempotency_key_not_null NOT NULL,
    request_sha256 text NOT NULL,
    approval_idempotency_key text CONSTRAINT catalog_purge_approval_receip_approval_idempotency_key_not_null NOT NULL,
    step_up_authenticated_at timestamp with time zone CONSTRAINT catalog_purge_approval_receip_step_up_authenticated_at_not_null NOT NULL,
    approved_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    approval_sha256 text NOT NULL,
    consumed_operation_id uuid,
    consumed_authority_sha256 text,
    consumed_at timestamp with time zone,
    CONSTRAINT catalog_purge_approval_package_id_nonzero CHECK (((package_id IS NOT NULL) AND (package_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT catalog_purge_approval_receipts__approval_idempotency_key_check CHECK ((approval_idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'::text)),
    CONSTRAINT catalog_purge_approval_receipts_consumed_authority_sha256_check CHECK ((consumed_authority_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT catalog_purge_approval_receipts_v2_approval_sha256_check CHECK ((approval_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT catalog_purge_approval_receipts_v2_backup_sha256_check CHECK ((backup_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT catalog_purge_approval_receipts_v2_check CHECK ((requested_by <> approved_by)),
    CONSTRAINT catalog_purge_approval_receipts_v2_check1 CHECK ((step_up_authenticated_at <= approved_at)),
    CONSTRAINT catalog_purge_approval_receipts_v2_check2 CHECK ((step_up_authenticated_at >= (approved_at - '00:10:00'::interval))),
    CONSTRAINT catalog_purge_approval_receipts_v2_check3 CHECK ((expires_at > approved_at)),
    CONSTRAINT catalog_purge_approval_receipts_v2_check4 CHECK ((((state = 'AVAILABLE'::text) AND (consumed_operation_id IS NULL) AND (consumed_authority_sha256 IS NULL) AND (consumed_at IS NULL)) OR ((state = 'CONSUMED'::text) AND (consumed_operation_id IS NOT NULL) AND (consumed_authority_sha256 IS NOT NULL) AND (consumed_at IS NOT NULL)))),
    CONSTRAINT catalog_purge_approval_receipts_v2_confirmation_slug_check CHECK ((confirmation_slug ~ '^[a-z][a-z0-9-]{1,62}$'::text)),
    CONSTRAINT catalog_purge_approval_receipts_v2_package_id_check CHECK ((package_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT catalog_purge_approval_receipts_v2_purge_idempotency_key_check CHECK ((purge_idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'::text)),
    CONSTRAINT catalog_purge_approval_receipts_v2_reason_check CHECK (((length(reason) >= 1) AND (length(reason) <= 1024))),
    CONSTRAINT catalog_purge_approval_receipts_v2_request_sha256_check CHECK ((request_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT catalog_purge_approval_receipts_v2_state_check CHECK ((state = ANY (ARRAY['AVAILABLE'::text, 'CONSUMED'::text]))),
    CONSTRAINT catalog_purge_approval_receipts_v2_tenant_id_check CHECK ((tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid))
);


ALTER TABLE __tenant_schema__.catalog_purge_approval_receipts_v2 OWNER TO harpy_owner;

--
-- Name: catalog_create_purge_approval_v2(name, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_create_purge_approval_v2(p_scope_schema name, p_receipt_id uuid, p_tenant_id uuid, p_installation_id uuid, p_package_id uuid, p_operation_id uuid, p_requested_by uuid, p_approved_by uuid, p_backup_receipt_id uuid, p_backup_sha256 text, p_confirmation_slug text, p_reason text, p_purge_idempotency_key text, p_request_sha256 text, p_approval_idempotency_key text, p_step_up_at timestamp with time zone, p_approved_at timestamp with time zone, p_expires_at timestamp with time zone, p_approval_sha256 text) RETURNS SETOF __tenant_schema__.catalog_purge_approval_receipts_v2
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_installation catalog_installations%ROWTYPE;
    v_existing catalog_purge_approval_receipts_v2%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT EXISTS (SELECT 1 FROM tenancy_schema_identity i WHERE i.singleton
           AND i.schema_name=pg_catalog.current_schema() AND i.tenant_id=p_tenant_id) OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_tenant_id IS NULL OR p_tenant_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_installation_id) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR p_package_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_requested_by) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_approved_by) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_backup_receipt_id) IS DISTINCT FROM 7 OR
       p_backup_sha256 !~ '^[0-9a-f]{64}$' OR p_request_sha256 !~ '^[0-9a-f]{64}$' OR
       p_approval_sha256 !~ '^[0-9a-f]{64}$' OR
       p_purge_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$' OR
       p_approval_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$' OR
       NOT isfinite(p_step_up_at) OR NOT isfinite(p_approved_at) OR NOT isfinite(p_expires_at) OR
       date_trunc('microseconds',p_step_up_at)<>p_step_up_at OR
       date_trunc('microseconds',p_approved_at)<>p_approved_at OR
       date_trunc('microseconds',p_expires_at)<>p_expires_at THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Catalog purge approval identifiers are invalid';
    END IF;
    SELECT * INTO v_existing FROM catalog_purge_approval_receipts_v2
    WHERE approved_by=p_approved_by AND approval_idempotency_key=p_approval_idempotency_key
    FOR SHARE;
    IF FOUND THEN
        IF v_existing.request_sha256<>p_request_sha256 OR
           v_existing.tenant_id<>p_tenant_id OR
           v_existing.installation_id<>p_installation_id OR
           v_existing.package_id<>p_package_id OR v_existing.operation_id<>p_operation_id OR
           v_existing.requested_by<>p_requested_by OR
           v_existing.backup_receipt_id<>p_backup_receipt_id OR
           v_existing.backup_sha256<>p_backup_sha256 OR
           v_existing.confirmation_slug<>p_confirmation_slug OR
           v_existing.reason<>p_reason OR
           v_existing.purge_idempotency_key<>p_purge_idempotency_key THEN
            RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='Catalog purge approval replay differs';
        END IF;
        RETURN NEXT v_existing;
        RETURN;
    END IF;
    SELECT * INTO v_installation FROM catalog_installations
    WHERE installation_id=p_installation_id FOR SHARE;
    IF v_installation.installation_id IS NULL OR
       v_installation.package_id<>p_package_id OR v_installation.state<>'RETIRED' OR
       p_requested_by=p_approved_by OR p_step_up_at>p_approved_at OR
       p_step_up_at<p_approved_at-interval '10 minutes' OR
       p_expires_at<=p_approved_at THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Catalog purge approval authority differs';
    END IF;
    INSERT INTO catalog_purge_approval_receipts_v2(
        receipt_id,tenant_id,installation_id,package_id,operation_id,requested_by,
        approved_by,backup_receipt_id,backup_sha256,confirmation_slug,reason,
        purge_idempotency_key,request_sha256,approval_idempotency_key,
        step_up_authenticated_at,approved_at,expires_at,state,approval_sha256
    ) VALUES (
        p_receipt_id,p_tenant_id,p_installation_id,p_package_id,p_operation_id,p_requested_by,
        p_approved_by,p_backup_receipt_id,p_backup_sha256,p_confirmation_slug,p_reason,
        p_purge_idempotency_key,p_request_sha256,p_approval_idempotency_key,
        p_step_up_at,p_approved_at,p_expires_at,'AVAILABLE',p_approval_sha256
    ) RETURNING * INTO v_existing;
    RETURN NEXT v_existing;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_create_purge_approval_v2(p_scope_schema name, p_receipt_id uuid, p_tenant_id uuid, p_installation_id uuid, p_package_id uuid, p_operation_id uuid, p_requested_by uuid, p_approved_by uuid, p_backup_receipt_id uuid, p_backup_sha256 text, p_confirmation_slug text, p_reason text, p_purge_idempotency_key text, p_request_sha256 text, p_approval_idempotency_key text, p_step_up_at timestamp with time zone, p_approved_at timestamp with time zone, p_expires_at timestamp with time zone, p_approval_sha256 text) OWNER TO harpy_owner;

