CREATE FUNCTION __tenant_schema__.catalog_delete_dependency_resolutions_v1(p_installation_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_deleted bigint;
BEGIN
    DELETE FROM catalog_dependency_resolutions
    WHERE installation_id = p_installation_id;
