--
-- Name: catalog_demo_activation_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_activation_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.component_kind = 'DEMO_DATA' AND
       (NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state OR
        NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256) AND
       NEW.lifecycle_state = 'STAGED' AND NOT EXISTS (
        SELECT 1
        FROM catalog_demo_provisions AS provision
        JOIN catalog_demo_handoffs AS handoff
          ON handoff.provision_receipt_id = provision.receipt_id
        WHERE provision.component_id = NEW.component_id
          AND provision.owner_generation = NEW.owner_generation
          AND provision.contract = NEW.contract
          AND provision.content_sha256 = NEW.content_sha256
          AND provision.ready
          AND provision.retry_at IS NULL
          AND handoff.completed_at = provision.completed_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog demo activation lacks Forms handoff readback';
    END IF;
    IF NEW.component_kind = 'DEMO_DATA' AND
       (NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state OR
        NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256) AND
       NEW.lifecycle_state IN ('ACTIVE','DISABLED') AND NOT EXISTS (
        SELECT 1
        FROM catalog_demo_component_heads AS head
        JOIN catalog_demo_provisions AS provision
          ON provision.receipt_id = head.provision_receipt_id
         AND provision.component_id = head.component_id
         AND provision.package_id = head.package_id
         AND provision.package_version = head.package_version
         AND provision.release_id = head.release_id
         AND provision.content_sha256 = head.content_sha256
        JOIN catalog_demo_handoffs AS handoff
          ON handoff.handoff_id = head.handoff_id
         AND handoff.provision_receipt_id = provision.receipt_id
         AND handoff.forms_run_id = head.forms_run_id
        WHERE head.component_id = NEW.component_id
          AND head.content_sha256 = NEW.content_sha256
          AND provision.ready AND provision.retry_at IS NULL
          AND handoff.completed_at = provision.completed_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog demo active head lacks exact ready handoff';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_activation_guard_v1() OWNER TO harpy_owner;

--
-- Name: catalog_demo_assert_current_authority_v1(name, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_assert_current_authority_v1(p_scope_schema name, p_generation bigint) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_schema text;
    v_tenant_id uuid;
BEGIN
    v_schema := pg_catalog.current_schema()::text;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS NULL OR p_scope_schema::text IS DISTINCT FROM v_schema OR
       p_generation < 1 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog demo runtime authority role is invalid';
    END IF;
    BEGIN
        SELECT identity_row.tenant_id INTO STRICT v_tenant_id
        FROM tenancy_schema_identity AS identity_row
        WHERE identity_row.singleton AND identity_row.schema_name = v_schema;
    EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog demo TenantScope identity is invalid';
    END;
    PERFORM platform.catalog_assert_tenant_authority_v1(
        v_tenant_id, p_generation
    );
    RETURN v_tenant_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_assert_current_authority_v1(p_scope_schema name, p_generation bigint) OWNER TO harpy_owner;

--
-- Name: catalog_demo_component_apply_v1(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_component_apply_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component catalog_catalog_components%ROWTYPE;
    v_receipt catalog_catalog_component_receipts%ROWTYPE;
    v_provision catalog_demo_provisions%ROWTYPE;
    v_handoff catalog_demo_handoffs%ROWTYPE;
    v_has_head boolean;
    v_next text;
BEGIN
    SELECT * INTO v_receipt
    FROM catalog_catalog_component_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id
      AND receipt.component_id=p_component_id AND receipt.action=p_action;
    IF FOUND THEN
        IF v_receipt.owner_generation<>p_generation OR v_receipt.contract<>p_contract OR
           v_receipt.content_sha256<>p_content_sha256 OR
           v_receipt.idempotency_key<>p_idempotency_key THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='catalog demo component receipt differs';
        END IF;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.owner_module,
            v_receipt.owner_generation,v_receipt.contract,
            v_receipt.content_sha256,v_receipt.action,
            v_receipt.ready,v_receipt.completed_at;
        RETURN;
    END IF;
    IF p_action NOT IN ('stage','cleanup','activate') THEN
        RETURN QUERY SELECT * FROM catalog_catalog_component_apply_v1(
            p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
            p_contract,p_content_sha256,p_action,p_reference_epoch,
            p_idempotency_key,p_completed_at
        );
        RETURN;
    END IF;
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_owner IS DISTINCT FROM 'catalog' OR p_generation<1 OR
       p_contract IS NULL OR p_content_sha256!~'^[0-9a-f]{64}$' OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='catalog demo component command invalid';
    END IF;
    SELECT * INTO v_component
    FROM catalog_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    IF NOT FOUND OR v_component.component_kind<>'DEMO_DATA' OR
       v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR v_component.contract<>p_contract THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='catalog demo component authority differs';
    END IF;
    SELECT EXISTS(SELECT 1 FROM catalog_demo_component_heads AS head
        WHERE head.component_id=p_component_id) INTO v_has_head;
    IF p_action='cleanup' THEN
        IF NOT EXISTS (
            SELECT 1 FROM catalog_catalog_component_receipts AS stage
            WHERE stage.operation_id=p_operation_id
              AND stage.component_id=p_component_id
              AND stage.action='stage'
              AND stage.content_sha256=p_content_sha256
        ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='catalog demo cleanup lacks staged evidence';
        END IF;
        v_next:=CASE
          WHEN NOT v_has_head AND v_component.lifecycle_state='STAGED'
            AND v_component.content_sha256=p_content_sha256 THEN 'AVAILABLE'
          WHEN v_has_head AND v_component.lifecycle_state IN ('ACTIVE','DISABLED')
            THEN v_component.lifecycle_state
          ELSE NULL END;
    ELSE
        SELECT * INTO v_provision
        FROM catalog_demo_provisions AS provision
        WHERE provision.component_id=p_component_id
          AND provision.owner_generation=p_generation
          AND provision.contract=p_contract
          AND provision.content_sha256=p_content_sha256
          AND provision.ready AND provision.retry_at IS NULL
          AND (
            provision.idempotency_key=p_operation_id::text||':'||
                p_component_id::text||':provision' OR
            NOT v_has_head AND
                v_component.content_sha256=p_content_sha256
          )
        ORDER BY (
            provision.idempotency_key=p_operation_id::text||':'||
                p_component_id::text||':provision'
        ) DESC, provision.created_at DESC
        LIMIT 1 FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='catalog demo exact ready provision is unavailable';
        END IF;
        SELECT * INTO STRICT v_handoff
        FROM catalog_demo_handoffs AS handoff
        WHERE handoff.provision_receipt_id=v_provision.receipt_id
          AND handoff.component_id=v_provision.component_id
          AND handoff.package_id=v_provision.package_id
          AND handoff.package_version=v_provision.package_version
          AND handoff.release_id=v_provision.release_id
          AND handoff.content_sha256=v_provision.content_sha256
          AND handoff.completed_at=v_provision.completed_at
        FOR SHARE;
        IF p_action='stage' THEN
            v_next:=CASE
              WHEN NOT v_has_head AND v_component.lifecycle_state='AVAILABLE'
                AND v_component.content_sha256=p_content_sha256 THEN 'STAGED'
              WHEN v_has_head AND
                v_component.lifecycle_state IN ('ACTIVE','DISABLED')
                THEN v_component.lifecycle_state
              ELSE NULL END;
        ELSIF NOT EXISTS (
            SELECT 1 FROM catalog_catalog_component_receipts AS stage
            WHERE stage.operation_id=p_operation_id
              AND stage.component_id=p_component_id
              AND stage.action='stage'
              AND stage.content_sha256=p_content_sha256
        ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='catalog demo activation lacks staged evidence';
        ELSE
            v_next:=CASE
              WHEN NOT v_has_head AND v_component.lifecycle_state='STAGED'
                THEN 'ACTIVE'
              WHEN v_has_head AND
                v_component.lifecycle_state IN ('ACTIVE','DISABLED')
                THEN v_component.lifecycle_state
              ELSE NULL END;
            INSERT INTO catalog_demo_component_heads(
                component_id,package_id,package_version,release_id,
                provision_receipt_id,handoff_id,forms_run_id,
                content_sha256,activated_at
            ) VALUES (
                p_component_id,v_provision.package_id,
                v_provision.package_version,v_provision.release_id,
                v_provision.receipt_id,v_handoff.handoff_id,
                v_handoff.forms_run_id,p_content_sha256,p_completed_at
            ) ON CONFLICT ON CONSTRAINT catalog_demo_component_heads_pkey DO UPDATE SET
                package_id=EXCLUDED.package_id,
                package_version=EXCLUDED.package_version,
                release_id=EXCLUDED.release_id,
                provision_receipt_id=EXCLUDED.provision_receipt_id,
                handoff_id=EXCLUDED.handoff_id,
                forms_run_id=EXCLUDED.forms_run_id,
                content_sha256=EXCLUDED.content_sha256,
                activated_at=EXCLUDED.activated_at;
        END IF;
    END IF;
    IF v_next IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='catalog demo component transition invalid';
    END IF;
    UPDATE catalog_catalog_components
    SET lifecycle_state=v_next,
        content_sha256=CASE WHEN p_action='activate' THEN p_content_sha256
            ELSE catalog_catalog_components.content_sha256 END,
        updated_at=CASE
          WHEN v_component.lifecycle_state IS DISTINCT FROM v_next
            OR p_action='activate' THEN p_completed_at
          ELSE v_component.updated_at END
    WHERE catalog_catalog_components.component_id=p_component_id;
    INSERT INTO catalog_catalog_component_receipts(
        receipt_id,operation_id,component_id,owner_module,owner_generation,
        contract,content_sha256,action,idempotency_key,ready,completed_at
    ) VALUES (
        p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
        p_contract,p_content_sha256,p_action,p_idempotency_key,true,p_completed_at
    ) RETURNING * INTO v_receipt;
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.owner_module,
        v_receipt.owner_generation,v_receipt.contract,
        v_receipt.content_sha256,v_receipt.action,
        v_receipt.ready,v_receipt.completed_at;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_demo_component_apply_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: catalog_demo_evidence_immutable_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_evidence_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='Catalog demo evidence is immutable';
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_evidence_immutable_v1() OWNER TO harpy_owner;

--
-- Name: catalog_demo_head_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_head_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM catalog_demo_provisions AS provision
        JOIN catalog_demo_handoffs AS handoff
          ON handoff.handoff_id = NEW.handoff_id
         AND handoff.provision_receipt_id = provision.receipt_id
         AND handoff.component_id = provision.component_id
         AND handoff.package_id = provision.package_id
         AND handoff.package_version = provision.package_version
         AND handoff.release_id = provision.release_id
         AND handoff.forms_run_id = NEW.forms_run_id
         AND handoff.content_sha256 = provision.content_sha256
        WHERE provision.receipt_id = NEW.provision_receipt_id
          AND provision.component_id = NEW.component_id
          AND provision.package_id = NEW.package_id
          AND provision.package_version = NEW.package_version
          AND provision.release_id = NEW.release_id
          AND provision.content_sha256 = NEW.content_sha256
          AND provision.ready AND provision.retry_at IS NULL
          AND handoff.completed_at = provision.completed_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog demo head lacks exact ready handoff';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_head_guard_v1() OWNER TO harpy_owner;

--
-- Name: catalog_demo_materialize_v1(uuid, text, text, uuid, uuid, bigint, text, text, text, text, bytea, integer, integer, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_materialize_v1(p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_module_slug text, p_source_contract text, p_semantic_sha256 bytea, p_form_count integer, p_row_count integer, p_document_bytes bytea, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_component catalog_catalog_components%ROWTYPE;
    v_payload catalog_demo_payloads%ROWTYPE;
BEGIN
    SELECT * INTO v_component
    FROM catalog_catalog_components AS component
    WHERE component.component_id = p_component_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO catalog_catalog_components(
            component_id, component_kind, contract, content_sha256,
            owner_generation, writer_state, lifecycle_state, updated_at
        ) VALUES (
            p_component_id, 'DEMO_DATA', p_contract, p_content_sha256,
            p_owner_generation, 'v2', 'AVAILABLE', p_occurred_at
        );
    ELSIF ROW(
              v_component.component_kind, v_component.contract,
              v_component.owner_generation, v_component.writer_state
          ) IS DISTINCT FROM ROW(
              'DEMO_DATA'::text, p_contract,
              p_owner_generation, 'v2'::text
          ) OR v_component.lifecycle_state NOT IN (
              'AVAILABLE','STAGED','ACTIVE','DISABLED'
          ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog demo component authority differs';
    END IF;
    IF EXISTS (
        SELECT 1 FROM catalog_demo_payloads AS prior
        WHERE prior.component_id = p_component_id
          AND prior.package_id <> p_package_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='Catalog demo component package differs';
    END IF;
    SELECT * INTO v_payload
    FROM catalog_demo_payloads AS payload
    WHERE payload.package_id = p_package_id
      AND payload.package_version = p_package_version
      AND payload.component_id = p_component_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO catalog_demo_payloads(
            component_id, package_id, package_slug, package_version,
            release_id, module_slug, source_contract, semantic_sha256,
            form_count, row_count, document_bytes, installed_at
        ) VALUES (
            p_component_id, p_package_id, p_package_slug, p_package_version,
            p_release_id, p_module_slug, p_source_contract, p_semantic_sha256,
            p_form_count, p_row_count, p_document_bytes, p_occurred_at
        );
    ELSIF ROW(
              v_payload.package_id, v_payload.package_slug,
              v_payload.package_version, v_payload.release_id,
              v_payload.module_slug, v_payload.source_contract,
              v_payload.semantic_sha256, v_payload.form_count,
              v_payload.row_count, v_payload.document_bytes
          ) IS DISTINCT FROM ROW(
              p_package_id, p_package_slug, p_package_version, p_release_id,
              p_module_slug, p_source_contract, p_semantic_sha256,
              p_form_count, p_row_count, p_document_bytes
          ) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='Catalog demo semantic projection differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_materialize_v1(p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_module_slug text, p_source_contract text, p_semantic_sha256 bytea, p_form_count integer, p_row_count integer, p_document_bytes bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: catalog_demo_project_document_v1(text, uuid, text, text, text, text, bytea, integer, integer, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_project_document_v1(p_package_slug text, p_component_id uuid, p_contract text, p_content_sha256 text, p_module_slug text, p_source_contract text, p_semantic_sha256 bytea, p_form_count integer, p_row_count integer, p_document_bytes bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_document jsonb;
    v_rows bigint;
    v_forms_valid boolean;
BEGIN
    IF p_package_slug IS NULL OR
       p_package_slug !~ '^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$' OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_contract IS DISTINCT FROM 'catalog.demo-data.v1' OR
       p_content_sha256 !~ '^[0-9a-f]{64}$' OR
       p_module_slug IS DISTINCT FROM p_package_slug OR
       p_source_contract IS DISTINCT FROM
           'harpy-v1.enterprise-seed.' || p_package_slug OR
       octet_length(p_semantic_sha256) IS DISTINCT FROM 32 OR
       p_semantic_sha256 IS DISTINCT FROM pg_catalog.sha256(p_document_bytes) OR
       pg_catalog.encode(pg_catalog.sha256(p_document_bytes), 'hex')
           IS DISTINCT FROM p_content_sha256 OR
       p_form_count < 1 OR p_row_count < 1 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog demo payload identity is invalid';
    END IF;
    BEGIN
        v_document := pg_catalog.convert_from(p_document_bytes, 'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog demo payload JSON is invalid';
    END;
    IF jsonb_typeof(v_document) IS DISTINCT FROM 'object' OR
       v_document->>'contract_version' IS DISTINCT FROM p_contract OR
       v_document->>'component_id' IS DISTINCT FROM p_component_id::text OR
       v_document->>'module_slug' IS DISTINCT FROM p_package_slug OR
       v_document->>'source_contract' IS DISTINCT FROM p_source_contract OR
       jsonb_typeof(v_document->'demo_forms') IS DISTINCT FROM 'array' OR
       jsonb_array_length(v_document->'demo_forms') IS DISTINCT FROM p_form_count THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog demo payload contract is invalid';
    END IF;
    SELECT bool_and(
        jsonb_typeof(form.value) = 'object' AND
        jsonb_typeof(form.value->'rows') = 'array'
    ), sum(CASE WHEN jsonb_typeof(form.value->'rows') = 'array'
        THEN jsonb_array_length(form.value->'rows') ELSE 0 END)
    INTO v_forms_valid, v_rows
    FROM jsonb_array_elements(v_document->'demo_forms') AS form(value);
    IF v_forms_valid IS DISTINCT FROM true OR v_rows IS DISTINCT FROM p_row_count THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog demo payload counts are invalid';
    END IF;
    RETURN v_document;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_demo_project_document_v1(p_package_slug text, p_component_id uuid, p_contract text, p_content_sha256 text, p_module_slug text, p_source_contract text, p_semantic_sha256 bytea, p_form_count integer, p_row_count integer, p_document_bytes bytea) OWNER TO harpy_owner;

--
-- Name: catalog_demo_project_v1(name, uuid, uuid, text, text, uuid, uuid, bigint, text, text, text, text, bytea, integer, integer, bytea, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_project_v1(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_module_slug text, p_source_contract text, p_semantic_sha256 bytea, p_form_count integer, p_row_count integer, p_document_bytes bytea, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, module_slug text, source_contract text, semantic_sha256 bytea, form_count integer, row_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready boolean, retry_at timestamp with time zone, completed_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_document jsonb;
    v_receipt catalog_demo_provisions%ROWTYPE;
    v_payload catalog_demo_payloads%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR
       p_package_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_package_version IS NULL OR
       p_package_version !~
        '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$' OR
       p_owner_generation < 1 OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_idempotency_key !~ '^[A-Za-z0-9_.:-]+$' OR
       octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds', p_occurred_at) <> p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog demo projection request is invalid';
    END IF;
    v_document := catalog_demo_project_document_v1(
        p_package_slug, p_component_id, p_contract, p_content_sha256,
        p_module_slug, p_source_contract, p_semantic_sha256,
        p_form_count, p_row_count, p_document_bytes
    );
    PERFORM catalog_demo_assert_current_authority_v1(
        p_scope_schema, p_owner_generation
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'catalog:demo-project:' || p_component_id::text, 6104
    ));
    SELECT * INTO v_receipt
    FROM catalog_demo_provisions AS provision
    WHERE provision.package_id = p_package_id
      AND provision.package_version = p_package_version
      AND provision.component_id = p_component_id
    FOR UPDATE;
    IF FOUND THEN
        SELECT * INTO STRICT v_payload
        FROM catalog_demo_payloads AS payload
        WHERE payload.package_id = p_package_id
          AND payload.package_version = p_package_version
          AND payload.component_id = p_component_id
        FOR SHARE;
        IF ROW(
              v_receipt.package_id, v_receipt.package_slug,
              v_receipt.package_version, v_receipt.release_id,
              v_receipt.owner_generation, v_receipt.contract,
              v_receipt.content_sha256, v_receipt.idempotency_key,
              v_receipt.request_sha256
           ) IS DISTINCT FROM ROW(
              p_package_id, p_package_slug, p_package_version, p_release_id,
              p_owner_generation, p_contract, p_content_sha256,
              p_idempotency_key, p_request_sha256
           ) OR ROW(
              v_payload.module_slug, v_payload.source_contract,
              v_payload.semantic_sha256, v_payload.form_count,
              v_payload.row_count, v_payload.document_bytes
           ) IS DISTINCT FROM ROW(
              p_module_slug, p_source_contract, p_semantic_sha256,
              p_form_count, p_row_count, p_document_bytes
           ) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='Catalog demo projection replay differs';
        END IF;
        PERFORM catalog_demo_reconcile_v1(
            v_receipt.receipt_id, p_occurred_at
        );
        RETURN QUERY
        SELECT * FROM catalog_demo_readback_v1(v_receipt.receipt_id);
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Catalog demo replay readback differs';
        END IF;
        RETURN;
    END IF;
    PERFORM catalog_demo_materialize_v1(
        p_package_id, p_package_slug, p_package_version,
        p_release_id, p_component_id, p_owner_generation,
        p_contract, p_content_sha256, p_module_slug,
        p_source_contract, p_semantic_sha256,
        p_form_count, p_row_count, p_document_bytes, p_occurred_at
    );
    INSERT INTO catalog_demo_provisions(
        receipt_id, package_id, package_slug, package_version,
        release_id, component_id, owner_generation, contract,
        content_sha256, idempotency_key, request_sha256,
        ready, retry_at, completed_at, created_at, updated_at
    ) VALUES (
        p_receipt_id, p_package_id, p_package_slug, p_package_version,
        p_release_id, p_component_id, p_owner_generation, p_contract,
        p_content_sha256, p_idempotency_key, p_request_sha256,
        false, p_occurred_at + interval '30 seconds',
        p_occurred_at, p_occurred_at, p_occurred_at
    );
    RETURN QUERY SELECT * FROM catalog_demo_readback_v1(p_receipt_id);
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog demo projection readback differs';
    END IF;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_demo_project_v1(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_module_slug text, p_source_contract text, p_semantic_sha256 bytea, p_form_count integer, p_row_count integer, p_document_bytes bytea, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: catalog_demo_readback_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_readback_v1(p_receipt_id uuid) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, module_slug text, source_contract text, semantic_sha256 bytea, form_count integer, row_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready boolean, retry_at timestamp with time zone, completed_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT provision.receipt_id, provision.package_id,
        provision.package_slug, provision.package_version,
        provision.release_id, provision.component_id,
        provision.owner_generation, provision.contract,
        provision.content_sha256, payload.module_slug,
        payload.source_contract, payload.semantic_sha256,
        payload.form_count, payload.row_count, payload.document_bytes,
        provision.idempotency_key, provision.request_sha256,
        CASE
          WHEN component.lifecycle_state = 'AVAILABLE'
           AND head.component_id IS NULL THEN 'AVAILABLE'
          ELSE 'STAGED'
        END,
        provision.ready AND handoff.handoff_id IS NOT NULL,
        provision.retry_at, provision.completed_at,
        provision.created_at, provision.updated_at
    FROM catalog_demo_provisions AS provision
    JOIN catalog_demo_payloads AS payload
      ON payload.package_id = provision.package_id
     AND payload.package_version = provision.package_version
     AND payload.component_id = provision.component_id
     AND payload.release_id = provision.release_id
    JOIN catalog_catalog_components AS component
      ON component.component_id = provision.component_id
    LEFT JOIN catalog_demo_component_heads AS head
      ON head.component_id = provision.component_id
    LEFT JOIN catalog_demo_handoffs AS handoff
      ON handoff.provision_receipt_id = provision.receipt_id
    WHERE provision.receipt_id = p_receipt_id
      AND component.lifecycle_state IN (
          'AVAILABLE','STAGED','ACTIVE','DISABLED'
      );
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_readback_v1(p_receipt_id uuid) OWNER TO harpy_owner;

--
-- Name: catalog_demo_ready_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_ready_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.ready AND NOT OLD.ready AND NOT EXISTS (
        SELECT 1
        FROM catalog_demo_handoffs AS handoff
        WHERE handoff.provision_receipt_id = NEW.receipt_id
          AND handoff.component_id = NEW.component_id
          AND handoff.package_id = NEW.package_id
          AND handoff.package_version = NEW.package_version
          AND handoff.release_id = NEW.release_id
          AND handoff.content_sha256 = NEW.content_sha256
          AND handoff.request_sha256 = NEW.request_sha256
          AND handoff.completed_at = NEW.completed_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog demo ready transition lacks Forms handoff';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_ready_guard_v1() OWNER TO harpy_owner;

--
-- Name: catalog_demo_reconcile_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_reconcile_v1(p_receipt_id uuid, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_provision catalog_demo_provisions%ROWTYPE;
    v_handoff catalog_demo_handoffs%ROWTYPE;
BEGIN
    SELECT * INTO STRICT v_provision
    FROM catalog_demo_provisions AS provision
    WHERE provision.receipt_id = p_receipt_id
    FOR UPDATE;
    SELECT * INTO v_handoff
    FROM catalog_demo_handoffs AS handoff
    WHERE handoff.provision_receipt_id = p_receipt_id
    FOR SHARE;
    IF FOUND THEN
        IF v_handoff.completed_at < v_provision.created_at THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Catalog demo handoff predates provision';
        END IF;
        IF NOT v_provision.ready THEN
            UPDATE catalog_demo_provisions
            SET ready = true,
                retry_at = NULL,
                completed_at = v_handoff.completed_at,
                updated_at = GREATEST(p_occurred_at, v_handoff.completed_at)
            WHERE receipt_id = p_receipt_id;
        END IF;
        RETURN;
    END IF;
    IF v_provision.ready THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog demo ready receipt lacks handoff';
    END IF;
    IF p_occurred_at >= v_provision.retry_at THEN
        UPDATE catalog_demo_provisions
        SET retry_at = p_occurred_at + interval '30 seconds',
            completed_at = p_occurred_at,
            updated_at = p_occurred_at
        WHERE receipt_id = p_receipt_id;
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_reconcile_v1(p_receipt_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: catalog_demo_record_handoff_v1(name, bigint, uuid, uuid, uuid, uuid, uuid, uuid, bytea, integer, integer, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_record_handoff_v1(p_scope_schema name, p_owner_generation bigint, p_handoff_id uuid, p_provision_receipt_id uuid, p_component_id uuid, p_package_id uuid, p_release_id uuid, p_forms_run_id uuid, p_request_sha256 bytea, p_form_count integer, p_row_count integer, p_readback_sha256 bytea, p_completed_at timestamp with time zone) RETURNS TABLE(handoff_id uuid, provision_receipt_id uuid, component_id uuid, package_id uuid, release_id uuid, forms_run_id uuid, request_sha256 bytea, form_count integer, row_count integer, readback_sha256 bytea, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_provision catalog_demo_provisions%ROWTYPE;
    v_payload catalog_demo_payloads%ROWTYPE;
    v_existing catalog_demo_handoffs%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_handoff_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_provision_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR
       p_package_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_forms_run_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_form_count < 1 OR p_row_count < p_form_count OR
       pg_catalog.octet_length(p_readback_sha256) IS DISTINCT FROM 32 OR
       p_readback_sha256 = pg_catalog.decode(pg_catalog.repeat('00',32),'hex') OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       pg_catalog.date_trunc('microseconds',p_completed_at) <> p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog demo handoff input is invalid';
    END IF;
    PERFORM catalog_demo_assert_current_authority_v1(
        p_scope_schema,p_owner_generation
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'catalog:demo-handoff:' || p_provision_receipt_id::text,6001
    ));
    SELECT * INTO v_existing
    FROM catalog_demo_handoffs AS handoff
    WHERE handoff.provision_receipt_id=p_provision_receipt_id;
    IF FOUND THEN
        IF ROW(v_existing.component_id,v_existing.package_id,
               v_existing.release_id,v_existing.forms_run_id,
               v_existing.request_sha256,
               v_existing.form_count,v_existing.row_count,
               v_existing.readback_sha256,v_existing.completed_at)
           IS DISTINCT FROM
           ROW(p_component_id,p_package_id,p_release_id,p_forms_run_id,
               p_request_sha256,
               p_form_count,p_row_count,p_readback_sha256,p_completed_at) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='Catalog demo handoff replay differs';
        END IF;
        RETURN QUERY SELECT v_existing.handoff_id,
            v_existing.provision_receipt_id,v_existing.component_id,
            v_existing.package_id,v_existing.release_id,
            v_existing.forms_run_id,
            v_existing.request_sha256,v_existing.form_count,
            v_existing.row_count,v_existing.readback_sha256,
            v_existing.completed_at;
        RETURN;
    END IF;
    SELECT * INTO STRICT v_provision
    FROM catalog_demo_provisions AS provision
    WHERE provision.receipt_id=p_provision_receipt_id
      AND provision.component_id=p_component_id
      AND provision.package_id=p_package_id
      AND provision.release_id=p_release_id
      AND provision.owner_generation=p_owner_generation
      AND provision.request_sha256=p_request_sha256
    FOR UPDATE;
    SELECT * INTO STRICT v_payload
    FROM catalog_demo_payloads AS payload
    WHERE payload.package_id=v_provision.package_id
      AND payload.package_version=v_provision.package_version
      AND payload.component_id=p_component_id
      AND payload.package_id=p_package_id
      AND payload.release_id=p_release_id
      AND payload.form_count=p_form_count
      AND payload.row_count=p_row_count
    FOR SHARE;
    IF v_provision.ready OR p_completed_at < v_provision.created_at THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='Catalog demo handoff provision state differs';
    END IF;
    INSERT INTO catalog_demo_handoffs(
        handoff_id,provision_receipt_id,component_id,package_id,
        package_version,release_id,forms_run_id,content_sha256,
        request_sha256,form_count,row_count,readback_sha256,completed_at
    ) VALUES (
        p_handoff_id,p_provision_receipt_id,p_component_id,p_package_id,
        v_provision.package_version,p_release_id,p_forms_run_id,
        v_provision.content_sha256,p_request_sha256,p_form_count,p_row_count,
        p_readback_sha256,p_completed_at
    ) RETURNING * INTO v_existing;
    RETURN QUERY SELECT v_existing.handoff_id,
        v_existing.provision_receipt_id,v_existing.component_id,
        v_existing.package_id,v_existing.release_id,
        v_existing.forms_run_id,
        v_existing.request_sha256,v_existing.form_count,
        v_existing.row_count,v_existing.readback_sha256,
        v_existing.completed_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_record_handoff_v1(p_scope_schema name, p_owner_generation bigint, p_handoff_id uuid, p_provision_receipt_id uuid, p_component_id uuid, p_package_id uuid, p_release_id uuid, p_forms_run_id uuid, p_request_sha256 bytea, p_form_count integer, p_row_count integer, p_readback_sha256 bytea, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: catalog_demo_sync_head_state_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_demo_sync_head_state_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_installation_id uuid;
BEGIN
    SELECT binding.installation_id INTO STRICT v_installation_id
    FROM catalog_component_bindings AS binding
    WHERE binding.component_id = NEW.component_id
      AND binding.owner_module = 'catalog'
      AND binding.owner_contract = 'catalog.demo-data.v1'
    FOR SHARE;

    INSERT INTO catalog_demo_states (
        installation_id, component_id, package_id, release_id, source_run_id,
        content_sha256, state, record_ids, last_receipt_id, revision, updated_at
    ) VALUES (
        v_installation_id, NEW.component_id, NEW.package_id, NEW.release_id,
        NEW.forms_run_id, NEW.content_sha256, 'INSTALLED', '[]'::jsonb,
        NULL, 1, NEW.activated_at
    )
    ON CONFLICT (installation_id, component_id) DO UPDATE
    SET package_id = EXCLUDED.package_id,
        release_id = EXCLUDED.release_id,
        source_run_id = EXCLUDED.source_run_id,
        content_sha256 = EXCLUDED.content_sha256,
        state = 'INSTALLED',
        record_ids = '[]'::jsonb,
        last_receipt_id = NULL,
        revision = catalog_demo_states.revision + 1,
        updated_at = EXCLUDED.updated_at
    WHERE catalog_demo_states.release_id IS DISTINCT FROM EXCLUDED.release_id
       OR catalog_demo_states.source_run_id IS DISTINCT FROM EXCLUDED.source_run_id
       OR catalog_demo_states.content_sha256 IS DISTINCT FROM EXCLUDED.content_sha256;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_demo_sync_head_state_v1() OWNER TO harpy_owner;

--
-- Name: catalog_guard_purge_approval_v2(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_guard_purge_approval_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Catalog purge approval is immutable';
    END IF;
    IF (OLD.receipt_id,OLD.tenant_id,OLD.installation_id,OLD.package_id,OLD.operation_id,
        OLD.requested_by,OLD.approved_by,OLD.backup_receipt_id,OLD.backup_sha256,
        OLD.confirmation_slug,OLD.reason,OLD.purge_idempotency_key,OLD.request_sha256,
        OLD.approval_idempotency_key,OLD.step_up_authenticated_at,OLD.approved_at,
        OLD.expires_at,OLD.approval_sha256) IS DISTINCT FROM
       (NEW.receipt_id,NEW.tenant_id,NEW.installation_id,NEW.package_id,NEW.operation_id,
        NEW.requested_by,NEW.approved_by,NEW.backup_receipt_id,NEW.backup_sha256,
        NEW.confirmation_slug,NEW.reason,NEW.purge_idempotency_key,NEW.request_sha256,
        NEW.approval_idempotency_key,NEW.step_up_authenticated_at,NEW.approved_at,
        NEW.expires_at,NEW.approval_sha256) OR OLD.state<>'AVAILABLE' OR
       NEW.state<>'CONSUMED' OR NEW.consumed_operation_id<>OLD.operation_id OR
       NEW.consumed_authority_sha256 IS NULL OR NEW.consumed_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='Catalog purge approval is immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_guard_purge_approval_v2() OWNER TO harpy_owner;

