ALTER FUNCTION __tenant_schema__.catalog_purge_authority_immutable_v2() OWNER TO harpy_owner;

--
-- Name: catalog_record_purge_authority_v2(uuid, uuid, uuid, text, uuid, uuid, uuid, uuid, text, uuid, text, text, text, text, text, bigint, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_record_purge_authority_v2(p_operation_id uuid, p_tenant_id uuid, p_package_id uuid, p_package_slug text, p_actor_id uuid, p_requested_by uuid, p_approved_by uuid, p_approval_receipt_id uuid, p_approval_sha256 text, p_backup_receipt_id uuid, p_backup_state text, p_backup_sha256 text, p_confirmation_slug text, p_reason text, p_idempotency_key text, p_reference_epoch bigint, p_step_up_at timestamp with time zone, p_approval_step_up_at timestamp with time zone, p_approved_at timestamp with time zone, p_approval_expires_at timestamp with time zone, p_requested_at timestamp with time zone, p_cooling_until timestamp with time zone, p_authority_sha256 text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_operation catalog_operation_runs%ROWTYPE;
    v_installation catalog_installations%ROWTYPE;
    v_existing catalog_purge_authorities_v2%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       p_tenant_id IS NULL OR
       p_tenant_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       p_package_id IS NULL OR
       p_package_id = '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_actor_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_requested_by) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_approved_by) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_approval_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_backup_receipt_id) IS DISTINCT FROM 7 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog purge authority identifiers are invalid';
    END IF;
    SELECT * INTO v_operation FROM catalog_operation_runs
    WHERE operation_id=p_operation_id FOR UPDATE;
    SELECT * INTO v_installation FROM catalog_installations
    WHERE installation_id=v_operation.installation_id FOR SHARE;
    IF v_operation.operation_id IS NULL OR v_operation.kind<>'PURGE' OR
       v_operation.package_id<>p_package_id OR v_operation.actor_id<>p_actor_id OR
       v_operation.idempotency_key<>p_idempotency_key OR
       v_operation.plan->>'slug'<>p_package_slug OR
       v_installation.reference_epoch<>p_reference_epoch OR
       v_operation.started_at<p_requested_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog purge operation authority differs';
    END IF;
    SELECT * INTO v_existing FROM catalog_purge_authorities_v2
    WHERE operation_id=p_operation_id;
    IF FOUND THEN
        IF v_existing.tenant_id<>p_tenant_id OR v_existing.package_id<>p_package_id OR
           v_existing.actor_id<>p_actor_id OR v_existing.requested_by<>p_requested_by OR
           v_existing.approved_by<>p_approved_by OR
           v_existing.approval_receipt_id<>p_approval_receipt_id OR
           v_existing.approval_sha256<>p_approval_sha256 OR
           v_existing.backup_receipt_id<>p_backup_receipt_id OR
           v_existing.backup_sha256<>p_backup_sha256 OR
           v_existing.confirmation_slug<>p_confirmation_slug OR
           v_existing.reason<>p_reason OR v_existing.idempotency_key<>p_idempotency_key OR
           v_existing.reference_epoch<>p_reference_epoch OR
           v_existing.step_up_authenticated_at<>p_step_up_at OR
           v_existing.approval_step_up_at<>p_approval_step_up_at OR
           v_existing.approved_at<>p_approved_at OR
           v_existing.approval_expires_at<>p_approval_expires_at OR
           v_existing.requested_at<>p_requested_at OR
           v_existing.cooling_until<>p_cooling_until OR
           v_existing.authority_sha256<>p_authority_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='Catalog purge authority differs';
        END IF;
        RETURN v_existing.authority_sha256;
    END IF;
    INSERT INTO catalog_purge_authorities_v2(
        operation_id,tenant_id,package_id,package_slug,actor_id,requested_by,
        approved_by,approval_receipt_id,approval_sha256,backup_receipt_id,
        backup_state,backup_sha256,confirmation_slug,reason,idempotency_key,
        reference_epoch,step_up_authenticated_at,approval_step_up_at,approved_at,
        approval_expires_at,requested_at,
        cooling_until,authority_sha256
    ) VALUES (
        p_operation_id,p_tenant_id,p_package_id,p_package_slug,p_actor_id,p_requested_by,
        p_approved_by,p_approval_receipt_id,p_approval_sha256,p_backup_receipt_id,
        p_backup_state,p_backup_sha256,p_confirmation_slug,p_reason,p_idempotency_key,
        p_reference_epoch,p_step_up_at,p_approval_step_up_at,p_approved_at,
        p_approval_expires_at,p_requested_at,
        p_cooling_until,p_authority_sha256
    );
    RETURN p_authority_sha256;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_record_purge_authority_v2(p_operation_id uuid, p_tenant_id uuid, p_package_id uuid, p_package_slug text, p_actor_id uuid, p_requested_by uuid, p_approved_by uuid, p_approval_receipt_id uuid, p_approval_sha256 text, p_backup_receipt_id uuid, p_backup_state text, p_backup_sha256 text, p_confirmation_slug text, p_reason text, p_idempotency_key text, p_reference_epoch bigint, p_step_up_at timestamp with time zone, p_approval_step_up_at timestamp with time zone, p_approved_at timestamp with time zone, p_approval_expires_at timestamp with time zone, p_requested_at timestamp with time zone, p_cooling_until timestamp with time zone, p_authority_sha256 text) OWNER TO harpy_owner;

--
-- Name: catalog_record_purge_authority_v3(uuid, uuid, uuid, text, uuid, uuid, uuid, uuid, text, uuid, text, text, text, text, text, bigint, bigint, bigint, bigint, uuid, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_record_purge_authority_v3(p_operation_id uuid, p_tenant_id uuid, p_package_id uuid, p_package_slug text, p_actor_id uuid, p_requested_by uuid, p_approved_by uuid, p_approval_receipt_id uuid, p_approval_sha256 text, p_backup_receipt_id uuid, p_backup_state text, p_backup_sha256 text, p_confirmation_slug text, p_reason text, p_idempotency_key text, p_reference_epoch bigint, p_authorization_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_authorization_permission_id uuid, p_authorization_evidence_sha256 text, p_step_up_purpose_sha256 text, p_step_up_at timestamp with time zone, p_approval_step_up_at timestamp with time zone, p_approved_at timestamp with time zone, p_approval_expires_at timestamp with time zone, p_requested_at timestamp with time zone, p_cooling_until timestamp with time zone, p_authority_sha256 text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
 v_operation catalog_operation_runs%ROWTYPE;
 v_installation catalog_installations%ROWTYPE;
 v_existing catalog_purge_authorities_v2%ROWTYPE;
BEGIN
 IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
 p_tenant_id IS NULL OR p_tenant_id='00000000-0000-0000-0000-000000000000'::uuid OR
 p_package_id IS NULL OR p_package_id='00000000-0000-0000-0000-000000000000'::uuid OR
 pg_catalog.uuid_extract_version(p_actor_id) IS DISTINCT FROM 7 OR
 pg_catalog.uuid_extract_version(p_requested_by) IS DISTINCT FROM 7 OR
 pg_catalog.uuid_extract_version(p_approved_by) IS DISTINCT FROM 7 OR
 pg_catalog.uuid_extract_version(p_approval_receipt_id) IS DISTINCT FROM 7 OR
 pg_catalog.uuid_extract_version(p_backup_receipt_id) IS DISTINCT FROM 7 OR
 p_authorization_token_version<1 OR p_authorization_version<1 OR
 p_authorization_clock<1 OR p_authorization_permission_id IS NULL OR
 p_authorization_permission_id='00000000-0000-0000-0000-000000000000'::uuid OR
 p_authorization_evidence_sha256!~'^[0-9a-f]{64}$' OR
 p_step_up_purpose_sha256!~'^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION USING ERRCODE='22023',
  MESSAGE='Catalog purge authority identifiers are invalid';
 END IF;
 SELECT * INTO v_operation FROM catalog_operation_runs
 WHERE operation_id=p_operation_id FOR UPDATE;
 SELECT * INTO v_installation FROM catalog_installations
 WHERE installation_id=v_operation.installation_id FOR SHARE;
 IF v_operation.operation_id IS NULL OR v_operation.kind<>'PURGE' OR
 v_operation.package_id<>p_package_id OR v_operation.actor_id<>p_actor_id OR
 v_operation.idempotency_key<>p_idempotency_key OR
 v_operation.plan->>'slug'<>p_package_slug OR
 v_installation.reference_epoch<>p_reference_epoch OR
 v_operation.started_at<p_requested_at THEN
  RAISE EXCEPTION USING ERRCODE='55000',
  MESSAGE='Catalog purge operation authority differs';
 END IF;
 SELECT * INTO v_existing FROM catalog_purge_authorities_v2
 WHERE operation_id=p_operation_id;
 IF FOUND THEN
  IF v_existing.tenant_id<>p_tenant_id OR v_existing.package_id<>p_package_id OR
  v_existing.actor_id<>p_actor_id OR v_existing.requested_by<>p_requested_by OR
  v_existing.approved_by<>p_approved_by OR
  v_existing.approval_receipt_id<>p_approval_receipt_id OR
  v_existing.approval_sha256<>p_approval_sha256 OR
  v_existing.backup_receipt_id<>p_backup_receipt_id OR
  v_existing.backup_sha256<>p_backup_sha256 OR
  v_existing.confirmation_slug<>p_confirmation_slug OR
  v_existing.reason<>p_reason OR v_existing.idempotency_key<>p_idempotency_key OR
  v_existing.reference_epoch<>p_reference_epoch OR
  v_existing.authorization_token_version<>p_authorization_token_version OR
  v_existing.authorization_version<>p_authorization_version OR
  v_existing.authorization_clock<>p_authorization_clock OR
  v_existing.authorization_permission_id<>p_authorization_permission_id OR
  v_existing.authorization_evidence_sha256<>p_authorization_evidence_sha256 OR
  v_existing.step_up_purpose_sha256<>p_step_up_purpose_sha256 OR
  v_existing.step_up_authenticated_at<>p_step_up_at OR
  v_existing.approval_step_up_at<>p_approval_step_up_at OR
  v_existing.approved_at<>p_approved_at OR
  v_existing.approval_expires_at<>p_approval_expires_at OR
  v_existing.requested_at<>p_requested_at OR
  v_existing.cooling_until<>p_cooling_until OR
  v_existing.authority_sha256<>p_authority_sha256 THEN
   RAISE EXCEPTION USING ERRCODE='23505',
   MESSAGE='Catalog purge authority differs';
  END IF;
  RETURN v_existing.authority_sha256;
 END IF;
 INSERT INTO catalog_purge_authorities_v2(
  operation_id,tenant_id,package_id,package_slug,actor_id,requested_by,
  approved_by,approval_receipt_id,approval_sha256,backup_receipt_id,
  backup_state,backup_sha256,confirmation_slug,reason,idempotency_key,
  reference_epoch,authorization_token_version,authorization_version,
  authorization_clock,authorization_permission_id,
  authorization_evidence_sha256,step_up_purpose_sha256,
  step_up_authenticated_at,approval_step_up_at,approved_at,approval_expires_at,
  requested_at,cooling_until,authority_sha256
 ) VALUES(
  p_operation_id,p_tenant_id,p_package_id,p_package_slug,p_actor_id,p_requested_by,
  p_approved_by,p_approval_receipt_id,p_approval_sha256,p_backup_receipt_id,
  p_backup_state,p_backup_sha256,p_confirmation_slug,p_reason,p_idempotency_key,
  p_reference_epoch,p_authorization_token_version,p_authorization_version,
  p_authorization_clock,p_authorization_permission_id,
  p_authorization_evidence_sha256,p_step_up_purpose_sha256,
  p_step_up_at,p_approval_step_up_at,p_approved_at,p_approval_expires_at,
  p_requested_at,p_cooling_until,p_authority_sha256
 );
 RETURN p_authority_sha256;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_record_purge_authority_v3(p_operation_id uuid, p_tenant_id uuid, p_package_id uuid, p_package_slug text, p_actor_id uuid, p_requested_by uuid, p_approved_by uuid, p_approval_receipt_id uuid, p_approval_sha256 text, p_backup_receipt_id uuid, p_backup_state text, p_backup_sha256 text, p_confirmation_slug text, p_reason text, p_idempotency_key text, p_reference_epoch bigint, p_authorization_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_authorization_permission_id uuid, p_authorization_evidence_sha256 text, p_step_up_purpose_sha256 text, p_step_up_at timestamp with time zone, p_approval_step_up_at timestamp with time zone, p_approved_at timestamp with time zone, p_approval_expires_at timestamp with time zone, p_requested_at timestamp with time zone, p_cooling_until timestamp with time zone, p_authority_sha256 text) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_activate_menu_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_activate_menu_v1(p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption menu activation denied';
    END IF;
    UPDATE catalog_menu_definitions
    SET active_version_id=(p_record->>'active_version_id')::uuid
    WHERE definition_id=(p_record->>'definition_id')::uuid
      AND active_version_id IS NULL
      AND p_record->>'active_version_id' IS NOT NULL;
    PERFORM 1 FROM catalog_menu_definitions AS row
    WHERE row.definition_id=(p_record->>'definition_id')::uuid
      AND to_jsonb(row)=p_record;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption menu activation differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_activate_menu_v1(p_record jsonb) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract_id text;
    v_procedure_oid bigint;
    v_procedure_signature text;
    v_expected_signature text;
    v_already_applied boolean;
    v_applied_count bigint;
    v_key_sha text;
    v_state_sha text;
    v_projected_sha text;
    v_asserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption composite principal denied';
    END IF;
    v_batch:=catalog_v1_adoption_batch_decode_v1(
      p_change_batch_bytes,p_batch_sha256,p_batch_bytes
    );
    v_asserted:=catalog_v1_adoption_batch_assert_v1(
      v_batch,p_operation_id,p_run_id,p_scope_kind,p_scope_id,
      p_relation_ordinal,p_checkpoint_key,p_snapshot_name,
      p_snapshot_lsn,p_received_lsn,p_commit_lsn,p_final_lsn,
      p_source_xid,p_batch_ordinal,p_checkpoint_state,p_last_key
    );
    IF NOT v_asserted THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='Catalog V1 adoption batch assertion failed';
    END IF;
    SELECT prepared.procedure_contract_id,prepared.procedure_oid,
      prepared.procedure_signature,prepared.already_applied,
      prepared.applied_count,prepared.key_state_sha256,prepared.state_sha256
    INTO STRICT v_contract_id,v_procedure_oid,v_procedure_signature,
      v_already_applied,v_applied_count,v_key_sha,v_state_sha
    FROM platform.cutover_prepare_batch_v1(
      p_operation_id,p_run_id,p_scope_kind,p_scope_id,
      p_relation_ordinal,p_checkpoint_key,p_batch_ordinal,
      p_commit_lsn,p_source_xid,p_batch_sha256,p_lease_manifest_sha256
    ) AS prepared;
    v_expected_signature:=pg_catalog.format(
      '%I.catalog_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)',
      pg_catalog.current_schema()
    );
    IF v_contract_id IS DISTINCT FROM 'catalog.v1_adoption.v1' OR
       v_procedure_oid IS DISTINCT FROM
        'catalog_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure_signature IS DISTINCT FROM v_expected_signature THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption procedure binding differs';
    END IF;
    IF v_already_applied THEN
        IF v_applied_count IS DISTINCT FROM
             pg_catalog.jsonb_array_length(v_batch->'changes') OR
           v_key_sha !~ '^[0-9a-f]{64}$' OR v_state_sha !~ '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION USING ERRCODE='22000',
                MESSAGE='Catalog V1 adoption replay result differs';
        END IF;
        RETURN QUERY SELECT v_applied_count,v_key_sha,v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count,result.key_state_sha256,result.state_sha256
    INTO STRICT v_applied_count,v_key_sha,v_state_sha
    FROM catalog_v1_adoption_apply_v1(
      p_operation_id,p_run_id,p_scope_kind,p_scope_id,p_relation_ordinal,
      p_checkpoint_key,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
      p_source_xid,p_batch_ordinal,v_batch,p_batch_sha256
    ) AS result;
    IF v_applied_count IS DISTINCT FROM
         pg_catalog.jsonb_array_length(v_batch->'changes') OR
       v_key_sha !~ '^[0-9a-f]{64}$' OR v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='Catalog V1 adoption owner result invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
      p_operation_id,p_run_id,p_relation_ordinal,p_checkpoint_key,
      p_snapshot_name,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
      p_final_lsn,p_source_xid,p_batch_ordinal,p_checkpoint_state,
      p_last_key,p_batch_sha256,p_batch_bytes,v_applied_count,
      v_key_sha,v_state_sha
    );
    IF p_checkpoint_state='complete' AND NOT EXISTS (
      SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS expected
      LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint
        ON checkpoint.operation_id=expected.operation_id
       AND checkpoint.run_id=expected.run_id
       AND checkpoint.relation_ordinal=expected.relation_ordinal
       AND checkpoint.checkpoint_key=expected.checkpoint_key
       AND checkpoint.state='complete'
      WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
        AND checkpoint.operation_id IS NULL
    ) THEN
        v_projected_sha:=catalog_v1_adoption_finalize_v1(
          p_operation_id,p_run_id,p_scope_id
        );
        IF v_projected_sha IS DISTINCT FROM v_state_sha THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Catalog V1 adoption projected digest differs';
        END IF;
    END IF;
    RETURN QUERY SELECT v_applied_count,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_change jsonb;
    v_payload jsonb;
    v_lease_manifest text;
    v_rows bigint;
    v_applied bigint;
    v_key_sha text;
    v_state_sha text;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind IS DISTINCT FROM 'tenant' OR p_relation_ordinal<>1 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption apply principal denied';
    END IF;
    v_now:=pg_catalog.date_trunc(
      'microseconds',pg_catalog.transaction_timestamp()
    );
    v_applied:=0;
    SELECT operation.lease_manifest_sha256 INTO STRICT v_lease_manifest
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind=p_scope_kind AND operation.scope_id=p_scope_id
      AND operation.group_id='catalog' AND operation.domain='catalog'
      AND operation.state IN ('copying','shadow','quiescing')
    FOR SHARE;
    FOR v_change IN
        SELECT value FROM pg_catalog.jsonb_array_elements(p_change_batch->'changes')
          WITH ORDINALITY AS item(value,position) ORDER BY position
    LOOP
        v_payload:=CASE v_change->>'kind'
          WHEN 'delete' THEN v_change->'before' ELSE v_change->'after' END;
        INSERT INTO catalog_v1_adoption_stage(
          operation_id,run_id,source_kind,source_identity,source_sha256,
          source_document,target_kind,target_identity,target_sha256,target_record,
          removed,source_xid,commit_lsn,batch_ordinal,change_ordinal,recorded_at
        ) VALUES (
          p_operation_id,p_run_id,v_payload->>'source_kind',
          v_payload->>'source_identity',
          pg_catalog.decode(v_payload->>'source_sha256','hex'),
          v_payload->'source_document',v_payload->>'target_kind',
          v_payload->>'target_identity',
          pg_catalog.sha256(pg_catalog.convert_to(
            (v_payload->'target_record')::text,'UTF8'
          )),v_payload->'target_record',v_change->>'kind'='delete',
          p_source_xid,p_commit_lsn,p_batch_ordinal,
          (v_change->>'ordinal')::smallint,v_now
        ) ON CONFLICT(operation_id,run_id,target_kind,target_identity) DO UPDATE
        SET source_kind=EXCLUDED.source_kind,
          source_identity=EXCLUDED.source_identity,
          source_sha256=EXCLUDED.source_sha256,
          source_document=EXCLUDED.source_document,
          target_sha256=EXCLUDED.target_sha256,
          target_record=EXCLUDED.target_record,removed=EXCLUDED.removed,
          source_xid=EXCLUDED.source_xid,commit_lsn=EXCLUDED.commit_lsn,
          batch_ordinal=EXCLUDED.batch_ordinal,
          change_ordinal=EXCLUDED.change_ordinal,recorded_at=EXCLUDED.recorded_at
        WHERE (catalog_v1_adoption_stage.batch_ordinal,
               catalog_v1_adoption_stage.change_ordinal)
             <(EXCLUDED.batch_ordinal,EXCLUDED.change_ordinal);
        GET DIAGNOSTICS v_rows=ROW_COUNT;
        IF v_rows IS DISTINCT FROM 1::bigint THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Catalog V1 adoption target checkpoint regressed';
        END IF;
        v_applied:=v_applied+1;
        INSERT INTO platform.applied_change_receipts(
          receipt_id,operation_id,run_id,manifest_sha256,source_xid,
          source_commit_lsn,relation_ordinal,change_ordinal,checkpoint_key,
          mutation_kind,mutation_sha256,applied_at
        ) VALUES (
          pg_catalog.gen_random_uuid(),p_operation_id,p_run_id,v_lease_manifest,
          p_source_xid,p_commit_lsn,p_relation_ordinal,
          (((p_batch_ordinal-1)::bigint*1000)+v_applied)::integer,
          p_checkpoint_key,v_change->>'kind',
          pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            p_batch_sha256||':'||v_change::text,'UTF8'
          )),'hex'),v_now
        );
    END LOOP;
    IF EXISTS (
      SELECT 1 FROM catalog_v1_adoption_stage AS stage
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed
      GROUP BY stage.source_kind,stage.source_identity
      HAVING pg_catalog.count(DISTINCT stage.source_sha256)<>1 OR
             pg_catalog.count(DISTINCT stage.source_document)<>1
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption source digest differs';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
      pg_catalog.int4send(pg_catalog.octet_length(stage.target_kind))||
      pg_catalog.convert_to(stage.target_kind,'UTF8')||
      pg_catalog.int4send(pg_catalog.octet_length(stage.target_identity))||
      pg_catalog.convert_to(stage.target_identity,'UTF8')||
      pg_catalog.int4send(pg_catalog.octet_length(stage.target_record::text))||
      pg_catalog.convert_to(stage.target_record::text,'UTF8'),
      ''::bytea ORDER BY stage.target_kind,stage.target_identity),''::bytea)),'hex')
    INTO v_key_sha FROM catalog_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND stage.source_kind=p_checkpoint_key AND NOT stage.removed
      AND stage.target_kind<>'discard';
    SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
      pg_catalog.int4send(pg_catalog.octet_length(stage.target_kind))||
      pg_catalog.convert_to(stage.target_kind,'UTF8')||
      pg_catalog.int4send(pg_catalog.octet_length(stage.target_identity))||
      pg_catalog.convert_to(stage.target_identity,'UTF8')||
      pg_catalog.int4send(pg_catalog.octet_length(stage.target_record::text))||
      pg_catalog.convert_to(stage.target_record::text,'UTF8'),
      ''::bytea ORDER BY stage.target_kind,stage.target_identity),''::bytea)),'hex')
    INTO v_state_sha FROM catalog_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed AND stage.target_kind<>'discard';
    RETURN QUERY SELECT v_applied,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_batch_assert_v1(jsonb, uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_count integer;
    v_generation bigint;
    v_evidence text;
BEGIN
    v_count:=pg_catalog.jsonb_array_length(p_batch->'changes');
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption evidence principal denied';
    END IF;
    SELECT operation.cutover_generation INTO v_generation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind=p_scope_kind AND operation.scope_id=p_scope_id
      AND operation.group_id='catalog' AND operation.domain='catalog'
      AND operation.state IN ('copying','shadow','quiescing');
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption operation binding differs';
    END IF;
    IF p_scope_kind IS DISTINCT FROM 'tenant' OR p_relation_ordinal<>1 OR
       p_checkpoint_key NOT IN (
         'modules','module_dependencies','module_forms',
         'module_schema_versions','module_migration_runs','menu_configs'
       ) OR p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_checkpoint_state NOT IN ('initial_copy','delta','complete') OR
       (p_checkpoint_state='complete') IS DISTINCT FROM (p_final_lsn IS NOT NULL) OR
       (v_count=0 AND (
         p_checkpoint_state<>'complete' OR p_commit_lsn IS DISTINCT FROM p_final_lsn
       )) OR NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS tenant
        WHERE tenant.singleton AND tenant.tenant_id=p_scope_id
          AND tenant.schema_name=pg_catalog.current_schema()
          AND tenant.origin='v1_adopted'
       ) OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS expected
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
          AND expected.relation_ordinal=p_relation_ordinal
          AND expected.checkpoint_key=p_checkpoint_key
       ) OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_groups AS fence
        WHERE fence.scope_kind='tenant' AND fence.scope_id=p_scope_id
          AND fence.group_id='catalog' AND fence.generation=v_generation
          AND fence.state IN ('shadow','quiescing')
          AND fence.writer=CASE fence.state WHEN 'shadow' THEN 'v1' ELSE 'none' END
       ) OR NOT EXISTS (
        SELECT 1 FROM platform.domain_cutovers AS fence
        WHERE fence.scope_kind='tenant' AND fence.scope_id=p_scope_id
          AND fence.domain='catalog' AND fence.generation=v_generation
          AND fence.state IN ('shadow','quiescing')
          AND fence.writer=CASE fence.state WHEN 'shadow' THEN 'v1' ELSE 'none' END
       ) OR (SELECT pg_catalog.array_agg(member.domain ORDER BY member.ordinal)
             FROM platform.cutover_group_members AS member
             WHERE member.scope_kind='tenant' AND member.scope_id=p_scope_id
               AND member.group_id='catalog')
          IS DISTINCT FROM ARRAY['catalog']::text[] OR
       (p_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (p_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       p_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (p_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       (p_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal OR
       p_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key OR
       p_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state OR
       p_batch->'last_key' IS DISTINCT FROM p_last_key OR
       p_batch->'source_position'->>'snapshot_name' IS DISTINCT FROM p_snapshot_name OR
       (p_batch->'source_position'->>'snapshot_lsn')::pg_lsn
         IS DISTINCT FROM p_snapshot_lsn OR
       (p_batch->'source_position'->>'received_lsn')::pg_lsn
         IS DISTINCT FROM p_received_lsn OR
       (p_batch->'source_position'->>'commit_lsn')::pg_lsn
         IS DISTINCT FROM p_commit_lsn OR
       (p_batch->'source_position'->>'final_lsn')::pg_lsn
         IS DISTINCT FROM p_final_lsn OR
       (p_batch->'source_position'->>'source_xid')::xid8
         IS DISTINCT FROM p_source_xid OR
       (p_batch->'source_position'->>'batch_ordinal')::integer
         IS DISTINCT FROM p_batch_ordinal OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change
        WHERE COALESCE(change->'after'->>'source_kind',
                       change->'before'->>'source_kind')<>p_checkpoint_key
       ) OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change
        GROUP BY COALESCE(change->'after'->>'source_identity',
                          change->'before'->>'source_identity')
        HAVING pg_catalog.count(DISTINCT COALESCE(
          change->'after'->>'source_sha256',change->'before'->>'source_sha256'
        ))<>1
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog V1 adoption batch evidence differs';
    END IF;
    IF p_checkpoint_state='complete' THEN
        IF pg_catalog.jsonb_typeof(p_last_key) IS DISTINCT FROM 'object' OR
           (SELECT pg_catalog.array_agg(key ORDER BY key)
            FROM pg_catalog.jsonb_object_keys(p_last_key) AS key)
           IS DISTINCT FROM ARRAY[
             'blocker_sha256','consumer_sha256','evidence_sha256',
             'source_count','source_root_sha256','target_count','target_root_sha256'
           ]::text[] OR
           (p_last_key->>'source_count')::bigint<0 OR
           (p_last_key->>'target_count')::bigint<0 OR
           p_last_key->>'source_root_sha256' !~ '^[0-9a-f]{64}$' OR
           p_last_key->>'target_root_sha256' !~ '^[0-9a-f]{64}$' OR
           p_last_key->>'blocker_sha256' !~ '^[0-9a-f]{64}$' OR
           p_last_key->>'consumer_sha256' !~ '^[0-9a-f]{64}$' OR
           p_last_key->>'evidence_sha256' !~ '^[0-9a-f]{64}$' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Catalog V1 adoption terminal evidence invalid';
        END IF;
        v_evidence:=pg_catalog.encode(pg_catalog.sha256(
          pg_catalog.convert_to('catalog-v1-adoption-evidence.v1','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'source_count','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'source_root_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'target_count','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'target_root_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'blocker_sha256','UTF8')||
          pg_catalog.decode('00','hex')||
          pg_catalog.convert_to(p_last_key->>'consumer_sha256','UTF8')
        ),'hex');
        IF v_evidence IS DISTINCT FROM p_last_key->>'evidence_sha256' THEN
            RAISE EXCEPTION USING ERRCODE='22023',
                MESSAGE='Catalog V1 adoption terminal evidence digest differs';
        END IF;
    END IF;
    RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE='22023',
        MESSAGE='Catalog V1 adoption typed evidence invalid';
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_batch_decode_v1(bytea, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_actual_bytes bigint;
    v_change_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption batch principal denied';
    END IF;
    v_actual_bytes:=pg_catalog.octet_length(p_change_batch_bytes);
    IF p_batch_bytes IS DISTINCT FROM v_actual_bytes OR
       v_actual_bytes NOT BETWEEN 2 AND 8388608 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes),'hex')
         IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog V1 adoption batch digest invalid';
    END IF;
    v_batch:=pg_catalog.convert_from(p_change_batch_bytes,'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_batch) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch) AS key)
       IS DISTINCT FROM ARRAY[
         'changes','checkpoint_key','checkpoint_state','last_key',
         'operation_id','relation_ordinal','run_id','scope_id',
         'scope_kind','source_position'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'source_position') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch->'source_position') AS key)
       IS DISTINCT FROM ARRAY[
         'batch_ordinal','commit_lsn','final_lsn','received_lsn',
         'snapshot_lsn','snapshot_name','source_xid'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'changes') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_batch->'changes')>1000 OR
       pg_catalog.jsonb_typeof(v_batch->'last_key') NOT IN ('object','null') OR
       v_batch->'last_key'='{}'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog V1 adoption batch envelope invalid';
    END IF;
    v_change_count:=pg_catalog.jsonb_array_length(v_batch->'changes');
    IF (SELECT pg_catalog.count(DISTINCT change.value->'key')
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes') AS change(value))
       IS DISTINCT FROM v_change_count::bigint OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_batch->'changes')
          WITH ORDINALITY AS change(value,position)
        WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
          OR (SELECT pg_catalog.array_agg(key ORDER BY key)
              FROM pg_catalog.jsonb_object_keys(change.value) AS key)
             IS DISTINCT FROM ARRAY['after','before','key','kind','ordinal']::text[]
          OR (change.value->>'ordinal')::integer IS DISTINCT FROM change.position::integer
          OR change.value->>'kind' NOT IN ('insert','update','delete')
          OR (change.value->>'kind'='insert' AND (
              change.value->'before'<>'null'::jsonb OR
              NOT catalog_v1_adoption_value_valid_v1(
                change.value->'key',change.value->'after'
              )))
          OR (change.value->>'kind'='update' AND (
              NOT catalog_v1_adoption_value_valid_v1(
                change.value->'key',change.value->'before'
              ) OR NOT catalog_v1_adoption_value_valid_v1(
                change.value->'key',change.value->'after'
              )))
          OR (change.value->>'kind'='delete' AND (
              change.value->'after'<>'null'::jsonb OR
              NOT catalog_v1_adoption_value_valid_v1(
                change.value->'key',change.value->'before'
              )))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Catalog V1 adoption batch change invalid';
    END IF;
    RETURN v_batch;
END;
$_$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_consumer_sha256_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_consumer_sha256_v1(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_digest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS tenant
        WHERE tenant.singleton AND tenant.tenant_id=p_tenant_id
          AND tenant.schema_name=pg_catalog.current_schema()
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption consumer evidence denied';
    END IF;
    IF EXISTS (
      SELECT 1 FROM catalog_legacy_route_hits AS route
      LEFT JOIN LATERAL (
        SELECT pg_catalog.count(*) AS count
        FROM catalog_legacy_consumer_acks AS acknowledgement
        WHERE acknowledgement.route_key=route.route_key
      ) AS actual ON true
      WHERE route.retired_at IS NULL OR route.retired_at<route.remove_after OR
        route.consumer_ack_count<>route.required_consumer_count OR
        route.consumer_ack_count<>actual.count OR
        (route.last_hit_at IS NOT NULL AND route.last_hit_at>=route.remove_after) OR
        (route.hit_count=0) IS DISTINCT FROM (route.last_hit_at IS NULL)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption consumers are not retired';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
      pg_catalog.int4send(pg_catalog.octet_length(row.kind))||
      pg_catalog.convert_to(row.kind,'UTF8')||
      pg_catalog.int4send(pg_catalog.octet_length(row.identity))||
      pg_catalog.convert_to(row.identity,'UTF8')||
      pg_catalog.int4send(pg_catalog.octet_length(row.document))||
      pg_catalog.convert_to(row.document,'UTF8'),
      ''::bytea ORDER BY row.kind,row.identity),''::bytea)),'hex')
    INTO v_digest FROM (
      SELECT 'route' AS kind,route.route_key AS identity,to_jsonb(route)::text AS document
      FROM catalog_legacy_route_hits AS route
      UNION ALL
      SELECT 'ack',ack.route_key||':'||ack.consumer_id,to_jsonb(ack)::text
      FROM catalog_legacy_consumer_acks AS ack
    ) AS row;
    RETURN v_digest;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_consumer_sha256_v1(p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_finalize_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_finalize_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_kind text;
    v_stage catalog_v1_adoption_stage%ROWTYPE;
    v_generation bigint;
    v_plan text;
    v_transform text;
    v_lease text;
    v_final_lsn pg_lsn;
    v_evidence jsonb;
    v_source_count bigint;
    v_source_root text;
    v_target_count bigint;
    v_target_root text;
    v_live_count bigint;
    v_live_root text;
    v_blocker text;
    v_consumer text;
    v_acceptance text;
    v_now timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption finalization principal denied';
    END IF;
    v_now:=pg_catalog.date_trunc(
      'microseconds',pg_catalog.transaction_timestamp()
    );
    SELECT ready.final_lsn,ready.evidence INTO STRICT v_final_lsn,v_evidence
    FROM catalog_v1_adoption_projection_ready_v1(
      p_operation_id,p_run_id,p_scope_id
    ) AS ready;
    SELECT operation.cutover_generation,operation.plan_sha256,
      operation.transform_manifest_sha256,operation.lease_manifest_sha256
    INTO STRICT v_generation,v_plan,v_transform,v_lease
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
    FOR SHARE;
    SELECT pg_catalog.count(*),
      pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
        pg_catalog.int4send(pg_catalog.octet_length(source.kind))||
        pg_catalog.convert_to(source.kind,'UTF8')||
        pg_catalog.int4send(pg_catalog.octet_length(source.identity))||
        pg_catalog.convert_to(source.identity,'UTF8')||
        pg_catalog.int4send(pg_catalog.octet_length(source.document))||
        pg_catalog.convert_to(source.document,'UTF8'),
        ''::bytea ORDER BY source.kind,source.identity),''::bytea)),'hex')
    INTO v_source_count,v_source_root FROM (
      SELECT CASE stage.source_kind
        WHEN 'modules' THEN 'module'
        WHEN 'module_dependencies' THEN 'dependency'
        WHEN 'module_forms' THEN 'form'
        WHEN 'module_schema_versions' THEN 'schema_version'
        WHEN 'module_migration_runs' THEN 'migration_run'
        WHEN 'menu_configs' THEN 'menu' END AS kind,
        stage.source_identity AS identity,
        pg_catalog.min(stage.source_document::text) AS document
      FROM catalog_v1_adoption_stage AS stage
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed
      GROUP BY stage.source_kind,stage.source_identity
    ) AS source;
    SELECT pg_catalog.count(*),
      pg_catalog.encode(pg_catalog.sha256(COALESCE(pg_catalog.string_agg(
        pg_catalog.int4send(pg_catalog.octet_length(stage.target_kind))||
        pg_catalog.convert_to(stage.target_kind,'UTF8')||
        pg_catalog.int4send(pg_catalog.octet_length(stage.target_identity))||
        pg_catalog.convert_to(stage.target_identity,'UTF8')||
        pg_catalog.int4send(pg_catalog.octet_length(stage.target_record::text))||
        pg_catalog.convert_to(stage.target_record::text,'UTF8'),
        ''::bytea ORDER BY stage.target_kind,stage.target_identity),''::bytea)),'hex')
    INTO v_target_count,v_target_root
    FROM catalog_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed AND stage.target_kind<>'discard';
    SELECT root.row_count,root.root_sha256 INTO STRICT v_live_count,v_live_root
    FROM catalog_adoption_inventory_root_v1(p_scope_id,'source') AS root;
    v_blocker:=catalog_adoption_blocker_sha256_v1(p_scope_id);
    v_consumer:=catalog_v1_adoption_consumer_sha256_v1(p_scope_id);
    IF EXISTS (SELECT 1 FROM catalog_adoption_blockers_v1(p_scope_id)) OR
       v_source_count IS DISTINCT FROM v_live_count OR
       v_source_root IS DISTINCT FROM v_live_root OR
       (v_evidence->>'source_count')::bigint IS DISTINCT FROM v_source_count OR
       v_evidence->>'source_root_sha256' IS DISTINCT FROM v_source_root OR
       (v_evidence->>'target_count')::bigint IS DISTINCT FROM v_target_count OR
       v_evidence->>'target_root_sha256' IS DISTINCT FROM v_target_root OR
       v_evidence->>'blocker_sha256' IS DISTINCT FROM v_blocker OR
       v_evidence->>'consumer_sha256' IS DISTINCT FROM v_consumer THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption inventory evidence differs';
    END IF;
    FOREACH v_kind IN ARRAY ARRAY[
      'installation','binding','dependency',
      'menu_definition','menu_version','menu_item'
    ]::text[] LOOP
      FOR v_stage IN
        SELECT stage.* FROM catalog_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
          AND NOT stage.removed AND stage.target_kind=v_kind
        ORDER BY stage.target_identity
      LOOP
        IF v_kind IN ('installation','binding','dependency') THEN
          PERFORM catalog_v1_adoption_project_core_v1(
            v_stage.target_kind,v_stage.target_record
          );
        ELSE
          PERFORM catalog_v1_adoption_project_menu_v1(
            v_stage.target_kind,v_stage.target_record
          );
        END IF;
      END LOOP;
    END LOOP;
    FOR v_stage IN
      SELECT stage.* FROM catalog_v1_adoption_stage AS stage
      WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
        AND NOT stage.removed AND stage.target_kind='menu_definition'
      ORDER BY stage.target_identity
    LOOP
      PERFORM catalog_v1_adoption_activate_menu_v1(v_stage.target_record);
    END LOOP;
    SELECT root.row_count,root.root_sha256 INTO STRICT v_live_count,v_live_root
    FROM catalog_adoption_inventory_root_v1(p_scope_id,'target') AS root;
    IF v_live_count IS DISTINCT FROM v_target_count OR
       v_live_root IS DISTINCT FROM v_target_root THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption target projection differs';
    END IF;
    INSERT INTO catalog_adoption_runs(
      run_id,source_manifest_sha256,transform_sha256,source_count,target_count,
      source_root_sha256,target_root_sha256,state,blocker_code,
      cutover_generation,created_at,verified_at
    ) VALUES (
      p_run_id,v_plan,v_transform,v_source_count,v_target_count,
      v_source_root,v_target_root,'VERIFIED',NULL,v_generation,v_now,v_now
    ) ON CONFLICT DO NOTHING;
    PERFORM 1 FROM catalog_adoption_runs AS run
    WHERE run.run_id=p_run_id AND run.source_manifest_sha256=v_plan
      AND run.transform_sha256=v_transform AND run.source_count=v_source_count
      AND run.target_count=v_target_count AND run.source_root_sha256=v_source_root
      AND run.target_root_sha256=v_target_root AND run.state='VERIFIED'
      AND run.blocker_code IS NULL AND run.cutover_generation=v_generation
      AND run.created_at=v_now AND run.verified_at=v_now;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption run replay differs';
    END IF;
    v_acceptance:=pg_catalog.encode(pg_catalog.sha256(
      pg_catalog.convert_to('catalog-v1-adoption-acceptance.v1','UTF8')||
      pg_catalog.decode('00','hex')||pg_catalog.uuid_send(p_operation_id)||
      pg_catalog.decode('00','hex')||pg_catalog.uuid_send(p_run_id)||
      pg_catalog.decode('00','hex')||pg_catalog.uuid_send(p_scope_id)||
      pg_catalog.decode('00','hex')||pg_catalog.int8send(v_generation)||
      pg_catalog.decode('00','hex')||pg_catalog.convert_to(v_plan,'UTF8')||
      pg_catalog.decode('00','hex')||pg_catalog.convert_to(v_transform,'UTF8')||
      pg_catalog.decode('00','hex')||pg_catalog.convert_to(v_lease,'UTF8')||
      pg_catalog.decode('00','hex')||pg_catalog.convert_to(v_final_lsn::text,'UTF8')||
      pg_catalog.decode('00','hex')||
      pg_catalog.convert_to(v_evidence->>'evidence_sha256','UTF8')
    ),'hex');
    INSERT INTO catalog_v1_adoption_receipts(
      operation_id,run_id,tenant_id,cutover_generation,plan_sha256,
      transform_sha256,lease_manifest_sha256,final_lsn,source_count,
      source_root_sha256,target_count,target_root_sha256,blocker_sha256,
      consumer_sha256,evidence_sha256,acceptance_sha256,recorded_at
    ) VALUES (
      p_operation_id,p_run_id,p_scope_id,v_generation,v_plan,v_transform,v_lease,
      v_final_lsn,v_source_count,v_source_root,v_target_count,v_target_root,
      v_blocker,v_consumer,v_evidence->>'evidence_sha256',v_acceptance,v_now
    );
    RETURN v_target_root;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_finalize_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_project_core_v1(text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_project_core_v1(p_kind text, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_kind NOT IN ('installation','binding','dependency') OR
       pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption core projection denied';
    END IF;
    IF p_kind='installation' THEN
        INSERT INTO catalog_installations(
          installation_id,package_id,active_version,state,reference_epoch,
          row_version,updated_at
        ) VALUES (
          (p_record->>'installation_id')::uuid,
          (p_record->>'package_id')::uuid,p_record->>'active_version',
          p_record->>'state',(p_record->>'reference_epoch')::bigint,
          (p_record->>'row_version')::bigint,
          (p_record->>'updated_at')::timestamptz
        ) ON CONFLICT DO NOTHING;
        PERFORM 1 FROM catalog_installations AS row
        WHERE row.installation_id=(p_record->>'installation_id')::uuid
          AND to_jsonb(row)=p_record;
    ELSIF p_kind='binding' THEN
        INSERT INTO catalog_component_bindings(
          installation_id,component_id,owner_module,owner_generation,
          owner_contract,content_sha256,state
        ) VALUES (
          (p_record->>'installation_id')::uuid,
          (p_record->>'component_id')::uuid,p_record->>'owner_module',
          (p_record->>'owner_generation')::bigint,p_record->>'owner_contract',
          p_record->>'content_sha256',p_record->>'state'
        ) ON CONFLICT DO NOTHING;
        PERFORM 1 FROM catalog_component_bindings AS row
        WHERE row.installation_id=(p_record->>'installation_id')::uuid
          AND row.component_id=(p_record->>'component_id')::uuid
          AND to_jsonb(row)=p_record;
    ELSE
        INSERT INTO catalog_dependency_resolutions(
          installation_id,dependency_package_id,exact_version,required,plan_sha256
        ) VALUES (
          (p_record->>'installation_id')::uuid,
          (p_record->>'dependency_package_id')::uuid,
          p_record->>'exact_version',(p_record->>'required')::boolean,
          p_record->>'plan_sha256'
        ) ON CONFLICT DO NOTHING;
        PERFORM 1 FROM catalog_dependency_resolutions AS row
        WHERE row.installation_id=(p_record->>'installation_id')::uuid
          AND row.dependency_package_id=(p_record->>'dependency_package_id')::uuid
          AND to_jsonb(row)=p_record;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption core projection differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_project_core_v1(p_kind text, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_project_menu_v1(text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_project_menu_v1(p_kind text, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_kind NOT IN ('menu_definition','menu_version','menu_item') OR
       pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption menu projection denied';
    END IF;
    IF p_kind='menu_definition' THEN
        INSERT INTO catalog_menu_definitions(
          definition_id,revision,active_version_id,updated_at
        ) VALUES (
          (p_record->>'definition_id')::uuid,
          (p_record->>'revision')::bigint,NULL,
          (p_record->>'updated_at')::timestamptz
        ) ON CONFLICT DO NOTHING;
        PERFORM 1 FROM catalog_menu_definitions AS row
        WHERE row.definition_id=(p_record->>'definition_id')::uuid
          AND row.revision=(p_record->>'revision')::bigint
          AND row.active_version_id IS NULL
          AND row.updated_at=(p_record->>'updated_at')::timestamptz;
    ELSIF p_kind='menu_version' THEN
        INSERT INTO catalog_menu_versions(
          version_id,definition_id,version_number,content_sha256,created_at
        ) VALUES (
          (p_record->>'version_id')::uuid,
          (p_record->>'definition_id')::uuid,
          (p_record->>'version_number')::bigint,
          p_record->>'content_sha256',
          (p_record->>'created_at')::timestamptz
        ) ON CONFLICT DO NOTHING;
        PERFORM 1 FROM catalog_menu_versions AS row
        WHERE row.version_id=(p_record->>'version_id')::uuid
          AND to_jsonb(row)=p_record;
    ELSE
        INSERT INTO catalog_menu_items(
          version_id,item_id,parent_item_id,package_id,item_kind,target_id,
          external_url,label,sort_order
        ) VALUES (
          (p_record->>'version_id')::uuid,(p_record->>'item_id')::uuid,
          (p_record->>'parent_item_id')::uuid,(p_record->>'package_id')::uuid,
          p_record->>'item_kind',(p_record->>'target_id')::uuid,
          p_record->>'external_url',p_record->>'label',
          (p_record->>'sort_order')::integer
        ) ON CONFLICT DO NOTHING;
        PERFORM 1 FROM catalog_menu_items AS row
        WHERE row.version_id=(p_record->>'version_id')::uuid
          AND row.item_id=(p_record->>'item_id')::uuid
          AND to_jsonb(row)=p_record;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption menu projection differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_project_menu_v1(p_kind text, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: catalog_v1_adoption_projection_ready_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.catalog_v1_adoption_projection_ready_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS TABLE(final_lsn pg_lsn, evidence jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_generation bigint;
    v_expected bigint;
    v_complete bigint;
    v_final_count bigint;
    v_evidence_count bigint;
    v_existing bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Catalog V1 adoption readiness principal denied';
    END IF;
    SELECT operation.cutover_generation INTO v_generation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='catalog' AND operation.domain='catalog'
      AND operation.state='quiescing'
    FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
      SELECT 1 FROM tenancy_schema_identity AS tenant
      WHERE tenant.singleton AND tenant.tenant_id=p_scope_id
        AND tenant.schema_name=pg_catalog.current_schema()
        AND tenant.origin='v1_adopted'
    ) OR NOT EXISTS (
      SELECT 1 FROM platform.cutover_groups AS fence
      WHERE fence.scope_kind='tenant' AND fence.scope_id=p_scope_id
        AND fence.group_id='catalog' AND fence.generation=v_generation
        AND fence.state='quiescing' AND fence.writer='none'
    ) OR NOT EXISTS (
      SELECT 1 FROM platform.domain_cutovers AS fence
      WHERE fence.scope_kind='tenant' AND fence.scope_id=p_scope_id
        AND fence.domain='catalog' AND fence.generation=v_generation
        AND fence.state='quiescing' AND fence.writer='none'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption projection authority not ready';
    END IF;
    SELECT pg_catalog.count(*) INTO v_expected
    FROM platform.cutover_operation_checkpoint_keys AS expected
    WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
      AND expected.relation_ordinal=1 AND expected.checkpoint_key IN (
        'modules','module_dependencies','module_forms',
        'module_schema_versions','module_migration_runs','menu_configs'
      );
    SELECT pg_catalog.count(*),
      pg_catalog.count(DISTINCT checkpoint.final_lsn::text),
      pg_catalog.count(DISTINCT checkpoint.last_key)
    INTO v_complete,v_final_count,v_evidence_count
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id
      AND checkpoint.relation_ordinal=1 AND checkpoint.state='complete'
      AND checkpoint.final_lsn IS NOT NULL
      AND checkpoint.applied_lsn=checkpoint.final_lsn;
    IF v_expected<>6 OR (SELECT pg_catalog.count(*)
      FROM platform.cutover_operation_checkpoint_keys AS expected
      WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id)<>6 OR
      v_complete<>6 OR v_final_count<>1 OR v_evidence_count<>1 OR EXISTS (
      SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS expected
      LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint
        ON checkpoint.operation_id=expected.operation_id
       AND checkpoint.run_id=expected.run_id
       AND checkpoint.relation_ordinal=expected.relation_ordinal
       AND checkpoint.checkpoint_key=expected.checkpoint_key
       AND checkpoint.state='complete'
      WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
        AND checkpoint.operation_id IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption checkpoints incomplete';
    END IF;
    SELECT
      (SELECT pg_catalog.count(*) FROM catalog_installations)+
      (SELECT pg_catalog.count(*) FROM catalog_component_bindings)+
      (SELECT pg_catalog.count(*) FROM catalog_dependency_resolutions)+
      (SELECT pg_catalog.count(*) FROM catalog_menu_definitions)+
      (SELECT pg_catalog.count(*) FROM catalog_menu_versions)+
      (SELECT pg_catalog.count(*) FROM catalog_menu_items)
    INTO v_existing;
    IF v_existing<>0 OR EXISTS (
      SELECT 1 FROM catalog_operation_runs AS operation
      WHERE operation.state IN (
        'PLANNED','APPLYING','WAITING','VERIFYING','ACTIVATING','CANCELLING'
      )
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Catalog V1 adoption inactive target not ready';
    END IF;
    RETURN QUERY
    SELECT checkpoint.final_lsn,checkpoint.last_key
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id
    ORDER BY checkpoint.checkpoint_key LIMIT 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.catalog_v1_adoption_projection_ready_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

