        (OLD.lifecycle_state = 'PENDING' AND NEW.lifecycle_state = 'PENDING' AND
         OLD.entry_count = 0 AND NEW.entry_count > 0 AND
         OLD.entries_sha256 IS NULL AND NEW.entries_sha256 IS NOT NULL)
