        OR (OLD.lifecycle_state = 'EXPIRED' AND NEW.lifecycle_state = 'PURGED' AND
            NEW.delete_receipt_sha256 IS NOT NULL AND NEW.purged_at IS NOT NULL);
    IF NOT allowed OR
       (NEW.id, NEW.actor_id, NEW.authorization_revision, NEW.job_id,
        NEW.retry_of_archive_id, NEW.request_sha256, NEW.request_document,
        NEW.billing_reservation_id, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.actor_id, OLD.authorization_revision, OLD.job_id,
        OLD.retry_of_archive_id, OLD.request_sha256, OLD.request_document,
        OLD.billing_reservation_id, OLD.created_at) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'DOCUMENT_ARCHIVE_IMMUTABLE';
    END IF;
    IF OLD.lifecycle_state <> 'PENDING' AND
       (NEW.entry_count, NEW.entries_sha256, NEW.plaintext_bytes,
        NEW.ciphertext_bytes, NEW.artifact_sha256, NEW.ciphertext_sha256,
        NEW.artifact_plaintext_bytes, NEW.cipher_format, NEW.object_key,
        NEW.object_version, NEW.object_generation, NEW.key_id, NEW.wrapped_dek,
        NEW.ready_at, NEW.expires_at)
       IS DISTINCT FROM
       (OLD.entry_count, OLD.entries_sha256, OLD.plaintext_bytes,
        OLD.ciphertext_bytes, OLD.artifact_sha256, OLD.ciphertext_sha256,
        OLD.artifact_plaintext_bytes, OLD.cipher_format, OLD.object_key,
        OLD.object_version, OLD.object_generation, OLD.key_id, OLD.wrapped_dek,
        OLD.ready_at, OLD.expires_at) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'DOCUMENT_ARCHIVE_IMMUTABLE';
    END IF;
    IF OLD.lifecycle_state = 'PENDING' AND OLD.object_version IS NOT NULL AND
       (NEW.artifact_plaintext_bytes, NEW.ciphertext_bytes, NEW.artifact_sha256,
        NEW.ciphertext_sha256, NEW.cipher_format, NEW.object_key,
        NEW.object_version, NEW.object_generation, NEW.key_id, NEW.wrapped_dek)
       IS DISTINCT FROM
       (OLD.artifact_plaintext_bytes, OLD.ciphertext_bytes, OLD.artifact_sha256,
        OLD.ciphertext_sha256, OLD.cipher_format, OLD.object_key,
        OLD.object_version, OLD.object_generation, OLD.key_id, OLD.wrapped_dek) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'DOCUMENT_ARCHIVE_IMMUTABLE';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_guard_archive_transition_v1() OWNER TO harpy_owner;

--
-- Name: documents_guard_current_version_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_guard_current_version_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.lifecycle_state IN ('PURGING','PURGED') THEN
        IF NEW.current_version_id IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'DOCUMENT_DELETING_CURRENT_VERSION';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.current_version_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM documents_versions version
        WHERE version.id = NEW.current_version_id
          AND version.item_id = NEW.id
          AND version.lifecycle_state = 'READY'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'DOCUMENT_CURRENT_VERSION_INVALID';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_guard_current_version_v1() OWNER TO harpy_owner;

--
-- Name: documents_guard_folder_cycle_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_guard_folder_cycle_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE ancestor_id uuid;
BEGIN
    LOCK TABLE documents_folders IN SHARE ROW EXCLUSIVE MODE;
    IF NEW.parent_id IS NULL THEN
        RETURN NEW;
    END IF;
    ancestor_id := NEW.parent_id;
    WHILE ancestor_id IS NOT NULL LOOP
        IF ancestor_id = NEW.id THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'DOCUMENT_FOLDER_CYCLE';
        END IF;
        SELECT parent_id INTO ancestor_id
        FROM documents_folders WHERE id = ancestor_id;
    END LOOP;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_guard_folder_cycle_v1() OWNER TO harpy_owner;

--
-- Name: documents_guard_knowledge_file_lease_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_guard_knowledge_file_lease_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.lease_id <> OLD.lease_id OR NEW.upload_id <> OLD.upload_id
       OR NEW.actor_id <> OLD.actor_id OR NEW.item_id <> OLD.item_id
       OR NEW.version_id <> OLD.version_id
       OR NEW.expected_plaintext_bytes <> OLD.expected_plaintext_bytes
       OR NEW.expected_plaintext_sha256 <> OLD.expected_plaintext_sha256
       OR NEW.filename <> OLD.filename OR NEW.declared_mime <> OLD.declared_mime
       OR NEW.expires_at <> OLD.expires_at OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'documents knowledge-file lease identity is immutable';
    END IF;
    IF NOT (
        NEW.lifecycle_state = OLD.lifecycle_state
        OR OLD.lifecycle_state = 'PENDING' AND NEW.lifecycle_state IN ('STAGED','EXPIRED')
        OR OLD.lifecycle_state = 'STAGED' AND NEW.lifecycle_state IN ('ADOPTED','EXPIRED')
        OR OLD.lifecycle_state = 'ADOPTED' AND NEW.lifecycle_state = 'RELEASED'
    ) THEN
        RAISE EXCEPTION 'documents knowledge-file lease transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_guard_knowledge_file_lease_v1() OWNER TO harpy_owner;

--
-- Name: documents_guard_reference_target_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_guard_reference_target_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE item_state text;
BEGIN
    IF NEW.lifecycle_state <> 'ACTIVE' THEN
        RETURN NEW;
    END IF;
    SELECT lifecycle_state INTO item_state
    FROM documents_items WHERE id = NEW.item_id FOR SHARE;
    IF item_state IS DISTINCT FROM 'ACTIVE' THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'DOCUMENT_REFERENCE_TARGET_CLOSED';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_guard_reference_target_v1() OWNER TO harpy_owner;

--
-- Name: documents_guard_reference_transition_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_guard_reference_transition_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' OR OLD.lifecycle_state <> 'ACTIVE' OR
       NEW.lifecycle_state <> 'RELEASED' OR OLD.released_at IS NOT NULL OR
       NEW.released_at IS NULL OR
       (pg_catalog.to_jsonb(NEW) - 'lifecycle_state' - 'released_at')
       IS DISTINCT FROM
       (pg_catalog.to_jsonb(OLD) - 'lifecycle_state' - 'released_at') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'DOCUMENT_REFERENCE_IMMUTABLE';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_guard_reference_transition_v1() OWNER TO harpy_owner;

--
-- Name: documents_guard_upload_transition_restore_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_guard_upload_transition_restore_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE allowed boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'DOCUMENT_UPLOAD_IMMUTABLE';
    END IF;
    IF SESSION_USER = 'harpy_restore'
       AND OLD.lifecycle_state NOT IN ('READY','CANCELLED','EXPIRED')
       AND NEW.lifecycle_state = 'CANCELLED'
       AND NEW.lease_owner_id IS NULL AND NEW.lease_expires_at IS NULL
       AND NEW.cancel_requested_at IS NOT NULL AND NOT NEW.cleanup_required
       AND (NEW.id, NEW.actor_id, NEW.document_id, NEW.candidate_version_id,
            NEW.expected_current_version_id, NEW.folder_id, NEW.request_sha256,
            NEW.expected_content_sha256, NEW.expected_plaintext_bytes,
            NEW.ciphertext_upper_bound, NEW.original_name, NEW.declared_mime,
            NEW.description, NEW.tags, NEW.billing_reservation_id,
            NEW.expires_at, NEW.created_at)
           IS NOT DISTINCT FROM
           (OLD.id, OLD.actor_id, OLD.document_id, OLD.candidate_version_id,
            OLD.expected_current_version_id, OLD.folder_id, OLD.request_sha256,
            OLD.expected_content_sha256, OLD.expected_plaintext_bytes,
            OLD.ciphertext_upper_bound, OLD.original_name, OLD.declared_mime,
            OLD.description, OLD.tags, OLD.billing_reservation_id,
            OLD.expires_at, OLD.created_at) THEN
        RETURN NEW;
    END IF;
    allowed :=
        (OLD.lifecycle_state IN ('CREATED','RETRYABLE') AND
         NEW.lifecycle_state = 'RECEIVING' AND
         NEW.attempt_generation = OLD.attempt_generation + 1 AND
         NOT OLD.cleanup_required AND NEW.cancel_requested_at IS NULL)
        OR (OLD.lifecycle_state = 'RECEIVING' AND
            NEW.lifecycle_state IN ('SCANNING','RETRYABLE','REJECTED'))
        OR (OLD.lifecycle_state = 'SCANNING' AND
            NEW.lifecycle_state IN ('READY','RETRYABLE','REJECTED','CONFLICTED'))
        OR (OLD.lifecycle_state IN ('RECEIVING','SCANNING') AND
            NEW.lifecycle_state = OLD.lifecycle_state AND
            OLD.cancel_requested_at IS NULL AND NEW.cancel_requested_at IS NOT NULL)
        OR (OLD.lifecycle_state IN ('RECEIVING','SCANNING') AND
            NEW.lifecycle_state = 'CANCELLED' AND
            NEW.cancel_requested_at IS NOT NULL AND NEW.cleanup_required)
        OR (OLD.lifecycle_state IN ('CREATED','RETRYABLE') AND
            NEW.lifecycle_state IN ('CANCELLED','EXPIRED') AND NOT OLD.cleanup_required)
        OR (OLD.lifecycle_state IN ('RETRYABLE','REJECTED','CONFLICTED','CANCELLED') AND
            NEW.lifecycle_state = OLD.lifecycle_state AND OLD.cleanup_required AND
            NOT NEW.cleanup_required AND NEW.cleanup_receipt_sha256 IS NOT NULL);
    IF NOT allowed OR
       (NEW.id, NEW.actor_id, NEW.document_id, NEW.candidate_version_id,
        NEW.expected_current_version_id, NEW.folder_id, NEW.request_sha256,
        NEW.expected_content_sha256, NEW.expected_plaintext_bytes,
        NEW.ciphertext_upper_bound, NEW.original_name, NEW.declared_mime,
        NEW.description, NEW.tags, NEW.billing_reservation_id,
        NEW.expires_at, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.actor_id, OLD.document_id, OLD.candidate_version_id,
        OLD.expected_current_version_id, OLD.folder_id, OLD.request_sha256,
        OLD.expected_content_sha256, OLD.expected_plaintext_bytes,
        OLD.ciphertext_upper_bound, OLD.original_name, OLD.declared_mime,
        OLD.description, OLD.tags, OLD.billing_reservation_id,
        OLD.expires_at, OLD.created_at) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'DOCUMENT_UPLOAD_IMMUTABLE';
    END IF;
    RETURN NEW;
END;
$$;


