--
-- Name: documents_item_response_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_item_response_v1(target_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN (SELECT pg_catalog.convert_to(pg_catalog.jsonb_build_object(
        'id', i.id::text, 'folder_id', i.folder_id::text,
        'owner_id', i.owner_id::text,
        'current_version_id', i.current_version_id::text,
        'state', i.lifecycle_state, 'row_version', i.row_version,
        'description', i.description, 'tags', i.tags,
        'trashed_at', i.trashed_at, 'retention_ends_at', i.retention_ends_at,
        'purge_requested_at', i.purge_requested_at,
        'purge_starts_at', i.purge_starts_at,
        'created_at', i.created_at, 'updated_at', i.updated_at,
        'current', pg_catalog.jsonb_build_object(
            'id', v.id::text, 'number', v.version_number,
            'original_name', v.original_name, 'mime', v.detected_mime,
            'file_kind', v.file_kind, 'plaintext_bytes', v.plaintext_bytes,
            'plaintext_sha256', pg_catalog.encode(v.plaintext_sha256, 'hex'),
            'created_at', v.created_at
        )
    )::text, 'UTF8')
    FROM documents_items i
    JOIN documents_versions v ON v.id = i.current_version_id
    WHERE i.id = target_id AND i.lifecycle_state <> 'PURGED'
      AND v.lifecycle_state = 'READY');
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_item_response_v1(target_id uuid) OWNER TO harpy_owner;

--
-- Name: documents_recovery_apply_locator_v1(uuid, uuid, uuid, text, text, text, text, bigint, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_recovery_apply_locator_v1(p_restore_operation_id uuid, p_recovery_set_id uuid, p_version_id uuid, p_source_object_key text, p_source_object_version text, p_target_object_key text, p_target_object_version text, p_target_object_generation bigint, p_ciphertext_sha256 bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing documents_restore_locator_remaps%ROWTYPE;
    v_live documents_versions%ROWTYPE;
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR p_restore_operation_id IS NULL OR p_target_object_generation < 1
       OR p_target_object_version = '' OR p_target_object_key <> p_source_object_key
       OR pg_catalog.octet_length(p_ciphertext_sha256) <> 32
       OR NOT EXISTS (
           SELECT 1 FROM documents_dr_holds AS hold
           JOIN documents_dr_copy_receipts AS receipt
             ON receipt.recovery_set_id = hold.recovery_set_id
           WHERE hold.recovery_set_id = p_recovery_set_id
             AND hold.lifecycle_state IN ('VERIFIED','RELEASED')
             AND receipt.version_id = p_version_id
             AND receipt.source_object_key = p_source_object_key
             AND receipt.source_object_version = p_source_object_version
             AND receipt.ciphertext_sha256 = p_ciphertext_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'documents restore locator denied';
    END IF;
    SELECT * INTO v_existing FROM documents_restore_locator_remaps
    WHERE restore_operation_id = p_restore_operation_id AND version_id = p_version_id;
    IF FOUND THEN
        SELECT * INTO v_live
        FROM documents_versions
        WHERE id = p_version_id
        FOR UPDATE;
        IF NOT FOUND THEN
            RETURN false;
        END IF;
        RETURN (v_existing.recovery_set_id, v_existing.source_object_key,
                v_existing.source_object_version, v_existing.target_object_key,
                v_existing.target_object_version, v_existing.target_object_generation,
                v_existing.ciphertext_sha256, v_live.lifecycle_state,
                v_live.object_key, v_live.object_version,
                v_live.object_generation, v_live.ciphertext_sha256)
            IS NOT DISTINCT FROM
               (p_recovery_set_id, p_source_object_key, p_source_object_version,
                p_target_object_key, p_target_object_version,
                p_target_object_generation, p_ciphertext_sha256, 'READY',
                p_target_object_key, p_target_object_version,
                p_target_object_generation, p_ciphertext_sha256);
    END IF;
    UPDATE documents_versions SET object_key = p_target_object_key,
        object_version = p_target_object_version,
        object_generation = p_target_object_generation
    WHERE id = p_version_id AND lifecycle_state = 'READY'
      AND object_key = p_source_object_key AND object_version = p_source_object_version
      AND ciphertext_sha256 = p_ciphertext_sha256;
    IF NOT FOUND THEN RETURN false; END IF;
    INSERT INTO documents_restore_locator_remaps VALUES (
        p_restore_operation_id, p_recovery_set_id, p_version_id,
        p_source_object_key, p_source_object_version, p_target_object_key,
        p_target_object_version, p_target_object_generation,
        p_ciphertext_sha256, v_now
    );
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_recovery_apply_locator_v1(p_restore_operation_id uuid, p_recovery_set_id uuid, p_version_id uuid, p_source_object_key text, p_source_object_version text, p_target_object_key text, p_target_object_version text, p_target_object_generation bigint, p_ciphertext_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: documents_recovery_begin_hold_v1(uuid, uuid, uuid, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_recovery_begin_hold_v1(p_recovery_set_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_set_sha256 bytea) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing documents_dr_holds%ROWTYPE;
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR p_recovery_set_id IS NULL OR p_environment_id IS NULL
       OR p_tenant_id IS NULL
       OR pg_catalog.octet_length(p_tenant_set_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'documents recovery hold denied';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'documents:dr-hold:' || pg_catalog.current_schema(), 0
        )
    );
    IF NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.tenant_id = p_tenant_id
          AND identity.schema_name = pg_catalog.current_schema()
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'documents recovery tenant mismatch';
    END IF;
    SELECT * INTO v_existing
    FROM documents_dr_holds
    WHERE recovery_set_id = p_recovery_set_id;
    IF FOUND THEN
        IF v_existing.environment_id <> p_environment_id
           OR v_existing.tenant_id <> p_tenant_id
           OR v_existing.tenant_set_sha256 <> p_tenant_set_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'documents recovery hold conflicts';
        END IF;
        RETURN v_existing.lifecycle_state;
    END IF;
    IF EXISTS (
        SELECT 1 FROM documents_dr_holds AS hold
        WHERE hold.lifecycle_state IN ('HOLDING','COPYING','VERIFIED')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'documents recovery hold is already active';
    END IF;
    IF EXISTS (
        SELECT 1 FROM documents_blob_deletions AS deletion
        WHERE deletion.target_kind IN ('VERSION','ARCHIVE')
          AND deletion.lifecycle_state IN ('CLAIMED','RECONCILING')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'documents durable deletion is in flight';
    END IF;
    INSERT INTO documents_dr_holds(
        recovery_set_id, environment_id, tenant_id,
        tenant_set_sha256, lifecycle_state,
        started_at, updated_at
    ) VALUES (
        p_recovery_set_id, p_environment_id, p_tenant_id,
        p_tenant_set_sha256, 'HOLDING',
        v_now, v_now
    );
    RETURN 'HOLDING';
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_recovery_begin_hold_v1(p_recovery_set_id uuid, p_environment_id uuid, p_tenant_id uuid, p_tenant_set_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: documents_recovery_fail_hold_v1(uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_recovery_fail_hold_v1(p_recovery_set_id uuid, p_failure_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR p_failure_code !~ '^[a-z0-9_]{1,64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'documents recovery failure denied';
    END IF;
    UPDATE documents_dr_holds
    SET lifecycle_state = 'FAILED', failure_code = p_failure_code,
        updated_at = pg_catalog.statement_timestamp()
    WHERE recovery_set_id = p_recovery_set_id
      AND lifecycle_state IN ('HOLDING','COPYING','VERIFIED');
    RETURN FOUND;
END;
$_$;


ALTER FUNCTION __tenant_schema__.documents_recovery_fail_hold_v1(p_recovery_set_id uuid, p_failure_code text) OWNER TO harpy_owner;

--
-- Name: documents_recovery_fail_hold_v2(uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_recovery_fail_hold_v2(p_recovery_set_id uuid, p_failure_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
