--
-- Name: documents_recovery_inventory_v1(uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_recovery_inventory_v1(p_recovery_set_id uuid, p_tenant_id uuid) RETURNS TABLE(version_id uuid, object_key text, object_version text, object_generation bigint, ciphertext_sha256 bytea, ciphertext_bytes bigint, key_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR NOT EXISTS (
           SELECT 1 FROM documents_dr_holds AS hold
           WHERE hold.recovery_set_id = p_recovery_set_id
             AND hold.tenant_id = p_tenant_id
             AND hold.lifecycle_state IN ('HOLDING','COPYING','VERIFIED')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'documents recovery inventory denied';
    END IF;
    RETURN QUERY
    SELECT version.id, version.object_key, version.object_version,
           version.object_generation, version.ciphertext_sha256,
           version.ciphertext_bytes, version.key_id
    FROM documents_versions AS version
    WHERE version.lifecycle_state = 'READY'
    ORDER BY version.id;
END;
$$;


