--
-- Name: documents_recovery_seal_hold_v1(uuid, bytea, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_recovery_seal_hold_v1(p_recovery_set_id uuid, p_inventory_sha256 bytea, p_inventory_count bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_backup'
       OR pg_catalog.octet_length(p_inventory_sha256) <> 32
       OR p_inventory_count < 0 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'documents recovery seal denied';
    END IF;
    UPDATE documents_dr_holds AS hold
    SET lifecycle_state = 'VERIFIED',
        inventory_sha256 = p_inventory_sha256,
        inventory_count = p_inventory_count,
        updated_at = v_now
    WHERE hold.recovery_set_id = p_recovery_set_id
      AND hold.lifecycle_state IN ('HOLDING','COPYING')
      AND (
          SELECT pg_catalog.count(*)
          FROM documents_dr_copy_receipts AS receipt
          WHERE receipt.recovery_set_id = p_recovery_set_id
      ) = p_inventory_count;
    RETURN FOUND;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_recovery_seal_hold_v1(p_recovery_set_id uuid, p_inventory_sha256 bytea, p_inventory_count bigint) OWNER TO harpy_owner;

