--
-- Name: documents_recovery_terminalize_transients_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_recovery_terminalize_transients_v1(p_restore_operation_id uuid) RETURNS TABLE(cancelled_uploads bigint, expired_archives bigint, cancelled_archives bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR p_restore_operation_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'documents transient restore policy denied';
    END IF;
    WITH changed AS (
        UPDATE documents_uploads SET lifecycle_state='CANCELLED',
            lease_owner_id=NULL,lease_expires_at=NULL,cancel_requested_at=v_now,
            cleanup_required=false,updated_at=v_now
        WHERE lifecycle_state NOT IN ('READY','CANCELLED','EXPIRED')
        RETURNING id
    ), disposed AS (
        INSERT INTO documents_restore_transient_dispositions
            (restore_operation_id,target_kind,target_id,disposition,disposed_at)
        SELECT p_restore_operation_id,'UPLOAD',id,'CANCELLED',v_now FROM changed
        ON CONFLICT DO NOTHING
    )
    SELECT pg_catalog.count(*) INTO cancelled_uploads FROM changed;
    WITH changed AS (
        UPDATE documents_archives SET lifecycle_state='EXPIRED',updated_at=v_now
        WHERE lifecycle_state='READY'
        RETURNING id
    ), disposed AS (
        INSERT INTO documents_restore_transient_dispositions
            (restore_operation_id,target_kind,target_id,disposition,disposed_at)
        SELECT p_restore_operation_id,'ARCHIVE',id,'EXPIRED',v_now FROM changed
        ON CONFLICT DO NOTHING
    )
    SELECT pg_catalog.count(*) INTO expired_archives FROM changed;
    WITH changed AS (
        UPDATE documents_archives SET lifecycle_state='CANCELLED',updated_at=v_now
        WHERE lifecycle_state='PENDING'
        RETURNING id
    ), disposed AS (
        INSERT INTO documents_restore_transient_dispositions
            (restore_operation_id,target_kind,target_id,disposition,disposed_at)
        SELECT p_restore_operation_id,'ARCHIVE',id,'CANCELLED',v_now FROM changed
        ON CONFLICT DO NOTHING
    )
    SELECT pg_catalog.count(*) INTO cancelled_archives FROM changed;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_recovery_terminalize_transients_v1(p_restore_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: documents_recovery_terminalize_transients_v2(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_recovery_terminalize_transients_v2(p_restore_operation_id uuid) RETURNS TABLE(cancelled_uploads bigint, expired_archives bigint, cancelled_archives bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_restore'
       OR p_restore_operation_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'documents transient restore policy denied';
    END IF;
    WITH changed AS (
        UPDATE documents_uploads
        SET lifecycle_state = 'CANCELLED',
            lease_owner_id = NULL,
            lease_expires_at = NULL,
            cancel_requested_at = v_now,
            cleanup_required = false,
            updated_at = v_now
        WHERE lifecycle_state NOT IN ('READY','CANCELLED','EXPIRED')
        RETURNING id
    )
    INSERT INTO documents_restore_transient_dispositions(
        restore_operation_id,target_kind,target_id,disposition,disposed_at
    )
    SELECT p_restore_operation_id,'UPLOAD',id,'CANCELLED',v_now
    FROM changed
    ON CONFLICT DO NOTHING;
    WITH changed AS (
        UPDATE documents_archives
        SET lifecycle_state = 'EXPIRED',updated_at = v_now
        WHERE lifecycle_state = 'READY'
        RETURNING id
    )
    INSERT INTO documents_restore_transient_dispositions(
        restore_operation_id,target_kind,target_id,disposition,disposed_at
    )
    SELECT p_restore_operation_id,'ARCHIVE',id,'EXPIRED',v_now
    FROM changed
    ON CONFLICT DO NOTHING;

    WITH changed AS (
        UPDATE documents_archives
        SET lifecycle_state = 'CANCELLED',updated_at = v_now
        WHERE lifecycle_state = 'PENDING'
        RETURNING id
    )
    INSERT INTO documents_restore_transient_dispositions(
        restore_operation_id,target_kind,target_id,disposition,disposed_at
    )
    SELECT p_restore_operation_id,'ARCHIVE',id,'CANCELLED',v_now
    FROM changed
    ON CONFLICT DO NOTHING;

    SELECT count(*) FILTER (
               WHERE target_kind = 'UPLOAD' AND disposition = 'CANCELLED'
           ),
           count(*) FILTER (
               WHERE target_kind = 'ARCHIVE' AND disposition = 'EXPIRED'
           ),
           count(*) FILTER (
               WHERE target_kind = 'ARCHIVE' AND disposition = 'CANCELLED'
           )
    INTO cancelled_uploads,expired_archives,cancelled_archives
    FROM documents_restore_transient_dispositions
    WHERE restore_operation_id = p_restore_operation_id;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_recovery_terminalize_transients_v2(p_restore_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_accept_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_accept_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_adoption_run_id uuid;
    v_final_lsn pg_lsn;
    v_binding_root text;
    v_effect_root text;
    v_row_root text;
    v_generation bigint;
    v_manifest text;
    v_source_count bigint;
    v_target_count bigint;
    v_source_bytes bigint;
    v_target_bytes bigint;
    v_source_root text;
    v_target_root text;
    v_acceptance bytea;
    v_receipt_sha text;
    v_rows bigint;
    v_now timestamptz:=pg_catalog.transaction_timestamp();
BEGIN
    SELECT ready.adoption_run_id,ready.final_lsn,
        ready.binding_root_sha256,ready.effect_root_sha256
    INTO STRICT v_adoption_run_id,v_final_lsn,v_binding_root,v_effect_root
    FROM documents_v1_adoption_projection_ready_v1(
        p_operation_id,p_cutover_run_id,p_scope_id
    ) AS ready;
    v_row_root:=documents_v1_adoption_project_rows_v1(
        p_operation_id,p_cutover_run_id,p_scope_id
    );
    SELECT operation.cutover_generation,operation.lease_manifest_sha256
    INTO STRICT v_generation,v_manifest
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id
      AND operation.run_id=p_cutover_run_id
    FOR SHARE;
    SELECT pg_catalog.count(*)::bigint,
        pg_catalog.count(*) FILTER (
            WHERE checkpoint.lifecycle_state='VERIFIED'
        )::bigint,
        COALESCE(pg_catalog.sum(checkpoint.source_bytes),0)::bigint,
        COALESCE(pg_catalog.sum(checkpoint.source_bytes) FILTER (
            WHERE checkpoint.lifecycle_state='VERIFIED'
        ),0)::bigint,
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
            pg_catalog.string_agg(checkpoint.source_version_id::text||':'||
                checkpoint.source_object_revision||':'||
                pg_catalog.encode(checkpoint.source_sha256,'hex')||':'||
                pg_catalog.encode(checkpoint.source_metadata_sha256,'hex'),','
                ORDER BY checkpoint.source_version_id,
                         checkpoint.source_object_revision),''),'UTF8')),'hex'),
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
            pg_catalog.string_agg(checkpoint.source_version_id::text||':'||
                checkpoint.source_object_revision||':'||
                pg_catalog.encode(checkpoint.target_plaintext_sha256,'hex')||':'||
                pg_catalog.encode(checkpoint.metadata_sha256,'hex'),','
                ORDER BY checkpoint.target_version_id,
                         checkpoint.source_object_revision),''),'UTF8')),'hex')
    INTO v_source_count,v_target_count,v_source_bytes,v_target_bytes,
         v_source_root,v_target_root
    FROM documents_blob_copy_checkpoints AS checkpoint
    WHERE checkpoint.run_id=v_adoption_run_id;
    IF v_source_count IS DISTINCT FROM v_target_count OR
       v_source_bytes IS DISTINCT FROM v_target_bytes OR
       v_source_root IS DISTINCT FROM v_target_root OR
       v_target_count IS DISTINCT FROM (
           SELECT pg_catalog.count(*)
           FROM documents_v1_adoption_stage AS stage
           WHERE stage.operation_id=p_operation_id
             AND stage.cutover_run_id=p_cutover_run_id
             AND stage.target_kind='version' AND NOT stage.removed
       ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 exact digest reconciliation differs';
    END IF;
    v_acceptance:=pg_catalog.sha256(
        pg_catalog.decode(v_manifest,'hex')||
        pg_catalog.decode(v_source_root,'hex')||
        pg_catalog.decode(v_target_root,'hex')||
        pg_catalog.decode(v_row_root,'hex')||
        pg_catalog.decode(v_binding_root,'hex')||
        pg_catalog.decode(v_effect_root,'hex')
    );
    UPDATE documents_adoption_runs SET lifecycle_state='ACCEPTED',
        source_count=v_source_count,target_count=v_target_count,
        source_plaintext_bytes=v_source_bytes,
        target_plaintext_bytes=v_target_bytes,
        source_merkle_sha256=pg_catalog.decode(v_source_root,'hex'),
        target_merkle_sha256=pg_catalog.decode(v_target_root,'hex'),
        pending_object_count=0,pending_job_count=0,
        final_lsn=v_final_lsn,applied_lsn=v_final_lsn,
        acceptance_sha256=v_acceptance,updated_at=v_now
    WHERE run_id=v_adoption_run_id AND cutover_generation=v_generation
      AND manifest_sha256=pg_catalog.decode(v_manifest,'hex')
      AND lifecycle_state IN (
          'INVENTORY','COPYING','SHADOW','RECONCILING','QUIESCED'
      );
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 adoption acceptance state differs';
    END IF;
    v_receipt_sha:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy/documents/v1-cutover-receipt/v1:'||p_operation_id::text||':'||
        p_cutover_run_id::text||':'||v_adoption_run_id::text||':'||p_scope_id::text||
        ':'||v_generation::text||':'||v_source_count::text||':'||
        v_source_bytes::text||':'||v_source_root||':'||v_target_root||':'||
        v_row_root||':'||v_binding_root||':'||v_effect_root||':'||v_final_lsn::text,
        'UTF8'
    )),'hex');
    INSERT INTO documents_v1_cutover_receipts (
        operation_id,cutover_run_id,adoption_run_id,tenant_id,cutover_generation,
        source_count,target_count,source_plaintext_bytes,target_plaintext_bytes,
        source_merkle_sha256,target_merkle_sha256,row_root_sha256,
        binding_root_sha256,effect_root_sha256,final_lsn,accepted_at,receipt_sha256
    ) VALUES (
        p_operation_id,p_cutover_run_id,v_adoption_run_id,p_scope_id,v_generation,
        v_source_count,v_target_count,v_source_bytes,v_target_bytes,
        v_source_root,v_target_root,v_row_root,v_binding_root,v_effect_root,
        v_final_lsn,v_now,v_receipt_sha
    );
    RETURN v_row_root;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_accept_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract_id text;
    v_procedure_oid bigint;
    v_procedure_signature text;
    v_expected_signature text;
    v_already_applied boolean;
    v_applied_count bigint;
    v_key_sha text;
    v_state_sha text;
    v_projected_sha text;
    v_asserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 adoption composite principal denied';
    END IF;
    v_batch:=documents_v1_adoption_batch_decode_v1(
        p_change_batch_bytes,p_batch_sha256,p_batch_bytes
    );
    v_asserted:=documents_v1_adoption_batch_assert_v1(
        v_batch,p_operation_id,p_run_id,p_scope_kind,p_scope_id,
        p_relation_ordinal,p_checkpoint_key,p_snapshot_name,
        p_snapshot_lsn,p_received_lsn,p_commit_lsn,p_final_lsn,
        p_source_xid,p_batch_ordinal,p_checkpoint_state,p_last_key
    );
    IF NOT v_asserted THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='Documents V1 adoption batch assertion failed';
    END IF;
    SELECT prepared.procedure_contract_id,prepared.procedure_oid,
        prepared.procedure_signature,prepared.already_applied,
        prepared.applied_count,prepared.key_state_sha256,prepared.state_sha256
    INTO STRICT v_contract_id,v_procedure_oid,v_procedure_signature,
        v_already_applied,v_applied_count,v_key_sha,v_state_sha
    FROM platform.cutover_prepare_batch_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,
        p_relation_ordinal,p_checkpoint_key,p_batch_ordinal,
        p_commit_lsn,p_source_xid,p_batch_sha256,p_lease_manifest_sha256
    ) AS prepared;
    v_expected_signature:=pg_catalog.format(
        '%I.documents_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)',
        pg_catalog.current_schema()
    );
    IF v_contract_id IS DISTINCT FROM 'documents.v1_adoption.v1' OR
       v_procedure_oid IS DISTINCT FROM
           'documents_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure_signature IS DISTINCT FROM v_expected_signature THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 adoption procedure binding differs';
    END IF;
    IF v_already_applied THEN
        RETURN QUERY SELECT v_applied_count,v_key_sha,v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count,result.key_state_sha256,result.state_sha256
    INTO STRICT v_applied_count,v_key_sha,v_state_sha
    FROM documents_v1_adoption_apply_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,
        p_relation_ordinal,p_checkpoint_key,p_snapshot_lsn,p_received_lsn,
        p_commit_lsn,p_source_xid,p_batch_ordinal,v_batch,p_batch_sha256
    ) AS result;
    IF v_applied_count<0 OR v_key_sha!~'^[0-9a-f]{64}$' OR
       v_state_sha!~'^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='Documents V1 adoption owner result is invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id,p_run_id,p_relation_ordinal,p_checkpoint_key,
        p_snapshot_name,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
        p_final_lsn,p_source_xid,p_batch_ordinal,p_checkpoint_state,
        p_last_key,p_batch_sha256,p_batch_bytes,v_applied_count,
        v_key_sha,v_state_sha
    );
    IF p_checkpoint_state='complete' AND EXISTS (
        SELECT 1 FROM platform.cutover_operations AS operation
        WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
          AND operation.state='quiescing'
    ) AND NOT EXISTS (
        SELECT 1
        FROM platform.cutover_operation_checkpoint_keys AS expected
        LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint
          ON checkpoint.operation_id=expected.operation_id
         AND checkpoint.run_id=expected.run_id
         AND checkpoint.relation_ordinal=expected.relation_ordinal
         AND checkpoint.checkpoint_key=expected.checkpoint_key
         AND checkpoint.state='complete'
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
          AND checkpoint.operation_id IS NULL
    ) THEN
        SELECT receipt.row_root_sha256 INTO v_projected_sha
        FROM documents_v1_cutover_receipts AS receipt
        WHERE receipt.operation_id=p_operation_id
          AND receipt.cutover_run_id=p_run_id;
        IF NOT FOUND THEN
            v_projected_sha:=documents_v1_adoption_accept_v1(
                p_operation_id,p_run_id,p_scope_id
            );
        END IF;
        IF v_projected_sha IS DISTINCT FROM v_state_sha THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Documents V1 adoption projected digest differs';
        END IF;
    END IF;
    RETURN QUERY SELECT v_applied_count,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_change jsonb;
    v_payload jsonb;
    v_stage documents_v1_adoption_stage%ROWTYPE;
    v_manifest text;
    v_rows bigint;
    v_applied bigint;
    v_key_sha text;
    v_state_sha text;
    v_operation_state text;
    v_now timestamptz;
BEGIN
    v_applied:=0;
    v_now:=pg_catalog.transaction_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind IS DISTINCT FROM 'tenant' OR
       p_checkpoint_key NOT IN ('folder','item','version','inventory') OR
       p_batch_sha256!~'^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 adoption apply principal denied';
    END IF;
    SELECT operation.lease_manifest_sha256,operation.state
    INTO STRICT v_manifest,v_operation_state
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind=p_scope_kind AND operation.scope_id=p_scope_id
      AND operation.group_id='documents' AND operation.domain='documents'
      AND operation.state IN ('copying','shadow','quiescing')
    FOR SHARE;
    FOR v_change IN
        SELECT value FROM pg_catalog.jsonb_array_elements(p_change_batch->'changes')
            WITH ORDINALITY AS item(value,position) ORDER BY position
    LOOP
        v_payload:=CASE v_change->>'kind'
            WHEN 'delete' THEN v_change->'before' ELSE v_change->'after'
        END;
        INSERT INTO documents_v1_adoption_stage (
            operation_id,cutover_run_id,source_kind,source_identity,source_sha256,
            target_kind,target_identity,target_id,target_sha256,target_record,
            removed,source_xid,commit_lsn,batch_ordinal,change_ordinal,recorded_at
        ) VALUES (
            p_operation_id,p_run_id,v_payload->>'source_kind',
            v_payload->>'source_identity',
            pg_catalog.decode(v_payload->>'source_sha256','hex'),
            v_payload->>'target_kind',v_payload->>'target_identity',
            (v_payload->>'target_id')::uuid,
            pg_catalog.sha256(pg_catalog.convert_to(
                (v_payload->'target_record')::text,'UTF8'
            )),v_payload->'target_record',v_change->>'kind'='delete',
            p_source_xid,p_commit_lsn,p_batch_ordinal,
            (v_change->>'ordinal')::integer,v_now
        )
        ON CONFLICT (operation_id,cutover_run_id,target_kind,target_identity)
        DO UPDATE SET source_kind=EXCLUDED.source_kind,
            source_identity=EXCLUDED.source_identity,
            source_sha256=EXCLUDED.source_sha256,target_id=EXCLUDED.target_id,
            target_sha256=EXCLUDED.target_sha256,target_record=EXCLUDED.target_record,
            removed=EXCLUDED.removed,source_xid=EXCLUDED.source_xid,
            commit_lsn=EXCLUDED.commit_lsn,batch_ordinal=EXCLUDED.batch_ordinal,
            change_ordinal=EXCLUDED.change_ordinal,recorded_at=EXCLUDED.recorded_at
        WHERE (documents_v1_adoption_stage.batch_ordinal,
               documents_v1_adoption_stage.change_ordinal)
            < (EXCLUDED.batch_ordinal,EXCLUDED.change_ordinal);
        GET DIAGNOSTICS v_rows=ROW_COUNT;
        IF v_rows IS DISTINCT FROM 1::bigint THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Documents V1 adoption target checkpoint regressed';
        END IF;
        v_applied:=v_applied+1;
        INSERT INTO platform.applied_change_receipts (
            receipt_id,operation_id,run_id,manifest_sha256,source_xid,
            source_commit_lsn,relation_ordinal,change_ordinal,checkpoint_key,
            mutation_kind,mutation_sha256,applied_at
        ) VALUES (
            pg_catalog.gen_random_uuid(),p_operation_id,p_run_id,v_manifest,
            p_source_xid,p_commit_lsn,p_relation_ordinal,
            (((p_batch_ordinal-1)::bigint*1000)+v_applied)::integer,
            p_checkpoint_key,v_change->>'kind',
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                p_batch_sha256||':'||v_change::text,'UTF8'
            )),'hex'),v_now
        );
    END LOOP;
    IF EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id AND stage.cutover_run_id=p_run_id
          AND NOT stage.removed GROUP BY stage.source_kind,stage.source_identity
        HAVING pg_catalog.count(DISTINCT stage.source_sha256)<>1
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 adoption source digest differs';
    END IF;
    IF v_operation_state IN ('copying','shadow') THEN
        FOR v_stage IN
            SELECT stage.* FROM documents_v1_adoption_stage AS stage
            WHERE stage.operation_id=p_operation_id
              AND stage.cutover_run_id=p_run_id
              AND stage.target_kind='inventory' AND NOT stage.removed
            ORDER BY stage.target_identity
        LOOP
            PERFORM documents_v1_adoption_project_inventory_v1(
                p_operation_id,p_run_id,p_scope_id,v_stage.target_record
            );
        END LOOP;
        FOR v_stage IN
            SELECT stage.* FROM documents_v1_adoption_stage AS stage
            WHERE stage.operation_id=p_operation_id
              AND stage.cutover_run_id=p_run_id
              AND stage.target_kind='checkpoint' AND NOT stage.removed
            ORDER BY stage.target_identity
        LOOP
            PERFORM documents_v1_adoption_project_checkpoint_v1(
                p_operation_id,p_run_id,p_scope_id,v_stage.target_record
            );
        END LOOP;
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(stage.target_kind||':'||stage.target_identity||
            ':'||pg_catalog.encode(stage.target_sha256,'hex'),',' ORDER BY
            stage.target_kind,stage.target_identity),''),'UTF8'
    )),'hex') INTO v_key_sha
    FROM documents_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.cutover_run_id=p_run_id
      AND NOT stage.removed;
    v_state_sha:=v_key_sha;
    RETURN QUERY SELECT v_applied,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_batch_assert_v1(jsonb, uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count integer;
BEGIN
    v_count:=pg_catalog.jsonb_array_length(p_batch->'changes');
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 adoption evidence principal denied';
    END IF;
    IF p_scope_kind IS DISTINCT FROM 'tenant' OR p_scope_id IS NULL OR
       p_relation_ordinal NOT BETWEEN 1 AND 32767 OR
       p_checkpoint_key NOT IN ('folder','item','version','inventory') OR
       p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_checkpoint_state NOT IN ('initial_copy','delta','complete') OR
       (p_checkpoint_state='complete') IS DISTINCT FROM (p_final_lsn IS NOT NULL) OR
       (v_count=0 AND (
           p_checkpoint_state<>'complete' OR p_final_lsn IS DISTINCT FROM p_commit_lsn
       )) OR NOT EXISTS (
           SELECT 1 FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.tenant_id=p_scope_id
             AND identity.schema_name=pg_catalog.current_schema()
             AND identity.origin='v1_adopted'
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_operations AS operation
           WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
             AND operation.scope_kind=p_scope_kind AND operation.scope_id=p_scope_id
             AND operation.group_id='documents' AND operation.domain='documents'
             AND operation.state IN ('copying','shadow','quiescing')
             AND (operation.state<>'quiescing' OR
                  (p_checkpoint_state='complete' AND v_count=0))
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS expected
           WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
             AND expected.relation_ordinal=p_relation_ordinal
             AND expected.checkpoint_key=p_checkpoint_key
       ) OR (p_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (p_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       p_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (p_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       (p_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal OR
       p_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key OR
       p_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state OR
       p_batch->'last_key' IS DISTINCT FROM p_last_key OR
       p_batch->'source_position'->>'snapshot_name' IS DISTINCT FROM p_snapshot_name OR
       (p_batch->'source_position'->>'snapshot_lsn')::pg_lsn
           IS DISTINCT FROM p_snapshot_lsn OR
       (p_batch->'source_position'->>'received_lsn')::pg_lsn
           IS DISTINCT FROM p_received_lsn OR
       (p_batch->'source_position'->>'commit_lsn')::pg_lsn
           IS DISTINCT FROM p_commit_lsn OR
       (p_batch->'source_position'->>'final_lsn')::pg_lsn
           IS DISTINCT FROM p_final_lsn OR
       (p_batch->'source_position'->>'source_xid')::xid8 IS DISTINCT FROM p_source_xid OR
       (p_batch->'source_position'->>'batch_ordinal')::integer
           IS DISTINCT FROM p_batch_ordinal OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change
           WHERE COALESCE(change->'after'->>'source_kind',
                          change->'before'->>'source_kind')<>p_checkpoint_key
       ) OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change
           GROUP BY COALESCE(change->'after'->>'source_identity',
                             change->'before'->>'source_identity')
           HAVING pg_catalog.count(DISTINCT COALESCE(
               change->'after'->>'source_sha256',change->'before'->>'source_sha256'
           ))<>1
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Documents V1 adoption batch evidence differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_batch_decode_v1(bytea, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_actual_bytes bigint;
    v_change_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 adoption batch principal denied';
    END IF;
    v_actual_bytes:=pg_catalog.octet_length(p_change_batch_bytes);
    IF p_batch_bytes IS DISTINCT FROM v_actual_bytes OR
       v_actual_bytes NOT BETWEEN 2 AND 8388608 OR
       p_batch_sha256!~'^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes),'hex')
           IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Documents V1 adoption batch digest is invalid';
    END IF;
    v_batch:=pg_catalog.convert_from(p_change_batch_bytes,'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_batch) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch) AS key) IS DISTINCT FROM ARRAY[
           'changes','checkpoint_key','checkpoint_state','last_key',
           'operation_id','relation_ordinal','run_id','scope_id',
           'scope_kind','source_position'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'source_position') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch->'source_position') AS key)
       IS DISTINCT FROM ARRAY[
           'batch_ordinal','commit_lsn','final_lsn','received_lsn',
           'snapshot_lsn','snapshot_name','source_xid'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'changes') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_batch->'changes')>1000 OR
       pg_catalog.jsonb_typeof(v_batch->'last_key') NOT IN ('object','null') OR
       v_batch->'last_key'='{}'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Documents V1 adoption batch envelope is invalid';
    END IF;
    v_change_count:=pg_catalog.jsonb_array_length(v_batch->'changes');
    IF (SELECT pg_catalog.count(DISTINCT change.value->'key')
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes') AS change(value))
       IS DISTINCT FROM v_change_count::bigint OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes')
             WITH ORDINALITY AS change(value,position)
        WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.array_agg(key ORDER BY key)
               FROM pg_catalog.jsonb_object_keys(change.value) AS key)
              IS DISTINCT FROM ARRAY['after','before','key','kind','ordinal']::text[]
           OR (change.value->>'ordinal')::integer IS DISTINCT FROM change.position::integer
           OR change.value->>'kind' NOT IN ('insert','update','delete')
           OR (change.value->>'kind'='insert' AND (
                  change.value->'before'<>'null'::jsonb OR
                  NOT documents_v1_adoption_value_valid_v1(
                      change.value->'key',change.value->'after'
                  )))
           OR (change.value->>'kind'='update' AND (
                  NOT documents_v1_adoption_value_valid_v1(
                      change.value->'key',change.value->'before'
                  ) OR NOT documents_v1_adoption_value_valid_v1(
                      change.value->'key',change.value->'after'
                  )))
           OR (change.value->>'kind'='delete' AND (
                  change.value->'after'<>'null'::jsonb OR
                  NOT documents_v1_adoption_value_valid_v1(
                      change.value->'key',change.value->'before'
                  )))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Documents V1 adoption batch change is invalid';
    END IF;
    RETURN v_batch;
END;
$_$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_mapping_ready_v1(uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_mapping_ready_v1(p_operation_id uuid, p_cutover_run_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_adoption_run_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 mapping principal denied';
    END IF;
    SELECT (stage.target_record->>'adoption_run_id')::uuid
    INTO STRICT v_adoption_run_id
    FROM documents_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id
      AND stage.cutover_run_id=p_cutover_run_id
      AND stage.target_kind='inventory' AND NOT stage.removed;
    IF (SELECT pg_catalog.count(*) FROM documents_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id
          AND stage.cutover_run_id=p_cutover_run_id
          AND stage.target_kind='inventory' AND NOT stage.removed)<>1 OR EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id
          AND stage.cutover_run_id=p_cutover_run_id AND NOT stage.removed
        GROUP BY stage.source_kind,stage.source_identity
        HAVING (stage.source_kind IN ('folder','item','inventory') AND
                (pg_catalog.count(*)<>1 OR
                 pg_catalog.count(DISTINCT stage.target_kind)<>1)) OR
               (stage.source_kind='version' AND
                (pg_catalog.count(*)<>2 OR
                 pg_catalog.count(DISTINCT stage.target_kind)<>2 OR
                 pg_catalog.count(DISTINCT stage.target_id)<>1))
    ) OR EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id
          AND stage.cutover_run_id=p_cutover_run_id AND NOT stage.removed
          AND stage.source_kind='version'
        GROUP BY stage.source_identity
        HAVING pg_catalog.bool_or(stage.target_kind='version') IS DISTINCT FROM true OR
               pg_catalog.bool_or(stage.target_kind='checkpoint') IS DISTINCT FROM true
    ) OR EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS folder
        WHERE folder.operation_id=p_operation_id
          AND folder.cutover_run_id=p_cutover_run_id
          AND folder.target_kind='folder' AND NOT folder.removed
          AND folder.target_record->>'parent_id' IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM documents_v1_adoption_stage AS parent
              WHERE parent.operation_id=folder.operation_id
                AND parent.cutover_run_id=folder.cutover_run_id
                AND parent.target_kind='folder' AND NOT parent.removed
                AND parent.target_id=(folder.target_record->>'parent_id')::uuid
          )
    ) OR EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS item
        WHERE item.operation_id=p_operation_id
          AND item.cutover_run_id=p_cutover_run_id
          AND item.target_kind='item' AND NOT item.removed
          AND NOT EXISTS (
              SELECT 1 FROM documents_v1_adoption_stage AS folder
              WHERE folder.operation_id=item.operation_id
                AND folder.cutover_run_id=item.cutover_run_id
                AND folder.target_kind='folder' AND NOT folder.removed
                AND folder.target_id=(item.target_record->>'folder_id')::uuid
          )
    ) OR EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS version
        WHERE version.operation_id=p_operation_id
          AND version.cutover_run_id=p_cutover_run_id
          AND version.target_kind='version' AND NOT version.removed
          AND NOT EXISTS (
              SELECT 1 FROM documents_v1_adoption_stage AS item
              WHERE item.operation_id=version.operation_id
                AND item.cutover_run_id=version.cutover_run_id
                AND item.target_kind='item' AND NOT item.removed
                AND item.target_id=(version.target_record->>'item_id')::uuid
          )
    ) OR EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS item
        WHERE item.operation_id=p_operation_id
          AND item.cutover_run_id=p_cutover_run_id
          AND item.target_kind='item' AND NOT item.removed
          AND item.target_record->>'current_version_id' IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM documents_v1_adoption_stage AS version
              WHERE version.operation_id=item.operation_id
                AND version.cutover_run_id=item.cutover_run_id
                AND version.target_kind='version' AND NOT version.removed
                AND version.target_id=(item.target_record->>'current_version_id')::uuid
                AND (version.target_record->>'item_id')::uuid=item.target_id
          )
    ) OR EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS checkpoint
        WHERE checkpoint.operation_id=p_operation_id
          AND checkpoint.cutover_run_id=p_cutover_run_id
          AND checkpoint.target_kind='checkpoint' AND NOT checkpoint.removed
          AND (checkpoint.target_record->>'adoption_run_id')::uuid
              IS DISTINCT FROM v_adoption_run_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 source-target mapping is incomplete';
    END IF;
    RETURN v_adoption_run_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_mapping_ready_v1(p_operation_id uuid, p_cutover_run_id uuid) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_project_checkpoint_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_project_checkpoint_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid, p_record jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_adoption_run_id uuid;
    v_source_version_id uuid;
    v_target_version_id uuid;
    v_job_id uuid;
    v_enqueued_at timestamptz;
    v_source_sha bytea;
    v_metadata_sha bytea;
    v_persisted_job uuid;
BEGIN
    v_adoption_run_id:=(p_record->>'adoption_run_id')::uuid;
    v_source_version_id:=(p_record->>'source_version_id')::uuid;
    v_target_version_id:=(p_record->>'target_version_id')::uuid;
    v_job_id:=(p_record->>'job_id')::uuid;
    v_enqueued_at:=(p_record->>'enqueued_at')::timestamptz;
    v_source_sha:=pg_catalog.decode(p_record->>'source_sha256','hex');
    v_metadata_sha:=pg_catalog.decode(p_record->>'source_metadata_sha256','hex');
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 checkpoint projection principal denied';
    END IF;
    PERFORM 1 FROM documents_adoption_runs AS run
    JOIN platform.cutover_operations AS operation
      ON operation.operation_id=p_operation_id
     AND operation.run_id=p_cutover_run_id
     AND operation.cutover_generation=run.cutover_generation
     AND operation.lease_manifest_sha256=pg_catalog.encode(run.manifest_sha256,'hex')
    WHERE run.run_id=v_adoption_run_id
      AND run.lifecycle_state IN ('INVENTORY','COPYING','SHADOW')
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='documents' AND operation.domain='documents'
      AND operation.state IN ('copying','shadow')
      AND operation.lease_expires_at>pg_catalog.clock_timestamp()
    FOR SHARE OF run,operation;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id
          AND stage.cutover_run_id=p_cutover_run_id
          AND stage.target_kind='version' AND stage.target_id=v_target_version_id
          AND NOT stage.removed
          AND (stage.target_record->>'item_id')::uuid=
              (p_record->>'target_document_id')::uuid
          AND stage.source_kind='version'
          AND stage.source_identity=(SELECT source.source_identity
              FROM documents_v1_adoption_stage AS source
              WHERE source.operation_id=p_operation_id
                AND source.cutover_run_id=p_cutover_run_id
                AND source.target_kind='checkpoint'
                AND source.target_id=v_target_version_id AND NOT source.removed)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 checkpoint mapping differs';
    END IF;
    INSERT INTO documents_blob_copy_checkpoints (
        run_id,source_document_id,source_version_id,source_object_key,
        source_object_revision,source_bytes,source_sha256,source_metadata_sha256,
        source_lsn,target_document_id,target_version_id,lifecycle_state,updated_at
    ) VALUES (
        v_adoption_run_id,(p_record->>'source_document_id')::uuid,
        v_source_version_id,p_record->>'source_object_key',
        p_record->>'source_object_revision',(p_record->>'source_bytes')::bigint,
        v_source_sha,v_metadata_sha,(p_record->>'source_lsn')::pg_lsn,
        (p_record->>'target_document_id')::uuid,v_target_version_id,
        'INVENTORIED',v_enqueued_at
    ) ON CONFLICT (run_id,source_version_id,source_object_revision) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM documents_blob_copy_checkpoints AS checkpoint
        WHERE checkpoint.run_id=v_adoption_run_id
          AND checkpoint.source_document_id=(p_record->>'source_document_id')::uuid
          AND checkpoint.source_version_id=v_source_version_id
          AND checkpoint.source_object_key=p_record->>'source_object_key'
          AND checkpoint.source_object_revision=p_record->>'source_object_revision'
          AND checkpoint.source_bytes=(p_record->>'source_bytes')::bigint
          AND checkpoint.source_sha256=v_source_sha
          AND checkpoint.source_metadata_sha256=v_metadata_sha
          AND checkpoint.source_lsn=(p_record->>'source_lsn')::pg_lsn
          AND checkpoint.target_document_id=(p_record->>'target_document_id')::uuid
          AND checkpoint.target_version_id=v_target_version_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 checkpoint replay differs';
    END IF;
    v_persisted_job:=platform.platform_async_enqueue_documents_cutover_copy_v1(
        p_operation_id,p_cutover_run_id,v_adoption_run_id,v_source_version_id,
        v_job_id,v_enqueued_at
    );
    IF v_persisted_job IS DISTINCT FROM v_job_id THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 checkpoint job identity differs';
    END IF;
    UPDATE documents_adoption_runs AS run SET
        source_count=stats.source_count,
        source_plaintext_bytes=stats.source_bytes,
        pending_object_count=stats.pending_objects,
        pending_job_count=stats.pending_jobs,
        updated_at=pg_catalog.transaction_timestamp()
    FROM (
        SELECT pg_catalog.count(*)::bigint AS source_count,
            COALESCE(pg_catalog.sum(checkpoint.source_bytes),0)::bigint AS source_bytes,
            pg_catalog.count(*) FILTER (WHERE checkpoint.lifecycle_state<>'VERIFIED')
                ::bigint AS pending_objects,
            pg_catalog.count(*) FILTER (WHERE job.state<>'succeeded')
                ::bigint AS pending_jobs
        FROM documents_blob_copy_checkpoints AS checkpoint
        JOIN platform.cutover_job_bindings AS binding
          ON binding.adoption_run_id=checkpoint.run_id
         AND binding.source_version_id=checkpoint.source_version_id
        JOIN platform.jobs AS job ON job.id=binding.job_id
        WHERE checkpoint.run_id=v_adoption_run_id
    ) AS stats WHERE run.run_id=v_adoption_run_id;
    RETURN v_job_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_project_checkpoint_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_project_folder_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_project_folder_v1(p_record jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_row documents_folders%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 folder projection principal denied';
    END IF;
    SELECT * INTO STRICT v_row
    FROM pg_catalog.jsonb_populate_record(NULL::documents_folders,p_record);
    INSERT INTO documents_folders (
        id,parent_id,owner_id,display_name,lifecycle_state,row_version,
        created_at,updated_at,trashed_at
    ) VALUES (
        v_row.id,v_row.parent_id,v_row.owner_id,v_row.display_name,
        v_row.lifecycle_state,v_row.row_version,v_row.created_at,
        v_row.updated_at,v_row.trashed_at
    ) ON CONFLICT (id) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM documents_folders AS target
        WHERE target.id=v_row.id AND pg_catalog.to_jsonb(target)=p_record
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 folder projection differs';
    END IF;
    RETURN v_row.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_project_folder_v1(p_record jsonb) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_project_inventory_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_project_inventory_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid, p_record jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_adoption_run_id uuid;
    v_generation bigint;
    v_manifest text;
    v_created_at timestamptz;
BEGIN
    v_adoption_run_id:=(p_record->>'adoption_run_id')::uuid;
    v_created_at:=(p_record->>'created_at')::timestamptz;
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 inventory projection principal denied';
    END IF;
    SELECT operation.cutover_generation,operation.lease_manifest_sha256
    INTO STRICT v_generation,v_manifest
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id
      AND operation.run_id=p_cutover_run_id
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='documents' AND operation.domain='documents'
      AND operation.state IN ('copying','shadow')
      AND operation.lease_expires_at>pg_catalog.clock_timestamp()
    FOR SHARE;
    IF (p_record->>'cutover_generation')::bigint IS DISTINCT FROM v_generation OR
       p_record->>'manifest_sha256' IS DISTINCT FROM v_manifest OR
       p_record->>'transform_version' IS DISTINCT FROM 'documents_adoption_v1' OR
       v_created_at>pg_catalog.transaction_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 inventory authority differs';
    END IF;
    INSERT INTO documents_adoption_runs (
        run_id,cutover_generation,manifest_sha256,transform_version,
        lifecycle_state,source_count,target_count,source_plaintext_bytes,
        target_plaintext_bytes,pending_object_count,pending_job_count,
        created_at,updated_at
    ) VALUES (
        v_adoption_run_id,v_generation,pg_catalog.decode(v_manifest,'hex'),
        'documents_adoption_v1','INVENTORY',0,0,0,0,0,0,
        v_created_at,v_created_at
    ) ON CONFLICT (run_id) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM documents_adoption_runs AS run
        WHERE run.run_id=v_adoption_run_id
          AND run.cutover_generation=v_generation
          AND run.manifest_sha256=pg_catalog.decode(v_manifest,'hex')
          AND run.transform_version='documents_adoption_v1'
          AND run.created_at=v_created_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 inventory replay differs';
    END IF;
    RETURN v_adoption_run_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_project_inventory_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_project_item_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_project_item_v1(p_record jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_row documents_items%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 item projection principal denied';
    END IF;
    SELECT * INTO STRICT v_row
    FROM pg_catalog.jsonb_populate_record(NULL::documents_items,p_record);
    INSERT INTO documents_items (
        id,folder_id,owner_id,current_version_id,lifecycle_state,resume_state,
        row_version,trashed_at,retention_ends_at,purge_requested_at,
        purge_starts_at,purge_reason,purged_at,tombstone_until,
        purge_evidence_sha256,created_at,updated_at,description,tags
    ) VALUES (
        v_row.id,v_row.folder_id,v_row.owner_id,v_row.current_version_id,
        v_row.lifecycle_state,v_row.resume_state,v_row.row_version,v_row.trashed_at,
        v_row.retention_ends_at,v_row.purge_requested_at,v_row.purge_starts_at,
        v_row.purge_reason,v_row.purged_at,v_row.tombstone_until,
        v_row.purge_evidence_sha256,v_row.created_at,v_row.updated_at,
        v_row.description,v_row.tags
    ) ON CONFLICT (id) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM documents_items AS target
        WHERE target.id=v_row.id AND pg_catalog.to_jsonb(target)=p_record
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 item projection differs';
    END IF;
    RETURN v_row.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_project_item_v1(p_record jsonb) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_project_rows_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_project_rows_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_stage documents_v1_adoption_stage%ROWTYPE;
    v_adoption_run_id uuid;
    v_final_lsn pg_lsn;
    v_binding_root text;
    v_effect_root text;
    v_row_root text;
    v_folder_count bigint;
    v_item_count bigint;
    v_version_count bigint;
BEGIN
    SELECT ready.adoption_run_id,ready.final_lsn,
        ready.binding_root_sha256,ready.effect_root_sha256
    INTO STRICT v_adoption_run_id,v_final_lsn,v_binding_root,v_effect_root
    FROM documents_v1_adoption_projection_ready_v1(
        p_operation_id,p_cutover_run_id,p_scope_id
    ) AS ready;
    SET CONSTRAINTS ALL DEFERRED;
    FOR v_stage IN
        WITH RECURSIVE folder_tree AS (
            SELECT stage.*,0 AS depth
            FROM documents_v1_adoption_stage AS stage
            WHERE stage.operation_id=p_operation_id
              AND stage.cutover_run_id=p_cutover_run_id
              AND stage.target_kind='folder' AND NOT stage.removed
              AND stage.target_record->>'parent_id' IS NULL
            UNION ALL
            SELECT child.*,parent.depth+1
            FROM documents_v1_adoption_stage AS child
            JOIN folder_tree AS parent
              ON (child.target_record->>'parent_id')::uuid=parent.target_id
            WHERE child.operation_id=p_operation_id
              AND child.cutover_run_id=p_cutover_run_id
              AND child.target_kind='folder' AND NOT child.removed
              AND parent.depth<1024
        )
        SELECT tree.* FROM folder_tree AS tree
        ORDER BY tree.depth,tree.target_id
    LOOP
        PERFORM documents_v1_adoption_project_folder_v1(v_stage.target_record);
    END LOOP;
    FOR v_stage IN
        SELECT stage.* FROM documents_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id
          AND stage.cutover_run_id=p_cutover_run_id
          AND stage.target_kind='item' AND NOT stage.removed
        ORDER BY stage.target_id
    LOOP
        PERFORM documents_v1_adoption_project_item_v1(v_stage.target_record);
    END LOOP;
    FOR v_stage IN
        SELECT stage.* FROM documents_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id
          AND stage.cutover_run_id=p_cutover_run_id
          AND stage.target_kind='version' AND NOT stage.removed
        ORDER BY stage.target_id
    LOOP
        PERFORM documents_v1_adoption_project_version_v1(
            v_adoption_run_id,v_stage.target_record
        );
    END LOOP;
    SELECT pg_catalog.count(*) INTO v_folder_count
    FROM documents_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id
      AND stage.cutover_run_id=p_cutover_run_id
      AND stage.target_kind='folder' AND NOT stage.removed;
    SELECT pg_catalog.count(*) INTO v_item_count
    FROM documents_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id
      AND stage.cutover_run_id=p_cutover_run_id
      AND stage.target_kind='item' AND NOT stage.removed;
    SELECT pg_catalog.count(*) INTO v_version_count
    FROM documents_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id
      AND stage.cutover_run_id=p_cutover_run_id
      AND stage.target_kind='version' AND NOT stage.removed;
    IF (SELECT pg_catalog.count(*) FROM documents_folders)<>v_folder_count OR
       (SELECT pg_catalog.count(*) FROM documents_items)<>v_item_count OR
       (SELECT pg_catalog.count(*) FROM documents_versions)<>v_version_count OR
       EXISTS (
           SELECT 1 FROM documents_v1_adoption_stage AS stage
           WHERE stage.operation_id=p_operation_id
             AND stage.cutover_run_id=p_cutover_run_id
             AND stage.target_kind IN ('folder','item') AND NOT stage.removed
             AND NOT CASE stage.target_kind
                 WHEN 'folder' THEN EXISTS (
                     SELECT 1 FROM documents_folders AS target
                     WHERE target.id=stage.target_id
                       AND pg_catalog.to_jsonb(target)=stage.target_record
                 )
                 WHEN 'item' THEN EXISTS (
                     SELECT 1 FROM documents_items AS target
                     WHERE target.id=stage.target_id
                       AND pg_catalog.to_jsonb(target)=stage.target_record
                 )
             END
       ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 projected rows differ';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(stage.target_kind||':'||stage.target_identity||
            ':'||pg_catalog.encode(stage.target_sha256,'hex'),',' ORDER BY
            stage.target_kind,stage.target_identity),''),'UTF8'
    )),'hex') INTO v_row_root
    FROM documents_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id
      AND stage.cutover_run_id=p_cutover_run_id AND NOT stage.removed;
    RETURN v_row_root;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_project_rows_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_project_version_v1(uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_project_version_v1(p_adoption_run_id uuid, p_record jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_checkpoint documents_blob_copy_checkpoints%ROWTYPE;
    v_id uuid;
    v_plaintext_sha bytea;
    v_logical jsonb;
BEGIN
    v_id:=(p_record->>'id')::uuid;
    v_plaintext_sha:=pg_catalog.decode(
        pg_catalog.substr(p_record->>'plaintext_sha256',3),'hex'
    );
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 version projection principal denied';
    END IF;
    SELECT checkpoint.* INTO STRICT v_checkpoint
    FROM documents_blob_copy_checkpoints AS checkpoint
    WHERE checkpoint.run_id=p_adoption_run_id
      AND checkpoint.target_version_id=v_id
      AND checkpoint.lifecycle_state='VERIFIED'
    FOR SHARE;
    IF v_checkpoint.source_bytes IS DISTINCT FROM
           (p_record->>'plaintext_bytes')::bigint OR
       v_checkpoint.source_sha256 IS DISTINCT FROM v_plaintext_sha OR
       v_checkpoint.target_plaintext_sha256 IS DISTINCT FROM v_plaintext_sha OR
       v_checkpoint.metadata_sha256 IS DISTINCT FROM
           v_checkpoint.source_metadata_sha256 OR
       v_checkpoint.applied_lsn IS DISTINCT FROM v_checkpoint.source_lsn THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 verified copy differs from signed version';
    END IF;
    INSERT INTO documents_versions (
        id,item_id,version_number,lifecycle_state,original_name,declared_mime,
        detected_mime,file_kind,plaintext_bytes,ciphertext_bytes,
        plaintext_sha256,ciphertext_sha256,cipher_format,object_key,
        object_version,object_generation,key_id,wrapped_dek,
        scan_signature_revision,scanned_at,created_at
    ) VALUES (
        v_id,(p_record->>'item_id')::uuid,(p_record->>'version_number')::bigint,
        'READY',p_record->>'original_name',p_record->>'declared_mime',
        p_record->>'detected_mime',p_record->>'file_kind',
        (p_record->>'plaintext_bytes')::bigint,
        v_checkpoint.target_ciphertext_bytes,v_plaintext_sha,
        v_checkpoint.target_ciphertext_sha256,'FCDOC1',
        v_checkpoint.target_object_key,v_checkpoint.target_object_version,
        v_checkpoint.target_object_generation,v_checkpoint.target_key_id,
        v_checkpoint.target_wrapped_dek,p_record->>'scan_signature_revision',
        (p_record->>'scanned_at')::timestamptz,
        (p_record->>'created_at')::timestamptz
    ) ON CONFLICT (id) DO NOTHING;
    SELECT pg_catalog.jsonb_build_object(
        'id',target.id,'item_id',target.item_id,
        'version_number',target.version_number,
        'lifecycle_state',target.lifecycle_state,
        'original_name',target.original_name,'declared_mime',target.declared_mime,
        'detected_mime',target.detected_mime,'file_kind',target.file_kind,
        'plaintext_bytes',target.plaintext_bytes,
        'plaintext_sha256',target.plaintext_sha256,
        'scan_signature_revision',target.scan_signature_revision,
        'scanned_at',target.scanned_at,'created_at',target.created_at
    ) INTO v_logical
    FROM documents_versions AS target
    WHERE target.id=v_id AND target.ciphertext_bytes=v_checkpoint.target_ciphertext_bytes
      AND target.ciphertext_sha256=v_checkpoint.target_ciphertext_sha256
      AND target.object_key=v_checkpoint.target_object_key
      AND target.object_version=v_checkpoint.target_object_version
      AND target.object_generation=v_checkpoint.target_object_generation
      AND target.key_id=v_checkpoint.target_key_id
      AND target.wrapped_dek=v_checkpoint.target_wrapped_dek;
    IF v_logical IS DISTINCT FROM p_record THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 version projection differs';
    END IF;
    RETURN v_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_project_version_v1(p_adoption_run_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_projection_ready_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_projection_ready_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid) RETURNS TABLE(adoption_run_id uuid, final_lsn pg_lsn, binding_root_sha256 text, effect_root_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_expected bigint;
    v_complete bigint;
    v_final_count bigint;
    v_checkpoint_count bigint;
    v_adoption_run_id uuid;
    v_final_lsn pg_lsn;
    v_binding_root text;
    v_effect_root text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 projection principal denied';
    END IF;
    PERFORM 1 FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id
      AND operation.run_id=p_cutover_run_id
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='documents' AND operation.domain='documents'
      AND operation.state='quiescing'
      AND operation.lease_expires_at>pg_catalog.clock_timestamp()
    FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.tenant_id=p_scope_id
          AND identity.schema_name=pg_catalog.current_schema()
          AND identity.origin='v1_adopted'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 projection authority is not ready';
    END IF;
    v_adoption_run_id:=documents_v1_adoption_mapping_ready_v1(
        p_operation_id,p_cutover_run_id
    );
    SELECT pg_catalog.count(*) INTO v_expected
    FROM platform.cutover_operation_checkpoint_keys AS expected
    WHERE expected.operation_id=p_operation_id
      AND expected.run_id=p_cutover_run_id;
    SELECT pg_catalog.count(*),
        pg_catalog.count(DISTINCT checkpoint.final_lsn::text)
    INTO v_complete,v_final_count
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id
      AND checkpoint.run_id=p_cutover_run_id
      AND checkpoint.state='complete' AND checkpoint.final_lsn IS NOT NULL;
    IF v_expected<1 OR v_complete IS DISTINCT FROM v_expected OR
       v_final_count IS DISTINCT FROM 1::bigint OR EXISTS (
        SELECT 1
        FROM platform.cutover_operation_checkpoint_keys AS expected
        LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint
          ON checkpoint.operation_id=expected.operation_id
         AND checkpoint.run_id=expected.run_id
         AND checkpoint.relation_ordinal=expected.relation_ordinal
         AND checkpoint.checkpoint_key=expected.checkpoint_key
         AND checkpoint.state='complete'
        WHERE expected.operation_id=p_operation_id
          AND expected.run_id=p_cutover_run_id
          AND checkpoint.operation_id IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 logical checkpoints are incomplete';
    END IF;
    SELECT checkpoint.final_lsn INTO STRICT v_final_lsn
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id
      AND checkpoint.run_id=p_cutover_run_id
    ORDER BY checkpoint.relation_ordinal,checkpoint.checkpoint_key LIMIT 1;
    SELECT pg_catalog.count(*) INTO v_checkpoint_count
    FROM documents_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id
      AND stage.cutover_run_id=p_cutover_run_id
      AND stage.target_kind='checkpoint' AND NOT stage.removed;
    IF (SELECT pg_catalog.count(*) FROM documents_blob_copy_checkpoints
        WHERE run_id=v_adoption_run_id) IS DISTINCT FROM v_checkpoint_count OR
       EXISTS (
        SELECT 1 FROM documents_v1_adoption_stage AS stage
        LEFT JOIN documents_blob_copy_checkpoints AS checkpoint
          ON checkpoint.run_id=v_adoption_run_id
         AND checkpoint.source_version_id=
             (stage.target_record->>'source_version_id')::uuid
         AND checkpoint.source_object_revision=
             stage.target_record->>'source_object_revision'
         AND checkpoint.target_version_id=stage.target_id
         AND checkpoint.source_sha256=pg_catalog.decode(
             stage.target_record->>'source_sha256','hex')
         AND checkpoint.source_metadata_sha256=pg_catalog.decode(
             stage.target_record->>'source_metadata_sha256','hex')
         AND checkpoint.source_lsn=(stage.target_record->>'source_lsn')::pg_lsn
         AND checkpoint.lifecycle_state='VERIFIED'
         AND checkpoint.applied_lsn=checkpoint.source_lsn
         AND checkpoint.target_plaintext_sha256=checkpoint.source_sha256
         AND checkpoint.metadata_sha256=checkpoint.source_metadata_sha256
        WHERE stage.operation_id=p_operation_id
          AND stage.cutover_run_id=p_cutover_run_id
          AND stage.target_kind='checkpoint' AND NOT stage.removed
          AND checkpoint.run_id IS NULL
    ) OR EXISTS (
        SELECT 1 FROM documents_blob_copy_checkpoints AS checkpoint
        WHERE checkpoint.run_id=v_adoption_run_id
          AND (checkpoint.lifecycle_state<>'VERIFIED' OR
               checkpoint.applied_lsn IS NULL OR
               checkpoint.applied_lsn>v_final_lsn)
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 object checkpoints are incomplete';
    END IF;
    IF (SELECT pg_catalog.count(*) FROM platform.cutover_job_bindings AS binding
        WHERE binding.operation_id=p_operation_id
          AND binding.cutover_run_id=p_cutover_run_id)
       IS DISTINCT FROM v_checkpoint_count OR EXISTS (
        SELECT 1 FROM platform.cutover_job_bindings AS binding
        JOIN platform.jobs AS job ON job.id=binding.job_id
        WHERE binding.operation_id=p_operation_id
          AND binding.cutover_run_id=p_cutover_run_id
          AND (binding.tenant_id<>p_scope_id OR
               binding.adoption_run_id<>v_adoption_run_id OR
               binding.job_kind<>'documents.adoption.copy' OR
               job.state<>'succeeded' OR job.kind<>binding.job_kind OR
               NOT EXISTS (
                   SELECT 1 FROM platform.job_attempts AS attempt
                   JOIN platform.idempotency_receipts AS receipt
                     ON receipt.receipt_id=attempt.effect_receipt_id
                   WHERE attempt.job_id=job.id AND attempt.outcome='succeeded'
                     AND attempt.finished_at IS NOT NULL
                     AND receipt.causation_id=job.id
                     AND receipt.effect_kind='documents.adoption.copy'
                     AND receipt.provider='documents.adoption'
                     AND receipt.operation='copy'
                     AND receipt.effect_status='succeeded'
               ))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 shadow jobs or effects are pending';
    END IF;
    IF (SELECT (SELECT pg_catalog.count(*) FROM documents_folders)+
               (SELECT pg_catalog.count(*) FROM documents_items)+
               (SELECT pg_catalog.count(*) FROM documents_versions)+
               (SELECT pg_catalog.count(*) FROM documents_v1_cutover_receipts))<>0 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 inactive target is not empty';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
        pg_catalog.string_agg(binding.job_id::text||':'||binding.source_version_id::text||
            ':'||binding.payload_sha256,',' ORDER BY binding.job_id),''),'UTF8')),'hex')
    INTO v_binding_root FROM platform.cutover_job_bindings AS binding
    WHERE binding.operation_id=p_operation_id
      AND binding.cutover_run_id=p_cutover_run_id;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
        pg_catalog.string_agg(receipt.causation_id::text||':'||receipt.effect_id::text||
            ':'||receipt.effect_result_sha256,',' ORDER BY receipt.causation_id),''),
        'UTF8')),'hex') INTO v_effect_root
    FROM platform.idempotency_receipts AS receipt
    JOIN platform.cutover_job_bindings AS binding
      ON binding.job_id=receipt.causation_id
    WHERE binding.operation_id=p_operation_id
      AND binding.cutover_run_id=p_cutover_run_id
      AND receipt.effect_status='succeeded';
    RETURN QUERY SELECT v_adoption_run_id,v_final_lsn,v_binding_root,v_effect_root;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_projection_ready_v1(p_operation_id uuid, p_cutover_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_target_record_valid_v1(text, text, uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_target_record_valid_v1(p_target_kind text, p_target_identity text, p_target_id uuid, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_relation oid;
    v_expected jsonb;
    v_actual jsonb;
    v_folder documents_folders%ROWTYPE;
    v_item documents_items%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' OR
       p_record='{}'::jsonb OR pg_catalog.octet_length(p_record::text)>1048576 OR
       p_target_id='00000000-0000-0000-0000-000000000000'::uuid OR
       p_target_identity IS DISTINCT FROM p_target_kind||':'||p_target_id::text THEN
        RETURN false;
    END IF;
    v_relation:=CASE p_target_kind
        WHEN 'folder' THEN 'documents_folders'::regclass::oid
        WHEN 'item' THEN 'documents_items'::regclass::oid
        ELSE NULL
    END;
    IF v_relation IS NOT NULL THEN
        SELECT pg_catalog.jsonb_agg(
            attribute.attname::text ORDER BY attribute.attname::text COLLATE "C"
        )
        INTO v_expected FROM pg_catalog.pg_attribute AS attribute
        WHERE attribute.attrelid=v_relation AND attribute.attnum>0
          AND NOT attribute.attisdropped;
    ELSIF p_target_kind='version' THEN
        v_expected:=pg_catalog.to_jsonb(ARRAY[
            'created_at','declared_mime','detected_mime','file_kind','id','item_id',
            'lifecycle_state','original_name','plaintext_bytes','plaintext_sha256',
            'scan_signature_revision','scanned_at','version_number'
        ]::text[]);
    ELSIF p_target_kind='inventory' THEN
        v_expected:=pg_catalog.to_jsonb(ARRAY[
            'adoption_run_id','created_at','cutover_generation',
            'manifest_sha256','transform_version'
        ]::text[]);
    ELSIF p_target_kind='checkpoint' THEN
        v_expected:=pg_catalog.to_jsonb(ARRAY[
            'adoption_run_id','enqueued_at','job_id','source_bytes',
            'source_document_id','source_lsn','source_metadata_sha256',
            'source_object_key','source_object_revision','source_sha256',
            'source_version_id','target_document_id','target_version_id'
        ]::text[]);
    ELSE
        RETURN false;
    END IF;
    SELECT pg_catalog.jsonb_agg(key ORDER BY key COLLATE "C") INTO v_actual
    FROM pg_catalog.jsonb_object_keys(p_record) AS key;
    IF v_actual IS DISTINCT FROM v_expected THEN RETURN false; END IF;
    BEGIN
        CASE p_target_kind
            WHEN 'folder' THEN
                SELECT * INTO v_folder
                FROM pg_catalog.jsonb_populate_record(NULL::documents_folders,p_record);
                RETURN v_folder.id=p_target_id AND v_folder.row_version>0 AND
                    v_folder.lifecycle_state IN ('ACTIVE','TRASHED');
            WHEN 'item' THEN
                SELECT * INTO v_item
                FROM pg_catalog.jsonb_populate_record(NULL::documents_items,p_record);
                RETURN v_item.id=p_target_id AND v_item.row_version>0 AND
                    v_item.lifecycle_state IN ('ACTIVE','TRASHED','PURGE_COOLING');
            WHEN 'version' THEN
                RETURN (p_record->>'id')::uuid=p_target_id AND
                    (p_record->>'item_id')::uuid IS NOT NULL AND
                    p_record->>'lifecycle_state'='READY' AND
                    (p_record->>'version_number')::bigint>0 AND
                    (p_record->>'plaintext_bytes')::bigint BETWEEN 1 AND 104857600 AND
                    p_record->>'plaintext_sha256'~'^\\x[0-9a-f]{64}$' AND
                    pg_catalog.isfinite((p_record->>'created_at')::timestamptz) AND
                    pg_catalog.isfinite((p_record->>'scanned_at')::timestamptz);
            WHEN 'inventory' THEN
                RETURN (p_record->>'adoption_run_id')::uuid=p_target_id AND
                    pg_catalog.uuid_extract_version(p_target_id)=7 AND
                    (p_record->>'cutover_generation')::bigint>0 AND
                    p_record->>'manifest_sha256'~'^[0-9a-f]{64}$' AND
                    p_record->>'transform_version'='documents_adoption_v1' AND
                    pg_catalog.isfinite((p_record->>'created_at')::timestamptz);
            WHEN 'checkpoint' THEN
                RETURN (p_record->>'target_version_id')::uuid=p_target_id AND
                    pg_catalog.uuid_extract_version(
                        (p_record->>'adoption_run_id')::uuid)=7 AND
                    pg_catalog.uuid_extract_version((p_record->>'job_id')::uuid)=7 AND
                    pg_catalog.uuid_extract_version(
                        (p_record->>'source_version_id')::uuid)=7 AND
                    (p_record->>'source_bytes')::bigint BETWEEN 1 AND 104857600 AND
                    p_record->>'source_sha256'~'^[0-9a-f]{64}$' AND
                    p_record->>'source_metadata_sha256'~'^[0-9a-f]{64}$' AND
                    (p_record->>'source_lsn')::pg_lsn IS NOT NULL AND
                    pg_catalog.octet_length(p_record->>'source_object_key')
                        BETWEEN 1 AND 1024 AND
                    pg_catalog.octet_length(p_record->>'source_object_revision')
                        BETWEEN 1 AND 1024 AND
                    pg_catalog.isfinite((p_record->>'enqueued_at')::timestamptz);
        END CASE;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR
        datetime_field_overflow THEN
        RETURN false;
    END;
    RETURN false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_target_record_valid_v1(p_target_kind text, p_target_identity text, p_target_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: documents_v1_adoption_value_valid_v1(jsonb, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_adoption_value_valid_v1(p_key jsonb, p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_target_id uuid;
    v_source_kind text;
    v_target_kind text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.jsonb_typeof(p_key) IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(p_value) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_key) AS key) IS DISTINCT FROM ARRAY[
           'source_identity','source_kind','target_identity','target_kind'
       ]::text[] OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_value) AS key) IS DISTINCT FROM ARRAY[
           'source_identity','source_kind','source_sha256','target_id',
           'target_identity','target_kind','target_record'
       ]::text[] THEN
        RETURN false;
    END IF;
    IF p_value->>'source_identity' IS DISTINCT FROM p_key->>'source_identity' OR
       p_value->>'source_kind' IS DISTINCT FROM p_key->>'source_kind' OR
       p_value->>'target_identity' IS DISTINCT FROM p_key->>'target_identity' OR
       p_value->>'target_kind' IS DISTINCT FROM p_key->>'target_kind' OR
       pg_catalog.octet_length(p_value->>'source_identity') NOT BETWEEN 1 AND 1024 OR
       p_value->>'source_identity' OPERATOR(pg_catalog.~) '[[:cntrl:]]' OR
       pg_catalog.octet_length(p_value->>'target_identity') NOT BETWEEN 1 AND 1024 OR
       p_value->>'target_identity' OPERATOR(pg_catalog.~) '[[:cntrl:]]' OR
       p_value->>'source_sha256'!~'^[0-9a-f]{64}$' THEN
        RETURN false;
    END IF;
    v_source_kind:=p_value->>'source_kind';
    v_target_kind:=p_value->>'target_kind';
    IF NOT ((v_source_kind='folder' AND v_target_kind='folder') OR
            (v_source_kind='item' AND v_target_kind='item') OR
            (v_source_kind='version' AND v_target_kind IN ('version','checkpoint')) OR
            (v_source_kind='inventory' AND v_target_kind='inventory')) THEN
        RETURN false;
    END IF;
    BEGIN
        v_target_id:=(p_value->>'target_id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        RETURN false;
    END;
    RETURN documents_v1_adoption_target_record_valid_v1(
        v_target_kind,p_value->>'target_identity',v_target_id,
        p_value->'target_record'
    );
END;
$_$;


ALTER FUNCTION __tenant_schema__.documents_v1_adoption_value_valid_v1(p_key jsonb, p_value jsonb) OWNER TO harpy_owner;

