--
-- Name: documents_v1_reverse_accept_v1(uuid, uuid, bigint, bigint, bigint, bigint, bytea, bytea, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_reverse_accept_v1(p_reconciliation_id uuid, p_tenant_id uuid, p_source_generation bigint, p_target_generation bigint, p_source_count bigint, p_target_count bigint, p_source_sha256 bytea, p_target_sha256 bytea, p_requested_by uuid, p_approved_by uuid, p_accepted_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_receipt_sha text;
BEGIN
    v_receipt_sha:=documents_v1_reverse_evidence_v1(
        p_reconciliation_id,p_tenant_id,p_source_generation,p_target_generation,
        p_source_count,p_target_count,p_source_sha256,p_target_sha256,
        p_requested_by,p_approved_by,p_accepted_at
    );
    INSERT INTO documents_reverse_reconciliations (
        reconciliation_id,source_generation,target_generation,
        source_count,target_count,source_sha256,target_sha256,lifecycle_state,
        requested_by,approved_by,created_at,decided_at
    ) VALUES (
        p_reconciliation_id,p_source_generation,p_target_generation,
        p_source_count,p_target_count,p_source_sha256,p_target_sha256,'ACCEPTED',
        p_requested_by,p_approved_by,p_accepted_at,p_accepted_at
    ) ON CONFLICT (reconciliation_id) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM documents_reverse_reconciliations AS reconciliation
        WHERE reconciliation.reconciliation_id=p_reconciliation_id
          AND reconciliation.source_generation=p_source_generation
          AND reconciliation.target_generation=p_target_generation
          AND reconciliation.source_count=p_source_count
          AND reconciliation.target_count=p_target_count
          AND reconciliation.source_sha256=p_source_sha256
          AND reconciliation.target_sha256=p_target_sha256
          AND reconciliation.lifecycle_state='ACCEPTED'
          AND reconciliation.requested_by=p_requested_by
          AND reconciliation.approved_by=p_approved_by
          AND reconciliation.created_at=p_accepted_at
          AND reconciliation.decided_at=p_accepted_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 reverse reconciliation replay differs';
    END IF;
    INSERT INTO documents_v1_reverse_receipts (
        reconciliation_id,tenant_id,source_generation,target_generation,
        source_count,target_count,source_sha256,target_sha256,
        requested_by,approved_by,accepted_at,receipt_sha256
    ) VALUES (
        p_reconciliation_id,p_tenant_id,p_source_generation,p_target_generation,
        p_source_count,p_target_count,p_source_sha256,p_target_sha256,
        p_requested_by,p_approved_by,p_accepted_at,v_receipt_sha
    ) ON CONFLICT (reconciliation_id) DO NOTHING;
    IF NOT EXISTS (
        SELECT 1 FROM documents_v1_reverse_receipts AS receipt
        WHERE receipt.reconciliation_id=p_reconciliation_id
          AND receipt.tenant_id=p_tenant_id
          AND receipt.source_generation=p_source_generation
          AND receipt.target_generation=p_target_generation
          AND receipt.source_count=p_source_count AND receipt.target_count=p_target_count
          AND receipt.source_sha256=p_source_sha256
          AND receipt.target_sha256=p_target_sha256
          AND receipt.requested_by=p_requested_by
          AND receipt.approved_by=p_approved_by
          AND receipt.accepted_at=p_accepted_at
          AND receipt.receipt_sha256=v_receipt_sha
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 reverse receipt replay differs';
    END IF;
    RETURN v_receipt_sha;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_reverse_accept_v1(p_reconciliation_id uuid, p_tenant_id uuid, p_source_generation bigint, p_target_generation bigint, p_source_count bigint, p_target_count bigint, p_source_sha256 bytea, p_target_sha256 bytea, p_requested_by uuid, p_approved_by uuid, p_accepted_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: documents_v1_reverse_evidence_v1(uuid, uuid, bigint, bigint, bigint, bigint, bytea, bytea, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_reverse_evidence_v1(p_reconciliation_id uuid, p_tenant_id uuid, p_source_generation bigint, p_target_generation bigint, p_source_count bigint, p_target_count bigint, p_source_sha256 bytea, p_target_sha256 bytea, p_requested_by uuid, p_approved_by uuid, p_accepted_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_receipt_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_cutover_finalizer' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Documents V1 reverse principal denied';
    END IF;
    IF pg_catalog.uuid_extract_version(p_reconciliation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_requested_by) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_approved_by) IS DISTINCT FROM 7 OR
       p_requested_by=p_approved_by OR p_source_generation<1 OR
       p_target_generation<=p_source_generation OR p_source_count<0 OR
       p_source_count IS DISTINCT FROM p_target_count OR
       pg_catalog.octet_length(p_source_sha256)<>32 OR
       p_source_sha256 IS DISTINCT FROM p_target_sha256 OR
       p_accepted_at IS NULL OR NOT pg_catalog.isfinite(p_accepted_at) OR
       p_accepted_at>pg_catalog.clock_timestamp() THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Documents V1 reverse evidence is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.tenant_id=p_tenant_id
          AND identity.schema_name=pg_catalog.current_schema()
          AND identity.origin='v1_adopted'
    ) OR NOT EXISTS (
        SELECT 1 FROM platform.domain_cutovers AS authority
        WHERE authority.scope_kind='tenant' AND authority.scope_id=p_tenant_id
          AND authority.domain='documents'
          AND authority.generation=p_target_generation
          AND authority.state IN ('v2','fenced')
    ) OR NOT EXISTS (
        SELECT 1 FROM documents_v1_cutover_receipts AS receipt
        WHERE receipt.tenant_id=p_tenant_id
          AND receipt.cutover_generation=p_target_generation
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Documents V1 reverse authority is not ready';
    END IF;
    v_receipt_sha:=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy/documents/v1-reverse-receipt/v1:'||
        p_reconciliation_id::text||':'||p_tenant_id::text||':'||
        p_source_generation::text||':'||p_target_generation::text||':'||
        p_source_count::text||':'||pg_catalog.encode(p_source_sha256,'hex')||':'||
        p_requested_by::text||':'||p_approved_by::text||':'||p_accepted_at::text,
        'UTF8'
    )),'hex');
    RETURN v_receipt_sha;
END;
$$;


ALTER FUNCTION __tenant_schema__.documents_v1_reverse_evidence_v1(p_reconciliation_id uuid, p_tenant_id uuid, p_source_generation bigint, p_target_generation bigint, p_source_count bigint, p_target_count bigint, p_source_sha256 bytea, p_target_sha256 bytea, p_requested_by uuid, p_approved_by uuid, p_accepted_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: documents_v1_reverse_reconciliation_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.documents_v1_reverse_reconciliation_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='INSERT' AND SESSION_USER='harpy_cutover_finalizer'
       AND CURRENT_USER='harpy_owner' AND NEW.lifecycle_state='ACCEPTED'
       AND NEW.approved_by IS NOT NULL AND NEW.decided_at IS NOT NULL THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='Documents V1 reverse reconciliation authority denied';
END;
$$;


