--
-- Name: iam_analytics_role_permission_v1(name, uuid, uuid, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_analytics_role_permission_v1(p_scope_schema name, p_tenant_id uuid, p_role_id uuid, p_resource_key text, p_action_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_group_generation bigint;
    v_iam_generation bigint;
    v_layout_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_role_id IS NULL OR
       p_resource_key IS NULL OR p_action_key IS NULL OR
       pg_catalog.char_length(p_resource_key) NOT BETWEEN 1 AND 100 OR
       pg_catalog.char_length(p_action_key) NOT BETWEEN 1 AND 100 OR
       NOT EXISTS (
           SELECT 1 FROM tenancy_schema_identity AS identity_row
           WHERE identity_row.singleton AND identity_row.tenant_id = p_tenant_id
             AND identity_row.schema_name = p_scope_schema::text
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM Analytics role permission scope is invalid';
    END IF;

    SELECT authority.generation INTO v_group_generation
    FROM platform.cutover_groups AS authority
    WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
      AND authority.group_id = 'iam_system_resources'
      AND authority.state = 'v2' AND authority.writer = 'v2';
    SELECT authority.generation INTO v_iam_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
      AND authority.domain = 'iam'
      AND authority.state = 'v2' AND authority.writer = 'v2';
    SELECT authority.generation INTO v_layout_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
      AND authority.domain = 'system_resource_layout'
      AND authority.state = 'v2' AND authority.writer = 'v2';
    IF v_group_generation IS NULL OR v_group_generation < 1 OR
       v_iam_generation IS DISTINCT FROM v_group_generation OR
       v_layout_generation IS DISTINCT FROM v_group_generation OR
       NOT EXISTS (
           SELECT 1 FROM platform.cutover_group_members AS member
           WHERE member.scope_kind = 'tenant' AND member.scope_id = p_tenant_id
             AND member.group_id = 'iam_system_resources'
             AND member.ordinal = 1 AND member.domain = 'iam'
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_group_members AS member
           WHERE member.scope_kind = 'tenant' AND member.scope_id = p_tenant_id
             AND member.group_id = 'iam_system_resources'
             AND member.ordinal = 2 AND member.domain = 'system_resource_layout'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5701',
            MESSAGE = 'IAM Analytics role permission authority is unavailable';
    END IF;

    RETURN EXISTS (
        WITH target AS (
            SELECT permission.id, permission.resource_id, permission.action_id
            FROM iam_permissions AS permission
            JOIN iam_resources AS resource ON resource.id = permission.resource_id
            JOIN iam_actions AS action ON action.id = permission.action_id
            WHERE permission.match_kind = 'exact' AND permission.state = 'active'
              AND resource.resource_key = p_resource_key AND resource.state = 'active'
              AND action.action_key = p_action_key AND action.state = 'active'
        ), eligible AS (
            SELECT target.id FROM target
            UNION ALL
            SELECT permission.id
            FROM iam_permissions AS permission
            JOIN target ON target.resource_id = permission.resource_id
            WHERE permission.match_kind = 'resource_all_actions'
              AND permission.state = 'active'
            UNION ALL
            SELECT permission.id FROM iam_permissions AS permission
            WHERE permission.match_kind = 'tenant_all' AND permission.state = 'active'
        )
        SELECT 1
        FROM iam_roles AS role
        JOIN iam_role_permission_bindings AS binding ON binding.role_id = role.id
        JOIN iam_permissions AS permission ON permission.id = binding.permission_id
        JOIN eligible ON eligible.id = binding.permission_id
        LEFT JOIN iam_protected_admin_policies AS policy ON policy.role_id = role.id
        WHERE role.id = p_role_id AND role.status = 'active'
          AND binding.state = 'active'
          AND (
              permission.match_kind = 'exact' OR
              (permission.match_kind = 'resource_all_actions' AND role.is_protected
               AND policy.policy_state = 'active') OR
              (permission.match_kind = 'tenant_all' AND role.is_protected
               AND policy.policy_state = 'active'
               AND policy.tenant_all_permission_id = permission.id
               AND policy.role_permission_binding_id = binding.id)
          )
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_analytics_role_permission_v1(p_scope_schema name, p_tenant_id uuid, p_role_id uuid, p_resource_key text, p_action_key text) OWNER TO harpy_owner;

--
-- Name: iam_assert_profile_recovery_materialization_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_assert_profile_recovery_materialization_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.recovery_of_plan_id IS NULL THEN
        RETURN NULL;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM (
            SELECT * FROM iam_profile_backfill_mappings
            WHERE plan_id = NEW.recovery_of_plan_id
        ) AS parent
        FULL JOIN (
            SELECT * FROM iam_profile_backfill_mappings
            WHERE plan_id = NEW.id
        ) AS child ON child.ordinal = parent.ordinal
        WHERE parent.ordinal IS NULL OR child.ordinal IS NULL OR
              child.source_field_id <> parent.source_field_id OR
              child.target_field_id <> parent.target_field_id OR
              child.converter_kind <> parent.converter_kind OR
              child.semantic_sha256 <> parent.semantic_sha256
    ) OR NEW.page_count <> (
        SELECT pg_catalog.count(*) FROM iam_profile_backfill_pages AS page
        WHERE page.plan_id = NEW.id
    ) OR NEW.source_count <> COALESCE((
        SELECT pg_catalog.sum(page.expected_count)
        FROM iam_profile_backfill_pages AS page WHERE page.plan_id = NEW.id
    ), 0) OR NOT EXISTS (
        SELECT 1 FROM iam_profile_backfill_checkpoints AS checkpoint
        WHERE checkpoint.plan_id = NEW.id AND checkpoint.completed_pages = 0
          AND checkpoint.converted_count = 0 AND checkpoint.error_count = 0
          AND checkpoint.rolling_sha256 = NEW.initial_rolling_sha256
          AND checkpoint.last_page_number IS NULL AND checkpoint.revision = 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_recovery_materialization_guard',
            MESSAGE = 'IAM profile recovery materialization is incomplete';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_assert_profile_recovery_materialization_v1() OWNER TO harpy_owner;

--
-- Name: iam_authenticator_list_v1(name, uuid, uuid, uuid, bigint, bigint, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_authenticator_list_v1(p_scope_schema name, p_user_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_limit integer, p_after_updated_at timestamp with time zone, p_after_id uuid) RETURNS TABLE(authenticator_id uuid, user_id uuid, kind text, display_label text, state text, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, activated_at timestamp with time zone, last_used_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_user_id IS NULL OR p_limit NOT BETWEEN 1 AND 100 OR
       ((p_after_updated_at IS NULL) <> (p_after_id IS NULL)) OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
    RETURN QUERY
    SELECT authenticator.id, authenticator.user_id, authenticator.kind,
        authenticator.display_label, authenticator.state,
        authenticator.revision, authenticator.created_at,
        authenticator.updated_at, authenticator.activated_at,
        authenticator.last_used_at
    FROM iam_authenticators AS authenticator
    WHERE authenticator.user_id = p_user_id
      AND authenticator.state <> 'retired'
      AND (p_after_updated_at IS NULL OR
          (authenticator.updated_at, authenticator.id) <
          (p_after_updated_at, p_after_id))
    ORDER BY authenticator.updated_at DESC, authenticator.id DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_authenticator_list_v1(p_scope_schema name, p_user_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_limit integer, p_after_updated_at timestamp with time zone, p_after_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_authenticator_retire_v1(name, uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_authenticator_retire_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_authenticator_id IS NULL OR p_expected_revision < 1 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.authenticator.retire',
        p_request_sha256, p_authenticator_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    UPDATE iam_authenticators AS authenticator SET state = 'retired',
        retired_at = v_now, revision = authenticator.revision + 1,
        updated_at = v_now
    WHERE authenticator.id = p_authenticator_id
      AND authenticator.revision = p_expected_revision
      AND authenticator.state IN (
          'pending', 'suspended', 'compromised', 'renewal_required'
      ) RETURNING authenticator.user_id, authenticator.revision
        INTO v_user_id, v_revision;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '40001'; END IF;
    UPDATE iam_auth_challenges SET state = 'cancelled', terminal_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE authenticator_id = p_authenticator_id AND state = 'pending';
    UPDATE iam_recovery_codes SET state = 'revoked', revoked_at = v_now,
        purge_after = v_now + INTERVAL '30 days', revision = revision + 1,
        updated_at = v_now
    WHERE authenticator_id = p_authenticator_id AND state = 'active';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.authenticator.retire', p_request_sha256,
        p_authenticator_id, v_user_id, v_revision,
        'actor_tenant', p_actor_id, 'authenticator', true, true
    ) AS result;
    RETURN QUERY SELECT p_authenticator_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_authenticator_retire_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_authenticator_retire_v2(name, uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_authenticator_retire_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    SELECT result.result_id, result.subject_user_id, result.result_revision,
        result.token_version, result.authorization_version, result.replayed
    INTO result_id, subject_user_id, result_revision,
        token_version, authorization_version, replayed
    FROM iam_authenticator_retire_v1(
        p_scope_schema, p_tenant_id, p_operation_id, p_request_sha256,
        p_authenticator_id, p_expected_revision, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS result;
    IF NOT replayed THEN
        UPDATE iam_sessions SET state = 'revoked', revoked_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE user_id = subject_user_id AND state = 'active';
        UPDATE iam_refresh_families SET state = 'revoked',
            revoke_reason = 'authenticator_retired', revoked_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE user_id = subject_user_id AND state = 'active';
        UPDATE iam_refresh_tokens SET state = 'revoked', revoked_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE family_id IN (
            SELECT id FROM iam_refresh_families WHERE user_id = subject_user_id
        ) AND state = 'active';
    END IF;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_authenticator_retire_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_authenticator_suspend_v1(name, uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_authenticator_suspend_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_authenticator_id IS NULL OR p_expected_revision < 1 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.authenticator.disable',
        p_request_sha256, p_authenticator_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    UPDATE iam_authenticators AS authenticator SET state = 'suspended',
        suspended_at = v_now, revision = authenticator.revision + 1,
        updated_at = v_now
    WHERE authenticator.id = p_authenticator_id
      AND authenticator.revision = p_expected_revision
      AND authenticator.state = 'active'
    RETURNING authenticator.user_id, authenticator.revision
    INTO v_user_id, v_revision;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '40001'; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM iam_authenticators AS alternative
        WHERE alternative.user_id = v_user_id
          AND alternative.id <> p_authenticator_id
          AND alternative.state = 'active'
    ) AND NOT EXISTS (
        SELECT 1 FROM iam_password_credentials AS password
        WHERE password.user_id = v_user_id AND password.state = 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM user requires another active authenticator';
    END IF;
    UPDATE iam_auth_challenges SET state = 'cancelled', terminal_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE authenticator_id = p_authenticator_id AND state = 'pending';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.authenticator.disable', p_request_sha256,
        p_authenticator_id, v_user_id, v_revision,
        'actor_tenant', p_actor_id, 'authenticator', true, true
    ) AS result;
    RETURN QUERY SELECT p_authenticator_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_authenticator_suspend_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

