--
-- Name: iam_authorization_evidence_read_v1(name, uuid, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_authorization_evidence_read_v1(p_scope_schema name, p_actor_id uuid, p_resource_key text, p_action_key text) RETURNS TABLE(actor_document jsonb, resource_document jsonb, action_document jsonb, authorization_clock bigint, bindings_document jsonb, implications_document jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_actor_id IS NULL OR p_resource_key IS NULL OR p_action_key IS NULL OR
       pg_catalog.char_length(p_resource_key) NOT BETWEEN 1 AND 100 OR
       pg_catalog.char_length(p_action_key) NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM authorization evidence scope is invalid';
    END IF;
    RETURN QUERY
    WITH actor AS (
        SELECT id, status, token_version, authorization_version
        FROM iam_users
        WHERE id = p_actor_id
    ), target_resource AS (
        SELECT id, state, is_protected
        FROM iam_resources
        WHERE resource_key = p_resource_key
    ), target_action AS (
        SELECT id, state, is_protected
        FROM iam_actions
        WHERE action_key = p_action_key
    ), target_exact AS (
        SELECT permission.id
        FROM iam_permissions AS permission
        JOIN target_resource AS resource ON resource.id = permission.resource_id
        JOIN target_action AS action ON action.id = permission.action_id
        WHERE permission.match_kind = 'exact'
    ), target_edges AS (
        SELECT implication.*
        FROM iam_permission_implications AS implication
        JOIN target_exact AS target ON target.id = implication.implied_permission_id
    ), relevant_permissions AS (
        SELECT id FROM target_exact
        UNION
        SELECT source_permission_id FROM target_edges
        UNION
        SELECT permission.id
        FROM iam_permissions AS permission
        JOIN target_resource AS resource ON resource.id = permission.resource_id
        WHERE permission.match_kind = 'resource_all_actions'
        UNION
        SELECT id FROM iam_permissions WHERE match_kind = 'tenant_all'
    ), binding_paths AS (
        SELECT
            'user'::text AS path, binding.id AS binding_id,
            binding.state AS binding_state, binding.permission_id,
            NULL::uuid AS assignment_id, ''::text AS assignment_state,
            NULL::uuid AS role_id, ''::text AS role_status,
            ''::text AS role_scope_kind, false AS role_protected,
            NULL::uuid AS membership_id, ''::text AS membership_state,
            NULL::uuid AS organization_id, ''::text AS organization_status,
            NULL::uuid AS policy_role_id, NULL::uuid AS policy_permission_id,
            NULL::uuid AS policy_binding_id, ''::text AS policy_state
        FROM iam_user_permission_bindings AS binding
        JOIN relevant_permissions AS relevant ON relevant.id = binding.permission_id
        WHERE binding.user_id = p_actor_id
        UNION ALL
        SELECT
            'role', binding.id, binding.state, binding.permission_id,
            assignment.id, assignment.state, role.id, role.status,
            role.scope_kind, role.is_protected,
            membership.id, COALESCE(membership.state, ''),
            organization.id, COALESCE(organization.status, ''),
            policy.role_id, policy.tenant_all_permission_id,
            policy.role_permission_binding_id, COALESCE(policy.policy_state, '')
        FROM iam_user_role_assignments AS assignment
        JOIN iam_roles AS role ON role.id = assignment.role_id
        JOIN iam_role_permission_bindings AS binding ON binding.role_id = role.id
        JOIN relevant_permissions AS relevant ON relevant.id = binding.permission_id
        LEFT JOIN iam_organization_memberships AS membership
            ON membership.id = assignment.membership_id
        LEFT JOIN iam_organizations AS organization
            ON organization.id = assignment.organization_id
        LEFT JOIN iam_protected_admin_policies AS policy ON policy.role_id = role.id
        WHERE assignment.user_id = p_actor_id
        UNION ALL
        SELECT
            'organization', binding.id, binding.state, binding.permission_id,
            NULL::uuid, '', NULL::uuid, '', '', false,
            membership.id, membership.state, organization.id, organization.status,
            NULL::uuid, NULL::uuid, NULL::uuid, ''
        FROM iam_organization_memberships AS membership
        JOIN iam_organizations AS organization
          ON organization.id = membership.organization_id
        JOIN iam_organization_permission_bindings AS binding
          ON binding.organization_id = organization.id
        JOIN relevant_permissions AS relevant ON relevant.id = binding.permission_id
        WHERE membership.user_id = p_actor_id
    ), binding_evidence AS (
        SELECT path.*, permission.match_kind, permission.state AS permission_state,
            permission.is_protected AS permission_protected,
            permission.resource_id, permission.action_id,
            COALESCE(resource.state, '') AS resource_state,
            COALESCE(action.state, '') AS action_state
        FROM binding_paths AS path
        JOIN iam_permissions AS permission ON permission.id = path.permission_id
        LEFT JOIN iam_resources AS resource ON resource.id = permission.resource_id
        LEFT JOIN iam_actions AS action ON action.id = permission.action_id
    ), implication_evidence AS (
        SELECT implication.id, implication.implication_kind, implication.state,
            source.id AS source_permission_id,
            source.state AS source_permission_state,
            source.resource_id AS source_resource_id,
            source.action_id AS source_action_id,
            source_resource.state AS source_resource_state,
            source_action.state AS source_action_state,
            implied.id AS implied_permission_id,
            implied.state AS implied_permission_state,
            implied.resource_id AS implied_resource_id,
            implied.action_id AS implied_action_id,
            implied_resource.state AS implied_resource_state,
            implied_action.state AS implied_action_state
        FROM target_edges AS implication
        JOIN iam_permissions AS source ON source.id = implication.source_permission_id
        JOIN iam_resources AS source_resource ON source_resource.id = source.resource_id
        JOIN iam_actions AS source_action ON source_action.id = source.action_id
        JOIN iam_permissions AS implied ON implied.id = implication.implied_permission_id
        JOIN iam_resources AS implied_resource ON implied_resource.id = implied.resource_id
        JOIN iam_actions AS implied_action ON implied_action.id = implied.action_id
    )
    SELECT
        (SELECT pg_catalog.jsonb_build_object(
            'id', id, 'status', status, 'token_version', token_version,
            'authorization_version', authorization_version
        ) FROM actor),
        (SELECT pg_catalog.jsonb_build_object(
            'id', id, 'state', state, 'protected', is_protected
        ) FROM target_resource),
        (SELECT pg_catalog.jsonb_build_object(
            'id', id, 'state', state, 'protected', is_protected
        ) FROM target_action),
        COALESCE((SELECT clock_value FROM iam_authorization_clock WHERE singleton), -1),
        COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'path', path, 'binding_id', binding_id,
            'binding_state', binding_state, 'permission_id', permission_id,
            'permission_match_kind', match_kind, 'permission_state', permission_state,
            'permission_protected', permission_protected,
            'permission_resource', resource_id, 'permission_action', action_id,
            'resource_state', resource_state, 'action_state', action_state,
            'assignment_id', assignment_id, 'assignment_state', assignment_state,
            'role_id', role_id, 'role_status', role_status,
            'role_scope_kind', role_scope_kind, 'role_protected', role_protected,
            'membership_id', membership_id, 'membership_state', membership_state,
            'organization_id', organization_id,
            'organization_status', organization_status,
            'policy_role_id', policy_role_id,
            'policy_permission_id', policy_permission_id,
            'policy_binding_id', policy_binding_id, 'policy_state', policy_state
        ) ORDER BY path, binding_id) FROM binding_evidence), '[]'::jsonb),
        COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'id', id, 'kind', implication_kind, 'state', state,
            'source_permission_id', source_permission_id,
            'source_permission_state', source_permission_state,
            'source_resource_id', source_resource_id,
            'source_action_id', source_action_id,
            'source_resource_state', source_resource_state,
            'source_action_state', source_action_state,
            'implied_permission_id', implied_permission_id,
            'implied_permission_state', implied_permission_state,
            'implied_resource_id', implied_resource_id,
            'implied_action_id', implied_action_id,
            'implied_resource_state', implied_resource_state,
            'implied_action_state', implied_action_state
        ) ORDER BY id) FROM implication_evidence), '[]'::jsonb);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_authorization_evidence_read_v1(p_scope_schema name, p_actor_id uuid, p_resource_key text, p_action_key text) OWNER TO harpy_owner;

--
-- Name: iam_authorization_evidence_read_v2(name, uuid, uuid, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_authorization_evidence_read_v2(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_resource_key text, p_action_key text) RETURNS TABLE(actor_document jsonb, resource_document jsonb, action_document jsonb, authorization_clock bigint, bindings_document jsonb, implications_document jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_group_generation bigint;
    v_iam_generation bigint;
    v_layout_generation bigint;
    v_clock bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_actor_id IS NULL OR
       p_resource_key IS NULL OR p_action_key IS NULL OR
       pg_catalog.char_length(p_resource_key) NOT BETWEEN 1 AND 100 OR
       pg_catalog.char_length(p_action_key) NOT BETWEEN 1 AND 100 OR
       NOT EXISTS (
           SELECT 1
           FROM tenancy_schema_identity AS identity_row
           WHERE identity_row.singleton
             AND identity_row.tenant_id = p_tenant_id
             AND identity_row.schema_name = p_scope_schema::text
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM authorization evidence V2 scope is invalid';
    END IF;

    SELECT authority.generation
    INTO v_group_generation
    FROM platform.cutover_groups AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.group_id = 'iam_system_resources'
      AND authority.state = 'v2'
      AND authority.writer = 'v2'
    FOR SHARE;
    IF NOT FOUND OR v_group_generation < 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5701',
            MESSAGE = 'IAM authorization authority is not current V2';
    END IF;
    SELECT authority.generation
    INTO v_iam_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.domain = 'iam'
      AND authority.state = 'v2'
      AND authority.writer = 'v2'
    FOR SHARE;
    IF NOT FOUND OR v_iam_generation IS DISTINCT FROM v_group_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5702',
            MESSAGE = 'IAM domain authority is not current V2';
    END IF;

    SELECT authority.generation
    INTO v_layout_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.domain = 'system_resource_layout'
      AND authority.state = 'v2'
      AND authority.writer = 'v2'
    FOR SHARE;
    IF NOT FOUND OR v_layout_generation IS DISTINCT FROM v_group_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5703',
            MESSAGE = 'IAM layout domain authority is not current V2';
    END IF;

    PERFORM 1
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind = 'tenant'
      AND member.scope_id = p_tenant_id
      AND member.group_id = 'iam_system_resources'
      AND member.ordinal = 1
      AND member.domain = 'iam'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5704',
            MESSAGE = 'IAM group membership is invalid';
    END IF;
    PERFORM 1
    FROM platform.cutover_group_members AS member
    WHERE member.scope_kind = 'tenant'
      AND member.scope_id = p_tenant_id
      AND member.group_id = 'iam_system_resources'
      AND member.ordinal = 2
      AND member.domain = 'system_resource_layout'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5704',
            MESSAGE = 'IAM group membership is invalid';
    END IF;

    PERFORM 1 FROM iam_users WHERE id = p_actor_id FOR SHARE;
    SELECT clock_value INTO v_clock
    FROM iam_authorization_clock
    WHERE singleton
    FOR SHARE;
    IF NOT FOUND OR v_clock < 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5705',
            MESSAGE = 'IAM authorization clock is unavailable';
    END IF;

    RETURN QUERY
    SELECT evidence.actor_document, evidence.resource_document,
           evidence.action_document, evidence.authorization_clock,
           evidence.bindings_document, evidence.implications_document
    FROM iam_authorization_evidence_read_v1(
        p_scope_schema, p_actor_id, p_resource_key, p_action_key
    ) AS evidence;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_authorization_evidence_read_v2(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_resource_key text, p_action_key text) OWNER TO harpy_owner;

--
-- Name: iam_authorization_evidence_read_v3(name, uuid, uuid, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_authorization_evidence_read_v3(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_resource_key text, p_action_key text) RETURNS TABLE(actor_document jsonb, resource_document jsonb, action_document jsonb, authorization_clock bigint, bindings_document jsonb, implications_document jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_group_generation bigint;
    v_iam_generation bigint;
    v_layout_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_actor_id IS NULL OR
       p_resource_key IS NULL OR p_action_key IS NULL OR
       pg_catalog.char_length(p_resource_key) NOT BETWEEN 1 AND 100 OR
       pg_catalog.char_length(p_action_key) NOT BETWEEN 1 AND 100 OR
       NOT EXISTS (
           SELECT 1
           FROM tenancy_schema_identity AS identity_row
           WHERE identity_row.singleton
             AND identity_row.tenant_id = p_tenant_id
             AND identity_row.schema_name = p_scope_schema::text
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM authorization evidence V3 scope is invalid';
    END IF;

    SELECT authority.generation
    INTO v_group_generation
    FROM platform.cutover_groups AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.group_id = 'iam_system_resources'
      AND authority.state = 'v2'
      AND authority.writer = 'v2';
    IF NOT FOUND OR v_group_generation < 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P5701',
            MESSAGE = 'IAM authorization authority is not current V2';
    END IF;
    SELECT authority.generation
    INTO v_iam_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.domain = 'iam'
      AND authority.state = 'v2'
      AND authority.writer = 'v2';
    IF NOT FOUND OR v_iam_generation IS DISTINCT FROM v_group_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5702',
            MESSAGE = 'IAM domain authority is not current V2';
    END IF;

    SELECT authority.generation
    INTO v_layout_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant'
      AND authority.scope_id = p_tenant_id
      AND authority.domain = 'system_resource_layout'
      AND authority.state = 'v2'
      AND authority.writer = 'v2';
    IF NOT FOUND OR v_layout_generation IS DISTINCT FROM v_group_generation THEN
        RAISE EXCEPTION USING ERRCODE = 'P5703',
            MESSAGE = 'IAM layout domain authority is not current V2';
    END IF;

    IF NOT (EXISTS (
        SELECT 1 FROM platform.cutover_group_members AS member
        WHERE member.scope_kind = 'tenant'
          AND member.scope_id = p_tenant_id
          AND member.group_id = 'iam_system_resources'
          AND member.ordinal = 1
          AND member.domain = 'iam'
    )) OR NOT (EXISTS (
        SELECT 1 FROM platform.cutover_group_members AS member
        WHERE member.scope_kind = 'tenant'
          AND member.scope_id = p_tenant_id
          AND member.group_id = 'iam_system_resources'
          AND member.ordinal = 2
          AND member.domain = 'system_resource_layout'
    )) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5704',
            MESSAGE = 'IAM system-resource group membership is invalid';
    END IF;

    RETURN QUERY
    SELECT evidence.actor_document, evidence.resource_document,
           evidence.action_document, evidence.authorization_clock,
           evidence.bindings_document, evidence.implications_document
    FROM iam_authorization_evidence_read_v1(
        p_scope_schema, p_actor_id, p_resource_key, p_action_key
    ) AS evidence;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_authorization_evidence_read_v3(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_resource_key text, p_action_key text) OWNER TO harpy_owner;

--
-- Name: iam_capability_grant_read_v1(name, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_capability_grant_read_v1(p_scope_schema name, p_grant_id uuid, p_grant_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_grant_id IS NULL OR p_grant_revision IS NULL OR p_grant_revision < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM capability grant read scope is invalid';
    END IF;
    SELECT pg_catalog.jsonb_build_object(
        'principal', pg_catalog.jsonb_build_object(
            'id', principal.id,
            'kind', principal.kind,
            'state', principal.state,
            'authorization_version', principal.authorization_version,
            'revision', principal.revision
        ),
        'grant', pg_catalog.jsonb_build_object(
            'id', head.id,
            'revision', revision.grant_revision,
            'previous_revision', COALESCE(revision.previous_revision, 0),
            'principal_id', revision.principal_id,
            'capability', revision.capability_key,
            'scope_kind', revision.scope_kind,
            'owner', revision.owner_domain,
            'resource_kind', revision.resource_kind,
            'resource_id', revision.resource_id,
            'valid_from', revision.valid_from,
            'valid_until', revision.valid_until,
            'state', revision.disposition,
            'manifest_sha256', pg_catalog.encode(revision.manifest_sha256, 'hex')
        )
    )
    INTO v_document
    FROM iam_capability_grants AS head
    JOIN iam_capability_grant_revisions AS revision
      ON revision.grant_id = head.id
     AND revision.grant_revision = head.current_revision
    JOIN iam_service_principals AS principal
      ON principal.id = head.principal_id
    WHERE head.id = p_grant_id
      AND head.current_revision = p_grant_revision
      AND revision.principal_id = head.principal_id
      AND revision.capability_key = head.capability_key;
    RETURN v_document;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_capability_grant_read_v1(p_scope_schema name, p_grant_id uuid, p_grant_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_capability_grant_revoke_v1(name, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_capability_grant_revoke_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_grant_id uuid, p_expected_revision bigint, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_new_revision bigint;
    v_principal_id uuid;
    v_capability_key text;
    v_scope_kind text;
    v_owner_domain text;
    v_resource_kind text;
    v_resource_id uuid;
    v_valid_from timestamptz;
    v_valid_until timestamptz;
    v_manifest bytea;
    v_head_revision bigint;
    v_head_state text;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_clock bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    v_new_revision := p_expected_revision + 1;
    IF p_operation_id IS NULL OR p_grant_id IS NULL OR p_expected_revision < 1 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM capability grant revoke input is invalid';
    END IF;
    IF NOT iam_service_principal_actor_assert_v1(
        p_scope_schema, p_actor_id, p_manage_permission_id,
        p_expected_token_version, p_expected_authorization_version,
        p_purpose_sha256, p_auth_time,
        p_amr_password, p_amr_webauthn, p_amr_totp
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM service principal command authority is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_id,
         v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.capability_grant.revoke' OR
           v_receipt_request IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_grant_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM capability grant operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    SELECT grant_head.principal_id, grant_head.current_revision, grant_head.state
    INTO v_principal_id, v_head_revision, v_head_state
    FROM iam_capability_grants AS grant_head
    WHERE grant_head.id OPERATOR(pg_catalog.=) p_grant_id
    FOR UPDATE;
    IF NOT FOUND OR v_head_revision IS DISTINCT FROM p_expected_revision OR
       v_head_state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM capability grant revoke CAS is stale';
    END IF;
    SELECT revision.capability_key, revision.scope_kind,
           revision.owner_domain, revision.resource_kind, revision.resource_id,
           revision.valid_from, revision.valid_until, revision.manifest_sha256
    INTO v_capability_key, v_scope_kind, v_owner_domain, v_resource_kind,
         v_resource_id, v_valid_from, v_valid_until, v_manifest
    FROM iam_capability_grant_revisions AS revision
    WHERE revision.grant_id OPERATOR(pg_catalog.=) p_grant_id
      AND revision.grant_revision OPERATOR(pg_catalog.=) p_expected_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM capability grant head evidence is unavailable';
    END IF;
    INSERT INTO iam_capability_grant_revisions (
        grant_id, grant_revision, previous_revision, principal_id,
        capability_key, scope_kind, owner_domain, resource_kind,
        resource_id, valid_from, valid_until, disposition,
        manifest_sha256, created_by_user_id, created_at
    ) VALUES (
        p_grant_id, v_new_revision, p_expected_revision, v_principal_id,
        v_capability_key, v_scope_kind, v_owner_domain, v_resource_kind,
        v_resource_id, v_valid_from, v_valid_until, 'revoked',
        v_manifest, p_actor_id, v_now
    );
    UPDATE iam_capability_grants
    SET current_revision = v_new_revision, state = 'revoked',
        revision = revision + 1, updated_at = v_now, revoked_at = v_now
    WHERE id = p_grant_id;
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton
    RETURNING clock_value INTO v_clock;
    UPDATE iam_service_principals
    SET authorization_version = v_clock, revision = revision + 1, updated_at = v_now
    WHERE id = v_principal_id;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.capability_grant.revoke', p_request_sha256,
        v_clock, 'iam.capability_grant.revoked', p_grant_id,
        v_new_revision, p_request_sha256, v_now
    );
    RETURN QUERY SELECT p_grant_id, v_new_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_capability_grant_revoke_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_grant_id uuid, p_expected_revision bigint, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_capability_grant_write_v1(name, uuid, bytea, uuid, uuid, bigint, text, text, text, text, uuid, timestamp with time zone, timestamp with time zone, bytea, uuid, uuid, bigint, bigint, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_capability_grant_write_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_grant_id uuid, p_principal_id uuid, p_expected_revision bigint, p_capability_key text, p_scope_kind text, p_owner_domain text, p_resource_kind text, p_resource_id uuid, p_valid_from timestamp with time zone, p_valid_until timestamp with time zone, p_manifest_sha256 bytea, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_new_revision bigint;
    v_head_principal uuid;
    v_head_capability text;
    v_head_revision bigint;
    v_head_state text;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_clock bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    v_new_revision := p_expected_revision + 1;
    IF p_operation_id IS NULL OR p_grant_id IS NULL OR p_principal_id IS NULL OR
       p_expected_revision < 0 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_manifest_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM capability grant input is invalid';
    END IF;
    IF NOT iam_service_principal_actor_assert_v1(
        p_scope_schema, p_actor_id, p_manage_permission_id,
        p_expected_token_version, p_expected_authorization_version,
        p_purpose_sha256, p_auth_time,
        p_amr_password, p_amr_webauthn, p_amr_totp
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM service principal command authority is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_id,
         v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.capability_grant.write' OR
           v_receipt_request IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_grant_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM capability grant operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    PERFORM principal.id
    FROM iam_service_principals AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_principal_id
      AND principal.state OPERATOR(pg_catalog.=) 'active'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM capability grant principal is inactive';
    END IF;
    SELECT grant_head.principal_id, grant_head.capability_key,
           grant_head.current_revision, grant_head.state
    INTO v_head_principal, v_head_capability, v_head_revision, v_head_state
    FROM iam_capability_grants AS grant_head
    WHERE grant_head.id OPERATOR(pg_catalog.=) p_grant_id
    FOR UPDATE;
    IF p_expected_revision = 0 THEN
        IF FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM capability grant create CAS is stale';
        END IF;
        INSERT INTO iam_capability_grants (
            id, principal_id, capability_key, current_revision,
            state, revision, created_at, updated_at
        ) VALUES (
            p_grant_id, p_principal_id, p_capability_key, 1,
            'active', 1, v_now, v_now
        );
    ELSIF NOT FOUND OR v_head_principal IS DISTINCT FROM p_principal_id OR
          v_head_capability IS DISTINCT FROM p_capability_key OR
          v_head_revision IS DISTINCT FROM p_expected_revision OR
          v_head_state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM capability grant revision CAS is stale';
    END IF;
    INSERT INTO iam_capability_grant_revisions (
        grant_id, grant_revision, previous_revision, principal_id,
        capability_key, scope_kind, owner_domain, resource_kind,
        resource_id, valid_from, valid_until, disposition,
        manifest_sha256, created_by_user_id, created_at
    ) VALUES (
        p_grant_id, v_new_revision,
        CASE WHEN p_expected_revision = 0 THEN NULL ELSE p_expected_revision END,
        p_principal_id, p_capability_key, p_scope_kind, p_owner_domain,
        p_resource_kind, p_resource_id, p_valid_from, p_valid_until,
        'active', p_manifest_sha256, p_actor_id, v_now
    );
    IF p_expected_revision > 0 THEN
        UPDATE iam_capability_grants
        SET current_revision = v_new_revision, revision = revision + 1,
            updated_at = v_now
        WHERE id = p_grant_id;
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton
    RETURNING clock_value INTO v_clock;
    UPDATE iam_service_principals
    SET authorization_version = v_clock, revision = revision + 1, updated_at = v_now
    WHERE id = p_principal_id;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.capability_grant.write', p_request_sha256,
        v_clock, 'iam.capability_grant.written', p_grant_id,
        v_new_revision, p_request_sha256, v_now
    );
    RETURN QUERY SELECT p_grant_id, v_new_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_capability_grant_write_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_grant_id uuid, p_principal_id uuid, p_expected_revision bigint, p_capability_key text, p_scope_kind text, p_owner_domain text, p_resource_kind text, p_resource_id uuid, p_valid_from timestamp with time zone, p_valid_until timestamp with time zone, p_manifest_sha256 bytea, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_catalog_authorization_record_v2(uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_authorization_record_v2(p_operation_id uuid, p_component_id uuid, p_content_sha256 text, p_action text, p_completed_at timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_clock bigint;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_content_sha256!~'^[0-9a-f]{64}$' OR
       p_action NOT IN ('disable','enable','retire','restore','purge') OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM Catalog authorization receipt input is invalid';
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value=clock_value+1,revision=revision+1,
        updated_at=GREATEST(updated_at,p_completed_at)
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog authorization clock is unavailable';
    END IF;
    PERFORM iam_rbac_bump_all_users_v1(v_clock);
    INSERT INTO iam_authorization_operation_receipts(
        operation_id,command_key,request_sha256,clock_value,
        result_code,result_id,result_revision,result_sha256,created_at
    ) VALUES (
        p_operation_id,'iam.catalog.'||p_action,
        pg_catalog.decode(p_content_sha256,'hex'),v_clock,
        'iam.catalog.'||p_action||'.succeeded',p_component_id,1,
        pg_catalog.decode(p_content_sha256,'hex'),p_completed_at
    );
    RETURN v_clock;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_catalog_authorization_record_v2(p_operation_id uuid, p_component_id uuid, p_content_sha256 text, p_action text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_blocker_snapshot_v2(uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_blocker_snapshot_v2(p_component_id uuid, p_reference_epoch bigint, p_generation bigint) RETURNS TABLE(blockers jsonb, zero_digest text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_component iam_catalog_components%ROWTYPE;
    v_head iam_catalog_component_heads%ROWTYPE;
BEGIN
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_reference_epoch IS NULL OR p_reference_epoch<1 OR
       p_generation IS NULL OR p_generation<1 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM Catalog blocker snapshot input is invalid';
    END IF;
    SELECT * INTO v_component
    FROM iam_catalog_components AS component
    WHERE component.component_id=p_component_id FOR SHARE;
    SELECT * INTO v_head
    FROM iam_catalog_component_heads AS head
    WHERE head.component_id=p_component_id FOR SHARE;
    IF v_component.component_id IS NULL OR v_head.component_id IS NULL OR
       v_component.component_kind<>'IAM_TEMPLATE' OR
       v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR
       v_component.lifecycle_state<>'RETIRED' OR
       v_head.owner_generation<>p_generation OR
       v_head.content_sha256<>v_component.content_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog blocker snapshot authority differs';
    END IF;
    RETURN QUERY
    WITH mapped_resources AS (
        SELECT DISTINCT mapped.resource_id
        FROM iam_catalog_version_operational_resources AS mapped
        WHERE mapped.component_id=p_component_id
    ),mapped_permissions AS (
        SELECT DISTINCT mapped.permission_id
        FROM iam_catalog_version_operational_grants AS mapped
        WHERE mapped.component_id=p_component_id
    ),mapped_bindings AS (
        SELECT DISTINCT mapped.binding_id
        FROM iam_catalog_version_operational_grants AS mapped
        WHERE mapped.component_id=p_component_id
    ),external_permission_references AS (
        SELECT 'role:'||binding.id::text AS reference
        FROM iam_role_permission_bindings AS binding
        JOIN mapped_permissions AS permission
          ON permission.permission_id=binding.permission_id
        LEFT JOIN mapped_bindings AS mapped ON mapped.binding_id=binding.id
        WHERE binding.state='active' AND mapped.binding_id IS NULL
        UNION ALL
        SELECT 'user:'||binding.id::text
        FROM iam_user_permission_bindings AS binding
        JOIN mapped_permissions AS permission
          ON permission.permission_id=binding.permission_id
        WHERE binding.state='active'
        UNION ALL
        SELECT 'organization:'||binding.id::text
        FROM iam_organization_permission_bindings AS binding
        JOIN mapped_permissions AS permission
          ON permission.permission_id=binding.permission_id
        WHERE binding.state='active'
        UNION ALL
        SELECT 'implication:'||implication.id::text
        FROM iam_permission_implications AS implication
        WHERE implication.state='active' AND (
            EXISTS (SELECT 1 FROM mapped_permissions AS mapped
                WHERE mapped.permission_id=implication.source_permission_id) OR
            EXISTS (SELECT 1 FROM mapped_permissions AS mapped
                WHERE mapped.permission_id=implication.implied_permission_id)
        )
        UNION ALL
        SELECT 'assignment:'||member.group_id::text||':'||
            member.group_revision::text||':'||member.ordinal::text
        FROM iam_rbac_assignment_members AS member
        JOIN mapped_permissions AS permission
          ON permission.permission_id=member.permission_id
        WHERE member.state='active'
        UNION ALL
        SELECT 'request:'||request.id::text
        FROM iam_permission_requests AS request
        JOIN mapped_permissions AS permission
          ON permission.permission_id=request.permission_id
        WHERE request.state IN ('PENDING','IN_REVIEW')
    ),facts AS (
        SELECT blocker.code,blocker.digest
        FROM iam_catalog_component_blockers AS blocker
        WHERE blocker.component_id=p_component_id AND blocker.active
        UNION ALL
        SELECT 'IAM_CATALOG_CANDIDATE_ACTIVE',
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                pg_catalog.string_agg(
                    candidate.provision_receipt_id::text,',' ORDER BY
                    candidate.provision_receipt_id
                ),'UTF8')),'hex')
        FROM iam_catalog_component_candidates AS candidate
        WHERE candidate.component_id=p_component_id
        HAVING pg_catalog.count(*)>0
        UNION ALL
        SELECT 'IAM_CATALOG_GRANT_ACTIVE',
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                pg_catalog.string_agg(
                    binding.id::text,',' ORDER BY binding.id
                ),'UTF8')),'hex')
        FROM iam_role_permission_bindings AS binding
        JOIN mapped_bindings AS mapped ON mapped.binding_id=binding.id
        WHERE binding.state='active'
        HAVING pg_catalog.count(*)>0
        UNION ALL
        SELECT 'IAM_CATALOG_EXTERNAL_PERMISSION',
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                pg_catalog.string_agg(
                    permission.id::text,',' ORDER BY permission.id
                ),'UTF8')),'hex')
        FROM iam_permissions AS permission
        JOIN mapped_resources AS resource
          ON resource.resource_id=permission.resource_id
        LEFT JOIN mapped_permissions AS mapped
          ON mapped.permission_id=permission.id
        WHERE permission.state='active' AND mapped.permission_id IS NULL
        HAVING pg_catalog.count(*)>0
        UNION ALL
        SELECT 'IAM_CATALOG_EXTERNAL_PERMISSION_REFERENCE',
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                pg_catalog.string_agg(
                    reference.reference,',' ORDER BY reference.reference
                ),'UTF8')),'hex')
        FROM external_permission_references AS reference
        HAVING pg_catalog.count(*)>0
    ),document AS (
        SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'Owner','iam','Code',fact.code,'Digest',fact.digest
        ) ORDER BY fact.code,fact.digest),'[]'::jsonb) AS blockers
        FROM facts AS fact
    )
    SELECT document.blockers,
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
            'iam-catalog-blockers.v2'||E'\\000'||p_component_id::text||
            E'\\000'||p_reference_epoch::text||E'\\000'||
            v_head.package_id::text||E'\\000'||v_head.package_version||
            E'\\000'||v_head.release_id::text||E'\\000'||
            v_head.content_sha256||E'\\000'||document.blockers::text,
            'UTF8'
        )),'hex')
    FROM document;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_blocker_snapshot_v2(p_component_id uuid, p_reference_epoch bigint, p_generation bigint) OWNER TO harpy_owner;

--
-- Name: iam_catalog_component_apply_v1(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_component_apply_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_action='purge' THEN
        RETURN QUERY SELECT result.*
        FROM iam_catalog_component_purge_v3(
            p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
            p_contract,p_content_sha256,p_action,p_reference_epoch,
            p_idempotency_key,p_completed_at
        ) AS result;
    ELSIF p_action IN ('disable','enable','retire','restore') THEN
        RETURN QUERY SELECT result.*
        FROM iam_catalog_component_transition_v3(
            p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
            p_contract,p_content_sha256,p_action,p_reference_epoch,
            p_idempotency_key,p_completed_at
        ) AS result;
    ELSIF p_action IN ('stage','cleanup','activate') AND
          p_reference_epoch=0 THEN
        RETURN QUERY SELECT result.*
        FROM iam_catalog_component_apply_v2(
            p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
            p_contract,p_content_sha256,p_action,p_reference_epoch,
            p_idempotency_key,p_completed_at
        ) AS result;
    ELSE
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM Catalog component action is invalid';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_component_apply_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_component_apply_v2(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_component_apply_v2(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component iam_catalog_components%ROWTYPE; v_receipt iam_catalog_component_receipts%ROWTYPE;
    v_provision iam_catalog_version_provisions%ROWTYPE; v_has_head boolean; v_head_matches boolean; v_next text;
BEGIN
    SELECT * INTO v_receipt FROM iam_catalog_component_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id AND receipt.component_id=p_component_id
      AND receipt.action=p_action;
    IF FOUND THEN
        IF v_receipt.owner_generation<>p_generation OR
           v_receipt.contract<>p_contract OR
           v_receipt.content_sha256<>p_content_sha256 OR
           v_receipt.idempotency_key<>p_idempotency_key THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='IAM catalog version component receipt differs';
        END IF;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.owner_module,v_receipt.owner_generation,
            v_receipt.contract,v_receipt.content_sha256,v_receipt.action,
            v_receipt.ready,v_receipt.completed_at;
        RETURN;
    END IF;
    IF p_action NOT IN ('stage','cleanup','activate') THEN
        RETURN QUERY SELECT * FROM iam_catalog_component_apply_v1(
            p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,p_contract,
            p_content_sha256,p_action,p_reference_epoch,p_idempotency_key,p_completed_at
        );
        RETURN;
    END IF;
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_owner IS DISTINCT FROM 'iam' OR p_generation<1 OR
       p_contract IS NULL OR p_content_sha256!~'^[0-9a-f]{64}$' OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='IAM catalog version component command is invalid';
    END IF;
    SELECT * INTO v_component
    FROM iam_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    IF NOT FOUND OR v_component.component_kind<>'IAM_TEMPLATE' OR
       v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR
       v_component.contract<>p_contract THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='IAM catalog version component authority differs';
    END IF;
    SELECT EXISTS(SELECT 1 FROM iam_catalog_component_heads AS head WHERE head.component_id=p_component_id) INTO v_has_head;
    IF p_action='cleanup' THEN
        IF NOT EXISTS (
            SELECT 1 FROM iam_catalog_component_receipts AS stage
            WHERE stage.operation_id=p_operation_id
              AND stage.component_id=p_component_id
              AND stage.action='stage'
              AND stage.content_sha256=p_content_sha256
        ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='IAM catalog version cleanup lacks staged evidence';
        END IF;
        v_next:=CASE
          WHEN NOT v_has_head AND v_component.lifecycle_state='STAGED'
            AND v_component.content_sha256=p_content_sha256
            AND EXISTS (SELECT 1 FROM iam_catalog_component_candidates AS candidate
                WHERE candidate.component_id=p_component_id
                  AND candidate.staged_operation_id=p_operation_id) THEN 'AVAILABLE'
          WHEN NOT v_has_head AND v_component.lifecycle_state IN ('AVAILABLE','STAGED')
            AND EXISTS (SELECT 1 FROM iam_catalog_component_candidates AS candidate
                WHERE candidate.component_id=p_component_id) THEN v_component.lifecycle_state
          WHEN v_has_head AND
            v_component.lifecycle_state IN ('ACTIVE','DISABLED')
            THEN v_component.lifecycle_state
          ELSE NULL END;
        DELETE FROM iam_catalog_component_candidates AS candidate
        WHERE candidate.component_id=p_component_id
          AND candidate.content_sha256=p_content_sha256
          AND candidate.staged_operation_id=p_operation_id;
    ELSE
        SELECT provision.* INTO v_provision
        FROM iam_catalog_component_candidates AS candidate
        JOIN iam_catalog_version_provisions AS provision
          ON provision.receipt_id=candidate.provision_receipt_id
         AND provision.component_id=candidate.component_id
         AND provision.package_id=candidate.package_id
         AND provision.package_version=candidate.package_version
         AND provision.release_id=candidate.release_id
         AND provision.owner_generation=candidate.owner_generation
         AND provision.content_sha256=candidate.content_sha256
        WHERE candidate.component_id=p_component_id
          AND candidate.owner_generation=p_generation
          AND candidate.content_sha256=p_content_sha256
          AND provision.contract=p_contract
          AND ((p_action='stage' AND (candidate.staged_operation_id IS NULL
                    OR candidate.staged_operation_id=p_operation_id))
            OR (p_action='activate'
                AND candidate.staged_operation_id=p_operation_id))
        FOR UPDATE OF candidate,provision;
        IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='IAM catalog exact candidate unavailable';
        END IF;
        IF p_action='stage' THEN
            UPDATE iam_catalog_component_candidates AS candidate
            SET staged_operation_id=p_operation_id,staged_at=p_completed_at
            WHERE candidate.component_id=p_component_id;
            v_next:=CASE
              WHEN NOT v_has_head
                AND v_component.lifecycle_state IN ('AVAILABLE','STAGED')
                AND v_component.content_sha256=p_content_sha256 THEN 'STAGED'
              WHEN v_has_head AND
                v_component.lifecycle_state IN ('ACTIVE','DISABLED')
                THEN v_component.lifecycle_state
              ELSE NULL END;
        ELSIF NOT EXISTS (
            SELECT 1 FROM iam_catalog_component_receipts AS stage
            WHERE stage.operation_id=p_operation_id
              AND stage.component_id=p_component_id
              AND stage.action='stage'
              AND stage.content_sha256=p_content_sha256
        ) THEN
            RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='IAM catalog version activation lacks staged evidence';
        ELSE
            v_next:=CASE
              WHEN NOT v_has_head
                AND v_component.lifecycle_state='STAGED' THEN 'ACTIVE'
              WHEN v_has_head AND
                v_component.lifecycle_state IN ('ACTIVE','DISABLED')
                THEN v_component.lifecycle_state
              ELSE NULL END;
            SELECT EXISTS(SELECT 1 FROM iam_catalog_component_heads AS head
                WHERE head.component_id=p_component_id
                  AND head.package_id=v_provision.package_id
                  AND head.package_version=v_provision.package_version
                  AND head.release_id=v_provision.release_id
                  AND head.owner_generation=v_provision.owner_generation
                  AND head.content_sha256=v_provision.content_sha256
            ) INTO v_head_matches;
            IF NOT v_head_matches THEN
                PERFORM iam_catalog_operational_activate_v2(
                    (SELECT schema_name::name FROM tenancy_schema_identity WHERE singleton),
                    v_provision.receipt_id,p_completed_at
                );
            END IF;
            INSERT INTO iam_catalog_component_heads(
                component_id,package_id,package_version,release_id,
                owner_generation,content_sha256,
                provision_receipt_id,activated_at
            ) VALUES (
                p_component_id,v_provision.package_id,
                v_provision.package_version,v_provision.release_id,
                v_provision.owner_generation,v_provision.content_sha256,
                v_provision.receipt_id,p_completed_at
            ) ON CONFLICT ON CONSTRAINT iam_catalog_component_heads_pkey
              DO UPDATE SET
                package_id=EXCLUDED.package_id,
                package_version=EXCLUDED.package_version,
                release_id=EXCLUDED.release_id,
                owner_generation=EXCLUDED.owner_generation,
                content_sha256=EXCLUDED.content_sha256,
                provision_receipt_id=EXCLUDED.provision_receipt_id,
                activated_at=EXCLUDED.activated_at;
            DELETE FROM iam_catalog_component_candidates AS candidate
            WHERE candidate.component_id=p_component_id;
        END IF;
    END IF;
    IF v_next IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='IAM catalog version transition invalid';
    END IF;
    UPDATE iam_catalog_components AS component SET lifecycle_state=v_next,
        content_sha256=CASE WHEN p_action='activate'
            THEN p_content_sha256 ELSE component.content_sha256 END,
        updated_at=CASE
          WHEN lifecycle_state IS DISTINCT FROM v_next
            OR p_action='activate' THEN p_completed_at
          ELSE updated_at END
    WHERE component.component_id=p_component_id;
    INSERT INTO iam_catalog_component_receipts(
        receipt_id,operation_id,component_id,owner_module,
        owner_generation,contract,content_sha256,action,
        idempotency_key,ready,completed_at
    ) VALUES (
        p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
        p_contract,p_content_sha256,p_action,p_idempotency_key,
        true,p_completed_at
    ) RETURNING * INTO v_receipt;
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.owner_module,v_receipt.owner_generation,
        v_receipt.contract,v_receipt.content_sha256,v_receipt.action,
        v_receipt.ready,v_receipt.completed_at;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_catalog_component_apply_v2(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_component_blockers_v1(uuid, uuid, uuid, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_component_blockers_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_reference_epoch bigint, p_generation bigint, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, reference_epoch bigint, catalog_version text, zero_digest text, blockers jsonb, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_component iam_catalog_components%ROWTYPE;
    v_receipt iam_catalog_blocker_receipts%ROWTYPE;
    v_blockers jsonb;
    v_digest text;
    v_legacy_digest text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_receipt_id=p_operation_id OR p_reference_epoch<1 OR p_generation<1 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM Catalog blocker request is invalid';
    END IF;
    SELECT * INTO v_component
    FROM iam_catalog_components AS component
    WHERE component.component_id=p_component_id FOR SHARE;
    IF NOT FOUND OR v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR
       v_component.lifecycle_state<>'RETIRED' OR
       p_completed_at<v_component.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog blocker authority differs';
    END IF;
    SELECT snapshot.blockers,snapshot.zero_digest
    INTO STRICT v_blockers,v_digest
    FROM iam_catalog_blocker_snapshot_v2(
        p_component_id,p_reference_epoch,p_generation
    ) AS snapshot;
    SELECT * INTO v_receipt
    FROM iam_catalog_blocker_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id
      AND receipt.component_id=p_component_id
      AND receipt.reference_epoch=p_reference_epoch
    FOR SHARE;
    IF FOUND THEN
        IF v_receipt.blockers<>'[]'::jsonb OR v_blockers<>'[]'::jsonb OR
           v_receipt.completed_at>p_completed_at THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='IAM Catalog blocker receipt is stale';
        END IF;
        IF v_receipt.catalog_version='iam-catalog-blockers.v1' THEN
            v_legacy_digest:=pg_catalog.encode(pg_catalog.sha256(
                pg_catalog.convert_to(
                    'iam-catalog-blockers.v1'||E'\\000'||
                    p_component_id::text||E'\\000'||
                    p_reference_epoch::text||E'\\000'||
                    v_receipt.blockers::text,'UTF8'
                )
            ),'hex');
            IF v_receipt.zero_digest<>v_legacy_digest THEN
                RAISE EXCEPTION USING ERRCODE='55000',
                    MESSAGE='IAM Catalog legacy blocker proof differs';
            END IF;
        ELSIF v_receipt.catalog_version<>'iam-catalog-blockers.v2' OR
              v_receipt.zero_digest<>v_digest OR
              v_receipt.blockers<>v_blockers THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='IAM Catalog blocker proof differs';
        END IF;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.reference_epoch,
            v_receipt.catalog_version,v_receipt.zero_digest,
            v_receipt.blockers,v_receipt.completed_at;
        RETURN;
    END IF;
    IF v_blockers='[]'::jsonb THEN
        INSERT INTO iam_catalog_blocker_receipts(
            receipt_id,operation_id,component_id,reference_epoch,
            catalog_version,zero_digest,blockers,completed_at
        ) VALUES (
            p_receipt_id,p_operation_id,p_component_id,p_reference_epoch,
            'iam-catalog-blockers.v2',v_digest,v_blockers,p_completed_at
        ) RETURNING * INTO v_receipt;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.reference_epoch,
            v_receipt.catalog_version,v_receipt.zero_digest,
            v_receipt.blockers,v_receipt.completed_at;
        RETURN;
    END IF;
    RETURN QUERY SELECT p_receipt_id,p_operation_id,p_component_id,
        p_reference_epoch,'iam-catalog-blockers.v2',v_digest,
        v_blockers,p_completed_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_component_blockers_v1(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_reference_epoch bigint, p_generation bigint, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_component_purge_v3(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_component_purge_v3(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component iam_catalog_components%ROWTYPE;
    v_head iam_catalog_component_heads%ROWTYPE;
    v_receipt iam_catalog_component_receipts%ROWTYPE;
    v_blocker iam_catalog_blocker_receipts%ROWTYPE;
    v_authorization iam_authorization_operation_receipts%ROWTYPE;
    v_blockers jsonb;
    v_digest text;
    v_legacy_digest text;
    v_count bigint;
    v_changed bigint;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_receipt_id=p_operation_id OR p_owner IS DISTINCT FROM 'iam' OR
       p_generation<1 OR p_contract IS NULL OR
       p_content_sha256!~'^[0-9a-f]{64}$' OR
       p_action IS DISTINCT FROM 'purge' OR p_reference_epoch<1 OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM Catalog purge command is invalid';
    END IF;
    SELECT * INTO v_receipt
    FROM iam_catalog_component_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id
      AND receipt.component_id=p_component_id
      AND receipt.action='purge'
    FOR SHARE;
    IF FOUND THEN
        SELECT * INTO v_authorization
        FROM iam_authorization_operation_receipts AS receipt
        WHERE receipt.operation_id=p_operation_id;
        IF v_receipt.owner_module<>p_owner OR
           v_receipt.owner_generation<>p_generation OR
           v_receipt.contract<>p_contract OR
           v_receipt.content_sha256<>p_content_sha256 OR
           v_receipt.idempotency_key<>p_idempotency_key OR
           NOT v_receipt.ready OR
           v_authorization.operation_id IS NULL OR
           v_authorization.command_key<>'iam.catalog.purge' OR
           v_authorization.request_sha256<>
             pg_catalog.decode(p_content_sha256,'hex') OR
           v_authorization.result_id<>p_component_id OR NOT EXISTS (
               SELECT 1 FROM iam_catalog_components AS component
               WHERE component.component_id=p_component_id
                 AND component.lifecycle_state='PURGED'
           ) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='IAM Catalog purge receipt differs';
        END IF;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.owner_module,
            v_receipt.owner_generation,v_receipt.contract,
            v_receipt.content_sha256,v_receipt.action,
            v_receipt.ready,v_receipt.completed_at;
        RETURN;
    END IF;
    SELECT * INTO v_component
    FROM iam_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    SELECT * INTO v_head
    FROM iam_catalog_component_heads AS head
    WHERE head.component_id=p_component_id FOR UPDATE;
    IF v_component.component_id IS NULL OR v_head.component_id IS NULL OR
       v_component.component_kind<>'IAM_TEMPLATE' OR
       v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR
       v_component.lifecycle_state<>'RETIRED' OR
       v_component.contract<>p_contract OR
       v_component.content_sha256<>p_content_sha256 OR
       v_head.owner_generation<>p_generation OR
       v_head.content_sha256<>p_content_sha256 OR
       p_completed_at<v_component.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog purge authority differs';
    END IF;
    SELECT pg_catalog.count(*) INTO v_count
    FROM iam_catalog_blocker_receipts AS blocker
    WHERE blocker.operation_id=p_operation_id
      AND blocker.component_id=p_component_id;
    IF v_count<>1 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog purge blocker receipt is ambiguous';
    END IF;
    SELECT * INTO STRICT v_blocker
    FROM iam_catalog_blocker_receipts AS blocker
    WHERE blocker.operation_id=p_operation_id
      AND blocker.component_id=p_component_id
    FOR SHARE;
    IF v_blocker.reference_epoch<>p_reference_epoch OR
       v_blocker.blockers<>'[]'::jsonb OR
       v_blocker.completed_at>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog purge blocker receipt differs';
    END IF;
    SELECT snapshot.blockers,snapshot.zero_digest
    INTO STRICT v_blockers,v_digest
    FROM iam_catalog_blocker_snapshot_v2(
        p_component_id,p_reference_epoch,p_generation
    ) AS snapshot;
    IF v_blockers<>'[]'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog purge blockers changed';
    END IF;
    IF v_blocker.catalog_version='iam-catalog-blockers.v1' THEN
        v_legacy_digest:=pg_catalog.encode(pg_catalog.sha256(
            pg_catalog.convert_to(
                'iam-catalog-blockers.v1'||E'\\000'||
                p_component_id::text||E'\\000'||
                p_reference_epoch::text||E'\\000'||'[]','UTF8'
            )
        ),'hex');
        IF v_blocker.zero_digest<>v_legacy_digest THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='IAM Catalog legacy purge proof differs';
        END IF;
    ELSIF v_blocker.catalog_version<>'iam-catalog-blockers.v2' OR
          v_blocker.zero_digest<>v_digest THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog purge proof differs';
    END IF;
    PERFORM iam_catalog_purge_data_v2(
        p_operation_id,p_component_id,p_generation,p_content_sha256,
        p_reference_epoch,p_completed_at
    );
    INSERT INTO iam_catalog_component_receipts(
        receipt_id,operation_id,component_id,owner_module,owner_generation,
        contract,content_sha256,action,idempotency_key,ready,completed_at
    ) VALUES (
        p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
        p_contract,p_content_sha256,'purge',p_idempotency_key,true,
        p_completed_at
    ) RETURNING * INTO v_receipt;
    UPDATE iam_catalog_components AS component
    SET lifecycle_state='PURGED',updated_at=p_completed_at
    WHERE component.component_id=p_component_id
      AND component.lifecycle_state='RETIRED'
      AND component.owner_generation=p_generation
      AND component.content_sha256=p_content_sha256;
    GET DIAGNOSTICS v_changed=ROW_COUNT;
    IF v_changed<>1 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog purge final CAS differs';
    END IF;
    PERFORM iam_catalog_authorization_record_v2(
        p_operation_id,p_component_id,p_content_sha256,'purge',p_completed_at
    );
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.owner_module,
        v_receipt.owner_generation,v_receipt.contract,
        v_receipt.content_sha256,v_receipt.action,
        v_receipt.ready,v_receipt.completed_at;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_catalog_component_purge_v3(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_component_transition_v3(uuid, uuid, uuid, text, bigint, text, text, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_component_transition_v3(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, operation_id uuid, component_id uuid, owner_module text, owner_generation bigint, contract text, content_sha256 text, action text, ready boolean, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component iam_catalog_components%ROWTYPE;
    v_head iam_catalog_component_heads%ROWTYPE;
    v_receipt iam_catalog_component_receipts%ROWTYPE;
    v_authorization iam_authorization_operation_receipts%ROWTYPE;
    v_expected_state text;
BEGIN
    IF pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_receipt_id=p_operation_id OR
       p_owner IS DISTINCT FROM 'iam' OR p_generation<1 OR
       p_contract IS NULL OR p_content_sha256!~'^[0-9a-f]{64}$' OR
       p_action NOT IN ('disable','enable','retire','restore') OR
       p_reference_epoch<>0 OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_completed_at IS NULL OR NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM Catalog transition command is invalid';
    END IF;
    SELECT * INTO v_receipt
    FROM iam_catalog_component_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id
      AND receipt.component_id=p_component_id
      AND receipt.action=p_action
    FOR SHARE;
    IF FOUND THEN
        SELECT * INTO v_authorization
        FROM iam_authorization_operation_receipts AS receipt
        WHERE receipt.operation_id=p_operation_id;
        IF v_receipt.owner_module<>p_owner OR
           v_receipt.owner_generation<>p_generation OR
           v_receipt.contract<>p_contract OR
           v_receipt.content_sha256<>p_content_sha256 OR
           v_receipt.idempotency_key<>p_idempotency_key OR
           NOT v_receipt.ready OR
           v_authorization.operation_id IS NULL OR
           v_authorization.command_key<>'iam.catalog.'||p_action OR
           v_authorization.request_sha256<>
             pg_catalog.decode(p_content_sha256,'hex') OR
           v_authorization.result_id<>p_component_id THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='IAM Catalog transition receipt differs';
        END IF;
        RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
            v_receipt.component_id,v_receipt.owner_module,
            v_receipt.owner_generation,v_receipt.contract,
            v_receipt.content_sha256,v_receipt.action,
            v_receipt.ready,v_receipt.completed_at;
        RETURN;
    END IF;
    SELECT * INTO v_component
    FROM iam_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    SELECT * INTO v_head
    FROM iam_catalog_component_heads AS head
    WHERE head.component_id=p_component_id FOR SHARE;
    v_expected_state:=CASE p_action
      WHEN 'disable' THEN 'ACTIVE'
      WHEN 'enable' THEN 'DISABLED'
      WHEN 'restore' THEN 'RETIRED'
      WHEN 'retire' THEN NULL
      ELSE NULL END;
    IF v_component.component_id IS NULL OR v_head.component_id IS NULL OR
       v_component.component_kind<>'IAM_TEMPLATE' OR
       v_component.owner_generation<>p_generation OR
       v_component.writer_state<>'v2' OR
       v_component.contract<>p_contract OR
       v_component.content_sha256<>p_content_sha256 OR
       v_head.owner_generation<>p_generation OR
       v_head.content_sha256<>p_content_sha256 OR
       p_completed_at<v_component.updated_at OR
       (p_action='retire' AND
        v_component.lifecycle_state NOT IN ('ACTIVE','DISABLED')) OR
       (p_action<>'retire' AND
        v_component.lifecycle_state<>v_expected_state) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog transition authority differs';
    END IF;
    PERFORM iam_catalog_grants_set_v2(
        p_component_id,p_action IN ('enable','restore'),p_completed_at
    );
    UPDATE iam_catalog_components AS component
    SET lifecycle_state=CASE p_action
          WHEN 'disable' THEN 'DISABLED'
          WHEN 'retire' THEN 'RETIRED'
          ELSE 'ACTIVE' END,
        updated_at=p_completed_at
    WHERE component.component_id=p_component_id;
    INSERT INTO iam_catalog_component_receipts(
        receipt_id,operation_id,component_id,owner_module,owner_generation,
        contract,content_sha256,action,idempotency_key,ready,completed_at
    ) VALUES (
        p_receipt_id,p_operation_id,p_component_id,p_owner,p_generation,
        p_contract,p_content_sha256,p_action,p_idempotency_key,true,
        p_completed_at
    ) RETURNING * INTO v_receipt;
    PERFORM iam_catalog_authorization_record_v2(
        p_operation_id,p_component_id,p_content_sha256,p_action,p_completed_at
    );
    RETURN QUERY SELECT v_receipt.receipt_id,v_receipt.operation_id,
        v_receipt.component_id,v_receipt.owner_module,
        v_receipt.owner_generation,v_receipt.contract,
        v_receipt.content_sha256,v_receipt.action,
        v_receipt.ready,v_receipt.completed_at;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_catalog_component_transition_v3(p_receipt_id uuid, p_operation_id uuid, p_component_id uuid, p_owner text, p_generation bigint, p_contract text, p_content_sha256 text, p_action text, p_reference_epoch bigint, p_idempotency_key text, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_grants_set_v2(uuid, boolean, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_grants_set_v2(p_component_id uuid, p_enable boolean, p_completed_at timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_binding_id uuid;
    v_changed bigint:=0;
    v_step bigint;
BEGIN
    IF pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_enable IS NULL OR p_completed_at IS NULL OR
       NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at OR
       NOT EXISTS (
           SELECT 1 FROM iam_catalog_component_heads AS head
           WHERE head.component_id=p_component_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM Catalog grant lifecycle input is invalid';
    END IF;
    FOR v_binding_id IN
        SELECT DISTINCT mapped.binding_id
        FROM iam_catalog_version_operational_grants AS mapped
        JOIN iam_catalog_component_heads AS head
          ON head.component_id=mapped.component_id
         AND head.package_id=mapped.package_id
         AND head.package_version=mapped.package_version
         AND head.release_id=mapped.release_id
         AND head.owner_generation=mapped.owner_generation
         AND head.content_sha256=mapped.content_sha256
        WHERE mapped.component_id=p_component_id
        ORDER BY mapped.binding_id
    LOOP
        IF p_enable THEN
            UPDATE iam_role_permission_bindings AS binding
            SET state='active',revision=binding.revision+1,
                updated_at=p_completed_at,activated_at=p_completed_at,
                revoked_at=NULL
            WHERE binding.id=v_binding_id AND binding.state='revoked';
        ELSE
            UPDATE iam_role_permission_bindings AS binding
            SET state='revoked',revision=binding.revision+1,
                updated_at=p_completed_at,revoked_at=p_completed_at
            WHERE binding.id=v_binding_id AND binding.state='active'
              AND NOT EXISTS (
                  SELECT 1
                  FROM iam_catalog_version_operational_grants AS other
                  JOIN iam_catalog_component_heads AS other_head
                    ON other_head.component_id=other.component_id
                   AND other_head.package_id=other.package_id
                   AND other_head.package_version=other.package_version
                   AND other_head.release_id=other.release_id
                   AND other_head.owner_generation=other.owner_generation
                   AND other_head.content_sha256=other.content_sha256
                  JOIN iam_catalog_components AS other_component
                    ON other_component.component_id=other.component_id
                  WHERE other.binding_id=v_binding_id
                    AND other.component_id<>p_component_id
                    AND other_component.lifecycle_state='ACTIVE'
              );
        END IF;
        GET DIAGNOSTICS v_step=ROW_COUNT;
        v_changed:=v_changed+v_step;
    END LOOP;
    IF p_enable AND EXISTS (
        SELECT 1
        FROM iam_catalog_version_operational_grants AS mapped
        JOIN iam_catalog_component_heads AS head
          ON head.component_id=mapped.component_id
         AND head.package_id=mapped.package_id
         AND head.package_version=mapped.package_version
         AND head.release_id=mapped.release_id
         AND head.owner_generation=mapped.owner_generation
         AND head.content_sha256=mapped.content_sha256
        JOIN iam_role_permission_bindings AS binding
          ON binding.id=mapped.binding_id
        WHERE mapped.component_id=p_component_id
          AND binding.state<>'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog grants could not be activated';
    END IF;
    RETURN v_changed;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_grants_set_v2(p_component_id uuid, p_enable boolean, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_materialize_v1(uuid, text, text, uuid, uuid, bigint, text, text, text, text, bytea, bytea, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_materialize_v1(p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_sha256 bytea, p_document_bytes bytea, p_document jsonb, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_component iam_catalog_components%ROWTYPE;
    v_materialization iam_catalog_materializations%ROWTYPE;
BEGIN
    SELECT * INTO v_component
    FROM iam_catalog_components AS component
    WHERE component.component_id = p_component_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO iam_catalog_components(
            component_id, component_kind, contract, content_sha256,
            owner_generation, writer_state, lifecycle_state, updated_at
        ) VALUES (
            p_component_id, p_component_kind, p_contract, p_content_sha256,
            p_owner_generation, 'v2', 'AVAILABLE', p_occurred_at
        );
    ELSIF ROW(v_component.component_kind, v_component.contract,
              v_component.content_sha256, v_component.owner_generation,
              v_component.writer_state)
          IS DISTINCT FROM
          ROW(p_component_kind, p_contract, p_content_sha256,
              p_owner_generation, 'v2'::text) OR
          v_component.lifecycle_state NOT IN ('AVAILABLE','STAGED') THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog component authority differs';
    END IF;
    SELECT * INTO v_materialization
    FROM iam_catalog_materializations AS materialization
    WHERE materialization.component_id = p_component_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO iam_catalog_materializations(
            component_id, module_slug, content_sha256, semantic_sha256,
            document_bytes, package_id, package_slug,
            package_version, release_id, installed_at
        ) VALUES (
            p_component_id, p_module_slug, p_content_sha256,
            p_semantic_sha256, p_document_bytes, p_package_id,
            p_package_slug, p_package_version, p_release_id, p_occurred_at
        );
        INSERT INTO iam_catalog_resource_projections(
            component_id, resource_slug, resource_kind, name, description
        )
        SELECT p_component_id, resource.slug, resource.kind,
            resource.name, resource.description
        FROM jsonb_to_recordset(p_document->'resources')
            AS resource(slug text, kind text, name text, description text);
        INSERT INTO iam_catalog_grant_projections(
            component_id, resource_slug, role_name, role_description, actions
        )
        SELECT p_component_id, permission.resource_slug, permission.role_name,
            permission.role_description,
            ARRAY(SELECT jsonb_array_elements_text(permission.actions))
        FROM jsonb_to_recordset(p_document->'grants')
            AS permission(
                resource_slug text, role_name text,
                role_description text, actions jsonb
            );
    ELSIF ROW(v_materialization.module_slug,
              v_materialization.content_sha256,
              v_materialization.semantic_sha256,
              v_materialization.document_bytes)
          IS DISTINCT FROM
          ROW(p_module_slug, p_content_sha256,
              p_semantic_sha256, p_document_bytes) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog semantic projection differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_materialize_v1(p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_sha256 bytea, p_document_bytes bytea, p_document jsonb, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_materialize_v2(uuid, text, text, uuid, uuid, bigint, text, text, text, text, text, bytea, integer, integer, bytea, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_materialize_v2(p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_document jsonb, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_component iam_catalog_components%ROWTYPE;
    v_evidence iam_catalog_version_evidence%ROWTYPE;
    v_has_head boolean;
BEGIN
    SELECT * INTO v_component
    FROM iam_catalog_components AS component
    WHERE component.component_id=p_component_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO iam_catalog_components(
            component_id,component_kind,contract,content_sha256,
            owner_generation,writer_state,lifecycle_state,updated_at
        ) VALUES (
            p_component_id,p_component_kind,p_contract,p_content_sha256,
            p_owner_generation,'v2','AVAILABLE',p_occurred_at
        ) RETURNING * INTO v_component;
    ELSIF ROW(
              v_component.component_kind,v_component.contract,
              v_component.owner_generation,v_component.writer_state
          ) IS DISTINCT FROM ROW(
              p_component_kind,p_contract,p_owner_generation,'v2'::text
          ) OR v_component.lifecycle_state NOT IN (
              'AVAILABLE','STAGED','ACTIVE','DISABLED'
          ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog component authority differs';
    END IF;
    SELECT EXISTS(
        SELECT 1 FROM iam_catalog_component_heads AS head
        WHERE head.component_id=p_component_id
    ) INTO v_has_head;
    IF v_has_head AND NOT EXISTS (
        SELECT 1 FROM iam_catalog_component_heads AS head
        WHERE head.component_id=p_component_id
          AND head.owner_generation=v_component.owner_generation
          AND head.content_sha256=v_component.content_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog active head differs';
    ELSIF NOT v_has_head AND v_component.lifecycle_state='STAGED'
          AND v_component.content_sha256<>p_content_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog staged component differs';
    ELSIF NOT v_has_head AND v_component.lifecycle_state='AVAILABLE'
          AND v_component.content_sha256<>p_content_sha256 THEN
        UPDATE iam_catalog_components
        SET content_sha256=p_content_sha256,updated_at=p_occurred_at
        WHERE component_id=p_component_id;
    END IF;
    IF EXISTS (
        SELECT 1 FROM iam_catalog_version_evidence AS prior
        WHERE prior.component_id=p_component_id
          AND prior.package_id<>p_package_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog component package differs';
    END IF;
    SELECT * INTO v_evidence
    FROM iam_catalog_version_evidence AS evidence
    WHERE evidence.package_id=p_package_id
      AND evidence.package_version=p_package_version
      AND evidence.component_id=p_component_id
    FOR SHARE;
    IF NOT FOUND THEN
        INSERT INTO iam_catalog_version_evidence(
            component_id,package_id,package_slug,package_version,
            release_id,owner_generation,contract,content_sha256,
            component_kind,module_slug,semantic_identity,semantic_sha256,
            item_count,auxiliary_count,document_bytes,installed_at
        ) VALUES (
            p_component_id,p_package_id,p_package_slug,p_package_version,
            p_release_id,p_owner_generation,p_contract,p_content_sha256,
            p_component_kind,p_module_slug,p_semantic_identity,
            p_semantic_sha256,p_item_count,p_auxiliary_count,
            p_document_bytes,p_occurred_at
        );
        INSERT INTO iam_catalog_version_resources(
            component_id,package_id,package_version,release_id,
            owner_generation,content_sha256,resource_slug,
            resource_kind,name,description
        )
        SELECT p_component_id,p_package_id,p_package_version,p_release_id,
            p_owner_generation,p_content_sha256,resource.slug,
            resource.kind,resource.name,resource.description
        FROM pg_catalog.jsonb_to_recordset(p_document->'resources')
            AS resource(slug text,kind text,name text,description text);
        INSERT INTO iam_catalog_version_grants(
            component_id,package_id,package_version,release_id,
            owner_generation,content_sha256,resource_slug,
            role_name,role_description,actions
        )
        SELECT p_component_id,p_package_id,p_package_version,p_release_id,
            p_owner_generation,p_content_sha256,grant_row.resource_slug,
            grant_row.role_name,grant_row.role_description,
            ARRAY(SELECT pg_catalog.jsonb_array_elements_text(grant_row.actions))
        FROM pg_catalog.jsonb_to_recordset(p_document->'grants')
            AS grant_row(
                resource_slug text,role_name text,
                role_description text,actions jsonb
            );
    ELSIF ROW(
              v_evidence.package_slug,v_evidence.release_id,
              v_evidence.owner_generation,v_evidence.contract,
              v_evidence.content_sha256,v_evidence.component_kind,
              v_evidence.module_slug,v_evidence.semantic_identity,
              v_evidence.semantic_sha256,v_evidence.item_count,
              v_evidence.auxiliary_count,v_evidence.document_bytes
          ) IS DISTINCT FROM ROW(
              p_package_slug,p_release_id,p_owner_generation,p_contract,
              p_content_sha256,p_component_kind,p_module_slug,
              p_semantic_identity,p_semantic_sha256,p_item_count,
              p_auxiliary_count,p_document_bytes
          ) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog version evidence differs';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_materialize_v2(p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_document jsonb, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_action_v1(text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_action_v1(p_action_key text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_action iam_actions%ROWTYPE;
BEGIN
    SELECT * INTO v_action FROM iam_actions AS action
    WHERE action.action_key=p_action_key FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO iam_actions(
            id,action_key,display_name,description,is_protected,
            state,revision,created_at,updated_at
        ) VALUES (
            pg_catalog.uuidv7(),p_action_key,p_action_key,
            'First-party module catalog action',false,
            'active',1,p_occurred_at,p_occurred_at
        ) RETURNING * INTO v_action;
    ELSIF v_action.state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog operational action differs';
    END IF;
    RETURN v_action.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_action_v1(p_action_key text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_activate_v2(name, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_activate_v2(p_scope_schema name, p_provision_receipt_id uuid, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_provision iam_catalog_version_provisions%ROWTYPE;
    v_resource iam_catalog_version_resources%ROWTYPE;
    v_grant iam_catalog_version_grants%ROWTYPE;
    v_action_key text;
    v_resource_id uuid;
    v_role_id uuid;
    v_action_id uuid;
    v_permission_id uuid;
    v_binding iam_role_permission_bindings%ROWTYPE;
    v_clock bigint;
BEGIN
    SELECT * INTO v_provision
    FROM iam_catalog_version_provisions AS provision
    WHERE provision.receipt_id=p_provision_receipt_id
    FOR SHARE;
    IF NOT FOUND OR p_scope_schema IS DISTINCT FROM (
           SELECT identity_row.schema_name::name
           FROM tenancy_schema_identity AS identity_row
           WHERE identity_row.singleton
       ) OR p_occurred_at IS NULL OR
       NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog version activation input is invalid';
    END IF;
    FOR v_resource IN
        SELECT resource.*
        FROM iam_catalog_version_resources AS resource
        WHERE resource.component_id=v_provision.component_id
          AND resource.package_id=v_provision.package_id
          AND resource.package_version=v_provision.package_version
          AND resource.release_id=v_provision.release_id
          AND resource.owner_generation=v_provision.owner_generation
          AND resource.content_sha256=v_provision.content_sha256
        ORDER BY resource.resource_slug
    LOOP
        v_resource_id := iam_catalog_operational_resource_v2(
            v_provision.component_id,v_provision.package_id,
            v_provision.package_version,v_provision.release_id,
            v_provision.owner_generation,v_provision.content_sha256,
            v_resource.resource_slug,v_resource.resource_kind,
            v_resource.name,v_resource.description,p_occurred_at
        );
    END LOOP;
    FOR v_grant IN
        SELECT grant_row.*
        FROM iam_catalog_version_grants AS grant_row
        WHERE grant_row.component_id=v_provision.component_id
          AND grant_row.package_id=v_provision.package_id
          AND grant_row.package_version=v_provision.package_version
          AND grant_row.release_id=v_provision.release_id
          AND grant_row.owner_generation=v_provision.owner_generation
          AND grant_row.content_sha256=v_provision.content_sha256
        ORDER BY grant_row.resource_slug,grant_row.role_name
    LOOP
        SELECT projected.resource_id INTO STRICT v_resource_id
        FROM iam_catalog_version_operational_resources AS projected
        WHERE projected.component_id=v_provision.component_id
          AND projected.package_id=v_provision.package_id
          AND projected.package_version=v_provision.package_version
          AND projected.release_id=v_provision.release_id
          AND projected.owner_generation=v_provision.owner_generation
          AND projected.content_sha256=v_provision.content_sha256
          AND projected.resource_slug=v_grant.resource_slug;
        v_role_id := iam_catalog_operational_role_v2(
            p_scope_schema,v_grant.role_name,
            v_grant.role_description,p_occurred_at
        );
        FOREACH v_action_key IN ARRAY v_grant.actions
        LOOP
            v_action_id := iam_catalog_operational_action_v1(
                v_action_key,p_occurred_at
            );
            v_permission_id := iam_catalog_operational_permission_v1(
                v_resource_id,v_action_id,p_occurred_at
            );
            SELECT * INTO v_binding
            FROM iam_role_permission_bindings AS binding
            WHERE binding.role_id=v_role_id
              AND binding.permission_id=v_permission_id
            FOR UPDATE;
            IF NOT FOUND THEN
                INSERT INTO iam_role_permission_bindings(
                    id,role_id,role_is_protected,permission_id,
                    permission_match_kind,state,revision,created_at,
                    updated_at,activated_at
                ) VALUES (
                    pg_catalog.uuidv7(),v_role_id,false,v_permission_id,
                    'exact','active',1,p_occurred_at,
                    p_occurred_at,p_occurred_at
                ) RETURNING * INTO v_binding;
            ELSIF v_binding.state='revoked' THEN
                UPDATE iam_role_permission_bindings
                SET state='active',revision=revision+1,
                    updated_at=p_occurred_at,activated_at=p_occurred_at,
                    revoked_at=NULL
                WHERE id=v_binding.id
                RETURNING * INTO v_binding;
            ELSIF v_binding.state<>'active' THEN
                RAISE EXCEPTION USING ERRCODE='23505',
                    MESSAGE='IAM catalog version binding differs';
            END IF;
            INSERT INTO iam_catalog_version_operational_grants(
                component_id,package_id,package_version,release_id,
                owner_generation,content_sha256,resource_slug,
                role_name,action_key,role_id,resource_id,action_id,
                permission_id,binding_id
            ) VALUES (
                v_provision.component_id,v_provision.package_id,
                v_provision.package_version,v_provision.release_id,
                v_provision.owner_generation,v_provision.content_sha256,
                v_grant.resource_slug,v_grant.role_name,v_action_key,
                v_role_id,v_resource_id,v_action_id,
                v_permission_id,v_binding.id
            ) ON CONFLICT DO NOTHING;
            IF NOT EXISTS (
                SELECT 1
                FROM iam_catalog_version_operational_grants AS projected
                WHERE projected.component_id=v_provision.component_id
                  AND projected.package_id=v_provision.package_id
                  AND projected.package_version=v_provision.package_version
                  AND projected.release_id=v_provision.release_id
                  AND projected.owner_generation=v_provision.owner_generation
                  AND projected.content_sha256=v_provision.content_sha256
                  AND projected.resource_slug=v_grant.resource_slug
                  AND projected.role_name=v_grant.role_name
                  AND projected.action_key=v_action_key
                  AND projected.role_id=v_role_id
                  AND projected.resource_id=v_resource_id
                  AND projected.action_id=v_action_id
                  AND projected.permission_id=v_permission_id
                  AND projected.binding_id=v_binding.id
            ) THEN
                RAISE EXCEPTION USING ERRCODE='23505',
                    MESSAGE='IAM catalog version grant mapping differs';
            END IF;
        END LOOP;
    END LOOP;
    IF NOT iam_catalog_operational_readback_v2(
        v_provision.component_id,v_provision.package_id,
        v_provision.package_version,v_provision.release_id,
        v_provision.owner_generation,v_provision.content_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog version operational readback differs';
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value=clock_value+1,revision=revision+1,
        updated_at=GREATEST(updated_at,p_occurred_at)
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM authorization clock is unavailable';
    END IF;
    PERFORM iam_rbac_bump_all_users_v1(v_clock);
    INSERT INTO iam_authorization_operation_receipts(
        operation_id,command_key,request_sha256,clock_value,
        result_code,result_id,result_revision,result_sha256,created_at
    ) VALUES (
        v_provision.receipt_id,'iam.catalog.activate',
        v_provision.semantic_sha256,v_clock,'iam.catalog.activated',
        v_provision.component_id,1,
        v_provision.semantic_sha256,p_occurred_at
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_activate_v2(p_scope_schema name, p_provision_receipt_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_materialize_v1(name, uuid, jsonb, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_materialize_v1(p_scope_schema name, p_component_id uuid, p_document jsonb, p_semantic_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_resource_slug text;
    v_resource_kind text;
    v_resource_name text;
    v_resource_description text;
    v_grant_resource_slug text;
    v_grant_role_name text;
    v_grant_role_description text;
    v_grant_actions jsonb;
    v_action_key text;
    v_resource_id uuid;
    v_role_id uuid;
    v_action_id uuid;
    v_permission_id uuid;
    v_binding iam_role_permission_bindings%ROWTYPE;
    v_clock bigint;
    v_count bigint;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM iam_catalog_materializations AS materialization
        WHERE materialization.component_id=p_component_id
          AND materialization.semantic_sha256=p_semantic_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog projection prerequisite differs';
    END IF;
    FOR v_resource_slug,v_resource_kind,
        v_resource_name,v_resource_description IN
        SELECT resource.slug,resource.kind,resource.name,resource.description
        FROM pg_catalog.jsonb_to_recordset(p_document->'resources')
            AS resource(slug text,kind text,name text,description text)
    LOOP
        v_resource_id := iam_catalog_operational_resource_v1(
            p_component_id,v_resource_slug,v_resource_kind,
            v_resource_name,v_resource_description,p_occurred_at
        );
    END LOOP;
    FOR v_grant_resource_slug,v_grant_role_name,
        v_grant_role_description,v_grant_actions IN
        SELECT grant_row.resource_slug,grant_row.role_name,
               grant_row.role_description,grant_row.actions
        FROM pg_catalog.jsonb_to_recordset(p_document->'grants')
            AS grant_row(
                resource_slug text,role_name text,
                role_description text,actions jsonb
            )
    LOOP
        SELECT resource.resource_id INTO STRICT v_resource_id
        FROM iam_catalog_operational_resources AS resource
        WHERE resource.component_id=p_component_id
          AND resource.resource_slug=v_grant_resource_slug;
        v_role_id := iam_catalog_operational_role_v1(
            p_scope_schema,v_grant_role_name,
            v_grant_role_description,p_occurred_at
        );
        FOR v_action_key IN
            SELECT pg_catalog.jsonb_array_elements_text(v_grant_actions)
        LOOP
            v_action_id := iam_catalog_operational_action_v1(
                v_action_key,p_occurred_at
            );
            v_permission_id := iam_catalog_operational_permission_v1(
                v_resource_id,v_action_id,p_occurred_at
            );
            SELECT * INTO v_binding
            FROM iam_role_permission_bindings AS binding
            WHERE binding.role_id=v_role_id
              AND binding.permission_id=v_permission_id
            FOR UPDATE;
            IF NOT FOUND THEN
                INSERT INTO iam_role_permission_bindings(
                    id,role_id,role_is_protected,permission_id,
                    permission_match_kind,state,revision,created_at,
                    updated_at,activated_at
                ) VALUES (
                    pg_catalog.uuidv7(),v_role_id,false,v_permission_id,
                    'exact','active',1,p_occurred_at,
                    p_occurred_at,p_occurred_at
                ) RETURNING * INTO v_binding;
            ELSIF v_binding.state='revoked' THEN
                UPDATE iam_role_permission_bindings
                SET state='active',revision=revision+1,
                    updated_at=p_occurred_at,activated_at=p_occurred_at,
                    revoked_at=NULL
                WHERE id=v_binding.id
                RETURNING * INTO v_binding;
            ELSIF v_binding.state IS DISTINCT FROM 'active' THEN
                RAISE EXCEPTION USING ERRCODE='23505',
                    MESSAGE='IAM catalog operational binding differs';
            END IF;
            INSERT INTO iam_catalog_operational_grants(
                component_id,resource_slug,role_name,action_key,
                role_id,resource_id,action_id,permission_id,binding_id
            ) VALUES (
                p_component_id,v_grant_resource_slug,v_grant_role_name,
                v_action_key,v_role_id,v_resource_id,v_action_id,
                v_permission_id,v_binding.id
            );
        END LOOP;
    END LOOP;
    UPDATE iam_authorization_clock
    SET clock_value=clock_value+1,revision=revision+1,
        updated_at=GREATEST(updated_at,p_occurred_at)
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM authorization clock is unavailable';
    END IF;
    v_count := iam_rbac_bump_all_users_v1(v_clock);
    INSERT INTO iam_authorization_operation_receipts(
        operation_id,command_key,request_sha256,clock_value,
        result_code,result_id,result_revision,result_sha256,created_at
    ) VALUES (
        p_component_id,'iam.catalog.materialize',p_semantic_sha256,
        v_clock,'iam.catalog.materialized',p_component_id,1,
        p_semantic_sha256,p_occurred_at
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_materialize_v1(p_scope_schema name, p_component_id uuid, p_document jsonb, p_semantic_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_permission_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_permission_v1(p_resource_id uuid, p_action_id uuid, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_permission iam_permissions%ROWTYPE;
BEGIN
    SELECT * INTO v_permission FROM iam_permissions AS permission
    WHERE permission.match_kind='exact'
      AND permission.resource_id=p_resource_id
      AND permission.action_id=p_action_id
    FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO iam_permissions(
            id,match_kind,resource_id,action_id,is_protected,
            state,revision,created_at,updated_at
        ) VALUES (
            pg_catalog.uuidv7(),'exact',p_resource_id,p_action_id,
            false,'active',1,p_occurred_at,p_occurred_at
        ) RETURNING * INTO v_permission;
    ELSIF v_permission.state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog operational permission differs';
    END IF;
    RETURN v_permission.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_permission_v1(p_resource_id uuid, p_action_id uuid, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_readback_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_readback_v1(p_component_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_expected_resources bigint;
    v_expected_grants bigint;
    v_actual_resources bigint;
    v_actual_grants bigint;
    v_invalid bigint;
BEGIN
    SELECT pg_catalog.count(*) INTO v_expected_resources
    FROM iam_catalog_resource_projections AS resource
    WHERE resource.component_id=p_component_id;
    SELECT COALESCE(pg_catalog.sum(cardinality(grant_row.actions)),0)
    INTO v_expected_grants
    FROM iam_catalog_grant_projections AS grant_row
    WHERE grant_row.component_id=p_component_id;
    SELECT pg_catalog.count(*) INTO v_actual_resources
    FROM iam_catalog_operational_resources AS resource
    WHERE resource.component_id=p_component_id;
    SELECT pg_catalog.count(*) INTO v_actual_grants
    FROM iam_catalog_operational_grants AS grant_row
    WHERE grant_row.component_id=p_component_id;
    IF v_expected_resources < 2 OR v_expected_grants < 1 OR
       v_actual_resources <> v_expected_resources OR
       v_actual_grants <> v_expected_grants THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.count(*) INTO v_invalid
    FROM iam_catalog_operational_resources AS projected
    JOIN iam_catalog_resource_projections AS source
      ON source.component_id=projected.component_id
     AND source.resource_slug=projected.resource_slug
    JOIN iam_resources AS resource ON resource.id=projected.resource_id
    WHERE projected.component_id=p_component_id
      AND ROW(resource.resource_key,resource.resource_kind,
              resource.display_name,COALESCE(resource.description,''),
              resource.is_protected,resource.state)
          IS DISTINCT FROM
          ROW(source.resource_slug,source.resource_kind,
              source.name,source.description,false,'active'::text);
    IF v_invalid <> 0 THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.count(*) INTO v_invalid
    FROM iam_catalog_operational_grants AS projected
    JOIN iam_roles AS role ON role.id=projected.role_id
    JOIN iam_resources AS resource ON resource.id=projected.resource_id
    JOIN iam_actions AS action ON action.id=projected.action_id
    JOIN iam_permissions AS permission ON permission.id=projected.permission_id
    JOIN iam_role_permission_bindings AS binding
      ON binding.id=projected.binding_id
    WHERE projected.component_id=p_component_id
      AND (
        role.name IS DISTINCT FROM projected.role_name OR
        role.status IS DISTINCT FROM 'active' OR
        role.is_protected IS DISTINCT FROM false OR
        resource.resource_key IS DISTINCT FROM projected.resource_slug OR
        resource.state IS DISTINCT FROM 'active' OR
        action.action_key IS DISTINCT FROM projected.action_key OR
        action.state IS DISTINCT FROM 'active' OR
        permission.match_kind IS DISTINCT FROM 'exact' OR
        permission.resource_id IS DISTINCT FROM projected.resource_id OR
        permission.action_id IS DISTINCT FROM projected.action_id OR
        permission.state IS DISTINCT FROM 'active' OR
        binding.role_id IS DISTINCT FROM projected.role_id OR
        binding.permission_id IS DISTINCT FROM projected.permission_id OR
        binding.permission_match_kind IS DISTINCT FROM 'exact' OR
        binding.state IS DISTINCT FROM 'active'
      );
    RETURN v_invalid=0;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_readback_v1(p_component_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_readback_v2(uuid, uuid, text, uuid, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_readback_v2(p_component_id uuid, p_package_id uuid, p_package_version text, p_release_id uuid, p_owner_generation bigint, p_content_sha256 text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_expected_resources bigint;
    v_expected_grants bigint;
    v_actual_resources bigint;
    v_actual_grants bigint;
    v_invalid bigint;
BEGIN
    SELECT pg_catalog.count(*) INTO v_expected_resources
    FROM iam_catalog_version_resources AS resource
    WHERE resource.component_id=p_component_id
      AND resource.package_id=p_package_id
      AND resource.package_version=p_package_version
      AND resource.release_id=p_release_id
      AND resource.owner_generation=p_owner_generation
      AND resource.content_sha256=p_content_sha256;
    SELECT COALESCE(pg_catalog.sum(cardinality(grant_row.actions)),0)
    INTO v_expected_grants
    FROM iam_catalog_version_grants AS grant_row
    WHERE grant_row.component_id=p_component_id
      AND grant_row.package_id=p_package_id
      AND grant_row.package_version=p_package_version
      AND grant_row.release_id=p_release_id
      AND grant_row.owner_generation=p_owner_generation
      AND grant_row.content_sha256=p_content_sha256;
    SELECT pg_catalog.count(*) INTO v_actual_resources
    FROM iam_catalog_version_operational_resources AS resource
    WHERE resource.component_id=p_component_id
      AND resource.package_id=p_package_id
      AND resource.package_version=p_package_version
      AND resource.release_id=p_release_id
      AND resource.owner_generation=p_owner_generation
      AND resource.content_sha256=p_content_sha256;
    SELECT pg_catalog.count(*) INTO v_actual_grants
    FROM iam_catalog_version_operational_grants AS grant_row
    WHERE grant_row.component_id=p_component_id
      AND grant_row.package_id=p_package_id
      AND grant_row.package_version=p_package_version
      AND grant_row.release_id=p_release_id
      AND grant_row.owner_generation=p_owner_generation
      AND grant_row.content_sha256=p_content_sha256;
    IF v_expected_resources<2 OR v_expected_grants<1 OR
       v_actual_resources<>v_expected_resources OR
       v_actual_grants<>v_expected_grants THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.count(*) INTO v_invalid
    FROM iam_catalog_version_operational_resources AS projected
    JOIN iam_catalog_version_resources AS source
      ON source.component_id=projected.component_id
     AND source.package_id=projected.package_id
     AND source.package_version=projected.package_version
     AND source.release_id=projected.release_id
     AND source.owner_generation=projected.owner_generation
     AND source.content_sha256=projected.content_sha256
     AND source.resource_slug=projected.resource_slug
    JOIN iam_resources AS resource ON resource.id=projected.resource_id
    WHERE projected.component_id=p_component_id
      AND projected.package_id=p_package_id
      AND projected.package_version=p_package_version
      AND projected.release_id=p_release_id
      AND projected.owner_generation=p_owner_generation
      AND projected.content_sha256=p_content_sha256
      AND ROW(
        resource.resource_key,resource.resource_kind,
        resource.display_name,COALESCE(resource.description,''),
        resource.is_protected,resource.state
      ) IS DISTINCT FROM ROW(
        source.resource_slug,source.resource_kind,
        source.name,source.description,false,'active'::text
      );
    IF v_invalid<>0 THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.count(*) INTO v_invalid
    FROM iam_catalog_version_operational_grants AS projected
    JOIN iam_catalog_version_grants AS source
      ON source.component_id=projected.component_id
     AND source.package_id=projected.package_id
     AND source.package_version=projected.package_version
     AND source.release_id=projected.release_id
     AND source.owner_generation=projected.owner_generation
     AND source.content_sha256=projected.content_sha256
     AND source.resource_slug=projected.resource_slug
     AND source.role_name=projected.role_name
    JOIN iam_roles AS role ON role.id=projected.role_id
    JOIN iam_resources AS resource ON resource.id=projected.resource_id
    JOIN iam_actions AS action ON action.id=projected.action_id
    JOIN iam_permissions AS permission ON permission.id=projected.permission_id
    JOIN iam_role_permission_bindings AS binding ON binding.id=projected.binding_id
    WHERE projected.component_id=p_component_id
      AND projected.package_id=p_package_id
      AND projected.package_version=p_package_version
      AND projected.release_id=p_release_id
      AND projected.owner_generation=p_owner_generation
      AND projected.content_sha256=p_content_sha256
      AND (
        NOT projected.action_key=ANY(source.actions) OR
        role.name IS DISTINCT FROM projected.role_name OR
        role.status<>'active' OR role.is_protected OR
        resource.resource_key IS DISTINCT FROM projected.resource_slug OR
        resource.state<>'active' OR
        action.action_key IS DISTINCT FROM projected.action_key OR
        action.state<>'active' OR permission.match_kind<>'exact' OR
        permission.resource_id IS DISTINCT FROM projected.resource_id OR
        permission.action_id IS DISTINCT FROM projected.action_id OR
        permission.state<>'active' OR
        binding.role_id IS DISTINCT FROM projected.role_id OR
        binding.permission_id IS DISTINCT FROM projected.permission_id OR
        binding.permission_match_kind<>'exact' OR binding.state<>'active'
      );
    RETURN v_invalid=0;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_readback_v2(p_component_id uuid, p_package_id uuid, p_package_version text, p_release_id uuid, p_owner_generation bigint, p_content_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_resource_v1(uuid, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_resource_v1(p_component_id uuid, p_resource_slug text, p_resource_kind text, p_name text, p_description text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_resource iam_resources%ROWTYPE;
    v_owner_domain text;
BEGIN
    v_owner_domain := CASE p_resource_kind
        WHEN 'form' THEN 'forms'
        WHEN 'workflow' THEN 'workflow'
        WHEN 'module' THEN 'catalog'
        ELSE NULL
    END;
    IF v_owner_domain IS NULL OR p_resource_slug IS NULL OR
       p_name IS NULL OR p_description IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog resource input is invalid';
    END IF;
    SELECT * INTO v_resource FROM iam_resources AS resource
    WHERE resource.resource_key=p_resource_slug FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO iam_resources(
            id,resource_key,owner_domain,resource_kind,display_name,
            description,is_protected,state,revision,created_at,updated_at
        ) VALUES (
            pg_catalog.uuidv7(),p_resource_slug,v_owner_domain,
            p_resource_kind,p_name,NULLIF(p_description,''),
            false,'active',1,p_occurred_at,p_occurred_at
        ) RETURNING * INTO v_resource;
    ELSIF ROW(v_resource.owner_domain,v_resource.resource_kind,
              v_resource.display_name,COALESCE(v_resource.description,''),
              v_resource.is_protected,v_resource.state)
          IS DISTINCT FROM
          ROW(v_owner_domain,p_resource_kind,p_name,p_description,
              false,'active') THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog operational resource differs';
    END IF;
    INSERT INTO iam_catalog_operational_resources(
        component_id,resource_slug,resource_id
    ) VALUES (p_component_id,p_resource_slug,v_resource.id);
    RETURN v_resource.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_resource_v1(p_component_id uuid, p_resource_slug text, p_resource_kind text, p_name text, p_description text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_resource_v2(uuid, uuid, text, uuid, bigint, text, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_resource_v2(p_component_id uuid, p_package_id uuid, p_package_version text, p_release_id uuid, p_owner_generation bigint, p_content_sha256 text, p_resource_slug text, p_resource_kind text, p_name text, p_description text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_resource iam_resources%ROWTYPE;
    v_owner_domain text;
    v_projected_id uuid;
BEGIN
    v_owner_domain := CASE p_resource_kind
        WHEN 'form' THEN 'forms'
        WHEN 'workflow' THEN 'workflow'
        WHEN 'module' THEN 'catalog'
        ELSE NULL
    END;
    IF v_owner_domain IS NULL OR p_resource_slug IS NULL OR
       p_name IS NULL OR p_description IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog version resource input is invalid';
    END IF;
    SELECT * INTO v_resource FROM iam_resources AS resource
    WHERE resource.resource_key=p_resource_slug FOR UPDATE;
    IF NOT FOUND THEN
        INSERT INTO iam_resources(
            id,resource_key,owner_domain,resource_kind,display_name,
            description,is_protected,state,revision,created_at,updated_at
        ) VALUES (
            pg_catalog.uuidv7(),p_resource_slug,v_owner_domain,
            p_resource_kind,p_name,NULLIF(p_description,''),
            false,'active',1,p_occurred_at,p_occurred_at
        ) RETURNING * INTO v_resource;
    ELSIF ROW(
              v_resource.owner_domain,v_resource.resource_kind,
              v_resource.is_protected,v_resource.state
          ) IS DISTINCT FROM ROW(
              v_owner_domain,p_resource_kind,false,'active'::text
          ) THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog version operational resource differs';
    ELSIF ROW(
              v_resource.display_name,COALESCE(v_resource.description,'')
          ) IS DISTINCT FROM ROW(p_name,p_description) THEN
        UPDATE iam_resources
        SET display_name=p_name,description=NULLIF(p_description,''),
            revision=revision+1,updated_at=p_occurred_at
        WHERE id=v_resource.id
        RETURNING * INTO v_resource;
    END IF;
    INSERT INTO iam_catalog_version_operational_resources(
        component_id,package_id,package_version,release_id,
        owner_generation,content_sha256,resource_slug,resource_id
    ) VALUES (
        p_component_id,p_package_id,p_package_version,p_release_id,
        p_owner_generation,p_content_sha256,p_resource_slug,v_resource.id
    ) ON CONFLICT DO NOTHING;
    SELECT projected.resource_id INTO STRICT v_projected_id
    FROM iam_catalog_version_operational_resources AS projected
    WHERE projected.component_id=p_component_id
      AND projected.package_id=p_package_id
      AND projected.package_version=p_package_version
      AND projected.release_id=p_release_id
      AND projected.owner_generation=p_owner_generation
      AND projected.content_sha256=p_content_sha256
      AND projected.resource_slug=p_resource_slug;
    IF v_projected_id<>v_resource.id THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog version resource mapping differs';
    END IF;
    RETURN v_resource.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_resource_v2(p_component_id uuid, p_package_id uuid, p_package_version text, p_release_id uuid, p_owner_generation bigint, p_content_sha256 text, p_resource_slug text, p_resource_kind text, p_name text, p_description text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_role_v1(name, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_role_v1(p_scope_schema name, p_role_name text, p_role_description text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_schema_id uuid;
    v_role iam_roles%ROWTYPE;
    v_profile jsonb;
BEGIN
    SELECT tenant.id INTO v_tenant_id
    FROM platform.tenants AS tenant
    WHERE tenant.schema_name=p_scope_schema::text
      AND tenant.status='ACTIVE' AND tenant.deleted_at IS NULL;
    SELECT role.id INTO v_schema_id
    FROM iam_profile_schema_versions AS role
    WHERE role.resource_kind='role' AND role.state='active'
    ORDER BY role.version DESC LIMIT 1;
    IF v_tenant_id IS NULL OR v_schema_id IS NULL OR
       p_role_name IS NULL OR p_role_description IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog role prerequisites are unavailable';
    END IF;
    SELECT * INTO v_role FROM iam_roles AS role
    WHERE role.scope_kind='tenant' AND
          role.name_key=pg_catalog.convert_to(p_role_name,'UTF8')
    FOR UPDATE;
    IF NOT FOUND THEN
        v_profile := pg_catalog.jsonb_build_object(
            'display_name',p_role_name
        );
        INSERT INTO iam_roles(
            id,scope_kind,scope_id,organization_id,name,name_key,
            description,status,is_protected,is_default,
            profile_resource_kind,profile_schema_version_id,
            profile_values,profile_sha256,revision,created_at,updated_at
        ) VALUES (
            pg_catalog.uuidv7(),'tenant',v_tenant_id,NULL,
            p_role_name,pg_catalog.convert_to(p_role_name,'UTF8'),
            NULLIF(p_role_description,''),'active',false,false,
            'role',v_schema_id,v_profile,
            pg_catalog.sha256(pg_catalog.convert_to(v_profile::text,'UTF8')),
            1,p_occurred_at,p_occurred_at
        ) RETURNING * INTO v_role;
    ELSIF v_role.status IS DISTINCT FROM 'active' OR
          v_role.is_protected IS DISTINCT FROM false OR
          v_role.scope_id IS DISTINCT FROM v_tenant_id THEN
        RAISE EXCEPTION USING ERRCODE='23505',
            MESSAGE='IAM catalog operational role differs';
    END IF;
    RETURN v_role.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_role_v1(p_scope_schema name, p_role_name text, p_role_description text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_operational_role_v2(name, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_operational_role_v2(p_scope_schema name, p_role_name text, p_role_description text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_role_id uuid;
BEGIN
    v_role_id := iam_catalog_operational_role_v1(
        p_scope_schema,p_role_name,p_role_description,p_occurred_at
    );
    UPDATE iam_roles
    SET description=NULLIF(p_role_description,''),
        revision=revision+1,updated_at=p_occurred_at
    WHERE id=v_role_id
      AND COALESCE(description,'')<>p_role_description;
    RETURN v_role_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_operational_role_v2(p_scope_schema name, p_role_name text, p_role_description text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_project_document_v1(text, uuid, text, text, text, text, text, bytea, integer, integer, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_project_document_v1(p_package_slug text, p_component_id uuid, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_document jsonb;
BEGIN
    IF p_package_slug !~ '^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$' OR
       p_module_slug IS DISTINCT FROM p_package_slug OR
       p_semantic_identity IS DISTINCT FROM p_package_slug OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_contract IS DISTINCT FROM 'iam.catalog-template.v1' OR
       p_content_sha256 !~ '^[0-9a-f]{64}$' OR
       p_component_kind IS DISTINCT FROM 'IAM_TEMPLATE' OR
       octet_length(p_semantic_sha256) IS DISTINCT FROM 32 OR
       p_item_count < 2 OR p_auxiliary_count < 1 OR
       p_document_bytes IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog document input is invalid';
    END IF;
    IF pg_catalog.encode(pg_catalog.sha256(p_document_bytes), 'hex')
           IS DISTINCT FROM p_content_sha256 OR
       p_semantic_sha256 IS DISTINCT FROM pg_catalog.sha256(p_document_bytes) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog document digest differs';
    END IF;
    BEGIN
        v_document := pg_catalog.convert_from(p_document_bytes, 'UTF8')::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog document is invalid';
    END;
    IF jsonb_typeof(v_document) IS DISTINCT FROM 'object' OR
       v_document->>'contract_version' IS DISTINCT FROM p_contract OR
       v_document->>'source_contract'
           IS DISTINCT FROM 'harpy-v1.enterprise-seed.' || p_package_slug OR
       v_document->>'component_id' IS DISTINCT FROM p_component_id::text OR
       v_document->>'module_slug' IS DISTINCT FROM p_package_slug OR
       jsonb_typeof(v_document->'resources') IS DISTINCT FROM 'array' OR
       jsonb_typeof(v_document->'grants') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog document binding differs';
    END IF;
    IF jsonb_array_length(v_document->'resources') <> p_item_count OR
       jsonb_array_length(v_document->'grants') <> p_auxiliary_count OR
       (SELECT count(*) FROM jsonb_to_recordset(v_document->'resources')
            AS resource(slug text, kind text, name text, description text)
        WHERE resource.slug = 'module.' || p_package_slug
          AND resource.kind = 'module') <> 1 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog document composition differs';
    END IF;
    RETURN v_document;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_catalog_project_document_v1(p_package_slug text, p_component_id uuid, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea) OWNER TO harpy_owner;

--
-- Name: iam_catalog_project_v1(name, uuid, uuid, text, text, uuid, uuid, bigint, text, text, text, text, text, bytea, integer, integer, bytea, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_project_v1(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, component_kind text, module_slug text, semantic_identity text, semantic_sha256 bytea, item_count integer, auxiliary_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_document jsonb;
    v_receipt iam_catalog_provisions%ROWTYPE;
BEGIN
    IF p_scope_schema IS DISTINCT FROM (
           SELECT identity_row.schema_name::name
           FROM tenancy_schema_identity AS identity_row
           WHERE identity_row.singleton
       ) OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_package_version IS NULL OR
       p_package_version !~
        '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$' OR
       p_owner_generation<1 OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_idempotency_key !~ '^[A-Za-z0-9_.:-]+$' OR
       octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog projection request is invalid';
    END IF;
    v_document := iam_catalog_project_document_v1(
        p_package_slug,p_component_id,p_contract,p_content_sha256,
        p_component_kind,p_module_slug,p_semantic_identity,
        p_semantic_sha256,p_item_count,p_auxiliary_count,p_document_bytes
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'iam:catalog-project:'||p_component_id::text,6201
    ));
    SELECT * INTO v_receipt FROM iam_catalog_provisions AS provision
    WHERE provision.component_id=p_component_id
      AND provision.idempotency_key=p_idempotency_key
    FOR UPDATE;
    IF FOUND THEN
        IF ROW(v_receipt.package_id,v_receipt.package_slug,
               v_receipt.package_version,v_receipt.release_id,
               v_receipt.owner_generation,v_receipt.contract,
               v_receipt.content_sha256,v_receipt.component_kind,
               v_receipt.module_slug,v_receipt.semantic_identity,
               v_receipt.semantic_sha256,v_receipt.item_count,
               v_receipt.auxiliary_count,v_receipt.request_sha256)
           IS DISTINCT FROM
           ROW(p_package_id,p_package_slug,p_package_version,p_release_id,
               p_owner_generation,p_contract,p_content_sha256,
               p_component_kind,p_module_slug,p_semantic_identity,
               p_semantic_sha256,p_item_count,p_auxiliary_count,
               p_request_sha256) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='IAM catalog projection replay differs';
        END IF;
        RETURN QUERY SELECT * FROM
            iam_catalog_projection_read_v1(v_receipt.receipt_id);
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='IAM catalog replay readback differs';
        END IF;
        RETURN;
    END IF;
    PERFORM iam_catalog_materialize_v1(
        p_package_id,p_package_slug,p_package_version,
        p_release_id,p_component_id,p_owner_generation,
        p_contract,p_content_sha256,p_component_kind,
        p_module_slug,p_semantic_sha256,p_document_bytes,
        v_document,p_occurred_at
    );
    PERFORM iam_catalog_operational_materialize_v1(
        p_scope_schema,p_component_id,v_document,
        p_semantic_sha256,p_occurred_at
    );
    IF NOT iam_catalog_operational_readback_v1(p_component_id) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog operational readback differs';
    END IF;
    INSERT INTO iam_catalog_provisions(
        receipt_id,package_id,package_slug,package_version,release_id,
        component_id,owner_generation,contract,content_sha256,
        component_kind,module_slug,semantic_identity,semantic_sha256,
        item_count,auxiliary_count,idempotency_key,request_sha256,
        ready_at,created_at,updated_at
    ) VALUES (
        p_receipt_id,p_package_id,p_package_slug,p_package_version,
        p_release_id,p_component_id,p_owner_generation,p_contract,
        p_content_sha256,p_component_kind,p_module_slug,
        p_semantic_identity,p_semantic_sha256,p_item_count,
        p_auxiliary_count,p_idempotency_key,p_request_sha256,
        p_occurred_at,p_occurred_at,p_occurred_at
    );
    RETURN QUERY SELECT * FROM iam_catalog_projection_read_v1(p_receipt_id);
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog projection readback differs';
    END IF;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_catalog_project_v1(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_project_v2(name, uuid, uuid, text, text, uuid, uuid, bigint, text, text, text, text, text, bytea, integer, integer, bytea, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_project_v2(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, component_kind text, module_slug text, semantic_identity text, semantic_sha256 bytea, item_count integer, auxiliary_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_document jsonb;
    v_receipt iam_catalog_version_provisions%ROWTYPE;
    v_candidate iam_catalog_component_candidates%ROWTYPE;
BEGIN
    IF p_scope_schema IS DISTINCT FROM (
           SELECT identity_row.schema_name::name
           FROM tenancy_schema_identity AS identity_row
           WHERE identity_row.singleton
       ) OR
       pg_catalog.uuid_extract_version(p_receipt_id) IS DISTINCT FROM 7 OR
       p_package_id IS NULL OR
       p_package_id='00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.uuid_extract_version(p_release_id) IS DISTINCT FROM 7 OR
       p_package_version IS NULL OR
       p_package_version !~
        '^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$' OR
       p_owner_generation<1 OR
       length(p_idempotency_key) NOT BETWEEN 1 AND 128 OR
       p_idempotency_key !~ '^[A-Za-z0-9_.:-]+$' OR
       octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_occurred_at IS NULL OR NOT pg_catalog.isfinite(p_occurred_at) OR
       date_trunc('microseconds',p_occurred_at)<>p_occurred_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM catalog version projection request is invalid';
    END IF;
    v_document := iam_catalog_project_document_v1(
        p_package_slug,p_component_id,p_contract,p_content_sha256,
        p_component_kind,p_module_slug,p_semantic_identity,
        p_semantic_sha256,p_item_count,p_auxiliary_count,p_document_bytes
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'iam:catalog-project:'||p_component_id::text,6201
    ));
    SELECT * INTO v_receipt
    FROM iam_catalog_version_provisions AS provision
    WHERE provision.component_id=p_component_id
      AND provision.idempotency_key=p_idempotency_key
    FOR SHARE;
    IF FOUND THEN
        IF ROW(
              v_receipt.package_id,v_receipt.package_slug,
              v_receipt.package_version,v_receipt.release_id,
              v_receipt.owner_generation,v_receipt.contract,
              v_receipt.content_sha256,v_receipt.component_kind,
              v_receipt.module_slug,v_receipt.semantic_identity,
              v_receipt.semantic_sha256,v_receipt.item_count,
              v_receipt.auxiliary_count,v_receipt.request_sha256
           ) IS DISTINCT FROM ROW(
              p_package_id,p_package_slug,p_package_version,p_release_id,
              p_owner_generation,p_contract,p_content_sha256,
              p_component_kind,p_module_slug,p_semantic_identity,
              p_semantic_sha256,p_item_count,p_auxiliary_count,
              p_request_sha256
           ) THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='IAM catalog version projection replay differs';
        END IF;
        RETURN QUERY
        SELECT * FROM iam_catalog_projection_read_v2(v_receipt.receipt_id);
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='IAM catalog version replay readback differs';
        END IF;
        RETURN;
    END IF;
    PERFORM iam_catalog_materialize_v2(
        p_package_id,p_package_slug,p_package_version,
        p_release_id,p_component_id,p_owner_generation,
        p_contract,p_content_sha256,p_component_kind,
        p_module_slug,p_semantic_identity,p_semantic_sha256,
        p_item_count,p_auxiliary_count,p_document_bytes,
        v_document,p_occurred_at
    );
    SELECT * INTO v_candidate
    FROM iam_catalog_component_candidates AS candidate
    WHERE candidate.component_id=p_component_id
    FOR UPDATE;
    IF FOUND AND ROW(
        v_candidate.package_id,v_candidate.package_version,
        v_candidate.release_id,v_candidate.owner_generation,
        v_candidate.content_sha256
    ) IS DISTINCT FROM ROW(
        p_package_id,p_package_version,p_release_id,
        p_owner_generation,p_content_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog component candidate is unresolved';
    END IF;
    INSERT INTO iam_catalog_version_provisions(
        receipt_id,component_id,package_id,package_slug,package_version,
        release_id,owner_generation,contract,content_sha256,
        component_kind,module_slug,semantic_identity,semantic_sha256,
        item_count,auxiliary_count,idempotency_key,request_sha256,
        ready_at,created_at,updated_at
    ) VALUES (
        p_receipt_id,p_component_id,p_package_id,p_package_slug,
        p_package_version,p_release_id,p_owner_generation,p_contract,
        p_content_sha256,p_component_kind,p_module_slug,
        p_semantic_identity,p_semantic_sha256,p_item_count,
        p_auxiliary_count,p_idempotency_key,p_request_sha256,
        p_occurred_at,p_occurred_at,p_occurred_at
    );
    INSERT INTO iam_catalog_component_candidates(
        component_id,package_id,package_version,release_id,
        owner_generation,content_sha256,provision_receipt_id,staged_at
    ) VALUES (
        p_component_id,p_package_id,p_package_version,p_release_id,
        p_owner_generation,p_content_sha256,p_receipt_id,p_occurred_at
    ) ON CONFLICT ON CONSTRAINT iam_catalog_component_candidates_pkey
      DO UPDATE SET
        provision_receipt_id=EXCLUDED.provision_receipt_id,
        staged_operation_id=NULL,
        staged_at=EXCLUDED.staged_at;
    RETURN QUERY SELECT * FROM iam_catalog_projection_read_v2(p_receipt_id);
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM catalog version projection readback differs';
    END IF;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_catalog_project_v2(p_scope_schema name, p_receipt_id uuid, p_package_id uuid, p_package_slug text, p_package_version text, p_release_id uuid, p_component_id uuid, p_owner_generation bigint, p_contract text, p_content_sha256 text, p_component_kind text, p_module_slug text, p_semantic_identity text, p_semantic_sha256 bytea, p_item_count integer, p_auxiliary_count integer, p_document_bytes bytea, p_idempotency_key text, p_request_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_projection_read_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_projection_read_v1(p_receipt_id uuid) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, component_kind text, module_slug text, semantic_identity text, semantic_sha256 bytea, item_count integer, auxiliary_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT provision.receipt_id,provision.package_id,
        provision.package_slug,provision.package_version,
        provision.release_id,provision.component_id,
        provision.owner_generation,provision.contract,
        provision.content_sha256,provision.component_kind,
        provision.module_slug,provision.semantic_identity,
        provision.semantic_sha256,provision.item_count,
        provision.auxiliary_count,materialization.document_bytes,
        provision.idempotency_key,provision.request_sha256,
        component.lifecycle_state,provision.ready_at,
        provision.created_at,provision.updated_at
    FROM iam_catalog_provisions AS provision
    JOIN iam_catalog_materializations AS materialization
      ON materialization.component_id=provision.component_id
    JOIN iam_catalog_components AS component
      ON component.component_id=provision.component_id
    WHERE provision.receipt_id=p_receipt_id
      AND component.lifecycle_state IN ('AVAILABLE','STAGED')
      AND iam_catalog_operational_readback_v1(provision.component_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_projection_read_v1(p_receipt_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_catalog_projection_read_v2(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_projection_read_v2(p_receipt_id uuid) RETURNS TABLE(receipt_id uuid, package_id uuid, package_slug text, package_version text, release_id uuid, component_id uuid, owner_generation bigint, contract text, content_sha256 text, component_kind text, module_slug text, semantic_identity text, semantic_sha256 bytea, item_count integer, auxiliary_count integer, document_bytes bytea, idempotency_key text, request_sha256 bytea, lifecycle_state text, ready_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT provision.receipt_id,provision.package_id,
        provision.package_slug,provision.package_version,
        provision.release_id,provision.component_id,
        provision.owner_generation,provision.contract,
        provision.content_sha256,provision.component_kind,
        provision.module_slug,provision.semantic_identity,
        provision.semantic_sha256,provision.item_count,
        provision.auxiliary_count,evidence.document_bytes,
        provision.idempotency_key,provision.request_sha256,
        CASE
          WHEN candidate.provision_receipt_id=provision.receipt_id
           AND head.component_id IS NULL
           AND component.lifecycle_state='AVAILABLE' THEN 'AVAILABLE'
          ELSE 'STAGED'
        END,
        provision.ready_at,provision.created_at,provision.updated_at
    FROM iam_catalog_version_provisions AS provision
    JOIN iam_catalog_version_evidence AS evidence
      ON evidence.component_id=provision.component_id
     AND evidence.package_id=provision.package_id
     AND evidence.package_version=provision.package_version
     AND evidence.release_id=provision.release_id
     AND evidence.owner_generation=provision.owner_generation
     AND evidence.content_sha256=provision.content_sha256
    JOIN iam_catalog_components AS component
      ON component.component_id=provision.component_id
    LEFT JOIN iam_catalog_component_candidates AS candidate
      ON candidate.component_id=provision.component_id
    LEFT JOIN iam_catalog_component_heads AS head
      ON head.component_id=provision.component_id
    WHERE provision.receipt_id=p_receipt_id
      AND component.lifecycle_state<>'PURGED';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_projection_read_v2(p_receipt_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_catalog_purge_context_matches_v2(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_purge_context_matches_v2(p_component_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM iam_catalog_purge_contexts AS context
        WHERE context.backend_pid=pg_catalog.pg_backend_pid()
          AND context.transaction_id=pg_catalog.pg_current_xact_id()
          AND context.component_id=p_component_id
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_purge_context_matches_v2(p_component_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_catalog_purge_data_v2(uuid, uuid, bigint, text, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_purge_data_v2(p_operation_id uuid, p_component_id uuid, p_generation bigint, p_content_sha256 text, p_reference_epoch bigint, p_completed_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_component iam_catalog_components%ROWTYPE;
    v_head iam_catalog_component_heads%ROWTYPE;
    v_blockers jsonb;
BEGIN
    IF pg_catalog.uuid_extract_version(p_operation_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_component_id) IS DISTINCT FROM 7 OR
       p_generation<1 OR p_content_sha256!~'^[0-9a-f]{64}$' OR
       p_reference_epoch<1 OR p_completed_at IS NULL OR
       NOT pg_catalog.isfinite(p_completed_at) OR
       date_trunc('microseconds',p_completed_at)<>p_completed_at THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM Catalog purge data input is invalid';
    END IF;
    SELECT * INTO v_component
    FROM iam_catalog_components AS component
    WHERE component.component_id=p_component_id FOR UPDATE;
    SELECT * INTO v_head
    FROM iam_catalog_component_heads AS head
    WHERE head.component_id=p_component_id FOR UPDATE;
    IF v_component.component_id IS NULL OR v_head.component_id IS NULL OR
       v_component.lifecycle_state<>'RETIRED' OR
       v_component.owner_generation<>p_generation OR
       v_component.content_sha256<>p_content_sha256 OR
       v_head.owner_generation<>p_generation OR
       v_head.content_sha256<>p_content_sha256 OR
       p_completed_at<v_component.updated_at THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog purge data authority differs';
    END IF;
    PERFORM permission.id
    FROM iam_permissions AS permission
    WHERE permission.id IN (
            SELECT mapped.permission_id
            FROM iam_catalog_version_operational_grants AS mapped
            WHERE mapped.component_id=p_component_id
        ) OR permission.resource_id IN (
            SELECT mapped.resource_id
            FROM iam_catalog_version_operational_resources AS mapped
            WHERE mapped.component_id=p_component_id
        )
    ORDER BY permission.id FOR UPDATE OF permission;
    PERFORM resource.id
    FROM iam_resources AS resource
    WHERE resource.id IN (
        SELECT mapped.resource_id
        FROM iam_catalog_version_operational_resources AS mapped
        WHERE mapped.component_id=p_component_id
    ) ORDER BY resource.id FOR UPDATE OF resource;
    PERFORM binding.id
    FROM iam_role_permission_bindings AS binding
    WHERE binding.permission_id IN (
        SELECT mapped.permission_id
        FROM iam_catalog_version_operational_grants AS mapped
        WHERE mapped.component_id=p_component_id
    ) ORDER BY binding.id FOR UPDATE OF binding;
    PERFORM binding.id
    FROM iam_user_permission_bindings AS binding
    WHERE binding.permission_id IN (
        SELECT mapped.permission_id
        FROM iam_catalog_version_operational_grants AS mapped
        WHERE mapped.component_id=p_component_id
    ) ORDER BY binding.id FOR UPDATE OF binding;
    PERFORM binding.id
    FROM iam_organization_permission_bindings AS binding
    WHERE binding.permission_id IN (
        SELECT mapped.permission_id
        FROM iam_catalog_version_operational_grants AS mapped
        WHERE mapped.component_id=p_component_id
    ) ORDER BY binding.id FOR UPDATE OF binding;
    SELECT snapshot.blockers INTO STRICT v_blockers
    FROM iam_catalog_blocker_snapshot_v2(
        p_component_id,p_reference_epoch,p_generation
    ) AS snapshot;
    IF v_blockers<>'[]'::jsonb OR EXISTS (
        SELECT 1 FROM iam_permissions AS permission
        WHERE permission.id IN (
            SELECT mapped.permission_id
            FROM iam_catalog_version_operational_grants AS mapped
            WHERE mapped.component_id=p_component_id
        ) AND permission.updated_at>p_completed_at
    ) OR EXISTS (
        SELECT 1 FROM iam_resources AS resource
        WHERE resource.id IN (
            SELECT mapped.resource_id
            FROM iam_catalog_version_operational_resources AS mapped
            WHERE mapped.component_id=p_component_id
        ) AND resource.updated_at>p_completed_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM Catalog purge data is blocked or stale';
    END IF;
    UPDATE iam_permissions AS permission
    SET state='retired',revision=permission.revision+1,
        updated_at=p_completed_at,retired_at=p_completed_at
    WHERE permission.state='active' AND permission.id IN (
        SELECT mapped.permission_id
        FROM iam_catalog_version_operational_grants AS mapped
        WHERE mapped.component_id=p_component_id
    );
    UPDATE iam_resources AS resource
    SET state='retired',revision=resource.revision+1,
        updated_at=p_completed_at,retired_at=p_completed_at
    WHERE resource.state='active' AND resource.id IN (
        SELECT mapped.resource_id
        FROM iam_catalog_version_operational_resources AS mapped
        WHERE mapped.component_id=p_component_id
    );
    INSERT INTO iam_catalog_purge_contexts(
        backend_pid,transaction_id,operation_id,component_id,opened_at
    ) VALUES (
        pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id(),
        p_operation_id,p_component_id,p_completed_at
    );
    DELETE FROM iam_catalog_component_candidates
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_component_heads
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_version_operational_grants
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_version_operational_resources
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_version_provisions
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_version_grants
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_version_resources
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_version_evidence
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_operational_grants
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_operational_resources
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_provisions
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_grant_projections
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_resource_projections
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_materializations
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_component_blockers
    WHERE component_id=p_component_id;
    DELETE FROM iam_catalog_purge_contexts AS context
    WHERE context.backend_pid=pg_catalog.pg_backend_pid()
      AND context.transaction_id=pg_catalog.pg_current_xact_id()
      AND context.component_id=p_component_id;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_catalog_purge_data_v2(p_operation_id uuid, p_component_id uuid, p_generation bigint, p_content_sha256 text, p_reference_epoch bigint, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_catalog_version_evidence_guard_v3(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_version_evidence_guard_v3() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='DELETE' AND
       iam_catalog_purge_context_matches_v2(OLD.component_id) THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='IAM Catalog version evidence is immutable';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_version_evidence_guard_v3() OWNER TO harpy_owner;

--
-- Name: iam_catalog_version_evidence_immutable_v2(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_catalog_version_evidence_immutable_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION USING ERRCODE='55000',
        MESSAGE='IAM catalog version evidence is immutable';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_catalog_version_evidence_immutable_v2() OWNER TO harpy_owner;

--
-- Name: iam_challenge_resolve_v1(name, uuid, bigint, smallint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_challenge_resolve_v1(p_scope_schema name, p_challenge_id uuid, p_expected_revision bigint, p_expected_attempt_count smallint, p_disposition text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_state text;
    v_revision bigint;
    v_attempt_count smallint;
    v_expires_at timestamptz;
    v_next_attempt integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT (
           p_disposition OPERATOR(pg_catalog.=) 'consume' OR
           p_disposition OPERATOR(pg_catalog.=) 'reject' OR
           p_disposition OPERATOR(pg_catalog.=) 'cancel' OR
           p_disposition OPERATOR(pg_catalog.=) 'expire'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM challenge resolution scope or disposition is invalid';
    END IF;
    SELECT challenge.state, challenge.revision,
           challenge.attempt_count, challenge.expires_at
    INTO v_state, v_revision, v_attempt_count, v_expires_at
    FROM iam_auth_challenges AS challenge
    WHERE challenge.id OPERATOR(pg_catalog.=) p_challenge_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM challenge is unknown';
    END IF;
    IF v_state IS DISTINCT FROM 'pending' OR
       v_revision IS DISTINCT FROM p_expected_revision OR
       v_attempt_count IS DISTINCT FROM p_expected_attempt_count THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM challenge resolution CAS is stale';
    END IF;
    IF v_now OPERATOR(pg_catalog.>=) v_expires_at THEN
        UPDATE iam_auth_challenges
        SET state = 'expired', terminal_at = v_now,
            purge_after = v_now OPERATOR(pg_catalog.+) INTERVAL '24 hours',
            updated_at = v_now,
            revision = v_revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_challenge_id;
        RETURN 'expired';
    END IF;
    IF p_disposition OPERATOR(pg_catalog.=) 'expire' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM challenge has not expired';
    END IF;
    IF p_disposition OPERATOR(pg_catalog.=) 'consume' THEN
        UPDATE iam_auth_challenges
        SET state = 'consumed', terminal_at = v_now, updated_at = v_now,
            revision = v_revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_challenge_id;
        RETURN 'consumed';
    END IF;
    IF p_disposition OPERATOR(pg_catalog.=) 'cancel' THEN
        UPDATE iam_auth_challenges
        SET state = 'cancelled', terminal_at = v_now, updated_at = v_now,
            revision = v_revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_challenge_id;
        RETURN 'cancelled';
    END IF;
    v_next_attempt := v_attempt_count OPERATOR(pg_catalog.+) 1;
    IF v_next_attempt OPERATOR(pg_catalog.>=) 5 THEN
        UPDATE iam_auth_challenges
        SET state = 'failed', attempt_count = 5,
            terminal_at = v_now, updated_at = v_now,
            revision = v_revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_challenge_id;
        RETURN 'failed';
    END IF;
    UPDATE iam_auth_challenges
    SET attempt_count = v_next_attempt, updated_at = v_now,
        revision = v_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_challenge_id;
    RETURN 'pending';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_challenge_resolve_v1(p_scope_schema name, p_challenge_id uuid, p_expected_revision bigint, p_expected_attempt_count smallint, p_disposition text) OWNER TO harpy_owner;

--
-- Name: iam_credential_security_epoch_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_credential_security_epoch_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_current bytea;
BEGIN
    v_current := iam_security_epoch_current_v1(pg_catalog.current_schema());
    IF TG_OP = 'INSERT' AND NEW.security_epoch IS DISTINCT FROM v_current THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM credential security epoch is stale';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        NEW.security_epoch IS DISTINCT FROM OLD.security_epoch OR
        (NEW.state IN ('active', 'pending') AND
         NEW.security_epoch IS DISTINCT FROM v_current)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM credential security epoch is stale';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_credential_security_epoch_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_current_session_read_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_current_session_read_v1(p_scope_schema name, p_user_id uuid, p_session_id uuid) RETURNS TABLE(result_user_id uuid, result_session_id uuid, result_client_id text, result_access_mode text, result_portal_binding_id uuid, result_token_version bigint, result_authorization_version bigint, result_permissions text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_user_id IS NULL OR p_session_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM current session caller is invalid';
    END IF;
    RETURN QUERY
    SELECT principal.id, session.id,
           CASE session.access_mode
               WHEN 'operator_console' THEN 'harpy-operator-console-v1'
               WHEN 'portal' THEN 'harpy-portal-v1'
           END,
           session.access_mode, session.portal_binding_id,
           principal.token_version, principal.authorization_version,
           ARRAY(
               SELECT resource.resource_key || '.' || action.action_key
               FROM iam_permissions AS permission
               JOIN iam_resources AS resource ON resource.id = permission.resource_id
               JOIN iam_actions AS action ON action.id = permission.action_id
               WHERE permission.match_kind = 'exact'
                 AND permission.state = 'active'
                 AND resource.state = 'active' AND action.state = 'active'
                 AND iam_user_has_permission_v1(principal.id, permission.id)
               ORDER BY resource.resource_key, action.action_key
           )
    FROM iam_users AS principal
    JOIN iam_sessions AS session ON session.user_id = principal.id
    JOIN iam_user_access_modes AS access
      ON access.id = session.access_mode_id
     AND access.user_id = principal.id AND access.mode = session.access_mode
    LEFT JOIN iam_portal_subject_bindings AS portal
      ON portal.id = session.portal_binding_id
     AND portal.user_id = principal.id AND portal.access_mode_id = access.id
    WHERE principal.id = p_user_id AND session.id = p_session_id
      AND principal.status = 'active' AND principal.identity_kind = 'human'
      AND session.state = 'active'
      AND session.absolute_expires_at > pg_catalog.statement_timestamp()
      AND access.state = 'active'
      AND (
          (session.access_mode = 'operator_console' AND portal.id IS NULL) OR
          (session.access_mode = 'portal' AND portal.state = 'active')
      );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_current_session_read_v1(p_scope_schema name, p_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_current_session_read_v2(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_current_session_read_v2(p_scope_schema name, p_user_id uuid, p_session_id uuid) RETURNS TABLE(result_user_id uuid, result_session_id uuid, result_client_id text, result_access_mode text, result_portal_binding_id uuid, result_token_version bigint, result_authorization_version bigint, result_deployment_mode text, result_tenant_purpose text, result_platform_subject_id uuid, result_platform_clock bigint, result_security_epoch bytea, result_tenant_capabilities text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT session_view.result_user_id, session_view.result_session_id,
           session_view.result_client_id, session_view.result_access_mode,
           session_view.result_portal_binding_id,
           session_view.result_token_version,
           session_view.result_authorization_version,
           context.deployment_mode, context.tenant_purpose, context.subject_id,
           context.platform_clock, session.security_epoch,
           session_view.result_permissions
    FROM iam_current_session_read_v1(p_scope_schema, p_user_id, p_session_id)
         AS session_view
    JOIN iam_sessions AS session ON session.id = session_view.result_session_id
    CROSS JOIN iam_platform_session_context_v1(
        p_scope_schema, session_view.result_user_id,
        session_view.result_token_version,
        session_view.result_authorization_version
    ) AS context
    WHERE session.security_epoch = iam_security_epoch_current_v1(p_scope_schema)
      AND NOT EXISTS (
          SELECT 1
          FROM pg_catalog.unnest(session_view.result_permissions) AS capability(key)
          WHERE capability.key OPERATOR(pg_catalog.~) '^platform\.'
      );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_current_session_read_v2(p_scope_schema name, p_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_current_session_read_v3(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_current_session_read_v3(p_scope_schema name, p_user_id uuid, p_session_id uuid) RETURNS TABLE(result_user_id uuid, result_session_id uuid, result_client_id text, result_access_mode text, result_portal_binding_id uuid, result_token_version bigint, result_authorization_version bigint, result_deployment_mode text, result_tenant_purpose text, result_platform_subject_id uuid, result_platform_clock bigint, result_security_epoch bytea, result_tenant_capabilities text[], result_password_credential_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT session_view.result_user_id, session_view.result_session_id,
           session_view.result_client_id, session_view.result_access_mode,
           session_view.result_portal_binding_id,
           session_view.result_token_version,
           session_view.result_authorization_version,
           session_view.result_deployment_mode,
           session_view.result_tenant_purpose,
           session_view.result_platform_subject_id,
           session_view.result_platform_clock,
           session_view.result_security_epoch,
           session_view.result_tenant_capabilities,
           credential.revision
    FROM iam_current_session_read_v2(p_scope_schema, p_user_id, p_session_id)
         AS session_view
    LEFT JOIN iam_password_credentials AS credential
           ON credential.user_id OPERATOR(pg_catalog.=) session_view.result_user_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_current_session_read_v3(p_scope_schema name, p_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_current_session_read_v4(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_current_session_read_v4(p_scope_schema name, p_user_id uuid, p_session_id uuid) RETURNS TABLE(result_user_id uuid, result_session_id uuid, result_client_id text, result_access_mode text, result_portal_binding_id uuid, result_token_version bigint, result_authorization_version bigint, result_deployment_mode text, result_tenant_purpose text, result_platform_subject_id uuid, result_platform_clock bigint, result_security_epoch bytea, result_tenant_capabilities text[], result_password_credential_revision bigint, result_email text, result_display_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT session_view.result_user_id, session_view.result_session_id,
           session_view.result_client_id, session_view.result_access_mode,
           session_view.result_portal_binding_id,
           session_view.result_token_version,
           session_view.result_authorization_version,
           session_view.result_deployment_mode,
           session_view.result_tenant_purpose,
           session_view.result_platform_subject_id,
           session_view.result_platform_clock,
           session_view.result_security_epoch,
           session_view.result_tenant_capabilities,
           session_view.result_password_credential_revision,
           identifier.display_value,
           COALESCE(
               NULLIF(pg_catalog.btrim(subject.profile_values->>'display_name'), ''),
               identifier.display_value
           )
    FROM iam_current_session_read_v3(p_scope_schema, p_user_id, p_session_id)
         AS session_view
    JOIN iam_users AS subject
      ON subject.id OPERATOR(pg_catalog.=) session_view.result_user_id
     AND subject.status OPERATOR(pg_catalog.=) 'active'
    JOIN iam_user_identifiers AS identifier
      ON identifier.user_id OPERATOR(pg_catalog.=) session_view.result_user_id
     AND identifier.kind OPERATOR(pg_catalog.=) 'email_v1'
     AND identifier.state OPERATOR(pg_catalog.=) 'active';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_current_session_read_v4(p_scope_schema name, p_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_current_session_read_v5(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_current_session_read_v5(p_scope_schema name, p_user_id uuid, p_session_id uuid) RETURNS TABLE(result_user_id uuid, result_session_id uuid, result_client_id text, result_access_mode text, result_portal_binding_id uuid, result_token_version bigint, result_authorization_version bigint, result_deployment_mode text, result_tenant_purpose text, result_platform_subject_id uuid, result_platform_clock bigint, result_security_epoch bytea, result_tenant_capabilities text[], result_password_credential_revision bigint, result_email text, result_display_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT session_view.result_user_id, session_view.result_session_id,
           session_view.result_client_id, session_view.result_access_mode,
           session_view.result_portal_binding_id,
           session_view.result_token_version,
           session_view.result_authorization_version,
           session_view.result_deployment_mode,
           session_view.result_tenant_purpose,
           session_view.result_platform_subject_id,
           session_view.result_platform_clock,
           session_view.result_security_epoch,
           ARRAY(
               SELECT capability
               FROM pg_catalog.unnest(
                   session_view.result_tenant_capabilities
               ) AS capability
               ORDER BY capability COLLATE "C"
           ),
           session_view.result_password_credential_revision,
           session_view.result_email,
           session_view.result_display_name
    FROM iam_current_session_read_v4(p_scope_schema, p_user_id, p_session_id)
         AS session_view;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_current_session_read_v5(p_scope_schema name, p_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_current_session_read_v6(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_current_session_read_v6(p_scope_schema name, p_user_id uuid, p_session_id uuid) RETURNS TABLE(result_user_id uuid, result_session_id uuid, result_client_id text, result_access_mode text, result_portal_binding_id uuid, result_token_version bigint, result_authorization_version bigint, result_deployment_mode text, result_tenant_purpose text, result_platform_subject_id uuid, result_platform_clock bigint, result_security_epoch bytea, result_tenant_capabilities text[], result_password_credential_revision bigint, result_email text, result_display_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_profile_field_id uuid;
    v_display_count bigint;
    v_exact_count bigint;
BEGIN
    SELECT
        pg_catalog.count(*) FILTER (
            WHERE snapshot.field_key = 'display_name'
        ),
        pg_catalog.count(*) FILTER (
            WHERE snapshot.field_key = 'display_name'
              AND snapshot.value_kind = 'string'
              AND snapshot.cardinality = 'single'
              AND snapshot.field_state = 'active'
        )
    INTO v_display_count, v_exact_count
    FROM iam_users AS subject
    LEFT JOIN iam_profile_field_revisions AS snapshot
      ON snapshot.schema_version_id = subject.profile_schema_version_id
     AND snapshot.resource_kind = 'user'
    WHERE subject.id = p_user_id;
    IF v_display_count IS DISTINCT FROM 1
       OR v_exact_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM current session profile snapshot is invalid';
    END IF;
    SELECT snapshot.field_id
    INTO STRICT v_profile_field_id
    FROM iam_users AS subject
    JOIN iam_profile_field_revisions AS snapshot
      ON snapshot.schema_version_id = subject.profile_schema_version_id
     AND snapshot.resource_kind = 'user'
    WHERE subject.id = p_user_id
      AND snapshot.field_key = 'display_name'
      AND snapshot.value_kind = 'string'
      AND snapshot.cardinality = 'single'
      AND snapshot.field_state = 'active';
    RETURN QUERY
    SELECT session_view.result_user_id, session_view.result_session_id,
           session_view.result_client_id, session_view.result_access_mode,
           session_view.result_portal_binding_id,
           session_view.result_token_version,
           session_view.result_authorization_version,
           session_view.result_deployment_mode,
           session_view.result_tenant_purpose,
           session_view.result_platform_subject_id,
           session_view.result_platform_clock,
           session_view.result_security_epoch,
           session_view.result_tenant_capabilities,
           session_view.result_password_credential_revision,
           session_view.result_email,
           COALESCE(
               CASE WHEN pg_catalog.jsonb_typeof(
                        subject.profile_values -> v_profile_field_id::text
                    ) = 'string' THEN NULLIF(pg_catalog.btrim(
                   subject.profile_values ->> v_profile_field_id::text
               ), '') END,
               CASE WHEN subject.profile_sha256 =
                       pg_catalog.sha256(pg_catalog.convert_to(
                           subject.profile_values::text, 'UTF8'
                       ))
                    AND pg_catalog.jsonb_typeof(subject.profile_values) = 'object'
                    AND (SELECT pg_catalog.count(*) FROM
                        pg_catalog.jsonb_object_keys(subject.profile_values)) = 1
                    AND NOT subject.profile_values ? v_profile_field_id::text
                    AND subject.profile_values ? 'display_name'
                    AND pg_catalog.jsonb_typeof(
                        subject.profile_values -> 'display_name'
                    ) = 'string'
                   THEN NULLIF(pg_catalog.btrim(
                       subject.profile_values ->> 'display_name'
                   ), '') END,
               session_view.result_email
           )
    FROM iam_current_session_read_v5(p_scope_schema, p_user_id, p_session_id)
         AS session_view
    JOIN iam_users AS subject
      ON subject.id OPERATOR(pg_catalog.=) session_view.result_user_id
     AND subject.status OPERATOR(pg_catalog.=) 'active';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_current_session_read_v6(p_scope_schema name, p_user_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_email_verification_delivery_target_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_email_verification_delivery_target_v1(p_scope_schema name, p_identifier_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(subject_user_id uuid, resource_id uuid, recipient_identifier_id uuid, recipient_address text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT iam_identity_actor_assert_v1(
           p_scope_schema, p_actor_id, p_permission_id,
           p_expected_token_version, p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM email verification delivery target is denied';
    END IF;
    RETURN QUERY
    SELECT identifier.user_id, identifier.id, identifier.id,
           identifier.normalized_value
    FROM iam_user_identifiers AS identifier
    JOIN iam_users AS subject ON subject.id = identifier.user_id
    WHERE identifier.id = p_identifier_id
      AND identifier.kind = 'email_v1'
      AND identifier.state IN ('pending', 'verified')
      AND subject.status = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM email verification target is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_email_verification_delivery_target_v1(p_scope_schema name, p_identifier_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_email_verification_start_v1(name, uuid, uuid, bytea, uuid, uuid, bytea, text, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_email_verification_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_identifier_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_kind text;
    v_identifier_revision bigint;
    v_issue bigint;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF p_token_id IS NULL OR p_identifier_id IS NULL OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.email_verification.start',
        p_request_sha256, p_token_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT identifier.user_id, identifier.kind, identifier.revision
    INTO v_user_id, v_kind, v_identifier_revision
    FROM iam_user_identifiers AS identifier
    WHERE identifier.id = p_identifier_id AND identifier.kind = 'email_v1'
      AND identifier.state IN ('pending', 'verified') FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '23503'; END IF;
    v_issue := iam_one_time_issue_v1(
        p_token_id, 'email_verification_v1', v_user_id,
        p_identifier_id, v_kind, v_identifier_revision,
        NULL, NULL, p_selector, p_hash_key_id, p_secret_hmac,
        p_binding_sha256
    );
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.email_verification.start', p_request_sha256,
        p_token_id, v_user_id, 1, 'actor_tenant', p_actor_id,
        'one_time_token', false, false
    ) AS result;
    RETURN QUERY SELECT p_token_id, v_user_id, 1::bigint,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_email_verification_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_identifier_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_email_verification_start_v2(name, uuid, uuid, bytea, uuid, uuid, bytea, text, bytea, bytea, uuid, uuid, bigint, bigint, uuid, uuid, uuid, uuid, text, text, bytea, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_email_verification_start_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_identifier_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_artifact_id uuid, p_subject_user_id uuid, p_resource_id uuid, p_recipient_identifier_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_result_id uuid; v_subject_user_id uuid; v_result_revision bigint;
    v_token_version bigint; v_authorization_version bigint;
    v_replayed boolean; v_insert bigint;
BEGIN
    SELECT started.result_id, started.subject_user_id, started.result_revision,
           started.token_version, started.authorization_version, started.replayed
    INTO v_result_id, v_subject_user_id, v_result_revision,
         v_token_version, v_authorization_version, v_replayed
    FROM iam_email_verification_start_v1(
        p_scope_schema, p_tenant_id, p_operation_id, p_request_sha256,
        p_token_id, p_identifier_id, p_selector, p_hash_key_id,
        p_secret_hmac, p_binding_sha256, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS started;
    IF NOT FOUND THEN RETURN; END IF;
    IF NOT v_replayed THEN
        v_insert := iam_lifecycle_delivery_artifact_insert_v1(
            p_scope_schema, p_tenant_id, p_artifact_id,
            'email_verification_v1', p_subject_user_id, p_resource_id,
            p_recipient_identifier_id, p_token_id, p_artifact_ref,
            p_kms_key_id, p_nonce, p_ciphertext, p_authentication_tag,
            p_aad_sha256, p_ciphertext_sha256
        );
    END IF;
    RETURN QUERY SELECT v_result_id, v_subject_user_id,
        v_result_revision, v_token_version,
        v_authorization_version, v_replayed;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_email_verification_start_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_identifier_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_artifact_id uuid, p_subject_user_id uuid, p_resource_id uuid, p_recipient_identifier_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) OWNER TO harpy_owner;

