--
-- Name: iam_guard_active_organization_binding_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_active_organization_binding_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    eligible boolean;
BEGIN
    IF TG_OP NOT IN ('INSERT', 'UPDATE') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM organization binding guard invocation is invalid';
    END IF;
    IF NEW.state IS DISTINCT FROM 'active' THEN
        RETURN NEW;
    END IF;
    SELECT true INTO eligible
    FROM iam_organizations AS subject
    JOIN iam_permissions AS permission ON permission.id = NEW.permission_id
    LEFT JOIN iam_resources AS resource ON resource.id = permission.resource_id
    LEFT JOIN iam_actions AS action ON action.id = permission.action_id
    WHERE subject.id = NEW.organization_id AND subject.status = 'active'
      AND permission.match_kind = NEW.permission_match_kind
      AND permission.state = 'active'
      AND (resource.id IS NULL OR resource.state = 'active')
      AND (action.id IS NULL OR action.state = 'active');
    IF eligible IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_organization_permission_bindings_active_guard',
            MESSAGE = 'Active organization binding requires active subject and permission';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_active_organization_binding_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_active_permission_catalog_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_active_permission_catalog_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    resource_active boolean := true;
    action_active boolean := true;
BEGIN
    IF TG_OP NOT IN ('INSERT', 'UPDATE') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM permission catalog guard invocation is invalid';
    END IF;
    IF NEW.state IS DISTINCT FROM 'active' THEN
        RETURN NEW;
    END IF;
    IF NEW.resource_id IS NOT NULL THEN
        SELECT resource.state = 'active' INTO resource_active
        FROM iam_resources AS resource WHERE resource.id = NEW.resource_id;
    END IF;
    IF NEW.action_id IS NOT NULL THEN
        SELECT action.state = 'active' INTO action_active
        FROM iam_actions AS action WHERE action.id = NEW.action_id;
    END IF;
    IF resource_active IS DISTINCT FROM true OR action_active IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_permissions_active_catalog_guard',
            MESSAGE = 'Active permission requires active catalog entries';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_active_permission_catalog_v1() OWNER TO harpy_owner;

