--
-- Name: iam_guard_immutable_columns_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_immutable_columns_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    column_index integer;
    column_name text;
    old_row jsonb;
    new_row jsonb;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR TG_NARGS < 1 THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'IAM immutable guard invocation is invalid';
    END IF;
    old_row := pg_catalog.to_jsonb(OLD);
    new_row := pg_catalog.to_jsonb(NEW);
    FOR column_index IN 0..TG_NARGS - 1 LOOP
        column_name := TG_ARGV[column_index];
        IF (new_row -> column_name) IS DISTINCT FROM (old_row -> column_name) THEN
            RAISE EXCEPTION USING
                ERRCODE = '23514',
                CONSTRAINT = TG_TABLE_NAME || '_immutable_guard',
                MESSAGE = pg_catalog.format(
                    'IAM immutable column %I cannot change',
                    column_name
                );
        END IF;
    END LOOP;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_immutable_columns_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_monotonic_bigint_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_monotonic_bigint_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    column_name text;
    old_value bigint;
    new_value bigint;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR TG_NARGS <> 1 THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'IAM monotonic guard invocation is invalid';
    END IF;
    column_name := TG_ARGV[0];
    old_value := (pg_catalog.to_jsonb(OLD) ->> column_name)::bigint;
    new_value := (pg_catalog.to_jsonb(NEW) ->> column_name)::bigint;
    IF old_value IS NOT NULL AND
       (new_value IS NULL OR new_value < old_value) THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            CONSTRAINT = TG_TABLE_NAME || '_' || column_name ||
                '_monotonic_guard',
            MESSAGE = pg_catalog.format(
                'IAM monotonic column %I cannot decrease',
                column_name
            );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_monotonic_bigint_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_permission_implication_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_permission_implication_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    eligible boolean;
BEGIN
    IF TG_OP NOT IN ('INSERT', 'UPDATE') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM permission implication guard invocation is invalid';
    END IF;
    IF TG_OP = 'UPDATE' AND (
        NEW.hit_count < OLD.hit_count OR
        (OLD.last_hit_at IS NOT NULL AND NEW.last_hit_at < OLD.last_hit_at)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_permission_implications_hit_guard',
            MESSAGE = 'IAM implication hit evidence cannot decrease';
    END IF;
    IF NEW.state = 'active' THEN
        SELECT pg_catalog.count(*) = 2 INTO eligible
        FROM iam_permissions AS permission
        JOIN iam_resources AS resource ON resource.id = permission.resource_id
        JOIN iam_actions AS action ON action.id = permission.action_id
        WHERE permission.id IN (NEW.source_permission_id, NEW.implied_permission_id)
          AND permission.match_kind = 'exact' AND permission.state = 'active'
          AND resource.state = 'active' AND action.state = 'active';
        IF eligible IS DISTINCT FROM true THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                CONSTRAINT = 'iam_permission_implications_active_guard',
                MESSAGE = 'Active implication requires two active exact permissions';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_permission_implication_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_permission_request_authority_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_permission_request_authority_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM iam_permissions AS permission
        JOIN iam_resources AS resource ON resource.id = permission.resource_id
        JOIN iam_actions AS action ON action.id = permission.action_id
        WHERE permission.id = NEW.creator_authority_permission_id
          AND permission.match_kind = 'exact'
          AND permission.is_protected
          AND permission.state = 'active'
          AND resource.resource_key = 'iam.permission_requests'
          AND resource.state = 'active'
          AND action.action_key = 'manage'
          AND action.state = 'active'
    ) OR NOT EXISTS (
        SELECT 1
        FROM iam_permissions AS permission
        JOIN iam_resources AS resource ON resource.id = permission.resource_id
        JOIN iam_actions AS action ON action.id = permission.action_id
        WHERE permission.id = NEW.reviewer_authority_permission_id
          AND permission.match_kind = 'exact'
          AND permission.is_protected
          AND permission.state = 'active'
          AND resource.resource_key = 'iam.permission_requests'
          AND resource.state = 'active'
          AND action.action_key = 'review'
          AND action.state = 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_permission_request_groups_authority_guard',
            MESSAGE = 'IAM permission request authority catalog is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_permission_request_authority_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_permission_request_group_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_permission_request_group_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_group_id uuid;
    v_expected smallint;
    v_actual bigint;
    v_mismatch boolean;
BEGIN
    IF TG_TABLE_NAME = 'iam_permission_request_groups' THEN
        v_group_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
    ELSE
        v_group_id := CASE
            WHEN TG_OP = 'DELETE' THEN OLD.group_id ELSE NEW.group_id END;
    END IF;
    SELECT request_group.request_count INTO v_expected
    FROM iam_permission_request_groups AS request_group
    WHERE request_group.id = v_group_id;
    IF NOT FOUND THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_permission_request_groups_cardinality_guard',
            MESSAGE = 'IAM permission request group is missing';
    END IF;
    SELECT pg_catalog.count(*), pg_catalog.bool_or(
        request.state IS DISTINCT FROM request_group.state
    ) INTO v_actual, v_mismatch
    FROM iam_permission_request_groups AS request_group
    LEFT JOIN iam_permission_requests AS request ON request.group_id = request_group.id
    WHERE request_group.id = v_group_id
    GROUP BY request_group.state;
    IF v_actual IS DISTINCT FROM v_expected OR v_mismatch IS TRUE THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_permission_request_groups_cardinality_guard',
            MESSAGE = 'IAM permission request group must be complete and state-aligned';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_permission_request_group_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_permission_request_terminal_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_permission_request_terminal_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR OLD.state NOT IN (
        'APPROVED', 'REJECTED', 'CANCELLED', 'EXPIRED'
    ) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '23514',
        CONSTRAINT = TG_TABLE_NAME || '_terminal_guard',
        MESSAGE = 'Terminal IAM permission request state is immutable';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_permission_request_terminal_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_policy_wildcard_move_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_policy_wildcard_move_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM protected policy move guard invocation is invalid';
    END IF;
    IF NEW.role_id IS NOT DISTINCT FROM OLD.role_id THEN
        RETURN NEW;
    END IF;
    IF EXISTS (
        SELECT 1 FROM iam_role_permission_bindings AS binding
        WHERE binding.role_id = OLD.role_id AND binding.state = 'active'
          AND binding.permission_match_kind <> 'exact'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_protected_admin_policies_wildcard_move_guard',
            MESSAGE = 'Old protected role retains an active wildcard binding';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_policy_wildcard_move_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_backfill_source_write_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_backfill_source_write_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_target_schema_id uuid;
BEGIN
    IF TG_OP='INSERT' THEN
        IF EXISTS (
            SELECT 1 FROM iam_profile_backfill_plans AS plan
            WHERE plan.source_schema_id=NEW.profile_schema_version_id
              AND plan.resource_kind=TG_ARGV[0]
              AND plan.state IN ('planned','running','verified')
        ) THEN
            RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='IAM profile source is fenced for backfill';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.profile_schema_version_id IS NOT DISTINCT FROM OLD.profile_schema_version_id AND
       NEW.profile_values IS NOT DISTINCT FROM OLD.profile_values AND
       NEW.profile_sha256 IS NOT DISTINCT FROM OLD.profile_sha256 THEN
        RETURN NEW;
    END IF;
    SELECT plan.target_schema_id INTO v_target_schema_id
    FROM iam_profile_backfill_plans AS plan
    WHERE plan.source_schema_id=OLD.profile_schema_version_id
      AND plan.resource_kind=TG_ARGV[0]
      AND plan.state IN ('planned','running','verified');
    IF FOUND AND NEW.profile_schema_version_id IS DISTINCT FROM v_target_schema_id THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='IAM profile source mutation is fenced for backfill';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_backfill_source_write_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_backfill_source_write_v2(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_backfill_source_write_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_target_schema_id uuid;
    v_source_version bigint;
    v_old_version bigint;
BEGIN
    SELECT plan.target_schema_id, source.version
    INTO v_target_schema_id, v_source_version
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.resource_kind = TG_ARGV[0]
      AND plan.state IN ('planned','running','verified');
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' AND
       NEW.profile_schema_version_id IS NOT DISTINCT FROM OLD.profile_schema_version_id AND
       NEW.profile_values IS NOT DISTINCT FROM OLD.profile_values AND
       NEW.profile_sha256 IS NOT DISTINCT FROM OLD.profile_sha256 THEN
        RETURN NEW;
    END IF;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       NEW.profile_schema_version_id IS DISTINCT FROM v_target_schema_id THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile resource kind is fenced for backfill';
    END IF;
    IF TG_OP = 'INSERT' OR
       OLD.profile_schema_version_id IS NOT DISTINCT FROM v_target_schema_id THEN
        RETURN NEW;
    END IF;
    SELECT actual.version INTO v_old_version
    FROM iam_profile_schema_versions AS actual
    WHERE actual.id = OLD.profile_schema_version_id
      AND actual.resource_kind = TG_ARGV[0]
      AND actual.state IN ('active','retired');
    IF v_old_version IS NULL OR v_old_version > v_source_version THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile lineage transition is fenced';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_backfill_source_write_v2() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_backfill_source_write_v3(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_backfill_source_write_v3() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_plan_id uuid;
    v_target_schema_id uuid;
    v_source_version bigint;
    v_old_version bigint;
    v_worker_capability boolean;
BEGIN
    SELECT plan.id, plan.target_schema_id, source.version
    INTO v_plan_id, v_target_schema_id, v_source_version
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.resource_kind = TG_ARGV[0]
      AND plan.state IN ('planned','running','verified')
    FOR SHARE OF plan, source, target;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' AND
       NEW.profile_schema_version_id IS NOT DISTINCT FROM
           OLD.profile_schema_version_id AND
       NEW.profile_values IS NOT DISTINCT FROM OLD.profile_values AND
       NEW.profile_sha256 IS NOT DISTINCT FROM OLD.profile_sha256 THEN
        RETURN NEW;
    END IF;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       NEW.profile_schema_version_id IS DISTINCT FROM v_target_schema_id THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile resource kind is fenced for backfill';
    END IF;
    IF TG_OP = 'INSERT' OR
       OLD.profile_schema_version_id IS NOT DISTINCT FROM v_target_schema_id THEN
        RETURN NEW;
    END IF;
    SELECT actual.version INTO v_old_version
    FROM iam_profile_schema_versions AS actual
    WHERE actual.id = OLD.profile_schema_version_id
      AND actual.resource_kind = TG_ARGV[0]
      AND actual.state IN ('active','retired');
    IF v_old_version IS NULL OR v_old_version > v_source_version OR
       NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile lineage transition is fenced';
    END IF;
    v_worker_capability := iam_profile_worker_capability_consume_v1(
        v_plan_id, TG_ARGV[0], NEW.id, OLD.profile_schema_version_id,
        OLD.revision, OLD.profile_sha256, NEW.profile_schema_version_id,
        NEW.profile_sha256
    );
    IF v_worker_capability THEN
        RETURN NEW;
    END IF;
    IF EXISTS (
        SELECT 1 FROM iam_profile_backfill_preconversions AS receipt
        WHERE receipt.plan_id = v_plan_id
          AND receipt.resource_kind = TG_ARGV[0]
          AND receipt.resource_id = NEW.id
          AND receipt.actual_source_schema_id =
              OLD.profile_schema_version_id
          AND receipt.source_revision = OLD.revision
          AND receipt.source_sha256 = OLD.profile_sha256
          AND receipt.first_target_revision = NEW.revision
          AND receipt.first_target_sha256 = NEW.profile_sha256
    ) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM profile source transition lacks authority evidence';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_backfill_source_write_v3() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_backfill_source_write_v4(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_backfill_source_write_v4() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_plan_id uuid;
    v_target_schema_id uuid;
    v_source_version bigint;
    v_old_version bigint;
    v_worker_capability boolean;
BEGIN
    IF TG_OP = 'UPDATE' AND
       NEW.profile_schema_version_id IS NOT DISTINCT FROM
           OLD.profile_schema_version_id AND
       NEW.profile_values IS NOT DISTINCT FROM OLD.profile_values AND
       NEW.profile_sha256 IS NOT DISTINCT FROM OLD.profile_sha256 THEN
        RETURN NEW;
    END IF;
    SELECT plan.id, plan.target_schema_id, source.version
    INTO v_plan_id, v_target_schema_id, v_source_version
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.resource_kind = TG_ARGV[0]
      AND (plan.state IN ('planned','running') OR
           (plan.recovery_of_plan_id IS NULL AND plan.state = 'verified'))
    FOR SHARE OF plan, source, target;
    IF NOT FOUND THEN
        IF EXISTS (
            SELECT 1 FROM iam_profile_backfill_plans AS fenced
            JOIN iam_profile_schema_versions AS source
              ON source.id = fenced.source_schema_id
             AND source.resource_kind = fenced.resource_kind
             AND source.state = 'active'
            JOIN iam_profile_schema_versions AS target
              ON target.id = fenced.target_schema_id
             AND target.resource_kind = fenced.resource_kind
             AND target.state = 'draft'
            WHERE fenced.resource_kind = TG_ARGV[0]
              AND fenced.state = 'fenced'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = 'P5741',
                MESSAGE = 'IAM profile domain is fenced pending recovery';
        END IF;
        RETURN NEW;
    END IF;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       NEW.profile_schema_version_id IS DISTINCT FROM v_target_schema_id THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile resource kind is fenced for backfill';
    END IF;
    IF TG_OP = 'INSERT' OR
       OLD.profile_schema_version_id IS NOT DISTINCT FROM v_target_schema_id THEN
        RETURN NEW;
    END IF;
    SELECT actual.version INTO v_old_version
    FROM iam_profile_schema_versions AS actual
    WHERE actual.id = OLD.profile_schema_version_id
      AND actual.resource_kind = TG_ARGV[0]
      AND actual.state IN ('active','retired');
    IF v_old_version IS NULL OR v_old_version > v_source_version OR
       NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile lineage transition is fenced';
    END IF;
    v_worker_capability := iam_profile_worker_capability_consume_v1(
        v_plan_id, TG_ARGV[0], NEW.id, OLD.profile_schema_version_id,
        OLD.revision, OLD.profile_sha256, NEW.profile_schema_version_id,
        NEW.profile_sha256
    );
    IF v_worker_capability THEN
        RETURN NEW;
    END IF;
    IF EXISTS (
        SELECT 1 FROM iam_profile_backfill_preconversions AS receipt
        WHERE receipt.plan_id = v_plan_id
          AND receipt.resource_kind = TG_ARGV[0]
          AND receipt.resource_id = NEW.id
          AND receipt.actual_source_schema_id = OLD.profile_schema_version_id
          AND receipt.source_revision = OLD.revision
          AND receipt.source_sha256 = OLD.profile_sha256
          AND receipt.first_target_revision = NEW.revision
          AND receipt.first_target_sha256 = NEW.profile_sha256
    ) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM profile source transition lacks authority evidence';
END;
$$;


