--
-- Name: iam_guard_profile_field_lifecycle_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_field_lifecycle_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' AND TG_OP IS DISTINCT FROM 'UPDATE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM profile field lifecycle invocation is invalid';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.state IS DISTINCT FROM 'active' OR NEW.retired_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                CONSTRAINT = 'iam_profile_fields_lifecycle_guard',
                MESSAGE = 'IAM profile field must begin as active';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR
       NEW.resource_kind IS DISTINCT FROM OLD.resource_kind OR
       NEW.field_key IS DISTINCT FROM OLD.field_key OR
       NEW.value_kind IS DISTINCT FROM OLD.value_kind OR
       NEW.cardinality IS DISTINCT FROM OLD.cardinality OR
       NEW.required IS DISTINCT FROM OLD.required OR
       NEW.classification IS DISTINCT FROM OLD.classification OR
       NEW.normalization_profile IS DISTINCT FROM OLD.normalization_profile OR
       NEW.created_at IS DISTINCT FROM OLD.created_at OR
       NEW.revision IS DISTINCT FROM OLD.revision + 1 OR
       NEW.updated_at < OLD.updated_at OR
       OLD.state IS DISTINCT FROM 'active' OR
       NEW.state IS DISTINCT FROM 'retired' OR NEW.retired_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_fields_lifecycle_guard',
            MESSAGE = 'IAM profile field semantic or lifecycle is immutable';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_field_lifecycle_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_recovery_activation_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_recovery_activation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_total_count bigint;
    v_target_count bigint;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       NEW.recovery_of_plan_id IS NULL OR NEW.state IS DISTINCT FROM 'activated' OR
       OLD.state IS NOT DISTINCT FROM 'activated' THEN
        RETURN NEW;
    END IF;
    IF OLD.state NOT IN ('planned','running') OR
       NOT EXISTS (
           SELECT 1
           FROM iam_profile_backfill_checkpoints AS checkpoint
           WHERE checkpoint.plan_id = NEW.id
             AND checkpoint.completed_pages = NEW.page_count
             AND checkpoint.converted_count = NEW.remaining_source_count
             AND checkpoint.error_count = 0
             AND checkpoint.rolling_sha256 =
                 NEW.expected_remaining_target_sha256
             AND ((NEW.page_count = 0 AND checkpoint.last_page_number IS NULL) OR
                  checkpoint.last_page_number = NEW.page_count)
       ) OR EXISTS (
           SELECT 1 FROM iam_profile_backfill_pages AS page
           WHERE page.plan_id = NEW.id AND (
               page.state <> 'completed' OR page.error_count <> 0 OR
               page.converted_count <> page.expected_count OR
               page.result_sha256 <> page.expected_target_sha256
           )
       ) OR NOT EXISTS (
           SELECT 1
           FROM iam_authorization_operation_receipts AS receipt
           JOIN iam_authorization_clock AS clock ON clock.singleton
           WHERE receipt.command_key = 'iam.profile_backfill.recovery_create'
             AND receipt.result_id = NEW.id AND receipt.result_revision = 1
             AND receipt.result_sha256 = NEW.plan_sha256
             AND receipt.clock_value <= clock.clock_value
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_recovery_activation_evidence_guard',
            MESSAGE = 'IAM profile recovery activation evidence is incomplete';
    END IF;
    SELECT pg_catalog.count(*), pg_catalog.count(*) FILTER (
               WHERE resource.schema_version_id = NEW.target_schema_id
           )
    INTO v_total_count, v_target_count
    FROM iam_profile_recovery_resources_v1 AS resource
    WHERE resource.resource_kind = NEW.resource_kind;
    IF v_total_count < NEW.inherited_target_count + NEW.remaining_source_count OR
       v_target_count <> v_total_count OR NOT EXISTS (
           SELECT 1 FROM iam_profile_schema_versions AS source
           JOIN iam_profile_schema_versions AS target
             ON target.id = NEW.target_schema_id
            AND target.resource_kind = NEW.resource_kind
            AND target.state = 'active'
           WHERE source.id = NEW.source_schema_id
             AND source.resource_kind = NEW.resource_kind
             AND source.state = 'retired'
             AND target.version = source.version + 1
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_recovery_activation_lineage_guard',
            MESSAGE = 'IAM profile recovery activation lineage is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_recovery_activation_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_recovery_lineage_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_recovery_lineage_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_parent_resource_kind text;
    v_parent_source_schema_id uuid;
    v_parent_target_schema_id uuid;
    v_parent_converter_version text;
    v_parent_plan_sha256 bytea;
    v_parent_root_plan_id uuid;
    v_parent_sequence bigint;
    v_parent_state text;
    v_target_definition_sha256 bytea;
    v_expected_root_plan_id uuid;
BEGIN
    IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM profile backfill plan evidence is immutable';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF OLD.state IN ('activated', 'fenced') AND NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'Terminal IAM profile backfill evidence is immutable';
        END IF;
        IF NEW.id IS DISTINCT FROM OLD.id OR
           NEW.resource_kind IS DISTINCT FROM OLD.resource_kind OR
           NEW.source_schema_id IS DISTINCT FROM OLD.source_schema_id OR
           NEW.target_schema_id IS DISTINCT FROM OLD.target_schema_id OR
           NEW.converter_version IS DISTINCT FROM OLD.converter_version OR
           NEW.plan_sha256 IS DISTINCT FROM OLD.plan_sha256 OR
           NEW.source_count IS DISTINCT FROM OLD.source_count OR
           NEW.expected_source_sha256 IS DISTINCT FROM OLD.expected_source_sha256 OR
           NEW.expected_target_sha256 IS DISTINCT FROM OLD.expected_target_sha256 OR
           NEW.page_size IS DISTINCT FROM OLD.page_size OR
           NEW.page_count IS DISTINCT FROM OLD.page_count OR
           NEW.created_at IS DISTINCT FROM OLD.created_at OR
           NEW.recovery_of_plan_id IS DISTINCT FROM OLD.recovery_of_plan_id OR
           NEW.recovery_root_plan_id IS DISTINCT FROM OLD.recovery_root_plan_id OR
           NEW.recovery_sequence IS DISTINCT FROM OLD.recovery_sequence OR
           NEW.parent_plan_sha256 IS DISTINCT FROM OLD.parent_plan_sha256 OR
           NEW.target_definition_sha256 IS DISTINCT FROM OLD.target_definition_sha256 OR
           NEW.inherited_target_count IS DISTINCT FROM OLD.inherited_target_count OR
           NEW.inherited_target_sha256 IS DISTINCT FROM OLD.inherited_target_sha256 OR
           NEW.remaining_source_count IS DISTINCT FROM OLD.remaining_source_count OR
           NEW.remaining_source_sha256 IS DISTINCT FROM OLD.remaining_source_sha256 OR
           NEW.expected_remaining_target_sha256 IS DISTINCT FROM
               OLD.expected_remaining_target_sha256 OR
           NEW.initial_rolling_sha256 IS DISTINCT FROM OLD.initial_rolling_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'IAM profile backfill plan identity is immutable';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.recovery_of_plan_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT parent.resource_kind, parent.source_schema_id, parent.target_schema_id,
           parent.converter_version, parent.plan_sha256,
           parent.recovery_root_plan_id, parent.recovery_sequence, parent.state,
           target.definition_sha256
    INTO v_parent_resource_kind, v_parent_source_schema_id,
         v_parent_target_schema_id, v_parent_converter_version,
         v_parent_plan_sha256, v_parent_root_plan_id, v_parent_sequence,
         v_parent_state, v_target_definition_sha256
    FROM iam_profile_backfill_plans AS parent
    JOIN iam_profile_schema_versions AS source
      ON source.id = parent.source_schema_id
     AND source.resource_kind = parent.resource_kind
     AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = parent.target_schema_id
     AND target.resource_kind = parent.resource_kind
     AND target.state = 'draft'
    WHERE parent.id = NEW.recovery_of_plan_id
    FOR SHARE OF parent, source, target;
    v_expected_root_plan_id := COALESCE(
        v_parent_root_plan_id, NEW.recovery_of_plan_id
    );
    IF v_parent_state IS DISTINCT FROM 'fenced' OR
       NEW.state IS DISTINCT FROM 'planned' OR
       NEW.resource_kind IS DISTINCT FROM v_parent_resource_kind OR
       NEW.source_schema_id IS DISTINCT FROM v_parent_source_schema_id OR
       NEW.target_schema_id IS DISTINCT FROM v_parent_target_schema_id OR
       NEW.converter_version IS DISTINCT FROM v_parent_converter_version OR
       NEW.parent_plan_sha256 IS DISTINCT FROM v_parent_plan_sha256 OR
       NEW.target_definition_sha256 IS DISTINCT FROM v_target_definition_sha256 OR
       NEW.recovery_root_plan_id IS DISTINCT FROM v_expected_root_plan_id OR
       NEW.recovery_sequence IS DISTINCT FROM COALESCE(v_parent_sequence, 0) + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_backfill_plans_recovery_lineage_guard',
            MESSAGE = 'IAM profile recovery lineage is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_recovery_lineage_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_schema_lifecycle_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_schema_lifecycle_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' AND TG_OP IS DISTINCT FROM 'UPDATE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM profile schema lifecycle invocation is invalid';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.state IS DISTINCT FROM 'draft' OR NEW.activated_at IS NOT NULL OR
           NEW.retired_at IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                CONSTRAINT = 'iam_profile_schema_versions_lifecycle_guard',
                MESSAGE = 'IAM profile schema must begin as draft';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR
       NEW.resource_kind IS DISTINCT FROM OLD.resource_kind OR
       NEW.version IS DISTINCT FROM OLD.version OR
       NEW.created_at IS DISTINCT FROM OLD.created_at OR
       NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_schema_versions_lifecycle_guard',
            MESSAGE = 'IAM profile schema identity or revision is immutable';
    END IF;
    IF OLD.state IS NOT DISTINCT FROM 'draft' AND
       NEW.state IS NOT DISTINCT FROM 'draft' AND
       NEW.activated_at IS NULL AND NEW.retired_at IS NULL THEN
        RETURN NEW;
    END IF;
    IF OLD.state IS NOT DISTINCT FROM 'draft' AND
       NEW.state IS NOT DISTINCT FROM 'active' AND
       NEW.activated_at IS NOT NULL AND NEW.retired_at IS NULL AND
       NEW.definition_sha256 IS NOT DISTINCT FROM
           iam_profile_definition_sha256_v1(NEW.id) THEN
        RETURN NEW;
    END IF;
    IF OLD.state IS NOT DISTINCT FROM 'active' AND
       NEW.state IS NOT DISTINCT FROM 'retired' AND
       NEW.definition_sha256 IS NOT DISTINCT FROM OLD.definition_sha256 AND
       NEW.activated_at IS NOT DISTINCT FROM OLD.activated_at AND
       NEW.retired_at IS NOT NULL THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '23514',
        CONSTRAINT = 'iam_profile_schema_versions_lifecycle_guard',
        MESSAGE = 'IAM profile schema lifecycle transition is forbidden';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_schema_lifecycle_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_snapshot_insert_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_snapshot_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_schema_state text;
    v_field_key text;
    v_value_kind text;
    v_cardinality text;
    v_required boolean;
    v_classification text;
    v_normalization text;
    v_field_state text;
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM profile snapshot insert invocation is invalid';
    END IF;
    SELECT schema_version.state, field.field_key, field.value_kind,
           field.cardinality, field.required, field.classification,
           field.normalization_profile, field.state
    INTO v_schema_state, v_field_key, v_value_kind, v_cardinality,
         v_required, v_classification, v_normalization, v_field_state
    FROM iam_profile_schema_versions AS schema_version
    JOIN iam_profile_fields AS field
      ON field.id = NEW.field_id
     AND field.resource_kind = NEW.resource_kind
    WHERE schema_version.id = NEW.schema_version_id
      AND schema_version.resource_kind = NEW.resource_kind
    FOR KEY SHARE OF schema_version, field;
    IF NOT FOUND OR v_schema_state IS DISTINCT FROM 'draft' OR
       NEW.field_key IS DISTINCT FROM v_field_key OR
       NEW.value_kind IS DISTINCT FROM v_value_kind OR
       NEW.cardinality IS DISTINCT FROM v_cardinality OR
       NEW.required IS DISTINCT FROM v_required OR
       NEW.classification IS DISTINCT FROM v_classification OR
       NEW.normalization_profile IS DISTINCT FROM v_normalization OR
       NEW.field_state IS DISTINCT FROM v_field_state THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_field_revisions_snapshot_insert_guard',
            MESSAGE = 'IAM profile snapshot does not match its draft field';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_snapshot_insert_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_profile_snapshot_insert_v2(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_profile_snapshot_insert_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_schema_state text;
    v_field_key text;
    v_value_kind text;
    v_cardinality text;
    v_required boolean;
    v_classification text;
    v_normalization text;
    v_field_state text;
BEGIN
    IF TG_OP IS DISTINCT FROM 'INSERT' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM profile snapshot insert invocation is invalid';
    END IF;
    SELECT schema_version.state, field.field_key, field.value_kind,
           field.cardinality, field.required, field.classification,
           field.normalization_profile, field.state
    INTO v_schema_state, v_field_key, v_value_kind, v_cardinality,
         v_required, v_classification, v_normalization, v_field_state
    FROM iam_profile_schema_versions AS schema_version
    JOIN iam_profile_fields AS field
      ON field.id = NEW.field_id AND field.resource_kind = NEW.resource_kind
    WHERE schema_version.id = NEW.schema_version_id
      AND schema_version.resource_kind = NEW.resource_kind
    FOR KEY SHARE OF schema_version, field;
    IF NOT FOUND OR v_schema_state IS DISTINCT FROM 'draft' OR
       NEW.field_key IS DISTINCT FROM v_field_key OR
       NEW.value_kind IS DISTINCT FROM v_value_kind OR
       NEW.cardinality IS DISTINCT FROM v_cardinality OR
       NEW.required IS DISTINCT FROM v_required OR
       NEW.classification IS DISTINCT FROM v_classification OR
       NEW.normalization_profile IS DISTINCT FROM v_normalization OR
       (v_field_state = 'retired' AND NEW.field_state <> 'retired') OR
       (v_field_state = 'active' AND NEW.field_state NOT IN ('active','retired')) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_field_revisions_snapshot_insert_guard',
            MESSAGE = 'IAM profile snapshot does not match its draft lineage';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_profile_snapshot_insert_v2() OWNER TO harpy_owner;

--
-- Name: iam_guard_protected_admin_minimum_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_protected_admin_minimum_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    protected_role uuid;
    required_count integer;
    remaining_count bigint;
BEGIN
    IF TG_TABLE_NAME = 'iam_user_role_assignments' THEN
        IF OLD.state IS DISTINCT FROM 'active' OR
           (TG_OP = 'UPDATE' AND NEW.state IS NOT DISTINCT FROM 'active') THEN
            IF TG_OP = 'DELETE' THEN
                RETURN OLD;
            END IF;
            RETURN NEW;
        END IF;
        SELECT policy.role_id, policy.minimum_active_assignments
        INTO protected_role, required_count
        FROM iam_protected_admin_policies AS policy
        WHERE policy.role_id = OLD.role_id FOR UPDATE;
        IF protected_role IS NULL THEN
            IF TG_OP = 'DELETE' THEN
                RETURN OLD;
            END IF;
            RETURN NEW;
        END IF;
        SELECT pg_catalog.count(*) INTO remaining_count
        FROM iam_user_role_assignments AS assignment
        JOIN iam_users AS subject ON subject.id = assignment.user_id
        WHERE assignment.role_id = protected_role AND assignment.state = 'active'
          AND subject.status = 'active' AND assignment.id <> OLD.id;
    ELSIF TG_TABLE_NAME = 'iam_users' AND TG_OP = 'UPDATE' THEN
        IF OLD.status IS DISTINCT FROM 'active' OR NEW.status = 'active' THEN
            RETURN NEW;
        END IF;
        SELECT policy.role_id, policy.minimum_active_assignments
        INTO protected_role, required_count
        FROM iam_protected_admin_policies AS policy
        JOIN iam_user_role_assignments AS assignment
          ON assignment.role_id = policy.role_id
        WHERE assignment.user_id = OLD.id AND assignment.state = 'active'
        FOR UPDATE OF policy;
        IF protected_role IS NULL THEN
            RETURN NEW;
        END IF;
        SELECT pg_catalog.count(*) INTO remaining_count
        FROM iam_user_role_assignments AS assignment
        JOIN iam_users AS subject ON subject.id = assignment.user_id
        WHERE assignment.role_id = protected_role AND assignment.state = 'active'
          AND subject.status = 'active' AND subject.id <> OLD.id;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM protected admin minimum guard invocation is invalid';
    END IF;
    IF remaining_count < required_count THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_protected_admin_minimum_guard',
            MESSAGE = 'Protected admin assignment minimum would be violated';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_protected_admin_minimum_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_protected_admin_policy_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_protected_admin_policy_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    active_assignments bigint;
BEGIN
    IF TG_OP NOT IN ('INSERT', 'UPDATE') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM protected admin policy guard invocation is invalid';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.authorization_epoch <= OLD.authorization_epoch THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_protected_admin_policies_epoch_guard',
            MESSAGE = 'Protected admin policy epoch must increase';
    END IF;
    SELECT pg_catalog.count(*) INTO active_assignments
    FROM iam_user_role_assignments AS assignment
    JOIN iam_users AS subject ON subject.id = assignment.user_id
    WHERE assignment.role_id = NEW.role_id
      AND assignment.state = 'active' AND subject.status = 'active';
    IF active_assignments < NEW.minimum_active_assignments THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_protected_admin_policies_minimum_guard',
            MESSAGE = 'Protected admin policy requires active assignments';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_protected_admin_policy_v1() OWNER TO harpy_owner;

