    IF TG_OP IS DISTINCT FROM 'UPDATE' OR OLD.state IS DISTINCT FROM 'retired' THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING
        ERRCODE = '23514',
        CONSTRAINT = TG_TABLE_NAME || '_terminal_guard',
        MESSAGE = 'Retired IAM RBAC state is immutable';
END;
