--
-- Name: iam_guard_revision_step_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_revision_step_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR TG_NARGS <> 0 THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'IAM revision guard invocation is invalid';
    END IF;
    IF NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            CONSTRAINT = TG_TABLE_NAME || '_revision_guard',
            MESSAGE = 'IAM revision must increase by exactly one';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_revision_step_v1() OWNER TO harpy_owner;

--
-- Name: iam_guard_role_wildcard_policy_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_role_wildcard_policy_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    policy_exists boolean;
BEGIN
    IF TG_OP NOT IN ('INSERT', 'UPDATE') THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM role wildcard guard invocation is invalid';
    END IF;
    IF NEW.state IS DISTINCT FROM 'active' OR
       NEW.permission_match_kind IS NOT DISTINCT FROM 'exact' THEN
        RETURN NEW;
    END IF;
    SELECT true INTO policy_exists
    FROM iam_protected_admin_policies AS policy
    WHERE policy.role_id = NEW.role_id AND policy.policy_state = 'active';
    IF policy_exists IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_role_permission_bindings_wildcard_policy_guard',
            MESSAGE = 'Wildcard binding requires the protected admin policy role';
    END IF;
    RETURN NEW;
END;
$$;


