--
-- Name: iam_guard_state_transition_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_guard_state_transition_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    transition text;
    transition_index integer;
    allowed boolean := false;
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR TG_NARGS < 1 THEN
        RAISE EXCEPTION USING
            ERRCODE = '55000',
            MESSAGE = 'IAM state transition guard invocation is invalid';
    END IF;
    IF NEW.state IS NOT DISTINCT FROM OLD.state THEN
        RETURN NEW;
    END IF;
    transition := OLD.state || '>' || NEW.state;
    FOR transition_index IN 0..TG_NARGS - 1 LOOP
        IF transition IS NOT DISTINCT FROM TG_ARGV[transition_index] THEN
            allowed := true;
            EXIT;
        END IF;
    END LOOP;
    IF NOT allowed THEN
        RAISE EXCEPTION USING
            ERRCODE = '23514',
            CONSTRAINT = TG_TABLE_NAME || '_state_transition_guard',
            MESSAGE = pg_catalog.format(
                'IAM state transition %s is forbidden',
                transition
            );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_guard_state_transition_v1() OWNER TO harpy_owner;

