--
-- Name: iam_identifier_add_v1(name, uuid, uuid, bytea, uuid, uuid, text, text, text, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identifier_add_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_identifier_id uuid, p_user_id uuid, p_kind text, p_display_value text, p_normalized_value text, p_normalized_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_identifier_id IS NULL OR p_user_id IS NULL OR
       p_kind NOT IN ('email_v1', 'portal_v1') OR
       p_display_value IS NULL OR p_normalized_value IS NULL OR
       pg_catalog.octet_length(p_normalized_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.sha256(pg_catalog.convert_to(p_normalized_value, 'UTF8'))
           IS DISTINCT FROM p_normalized_sha256 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM identifier add input is invalid';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.identifier.add', p_request_sha256, p_identifier_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM iam_users AS subject
        WHERE subject.id = p_user_id AND subject.status IN ('pending', 'active')
        FOR UPDATE
    ) THEN RAISE EXCEPTION USING ERRCODE = '23503'; END IF;
    INSERT INTO iam_user_identifiers (
        id, user_id, kind, display_value, normalized_value,
        normalized_sha256, state, revision, created_at, updated_at
    ) VALUES (
        p_identifier_id, p_user_id, p_kind, p_display_value,
        p_normalized_value, p_normalized_sha256, 'pending', 1, v_now, v_now
    );
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.identifier.add', p_request_sha256,
        p_identifier_id, p_user_id, 1, 'actor_tenant', p_actor_id,
        'identifier', true, true
    ) AS result;
    RETURN QUERY SELECT p_identifier_id, p_user_id, 1::bigint,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identifier_add_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_identifier_id uuid, p_user_id uuid, p_kind text, p_display_value text, p_normalized_value text, p_normalized_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identifier_retire_v1(name, uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identifier_retire_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_identifier_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_state text;
    v_revision bigint;
    v_cooldown_until timestamptz;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_identifier_id IS NULL OR p_expected_revision < 1 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.identifier.retire',
        p_request_sha256, p_identifier_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT identifier.user_id, identifier.state, identifier.revision,
        identifier.cooldown_until
    INTO v_user_id, v_state, v_revision, v_cooldown_until
    FROM iam_user_identifiers AS identifier
    WHERE identifier.id = p_identifier_id FOR UPDATE;
    IF NOT FOUND OR v_state <> 'tombstoned' OR
       v_revision <> p_expected_revision OR v_cooldown_until > v_now THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM identifier is not retireable';
    END IF;
    UPDATE iam_user_identifiers SET state = 'retired', retired_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = p_identifier_id RETURNING revision INTO v_revision;
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.identifier.retire', p_request_sha256,
        p_identifier_id, v_user_id, v_revision,
        'actor_tenant', p_actor_id, 'identifier', true, true
    ) AS result;
    RETURN QUERY SELECT p_identifier_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identifier_retire_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_identifier_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identifier_tombstone_v1(name, uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identifier_tombstone_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_identifier_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_state text;
    v_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_identifier_id IS NULL OR p_expected_revision < 1 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.identifier.tombstone',
        p_request_sha256, p_identifier_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT identifier.user_id, identifier.state, identifier.revision
    INTO v_user_id, v_state, v_revision
    FROM iam_user_identifiers AS identifier
    WHERE identifier.id = p_identifier_id FOR UPDATE;
    IF NOT FOUND OR v_state <> 'active' OR v_revision <> p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM identifier revision changed';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM iam_user_identifiers AS alternative
        WHERE alternative.user_id = v_user_id
          AND alternative.state = 'active' AND alternative.id <> p_identifier_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM user requires another active identifier';
    END IF;
    UPDATE iam_user_identifiers SET state = 'tombstoned',
        tombstoned_at = v_now, cooldown_until = v_now + INTERVAL '30 days',
        revision = revision + 1, updated_at = v_now
    WHERE id = p_identifier_id RETURNING revision INTO v_revision;
    UPDATE iam_one_time_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE identifier_id = p_identifier_id AND state = 'pending';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.identifier.tombstone', p_request_sha256,
        p_identifier_id, v_user_id, v_revision,
        'actor_tenant', p_actor_id, 'identifier', true, true
    ) AS result;
    RETURN QUERY SELECT p_identifier_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identifier_tombstone_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_identifier_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identifier_verify_v1(name, uuid, uuid, bytea, bytea, text, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identifier_verify_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_token_id uuid;
    v_user_id uuid;
    v_identifier_id uuid;
    v_identifier_revision bigint;
    v_token_state text;
    v_expires_at timestamptz;
    v_identifier_state text;
    v_result_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       p_hash_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_binding_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM identifier verify input is invalid';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.identifier.verify', p_request_sha256, NULL
    );
    IF FOUND THEN RETURN; END IF;
    SELECT token.id, token.user_id, token.identifier_id,
        token.identifier_revision, token.state, token.expires_at
    INTO v_token_id, v_user_id, v_identifier_id,
        v_identifier_revision, v_token_state, v_expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.purpose = 'email_verification_v1'
      AND token.selector = p_selector AND token.hash_key_id = p_hash_key_id
      AND token.secret_hmac = p_secret_hmac
      AND token.binding_sha256 = p_binding_sha256
    FOR UPDATE;
    IF NOT FOUND OR v_token_state <> 'pending' OR v_expires_at <= v_now THEN
        RAISE EXCEPTION USING ERRCODE = '28000',
            MESSAGE = 'IAM email verification proof is invalid';
    END IF;
    SELECT identifier.state, identifier.revision
    INTO v_identifier_state, v_result_revision
    FROM iam_user_identifiers AS identifier
    WHERE identifier.id = v_identifier_id
      AND identifier.user_id = v_user_id
      AND identifier.kind = 'email_v1'
      AND identifier.revision = v_identifier_revision
    FOR UPDATE;
    IF NOT FOUND OR v_identifier_state NOT IN ('pending', 'verified') THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM email identifier changed';
    END IF;
    UPDATE iam_user_identifiers SET state = 'active',
        verified_at = COALESCE(verified_at, v_now), activated_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = v_identifier_id RETURNING revision INTO v_result_revision;
    UPDATE iam_one_time_tokens SET state = 'consumed', consumed_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = v_token_id;
    UPDATE iam_one_time_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE purpose = 'email_verification_v1'
      AND user_id = v_user_id AND identifier_id = v_identifier_id
      AND state = 'pending';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.identifier.verify', p_request_sha256,
        v_identifier_id, v_user_id, v_result_revision,
        'credential_target', v_user_id, 'identifier', true, true
    ) AS result;
    RETURN QUERY SELECT v_identifier_id, v_user_id, v_result_revision,
        v_token_version, v_authorization_version, false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_identifier_verify_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_identifier_verify_v2(name, uuid, uuid, bytea, bytea, text, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identifier_verify_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_token_id uuid;
    v_user_id uuid;
    v_identifier_id uuid;
    v_identifier_kind text;
    v_identifier_revision bigint;
    v_token_state text;
    v_expires_at timestamptz;
    v_identifier_state text;
    v_result_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       p_hash_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_binding_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM identifier verify input is invalid';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.identifier.verify', p_request_sha256, NULL
    );
    IF FOUND THEN RETURN; END IF;
    SELECT token.id, token.user_id, token.identifier_id,
        token.identifier_kind, token.identifier_revision,
        token.state, token.expires_at
    INTO v_token_id, v_user_id, v_identifier_id, v_identifier_kind,
        v_identifier_revision, v_token_state, v_expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.purpose = 'email_verification_v1'
      AND token.selector = p_selector AND token.hash_key_id = p_hash_key_id
      AND token.secret_hmac = p_secret_hmac
      AND token.binding_sha256 = p_binding_sha256
    FOR UPDATE;
    IF NOT FOUND OR v_token_state <> 'pending' OR v_expires_at <= v_now THEN
        RAISE EXCEPTION USING ERRCODE = '28000',
            MESSAGE = 'IAM email verification proof is invalid';
    END IF;
    SELECT identifier.state, identifier.revision
    INTO v_identifier_state, v_result_revision
    FROM iam_user_identifiers AS identifier
    WHERE identifier.id = v_identifier_id
      AND identifier.user_id = v_user_id
      AND identifier.kind = v_identifier_kind
      AND identifier.revision = v_identifier_revision
    FOR UPDATE;
    IF NOT FOUND OR v_identifier_state NOT IN ('pending', 'verified') THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM email identifier changed';
    END IF;
    PERFORM 1 FROM iam_user_identifiers AS current_identifier
    WHERE current_identifier.user_id = v_user_id
      AND current_identifier.kind = v_identifier_kind
      AND current_identifier.state = 'active'
      AND current_identifier.id <> v_identifier_id
    FOR UPDATE;
    UPDATE iam_user_identifiers SET state = 'tombstoned',
        tombstoned_at = v_now, cooldown_until = v_now + INTERVAL '30 days',
        revision = revision + 1, updated_at = v_now
    WHERE user_id = v_user_id AND kind = v_identifier_kind
      AND state = 'active' AND id <> v_identifier_id;
    UPDATE iam_user_identifiers SET state = 'active',
        verified_at = COALESCE(verified_at, v_now), activated_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = v_identifier_id RETURNING revision INTO v_result_revision;
    UPDATE iam_one_time_tokens SET state = 'consumed', consumed_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = v_token_id;
    UPDATE iam_one_time_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE purpose = 'email_verification_v1'
      AND user_id = v_user_id AND identifier_id = v_identifier_id
      AND state = 'pending';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.identifier.verify', p_request_sha256,
        v_identifier_id, v_user_id, v_result_revision,
        'credential_target', v_user_id, 'identifier', true, true
    ) AS result;
    RETURN QUERY SELECT v_identifier_id, v_user_id, v_result_revision,
        v_token_version, v_authorization_version, false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_identifier_verify_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_identity_actor_assert_v1(name, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_actor_assert_v1(p_scope_schema name, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_status text;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_actor_id IS NULL OR p_permission_id IS NULL OR
       p_expected_token_version < 1 OR p_expected_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM identity command scope is invalid';
    END IF;
    SELECT status, token_version, authorization_version
    INTO v_status, v_token_version, v_authorization_version
    FROM iam_users WHERE id = p_actor_id FOR UPDATE;
    IF NOT FOUND OR v_status IS DISTINCT FROM 'active' OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version OR
       NOT iam_user_has_rbac_evidence_v2(p_actor_id, p_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM identity command authority is denied';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_actor_assert_v1(p_scope_schema name, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_assignment_grant_v1(name, uuid, bytea, uuid, uuid, uuid, text, uuid, uuid, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_assignment_grant_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_assignment_id uuid, p_user_id uuid, p_role_id uuid, p_scope_kind text, p_scope_id uuid, p_organization_id uuid, p_membership_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_clock bigint; v_user_revision bigint;
BEGIN
    IF p_assignment_id IS NULL OR p_user_id IS NULL OR p_role_id IS NULL OR
       p_scope_kind NOT IN ('tenant', 'organization') OR
       (p_scope_kind = 'tenant' AND
          (p_organization_id IS NOT NULL OR p_membership_id IS NOT NULL)) OR
       (p_scope_kind = 'organization' AND
          (p_organization_id IS DISTINCT FROM p_scope_id OR p_membership_id IS NULL)) OR
       NOT EXISTS (SELECT 1 FROM iam_users WHERE id = p_user_id AND status = 'active') OR
       NOT EXISTS (SELECT 1 FROM iam_roles WHERE id = p_role_id
                   AND scope_kind = p_scope_kind AND scope_id = p_scope_id
                   AND status = 'active' AND NOT is_protected) OR
       (p_scope_kind = 'organization' AND NOT EXISTS (
          SELECT 1 FROM iam_organization_memberships AS membership
          JOIN iam_organizations AS organization ON organization.id = membership.organization_id
          WHERE membership.id = p_membership_id
            AND membership.organization_id = p_organization_id
            AND membership.user_id = p_user_id AND membership.state = 'active'
            AND organization.status = 'active'
       )) OR NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '23514',
          MESSAGE = 'IAM identity assignment grant input is invalid'; END IF;
    RETURN QUERY SELECT * FROM iam_identity_replay_v1(
        p_operation_id, 'iam.identity.assignment.grant',
        p_request_sha256, p_assignment_id
    );
    IF FOUND THEN RETURN; END IF;
    INSERT INTO iam_user_role_assignments (
        id, user_id, role_id, role_scope_kind, role_scope_id,
        organization_id, membership_id, state, revision, created_at, updated_at
    ) VALUES (
        p_assignment_id, p_user_id, p_role_id, p_scope_kind, p_scope_id,
        p_organization_id, p_membership_id, 'active', 1, v_now, v_now
    );
    v_user_revision := iam_identity_user_bump_v1(p_user_id, false);
    v_clock := iam_identity_record_v1(
        p_operation_id, 'iam.identity.assignment.grant', p_request_sha256,
        p_assignment_id, 1, p_request_sha256
    );
    RETURN QUERY SELECT p_assignment_id, 1::bigint, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_assignment_grant_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_assignment_id uuid, p_user_id uuid, p_role_id uuid, p_scope_kind text, p_scope_id uuid, p_organization_id uuid, p_membership_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_assignment_list_v1(name, uuid, integer, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_assignment_list_v1(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(id uuid, user_id uuid, role_id uuid, role_scope_kind text, role_scope_id uuid, organization_id uuid, membership_id uuid, state text, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, revoked_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit NOT BETWEEN 1 AND 100 OR NOT iam_identity_query_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY SELECT assignment.id, assignment.user_id, assignment.role_id,
        assignment.role_scope_kind, assignment.role_scope_id,
        COALESCE(assignment.organization_id, '00000000-0000-0000-0000-000000000000'::uuid),
        COALESCE(assignment.membership_id, '00000000-0000-0000-0000-000000000000'::uuid),
        assignment.state, assignment.revision, assignment.created_at,
        assignment.updated_at, assignment.revoked_at
    FROM iam_user_role_assignments AS assignment
    WHERE p_after_id IS NULL OR assignment.id > p_after_id
    ORDER BY assignment.id LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_assignment_list_v1(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_assignment_read_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_assignment_read_v1(p_scope_schema name, p_assignment_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(id uuid, user_id uuid, role_id uuid, role_scope_kind text, role_scope_id uuid, organization_id uuid, membership_id uuid, state text, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, revoked_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_assignment_id IS NULL OR NOT iam_identity_query_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY SELECT assignment.id, assignment.user_id, assignment.role_id,
        assignment.role_scope_kind, assignment.role_scope_id,
        COALESCE(assignment.organization_id, '00000000-0000-0000-0000-000000000000'::uuid),
        COALESCE(assignment.membership_id, '00000000-0000-0000-0000-000000000000'::uuid),
        assignment.state, assignment.revision, assignment.created_at,
        assignment.updated_at, assignment.revoked_at
    FROM iam_user_role_assignments AS assignment WHERE assignment.id = p_assignment_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_assignment_read_v1(p_scope_schema name, p_assignment_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_assignment_revoke_v1(name, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_assignment_revoke_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_assignment_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_user_id uuid; v_revision bigint; v_clock bigint; v_user_revision bigint;
BEGIN
    IF p_assignment_id IS NULL OR p_expected_revision < 1 OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY SELECT * FROM iam_identity_replay_v1(
        p_operation_id, 'iam.identity.assignment.revoke',
        p_request_sha256, p_assignment_id
    );
    IF FOUND THEN RETURN; END IF;
    UPDATE iam_user_role_assignments SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = p_assignment_id AND revision = p_expected_revision AND state <> 'revoked'
    RETURNING user_id, revision INTO v_user_id, v_revision;
    IF v_revision IS NULL THEN RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM identity assignment revoke compare-and-swap failed'; END IF;
    v_user_revision := iam_identity_user_bump_v1(v_user_id, false);
    v_clock := iam_identity_record_v1(
        p_operation_id, 'iam.identity.assignment.revoke', p_request_sha256,
        p_assignment_id, v_revision, p_request_sha256
    );
    RETURN QUERY SELECT p_assignment_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_assignment_revoke_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_assignment_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_assignment_update_v1(name, uuid, bytea, uuid, bigint, text, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_assignment_update_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_assignment_id uuid, p_expected_revision bigint, p_state text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid; v_revision bigint; v_clock bigint; v_user_revision bigint;
BEGIN
    IF p_assignment_id IS NULL OR p_expected_revision < 1 OR
       p_state NOT IN ('active', 'suspended') OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '23514',
          MESSAGE = 'IAM identity assignment update input is invalid'; END IF;
    RETURN QUERY SELECT * FROM iam_identity_replay_v1(
        p_operation_id, 'iam.identity.assignment.update',
        p_request_sha256, p_assignment_id
    );
    IF FOUND THEN RETURN; END IF;
    UPDATE iam_user_role_assignments SET state = p_state,
        revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
    WHERE id = p_assignment_id AND revision = p_expected_revision AND state <> 'revoked'
    RETURNING user_id, revision INTO v_user_id, v_revision;
    IF v_revision IS NULL THEN RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM identity assignment update compare-and-swap failed'; END IF;
    v_user_revision := iam_identity_user_bump_v1(v_user_id, false);
    v_clock := iam_identity_record_v1(
        p_operation_id, 'iam.identity.assignment.update', p_request_sha256,
        p_assignment_id, v_revision, p_request_sha256
    );
    RETURN QUERY SELECT p_assignment_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_assignment_update_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_assignment_id uuid, p_expected_revision bigint, p_state text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_bulk_delete_reserve_v1(name, uuid, uuid, text, bytea, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_bulk_delete_reserve_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_resource_kind text, p_request_sha256 bytea, p_deleted_count integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing iam_identity_bulk_delete_receipts%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_operation_id IS NULL OR p_actor_id IS NULL
       OR p_resource_kind NOT IN ('user','role','organization')
       OR pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32
       OR p_deleted_count NOT BETWEEN 1 AND 100
       OR NOT EXISTS (
           SELECT 1 FROM iam_users AS actor
           WHERE actor.id = p_actor_id AND actor.status = 'active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM bulk delete receipt scope is invalid';
    END IF;
    INSERT INTO iam_identity_bulk_delete_receipts (
        operation_id, actor_id, resource_kind, request_sha256,
        deleted_count, created_at
    ) VALUES (
        p_operation_id, p_actor_id, p_resource_kind, p_request_sha256,
        p_deleted_count, pg_catalog.transaction_timestamp()
    ) ON CONFLICT (operation_id) DO NOTHING;
    IF FOUND THEN RETURN false; END IF;
    SELECT * INTO STRICT v_existing
    FROM iam_identity_bulk_delete_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id
    FOR SHARE;
    IF v_existing.actor_id IS DISTINCT FROM p_actor_id
       OR v_existing.resource_kind IS DISTINCT FROM p_resource_kind
       OR v_existing.request_sha256 IS DISTINCT FROM p_request_sha256
       OR v_existing.deleted_count IS DISTINCT FROM p_deleted_count THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'IAM bulk delete replay conflicts';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_bulk_delete_reserve_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_resource_kind text, p_request_sha256 bytea, p_deleted_count integer) OWNER TO harpy_owner;

--
-- Name: iam_identity_change_audit_write_v1(name, uuid, uuid, text, uuid, bytea, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_change_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_resource_kind text, p_aggregate_id uuid, p_request_sha256 bytea, p_command_key text, p_result_code text) RETURNS TABLE(aggregate_revision bigint, authorization_clock bigint, event_sequence bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_command text; v_request bytea; v_result text; v_result_id uuid;
    v_receipt_revision bigint; v_receipt_clock bigint; v_receipt_created timestamptz;
    v_revision bigint; v_clock bigint; v_sequence bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'role', 'organization') OR
       p_command_key NOT LIKE 'iam.identity.' || p_resource_kind || '.%' OR
       p_result_code IS DISTINCT FROM p_command_key || '.succeeded' OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM identity change audit scope is invalid';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_code,
           receipt.result_id, receipt.result_revision, receipt.clock_value,
           receipt.created_at
    INTO v_command, v_request, v_result, v_result_id, v_receipt_revision,
         v_receipt_clock, v_receipt_created
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF v_command IS DISTINCT FROM p_command_key OR
       v_request IS DISTINCT FROM p_request_sha256 OR
       v_result IS DISTINCT FROM p_result_code OR
       v_result_id IS DISTINCT FROM p_aggregate_id OR
       v_receipt_created IS DISTINCT FROM pg_catalog.transaction_timestamp() OR
       NOT EXISTS (
           SELECT 1 FROM iam_users AS actor
           WHERE actor.id = p_actor_id AND actor.status = 'active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM identity change audit evidence is invalid';
    END IF;
    CASE p_resource_kind
        WHEN 'user' THEN
            SELECT revision INTO v_revision FROM iam_users
            WHERE id = p_aggregate_id FOR UPDATE;
        WHEN 'role' THEN
            SELECT revision INTO v_revision FROM iam_roles
            WHERE id = p_aggregate_id FOR UPDATE;
        WHEN 'organization' THEN
            SELECT revision INTO v_revision FROM iam_organizations
            WHERE id = p_aggregate_id FOR UPDATE;
    END CASE;
    SELECT clock_value INTO v_clock FROM iam_authorization_clock
    WHERE singleton FOR UPDATE;
    IF v_revision IS NULL OR v_clock IS NULL OR
       v_receipt_revision > v_revision OR v_receipt_clock > v_clock THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM identity change result is invalid';
    END IF;
    SELECT COALESCE(pg_catalog.max(audit.event_sequence), 0) + 1
    INTO v_sequence FROM iam_identity_change_audit AS audit
    WHERE audit.resource_kind = p_resource_kind
      AND audit.aggregate_id = p_aggregate_id;
    INSERT INTO iam_identity_change_audit (
        operation_id, actor_id, resource_kind, aggregate_id, request_sha256,
        command_key, result_code, aggregate_revision, authorization_clock,
        event_sequence, recorded_at
    ) VALUES (
        p_operation_id, p_actor_id, p_resource_kind, p_aggregate_id,
        p_request_sha256, p_command_key, p_result_code, v_revision, v_clock,
        v_sequence, pg_catalog.transaction_timestamp()
    );
    RETURN QUERY SELECT v_revision, v_clock, v_sequence;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_change_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_resource_kind text, p_aggregate_id uuid, p_request_sha256 bytea, p_command_key text, p_result_code text) OWNER TO harpy_owner;

--
-- Name: iam_identity_membership_add_v1(name, uuid, bytea, uuid, uuid, uuid, text, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_membership_add_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_membership_id uuid, p_organization_id uuid, p_user_id uuid, p_kind text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_clock bigint; v_user_revision bigint;
BEGIN
    IF p_membership_id IS NULL OR p_organization_id IS NULL OR p_user_id IS NULL OR
       p_kind NOT IN ('member', 'owner') OR
       NOT EXISTS (SELECT 1 FROM iam_organizations
                   WHERE id = p_organization_id AND status = 'active') OR
       NOT EXISTS (SELECT 1 FROM iam_users WHERE id = p_user_id AND status = 'active') OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '23514',
          MESSAGE = 'IAM identity membership add input is invalid'; END IF;
    RETURN QUERY SELECT * FROM iam_identity_replay_v1(
        p_operation_id, 'iam.identity.membership.add', p_request_sha256, p_membership_id
    );
    IF FOUND THEN RETURN; END IF;
    INSERT INTO iam_organization_memberships (
        id, organization_id, user_id, membership_kind, state,
        revision, created_at, updated_at
    ) VALUES (
        p_membership_id, p_organization_id, p_user_id, p_kind,
        'active', 1, v_now, v_now
    );
    v_user_revision := iam_identity_user_bump_v1(p_user_id, false);
    v_clock := iam_identity_record_v1(
        p_operation_id, 'iam.identity.membership.add', p_request_sha256,
        p_membership_id, 1, p_request_sha256
    );
    RETURN QUERY SELECT p_membership_id, 1::bigint, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_membership_add_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_membership_id uuid, p_organization_id uuid, p_user_id uuid, p_kind text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_membership_delete_v1(name, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_membership_delete_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_membership_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_organization_id uuid; v_user_id uuid; v_kind text; v_state text;
    v_revision bigint; v_clock bigint; v_user_revision bigint;
BEGIN
    IF p_membership_id IS NULL OR p_expected_revision < 1 OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) OR EXISTS (
          SELECT 1 FROM iam_user_role_assignments
          WHERE membership_id = p_membership_id AND state <> 'revoked'
       ) THEN RAISE EXCEPTION USING ERRCODE = '23514',
          MESSAGE = 'IAM identity membership deletion is denied'; END IF;
    RETURN QUERY SELECT * FROM iam_identity_replay_v1(
        p_operation_id, 'iam.identity.membership.delete',
        p_request_sha256, p_membership_id
    );
    IF FOUND THEN RETURN; END IF;
    SELECT organization_id, user_id, membership_kind, state
    INTO v_organization_id, v_user_id, v_kind, v_state
    FROM iam_organization_memberships
    WHERE id = p_membership_id AND revision = p_expected_revision FOR UPDATE;
    IF NOT FOUND OR v_state = 'tombstoned' THEN RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM identity membership delete compare-and-swap failed'; END IF;
    PERFORM 1 FROM iam_organizations WHERE id = v_organization_id FOR UPDATE;
    IF v_kind = 'owner' AND v_state = 'active' AND NOT EXISTS (
        SELECT 1 FROM iam_organization_memberships AS other
        JOIN iam_users AS principal ON principal.id = other.user_id
        WHERE other.organization_id = v_organization_id
          AND other.id <> p_membership_id AND other.membership_kind = 'owner'
          AND other.state = 'active' AND principal.status = 'active'
    ) THEN RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'IAM identity organization requires an active owner'; END IF;
    UPDATE iam_organization_memberships SET state = 'tombstoned',
        tombstoned_at = v_now, revision = revision + 1, updated_at = v_now
    WHERE id = p_membership_id AND revision = p_expected_revision
    RETURNING revision INTO v_revision;
    v_user_revision := iam_identity_user_bump_v1(v_user_id, false);
    v_clock := iam_identity_record_v1(
        p_operation_id, 'iam.identity.membership.delete', p_request_sha256,
        p_membership_id, v_revision, p_request_sha256
    );
    RETURN QUERY SELECT p_membership_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_membership_delete_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_membership_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_membership_list_v1(name, uuid, integer, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_membership_list_v1(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(id uuid, organization_id uuid, user_id uuid, membership_kind text, state text, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, tombstoned_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit NOT BETWEEN 1 AND 100 OR NOT iam_identity_query_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY SELECT membership.id, membership.organization_id,
        membership.user_id, membership.membership_kind, membership.state,
        membership.revision, membership.created_at,
        membership.updated_at, membership.tombstoned_at
    FROM iam_organization_memberships AS membership
    WHERE p_after_id IS NULL OR membership.id > p_after_id
    ORDER BY membership.id LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_membership_list_v1(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_membership_read_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_membership_read_v1(p_scope_schema name, p_membership_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(id uuid, organization_id uuid, user_id uuid, membership_kind text, state text, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, tombstoned_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_membership_id IS NULL OR NOT iam_identity_query_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY SELECT membership.id, membership.organization_id,
        membership.user_id, membership.membership_kind, membership.state,
        membership.revision, membership.created_at,
        membership.updated_at, membership.tombstoned_at
    FROM iam_organization_memberships AS membership
    WHERE membership.id = p_membership_id;
END;
$$;


