--
-- Name: iam_identity_organization_list_v1(name, uuid, integer, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_organization_list_v1(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(id uuid, name text, slug text, status text, parent_id uuid, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, tombstoned_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit NOT BETWEEN 1 AND 100 OR NOT iam_identity_query_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY SELECT organization.id, organization.name, organization.slug,
        organization.status,
        COALESCE(organization.parent_id, '00000000-0000-0000-0000-000000000000'::uuid),
        organization.revision, organization.created_at,
        organization.updated_at, organization.tombstoned_at
    FROM iam_organizations AS organization
    WHERE p_after_id IS NULL OR organization.id > p_after_id
    ORDER BY organization.id LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_organization_list_v1(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_organization_list_v2(name, uuid, integer, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_organization_list_v2(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(id uuid, name text, slug text, status text, parent_id uuid, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, tombstoned_at timestamp with time zone, owner_ids uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit NOT BETWEEN 1 AND 100 OR NOT iam_identity_query_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY
    SELECT organization.id, organization.name, organization.slug,
        organization.status, organization.parent_id, organization.revision,
        organization.created_at, organization.updated_at,
        organization.tombstoned_at,
        COALESCE((SELECT pg_catalog.array_agg(member.user_id ORDER BY member.user_id)
          FROM iam_organization_memberships AS member
          WHERE member.organization_id = organization.id
            AND member.membership_kind = 'owner'
            AND member.state = 'active'), '{}'::uuid[])
    FROM iam_organizations AS organization
    WHERE p_after_id IS NULL OR organization.id > p_after_id
    ORDER BY organization.id LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_organization_list_v2(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_organization_owners_replace_v1(uuid, bigint, uuid[], uuid[]); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_organization_owners_replace_v1(p_organization_id uuid, p_expected_revision bigint, p_owner_ids uuid[], p_membership_ids uuid[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_status text; v_revision bigint; v_user_id uuid;
    v_changed boolean := false;
BEGIN
    IF p_organization_id IS NULL OR p_expected_revision < 1 OR
       COALESCE(pg_catalog.cardinality(p_owner_ids), -1) NOT BETWEEN 1 AND 100 OR
       p_membership_ids IS NULL OR pg_catalog.cardinality(p_owner_ids) <>
          pg_catalog.cardinality(p_membership_ids) OR
       p_owner_ids IS DISTINCT FROM ARRAY(
          SELECT value FROM pg_catalog.unnest(p_owner_ids) AS desired(value)
          ORDER BY value
       ) OR pg_catalog.cardinality(p_owner_ids) <> (
          SELECT pg_catalog.count(DISTINCT value)
          FROM pg_catalog.unnest(p_owner_ids) AS desired(value)
       ) OR pg_catalog.cardinality(p_membership_ids) <> (
          SELECT pg_catalog.count(DISTINCT value)
          FROM pg_catalog.unnest(p_membership_ids) AS desired(value)
       ) OR EXISTS (
          SELECT 1 FROM pg_catalog.generate_subscripts(p_owner_ids, 1) AS desired(position)
          WHERE p_owner_ids[desired.position] IS NULL OR
                p_membership_ids[desired.position] IS NULL
       ) THEN RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE =
          'IAM identity organization owner set is not canonical'; END IF;
    PERFORM membership.id FROM iam_organization_memberships AS membership
    WHERE membership.organization_id = p_organization_id
    ORDER BY membership.user_id, membership.id FOR UPDATE;
    SELECT organization.status, organization.revision INTO v_status, v_revision
    FROM iam_organizations AS organization
    WHERE organization.id = p_organization_id FOR UPDATE;
    IF NOT FOUND OR v_status <> 'active' OR v_revision <> p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE =
            'IAM identity organization owner compare-and-swap failed';
    END IF;
    IF (SELECT pg_catalog.count(*) FROM iam_users AS principal
        WHERE principal.id = ANY(p_owner_ids) AND principal.status = 'active') <>
       pg_catalog.cardinality(p_owner_ids) OR EXISTS (
        SELECT 1 FROM iam_organization_memberships AS membership
        WHERE membership.organization_id = p_organization_id
          AND membership.user_id = ANY(p_owner_ids)
          AND membership.state = 'tombstoned'
       ) OR EXISTS (
        SELECT 1
        FROM pg_catalog.generate_subscripts(p_owner_ids, 1) AS desired(position)
        JOIN iam_organization_memberships AS collision
          ON collision.id = p_membership_ids[desired.position]
        WHERE NOT EXISTS (
          SELECT 1 FROM iam_organization_memberships AS relation
          WHERE relation.organization_id = p_organization_id
            AND relation.user_id = p_owner_ids[desired.position]
        )
       ) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE =
          'IAM identity organization owner set is invalid'; END IF;
    FOR v_user_id IN
      WITH demoted AS (
        UPDATE iam_organization_memberships AS membership
        SET membership_kind = 'member', revision = membership.revision + 1,
            updated_at = v_now
        WHERE membership.organization_id = p_organization_id
          AND membership.membership_kind = 'owner'
          AND membership.state <> 'tombstoned'
          AND NOT membership.user_id = ANY(p_owner_ids)
        RETURNING membership.user_id
    ), promoted AS (
        UPDATE iam_organization_memberships AS membership
        SET membership_kind = 'owner', state = 'active',
            revision = membership.revision + 1, updated_at = v_now
        WHERE membership.organization_id = p_organization_id
          AND membership.user_id = ANY(p_owner_ids)
          AND membership.state <> 'tombstoned'
          AND (membership.membership_kind <> 'owner' OR membership.state <> 'active')
        RETURNING membership.user_id
    ), inserted AS (
        INSERT INTO iam_organization_memberships (
            id, organization_id, user_id, membership_kind, state,
            revision, created_at, updated_at
        ) SELECT p_membership_ids[desired.position], p_organization_id,
            p_owner_ids[desired.position], 'owner', 'active', 1, v_now, v_now
        FROM pg_catalog.generate_subscripts(p_owner_ids, 1) AS desired(position)
        WHERE NOT EXISTS (
            SELECT 1 FROM iam_organization_memberships AS membership
            WHERE membership.organization_id = p_organization_id
              AND membership.user_id = p_owner_ids[desired.position]
        ) RETURNING user_id
    ) SELECT changed.user_id FROM (
        SELECT user_id FROM demoted UNION SELECT user_id FROM promoted
        UNION SELECT user_id FROM inserted
      ) AS changed ORDER BY changed.user_id
    LOOP
        v_changed := true;
        PERFORM iam_identity_user_bump_v1(v_user_id, false);
    END LOOP;
    IF (SELECT pg_catalog.count(*) FROM iam_organization_memberships AS membership
        JOIN iam_users AS principal ON principal.id = membership.user_id
        WHERE membership.organization_id = p_organization_id
          AND membership.membership_kind = 'owner' AND membership.state = 'active'
          AND principal.status = 'active') <> pg_catalog.cardinality(p_owner_ids) OR
       EXISTS (
        SELECT 1 FROM iam_organization_memberships AS membership
        WHERE membership.organization_id = p_organization_id
          AND membership.membership_kind = 'owner' AND membership.state = 'active'
          AND NOT membership.user_id = ANY(p_owner_ids)
       ) THEN RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE =
          'IAM identity organization requires the exact active owner set'; END IF;
    RETURN v_changed;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_organization_owners_replace_v1(p_organization_id uuid, p_expected_revision bigint, p_owner_ids uuid[], p_membership_ids uuid[]) OWNER TO harpy_owner;

