--
-- Name: iam_identity_password_enroll_v1(name, uuid, bytea, uuid, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_password_enroll_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_salt bytea, p_tag bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_clock bigint;
BEGIN
    IF p_operation_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_user_id IS NULL OR
       pg_catalog.octet_length(p_salt) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_tag) IS DISTINCT FROM 32 OR
       NOT EXISTS (
          SELECT 1 FROM iam_users AS subject
          WHERE subject.id = p_user_id AND subject.status = 'active'
       ) OR NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '42501',
          MESSAGE = 'IAM password enrollment input or authority is invalid';
    END IF;
    RETURN QUERY SELECT * FROM iam_identity_replay_v1(
        p_operation_id, 'iam.identity.user.password_enroll',
        p_request_sha256, p_user_id
    );
    IF FOUND THEN RETURN; END IF;
    INSERT INTO iam_password_credentials (
        user_id, credential_version, state, algorithm, salt, tag,
        memory_kib, iterations, parallelism, legacy_bcrypt_hash,
        upgrade_required, revision, created_at, updated_at
    ) VALUES (
        p_user_id, 1, 'active', 'argon2id_v1', p_salt, p_tag,
        65536, 3, 4, NULL, false, 1, v_now, v_now
    );
    v_clock := iam_identity_record_v1(
        p_operation_id, 'iam.identity.user.password_enroll',
        p_request_sha256, p_user_id, 1,
        pg_catalog.sha256(p_salt || p_tag)
    );
    RETURN QUERY SELECT p_user_id, 1::bigint, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_password_enroll_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_salt bytea, p_tag bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_profile_assert_v1(text, uuid, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_profile_assert_v1(p_resource_kind text, p_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_values jsonb;
BEGIN
    IF p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_schema_id IS NULL OR pg_catalog.octet_length(p_profile_document) > 1048576 OR
       pg_catalog.octet_length(p_profile_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.sha256(p_profile_document) IS DISTINCT FROM p_profile_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM identity profile input is invalid';
    END IF;
    v_values := pg_catalog.convert_from(p_profile_document, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_values) <> 'object' OR NOT EXISTS (
        SELECT 1 FROM iam_profile_schema_versions AS schema_version
        WHERE schema_version.id = p_schema_id
          AND schema_version.resource_kind = p_resource_kind
          AND schema_version.state = 'active'
    ) OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_each(v_values) AS entry(key, value)
        WHERE entry.key !~
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR pg_catalog.jsonb_typeof(entry.value) = 'null'
           OR NOT EXISTS (
              SELECT 1 FROM iam_profile_field_revisions AS field
              WHERE field.schema_version_id = p_schema_id
                AND field.resource_kind = p_resource_kind
                AND field.field_id = entry.key::uuid AND field.field_state = 'active'
           )
    ) OR EXISTS (
        SELECT 1 FROM iam_profile_field_revisions AS required
        WHERE required.schema_version_id = p_schema_id
          AND required.resource_kind = p_resource_kind
          AND required.field_state = 'active' AND required.required
          AND NOT v_values ? required.field_id::text
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM identity profile contract is invalid';
    END IF;
    RETURN v_values;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_identity_profile_assert_v1(p_resource_kind text, p_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_identity_profile_assert_v2(text, uuid, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_profile_assert_v2(p_resource_kind text, p_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_values jsonb;
    v_source_schema_id uuid;
    v_plan_id uuid;
    v_target_schema_id uuid;
BEGIN
    IF p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_schema_id IS NULL OR
       pg_catalog.octet_length(p_profile_document) > 1048576 OR
       pg_catalog.octet_length(p_profile_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.sha256(p_profile_document) IS DISTINCT FROM p_profile_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM identity profile input is invalid';
    END IF;
    SELECT source.id INTO v_source_schema_id
    FROM iam_profile_schema_versions AS source
    WHERE source.resource_kind = p_resource_kind AND source.state = 'active'
    FOR SHARE;
    SELECT plan.id, plan.target_schema_id INTO v_plan_id, v_target_schema_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id AND target.state = 'draft'
    WHERE plan.resource_kind = p_resource_kind
      AND plan.source_schema_id = v_source_schema_id
      AND plan.state IN ('planned', 'running', 'verified')
    FOR SHARE OF plan, source, target;
    IF v_source_schema_id IS NULL OR
       (v_plan_id IS NULL AND p_schema_id <> v_source_schema_id) OR
       (v_plan_id IS NOT NULL AND p_schema_id <> v_target_schema_id) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM identity profile write schema is stale';
    END IF;
    v_values := pg_catalog.convert_from(p_profile_document, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_values) <> 'object' OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_each(v_values) AS entry(key, value)
        WHERE entry.key !~
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR pg_catalog.jsonb_typeof(entry.value) = 'null'
           OR NOT EXISTS (
              SELECT 1 FROM iam_profile_field_revisions AS field
              WHERE field.schema_version_id = p_schema_id
                AND field.resource_kind = p_resource_kind
                AND field.field_id = entry.key::uuid AND (
                    field.field_state = 'active' OR
                    field.field_state = 'retired' AND v_plan_id IS NOT NULL AND EXISTS (
                        SELECT 1 FROM iam_profile_field_revisions AS source_field
                        WHERE source_field.schema_version_id = v_source_schema_id
                          AND source_field.resource_kind = p_resource_kind
                          AND source_field.field_id = field.field_id
                          AND source_field.semantic_sha256 = field.semantic_sha256
                    )
                )
           )
    ) OR EXISTS (
        SELECT 1 FROM iam_profile_field_revisions AS required
        WHERE required.schema_version_id = p_schema_id
          AND required.resource_kind = p_resource_kind
          AND required.field_state = 'active' AND required.required
          AND NOT v_values ? required.field_id::text
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM identity profile contract is invalid';
    END IF;
    RETURN v_values;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_identity_profile_assert_v2(p_resource_kind text, p_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_identity_query_assert_v1(name, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_query_assert_v1(p_scope_schema name, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_actor_id IS NULL OR p_permission_id IS NULL OR
       NOT EXISTS (
          SELECT 1 FROM iam_users AS actor
          WHERE actor.id = p_actor_id AND actor.status = 'active'
            AND actor.token_version = p_expected_token_version
            AND actor.authorization_version = p_expected_authorization_version
       ) OR NOT iam_user_has_rbac_evidence_v2(p_actor_id, p_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM identity query authority is denied';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_query_assert_v1(p_scope_schema name, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_identity_record_v1(uuid, text, bytea, uuid, bigint, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_record_v1(p_operation_id uuid, p_command_key text, p_request_sha256 bytea, p_result_id uuid, p_result_revision bigint, p_result_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_clock bigint;
BEGIN
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM identity authorization clock is unavailable';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, p_command_key, p_request_sha256, v_clock,
        p_command_key || '.succeeded', p_result_id, p_result_revision,
        p_result_sha256, v_now
    );
    RETURN v_clock;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_record_v1(p_operation_id uuid, p_command_key text, p_request_sha256 bytea, p_result_id uuid, p_result_revision bigint, p_result_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_identity_replay_v1(uuid, text, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_replay_v1(p_operation_id uuid, p_command_key text, p_request_sha256 bytea, p_result_id uuid) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_command text; v_request bytea; v_id uuid;
    v_revision bigint; v_clock bigint;
BEGIN
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_command, v_request, v_id, v_revision, v_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF NOT FOUND THEN RETURN; END IF;
    IF v_command IS DISTINCT FROM p_command_key OR
       v_request IS DISTINCT FROM p_request_sha256 OR
       v_id IS DISTINCT FROM p_result_id THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'IAM identity operation identity was reused';
    END IF;
    RETURN QUERY SELECT v_id, v_revision, v_clock, true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_replay_v1(p_operation_id uuid, p_command_key text, p_request_sha256 bytea, p_result_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_identity_role_create_v1(name, uuid, uuid, bytea, uuid, text, uuid, uuid, text, text, boolean, uuid, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_role_create_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_role_id uuid, p_scope_kind text, p_scope_id uuid, p_organization_id uuid, p_name text, p_description text, p_is_default boolean, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_values jsonb; v_clock bigint;
BEGIN
    IF p_role_id IS NULL OR p_scope_kind NOT IN ('tenant', 'organization') OR
       (p_scope_kind = 'tenant' AND (p_scope_id <> p_tenant_id OR p_organization_id IS NOT NULL)) OR
       (p_scope_kind = 'organization' AND (p_scope_id IS DISTINCT FROM p_organization_id OR
          NOT EXISTS (SELECT 1 FROM iam_organizations
                      WHERE id = p_organization_id AND status = 'active'))) OR
       pg_catalog.char_length(p_name) NOT BETWEEN 1 AND 255 OR
       p_name <> pg_catalog.btrim(p_name) OR
       pg_catalog.char_length(COALESCE(p_description, '')) > 2000 OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '23514',
          MESSAGE = 'IAM identity role create input is invalid'; END IF;
    RETURN QUERY SELECT * FROM iam_identity_replay_v1(
        p_operation_id, 'iam.identity.role.create', p_request_sha256, p_role_id
    );
    IF FOUND THEN RETURN; END IF;
    v_values := iam_identity_profile_assert_v1(
        'role', p_profile_schema_id, p_profile_document, p_profile_sha256
    );
    INSERT INTO iam_roles (
        id, scope_kind, scope_id, organization_id, name, name_key, description,
        status, is_protected, is_default, profile_resource_kind,
        profile_schema_version_id, profile_values, profile_sha256,
        revision, created_at, updated_at
    ) VALUES (
        p_role_id, p_scope_kind, p_scope_id, p_organization_id, p_name,
        pg_catalog.convert_to(p_name, 'UTF8'), NULLIF(p_description, ''),
        'active', false, p_is_default, 'role', p_profile_schema_id,
        v_values, p_profile_sha256, 1, v_now, v_now
    );
    v_clock := iam_identity_record_v1(
        p_operation_id, 'iam.identity.role.create', p_request_sha256,
        p_role_id, 1, p_request_sha256
    );
    RETURN QUERY SELECT p_role_id, 1::bigint, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_identity_role_create_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_role_id uuid, p_scope_kind text, p_scope_id uuid, p_organization_id uuid, p_name text, p_description text, p_is_default boolean, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

