CREATE FUNCTION __tenant_schema__.iam_identity_role_update_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_role_id uuid, p_expected_revision bigint, p_name text, p_description text, p_is_default boolean, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_values jsonb; v_revision bigint; v_clock bigint;
BEGIN
    IF p_role_id IS NULL OR p_expected_revision < 1 OR
       pg_catalog.char_length(p_name) NOT BETWEEN 1 AND 255 OR
       p_name <> pg_catalog.btrim(p_name) OR
       pg_catalog.char_length(COALESCE(p_description, '')) > 2000 OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '23514',
