-- Name: iam_identity_user_list_v2(name, uuid, integer, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_identity_user_list_v2(p_scope_schema name, p_after_id uuid, p_limit integer, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(id uuid, status text, token_version bigint, authorization_version bigint, revision bigint, identifier_id uuid, email_display text, email_normalized text, role_ids uuid[], organization_ids uuid[], created_at timestamp with time zone, updated_at timestamp with time zone, tombstoned_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit NOT BETWEEN 1 AND 100 OR NOT iam_identity_query_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY
    SELECT principal.id, principal.status, principal.token_version,
        principal.authorization_version, principal.revision,
        email.id, email.display_value, email.normalized_value,
        COALESCE((SELECT pg_catalog.array_agg(assignment.role_id ORDER BY assignment.role_id)
          FROM iam_user_role_assignments AS assignment
          WHERE assignment.user_id = principal.id AND assignment.state = 'active'),
          '{}'::uuid[]),
        COALESCE((SELECT pg_catalog.array_agg(membership.organization_id
                                              ORDER BY membership.organization_id)
          FROM iam_organization_memberships AS membership
          WHERE membership.user_id = principal.id AND membership.state = 'active'),
          '{}'::uuid[]),
        principal.created_at, principal.updated_at, principal.tombstoned_at
    FROM iam_users AS principal
    JOIN LATERAL (
        SELECT source.id, source.display_value, source.normalized_value
        FROM iam_user_identifiers AS source
        WHERE source.user_id = principal.id AND source.kind = 'email_v1'
          AND source.state <> 'retired'
        ORDER BY source.revision DESC LIMIT 1
    ) AS email ON true
    WHERE p_after_id IS NULL OR principal.id > p_after_id
    ORDER BY principal.id LIMIT p_limit;
END;
$$;


