--
-- Name: iam_initial_admin_setup_accept_v1(name, uuid, uuid, bytea, bytea, text, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_admin_setup_accept_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_salt bytea, p_tag bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_setup iam_initial_admin_setups%ROWTYPE;
    v_user_id uuid;
    v_identifier_id uuid;
    v_token_state text;
    v_expires_at timestamptz;
    v_credential_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_tenant_id IS NULL OR p_operation_id IS NULL
       OR pg_catalog.octet_length(p_request_sha256) <> 32
       OR pg_catalog.octet_length(p_selector) <> 16
       OR p_hash_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$'
       OR pg_catalog.octet_length(p_secret_hmac) <> 32
       OR pg_catalog.octet_length(p_binding_sha256) <> 32
       OR pg_catalog.octet_length(p_salt) <> 16
       OR pg_catalog.octet_length(p_tag) <> 32
       OR NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id=p_tenant_id
             AND tenant.schema_name=p_scope_schema::text
             AND tenant.status='active' AND tenant.deleted_at IS NULL
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id,'iam.initial_admin_setup.accept',p_request_sha256,NULL
    );
    IF FOUND THEN RETURN; END IF;
    SELECT setup.* INTO v_setup
    FROM iam_initial_admin_setups AS setup
    JOIN iam_one_time_tokens AS token ON token.id=setup.token_id
    WHERE token.purpose='initial_admin_setup.v1'
      AND token.selector=p_selector AND token.hash_key_id=p_hash_key_id
      AND token.secret_hmac=p_secret_hmac
      AND token.binding_sha256=p_binding_sha256
    FOR UPDATE OF setup,token;
    IF NOT FOUND OR v_setup.state<>'pending' THEN
        RAISE EXCEPTION USING ERRCODE='28000',
            MESSAGE='initial admin setup proof is invalid';
    END IF;
    SELECT token.user_id,token.identifier_id,token.state,token.expires_at
    INTO v_user_id,v_identifier_id,v_token_state,v_expires_at
    FROM iam_one_time_tokens AS token WHERE token.id=v_setup.token_id;
    IF v_token_state<>'pending' OR v_expires_at<=v_now
       OR v_user_id IS DISTINCT FROM v_setup.user_id
       OR EXISTS (
           SELECT 1 FROM iam_password_credentials AS credential
           WHERE credential.user_id=v_setup.user_id
       ) OR NOT EXISTS (
           SELECT 1 FROM iam_users AS app_user
           JOIN iam_user_identifiers AS identifier
             ON identifier.id=v_identifier_id
            AND identifier.user_id=app_user.id
           WHERE app_user.id=v_setup.user_id AND app_user.status='active'
             AND app_user.identity_kind='human'
             AND identifier.kind='email_v1' AND identifier.state='active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='28000',
            MESSAGE='initial admin setup target is invalid';
    END IF;
    INSERT INTO iam_password_credentials (
        user_id,credential_version,state,algorithm,salt,tag,memory_kib,
        iterations,parallelism,upgrade_required,revision,created_at,updated_at
    ) VALUES (
        v_setup.user_id,1,'active','argon2id_v1',p_salt,p_tag,65536,
        3,4,false,1,v_now,v_now
    ) RETURNING revision INTO v_credential_revision;
    UPDATE iam_one_time_tokens SET state='consumed',consumed_at=v_now,
        revision=revision+1,updated_at=v_now WHERE id=v_setup.token_id;
    UPDATE iam_one_time_tokens SET state='revoked',revoked_at=v_now,
        revision=revision+1,updated_at=v_now
    WHERE user_id=v_setup.user_id AND state='pending';
    UPDATE iam_initial_admin_setups SET state='accepted',accepted_at=v_now,
        revision=revision+1 WHERE installation_operation_id=
        v_setup.installation_operation_id;
    UPDATE iam_sessions SET state='revoked',revoked_at=v_now,
        revision=revision+1,updated_at=v_now
    WHERE user_id=v_setup.user_id AND state='active';
    UPDATE iam_refresh_families SET state='revoked',
        revoke_reason='initial_admin_setup',revoked_at=v_now,
        revision=revision+1,updated_at=v_now
    WHERE user_id=v_setup.user_id AND state='active';
    UPDATE iam_refresh_tokens SET state='revoked',revoked_at=v_now,
        revision=revision+1,updated_at=v_now
    WHERE family_id IN (SELECT id FROM iam_refresh_families
        WHERE user_id=v_setup.user_id) AND state='active';
    SELECT result.token_version,result.authorization_version
    INTO STRICT v_token_version,v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id,'iam.initial_admin_setup.accept',p_request_sha256,
        v_setup.user_id,v_setup.user_id,v_credential_revision,
        'credential_target',v_setup.user_id,'password_credential',true,true
    ) AS result;
    PERFORM platform.tenancy_customer_setup_accepted_v1(
        v_setup.installation_operation_id,p_tenant_id,v_setup.artifact_id
    );
    RETURN QUERY SELECT v_setup.user_id,v_setup.user_id,
        v_credential_revision,v_token_version,v_authorization_version,false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_initial_admin_setup_accept_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_salt bytea, p_tag bytea) OWNER TO harpy_owner;

--
-- Name: iam_initial_admin_setup_finalize_v1(name, uuid, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_admin_setup_finalize_v1(p_scope_schema name, p_operation_id uuid, p_tenant_id uuid, p_manifest_sha256 text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_stage jsonb;
    v_stage_user_id uuid;
    v_stage_identifier_id uuid;
    v_stage_normalized_email text;
    v_stage_token_id uuid;
    v_stage_selector bytea;
    v_stage_hash_key_id text;
    v_stage_secret_hmac bytea;
    v_stage_binding_sha256 bytea;
    v_stage_artifact_id uuid;
    v_stage_artifact_ref text;
    v_stage_kms_key_id text;
    v_stage_nonce bytea;
    v_stage_ciphertext bytea;
    v_stage_authentication_tag bytea;
    v_stage_aad_sha256 bytea;
    v_stage_ciphertext_sha256 bytea;
    v_existing iam_initial_admin_setups%ROWTYPE;
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_expires timestamptz;
BEGIN
    v_expires := v_now + INTERVAL '24 hours';
    v_stage := platform.iam_initial_admin_setup_stage_read_v1(
        p_operation_id,p_tenant_id
    );
    v_stage_user_id := (v_stage->>'user_id')::uuid;
    v_stage_identifier_id := (v_stage->>'identifier_id')::uuid;
    v_stage_normalized_email := v_stage->>'normalized_email';
    v_stage_token_id := (v_stage->>'token_id')::uuid;
    v_stage_selector := (v_stage->>'selector')::bytea;
    v_stage_hash_key_id := v_stage->>'hash_key_id';
    v_stage_secret_hmac := (v_stage->>'secret_hmac')::bytea;
    v_stage_binding_sha256 := (v_stage->>'binding_sha256')::bytea;
    v_stage_artifact_id := (v_stage->>'artifact_id')::uuid;
    v_stage_artifact_ref := v_stage->>'artifact_ref';
    v_stage_kms_key_id := v_stage->>'kms_key_id';
    v_stage_nonce := (v_stage->>'nonce')::bytea;
    v_stage_ciphertext := (v_stage->>'ciphertext')::bytea;
    v_stage_authentication_tag := (v_stage->>'authentication_tag')::bytea;
    v_stage_aad_sha256 := (v_stage->>'aad_sha256')::bytea;
    v_stage_ciphertext_sha256 := (v_stage->>'ciphertext_sha256')::bytea;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_operation_id IS NULL OR p_tenant_id IS NULL
       OR p_manifest_sha256 !~ '^[0-9a-f]{64}$'
       OR NOT platform.tenancy_activation_assert_v2(
           p_operation_id,p_tenant_id,p_scope_schema
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='initial admin setup finalization denied';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM iam_installation_identity_facts AS fact
        JOIN iam_users AS app_user ON app_user.id=fact.first_user_id
        JOIN iam_user_identifiers AS identifier
          ON identifier.id=v_stage_identifier_id
         AND identifier.user_id=app_user.id
        WHERE fact.operation_id=p_operation_id
          AND fact.tenant_id=p_tenant_id
          AND fact.first_user_id=v_stage_user_id
          AND fact.normalized_email=v_stage_normalized_email
          AND app_user.status='active' AND app_user.identity_kind='human'
          AND identifier.kind='email_v1'
          AND identifier.normalized_value=v_stage_normalized_email
          AND identifier.state='active' AND identifier.revision=1
    ) THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='initial admin setup identity conflicts';
    END IF;
    SELECT * INTO v_existing
    FROM iam_initial_admin_setups AS setup
    WHERE setup.installation_operation_id=p_operation_id
    FOR SHARE;
    IF FOUND THEN
        IF v_existing.user_id IS DISTINCT FROM v_stage_user_id
           OR v_existing.token_id IS DISTINCT FROM v_stage_token_id
           OR v_existing.artifact_id IS DISTINCT FROM v_stage_artifact_id
           OR v_existing.generation IS DISTINCT FROM 1::bigint THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='initial admin setup replay conflicts';
        END IF;
        RETURN v_existing.artifact_id;
    END IF;
    INSERT INTO iam_one_time_tokens (
        id,purpose,user_id,identifier_id,identifier_kind,
        identifier_revision,portal_binding_id,portal_setup_revision,
        selector,hash_key_id,secret_hmac,binding_sha256,state,
        attempt_count,revision,created_at,updated_at,expires_at,purge_after
    ) VALUES (
        v_stage_token_id,'initial_admin_setup.v1',v_stage_user_id,
        v_stage_identifier_id,'email_v1',1,NULL,NULL,v_stage_selector,
        v_stage_hash_key_id,v_stage_secret_hmac,v_stage_binding_sha256,
        'pending',0,1,v_now,v_now,v_expires,v_expires + INTERVAL '24 hours'
    );
    INSERT INTO iam_lifecycle_delivery_artifacts (
        id,purpose,subject_user_id,resource_id,recipient_identifier_id,
        token_id,artifact_ref,kms_key_id,nonce,ciphertext,
        authentication_tag,aad_sha256,ciphertext_sha256,revision,
        created_at,expires_at
    ) VALUES (
        v_stage_artifact_id,'initial_admin_setup.v1',v_stage_user_id,
        v_stage_identifier_id,v_stage_identifier_id,v_stage_token_id,
        v_stage_artifact_ref,v_stage_kms_key_id,v_stage_nonce,
        v_stage_ciphertext,v_stage_authentication_tag,v_stage_aad_sha256,
        v_stage_ciphertext_sha256,1,v_now,v_expires
    );
    INSERT INTO iam_initial_admin_setups (
        installation_operation_id,user_id,token_id,artifact_id,generation,
        state,revision,created_at,accepted_at,revoked_at
    ) VALUES (
        p_operation_id,v_stage_user_id,v_stage_token_id,v_stage_artifact_id,
        1,'pending',1,v_now,NULL,NULL
    );
    PERFORM platform.tenancy_customer_setup_artifact_bind_v1(
        p_operation_id,p_tenant_id,v_stage_artifact_id
    );
    RETURN v_stage_artifact_id;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_initial_admin_setup_finalize_v1(p_scope_schema name, p_operation_id uuid, p_tenant_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_initial_admin_setup_finalize_v2(name, uuid, uuid, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_admin_setup_finalize_v2(p_scope_schema name, p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_manifest_sha256 text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    SET application_name TO 'harpy-v2:core-operator-initialize'
    AS $$
DECLARE
    v_artifact_id uuid;
BEGIN
    IF NOT platform.tenancy_activation_step_context_assert_v1(
        p_operation_id, 'iam.initialize_tenant_identity',
        p_environment_id, p_tenant_id, p_scope_schema,
        'saas_customer_tenant_provision'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'initial admin setup capability required';
    END IF;
    v_artifact_id := iam_initial_admin_setup_finalize_v1(
        p_scope_schema, p_operation_id, p_tenant_id, p_manifest_sha256
    );
    IF NOT platform.tenancy_activation_step_consume_v1(
        p_operation_id, 'iam.initialize_tenant_identity'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'initial admin setup capability consume failed';
    END IF;
    RETURN v_artifact_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_initial_admin_setup_finalize_v2(p_scope_schema name, p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_initial_admin_setup_reissue_v1(name, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_admin_setup_reissue_v1(p_scope_schema name, p_operation_id uuid, p_reissue_operation_id uuid, p_tenant_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_stage jsonb;
    v_stage_user_id uuid;
    v_stage_identifier_id uuid;
    v_stage_normalized_email text;
    v_stage_token_id uuid;
    v_stage_selector bytea;
    v_stage_hash_key_id text;
    v_stage_secret_hmac bytea;
    v_stage_binding_sha256 bytea;
    v_stage_artifact_id uuid;
    v_stage_artifact_ref text;
    v_stage_kms_key_id text;
    v_stage_nonce bytea;
    v_stage_ciphertext bytea;
    v_stage_authentication_tag bytea;
    v_stage_aad_sha256 bytea;
    v_stage_ciphertext_sha256 bytea;
    v_setup iam_initial_admin_setups%ROWTYPE;
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_expires timestamptz;
BEGIN
    v_expires := v_now + INTERVAL '24 hours';
    v_stage := platform.iam_initial_admin_setup_stage_read_v1(
        p_reissue_operation_id,p_tenant_id
    );
    v_stage_user_id := (v_stage->>'user_id')::uuid;
    v_stage_identifier_id := (v_stage->>'identifier_id')::uuid;
    v_stage_normalized_email := v_stage->>'normalized_email';
    v_stage_token_id := (v_stage->>'token_id')::uuid;
    v_stage_selector := (v_stage->>'selector')::bytea;
    v_stage_hash_key_id := v_stage->>'hash_key_id';
    v_stage_secret_hmac := (v_stage->>'secret_hmac')::bytea;
    v_stage_binding_sha256 := (v_stage->>'binding_sha256')::bytea;
    v_stage_artifact_id := (v_stage->>'artifact_id')::uuid;
    v_stage_artifact_ref := v_stage->>'artifact_ref';
    v_stage_kms_key_id := v_stage->>'kms_key_id';
    v_stage_nonce := (v_stage->>'nonce')::bytea;
    v_stage_ciphertext := (v_stage->>'ciphertext')::bytea;
    v_stage_authentication_tag := (v_stage->>'authentication_tag')::bytea;
    v_stage_aad_sha256 := (v_stage->>'aad_sha256')::bytea;
    v_stage_ciphertext_sha256 := (v_stage->>'ciphertext_sha256')::bytea;
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-api'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_operation_id IS NULL OR p_reissue_operation_id IS NULL
       OR p_tenant_id IS NULL
       OR NOT platform.tenancy_activation_assert_v2(
           p_operation_id,p_tenant_id,p_scope_schema
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='initial admin setup reissue denied';
    END IF;
    SELECT * INTO v_setup
    FROM iam_initial_admin_setups AS setup
    WHERE setup.installation_operation_id=p_operation_id
    FOR UPDATE;
    IF NOT FOUND OR v_setup.state<>'pending'
       OR v_setup.user_id IS DISTINCT FROM v_stage_user_id
       OR NOT EXISTS (
           SELECT 1 FROM iam_users AS app_user
           JOIN iam_user_identifiers AS identifier
             ON identifier.id=v_stage_identifier_id
            AND identifier.user_id=app_user.id
           WHERE app_user.id=v_stage_user_id AND app_user.status='active'
             AND app_user.identity_kind='human' AND identifier.kind='email_v1'
             AND identifier.normalized_value=v_stage_normalized_email
             AND identifier.state='active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='initial admin setup reissue identity conflicts';
    END IF;
    IF v_setup.last_reissue_operation_id=p_reissue_operation_id
       AND v_setup.artifact_id=v_stage_artifact_id
       AND v_setup.token_id=v_stage_token_id THEN
        PERFORM platform.tenancy_customer_setup_reissue_v1(
            p_operation_id,p_reissue_operation_id,p_tenant_id,
            v_setup.artifact_id,v_stage_artifact_id
        );
        PERFORM platform.platform_async_initial_admin_setup_reissue_enqueue_v1(
            p_operation_id,p_reissue_operation_id,p_tenant_id,
            v_stage_artifact_id,v_stage_artifact_ref,p_scope_schema
        );
        RETURN v_stage_artifact_id;
    END IF;
    PERFORM platform.tenancy_customer_setup_reissue_v1(
        p_operation_id,p_reissue_operation_id,p_tenant_id,
        v_setup.artifact_id,v_stage_artifact_id
    );
    UPDATE iam_one_time_tokens
    SET state='revoked',revoked_at=v_now,revision=revision+1,updated_at=v_now
    WHERE id=v_setup.token_id AND state='pending';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='initial admin setup token reissue conflicts';
    END IF;
    DELETE FROM iam_lifecycle_delivery_artifacts
    WHERE id=v_setup.artifact_id;
    INSERT INTO iam_one_time_tokens (
        id,purpose,user_id,identifier_id,identifier_kind,
        identifier_revision,portal_binding_id,portal_setup_revision,
        selector,hash_key_id,secret_hmac,binding_sha256,state,
        attempt_count,revision,created_at,updated_at,expires_at,purge_after
    ) VALUES (
        v_stage_token_id,'initial_admin_setup.v1',v_stage_user_id,
        v_stage_identifier_id,'email_v1',1,NULL,NULL,v_stage_selector,
        v_stage_hash_key_id,v_stage_secret_hmac,v_stage_binding_sha256,
        'pending',0,1,v_now,v_now,v_expires,v_expires + INTERVAL '24 hours'
    );
    INSERT INTO iam_lifecycle_delivery_artifacts (
        id,purpose,subject_user_id,resource_id,recipient_identifier_id,
        token_id,artifact_ref,kms_key_id,nonce,ciphertext,
        authentication_tag,aad_sha256,ciphertext_sha256,revision,
        created_at,expires_at
    ) VALUES (
        v_stage_artifact_id,'initial_admin_setup.v1',v_stage_user_id,
        v_stage_identifier_id,v_stage_identifier_id,v_stage_token_id,
        v_stage_artifact_ref,v_stage_kms_key_id,v_stage_nonce,
        v_stage_ciphertext,v_stage_authentication_tag,v_stage_aad_sha256,
        v_stage_ciphertext_sha256,1,v_now,v_expires
    );
    UPDATE iam_initial_admin_setups
    SET token_id=v_stage_token_id,artifact_id=v_stage_artifact_id,
        generation=generation+1,revision=revision+1,
        last_reissue_operation_id=p_reissue_operation_id
    WHERE installation_operation_id=p_operation_id;
    PERFORM platform.platform_async_initial_admin_setup_reissue_enqueue_v1(
        p_operation_id,p_reissue_operation_id,p_tenant_id,
        v_stage_artifact_id,v_stage_artifact_ref,p_scope_schema
    );
    RETURN v_stage_artifact_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_initial_admin_setup_reissue_v1(p_scope_schema name, p_operation_id uuid, p_reissue_operation_id uuid, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_initial_password_complete_v1(name, uuid, bytea, bytea, bytea, bigint, uuid, uuid, bigint, bigint, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_password_complete_v1(p_scope_schema name, p_tenant_id uuid, p_selector bytea, p_secret_hmac bytea, p_csrf_hmac bytea, p_expected_continuation_revision bigint, p_user_id uuid, p_credential_id uuid, p_expected_credential_version bigint, p_expected_credential_revision bigint, p_salt bytea, p_tag bytea, p_request_sha256 bytea) RETURNS TABLE(user_id uuid, access_mode_id uuid, user_revision bigint, token_version bigint, authorization_version bigint, access_mode_revision bigint, credential_version bigint, credential_revision bigint, continuation_revision bigint, installation_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_continuation iam_initial_password_continuations%ROWTYPE;
    v_marker iam_installation_password_credentials%ROWTYPE;
    v_credential_revision bigint;
    v_access_mode_id uuid;
    v_access_mode_revision bigint;
    v_user_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM initial password completion scope is invalid';
    END IF;
    IF p_tenant_id IS NULL OR p_user_id IS NULL OR p_credential_id IS NULL OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_csrf_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_salt) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_tag) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_expected_continuation_revision OPERATOR(pg_catalog.<) 1 OR
       p_expected_credential_version OPERATOR(pg_catalog.<) 1 OR
       p_expected_credential_revision OPERATOR(pg_catalog.<) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM initial password completion evidence is invalid';
    END IF;
    SELECT continuation.*
    INTO v_continuation
    FROM iam_initial_password_continuations AS continuation
    WHERE continuation.selector OPERATOR(pg_catalog.=) p_selector
    FOR UPDATE;
    IF NOT FOUND OR v_continuation.tenant_id IS DISTINCT FROM p_tenant_id OR
       v_continuation.user_id IS DISTINCT FROM p_user_id OR
       v_continuation.credential_id IS DISTINCT FROM p_credential_id OR
       v_continuation.credential_version IS DISTINCT FROM
            p_expected_credential_version OR
       v_continuation.credential_revision IS DISTINCT FROM
            p_expected_credential_revision OR
       v_continuation.state IS DISTINCT FROM 'active' OR
       v_continuation.revision IS DISTINCT FROM
            p_expected_continuation_revision OR
       v_continuation.secret_hmac IS DISTINCT FROM p_secret_hmac OR
       v_continuation.csrf_hmac IS DISTINCT FROM p_csrf_hmac OR
       v_continuation.policy_attempts OPERATOR(pg_catalog.>=) 5 OR
       v_now OPERATOR(pg_catalog.<) v_continuation.issued_at OR
       v_now OPERATOR(pg_catalog.>=) v_continuation.expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM initial password continuation changed';
    END IF;
    SELECT marker.*
    INTO v_marker
    FROM iam_installation_password_credentials AS marker
    WHERE marker.credential_id OPERATOR(pg_catalog.=) p_credential_id
    FOR UPDATE;
    IF NOT FOUND OR v_marker.user_id IS DISTINCT FROM p_user_id OR
       v_marker.installation_operation_id IS DISTINCT FROM
            v_continuation.installation_operation_id OR
       v_marker.credential_version IS DISTINCT FROM
            p_expected_credential_version OR
       v_marker.state IS DISTINCT FROM 'active' OR EXISTS (
            SELECT 1 FROM iam_sessions AS session
            WHERE session.user_id OPERATOR(pg_catalog.=) p_user_id AND
                  session.state OPERATOR(pg_catalog.=) 'active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM installation credential changed';
    END IF;
    UPDATE iam_password_credentials AS credential
    SET credential_version =
            p_expected_credential_version OPERATOR(pg_catalog.+) 1,
        state = 'active', algorithm = 'argon2id_v1',
        salt = p_salt, tag = p_tag, memory_kib = 65536,
        iterations = 3, parallelism = 4, legacy_bcrypt_hash = NULL,
        upgrade_required = false,
        revision = credential.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now, last_used_at = v_now, invalidated_at = NULL
    WHERE credential.user_id OPERATOR(pg_catalog.=) p_user_id AND
          credential.credential_version OPERATOR(pg_catalog.=)
              p_expected_credential_version AND
          credential.revision OPERATOR(pg_catalog.=)
              p_expected_credential_revision AND
          credential.state OPERATOR(pg_catalog.=) 'reset_required'
    RETURNING credential.revision INTO v_credential_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM initial password credential CAS changed';
    END IF;
    UPDATE iam_installation_password_credentials AS marker
    SET state = 'retired',
        revision = marker.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now, retired_at = v_now
    WHERE marker.credential_id OPERATOR(pg_catalog.=) p_credential_id;
    UPDATE iam_initial_password_continuations AS continuation
    SET state = 'consumed',
        revision = continuation.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now, consumed_at = v_now
    WHERE continuation.selector OPERATOR(pg_catalog.=) p_selector;
    SELECT recorded.token_version, recorded.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        v_continuation.installation_operation_id,
        'iam.initial_password.complete', p_request_sha256,
        p_user_id, p_user_id, v_credential_revision,
        'credential_target', p_user_id, 'password_credential', true, false
    ) AS recorded;
    SELECT principal.revision
    INTO STRICT v_user_revision
    FROM iam_users AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_user_id;
    SELECT access.id, access.revision
    INTO STRICT v_access_mode_id, v_access_mode_revision
    FROM iam_user_access_modes AS access
    WHERE access.user_id OPERATOR(pg_catalog.=) p_user_id AND
          access.mode OPERATOR(pg_catalog.=) 'operator_console' AND
          access.state OPERATOR(pg_catalog.=) 'active';
    RETURN QUERY SELECT p_user_id, v_access_mode_id, v_user_revision,
        v_token_version, v_authorization_version, v_access_mode_revision,
        p_expected_credential_version OPERATOR(pg_catalog.+) 1,
        v_credential_revision,
        p_expected_continuation_revision OPERATOR(pg_catalog.+) 1,
        v_marker.revision OPERATOR(pg_catalog.+) 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_initial_password_complete_v1(p_scope_schema name, p_tenant_id uuid, p_selector bytea, p_secret_hmac bytea, p_csrf_hmac bytea, p_expected_continuation_revision bigint, p_user_id uuid, p_credential_id uuid, p_expected_credential_version bigint, p_expected_credential_revision bigint, p_salt bytea, p_tag bytea, p_request_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_initial_password_continuations; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.iam_initial_password_continuations (
    selector bytea NOT NULL,
    tenant_id uuid NOT NULL,
    user_id uuid NOT NULL,
    installation_operation_id uuid CONSTRAINT iam_initial_password_continu_installation_operation_id_not_null NOT NULL,
    credential_id uuid NOT NULL,
    credential_version bigint NOT NULL,
    credential_revision bigint NOT NULL,
    secret_key_id text NOT NULL COLLATE pg_catalog."C",
    secret_hmac bytea NOT NULL,
    csrf_key_id text NOT NULL COLLATE pg_catalog."C",
    csrf_hmac bytea NOT NULL,
    state text NOT NULL,
    policy_attempts smallint NOT NULL,
    revision bigint NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    CONSTRAINT iam_initial_password_continuations_attempt_check CHECK (((policy_attempts >= 0) AND (policy_attempts <= 5))),
    CONSTRAINT iam_initial_password_continuations_key_check CHECK (((secret_key_id ~ '^[A-Za-z0-9_-]{16,64}$'::text) AND (csrf_key_id ~ '^[A-Za-z0-9_-]{16,64}$'::text) AND (secret_key_id <> csrf_key_id) AND (octet_length(secret_hmac) = 32) AND (octet_length(csrf_hmac) = 32))),
    CONSTRAINT iam_initial_password_continuations_lifetime_check CHECK (((expires_at = (issued_at + '00:10:00'::interval)) AND (updated_at >= issued_at) AND ((consumed_at IS NULL) OR (consumed_at >= issued_at)))),
    CONSTRAINT iam_initial_password_continuations_selector_check CHECK ((octet_length(selector) = 16)),
    CONSTRAINT iam_initial_password_continuations_state_check CHECK ((state = ANY (ARRAY['active'::text, 'superseded'::text, 'consumed'::text, 'exhausted'::text, 'expired'::text]))),
    CONSTRAINT iam_initial_password_continuations_state_shape_check CHECK ((((state = 'active'::text) AND (consumed_at IS NULL) AND (policy_attempts < 5)) OR ((state = 'exhausted'::text) AND (consumed_at IS NOT NULL) AND (policy_attempts = 5)) OR ((state = ANY (ARRAY['superseded'::text, 'consumed'::text, 'expired'::text])) AND (consumed_at IS NOT NULL)))),
    CONSTRAINT iam_initial_password_continuations_version_check CHECK (((credential_version > 0) AND (credential_revision > 0) AND (revision > 0)))
);


ALTER TABLE __tenant_schema__.iam_initial_password_continuations OWNER TO harpy_owner;

--
-- Name: iam_initial_password_continuation_v1(name, uuid, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_password_continuation_v1(p_scope_schema name, p_tenant_id uuid, p_selector bytea) RETURNS SETOF __tenant_schema__.iam_initial_password_continuations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM initial password continuation scope is invalid';
    END IF;
    RETURN QUERY
    SELECT continuation.*
    FROM iam_initial_password_continuations AS continuation
    WHERE continuation.tenant_id OPERATOR(pg_catalog.=) p_tenant_id AND
          continuation.selector OPERATOR(pg_catalog.=) p_selector;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_initial_password_continuation_v1(p_scope_schema name, p_tenant_id uuid, p_selector bytea) OWNER TO harpy_owner;

--
-- Name: iam_initial_password_credential_v1(name, uuid, uuid, text, bigint, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_password_credential_v1(p_scope_schema name, p_source_user_id uuid, p_source_identifier_id uuid, p_identifier_kind text, p_source_revision bigint, p_source_sha256 bytea) RETURNS TABLE(identifier_id uuid, user_id uuid, user_revision bigint, token_version bigint, authorization_version bigint, access_mode_id uuid, access_mode_revision bigint, installation_operation_id uuid, credential_id uuid, credential_version bigint, credential_revision bigint, algorithm text, salt bytea, tag bytea, memory_kib integer, iterations smallint, parallelism smallint, credential_created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_rows bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM initial password credential scope is invalid';
    END IF;
    IF p_source_user_id IS NULL OR p_source_identifier_id IS NULL OR
       p_identifier_kind IS DISTINCT FROM 'email_v1' OR
       p_source_revision OPERATOR(pg_catalog.<=) 0 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM initial password credential evidence is invalid';
    END IF;
    RETURN QUERY
    SELECT identifier.id, principal.id, principal.revision,
           principal.token_version, principal.authorization_version,
           access.id, access.revision, marker.installation_operation_id,
           marker.credential_id, credential.credential_version,
           credential.revision, credential.algorithm, credential.salt,
           credential.tag, credential.memory_kib, credential.iterations,
           credential.parallelism, credential.created_at
    FROM iam_user_identifiers AS identifier
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) identifier.user_id
    JOIN iam_user_access_modes AS access
      ON access.user_id OPERATOR(pg_catalog.=) principal.id AND
         access.mode OPERATOR(pg_catalog.=) 'operator_console'
    JOIN iam_password_credentials AS credential
      ON credential.user_id OPERATOR(pg_catalog.=) principal.id
    JOIN iam_installation_password_credentials AS marker
      ON marker.user_id OPERATOR(pg_catalog.=) principal.id AND
         marker.credential_version OPERATOR(pg_catalog.=)
            credential.credential_version
    WHERE identifier.id OPERATOR(pg_catalog.=) p_source_identifier_id AND
          identifier.user_id OPERATOR(pg_catalog.=) p_source_user_id AND
          identifier.kind OPERATOR(pg_catalog.=) p_identifier_kind AND
          identifier.revision OPERATOR(pg_catalog.=) p_source_revision AND
          identifier.normalized_sha256 OPERATOR(pg_catalog.=) p_source_sha256 AND
          identifier.state OPERATOR(pg_catalog.=) 'active' AND
          principal.status OPERATOR(pg_catalog.=) 'active' AND
          principal.identity_kind OPERATOR(pg_catalog.=) 'human' AND
          access.state OPERATOR(pg_catalog.=) 'active' AND
          credential.state OPERATOR(pg_catalog.=) 'reset_required' AND
          credential.algorithm OPERATOR(pg_catalog.=) 'argon2id_v1' AND
          marker.purpose OPERATOR(pg_catalog.=) 'installation_initial_v1' AND
          marker.state OPERATOR(pg_catalog.=) 'active';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows OPERATOR(pg_catalog.>) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '21000',
            MESSAGE = 'IAM initial password credential is ambiguous';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_initial_password_credential_v1(p_scope_schema name, p_source_user_id uuid, p_source_identifier_id uuid, p_identifier_kind text, p_source_revision bigint, p_source_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_initial_password_reject_v1(name, uuid, bytea, bytea, bytea, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_password_reject_v1(p_scope_schema name, p_tenant_id uuid, p_selector bytea, p_secret_hmac bytea, p_csrf_hmac bytea, p_expected_revision bigint) RETURNS TABLE(state text, policy_attempts smallint, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_continuation iam_initial_password_continuations%ROWTYPE;
    v_attempts smallint;
    v_state text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM initial password rejection scope is invalid';
    END IF;
    IF p_tenant_id IS NULL OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_csrf_hmac) IS DISTINCT FROM 32 OR
       p_expected_revision OPERATOR(pg_catalog.<) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM initial password rejection evidence is invalid';
    END IF;
    SELECT continuation.*
    INTO v_continuation
    FROM iam_initial_password_continuations AS continuation
    WHERE continuation.selector OPERATOR(pg_catalog.=) p_selector
    FOR UPDATE;
    IF NOT FOUND OR v_continuation.tenant_id IS DISTINCT FROM p_tenant_id OR
       v_continuation.state IS DISTINCT FROM 'active' OR
       v_continuation.revision IS DISTINCT FROM p_expected_revision OR
       v_continuation.secret_hmac IS DISTINCT FROM p_secret_hmac OR
       v_continuation.csrf_hmac IS DISTINCT FROM p_csrf_hmac OR
       v_continuation.policy_attempts OPERATOR(pg_catalog.>=) 5 OR
       v_now OPERATOR(pg_catalog.<) v_continuation.issued_at OR
       v_now OPERATOR(pg_catalog.>=) v_continuation.expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM initial password continuation changed';
    END IF;
    v_attempts := v_continuation.policy_attempts OPERATOR(pg_catalog.+) 1;
    v_state := CASE WHEN v_attempts OPERATOR(pg_catalog.=) 5
        THEN 'exhausted' ELSE 'active' END;
    UPDATE iam_initial_password_continuations AS continuation
    SET policy_attempts = v_attempts, state = v_state,
        revision = continuation.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now,
        consumed_at = CASE WHEN v_state OPERATOR(pg_catalog.=) 'exhausted'
            THEN v_now ELSE NULL END
    WHERE continuation.selector OPERATOR(pg_catalog.=) p_selector;
    RETURN QUERY SELECT v_state, v_attempts,
        p_expected_revision OPERATOR(pg_catalog.+) 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_initial_password_reject_v1(p_scope_schema name, p_tenant_id uuid, p_selector bytea, p_secret_hmac bytea, p_csrf_hmac bytea, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_initial_password_start_v1(name, uuid, uuid, uuid, uuid, bigint, bigint, bytea, text, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_initial_password_start_v1(p_scope_schema name, p_tenant_id uuid, p_user_id uuid, p_installation_operation_id uuid, p_credential_id uuid, p_credential_version bigint, p_credential_revision bigint, p_selector bytea, p_secret_key_id text, p_secret_hmac bytea, p_csrf_key_id text, p_csrf_hmac bytea) RETURNS TABLE(revision bigint, issued_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_existing iam_initial_password_continuations%ROWTYPE;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM initial password start scope is invalid';
    END IF;
    IF p_tenant_id IS NULL OR p_user_id IS NULL OR
       p_installation_operation_id IS NULL OR p_credential_id IS NULL OR
       p_credential_version OPERATOR(pg_catalog.<) 1 OR
       p_credential_revision OPERATOR(pg_catalog.<) 1 OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       pg_catalog.char_length(p_secret_key_id) NOT BETWEEN 16 AND 64 OR
       pg_catalog.char_length(p_csrf_key_id) NOT BETWEEN 16 AND 64 OR
       p_secret_key_id IS NOT DISTINCT FROM p_csrf_key_id OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_csrf_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM initial password start evidence is invalid';
    END IF;
    SELECT continuation.*
    INTO v_existing
    FROM iam_initial_password_continuations AS continuation
    WHERE continuation.selector OPERATOR(pg_catalog.=) p_selector;
    IF FOUND THEN
        IF v_existing.tenant_id IS DISTINCT FROM p_tenant_id OR
           v_existing.user_id IS DISTINCT FROM p_user_id OR
           v_existing.installation_operation_id IS DISTINCT FROM
                p_installation_operation_id OR
           v_existing.credential_id IS DISTINCT FROM p_credential_id OR
           v_existing.credential_version IS DISTINCT FROM p_credential_version OR
           v_existing.credential_revision IS DISTINCT FROM p_credential_revision OR
           v_existing.secret_key_id IS DISTINCT FROM p_secret_key_id OR
           v_existing.secret_hmac IS DISTINCT FROM p_secret_hmac OR
           v_existing.csrf_key_id IS DISTINCT FROM p_csrf_key_id OR
           v_existing.csrf_hmac IS DISTINCT FROM p_csrf_hmac OR
           v_existing.state IS DISTINCT FROM 'active' THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM initial password start replay conflicts';
        END IF;
        RETURN QUERY SELECT v_existing.revision, v_existing.issued_at,
            v_existing.expires_at;
        RETURN;
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM iam_installation_password_credentials AS marker
        JOIN iam_password_credentials AS credential
          ON credential.user_id OPERATOR(pg_catalog.=) marker.user_id
        WHERE marker.credential_id OPERATOR(pg_catalog.=) p_credential_id AND
              marker.user_id OPERATOR(pg_catalog.=) p_user_id AND
              marker.installation_operation_id OPERATOR(pg_catalog.=)
                  p_installation_operation_id AND
              marker.credential_version OPERATOR(pg_catalog.=)
                  p_credential_version AND
              marker.state OPERATOR(pg_catalog.=) 'active' AND
              credential.credential_version OPERATOR(pg_catalog.=)
                  p_credential_version AND
              credential.revision OPERATOR(pg_catalog.=)
                  p_credential_revision AND
              credential.state OPERATOR(pg_catalog.=) 'reset_required'
        FOR UPDATE OF marker, credential
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM initial password credential changed';
    END IF;
    UPDATE iam_initial_password_continuations AS continuation
    SET state = CASE WHEN continuation.expires_at OPERATOR(pg_catalog.<=) v_now
            THEN 'expired' ELSE 'superseded' END,
        revision = continuation.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now, consumed_at = v_now
    WHERE continuation.user_id OPERATOR(pg_catalog.=) p_user_id AND
          continuation.state OPERATOR(pg_catalog.=) 'active';
    INSERT INTO iam_initial_password_continuations (
        selector, tenant_id, user_id, installation_operation_id,
        credential_id, credential_version, credential_revision,
        secret_key_id, secret_hmac, csrf_key_id, csrf_hmac,
        state, policy_attempts, revision, issued_at, expires_at,
        updated_at, consumed_at
    ) VALUES (
        p_selector, p_tenant_id, p_user_id, p_installation_operation_id,
        p_credential_id, p_credential_version, p_credential_revision,
        p_secret_key_id, p_secret_hmac, p_csrf_key_id, p_csrf_hmac,
        'active', 0, 1, v_now,
        v_now OPERATOR(pg_catalog.+) INTERVAL '10 minutes', v_now, NULL
    );
    RETURN QUERY SELECT 1::bigint, v_now,
        v_now OPERATOR(pg_catalog.+) INTERVAL '10 minutes';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_initial_password_start_v1(p_scope_schema name, p_tenant_id uuid, p_user_id uuid, p_installation_operation_id uuid, p_credential_id uuid, p_credential_version bigint, p_credential_revision bigint, p_selector bytea, p_secret_key_id text, p_secret_hmac bytea, p_csrf_key_id text, p_csrf_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_installation_credential_initialize_v1(name, uuid, uuid, uuid, uuid, bigint, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_credential_initialize_v1(p_scope_schema name, p_operation_id uuid, p_tenant_id uuid, p_user_id uuid, p_credential_id uuid, p_credential_version bigint, p_salt bytea, p_tag bytea) RETURNS TABLE(operation_id uuid, tenant_id uuid, user_id uuid, credential_id uuid, credential_version bigint, credential_revision bigint, marker_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_existing iam_installation_password_credentials%ROWTYPE;
    v_user_status text;
    v_identity_kind text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.current_setting('application_name', true)
            IS DISTINCT FROM 'harpy-v2:core-operator-initialize' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM installation credential scope is invalid';
    END IF;
    IF p_operation_id IS NULL OR p_tenant_id IS NULL OR p_user_id IS NULL OR
       p_credential_id IS NULL OR
       p_credential_version IS DISTINCT FROM 1::bigint OR
       pg_catalog.octet_length(p_salt) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_tag) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM installation credential evidence is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM iam_installation_identity_facts AS identity
        WHERE identity.operation_id OPERATOR(pg_catalog.=) p_operation_id AND
              identity.tenant_id OPERATOR(pg_catalog.=) p_tenant_id AND
              identity.first_user_id OPERATOR(pg_catalog.=) p_user_id
        FOR UPDATE
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM installation credential plan changed';
    END IF;
    SELECT marker.*
    INTO v_existing
    FROM iam_installation_password_credentials AS marker
    WHERE marker.mutation_operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_existing.user_id IS DISTINCT FROM p_user_id OR
           v_existing.credential_id IS DISTINCT FROM p_credential_id OR
           v_existing.credential_version IS DISTINCT FROM p_credential_version OR
           v_existing.state IS DISTINCT FROM 'active' OR NOT EXISTS (
                SELECT 1 FROM iam_password_credentials AS credential
                WHERE credential.user_id OPERATOR(pg_catalog.=) p_user_id AND
                      credential.credential_version OPERATOR(pg_catalog.=)
                          p_credential_version AND
                      credential.state OPERATOR(pg_catalog.=) 'reset_required' AND
                      credential.salt OPERATOR(pg_catalog.=) p_salt AND
                      credential.tag OPERATOR(pg_catalog.=) p_tag
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM installation credential replay conflicts';
        END IF;
        RETURN QUERY SELECT p_operation_id, p_tenant_id, p_user_id,
            p_credential_id, p_credential_version, 1::bigint,
            v_existing.revision;
        RETURN;
    END IF;
    SELECT principal.status, principal.identity_kind
    INTO v_user_status, v_identity_kind
    FROM iam_users AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_user_id
    FOR UPDATE;
    IF v_user_status IS DISTINCT FROM 'active' OR
       v_identity_kind IS DISTINCT FROM 'human' OR EXISTS (
            SELECT 1 FROM iam_password_credentials AS credential
            WHERE credential.user_id OPERATOR(pg_catalog.=) p_user_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM installation credential subject changed';
    END IF;
    INSERT INTO iam_password_credentials (
        user_id, credential_version, state, algorithm, salt, tag,
        memory_kib, iterations, parallelism, legacy_bcrypt_hash,
        upgrade_required, revision, created_at, updated_at,
        last_used_at, invalidated_at
    ) VALUES (
        p_user_id, p_credential_version, 'reset_required', 'argon2id_v1',
        p_salt, p_tag, 65536, 3, 4, NULL, false, 1, v_now, v_now, NULL, NULL
    );
    INSERT INTO iam_installation_password_credentials (
        credential_id, user_id, installation_operation_id,
        mutation_operation_id, credential_version, purpose, state,
        superseded_by, revision, created_at, updated_at, retired_at
    ) VALUES (
        p_credential_id, p_user_id, p_operation_id, p_operation_id,
        p_credential_version, 'installation_initial_v1', 'active',
        NULL, 1, v_now, v_now, NULL
    );
    RETURN QUERY SELECT p_operation_id, p_tenant_id, p_user_id,
        p_credential_id, p_credential_version, 1::bigint, 1::bigint;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_installation_credential_initialize_v1(p_scope_schema name, p_operation_id uuid, p_tenant_id uuid, p_user_id uuid, p_credential_id uuid, p_credential_version bigint, p_salt bytea, p_tag bytea) OWNER TO harpy_owner;

--
-- Name: iam_installation_credential_initialize_v2(name, uuid, uuid, uuid, uuid, uuid, bigint, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_credential_initialize_v2(p_scope_schema name, p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_user_id uuid, p_credential_id uuid, p_credential_version bigint, p_salt bytea, p_tag bytea) RETURNS TABLE(operation_id uuid, tenant_id uuid, user_id uuid, credential_id uuid, credential_version bigint, credential_revision bigint, marker_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    SET application_name TO 'harpy-v2:core-operator-initialize'
    AS $$
BEGIN
    IF NOT platform.tenancy_activation_step_context_assert_v1(
        p_operation_id, 'iam.initialize_tenant_identity',
        p_environment_id, p_tenant_id, p_scope_schema,
        'environment_initialize'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM installation credential capability required';
    END IF;
    RETURN QUERY SELECT * FROM iam_installation_credential_initialize_v1(
        p_scope_schema, p_operation_id, p_tenant_id, p_user_id,
        p_credential_id, p_credential_version, p_salt, p_tag
    );
    IF NOT platform.tenancy_activation_step_consume_v1(
        p_operation_id, 'iam.initialize_tenant_identity'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM installation credential capability consume failed';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_installation_credential_initialize_v2(p_scope_schema name, p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_user_id uuid, p_credential_id uuid, p_credential_version bigint, p_salt bytea, p_tag bytea) OWNER TO harpy_owner;

--
-- Name: iam_installation_credential_supersede_v1(name, uuid, uuid, uuid, uuid, bigint, uuid, bigint, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_credential_supersede_v1(p_scope_schema name, p_operation_id uuid, p_tenant_id uuid, p_user_id uuid, p_current_credential_id uuid, p_current_version bigint, p_next_credential_id uuid, p_next_version bigint, p_salt bytea, p_tag bytea) RETURNS TABLE(operation_id uuid, tenant_id uuid, user_id uuid, previous_credential_id uuid, credential_id uuid, credential_version bigint, credential_revision bigint, previous_marker_revision bigint, marker_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_previous iam_installation_password_credentials%ROWTYPE;
    v_replay iam_installation_password_credentials%ROWTYPE;
    v_credential_revision bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM credential supersede scope is invalid';
    END IF;
    IF p_operation_id IS NULL OR p_tenant_id IS NULL OR p_user_id IS NULL OR
       p_current_credential_id IS NULL OR p_next_credential_id IS NULL OR
       p_current_credential_id OPERATOR(pg_catalog.=) p_next_credential_id OR
       p_current_version OPERATOR(pg_catalog.<) 1 OR
       p_next_version IS DISTINCT FROM
           p_current_version OPERATOR(pg_catalog.+) 1 OR
       pg_catalog.octet_length(p_salt) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_tag) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM credential supersede evidence is invalid';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM iam_installation_identity_facts AS identity
        WHERE identity.tenant_id OPERATOR(pg_catalog.=) p_tenant_id AND
              identity.first_user_id OPERATOR(pg_catalog.=) p_user_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM credential supersede tenant is invalid';
    END IF;
    SELECT marker.*
    INTO v_replay
    FROM iam_installation_password_credentials AS marker
    WHERE marker.mutation_operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_replay.user_id IS DISTINCT FROM p_user_id OR
           v_replay.credential_id IS DISTINCT FROM p_next_credential_id OR
           v_replay.credential_version IS DISTINCT FROM p_next_version OR
           v_replay.state IS DISTINCT FROM 'active' OR NOT EXISTS (
                SELECT 1 FROM iam_password_credentials AS credential
                WHERE credential.user_id OPERATOR(pg_catalog.=) p_user_id AND
                      credential.credential_version OPERATOR(pg_catalog.=)
                          p_next_version AND
                      credential.state OPERATOR(pg_catalog.=) 'reset_required' AND
                      credential.salt OPERATOR(pg_catalog.=) p_salt AND
                      credential.tag OPERATOR(pg_catalog.=) p_tag
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM credential supersede replay conflicts';
        END IF;
        SELECT marker.*
        INTO STRICT v_previous
        FROM iam_installation_password_credentials AS marker
        WHERE marker.superseded_by OPERATOR(pg_catalog.=) p_next_credential_id;
        SELECT credential.revision
        INTO STRICT v_credential_revision
        FROM iam_password_credentials AS credential
        WHERE credential.user_id OPERATOR(pg_catalog.=) p_user_id;
        RETURN QUERY SELECT p_operation_id, p_tenant_id, p_user_id,
            p_current_credential_id, p_next_credential_id, p_next_version,
            v_credential_revision, v_previous.revision, v_replay.revision;
        RETURN;
    END IF;
    SELECT marker.*
    INTO v_previous
    FROM iam_installation_password_credentials AS marker
    WHERE marker.credential_id OPERATOR(pg_catalog.=) p_current_credential_id
    FOR UPDATE;
    IF NOT FOUND OR v_previous.user_id IS DISTINCT FROM p_user_id OR
       v_previous.credential_version IS DISTINCT FROM p_current_version OR
       v_previous.state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM credential supersede predecessor changed';
    END IF;
    UPDATE iam_password_credentials AS credential
    SET credential_version = p_next_version, state = 'reset_required',
        algorithm = 'argon2id_v1', salt = p_salt, tag = p_tag,
        memory_kib = 65536, iterations = 3, parallelism = 4,
        legacy_bcrypt_hash = NULL, upgrade_required = false,
        revision = credential.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now, last_used_at = NULL, invalidated_at = NULL
    WHERE credential.user_id OPERATOR(pg_catalog.=) p_user_id AND
          credential.credential_version OPERATOR(pg_catalog.=)
              p_current_version AND
          credential.state OPERATOR(pg_catalog.=) 'reset_required'
    RETURNING credential.revision INTO v_credential_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM credential supersede CAS changed';
    END IF;
    INSERT INTO iam_installation_password_credentials (
        credential_id, user_id, installation_operation_id,
        mutation_operation_id, credential_version, purpose, state,
        superseded_by, revision, created_at, updated_at, retired_at
    ) VALUES (
        p_next_credential_id, p_user_id,
        v_previous.installation_operation_id, p_operation_id,
        p_next_version, 'installation_initial_v1', 'active',
        NULL, 1, v_now, v_now, NULL
    );
    UPDATE iam_installation_password_credentials AS marker
    SET state = 'superseded', superseded_by = p_next_credential_id,
        revision = marker.revision OPERATOR(pg_catalog.+) 1,
        updated_at = v_now, retired_at = v_now
    WHERE marker.credential_id OPERATOR(pg_catalog.=)
        p_current_credential_id;
    RETURN QUERY SELECT p_operation_id, p_tenant_id, p_user_id,
        p_current_credential_id, p_next_credential_id, p_next_version,
        v_credential_revision,
        v_previous.revision OPERATOR(pg_catalog.+) 1, 1::bigint;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_installation_credential_supersede_v1(p_scope_schema name, p_operation_id uuid, p_tenant_id uuid, p_user_id uuid, p_current_credential_id uuid, p_current_version bigint, p_next_credential_id uuid, p_next_version bigint, p_salt bytea, p_tag bytea) OWNER TO harpy_owner;

--
-- Name: iam_installation_derived_id_v1(uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_derived_id_v1(p_operation_id uuid, p_label text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_digest bytea;
    v_hex text;
BEGIN
    IF p_operation_id IS NULL OR p_label IS NULL
       OR pg_catalog.octet_length(p_label) NOT BETWEEN 1 AND 64
       OR p_label !~ '^[a-z0-9-]+$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM installation identity derivation input is invalid';
    END IF;
    v_digest := pg_catalog.sha256(
        pg_catalog.convert_to('harpy:iam:installation:v1', 'UTF8') ||
        pg_catalog.uuid_send(p_operation_id) || '\x00'::bytea ||
        pg_catalog.convert_to(p_label, 'UTF8')
    );
    v_digest := pg_catalog.set_byte(
        v_digest, 6, (pg_catalog.get_byte(v_digest, 6) & 15) | 112
    );
    v_digest := pg_catalog.set_byte(
        v_digest, 8, (pg_catalog.get_byte(v_digest, 8) & 63) | 128
    );
    v_hex := pg_catalog.encode(pg_catalog.substring(v_digest, 1, 16), 'hex');
    RETURN (
        pg_catalog.substring(v_hex, 1, 8) || '-' ||
        pg_catalog.substring(v_hex, 9, 4) || '-' ||
        pg_catalog.substring(v_hex, 13, 4) || '-' ||
        pg_catalog.substring(v_hex, 17, 4) || '-' ||
        pg_catalog.substring(v_hex, 21, 12)
    )::uuid;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_installation_derived_id_v1(p_operation_id uuid, p_label text) OWNER TO harpy_owner;

--
-- Name: iam_installation_identity_core_v1(uuid, uuid, uuid, uuid, uuid, text, text, text, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_identity_core_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_user_id uuid, p_organization_id uuid, p_email text, p_display_name text, p_tenant_name text, p_user_schema_id uuid, p_user_field_id uuid, p_organization_schema_id uuid, p_organization_field_id uuid, p_role_schema_id uuid, p_role_field_id uuid, p_identifier_id uuid, p_access_mode_id uuid, p_membership_id uuid, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_profile jsonb;
    v_organization_profile jsonb;
BEGIN
    v_user_profile := pg_catalog.jsonb_build_object('display_name', p_display_name);
    v_organization_profile := pg_catalog.jsonb_build_object('display_name', p_tenant_name);
    PERFORM iam_installation_profile_v1(
        p_user_schema_id, p_user_field_id, 'user', p_now
    );
    PERFORM iam_installation_profile_v1(
        p_organization_schema_id, p_organization_field_id, 'organization', p_now
    );
    PERFORM iam_installation_profile_v1(
        p_role_schema_id, p_role_field_id, 'role', p_now
    );
    INSERT INTO iam_users (
        id, status, profile_resource_kind, profile_schema_version_id,
        profile_values, profile_sha256, token_version, authorization_version,
        revision, created_at, updated_at, tombstoned_at, identity_kind
    ) VALUES (
        p_user_id, 'active', 'user', p_user_schema_id, v_user_profile,
        pg_catalog.sha256(pg_catalog.convert_to(v_user_profile::text, 'UTF8')),
        1, 1, 1, p_now, p_now, NULL, 'human'
    );
    INSERT INTO iam_user_access_modes (
        id, user_id, mode, state, revision, created_at, updated_at,
        activated_at, suspended_at, retired_at
    ) VALUES (
        p_access_mode_id, p_user_id, 'operator_console', 'active', 1,
        p_now, p_now, p_now, NULL, NULL
    );
    INSERT INTO iam_user_identifiers (
        id, user_id, kind, display_value, normalized_value,
        normalized_sha256, state, revision, verified_at, activated_at,
        tombstoned_at, cooldown_until, retired_at, created_at, updated_at
    ) VALUES (
        p_identifier_id, p_user_id, 'email_v1', p_email, p_email,
        pg_catalog.sha256(pg_catalog.convert_to(p_email, 'UTF8')),
        'active', 1, p_now, p_now, NULL, NULL, NULL, p_now, p_now
    );
    INSERT INTO iam_organizations (
        id, name, slug, status, parent_id, profile_resource_kind,
        profile_schema_version_id, profile_values, profile_sha256,
        revision, created_at, updated_at, tombstoned_at
    ) VALUES (
        p_organization_id, p_tenant_name, 'root', 'active', NULL,
        'organization', p_organization_schema_id, v_organization_profile,
        pg_catalog.sha256(pg_catalog.convert_to(v_organization_profile::text, 'UTF8')),
        1, p_now, p_now, NULL
    );
    INSERT INTO iam_organization_memberships (
        id, organization_id, user_id, membership_kind, state, revision,
        created_at, updated_at, tombstoned_at
    ) VALUES (
        p_membership_id, p_organization_id, p_user_id, 'owner', 'active',
        1, p_now, p_now, NULL
    );
    INSERT INTO iam_authorization_clock (
        singleton, clock_value, revision, created_at, updated_at
    ) VALUES (true, 1, 1, p_now, p_now);
    PERFORM iam_installation_schedules_v1(p_operation_id, p_now);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_installation_identity_core_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_user_id uuid, p_organization_id uuid, p_email text, p_display_name text, p_tenant_name text, p_user_schema_id uuid, p_user_field_id uuid, p_organization_schema_id uuid, p_organization_field_id uuid, p_role_schema_id uuid, p_role_field_id uuid, p_identifier_id uuid, p_access_mode_id uuid, p_membership_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_installation_initialize_v1(uuid, uuid, uuid, uuid, uuid, uuid, text, text, text, text, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_initialize_v1(p_operation_id uuid, p_environment_id uuid, p_tenant_id uuid, p_user_id uuid, p_organization_id uuid, p_protected_assignment_id uuid, p_email text, p_display_name text, p_tenant_name text, p_binding_set_sha256 text, p_user_schema_id uuid, p_user_field_id uuid, p_organization_schema_id uuid, p_organization_field_id uuid, p_role_schema_id uuid, p_role_field_id uuid, p_identifier_id uuid, p_access_mode_id uuid, p_membership_id uuid, p_role_id uuid, p_permission_id uuid, p_role_permission_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_existing iam_installation_identity_facts%ROWTYPE;
    v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM installation initialization denied';
    END IF;
    IF p_email IS NULL OR p_email IS DISTINCT FROM pg_catalog.lower(p_email)
       OR pg_catalog.char_length(p_email) NOT BETWEEN 3 AND 254
       OR p_email !~ '^[^[:space:]@]+@[^[:space:]@]+$'
       OR p_display_name IS NULL OR pg_catalog.char_length(p_display_name) NOT BETWEEN 1 AND 128
       OR p_display_name IS DISTINCT FROM pg_catalog.btrim(p_display_name)
       OR p_tenant_name IS NULL OR pg_catalog.char_length(p_tenant_name) NOT BETWEEN 1 AND 128
       OR p_tenant_name IS DISTINCT FROM pg_catalog.btrim(p_tenant_name)
       OR p_binding_set_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM installation input is invalid';
    END IF;
    SELECT * INTO v_existing
    FROM iam_installation_identity_facts AS fact
    WHERE fact.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_existing.environment_id IS DISTINCT FROM p_environment_id
           OR v_existing.tenant_id IS DISTINCT FROM p_tenant_id
           OR v_existing.first_user_id IS DISTINCT FROM p_user_id
           OR v_existing.root_organization_id IS DISTINCT FROM p_organization_id
           OR v_existing.protected_admin_binding_id IS DISTINCT FROM p_protected_assignment_id
           OR v_existing.normalized_email IS DISTINCT FROM p_email
           OR v_existing.protected_admin_binding_set_sha256 IS DISTINCT FROM
                pg_catalog.decode(p_binding_set_sha256, 'hex') THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM installation replay conflict';
        END IF;
        RETURN true;
    END IF;
    PERFORM iam_installation_identity_core_v1(
        p_operation_id, p_environment_id, p_tenant_id, p_user_id,
        p_organization_id, p_email, p_display_name, p_tenant_name,
        p_user_schema_id, p_user_field_id, p_organization_schema_id,
        p_organization_field_id, p_role_schema_id, p_role_field_id,
        p_identifier_id, p_access_mode_id, p_membership_id, v_now
    );
    PERFORM iam_installation_protected_admin_v1(
        p_tenant_id, p_user_id, p_protected_assignment_id, p_role_id,
        p_permission_id, p_role_permission_id, p_role_schema_id, v_now
    );
    INSERT INTO iam_installation_identity_facts (
        operation_id, environment_id, tenant_id, first_user_id,
        root_organization_id, protected_admin_binding_id,
        protected_admin_binding_set_sha256, normalized_email, activated_at
    ) VALUES (
        p_operation_id, p_environment_id, p_tenant_id, p_user_id,
        p_organization_id, p_protected_assignment_id,
        pg_catalog.decode(p_binding_set_sha256, 'hex'), p_email, v_now
    );
    RETURN false;
END;
$_$;


