--
-- Name: iam_installation_profile_v1(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_profile_v1(p_schema_id uuid, p_field_id uuid, p_resource_kind text, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_validation jsonb;
BEGIN
    v_validation := '{"maximum_bytes":128}'::jsonb;
    IF p_resource_kind NOT IN ('user', 'organization', 'role')
       OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM installation profile input is invalid';
    END IF;
    INSERT INTO iam_profile_schema_versions (
        id, resource_kind, version, state, definition_sha256,
        activated_at, retired_at, created_at, updated_at, revision
    ) VALUES (
        p_schema_id, p_resource_kind, 1, 'draft',
        pg_catalog.sha256(pg_catalog.uuid_send(p_schema_id)),
        NULL, NULL, p_now, p_now, 1
    );
    INSERT INTO iam_profile_fields (
        id, resource_kind, field_key, value_kind, cardinality, required,
        classification, normalization_profile, state, created_at,
        updated_at, retired_at, revision
    ) VALUES (
        p_field_id, p_resource_kind, 'display_name', 'string', 'single', true,
        'public', 'none_v1', 'active', p_now, p_now, NULL, 1
    );
    INSERT INTO iam_profile_field_revisions (
        schema_version_id, resource_kind, field_id, validation_schema,
        validation_sha256, created_at, field_key, value_kind, cardinality,
        required, classification, normalization_profile, field_state,
        semantic_sha256
    ) VALUES (
        p_schema_id, p_resource_kind, p_field_id, v_validation,
        pg_catalog.sha256(pg_catalog.convert_to(
            iam_profile_validation_canonical_v1(v_validation), 'UTF8'
        )), p_now, 'display_name', 'string', 'single', true, 'public',
        'none_v1', 'active', iam_profile_semantic_sha256_v1(
            p_field_id, p_resource_kind, 'display_name', 'string',
            'single', true, 'public', 'none_v1'
        )
    );
    UPDATE iam_profile_schema_versions
    SET state = 'active',
        definition_sha256 = iam_profile_definition_sha256_v1(p_schema_id),
        activated_at = p_now, updated_at = p_now, revision = 2
    WHERE id = p_schema_id AND resource_kind = p_resource_kind
      AND state = 'draft' AND revision = 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM installation profile activation conflict';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_installation_profile_v1(p_schema_id uuid, p_field_id uuid, p_resource_kind text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_installation_protected_admin_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_protected_admin_v1(p_tenant_id uuid, p_user_id uuid, p_assignment_id uuid, p_role_id uuid, p_permission_id uuid, p_role_permission_id uuid, p_role_schema_id uuid, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_role_name text;
    v_role_profile jsonb;
BEGIN
    v_role_name := 'Protected Tenant Admin';
    v_role_profile := '{"display_name":"Protected Tenant Admin"}'::jsonb;
    INSERT INTO iam_roles (
        id, scope_kind, scope_id, organization_id, name, name_key,
        description, status, is_protected, is_default,
        profile_resource_kind, profile_schema_version_id, profile_values,
        profile_sha256, revision, created_at, updated_at, retired_at
    ) VALUES (
        p_role_id, 'tenant', p_tenant_id, NULL, v_role_name,
        pg_catalog.convert_to(v_role_name, 'UTF8'),
        'Non-deletable tenant-wide installation authority',
        'active', true, false, 'role', p_role_schema_id, v_role_profile,
        pg_catalog.sha256(pg_catalog.convert_to(v_role_profile::text, 'UTF8')),
        1, p_now, p_now, NULL
    );
    INSERT INTO iam_permissions (
        id, match_kind, resource_id, action_id, is_protected, state,
        revision, created_at, updated_at, retired_at
    ) VALUES (
        p_permission_id, 'tenant_all', NULL, NULL, true, 'active',
        1, p_now, p_now, NULL
    );
    INSERT INTO iam_role_permission_bindings (
        id, role_id, role_is_protected, permission_id,
        permission_match_kind, state, revision, created_at, updated_at,
        activated_at, revoked_at
    ) VALUES (
        p_role_permission_id, p_role_id, true, p_permission_id,
        'tenant_all', 'active', 1, p_now, p_now, p_now, NULL
    );
    INSERT INTO iam_user_role_assignments (
        id, user_id, role_id, role_scope_kind, role_scope_id,
        organization_id, membership_id, state, revision,
        created_at, updated_at, revoked_at
    ) VALUES (
        p_assignment_id, p_user_id, p_role_id, 'tenant', p_tenant_id,
        NULL, NULL, 'active', 1, p_now, p_now, NULL
    );
    INSERT INTO iam_protected_admin_policies (
        singleton, role_id, role_is_protected, role_status, role_scope_kind,
        tenant_all_permission_id, permission_match_kind,
        permission_is_protected, permission_state,
        role_permission_binding_id, role_binding_state,
        minimum_active_assignments, policy_state, authorization_epoch,
        revision, created_at, updated_at
    ) VALUES (
        true, p_role_id, true, 'active', 'tenant', p_permission_id,
        'tenant_all', true, 'active', p_role_permission_id, 'active',
        1, 'active', 1, 1, p_now, p_now
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_installation_protected_admin_v1(p_tenant_id uuid, p_user_id uuid, p_assignment_id uuid, p_role_id uuid, p_permission_id uuid, p_role_permission_id uuid, p_role_schema_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_installation_schedules_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_schedules_v1(p_operation_id uuid, p_now timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_kind text;
    v_cadence integer;
    v_reference text;
BEGIN
    FOR v_kind, v_cadence IN
        SELECT * FROM (VALUES
            ('iam.directory.repair', 900),
            ('iam.directory.checksum', 86400),
            ('iam.credential.bcrypt-retire', 86400),
            ('iam.identifier.retire', 86400),
            ('iam.directory.tombstone-purge', 86400),
            ('iam.security-artifact-purge', 3600)
        ) AS schedule(kind, cadence)
    LOOP
        v_reference := '{"contract":"iam-maintenance-schedule.v1","kind":"' ||
            v_kind || '"}';
        INSERT INTO iam_maintenance_schedules (
            kind, payload_revision, payload_reference, payload_sha256,
            current_job_id, scheduled_run_at, cadence_seconds, revision,
            created_at, updated_at
        ) VALUES (
            v_kind, 1, v_reference,
            pg_catalog.sha256(pg_catalog.convert_to(v_reference, 'UTF8')),
            pg_catalog.md5(p_operation_id::text || ':' || v_kind)::uuid,
            p_now + pg_catalog.make_interval(secs => v_cadence),
            v_cadence, 1, p_now, p_now
        );
    END LOOP;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_installation_schedules_v1(p_operation_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_installation_user_profile_upgrade_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_installation_user_profile_upgrade_v1(p_operation_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_source_id uuid; v_target_id uuid; v_display_id uuid;
    v_first_id uuid; v_last_id uuid; v_phone_id uuid;
    v_source_version bigint;
    v_now timestamptz := pg_catalog.statement_timestamp();
    v_validation jsonb;
BEGIN
    v_source_id := iam_installation_derived_id_v1(p_operation_id, 'user-profile-schema');
    v_target_id := iam_installation_derived_id_v1(p_operation_id, 'user-profile-schema-v2');
    v_display_id := iam_installation_derived_id_v1(p_operation_id, 'user-display-name-field');
    v_first_id := iam_installation_derived_id_v1(p_operation_id, 'user-first-name-field');
    v_last_id := iam_installation_derived_id_v1(p_operation_id, 'user-last-name-field');
    v_phone_id := iam_installation_derived_id_v1(p_operation_id, 'user-phone-field');
    IF EXISTS (
        SELECT 1 FROM iam_profile_schema_versions AS target
        WHERE target.id = v_target_id AND target.resource_kind = 'user'
          AND target.state = 'active'
    ) THEN
        IF (SELECT pg_catalog.count(*)
            FROM iam_profile_field_revisions AS field
            WHERE field.schema_version_id = v_target_id
              AND field.resource_kind = 'user'
              AND field.field_state = 'active'
              AND field.field_id IN (
                  v_display_id, v_first_id, v_last_id, v_phone_id
              )) IS DISTINCT FROM 4 THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'IAM installation user profile successor is invalid';
        END IF;
        RETURN true;
    END IF;
    SELECT source.version INTO v_source_version
    FROM iam_profile_schema_versions AS source
    WHERE source.id = v_source_id AND source.resource_kind = 'user'
      AND source.state = 'active'
    FOR UPDATE;
    IF NOT FOUND THEN
        IF EXISTS (
            SELECT 1
            FROM iam_profile_schema_versions AS active
            JOIN iam_profile_field_revisions AS field
              ON field.schema_version_id = active.id
             AND field.resource_kind = active.resource_kind
            WHERE active.resource_kind = 'user' AND active.state = 'active'
              AND field.field_state = 'active'
              AND field.field_key IN ('first_name','last_name','phone')
            GROUP BY active.id HAVING pg_catalog.count(*) = 3
        ) THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM installation user profile source is unavailable';
    END IF;
    IF (SELECT pg_catalog.count(*)
        FROM iam_profile_field_revisions AS field
        WHERE field.schema_version_id = v_source_id
          AND field.resource_kind = 'user') IS DISTINCT FROM 1
       OR NOT EXISTS (
           SELECT 1 FROM iam_profile_field_revisions AS field
           WHERE field.schema_version_id = v_source_id
             AND field.resource_kind = 'user'
             AND field.field_id = v_display_id
             AND field.field_key = 'display_name'
             AND field.value_kind = 'string'
             AND field.cardinality = 'single'
             AND field.required AND field.classification = 'public'
             AND field.normalization_profile = 'none_v1'
             AND field.field_state = 'active'
       )
       OR EXISTS (
           SELECT 1 FROM iam_users AS subject
           WHERE subject.profile_schema_version_id = v_source_id
             AND (
                 pg_catalog.jsonb_typeof(subject.profile_values) <> 'object'
                 OR (SELECT pg_catalog.count(*)
                     FROM pg_catalog.jsonb_object_keys(subject.profile_values)) <> 1
                 OR NOT subject.profile_values ? v_display_id::text
                 OR pg_catalog.jsonb_typeof(
                     subject.profile_values -> v_display_id::text
                 ) <> 'string'
             )
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM installation user profile source is invalid';
    END IF;
    v_validation := '{"maximum_bytes":200}'::jsonb;
    INSERT INTO iam_profile_fields (
        id, resource_kind, field_key, value_kind, cardinality, required,
        classification, normalization_profile, state, created_at,
        updated_at, retired_at, revision
    ) VALUES
        (v_first_id,'user','first_name','string','single',false,
         'public','none_v1','active',v_now,v_now,NULL,1),
        (v_last_id,'user','last_name','string','single',false,
         'public','none_v1','active',v_now,v_now,NULL,1),
        (v_phone_id,'user','phone','string','single',false,
         'public','none_v1','active',v_now,v_now,NULL,1);
    INSERT INTO iam_profile_schema_versions (
        id, resource_kind, version, state, definition_sha256,
        activated_at, retired_at, created_at, updated_at, revision
    ) VALUES (
        v_target_id, 'user', v_source_version + 1, 'draft',
        pg_catalog.sha256(pg_catalog.uuid_send(v_target_id)),
        NULL, NULL, v_now, v_now, 1
    );
    INSERT INTO iam_profile_field_revisions
    SELECT v_target_id, resource_kind, field_id, validation_schema,
        validation_sha256, v_now, field_key, value_kind, cardinality,
        required, classification, normalization_profile, field_state,
        semantic_sha256
    FROM iam_profile_field_revisions
    WHERE schema_version_id = v_source_id AND field_id = v_display_id;
    INSERT INTO iam_profile_field_revisions (
        schema_version_id, resource_kind, field_id, validation_schema,
        validation_sha256, created_at, field_key, value_kind, cardinality,
        required, classification, normalization_profile, field_state,
        semantic_sha256
    )
    SELECT v_target_id, 'user', field.id,
        CASE WHEN field.id = v_phone_id
             THEN '{"maximum_bytes":32}'::jsonb ELSE v_validation END,
        pg_catalog.sha256(pg_catalog.convert_to(
            iam_profile_validation_canonical_v1(
                CASE WHEN field.id = v_phone_id
                     THEN '{"maximum_bytes":32}'::jsonb ELSE v_validation END
            ), 'UTF8'
        )), v_now, field.field_key, field.value_kind, field.cardinality,
        field.required, field.classification, field.normalization_profile,
        field.state, iam_profile_semantic_sha256_v1(
            field.id, field.resource_kind, field.field_key, field.value_kind,
            field.cardinality, field.required, field.classification,
            field.normalization_profile
        )
    FROM iam_profile_fields AS field
    WHERE field.id IN (v_first_id, v_last_id, v_phone_id);
    UPDATE iam_profile_schema_versions
    SET definition_sha256 = iam_profile_definition_sha256_v1(v_target_id),
        updated_at = v_now, revision = 2
    WHERE id = v_target_id AND state = 'draft' AND revision = 1;
    WITH documents AS (
        SELECT subject.id,
               '{' || pg_catalog.string_agg(
                   pg_catalog.to_json(entry.key)::text || ':' ||
                   entry.value::text, ',' ORDER BY entry.key
               ) || '}' AS canonical_json
        FROM iam_users AS subject
        CROSS JOIN LATERAL pg_catalog.jsonb_each(
            subject.profile_values ||
            pg_catalog.jsonb_build_object(
                v_first_id::text,
                subject.profile_values -> v_display_id::text
            )
        ) AS entry(key,value)
        WHERE subject.profile_schema_version_id = v_source_id
        GROUP BY subject.id
    )
    UPDATE iam_users AS subject
    SET profile_schema_version_id = v_target_id,
        profile_values = documents.canonical_json::jsonb,
        profile_sha256 = pg_catalog.sha256(
            pg_catalog.convert_to(documents.canonical_json, 'UTF8')
        ),
        revision = subject.revision + 1, updated_at = v_now
    FROM documents WHERE subject.id = documents.id;
    UPDATE iam_profile_schema_versions
    SET state = 'retired', retired_at = v_now, updated_at = v_now,
        revision = revision + 1
    WHERE id = v_source_id AND state = 'active';
    UPDATE iam_profile_schema_versions
    SET state = 'active', activated_at = v_now, updated_at = v_now,
        revision = revision + 1
    WHERE id = v_target_id AND state = 'draft' AND revision = 2;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM installation user profile activation conflict';
    END IF;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_installation_user_profile_upgrade_v1(p_operation_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_invitation_accept_v1(name, uuid, bigint, uuid, bigint, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_accept_v1(p_scope_schema name, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_accepted_user_id uuid, p_accepted_identifier_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_invitation_state text;
    v_invitation_revision bigint;
    v_invitation_expires_at timestamptz;
    v_token_state text;
    v_token_revision bigint;
    v_token_invitation_id uuid;
    v_token_expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation acceptance scope is invalid';
    END IF;
    SELECT invitation.state, invitation.revision, invitation.expires_at
    INTO v_invitation_state, v_invitation_revision, v_invitation_expires_at
    FROM iam_invitations AS invitation
    WHERE invitation.id OPERATOR(pg_catalog.=) p_invitation_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation is unknown';
    END IF;
    SELECT token.state, token.revision, token.invitation_id, token.expires_at
    INTO v_token_state, v_token_revision,
         v_token_invitation_id, v_token_expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
      AND token.purpose OPERATOR(pg_catalog.=) 'invitation_accept_v1'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation token is unknown';
    END IF;
    IF v_invitation_state IS DISTINCT FROM 'pending' OR
       v_invitation_revision IS DISTINCT FROM p_expected_invitation_revision OR
       v_token_state IS DISTINCT FROM 'pending' OR
       v_token_revision IS DISTINCT FROM p_expected_token_revision OR
       v_token_invitation_id IS DISTINCT FROM p_invitation_id OR
       v_token_expires_at IS DISTINCT FROM v_invitation_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation acceptance CAS is stale';
    END IF;
    IF v_now OPERATOR(pg_catalog.>=) v_invitation_expires_at THEN
        UPDATE iam_one_time_tokens
        SET state = 'expired', expired_at = v_token_expires_at,
            updated_at = v_now,
            revision = v_token_revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_token_id;
        UPDATE iam_invitations
        SET state = 'expired', expired_at = v_invitation_expires_at,
            updated_at = v_now,
            revision = v_invitation_revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_invitation_id;
        RETURN 'expired';
    END IF;
    UPDATE iam_invitations
    SET accepted_user_id = p_accepted_user_id,
        accepted_identifier_id = p_accepted_identifier_id,
        accepted_identifier_kind = 'email_v1',
        state = 'accepted', accepted_at = v_now, updated_at = v_now,
        revision = v_invitation_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_invitation_id;
    UPDATE iam_one_time_tokens
    SET state = 'consumed', consumed_at = v_now, updated_at = v_now,
        revision = v_token_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_token_id;
    RETURN 'accepted';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_accept_v1(p_scope_schema name, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_accepted_user_id uuid, p_accepted_identifier_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_invitation_accept_v2(name, uuid, bytea, uuid, bigint, uuid, bigint, bytea, text, bytea, bytea, uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_accept_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_accepted_user_id uuid, p_accepted_identifier_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_expected_authorization_version bigint) RETURNS TABLE(result_code text, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_invitation_state text;
    v_invitation_revision bigint;
    v_invitation_expires_at timestamptz;
    v_normalized_value text;
    v_role_id uuid;
    v_role_scope_kind text;
    v_role_scope_id uuid;
    v_organization_id uuid;
    v_token_state text;
    v_token_revision bigint;
    v_token_selector bytea;
    v_token_key_id text;
    v_token_hmac bytea;
    v_token_binding bytea;
    v_user_state text;
    v_user_authorization_version bigint;
    v_identifier_state text;
    v_identifier_value text;
    v_receipt_command text;
    v_receipt_hash bytea;
    v_receipt_code text;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_receipt_result_id uuid;
    v_clock bigint;
    v_assignment_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation acceptance scope is invalid';
    END IF;
    IF p_operation_id IS NULL OR p_invitation_id IS NULL OR p_token_id IS NULL OR
       p_accepted_user_id IS NULL OR p_accepted_identifier_id IS NULL OR
       p_role_assignment_id IS NULL OR p_expected_invitation_revision < 1 OR
       p_expected_token_revision < 1 OR p_expected_authorization_version < 1 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       p_hash_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_binding_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation acceptance input is invalid';
    END IF;
    SELECT invitation.state, invitation.revision, invitation.expires_at,
           invitation.normalized_value, invitation.role_id,
           invitation.role_scope_kind, invitation.role_scope_id,
           invitation.organization_id, token.state, token.revision,
           token.selector, token.hash_key_id, token.secret_hmac,
           token.binding_sha256, principal.status,
           principal.authorization_version, identifier.state,
           identifier.normalized_value
    INTO v_invitation_state, v_invitation_revision, v_invitation_expires_at,
         v_normalized_value, v_role_id, v_role_scope_kind,
         v_role_scope_id, v_organization_id, v_token_state,
         v_token_revision, v_token_selector, v_token_key_id,
         v_token_hmac, v_token_binding, v_user_state,
         v_user_authorization_version, v_identifier_state, v_identifier_value
    FROM iam_invitations AS invitation
    JOIN iam_one_time_tokens AS token
      ON token.id = p_token_id AND token.invitation_id = invitation.id
     AND token.purpose = 'invitation_accept_v1'
    JOIN iam_users AS principal ON principal.id = p_accepted_user_id
    JOIN iam_user_identifiers AS identifier
      ON identifier.id = p_accepted_identifier_id
     AND identifier.user_id = principal.id AND identifier.kind = 'email_v1'
    WHERE invitation.id = p_invitation_id
    FOR UPDATE OF invitation, token, principal, identifier;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation acceptance target is unknown';
    END IF;
    IF v_token_selector IS DISTINCT FROM p_selector OR
       v_token_key_id IS DISTINCT FROM p_hash_key_id OR
       v_token_hmac IS DISTINCT FROM p_secret_hmac OR
       v_token_binding IS DISTINCT FROM p_binding_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation credential is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_code,
           receipt.result_revision, receipt.clock_value, receipt.result_id
    INTO v_receipt_command, v_receipt_hash, v_receipt_code,
         v_receipt_revision, v_receipt_clock, v_receipt_result_id
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.invitation.accept' OR
           v_receipt_hash IS DISTINCT FROM p_request_sha256 OR
           v_receipt_result_id IS DISTINCT FROM p_invitation_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM invitation operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_code, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    IF v_invitation_state IS DISTINCT FROM 'pending' OR
       v_invitation_revision IS DISTINCT FROM p_expected_invitation_revision OR
       v_token_state IS DISTINCT FROM 'pending' OR
       v_token_revision IS DISTINCT FROM p_expected_token_revision OR
       v_now >= v_invitation_expires_at OR v_user_state IS DISTINCT FROM 'active' OR
       v_user_authorization_version IS DISTINCT FROM
           p_expected_authorization_version OR
       v_identifier_state IS DISTINCT FROM 'active' OR
       v_identifier_value IS DISTINCT FROM v_normalized_value THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation acceptance CAS is stale';
    END IF;
    v_assignment_id := iam_invitation_grant_role_v1(
        p_accepted_user_id, p_role_assignment_id, p_membership_id,
        v_role_id, v_role_scope_kind, v_role_scope_id,
        v_organization_id, v_now
    );
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL OR v_assignment_id IS DISTINCT FROM p_role_assignment_id THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM invitation authorization clock is unavailable';
    END IF;
    UPDATE iam_users
    SET authorization_version = authorization_version + 1,
        revision = revision + 1, updated_at = v_now
    WHERE id = p_accepted_user_id;
    UPDATE iam_invitations
    SET accepted_user_id = p_accepted_user_id,
        accepted_identifier_id = p_accepted_identifier_id,
        accepted_identifier_kind = 'email_v1', state = 'accepted',
        accepted_at = v_now, updated_at = v_now,
        revision = v_invitation_revision + 1
    WHERE id = p_invitation_id;
    UPDATE iam_one_time_tokens
    SET state = 'consumed', consumed_at = v_now,
        updated_at = v_now, revision = v_token_revision + 1
    WHERE id = p_token_id;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value, result_code,
        result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.invitation.accept', p_request_sha256,
        v_clock, 'iam.invitation.accepted', p_invitation_id,
        v_invitation_revision + 1, p_request_sha256, v_now
    );
    RETURN QUERY SELECT 'iam.invitation.accepted'::text,
        v_invitation_revision + 1, v_clock, false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_invitation_accept_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_accepted_user_id uuid, p_accepted_identifier_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_accept_v3(name, uuid, bytea, uuid, bigint, uuid, bigint, bytea, text, bytea, bytea, uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_accept_v3(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_accepted_user_id uuid, p_accepted_identifier_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_expected_authorization_version bigint) RETURNS TABLE(result_code text, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_invitation_state text;
    v_invitation_revision bigint;
    v_invitation_expires_at timestamptz;
    v_normalized_value text;
    v_role_id uuid;
    v_role_scope_kind text;
    v_role_scope_id uuid;
    v_organization_id uuid;
    v_token_state text;
    v_token_revision bigint;
    v_token_selector bytea;
    v_token_key_id text;
    v_token_hmac bytea;
    v_token_binding bytea;
    v_user_state text;
    v_user_authorization_version bigint;
    v_identifier_state text;
    v_identifier_value text;
    v_receipt_command text;
    v_receipt_hash bytea;
    v_receipt_code text;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_receipt_result_id uuid;
    v_clock bigint;
    v_assignment_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation acceptance scope is invalid';
    END IF;
    IF p_operation_id IS NULL OR p_invitation_id IS NULL OR p_token_id IS NULL OR
       p_accepted_user_id IS NULL OR p_accepted_identifier_id IS NULL OR
       p_role_assignment_id IS NULL OR p_expected_invitation_revision < 1 OR
       p_expected_token_revision < 1 OR p_expected_authorization_version < 1 OR
       pg_catalog.octet_length(p_request_sha256) <> 32 OR
       pg_catalog.octet_length(p_selector) <> 16 OR
       NOT iam_hmac_key_id_valid_v1(p_hash_key_id) OR
       pg_catalog.octet_length(p_secret_hmac) <> 32 OR
       pg_catalog.octet_length(p_binding_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation acceptance input is invalid';
    END IF;
    SELECT invitation.state, invitation.revision, invitation.expires_at,
           invitation.normalized_value, invitation.role_id,
           invitation.role_scope_kind, invitation.role_scope_id,
           invitation.organization_id, token.state, token.revision,
           token.selector, token.hash_key_id, token.secret_hmac,
           token.binding_sha256, principal.status,
           principal.authorization_version, identifier.state,
           identifier.normalized_value
    INTO v_invitation_state, v_invitation_revision, v_invitation_expires_at,
         v_normalized_value, v_role_id, v_role_scope_kind,
         v_role_scope_id, v_organization_id, v_token_state,
         v_token_revision, v_token_selector, v_token_key_id,
         v_token_hmac, v_token_binding, v_user_state,
         v_user_authorization_version, v_identifier_state, v_identifier_value
    FROM iam_invitations AS invitation
    JOIN iam_one_time_tokens AS token
      ON token.id = p_token_id AND token.invitation_id = invitation.id
     AND token.purpose = 'invitation_accept_v1'
    JOIN iam_users AS principal ON principal.id = p_accepted_user_id
    JOIN iam_user_identifiers AS identifier
      ON identifier.id = p_accepted_identifier_id
     AND identifier.user_id = principal.id AND identifier.kind = 'email_v1'
    WHERE invitation.id = p_invitation_id
    FOR UPDATE OF invitation, token, principal, identifier;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation acceptance target is unknown';
    END IF;
    IF v_token_selector IS DISTINCT FROM p_selector OR
       v_token_key_id IS DISTINCT FROM p_hash_key_id OR
       v_token_hmac IS DISTINCT FROM p_secret_hmac OR
       v_token_binding IS DISTINCT FROM p_binding_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation credential is denied';
    END IF;
    SELECT command_key, request_sha256, result_code,
           result_revision, clock_value, result_id
    INTO v_receipt_command, v_receipt_hash, v_receipt_code,
         v_receipt_revision, v_receipt_clock, v_receipt_result_id
    FROM iam_authorization_operation_receipts WHERE operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.invitation.accept' OR
           v_receipt_hash IS DISTINCT FROM p_request_sha256 OR
           v_receipt_result_id IS DISTINCT FROM p_invitation_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM invitation operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_code, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    IF v_invitation_state IS DISTINCT FROM 'pending' OR
       v_invitation_revision IS DISTINCT FROM p_expected_invitation_revision OR
       v_token_state IS DISTINCT FROM 'pending' OR
       v_token_revision IS DISTINCT FROM p_expected_token_revision OR
       v_now >= v_invitation_expires_at OR v_user_state IS DISTINCT FROM 'active' OR
       v_user_authorization_version IS DISTINCT FROM
           p_expected_authorization_version OR
       v_identifier_state IS DISTINCT FROM 'active' OR
       v_identifier_value IS DISTINCT FROM v_normalized_value THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation acceptance CAS is stale';
    END IF;
    v_assignment_id := iam_invitation_grant_role_v1(
        p_accepted_user_id, p_role_assignment_id, p_membership_id,
        v_role_id, v_role_scope_kind, v_role_scope_id,
        v_organization_id, v_now
    );
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL OR v_assignment_id IS DISTINCT FROM p_role_assignment_id THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM invitation authorization clock is unavailable';
    END IF;
    UPDATE iam_users
    SET authorization_version = authorization_version + 1,
        revision = revision + 1, updated_at = v_now
    WHERE id = p_accepted_user_id;
    UPDATE iam_invitations
    SET accepted_user_id = p_accepted_user_id,
        accepted_identifier_id = p_accepted_identifier_id,
        accepted_identifier_kind = 'email_v1', state = 'accepted',
        accepted_at = v_now, updated_at = v_now,
        revision = v_invitation_revision + 1
    WHERE id = p_invitation_id;
    UPDATE iam_one_time_tokens
    SET state = 'consumed', consumed_at = v_now,
        updated_at = v_now, revision = v_token_revision + 1
    WHERE id = p_token_id;
    DELETE FROM iam_invitation_delivery_artifacts
    WHERE invitation_id = p_invitation_id AND token_id = p_token_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation delivery artifact is stale';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value, result_code,
        result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.invitation.accept', p_request_sha256,
        v_clock, 'iam.invitation.accepted', p_invitation_id,
        v_invitation_revision + 1, p_request_sha256, v_now
    );
    RETURN QUERY SELECT 'iam.invitation.accepted'::text,
        v_invitation_revision + 1, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_accept_v3(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_accepted_user_id uuid, p_accepted_identifier_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_audit_write_v1(name, uuid, uuid, uuid, bytea, text, text, bigint, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_invitation_id uuid, p_request_sha256 bytea, p_command_key text, p_result_state text, p_result_revision bigint, p_delivery_artifact_ref text, p_authorization_clock bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_command text;
    v_actor uuid;
    v_request bytea;
    v_result_id uuid;
    v_state text;
    v_revision bigint;
    v_clock bigint;
    v_result_code text;
    v_invitation_state text;
    v_invitation_revision bigint;
    v_actor_active boolean;
    v_artifact_ref text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR p_actor_id IS NULL OR
       p_invitation_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation audit scope is invalid';
    END IF;
    SELECT state, revision INTO v_invitation_state, v_invitation_revision
    FROM iam_invitations WHERE id = p_invitation_id;
    SELECT true INTO v_actor_active FROM iam_users
    WHERE id = p_actor_id AND status = 'active';
    IF p_command_key = 'iam.invitation.accept' THEN
        SELECT command_key, request_sha256, result_id, result_code,
               result_revision, clock_value
        INTO v_command, v_request, v_result_id, v_result_code,
             v_revision, v_clock
        FROM iam_authorization_operation_receipts
        WHERE operation_id = p_operation_id;
        v_actor := p_actor_id;
        v_state := 'accepted';
        IF v_result_code IS DISTINCT FROM 'iam.invitation.accepted' OR
           v_clock IS DISTINCT FROM p_authorization_clock THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'IAM invitation acceptance audit evidence is invalid';
        END IF;
    ELSE
        SELECT command_key, actor_id, request_sha256, result_id,
               result_state, result_revision
        INTO v_command, v_actor, v_request, v_result_id, v_state, v_revision
        FROM iam_invitation_operation_receipts
        WHERE operation_id = p_operation_id;
        IF p_authorization_clock IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'IAM invitation audit clock is invalid';
        END IF;
    END IF;
    IF p_command_key = 'iam.invitation.create' THEN
        SELECT artifact_ref INTO v_artifact_ref
        FROM iam_invitation_delivery_artifacts
        WHERE invitation_id = p_invitation_id;
    END IF;
    IF v_command IS DISTINCT FROM p_command_key OR
       v_actor IS DISTINCT FROM p_actor_id OR
       v_request IS DISTINCT FROM p_request_sha256 OR
       v_result_id IS DISTINCT FROM p_invitation_id OR
       v_state IS DISTINCT FROM p_result_state OR
       v_revision IS DISTINCT FROM p_result_revision OR
       v_invitation_state IS DISTINCT FROM p_result_state OR
       v_invitation_revision IS DISTINCT FROM p_result_revision OR
       v_actor_active IS DISTINCT FROM true OR
       v_artifact_ref IS DISTINCT FROM p_delivery_artifact_ref THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM invitation audit evidence is invalid';
    END IF;
    INSERT INTO iam_invitation_change_audit (
        operation_id, command_key, actor_id, invitation_id, request_sha256,
        result_state, result_revision, delivery_artifact_ref,
        authorization_clock, recorded_at
    ) VALUES (
        p_operation_id, p_command_key, p_actor_id, p_invitation_id,
        p_request_sha256, p_result_state, p_result_revision,
        p_delivery_artifact_ref, p_authorization_clock,
        pg_catalog.transaction_timestamp()
    );
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_invitation_id uuid, p_request_sha256 bytea, p_command_key text, p_result_state text, p_result_revision bigint, p_delivery_artifact_ref text, p_authorization_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_create_v1(name, uuid, text, text, bytea, uuid, text, uuid, uuid, uuid, bigint, uuid, bytea, text, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_create_v1(p_scope_schema name, p_invitation_id uuid, p_display_value text, p_normalized_value text, p_normalized_sha256 bytea, p_role_id uuid, p_role_scope_kind text, p_role_scope_id uuid, p_organization_id uuid, p_invited_by uuid, p_expected_authorization_version bigint, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) RETURNS TABLE(invitation_id uuid, invitation_state text, invitation_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_expires_at timestamptz;
    v_user_state text;
    v_authorization_version bigint;
    v_role_state text;
    v_role_scope_kind text;
    v_role_scope_id uuid;
    v_role_protected boolean;
BEGIN
    v_expires_at := v_now + INTERVAL '7 days';
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation creation scope is invalid';
    END IF;
    IF p_invitation_id IS NULL OR p_token_id IS NULL OR
       p_role_id IS NULL OR p_role_scope_id IS NULL OR p_invited_by IS NULL OR
       p_expected_authorization_version < 1 OR
       p_role_scope_kind NOT IN ('tenant', 'organization') OR
       (p_role_scope_kind = 'tenant' AND p_organization_id IS NOT NULL) OR
       (p_role_scope_kind = 'organization' AND
           p_organization_id IS DISTINCT FROM p_role_scope_id) OR
       pg_catalog.char_length(p_display_value) NOT BETWEEN 1 AND 320 OR
       pg_catalog.octet_length(p_normalized_value) NOT BETWEEN 3 AND 254 OR
       pg_catalog.octet_length(p_normalized_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       p_hash_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_binding_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation creation input is invalid';
    END IF;
    SELECT principal.status, principal.authorization_version
    INTO v_user_state, v_authorization_version
    FROM iam_users AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_invited_by
    FOR UPDATE;
    IF NOT FOUND OR v_user_state IS DISTINCT FROM 'active' OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version OR
       NOT iam_invitation_manager_v1(p_invited_by) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation creation authority is denied';
    END IF;
    SELECT role.status, role.scope_kind, role.scope_id, role.is_protected
    INTO v_role_state, v_role_scope_kind, v_role_scope_id, v_role_protected
    FROM iam_roles AS role
    WHERE role.id OPERATOR(pg_catalog.=) p_role_id
    FOR UPDATE;
    IF NOT FOUND OR v_role_state IS DISTINCT FROM 'active' OR v_role_protected OR
       v_role_scope_kind IS DISTINCT FROM p_role_scope_kind OR
       v_role_scope_id IS DISTINCT FROM p_role_scope_id OR
       (p_organization_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM iam_organizations AS organization
           WHERE organization.id OPERATOR(pg_catalog.=) p_organization_id
             AND organization.status OPERATOR(pg_catalog.=) 'active'
       )) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation role authority is denied';
    END IF;
    INSERT INTO iam_invitations (
        id, identifier_kind, display_value, normalized_value, normalized_sha256,
        role_id, role_scope_kind, role_scope_id, organization_id, invited_by,
        accepted_user_id, accepted_identifier_id, accepted_identifier_kind,
        state, revision, created_at, updated_at, expires_at,
        accepted_at, revoked_at, expired_at
    ) VALUES (
        p_invitation_id, 'email_v1', p_display_value, p_normalized_value,
        p_normalized_sha256, p_role_id, p_role_scope_kind, p_role_scope_id,
        p_organization_id, p_invited_by, NULL, NULL, NULL,
        'pending', 1, v_now, v_now, v_expires_at, NULL, NULL, NULL
    );
    INSERT INTO iam_one_time_tokens (
        id, purpose, user_id, identifier_id, identifier_kind,
        identifier_revision, invitation_id, invitation_expires_at,
        invitation_revision, portal_binding_id, portal_setup_revision,
        selector, hash_key_id, secret_hmac, binding_sha256, state,
        attempt_count, revision, created_at, updated_at, expires_at,
        consumed_at, revoked_at, expired_at, purge_after
    ) VALUES (
        p_token_id, 'invitation_accept_v1', NULL, NULL, NULL, NULL,
        p_invitation_id, v_expires_at, 1, NULL, NULL,
        p_selector, p_hash_key_id, p_secret_hmac, p_binding_sha256,
        'pending', 0, 1, v_now, v_now, v_expires_at,
        NULL, NULL, NULL, v_expires_at + INTERVAL '24 hours'
    );
    RETURN QUERY SELECT p_invitation_id, 'pending'::text, 1::bigint;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_invitation_create_v1(p_scope_schema name, p_invitation_id uuid, p_display_value text, p_normalized_value text, p_normalized_sha256 bytea, p_role_id uuid, p_role_scope_kind text, p_role_scope_id uuid, p_organization_id uuid, p_invited_by uuid, p_expected_authorization_version bigint, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_invitation_create_v2(name, uuid, bytea, uuid, text, text, bytea, uuid, text, uuid, uuid, uuid, bigint, uuid, bytea, text, bytea, bytea, uuid, text, text, bytea, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_create_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_display_value text, p_normalized_value text, p_normalized_sha256 bytea, p_role_id uuid, p_role_scope_kind text, p_role_scope_id uuid, p_organization_id uuid, p_invited_by uuid, p_expected_authorization_version bigint, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_artifact_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) RETURNS TABLE(invitation_id uuid, invitation_state text, invitation_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_expires_at timestamptz;
    v_user_state text;
    v_authorization_version bigint;
    v_role_state text;
    v_role_scope_kind text;
    v_role_scope_id uuid;
    v_role_protected boolean;
    v_receipt_command text;
    v_receipt_actor uuid;
    v_receipt_hash bytea;
    v_receipt_id uuid;
    v_receipt_state text;
    v_receipt_revision bigint;
BEGIN
    v_expires_at := v_now + INTERVAL '7 days';
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation creation scope is invalid';
    END IF;
    IF p_operation_id IS NULL OR p_invitation_id IS NULL OR
       p_invited_by IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation creation identity is invalid';
    END IF;
    SELECT command_key, actor_id, request_sha256, result_id,
           result_state, result_revision
    INTO v_receipt_command, v_receipt_actor, v_receipt_hash, v_receipt_id,
         v_receipt_state, v_receipt_revision
    FROM iam_invitation_operation_receipts WHERE operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.invitation.create' OR
           v_receipt_actor IS DISTINCT FROM p_invited_by OR
           v_receipt_hash IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_invitation_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM invitation operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_state,
            v_receipt_revision, true;
        RETURN;
    END IF;
    IF p_token_id IS NULL OR p_artifact_id IS NULL OR p_role_id IS NULL OR
       p_role_scope_id IS NULL OR p_expected_authorization_version < 1 OR
       p_role_scope_kind NOT IN ('tenant', 'organization') OR
       (p_role_scope_kind = 'tenant' AND p_organization_id IS NOT NULL) OR
       (p_role_scope_kind = 'organization' AND
        p_organization_id IS DISTINCT FROM p_role_scope_id) OR
       pg_catalog.char_length(p_display_value) NOT BETWEEN 1 AND 320 OR
       pg_catalog.octet_length(p_normalized_value) NOT BETWEEN 3 AND 254 OR
       pg_catalog.octet_length(p_normalized_sha256) <> 32 OR
       pg_catalog.octet_length(p_selector) <> 16 OR
       NOT iam_hmac_key_id_valid_v1(p_hash_key_id) OR
       pg_catalog.octet_length(p_secret_hmac) <> 32 OR
       pg_catalog.octet_length(p_binding_sha256) <> 32 OR
       p_artifact_ref NOT LIKE '%/artifact/' || p_artifact_id::text OR
       pg_catalog.octet_length(p_nonce) <> 12 OR
       pg_catalog.octet_length(p_ciphertext) <> 66 OR
       pg_catalog.octet_length(p_authentication_tag) <> 16 OR
       pg_catalog.octet_length(p_aad_sha256) <> 32 OR
       pg_catalog.octet_length(p_ciphertext_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation creation input is invalid';
    END IF;
    SELECT status, authorization_version
    INTO v_user_state, v_authorization_version
    FROM iam_users WHERE id = p_invited_by FOR UPDATE;
    IF NOT FOUND OR v_user_state IS DISTINCT FROM 'active' OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version OR
       NOT iam_invitation_manager_v1(p_invited_by) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation creation authority is denied';
    END IF;
    SELECT status, scope_kind, scope_id, is_protected
    INTO v_role_state, v_role_scope_kind, v_role_scope_id, v_role_protected
    FROM iam_roles WHERE id = p_role_id FOR UPDATE;
    IF NOT FOUND OR v_role_state IS DISTINCT FROM 'active' OR v_role_protected OR
       v_role_scope_kind IS DISTINCT FROM p_role_scope_kind OR
       v_role_scope_id IS DISTINCT FROM p_role_scope_id OR
       (p_organization_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM iam_organizations
           WHERE id = p_organization_id AND status = 'active'
       )) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation role authority is denied';
    END IF;
    INSERT INTO iam_invitations (
        id, identifier_kind, display_value, normalized_value, normalized_sha256,
        role_id, role_scope_kind, role_scope_id, organization_id, invited_by,
        accepted_user_id, accepted_identifier_id, accepted_identifier_kind,
        state, revision, created_at, updated_at, expires_at,
        accepted_at, revoked_at, expired_at
    ) VALUES (
        p_invitation_id, 'email_v1', p_display_value, p_normalized_value,
        p_normalized_sha256, p_role_id, p_role_scope_kind, p_role_scope_id,
        p_organization_id, p_invited_by, NULL, NULL, NULL,
        'pending', 1, v_now, v_now, v_expires_at, NULL, NULL, NULL
    );
    INSERT INTO iam_one_time_tokens (
        id, purpose, user_id, identifier_id, identifier_kind,
        identifier_revision, invitation_id, invitation_expires_at,
        invitation_revision, portal_binding_id, portal_setup_revision,
        selector, hash_key_id, secret_hmac, binding_sha256, state,
        attempt_count, revision, created_at, updated_at, expires_at,
        consumed_at, revoked_at, expired_at, purge_after
    ) VALUES (
        p_token_id, 'invitation_accept_v1', NULL, NULL, NULL, NULL,
        p_invitation_id, v_expires_at, 1, NULL, NULL,
        p_selector, p_hash_key_id, p_secret_hmac, p_binding_sha256,
        'pending', 0, 1, v_now, v_now, v_expires_at,
        NULL, NULL, NULL, v_expires_at + INTERVAL '24 hours'
    );
    INSERT INTO iam_invitation_delivery_artifacts (
        id, invitation_id, token_id, artifact_ref, kms_key_id, nonce,
        ciphertext, authentication_tag, aad_sha256, ciphertext_sha256,
        revision, created_at, expires_at
    ) VALUES (
        p_artifact_id, p_invitation_id, p_token_id, p_artifact_ref, p_kms_key_id,
        p_nonce, p_ciphertext, p_authentication_tag, p_aad_sha256,
        p_ciphertext_sha256, 1, v_now, v_expires_at
    );
    INSERT INTO iam_invitation_operation_receipts (
        operation_id, command_key, actor_id, request_sha256, result_id,
        result_state, result_revision, created_at
    ) VALUES (
        p_operation_id, 'iam.invitation.create', p_invited_by, p_request_sha256,
        p_invitation_id, 'pending', 1, v_now
    );
    RETURN QUERY SELECT p_invitation_id, 'pending'::text, 1::bigint, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_create_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_display_value text, p_normalized_value text, p_normalized_sha256 bytea, p_role_id uuid, p_role_scope_kind text, p_role_scope_id uuid, p_organization_id uuid, p_invited_by uuid, p_expected_authorization_version bigint, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_artifact_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_invitation_credential_lookup_v1(name, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_credential_lookup_v1(p_scope_schema name, p_selector bytea, p_binding_sha256 bytea) RETURNS TABLE(invitation_id uuid, display_value text, normalized_value text, role_id uuid, role_name text, role_scope_kind text, role_scope_id uuid, organization_id uuid, invited_by uuid, accepted_user_id uuid, accepted_identifier_id uuid, invitation_state text, invitation_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, terminal_at timestamp with time zone, token_id uuid, selector bytea, hash_key_id text, secret_hmac bytea, binding_sha256 bytea, token_revision bigint, profile_catalog jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.octet_length(p_selector) <> 16 OR
       pg_catalog.octet_length(p_binding_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation credential lookup is denied';
    END IF;
    RETURN QUERY
    SELECT invitation.id, invitation.display_value, invitation.normalized_value,
           invitation.role_id, role.name, invitation.role_scope_kind,
           invitation.role_scope_id, invitation.organization_id,
           invitation.invited_by, invitation.accepted_user_id,
           invitation.accepted_identifier_id, invitation.state,
           invitation.revision, invitation.created_at, invitation.updated_at,
           invitation.expires_at, COALESCE(
               invitation.accepted_at, invitation.revoked_at, invitation.expired_at
           ), token.id, token.selector, token.hash_key_id,
           token.secret_hmac, token.binding_sha256, token.revision,
           iam_profile_active_catalog_read_v1(p_scope_schema, 'user')
    FROM iam_one_time_tokens AS token
    JOIN iam_invitations AS invitation ON invitation.id = token.invitation_id
    JOIN iam_roles AS role ON role.id = invitation.role_id
    WHERE token.purpose = 'invitation_accept_v1'
      AND token.selector = p_selector
      AND token.binding_sha256 = p_binding_sha256
      AND token.state IN ('pending', 'consumed')
      AND invitation.state IN ('pending', 'accepted');
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation credential is unavailable';
    END IF;
END;
$$;


