--
-- Name: iam_invitation_delivery_worker_claim_v1(name, text, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_delivery_worker_claim_v1(p_scope_schema name, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text, p_message_id text, p_claimed_at timestamp with time zone) RETURNS TABLE(artifact_id uuid, invitation_id uuid, token_id uuid, artifact_ref text, recipient text, kms_key_id text, nonce bytea, ciphertext bytea, authentication_tag bytea, aad_sha256 bytea, ciphertext_sha256 bytea, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_effect_id IS NULL OR p_claimed_at IS NULL OR
       pg_catalog.char_length(p_effect_idempotency_key) NOT BETWEEN 1 AND 512 OR
       pg_catalog.char_length(p_message_id) NOT BETWEEN 3 AND 512 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation delivery claim is denied';
    END IF;
    RETURN QUERY
    WITH candidate AS MATERIALIZED (
        SELECT artifact.id, artifact.invitation_id, artifact.token_id,
               artifact.artifact_ref, invitation.normalized_value,
               artifact.kms_key_id, artifact.nonce, artifact.ciphertext,
               artifact.authentication_tag, artifact.aad_sha256,
               artifact.ciphertext_sha256, artifact.expires_at
        FROM iam_invitation_delivery_artifacts AS artifact
        JOIN iam_invitations AS invitation ON invitation.id = artifact.invitation_id
        WHERE artifact.artifact_ref = p_artifact_ref
          AND invitation.state = 'pending'
          AND invitation.expires_at > pg_catalog.statement_timestamp()
          AND artifact.expires_at > pg_catalog.statement_timestamp()
        FOR UPDATE OF artifact
    ), claimed AS (
        INSERT INTO iam_invitation_delivery_worker_claims (
            artifact_id, artifact_ref, effect_id, effect_idempotency_key,
            message_id, state, claimed_at, outcome_unknown_at
        )
        SELECT candidate.id, candidate.artifact_ref, p_effect_id,
               p_effect_idempotency_key, p_message_id, 'claimed', p_claimed_at, NULL
        FROM candidate
        ON CONFLICT ON CONSTRAINT iam_invitation_delivery_worker_claims_pkey DO NOTHING
        RETURNING iam_invitation_delivery_worker_claims.artifact_id
    )
    SELECT candidate.id, candidate.invitation_id, candidate.token_id,
           candidate.artifact_ref, candidate.normalized_value,
           candidate.kms_key_id, candidate.nonce, candidate.ciphertext,
           candidate.authentication_tag, candidate.aad_sha256,
           candidate.ciphertext_sha256, candidate.expires_at
    FROM candidate JOIN claimed ON claimed.artifact_id = candidate.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_delivery_worker_claim_v1(p_scope_schema name, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text, p_message_id text, p_claimed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_invitation_delivery_worker_finalize_v1(name, uuid, text, uuid, text, text, text, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_delivery_worker_finalize_v1(p_scope_schema name, p_receipt_id uuid, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text, p_message_id text, p_outcome text, p_code text, p_provider_reference text, p_result_sha256 bytea, p_completed_at timestamp with time zone) RETURNS TABLE(receipt_id uuid, artifact_ref text, effect_idempotency_key text, message_id text, outcome text, code text, provider_reference text, result_sha256 bytea, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_receipt_id IS NULL OR p_effect_id IS NULL OR p_completed_at IS NULL OR
       p_outcome NOT IN ('delivered','permanent_failure') OR
       p_code !~ '^[A-Z][A-Z0-9_]{1,63}$' OR
       pg_catalog.octet_length(p_result_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation delivery finalization is denied';
    END IF;
    RETURN QUERY
    WITH inserted AS (
        INSERT INTO iam_invitation_delivery_worker_receipts (
            receipt_id, artifact_id, invitation_id, token_id, artifact_ref,
            effect_id, effect_idempotency_key, message_id, outcome, code,
            provider_reference, result_sha256, completed_at
        )
        SELECT p_receipt_id, artifact.id, artifact.invitation_id, artifact.token_id,
               artifact.artifact_ref, p_effect_id, p_effect_idempotency_key,
               p_message_id, p_outcome, p_code, p_provider_reference,
               p_result_sha256, p_completed_at
        FROM iam_invitation_delivery_artifacts AS artifact
        JOIN iam_invitation_delivery_worker_claims AS claim
          ON claim.artifact_id = artifact.id
        WHERE artifact.artifact_ref = p_artifact_ref
          AND claim.effect_id = p_effect_id
          AND claim.effect_idempotency_key = p_effect_idempotency_key
          AND claim.message_id = p_message_id AND claim.state = 'claimed'
        ON CONFLICT ON CONSTRAINT iam_invitation_delivery_worker_receipts_artifact_key DO NOTHING
        RETURNING iam_invitation_delivery_worker_receipts.*
    ), consumed AS (
        DELETE FROM iam_invitation_delivery_artifacts AS artifact
        USING inserted
        WHERE artifact.id = inserted.artifact_id
        RETURNING artifact.id
    )
    SELECT inserted.receipt_id, inserted.artifact_ref,
           inserted.effect_idempotency_key, inserted.message_id,
           inserted.outcome, inserted.code, inserted.provider_reference,
           inserted.result_sha256, inserted.completed_at
    FROM inserted JOIN consumed ON consumed.id = inserted.artifact_id;
    IF NOT FOUND THEN
        RETURN QUERY
        SELECT receipt.receipt_id, receipt.artifact_ref,
               receipt.effect_idempotency_key, receipt.message_id,
               receipt.outcome, receipt.code, receipt.provider_reference,
               receipt.result_sha256, receipt.completed_at
        FROM iam_invitation_delivery_worker_receipts AS receipt
        WHERE receipt.artifact_ref = p_artifact_ref
          AND receipt.effect_id = p_effect_id
          AND receipt.effect_idempotency_key = p_effect_idempotency_key
          AND receipt.message_id = p_message_id;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation delivery finalization conflicts';
    END IF;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_invitation_delivery_worker_finalize_v1(p_scope_schema name, p_receipt_id uuid, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text, p_message_id text, p_outcome text, p_code text, p_provider_reference text, p_result_sha256 bytea, p_completed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_invitation_delivery_worker_mark_unknown_v1(name, text, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_delivery_worker_mark_unknown_v1(p_scope_schema name, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text, p_outcome_unknown_at timestamp with time zone) RETURNS SETOF boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_effect_id IS NULL OR p_outcome_unknown_at IS NULL OR
       pg_catalog.char_length(p_artifact_ref) < 1 OR
       pg_catalog.char_length(p_effect_idempotency_key) NOT BETWEEN 1 AND 512 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation delivery unknown outcome is denied';
    END IF;
    RETURN QUERY
    WITH marked AS (
        UPDATE iam_invitation_delivery_worker_claims AS claim
        SET state = 'outcome_unknown',
            outcome_unknown_at = p_outcome_unknown_at
        WHERE claim.artifact_ref = p_artifact_ref
          AND claim.effect_id = p_effect_id
          AND claim.effect_idempotency_key = p_effect_idempotency_key
          AND (claim.state = 'claimed' OR
               (claim.state = 'outcome_unknown' AND
                claim.outcome_unknown_at = p_outcome_unknown_at))
        RETURNING true AS marked
    )
    SELECT marked.marked FROM marked;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_delivery_worker_mark_unknown_v1(p_scope_schema name, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text, p_outcome_unknown_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_invitation_delivery_worker_release_v1(name, text, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_delivery_worker_release_v1(p_scope_schema name, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text) RETURNS SETOF boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_effect_id IS NULL OR pg_catalog.char_length(p_artifact_ref) < 1 OR
       pg_catalog.char_length(p_effect_idempotency_key) NOT BETWEEN 1 AND 512 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation delivery claim release is denied';
    END IF;
    RETURN QUERY
    WITH released AS (
        DELETE FROM iam_invitation_delivery_worker_claims AS claim
        WHERE claim.artifact_ref = p_artifact_ref
          AND claim.effect_id = p_effect_id
          AND claim.effect_idempotency_key = p_effect_idempotency_key
          AND claim.state = 'claimed'
        RETURNING true AS released
    )
    SELECT released.released FROM released;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_delivery_worker_release_v1(p_scope_schema name, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text) OWNER TO harpy_owner;

--
-- Name: iam_invitation_expire_v1(name, uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_expire_v1(p_scope_schema name, p_invitation_id uuid, p_expected_revision bigint, p_actor_user_id uuid, p_expected_authorization_version bigint) RETURNS TABLE(invitation_id uuid, invitation_state text, invitation_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_state text;
    v_revision bigint;
    v_expires_at timestamptz;
    v_actor_state text;
    v_authorization_version bigint;
    v_token_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation expiry scope is invalid';
    END IF;
    IF p_invitation_id IS NULL OR p_expected_revision < 1 OR
       p_actor_user_id IS NULL OR p_expected_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation expiry input is invalid';
    END IF;
    SELECT invitation.state, invitation.revision, invitation.expires_at,
           actor.status, actor.authorization_version
    INTO v_state, v_revision, v_expires_at,
         v_actor_state, v_authorization_version
    FROM iam_invitations AS invitation
    JOIN iam_users AS actor ON actor.id = p_actor_user_id
    WHERE invitation.id OPERATOR(pg_catalog.=) p_invitation_id
    FOR UPDATE OF invitation, actor;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation is unknown';
    END IF;
    IF v_state IS DISTINCT FROM 'pending' OR
       v_revision IS DISTINCT FROM p_expected_revision OR
       v_now < v_expires_at OR v_actor_state IS DISTINCT FROM 'active' OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation expiry CAS is stale';
    END IF;
    IF NOT iam_invitation_manager_v1(p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation expiry authority is denied';
    END IF;
    UPDATE iam_one_time_tokens AS token
    SET state = 'expired', expired_at = expires_at, updated_at = v_now,
        revision = revision + 1
    WHERE token.invitation_id = p_invitation_id
      AND token.purpose = 'invitation_accept_v1' AND token.state = 'pending';
    GET DIAGNOSTICS v_token_count = ROW_COUNT;
    IF v_token_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation token expiry CAS is stale';
    END IF;
    UPDATE iam_invitations
    SET state = 'expired', expired_at = expires_at, updated_at = v_now,
        revision = v_revision + 1
    WHERE id = p_invitation_id;
    RETURN QUERY SELECT p_invitation_id, 'expired'::text, v_revision + 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_expire_v1(p_scope_schema name, p_invitation_id uuid, p_expected_revision bigint, p_actor_user_id uuid, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_expire_v2(name, uuid, bytea, uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_expire_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_revision bigint, p_actor_user_id uuid, p_expected_authorization_version bigint) RETURNS TABLE(invitation_id uuid, invitation_state text, invitation_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_id uuid;
    v_state text;
    v_revision bigint;
    v_command text;
    v_actor uuid;
    v_request bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR p_invitation_id IS NULL OR
       p_actor_user_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation expiry scope is invalid';
    END IF;
    SELECT command_key, actor_id, request_sha256, result_id,
           result_state, result_revision
    INTO v_command, v_actor, v_request, v_id, v_state, v_revision
    FROM iam_invitation_operation_receipts WHERE operation_id = p_operation_id;
    IF FOUND THEN
        IF v_command IS DISTINCT FROM 'iam.invitation.expire' OR
           v_actor IS DISTINCT FROM p_actor_user_id OR
           v_request IS DISTINCT FROM p_request_sha256 OR
           v_id IS DISTINCT FROM p_invitation_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM invitation operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_id, v_state, v_revision, true;
        RETURN;
    END IF;
    SELECT result.invitation_id, result.invitation_state,
           result.invitation_revision
    INTO v_id, v_state, v_revision
    FROM iam_invitation_expire_v1(
        p_scope_schema, p_invitation_id, p_expected_revision,
        p_actor_user_id, p_expected_authorization_version
    ) AS result;
    DELETE FROM iam_invitation_delivery_artifacts
    WHERE invitation_id = p_invitation_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation delivery artifact is stale';
    END IF;
    INSERT INTO iam_invitation_operation_receipts (
        operation_id, command_key, actor_id, request_sha256, result_id,
        result_state, result_revision, created_at
    ) VALUES (
        p_operation_id, 'iam.invitation.expire', p_actor_user_id,
        p_request_sha256, v_id, v_state, v_revision,
        pg_catalog.transaction_timestamp()
    );
    RETURN QUERY SELECT v_id, v_state, v_revision, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_expire_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_revision bigint, p_actor_user_id uuid, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_grant_role_v1(uuid, uuid, uuid, uuid, text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_grant_role_v1(p_user_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_role_id uuid, p_role_scope_kind text, p_role_scope_id uuid, p_organization_id uuid, p_now timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_role_state text;
    v_role_protected boolean;
    v_membership_id uuid;
    v_membership_state text;
BEGIN
    SELECT role.status, role.is_protected
    INTO v_role_state, v_role_protected
    FROM iam_roles AS role
    WHERE role.id = p_role_id
      AND role.scope_kind = p_role_scope_kind
      AND role.scope_id = p_role_scope_id
    FOR UPDATE;
    IF NOT FOUND OR v_role_state IS DISTINCT FROM 'active' OR v_role_protected THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation role grant is denied';
    END IF;
    IF p_role_scope_kind = 'tenant' THEN
        IF p_organization_id IS NOT NULL OR p_membership_id IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'IAM tenant invitation membership is invalid';
        END IF;
    ELSIF p_role_scope_kind = 'organization' THEN
        IF p_organization_id IS DISTINCT FROM p_role_scope_id OR NOT EXISTS (
            SELECT 1 FROM iam_organizations AS organization
            WHERE organization.id = p_organization_id
              AND organization.status = 'active'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '42501',
                MESSAGE = 'IAM invitation organization is denied';
        END IF;
        SELECT membership.id, membership.state
        INTO v_membership_id, v_membership_state
        FROM iam_organization_memberships AS membership
        WHERE membership.organization_id = p_organization_id
          AND membership.user_id = p_user_id
        FOR UPDATE;
        IF FOUND THEN
            IF v_membership_state IS DISTINCT FROM 'active' OR
               (p_membership_id IS NOT NULL AND
                   p_membership_id IS DISTINCT FROM v_membership_id) THEN
                RAISE EXCEPTION USING ERRCODE = '40001',
                    MESSAGE = 'IAM invitation membership is stale';
            END IF;
        ELSE
            IF p_membership_id IS NULL THEN
                RAISE EXCEPTION USING ERRCODE = '22023',
                    MESSAGE = 'IAM invitation membership identity is required';
            END IF;
            v_membership_id := p_membership_id;
            INSERT INTO iam_organization_memberships (
                id, organization_id, user_id, membership_kind, state,
                revision, created_at, updated_at, tombstoned_at
            ) VALUES (
                v_membership_id, p_organization_id, p_user_id, 'member',
                'active', 1, p_now, p_now, NULL
            );
        END IF;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation role scope is invalid';
    END IF;
    INSERT INTO iam_user_role_assignments (
        id, user_id, role_id, role_scope_kind, role_scope_id,
        organization_id, membership_id, state, revision,
        created_at, updated_at, revoked_at
    ) VALUES (
        p_role_assignment_id, p_user_id, p_role_id,
        p_role_scope_kind, p_role_scope_id, p_organization_id,
        v_membership_id, 'active', 1, p_now, p_now, NULL
    );
    RETURN p_role_assignment_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_grant_role_v1(p_user_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_role_id uuid, p_role_scope_kind text, p_role_scope_id uuid, p_organization_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_invitation_list_v1(name, uuid, jsonb, uuid, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_list_v1(p_scope_schema name, p_actor_user_id uuid, p_states jsonb, p_after uuid, p_limit integer) RETURNS TABLE(invitation_id uuid, display_value text, normalized_value text, role_id uuid, role_scope_kind text, role_scope_id uuid, organization_id uuid, invited_by uuid, accepted_user_id uuid, accepted_identifier_id uuid, invitation_state text, invitation_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, terminal_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation list scope is invalid';
    END IF;
    IF p_actor_user_id IS NULL OR
       pg_catalog.jsonb_typeof(p_states) IS DISTINCT FROM 'array' OR
       p_limit NOT BETWEEN 1 AND 101 OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements_text(p_states) AS requested(state)
           WHERE requested.state NOT IN (
               'pending', 'accepted', 'revoked', 'expired'
           )
       ) OR NOT EXISTS (
           SELECT 1 FROM iam_users AS actor
           WHERE actor.id OPERATOR(pg_catalog.=) p_actor_user_id
             AND actor.status OPERATOR(pg_catalog.=) 'active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation list authority is denied';
    END IF;
    RETURN QUERY
    SELECT invitation.id, invitation.display_value, invitation.normalized_value,
           invitation.role_id, invitation.role_scope_kind,
           invitation.role_scope_id, invitation.organization_id,
           invitation.invited_by, invitation.accepted_user_id,
           invitation.accepted_identifier_id, invitation.state,
           invitation.revision, invitation.created_at, invitation.updated_at,
           invitation.expires_at, COALESCE(
               invitation.accepted_at,
               invitation.revoked_at,
               invitation.expired_at
           )
    FROM iam_invitations AS invitation
    WHERE (p_states OPERATOR(pg_catalog.=) '[]'::jsonb OR
           invitation.state IN (
               SELECT requested.state
               FROM pg_catalog.jsonb_array_elements_text(p_states)
                   AS requested(state)
           ))
      AND (p_after IS NULL OR invitation.id OPERATOR(pg_catalog.>) p_after)
      AND (
          invitation.invited_by OPERATOR(pg_catalog.=) p_actor_user_id OR
          iam_invitation_manager_v1(p_actor_user_id)
      )
    ORDER BY invitation.id
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_list_v1(p_scope_schema name, p_actor_user_id uuid, p_states jsonb, p_after uuid, p_limit integer) OWNER TO harpy_owner;

--
-- Name: iam_invitation_list_v2(name, uuid, jsonb, uuid, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_list_v2(p_scope_schema name, p_actor_user_id uuid, p_states jsonb, p_after uuid, p_limit integer) RETURNS TABLE(invitation_id uuid, display_value text, normalized_value text, role_id uuid, role_name text, role_scope_kind text, role_scope_id uuid, organization_id uuid, invited_by uuid, accepted_user_id uuid, accepted_identifier_id uuid, invitation_state text, invitation_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, terminal_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT legacy.invitation_id, legacy.display_value, legacy.normalized_value,
           legacy.role_id, role.name, legacy.role_scope_kind, legacy.role_scope_id,
           legacy.organization_id, legacy.invited_by, legacy.accepted_user_id,
           legacy.accepted_identifier_id, legacy.invitation_state,
           legacy.invitation_revision, legacy.created_at, legacy.updated_at,
           legacy.expires_at, legacy.terminal_at
    FROM iam_invitation_list_v1(
        p_scope_schema, p_actor_user_id, p_states, p_after, p_limit
    ) AS legacy
    JOIN iam_roles AS role ON role.id = legacy.role_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_list_v2(p_scope_schema name, p_actor_user_id uuid, p_states jsonb, p_after uuid, p_limit integer) OWNER TO harpy_owner;

--
-- Name: iam_invitation_manager_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_manager_v1(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_permission_id uuid;
BEGIN
    SELECT permission.id
    INTO v_permission_id
    FROM iam_permissions AS permission
    JOIN iam_resources AS resource ON resource.id = permission.resource_id
    JOIN iam_actions AS action ON action.id = permission.action_id
    WHERE resource.resource_key OPERATOR(pg_catalog.=) 'iam.invitations'
      AND resource.state OPERATOR(pg_catalog.=) 'active'
      AND action.action_key OPERATOR(pg_catalog.=) 'manage'
      AND action.state OPERATOR(pg_catalog.=) 'active'
      AND permission.match_kind OPERATOR(pg_catalog.=) 'exact'
      AND permission.state OPERATOR(pg_catalog.=) 'active';
    IF NOT FOUND THEN
        RETURN false;
    END IF;
    RETURN iam_user_has_permission_v1(p_user_id, v_permission_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_manager_v1(p_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_invitation_read_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_read_v1(p_scope_schema name, p_actor_user_id uuid, p_invitation_id uuid) RETURNS TABLE(invitation_id uuid, display_value text, normalized_value text, role_id uuid, role_scope_kind text, role_scope_id uuid, organization_id uuid, invited_by uuid, accepted_user_id uuid, accepted_identifier_id uuid, invitation_state text, invitation_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, terminal_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation read scope is invalid';
    END IF;
    IF p_actor_user_id IS NULL OR p_invitation_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM iam_users AS actor
        WHERE actor.id OPERATOR(pg_catalog.=) p_actor_user_id
          AND actor.status OPERATOR(pg_catalog.=) 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation read authority is denied';
    END IF;
    RETURN QUERY
    SELECT invitation.id, invitation.display_value, invitation.normalized_value,
           invitation.role_id, invitation.role_scope_kind,
           invitation.role_scope_id, invitation.organization_id,
           invitation.invited_by, invitation.accepted_user_id,
           invitation.accepted_identifier_id, invitation.state,
           invitation.revision, invitation.created_at, invitation.updated_at,
           invitation.expires_at, COALESCE(
               invitation.accepted_at,
               invitation.revoked_at,
               invitation.expired_at
           )
    FROM iam_invitations AS invitation
    WHERE invitation.id OPERATOR(pg_catalog.=) p_invitation_id AND (
        invitation.invited_by OPERATOR(pg_catalog.=) p_actor_user_id OR
        iam_invitation_manager_v1(p_actor_user_id)
    );
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_read_v1(p_scope_schema name, p_actor_user_id uuid, p_invitation_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_invitation_read_v2(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_read_v2(p_scope_schema name, p_actor_user_id uuid, p_invitation_id uuid) RETURNS TABLE(invitation_id uuid, display_value text, normalized_value text, role_id uuid, role_name text, role_scope_kind text, role_scope_id uuid, organization_id uuid, invited_by uuid, accepted_user_id uuid, accepted_identifier_id uuid, invitation_state text, invitation_revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, expires_at timestamp with time zone, terminal_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT legacy.invitation_id, legacy.display_value, legacy.normalized_value,
           legacy.role_id, role.name, legacy.role_scope_kind, legacy.role_scope_id,
           legacy.organization_id, legacy.invited_by, legacy.accepted_user_id,
           legacy.accepted_identifier_id, legacy.invitation_state,
           legacy.invitation_revision, legacy.created_at, legacy.updated_at,
           legacy.expires_at, legacy.terminal_at
    FROM iam_invitation_read_v1(
        p_scope_schema, p_actor_user_id, p_invitation_id
    ) AS legacy
    JOIN iam_roles AS role ON role.id = legacy.role_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_read_v2(p_scope_schema name, p_actor_user_id uuid, p_invitation_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_invitation_register_accept_v1(name, uuid, bytea, uuid, bigint, uuid, bigint, bytea, text, bytea, bytea, uuid, uuid, uuid, uuid, uuid, uuid, bytea, bytea, bytea, bytea, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_register_accept_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_user_id uuid, p_identifier_id uuid, p_access_mode_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_password_salt bytea, p_password_tag bytea, p_expected_authorization_version bigint) RETURNS TABLE(result_code text, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_state text; v_revision bigint; v_expires_at timestamptz;
    v_display text; v_normalized text; v_normalized_sha bytea;
    v_role_id uuid; v_scope_kind text; v_scope_id uuid; v_organization_id uuid;
    v_token_state text; v_token_revision bigint; v_selector bytea;
    v_key_id text; v_hmac bytea; v_binding bytea; v_values jsonb;
    v_receipt_command text; v_receipt_hash bytea; v_receipt_code text;
    v_receipt_revision bigint; v_receipt_clock bigint; v_receipt_id uuid;
    v_clock bigint; v_assignment uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR
       p_invitation_id IS NULL OR p_token_id IS NULL OR p_user_id IS NULL OR
       p_identifier_id IS NULL OR p_access_mode_id IS NULL OR
       p_role_assignment_id IS NULL OR p_profile_schema_id IS NULL OR
       p_expected_invitation_revision < 1 OR p_expected_token_revision < 1 OR
       p_expected_authorization_version <> 1 OR
       pg_catalog.octet_length(p_request_sha256) <> 32 OR
       pg_catalog.octet_length(p_selector) <> 16 OR
       NOT iam_hmac_key_id_valid_v1(p_hash_key_id) OR
       pg_catalog.octet_length(p_secret_hmac) <> 32 OR
       pg_catalog.octet_length(p_binding_sha256) <> 32 OR
       pg_catalog.octet_length(p_profile_sha256) <> 32 OR
       pg_catalog.octet_length(p_password_salt) <> 16 OR
       pg_catalog.octet_length(p_password_tag) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation registration input is invalid';
    END IF;
    SELECT invitation.state, invitation.revision, invitation.expires_at,
           invitation.display_value, invitation.normalized_value,
           invitation.normalized_sha256, invitation.role_id,
           invitation.role_scope_kind, invitation.role_scope_id,
           invitation.organization_id, token.state, token.revision,
           token.selector, token.hash_key_id, token.secret_hmac,
           token.binding_sha256
    INTO v_state, v_revision, v_expires_at, v_display, v_normalized,
         v_normalized_sha, v_role_id, v_scope_kind, v_scope_id,
         v_organization_id, v_token_state, v_token_revision, v_selector,
         v_key_id, v_hmac, v_binding
    FROM iam_invitations AS invitation
    JOIN iam_one_time_tokens AS token
      ON token.id = p_token_id AND token.invitation_id = invitation.id
     AND token.purpose = 'invitation_accept_v1'
    WHERE invitation.id = p_invitation_id
    FOR UPDATE OF invitation, token;
    IF NOT FOUND OR v_selector IS DISTINCT FROM p_selector OR
       v_key_id IS DISTINCT FROM p_hash_key_id OR
       v_hmac IS DISTINCT FROM p_secret_hmac OR
       v_binding IS DISTINCT FROM p_binding_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation credential is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_code,
           receipt.result_revision, receipt.clock_value, receipt.result_id
    INTO v_receipt_command, v_receipt_hash, v_receipt_code,
         v_receipt_revision, v_receipt_clock, v_receipt_id
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.invitation.accept' OR
           v_receipt_hash IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_invitation_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM invitation operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_code, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    IF v_state IS DISTINCT FROM 'pending' OR
       v_revision IS DISTINCT FROM p_expected_invitation_revision OR
       v_token_state IS DISTINCT FROM 'pending' OR
       v_token_revision IS DISTINCT FROM p_expected_token_revision OR
       v_now >= v_expires_at OR EXISTS (
           SELECT 1 FROM iam_user_identifiers AS identifier
           WHERE identifier.kind = 'email_v1'
             AND identifier.normalized_value = v_normalized
             AND identifier.state <> 'retired'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation registration CAS is stale';
    END IF;
    v_values := iam_identity_profile_assert_v1(
        'user', p_profile_schema_id, p_profile_document, p_profile_sha256
    );
    INSERT INTO iam_users (
        id, identity_kind, status, profile_resource_kind,
        profile_schema_version_id, profile_values, profile_sha256,
        token_version, authorization_version, revision, created_at, updated_at
    ) VALUES (
        p_user_id, 'human', 'active', 'user', p_profile_schema_id,
        v_values, p_profile_sha256, 1, 1, 1, v_now, v_now
    );
    INSERT INTO iam_user_identifiers (
        id, user_id, kind, display_value, normalized_value, normalized_sha256,
        state, revision, verified_at, activated_at, created_at, updated_at
    ) VALUES (
        p_identifier_id, p_user_id, 'email_v1', v_display, v_normalized,
        v_normalized_sha, 'active', 1, v_now, v_now, v_now, v_now
    );
    INSERT INTO iam_user_access_modes (
        id, user_id, mode, state, revision,
        created_at, updated_at, activated_at
    ) VALUES (
        p_access_mode_id, p_user_id, 'operator_console', 'active', 1,
        v_now, v_now, v_now
    );
    INSERT INTO iam_password_credentials (
        user_id, credential_version, state, algorithm, salt, tag,
        memory_kib, iterations, parallelism, legacy_bcrypt_hash,
        upgrade_required, revision, created_at, updated_at
    ) VALUES (
        p_user_id, 1, 'active', 'argon2id_v1', p_password_salt, p_password_tag,
        65536, 3, 4, NULL, false, 1, v_now, v_now
    );
    v_assignment := iam_invitation_grant_role_v1(
        p_user_id, p_role_assignment_id, p_membership_id, v_role_id,
        v_scope_kind, v_scope_id, v_organization_id, v_now
    );
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF v_assignment IS DISTINCT FROM p_role_assignment_id OR v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM invitation registration effect is unavailable';
    END IF;
    UPDATE iam_invitations SET accepted_user_id = p_user_id,
        accepted_identifier_id = p_identifier_id,
        accepted_identifier_kind = 'email_v1', state = 'accepted',
        accepted_at = v_now, updated_at = v_now, revision = v_revision + 1
    WHERE id = p_invitation_id;
    UPDATE iam_one_time_tokens SET state = 'consumed', consumed_at = v_now,
        updated_at = v_now, revision = v_token_revision + 1
    WHERE id = p_token_id;
    DELETE FROM iam_invitation_delivery_artifacts
    WHERE invitation_id = p_invitation_id AND token_id = p_token_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation delivery artifact is stale';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value, result_code,
        result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.invitation.accept', p_request_sha256,
        v_clock, 'iam.invitation.accepted', p_invitation_id,
        v_revision + 1, p_request_sha256, v_now
    );
    RETURN QUERY SELECT 'iam.invitation.accepted'::text,
        v_revision + 1, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_register_accept_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_user_id uuid, p_identifier_id uuid, p_access_mode_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_password_salt bytea, p_password_tag bytea, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_register_accept_v2(name, uuid, bytea, uuid, bigint, uuid, bigint, bytea, text, bytea, bytea, uuid, uuid, uuid, uuid, uuid, uuid, bytea, bytea, bytea, bytea, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_register_accept_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_user_id uuid, p_identifier_id uuid, p_access_mode_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_password_salt bytea, p_password_tag bytea, p_expected_authorization_version bigint) RETURNS TABLE(result_code text, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_state text; v_revision bigint; v_expires_at timestamptz;
    v_display text; v_normalized text; v_normalized_sha bytea;
    v_role_id uuid; v_scope_kind text; v_scope_id uuid; v_organization_id uuid;
    v_token_state text; v_token_revision bigint; v_selector bytea;
    v_key_id text; v_hmac bytea; v_binding bytea; v_values jsonb;
    v_receipt_command text; v_receipt_hash bytea; v_receipt_code text;
    v_receipt_revision bigint; v_receipt_clock bigint; v_receipt_id uuid;
    v_clock bigint; v_assignment uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR
       p_invitation_id IS NULL OR p_token_id IS NULL OR p_user_id IS NULL OR
       p_identifier_id IS NULL OR p_access_mode_id IS NULL OR
       p_role_assignment_id IS NULL OR p_profile_schema_id IS NULL OR
       p_expected_invitation_revision < 1 OR p_expected_token_revision < 1 OR
       p_expected_authorization_version <> 1 OR
       pg_catalog.octet_length(p_request_sha256) <> 32 OR
       pg_catalog.octet_length(p_selector) <> 16 OR
       NOT iam_hmac_key_id_valid_v1(p_hash_key_id) OR
       pg_catalog.octet_length(p_secret_hmac) <> 32 OR
       pg_catalog.octet_length(p_binding_sha256) <> 32 OR
       pg_catalog.octet_length(p_profile_sha256) <> 32 OR
       pg_catalog.octet_length(p_password_salt) <> 16 OR
       pg_catalog.octet_length(p_password_tag) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation registration input is invalid';
    END IF;
    SELECT invitation.state, invitation.revision, invitation.expires_at,
           invitation.display_value, invitation.normalized_value,
           invitation.normalized_sha256, invitation.role_id,
           invitation.role_scope_kind, invitation.role_scope_id,
           invitation.organization_id, token.state, token.revision,
           token.selector, token.hash_key_id, token.secret_hmac,
           token.binding_sha256
    INTO v_state, v_revision, v_expires_at, v_display, v_normalized,
         v_normalized_sha, v_role_id, v_scope_kind, v_scope_id,
         v_organization_id, v_token_state, v_token_revision, v_selector,
         v_key_id, v_hmac, v_binding
    FROM iam_invitations AS invitation
    JOIN iam_one_time_tokens AS token
      ON token.id = p_token_id AND token.invitation_id = invitation.id
     AND token.purpose = 'invitation_accept_v1'
    WHERE invitation.id = p_invitation_id
    FOR UPDATE OF invitation, token;
    IF NOT FOUND OR v_selector IS DISTINCT FROM p_selector OR
       v_key_id IS DISTINCT FROM p_hash_key_id OR
       v_hmac IS DISTINCT FROM p_secret_hmac OR
       v_binding IS DISTINCT FROM p_binding_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation credential is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_code,
           receipt.result_revision, receipt.clock_value, receipt.result_id
    INTO v_receipt_command, v_receipt_hash, v_receipt_code,
         v_receipt_revision, v_receipt_clock, v_receipt_id
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.invitation.accept' OR
           v_receipt_hash IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_invitation_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM invitation operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_code, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    IF v_state IS DISTINCT FROM 'pending' OR
       v_revision IS DISTINCT FROM p_expected_invitation_revision OR
       v_token_state IS DISTINCT FROM 'pending' OR
       v_token_revision IS DISTINCT FROM p_expected_token_revision OR
       v_now >= v_expires_at OR EXISTS (
           SELECT 1 FROM iam_user_identifiers AS identifier
           WHERE identifier.kind = 'email_v1'
             AND identifier.normalized_value = v_normalized
             AND identifier.state <> 'retired'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation registration CAS is stale';
    END IF;
    v_values := iam_identity_profile_assert_v2(
        'user', p_profile_schema_id, p_profile_document, p_profile_sha256
    );
    INSERT INTO iam_users (
        id, identity_kind, status, profile_resource_kind,
        profile_schema_version_id, profile_values, profile_sha256,
        token_version, authorization_version, revision, created_at, updated_at
    ) VALUES (
        p_user_id, 'human', 'active', 'user', p_profile_schema_id,
        v_values, p_profile_sha256, 1, 1, 1, v_now, v_now
    );
    INSERT INTO iam_user_identifiers (
        id, user_id, kind, display_value, normalized_value, normalized_sha256,
        state, revision, verified_at, activated_at, created_at, updated_at
    ) VALUES (
        p_identifier_id, p_user_id, 'email_v1', v_display, v_normalized,
        v_normalized_sha, 'active', 1, v_now, v_now, v_now, v_now
    );
    INSERT INTO iam_user_access_modes (
        id, user_id, mode, state, revision,
        created_at, updated_at, activated_at
    ) VALUES (
        p_access_mode_id, p_user_id, 'operator_console', 'active', 1,
        v_now, v_now, v_now
    );
    INSERT INTO iam_password_credentials (
        user_id, credential_version, state, algorithm, salt, tag,
        memory_kib, iterations, parallelism, legacy_bcrypt_hash,
        upgrade_required, revision, created_at, updated_at
    ) VALUES (
        p_user_id, 1, 'active', 'argon2id_v1', p_password_salt, p_password_tag,
        65536, 3, 4, NULL, false, 1, v_now, v_now
    );
    v_assignment := iam_invitation_grant_role_v1(
        p_user_id, p_role_assignment_id, p_membership_id, v_role_id,
        v_scope_kind, v_scope_id, v_organization_id, v_now
    );
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF v_assignment IS DISTINCT FROM p_role_assignment_id OR v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM invitation registration effect is unavailable';
    END IF;
    UPDATE iam_invitations SET accepted_user_id = p_user_id,
        accepted_identifier_id = p_identifier_id,
        accepted_identifier_kind = 'email_v1', state = 'accepted',
        accepted_at = v_now, updated_at = v_now, revision = v_revision + 1
    WHERE id = p_invitation_id;
    UPDATE iam_one_time_tokens SET state = 'consumed', consumed_at = v_now,
        updated_at = v_now, revision = v_token_revision + 1
    WHERE id = p_token_id;
    DELETE FROM iam_invitation_delivery_artifacts
    WHERE invitation_id = p_invitation_id AND token_id = p_token_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation delivery artifact is stale';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value, result_code,
        result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.invitation.accept', p_request_sha256,
        v_clock, 'iam.invitation.accepted', p_invitation_id,
        v_revision + 1, p_request_sha256, v_now
    );
    RETURN QUERY SELECT 'iam.invitation.accepted'::text,
        v_revision + 1, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_register_accept_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_invitation_revision bigint, p_token_id uuid, p_expected_token_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_user_id uuid, p_identifier_id uuid, p_access_mode_id uuid, p_role_assignment_id uuid, p_membership_id uuid, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_password_salt bytea, p_password_tag bytea, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_revoke_v1(name, uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_revoke_v1(p_scope_schema name, p_invitation_id uuid, p_expected_revision bigint, p_actor_user_id uuid, p_expected_authorization_version bigint) RETURNS TABLE(invitation_id uuid, invitation_state text, invitation_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_state text;
    v_revision bigint;
    v_expires_at timestamptz;
    v_invited_by uuid;
    v_actor_state text;
    v_authorization_version bigint;
    v_token_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation revocation scope is invalid';
    END IF;
    IF p_invitation_id IS NULL OR p_expected_revision < 1 OR
       p_actor_user_id IS NULL OR p_expected_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM invitation revocation input is invalid';
    END IF;
    SELECT invitation.state, invitation.revision,
           invitation.expires_at, invitation.invited_by,
           actor.status, actor.authorization_version
    INTO v_state, v_revision, v_expires_at, v_invited_by,
         v_actor_state, v_authorization_version
    FROM iam_invitations AS invitation
    JOIN iam_users AS actor ON actor.id = p_actor_user_id
    WHERE invitation.id OPERATOR(pg_catalog.=) p_invitation_id
    FOR UPDATE OF invitation, actor;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation is unknown';
    END IF;
    IF v_state IS DISTINCT FROM 'pending' OR
       v_revision IS DISTINCT FROM p_expected_revision OR
       v_now >= v_expires_at OR v_actor_state IS DISTINCT FROM 'active' OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation revocation CAS is stale';
    END IF;
    IF v_invited_by IS DISTINCT FROM p_actor_user_id AND
       NOT iam_invitation_manager_v1(p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation revocation authority is denied';
    END IF;
    UPDATE iam_one_time_tokens AS token
    SET state = 'revoked', revoked_at = v_now, updated_at = v_now,
        revision = revision + 1
    WHERE token.invitation_id = p_invitation_id
      AND token.purpose = 'invitation_accept_v1' AND token.state = 'pending';
    GET DIAGNOSTICS v_token_count = ROW_COUNT;
    IF v_token_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation token revocation CAS is stale';
    END IF;
    UPDATE iam_invitations
    SET state = 'revoked', revoked_at = v_now, updated_at = v_now,
        revision = v_revision + 1
    WHERE id = p_invitation_id;
    RETURN QUERY SELECT p_invitation_id, 'revoked'::text, v_revision + 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_revoke_v1(p_scope_schema name, p_invitation_id uuid, p_expected_revision bigint, p_actor_user_id uuid, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_revoke_v2(name, uuid, bytea, uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_revoke_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_revision bigint, p_actor_user_id uuid, p_expected_authorization_version bigint) RETURNS TABLE(invitation_id uuid, invitation_state text, invitation_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_id uuid;
    v_state text;
    v_revision bigint;
    v_command text;
    v_actor uuid;
    v_request bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR p_invitation_id IS NULL OR
       p_actor_user_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation revocation scope is invalid';
    END IF;
    SELECT command_key, actor_id, request_sha256, result_id,
           result_state, result_revision
    INTO v_command, v_actor, v_request, v_id, v_state, v_revision
    FROM iam_invitation_operation_receipts WHERE operation_id = p_operation_id;
    IF FOUND THEN
        IF v_command IS DISTINCT FROM 'iam.invitation.revoke' OR
           v_actor IS DISTINCT FROM p_actor_user_id OR
           v_request IS DISTINCT FROM p_request_sha256 OR
           v_id IS DISTINCT FROM p_invitation_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM invitation operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_id, v_state, v_revision, true;
        RETURN;
    END IF;
    SELECT result.invitation_id, result.invitation_state,
           result.invitation_revision
    INTO v_id, v_state, v_revision
    FROM iam_invitation_revoke_v1(
        p_scope_schema, p_invitation_id, p_expected_revision,
        p_actor_user_id, p_expected_authorization_version
    ) AS result;
    DELETE FROM iam_invitation_delivery_artifacts
    WHERE invitation_id = p_invitation_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM invitation delivery artifact is stale';
    END IF;
    INSERT INTO iam_invitation_operation_receipts (
        operation_id, command_key, actor_id, request_sha256, result_id,
        result_state, result_revision, created_at
    ) VALUES (
        p_operation_id, 'iam.invitation.revoke', p_actor_user_id,
        p_request_sha256, v_id, v_state, v_revision,
        pg_catalog.transaction_timestamp()
    );
    RETURN QUERY SELECT v_id, v_state, v_revision, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_revoke_v2(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_invitation_id uuid, p_expected_revision bigint, p_actor_user_id uuid, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_invitation_role_lookup_v1(name, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_invitation_role_lookup_v1(p_scope_schema name, p_actor_user_id uuid, p_role_name text) RETURNS TABLE(role_id uuid, role_name text, role_scope_kind text, role_scope_id uuid, organization_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_actor_user_id IS NULL OR
       pg_catalog.char_length(p_role_name) NOT BETWEEN 1 AND 255 OR
       NOT EXISTS (
           SELECT 1 FROM iam_users AS actor
           WHERE actor.id = p_actor_user_id AND actor.status = 'active'
       ) OR NOT iam_invitation_manager_v1(p_actor_user_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM invitation role lookup is denied';
    END IF;
    RETURN QUERY
    SELECT role.id, role.name, role.scope_kind, role.scope_id,
           role.organization_id
    FROM iam_roles AS role
    WHERE role.name_key = pg_catalog.convert_to(p_role_name, 'UTF8')
      AND role.status = 'active' AND NOT role.is_protected;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM invitation role is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_invitation_role_lookup_v1(p_scope_schema name, p_actor_user_id uuid, p_role_name text) OWNER TO harpy_owner;

--
-- Name: iam_lifecycle_credential_lookup_v1(name, text, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_lifecycle_credential_lookup_v1(p_scope_schema name, p_purpose text, p_selector bytea, p_binding_sha256 bytea) RETURNS TABLE(token_id uuid, token_purpose text, user_id uuid, identifier_id uuid, identifier_kind text, identifier_revision bigint, portal_binding_id uuid, portal_setup_revision bigint, selector bytea, hash_key_id text, secret_hmac bytea, binding_sha256 bytea, token_revision bigint, token_state text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_purpose NOT IN (
           'email_verification_v1', 'password_reset_v1', 'portal_setup_v1'
       ) OR pg_catalog.octet_length(p_selector) <> 16 OR
       pg_catalog.octet_length(p_binding_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM lifecycle credential lookup is denied';
    END IF;
    RETURN QUERY
    SELECT token.id, token.purpose, token.user_id, token.identifier_id,
           token.identifier_kind, token.identifier_revision,
           token.portal_binding_id, token.portal_setup_revision,
           token.selector, token.hash_key_id, token.secret_hmac,
           token.binding_sha256, token.revision, token.state,
           token.expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.purpose = p_purpose
      AND token.selector = p_selector
      AND token.binding_sha256 = p_binding_sha256
      AND token.state IN ('pending', 'consumed');
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM lifecycle credential is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_lifecycle_credential_lookup_v1(p_scope_schema name, p_purpose text, p_selector bytea, p_binding_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_lifecycle_credential_lookup_v2(name, text, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_lifecycle_credential_lookup_v2(p_scope_schema name, p_purpose text, p_selector bytea, p_binding_sha256 bytea) RETURNS TABLE(token_id uuid, token_purpose text, user_id uuid, identifier_id uuid, identifier_kind text, identifier_revision bigint, portal_binding_id uuid, portal_setup_revision bigint, selector bytea, hash_key_id text, secret_hmac bytea, binding_sha256 bytea, token_revision bigint, token_state text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_purpose NOT IN (
           'email_verification_v1','password_reset_v1','portal_setup_v1',
           'initial_admin_setup.v1'
       ) OR pg_catalog.octet_length(p_selector) <> 16 OR
       pg_catalog.octet_length(p_binding_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM lifecycle credential lookup is denied';
    END IF;
    RETURN QUERY
    SELECT token.id,token.purpose,token.user_id,token.identifier_id,
           token.identifier_kind,token.identifier_revision,
           token.portal_binding_id,token.portal_setup_revision,
           token.selector,token.hash_key_id,token.secret_hmac,
           token.binding_sha256,token.revision,token.state,token.expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.purpose=p_purpose AND token.selector=p_selector
      AND token.binding_sha256=p_binding_sha256
      AND token.state IN ('pending','consumed');
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='IAM lifecycle credential is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_lifecycle_credential_lookup_v2(p_scope_schema name, p_purpose text, p_selector bytea, p_binding_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_lifecycle_delivery_artifact_insert_v1(name, uuid, uuid, text, uuid, uuid, uuid, uuid, text, text, bytea, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_lifecycle_delivery_artifact_insert_v1(p_scope_schema name, p_tenant_id uuid, p_artifact_id uuid, p_purpose text, p_subject_user_id uuid, p_resource_id uuid, p_recipient_identifier_id uuid, p_token_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_user_id uuid;
    v_identifier_id uuid;
    v_portal_binding_id uuid;
    v_state text;
    v_expires_at timestamptz;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_artifact_id IS NULL OR p_subject_user_id IS NULL OR
       p_resource_id IS NULL OR p_recipient_identifier_id IS NULL OR
       p_token_id IS NULL OR
       p_purpose NOT IN (
           'email_verification_v1', 'password_reset_v1', 'portal_setup_v1'
       ) OR p_artifact_ref IS DISTINCT FROM
           'iam-lifecycle-delivery://tenant/' || p_tenant_id::text ||
           '/artifact/' || p_artifact_id::text OR
       pg_catalog.char_length(p_kms_key_id) > 512 OR p_kms_key_id !~
           '^gcp-kms://projects/([a-z][a-z0-9-]{4,28}[a-z0-9]|[0-9]{6,30})/locations/[a-z0-9][a-z0-9-]{0,62}/keyRings/[A-Za-z0-9_-]{1,63}/cryptoKeys/[A-Za-z0-9_-]{1,63}/cryptoKeyVersions/[1-9][0-9]{0,18}$' OR
       pg_catalog.octet_length(p_nonce) <> 12 OR
       pg_catalog.octet_length(p_ciphertext) <> 66 OR
       pg_catalog.octet_length(p_authentication_tag) <> 16 OR
       pg_catalog.octet_length(p_aad_sha256) <> 32 OR
       pg_catalog.octet_length(p_ciphertext_sha256) <> 32 OR
       NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id = p_tenant_id
             AND tenant.schema_name = p_scope_schema::text
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM lifecycle delivery artifact input is invalid';
    END IF;
    SELECT token.user_id, token.identifier_id, token.portal_binding_id,
           token.state, token.expires_at
    INTO v_user_id, v_identifier_id, v_portal_binding_id,
         v_state, v_expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.id = p_token_id AND token.purpose = p_purpose
    FOR UPDATE;
    IF NOT FOUND OR v_state <> 'pending' OR v_expires_at <= v_now OR
       v_user_id IS DISTINCT FROM p_subject_user_id THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM lifecycle delivery token changed';
    END IF;
    IF p_purpose = 'email_verification_v1' THEN
        IF p_resource_id IS DISTINCT FROM v_identifier_id OR
           p_recipient_identifier_id IS DISTINCT FROM v_identifier_id OR
           NOT EXISTS (
               SELECT 1 FROM iam_user_identifiers AS recipient
               WHERE recipient.id = p_recipient_identifier_id
                 AND recipient.user_id = v_user_id
                 AND recipient.kind = 'email_v1'
                 AND recipient.state IN ('pending', 'verified')
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '40001';
        END IF;
    ELSIF p_purpose = 'password_reset_v1' THEN
        IF p_resource_id IS DISTINCT FROM v_identifier_id OR
           NOT EXISTS (
               SELECT 1 FROM iam_user_identifiers AS recipient
               WHERE recipient.id = p_recipient_identifier_id
                 AND recipient.user_id = v_user_id
                 AND recipient.kind = 'email_v1'
                 AND recipient.state = 'active'
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '40001';
        END IF;
    ELSIF p_resource_id IS DISTINCT FROM v_portal_binding_id OR
       NOT EXISTS (
           SELECT 1 FROM iam_user_identifiers AS recipient
           WHERE recipient.id = p_recipient_identifier_id
             AND recipient.user_id = v_user_id
             AND recipient.kind = 'email_v1'
             AND recipient.state = 'active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001';
    END IF;
    INSERT INTO iam_lifecycle_delivery_artifacts (
        id, purpose, subject_user_id, resource_id,
        recipient_identifier_id, token_id, artifact_ref, kms_key_id,
        nonce, ciphertext, authentication_tag, aad_sha256,
        ciphertext_sha256, revision, created_at, expires_at
    ) VALUES (
        p_artifact_id, p_purpose, p_subject_user_id, p_resource_id,
        p_recipient_identifier_id, p_token_id, p_artifact_ref, p_kms_key_id,
        p_nonce, p_ciphertext, p_authentication_tag, p_aad_sha256,
        p_ciphertext_sha256, 1, v_now, v_expires_at
    );
    RETURN 1;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_lifecycle_delivery_artifact_insert_v1(p_scope_schema name, p_tenant_id uuid, p_artifact_id uuid, p_purpose text, p_subject_user_id uuid, p_resource_id uuid, p_recipient_identifier_id uuid, p_token_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_lifecycle_delivery_delete_artifact_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_lifecycle_delivery_delete_artifact_v1(p_artifact_id uuid, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_artifact_id uuid;
BEGIN
    DELETE FROM iam_lifecycle_delivery_artifacts AS artifact
    USING iam_lifecycle_delivery_worker_claims AS claim
    WHERE artifact.id = p_artifact_id
      AND artifact.artifact_ref = p_artifact_ref
      AND claim.artifact_id = artifact.id
      AND claim.effect_id = p_effect_id
      AND claim.effect_idempotency_key = p_effect_idempotency_key
      AND claim.state = 'claimed'
    RETURNING artifact.id INTO v_artifact_id;
    IF v_artifact_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM lifecycle delivery artifact deletion conflicts';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_lifecycle_delivery_delete_artifact_v1(p_artifact_id uuid, p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text) OWNER TO harpy_owner;

--
-- Name: iam_lifecycle_delivery_release_claim_v1(text, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_lifecycle_delivery_release_claim_v1(p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_artifact_id uuid;
BEGIN
    DELETE FROM iam_lifecycle_delivery_worker_claims
    WHERE artifact_ref = p_artifact_ref
      AND effect_id = p_effect_id
      AND effect_idempotency_key = p_effect_idempotency_key
      AND state = 'claimed'
    RETURNING artifact_id INTO v_artifact_id;
    IF v_artifact_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM lifecycle delivery claim release conflicts';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_lifecycle_delivery_release_claim_v1(p_artifact_ref text, p_effect_id uuid, p_effect_idempotency_key text) OWNER TO harpy_owner;

--
-- Name: iam_lifecycle_event_sequence_v1(uuid, text, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_lifecycle_event_sequence_v1(p_operation_id uuid, p_command_key text, p_aggregate_kind text, p_aggregate_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_sequence bigint;
    v_kind text;
    v_id uuid;
BEGIN
    SELECT receipt.aggregate_kind, receipt.aggregate_id, receipt.event_sequence
    INTO v_kind, v_id, v_sequence
    FROM iam_lifecycle_event_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_kind IS DISTINCT FROM p_aggregate_kind OR
           v_id IS DISTINCT FROM p_aggregate_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505';
        END IF;
        RETURN v_sequence;
    END IF;
    IF p_operation_id IS NULL OR p_aggregate_id IS NULL OR
       p_aggregate_kind !~ '^[a-z][a-z0-9_.]{1,63}$' OR
       NOT EXISTS (
          SELECT 1 FROM iam_lifecycle_audit AS audit
          WHERE audit.operation_id = p_operation_id
            AND audit.command_key = p_command_key
            AND audit.resource_id = p_aggregate_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501';
    END IF;
    INSERT INTO iam_lifecycle_event_sequences (
        aggregate_kind, aggregate_id, next_sequence
    ) VALUES (
        p_aggregate_kind, p_aggregate_id, 2
    ) ON CONFLICT (aggregate_kind, aggregate_id) DO UPDATE
      SET next_sequence = iam_lifecycle_event_sequences.next_sequence + 1
    RETURNING next_sequence - 1 INTO v_sequence;
    INSERT INTO iam_lifecycle_event_receipts (
        operation_id, aggregate_kind, aggregate_id, event_sequence, created_at
    ) VALUES (
        p_operation_id, p_aggregate_kind, p_aggregate_id,
        v_sequence, pg_catalog.transaction_timestamp()
    );
    RETURN v_sequence;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_lifecycle_event_sequence_v1(p_operation_id uuid, p_command_key text, p_aggregate_kind text, p_aggregate_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_lifecycle_record_v1(uuid, text, bytea, uuid, uuid, bigint, text, uuid, text, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_lifecycle_record_v1(p_operation_id uuid, p_command_key text, p_request_sha256 bytea, p_result_id uuid, p_subject_user_id uuid, p_result_revision bigint, p_source_kind text, p_actor_id uuid, p_resource_kind text, p_bump_token boolean, p_bump_authorization boolean) RETURNS TABLE(token_version bigint, authorization_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_operation_id IS NULL OR p_result_id IS NULL OR
       p_subject_user_id IS NULL OR p_actor_id IS NULL OR
       p_result_revision < 1 OR p_source_kind NOT IN (
           'actor_tenant', 'credential_target'
       ) OR p_resource_kind !~ '^[a-z][a-z0-9_.]{1,63}$' OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM lifecycle record input is invalid';
    END IF;
    UPDATE iam_users AS subject
    SET token_version = subject.token_version + p_bump_token::integer,
        authorization_version = subject.authorization_version +
            p_bump_authorization::integer,
        revision = subject.revision + 1, updated_at = v_now
    WHERE subject.id = p_subject_user_id
      AND subject.status <> 'tombstoned'
    RETURNING subject.token_version, subject.authorization_version
    INTO token_version, authorization_version;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'IAM lifecycle subject is unavailable';
    END IF;
    INSERT INTO iam_lifecycle_operation_receipts (
        operation_id, command_key, request_sha256, result_id,
        subject_user_id, result_revision, token_version,
        authorization_version, created_at
    ) VALUES (
        p_operation_id, p_command_key, p_request_sha256, p_result_id,
        p_subject_user_id, p_result_revision, token_version,
        authorization_version, v_now
    );
    INSERT INTO iam_lifecycle_audit (
        operation_id, command_key, source_kind, actor_id, subject_user_id,
        resource_id, resource_kind, resource_revision, token_version,
        authorization_version, request_sha256, occurred_at
    ) VALUES (
        p_operation_id, p_command_key, p_source_kind, p_actor_id,
        p_subject_user_id, p_result_id, p_resource_kind, p_result_revision,
        token_version, authorization_version, p_request_sha256, v_now
    );
    RETURN NEXT;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_lifecycle_record_v1(p_operation_id uuid, p_command_key text, p_request_sha256 bytea, p_result_id uuid, p_subject_user_id uuid, p_result_revision bigint, p_source_kind text, p_actor_id uuid, p_resource_kind text, p_bump_token boolean, p_bump_authorization boolean) OWNER TO harpy_owner;

--
-- Name: iam_lifecycle_replay_v1(uuid, text, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_lifecycle_replay_v1(p_operation_id uuid, p_command_key text, p_request_sha256 bytea, p_result_id uuid) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_command_key text;
    v_request_sha256 bytea;
    v_result_id uuid;
    v_subject_user_id uuid;
    v_result_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF p_operation_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM lifecycle replay input is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            pg_catalog.current_schema() || ':' || p_operation_id::text, 0
        )
    );
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
        receipt.subject_user_id, receipt.result_revision,
        receipt.token_version, receipt.authorization_version
    INTO v_command_key, v_request_sha256, v_result_id, v_subject_user_id,
        v_result_revision, v_token_version, v_authorization_version
    FROM iam_lifecycle_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF NOT FOUND THEN RETURN; END IF;
    IF v_command_key IS DISTINCT FROM p_command_key OR
       v_request_sha256 IS DISTINCT FROM p_request_sha256 OR
       (p_result_id IS NOT NULL AND
        v_result_id IS DISTINCT FROM p_result_id) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'IAM lifecycle operation identity was reused';
    END IF;
    RETURN QUERY SELECT v_result_id, v_subject_user_id, v_result_revision,
        v_token_version, v_authorization_version, true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_lifecycle_replay_v1(p_operation_id uuid, p_command_key text, p_request_sha256 bytea, p_result_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_login_credential_v1(name, uuid, uuid, text, bigint, bytea, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_login_credential_v1(p_scope_schema name, p_source_user_id uuid, p_source_identifier_id uuid, p_identifier_kind text, p_source_revision bigint, p_source_sha256 bytea, p_access_mode text) RETURNS TABLE(identifier_id uuid, user_id uuid, user_revision bigint, token_version bigint, authorization_version bigint, access_mode_id uuid, access_mode_revision bigint, portal_binding_id uuid, portal_binding_revision bigint, credential_version bigint, credential_revision bigint, algorithm text, salt bytea, tag bytea, memory_kib integer, iterations smallint, parallelism smallint, legacy_bcrypt_hash text, credential_created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_rows bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM login credential scope is invalid';
    END IF;
    IF p_source_user_id IS NULL OR p_source_identifier_id IS NULL OR
       p_source_revision OPERATOR(pg_catalog.<=) 0 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       NOT (
           (p_identifier_kind IS NOT DISTINCT FROM 'email_v1' AND
            p_access_mode IS NOT DISTINCT FROM 'operator_console') OR
           (p_identifier_kind IS NOT DISTINCT FROM 'portal_v1' AND
            p_access_mode IS NOT DISTINCT FROM 'portal')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM login credential evidence is invalid';
    END IF;
    RETURN QUERY
    SELECT identifier.id, principal.id, principal.revision,
           principal.token_version, principal.authorization_version,
           access.id, access.revision, binding.id, binding.revision,
           credential.credential_version, credential.revision,
           credential.algorithm, credential.salt, credential.tag,
           credential.memory_kib, credential.iterations,
           credential.parallelism, credential.legacy_bcrypt_hash,
           credential.created_at
    FROM iam_user_identifiers AS identifier
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) identifier.user_id
    JOIN iam_user_access_modes AS access
      ON access.user_id OPERATOR(pg_catalog.=) principal.id
     AND access.mode OPERATOR(pg_catalog.=) p_access_mode
    JOIN iam_password_credentials AS credential
      ON credential.user_id OPERATOR(pg_catalog.=) principal.id
    LEFT JOIN iam_portal_subject_bindings AS binding
      ON binding.user_id OPERATOR(pg_catalog.=) principal.id
     AND binding.access_mode_id OPERATOR(pg_catalog.=) access.id
     AND binding.state OPERATOR(pg_catalog.=) 'active'
    WHERE identifier.kind OPERATOR(pg_catalog.=) p_identifier_kind
      AND identifier.id OPERATOR(pg_catalog.=) p_source_identifier_id
      AND identifier.user_id OPERATOR(pg_catalog.=) p_source_user_id
      AND principal.id OPERATOR(pg_catalog.=) p_source_user_id
      AND identifier.revision OPERATOR(pg_catalog.=) p_source_revision
      AND identifier.normalized_sha256 OPERATOR(pg_catalog.=) p_source_sha256
      AND identifier.state OPERATOR(pg_catalog.=) 'active'
      AND principal.status OPERATOR(pg_catalog.=) 'active'
      AND principal.identity_kind OPERATOR(pg_catalog.=) 'human'
      AND access.state OPERATOR(pg_catalog.=) 'active'
      AND credential.state OPERATOR(pg_catalog.=) 'active'
      AND (
          (p_access_mode OPERATOR(pg_catalog.=) 'operator_console' AND
           binding.id IS NULL) OR
          (p_access_mode OPERATOR(pg_catalog.=) 'portal' AND
           binding.id IS NOT NULL)
      );
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows OPERATOR(pg_catalog.>) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '21000',
            MESSAGE = 'IAM login credential evidence is ambiguous';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_login_credential_v1(p_scope_schema name, p_source_user_id uuid, p_source_identifier_id uuid, p_identifier_kind text, p_source_revision bigint, p_source_sha256 bytea, p_access_mode text) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_bcrypt_retire_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_bcrypt_retire_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_successor_job_id uuid) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_cutover_at timestamptz;
    v_count bigint;
    v_result bytea;
BEGIN
    v_count := 0;
    IF NOT iam_maintenance_claim_assert_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.credential.bcrypt-retire', p_payload_revision,
        p_payload_reference, p_payload_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM bcrypt retirement claim is invalid';
    END IF;
    SELECT cutover.changed_at INTO v_cutover_at
    FROM platform.domain_cutovers AS cutover
    WHERE cutover.scope_kind = 'tenant' AND cutover.scope_id = p_tenant_id
      AND cutover.domain = 'iam' AND cutover.state = 'v2'
      AND cutover.writer = 'v2'
    FOR SHARE;
    IF v_cutover_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM bcrypt retirement cutover is unavailable';
    END IF;
    IF v_now >= v_cutover_at + INTERVAL '180 days' THEN
        UPDATE iam_password_credentials AS credential
        SET state = 'reset_required', algorithm = 'legacy_bcrypt_retired_v1',
            legacy_bcrypt_hash = NULL, legacy_retired_by_job_id = p_job_id,
            revision = revision + 1, updated_at = v_now
        WHERE credential.algorithm = 'bcrypt_v1_adopted';
        GET DIAGNOSTICS v_count = ROW_COUNT;
        UPDATE iam_refresh_tokens AS token
        SET state = 'revoked', revoked_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE token.state = 'active' AND EXISTS (
            SELECT 1 FROM iam_refresh_families AS family
            JOIN iam_password_credentials AS credential
              ON credential.user_id = family.user_id
            WHERE family.id = token.family_id
              AND credential.legacy_retired_by_job_id = p_job_id
        );
        UPDATE iam_refresh_families AS family
        SET state = 'revoked', revoke_reason = 'bcrypt_retired',
            revoked_at = v_now, revision = revision + 1, updated_at = v_now
        WHERE family.state = 'active' AND EXISTS (
            SELECT 1 FROM iam_password_credentials AS credential
            WHERE credential.user_id = family.user_id
              AND credential.legacy_retired_by_job_id = p_job_id
        );
        UPDATE iam_sessions AS session
        SET state = 'revoked', revoked_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE session.state = 'active' AND EXISTS (
            SELECT 1 FROM iam_password_credentials AS credential
            WHERE credential.user_id = session.user_id
              AND credential.legacy_retired_by_job_id = p_job_id
        );
        UPDATE iam_users AS user_record
        SET token_version = token_version + 1, revision = revision + 1,
            updated_at = v_now
        WHERE EXISTS (
            SELECT 1 FROM iam_password_credentials AS credential
            WHERE credential.user_id = user_record.id
              AND credential.legacy_retired_by_job_id = p_job_id
        );
    END IF;
    v_result := pg_catalog.sha256(pg_catalog.convert_to(
        'iam.credential.bcrypt-retire:' || v_count::text, 'UTF8'
    ));
    RETURN QUERY SELECT * FROM iam_maintenance_complete_recurring_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.credential.bcrypt-retire', p_payload_revision,
        p_payload_reference, p_payload_sha256, v_count, v_count, 0,
        v_result, p_successor_job_id
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_bcrypt_retire_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_successor_job_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_bootstrap_v1(name, uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_bootstrap_v1(p_scope_schema name, p_tenant_id uuid, p_kind text, p_job_id uuid, p_run_at timestamp with time zone) RETURNS TABLE(payload_reference text, payload_sha256 bytea, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_reference text;
    v_digest bytea;
    v_cadence integer;
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_created boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_job_id IS NULL OR
       pg_catalog.substring(p_job_id::text, 15, 1) <> '7' OR
       p_run_at IS NULL OR p_kind NOT IN (
           'iam.directory.repair', 'iam.directory.checksum',
           'iam.credential.bcrypt-retire', 'iam.identifier.retire',
           'iam.directory.tombstone-purge', 'iam.security-artifact-purge'
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.domain_cutovers AS cutover
           WHERE cutover.scope_kind = 'tenant' AND cutover.scope_id = p_tenant_id
             AND cutover.domain = 'iam' AND cutover.state = 'v2'
             AND cutover.writer = 'v2'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM maintenance bootstrap authority is invalid';
    END IF;
    v_cadence := CASE p_kind
        WHEN 'iam.directory.repair' THEN 900
        WHEN 'iam.security-artifact-purge' THEN 3600
        ELSE 86400
    END;
    v_reference := 'urn:harpy:iam:maintenance:' || p_tenant_id::text ||
        ':' || p_kind || ':v1';
    v_digest := pg_catalog.sha256(pg_catalog.convert_to(v_reference, 'UTF8'));
    INSERT INTO iam_maintenance_schedules (
        kind, payload_revision, payload_reference, payload_sha256,
        current_job_id, scheduled_run_at, cadence_seconds, revision,
        created_at, updated_at
    ) VALUES (
        p_kind, 1, v_reference, v_digest, p_job_id, p_run_at, v_cadence,
        1, v_now, v_now
    ) ON CONFLICT (kind) DO NOTHING;
    v_created := FOUND;
    IF NOT v_created AND NOT EXISTS (
        SELECT 1 FROM iam_maintenance_schedules AS schedule
        WHERE schedule.kind = p_kind AND schedule.payload_revision = 1
          AND schedule.payload_reference = v_reference
          AND schedule.payload_sha256 = v_digest
          AND schedule.current_job_id = p_job_id
          AND schedule.scheduled_run_at = p_run_at
          AND schedule.cadence_seconds = v_cadence
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'IAM maintenance schedule identity conflicts';
    END IF;
    INSERT INTO iam_maintenance_checkpoints (
        kind, cursor_id, scanned_count, affected_count, error_count,
        result_sha256, last_job_id, revision, updated_at
    ) VALUES (
        p_kind, NULL, 0, 0, 0, pg_catalog.sha256(''::bytea),
        NULL, 1, v_now
    ) ON CONFLICT (kind) DO NOTHING;
    RETURN QUERY SELECT v_reference, v_digest, v_created;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_bootstrap_v1(p_scope_schema name, p_tenant_id uuid, p_kind text, p_job_id uuid, p_run_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_claim_assert_v1(name, uuid, uuid, uuid, text, integer, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_claim_assert_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_kind text, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_job_id IS NULL OR p_attempt_id IS NULL OR
       p_payload_revision IS DISTINCT FROM 1 OR
       pg_catalog.octet_length(p_payload_reference) NOT BETWEEN 1 AND 1024 OR
       pg_catalog.octet_length(p_payload_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.sha256(pg_catalog.convert_to(p_payload_reference, 'UTF8'))
           IS DISTINCT FROM p_payload_sha256 OR NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.domain_cutovers AS cutover
           WHERE cutover.scope_kind = 'tenant' AND cutover.scope_id = p_tenant_id
             AND cutover.domain = 'iam' AND cutover.state = 'v2'
             AND cutover.writer = 'v2'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM maintenance claim authority is invalid';
    END IF;
    IF p_kind = 'iam.profile.backfill' THEN
        IF NOT EXISTS (
            SELECT 1 FROM iam_profile_backfill_pages AS page
            WHERE page.job_id = p_job_id AND page.payload_reference = p_payload_reference
              AND page.payload_sha256 = p_payload_sha256 AND page.state = 'queued'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM profile backfill claim is stale';
        END IF;
    ELSIF NOT EXISTS (
        SELECT 1 FROM iam_maintenance_schedules AS schedule
        WHERE schedule.kind = p_kind AND schedule.payload_revision = p_payload_revision
          AND schedule.payload_reference = p_payload_reference
          AND schedule.payload_sha256 = p_payload_sha256
          AND schedule.current_job_id = p_job_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM recurring maintenance claim is stale';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_claim_assert_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_kind text, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_complete_recurring_v1(name, uuid, uuid, uuid, text, integer, text, bytea, bigint, bigint, bigint, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_complete_recurring_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_kind text, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_scanned_count bigint, p_affected_count bigint, p_error_count bigint, p_result_sha256 bytea, p_successor_job_id uuid) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_scheduled_run_at timestamptz;
    v_cadence_seconds integer;
    v_next_run timestamptz;
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_outcome text;
BEGIN
    v_outcome := p_kind || '.completed';
    IF p_scanned_count < 0 OR p_affected_count < 0 OR p_error_count < 0 OR
       p_affected_count > p_scanned_count OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       p_successor_job_id IS NULL OR
       pg_catalog.substring(p_successor_job_id::text, 15, 1) <> '7' OR
       p_kind = 'iam.profile.backfill' OR NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id, p_kind,
           p_payload_revision, p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM recurring maintenance completion is invalid';
    END IF;
    SELECT schedule.scheduled_run_at, schedule.cadence_seconds
    INTO v_scheduled_run_at, v_cadence_seconds
    FROM iam_maintenance_schedules AS schedule
    WHERE schedule.kind = p_kind AND schedule.current_job_id = p_job_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM maintenance schedule claim changed';
    END IF;
    v_next_run := v_scheduled_run_at +
        v_cadence_seconds * INTERVAL '1 second';
    UPDATE iam_maintenance_schedules
    SET current_job_id = p_successor_job_id, scheduled_run_at = v_next_run,
        revision = revision + 1, updated_at = v_now
    WHERE kind = p_kind AND current_job_id = p_job_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM maintenance schedule advance lost';
    END IF;
    INSERT INTO iam_maintenance_receipts (
        job_id, attempt_id, kind, payload_revision, payload_reference,
        payload_sha256, outcome_code, scanned_count, affected_count,
        error_count, result_sha256, successor_job_id, successor_run_at,
        successor_payload_reference, successor_payload_sha256,
        successor_dedupe_key, successor_priority, created_at
    ) VALUES (
        p_job_id, p_attempt_id, p_kind, p_payload_revision,
        p_payload_reference, p_payload_sha256, v_outcome, p_scanned_count,
        p_affected_count, p_error_count, p_result_sha256,
        p_successor_job_id, v_next_run, p_payload_reference, p_payload_sha256,
        p_kind || ':' || p_successor_job_id::text,
        0, v_now
    );
    INSERT INTO iam_maintenance_audit (
        job_id, attempt_id, kind, outcome_code, affected_count,
        error_count, result_sha256, occurred_at
    ) VALUES (
        p_job_id, p_attempt_id, p_kind, v_outcome, p_affected_count,
        p_error_count, p_result_sha256, v_now
    );
    INSERT INTO iam_maintenance_metrics (
        kind, completed_runs, affected_total, error_total, last_job_id,
        last_result_sha256, last_completed_at, revision
    ) VALUES (
        p_kind, 1, p_affected_count, p_error_count, p_job_id,
        p_result_sha256, v_now, 1
    ) ON CONFLICT (kind) DO UPDATE SET
        completed_runs = iam_maintenance_metrics.completed_runs + 1,
        affected_total = iam_maintenance_metrics.affected_total +
            EXCLUDED.affected_total,
        error_total = iam_maintenance_metrics.error_total + EXCLUDED.error_total,
        last_job_id = EXCLUDED.last_job_id,
        last_result_sha256 = EXCLUDED.last_result_sha256,
        last_completed_at = EXCLUDED.last_completed_at,
        revision = iam_maintenance_metrics.revision + 1;
    RETURN QUERY SELECT
        p_successor_job_id, v_next_run, p_payload_reference, p_payload_sha256,
        p_kind || ':' || p_successor_job_id::text,
        0;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_complete_recurring_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_kind text, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_scanned_count bigint, p_affected_count bigint, p_error_count bigint, p_result_sha256 bytea, p_successor_job_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_checksum_finish_v1(name, uuid, uuid, uuid, integer, text, bytea, bigint, bigint, bytea, jsonb, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_directory_checksum_finish_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_scanned_count bigint, p_drift_count bigint, p_result_sha256 bytea, p_key_evidence jsonb, p_successor_job_id uuid) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_entry jsonb;
    v_key_count bigint;
BEGIN
    IF p_key_evidence IS NULL OR
       pg_catalog.jsonb_typeof(p_key_evidence) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM directory checksum key evidence is invalid';
    END IF;
    IF p_scanned_count < 0 OR p_drift_count < 0 OR
       p_drift_count > p_scanned_count OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.jsonb_array_length(p_key_evidence) NOT BETWEEN 1 AND 65 OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.directory.checksum', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM directory checksum completion is invalid';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_key_evidence) AS item(value)
        WHERE pg_catalog.jsonb_typeof(item.value) <> 'object'
           OR item.value <> pg_catalog.jsonb_build_object(
                'key_id', item.value ->> 'key_id',
                'count', item.value -> 'count'
              )
           OR NOT (
                (pg_catalog.octet_length(item.value ->> 'key_id')
                    BETWEEN 1 AND 128 AND
                 item.value ->> 'key_id' ~ '^[a-z0-9][a-z0-9._-]{0,127}$') OR
                iam_hmac_key_id_valid_v1(item.value ->> 'key_id')
              )
           OR pg_catalog.jsonb_typeof(item.value -> 'count')
                IS DISTINCT FROM 'number'
           OR item.value ->> 'count' !~ '^(0|[1-9][0-9]*)$'
           OR (item.value ->> 'count')::numeric > 9223372036854775807
    ) OR (
        SELECT pg_catalog.count(DISTINCT item.value ->> 'key_id')
        FROM pg_catalog.jsonb_array_elements(p_key_evidence) AS item(value)
    ) <> pg_catalog.jsonb_array_length(p_key_evidence) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM directory checksum key evidence is invalid';
    END IF;
    FOR v_entry IN
        SELECT item.value
        FROM pg_catalog.jsonb_array_elements(p_key_evidence) AS item(value)
        ORDER BY item.value ->> 'key_id'
    LOOP
        v_key_count := (v_entry ->> 'count')::bigint;
        INSERT INTO iam_directory_key_evidence (
            lookup_key_id, last_job_id, projected_row_count, zero_rows_since,
            last_result_sha256, revision, updated_at
        ) VALUES (
            v_entry ->> 'key_id', p_job_id, v_key_count,
            CASE WHEN v_key_count = 0 THEN v_now ELSE NULL END,
            p_result_sha256, 1, v_now
        ) ON CONFLICT (lookup_key_id) DO UPDATE SET
            last_job_id = EXCLUDED.last_job_id,
            projected_row_count = EXCLUDED.projected_row_count,
            zero_rows_since = CASE
                WHEN EXCLUDED.projected_row_count > 0 THEN NULL
                ELSE COALESCE(iam_directory_key_evidence.zero_rows_since, v_now)
            END,
            last_result_sha256 = EXCLUDED.last_result_sha256,
            revision = iam_directory_key_evidence.revision + 1,
            updated_at = v_now;
    END LOOP;
    UPDATE iam_maintenance_checkpoints
    SET cursor_id = NULL, scanned_count = p_scanned_count,
        affected_count = p_drift_count, error_count = 0,
        result_sha256 = p_result_sha256, last_job_id = p_job_id,
        revision = revision + 1, updated_at = v_now
    WHERE kind = 'iam.directory.checksum';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM directory checksum checkpoint is missing';
    END IF;
    RETURN QUERY SELECT * FROM iam_maintenance_complete_recurring_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.directory.checksum', p_payload_revision,
        p_payload_reference, p_payload_sha256,
        p_scanned_count, p_drift_count, 0, p_result_sha256,
        p_successor_job_id
    );
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_directory_checksum_finish_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_scanned_count bigint, p_drift_count bigint, p_result_sha256 bytea, p_key_evidence jsonb, p_successor_job_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_checksum_sources_v1(name, uuid, uuid, uuid, integer, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_directory_checksum_sources_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea) RETURNS TABLE(identifier_id uuid, user_id uuid, identifier_kind text, normalized_value text, normalized_sha256 bytea, identifier_state text, source_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.directory.checksum', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM directory checksum source authority is invalid';
    END IF;
    IF (SELECT pg_catalog.count(*) FROM iam_user_identifiers) > 10000 THEN
        RAISE EXCEPTION USING ERRCODE = '54000',
            MESSAGE = 'IAM directory checksum source bound exceeded';
    END IF;
    RETURN QUERY
    SELECT identifier.id, identifier.user_id, identifier.kind,
           identifier.normalized_value, identifier.normalized_sha256,
           identifier.state, identifier.revision
    FROM iam_user_identifiers AS identifier
    ORDER BY identifier.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_directory_checksum_sources_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_repair_apply_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid, uuid, text, text, bigint, bytea, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_directory_repair_apply_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_identifier_id uuid, p_user_id uuid, p_kind text, p_state text, p_source_revision bigint, p_source_sha256 bytea, p_key_evidence jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT iam_maintenance_claim_assert_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.directory.repair', p_payload_revision,
        p_payload_reference, p_payload_sha256
    ) OR p_identifier_id IS NULL OR p_user_id IS NULL OR
       p_kind NOT IN ('email_v1', 'portal_v1') OR
       p_state NOT IN ('pending', 'verified', 'active', 'tombstoned', 'retired') OR
       p_source_revision < 1 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (
           SELECT 1 FROM iam_user_identifiers AS identifier
           WHERE identifier.id = p_identifier_id AND identifier.user_id = p_user_id
             AND identifier.kind = p_kind AND identifier.state = p_state
             AND identifier.revision = p_source_revision
             AND identifier.normalized_sha256 = p_source_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM directory repair source is invalid';
    END IF;
    RETURN p_source_revision;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_directory_repair_apply_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_identifier_id uuid, p_user_id uuid, p_kind text, p_state text, p_source_revision bigint, p_source_sha256 bytea, p_key_evidence jsonb) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_repair_finish_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid, bigint, bigint, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_directory_repair_finish_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_cursor_id uuid, p_scanned_count bigint, p_affected_count bigint, p_result_sha256 bytea, p_successor_job_id uuid) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_scanned_count < 0 OR p_affected_count < 0 OR
       p_affected_count > p_scanned_count OR
       (p_scanned_count > 0 AND p_cursor_id IS NULL) OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.directory.repair', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM directory repair completion is invalid';
    END IF;
    UPDATE iam_maintenance_checkpoints
    SET cursor_id = p_cursor_id, scanned_count = p_scanned_count,
        affected_count = p_affected_count, error_count = 0,
        result_sha256 = p_result_sha256, last_job_id = p_job_id,
        revision = revision + 1, updated_at = v_now
    WHERE kind = 'iam.directory.repair';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM directory repair checkpoint is missing';
    END IF;
    RETURN QUERY SELECT * FROM iam_maintenance_complete_recurring_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.directory.repair', p_payload_revision,
        p_payload_reference, p_payload_sha256,
        p_scanned_count, p_affected_count, 0, p_result_sha256,
        p_successor_job_id
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_directory_repair_finish_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_cursor_id uuid, p_scanned_count bigint, p_affected_count bigint, p_result_sha256 bytea, p_successor_job_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_repair_page_v1(name, uuid, uuid, uuid, integer, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_directory_repair_page_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea) RETURNS TABLE(identifier_id uuid, user_id uuid, identifier_kind text, normalized_value text, normalized_sha256 bytea, identifier_state text, source_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.directory.repair', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM directory repair page authority is invalid';
    END IF;
    RETURN QUERY
    SELECT identifier.id, identifier.user_id, identifier.kind,
           identifier.normalized_value, identifier.normalized_sha256,
           identifier.state, identifier.revision
    FROM iam_user_identifiers AS identifier
    CROSS JOIN iam_maintenance_checkpoints AS checkpoint
    WHERE checkpoint.kind = 'iam.directory.repair'
      AND (checkpoint.cursor_id IS NULL OR identifier.id > checkpoint.cursor_id)
    ORDER BY identifier.id
    LIMIT 250;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_directory_repair_page_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_directory_tombstone_purge_v1(name, uuid, uuid, uuid, integer, text, bytea, bigint, bigint, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_directory_tombstone_purge_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_scanned_count bigint, p_purged_count bigint, p_successor_job_id uuid) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_result bytea;
BEGIN
    IF p_scanned_count < 0 OR p_purged_count < 0 OR
       p_purged_count > p_scanned_count OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.directory.tombstone-purge', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM directory tombstone purge completion is invalid';
    END IF;
    v_result := pg_catalog.sha256(pg_catalog.convert_to(
        'iam.directory.tombstone-purge:' || p_scanned_count::text || ':' ||
        p_purged_count::text, 'UTF8'
    ));
    UPDATE iam_maintenance_checkpoints
    SET cursor_id = NULL, scanned_count = p_scanned_count,
        affected_count = p_purged_count, error_count = 0,
        result_sha256 = v_result, last_job_id = p_job_id,
        revision = revision + 1,
        updated_at = pg_catalog.transaction_timestamp()
    WHERE kind = 'iam.directory.tombstone-purge';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM directory purge checkpoint is missing';
    END IF;
    RETURN QUERY SELECT * FROM iam_maintenance_complete_recurring_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.directory.tombstone-purge', p_payload_revision,
        p_payload_reference, p_payload_sha256,
        p_scanned_count, p_purged_count, 0, v_result, p_successor_job_id
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_directory_tombstone_purge_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_scanned_count bigint, p_purged_count bigint, p_successor_job_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_identifier_retire_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_identifier_retire_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_successor_job_id uuid) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_count bigint;
    v_result bytea;
BEGIN
    IF NOT iam_maintenance_claim_assert_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.identifier.retire', p_payload_revision,
        p_payload_reference, p_payload_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM identifier retirement claim is invalid';
    END IF;
    UPDATE iam_user_identifiers AS identifier
    SET state = 'retired', retired_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE identifier.state = 'tombstoned'
      AND identifier.cooldown_until <= v_now;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_result := pg_catalog.sha256(pg_catalog.convert_to(
        'iam.identifier.retire:' || v_count::text, 'UTF8'
    ));
    UPDATE iam_maintenance_checkpoints
    SET cursor_id = NULL, scanned_count = v_count, affected_count = v_count,
        error_count = 0, result_sha256 = v_result, last_job_id = p_job_id,
        revision = revision + 1, updated_at = v_now
    WHERE kind = 'iam.identifier.retire';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM identifier retirement checkpoint is missing';
    END IF;
    RETURN QUERY SELECT * FROM iam_maintenance_complete_recurring_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.identifier.retire', p_payload_revision,
        p_payload_reference, p_payload_sha256, v_count, v_count, 0,
        v_result, p_successor_job_id
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_identifier_retire_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_successor_job_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_profile_backfill_apply_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid, integer, uuid, bigint, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_apply_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_expected_revision bigint, p_source_sha256 bytea, p_target_document bytea, p_target_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_plan_id uuid;
    v_resource_kind text;
    v_source_schema_id uuid;
    v_target_schema_id uuid;
    v_page_job_id uuid;
    v_after_resource_id uuid;
    v_through_resource_id uuid;
    v_values jsonb;
    v_revision bigint;
    v_current_schema uuid;
    v_current_sha bytea;
BEGIN
    IF NOT iam_maintenance_claim_assert_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.profile.backfill', p_payload_revision,
        p_payload_reference, p_payload_sha256
    ) OR p_plan_id IS NULL OR p_page_number < 1 OR p_resource_id IS NULL OR
       p_expected_revision < 1 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_target_document) NOT BETWEEN 2 AND 1048576 OR
       pg_catalog.octet_length(p_target_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.sha256(p_target_document) IS DISTINCT FROM p_target_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill apply input is invalid';
    END IF;
    SELECT plan.id, plan.resource_kind, plan.source_schema_id,
           plan.target_schema_id
    INTO v_plan_id, v_resource_kind, v_source_schema_id, v_target_schema_id
    FROM iam_profile_backfill_plans AS plan
    WHERE plan.id = p_plan_id AND plan.state IN ('planned', 'running')
    FOR UPDATE;
    SELECT page.job_id, page.after_resource_id, page.through_resource_id
    INTO v_page_job_id, v_after_resource_id, v_through_resource_id
    FROM iam_profile_backfill_pages AS page
    WHERE page.plan_id = p_plan_id AND page.page_number = p_page_number
      AND page.job_id = p_job_id AND page.state = 'queued'
    FOR UPDATE;
    IF v_plan_id IS NULL OR v_page_job_id IS NULL OR
       (v_after_resource_id IS NOT NULL AND
        p_resource_id <= v_after_resource_id) OR
       p_resource_id > v_through_resource_id THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile backfill plan or page is stale';
    END IF;
    v_values := pg_catalog.convert_from(p_target_document, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_values) <> 'object' OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_each(v_values) AS entry(key, value)
        WHERE entry.key !~
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR pg_catalog.jsonb_typeof(entry.value) = 'null'
          OR NOT EXISTS (
              SELECT 1 FROM iam_profile_field_revisions AS field
              WHERE field.schema_version_id = v_target_schema_id
                AND field.resource_kind = v_resource_kind
                AND field.field_id = entry.key::uuid
          )
    ) OR EXISTS (
        SELECT 1 FROM iam_profile_field_revisions AS required
        WHERE required.schema_version_id = v_target_schema_id
          AND required.resource_kind = v_resource_kind
          AND required.field_state = 'active' AND required.required
          AND NOT v_values ? required.field_id::text
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile backfill target document is invalid';
    END IF;
    IF v_resource_kind = 'user' THEN
        SELECT profile_schema_version_id, profile_sha256
        INTO v_current_schema, v_current_sha
        FROM iam_users WHERE id = p_resource_id AND revision = p_expected_revision
        FOR UPDATE;
    ELSIF v_resource_kind = 'organization' THEN
        SELECT profile_schema_version_id, profile_sha256
        INTO v_current_schema, v_current_sha
        FROM iam_organizations WHERE id = p_resource_id AND revision = p_expected_revision
        FOR UPDATE;
    ELSE
        SELECT profile_schema_version_id, profile_sha256
        INTO v_current_schema, v_current_sha
        FROM iam_roles WHERE id = p_resource_id AND revision = p_expected_revision
        FOR UPDATE;
    END IF;
    IF v_current_schema IS DISTINCT FROM v_source_schema_id OR
       v_current_sha IS DISTINCT FROM p_source_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile backfill source changed';
    END IF;
    IF v_resource_kind = 'user' THEN
        UPDATE iam_users SET profile_schema_version_id = v_target_schema_id,
            profile_values = v_values, profile_sha256 = p_target_sha256,
            revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
        WHERE id = p_resource_id RETURNING revision INTO v_revision;
    ELSIF v_resource_kind = 'organization' THEN
        UPDATE iam_organizations SET profile_schema_version_id = v_target_schema_id,
            profile_values = v_values, profile_sha256 = p_target_sha256,
            revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
        WHERE id = p_resource_id RETURNING revision INTO v_revision;
    ELSE
        UPDATE iam_roles SET profile_schema_version_id = v_target_schema_id,
            profile_values = v_values, profile_sha256 = p_target_sha256,
            revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
        WHERE id = p_resource_id RETURNING revision INTO v_revision;
    END IF;
    UPDATE iam_profile_backfill_plans SET state = 'running',
        revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
    WHERE id = p_plan_id AND state = 'planned';
    RETURN v_revision;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_apply_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_expected_revision bigint, p_source_sha256 bytea, p_target_document bytea, p_target_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_profile_backfill_apply_v2(name, uuid, uuid, uuid, integer, text, bytea, uuid, integer, uuid, uuid, bigint, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_apply_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_actual_schema_version_id uuid, p_expected_revision bigint, p_source_sha256 bytea, p_target_document bytea, p_target_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_resource_kind text;
    v_source_schema_id uuid;
    v_source_version bigint;
    v_target_schema_id uuid;
    v_after_resource_id uuid;
    v_through_resource_id uuid;
    v_source_values jsonb;
    v_values jsonb;
    v_revision bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.profile.backfill', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) OR p_plan_id IS NULL OR p_page_number < 1 OR p_resource_id IS NULL OR
       p_actual_schema_version_id IS NULL OR p_expected_revision < 1 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_target_document) NOT BETWEEN 2 AND 1048576 OR
       pg_catalog.octet_length(p_target_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.sha256(p_target_document) IS DISTINCT FROM p_target_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile lineage apply input is invalid';
    END IF;
    SELECT plan.resource_kind, plan.source_schema_id, source.version,
           plan.target_schema_id, page.after_resource_id,
           page.through_resource_id
    INTO v_resource_kind, v_source_schema_id, v_source_version,
         v_target_schema_id, v_after_resource_id, v_through_resource_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_backfill_pages AS page ON page.plan_id = plan.id
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.id = p_plan_id AND plan.state IN ('planned', 'running')
      AND page.page_number = p_page_number AND page.job_id = p_job_id
      AND page.state = 'queued'
    FOR UPDATE OF plan, page, source, target;
    IF v_resource_kind IS NULL OR
       (v_after_resource_id IS NOT NULL AND p_resource_id <= v_after_resource_id) OR
       p_resource_id > v_through_resource_id OR NOT EXISTS (
           SELECT 1 FROM iam_profile_schema_versions AS actual
           WHERE actual.id = p_actual_schema_version_id
             AND actual.resource_kind = v_resource_kind
             AND actual.state IN ('active', 'retired')
             AND actual.version <= v_source_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile lineage apply is stale';
    END IF;
    IF v_resource_kind = 'user' THEN
        SELECT usr.profile_values INTO v_source_values
        FROM iam_users AS usr WHERE usr.id = p_resource_id
          AND usr.profile_schema_version_id = p_actual_schema_version_id
          AND usr.revision = p_expected_revision
          AND usr.profile_sha256 = p_source_sha256 FOR UPDATE;
    ELSIF v_resource_kind = 'organization' THEN
        SELECT organization.profile_values INTO v_source_values
        FROM iam_organizations AS organization
        WHERE organization.id = p_resource_id
          AND organization.profile_schema_version_id = p_actual_schema_version_id
          AND organization.revision = p_expected_revision
          AND organization.profile_sha256 = p_source_sha256 FOR UPDATE;
    ELSE
        SELECT role.profile_values INTO v_source_values
        FROM iam_roles AS role WHERE role.id = p_resource_id
          AND role.profile_schema_version_id = p_actual_schema_version_id
          AND role.revision = p_expected_revision
          AND role.profile_sha256 = p_source_sha256 FOR UPDATE;
    END IF;
    IF v_source_values IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile lineage source changed';
    END IF;
    v_values := pg_catalog.convert_from(p_target_document, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_values) <> 'object' OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_each(v_values) AS entry(key, value)
        WHERE entry.key !~
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR pg_catalog.jsonb_typeof(entry.value) = 'null'
          OR NOT EXISTS (
              SELECT 1 FROM iam_profile_field_revisions AS field
              WHERE field.schema_version_id = v_target_schema_id
                AND field.resource_kind = v_resource_kind
                AND field.field_id = entry.key::uuid
                AND (field.field_state = 'active' OR (
                    field.field_state = 'retired'
                    AND v_source_values ? entry.key
                    AND v_source_values -> entry.key = entry.value
                    AND EXISTS (
                        SELECT 1 FROM iam_profile_field_revisions AS source_field
                        WHERE source_field.schema_version_id =
                              p_actual_schema_version_id
                          AND source_field.resource_kind = v_resource_kind
                          AND source_field.field_id = field.field_id
                          AND source_field.semantic_sha256 = field.semantic_sha256
                    )
                ))
          )
    ) OR EXISTS (
        SELECT 1 FROM iam_profile_field_revisions AS required
        WHERE required.schema_version_id = v_target_schema_id
          AND required.resource_kind = v_resource_kind
          AND required.field_state = 'active' AND required.required
          AND NOT v_values ? required.field_id::text
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile lineage target document is invalid';
    END IF;
    IF v_resource_kind = 'user' THEN
        UPDATE iam_users SET profile_schema_version_id = v_target_schema_id,
            profile_values = v_values, profile_sha256 = p_target_sha256,
            revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
        WHERE id = p_resource_id
          AND profile_schema_version_id = p_actual_schema_version_id
          AND revision = p_expected_revision AND profile_sha256 = p_source_sha256
        RETURNING revision INTO v_revision;
    ELSIF v_resource_kind = 'organization' THEN
        UPDATE iam_organizations SET profile_schema_version_id = v_target_schema_id,
            profile_values = v_values, profile_sha256 = p_target_sha256,
            revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
        WHERE id = p_resource_id
          AND profile_schema_version_id = p_actual_schema_version_id
          AND revision = p_expected_revision AND profile_sha256 = p_source_sha256
        RETURNING revision INTO v_revision;
    ELSE
        UPDATE iam_roles SET profile_schema_version_id = v_target_schema_id,
            profile_values = v_values, profile_sha256 = p_target_sha256,
            revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
        WHERE id = p_resource_id
          AND profile_schema_version_id = p_actual_schema_version_id
          AND revision = p_expected_revision AND profile_sha256 = p_source_sha256
        RETURNING revision INTO v_revision;
    END IF;
    IF v_revision IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile lineage source changed';
    END IF;
    UPDATE iam_profile_backfill_plans SET state = 'running',
        revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
    WHERE id = p_plan_id AND state = 'planned';
    RETURN v_revision;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_apply_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_actual_schema_version_id uuid, p_expected_revision bigint, p_source_sha256 bytea, p_target_document bytea, p_target_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_profile_backfill_apply_v3(name, uuid, uuid, uuid, integer, text, bytea, uuid, integer, uuid, uuid, bigint, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_apply_v3(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_actual_schema_version_id uuid, p_expected_revision bigint, p_source_sha256 bytea, p_target_document bytea, p_target_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT iam_profile_worker_capability_mint_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        p_payload_revision, p_payload_reference, p_payload_sha256,
        p_plan_id, p_page_number, p_resource_id,
        p_actual_schema_version_id, p_expected_revision,
        p_source_sha256, p_target_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile worker capability was denied';
    END IF;
    RETURN iam_maintenance_profile_backfill_apply_v2(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        p_payload_revision, p_payload_reference, p_payload_sha256,
        p_plan_id, p_page_number, p_resource_id,
        p_actual_schema_version_id, p_expected_revision,
        p_source_sha256, p_target_document, p_target_sha256
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_apply_v3(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_actual_schema_version_id uuid, p_expected_revision bigint, p_source_sha256 bytea, p_target_document bytea, p_target_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_profile_backfill_error_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid, integer, uuid, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_error_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_error_code text, p_evidence_sha256 bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT iam_maintenance_claim_assert_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.profile.backfill', p_payload_revision,
        p_payload_reference, p_payload_sha256
    ) OR p_plan_id IS NULL OR p_page_number < 1 OR p_resource_id IS NULL OR
       p_error_code NOT IN (
           'converter_missing', 'source_changed', 'document_invalid',
           'target_schema_invalid', 'checksum_mismatch'
       ) OR pg_catalog.octet_length(p_evidence_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (
           SELECT 1 FROM iam_profile_backfill_pages AS page
           WHERE page.plan_id = p_plan_id AND page.page_number = p_page_number
             AND page.job_id = p_job_id AND page.state = 'queued'
             AND (page.after_resource_id IS NULL OR
                  p_resource_id > page.after_resource_id)
             AND p_resource_id <= page.through_resource_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill error evidence is invalid';
    END IF;
    INSERT INTO iam_profile_backfill_errors (
        plan_id, page_number, resource_id, error_code,
        evidence_sha256, created_at
    ) VALUES (
        p_plan_id, p_page_number, p_resource_id, p_error_code,
        p_evidence_sha256, pg_catalog.transaction_timestamp()
    ) ON CONFLICT (plan_id, page_number, resource_id) DO UPDATE SET
        error_code = EXCLUDED.error_code,
        evidence_sha256 = EXCLUDED.evidence_sha256;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_error_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_error_code text, p_evidence_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_profile_backfill_finish_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid, integer, bigint, bigint, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_finish_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_scanned_count bigint, p_converted_count bigint, p_source_sha256 bytea, p_result_sha256 bytea) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_plan_id uuid;
    v_resource_kind text;
    v_source_schema_id uuid;
    v_target_schema_id uuid;
    v_page_count integer;
    v_source_count bigint;
    v_plan_target_sha256 bytea;
    v_page_job_id uuid;
    v_expected_count integer;
    v_page_source_sha256 bytea;
    v_page_target_sha256 bytea;
    v_next_job_id uuid;
    v_next_run_at timestamptz;
    v_next_reference text;
    v_next_sha256 bytea;
    v_checkpoint_plan_id uuid;
    v_completed_pages integer;
    v_converted_total bigint;
    v_error_total bigint;
    v_rolling_sha256 bytea;
    v_row_errors bigint;
    v_errors bigint;
    v_rolling bytea;
    v_terminal boolean := false;
BEGIN
    IF p_scanned_count < 0 OR p_converted_count < 0 OR
       p_converted_count > p_scanned_count OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.profile.backfill', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill completion is invalid';
    END IF;
    SELECT plan.id, plan.resource_kind, plan.source_schema_id,
           plan.target_schema_id, plan.page_count, plan.source_count,
           plan.expected_target_sha256
    INTO v_plan_id, v_resource_kind, v_source_schema_id,
         v_target_schema_id, v_page_count, v_source_count,
         v_plan_target_sha256
    FROM iam_profile_backfill_plans AS plan
    WHERE plan.id = p_plan_id AND plan.state IN ('planned', 'running')
    FOR UPDATE;
    SELECT page.job_id, page.expected_count, page.source_sha256,
           page.expected_target_sha256
    INTO v_page_job_id, v_expected_count, v_page_source_sha256,
         v_page_target_sha256
    FROM iam_profile_backfill_pages AS page
    WHERE page.plan_id = p_plan_id AND page.page_number = p_page_number
      AND page.job_id = p_job_id AND page.state = 'queued'
    FOR UPDATE;
    SELECT checkpoint.plan_id, checkpoint.completed_pages,
           checkpoint.converted_count, checkpoint.error_count,
           checkpoint.rolling_sha256
    INTO v_checkpoint_plan_id, v_completed_pages, v_converted_total,
         v_error_total, v_rolling_sha256
    FROM iam_profile_backfill_checkpoints AS checkpoint
    WHERE checkpoint.plan_id = p_plan_id FOR UPDATE;
    SELECT pg_catalog.count(*) INTO v_row_errors
    FROM iam_profile_backfill_errors AS failure
    WHERE failure.plan_id = p_plan_id AND failure.page_number = p_page_number;
    IF v_plan_id IS NULL OR v_page_job_id IS NULL OR
       v_checkpoint_plan_id IS NULL OR
       v_completed_pages + 1 <> p_page_number OR
       v_expected_count <> p_scanned_count OR
       v_page_source_sha256 IS DISTINCT FROM p_source_sha256 OR
       p_converted_count + v_row_errors <> p_scanned_count THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile backfill page evidence changed';
    END IF;
    v_errors := v_row_errors;
    IF v_errors = 0 AND
       v_page_target_sha256 IS DISTINCT FROM p_result_sha256 THEN
        v_errors := 1;
    END IF;
    v_rolling := pg_catalog.sha256(
        v_rolling_sha256 || p_result_sha256
    );
    UPDATE iam_profile_backfill_pages
    SET state = CASE WHEN v_errors = 0 THEN 'completed' ELSE 'fenced' END,
        converted_count = p_converted_count, error_count = v_row_errors,
        result_sha256 = p_result_sha256, completed_at = v_now
    WHERE plan_id = p_plan_id AND page_number = p_page_number;
    UPDATE iam_profile_backfill_checkpoints
    SET completed_pages = completed_pages + 1,
        converted_count = converted_count + p_converted_count,
        error_count = error_count + v_errors, rolling_sha256 = v_rolling,
        last_page_number = p_page_number, revision = revision + 1,
        updated_at = v_now
    WHERE plan_id = p_plan_id
    RETURNING completed_pages, converted_count, error_count, rolling_sha256
    INTO v_completed_pages, v_converted_total, v_error_total,
         v_rolling_sha256;
    IF v_errors > 0 THEN
        UPDATE iam_profile_backfill_plans
        SET state = 'fenced', fenced_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE id = p_plan_id;
        v_terminal := true;
    ELSE
        SELECT page.job_id, page.scheduled_run_at, page.payload_reference,
               page.payload_sha256
        INTO v_next_job_id, v_next_run_at, v_next_reference, v_next_sha256
        FROM iam_profile_backfill_pages AS page
        WHERE page.plan_id = p_plan_id AND page.page_number = p_page_number + 1
          AND page.state = 'queued';
        IF FOUND THEN
            IF p_page_number >= v_page_count THEN
                RAISE EXCEPTION USING ERRCODE = '23514',
                    MESSAGE = 'IAM profile backfill page count conflicts';
            END IF;
        ELSE
            v_terminal := true;
            IF p_page_number <> v_page_count OR
               v_completed_pages <> v_page_count OR
               v_converted_total <> v_source_count OR
               v_error_total <> 0 OR
               v_rolling_sha256 IS DISTINCT FROM v_plan_target_sha256 THEN
                UPDATE iam_profile_backfill_plans
                SET state = 'fenced', fenced_at = v_now,
                    revision = revision + 1, updated_at = v_now
                WHERE id = p_plan_id;
                v_errors := 1;
                UPDATE iam_profile_backfill_pages SET state = 'fenced'
                WHERE plan_id = p_plan_id AND page_number = p_page_number;
            ELSE
                UPDATE iam_profile_schema_versions SET state = 'retired',
                    retired_at = v_now, updated_at = v_now, revision = revision + 1
                WHERE id = v_source_schema_id
                  AND resource_kind = v_resource_kind AND state = 'active';
                IF NOT FOUND THEN
                    RAISE EXCEPTION USING ERRCODE = '40001',
                        MESSAGE = 'IAM profile source pointer changed';
                END IF;
                UPDATE iam_profile_schema_versions SET state = 'active',
                    activated_at = v_now, updated_at = v_now, revision = revision + 1
                WHERE id = v_target_schema_id
                  AND resource_kind = v_resource_kind AND state = 'draft';
                IF NOT FOUND THEN
                    RAISE EXCEPTION USING ERRCODE = '40001',
                        MESSAGE = 'IAM profile target pointer changed';
                END IF;
                UPDATE iam_profile_backfill_plans SET state = 'activated',
                    activated_at = v_now, revision = revision + 1, updated_at = v_now
                WHERE id = p_plan_id;
            END IF;
        END IF;
    END IF;
    RETURN QUERY SELECT * FROM iam_maintenance_profile_backfill_receipt_v1(
        p_job_id, p_attempt_id, p_payload_revision, p_payload_reference,
        p_payload_sha256, p_scanned_count, p_converted_count, v_errors,
        p_result_sha256, CASE WHEN v_terminal THEN NULL ELSE v_next_job_id END,
        CASE WHEN v_terminal THEN NULL ELSE v_next_run_at END,
        CASE WHEN v_terminal THEN NULL ELSE v_next_reference END,
        CASE WHEN v_terminal THEN NULL ELSE v_next_sha256 END,
        CASE WHEN v_terminal THEN NULL ELSE
            'iam.profile.backfill:' || p_plan_id::text || ':' ||
            (p_page_number + 1)::text END
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_finish_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_scanned_count bigint, p_converted_count bigint, p_source_sha256 bytea, p_result_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_profile_backfill_finish_v2(name, uuid, uuid, uuid, integer, text, bytea, uuid, integer, bigint, bigint, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_finish_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_scanned_count bigint, p_converted_count bigint, p_source_sha256 bytea, p_result_sha256 bytea) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_resource_kind text;
    v_source_schema_id uuid;
    v_target_schema_id uuid;
    v_page_count integer;
    v_source_count bigint;
    v_plan_target_sha256 bytea;
    v_expected_count integer;
    v_page_source_sha256 bytea;
    v_page_target_sha256 bytea;
    v_next_job_id uuid;
    v_next_run_at timestamptz;
    v_next_reference text;
    v_next_sha256 bytea;
    v_completed_pages integer;
    v_converted_total bigint;
    v_error_total bigint;
    v_rolling_sha256 bytea;
    v_row_errors bigint;
    v_errors bigint;
    v_terminal boolean := false;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_scanned_count < 0 OR p_converted_count < 0 OR
       p_converted_count > p_scanned_count OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.profile.backfill', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile lineage completion is invalid';
    END IF;
    SELECT plan.resource_kind, plan.source_schema_id, plan.target_schema_id,
           plan.page_count, plan.source_count, plan.expected_target_sha256,
           page.expected_count, page.source_sha256,
           page.expected_target_sha256
    INTO v_resource_kind, v_source_schema_id, v_target_schema_id,
         v_page_count, v_source_count, v_plan_target_sha256,
         v_expected_count, v_page_source_sha256, v_page_target_sha256
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_backfill_pages AS page ON page.plan_id = plan.id
    WHERE plan.id = p_plan_id AND plan.state IN ('planned','running')
      AND page.page_number = p_page_number AND page.job_id = p_job_id
      AND page.state = 'queued'
    FOR UPDATE OF plan, page;
    SELECT checkpoint.completed_pages, checkpoint.converted_count,
           checkpoint.error_count, checkpoint.rolling_sha256
    INTO v_completed_pages, v_converted_total,
         v_error_total, v_rolling_sha256
    FROM iam_profile_backfill_checkpoints AS checkpoint
    WHERE checkpoint.plan_id = p_plan_id FOR UPDATE;
    SELECT pg_catalog.count(*) INTO v_row_errors
    FROM iam_profile_backfill_errors AS failure
    WHERE failure.plan_id = p_plan_id AND failure.page_number = p_page_number;
    IF v_resource_kind IS NULL OR v_completed_pages IS NULL OR
       v_completed_pages + 1 <> p_page_number OR
       v_expected_count <> p_scanned_count OR
       v_page_source_sha256 IS DISTINCT FROM p_source_sha256 OR
       p_converted_count + v_row_errors <> p_scanned_count THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile lineage page evidence changed';
    END IF;
    v_errors := v_row_errors;
    IF v_errors = 0 AND v_page_target_sha256 IS DISTINCT FROM p_result_sha256 THEN
        v_errors := 1;
    END IF;
    v_rolling_sha256 := pg_catalog.sha256(v_rolling_sha256 || p_result_sha256);
    UPDATE iam_profile_backfill_pages
    SET state = CASE WHEN v_errors = 0 THEN 'completed' ELSE 'fenced' END,
        converted_count = p_converted_count, error_count = v_row_errors,
        result_sha256 = p_result_sha256, completed_at = v_now
    WHERE plan_id = p_plan_id AND page_number = p_page_number;
    UPDATE iam_profile_backfill_checkpoints
    SET completed_pages = completed_pages + 1,
        converted_count = converted_count + p_converted_count,
        error_count = error_count + v_errors,
        rolling_sha256 = v_rolling_sha256, last_page_number = p_page_number,
        revision = revision + 1, updated_at = v_now
    WHERE plan_id = p_plan_id
    RETURNING completed_pages, converted_count, error_count, rolling_sha256
    INTO v_completed_pages, v_converted_total, v_error_total, v_rolling_sha256;
    IF v_errors > 0 THEN
        UPDATE iam_profile_backfill_plans
        SET state = 'fenced', fenced_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE id = p_plan_id;
        v_terminal := true;
    ELSE
        SELECT page.job_id, page.scheduled_run_at, page.payload_reference,
               page.payload_sha256
        INTO v_next_job_id, v_next_run_at, v_next_reference, v_next_sha256
        FROM iam_profile_backfill_pages AS page
        WHERE page.plan_id = p_plan_id AND page.page_number = p_page_number + 1
          AND page.state = 'queued';
        IF FOUND THEN
            IF p_page_number >= v_page_count THEN
                RAISE EXCEPTION USING ERRCODE = '23514',
                    MESSAGE = 'IAM profile lineage page count conflicts';
            END IF;
        ELSE
            v_terminal := true;
            IF p_page_number <> v_page_count OR
               v_completed_pages <> v_page_count OR
               v_converted_total <> v_source_count OR v_error_total <> 0 OR
               v_rolling_sha256 IS DISTINCT FROM v_plan_target_sha256 THEN
                UPDATE iam_profile_backfill_plans
                SET state = 'fenced', fenced_at = v_now,
                    revision = revision + 1, updated_at = v_now
                WHERE id = p_plan_id;
                UPDATE iam_profile_backfill_pages SET state = 'fenced'
                WHERE plan_id = p_plan_id AND page_number = p_page_number;
                v_errors := 1;
            ELSE
                IF NOT iam_profile_backfill_activate_v2(
                    p_plan_id, v_resource_kind, v_source_schema_id,
                    v_target_schema_id, v_source_count, v_now
                ) THEN
                    RAISE EXCEPTION USING ERRCODE = '55000',
                        MESSAGE = 'IAM profile lineage activation failed';
                END IF;
            END IF;
        END IF;
    END IF;
    RETURN QUERY SELECT * FROM iam_maintenance_profile_backfill_receipt_v1(
        p_job_id, p_attempt_id, p_payload_revision, p_payload_reference,
        p_payload_sha256, p_scanned_count, p_converted_count, v_errors,
        p_result_sha256, CASE WHEN v_terminal THEN NULL ELSE v_next_job_id END,
        CASE WHEN v_terminal THEN NULL ELSE v_next_run_at END,
        CASE WHEN v_terminal THEN NULL ELSE v_next_reference END,
        CASE WHEN v_terminal THEN NULL ELSE v_next_sha256 END,
        CASE WHEN v_terminal THEN NULL ELSE
            'iam.profile.backfill:' || p_plan_id::text || ':' ||
            (p_page_number + 1)::text END
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_finish_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_scanned_count bigint, p_converted_count bigint, p_source_sha256 bytea, p_result_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_profile_backfill_receipt_v1(uuid, uuid, integer, text, bytea, bigint, bigint, bigint, bytea, uuid, timestamp with time zone, text, bytea, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_profile_backfill_receipt_v1(p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_scanned_count bigint, p_affected_count bigint, p_error_count bigint, p_result_sha256 bytea, p_successor_job_id uuid, p_successor_run_at timestamp with time zone, p_successor_reference text, p_successor_sha256 bytea, p_successor_dedupe_key text) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_outcome text;
BEGIN
    v_outcome := 'iam.profile.backfill.completed';
    IF p_scanned_count < 0 OR p_affected_count < 0 OR p_error_count < 0 OR
       p_affected_count > p_scanned_count OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       ((p_successor_job_id IS NULL) <> (p_successor_run_at IS NULL)) OR
       ((p_successor_job_id IS NULL) <> (p_successor_reference IS NULL)) OR
       ((p_successor_job_id IS NULL) <> (p_successor_sha256 IS NULL)) OR
       ((p_successor_job_id IS NULL) <> (p_successor_dedupe_key IS NULL)) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill receipt is invalid';
    END IF;
    INSERT INTO iam_maintenance_receipts (
        job_id, attempt_id, kind, payload_revision, payload_reference,
        payload_sha256, outcome_code, scanned_count, affected_count,
        error_count, result_sha256, successor_job_id, successor_run_at,
        successor_payload_reference, successor_payload_sha256,
        successor_dedupe_key, successor_priority, created_at
    ) VALUES (
        p_job_id, p_attempt_id, 'iam.profile.backfill', p_payload_revision,
        p_payload_reference, p_payload_sha256, v_outcome, p_scanned_count,
        p_affected_count, p_error_count, p_result_sha256,
        p_successor_job_id, p_successor_run_at, p_successor_reference,
        p_successor_sha256, p_successor_dedupe_key,
        CASE WHEN p_successor_job_id IS NULL THEN NULL ELSE 0 END, v_now
    );
    INSERT INTO iam_maintenance_audit (
        job_id, attempt_id, kind, outcome_code, affected_count,
        error_count, result_sha256, occurred_at
    ) VALUES (
        p_job_id, p_attempt_id, 'iam.profile.backfill', v_outcome,
        p_affected_count, p_error_count, p_result_sha256, v_now
    );
    INSERT INTO iam_maintenance_metrics (
        kind, completed_runs, affected_total, error_total, last_job_id,
        last_result_sha256, last_completed_at, revision
    ) VALUES (
        'iam.profile.backfill', 1, p_affected_count, p_error_count,
        p_job_id, p_result_sha256, v_now, 1
    ) ON CONFLICT (kind) DO UPDATE SET
        completed_runs = iam_maintenance_metrics.completed_runs + 1,
        affected_total = iam_maintenance_metrics.affected_total +
            EXCLUDED.affected_total,
        error_total = iam_maintenance_metrics.error_total + EXCLUDED.error_total,
        last_job_id = EXCLUDED.last_job_id,
        last_result_sha256 = EXCLUDED.last_result_sha256,
        last_completed_at = EXCLUDED.last_completed_at,
        revision = iam_maintenance_metrics.revision + 1;
    RETURN QUERY SELECT p_successor_job_id, p_successor_run_at,
        p_successor_reference, p_successor_sha256,
        p_successor_dedupe_key,
        CASE WHEN p_successor_job_id IS NULL THEN NULL ELSE 0 END;
END;
$$;


