            MESSAGE = 'IAM profile backfill schema authority is invalid';
    END IF;
    SELECT plan.resource_kind INTO v_resource_kind
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_backfill_pages AS page ON page.plan_id = plan.id
    WHERE plan.id = p_plan_id AND page.job_id = p_job_id
      AND page.payload_reference = p_payload_reference
      AND page.payload_sha256 = p_payload_sha256 AND page.state = 'queued'
      AND p_schema_id IN (plan.source_schema_id, plan.target_schema_id);
    IF v_resource_kind IS NULL OR (
        SELECT pg_catalog.count(*) FROM iam_profile_field_revisions AS snapshot
        WHERE snapshot.schema_version_id = p_schema_id
          AND snapshot.resource_kind = v_resource_kind
    ) > 250 THEN
        RAISE EXCEPTION USING ERRCODE = '54000',
            MESSAGE = 'IAM profile backfill schema bound is invalid';
    END IF;
    RETURN QUERY
    SELECT version.id, version.resource_kind, version.version, version.state,
           version.definition_sha256, field.id, field.field_key,
           field.value_kind, field.cardinality, field.required,
           field.classification, field.normalization_profile, field.state,
           snapshot.validation_schema::text, snapshot.validation_sha256
    FROM iam_profile_schema_versions AS version
    LEFT JOIN iam_profile_field_revisions AS snapshot
      ON snapshot.schema_version_id = version.id
     AND snapshot.resource_kind = version.resource_kind
    LEFT JOIN iam_profile_fields AS field
      ON field.id = snapshot.field_id
     AND field.resource_kind = snapshot.resource_kind
    WHERE version.id = p_schema_id AND version.resource_kind = v_resource_kind
    ORDER BY field.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_profile_schema_read_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_schema_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_profile_schema_read_v2(name, uuid, uuid, uuid, integer, text, bytea, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_profile_schema_read_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_schema_id uuid) RETURNS TABLE(schema_id uuid, resource_kind text, schema_version bigint, schema_state text, definition_sha256 bytea, field_id uuid, field_key text, value_kind text, cardinality text, required boolean, classification text, normalization_profile text, field_state text, validation_schema text, validation_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_resource_kind text;
    v_source_schema_id uuid;
    v_source_version bigint;
    v_target_schema_id uuid;
    v_after_resource_id uuid;
    v_through_resource_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.profile.backfill', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile schema snapshot authority is invalid';
    END IF;
    SELECT plan.resource_kind, plan.source_schema_id, source.version,
           plan.target_schema_id, page.after_resource_id,
           page.through_resource_id
    INTO v_resource_kind, v_source_schema_id, v_source_version,
         v_target_schema_id, v_after_resource_id, v_through_resource_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_backfill_pages AS page ON page.plan_id = plan.id
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.id = p_plan_id AND page.job_id = p_job_id
      AND page.payload_reference = p_payload_reference
      AND page.payload_sha256 = p_payload_sha256 AND page.state = 'queued'
      AND plan.state IN ('planned', 'running');
    IF v_resource_kind IS NULL OR (
        SELECT pg_catalog.count(*)
        FROM iam_profile_field_revisions AS snapshot
        WHERE snapshot.schema_version_id = p_schema_id
          AND snapshot.resource_kind = v_resource_kind
    ) > 250 THEN
        RAISE EXCEPTION USING ERRCODE = '54000',
            MESSAGE = 'IAM profile schema snapshot bound is invalid';
    END IF;
    RETURN QUERY
    SELECT version.id, version.resource_kind, version.version, version.state,
           version.definition_sha256, snapshot.field_id, snapshot.field_key,
           snapshot.value_kind, snapshot.cardinality, snapshot.required,
           snapshot.classification, snapshot.normalization_profile,
           snapshot.field_state, snapshot.validation_schema::text,
           snapshot.validation_sha256
    FROM iam_profile_schema_versions AS version
    LEFT JOIN iam_profile_field_revisions AS snapshot
      ON snapshot.schema_version_id = version.id
     AND snapshot.resource_kind = version.resource_kind
    WHERE version.id = p_schema_id AND version.resource_kind = v_resource_kind
      AND ((version.id = v_source_schema_id AND version.state = 'active') OR
           (version.id = v_target_schema_id AND version.state = 'draft') OR
           (version.state IN ('active','retired') AND
            version.version <= v_source_version AND EXISTS (
                SELECT 1 FROM (
                    SELECT usr.id, usr.profile_schema_version_id
                    FROM iam_users AS usr WHERE v_resource_kind = 'user'
                    UNION ALL
                    SELECT organization.id,
                           organization.profile_schema_version_id
                    FROM iam_organizations AS organization
                    WHERE v_resource_kind = 'organization'
                    UNION ALL
                    SELECT role.id, role.profile_schema_version_id
                    FROM iam_roles AS role WHERE v_resource_kind = 'role'
                ) AS resource
                WHERE resource.profile_schema_version_id = version.id
                  AND (v_after_resource_id IS NULL OR
                       resource.id > v_after_resource_id)
                  AND resource.id <= v_through_resource_id
            )))
    ORDER BY snapshot.field_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_profile_schema_read_v2(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_schema_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_receipt_read_v1(name, uuid, uuid, text, integer, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_receipt_read_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_kind text, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_kind text;
    v_payload_revision integer;
    v_payload_reference text;
    v_payload_sha256 bytea;
    v_successor_job_id uuid;
    v_successor_run_at timestamptz;
    v_successor_reference text;
    v_successor_sha256 bytea;
    v_successor_dedupe_key text;
    v_successor_priority integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_job_id IS NULL OR NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM maintenance receipt authority is invalid';
    END IF;
    SELECT receipt.kind, receipt.payload_revision,
           receipt.payload_reference, receipt.payload_sha256,
           receipt.successor_job_id, receipt.successor_run_at,
           receipt.successor_payload_reference,
           receipt.successor_payload_sha256,
           receipt.successor_dedupe_key, receipt.successor_priority
    INTO v_kind, v_payload_revision, v_payload_reference, v_payload_sha256,
         v_successor_job_id, v_successor_run_at, v_successor_reference,
         v_successor_sha256, v_successor_dedupe_key, v_successor_priority
    FROM iam_maintenance_receipts AS receipt
    WHERE receipt.job_id = p_job_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF v_kind IS DISTINCT FROM p_kind OR
       v_payload_revision IS DISTINCT FROM p_payload_revision OR
       v_payload_reference IS DISTINCT FROM p_payload_reference OR
       v_payload_sha256 IS DISTINCT FROM p_payload_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '23505',
            MESSAGE = 'IAM maintenance receipt identity conflicts';
    END IF;
    RETURN QUERY SELECT
        v_successor_job_id, v_successor_run_at, v_successor_reference,
        v_successor_sha256, v_successor_dedupe_key, v_successor_priority;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_receipt_read_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_kind text, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_maintenance_security_artifact_purge_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_maintenance_security_artifact_purge_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_successor_job_id uuid) RETURNS TABLE(successor_job_id uuid, successor_run_at timestamp with time zone, successor_reference text, successor_sha256 bytea, successor_dedupe_key text, successor_priority integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_count bigint;
    v_step bigint;
    v_result bytea;
BEGIN
    v_count := 0;
    IF NOT iam_maintenance_claim_assert_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.security-artifact-purge', p_payload_revision,
        p_payload_reference, p_payload_sha256
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM security artifact purge claim is invalid';
    END IF;
    DELETE FROM iam_recovery_codes AS code
    WHERE code.state IN ('consumed', 'revoked')
      AND code.purge_after IS NOT NULL AND code.purge_after <= v_now;
    GET DIAGNOSTICS v_step = ROW_COUNT;
    v_count := v_count + v_step;
    DELETE FROM iam_auth_challenges AS challenge
    WHERE challenge.state <> 'pending' AND challenge.purge_after <= v_now;
    GET DIAGNOSTICS v_step = ROW_COUNT;
    v_count := v_count + v_step;
    DELETE FROM iam_one_time_tokens AS token
    WHERE token.state <> 'pending' AND token.purge_after <= v_now;
    GET DIAGNOSTICS v_step = ROW_COUNT;
    v_count := v_count + v_step;
    v_result := pg_catalog.sha256(pg_catalog.convert_to(
        'iam.security-artifact-purge:' || v_count::text, 'UTF8'
    ));
    UPDATE iam_maintenance_checkpoints
    SET cursor_id = NULL, scanned_count = v_count, affected_count = v_count,
        error_count = 0, result_sha256 = v_result, last_job_id = p_job_id,
        revision = revision + 1, updated_at = v_now
    WHERE kind = 'iam.security-artifact-purge';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM security purge checkpoint is missing';
    END IF;
    RETURN QUERY SELECT * FROM iam_maintenance_complete_recurring_v1(
        p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
        'iam.security-artifact-purge', p_payload_revision,
        p_payload_reference, p_payload_sha256, v_count, v_count, 0,
        v_result, p_successor_job_id
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_maintenance_security_artifact_purge_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_successor_job_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_notifications_recipient_read_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_notifications_recipient_read_v1(p_scope_schema name, p_recipient_id uuid) RETURNS TABLE(principal_id uuid, authorization_version bigint, supported_locales text[], email_target text, email_verified boolean, telegram_target text, telegram_verified boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_recipient_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM notification recipient read is denied';
    END IF;
    RETURN QUERY
    SELECT principal.id, principal.authorization_version,
           ARRAY['tr','en']::text[], email.normalized_value,
           email.id IS NOT NULL, NULL::text, false
    FROM iam_users AS principal
    LEFT JOIN LATERAL (
        SELECT identifier.id, identifier.normalized_value
        FROM iam_user_identifiers AS identifier
        WHERE identifier.user_id = principal.id
          AND identifier.kind = 'email_v1'
          AND identifier.state = 'active'
        ORDER BY identifier.revision DESC LIMIT 1
    ) AS email ON true
    WHERE principal.id = p_recipient_id AND principal.status = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM notification recipient is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_notifications_recipient_read_v1(p_scope_schema name, p_recipient_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_notifications_session_selector_v1(name, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_notifications_session_selector_v1(p_scope_schema name, p_principal_id uuid, p_session_id uuid, p_now timestamp with time zone) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_selector bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_principal_id IS NULL OR p_session_id IS NULL OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM notification session read is denied';
    END IF;
    SELECT token.selector
    INTO STRICT v_selector
    FROM iam_sessions AS session
    JOIN iam_refresh_families AS family
      ON family.session_id = session.id AND family.user_id = session.user_id
    JOIN iam_refresh_tokens AS token ON token.family_id = family.id
    WHERE session.id = p_session_id
      AND session.user_id = p_principal_id
      AND session.access_mode = 'operator_console'
      AND session.state = 'active'
      AND family.state = 'active'
      AND token.state = 'active'
      AND session.absolute_expires_at > p_now
      AND family.absolute_expires_at > p_now
      AND token.idle_expires_at > p_now;
    IF pg_catalog.octet_length(v_selector) IS DISTINCT FROM 16 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM notification session is unavailable';
    END IF;
    RETURN v_selector;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM notification session is unavailable';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_notifications_session_selector_v1(p_scope_schema name, p_principal_id uuid, p_session_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_one_time_consume_v1(name, uuid, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_one_time_consume_v1(p_scope_schema name, p_token_id uuid, p_expected_revision bigint, p_expected_purpose text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_purpose text;
    v_state text;
    v_revision bigint;
    v_expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT (
           p_expected_purpose OPERATOR(pg_catalog.=) 'password_reset_v1' OR
           p_expected_purpose OPERATOR(pg_catalog.=) 'email_verification_v1'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM one-time consume scope or purpose is invalid';
    END IF;
    SELECT token.purpose, token.state, token.revision, token.expires_at
    INTO v_purpose, v_state, v_revision, v_expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM one-time token is unknown';
    END IF;
    IF v_purpose IS DISTINCT FROM p_expected_purpose OR
       v_state IS DISTINCT FROM 'pending' OR
       v_revision IS DISTINCT FROM p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM one-time consume CAS is stale';
    END IF;
    IF v_now OPERATOR(pg_catalog.>=) v_expires_at THEN
        UPDATE iam_one_time_tokens
        SET state = 'expired', expired_at = v_expires_at,
            updated_at = v_now,
            revision = v_revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_token_id;
        RETURN 'expired';
    END IF;
    UPDATE iam_one_time_tokens
    SET state = 'consumed', consumed_at = v_now, updated_at = v_now,
        revision = v_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_token_id;
    RETURN 'consumed';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_one_time_consume_v1(p_scope_schema name, p_token_id uuid, p_expected_revision bigint, p_expected_purpose text) OWNER TO harpy_owner;

--
-- Name: iam_one_time_issue_v1(uuid, text, uuid, uuid, text, bigint, uuid, bigint, bytea, text, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_one_time_issue_v1(p_token_id uuid, p_purpose text, p_user_id uuid, p_identifier_id uuid, p_identifier_kind text, p_identifier_revision bigint, p_portal_binding_id uuid, p_portal_setup_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_expires timestamptz;
BEGIN
    IF p_token_id IS NULL OR p_user_id IS NULL OR p_identifier_id IS NULL OR
       p_identifier_kind NOT IN ('email_v1', 'portal_v1') OR
       p_identifier_revision < 1 OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       NOT iam_hmac_key_id_valid_v1(p_hash_key_id) OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_binding_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM one-time token issue input is invalid';
    END IF;
    CASE p_purpose
      WHEN 'email_verification_v1' THEN
        IF p_identifier_kind <> 'email_v1' OR p_portal_binding_id IS NOT NULL OR
           p_portal_setup_revision IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '22023';
        END IF;
        v_expires := v_now + INTERVAL '24 hours';
      WHEN 'password_reset_v1' THEN
        IF p_portal_binding_id IS NOT NULL OR
           p_portal_setup_revision IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '22023';
        END IF;
        v_expires := v_now + INTERVAL '1 hour';
      WHEN 'portal_setup_v1' THEN
        IF p_identifier_kind <> 'portal_v1' OR p_portal_binding_id IS NULL OR
           p_portal_setup_revision < 1 THEN
            RAISE EXCEPTION USING ERRCODE = '22023';
        END IF;
        v_expires := v_now + INTERVAL '1 hour';
      ELSE RAISE EXCEPTION USING ERRCODE = '22023';
    END CASE;
    UPDATE iam_one_time_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE purpose = p_purpose AND user_id = p_user_id
      AND identifier_id = p_identifier_id AND state = 'pending';
    INSERT INTO iam_one_time_tokens (
        id, purpose, user_id, identifier_id, identifier_kind,
        identifier_revision, portal_binding_id, portal_setup_revision,
        selector, hash_key_id, secret_hmac, binding_sha256, state,
        attempt_count, revision, created_at, updated_at, expires_at, purge_after
    ) VALUES (
        p_token_id, p_purpose, p_user_id, p_identifier_id, p_identifier_kind,
        p_identifier_revision, p_portal_binding_id, p_portal_setup_revision,
        p_selector, p_hash_key_id, p_secret_hmac, p_binding_sha256, 'pending',
        0, 1, v_now, v_now, v_expires, v_expires + INTERVAL '24 hours'
    );
    RETURN 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_one_time_issue_v1(p_token_id uuid, p_purpose text, p_user_id uuid, p_identifier_id uuid, p_identifier_kind text, p_identifier_revision bigint, p_portal_binding_id uuid, p_portal_setup_revision bigint, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_owner_transfer_ack_v1(name, uuid, bytea, uuid, bigint, bigint, bigint, bytea, timestamp with time zone, text, boolean, boolean, boolean, uuid, uuid, bigint, bigint, bytea, bytea, bytea, bytea, timestamp with time zone, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_owner_transfer_ack_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_acr text, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean, p_registry_binding_id uuid, p_scope_id uuid, p_registry_sequence bigint, p_generation bigint, p_proposal_sha256 bytea, p_previous_head_sha256 bytea, p_state_sha256 bytea, p_ack_sha256 bytea, p_ack_issued_at timestamp with time zone, p_ack_registry_kid text) RETURNS TABLE(operation_id uuid, registry_binding_id uuid, scope_id uuid, generation bigint, previous_head_sha256 bytea, state_sha256 bytea, proposal_sha256 bytea, status text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_tenant_id uuid; v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_actor_id IS NULL OR p_expected_token_version < 1 OR
       p_expected_authorization_version < 1 OR p_expected_platform_clock < 1 OR
       pg_catalog.octet_length(p_purpose_sha256) <> 32 OR
       p_acr <> 'urn:harpy:acr:step-up' OR
       NOT (p_amr_password OR p_amr_webauthn OR p_amr_totp) OR
       p_auth_time > v_now OR p_auth_time < v_now - INTERVAL '10 minutes' OR
       p_purpose_sha256 <> pg_catalog.sha256(pg_catalog.convert_to(
           'platform.owner.transfer.ack' || E'\n' || p_operation_id::text || E'\n' ||
           pg_catalog.encode(p_ack_sha256, 'hex'), 'UTF8')) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Owner transfer ack input is invalid';
    END IF;
    SELECT identity.tenant_id INTO v_tenant_id
    FROM tenancy_schema_identity AS identity WHERE identity.singleton;
    PERFORM 1 FROM iam_users AS principal
    WHERE principal.id = p_actor_id AND principal.status = 'active'
      AND principal.identity_kind = 'human'
      AND principal.token_version = p_expected_token_version
      AND principal.authorization_version = p_expected_authorization_version FOR UPDATE;
    IF NOT FOUND OR v_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Owner transfer ack actor is stale';
    END IF;
    RETURN QUERY SELECT result.operation_id,result.registry_binding_id,result.scope_id,
        result.generation,result.previous_head_sha256,result.state_sha256,
        result.proposal_sha256,result.status,result.replayed
    FROM platform.iam_owner_transfer_ack_v1(
        v_tenant_id,p_operation_id,p_request_sha256,p_actor_id,p_expected_platform_clock,
        p_registry_binding_id,p_scope_id,p_registry_sequence,p_generation,
        p_proposal_sha256,p_previous_head_sha256,p_state_sha256,p_ack_sha256,
        p_ack_issued_at,p_ack_registry_kid
    ) AS result;
END;
$$;


