--
-- Name: iam_password_change_v1(name, uuid, uuid, bytea, uuid, bigint, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_password_change_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_expected_credential_revision bigint, p_salt bytea, p_tag bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_user_id IS NULL OR p_expected_credential_revision < 1 OR
       pg_catalog.octet_length(p_salt) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_tag) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.password.change', p_request_sha256, p_user_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    UPDATE iam_password_credentials AS credential SET
        credential_version = credential.credential_version + 1,
        state = 'active', algorithm = 'argon2id_v1', salt = p_salt,
        tag = p_tag, memory_kib = 65536, iterations = 3, parallelism = 4,
        legacy_bcrypt_hash = NULL, upgrade_required = false,
        revision = credential.revision + 1, updated_at = v_now,
        invalidated_at = NULL
    WHERE credential.user_id = p_user_id
      AND credential.revision = p_expected_credential_revision
    RETURNING credential.revision INTO v_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM password credential revision changed';
    END IF;
    UPDATE iam_sessions SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = p_user_id AND state = 'active';
    UPDATE iam_refresh_families SET state = 'revoked',
        revoke_reason = 'password_changed', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = p_user_id AND state = 'active';
    UPDATE iam_refresh_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE family_id IN (SELECT id FROM iam_refresh_families
        WHERE user_id = p_user_id) AND state = 'active';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.password.change', p_request_sha256,
        p_user_id, p_user_id, v_revision, 'actor_tenant', p_actor_id,
        'password_credential', true, true
    ) AS result;
    RETURN QUERY SELECT p_user_id, p_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_password_change_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_expected_credential_revision bigint, p_salt bytea, p_tag bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_password_credential_read_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_password_credential_read_v1(p_scope_schema name, p_user_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(algorithm text, salt bytea, tag bytea, memory_kib integer, iterations smallint, parallelism smallint, legacy_bcrypt_hash text, credential_version bigint, credential_revision bigint, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_user_id IS NULL OR p_user_id <> p_actor_id OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY
    SELECT credential.algorithm, credential.salt, credential.tag,
        credential.memory_kib, credential.iterations, credential.parallelism,
        credential.legacy_bcrypt_hash, credential.credential_version,
        credential.revision, credential.created_at
    FROM iam_password_credentials AS credential
    WHERE credential.user_id = p_user_id AND credential.state = 'active';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_password_credential_read_v1(p_scope_schema name, p_user_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_password_reset_complete_v1(name, uuid, uuid, bytea, bytea, text, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_password_reset_complete_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_salt bytea, p_tag bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_token_id uuid; v_user_id uuid; v_identifier_id uuid;
    v_identifier_revision bigint; v_token_state text;
    v_expires_at timestamptz; v_credential_revision bigint;
    v_token_version bigint; v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       NOT iam_hmac_key_id_valid_v1(p_hash_key_id) OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_binding_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_salt) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_tag) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.password_reset.complete', p_request_sha256, NULL
    );
    IF FOUND THEN RETURN; END IF;
    SELECT token.id, token.user_id, token.identifier_id,
        token.identifier_revision, token.state, token.expires_at
    INTO v_token_id, v_user_id, v_identifier_id,
        v_identifier_revision, v_token_state, v_expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.purpose = 'password_reset_v1' AND token.selector = p_selector
      AND token.hash_key_id = p_hash_key_id AND token.secret_hmac = p_secret_hmac
      AND token.binding_sha256 = p_binding_sha256 FOR UPDATE;
    IF NOT FOUND OR v_token_state <> 'pending' OR v_expires_at <= v_now OR
       NOT EXISTS (
          SELECT 1 FROM iam_user_identifiers AS identifier
          WHERE identifier.id = v_identifier_id
            AND identifier.user_id = v_user_id
            AND identifier.revision = v_identifier_revision
            AND identifier.state = 'active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '28000',
            MESSAGE = 'IAM password reset proof is invalid';
    END IF;
    INSERT INTO iam_password_credentials (
        user_id, credential_version, state, algorithm, salt, tag,
        memory_kib, iterations, parallelism, upgrade_required,
        revision, created_at, updated_at
    ) VALUES (
        v_user_id, 1, 'active', 'argon2id_v1', p_salt, p_tag,
        65536, 3, 4, false, 1, v_now, v_now
    ) ON CONFLICT (user_id) DO UPDATE SET
        credential_version = iam_password_credentials.credential_version + 1,
        state = 'active', algorithm = 'argon2id_v1', salt = EXCLUDED.salt,
        tag = EXCLUDED.tag, memory_kib = 65536, iterations = 3,
        parallelism = 4, legacy_bcrypt_hash = NULL, upgrade_required = false,
        revision = iam_password_credentials.revision + 1,
        updated_at = v_now, invalidated_at = NULL
    RETURNING revision INTO v_credential_revision;
    UPDATE iam_one_time_tokens SET state = 'consumed', consumed_at = v_now,
        revision = revision + 1, updated_at = v_now WHERE id = v_token_id;
    UPDATE iam_one_time_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = v_user_id AND state = 'pending';
    UPDATE iam_sessions SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = v_user_id AND state = 'active';
    UPDATE iam_refresh_families SET state = 'revoked',
        revoke_reason = 'password_reset', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = v_user_id AND state = 'active';
    UPDATE iam_refresh_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE family_id IN (SELECT id FROM iam_refresh_families
        WHERE user_id = v_user_id) AND state = 'active';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.password_reset.complete', p_request_sha256,
        v_user_id, v_user_id, v_credential_revision,
        'credential_target', v_user_id, 'password_credential', true, true
    ) AS result;
    RETURN QUERY SELECT v_user_id, v_user_id, v_credential_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_password_reset_complete_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_salt bytea, p_tag bytea) OWNER TO harpy_owner;

--
-- Name: iam_password_reset_delivery_target_v1(name, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_password_reset_delivery_target_v1(p_scope_schema name, p_identifier_kind text, p_identifier_sha256 bytea) RETURNS TABLE(subject_user_id uuid, resource_id uuid, recipient_identifier_id uuid, recipient_address text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_identifier_kind NOT IN ('email_v1', 'portal_v1') OR
       pg_catalog.octet_length(p_identifier_sha256) <> 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM password reset delivery target is denied';
    END IF;
    RETURN QUERY
    SELECT target.user_id, target.id, recipient.id,
           recipient.normalized_value
    FROM iam_user_identifiers AS target
    JOIN iam_users AS subject
      ON subject.id = target.user_id AND subject.status = 'active'
    JOIN iam_user_identifiers AS recipient
      ON recipient.user_id = target.user_id
     AND recipient.kind = 'email_v1' AND recipient.state = 'active'
    WHERE target.kind = p_identifier_kind
      AND target.normalized_sha256 = p_identifier_sha256
      AND target.state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM password reset target is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_password_reset_delivery_target_v1(p_scope_schema name, p_identifier_kind text, p_identifier_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_password_reset_start_v1(name, uuid, uuid, bytea, uuid, text, bytea, bytea, text, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_password_reset_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_identifier_kind text, p_identifier_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_identifier_id uuid;
    v_kind text;
    v_identifier_revision bigint;
    v_issue bigint;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF p_token_id IS NULL OR p_identifier_kind NOT IN ('email_v1', 'portal_v1') OR
       pg_catalog.octet_length(p_identifier_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.password_reset.start',
        p_request_sha256, p_token_id
    );
    IF FOUND THEN RETURN; END IF;
    SELECT identifier.user_id, identifier.id, identifier.kind,
        identifier.revision
    INTO v_user_id, v_identifier_id, v_kind, v_identifier_revision
    FROM iam_user_identifiers AS identifier
    JOIN iam_users AS subject ON subject.id = identifier.user_id
    WHERE identifier.kind = p_identifier_kind
      AND identifier.normalized_sha256 = p_identifier_sha256
      AND identifier.state = 'active' AND subject.status = 'active'
    FOR UPDATE OF identifier, subject;
    IF NOT FOUND THEN RETURN; END IF;
    v_issue := iam_one_time_issue_v1(
        p_token_id, 'password_reset_v1', v_user_id,
        v_identifier_id, v_kind, v_identifier_revision,
        NULL, NULL, p_selector, p_hash_key_id, p_secret_hmac,
        p_binding_sha256
    );
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.password_reset.start', p_request_sha256,
        p_token_id, v_user_id, 1, 'credential_target',
        v_user_id, 'one_time_token', false, false
    ) AS result;
    RETURN QUERY SELECT p_token_id, v_user_id, 1::bigint,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_password_reset_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_identifier_kind text, p_identifier_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_password_reset_start_v2(name, uuid, uuid, bytea, uuid, text, bytea, bytea, text, bytea, bytea, uuid, uuid, uuid, uuid, text, text, bytea, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_password_reset_start_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_identifier_kind text, p_identifier_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_artifact_id uuid, p_subject_user_id uuid, p_resource_id uuid, p_recipient_identifier_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_result_id uuid; v_subject_user_id uuid; v_result_revision bigint;
    v_token_version bigint; v_authorization_version bigint;
    v_replayed boolean; v_insert bigint;
BEGIN
    SELECT started.result_id, started.subject_user_id, started.result_revision,
           started.token_version, started.authorization_version, started.replayed
    INTO v_result_id, v_subject_user_id, v_result_revision,
         v_token_version, v_authorization_version, v_replayed
    FROM iam_password_reset_start_v1(
        p_scope_schema, p_tenant_id, p_operation_id, p_request_sha256,
        p_token_id, p_identifier_kind, p_identifier_sha256, p_selector,
        p_hash_key_id, p_secret_hmac, p_binding_sha256
    ) AS started;
    IF NOT FOUND THEN RETURN; END IF;
    IF NOT v_replayed THEN
        v_insert := iam_lifecycle_delivery_artifact_insert_v1(
            p_scope_schema, p_tenant_id, p_artifact_id,
            'password_reset_v1', p_subject_user_id, p_resource_id,
            p_recipient_identifier_id, p_token_id, p_artifact_ref,
            p_kms_key_id, p_nonce, p_ciphertext, p_authentication_tag,
            p_aad_sha256, p_ciphertext_sha256
        );
    END IF;
    RETURN QUERY SELECT v_result_id, v_subject_user_id,
        v_result_revision, v_token_version,
        v_authorization_version, v_replayed;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_password_reset_start_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_identifier_kind text, p_identifier_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_artifact_id uuid, p_subject_user_id uuid, p_resource_id uuid, p_recipient_identifier_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_password_use_v1(name, uuid, bigint, bigint, bigint, bigint, bigint, boolean, bytea, bytea, integer, smallint, smallint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_password_use_v1(p_scope_schema name, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_credential_version bigint, p_expected_credential_revision bigint, p_rehash_legacy boolean, p_argon_salt bytea, p_argon_tag bytea, p_argon_memory_kib integer, p_argon_iterations smallint, p_argon_parallelism smallint) RETURNS TABLE(user_revision bigint, token_version bigint, authorization_version bigint, credential_version bigint, credential_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_user_status text;
    v_identity_kind text;
    v_user_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_user_updated_at timestamptz;
    v_credential_state text;
    v_algorithm text;
    v_upgrade_required boolean;
    v_credential_version bigint;
    v_credential_revision bigint;
    v_credential_created_at timestamptz;
    v_credential_updated_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM password use scope is invalid';
    END IF;
    SELECT principal.status, principal.identity_kind, principal.revision,
           principal.token_version, principal.authorization_version,
           principal.updated_at
    INTO v_user_status, v_identity_kind, v_user_revision,
         v_token_version, v_authorization_version, v_user_updated_at
    FROM iam_users AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_user_id
    FOR UPDATE;
    SELECT credential.state, credential.algorithm,
           credential.upgrade_required, credential.credential_version,
           credential.revision, credential.created_at, credential.updated_at
    INTO v_credential_state, v_algorithm, v_upgrade_required,
         v_credential_version, v_credential_revision,
         v_credential_created_at, v_credential_updated_at
    FROM iam_password_credentials AS credential
    WHERE credential.user_id OPERATOR(pg_catalog.=) p_user_id
    FOR UPDATE;
    IF v_user_status IS NULL OR v_credential_state IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM password subject is unavailable';
    END IF;
    IF v_user_status IS DISTINCT FROM 'active' OR
       v_identity_kind IS DISTINCT FROM 'human' OR
       v_credential_state IS DISTINCT FROM 'active' OR
       v_user_revision IS DISTINCT FROM p_expected_user_revision OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_authorization_version IS DISTINCT FROM
           p_expected_authorization_version OR
       v_credential_version IS DISTINCT FROM
           p_expected_credential_version OR
       v_credential_revision IS DISTINCT FROM p_expected_credential_revision OR
       v_now OPERATOR(pg_catalog.<) v_user_updated_at OR
       v_now OPERATOR(pg_catalog.<) v_credential_updated_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM password use CAS is stale';
    END IF;
    IF p_rehash_legacy THEN
        IF v_algorithm IS DISTINCT FROM 'bcrypt_v1_adopted' OR
           NOT v_upgrade_required OR
           v_now OPERATOR(pg_catalog.>=)
               v_credential_created_at OPERATOR(pg_catalog.+) INTERVAL '180 days' OR
           pg_catalog.octet_length(p_argon_salt) IS DISTINCT FROM 16 OR
           pg_catalog.octet_length(p_argon_tag) IS DISTINCT FROM 32 OR
           p_argon_memory_kib IS DISTINCT FROM 65536 OR
           p_argon_iterations IS DISTINCT FROM 3::smallint OR
           p_argon_parallelism IS DISTINCT FROM 4::smallint THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'IAM legacy password rehash is invalid';
        END IF;
        UPDATE iam_password_credentials
        SET credential_version =
                v_credential_version OPERATOR(pg_catalog.+) 1,
            algorithm = 'argon2id_v1',
            salt = p_argon_salt,
            tag = p_argon_tag,
            memory_kib = p_argon_memory_kib,
            iterations = p_argon_iterations,
            parallelism = p_argon_parallelism,
            legacy_bcrypt_hash = NULL,
            upgrade_required = false,
            revision = v_credential_revision OPERATOR(pg_catalog.+) 1,
            updated_at = v_now,
            last_used_at = v_now
        WHERE user_id OPERATOR(pg_catalog.=) p_user_id;
        UPDATE iam_users
        SET token_version = v_token_version OPERATOR(pg_catalog.+) 1,
            revision = v_user_revision OPERATOR(pg_catalog.+) 1,
            updated_at = v_now
        WHERE id OPERATOR(pg_catalog.=) p_user_id;
    ELSE
        IF v_algorithm IS DISTINCT FROM 'argon2id_v1' OR
           v_upgrade_required OR p_argon_salt IS NOT NULL OR
           p_argon_tag IS NOT NULL OR p_argon_memory_kib IS NOT NULL OR
           p_argon_iterations IS NOT NULL OR p_argon_parallelism IS NOT NULL THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'IAM password use profile is invalid';
        END IF;
        UPDATE iam_password_credentials
        SET revision = v_credential_revision OPERATOR(pg_catalog.+) 1,
            updated_at = v_now,
            last_used_at = v_now
        WHERE user_id OPERATOR(pg_catalog.=) p_user_id;
    END IF;
    RETURN QUERY
    SELECT principal.revision, principal.token_version,
           principal.authorization_version, credential.credential_version,
           credential.revision
    FROM iam_users AS principal
    JOIN iam_password_credentials AS credential
      ON credential.user_id OPERATOR(pg_catalog.=) principal.id
    WHERE principal.id OPERATOR(pg_catalog.=) p_user_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_password_use_v1(p_scope_schema name, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_credential_version bigint, p_expected_credential_revision bigint, p_rehash_legacy boolean, p_argon_salt bytea, p_argon_tag bytea, p_argon_memory_kib integer, p_argon_iterations smallint, p_argon_parallelism smallint) OWNER TO harpy_owner;

--
-- Name: iam_permission_cache_flush_v1(name, uuid, uuid, bytea, uuid, bigint, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_cache_flush_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint) RETURNS TABLE(authorization_clock bigint, result_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_command text;
    v_request bytea;
    v_result_id uuid;
    v_clock bigint;
    v_revision bigint;
    v_status text;
    v_token_version bigint;
    v_authorization_version bigint;
    v_platform_allowed boolean;
BEGIN
    IF p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_operation_id IS NULL OR p_actor_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_expected_token_version < 1 OR p_expected_authorization_version < 1 OR
       p_expected_platform_clock < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission cache flush identity is invalid';
    END IF;

    SELECT user_record.status, user_record.token_version,
           user_record.authorization_version
    INTO v_status, v_token_version, v_authorization_version
    FROM iam_users AS user_record
    WHERE user_record.id = p_actor_id
    FOR UPDATE;
    IF NOT FOUND OR v_status IS DISTINCT FROM 'active' OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission cache flush actor is stale';
    END IF;

    SELECT decision.allowed INTO v_platform_allowed
    FROM platform.iam_platform_authorize_decide_v1(
        p_tenant_id, p_actor_id, p_expected_platform_clock,
        'platform.operations.permission_cache.flush'
    ) AS decision;
    IF v_platform_allowed IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission cache flush capability is denied';
    END IF;

    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.clock_value, receipt.result_revision
    INTO v_command, v_request, v_result_id, v_clock, v_revision
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_command IS DISTINCT FROM 'iam.permission_cache.flush' OR
           v_request IS DISTINCT FROM p_request_sha256 OR
           v_result_id IS DISTINCT FROM p_tenant_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM permission cache flush identity was reused';
        END IF;
        RETURN QUERY SELECT v_clock, v_revision, true;
        RETURN;
    END IF;

    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1,
        updated_at = pg_catalog.transaction_timestamp()
    WHERE singleton
    RETURNING clock_value, revision INTO v_clock, v_revision;
    IF v_clock IS NULL OR v_revision IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM authorization clock is unavailable';
    END IF;

    INSERT INTO iam_authorization_operation_receipts(
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.permission_cache.flush', p_request_sha256, v_clock,
        'iam.permission_cache.flushed', p_tenant_id, v_revision,
        p_request_sha256, pg_catalog.transaction_timestamp()
    );
    RETURN QUERY SELECT v_clock, v_revision, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_cache_flush_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_action_catalog_v1(name, uuid, text, uuid, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_action_catalog_v1(p_scope_schema name, p_actor_user_id uuid, p_search text, p_after uuid, p_limit integer) RETURNS TABLE(action_id uuid, action_key text, display_name text, description text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request action catalog scope is invalid';
    END IF;
    IF p_actor_user_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM iam_users AS actor
        WHERE actor.id OPERATOR(pg_catalog.=) p_actor_user_id
          AND actor.status OPERATOR(pg_catalog.=) 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request action catalog actor is denied';
    END IF;
    IF p_search IS NULL OR p_search IS DISTINCT FROM pg_catalog.btrim(p_search) OR
       pg_catalog.char_length(p_search) > 128 OR p_limit IS NULL OR
       p_limit NOT BETWEEN 1 AND 101 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request action catalog query is invalid';
    END IF;

    RETURN QUERY
    SELECT action.id, action.action_key, action.display_name,
           COALESCE(action.description, '')
    FROM iam_actions AS action
    WHERE action.state OPERATOR(pg_catalog.=) 'active'
      AND NOT action.is_protected
      AND (p_after IS NULL OR action.id OPERATOR(pg_catalog.>) p_after)
      AND (
          p_search OPERATOR(pg_catalog.=) '' OR
          pg_catalog.strpos(
              pg_catalog.lower(pg_catalog.concat_ws(
                  ' ', action.action_key, action.display_name,
                  COALESCE(action.description, '')
              )),
              pg_catalog.lower(p_search)
          ) OPERATOR(pg_catalog.>) 0
      )
      AND EXISTS (
          SELECT 1
          FROM iam_permissions AS permission
          JOIN iam_resources AS resource
            ON resource.id OPERATOR(pg_catalog.=) permission.resource_id
          WHERE permission.action_id OPERATOR(pg_catalog.=) action.id
            AND permission.match_kind OPERATOR(pg_catalog.=) 'exact'
            AND permission.state OPERATOR(pg_catalog.=) 'active'
            AND NOT permission.is_protected
            AND resource.state OPERATOR(pg_catalog.=) 'active'
            AND NOT resource.is_protected
      )
    ORDER BY action.id
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_action_catalog_v1(p_scope_schema name, p_actor_user_id uuid, p_search text, p_after uuid, p_limit integer) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_audit_write_v1(name, uuid, bytea, uuid, uuid, uuid, text, text, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_group_id uuid, p_reviewer_user_id uuid, p_review_task_id uuid, p_decision text, p_result_code text, p_group_revision bigint, p_authorization_clock bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_result text;
    v_receipt_group uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_group_state text;
    v_group_reviewer uuid;
    v_group_task uuid;
    v_reviewer_active boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request audit scope is invalid';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256,
           receipt.result_code, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_result,
         v_receipt_group, v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    SELECT request_group.state, request_group.reviewer_user_id,
           request_group.review_task_id
    INTO v_group_state, v_group_reviewer, v_group_task
    FROM iam_permission_request_groups AS request_group
    WHERE request_group.id = p_group_id;
    SELECT true INTO v_reviewer_active
    FROM iam_users AS reviewer
    WHERE reviewer.id = p_reviewer_user_id AND reviewer.status = 'active';
    IF v_receipt_command IS DISTINCT FROM
           'iam.permission_request.group_decide' OR
       v_receipt_request IS DISTINCT FROM p_request_sha256 OR
       v_receipt_result IS DISTINCT FROM p_result_code OR
       v_receipt_group IS DISTINCT FROM p_group_id OR
       v_receipt_revision IS DISTINCT FROM p_group_revision OR
       v_receipt_clock IS DISTINCT FROM p_authorization_clock OR
       v_group_reviewer IS DISTINCT FROM p_reviewer_user_id OR
       v_group_task IS DISTINCT FROM p_review_task_id OR
       v_reviewer_active IS DISTINCT FROM true OR
       (p_decision = 'APPROVE' AND
           v_group_state IS DISTINCT FROM 'APPROVED') OR
       (p_decision = 'REJECT' AND
           v_group_state IS DISTINCT FROM 'REJECTED') OR
       p_decision NOT IN ('APPROVE', 'REJECT') THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM permission request audit evidence is invalid';
    END IF;
    INSERT INTO iam_permission_request_decision_audit (
        operation_id, group_id, reviewer_user_id, review_task_id,
        decision, result_code, request_sha256, group_revision,
        authorization_clock, recorded_at
    ) VALUES (
        p_operation_id, p_group_id, p_reviewer_user_id, p_review_task_id,
        p_decision, p_result_code, p_request_sha256, p_group_revision,
        p_authorization_clock, pg_catalog.transaction_timestamp()
    );
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_group_id uuid, p_reviewer_user_id uuid, p_review_task_id uuid, p_decision text, p_result_code text, p_group_revision bigint, p_authorization_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_bump_users_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_bump_users_v1(p_group_id uuid, p_now timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count integer;
BEGIN
    UPDATE iam_users AS principal
    SET authorization_version = principal.authorization_version + 1,
        revision = principal.revision + 1,
        updated_at = p_now
    WHERE principal.status = 'active' AND (
        EXISTS (
            SELECT 1 FROM iam_permission_requests AS request
            WHERE request.group_id = p_group_id AND request.target_kind = 'USER'
              AND request.target_user_id = principal.id
        ) OR EXISTS (
            SELECT 1
            FROM iam_permission_requests AS request
            JOIN iam_user_role_assignments AS assignment
              ON assignment.role_id = request.target_role_id
            WHERE request.group_id = p_group_id AND request.target_kind = 'ROLE'
              AND assignment.user_id = principal.id AND assignment.state = 'active'
        ) OR EXISTS (
            SELECT 1
            FROM iam_permission_requests AS request
            JOIN iam_organization_memberships AS membership
              ON membership.organization_id = request.target_organization_id
            WHERE request.group_id = p_group_id
              AND request.target_kind = 'ORGANIZATION'
              AND membership.user_id = principal.id AND membership.state = 'active'
        )
    );
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_bump_users_v1(p_group_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_cancel_v1(name, uuid, bigint, text, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_cancel_v1(p_scope_schema name, p_group_id uuid, p_expected_revision bigint, p_expected_state text, p_requester_user_id uuid, p_expected_authorization_version bigint) RETURNS TABLE(group_id uuid, group_state text, group_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_state text;
    v_revision bigint;
    v_requester_user_id uuid;
    v_requester_state text;
    v_authorization_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request cancellation scope is invalid';
    END IF;
    IF p_group_id IS NULL OR p_expected_revision < 1 OR
       p_expected_state NOT IN ('PENDING', 'IN_REVIEW') OR
       p_requester_user_id IS NULL OR p_expected_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request cancellation input is invalid';
    END IF;
    SELECT request_group.state, request_group.revision,
           request_group.requester_user_id,
           requester.status, requester.authorization_version
    INTO v_state, v_revision, v_requester_user_id,
         v_requester_state, v_authorization_version
    FROM iam_permission_request_groups AS request_group
    JOIN iam_users AS requester ON requester.id = request_group.requester_user_id
    WHERE request_group.id OPERATOR(pg_catalog.=) p_group_id
    FOR UPDATE OF request_group, requester;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM permission request group is unknown';
    END IF;
    IF v_state IS DISTINCT FROM p_expected_state OR
       v_revision IS DISTINCT FROM p_expected_revision OR
       v_requester_user_id IS DISTINCT FROM p_requester_user_id OR
       v_requester_state IS DISTINCT FROM 'active' OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM permission request cancellation CAS is stale';
    END IF;
    UPDATE iam_permission_request_groups
    SET state = 'CANCELLED', terminal_at = v_now,
        revision = v_revision + 1, updated_at = v_now
    WHERE id = p_group_id;
    UPDATE iam_permission_requests AS request
    SET state = 'CANCELLED', terminal_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE request.group_id = p_group_id;
    RETURN QUERY SELECT p_group_id, 'CANCELLED'::text, v_revision + 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_cancel_v1(p_scope_schema name, p_group_id uuid, p_expected_revision bigint, p_expected_state text, p_requester_user_id uuid, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_decide_v1(name, uuid, bytea, uuid, bigint, text, uuid, bigint, bigint, uuid, text, bytea, timestamp with time zone, text, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_decide_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_group_id uuid, p_expected_revision bigint, p_expected_state text, p_reviewer_user_id uuid, p_expected_reviewer_token_version bigint, p_expected_reviewer_authorization_version bigint, p_review_task_id uuid, p_decision text, p_step_up_purpose_sha256 bytea, p_step_up_auth_time timestamp with time zone, p_step_up_acr text, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS TABLE(result_code text, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_group_state text;
    v_group_revision bigint;
    v_group_expires_at timestamptz;
    v_group_reviewer_id uuid;
    v_group_task_id uuid;
    v_group_step_up_sha256 bytea;
    v_reviewer_permission_id uuid;
    v_reviewer_state text;
    v_reviewer_token_version bigint;
    v_reviewer_authorization_version bigint;
    v_receipt_command text;
    v_receipt_request_sha256 bytea;
    v_receipt_code text;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_receipt_result_id uuid;
    v_request_id uuid;
    v_binding_id uuid;
    v_bumped_users integer;
    v_clock bigint;
    v_result_code text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request decision scope is invalid';
    END IF;
    IF p_operation_id IS NULL OR p_group_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_expected_revision < 1 OR p_expected_state IS DISTINCT FROM 'IN_REVIEW' OR
       p_reviewer_user_id IS NULL OR p_review_task_id IS NULL OR
       p_expected_reviewer_token_version < 1 OR
       p_expected_reviewer_authorization_version < 1 OR
       p_decision NOT IN ('APPROVE', 'REJECT') OR
       pg_catalog.octet_length(p_step_up_purpose_sha256) IS DISTINCT FROM 32 OR
       p_step_up_acr IS DISTINCT FROM 'urn:harpy:acr:step-up' OR
       NOT (p_amr_password OR p_amr_webauthn OR p_amr_totp) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request decision input is invalid';
    END IF;
    SELECT request_group.state, request_group.revision,
           request_group.expires_at, request_group.reviewer_user_id,
           request_group.review_task_id, request_group.step_up_purpose_sha256,
           request_group.reviewer_authority_permission_id
    INTO v_group_state, v_group_revision, v_group_expires_at,
         v_group_reviewer_id, v_group_task_id, v_group_step_up_sha256,
         v_reviewer_permission_id
    FROM iam_permission_request_groups AS request_group
    WHERE request_group.id OPERATOR(pg_catalog.=) p_group_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM permission request group is unknown';
    END IF;
    SELECT reviewer.status, reviewer.token_version,
           reviewer.authorization_version
    INTO v_reviewer_state, v_reviewer_token_version,
         v_reviewer_authorization_version
    FROM iam_users AS reviewer
    WHERE reviewer.id OPERATOR(pg_catalog.=) p_reviewer_user_id
    FOR UPDATE;
    IF NOT FOUND OR v_reviewer_state IS DISTINCT FROM 'active' OR
       v_reviewer_token_version IS DISTINCT FROM p_expected_reviewer_token_version OR
       v_reviewer_authorization_version IS DISTINCT FROM
           p_expected_reviewer_authorization_version OR
       v_group_reviewer_id IS DISTINCT FROM p_reviewer_user_id OR
       v_group_task_id IS DISTINCT FROM p_review_task_id OR
       v_group_step_up_sha256 IS DISTINCT FROM p_step_up_purpose_sha256 OR
       p_step_up_auth_time IS NULL OR p_step_up_auth_time > v_now OR
       p_step_up_auth_time < v_now - INTERVAL '10 minutes' OR
       NOT iam_user_has_permission_v1(
           p_reviewer_user_id, v_reviewer_permission_id
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request decision evidence is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_code,
           receipt.result_revision, receipt.clock_value, receipt.result_id
    INTO v_receipt_command, v_receipt_request_sha256, v_receipt_code,
         v_receipt_revision, v_receipt_clock, v_receipt_result_id
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM
               'iam.permission_request.group_decide' OR
           v_receipt_request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_receipt_result_id IS DISTINCT FROM p_group_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM permission request operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_code, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    IF v_group_state IS DISTINCT FROM p_expected_state OR
       v_group_revision IS DISTINCT FROM p_expected_revision OR
       v_now >= v_group_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM permission request decision CAS is stale';
    END IF;
    PERFORM request.id FROM iam_permission_requests AS request
    WHERE request.group_id = p_group_id
    ORDER BY request.id FOR UPDATE;
    IF p_decision = 'APPROVE' THEN
        FOR v_request_id IN
            SELECT request.id FROM iam_permission_requests AS request
            WHERE request.group_id = p_group_id ORDER BY request.ordinal
        LOOP
            v_binding_id := iam_permission_request_grant_v1(v_request_id, v_now);
        END LOOP;
        v_bumped_users := iam_permission_request_bump_users_v1(p_group_id, v_now);
        v_result_code := 'iam.permission_request.approved';
    ELSE
        v_result_code := 'iam.permission_request.rejected';
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton
    RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM authorization clock is unavailable';
    END IF;
    UPDATE iam_permission_request_groups
    SET state = CASE WHEN p_decision = 'APPROVE' THEN 'APPROVED' ELSE 'REJECTED' END,
        terminal_at = v_now, revision = v_group_revision + 1, updated_at = v_now
    WHERE id = p_group_id;
    UPDATE iam_permission_requests AS request
    SET state = CASE WHEN p_decision = 'APPROVE' THEN 'APPROVED' ELSE 'REJECTED' END,
        granted_binding_id = CASE
            WHEN p_decision = 'APPROVE' THEN planned_binding_id ELSE NULL END,
        terminal_at = v_now, revision = revision + 1, updated_at = v_now
    WHERE request.group_id = p_group_id;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value, result_code,
        result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.permission_request.group_decide', p_request_sha256,
        v_clock, v_result_code, p_group_id, v_group_revision + 1,
        p_request_sha256, v_now
    );
    RETURN QUERY SELECT v_result_code, v_group_revision + 1, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_decide_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_group_id uuid, p_expected_revision bigint, p_expected_state text, p_reviewer_user_id uuid, p_expected_reviewer_token_version bigint, p_expected_reviewer_authorization_version bigint, p_review_task_id uuid, p_decision text, p_step_up_purpose_sha256 bytea, p_step_up_auth_time timestamp with time zone, p_step_up_acr text, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_expire_v1(name, uuid, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_expire_v1(p_scope_schema name, p_group_id uuid, p_expected_revision bigint, p_expected_state text) RETURNS TABLE(group_id uuid, group_state text, group_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_state text;
    v_revision bigint;
    v_expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request expiry scope is invalid';
    END IF;
    IF p_group_id IS NULL OR p_expected_revision < 1 OR
       p_expected_state NOT IN ('PENDING', 'IN_REVIEW') THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request expiry input is invalid';
    END IF;
    SELECT request_group.state, request_group.revision, request_group.expires_at
    INTO v_state, v_revision, v_expires_at
    FROM iam_permission_request_groups AS request_group
    WHERE request_group.id OPERATOR(pg_catalog.=) p_group_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM permission request group is unknown';
    END IF;
    IF v_state IS DISTINCT FROM p_expected_state OR
       v_revision IS DISTINCT FROM p_expected_revision OR v_now < v_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM permission request expiry CAS is stale';
    END IF;
    UPDATE iam_permission_request_groups
    SET state = 'EXPIRED', terminal_at = v_now,
        revision = v_revision + 1, updated_at = v_now
    WHERE id = p_group_id;
    UPDATE iam_permission_requests AS request
    SET state = 'EXPIRED', terminal_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE request.group_id = p_group_id;
    RETURN QUERY SELECT p_group_id, 'EXPIRED'::text, v_revision + 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_expire_v1(p_scope_schema name, p_group_id uuid, p_expected_revision bigint, p_expected_state text) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_grant_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_grant_v1(p_request_id uuid, p_now timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_target_kind text;
    v_target_user_id uuid;
    v_target_role_id uuid;
    v_target_organization_id uuid;
    v_permission_id uuid;
    v_planned_binding_id uuid;
    v_role_is_protected boolean;
BEGIN
    SELECT request.target_kind, request.target_user_id,
           request.target_role_id, request.target_organization_id,
           request.permission_id, request.planned_binding_id
    INTO v_target_kind, v_target_user_id, v_target_role_id,
         v_target_organization_id, v_permission_id, v_planned_binding_id
    FROM iam_permission_requests AS request
    JOIN iam_permissions AS permission ON permission.id = request.permission_id
    WHERE request.id OPERATOR(pg_catalog.=) p_request_id
      AND request.state OPERATOR(pg_catalog.=) 'IN_REVIEW'
      AND permission.match_kind OPERATOR(pg_catalog.=) 'exact'
      AND permission.state OPERATOR(pg_catalog.=) 'active'
    FOR UPDATE OF request;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM permission request grant evidence is stale';
    END IF;
    IF v_target_kind OPERATOR(pg_catalog.=) 'USER' THEN
        IF NOT EXISTS (
            SELECT 1 FROM iam_users AS principal
            WHERE principal.id = v_target_user_id
              AND principal.status = 'active'
        ) OR EXISTS (
            SELECT 1 FROM iam_user_permission_bindings AS binding
            WHERE binding.user_id = v_target_user_id
              AND binding.permission_id = v_permission_id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM permission request user grant is stale';
        END IF;
        INSERT INTO iam_user_permission_bindings (
            id, user_id, permission_id, permission_match_kind, state,
            revision, created_at, updated_at, activated_at, revoked_at
        ) VALUES (
            v_planned_binding_id, v_target_user_id,
            v_permission_id, 'exact', 'active', 1,
            p_now, p_now, p_now, NULL
        );
    ELSIF v_target_kind OPERATOR(pg_catalog.=) 'ROLE' THEN
        SELECT role.is_protected INTO v_role_is_protected
        FROM iam_roles AS role
        WHERE role.id = v_target_role_id AND role.status = 'active'
        FOR UPDATE;
        IF NOT FOUND OR EXISTS (
            SELECT 1 FROM iam_role_permission_bindings AS binding
            WHERE binding.role_id = v_target_role_id
              AND binding.permission_id = v_permission_id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM permission request role grant is stale';
        END IF;
        INSERT INTO iam_role_permission_bindings (
            id, role_id, role_is_protected, permission_id,
            permission_match_kind, state, revision, created_at,
            updated_at, activated_at, revoked_at
        ) VALUES (
            v_planned_binding_id, v_target_role_id,
            v_role_is_protected, v_permission_id, 'exact', 'active',
            1, p_now, p_now, p_now, NULL
        );
    ELSIF v_target_kind OPERATOR(pg_catalog.=) 'ORGANIZATION' THEN
        IF NOT EXISTS (
            SELECT 1 FROM iam_organizations AS organization
            WHERE organization.id = v_target_organization_id
              AND organization.status = 'active'
        ) OR EXISTS (
            SELECT 1 FROM iam_organization_permission_bindings AS binding
            WHERE binding.organization_id = v_target_organization_id
              AND binding.permission_id = v_permission_id
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM permission request organization grant is stale';
        END IF;
        INSERT INTO iam_organization_permission_bindings (
            id, organization_id, permission_id, permission_match_kind,
            state, revision, created_at, updated_at, activated_at, revoked_at
        ) VALUES (
            v_planned_binding_id, v_target_organization_id,
            v_permission_id, 'exact', 'active', 1,
            p_now, p_now, p_now, NULL
        );
    ELSE
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM permission request target kind is invalid';
    END IF;
    RETURN v_planned_binding_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_grant_v1(p_request_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_group_create_v1(name, uuid, uuid, text, uuid, uuid, bigint, bytea, timestamp with time zone, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_group_create_v1(p_scope_schema name, p_group_id uuid, p_requester_user_id uuid, p_request_mode text, p_creator_authority_permission_id uuid, p_reviewer_authority_permission_id uuid, p_expected_authorization_version bigint, p_step_up_purpose_sha256 bytea, p_expires_at timestamp with time zone, p_requests jsonb) RETURNS TABLE(group_id uuid, group_state text, group_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_user_state text;
    v_authorization_version bigint;
    v_request_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request creation scope is invalid';
    END IF;
    IF p_group_id IS NULL OR p_requester_user_id IS NULL OR
       p_request_mode NOT IN ('SELF_SERVICE', 'PRIVILEGED') OR
       p_creator_authority_permission_id IS NULL OR
       p_reviewer_authority_permission_id IS NULL OR
       p_expected_authorization_version < 1 OR
       pg_catalog.octet_length(p_step_up_purpose_sha256) IS DISTINCT FROM 32 OR
       p_expires_at <= v_now OR pg_catalog.jsonb_typeof(p_requests) <> 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request creation input is invalid';
    END IF;
    v_request_count := pg_catalog.jsonb_array_length(p_requests);
    IF v_request_count NOT BETWEEN 1 AND 100 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request group size is invalid';
    END IF;
    SELECT principal.status, principal.authorization_version
    INTO v_user_state, v_authorization_version
    FROM iam_users AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_requester_user_id
    FOR UPDATE;
    IF NOT FOUND OR v_user_state IS DISTINCT FROM 'active' OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM permission request creator evidence is stale';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM iam_permissions AS permission
        WHERE permission.id IN (
            p_creator_authority_permission_id,
            p_reviewer_authority_permission_id
        ) AND permission.match_kind = 'exact' AND permission.is_protected
          AND permission.state = 'active'
        HAVING pg_catalog.count(*) = 2
    ) OR (p_request_mode = 'PRIVILEGED' AND NOT iam_user_has_permission_v1(
        p_requester_user_id, p_creator_authority_permission_id
    )) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request creator authority is denied';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_requests) AS document(value)
        WHERE pg_catalog.jsonb_typeof(document.value) <> 'object' OR
          (SELECT pg_catalog.count(*)
           FROM pg_catalog.jsonb_object_keys(document.value)) <> 6
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request item shape is invalid';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_to_recordset(p_requests) AS item(
            id uuid, ordinal smallint, target_kind text, target_id uuid,
            permission_id uuid, planned_binding_id uuid
        )
        LEFT JOIN iam_permissions AS permission ON permission.id = item.permission_id
        LEFT JOIN iam_users AS target_user
            ON item.target_kind = 'USER' AND target_user.id = item.target_id
        LEFT JOIN iam_roles AS target_role
            ON item.target_kind = 'ROLE' AND target_role.id = item.target_id
        LEFT JOIN iam_organizations AS target_organization
            ON item.target_kind = 'ORGANIZATION' AND
               target_organization.id = item.target_id
        WHERE item.id IS NULL OR item.target_id IS NULL OR
          item.permission_id IS NULL OR item.planned_binding_id IS NULL OR
          item.ordinal NOT BETWEEN 1 AND v_request_count OR
          item.target_kind NOT IN ('USER', 'ROLE', 'ORGANIZATION') OR
          permission.match_kind IS DISTINCT FROM 'exact' OR
          permission.state IS DISTINCT FROM 'active' OR
          (item.target_kind = 'USER' AND target_user.status IS DISTINCT FROM 'active') OR
          (item.target_kind = 'ROLE' AND target_role.status IS DISTINCT FROM 'active') OR
          (item.target_kind = 'ORGANIZATION' AND
              target_organization.status IS DISTINCT FROM 'active') OR
          (p_request_mode = 'SELF_SERVICE' AND (
              item.target_kind <> 'USER' OR
              item.target_id IS DISTINCT FROM p_requester_user_id OR
              permission.is_protected
          ))
    ) OR (SELECT pg_catalog.count(DISTINCT item.ordinal)
          FROM pg_catalog.jsonb_to_recordset(p_requests) AS item(ordinal smallint))
          <> v_request_count THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request item is invalid';
    END IF;
    INSERT INTO iam_permission_request_groups (
        id, requester_user_id, request_mode, creator_authority_permission_id,
        reviewer_authority_permission_id, step_up_purpose_sha256, state,
        request_count, reviewer_user_id, review_task_id, revision, expires_at,
        terminal_at, created_at, updated_at
    ) VALUES (
        p_group_id, p_requester_user_id, p_request_mode,
        p_creator_authority_permission_id, p_reviewer_authority_permission_id,
        p_step_up_purpose_sha256, 'PENDING', v_request_count,
        NULL, NULL, 1, p_expires_at, NULL, v_now, v_now
    );
    INSERT INTO iam_permission_requests (
        id, group_id, ordinal, target_kind, target_user_id, target_role_id,
        target_organization_id, permission_id, permission_match_kind,
        permission_is_protected, planned_binding_id, granted_binding_id,
        state, revision, terminal_at, created_at, updated_at
    )
    SELECT item.id, p_group_id, item.ordinal, item.target_kind,
        CASE WHEN item.target_kind = 'USER' THEN item.target_id END,
        CASE WHEN item.target_kind = 'ROLE' THEN item.target_id END,
        CASE WHEN item.target_kind = 'ORGANIZATION' THEN item.target_id END,
        permission.id, permission.match_kind, permission.is_protected,
        item.planned_binding_id, NULL, 'PENDING', 1, NULL, v_now, v_now
    FROM pg_catalog.jsonb_to_recordset(p_requests) AS item(
        id uuid, ordinal smallint, target_kind text, target_id uuid,
        permission_id uuid, planned_binding_id uuid
    )
    JOIN iam_permissions AS permission ON permission.id = item.permission_id;
    RETURN QUERY SELECT p_group_id, 'PENDING'::text, 1::bigint;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_group_create_v1(p_scope_schema name, p_group_id uuid, p_requester_user_id uuid, p_request_mode text, p_creator_authority_permission_id uuid, p_reviewer_authority_permission_id uuid, p_expected_authorization_version bigint, p_step_up_purpose_sha256 bytea, p_expires_at timestamp with time zone, p_requests jsonb) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_list_v1(name, uuid, jsonb, uuid, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_list_v1(p_scope_schema name, p_actor_user_id uuid, p_states jsonb, p_after uuid, p_limit integer) RETURNS TABLE(group_id uuid, requester_user_id uuid, request_mode text, group_state text, reviewer_user_id uuid, review_task_id uuid, group_revision bigint, expires_at timestamp with time zone, terminal_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, request_documents jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request list scope is invalid';
    END IF;
    IF p_actor_user_id IS NULL OR
       pg_catalog.jsonb_typeof(p_states) IS DISTINCT FROM 'array' OR
       p_limit NOT BETWEEN 1 AND 101 OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_array_elements_text(p_states) AS requested(state)
           WHERE requested.state NOT IN (
               'PENDING', 'IN_REVIEW', 'APPROVED', 'REJECTED',
               'CANCELLED', 'EXPIRED'
           )
       ) OR NOT EXISTS (
           SELECT 1 FROM iam_users AS actor
           WHERE actor.id OPERATOR(pg_catalog.=) p_actor_user_id
             AND actor.status OPERATOR(pg_catalog.=) 'active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request list authority is denied';
    END IF;
    RETURN QUERY
    WITH selected AS (
        SELECT request_group.id
        FROM iam_permission_request_groups AS request_group
        WHERE (p_states OPERATOR(pg_catalog.=) '[]'::jsonb OR
               request_group.state IN (
                   SELECT requested.state
                   FROM pg_catalog.jsonb_array_elements_text(p_states)
                       AS requested(state)
               ))
          AND (p_after IS NULL OR request_group.id OPERATOR(pg_catalog.>) p_after)
          AND (
              request_group.requester_user_id OPERATOR(pg_catalog.=) p_actor_user_id OR
              request_group.reviewer_user_id OPERATOR(pg_catalog.=) p_actor_user_id OR
              iam_user_has_permission_v1(
                  p_actor_user_id,
                  request_group.reviewer_authority_permission_id
              )
          )
        ORDER BY request_group.id
        LIMIT p_limit
    )
    SELECT request_group.id, request_group.requester_user_id,
           request_group.request_mode, request_group.state,
           request_group.reviewer_user_id, request_group.review_task_id,
           request_group.revision, request_group.expires_at,
           request_group.terminal_at, request_group.created_at,
           request_group.updated_at,
           pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'id', request.id, 'ordinal', request.ordinal,
               'target_kind', request.target_kind,
               'target_id', CASE request.target_kind
                   WHEN 'USER' THEN request.target_user_id
                   WHEN 'ROLE' THEN request.target_role_id
                   ELSE request.target_organization_id END,
               'permission_id', request.permission_id,
               'permission_protected', request.permission_is_protected,
               'planned_binding_id', request.planned_binding_id,
               'granted_binding_id', request.granted_binding_id,
               'state', request.state, 'revision', request.revision
           ) ORDER BY request.ordinal)
    FROM selected
    JOIN iam_permission_request_groups AS request_group
      ON request_group.id OPERATOR(pg_catalog.=) selected.id
    JOIN iam_permission_requests AS request
      ON request.group_id OPERATOR(pg_catalog.=) request_group.id
    GROUP BY request_group.id
    ORDER BY request_group.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_list_v1(p_scope_schema name, p_actor_user_id uuid, p_states jsonb, p_after uuid, p_limit integer) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_read_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_read_v1(p_scope_schema name, p_actor_user_id uuid, p_group_id uuid) RETURNS TABLE(group_id uuid, requester_user_id uuid, request_mode text, group_state text, reviewer_user_id uuid, review_task_id uuid, group_revision bigint, expires_at timestamp with time zone, terminal_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, request_documents jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request read scope is invalid';
    END IF;
    IF p_actor_user_id IS NULL OR p_group_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM iam_users AS actor
        WHERE actor.id OPERATOR(pg_catalog.=) p_actor_user_id
          AND actor.status OPERATOR(pg_catalog.=) 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request read authority is denied';
    END IF;
    RETURN QUERY
    SELECT request_group.id, request_group.requester_user_id,
           request_group.request_mode, request_group.state,
           request_group.reviewer_user_id, request_group.review_task_id,
           request_group.revision, request_group.expires_at,
           request_group.terminal_at, request_group.created_at,
           request_group.updated_at,
           pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
               'id', request.id, 'ordinal', request.ordinal,
               'target_kind', request.target_kind,
               'target_id', CASE request.target_kind
                   WHEN 'USER' THEN request.target_user_id
                   WHEN 'ROLE' THEN request.target_role_id
                   ELSE request.target_organization_id END,
               'permission_id', request.permission_id,
               'permission_protected', request.permission_is_protected,
               'planned_binding_id', request.planned_binding_id,
               'granted_binding_id', request.granted_binding_id,
               'state', request.state, 'revision', request.revision
           ) ORDER BY request.ordinal)
    FROM iam_permission_request_groups AS request_group
    JOIN iam_permission_requests AS request
      ON request.group_id OPERATOR(pg_catalog.=) request_group.id
    WHERE request_group.id OPERATOR(pg_catalog.=) p_group_id AND (
        request_group.requester_user_id OPERATOR(pg_catalog.=) p_actor_user_id OR
        request_group.reviewer_user_id OPERATOR(pg_catalog.=) p_actor_user_id OR
        iam_user_has_permission_v1(
            p_actor_user_id, request_group.reviewer_authority_permission_id
        )
    )
    GROUP BY request_group.id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM permission request is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_read_v1(p_scope_schema name, p_actor_user_id uuid, p_group_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_resource_catalog_v1(name, uuid, text, text, uuid, integer, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_resource_catalog_v1(p_scope_schema name, p_actor_user_id uuid, p_kind text, p_search text, p_after uuid, p_limit integer, p_missing_action_key text) RETURNS TABLE(resource_id uuid, resource_key text, display_name text, description text, catalog_kind text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request catalog scope is invalid';
    END IF;
    IF p_actor_user_id IS NULL OR NOT EXISTS (
        SELECT 1
        FROM iam_users AS actor
        WHERE actor.id OPERATOR(pg_catalog.=) p_actor_user_id
          AND actor.status OPERATOR(pg_catalog.=) 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request catalog actor is denied';
    END IF;
    IF p_kind IS NULL OR p_kind NOT IN ('all', 'form', 'system') OR
       p_search IS NULL OR p_search IS DISTINCT FROM pg_catalog.btrim(p_search) OR
       pg_catalog.char_length(p_search) > 128 OR p_limit IS NULL OR
       p_limit NOT BETWEEN 1 AND 101 OR
       (
           p_missing_action_key IS NOT NULL AND (
               pg_catalog.char_length(p_missing_action_key) NOT BETWEEN 1 AND 100 OR
               p_missing_action_key OPERATOR(pg_catalog.!~)
                   '^[a-z][a-z0-9]*([-_][a-z0-9]+)*(\.[a-z][a-z0-9]*([-_][a-z0-9]+)*)*$'
           )
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request catalog query is invalid';
    END IF;
    IF p_missing_action_key IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM iam_permissions AS permission
        JOIN iam_resources AS resource
          ON resource.id OPERATOR(pg_catalog.=) permission.resource_id
        JOIN iam_actions AS action
          ON action.id OPERATOR(pg_catalog.=) permission.action_id
        WHERE permission.match_kind OPERATOR(pg_catalog.=) 'exact'
          AND permission.state OPERATOR(pg_catalog.=) 'active'
          AND NOT permission.is_protected
          AND resource.state OPERATOR(pg_catalog.=) 'active'
          AND NOT resource.is_protected
          AND action.state OPERATOR(pg_catalog.=) 'active'
          AND NOT action.is_protected
          AND action.action_key OPERATOR(pg_catalog.=) p_missing_action_key
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM requestable action was not found';
    END IF;

    IF p_missing_action_key IS NULL THEN
        RETURN QUERY
        SELECT resource.id, resource.resource_key, resource.display_name,
               COALESCE(resource.description, ''),
               CASE WHEN pg_catalog.starts_with(resource.resource_key, 'form.')
                    THEN 'form'::text ELSE 'system'::text END
        FROM iam_resources AS resource
        WHERE resource.state OPERATOR(pg_catalog.=) 'active'
          AND NOT resource.is_protected
          AND (p_after IS NULL OR resource.id OPERATOR(pg_catalog.>) p_after)
          AND (
              p_kind OPERATOR(pg_catalog.=) 'all' OR
              (p_kind OPERATOR(pg_catalog.=) 'form' AND
               pg_catalog.starts_with(resource.resource_key, 'form.')) OR
              (p_kind OPERATOR(pg_catalog.=) 'system' AND
               NOT pg_catalog.starts_with(resource.resource_key, 'form.'))
          )
          AND (
              p_search OPERATOR(pg_catalog.=) '' OR
              pg_catalog.strpos(
                  pg_catalog.lower(pg_catalog.concat_ws(
                      ' ', resource.resource_key, resource.display_name,
                      COALESCE(resource.description, '')
                  )),
                  pg_catalog.lower(p_search)
              ) OPERATOR(pg_catalog.>) 0
          )
          AND EXISTS (
              SELECT 1
              FROM iam_permissions AS permission
              JOIN iam_actions AS action
                ON action.id OPERATOR(pg_catalog.=) permission.action_id
              WHERE permission.resource_id OPERATOR(pg_catalog.=) resource.id
                AND permission.match_kind OPERATOR(pg_catalog.=) 'exact'
                AND permission.state OPERATOR(pg_catalog.=) 'active'
                AND NOT permission.is_protected
                AND action.state OPERATOR(pg_catalog.=) 'active'
                AND NOT action.is_protected
          )
        ORDER BY resource.id
        LIMIT p_limit;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT resource.id, resource.resource_key, resource.display_name,
           COALESCE(resource.description, ''),
           CASE WHEN pg_catalog.starts_with(resource.resource_key, 'form.')
                THEN 'form'::text ELSE 'system'::text END
    FROM iam_permissions AS permission
    JOIN iam_resources AS resource
      ON resource.id OPERATOR(pg_catalog.=) permission.resource_id
    JOIN iam_actions AS action
      ON action.id OPERATOR(pg_catalog.=) permission.action_id
    WHERE permission.match_kind OPERATOR(pg_catalog.=) 'exact'
      AND permission.state OPERATOR(pg_catalog.=) 'active'
      AND NOT permission.is_protected
      AND resource.state OPERATOR(pg_catalog.=) 'active'
      AND NOT resource.is_protected
      AND action.state OPERATOR(pg_catalog.=) 'active'
      AND NOT action.is_protected
      AND action.action_key OPERATOR(pg_catalog.=) p_missing_action_key
      AND (p_after IS NULL OR resource.id OPERATOR(pg_catalog.>) p_after)
      AND (
          p_kind OPERATOR(pg_catalog.=) 'all' OR
          (p_kind OPERATOR(pg_catalog.=) 'form' AND
           pg_catalog.starts_with(resource.resource_key, 'form.')) OR
          (p_kind OPERATOR(pg_catalog.=) 'system' AND
           NOT pg_catalog.starts_with(resource.resource_key, 'form.'))
      )
      AND (
          p_search OPERATOR(pg_catalog.=) '' OR
          pg_catalog.strpos(
              pg_catalog.lower(pg_catalog.concat_ws(
                  ' ', resource.resource_key, resource.display_name,
                  COALESCE(resource.description, '')
              )),
              pg_catalog.lower(p_search)
          ) OPERATOR(pg_catalog.>) 0
      )
      AND NOT iam_user_has_permission_v1(p_actor_user_id, permission.id)
    ORDER BY resource.id
    LIMIT p_limit;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_resource_catalog_v1(p_scope_schema name, p_actor_user_id uuid, p_kind text, p_search text, p_after uuid, p_limit integer, p_missing_action_key text) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_review_v1(name, uuid, bigint, text, uuid, bigint, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_review_v1(p_scope_schema name, p_group_id uuid, p_expected_revision bigint, p_expected_state text, p_reviewer_user_id uuid, p_expected_reviewer_authorization_version bigint, p_review_task_id uuid) RETURNS TABLE(group_id uuid, group_state text, group_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_state text;
    v_revision bigint;
    v_expires_at timestamptz;
    v_reviewer_permission_id uuid;
    v_reviewer_state text;
    v_reviewer_authorization_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request review scope is invalid';
    END IF;
    IF p_group_id IS NULL OR p_expected_revision < 1 OR
       p_expected_state IS DISTINCT FROM 'PENDING' OR
       p_reviewer_user_id IS NULL OR p_review_task_id IS NULL OR
       p_expected_reviewer_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request review input is invalid';
    END IF;
    SELECT request_group.state, request_group.revision,
           request_group.expires_at,
           request_group.reviewer_authority_permission_id,
           reviewer.status, reviewer.authorization_version
    INTO v_state, v_revision, v_expires_at, v_reviewer_permission_id,
         v_reviewer_state, v_reviewer_authorization_version
    FROM iam_permission_request_groups AS request_group
    JOIN iam_users AS reviewer ON reviewer.id = p_reviewer_user_id
    WHERE request_group.id OPERATOR(pg_catalog.=) p_group_id
    FOR UPDATE OF request_group, reviewer;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM permission request group is unknown';
    END IF;
    IF v_state IS DISTINCT FROM p_expected_state OR
       v_revision IS DISTINCT FROM p_expected_revision OR
       v_now >= v_expires_at OR v_reviewer_state IS DISTINCT FROM 'active' OR
       v_reviewer_authorization_version IS DISTINCT FROM
           p_expected_reviewer_authorization_version THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM permission request review CAS is stale';
    END IF;
    IF NOT iam_user_has_permission_v1(
        p_reviewer_user_id, v_reviewer_permission_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request reviewer authority is denied';
    END IF;
    UPDATE iam_permission_request_groups
    SET state = 'IN_REVIEW', reviewer_user_id = p_reviewer_user_id,
        review_task_id = p_review_task_id, revision = v_revision + 1,
        updated_at = v_now
    WHERE id = p_group_id;
    UPDATE iam_permission_requests AS request
    SET state = 'IN_REVIEW', revision = revision + 1, updated_at = v_now
    WHERE request.group_id = p_group_id;
    RETURN QUERY SELECT p_group_id, 'IN_REVIEW'::text, v_revision + 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_review_v1(p_scope_schema name, p_group_id uuid, p_expected_revision bigint, p_expected_state text, p_reviewer_user_id uuid, p_expected_reviewer_authorization_version bigint, p_review_task_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_permission_request_transition_audit_write_v1(name, uuid, bytea, uuid, uuid, uuid, text, text, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_permission_request_transition_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_group_id uuid, p_actor_user_id uuid, p_review_task_id uuid, p_command_key text, p_from_state text, p_to_state text, p_group_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_group_state text;
    v_group_revision bigint;
    v_requester uuid;
    v_reviewer uuid;
    v_review_task uuid;
    v_manage_permission uuid;
    v_actor_active boolean;
    v_clock bigint;
    v_result_code text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM permission request transition audit scope is invalid';
    END IF;
    IF p_operation_id IS NULL OR p_group_id IS NULL OR
       p_actor_user_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       p_group_revision < 1 OR p_command_key NOT IN (
           'iam.permission_request.create',
           'iam.permission_request.review',
           'iam.permission_request.cancel',
           'iam.permission_request.expire'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM permission request transition evidence is invalid';
    END IF;
    SELECT request_group.state, request_group.revision,
           request_group.requester_user_id, request_group.reviewer_user_id,
           request_group.review_task_id,
           request_group.creator_authority_permission_id
    INTO v_group_state, v_group_revision, v_requester, v_reviewer,
         v_review_task, v_manage_permission
    FROM iam_permission_request_groups AS request_group
    WHERE request_group.id = p_group_id;
    SELECT true INTO v_actor_active
    FROM iam_users AS actor
    WHERE actor.id = p_actor_user_id AND actor.status = 'active';
    IF v_group_state IS DISTINCT FROM p_to_state OR
       v_group_revision IS DISTINCT FROM p_group_revision OR
       v_actor_active IS DISTINCT FROM true OR
       (p_command_key = 'iam.permission_request.create' AND (
           p_from_state IS NOT NULL OR p_to_state <> 'PENDING' OR
           p_group_revision <> 1 OR p_review_task_id IS NOT NULL OR
           v_requester IS DISTINCT FROM p_actor_user_id)) OR
       (p_command_key = 'iam.permission_request.review' AND (
           p_from_state <> 'PENDING' OR p_to_state <> 'IN_REVIEW' OR
           p_review_task_id IS NULL OR
           v_reviewer IS DISTINCT FROM p_actor_user_id OR
           v_review_task IS DISTINCT FROM p_review_task_id)) OR
       (p_command_key = 'iam.permission_request.cancel' AND (
           p_from_state NOT IN ('PENDING', 'IN_REVIEW') OR
           p_to_state <> 'CANCELLED' OR p_review_task_id IS NOT NULL OR
           v_requester IS DISTINCT FROM p_actor_user_id)) OR
       (p_command_key = 'iam.permission_request.expire' AND (
           p_from_state NOT IN ('PENDING', 'IN_REVIEW') OR
           p_to_state <> 'EXPIRED' OR p_review_task_id IS NOT NULL OR
           NOT iam_user_has_permission_v1(
               p_actor_user_id, v_manage_permission
           ))) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM permission request transition evidence is stale';
    END IF;
    SELECT clock_value INTO v_clock
    FROM iam_authorization_clock
    WHERE singleton;
    IF v_clock IS NULL OR v_clock < 0 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM authorization clock is unavailable';
    END IF;
    v_result_code := CASE p_command_key
        WHEN 'iam.permission_request.create'
            THEN 'iam.permission_request.created'
        WHEN 'iam.permission_request.review'
            THEN 'iam.permission_request.reviewed'
        WHEN 'iam.permission_request.cancel'
            THEN 'iam.permission_request.cancelled'
        ELSE 'iam.permission_request.expired'
    END;
    INSERT INTO iam_permission_request_transition_receipts (
        operation_id, command_key, request_sha256, result_code,
        result_id, result_revision, created_at
    ) VALUES (
        p_operation_id, p_command_key, p_request_sha256, v_result_code,
        p_group_id, p_group_revision,
        pg_catalog.transaction_timestamp()
    );
    INSERT INTO iam_permission_request_transition_audit (
        operation_id, group_id, actor_user_id, review_task_id, command_key,
        from_state, to_state, request_sha256, group_revision,
        authorization_clock, recorded_at
    ) VALUES (
        p_operation_id, p_group_id, p_actor_user_id, p_review_task_id,
        p_command_key, p_from_state, p_to_state, p_request_sha256,
        p_group_revision, v_clock, pg_catalog.transaction_timestamp()
    );
    RETURN v_clock;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_permission_request_transition_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_group_id uuid, p_actor_user_id uuid, p_review_task_id uuid, p_command_key text, p_from_state text, p_to_state text, p_group_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_platform_authorize_v1(name, uuid, bigint, bigint, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_platform_authorize_v1(p_scope_schema name, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint, p_capability text) RETURNS TABLE(allowed boolean, capability_key text, deployment_mode text, subject_id uuid, platform_clock bigint, authorization_version bigint, reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_auth_version bigint;
    v_token_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_actor_id IS NULL OR p_expected_token_version < 1 OR
       p_expected_authorization_version < 1 OR p_expected_platform_clock < 1 OR
       p_capability !~ '^platform\.' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Platform authorization input is invalid';
    END IF;
    SELECT identity.tenant_id, principal.authorization_version,
           principal.token_version
    INTO v_tenant_id, v_auth_version, v_token_version
    FROM tenancy_schema_identity AS identity
    JOIN iam_users AS principal ON principal.id = p_actor_id
      AND principal.status = 'active' AND principal.identity_kind = 'human'
    WHERE identity.singleton;
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Platform authorization requires an active user';
    END IF;
    IF v_token_version <> p_expected_token_version OR
       v_auth_version <> p_expected_authorization_version THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'Platform authorization identity evidence is stale';
    END IF;
    RETURN QUERY
    SELECT decision.allowed, p_capability, decision.deployment_mode,
           decision.subject_id, decision.platform_clock, v_auth_version,
           decision.reason
    FROM platform.iam_platform_authorize_decide_v1(
        v_tenant_id, p_actor_id, p_expected_platform_clock, p_capability
    ) AS decision;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_platform_authorize_v1(p_scope_schema name, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint, p_capability text) OWNER TO harpy_owner;

--
-- Name: iam_platform_operator_grant_v1(name, uuid, bytea, uuid, bigint, bigint, bigint, bytea, timestamp with time zone, text, boolean, boolean, boolean, uuid, bigint, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_platform_operator_grant_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_acr text, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean, p_target_user_id uuid, p_target_expected_authorization_version bigint, p_subject_id uuid, p_role_id uuid, p_subject_role_binding_id uuid, p_role_permission_binding_id uuid, p_capability text) RETURNS TABLE(target_user_id uuid, subject_id uuid, role_id uuid, subject_role_binding_id uuid, role_permission_binding_id uuid, target_authorization_version bigint, platform_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_target_current_version bigint;
    v_subject_id uuid;
    v_role_id uuid;
    v_subject_role_id uuid;
    v_role_permission_id uuid;
    v_target_result_version bigint;
    v_platform_clock bigint;
    v_replayed boolean;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_actor_id IS NULL OR p_target_user_id IS NULL OR p_actor_id = p_target_user_id OR
       p_target_expected_authorization_version < 1 OR p_subject_id IS NULL OR
       p_role_id IS NULL OR p_subject_role_binding_id IS NULL OR
       p_role_permission_binding_id IS NULL OR p_capability !~ '^platform\.' OR
       pg_catalog.octet_length(p_purpose_sha256) <> 32 OR
       p_acr <> 'urn:harpy:acr:step-up' OR
       NOT (p_amr_password OR p_amr_webauthn OR p_amr_totp) OR
       p_auth_time > v_now OR p_auth_time < v_now - INTERVAL '10 minutes' OR
       p_purpose_sha256 <> pg_catalog.sha256(pg_catalog.convert_to(
           'platform.operators.grant' || E'\n' || p_target_user_id::text ||
           E'\n' || p_capability, 'UTF8')) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Platform operator grant input is invalid';
    END IF;
    SELECT identity.tenant_id INTO v_tenant_id
    FROM tenancy_schema_identity AS identity WHERE identity.singleton;
    PERFORM 1 FROM iam_users AS principal
    WHERE principal.id = p_actor_id AND principal.status = 'active'
      AND principal.identity_kind = 'human'
      AND principal.token_version = p_expected_token_version
      AND principal.authorization_version = p_expected_authorization_version
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'Platform owner identity evidence is stale';
    END IF;
    SELECT principal.authorization_version INTO v_target_current_version
    FROM iam_users AS principal
    WHERE principal.id = p_target_user_id AND principal.status = 'active'
      AND principal.identity_kind = 'human'
      AND principal.authorization_version IN (
          p_target_expected_authorization_version,
          p_target_expected_authorization_version + 1
      )
    FOR UPDATE;
    IF v_tenant_id IS NULL OR v_target_current_version IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P1404',
            MESSAGE = 'Platform operator target is not an active primary user';
    END IF;

    SELECT result.subject_id, result.role_id, result.subject_role_binding_id,
           result.role_permission_binding_id, result.target_authorization_version,
           result.platform_clock, result.replayed
    INTO v_subject_id, v_role_id, v_subject_role_id, v_role_permission_id,
         v_target_result_version, v_platform_clock, v_replayed
    FROM platform.iam_platform_operator_grant_apply_v1(
        v_tenant_id, p_operation_id, p_request_sha256, p_actor_id,
        p_target_user_id, p_target_expected_authorization_version + 1,
        p_expected_platform_clock, p_subject_id, p_role_id,
        p_subject_role_binding_id, p_role_permission_binding_id, p_capability
    ) AS result;

    IF v_replayed THEN
        IF v_target_current_version <> v_target_result_version THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'Platform operator grant replay identity is stale';
        END IF;
    ELSE
        IF v_target_current_version <> p_target_expected_authorization_version THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'Platform operator grant target changed';
        END IF;
        UPDATE iam_users SET authorization_version = v_target_result_version,
            revision = revision + 1, updated_at = v_now
        WHERE id = p_target_user_id
          AND authorization_version = p_target_expected_authorization_version;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'Platform operator grant target changed';
        END IF;
    END IF;
    RETURN QUERY SELECT p_target_user_id, v_subject_id, v_role_id,
        v_subject_role_id, v_role_permission_id, v_target_result_version,
        v_platform_clock, v_replayed;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_platform_operator_grant_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_acr text, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean, p_target_user_id uuid, p_target_expected_authorization_version bigint, p_subject_id uuid, p_role_id uuid, p_subject_role_binding_id uuid, p_role_permission_binding_id uuid, p_capability text) OWNER TO harpy_owner;

--
-- Name: iam_platform_operator_revoke_v1(name, uuid, bytea, uuid, bigint, bigint, bigint, bytea, timestamp with time zone, text, boolean, boolean, boolean, uuid, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_platform_operator_revoke_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_acr text, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean, p_target_user_id uuid, p_target_expected_authorization_version bigint, p_capability text) RETURNS TABLE(target_user_id uuid, subject_id uuid, role_id uuid, subject_role_binding_id uuid, role_permission_binding_id uuid, target_authorization_version bigint, platform_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_target_current_version bigint;
    v_subject_id uuid;
    v_role_id uuid;
    v_subject_role_id uuid;
    v_role_permission_id uuid;
    v_target_result_version bigint;
    v_platform_clock bigint;
    v_replayed boolean;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR pg_catalog.octet_length(p_request_sha256) <> 32 OR
       p_actor_id IS NULL OR p_target_user_id IS NULL OR p_actor_id = p_target_user_id OR
       p_target_expected_authorization_version < 1 OR p_capability !~ '^platform\.' OR
       pg_catalog.octet_length(p_purpose_sha256) <> 32 OR
       p_acr <> 'urn:harpy:acr:step-up' OR
       NOT (p_amr_password OR p_amr_webauthn OR p_amr_totp) OR
       p_auth_time > v_now OR p_auth_time < v_now - INTERVAL '10 minutes' OR
       p_purpose_sha256 <> pg_catalog.sha256(pg_catalog.convert_to(
           'platform.operators.revoke' || E'\n' || p_target_user_id::text ||
           E'\n' || p_capability, 'UTF8')) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Platform operator revoke input is invalid';
    END IF;
    SELECT identity.tenant_id INTO v_tenant_id
    FROM tenancy_schema_identity AS identity WHERE identity.singleton;
    PERFORM 1 FROM iam_users AS principal
    WHERE principal.id = p_actor_id AND principal.status = 'active'
      AND principal.identity_kind = 'human'
      AND principal.token_version = p_expected_token_version
      AND principal.authorization_version = p_expected_authorization_version
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'Platform owner identity evidence is stale';
    END IF;
    SELECT principal.authorization_version INTO v_target_current_version
    FROM iam_users AS principal
    WHERE principal.id = p_target_user_id AND principal.status = 'active'
      AND principal.identity_kind = 'human'
      AND principal.authorization_version IN (
          p_target_expected_authorization_version,
          p_target_expected_authorization_version + 1
      )
    FOR UPDATE;
    IF v_tenant_id IS NULL OR v_target_current_version IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P1404',
            MESSAGE = 'Platform operator target is not an active primary user';
    END IF;

    SELECT result.subject_id, result.role_id, result.subject_role_binding_id,
           result.role_permission_binding_id, result.target_authorization_version,
           result.platform_clock, result.replayed
    INTO v_subject_id, v_role_id, v_subject_role_id, v_role_permission_id,
         v_target_result_version, v_platform_clock, v_replayed
    FROM platform.iam_platform_operator_revoke_apply_v1(
        v_tenant_id, p_operation_id, p_request_sha256, p_actor_id,
        p_target_user_id, p_target_expected_authorization_version + 1,
        p_expected_platform_clock, p_capability
    ) AS result;

    IF v_replayed THEN
        IF v_target_current_version <> v_target_result_version THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'Platform operator revoke replay identity is stale';
        END IF;
    ELSE
        IF v_target_current_version <> p_target_expected_authorization_version THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'Platform operator revoke target changed';
        END IF;
        UPDATE iam_users SET authorization_version = v_target_result_version,
            revision = revision + 1, updated_at = v_now
        WHERE id = p_target_user_id
          AND authorization_version = p_target_expected_authorization_version;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'Platform operator revoke target changed';
        END IF;
    END IF;
    RETURN QUERY SELECT p_target_user_id, v_subject_id, v_role_id,
        v_subject_role_id, v_role_permission_id, v_target_result_version,
        v_platform_clock, v_replayed;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_platform_operator_revoke_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_platform_clock bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_acr text, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean, p_target_user_id uuid, p_target_expected_authorization_version bigint, p_capability text) OWNER TO harpy_owner;

--
-- Name: iam_platform_owner_user_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_platform_owner_user_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_tenant_id uuid;
BEGIN
    v_user_id := OLD.id;
    IF TG_OP = 'UPDATE' AND (
       OLD.status IS NOT DISTINCT FROM NEW.status OR NEW.status = 'active') THEN
        RETURN NEW;
    END IF;

    SELECT identity.tenant_id INTO v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton;

    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_platform_owner_user_scope_guard',
            MESSAGE = 'IAM platform owner user scope is unavailable';
    END IF;

    IF platform.iam_platform_current_owner_v1(v_tenant_id, v_user_id) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_platform_owner_user_lifecycle_guard',
            MESSAGE = 'Current Instance Owner requires a completed successor transfer';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_platform_owner_user_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_platform_session_context_v1(name, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_platform_session_context_v1(p_scope_schema name, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(deployment_mode text, tenant_purpose text, subject_id uuid, platform_clock bigint, authorization_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_auth_version bigint;
    v_token_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_actor_id IS NULL OR p_expected_token_version < 1 OR
       p_expected_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Platform session context input is invalid';
    END IF;
    SELECT identity.tenant_id, principal.authorization_version,
           principal.token_version
    INTO v_tenant_id, v_auth_version, v_token_version
    FROM tenancy_schema_identity AS identity
    JOIN iam_users AS principal ON principal.id = p_actor_id
      AND principal.status = 'active' AND principal.identity_kind = 'human'
    WHERE identity.singleton;
    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Platform session context is unavailable';
    END IF;
    IF v_token_version <> p_expected_token_version OR
       v_auth_version <> p_expected_authorization_version THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'Platform session identity evidence is stale';
    END IF;
    RETURN QUERY
    SELECT context.deployment_mode, context.tenant_purpose,
           context.subject_id, context.platform_clock, v_auth_version
    FROM platform.iam_platform_session_context_read_v1(
        v_tenant_id, p_actor_id
    ) AS context;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_platform_session_context_v1(p_scope_schema name, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_access_verify_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_access_verify_v1(p_scope_schema name, p_tenant_id uuid, p_principal_id uuid, p_binding_id uuid, p_token_version bigint, p_authorization_version bigint) RETURNS TABLE(principal_id uuid, binding_id uuid, tenant_id uuid, token_version bigint, authorization_version bigint, authorization_clock bigint, binding_revision bigint, subject_type text, form_id uuid, form_version_id uuid, subject_record_id uuid, identifier_field_id uuid, role_names text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_principal_id IS NULL OR p_binding_id IS NULL OR
       p_token_version<1 OR p_authorization_version<1 OR
       NOT EXISTS(SELECT 1 FROM tenancy_schema_identity identity_row
          WHERE identity_row.singleton AND identity_row.tenant_id=p_tenant_id
            AND identity_row.schema_name=p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE='42501';
    END IF;
    RETURN QUERY
    SELECT subject.id,binding.id,p_tenant_id,subject.token_version,
      subject.authorization_version,clock.clock_value,binding.revision,
      binding.subject_type,binding.profile_form_id,binding.profile_form_version_id,
      binding.subject_record_id,binding.identifier_field_id,
      (SELECT pg_catalog.array_agg(role.name ORDER BY role.name)
       FROM iam_portal_role_assignments portal_role
       JOIN iam_roles role ON role.id=portal_role.role_id AND role.status='active'
       JOIN iam_user_role_assignments assignment
         ON assignment.id=portal_role.assignment_id AND assignment.state='active'
       WHERE portal_role.binding_id=binding.id)
    FROM iam_users subject
    JOIN iam_portal_subject_bindings binding ON binding.user_id=subject.id
      AND binding.id=p_binding_id AND binding.state='active'
    JOIN iam_user_access_modes access ON access.id=binding.access_mode_id
      AND access.user_id=subject.id AND access.mode='portal' AND access.state='active'
    JOIN iam_portal_access_setups setup ON setup.binding_id=binding.id
      AND setup.setup_state='completed'
      AND setup.approval_state IN('not_required','approved')
    JOIN iam_user_identifiers identifier ON identifier.user_id=subject.id
      AND identifier.kind='portal_v1' AND identifier.state='active'
    CROSS JOIN iam_authorization_clock clock
    WHERE subject.id=p_principal_id AND subject.status='active'
      AND subject.token_version=p_token_version
      AND subject.authorization_version=p_authorization_version
      AND clock.singleton AND clock.clock_value>0;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',
      MESSAGE='IAM portal access is not current'; END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_access_verify_v1(p_scope_schema name, p_tenant_id uuid, p_principal_id uuid, p_binding_id uuid, p_token_version bigint, p_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_approval_decide_v1(name, uuid, uuid, bytea, uuid, bigint, text, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_approval_decide_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_binding_id uuid, p_expected_revision bigint, p_decision text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_access_mode_id uuid;
    v_revision bigint;
    v_identifier_id uuid;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_binding_id IS NULL OR p_expected_revision < 1 OR
       p_decision NOT IN ('approved', 'rejected', 'revision_required') OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.portal_approval.decide',
        p_request_sha256, p_binding_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT setup.user_id, setup.access_mode_id, setup.revision
    INTO v_user_id, v_access_mode_id, v_revision
    FROM iam_portal_access_setups AS setup
    WHERE setup.binding_id = p_binding_id AND setup.revision = p_expected_revision
      AND setup.setup_state = 'completed' AND setup.approval_state = 'pending'
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '40001'; END IF;
    UPDATE iam_portal_access_setups SET approval_state = p_decision,
        decision_at = v_now, decision_actor_id = p_actor_id,
        revision = revision + 1, updated_at = v_now
    WHERE binding_id = p_binding_id RETURNING revision INTO v_revision;
    IF p_decision = 'approved' THEN
        UPDATE iam_portal_subject_bindings SET state = 'active',
            activated_at = COALESCE(activated_at, v_now),
            suspended_at = NULL, revision = revision + 1, updated_at = v_now
        WHERE id = p_binding_id AND state IN ('pending', 'suspended');
        UPDATE iam_user_access_modes SET state = 'active',
            activated_at = COALESCE(activated_at, v_now),
            suspended_at = NULL, revision = revision + 1, updated_at = v_now
        WHERE id = v_access_mode_id AND state IN ('pending', 'suspended');
        SELECT identifier.id INTO v_identifier_id
        FROM iam_user_identifiers AS identifier
        WHERE identifier.user_id = v_user_id AND identifier.kind = 'portal_v1'
          AND identifier.state IN ('pending', 'verified', 'active') FOR UPDATE;
        UPDATE iam_user_identifiers SET state = 'active',
            verified_at = COALESCE(verified_at, v_now),
            activated_at = COALESCE(activated_at, v_now),
            revision = revision + 1, updated_at = v_now
        WHERE id = v_identifier_id AND state <> 'active';
        UPDATE iam_users SET status = 'active', revision = revision + 1,
            updated_at = v_now WHERE id = v_user_id AND status = 'pending';
    END IF;
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.portal_approval.decide', p_request_sha256,
        p_binding_id, v_user_id, v_revision,
        'actor_tenant', p_actor_id, 'portal_approval', true, true
    ) AS result;
    RETURN QUERY SELECT p_binding_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_approval_decide_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_binding_id uuid, p_expected_revision bigint, p_decision text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_authorization_evidence_read_v1(name, uuid, uuid, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_authorization_evidence_read_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_resource_key text, p_action_key text) RETURNS TABLE(actor_document jsonb, resource_document jsonb, action_document jsonb, authorization_clock bigint, bindings_document jsonb, implications_document jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_actor_id IS NULL OR p_resource_key IS NULL OR p_action_key IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501';
    END IF;
    RETURN QUERY
    SELECT evidence.actor_document,evidence.resource_document,evidence.action_document,
      evidence.authorization_clock,
      COALESCE((
        SELECT pg_catalog.jsonb_agg(binding_element ORDER BY binding_element->>'binding_id')
        FROM pg_catalog.jsonb_array_elements(evidence.bindings_document) binding_element
        WHERE binding_element->>'path'='role' AND EXISTS(
          SELECT 1 FROM iam_portal_role_assignments portal_role
          JOIN iam_portal_subject_bindings portal_binding
            ON portal_binding.id=portal_role.binding_id
            AND portal_binding.user_id=portal_role.user_id
          JOIN iam_user_access_modes portal_access
            ON portal_access.id=portal_binding.access_mode_id
            AND portal_access.user_id=portal_binding.user_id
          JOIN iam_portal_access_setups portal_setup
            ON portal_setup.binding_id=portal_binding.id
          WHERE portal_role.user_id=p_actor_id
            AND portal_role.assignment_id=(binding_element->>'assignment_id')::uuid
            AND portal_binding.state='active' AND portal_access.state='active'
            AND portal_setup.setup_state='completed'
            AND portal_setup.approval_state IN('not_required','approved')
        )
      ),'[]'::jsonb),
      evidence.implications_document
    FROM iam_authorization_evidence_read_v3(
      p_scope_schema,p_tenant_id,p_actor_id,p_resource_key,p_action_key
    ) evidence;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_authorization_evidence_read_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_resource_key text, p_action_key text) OWNER TO harpy_owner;

--
-- Name: iam_portal_setup_complete_v1(name, uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_setup_complete_v1(p_scope_schema name, p_binding_id uuid, p_expected_setup_revision bigint, p_token_id uuid, p_expected_token_revision bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_setup_state text;
    v_setup_revision bigint;
    v_user_id uuid;
    v_token_state text;
    v_token_revision bigint;
    v_token_user_id uuid;
    v_token_binding_id uuid;
    v_token_setup_revision bigint;
    v_token_expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM portal setup completion scope is invalid';
    END IF;
    SELECT setup.setup_state, setup.revision, setup.user_id
    INTO v_setup_state, v_setup_revision, v_user_id
    FROM iam_portal_access_setups AS setup
    WHERE setup.binding_id OPERATOR(pg_catalog.=) p_binding_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM portal setup is unknown';
    END IF;
    SELECT token.state, token.revision, token.user_id,
           token.portal_binding_id, token.portal_setup_revision,
           token.expires_at
    INTO v_token_state, v_token_revision, v_token_user_id,
         v_token_binding_id, v_token_setup_revision, v_token_expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
      AND token.purpose OPERATOR(pg_catalog.=) 'portal_setup_v1'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM portal setup token is unknown';
    END IF;
    IF v_setup_state IS DISTINCT FROM 'required' OR
       v_setup_revision IS DISTINCT FROM p_expected_setup_revision OR
       v_token_state IS DISTINCT FROM 'pending' OR
       v_token_revision IS DISTINCT FROM p_expected_token_revision OR
       v_token_user_id IS DISTINCT FROM v_user_id OR
       v_token_binding_id IS DISTINCT FROM p_binding_id OR
       v_token_setup_revision IS DISTINCT FROM p_expected_setup_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM portal setup completion CAS is stale';
    END IF;
    IF v_now OPERATOR(pg_catalog.>=) v_token_expires_at THEN
        UPDATE iam_one_time_tokens
        SET state = 'expired', expired_at = v_token_expires_at,
            updated_at = v_now,
            revision = v_token_revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_token_id;
        RETURN 'expired';
    END IF;
    UPDATE iam_portal_access_setups
    SET setup_state = 'completed', setup_completed_at = v_now,
        updated_at = v_now,
        revision = v_setup_revision OPERATOR(pg_catalog.+) 1
    WHERE binding_id OPERATOR(pg_catalog.=) p_binding_id;
    UPDATE iam_one_time_tokens
    SET state = 'consumed', consumed_at = v_now, updated_at = v_now,
        revision = v_token_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_token_id;
    RETURN 'completed';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_setup_complete_v1(p_scope_schema name, p_binding_id uuid, p_expected_setup_revision bigint, p_token_id uuid, p_expected_token_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_setup_complete_v2(name, uuid, uuid, bytea, bytea, text, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_setup_complete_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_salt bytea, p_tag bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_token_id uuid;
    v_user_id uuid;
    v_binding_id uuid;
    v_identifier_id uuid;
    v_portal_setup_revision bigint;
    v_token_state text;
    v_expires_at timestamptz;
    v_access_mode_id uuid;
    v_approval_state text;
    v_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       p_hash_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_binding_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_salt) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_tag) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.portal_setup.complete', p_request_sha256, NULL
    );
    IF FOUND THEN RETURN; END IF;
    SELECT token.id, token.user_id, token.portal_binding_id,
        token.identifier_id, token.portal_setup_revision,
        token.state, token.expires_at
    INTO v_token_id, v_user_id, v_binding_id, v_identifier_id,
        v_portal_setup_revision, v_token_state, v_expires_at
    FROM iam_one_time_tokens AS token
    WHERE token.purpose = 'portal_setup_v1' AND token.selector = p_selector
      AND token.hash_key_id = p_hash_key_id AND token.secret_hmac = p_secret_hmac
      AND token.binding_sha256 = p_binding_sha256 FOR UPDATE;
    IF NOT FOUND OR v_token_state <> 'pending' OR v_expires_at <= v_now THEN
        RAISE EXCEPTION USING ERRCODE = '28000';
    END IF;
    SELECT setup.access_mode_id, setup.approval_state
    INTO v_access_mode_id, v_approval_state
    FROM iam_portal_access_setups AS setup
    WHERE setup.binding_id = v_binding_id AND setup.user_id = v_user_id
      AND setup.revision = v_portal_setup_revision
      AND setup.setup_state = 'required' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '40001'; END IF;
    INSERT INTO iam_password_credentials (
        user_id, credential_version, state, algorithm, salt, tag,
        memory_kib, iterations, parallelism, upgrade_required,
        revision, created_at, updated_at
    ) VALUES (
        v_user_id, 1, 'active', 'argon2id_v1', p_salt, p_tag,
        65536, 3, 4, false, 1, v_now, v_now
    ) ON CONFLICT (user_id) DO UPDATE SET
        credential_version = iam_password_credentials.credential_version + 1,
        state = 'active', algorithm = 'argon2id_v1', salt = EXCLUDED.salt,
        tag = EXCLUDED.tag, memory_kib = 65536, iterations = 3,
        parallelism = 4, legacy_bcrypt_hash = NULL, upgrade_required = false,
        revision = iam_password_credentials.revision + 1,
        updated_at = v_now, invalidated_at = NULL;
    UPDATE iam_portal_access_setups SET setup_state = 'completed',
        setup_completed_at = v_now,
        approval_state = CASE WHEN approval_state = 'not_submitted'
            THEN 'pending' ELSE approval_state END,
        approval_revision = CASE WHEN approval_state = 'not_submitted'
            THEN approval_revision + 1 ELSE approval_revision END,
        submitted_at = CASE WHEN approval_state = 'not_submitted'
            THEN v_now ELSE submitted_at END,
        revision = revision + 1, updated_at = v_now
    WHERE binding_id = v_binding_id RETURNING revision INTO v_revision;
    IF v_approval_state = 'not_required' THEN
        UPDATE iam_portal_subject_bindings SET state = 'active',
            activated_at = v_now, revision = revision + 1, updated_at = v_now
        WHERE id = v_binding_id AND state = 'pending';
        UPDATE iam_user_access_modes SET state = 'active', activated_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE id = v_access_mode_id AND state = 'pending';
        UPDATE iam_user_identifiers SET state = 'active',
            verified_at = COALESCE(verified_at, v_now), activated_at = v_now,
            revision = revision + 1, updated_at = v_now
        WHERE id = v_identifier_id AND state IN ('pending', 'verified');
        UPDATE iam_users SET status = 'active', revision = revision + 1,
            updated_at = v_now WHERE id = v_user_id AND status = 'pending';
    END IF;
    UPDATE iam_one_time_tokens SET state = 'consumed', consumed_at = v_now,
        revision = revision + 1, updated_at = v_now WHERE id = v_token_id;
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.portal_setup.complete', p_request_sha256,
        v_binding_id, v_user_id, v_revision,
        'credential_target', v_user_id, 'portal_setup', true, true
    ) AS result;
    RETURN QUERY SELECT v_binding_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_portal_setup_complete_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_salt bytea, p_tag bytea) OWNER TO harpy_owner;

--
-- Name: iam_portal_setup_delivery_target_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_setup_delivery_target_v1(p_scope_schema name, p_binding_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(subject_user_id uuid, resource_id uuid, recipient_identifier_id uuid, recipient_address text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT iam_identity_actor_assert_v1(
           p_scope_schema, p_actor_id, p_permission_id,
           p_expected_token_version, p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM portal setup delivery target is denied';
    END IF;
    RETURN QUERY
    SELECT setup.user_id, setup.binding_id, recipient.id,
           recipient.normalized_value
    FROM iam_portal_access_setups AS setup
    JOIN iam_portal_subject_bindings AS binding
      ON binding.id = setup.binding_id AND binding.user_id = setup.user_id
    JOIN iam_users AS subject
      ON subject.id = setup.user_id AND subject.status = 'active'
    JOIN iam_user_identifiers AS recipient
      ON recipient.user_id = setup.user_id
     AND recipient.kind = 'email_v1' AND recipient.state = 'active'
    WHERE setup.binding_id = p_binding_id
      AND setup.setup_state = 'required' AND binding.state = 'pending';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM portal setup target is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_setup_delivery_target_v1(p_scope_schema name, p_binding_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_setup_read_v1(name, uuid, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_setup_read_v1(p_scope_schema name, p_tenant_id uuid, p_binding_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(binding_id uuid, user_id uuid, setup_state text, approval_state text, result_revision bigint, setup_completed_at timestamp with time zone, submitted_at timestamp with time zone, decision_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_tenant_id IS NULL OR p_binding_id IS NULL OR
       NOT EXISTS (
          SELECT 1
          FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id
            AND tenant.schema_name::text IS NOT DISTINCT FROM p_scope_schema::text
       ) OR NOT iam_identity_query_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM portal setup query authority is denied';
    END IF;

    RETURN QUERY
    SELECT setup.binding_id, setup.user_id, setup.setup_state,
        setup.approval_state, setup.revision, setup.setup_completed_at,
        setup.submitted_at, setup.decision_at, setup.updated_at
    FROM iam_portal_access_setups AS setup
    WHERE setup.binding_id = p_binding_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM portal setup was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_setup_read_v1(p_scope_schema name, p_tenant_id uuid, p_binding_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_setup_start_v1(name, uuid, uuid, bytea, uuid, uuid, bytea, text, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_setup_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_binding_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_setup_revision bigint;
    v_identifier_id uuid;
    v_identifier_kind text;
    v_identifier_revision bigint;
    v_issue bigint;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF p_token_id IS NULL OR p_binding_id IS NULL OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.portal_setup.start', p_request_sha256, p_token_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT setup.user_id, setup.revision
    INTO v_user_id, v_setup_revision
    FROM iam_portal_access_setups AS setup
    JOIN iam_portal_subject_bindings AS binding
      ON binding.id = setup.binding_id AND binding.user_id = setup.user_id
    WHERE setup.binding_id = p_binding_id AND setup.setup_state = 'required'
      AND binding.state = 'pending' FOR UPDATE OF setup, binding;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '23503'; END IF;
    SELECT identifier.id, identifier.kind, identifier.revision
    INTO v_identifier_id, v_identifier_kind, v_identifier_revision
    FROM iam_user_identifiers AS identifier
    WHERE identifier.user_id = v_user_id AND identifier.kind = 'portal_v1'
      AND identifier.state IN ('pending', 'verified', 'active') FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '23503'; END IF;
    v_issue := iam_one_time_issue_v1(
        p_token_id, 'portal_setup_v1', v_user_id, v_identifier_id,
        v_identifier_kind, v_identifier_revision, p_binding_id,
        v_setup_revision, p_selector, p_hash_key_id, p_secret_hmac,
        p_binding_sha256
    );
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.portal_setup.start', p_request_sha256,
        p_token_id, v_user_id, 1, 'actor_tenant', p_actor_id,
        'one_time_token', false, false
    ) AS result;
    RETURN QUERY SELECT p_token_id, v_user_id, 1::bigint,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_setup_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_binding_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_setup_start_v2(name, uuid, uuid, bytea, uuid, uuid, bytea, text, bytea, bytea, uuid, uuid, bigint, bigint, uuid, uuid, uuid, uuid, text, text, bytea, bytea, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_setup_start_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_binding_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_artifact_id uuid, p_subject_user_id uuid, p_resource_id uuid, p_recipient_identifier_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_result_id uuid; v_subject_user_id uuid; v_result_revision bigint;
    v_token_version bigint; v_authorization_version bigint;
    v_replayed boolean; v_insert bigint;
BEGIN
    SELECT started.result_id, started.subject_user_id, started.result_revision,
           started.token_version, started.authorization_version, started.replayed
    INTO v_result_id, v_subject_user_id, v_result_revision,
         v_token_version, v_authorization_version, v_replayed
    FROM iam_portal_setup_start_v1(
        p_scope_schema, p_tenant_id, p_operation_id, p_request_sha256,
        p_token_id, p_binding_id, p_selector, p_hash_key_id,
        p_secret_hmac, p_binding_sha256, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS started;
    IF NOT FOUND THEN RETURN; END IF;
    IF NOT v_replayed THEN
        v_insert := iam_lifecycle_delivery_artifact_insert_v1(
            p_scope_schema, p_tenant_id, p_artifact_id,
            'portal_setup_v1', p_subject_user_id, p_resource_id,
            p_recipient_identifier_id, p_token_id, p_artifact_ref,
            p_kms_key_id, p_nonce, p_ciphertext, p_authentication_tag,
            p_aad_sha256, p_ciphertext_sha256
        );
    END IF;
    RETURN QUERY SELECT v_result_id, v_subject_user_id,
        v_result_revision, v_token_version,
        v_authorization_version, v_replayed;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_setup_start_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_token_id uuid, p_binding_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea, p_binding_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_artifact_id uuid, p_subject_user_id uuid, p_resource_id uuid, p_recipient_identifier_id uuid, p_artifact_ref text, p_kms_key_id text, p_nonce bytea, p_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_ciphertext_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_portal_subject_links_read_v1(name, uuid, uuid, bigint, bigint, bigint, uuid, uuid, uuid[]); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_subject_links_read_v1(p_scope_schema name, p_tenant_id uuid, p_principal_id uuid, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_form_id uuid, p_form_version_id uuid, p_record_ids uuid[]) RETURNS TABLE(subject_record_id uuid, portal_user_id uuid, status text, account_type text, result_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_requested integer;
BEGIN
    v_requested := pg_catalog.cardinality(p_record_ids);
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_principal_id IS NULL OR
       p_token_version<1 OR p_authorization_version<1 OR p_authorization_clock<1 OR
       p_form_id IS NULL OR p_form_version_id IS NULL OR
       v_requested IS NULL OR v_requested<1 OR v_requested>500 OR
       EXISTS(SELECT 1 FROM pg_catalog.unnest(p_record_ids) requested(id)
         WHERE requested.id IS NULL) OR
       (SELECT pg_catalog.count(DISTINCT requested.id)
          FROM pg_catalog.unnest(p_record_ids) requested(id))<>v_requested OR
       NOT EXISTS(SELECT 1 FROM tenancy_schema_identity identity_row
          WHERE identity_row.singleton AND identity_row.tenant_id=p_tenant_id
            AND identity_row.schema_name=p_scope_schema::text) OR
       NOT EXISTS(SELECT 1 FROM iam_users principal
          WHERE principal.id=p_principal_id AND principal.status='active'
            AND principal.token_version=p_token_version
            AND principal.authorization_version=p_authorization_version) OR
       NOT EXISTS(SELECT 1 FROM iam_authorization_clock clock
          WHERE clock.singleton AND clock.clock_value=p_authorization_clock) THEN
        RAISE EXCEPTION USING ERRCODE='42501';
    END IF;
    RETURN QUERY
    SELECT binding.subject_record_id,subject.id,
      CASE
        WHEN subject.status<>'active' THEN 'INACTIVE'
        WHEN binding.state='active' THEN 'ACTIVE'
        WHEN binding.state='pending' THEN 'PENDING'
        WHEN setup.approval_state IN('pending','revision_required') THEN 'PENDING'
        ELSE 'INACTIVE'
      END,
      CASE WHEN console.id IS NULL THEN 'portal' ELSE 'operator_portal' END,
      subject.revision
    FROM iam_portal_subject_bindings binding
    JOIN iam_users subject ON subject.id=binding.user_id
      AND subject.status<>'tombstoned'
    JOIN iam_portal_access_setups setup ON setup.binding_id=binding.id
    LEFT JOIN iam_user_access_modes console ON console.user_id=subject.id
      AND console.mode='operator_console' AND console.state='active'
    WHERE binding.profile_form_id=p_form_id
      AND binding.profile_form_version_id=p_form_version_id
      AND binding.subject_record_id=ANY(p_record_ids)
      AND binding.subject_shape='form_record' AND binding.state<>'retired'
    ORDER BY binding.subject_record_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_subject_links_read_v1(p_scope_schema name, p_tenant_id uuid, p_principal_id uuid, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_form_id uuid, p_form_version_id uuid, p_record_ids uuid[]) OWNER TO harpy_owner;

--
-- Name: iam_portal_user_console_grant_v1(name, uuid, uuid, bytea, uuid, bigint, uuid, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_user_console_grant_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_expected_revision bigint, p_access_mode_id uuid, p_assignment_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean, email_identifier_id uuid, email_revision bigint, portal_identifier_id uuid, portal_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz:=pg_catalog.transaction_timestamp();
    v_role_id uuid; v_access_id uuid; v_assignment_id uuid; v_revision bigint;
    v_clock bigint; v_email_id uuid; v_email_revision bigint;
    v_portal_id uuid; v_portal_revision bigint; v_grant iam_portal_console_grants%ROWTYPE;
BEGIN
    IF p_user_id IS NULL OR p_expected_revision<1 OR p_access_mode_id IS NULL OR
       p_assignment_id IS NULL OR NOT EXISTS(SELECT 1 FROM platform.tenants tenant
         WHERE tenant.id=p_tenant_id AND tenant.schema_name=p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE='22023';
    END IF;
    RETURN QUERY SELECT replay.result_id,replay.result_revision,replay.authorization_clock,
      replay.replayed,email.id,email.revision,portal.id,portal.revision
    FROM iam_identity_replay_v1(p_operation_id,'iam.portal_user.console.grant',
      p_request_sha256,p_user_id) replay
    JOIN iam_user_identifiers email ON email.user_id=replay.result_id
      AND email.kind='email_v1' AND email.state<>'retired'
    JOIN iam_user_identifiers portal ON portal.user_id=replay.result_id
      AND portal.kind='portal_v1' AND portal.state<>'retired';
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
      p_scope_schema,p_actor_id,p_permission_id,
      p_expected_token_version,p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM iam_users subject
    WHERE subject.id=p_user_id AND subject.status='active'
      AND subject.revision=p_expected_revision FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001'; END IF;
    PERFORM 1 FROM iam_portal_subject_bindings binding
    JOIN iam_portal_access_setups setup ON setup.binding_id=binding.id
    JOIN iam_password_credentials credential ON credential.user_id=binding.user_id
    JOIN iam_user_identifiers email ON email.user_id=binding.user_id
      AND email.kind='email_v1' AND email.state='active'
    WHERE binding.user_id=p_user_id AND binding.state<>'retired'
      AND setup.setup_state='completed' AND credential.state='active' FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23514',
      MESSAGE='IAM portal console prerequisites are incomplete'; END IF;
    SELECT role.id INTO v_role_id FROM iam_roles role
    WHERE role.scope_kind='tenant' AND role.scope_id=p_tenant_id
      AND role.status='active' AND role.is_default FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23503'; END IF;
    SELECT grant_row.* INTO v_grant FROM iam_portal_console_grants grant_row
      WHERE grant_row.user_id=p_user_id FOR UPDATE;
    IF FOUND THEN
        v_access_id:=v_grant.access_mode_id;
        v_assignment_id:=v_grant.assignment_id;
        UPDATE iam_user_access_modes SET state='active',
          activated_at=COALESCE(activated_at,v_now),suspended_at=NULL,
          revision=revision+1,updated_at=v_now
        WHERE id=v_access_id AND state<>'active';
        UPDATE iam_user_role_assignments SET state='active',revoked_at=NULL,
          revision=revision+1,updated_at=v_now
        WHERE id=v_assignment_id AND state<>'active';
        UPDATE iam_portal_console_grants SET state='active',revoked_at=NULL,
          revision=revision+1,updated_at=v_now WHERE user_id=p_user_id AND state<>'active';
    ELSE
        SELECT access.id INTO v_access_id FROM iam_user_access_modes access
        WHERE access.user_id=p_user_id AND access.mode='operator_console' FOR UPDATE;
        IF FOUND THEN
            UPDATE iam_user_access_modes SET state='active',
              activated_at=COALESCE(activated_at,v_now),suspended_at=NULL,
              revision=revision+1,updated_at=v_now WHERE id=v_access_id AND state<>'active';
        ELSE
            v_access_id:=p_access_mode_id;
            INSERT INTO iam_user_access_modes(id,user_id,mode,state,revision,
              created_at,updated_at,activated_at)
            VALUES(v_access_id,p_user_id,'operator_console','active',1,v_now,v_now,v_now);
        END IF;
        SELECT assignment.id INTO v_assignment_id FROM iam_user_role_assignments assignment
        WHERE assignment.user_id=p_user_id AND assignment.role_id=v_role_id FOR UPDATE;
        IF FOUND THEN
            UPDATE iam_user_role_assignments SET state='active',revoked_at=NULL,
              revision=revision+1,updated_at=v_now
            WHERE id=v_assignment_id AND state<>'active';
        ELSE
            v_assignment_id:=p_assignment_id;
            INSERT INTO iam_user_role_assignments(id,user_id,role_id,role_scope_kind,
              role_scope_id,state,revision,created_at,updated_at)
            VALUES(v_assignment_id,p_user_id,v_role_id,'tenant',p_tenant_id,
              'active',1,v_now,v_now);
        END IF;
        INSERT INTO iam_portal_console_grants(user_id,access_mode_id,access_mode,
          assignment_id,role_id,source,state,revision,created_at,updated_at)
        VALUES(p_user_id,v_access_id,'operator_console',v_assignment_id,v_role_id,
          'portal_grant','active',1,v_now,v_now);
    END IF;
    UPDATE iam_users SET token_version=token_version+1,
      authorization_version=authorization_version+1,revision=revision+1,updated_at=v_now
    WHERE id=p_user_id RETURNING revision INTO v_revision;
    SELECT id,revision INTO STRICT v_email_id,v_email_revision FROM iam_user_identifiers
      WHERE user_id=p_user_id AND kind='email_v1' AND state<>'retired';
    SELECT id,revision INTO STRICT v_portal_id,v_portal_revision FROM iam_user_identifiers
      WHERE user_id=p_user_id AND kind='portal_v1' AND state<>'retired';
    v_clock:=iam_identity_record_v1(p_operation_id,'iam.portal_user.console.grant',
      p_request_sha256,p_user_id,v_revision,p_request_sha256);
    RETURN QUERY SELECT p_user_id,v_revision,v_clock,false,
      v_email_id,v_email_revision,v_portal_id,v_portal_revision;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_user_console_grant_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_expected_revision bigint, p_access_mode_id uuid, p_assignment_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_user_console_revoke_v1(name, uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_user_console_revoke_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean, email_identifier_id uuid, email_revision bigint, portal_identifier_id uuid, portal_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz:=pg_catalog.transaction_timestamp();
    v_access_id uuid; v_assignment_id uuid; v_revision bigint; v_clock bigint;
    v_email_id uuid; v_email_revision bigint; v_portal_id uuid; v_portal_revision bigint;
BEGIN
    IF p_user_id IS NULL OR p_expected_revision<1 OR
       NOT EXISTS(SELECT 1 FROM platform.tenants tenant
         WHERE tenant.id=p_tenant_id AND tenant.schema_name=p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE='22023';
    END IF;
    RETURN QUERY SELECT replay.result_id,replay.result_revision,replay.authorization_clock,
      replay.replayed,email.id,email.revision,portal.id,portal.revision
    FROM iam_identity_replay_v1(p_operation_id,'iam.portal_user.console.revoke',
      p_request_sha256,p_user_id) replay
    JOIN iam_user_identifiers email ON email.user_id=replay.result_id
      AND email.kind='email_v1' AND email.state<>'retired'
    JOIN iam_user_identifiers portal ON portal.user_id=replay.result_id
      AND portal.kind='portal_v1' AND portal.state<>'retired';
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
      p_scope_schema,p_actor_id,p_permission_id,
      p_expected_token_version,p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM iam_users subject
    WHERE subject.id=p_user_id AND subject.status='active'
      AND subject.revision=p_expected_revision FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001'; END IF;
    SELECT grant_row.access_mode_id,grant_row.assignment_id
    INTO v_access_id,v_assignment_id
    FROM iam_portal_console_grants grant_row
    WHERE grant_row.user_id=p_user_id AND grant_row.state='active' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002'; END IF;
    UPDATE iam_refresh_families family SET state='revoked',
      revoke_reason='portal_console_revoked',revoked_at=v_now,
      revision=revision+1,updated_at=v_now
    FROM iam_sessions session WHERE family.session_id=session.id
      AND session.user_id=p_user_id AND session.access_mode_id=v_access_id
      AND family.state='active';
    UPDATE iam_sessions SET state='revoked',revoked_at=v_now,
      revision=revision+1,updated_at=v_now
    WHERE user_id=p_user_id AND access_mode_id=v_access_id AND state='active';
    UPDATE iam_user_access_modes SET state='suspended',suspended_at=v_now,
      revision=revision+1,updated_at=v_now WHERE id=v_access_id;
    IF NOT EXISTS(SELECT 1 FROM iam_portal_role_assignments portal_role
       WHERE portal_role.assignment_id=v_assignment_id) THEN
        UPDATE iam_user_role_assignments SET state='revoked',revoked_at=v_now,
          revision=revision+1,updated_at=v_now WHERE id=v_assignment_id;
    END IF;
    UPDATE iam_portal_console_grants SET state='revoked',revoked_at=v_now,
      revision=revision+1,updated_at=v_now WHERE user_id=p_user_id;
    UPDATE iam_users SET token_version=token_version+1,
      authorization_version=authorization_version+1,revision=revision+1,updated_at=v_now
    WHERE id=p_user_id RETURNING revision INTO v_revision;
    SELECT id,revision INTO STRICT v_email_id,v_email_revision FROM iam_user_identifiers
      WHERE user_id=p_user_id AND kind='email_v1' AND state<>'retired';
    SELECT id,revision INTO STRICT v_portal_id,v_portal_revision FROM iam_user_identifiers
      WHERE user_id=p_user_id AND kind='portal_v1' AND state<>'retired';
    v_clock:=iam_identity_record_v1(p_operation_id,'iam.portal_user.console.revoke',
      p_request_sha256,p_user_id,v_revision,p_request_sha256);
    RETURN QUERY SELECT p_user_id,v_revision,v_clock,false,
      v_email_id,v_email_revision,v_portal_id,v_portal_revision;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_user_console_revoke_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_user_create_v1(name, uuid, uuid, bytea, uuid, uuid, bytea, bytea, uuid, text, text, bytea, uuid, text, text, bytea, uuid, uuid, text, uuid, uuid, uuid, uuid, bytea, text, text[], uuid[], uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_user_create_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_requested_user_id uuid, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_portal_identifier_id uuid, p_portal_display text, p_portal_normalized text, p_portal_sha256 bytea, p_email_identifier_id uuid, p_email_display text, p_email_normalized text, p_email_sha256 bytea, p_access_mode_id uuid, p_binding_id uuid, p_subject_type text, p_form_id uuid, p_form_version_id uuid, p_record_id uuid, p_identifier_field_id uuid, p_contract_sha256 bytea, p_initial_status text, p_role_names text[], p_assignment_ids uuid[], p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean, email_identifier_id uuid, email_revision bigint, portal_identifier_id uuid, portal_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_user_id uuid; v_values jsonb; v_revision bigint; v_clock bigint;
    v_email_id uuid; v_email_revision bigint; v_portal_id uuid;
    v_portal_revision bigint; v_role_id uuid; v_assignment_id uuid;
    v_console_access_id uuid; v_console_assignment_id uuid; v_console_role_id uuid;
    v_existing_binding iam_portal_subject_bindings%ROWTYPE;
    v_receipt iam_authorization_operation_receipts%ROWTYPE;
    v_index integer; v_state text; v_source text;
BEGIN
    IF p_tenant_id IS NULL OR p_requested_user_id IS NULL OR
       p_portal_identifier_id IS NULL OR p_email_identifier_id IS NULL OR
       p_access_mode_id IS NULL OR p_binding_id IS NULL OR
       p_form_id IS NULL OR p_form_version_id IS NULL OR p_record_id IS NULL OR
       p_identifier_field_id IS NULL OR p_initial_status NOT IN ('PENDING','INACTIVE') OR
       pg_catalog.octet_length(p_portal_sha256) <> 32 OR
       pg_catalog.sha256(pg_catalog.convert_to(p_portal_normalized,'UTF8')) <> p_portal_sha256 OR
       pg_catalog.octet_length(p_email_sha256) <> 32 OR
       pg_catalog.sha256(pg_catalog.convert_to(p_email_normalized,'UTF8')) <> p_email_sha256 OR
       pg_catalog.octet_length(p_contract_sha256) <> 32 OR
       pg_catalog.cardinality(p_role_names) NOT BETWEEN 1 AND 32 OR
       pg_catalog.cardinality(p_role_names) <> pg_catalog.cardinality(p_assignment_ids) OR
       (SELECT pg_catalog.count(DISTINCT role_name) FROM pg_catalog.unnest(p_role_names) role_name)
          <> pg_catalog.cardinality(p_role_names) OR
       NOT EXISTS (SELECT 1 FROM platform.tenants tenant
          WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM portal user create input is invalid';
    END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema,p_actor_id,p_permission_id,
        p_expected_token_version,p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT receipt.* INTO v_receipt
    FROM iam_authorization_operation_receipts receipt
    WHERE receipt.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt.command_key <> 'iam.portal_user.create' OR
           v_receipt.request_sha256 <> p_request_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505';
        END IF;
        SELECT id,revision INTO STRICT v_email_id,v_email_revision
        FROM iam_user_identifiers WHERE user_id=v_receipt.result_id AND kind='email_v1'
          AND state <> 'retired';
        SELECT id,revision INTO STRICT v_portal_id,v_portal_revision
        FROM iam_user_identifiers WHERE user_id=v_receipt.result_id AND kind='portal_v1'
          AND state <> 'retired';
        RETURN QUERY SELECT v_receipt.result_id,v_receipt.result_revision,
          v_receipt.clock_value,true,v_email_id,v_email_revision,v_portal_id,v_portal_revision;
        RETURN;
    END IF;
    SELECT binding.* INTO v_existing_binding
    FROM iam_portal_subject_bindings binding
    WHERE binding.profile_form_id=p_form_id AND binding.subject_record_id=p_record_id
      AND binding.state <> 'retired' FOR UPDATE;
    IF FOUND THEN
        IF v_existing_binding.subject_type <> p_subject_type OR
           v_existing_binding.profile_form_version_id <> p_form_version_id OR
           v_existing_binding.identifier_field_id <> p_identifier_field_id OR
           v_existing_binding.contract_sha256 <> p_contract_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505';
        END IF;
        v_user_id := v_existing_binding.user_id;
    ELSE
        SELECT identifier.user_id INTO v_user_id
        FROM iam_user_identifiers identifier
        WHERE identifier.kind='email_v1' AND identifier.normalized_value=p_email_normalized
          AND identifier.state <> 'retired' FOR UPDATE;
    END IF;
    IF v_user_id IS NULL THEN
        v_values := iam_identity_profile_assert_v2(
            'user',p_profile_schema_id,p_profile_document,p_profile_sha256
        );
        v_user_id := p_requested_user_id;
        INSERT INTO iam_users(id,identity_kind,status,profile_resource_kind,
          profile_schema_version_id,profile_values,profile_sha256,token_version,
          authorization_version,revision,created_at,updated_at)
        VALUES(v_user_id,'human','active','user',p_profile_schema_id,v_values,
          p_profile_sha256,1,1,1,v_now,v_now);
        INSERT INTO iam_user_identifiers(id,user_id,kind,display_value,normalized_value,
          normalized_sha256,state,revision,verified_at,activated_at,created_at,updated_at)
        VALUES(p_email_identifier_id,v_user_id,'email_v1',p_email_display,p_email_normalized,
          p_email_sha256,'active',1,v_now,v_now,v_now,v_now);
        v_email_id:=p_email_identifier_id; v_email_revision:=1;
    ELSE
        PERFORM 1 FROM iam_users subject
        WHERE subject.id=v_user_id AND subject.identity_kind='human'
          AND subject.status='active' FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505'; END IF;
        SELECT id,revision INTO STRICT v_email_id,v_email_revision
        FROM iam_user_identifiers WHERE user_id=v_user_id AND kind='email_v1'
          AND normalized_value=p_email_normalized AND state='active';
    END IF;
    IF v_existing_binding.id IS NULL THEN
        INSERT INTO iam_user_identifiers(id,user_id,kind,display_value,normalized_value,
          normalized_sha256,state,revision,created_at,updated_at)
        VALUES(p_portal_identifier_id,v_user_id,'portal_v1',p_portal_display,
          p_portal_normalized,p_portal_sha256,'pending',1,v_now,v_now);
        v_portal_id:=p_portal_identifier_id; v_portal_revision:=1;
        v_state:=CASE p_initial_status WHEN 'PENDING' THEN 'pending' ELSE 'suspended' END;
        INSERT INTO iam_user_access_modes(id,user_id,mode,state,revision,created_at,
          updated_at,suspended_at)
        VALUES(p_access_mode_id,v_user_id,'portal',v_state,1,v_now,v_now,
          CASE WHEN v_state='suspended' THEN v_now END);
        INSERT INTO iam_portal_subject_bindings(id,user_id,access_mode_id,access_mode,
          subject_shape,subject_type,profile_owner,profile_form_id,profile_form_version_id,
          subject_record_id,identifier_field_id,contract_sha256,state,revision,created_at,
          updated_at,suspended_at)
        VALUES(p_binding_id,v_user_id,p_access_mode_id,'portal','form_record',p_subject_type,
          'forms',p_form_id,p_form_version_id,p_record_id,p_identifier_field_id,
          p_contract_sha256,v_state,1,v_now,v_now,CASE WHEN v_state='suspended' THEN v_now END);
        INSERT INTO iam_portal_access_setups(binding_id,user_id,access_mode_id,access_mode,
          setup_state,approval_state,provenance,approval_revision,source_evidence_sha256,
          revision,created_at,updated_at)
        VALUES(p_binding_id,v_user_id,p_access_mode_id,'portal','required','not_required',
          'native_v2',0,p_contract_sha256,1,v_now,v_now);
    ELSE
        SELECT id,revision INTO STRICT v_portal_id,v_portal_revision
        FROM iam_user_identifiers WHERE user_id=v_user_id AND kind='portal_v1'
          AND normalized_value=p_portal_normalized AND state <> 'retired';
    END IF;
    FOR v_index IN 1..pg_catalog.cardinality(p_role_names) LOOP
        SELECT role.id INTO v_role_id FROM iam_roles role
        WHERE role.scope_kind='tenant' AND role.scope_id=p_tenant_id
          AND role.status='active' AND role.name_key=pg_catalog.convert_to(p_role_names[v_index],'UTF8');
        IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23503'; END IF;
        SELECT assignment.id INTO v_assignment_id FROM iam_user_role_assignments assignment
        WHERE assignment.user_id=v_user_id AND assignment.role_id=v_role_id FOR UPDATE;
        IF FOUND THEN
            UPDATE iam_user_role_assignments SET state='active',revoked_at=NULL,
              revision=revision+1,updated_at=v_now WHERE id=v_assignment_id AND state<>'active';
        ELSE
            v_assignment_id:=p_assignment_ids[v_index];
            INSERT INTO iam_user_role_assignments(id,user_id,role_id,role_scope_kind,
              role_scope_id,state,revision,created_at,updated_at)
            VALUES(v_assignment_id,v_user_id,v_role_id,'tenant',p_tenant_id,'active',1,v_now,v_now);
        END IF;
        INSERT INTO iam_portal_role_assignments(binding_id,user_id,assignment_id,role_id,created_at)
        VALUES(COALESCE(v_existing_binding.id,p_binding_id),v_user_id,v_assignment_id,v_role_id,v_now)
        ON CONFLICT (binding_id,role_id) DO NOTHING;
    END LOOP;
    SELECT access.id,assignment.id,assignment.role_id
    INTO v_console_access_id,v_console_assignment_id,v_console_role_id
    FROM iam_user_access_modes access
    JOIN iam_user_role_assignments assignment ON assignment.user_id=access.user_id
    JOIN iam_roles role ON role.id=assignment.role_id AND role.is_default
    WHERE access.user_id=v_user_id AND access.mode='operator_console' AND access.state='active'
      AND assignment.state='active' LIMIT 1;
    IF FOUND THEN
        INSERT INTO iam_portal_console_grants(user_id,access_mode_id,access_mode,
          assignment_id,role_id,source,state,revision,created_at,updated_at)
        VALUES(v_user_id,v_console_access_id,'operator_console',v_console_assignment_id,
          v_console_role_id,
          'preexisting_operator','active',1,v_now,v_now) ON CONFLICT(user_id) DO NOTHING;
    END IF;
    UPDATE iam_users SET token_version=token_version+1,
      authorization_version=authorization_version+1,revision=revision+1,updated_at=v_now
    WHERE id=v_user_id AND id<>p_requested_user_id RETURNING revision INTO v_revision;
    IF v_revision IS NULL THEN SELECT revision INTO v_revision FROM iam_users WHERE id=v_user_id; END IF;
    SELECT id,revision INTO STRICT v_portal_id,v_portal_revision
    FROM iam_user_identifiers WHERE user_id=v_user_id AND kind='portal_v1' AND state<>'retired';
    v_clock:=iam_identity_record_v1(p_operation_id,'iam.portal_user.create',
      p_request_sha256,v_user_id,v_revision,p_request_sha256);
    RETURN QUERY SELECT v_user_id,v_revision,v_clock,false,
      v_email_id,v_email_revision,v_portal_id,v_portal_revision;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_user_create_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_requested_user_id uuid, p_profile_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_portal_identifier_id uuid, p_portal_display text, p_portal_normalized text, p_portal_sha256 bytea, p_email_identifier_id uuid, p_email_display text, p_email_normalized text, p_email_sha256 bytea, p_access_mode_id uuid, p_binding_id uuid, p_subject_type text, p_form_id uuid, p_form_version_id uuid, p_record_id uuid, p_identifier_field_id uuid, p_contract_sha256 bytea, p_initial_status text, p_role_names text[], p_assignment_ids uuid[], p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_portal_user_read_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_user_read_v1(p_scope_schema name, p_user_id uuid) RETURNS TABLE(result_id uuid, binding_id uuid, email text, status text, account_type text, subject_type text, subject_record_id uuid, result_revision bigint, setup_required boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR p_user_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501';
    END IF;
    RETURN QUERY
    SELECT subject.id,binding.id,email.normalized_value,
      CASE
        WHEN subject.status<>'active' THEN 'INACTIVE'
        WHEN binding.state='active' THEN 'ACTIVE'
        WHEN binding.state='pending' THEN 'PENDING'
        WHEN setup.approval_state IN('pending','revision_required') THEN 'PENDING'
        ELSE 'INACTIVE'
      END,
      CASE WHEN console.id IS NULL THEN 'portal' ELSE 'operator_portal' END,
      binding.subject_type,binding.subject_record_id,subject.revision,
      setup.setup_state='required',subject.created_at,subject.updated_at
    FROM iam_users subject
    JOIN iam_user_identifiers email ON email.user_id=subject.id
      AND email.kind='email_v1' AND email.state<>'retired'
    JOIN iam_portal_subject_bindings binding ON binding.user_id=subject.id
      AND binding.state<>'retired'
    JOIN iam_portal_access_setups setup ON setup.binding_id=binding.id
    LEFT JOIN iam_user_access_modes console ON console.user_id=subject.id
      AND console.mode='operator_console' AND console.state='active'
    WHERE subject.id=p_user_id AND subject.status<>'tombstoned';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002'; END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_user_read_v1(p_scope_schema name, p_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_portal_user_status_v1(name, uuid, uuid, bytea, uuid, bigint, text, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_portal_user_status_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_expected_revision bigint, p_status text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean, email_identifier_id uuid, email_revision bigint, portal_identifier_id uuid, portal_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz:=pg_catalog.transaction_timestamp();
    v_binding_id uuid; v_access_id uuid; v_setup_state text; v_revision bigint;
    v_clock bigint; v_email_id uuid; v_email_revision bigint;
    v_portal_id uuid; v_portal_revision bigint;
BEGIN
    IF p_user_id IS NULL OR p_expected_revision<1 OR
       p_status NOT IN ('ACTIVE','PENDING','INACTIVE') OR
       NOT EXISTS(SELECT 1 FROM platform.tenants tenant
         WHERE tenant.id=p_tenant_id AND tenant.schema_name=p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE='22023';
    END IF;
    RETURN QUERY SELECT replay.result_id,replay.result_revision,replay.authorization_clock,
      replay.replayed,email.id,email.revision,portal.id,portal.revision
    FROM iam_identity_replay_v1(p_operation_id,'iam.portal_user.status',
      p_request_sha256,p_user_id) replay
    JOIN iam_user_identifiers email ON email.user_id=replay.result_id
      AND email.kind='email_v1' AND email.state<>'retired'
    JOIN iam_user_identifiers portal ON portal.user_id=replay.result_id
      AND portal.kind='portal_v1' AND portal.state<>'retired';
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
      p_scope_schema,p_actor_id,p_permission_id,
      p_expected_token_version,p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM iam_users subject
    WHERE subject.id=p_user_id AND subject.status='active'
      AND subject.revision=p_expected_revision FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001'; END IF;
    SELECT binding.id,binding.access_mode_id,setup.setup_state
    INTO v_binding_id,v_access_id,v_setup_state
    FROM iam_portal_subject_bindings binding
    JOIN iam_portal_access_setups setup ON setup.binding_id=binding.id
    WHERE binding.user_id=p_user_id AND binding.state<>'retired'
    FOR UPDATE OF binding,setup;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002'; END IF;
    IF p_status='ACTIVE' AND v_setup_state<>'completed' THEN
        RAISE EXCEPTION USING ERRCODE='23514',
          MESSAGE='IAM portal setup must be completed before activation';
    END IF;
    IF p_status='ACTIVE' THEN
        UPDATE iam_user_access_modes SET state='active',
          activated_at=COALESCE(activated_at,v_now),suspended_at=NULL,
          revision=revision+1,updated_at=v_now WHERE id=v_access_id;
        UPDATE iam_portal_subject_bindings SET state='active',
          activated_at=COALESCE(activated_at,v_now),suspended_at=NULL,
          revision=revision+1,updated_at=v_now WHERE id=v_binding_id;
        UPDATE iam_user_identifiers SET state='active',
          verified_at=COALESCE(verified_at,v_now),activated_at=COALESCE(activated_at,v_now),
          revision=revision+1,updated_at=v_now
        WHERE user_id=p_user_id AND kind='portal_v1' AND state IN('pending','verified');
        UPDATE iam_portal_access_setups SET approval_state='not_required',
          submitted_at=NULL,decision_at=NULL,decision_actor_id=NULL,
          revision=revision+1,updated_at=v_now WHERE binding_id=v_binding_id;
    ELSIF p_status='PENDING' AND v_setup_state='required' THEN
        UPDATE iam_user_access_modes SET state='pending',activated_at=NULL,suspended_at=NULL,
          revision=revision+1,updated_at=v_now WHERE id=v_access_id;
        UPDATE iam_portal_subject_bindings SET state='pending',activated_at=NULL,suspended_at=NULL,
          revision=revision+1,updated_at=v_now WHERE id=v_binding_id;
    ELSE
        UPDATE iam_user_access_modes SET state='suspended',suspended_at=v_now,
          revision=revision+1,updated_at=v_now WHERE id=v_access_id;
        UPDATE iam_portal_subject_bindings SET state='suspended',suspended_at=v_now,
          revision=revision+1,updated_at=v_now WHERE id=v_binding_id;
        IF v_setup_state='completed' THEN
            UPDATE iam_portal_access_setups SET
              approval_state=CASE p_status WHEN 'PENDING' THEN 'revision_required' ELSE 'rejected' END,
              approval_revision=approval_revision+1,submitted_at=COALESCE(submitted_at,v_now),
              decision_at=v_now,decision_actor_id=p_actor_id,
              revision=revision+1,updated_at=v_now WHERE binding_id=v_binding_id;
        END IF;
    END IF;
    UPDATE iam_refresh_families family SET state='revoked',
      revoke_reason='portal_status_changed',revoked_at=v_now,
      revision=revision+1,updated_at=v_now
    FROM iam_sessions session WHERE family.session_id=session.id
      AND session.portal_binding_id=v_binding_id AND family.state='active';
    UPDATE iam_sessions SET state='revoked',revoked_at=v_now,
      revision=revision+1,updated_at=v_now
    WHERE portal_binding_id=v_binding_id AND state='active';
    UPDATE iam_users SET token_version=token_version+1,
      authorization_version=authorization_version+1,
      revision=revision+1,updated_at=v_now
    WHERE id=p_user_id RETURNING revision INTO v_revision;
    SELECT id,revision INTO STRICT v_email_id,v_email_revision
      FROM iam_user_identifiers WHERE user_id=p_user_id AND kind='email_v1' AND state<>'retired';
    SELECT id,revision INTO STRICT v_portal_id,v_portal_revision
      FROM iam_user_identifiers WHERE user_id=p_user_id AND kind='portal_v1' AND state<>'retired';
    v_clock:=iam_identity_record_v1(p_operation_id,'iam.portal_user.status',
      p_request_sha256,p_user_id,v_revision,p_request_sha256);
    RETURN QUERY SELECT p_user_id,v_revision,v_clock,false,
      v_email_id,v_email_revision,v_portal_id,v_portal_revision;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_portal_user_status_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_user_id uuid, p_expected_revision bigint, p_status text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_owner_context_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_post_restore_owner_context_v1(p_owner_user_id uuid) RETURNS TABLE(identifier_id uuid, normalized_value text, normalized_sha256 bytea, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
RETURN QUERY
SELECT identifier.id,identifier.normalized_value,identifier.normalized_sha256,identifier.revision
FROM iam_user_identifiers AS identifier
JOIN iam_users AS subject ON subject.id=identifier.user_id
WHERE identifier.user_id=p_owner_user_id AND identifier.kind='email_v1'
  AND identifier.state='active' AND subject.status='active';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_post_restore_owner_context_v1(p_owner_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_post_restore_reactivate_owner_v1(uuid, uuid, uuid, uuid, uuid, uuid, bytea, bytea, bytea, bigint, bytea, bytea, integer, smallint, smallint, uuid, bigint, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_post_restore_reactivate_owner_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_assertion_sha256 bytea, p_password_credential_sha256 bytea, p_receipt_sha256 bytea, p_sign_count bigint, p_salt bytea, p_tag bytea, p_memory_kib integer, p_iterations smallint, p_parallelism smallint, p_identifier_id uuid, p_identifier_revision bigint, p_directory_key_id text, p_directory_hmac bytea, p_occurred_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE v_existing iam_post_restore_owner_receipts%ROWTYPE;
v_identifier iam_user_identifiers%ROWTYPE;
v_current_version bigint;
BEGIN
    IF p_operation_id IS NULL OR p_environment_id IS NULL OR p_restore_operation_id IS NULL OR
       p_tenant_id IS NULL OR p_owner_user_id IS NULL OR p_anchor_id IS NULL OR
       pg_catalog.octet_length(p_assertion_sha256)<>32 OR
       pg_catalog.octet_length(p_password_credential_sha256)<>32 OR
       pg_catalog.octet_length(p_receipt_sha256)<>32 OR p_sign_count<0 OR
       pg_catalog.octet_length(p_salt)<>16 OR pg_catalog.octet_length(p_tag)<>32 OR
       p_memory_kib<>65536 OR p_iterations<>3 OR p_parallelism<>4 OR
       p_identifier_id IS NULL OR p_identifier_revision<1 OR
       p_directory_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_directory_hmac)<>32 THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='post-restore owner result is invalid';
    END IF;
    SELECT * INTO v_existing FROM iam_post_restore_owner_receipts
     WHERE restore_operation_id=p_restore_operation_id;
    IF FOUND THEN
        IF v_existing.operation_id<>p_operation_id OR v_existing.owner_user_id<>p_owner_user_id OR
           v_existing.anchor_id<>p_anchor_id OR v_existing.assertion_sha256<>p_assertion_sha256 OR
           v_existing.password_credential_sha256<>p_password_credential_sha256 OR
           v_existing.receipt_sha256<>p_receipt_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='post-restore owner replay conflicts';
        END IF;
        RETURN false;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM iam_restored_identity_receipts
        WHERE restore_operation_id=p_restore_operation_id AND environment_id=p_environment_id
          AND owner_user_id=p_owner_user_id AND anchor_id=p_anchor_id) THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='restored identity receipt is unavailable';
    END IF;
    SELECT * INTO v_identifier FROM iam_user_identifiers
     WHERE id=p_identifier_id AND user_id=p_owner_user_id AND kind='email_v1'
       AND state='active' AND revision=p_identifier_revision FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='restored owner identifier is unavailable';
    END IF;
    SELECT credential_version INTO v_current_version FROM iam_password_credentials
     WHERE user_id=p_owner_user_id FOR UPDATE;
    IF FOUND THEN
        UPDATE iam_password_credentials SET credential_version=v_current_version+1,state='active',
            algorithm='argon2id_v1',salt=p_salt,tag=p_tag,memory_kib=p_memory_kib,
            iterations=p_iterations,parallelism=p_parallelism,legacy_bcrypt_hash=NULL,
            upgrade_required=false,revision=revision+1,updated_at=p_occurred_at,
            last_used_at=NULL,invalidated_at=NULL WHERE user_id=p_owner_user_id;
    ELSE
        INSERT INTO iam_password_credentials(user_id,credential_version,state,algorithm,salt,tag,
            memory_kib,iterations,parallelism,legacy_bcrypt_hash,upgrade_required,revision,
            created_at,updated_at,last_used_at,invalidated_at)
        VALUES(p_owner_user_id,1,'active','argon2id_v1',p_salt,p_tag,p_memory_kib,p_iterations,
            p_parallelism,NULL,false,1,p_occurred_at,p_occurred_at,NULL,NULL);
    END IF;
    UPDATE iam_users SET token_version=token_version+1,authorization_version=authorization_version+1,
        revision=revision+1,updated_at=p_occurred_at WHERE id=p_owner_user_id AND status='active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='restored owner is unavailable';
    END IF;
    IF NOT platform.iam_post_restore_reactivation_apply_v1(
        p_operation_id,p_environment_id,p_restore_operation_id,p_tenant_id,
        p_owner_user_id,p_anchor_id,p_assertion_sha256,
        p_password_credential_sha256,p_receipt_sha256,p_sign_count,
        p_identifier_id,p_identifier_revision,p_directory_key_id,
        p_directory_hmac,v_identifier.normalized_sha256,p_occurred_at
    ) THEN
        RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='post-restore owner completion replayed';
    END IF;
    INSERT INTO iam_post_restore_owner_receipts VALUES(p_restore_operation_id,p_operation_id,
        p_owner_user_id,p_anchor_id,p_assertion_sha256,p_password_credential_sha256,
        p_receipt_sha256,p_occurred_at);
    RETURN true;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_post_restore_reactivate_owner_v1(p_operation_id uuid, p_environment_id uuid, p_restore_operation_id uuid, p_tenant_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_assertion_sha256 bytea, p_password_credential_sha256 bytea, p_receipt_sha256 bytea, p_sign_count bigint, p_salt bytea, p_tag bytea, p_memory_kib integer, p_iterations smallint, p_parallelism smallint, p_identifier_id uuid, p_identifier_revision bigint, p_directory_key_id text, p_directory_hmac bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_profile_active_catalog_read_v1(name, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_active_catalog_read_v1(p_scope_schema name, p_resource_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM active profile catalog read scope is invalid';
    END IF;
    SELECT pg_catalog.jsonb_build_object(
        'schema_id', schema_version.id,
        'resource_kind', schema_version.resource_kind,
        'version', schema_version.version,
        'state', schema_version.state,
        'definition_sha256', pg_catalog.encode(
            schema_version.definition_sha256, 'hex'
        ),
        'fields', COALESCE(
            pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'id', snapshot.field_id,
                'key', snapshot.field_key,
                'logical_type', snapshot.value_kind,
                'cardinality', snapshot.cardinality,
                'required', snapshot.required,
                'classification', snapshot.classification,
                'normalization_profile', snapshot.normalization_profile,
                'state', snapshot.field_state,
                'validation', snapshot.validation_schema,
                'validation_sha256', pg_catalog.encode(
                    snapshot.validation_sha256, 'hex'
                ),
                'semantic_sha256', pg_catalog.encode(
                    snapshot.semantic_sha256, 'hex'
                )
            ) ORDER BY snapshot.field_id) FILTER (
                WHERE snapshot.field_id IS NOT NULL
            ),
            '[]'::jsonb
        )
    )
    INTO v_document
    FROM iam_profile_schema_versions AS schema_version
    LEFT JOIN iam_profile_field_revisions AS snapshot
      ON snapshot.schema_version_id = schema_version.id
     AND snapshot.resource_kind = schema_version.resource_kind
    WHERE schema_version.resource_kind = p_resource_kind
      AND schema_version.state = 'active'
    GROUP BY schema_version.id, schema_version.resource_kind,
             schema_version.version, schema_version.state,
             schema_version.definition_sha256;
    RETURN v_document;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_active_catalog_read_v1(p_scope_schema name, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: iam_profile_actor_assert_v1(name, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_actor_assert_v1(p_scope_schema name, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_state text;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile command scope is invalid';
    END IF;
    IF p_actor_id IS NULL OR p_manage_permission_id IS NULL OR
       p_expected_token_version < 1 OR p_expected_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile command evidence is invalid';
    END IF;
    SELECT actor.status, actor.token_version, actor.authorization_version
    INTO v_state, v_token_version, v_authorization_version
    FROM iam_users AS actor
    WHERE actor.id OPERATOR(pg_catalog.=) p_actor_id
    FOR UPDATE;
    IF NOT FOUND OR v_state IS DISTINCT FROM 'active' OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version OR
       NOT iam_user_has_rbac_evidence_v2(p_actor_id, p_manage_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile command authority is denied';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_actor_assert_v1(p_scope_schema name, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_activate_v2(uuid, text, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_activate_v2(p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_target_schema_id uuid, p_source_count bigint, p_now timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_total_count bigint;
    v_target_count bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_plan_id IS NULL OR p_resource_kind NOT IN ('user','organization','role') OR
       p_source_schema_id IS NULL OR p_target_schema_id IS NULL OR
       p_source_schema_id = p_target_schema_id OR p_source_count < 0 OR
       p_now IS NULL OR NOT EXISTS (
           SELECT 1 FROM iam_profile_backfill_plans AS plan
           JOIN iam_profile_schema_versions AS source
             ON source.id = plan.source_schema_id
            AND source.resource_kind = plan.resource_kind
            AND source.state = 'active'
           JOIN iam_profile_schema_versions AS target
             ON target.id = plan.target_schema_id
            AND target.resource_kind = plan.resource_kind
            AND target.state = 'draft'
            AND target.version = source.version + 1
           WHERE plan.id = p_plan_id AND plan.resource_kind = p_resource_kind
             AND plan.source_schema_id = p_source_schema_id
             AND plan.target_schema_id = p_target_schema_id
             AND plan.source_count = p_source_count
             AND plan.state IN ('planned','running')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile activation compare-and-swap failed';
    END IF;
    SELECT pg_catalog.count(*),
           pg_catalog.count(*) FILTER (
               WHERE resource.profile_schema_version_id = p_target_schema_id
           )
    INTO v_total_count, v_target_count
    FROM (
        SELECT usr.profile_schema_version_id FROM iam_users AS usr
        WHERE p_resource_kind = 'user'
        UNION ALL
        SELECT organization.profile_schema_version_id
        FROM iam_organizations AS organization
        WHERE p_resource_kind = 'organization'
        UNION ALL
        SELECT role.profile_schema_version_id FROM iam_roles AS role
        WHERE p_resource_kind = 'role'
    ) AS resource;
    IF v_total_count <> v_target_count OR v_target_count < p_source_count THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile activation row lineage is inconsistent';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM (
            SELECT * FROM iam_profile_fields
            WHERE resource_kind = p_resource_kind
        ) AS field
        FULL JOIN (
            SELECT * FROM iam_profile_field_revisions
            WHERE schema_version_id = p_target_schema_id
              AND resource_kind = p_resource_kind
        ) AS snapshot ON snapshot.field_id = field.id
        WHERE field.id IS NULL OR snapshot.field_id IS NULL OR
              field.field_key <> snapshot.field_key OR
              field.value_kind <> snapshot.value_kind OR
              field.cardinality <> snapshot.cardinality OR
              field.required <> snapshot.required OR
              field.classification <> snapshot.classification OR
              field.normalization_profile <> snapshot.normalization_profile OR
              (field.state = 'retired' AND snapshot.field_state = 'active')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile activation field lineage is inconsistent';
    END IF;
    UPDATE iam_profile_fields AS field
    SET state = 'retired', retired_at = p_now, updated_at = p_now,
        revision = field.revision + 1
    FROM iam_profile_field_revisions AS snapshot
    WHERE snapshot.schema_version_id = p_target_schema_id
      AND snapshot.resource_kind = p_resource_kind
      AND snapshot.field_id = field.id
      AND field.resource_kind = p_resource_kind
      AND snapshot.field_state = 'retired' AND field.state = 'active';
    UPDATE iam_profile_schema_versions
    SET state = 'retired', retired_at = p_now, updated_at = p_now,
        revision = revision + 1
    WHERE id = p_source_schema_id AND resource_kind = p_resource_kind
      AND state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile source pointer changed';
    END IF;
    UPDATE iam_profile_schema_versions
    SET state = 'active', activated_at = p_now, updated_at = p_now,
        revision = revision + 1
    WHERE id = p_target_schema_id AND resource_kind = p_resource_kind
      AND state = 'draft';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile target pointer changed';
    END IF;
    UPDATE iam_profile_backfill_plans
    SET state = 'activated', activated_at = p_now,
        revision = revision + 1, updated_at = p_now
    WHERE id = p_plan_id AND state IN ('planned','running');
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile plan activation changed';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_activate_v2(p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_target_schema_id uuid, p_source_count bigint, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_draft_create_v1(name, uuid, text, bigint, jsonb, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_draft_create_v1(p_scope_schema name, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_active_id uuid;
    v_active_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_schema_id IS NULL OR p_expected_active_schema_id IS NULL OR
       p_schema_id IS NOT DISTINCT FROM p_expected_active_schema_id OR
       p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_version < 2 OR pg_catalog.jsonb_typeof(p_definition) <> 'object' OR
       pg_catalog.octet_length(p_definition_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_definition::text) > 4194304 OR
       p_definition ->> 'contract' IS DISTINCT FROM 'harpy/iam-profile-schema/v1' OR
       p_definition ->> 'id' IS DISTINCT FROM p_schema_id::text OR
       p_definition ->> 'resource_kind' IS DISTINCT FROM p_resource_kind OR
       p_definition ->> 'version' IS DISTINCT FROM p_version::text OR
       pg_catalog.jsonb_typeof(p_definition -> 'fields') <> 'array' OR
       pg_catalog.jsonb_array_length(p_definition -> 'fields') > 500 OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_object_keys(p_definition) AS key
           WHERE key NOT IN ('contract', 'fields', 'id', 'resource_kind', 'version')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill draft definition is invalid';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        WHERE pg_catalog.jsonb_typeof(field.value) <> 'object'
           OR field.value ->> 'id' !~
              '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR pg_catalog.jsonb_typeof(field.value -> 'required') <> 'boolean'
           OR pg_catalog.jsonb_typeof(field.value -> 'validation') <> 'object'
           OR field.value ->> 'state' NOT IN ('active', 'retired')
           OR EXISTS (
                SELECT 1 FROM pg_catalog.jsonb_object_keys(field.value) AS key
                WHERE key NOT IN (
                    'id', 'key', 'logical_type', 'cardinality', 'required',
                    'classification', 'normalization_profile', 'state', 'validation'
                )
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill draft field is invalid';
    END IF;
    SELECT active.id, active.version INTO v_active_id, v_active_version
    FROM iam_profile_schema_versions AS active
    WHERE active.resource_kind = p_resource_kind AND active.state = 'active'
    FOR UPDATE;
    IF NOT FOUND OR v_active_id IS DISTINCT FROM p_expected_active_schema_id OR
       p_version IS DISTINCT FROM v_active_version + 1 OR EXISTS (
           SELECT 1 FROM iam_profile_schema_versions AS draft
           WHERE draft.resource_kind = p_resource_kind AND draft.state = 'draft'
       ) OR EXISTS (
           SELECT 1 FROM iam_profile_backfill_plans AS plan
           WHERE plan.resource_kind = p_resource_kind
             AND plan.state IN ('planned', 'running', 'verified')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile backfill draft compare-and-swap failed';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        LEFT JOIN iam_profile_fields AS stored
          ON stored.id = (field.value ->> 'id')::uuid
         AND stored.resource_kind = p_resource_kind
        WHERE stored.id IS NULL AND field.value ->> 'state' <> 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile backfill new field must be active';
    END IF;
    INSERT INTO iam_profile_fields (
        id, resource_kind, field_key, value_kind, cardinality, required,
        classification, normalization_profile, state, created_at, updated_at,
        retired_at, revision
    )
    SELECT (field.value ->> 'id')::uuid, p_resource_kind, field.value ->> 'key',
        field.value ->> 'logical_type', field.value ->> 'cardinality',
        (field.value ->> 'required')::boolean, field.value ->> 'classification',
        field.value ->> 'normalization_profile', 'active', v_now, v_now, NULL, 1
    FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
    WHERE NOT EXISTS (
        SELECT 1 FROM iam_profile_fields AS stored
        WHERE stored.id = (field.value ->> 'id')::uuid
    );
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        LEFT JOIN iam_profile_fields AS stored
          ON stored.id = (field.value ->> 'id')::uuid
         AND stored.resource_kind = p_resource_kind
        WHERE stored.id IS NULL OR stored.field_key IS DISTINCT FROM field.value ->> 'key'
           OR stored.value_kind IS DISTINCT FROM field.value ->> 'logical_type'
           OR stored.cardinality IS DISTINCT FROM field.value ->> 'cardinality'
           OR stored.required IS DISTINCT FROM (field.value ->> 'required')::boolean
           OR stored.classification IS DISTINCT FROM field.value ->> 'classification'
           OR stored.normalization_profile IS DISTINCT FROM field.value ->> 'normalization_profile'
           OR stored.state IS DISTINCT FROM field.value ->> 'state'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile backfill stable field semantic changed';
    END IF;
    INSERT INTO iam_profile_schema_versions (
        id, resource_kind, version, state, definition_sha256,
        activated_at, retired_at, created_at, updated_at, revision
    ) VALUES (
        p_schema_id, p_resource_kind, p_version, 'draft', p_definition_sha256,
        NULL, NULL, v_now, v_now, 1
    );
    INSERT INTO iam_profile_field_revisions (
        schema_version_id, resource_kind, field_id, validation_schema,
        validation_sha256, created_at, field_key, value_kind, cardinality,
        required, classification, normalization_profile, field_state,
        semantic_sha256
    )
    SELECT p_schema_id, p_resource_kind, (field.value ->> 'id')::uuid,
        field.value -> 'validation', pg_catalog.sha256(pg_catalog.convert_to(
            iam_profile_validation_canonical_v1(field.value -> 'validation'), 'UTF8'
        )), v_now, field.value ->> 'key', field.value ->> 'logical_type',
        field.value ->> 'cardinality', (field.value ->> 'required')::boolean,
        field.value ->> 'classification', field.value ->> 'normalization_profile',
        field.value ->> 'state', iam_profile_semantic_sha256_v1(
            (field.value ->> 'id')::uuid, p_resource_kind, field.value ->> 'key',
            field.value ->> 'logical_type', field.value ->> 'cardinality',
            (field.value ->> 'required')::boolean, field.value ->> 'classification',
            field.value ->> 'normalization_profile'
        )
    FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value);
    IF iam_profile_definition_sha256_v1(p_schema_id) IS DISTINCT FROM p_definition_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile backfill draft hash is inconsistent';
    END IF;
    RETURN 1;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_draft_create_v1(p_scope_schema name, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_draft_create_v2(name, uuid, text, bigint, jsonb, bytea, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_draft_create_v2(p_scope_schema name, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_active_id uuid;
    v_active_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_schema_id IS NULL OR p_expected_active_schema_id IS NULL OR
       p_schema_id IS NOT DISTINCT FROM p_expected_active_schema_id OR
       p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_version < 2 OR pg_catalog.jsonb_typeof(p_definition) <> 'object' OR
       pg_catalog.octet_length(p_definition_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_definition::text) > 4194304 OR
       p_definition ->> 'contract' IS DISTINCT FROM 'harpy/iam-profile-schema/v1' OR
       p_definition ->> 'id' IS DISTINCT FROM p_schema_id::text OR
       p_definition ->> 'resource_kind' IS DISTINCT FROM p_resource_kind OR
       p_definition ->> 'version' IS DISTINCT FROM p_version::text OR
       pg_catalog.jsonb_typeof(p_definition -> 'fields') <> 'array' OR
       pg_catalog.jsonb_array_length(p_definition -> 'fields') > 500 OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_object_keys(p_definition) AS key
           WHERE key NOT IN ('contract', 'fields', 'id', 'resource_kind', 'version')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill draft definition is invalid';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        WHERE pg_catalog.jsonb_typeof(field.value) <> 'object'
           OR field.value ->> 'id' !~
              '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR pg_catalog.jsonb_typeof(field.value -> 'required') <> 'boolean'
           OR pg_catalog.jsonb_typeof(field.value -> 'validation') <> 'object'
           OR field.value ->> 'state' NOT IN ('active', 'retired')
           OR EXISTS (
                SELECT 1 FROM pg_catalog.jsonb_object_keys(field.value) AS key
                WHERE key NOT IN (
                    'id', 'key', 'logical_type', 'cardinality', 'required',
                    'classification', 'normalization_profile', 'state', 'validation'
                )
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill draft field is invalid';
    END IF;
    SELECT active.id, active.version INTO v_active_id, v_active_version
    FROM iam_profile_schema_versions AS active
    WHERE active.resource_kind = p_resource_kind AND active.state = 'active'
    FOR UPDATE;
    IF NOT FOUND OR v_active_id IS DISTINCT FROM p_expected_active_schema_id OR
       p_version IS DISTINCT FROM v_active_version + 1 OR EXISTS (
           SELECT 1 FROM iam_profile_schema_versions AS draft
           WHERE draft.resource_kind = p_resource_kind AND draft.state = 'draft'
       ) OR EXISTS (
           SELECT 1 FROM iam_profile_backfill_plans AS plan
           WHERE plan.resource_kind = p_resource_kind
             AND plan.state IN ('planned', 'running', 'verified')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile backfill draft compare-and-swap failed';
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        LEFT JOIN iam_profile_fields AS stored
          ON stored.id = (field.value ->> 'id')::uuid
         AND stored.resource_kind = p_resource_kind
        WHERE stored.id IS NULL AND field.value ->> 'state' <> 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile backfill new field must be active';
    END IF;
    IF EXISTS (
        SELECT 1 FROM iam_profile_field_revisions AS source
        WHERE source.schema_version_id = v_active_id
          AND source.resource_kind = p_resource_kind
          AND NOT EXISTS (
              SELECT 1 FROM pg_catalog.jsonb_array_elements(
                  p_definition -> 'fields'
              ) AS target(value)
              WHERE target.value ->> 'id' = source.field_id::text
          )
    ) OR EXISTS (
        SELECT 1 FROM iam_profile_field_revisions AS source
        JOIN pg_catalog.jsonb_array_elements(
            p_definition -> 'fields'
        ) AS target(value) ON target.value ->> 'id' = source.field_id::text
        WHERE source.schema_version_id = v_active_id
          AND source.resource_kind = p_resource_kind
          AND source.field_state = 'retired'
          AND target.value ->> 'state' <> 'retired'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile backfill fields must evolve cumulatively';
    END IF;
    INSERT INTO iam_profile_fields (
        id, resource_kind, field_key, value_kind, cardinality, required,
        classification, normalization_profile, state, created_at, updated_at,
        retired_at, revision
    )
    SELECT (field.value ->> 'id')::uuid, p_resource_kind, field.value ->> 'key',
        field.value ->> 'logical_type', field.value ->> 'cardinality',
        (field.value ->> 'required')::boolean, field.value ->> 'classification',
        field.value ->> 'normalization_profile', 'active', v_now, v_now, NULL, 1
    FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
    WHERE NOT EXISTS (
        SELECT 1 FROM iam_profile_fields AS stored
        WHERE stored.id = (field.value ->> 'id')::uuid
    );
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        LEFT JOIN iam_profile_fields AS stored
          ON stored.id = (field.value ->> 'id')::uuid
         AND stored.resource_kind = p_resource_kind
        WHERE stored.id IS NULL OR stored.field_key IS DISTINCT FROM field.value ->> 'key'
           OR stored.value_kind IS DISTINCT FROM field.value ->> 'logical_type'
           OR stored.cardinality IS DISTINCT FROM field.value ->> 'cardinality'
           OR stored.required IS DISTINCT FROM (field.value ->> 'required')::boolean
           OR stored.classification IS DISTINCT FROM field.value ->> 'classification'
           OR stored.normalization_profile IS DISTINCT FROM field.value ->> 'normalization_profile'
           OR (stored.state = 'retired' AND field.value ->> 'state' <> 'retired')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile backfill stable field semantic changed';
    END IF;
    INSERT INTO iam_profile_schema_versions (
        id, resource_kind, version, state, definition_sha256,
        activated_at, retired_at, created_at, updated_at, revision
    ) VALUES (
        p_schema_id, p_resource_kind, p_version, 'draft', p_definition_sha256,
        NULL, NULL, v_now, v_now, 1
    );
    INSERT INTO iam_profile_field_revisions (
        schema_version_id, resource_kind, field_id, validation_schema,
        validation_sha256, created_at, field_key, value_kind, cardinality,
        required, classification, normalization_profile, field_state,
        semantic_sha256
    )
    SELECT p_schema_id, p_resource_kind, (field.value ->> 'id')::uuid,
        field.value -> 'validation', pg_catalog.sha256(pg_catalog.convert_to(
            iam_profile_validation_canonical_v1(field.value -> 'validation'), 'UTF8'
        )), v_now, field.value ->> 'key', field.value ->> 'logical_type',
        field.value ->> 'cardinality', (field.value ->> 'required')::boolean,
        field.value ->> 'classification', field.value ->> 'normalization_profile',
        field.value ->> 'state', iam_profile_semantic_sha256_v1(
            (field.value ->> 'id')::uuid, p_resource_kind, field.value ->> 'key',
            field.value ->> 'logical_type', field.value ->> 'cardinality',
            (field.value ->> 'required')::boolean, field.value ->> 'classification',
            field.value ->> 'normalization_profile'
        )
    FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value);
    IF iam_profile_definition_sha256_v1(p_schema_id) IS DISTINCT FROM p_definition_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile backfill draft hash is inconsistent';
    END IF;
    RETURN 1;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_draft_create_v2(p_scope_schema name, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_mapping_create_v1(uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_mapping_create_v1(p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_target_schema_id uuid, p_mappings jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count integer;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_plan_id IS NULL OR
       p_resource_kind NOT IN ('user','organization','role') OR
       p_source_schema_id IS NULL OR p_target_schema_id IS NULL OR
       pg_catalog.jsonb_typeof(p_mappings)<>'array' OR
       pg_catalog.jsonb_array_length(p_mappings) NOT BETWEEN 1 AND 500 OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_mappings)
                WITH ORDINALITY AS mapping(value,ordinal)
           WHERE pg_catalog.jsonb_typeof(mapping.value)<>'object'
              OR (mapping.value->>'ordinal')::integer<>mapping.ordinal
              OR mapping.value->>'converter_kind' NOT IN ('copy_v1','copy_normalize_v1')
              OR pg_catalog.octet_length(pg_catalog.decode(
                    mapping.value->>'semantic_sha256','hex'))<>32
              OR EXISTS (
                   SELECT 1 FROM pg_catalog.jsonb_object_keys(mapping.value) AS key
                   WHERE key NOT IN ('ordinal','source_field_id','target_field_id',
                                     'converter_kind','semantic_sha256')
              )
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill mapping input is invalid';
    END IF;
    INSERT INTO iam_profile_backfill_mappings (
        plan_id,ordinal,source_field_id,target_field_id,converter_kind,semantic_sha256
    )
    SELECT p_plan_id,mapping.ordinal,(mapping.value->>'source_field_id')::uuid,
        (mapping.value->>'target_field_id')::uuid,mapping.value->>'converter_kind',
        pg_catalog.decode(mapping.value->>'semantic_sha256','hex')
    FROM pg_catalog.jsonb_array_elements(p_mappings)
         WITH ORDINALITY AS mapping(value,ordinal);
    GET DIAGNOSTICS v_count=ROW_COUNT;
    IF EXISTS (
        SELECT 1 FROM iam_profile_backfill_mappings AS mapping
        LEFT JOIN iam_profile_field_revisions AS source
          ON source.schema_version_id=p_source_schema_id
         AND source.resource_kind=p_resource_kind
         AND source.field_id=mapping.source_field_id
        LEFT JOIN iam_profile_field_revisions AS target
          ON target.schema_version_id=p_target_schema_id
         AND target.resource_kind=p_resource_kind
         AND target.field_id=mapping.target_field_id
        WHERE mapping.plan_id=p_plan_id AND (
            source.field_id IS NULL OR target.field_id IS NULL OR
            target.semantic_sha256<>mapping.semantic_sha256 OR
            (mapping.converter_kind='copy_v1' AND
             source.semantic_sha256<>target.semantic_sha256)
        )
    ) OR EXISTS (
        SELECT 1 FROM iam_profile_field_revisions AS required
        WHERE required.schema_version_id=p_target_schema_id
          AND required.resource_kind=p_resource_kind AND required.field_state='active'
          AND required.required AND NOT EXISTS (
              SELECT 1 FROM iam_profile_backfill_mappings AS mapping
              WHERE mapping.plan_id=p_plan_id AND mapping.target_field_id=required.field_id
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='IAM profile backfill mapping is inconsistent';
    END IF;
    RETURN v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_mapping_create_v1(p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_target_schema_id uuid, p_mappings jsonb) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_page_create_v1(uuid, uuid, text, uuid, bigint, integer, bytea, bytea, bytea, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_page_create_v1(p_tenant_id uuid, p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_source_count bigint, p_page_size integer, p_expected_source bytea, p_expected_target bytea, p_initial_rolling bytea, p_pages jsonb, p_created_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_page_number integer;
    v_job_id uuid;
    v_payload_reference text;
    v_after_resource_id uuid;
    v_through_resource_id uuid;
    v_expected_count integer;
    v_source_sha256 bytea;
    v_expected_target_sha256 bytea;
    v_prior_through uuid;
    v_page_count integer;
    v_actual_count integer;
    v_actual_sha bytea;
    v_total_count bigint;
    v_source_evidence bytea;
    v_rolling bytea;
BEGIN
    v_source_evidence := ''::bytea;
    v_rolling := p_initial_rolling;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_tenant_id IS NULL OR
       p_plan_id IS NULL OR p_resource_kind NOT IN ('user','organization','role') OR
       p_source_schema_id IS NULL OR p_source_count<0 OR p_page_size NOT BETWEEN 1 AND 250 OR
       pg_catalog.octet_length(p_expected_source)<>32 OR
       pg_catalog.octet_length(p_expected_target)<>32 OR
       pg_catalog.octet_length(p_initial_rolling)<>32 OR
       pg_catalog.jsonb_typeof(p_pages)<>'array' OR
       pg_catalog.jsonb_array_length(p_pages) NOT BETWEEN 1 AND 65536 OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_pages)
                WITH ORDINALITY AS page(value,ordinal)
           WHERE pg_catalog.jsonb_typeof(page.value)<>'object'
              OR (page.value->>'page_number')::integer<>page.ordinal
              OR (page.value->>'expected_count')::integer NOT BETWEEN 0 AND p_page_size
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'payload_sha256','hex'))<>32
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'source_sha256','hex'))<>32
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'expected_target_sha256','hex'))<>32
              OR EXISTS (
                   SELECT 1 FROM pg_catalog.jsonb_object_keys(page.value) AS key
                   WHERE key NOT IN ('page_number','job_id','scheduled_run_at',
                       'payload_reference','payload_sha256','after_resource_id',
                       'through_resource_id','expected_count','source_sha256',
                       'expected_target_sha256')
              )
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill page input is invalid';
    END IF;
    INSERT INTO iam_profile_backfill_pages (
        plan_id,page_number,job_id,scheduled_run_at,payload_reference,payload_sha256,
        after_resource_id,through_resource_id,expected_count,source_sha256,
        expected_target_sha256,state,converted_count,error_count,result_sha256,
        completed_at,created_at
    )
    SELECT p_plan_id,page.ordinal,(page.value->>'job_id')::uuid,
        (page.value->>'scheduled_run_at')::timestamptz,page.value->>'payload_reference',
        pg_catalog.decode(page.value->>'payload_sha256','hex'),
        (page.value->>'after_resource_id')::uuid,(page.value->>'through_resource_id')::uuid,
        (page.value->>'expected_count')::integer,
        pg_catalog.decode(page.value->>'source_sha256','hex'),
        pg_catalog.decode(page.value->>'expected_target_sha256','hex'),
        'queued',0,0,NULL,NULL,p_created_at
    FROM pg_catalog.jsonb_array_elements(p_pages)
         WITH ORDINALITY AS page(value,ordinal);
    GET DIAGNOSTICS v_page_count=ROW_COUNT;
    FOR v_page_number,v_job_id,v_payload_reference,v_after_resource_id,
        v_through_resource_id,v_expected_count,v_source_sha256,
        v_expected_target_sha256 IN
        SELECT page.page_number,page.job_id,page.payload_reference,
               page.after_resource_id,page.through_resource_id,page.expected_count,
               page.source_sha256,page.expected_target_sha256
        FROM iam_profile_backfill_pages AS page
        WHERE page.plan_id=p_plan_id ORDER BY page.page_number
    LOOP
        IF v_payload_reference<>pg_catalog.format(
               'urn:harpy:iam:profile-backfill:%s:%s:%s:v1',
               p_tenant_id,p_plan_id,v_page_number
           ) OR (v_page_number=1 AND v_after_resource_id IS NOT NULL) OR
           (v_page_number>1 AND v_after_resource_id<>v_prior_through) OR
           pg_catalog.substr(v_job_id::text,15,1)<>'7' THEN
            RAISE EXCEPTION USING ERRCODE='23514',
                MESSAGE='IAM profile backfill page identity is invalid';
        END IF;
        SELECT evidence.source_count,evidence.source_sha256
          INTO v_actual_count,v_actual_sha
        FROM iam_profile_backfill_source_page_v1(
            p_resource_kind,p_source_schema_id,v_after_resource_id,
            v_through_resource_id
        ) AS evidence;
        IF v_actual_count<>v_expected_count OR v_actual_sha<>v_source_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='IAM profile backfill source evidence changed';
        END IF;
        v_source_evidence:=v_source_evidence||v_source_sha256;
        v_rolling:=pg_catalog.sha256(v_rolling||v_expected_target_sha256);
        v_prior_through:=v_through_resource_id;
    END LOOP;
    SELECT pg_catalog.count(*) INTO v_total_count FROM (
        SELECT usr.id FROM iam_users AS usr WHERE p_resource_kind='user'
          AND usr.profile_schema_version_id=p_source_schema_id
        UNION ALL
        SELECT org.id FROM iam_organizations AS org WHERE p_resource_kind='organization'
          AND org.profile_schema_version_id=p_source_schema_id
        UNION ALL
        SELECT role.id FROM iam_roles AS role WHERE p_resource_kind='role'
          AND role.profile_schema_version_id=p_source_schema_id
    ) AS resource;
    IF v_total_count<>p_source_count OR
       (SELECT pg_catalog.sum(page.expected_count) FROM iam_profile_backfill_pages AS page
        WHERE page.plan_id=p_plan_id)<>p_source_count OR
       pg_catalog.sha256(v_source_evidence)<>p_expected_source OR
       v_rolling<>p_expected_target THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='IAM profile backfill aggregate evidence is invalid';
    END IF;
    RETURN v_page_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_page_create_v1(p_tenant_id uuid, p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_source_count bigint, p_page_size integer, p_expected_source bytea, p_expected_target bytea, p_initial_rolling bytea, p_pages jsonb, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_page_create_v2(uuid, uuid, text, uuid, bigint, integer, bytea, bytea, bytea, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_page_create_v2(p_tenant_id uuid, p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_source_count bigint, p_page_size integer, p_expected_source bytea, p_expected_target bytea, p_initial_rolling bytea, p_pages jsonb, p_created_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_page_number integer;
    v_job_id uuid;
    v_payload_reference text;
    v_after_resource_id uuid;
    v_through_resource_id uuid;
    v_expected_count integer;
    v_source_sha256 bytea;
    v_expected_target_sha256 bytea;
    v_prior_through uuid;
    v_page_count integer;
    v_actual_count integer;
    v_actual_sha bytea;
    v_total_count bigint;
    v_source_evidence bytea;
    v_rolling bytea;
BEGIN
    v_source_evidence := ''::bytea;
    v_rolling := p_initial_rolling;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_tenant_id IS NULL OR
       p_plan_id IS NULL OR p_resource_kind NOT IN ('user','organization','role') OR
       p_source_schema_id IS NULL OR p_source_count<0 OR p_page_size NOT BETWEEN 1 AND 250 OR
       pg_catalog.octet_length(p_expected_source)<>32 OR
       pg_catalog.octet_length(p_expected_target)<>32 OR
       pg_catalog.octet_length(p_initial_rolling)<>32 OR
       pg_catalog.jsonb_typeof(p_pages)<>'array' OR
       pg_catalog.jsonb_array_length(p_pages) NOT BETWEEN 1 AND 65536 OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_pages)
                WITH ORDINALITY AS page(value,ordinal)
           WHERE pg_catalog.jsonb_typeof(page.value)<>'object'
              OR (page.value->>'page_number')::integer<>page.ordinal
              OR (page.value->>'expected_count')::integer NOT BETWEEN 0 AND p_page_size
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'payload_sha256','hex'))<>32
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'source_sha256','hex'))<>32
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'expected_target_sha256','hex'))<>32
              OR EXISTS (
                   SELECT 1 FROM pg_catalog.jsonb_object_keys(page.value) AS key
                   WHERE key NOT IN ('page_number','job_id','scheduled_run_at',
                       'payload_reference','payload_sha256','after_resource_id',
                       'through_resource_id','expected_count','source_sha256',
                       'expected_target_sha256')
              )
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill page input is invalid';
    END IF;
    INSERT INTO iam_profile_backfill_pages (
        plan_id,page_number,job_id,scheduled_run_at,payload_reference,payload_sha256,
        after_resource_id,through_resource_id,expected_count,source_sha256,
        expected_target_sha256,state,converted_count,error_count,result_sha256,
        completed_at,created_at
    )
    SELECT p_plan_id,page.ordinal,(page.value->>'job_id')::uuid,
        (page.value->>'scheduled_run_at')::timestamptz,page.value->>'payload_reference',
        pg_catalog.decode(page.value->>'payload_sha256','hex'),
        (page.value->>'after_resource_id')::uuid,(page.value->>'through_resource_id')::uuid,
        (page.value->>'expected_count')::integer,
        pg_catalog.decode(page.value->>'source_sha256','hex'),
        pg_catalog.decode(page.value->>'expected_target_sha256','hex'),
        'queued',0,0,NULL,NULL,p_created_at
    FROM pg_catalog.jsonb_array_elements(p_pages)
         WITH ORDINALITY AS page(value,ordinal);
    GET DIAGNOSTICS v_page_count=ROW_COUNT;
    FOR v_page_number,v_job_id,v_payload_reference,v_after_resource_id,
        v_through_resource_id,v_expected_count,v_source_sha256,
        v_expected_target_sha256 IN
        SELECT page.page_number,page.job_id,page.payload_reference,
               page.after_resource_id,page.through_resource_id,page.expected_count,
               page.source_sha256,page.expected_target_sha256
        FROM iam_profile_backfill_pages AS page
        WHERE page.plan_id=p_plan_id ORDER BY page.page_number
    LOOP
        IF v_payload_reference<>pg_catalog.format(
               'urn:harpy:iam:profile-backfill:%s:%s:%s:v1',
               p_tenant_id,p_plan_id,v_page_number
           ) OR (v_page_number=1 AND v_after_resource_id IS NOT NULL) OR
           (v_page_number>1 AND v_after_resource_id<>v_prior_through) OR
           pg_catalog.substr(v_job_id::text,15,1)<>'7' THEN
            RAISE EXCEPTION USING ERRCODE='23514',
                MESSAGE='IAM profile backfill page identity is invalid';
        END IF;
        SELECT evidence.source_count,evidence.source_sha256
          INTO v_actual_count,v_actual_sha
        FROM iam_profile_backfill_source_page_v2(
            p_resource_kind,p_source_schema_id,v_after_resource_id,
            v_through_resource_id
        ) AS evidence;
        IF v_actual_count<>v_expected_count OR v_actual_sha<>v_source_sha256 THEN
            RAISE EXCEPTION USING ERRCODE='40001',
                MESSAGE='IAM profile backfill source evidence changed';
        END IF;
        v_source_evidence:=v_source_evidence||v_source_sha256;
        v_rolling:=pg_catalog.sha256(v_rolling||v_expected_target_sha256);
        v_prior_through:=v_through_resource_id;
    END LOOP;
    SELECT pg_catalog.count(*) INTO v_total_count FROM (
        SELECT usr.id,usr.profile_schema_version_id FROM iam_users AS usr
        WHERE p_resource_kind='user'
        UNION ALL
        SELECT org.id,org.profile_schema_version_id FROM iam_organizations AS org
        WHERE p_resource_kind='organization'
        UNION ALL
        SELECT role.id,role.profile_schema_version_id FROM iam_roles AS role
        WHERE p_resource_kind='role'
    ) AS resource
    JOIN iam_profile_schema_versions AS row_schema
      ON row_schema.id=resource.profile_schema_version_id
     AND row_schema.resource_kind=p_resource_kind
     AND row_schema.state IN ('active','retired')
    JOIN iam_profile_schema_versions AS source_schema
      ON source_schema.id=p_source_schema_id
     AND source_schema.resource_kind=p_resource_kind
     AND source_schema.state='active'
     AND row_schema.version<=source_schema.version;
    IF v_total_count<>p_source_count OR
       (SELECT pg_catalog.sum(page.expected_count) FROM iam_profile_backfill_pages AS page
        WHERE page.plan_id=p_plan_id)<>p_source_count OR
       pg_catalog.sha256(v_source_evidence)<>p_expected_source OR
       v_rolling<>p_expected_target THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='IAM profile backfill aggregate evidence is invalid';
    END IF;
    RETURN v_page_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_page_create_v2(p_tenant_id uuid, p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_source_count bigint, p_page_size integer, p_expected_source bytea, p_expected_target bytea, p_initial_rolling bytea, p_pages jsonb, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_plan_create_v1(name, uuid, uuid, bytea, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_plan_create_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_plan_document bytea, p_plan_sha256 bytea, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_plan jsonb;
    v_plan_id uuid;
    v_resource_kind text;
    v_source_schema_id uuid;
    v_target_schema_id uuid;
    v_target_version bigint;
    v_target_definition_sha256 bytea;
    v_source_count bigint;
    v_page_size integer;
    v_page_count integer;
    v_expected_source bytea;
    v_expected_target bytea;
    v_initial_rolling bytea;
    v_clock bigint;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_draft_revision bigint;
    v_mapping_count integer;
BEGIN
    IF p_tenant_id IS NULL OR p_operation_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256)<>32 OR
       pg_catalog.octet_length(p_plan_sha256)<>32 OR
       pg_catalog.octet_length(p_plan_document) NOT BETWEEN 2 AND 16777216 OR
       pg_catalog.sha256(p_plan_document)<>p_plan_sha256 OR NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id=p_tenant_id AND tenant.schema_name=p_scope_schema
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.domain_cutovers AS cutover
           WHERE cutover.scope_kind='tenant' AND cutover.scope_id=p_tenant_id
             AND cutover.domain='iam' AND cutover.state='v2' AND cutover.writer='v2'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill plan input is invalid';
    END IF;
    IF NOT iam_profile_actor_assert_v1(
        p_scope_schema,p_actor_id,p_manage_permission_id,
        p_expected_token_version,p_expected_authorization_version
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM profile backfill plan authority is denied';
    END IF;
    v_plan:=pg_catalog.convert_from(p_plan_document,'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_plan)<>'object' OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_object_keys(v_plan) AS key
        WHERE key NOT IN (
            'id','resource_kind','source_schema_id','target_schema_id','target_version',
            'target_definition','target_definition_sha256','converter_version',
            'source_count','expected_source_sha256','expected_target_sha256',
            'page_size','initial_rolling_sha256','mappings','pages'
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill plan document is invalid';
    END IF;
    v_plan_id:=(v_plan->>'id')::uuid;
    v_resource_kind:=v_plan->>'resource_kind';
    v_source_schema_id:=(v_plan->>'source_schema_id')::uuid;
    v_target_schema_id:=(v_plan->>'target_schema_id')::uuid;
    v_target_version:=(v_plan->>'target_version')::bigint;
    v_target_definition_sha256:=pg_catalog.decode(
        v_plan->>'target_definition_sha256','hex');
    v_source_count:=(v_plan->>'source_count')::bigint;
    v_page_size:=(v_plan->>'page_size')::integer;
    v_expected_source:=pg_catalog.decode(v_plan->>'expected_source_sha256','hex');
    v_expected_target:=pg_catalog.decode(v_plan->>'expected_target_sha256','hex');
    v_initial_rolling:=pg_catalog.decode(v_plan->>'initial_rolling_sha256','hex');
    v_page_count:=pg_catalog.jsonb_array_length(v_plan->'pages');
    IF v_plan_id IS NULL OR v_resource_kind NOT IN ('user','organization','role') OR
       v_source_schema_id IS NULL OR v_target_schema_id IS NULL OR
       v_source_schema_id=v_target_schema_id OR v_target_version<2 OR
       v_plan->>'converter_version'<>'typed_map_v1' OR v_source_count<0 OR
       v_page_size NOT BETWEEN 1 AND 250 OR v_page_count NOT BETWEEN 1 AND 65536 OR
       pg_catalog.jsonb_typeof(v_plan->'target_definition')<>'object' OR
       pg_catalog.jsonb_typeof(v_plan->'mappings')<>'array' OR
       pg_catalog.octet_length(v_target_definition_sha256)<>32 OR
       pg_catalog.octet_length(v_expected_source)<>32 OR
       pg_catalog.octet_length(v_expected_target)<>32 OR
       pg_catalog.octet_length(v_initial_rolling)<>32 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill plan contract is invalid';
    END IF;
    SELECT receipt.command_key,receipt.request_sha256,receipt.result_id,
           receipt.result_revision INTO v_receipt_command,v_receipt_request,
           v_receipt_id,v_receipt_revision
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id;
    IF FOUND THEN
        IF v_receipt_command<>'iam.profile_backfill.plan_create' OR
           v_receipt_request<>p_request_sha256 OR v_receipt_id<>v_plan_id THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='IAM profile backfill plan identity was reused';
        END IF;
        RETURN QUERY SELECT v_plan_id,v_receipt_revision,true;
        RETURN;
    END IF;
    SELECT iam_profile_backfill_draft_create_v1(
        p_scope_schema,v_target_schema_id,v_resource_kind,v_target_version,
        v_plan->'target_definition',v_target_definition_sha256,v_source_schema_id
    ) INTO v_draft_revision;
    INSERT INTO iam_profile_backfill_plans (
        id,resource_kind,source_schema_id,target_schema_id,converter_version,
        plan_sha256,source_count,expected_source_sha256,expected_target_sha256,
        page_size,page_count,state,activated_at,fenced_at,revision,created_at,updated_at
    ) VALUES (
        v_plan_id,v_resource_kind,v_source_schema_id,v_target_schema_id,'typed_map_v1',
        p_plan_sha256,v_source_count,v_expected_source,v_expected_target,
        v_page_size,v_page_count,'planned',NULL,NULL,1,v_now,v_now
    );
    SELECT iam_profile_backfill_mapping_create_v1(
        v_plan_id,v_resource_kind,v_source_schema_id,v_target_schema_id,
        v_plan->'mappings'
    ) INTO v_mapping_count;
    IF v_draft_revision<>1 OR v_mapping_count<1 THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='IAM profile backfill materialization is inconsistent';
    END IF;
    IF iam_profile_backfill_page_create_v1(
        p_tenant_id,v_plan_id,v_resource_kind,v_source_schema_id,v_source_count,
        v_page_size,v_expected_source,v_expected_target,v_initial_rolling,
        v_plan->'pages',v_now
    )<>v_page_count THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='IAM profile backfill page count is inconsistent';
    END IF;
    INSERT INTO iam_profile_backfill_checkpoints (
        plan_id,completed_pages,converted_count,error_count,rolling_sha256,
        last_page_number,revision,updated_at
    ) VALUES (v_plan_id,0,0,0,v_initial_rolling,NULL,1,v_now);
    UPDATE iam_authorization_clock SET clock_value=clock_value+1,
        revision=revision+1,updated_at=v_now WHERE singleton
        RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM authorization clock is unavailable';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id,command_key,request_sha256,clock_value,result_code,
        result_id,result_revision,result_sha256,created_at
    ) VALUES (
        p_operation_id,'iam.profile_backfill.plan_create',p_request_sha256,v_clock,
        'iam.profile_backfill.planned',v_plan_id,1,p_plan_sha256,v_now
    );
    RETURN QUERY SELECT v_plan_id,1::bigint,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_plan_create_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_plan_document bytea, p_plan_sha256 bytea, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_plan_create_v2(name, uuid, uuid, bytea, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_plan_create_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_plan_document bytea, p_plan_sha256 bytea, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_plan jsonb;
    v_plan_id uuid;
    v_resource_kind text;
    v_source_schema_id uuid;
    v_target_schema_id uuid;
    v_target_version bigint;
    v_target_definition_sha256 bytea;
    v_source_count bigint;
    v_page_size integer;
    v_page_count integer;
    v_expected_source bytea;
    v_expected_target bytea;
    v_initial_rolling bytea;
    v_clock bigint;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_draft_revision bigint;
    v_mapping_count integer;
BEGIN
    IF p_tenant_id IS NULL OR p_operation_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256)<>32 OR
       pg_catalog.octet_length(p_plan_sha256)<>32 OR
       pg_catalog.octet_length(p_plan_document) NOT BETWEEN 2 AND 16777216 OR
       pg_catalog.sha256(p_plan_document)<>p_plan_sha256 OR NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id=p_tenant_id AND tenant.schema_name=p_scope_schema
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.domain_cutovers AS cutover
           WHERE cutover.scope_kind='tenant' AND cutover.scope_id=p_tenant_id
             AND cutover.domain='iam' AND cutover.state='v2' AND cutover.writer='v2'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill plan input is invalid';
    END IF;
    IF NOT iam_profile_actor_assert_v1(
        p_scope_schema,p_actor_id,p_manage_permission_id,
        p_expected_token_version,p_expected_authorization_version
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM profile backfill plan authority is denied';
    END IF;
    v_plan:=pg_catalog.convert_from(p_plan_document,'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_plan)<>'object' OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_object_keys(v_plan) AS key
        WHERE key NOT IN (
            'id','resource_kind','source_schema_id','target_schema_id','target_version',
            'target_definition','target_definition_sha256','converter_version',
            'source_count','expected_source_sha256','expected_target_sha256',
            'page_size','initial_rolling_sha256','mappings','pages'
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill plan document is invalid';
    END IF;
    v_plan_id:=(v_plan->>'id')::uuid;
    v_resource_kind:=v_plan->>'resource_kind';
    v_source_schema_id:=(v_plan->>'source_schema_id')::uuid;
    v_target_schema_id:=(v_plan->>'target_schema_id')::uuid;
    v_target_version:=(v_plan->>'target_version')::bigint;
    v_target_definition_sha256:=pg_catalog.decode(
        v_plan->>'target_definition_sha256','hex');
    v_source_count:=(v_plan->>'source_count')::bigint;
    v_page_size:=(v_plan->>'page_size')::integer;
    v_expected_source:=pg_catalog.decode(v_plan->>'expected_source_sha256','hex');
    v_expected_target:=pg_catalog.decode(v_plan->>'expected_target_sha256','hex');
    v_initial_rolling:=pg_catalog.decode(v_plan->>'initial_rolling_sha256','hex');
    v_page_count:=pg_catalog.jsonb_array_length(v_plan->'pages');
    IF v_plan_id IS NULL OR v_resource_kind NOT IN ('user','organization','role') OR
       v_source_schema_id IS NULL OR v_target_schema_id IS NULL OR
       v_source_schema_id=v_target_schema_id OR v_target_version<2 OR
       v_plan->>'converter_version'<>'typed_map_v1' OR v_source_count<0 OR
       v_page_size NOT BETWEEN 1 AND 250 OR v_page_count NOT BETWEEN 1 AND 65536 OR
       pg_catalog.jsonb_typeof(v_plan->'target_definition')<>'object' OR
       pg_catalog.jsonb_typeof(v_plan->'mappings')<>'array' OR
       pg_catalog.octet_length(v_target_definition_sha256)<>32 OR
       pg_catalog.octet_length(v_expected_source)<>32 OR
       pg_catalog.octet_length(v_expected_target)<>32 OR
       pg_catalog.octet_length(v_initial_rolling)<>32 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM profile backfill plan contract is invalid';
    END IF;
    SELECT receipt.command_key,receipt.request_sha256,receipt.result_id,
           receipt.result_revision INTO v_receipt_command,v_receipt_request,
           v_receipt_id,v_receipt_revision
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id=p_operation_id;
    IF FOUND THEN
        IF v_receipt_command<>'iam.profile_backfill.plan_create' OR
           v_receipt_request<>p_request_sha256 OR v_receipt_id<>v_plan_id THEN
            RAISE EXCEPTION USING ERRCODE='23505',
                MESSAGE='IAM profile backfill plan identity was reused';
        END IF;
        RETURN QUERY SELECT v_plan_id,v_receipt_revision,true;
        RETURN;
    END IF;
    SELECT iam_profile_backfill_draft_create_v2(
        p_scope_schema,v_target_schema_id,v_resource_kind,v_target_version,
        v_plan->'target_definition',v_target_definition_sha256,v_source_schema_id
    ) INTO v_draft_revision;
    INSERT INTO iam_profile_backfill_plans (
        id,resource_kind,source_schema_id,target_schema_id,converter_version,
        plan_sha256,source_count,expected_source_sha256,expected_target_sha256,
        page_size,page_count,state,activated_at,fenced_at,revision,created_at,updated_at
    ) VALUES (
        v_plan_id,v_resource_kind,v_source_schema_id,v_target_schema_id,'typed_map_v1',
        p_plan_sha256,v_source_count,v_expected_source,v_expected_target,
        v_page_size,v_page_count,'planned',NULL,NULL,1,v_now,v_now
    );
    SELECT iam_profile_backfill_mapping_create_v1(
        v_plan_id,v_resource_kind,v_source_schema_id,v_target_schema_id,
        v_plan->'mappings'
    ) INTO v_mapping_count;
    IF v_draft_revision<>1 OR v_mapping_count<1 THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='IAM profile backfill materialization is inconsistent';
    END IF;
    IF iam_profile_backfill_page_create_v2(
        p_tenant_id,v_plan_id,v_resource_kind,v_source_schema_id,v_source_count,
        v_page_size,v_expected_source,v_expected_target,v_initial_rolling,
        v_plan->'pages',v_now
    )<>v_page_count THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='IAM profile backfill page count is inconsistent';
    END IF;
    INSERT INTO iam_profile_backfill_checkpoints (
        plan_id,completed_pages,converted_count,error_count,rolling_sha256,
        last_page_number,revision,updated_at
    ) VALUES (v_plan_id,0,0,0,v_initial_rolling,NULL,1,v_now);
    UPDATE iam_authorization_clock SET clock_value=clock_value+1,
        revision=revision+1,updated_at=v_now WHERE singleton
        RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='IAM authorization clock is unavailable';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id,command_key,request_sha256,clock_value,result_code,
        result_id,result_revision,result_sha256,created_at
    ) VALUES (
        p_operation_id,'iam.profile_backfill.plan_create',p_request_sha256,v_clock,
        'iam.profile_backfill.planned',v_plan_id,1,p_plan_sha256,v_now
    );
    RETURN QUERY SELECT v_plan_id,1::bigint,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_plan_create_v2(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_plan_document bytea, p_plan_sha256 bytea, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_source_page_v1(text, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_source_page_v1(p_resource_kind text, p_source_schema_id uuid, p_after_resource_id uuid, p_through_resource_id uuid) RETURNS TABLE(source_count integer, source_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_id uuid;
    v_revision bigint;
    v_profile_sha256 bytea;
    v_part bytea;
    v_evidence bytea;
    v_count integer;
BEGIN
    v_evidence := ''::bytea;
    v_count := 0;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_source_schema_id IS NULL OR p_through_resource_id IS NULL OR
       (p_after_resource_id IS NOT NULL AND
        p_after_resource_id >= p_through_resource_id) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill source page input is invalid';
    END IF;
    FOR v_id,v_revision,v_profile_sha256 IN
        SELECT resource.id, resource.revision, resource.profile_sha256
        FROM (
            SELECT usr.id, usr.revision, usr.profile_sha256
            FROM iam_users AS usr
            WHERE p_resource_kind = 'user'
              AND usr.profile_schema_version_id = p_source_schema_id
            UNION ALL
            SELECT org.id, org.revision, org.profile_sha256
            FROM iam_organizations AS org
            WHERE p_resource_kind = 'organization'
              AND org.profile_schema_version_id = p_source_schema_id
            UNION ALL
            SELECT role.id, role.revision, role.profile_sha256
            FROM iam_roles AS role
            WHERE p_resource_kind = 'role'
              AND role.profile_schema_version_id = p_source_schema_id
        ) AS resource
        WHERE (p_after_resource_id IS NULL OR resource.id > p_after_resource_id)
          AND resource.id <= p_through_resource_id
        ORDER BY resource.id
    LOOP
        v_part := pg_catalog.convert_to(v_id::text, 'UTF8');
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := pg_catalog.convert_to(v_revision::text, 'UTF8');
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := v_profile_sha256;
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_count := v_count + 1;
    END LOOP;
    RETURN QUERY SELECT v_count, pg_catalog.sha256(v_evidence);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_source_page_v1(p_resource_kind text, p_source_schema_id uuid, p_after_resource_id uuid, p_through_resource_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_source_page_v2(text, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_source_page_v2(p_resource_kind text, p_source_schema_id uuid, p_after_resource_id uuid, p_through_resource_id uuid) RETURNS TABLE(source_count integer, source_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_id uuid;
    v_schema_id uuid;
    v_revision bigint;
    v_profile_sha256 bytea;
    v_part bytea;
    v_evidence bytea;
    v_count integer;
BEGIN
    v_evidence := ''::bytea;
    v_count := 0;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_source_schema_id IS NULL OR p_through_resource_id IS NULL OR
       (p_after_resource_id IS NOT NULL AND
        p_after_resource_id >= p_through_resource_id) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile backfill source page input is invalid';
    END IF;
    FOR v_id,v_schema_id,v_revision,v_profile_sha256 IN
        SELECT resource.id, resource.profile_schema_version_id,
               resource.revision, resource.profile_sha256
        FROM (
            SELECT usr.id, usr.profile_schema_version_id,
                   usr.revision, usr.profile_sha256
            FROM iam_users AS usr
            WHERE p_resource_kind = 'user'
            UNION ALL
            SELECT org.id, org.profile_schema_version_id,
                   org.revision, org.profile_sha256
            FROM iam_organizations AS org
            WHERE p_resource_kind = 'organization'
            UNION ALL
            SELECT role.id, role.profile_schema_version_id,
                   role.revision, role.profile_sha256
            FROM iam_roles AS role
            WHERE p_resource_kind = 'role'
        ) AS resource
        JOIN iam_profile_schema_versions AS row_schema
          ON row_schema.id = resource.profile_schema_version_id
         AND row_schema.resource_kind = p_resource_kind
         AND row_schema.state IN ('active', 'retired')
        JOIN iam_profile_schema_versions AS source_schema
          ON source_schema.id = p_source_schema_id
         AND source_schema.resource_kind = p_resource_kind
         AND source_schema.state = 'active'
         AND row_schema.version <= source_schema.version
        WHERE (p_after_resource_id IS NULL OR resource.id > p_after_resource_id)
          AND resource.id <= p_through_resource_id
        ORDER BY resource.id
    LOOP
        v_part := pg_catalog.convert_to(v_id::text, 'UTF8');
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := pg_catalog.convert_to(v_schema_id::text, 'UTF8');
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := pg_catalog.convert_to(v_revision::text, 'UTF8');
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := v_profile_sha256;
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_count := v_count + 1;
    END LOOP;
    RETURN QUERY SELECT v_count, pg_catalog.sha256(v_evidence);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_source_page_v2(p_resource_kind text, p_source_schema_id uuid, p_after_resource_id uuid, p_through_resource_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_backfill_source_resources_plan_v1(name, text, uuid, uuid, integer, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_backfill_source_resources_plan_v1(p_scope_schema name, p_resource_kind text, p_source_schema_id uuid, p_after_resource_id uuid, p_limit integer, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(resource_id uuid, source_schema_version_id uuid, source_revision bigint, profile_values text, profile_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_source_schema_id IS NULL OR p_limit NOT BETWEEN 1 AND 250 OR
       (p_after_resource_id IS NOT NULL AND p_after_resource_id =
            '00000000-0000-0000-0000-000000000000'::uuid) OR
       NOT EXISTS (
           SELECT 1 FROM iam_profile_schema_versions AS schema_version
           WHERE schema_version.id = p_source_schema_id
             AND schema_version.resource_kind = p_resource_kind
             AND schema_version.state = 'active'
       ) OR NOT iam_profile_actor_assert_v1(
           p_scope_schema, p_actor_id, p_manage_permission_id,
           p_expected_token_version, p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile backfill planning authority is denied';
    END IF;
    IF p_resource_kind = 'user' THEN
        LOCK TABLE iam_users IN SHARE MODE;
        RETURN QUERY
        SELECT resource.id, resource.profile_schema_version_id,
               resource.revision, resource.profile_values::text,
               resource.profile_sha256
        FROM iam_users AS resource
        JOIN iam_profile_schema_versions AS row_schema
          ON row_schema.id = resource.profile_schema_version_id
         AND row_schema.resource_kind = p_resource_kind
         AND row_schema.state IN ('active', 'retired')
        JOIN iam_profile_schema_versions AS source_schema
          ON source_schema.id = p_source_schema_id
         AND row_schema.version <= source_schema.version
        WHERE p_after_resource_id IS NULL OR resource.id > p_after_resource_id
        ORDER BY resource.id LIMIT p_limit;
    ELSIF p_resource_kind = 'organization' THEN
        LOCK TABLE iam_organizations IN SHARE MODE;
        RETURN QUERY
        SELECT resource.id, resource.profile_schema_version_id,
               resource.revision, resource.profile_values::text,
               resource.profile_sha256
        FROM iam_organizations AS resource
        JOIN iam_profile_schema_versions AS row_schema
          ON row_schema.id = resource.profile_schema_version_id
         AND row_schema.resource_kind = p_resource_kind
         AND row_schema.state IN ('active', 'retired')
        JOIN iam_profile_schema_versions AS source_schema
          ON source_schema.id = p_source_schema_id
         AND row_schema.version <= source_schema.version
        WHERE p_after_resource_id IS NULL OR resource.id > p_after_resource_id
        ORDER BY resource.id LIMIT p_limit;
    ELSE
        LOCK TABLE iam_roles IN SHARE MODE;
        RETURN QUERY
        SELECT resource.id, resource.profile_schema_version_id,
               resource.revision, resource.profile_values::text,
               resource.profile_sha256
        FROM iam_roles AS resource
        JOIN iam_profile_schema_versions AS row_schema
          ON row_schema.id = resource.profile_schema_version_id
         AND row_schema.resource_kind = p_resource_kind
         AND row_schema.state IN ('active', 'retired')
        JOIN iam_profile_schema_versions AS source_schema
          ON source_schema.id = p_source_schema_id
         AND row_schema.version <= source_schema.version
        WHERE p_after_resource_id IS NULL OR resource.id > p_after_resource_id
        ORDER BY resource.id LIMIT p_limit;
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_backfill_source_resources_plan_v1(p_scope_schema name, p_resource_kind text, p_source_schema_id uuid, p_after_resource_id uuid, p_limit integer, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_definition_sha256_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_definition_sha256_v1(p_schema_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_resource_kind text;
    v_version bigint;
    v_fields text;
    v_document text;
BEGIN
    SELECT schema_version.resource_kind, schema_version.version
    INTO v_resource_kind, v_version
    FROM iam_profile_schema_versions AS schema_version
    WHERE schema_version.id = p_schema_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM profile schema is unknown';
    END IF;
    SELECT COALESCE(
        '[' || pg_catalog.string_agg(
            '{"cardinality":' ||
                pg_catalog.to_jsonb(snapshot.cardinality)::text ||
            ',"classification":' ||
                pg_catalog.to_jsonb(snapshot.classification)::text ||
            ',"id":' || pg_catalog.to_jsonb(snapshot.field_id::text)::text ||
            ',"key":' || pg_catalog.to_jsonb(snapshot.field_key)::text ||
            ',"logical_type":' ||
                pg_catalog.to_jsonb(snapshot.value_kind)::text ||
            ',"normalization_profile":' ||
                pg_catalog.to_jsonb(snapshot.normalization_profile)::text ||
            ',"required":' || pg_catalog.to_jsonb(snapshot.required)::text ||
            ',"state":' || pg_catalog.to_jsonb(snapshot.field_state)::text ||
            ',"validation":' ||
                iam_profile_validation_canonical_v1(
                    snapshot.validation_schema
                ) || '}',
            ',' ORDER BY snapshot.field_id::text
        ) || ']',
        '[]'
    )
    INTO v_fields
    FROM iam_profile_field_revisions AS snapshot
    WHERE snapshot.schema_version_id = p_schema_id;
    v_document := '{"contract":"harpy/iam-profile-schema/v1"' ||
        ',"fields":' || v_fields ||
        ',"id":' || pg_catalog.to_jsonb(p_schema_id::text)::text ||
        ',"resource_kind":' || pg_catalog.to_jsonb(v_resource_kind)::text ||
        ',"version":' || v_version::text || '}';
    RETURN pg_catalog.sha256(pg_catalog.convert_to(v_document, 'UTF8'));
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_definition_sha256_v1(p_schema_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_display_name_key_repair_v1(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_display_name_key_repair_v1(p_legacy_key text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_changed bigint;
    v_count bigint;
BEGIN
    v_changed := 0;
    IF p_legacy_key IS DISTINCT FROM 'display_name' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM legacy profile key is invalid';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM (
            SELECT subject.id, pg_catalog.count(snapshot.field_id) AS field_count
            FROM iam_users AS subject LEFT JOIN iam_profile_field_revisions AS snapshot
              ON snapshot.schema_version_id = subject.profile_schema_version_id
             AND snapshot.resource_kind = 'user'
             AND snapshot.field_key = 'display_name'
            WHERE subject.profile_values ? 'display_name' GROUP BY subject.id
            UNION ALL
            SELECT subject.id, pg_catalog.count(snapshot.field_id)
            FROM iam_organizations AS subject LEFT JOIN iam_profile_field_revisions AS snapshot
              ON snapshot.schema_version_id = subject.profile_schema_version_id
             AND snapshot.resource_kind = 'organization'
             AND snapshot.field_key = 'display_name'
            WHERE subject.profile_values ? 'display_name' GROUP BY subject.id
            UNION ALL
            SELECT subject.id, pg_catalog.count(snapshot.field_id)
            FROM iam_roles AS subject LEFT JOIN iam_profile_field_revisions AS snapshot
              ON snapshot.schema_version_id = subject.profile_schema_version_id
             AND snapshot.resource_kind = 'role'
             AND snapshot.field_key = 'display_name'
            WHERE subject.profile_values ? 'display_name' GROUP BY subject.id
        ) AS installation_profile(id, field_count)
        WHERE installation_profile.field_count <> 1
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM installation profile snapshot is invalid';
    END IF;
    WITH repaired AS (
        SELECT subject.id,
               iam_profile_installation_legacy_document_v1(
                   subject.profile_values, subject.profile_sha256,
                   snapshot.field_id,
                   snapshot.field_key, snapshot.value_kind,
                   snapshot.cardinality, snapshot.field_state
               ) AS canonical_json
        FROM iam_users AS subject
        JOIN iam_profile_field_revisions AS snapshot
          ON snapshot.schema_version_id = subject.profile_schema_version_id
         AND snapshot.resource_kind = 'user'
         AND snapshot.field_key = 'display_name'
        WHERE subject.profile_values ? 'display_name'
    )
    UPDATE iam_users AS subject
    SET profile_values = repaired.canonical_json::jsonb,
        profile_sha256 = pg_catalog.sha256(
            pg_catalog.convert_to(repaired.canonical_json, 'UTF8')
        ),
        revision = subject.revision + 1,
        updated_at = pg_catalog.statement_timestamp()
    FROM repaired
    WHERE subject.id = repaired.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_changed := v_changed + v_count;
    WITH repaired AS (
        SELECT subject.id,
               iam_profile_installation_legacy_document_v1(
                   subject.profile_values, subject.profile_sha256,
                   snapshot.field_id,
                   snapshot.field_key, snapshot.value_kind,
                   snapshot.cardinality, snapshot.field_state
               ) AS canonical_json
        FROM iam_organizations AS subject
        JOIN iam_profile_field_revisions AS snapshot
          ON snapshot.schema_version_id = subject.profile_schema_version_id
         AND snapshot.resource_kind = 'organization'
         AND snapshot.field_key = 'display_name'
        WHERE subject.profile_values ? 'display_name'
    )
    UPDATE iam_organizations AS subject
    SET profile_values = repaired.canonical_json::jsonb,
        profile_sha256 = pg_catalog.sha256(
            pg_catalog.convert_to(repaired.canonical_json, 'UTF8')
        ),
        revision = subject.revision + 1,
        updated_at = pg_catalog.statement_timestamp()
    FROM repaired
    WHERE subject.id = repaired.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_changed := v_changed + v_count;
    WITH repaired AS (
        SELECT subject.id,
               iam_profile_installation_legacy_document_v1(
                   subject.profile_values, subject.profile_sha256,
                   snapshot.field_id,
                   snapshot.field_key, snapshot.value_kind,
                   snapshot.cardinality, snapshot.field_state
               ) AS canonical_json
        FROM iam_roles AS subject
        JOIN iam_profile_field_revisions AS snapshot
          ON snapshot.schema_version_id = subject.profile_schema_version_id
         AND snapshot.resource_kind = 'role'
         AND snapshot.field_key = 'display_name'
        WHERE subject.profile_values ? 'display_name'
    )
    UPDATE iam_roles AS subject
    SET profile_values = repaired.canonical_json::jsonb,
        profile_sha256 = pg_catalog.sha256(
            pg_catalog.convert_to(repaired.canonical_json, 'UTF8')
        ),
        revision = subject.revision + 1,
        updated_at = pg_catalog.statement_timestamp()
    FROM repaired
    WHERE subject.id = repaired.id;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_changed + v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_display_name_key_repair_v1(p_legacy_key text) OWNER TO harpy_owner;

--
-- Name: iam_profile_display_name_write_normalize_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_display_name_write_normalize_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_display_count bigint;
    v_exact_count bigint;
    v_field_id uuid;
    v_field_key text;
    v_value_kind text;
    v_cardinality text;
    v_field_state text;
    v_canonical text;
BEGIN
    IF pg_catalog.jsonb_typeof(NEW.profile_values) = 'object'
       AND (SELECT pg_catalog.count(*)
            FROM pg_catalog.jsonb_object_keys(NEW.profile_values)) = 1
       AND NEW.profile_values ? 'display_name' THEN
        SELECT pg_catalog.count(*),
               pg_catalog.count(*) FILTER (
                   WHERE snapshot.value_kind = 'string'
                     AND snapshot.cardinality = 'single'
                     AND snapshot.field_state = 'active'
               )
        INTO v_display_count, v_exact_count
        FROM iam_profile_field_revisions AS snapshot
        WHERE snapshot.schema_version_id = NEW.profile_schema_version_id
          AND snapshot.resource_kind = NEW.profile_resource_kind
          AND snapshot.field_key = 'display_name';
        IF v_display_count IS DISTINCT FROM 1
           OR v_exact_count IS DISTINCT FROM 1 THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'IAM profile display name snapshot is invalid';
        END IF;
        SELECT snapshot.field_id, snapshot.field_key, snapshot.value_kind,
               snapshot.cardinality, snapshot.field_state
        INTO STRICT v_field_id, v_field_key, v_value_kind,
                    v_cardinality, v_field_state
        FROM iam_profile_field_revisions AS snapshot
        WHERE snapshot.schema_version_id = NEW.profile_schema_version_id
          AND snapshot.resource_kind = NEW.profile_resource_kind
          AND snapshot.field_key = 'display_name';
        v_canonical := iam_profile_installation_legacy_document_v1(
            NEW.profile_values, NEW.profile_sha256, v_field_id,
            v_field_key, v_value_kind, v_cardinality, v_field_state
        );
        NEW.profile_values := v_canonical::jsonb;
        NEW.profile_sha256 := pg_catalog.sha256(
            pg_catalog.convert_to(v_canonical, 'UTF8')
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_display_name_write_normalize_v1() OWNER TO harpy_owner;

--
-- Name: iam_profile_document_backfill_v1(name, uuid, bytea, text, uuid, uuid, uuid, bytea, bytea, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_document_backfill_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_resource_kind text, p_resource_id uuid, p_expected_source_schema_id uuid, p_target_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_expected_revision bigint, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz;
    v_values jsonb;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_clock bigint;
    v_revision bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF p_operation_id IS NULL OR p_resource_id IS NULL OR
       p_expected_source_schema_id IS NULL OR p_target_schema_id IS NULL OR
       p_expected_source_schema_id IS NOT DISTINCT FROM p_target_schema_id OR
       p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_expected_revision < 1 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_profile_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_profile_document) > 1048576 OR
       pg_catalog.sha256(p_profile_document) IS DISTINCT FROM p_profile_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile document backfill input is invalid';
    END IF;
    v_values := pg_catalog.convert_from(p_profile_document, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_values) <> 'object' OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_each(v_values) AS entry(key, value)
        WHERE entry.key !~
            '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR pg_catalog.jsonb_typeof(entry.value) = 'null'
           OR NOT EXISTS (
                SELECT 1 FROM iam_profile_field_revisions AS field
                WHERE field.schema_version_id = p_target_schema_id
                  AND field.resource_kind = p_resource_kind
                  AND field.field_id = entry.key::uuid
           )
    ) OR EXISTS (
        SELECT 1 FROM iam_profile_field_revisions AS required
        WHERE required.schema_version_id = p_target_schema_id
          AND required.resource_kind = p_resource_kind
          AND required.field_state = 'active' AND required.required
          AND NOT v_values ? required.field_id::text
    ) OR NOT EXISTS (
        SELECT 1 FROM iam_profile_schema_versions AS target
        WHERE target.id = p_target_schema_id
          AND target.resource_kind = p_resource_kind AND target.state = 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile document backfill contract is invalid';
    END IF;
    IF NOT iam_profile_actor_assert_v1(
        p_scope_schema, p_actor_id, p_manage_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile document backfill authority is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_id,
         v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.profile_schema.backfill' OR
           v_receipt_request IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_resource_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM profile backfill operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1, revision = revision + 1, updated_at = v_now
    WHERE singleton RETURNING clock_value INTO v_clock;
    IF p_resource_kind = 'user' THEN
        UPDATE iam_users
        SET profile_schema_version_id = p_target_schema_id,
            profile_values = v_values, profile_sha256 = p_profile_sha256,
            revision = revision + 1, updated_at = v_now
        WHERE id = p_resource_id
          AND profile_schema_version_id = p_expected_source_schema_id
          AND revision = p_expected_revision
        RETURNING revision INTO v_revision;
    ELSIF p_resource_kind = 'organization' THEN
        UPDATE iam_organizations
        SET profile_schema_version_id = p_target_schema_id,
            profile_values = v_values, profile_sha256 = p_profile_sha256,
            revision = revision + 1, updated_at = v_now
        WHERE id = p_resource_id
          AND profile_schema_version_id = p_expected_source_schema_id
          AND revision = p_expected_revision
        RETURNING revision INTO v_revision;
    ELSE
        UPDATE iam_roles
        SET profile_schema_version_id = p_target_schema_id,
            profile_values = v_values, profile_sha256 = p_profile_sha256,
            revision = revision + 1, updated_at = v_now
        WHERE id = p_resource_id
          AND profile_schema_version_id = p_expected_source_schema_id
          AND revision = p_expected_revision
        RETURNING revision INTO v_revision;
    END IF;
    IF v_clock IS NULL OR v_revision IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile document backfill compare-and-swap failed';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.profile_schema.backfill', p_request_sha256,
        v_clock, 'iam.profile_schema.backfilled', p_resource_id, v_revision,
        p_profile_sha256, v_now
    );
    RETURN QUERY SELECT p_resource_id, v_revision, v_clock, false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_profile_document_backfill_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_resource_kind text, p_resource_id uuid, p_expected_source_schema_id uuid, p_target_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_expected_revision bigint, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_document_read_v1(name, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_document_read_v1(p_scope_schema name, p_resource_kind text, p_record_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile document read scope is invalid';
    END IF;
    IF p_resource_kind = 'user' THEN
        SELECT pg_catalog.jsonb_build_object(
            'schema_id', profile_schema_version_id,
            'values', profile_values,
            'sha256', pg_catalog.encode(profile_sha256, 'hex')
        )
        INTO v_document
        FROM iam_users WHERE id = p_record_id;
    ELSIF p_resource_kind = 'organization' THEN
        SELECT pg_catalog.jsonb_build_object(
            'schema_id', profile_schema_version_id,
            'values', profile_values,
            'sha256', pg_catalog.encode(profile_sha256, 'hex')
        )
        INTO v_document
        FROM iam_organizations WHERE id = p_record_id;
    ELSE
        SELECT pg_catalog.jsonb_build_object(
            'schema_id', profile_schema_version_id,
            'values', profile_values,
            'sha256', pg_catalog.encode(profile_sha256, 'hex')
        )
        INTO v_document
        FROM iam_roles WHERE id = p_record_id;
    END IF;
    RETURN v_document;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_document_read_v1(p_scope_schema name, p_resource_kind text, p_record_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_historical_read_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_historical_read_v1(p_scope_schema name, p_schema_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM historical profile read scope is invalid';
    END IF;
    SELECT pg_catalog.jsonb_build_object(
        'schema_id', schema_version.id,
        'resource_kind', schema_version.resource_kind,
        'version', schema_version.version,
        'state', schema_version.state,
        'definition_sha256', pg_catalog.encode(
            schema_version.definition_sha256, 'hex'
        ),
        'fields', COALESCE(
            pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'id', snapshot.field_id,
                'key', snapshot.field_key,
                'logical_type', snapshot.value_kind,
                'cardinality', snapshot.cardinality,
                'required', snapshot.required,
                'classification', snapshot.classification,
                'normalization_profile', snapshot.normalization_profile,
                'state', snapshot.field_state,
                'validation', snapshot.validation_schema,
                'validation_sha256', pg_catalog.encode(
                    snapshot.validation_sha256, 'hex'
                ),
                'semantic_sha256', pg_catalog.encode(
                    snapshot.semantic_sha256, 'hex'
                )
            ) ORDER BY snapshot.field_id) FILTER (
                WHERE snapshot.field_id IS NOT NULL
            ),
            '[]'::jsonb
        )
    )
    INTO v_document
    FROM iam_profile_schema_versions AS schema_version
    LEFT JOIN iam_profile_field_revisions AS snapshot
      ON snapshot.schema_version_id = schema_version.id
     AND snapshot.resource_kind = schema_version.resource_kind
    WHERE schema_version.id = p_schema_id
      AND schema_version.state IN ('active', 'retired')
    GROUP BY schema_version.id, schema_version.resource_kind,
             schema_version.version, schema_version.state,
             schema_version.definition_sha256;
    RETURN v_document;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_historical_read_v1(p_scope_schema name, p_schema_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_installation_legacy_document_v1(jsonb, bytea, uuid, text, text, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_installation_legacy_document_v1(p_profile_values jsonb, p_profile_sha256 bytea, p_stable_field_id uuid, p_field_key text, p_value_kind text, p_cardinality text, p_field_state text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_profile_values IS NULL OR p_stable_field_id IS NULL
       OR p_field_key IS DISTINCT FROM 'display_name'
       OR p_value_kind IS DISTINCT FROM 'string'
       OR p_cardinality IS DISTINCT FROM 'single'
       OR p_field_state IS DISTINCT FROM 'active'
       OR pg_catalog.jsonb_typeof(p_profile_values) <> 'object'
       OR (SELECT pg_catalog.count(*)
           FROM pg_catalog.jsonb_object_keys(p_profile_values)) <> 1
       OR NOT p_profile_values ? 'display_name'
       OR p_profile_values ? p_stable_field_id::text
       OR pg_catalog.jsonb_typeof(
            p_profile_values -> 'display_name'
          ) <> 'string'
       OR p_profile_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_profile_values::text, 'UTF8')
          ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM installation legacy profile shape is invalid';
    END IF;
    RETURN '{' || pg_catalog.to_json(p_stable_field_id::text)::text ||
        ':' || pg_catalog.to_json(
            p_profile_values ->> 'display_name'
        )::text || '}';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_installation_legacy_document_v1(p_profile_values jsonb, p_profile_sha256 bytea, p_stable_field_id uuid, p_field_key text, p_value_kind text, p_cardinality text, p_field_state text) OWNER TO harpy_owner;

--
-- Name: iam_profile_preconversion_reserve_v1(name, uuid, text, uuid, uuid, bigint, bytea, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_preconversion_reserve_v1(p_scope_schema name, p_plan_id uuid, p_resource_kind text, p_resource_id uuid, p_actual_source_schema_id uuid, p_source_revision bigint, p_source_sha256 bytea, p_planned_target_sha256 bytea, p_first_target_sha256 bytea) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_page_number integer;
    v_source_version bigint;
    v_current_schema_id uuid;
    v_current_revision bigint;
    v_current_sha256 bytea;
    v_existing_page_number integer;
    v_existing_resource_kind text;
    v_existing_schema_id uuid;
    v_existing_revision bigint;
    v_existing_source_sha256 bytea;
    v_existing_target_sha256 bytea;
    v_existing_first_sha256 bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_plan_id IS NULL OR p_resource_kind NOT IN ('user','organization','role') OR
       p_resource_id IS NULL OR p_actual_source_schema_id IS NULL OR
       p_source_revision < 1 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_planned_target_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_first_target_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile preconversion reservation is invalid';
    END IF;
    SELECT page.page_number, source.version
    INTO v_page_number, v_source_version
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_backfill_pages AS page ON page.plan_id = plan.id
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.id = p_plan_id AND plan.resource_kind = p_resource_kind
      AND plan.state IN ('planned','running') AND page.state = 'queued'
      AND (page.after_resource_id IS NULL OR p_resource_id > page.after_resource_id)
      AND p_resource_id <= page.through_resource_id
    FOR SHARE OF plan, page, source, target;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile preconversion page is stale';
    END IF;
    IF p_resource_kind = 'user' THEN
        SELECT resource.profile_schema_version_id, resource.revision,
               resource.profile_sha256
        INTO v_current_schema_id, v_current_revision, v_current_sha256
        FROM iam_users AS resource WHERE resource.id = p_resource_id
        FOR UPDATE;
    ELSIF p_resource_kind = 'organization' THEN
        SELECT resource.profile_schema_version_id, resource.revision,
               resource.profile_sha256
        INTO v_current_schema_id, v_current_revision, v_current_sha256
        FROM iam_organizations AS resource WHERE resource.id = p_resource_id
        FOR UPDATE;
    ELSE
        SELECT resource.profile_schema_version_id, resource.revision,
               resource.profile_sha256
        INTO v_current_schema_id, v_current_revision, v_current_sha256
        FROM iam_roles AS resource WHERE resource.id = p_resource_id
        FOR UPDATE;
    END IF;
    IF v_current_schema_id IS DISTINCT FROM p_actual_source_schema_id OR
       v_current_revision IS DISTINCT FROM p_source_revision OR
       v_current_sha256 IS DISTINCT FROM p_source_sha256 OR NOT EXISTS (
           SELECT 1 FROM iam_profile_schema_versions AS actual
           WHERE actual.id = p_actual_source_schema_id
             AND actual.resource_kind = p_resource_kind
             AND actual.state IN ('active','retired')
             AND actual.version <= v_source_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile preconversion source changed';
    END IF;
    SELECT receipt.page_number, receipt.resource_kind,
           receipt.actual_source_schema_id, receipt.source_revision,
           receipt.source_sha256, receipt.planned_target_sha256,
           receipt.first_target_sha256
    INTO v_existing_page_number, v_existing_resource_kind,
         v_existing_schema_id, v_existing_revision,
         v_existing_source_sha256, v_existing_target_sha256,
         v_existing_first_sha256
    FROM iam_profile_backfill_preconversions AS receipt
    WHERE receipt.plan_id = p_plan_id AND receipt.resource_id = p_resource_id;
    IF FOUND THEN
        IF v_existing_page_number IS DISTINCT FROM v_page_number OR
           v_existing_resource_kind IS DISTINCT FROM p_resource_kind OR
           v_existing_schema_id IS DISTINCT FROM p_actual_source_schema_id OR
           v_existing_revision IS DISTINCT FROM p_source_revision OR
           v_existing_source_sha256 IS DISTINCT FROM p_source_sha256 OR
           v_existing_target_sha256 IS DISTINCT FROM p_planned_target_sha256 OR
           v_existing_first_sha256 IS DISTINCT FROM p_first_target_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM profile preconversion identity was reused';
        END IF;
        RETURN v_existing_page_number;
    END IF;
    INSERT INTO iam_profile_backfill_preconversions (
        plan_id, page_number, resource_id, resource_kind,
        actual_source_schema_id, source_revision, source_sha256,
        planned_target_sha256, first_target_revision,
        first_target_sha256, created_at
    ) VALUES (
        p_plan_id, v_page_number, p_resource_id, p_resource_kind,
        p_actual_source_schema_id, p_source_revision, p_source_sha256,
        p_planned_target_sha256, p_source_revision + 1,
        p_first_target_sha256, pg_catalog.transaction_timestamp()
    );
    RETURN v_page_number;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_preconversion_reserve_v1(p_scope_schema name, p_plan_id uuid, p_resource_kind text, p_resource_id uuid, p_actual_source_schema_id uuid, p_source_revision bigint, p_source_sha256 bytea, p_planned_target_sha256 bytea, p_first_target_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_profile_publication_receipt_read_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_publication_receipt_read_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(command_key text, request_sha256 bytea, result_id uuid, target_schema_id uuid, result_revision bigint, authorization_clock bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR NOT iam_profile_actor_assert_v1(
           p_scope_schema, p_actor_id, p_manage_permission_id,
           p_expected_token_version, p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile publication receipt authority is denied';
    END IF;
    RETURN QUERY
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           plan.target_schema_id, receipt.result_revision, receipt.clock_value
    FROM iam_authorization_operation_receipts AS receipt
    LEFT JOIN iam_profile_backfill_plans AS plan
      ON plan.id = receipt.result_id
    WHERE receipt.operation_id = p_operation_id
      AND receipt.command_key IN (
          'iam.profile_schema.publish', 'iam.profile_backfill.plan_create'
      );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_publication_receipt_read_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_read_contract_v1(name, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_read_contract_v1(p_scope_schema name, p_resource_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_source_schema_id uuid;
    v_plan_id uuid;
    v_target_schema_id uuid;
    v_source jsonb;
    v_target jsonb;
    v_mappings jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile read contract scope is invalid';
    END IF;
    SELECT source.id INTO v_source_schema_id
    FROM iam_profile_schema_versions AS source
    WHERE source.resource_kind = p_resource_kind AND source.state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM active profile read schema is unavailable';
    END IF;
    SELECT plan.id, plan.target_schema_id
    INTO v_plan_id, v_target_schema_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind
     AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind
     AND target.state = 'draft'
    WHERE plan.resource_kind = p_resource_kind
      AND plan.source_schema_id = v_source_schema_id
      AND plan.state IN ('planned', 'running', 'verified');
    v_source := iam_profile_schema_snapshot_json_v1(v_source_schema_id);
    IF v_source IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM source profile read contract is unavailable';
    END IF;
    IF v_plan_id IS NOT NULL THEN
        v_target := iam_profile_schema_snapshot_json_v1(v_target_schema_id);
        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'source_field_id', mapping.source_field_id,
                'target_field_id', mapping.target_field_id,
                'converter_kind', mapping.converter_kind,
                'semantic_sha256', pg_catalog.encode(
                    mapping.semantic_sha256, 'hex'
                )
            ) ORDER BY mapping.ordinal
        ), '[]'::jsonb)
        INTO v_mappings
        FROM iam_profile_backfill_mappings AS mapping
        WHERE mapping.plan_id = v_plan_id;
        IF v_target IS NULL OR pg_catalog.jsonb_array_length(v_mappings) < 1 THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'IAM target profile read contract is unavailable';
        END IF;
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'contract', 'harpy/iam-profile-write-contract/v1',
        'plan_id', v_plan_id,
        'source', v_source,
        'target', v_target,
        'mappings', COALESCE(v_mappings, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_read_contract_v1(p_scope_schema name, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: iam_profile_read_contract_v2(name, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_read_contract_v2(p_scope_schema name, p_resource_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_source_schema_id uuid;
    v_plan_id uuid;
    v_target_schema_id uuid;
    v_source jsonb;
    v_target jsonb;
    v_mappings jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile read contract scope is invalid';
    END IF;
    SELECT source.id INTO v_source_schema_id
    FROM iam_profile_schema_versions AS source
    WHERE source.resource_kind = p_resource_kind AND source.state = 'active';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM active profile read schema is unavailable';
    END IF;
    SELECT plan.id, plan.target_schema_id
    INTO v_plan_id, v_target_schema_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.resource_kind = p_resource_kind
      AND plan.source_schema_id = v_source_schema_id
      AND plan.state IN ('planned', 'running', 'verified', 'fenced')
    ORDER BY (plan.state IN ('planned', 'running', 'verified')) DESC,
             COALESCE(plan.recovery_sequence, 0) DESC, plan.created_at DESC
    LIMIT 1;
    v_source := iam_profile_schema_snapshot_json_v1(v_source_schema_id);
    IF v_source IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM source profile read contract is unavailable';
    END IF;
    IF v_plan_id IS NOT NULL THEN
        v_target := iam_profile_schema_snapshot_json_v1(v_target_schema_id);
        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'source_field_id', mapping.source_field_id,
                'target_field_id', mapping.target_field_id,
                'converter_kind', mapping.converter_kind,
                'semantic_sha256', pg_catalog.encode(
                    mapping.semantic_sha256, 'hex'
                )
            ) ORDER BY mapping.ordinal
        ), '[]'::jsonb)
        INTO v_mappings
        FROM iam_profile_backfill_mappings AS mapping
        WHERE mapping.plan_id = v_plan_id;
        IF v_target IS NULL OR pg_catalog.jsonb_array_length(v_mappings) < 1 THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'IAM target profile read contract is unavailable';
        END IF;
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'contract', 'harpy/iam-profile-write-contract/v1',
        'plan_id', v_plan_id,
        'source', v_source,
        'target', v_target,
        'mappings', COALESCE(v_mappings, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_read_contract_v2(p_scope_schema name, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: iam_profile_recovery_inventory_open_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_recovery_inventory_open_v1(p_scope_schema name, p_parent_plan_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS refcursor
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_resource_kind text;
    v_source_schema_id uuid;
    v_target_schema_id uuid;
    v_source_version bigint;
    v_source_definition_sha256 bytea;
    v_target_definition_sha256 bytea;
    v_cursor refcursor;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_parent_plan_id IS NULL OR
       NOT iam_profile_actor_assert_v1(
           p_scope_schema, p_actor_id, p_manage_permission_id,
           p_expected_token_version, p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile recovery inventory authority is denied';
    END IF;
    SELECT parent.resource_kind, parent.source_schema_id, parent.target_schema_id,
           source.version, source.definition_sha256, target.definition_sha256
    INTO v_resource_kind, v_source_schema_id, v_target_schema_id,
         v_source_version, v_source_definition_sha256,
         v_target_definition_sha256
    FROM iam_profile_backfill_plans AS parent
    JOIN iam_profile_schema_versions AS source
      ON source.id = parent.source_schema_id
     AND source.resource_kind = parent.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = parent.target_schema_id
     AND target.resource_kind = parent.resource_kind AND target.state = 'draft'
     AND target.version = source.version + 1
    WHERE parent.id = p_parent_plan_id AND parent.state = 'fenced'
      AND NOT EXISTS (
          SELECT 1 FROM iam_profile_backfill_plans AS child
          WHERE child.recovery_of_plan_id = parent.id
      )
    FOR SHARE OF parent, source, target;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile recovery parent is unavailable';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM iam_profile_recovery_resources_v1 AS resource
        LEFT JOIN iam_profile_schema_versions AS row_schema
          ON row_schema.id = resource.schema_version_id
         AND row_schema.resource_kind = resource.resource_kind
        WHERE resource.resource_kind = v_resource_kind AND (
            row_schema.id IS NULL OR
            (resource.schema_version_id = v_target_schema_id AND
             row_schema.state <> 'draft') OR
            (resource.schema_version_id <> v_target_schema_id AND
             (row_schema.state NOT IN ('active', 'retired') OR
              row_schema.version > v_source_version))
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile recovery inventory lineage is invalid';
    END IF;
    IF iam_profile_schema_snapshot_json_v1(v_source_schema_id) IS NULL OR
       iam_profile_schema_snapshot_json_v1(v_target_schema_id) IS NULL OR
       iam_profile_definition_sha256_v1(v_source_schema_id) IS DISTINCT FROM
           v_source_definition_sha256 OR
       iam_profile_definition_sha256_v1(v_target_schema_id) IS DISTINCT FROM
           v_target_definition_sha256 OR EXISTS (
           SELECT 1 FROM (
               SELECT DISTINCT resource.schema_version_id
               FROM iam_profile_recovery_resources_v1 AS resource
               WHERE resource.resource_kind = v_resource_kind
           ) AS inventory_schema
           JOIN iam_profile_schema_versions AS row_schema
             ON row_schema.id = inventory_schema.schema_version_id
            AND row_schema.resource_kind = v_resource_kind
           WHERE iam_profile_definition_sha256_v1(row_schema.id) IS DISTINCT FROM
                   row_schema.definition_sha256
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile recovery schema snapshot drifted';
    END IF;
    IF EXISTS (
        SELECT 1 FROM iam_profile_backfill_mappings AS mapping
        LEFT JOIN iam_profile_field_revisions AS source_field
          ON source_field.schema_version_id = v_source_schema_id
         AND source_field.resource_kind = v_resource_kind
         AND source_field.field_id = mapping.source_field_id
        LEFT JOIN iam_profile_field_revisions AS target_field
          ON target_field.schema_version_id = v_target_schema_id
         AND target_field.resource_kind = v_resource_kind
         AND target_field.field_id = mapping.target_field_id
        WHERE mapping.plan_id = p_parent_plan_id AND (
            source_field.field_id IS NULL OR target_field.field_id IS NULL OR
            mapping.semantic_sha256 <> target_field.semantic_sha256 OR
            (mapping.converter_kind = 'copy_v1' AND
             source_field.semantic_sha256 <> target_field.semantic_sha256)
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile recovery mapping semantic drifted';
    END IF;
    IF EXISTS (
        SELECT 1 FROM iam_profile_recovery_resources_v1 AS resource
        WHERE resource.resource_kind = v_resource_kind
          AND resource.schema_version_id = v_target_schema_id AND (
              EXISTS (
                  SELECT 1 FROM pg_catalog.jsonb_each(resource.profile_values)
                       AS entry(key, value)
                  WHERE entry.key !~
                      '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                     OR pg_catalog.jsonb_typeof(entry.value) = 'null'
                     OR NOT EXISTS (
                         SELECT 1 FROM iam_profile_field_revisions AS field
                         WHERE field.schema_version_id = v_target_schema_id
                           AND field.resource_kind = v_resource_kind
                           AND field.field_id::text = entry.key
                     )
              ) OR EXISTS (
                  SELECT 1 FROM iam_profile_field_revisions AS required
                  WHERE required.schema_version_id = v_target_schema_id
                    AND required.resource_kind = v_resource_kind
                    AND required.field_state = 'active' AND required.required
                    AND NOT resource.profile_values ? required.field_id::text
              )
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile recovery target document is invalid';
    END IF;
    v_cursor := 'iam_profile_recovery_inventory_v1';
    IF v_resource_kind = 'user' THEN
        OPEN v_cursor NO SCROLL FOR
        SELECT resource.id,resource.profile_schema_version_id,row_schema.version,
               row_schema.state,CASE WHEN resource.profile_schema_version_id =
               v_target_schema_id THEN 'target' ELSE 'source' END,
               resource.revision,resource.profile_values::text,resource.profile_sha256
        FROM iam_users AS resource JOIN iam_profile_schema_versions AS row_schema
          ON row_schema.id = resource.profile_schema_version_id
         AND row_schema.resource_kind = 'user' ORDER BY resource.id;
    ELSIF v_resource_kind = 'organization' THEN
        OPEN v_cursor NO SCROLL FOR
        SELECT resource.id,resource.profile_schema_version_id,row_schema.version,
               row_schema.state,CASE WHEN resource.profile_schema_version_id =
               v_target_schema_id THEN 'target' ELSE 'source' END,
               resource.revision,resource.profile_values::text,resource.profile_sha256
        FROM iam_organizations AS resource JOIN iam_profile_schema_versions AS row_schema
          ON row_schema.id = resource.profile_schema_version_id
         AND row_schema.resource_kind = 'organization' ORDER BY resource.id;
    ELSE
        OPEN v_cursor NO SCROLL FOR
        SELECT resource.id,resource.profile_schema_version_id,row_schema.version,
               row_schema.state,CASE WHEN resource.profile_schema_version_id =
               v_target_schema_id THEN 'target' ELSE 'source' END,
               resource.revision,resource.profile_values::text,resource.profile_sha256
        FROM iam_roles AS resource JOIN iam_profile_schema_versions AS row_schema
          ON row_schema.id = resource.profile_schema_version_id
         AND row_schema.resource_kind = 'role' ORDER BY resource.id;
    END IF;
    RETURN v_cursor;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_profile_recovery_inventory_open_v1(p_scope_schema name, p_parent_plan_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_recovery_materialize_v1(uuid, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_recovery_materialize_v1(p_tenant_id uuid, p_plan_document bytea, p_plan_sha256 bytea, p_created_at timestamp with time zone) RETURNS TABLE(plan_id uuid, resource_kind text, source_schema_id uuid, target_schema_id uuid, remaining_source_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_plan jsonb;
    v_plan_id uuid;
    v_parent_id uuid;
    v_root_id uuid;
    v_sequence bigint;
    v_resource text;
    v_source_id uuid;
    v_target_id uuid;
    v_target_version bigint;
    v_converter text;
    v_parent_sha bytea;
    v_target_definition_sha bytea;
    v_inherited_count bigint;
    v_inherited_sha bytea;
    v_remaining_count bigint;
    v_remaining_sha bytea;
    v_expected_target_sha bytea;
    v_initial_rolling bytea;
    v_page_size integer;
    v_page_count integer;
    v_parent_mappings jsonb;
    v_expected_root uuid;
    v_expected_sequence bigint;
    v_target_count bigint;
    v_actual_target_sha bytea;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_tenant_id IS NULL OR
       pg_catalog.octet_length(p_plan_sha256) <> 32 OR
       pg_catalog.octet_length(p_plan_document) NOT BETWEEN 2 AND 16777216 OR
       pg_catalog.sha256(p_plan_document) <> p_plan_sha256 OR
       p_created_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile recovery materialization input is invalid';
    END IF;
    v_plan := pg_catalog.convert_from(p_plan_document,'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_plan) <> 'object' OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_object_keys(v_plan) AS key
        WHERE key NOT IN (
            'id','resource_kind','recovery_of_plan_id','recovery_root_plan_id',
            'recovery_sequence','parent_plan_sha256','source_schema_id',
            'target_schema_id','target_version','target_definition_sha256',
            'converter_version','inherited_target_count','inherited_target_sha256',
            'remaining_source_count','remaining_source_sha256',
            'expected_remaining_target_sha256','page_size',
            'initial_rolling_sha256','mappings','pages'
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile recovery plan document is invalid';
    END IF;
    v_plan_id := (v_plan->>'id')::uuid;
    v_parent_id := (v_plan->>'recovery_of_plan_id')::uuid;
    v_root_id := (v_plan->>'recovery_root_plan_id')::uuid;
    v_sequence := (v_plan->>'recovery_sequence')::bigint;
    v_resource := v_plan->>'resource_kind';
    v_source_id := (v_plan->>'source_schema_id')::uuid;
    v_target_id := (v_plan->>'target_schema_id')::uuid;
    v_target_version := (v_plan->>'target_version')::bigint;
    v_converter := v_plan->>'converter_version';
    v_parent_sha := pg_catalog.decode(v_plan->>'parent_plan_sha256','hex');
    v_target_definition_sha := pg_catalog.decode(
        v_plan->>'target_definition_sha256','hex');
    v_inherited_count := (v_plan->>'inherited_target_count')::bigint;
    v_inherited_sha := pg_catalog.decode(
        v_plan->>'inherited_target_sha256','hex');
    v_remaining_count := (v_plan->>'remaining_source_count')::bigint;
    v_remaining_sha := pg_catalog.decode(v_plan->>'remaining_source_sha256','hex');
    v_expected_target_sha := pg_catalog.decode(
        v_plan->>'expected_remaining_target_sha256','hex');
    v_page_size := (v_plan->>'page_size')::integer;
    v_initial_rolling := pg_catalog.decode(
        v_plan->>'initial_rolling_sha256','hex');
    v_page_count := pg_catalog.jsonb_array_length(v_plan->'pages');
    IF v_plan_id IS NULL OR v_parent_id IS NULL OR v_root_id IS NULL OR
       v_plan_id IN (v_parent_id,v_root_id) OR v_sequence < 1 OR
       v_resource NOT IN ('user','organization','role') OR v_source_id IS NULL OR
       v_target_id IS NULL OR v_source_id = v_target_id OR v_target_version < 2 OR
       v_converter <> 'typed_map_v1' OR v_inherited_count < 0 OR
       v_remaining_count < 0 OR v_page_size NOT BETWEEN 1 AND 250 OR
       pg_catalog.jsonb_typeof(v_plan->'mappings') <> 'array' OR
       pg_catalog.jsonb_typeof(v_plan->'pages') <> 'array' OR
       pg_catalog.octet_length(v_parent_sha) <> 32 OR
       pg_catalog.octet_length(v_target_definition_sha) <> 32 OR
       pg_catalog.octet_length(v_inherited_sha) <> 32 OR
       pg_catalog.octet_length(v_remaining_sha) <> 32 OR
       pg_catalog.octet_length(v_expected_target_sha) <> 32 OR
       pg_catalog.octet_length(v_initial_rolling) <> 32 OR
       (v_remaining_count = 0 AND v_page_count <> 0) OR
       (v_remaining_count > 0 AND v_page_count NOT BETWEEN 1 AND 65536) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile recovery plan contract is invalid';
    END IF;
    SELECT COALESCE(parent.recovery_root_plan_id,parent.id),
           COALESCE(parent.recovery_sequence,0) + 1
    INTO v_expected_root,v_expected_sequence
    FROM iam_profile_backfill_plans AS parent
    JOIN iam_profile_schema_versions AS source
      ON source.id = parent.source_schema_id AND source.state = 'active'
     AND source.resource_kind = parent.resource_kind
    JOIN iam_profile_schema_versions AS target
      ON target.id = parent.target_schema_id AND target.state = 'draft'
     AND target.resource_kind = parent.resource_kind
     AND target.version = source.version + 1
    WHERE parent.id = v_parent_id AND parent.state = 'fenced'
      AND parent.resource_kind = v_resource
      AND parent.source_schema_id = v_source_id
      AND parent.target_schema_id = v_target_id
      AND parent.converter_version = v_converter
      AND parent.plan_sha256 = v_parent_sha
      AND target.version = v_target_version
      AND target.definition_sha256 = v_target_definition_sha
      AND NOT EXISTS (SELECT 1 FROM iam_profile_backfill_plans AS child
                      WHERE child.recovery_of_plan_id = parent.id)
    FOR UPDATE OF parent FOR SHARE OF source, target;
    IF v_expected_root IS NULL OR v_root_id <> v_expected_root OR
       v_sequence <> v_expected_sequence THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile recovery parent changed';
    END IF;
    SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal', mapping.ordinal, 'source_field_id', mapping.source_field_id,
        'target_field_id', mapping.target_field_id,
        'converter_kind', mapping.converter_kind,
        'semantic_sha256', pg_catalog.encode(mapping.semantic_sha256,'hex')
    ) ORDER BY mapping.ordinal) INTO v_parent_mappings
    FROM iam_profile_backfill_mappings AS mapping WHERE mapping.plan_id = v_parent_id;
    IF v_parent_mappings IS NULL OR v_plan->'mappings' <> v_parent_mappings THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile recovery mapping contract changed';
    END IF;
    INSERT INTO iam_profile_backfill_plans (
        id,resource_kind,source_schema_id,target_schema_id,converter_version,
        plan_sha256,source_count,expected_source_sha256,expected_target_sha256,
        page_size,page_count,state,revision,created_at,updated_at,
        recovery_of_plan_id,recovery_root_plan_id,recovery_sequence,
        parent_plan_sha256,target_definition_sha256,inherited_target_count,
        inherited_target_sha256,remaining_source_count,remaining_source_sha256,
        expected_remaining_target_sha256,initial_rolling_sha256
    ) VALUES (
        v_plan_id,v_resource,v_source_id,v_target_id,v_converter,p_plan_sha256,
        v_remaining_count,v_remaining_sha,v_expected_target_sha,v_page_size,
        v_page_count,'planned',1,p_created_at,p_created_at,v_parent_id,v_root_id,
        v_sequence,v_parent_sha,v_target_definition_sha,v_inherited_count,
        v_inherited_sha,v_remaining_count,v_remaining_sha,v_expected_target_sha,
        v_initial_rolling
    );
    INSERT INTO iam_profile_backfill_mappings
    SELECT v_plan_id,mapping.ordinal,mapping.source_field_id,mapping.target_field_id,
           mapping.converter_kind,mapping.semantic_sha256 FROM iam_profile_backfill_mappings AS mapping
    WHERE mapping.plan_id = v_parent_id ORDER BY mapping.ordinal;
    IF v_remaining_count > 0 THEN
        IF iam_profile_recovery_pages_create_v1(
            p_tenant_id,v_plan_id,v_resource,v_source_id,v_target_id,
            v_remaining_count,v_page_size,v_remaining_sha,v_expected_target_sha,
            v_initial_rolling,v_inherited_count,v_inherited_sha,
            v_plan->'pages',p_created_at
        ) <> v_page_count THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'IAM profile recovery pages are incomplete';
        END IF;
    ELSE
        SELECT evidence.target_count,evidence.target_sha256
        INTO v_target_count,v_actual_target_sha
        FROM iam_profile_recovery_target_evidence_v1(v_resource,v_target_id)
             AS evidence;
        IF v_remaining_sha <> pg_catalog.sha256(''::bytea) OR
           v_expected_target_sha <> v_initial_rolling OR
           v_target_count <> v_inherited_count OR
           v_actual_target_sha <> v_inherited_sha THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM empty profile recovery evidence is invalid';
        END IF;
    END IF;
    INSERT INTO iam_profile_backfill_checkpoints (
        plan_id,completed_pages,converted_count,error_count,rolling_sha256,
        last_page_number,revision,updated_at
    ) VALUES (v_plan_id,0,0,0,v_initial_rolling,NULL,1,p_created_at);
    RETURN QUERY SELECT v_plan_id,v_resource,v_source_id,v_target_id,
        v_remaining_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_recovery_materialize_v1(p_tenant_id uuid, p_plan_document bytea, p_plan_sha256 bytea, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_profile_recovery_pages_create_v1(uuid, uuid, text, uuid, uuid, bigint, integer, bytea, bytea, bytea, bigint, bytea, jsonb, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_recovery_pages_create_v1(p_tenant_id uuid, p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_target_schema_id uuid, p_remaining_count bigint, p_page_size integer, p_remaining_source_sha256 bytea, p_expected_target_sha256 bytea, p_initial_rolling_sha256 bytea, p_inherited_target_count bigint, p_inherited_target_sha256 bytea, p_pages jsonb, p_created_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_number integer;
    v_job_id uuid;
    v_reference text;
    v_after uuid;
    v_through uuid;
    v_expected_count integer;
    v_source_sha256 bytea;
    v_target_sha256 bytea;
    v_prior uuid;
    v_page_count integer;
    v_actual_count integer;
    v_actual_sha256 bytea;
    v_target_count bigint;
    v_inherited_sha256 bytea;
    v_source_evidence bytea;
    v_rolling bytea;
    v_total bigint;
BEGIN
    v_source_evidence := pg_catalog.sha256(''::bytea);
    v_rolling := p_initial_rolling_sha256;
    v_total := 0;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR p_tenant_id IS NULL OR
       p_plan_id IS NULL OR p_resource_kind NOT IN ('user','organization','role') OR
       p_source_schema_id IS NULL OR p_target_schema_id IS NULL OR
       p_source_schema_id = p_target_schema_id OR p_remaining_count < 1 OR
       p_page_size NOT BETWEEN 1 AND 250 OR p_inherited_target_count < 0 OR
       pg_catalog.octet_length(p_remaining_source_sha256) <> 32 OR
       pg_catalog.octet_length(p_expected_target_sha256) <> 32 OR
       pg_catalog.octet_length(p_initial_rolling_sha256) <> 32 OR
       pg_catalog.octet_length(p_inherited_target_sha256) <> 32 OR
       pg_catalog.jsonb_typeof(p_pages) <> 'array' OR
       pg_catalog.jsonb_array_length(p_pages) NOT BETWEEN 1 AND 65536 OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_pages)
                WITH ORDINALITY AS page(value,ordinal)
           WHERE pg_catalog.jsonb_typeof(page.value) <> 'object'
              OR (page.value->>'page_number')::integer <> page.ordinal
              OR (page.value->>'expected_count')::integer NOT BETWEEN 1 AND p_page_size
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'payload_sha256','hex')) <> 32
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'source_sha256','hex')) <> 32
              OR pg_catalog.octet_length(pg_catalog.decode(
                    page.value->>'expected_target_sha256','hex')) <> 32
              OR EXISTS (SELECT 1 FROM pg_catalog.jsonb_object_keys(page.value) AS key
                 WHERE key NOT IN ('page_number','job_id','scheduled_run_at',
                     'payload_reference','payload_sha256','after_resource_id',
                     'through_resource_id','expected_count','source_sha256',
                     'expected_target_sha256'))
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile recovery page input is invalid';
    END IF;
    INSERT INTO iam_profile_backfill_pages (
        plan_id,page_number,job_id,scheduled_run_at,payload_reference,payload_sha256,
        after_resource_id,through_resource_id,expected_count,source_sha256,
        expected_target_sha256,state,converted_count,error_count,result_sha256,
        completed_at,created_at
    )
    SELECT p_plan_id,page.ordinal,(page.value->>'job_id')::uuid,
        (page.value->>'scheduled_run_at')::timestamptz,page.value->>'payload_reference',
        pg_catalog.decode(page.value->>'payload_sha256','hex'),
        (page.value->>'after_resource_id')::uuid,(page.value->>'through_resource_id')::uuid,
        (page.value->>'expected_count')::integer,
        pg_catalog.decode(page.value->>'source_sha256','hex'),
        pg_catalog.decode(page.value->>'expected_target_sha256','hex'),
        'queued',0,0,NULL,NULL,p_created_at
    FROM pg_catalog.jsonb_array_elements(p_pages)
         WITH ORDINALITY AS page(value,ordinal);
    GET DIAGNOSTICS v_page_count = ROW_COUNT;
    FOR v_number,v_job_id,v_reference,v_after,v_through,v_expected_count,
        v_source_sha256,v_target_sha256 IN
        SELECT page.page_number,page.job_id,page.payload_reference,
               page.after_resource_id,page.through_resource_id,
               page.expected_count,page.source_sha256,page.expected_target_sha256
        FROM iam_profile_backfill_pages AS page
        WHERE page.plan_id = p_plan_id ORDER BY page.page_number
    LOOP
        IF v_reference <> pg_catalog.format(
               'urn:harpy:iam:profile-backfill:%s:%s:%s:v1',
               p_tenant_id,p_plan_id,v_number
           ) OR (v_number = 1 AND v_after IS NOT NULL) OR
           (v_number > 1 AND v_after <> v_prior) OR
           pg_catalog.substr(v_job_id::text,15,1) <> '7' THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'IAM profile recovery page identity is invalid';
        END IF;
        SELECT evidence.source_count,evidence.source_sha256
        INTO v_actual_count,v_actual_sha256
        FROM iam_profile_recovery_source_page_v1(
            p_resource_kind,p_source_schema_id,p_target_schema_id,v_after,v_through
        ) AS evidence;
        IF v_actual_count <> v_expected_count OR
           v_actual_sha256 <> v_source_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM profile recovery source evidence changed';
        END IF;
        v_source_evidence := pg_catalog.sha256(
            v_source_evidence || v_source_sha256
        );
        v_rolling := pg_catalog.sha256(v_rolling || v_target_sha256);
        v_total := v_total + v_expected_count;
        v_prior := v_through;
    END LOOP;
    IF EXISTS (
        SELECT 1 FROM iam_profile_recovery_resources_v1 AS resource
        WHERE resource.resource_kind = p_resource_kind
          AND resource.schema_version_id <> p_target_schema_id
          AND resource.resource_id > v_prior
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile recovery source evidence changed';
    END IF;
    SELECT evidence.target_count,evidence.target_sha256
    INTO v_target_count,v_inherited_sha256
    FROM iam_profile_recovery_target_evidence_v1(
        p_resource_kind,p_target_schema_id
    ) AS evidence;
    IF v_total <> p_remaining_count OR
        v_source_evidence <> p_remaining_source_sha256 OR
        v_rolling <> p_expected_target_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile recovery aggregate evidence is invalid';
    END IF;
    IF v_target_count <> p_inherited_target_count OR
       v_inherited_sha256 <> p_inherited_target_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile recovery target evidence changed';
    END IF;
    RETURN v_page_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_recovery_pages_create_v1(p_tenant_id uuid, p_plan_id uuid, p_resource_kind text, p_source_schema_id uuid, p_target_schema_id uuid, p_remaining_count bigint, p_page_size integer, p_remaining_source_sha256 bytea, p_expected_target_sha256 bytea, p_initial_rolling_sha256 bytea, p_inherited_target_count bigint, p_inherited_target_sha256 bytea, p_pages jsonb, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_profile_recovery_parent_read_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_recovery_parent_read_v1(p_scope_schema name, p_parent_plan_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(plan_id uuid, recovery_root_plan_id uuid, recovery_sequence bigint, plan_sha256 bytea, resource_kind text, source_schema_id uuid, target_schema_id uuid, converter_version text, existing_child_plan_id uuid, source_snapshot jsonb, target_snapshot jsonb, mappings jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_root_plan_id uuid;
    v_sequence bigint;
    v_plan_sha256 bytea;
    v_resource_kind text;
    v_source_schema_id uuid;
    v_target_schema_id uuid;
    v_converter_version text;
    v_child_plan_id uuid;
    v_source_snapshot jsonb;
    v_target_snapshot jsonb;
    v_mappings jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_parent_plan_id IS NULL OR NOT iam_profile_actor_assert_v1(
           p_scope_schema, p_actor_id, p_manage_permission_id,
           p_expected_token_version, p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile recovery parent authority is denied';
    END IF;
    SELECT parent.recovery_root_plan_id, COALESCE(parent.recovery_sequence, 0),
           parent.plan_sha256, parent.resource_kind, parent.source_schema_id,
           parent.target_schema_id, parent.converter_version
    INTO v_root_plan_id, v_sequence, v_plan_sha256, v_resource_kind,
         v_source_schema_id, v_target_schema_id, v_converter_version
    FROM iam_profile_backfill_plans AS parent
    WHERE parent.id = p_parent_plan_id AND parent.state = 'fenced'
    FOR UPDATE OF parent;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile recovery parent is unavailable';
    END IF;
    SELECT child.id INTO v_child_plan_id
    FROM iam_profile_backfill_plans AS child
    WHERE child.recovery_of_plan_id = p_parent_plan_id;
    IF v_child_plan_id IS NOT NULL THEN
        RETURN QUERY SELECT p_parent_plan_id, v_root_plan_id, v_sequence,
            v_plan_sha256, v_resource_kind, v_source_schema_id,
            v_target_schema_id, v_converter_version, v_child_plan_id,
            NULL::jsonb, NULL::jsonb, NULL::jsonb;
        RETURN;
    END IF;
    PERFORM 1
    FROM iam_profile_schema_versions AS source
    JOIN iam_profile_schema_versions AS target
      ON target.id = v_target_schema_id
     AND target.resource_kind = v_resource_kind AND target.state = 'draft'
     AND target.version = source.version + 1
    WHERE source.id = v_source_schema_id
      AND source.resource_kind = v_resource_kind AND source.state = 'active'
    FOR SHARE OF source, target;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile recovery lineage is unavailable';
    END IF;
    v_source_snapshot := iam_profile_schema_snapshot_json_v1(v_source_schema_id);
    v_target_snapshot := iam_profile_schema_snapshot_json_v1(v_target_schema_id);
    SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'source_field_id', mapping.source_field_id,
        'target_field_id', mapping.target_field_id,
        'converter_kind', mapping.converter_kind,
        'semantic_sha256', pg_catalog.encode(mapping.semantic_sha256, 'hex')
    ) ORDER BY mapping.ordinal), '[]'::jsonb)
    INTO v_mappings
    FROM iam_profile_backfill_mappings AS mapping
    WHERE mapping.plan_id = p_parent_plan_id;
    IF v_source_snapshot IS NULL OR v_target_snapshot IS NULL OR
       pg_catalog.jsonb_array_length(v_mappings) < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile recovery parent contract is unavailable';
    END IF;
    RETURN QUERY SELECT p_parent_plan_id, v_root_plan_id, v_sequence,
        v_plan_sha256, v_resource_kind, v_source_schema_id, v_target_schema_id,
        v_converter_version, v_child_plan_id, v_source_snapshot,
        v_target_snapshot, v_mappings;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_recovery_parent_read_v1(p_scope_schema name, p_parent_plan_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_recovery_plan_create_v1(name, uuid, uuid, bytea, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_recovery_plan_create_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_plan_document bytea, p_plan_sha256 bytea, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, result_state text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_plan jsonb;
    v_plan_id uuid;
    v_resource text;
    v_source_id uuid;
    v_target_id uuid;
    v_remaining_count bigint;
    v_revision bigint;
    v_state text;
    v_clock bigint;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_tenant_id IS NULL OR p_operation_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256) <> 32 OR
       pg_catalog.octet_length(p_plan_sha256) <> 32 OR
       pg_catalog.octet_length(p_plan_document) NOT BETWEEN 2 AND 16777216 OR
       pg_catalog.sha256(p_plan_document) <> p_plan_sha256 OR NOT EXISTS (
           SELECT 1 FROM platform.tenants AS tenant
           WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.domain_cutovers AS cutover
           WHERE cutover.scope_kind = 'tenant' AND cutover.scope_id = p_tenant_id
             AND cutover.domain = 'iam' AND cutover.state = 'v2'
             AND cutover.writer = 'v2'
       ) OR NOT iam_profile_actor_assert_v1(
           p_scope_schema,p_actor_id,p_manage_permission_id,
           p_expected_token_version,p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile recovery plan authority is denied';
    END IF;
    v_plan := pg_catalog.convert_from(p_plan_document,'UTF8')::jsonb;
    v_plan_id := (v_plan->>'id')::uuid;
    IF v_plan_id IS NULL OR v_plan_id =
       '00000000-0000-0000-0000-000000000000'::uuid THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile recovery plan identity is invalid';
    END IF;
    SELECT receipt.command_key,receipt.request_sha256,receipt.result_id,
           plan.revision,plan.state,receipt.clock_value
    INTO v_receipt_command,v_receipt_request,v_receipt_id,
         v_revision,v_state,v_clock
    FROM iam_authorization_operation_receipts AS receipt
    JOIN iam_profile_backfill_plans AS plan ON plan.id = receipt.result_id
    WHERE receipt.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt_command <> 'iam.profile_backfill.recovery_create' OR
           v_receipt_request <> p_request_sha256 OR v_receipt_id <> v_plan_id THEN
            RAISE EXCEPTION USING ERRCODE = 'P5742',
                MESSAGE = 'IAM profile recovery operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_plan_id,v_revision,v_clock,v_state,true;
        RETURN;
    END IF;
    BEGIN
        SELECT materialized.plan_id,materialized.resource_kind,
               materialized.source_schema_id,materialized.target_schema_id,
               materialized.remaining_source_count
        INTO v_plan_id,v_resource,v_source_id,v_target_id,v_remaining_count
        FROM iam_profile_recovery_materialize_v1(
            p_tenant_id,p_plan_document,p_plan_sha256,v_now
        ) AS materialized;
    EXCEPTION WHEN serialization_failure OR unique_violation THEN
        SELECT receipt.command_key,receipt.request_sha256,receipt.result_id,
               plan.revision,plan.state,receipt.clock_value
        INTO v_receipt_command,v_receipt_request,v_receipt_id,
             v_revision,v_state,v_clock
        FROM iam_authorization_operation_receipts AS receipt
        JOIN iam_profile_backfill_plans AS plan ON plan.id = receipt.result_id
        WHERE receipt.operation_id = p_operation_id;
        IF NOT FOUND OR v_receipt_command <>
           'iam.profile_backfill.recovery_create' OR
           v_receipt_request <> p_request_sha256 OR v_receipt_id <> v_plan_id THEN
            RAISE EXCEPTION USING ERRCODE = 'P5742',
                MESSAGE = 'IAM profile recovery parent already has a child';
        END IF;
        RETURN QUERY SELECT v_plan_id,v_revision,v_clock,v_state,true;
        RETURN;
    END;
    UPDATE iam_authorization_clock SET clock_value = clock_value + 1,
        revision = revision + 1,updated_at = v_now WHERE singleton
        RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM authorization clock is unavailable';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id,command_key,request_sha256,clock_value,result_code,
        result_id,result_revision,result_sha256,created_at
    ) VALUES (
        p_operation_id,'iam.profile_backfill.recovery_create',p_request_sha256,
        v_clock,'iam.profile_backfill.recovery_committed',v_plan_id,1,
        p_plan_sha256,v_now
    );
    v_revision := 1;
    v_state := 'planned';
    IF v_remaining_count = 0 THEN
        IF NOT iam_profile_backfill_activate_v2(
            v_plan_id,v_resource,v_source_id,v_target_id,0,v_now
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'IAM empty profile recovery activation failed';
        END IF;
        v_revision := 2;
        v_state := 'activated';
    END IF;
    RETURN QUERY SELECT v_plan_id,v_revision,v_clock,v_state,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_recovery_plan_create_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_plan_document bytea, p_plan_sha256 bytea, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_recovery_receipt_read_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_recovery_receipt_read_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(request_sha256 bytea, plan_id uuid, recovery_of_plan_id uuid, recovery_root_plan_id uuid, recovery_sequence bigint, result_revision bigint, result_state text, authorization_clock bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR NOT iam_profile_actor_assert_v1(
           p_scope_schema,p_actor_id,p_manage_permission_id,
           p_expected_token_version,p_expected_authorization_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile recovery receipt authority is denied';
    END IF;
    RETURN QUERY
    SELECT receipt.request_sha256,plan.id,plan.recovery_of_plan_id,
           plan.recovery_root_plan_id,plan.recovery_sequence,
           plan.revision,plan.state,receipt.clock_value
    FROM iam_authorization_operation_receipts AS receipt
    JOIN iam_profile_backfill_plans AS plan ON plan.id = receipt.result_id
    WHERE receipt.operation_id = p_operation_id
      AND receipt.command_key = 'iam.profile_backfill.recovery_create'
      AND plan.recovery_of_plan_id IS NOT NULL
      AND receipt.result_sha256 = plan.plan_sha256;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_recovery_receipt_read_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_recovery_source_page_v1(text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_recovery_source_page_v1(p_resource_kind text, p_source_schema_id uuid, p_target_schema_id uuid, p_after_resource_id uuid, p_through_resource_id uuid) RETURNS TABLE(source_count integer, source_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_id uuid;
    v_schema_id uuid;
    v_revision bigint;
    v_profile_sha256 bytea;
    v_part bytea;
    v_evidence bytea;
    v_count integer;
BEGIN
    v_evidence := ''::bytea;
    v_count := 0;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_resource_kind NOT IN ('user','organization','role') OR
       p_source_schema_id IS NULL OR p_target_schema_id IS NULL OR
       p_source_schema_id = p_target_schema_id OR
       p_through_resource_id IS NULL OR
       (p_after_resource_id IS NOT NULL AND
        p_after_resource_id >= p_through_resource_id) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile recovery source page input is invalid';
    END IF;
    FOR v_id,v_schema_id,v_revision,v_profile_sha256 IN
        SELECT resource.id, resource.profile_schema_version_id,
               resource.revision, resource.profile_sha256
        FROM (
            SELECT usr.id, usr.profile_schema_version_id,
                   usr.revision, usr.profile_sha256
            FROM iam_users AS usr WHERE p_resource_kind = 'user'
            UNION ALL
            SELECT org.id, org.profile_schema_version_id,
                   org.revision, org.profile_sha256
            FROM iam_organizations AS org WHERE p_resource_kind = 'organization'
            UNION ALL
            SELECT role.id, role.profile_schema_version_id,
                   role.revision, role.profile_sha256
            FROM iam_roles AS role WHERE p_resource_kind = 'role'
        ) AS resource
        JOIN iam_profile_schema_versions AS actual
          ON actual.id = resource.profile_schema_version_id
         AND actual.resource_kind = p_resource_kind
         AND actual.state IN ('active','retired')
        JOIN iam_profile_schema_versions AS source
          ON source.id = p_source_schema_id
         AND source.resource_kind = p_resource_kind AND source.state = 'active'
         AND actual.version <= source.version
        WHERE resource.profile_schema_version_id <> p_target_schema_id
          AND (p_after_resource_id IS NULL OR resource.id > p_after_resource_id)
          AND resource.id <= p_through_resource_id
        ORDER BY resource.id
    LOOP
        v_part := pg_catalog.convert_to(v_id::text, 'UTF8');
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := pg_catalog.convert_to(v_schema_id::text, 'UTF8');
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := pg_catalog.convert_to(v_revision::text, 'UTF8');
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := v_profile_sha256;
        v_evidence := v_evidence || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_count := v_count + 1;
    END LOOP;
    RETURN QUERY SELECT v_count, pg_catalog.sha256(v_evidence);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_recovery_source_page_v1(p_resource_kind text, p_source_schema_id uuid, p_target_schema_id uuid, p_after_resource_id uuid, p_through_resource_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_recovery_target_evidence_v1(text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_recovery_target_evidence_v1(p_resource_kind text, p_target_schema_id uuid) RETURNS TABLE(target_count bigint, target_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_id uuid;
    v_schema_id uuid;
    v_revision bigint;
    v_profile_sha256 bytea;
    v_part bytea;
    v_entry bytea;
    v_evidence bytea;
    v_count bigint;
BEGIN
    v_evidence := pg_catalog.sha256(''::bytea);
    v_count := 0;
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_resource_kind NOT IN ('user','organization','role') OR
       p_target_schema_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile recovery target evidence input is invalid';
    END IF;
    FOR v_id,v_schema_id,v_revision,v_profile_sha256 IN
        SELECT resource.id, resource.profile_schema_version_id,
               resource.revision, resource.profile_sha256
        FROM (
            SELECT usr.id, usr.profile_schema_version_id,
                   usr.revision, usr.profile_sha256
            FROM iam_users AS usr WHERE p_resource_kind = 'user'
            UNION ALL
            SELECT org.id, org.profile_schema_version_id,
                   org.revision, org.profile_sha256
            FROM iam_organizations AS org WHERE p_resource_kind = 'organization'
            UNION ALL
            SELECT role.id, role.profile_schema_version_id,
                   role.revision, role.profile_sha256
            FROM iam_roles AS role WHERE p_resource_kind = 'role'
        ) AS resource
        WHERE resource.profile_schema_version_id = p_target_schema_id
        ORDER BY resource.id
    LOOP
        v_entry := ''::bytea;
        v_part := pg_catalog.convert_to(v_id::text, 'UTF8');
        v_entry := v_entry || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := pg_catalog.convert_to(v_schema_id::text, 'UTF8');
        v_entry := v_entry || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := pg_catalog.convert_to(v_revision::text, 'UTF8');
        v_entry := v_entry || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_part := v_profile_sha256;
        v_entry := v_entry || pg_catalog.int8send(
            pg_catalog.octet_length(v_part)::bigint
        ) || v_part;
        v_evidence := pg_catalog.sha256(
            v_evidence || pg_catalog.sha256(v_entry)
        );
        v_count := v_count + 1;
    END LOOP;
    RETURN QUERY SELECT v_count, v_evidence;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_recovery_target_evidence_v1(p_resource_kind text, p_target_schema_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_schema_apply_v1(name, uuid, text, bigint, jsonb, bytea, uuid, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_schema_apply_v1(p_scope_schema name, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid, p_retire_field_id uuid, p_expected_field_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_now timestamptz; v_active_id uuid; v_active_version bigint;
    v_definition_sha256 bytea; v_revision bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_schema_id IS NULL OR p_expected_active_schema_id IS NULL OR
       p_schema_id IS NOT DISTINCT FROM p_expected_active_schema_id OR
       p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_version < 2 OR pg_catalog.jsonb_typeof(p_definition) <> 'object' OR
       pg_catalog.octet_length(p_definition_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_definition::text) > 4194304 OR
       p_definition ->> 'contract' IS DISTINCT FROM 'harpy/iam-profile-schema/v1' OR
       p_definition ->> 'id' IS DISTINCT FROM p_schema_id::text OR
       p_definition ->> 'resource_kind' IS DISTINCT FROM p_resource_kind OR
       p_definition ->> 'version' IS DISTINCT FROM p_version::text OR
       pg_catalog.jsonb_typeof(p_definition -> 'fields') <> 'array' OR
       pg_catalog.jsonb_array_length(p_definition -> 'fields') > 500 OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_object_keys(p_definition) AS key
           WHERE key NOT IN ('contract', 'fields', 'id', 'resource_kind', 'version')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile schema definition is invalid';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        WHERE pg_catalog.jsonb_typeof(field.value) <> 'object'
           OR pg_catalog.jsonb_typeof(field.value -> 'id') <> 'string'
           OR field.value ->> 'id' !~
                '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR pg_catalog.jsonb_typeof(field.value -> 'key') <> 'string'
           OR pg_catalog.jsonb_typeof(field.value -> 'logical_type') <> 'string'
           OR pg_catalog.jsonb_typeof(field.value -> 'cardinality') <> 'string'
           OR pg_catalog.jsonb_typeof(field.value -> 'required') <> 'boolean'
           OR pg_catalog.jsonb_typeof(field.value -> 'classification') <> 'string'
           OR pg_catalog.jsonb_typeof(field.value -> 'normalization_profile') <> 'string'
           OR pg_catalog.jsonb_typeof(field.value -> 'state') <> 'string'
           OR pg_catalog.jsonb_typeof(field.value -> 'validation') <> 'object'
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(field.value) AS key
                WHERE key NOT IN (
                    'id', 'key', 'logical_type', 'cardinality', 'required',
                    'classification', 'normalization_profile', 'state', 'validation'
                )
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile schema field definition is invalid';
    END IF;
    SELECT active.id, active.version
    INTO v_active_id, v_active_version
    FROM iam_profile_schema_versions AS active
    WHERE active.resource_kind = p_resource_kind AND active.state = 'active'
    FOR UPDATE;
    IF NOT FOUND OR v_active_id IS DISTINCT FROM p_expected_active_schema_id OR
       p_version IS DISTINCT FROM v_active_version + 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile active schema compare-and-swap failed';
    END IF;
    IF p_retire_field_id IS NOT NULL THEN
        IF p_expected_field_revision < 1 OR NOT EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
            WHERE field.value ->> 'id' = p_retire_field_id::text
              AND field.value ->> 'state' = 'retired'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'IAM profile retirement target is invalid';
        END IF;
        UPDATE iam_profile_fields
        SET state = 'retired', retired_at = v_now, updated_at = v_now,
            revision = revision + 1
        WHERE id = p_retire_field_id AND resource_kind = p_resource_kind
          AND state = 'active' AND revision = p_expected_field_revision;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM profile field retirement compare-and-swap failed';
        END IF;
    ELSIF p_expected_field_revision IS NOT NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile publish retirement evidence is invalid';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        LEFT JOIN iam_profile_fields AS stored
          ON stored.id = (field.value ->> 'id')::uuid
         AND stored.resource_kind = p_resource_kind
        WHERE stored.id IS NULL AND field.value ->> 'state' <> 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile new field must begin as active';
    END IF;
    INSERT INTO iam_profile_fields (
        id, resource_kind, field_key, value_kind, cardinality, required,
        classification, normalization_profile, state, created_at, updated_at,
        retired_at, revision
    )
    SELECT (field.value ->> 'id')::uuid, p_resource_kind, field.value ->> 'key',
        field.value ->> 'logical_type', field.value ->> 'cardinality',
        (field.value ->> 'required')::boolean, field.value ->> 'classification',
        field.value ->> 'normalization_profile', 'active', v_now, v_now, NULL, 1
    FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
    WHERE NOT EXISTS (
        SELECT 1 FROM iam_profile_fields AS stored
        WHERE stored.id = (field.value ->> 'id')::uuid
    );
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value)
        LEFT JOIN iam_profile_fields AS stored
          ON stored.id = (field.value ->> 'id')::uuid
         AND stored.resource_kind = p_resource_kind
        WHERE stored.id IS NULL OR stored.field_key IS DISTINCT FROM field.value ->> 'key'
           OR stored.value_kind IS DISTINCT FROM field.value ->> 'logical_type'
           OR stored.cardinality IS DISTINCT FROM field.value ->> 'cardinality'
           OR stored.required IS DISTINCT FROM (field.value ->> 'required')::boolean
           OR stored.classification IS DISTINCT FROM field.value ->> 'classification'
           OR stored.normalization_profile IS DISTINCT FROM
                field.value ->> 'normalization_profile'
           OR stored.state IS DISTINCT FROM field.value ->> 'state'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile stable field semantic is inconsistent';
    END IF;
    INSERT INTO iam_profile_schema_versions (
        id, resource_kind, version, state, definition_sha256,
        activated_at, retired_at, created_at, updated_at, revision
    ) VALUES (
        p_schema_id, p_resource_kind, p_version, 'draft', p_definition_sha256,
        NULL, NULL, v_now, v_now, 1
    );
    INSERT INTO iam_profile_field_revisions (
        schema_version_id, resource_kind, field_id, validation_schema,
        validation_sha256, created_at, field_key, value_kind, cardinality,
        required, classification, normalization_profile, field_state,
        semantic_sha256
    )
    SELECT p_schema_id, p_resource_kind, (field.value ->> 'id')::uuid,
        field.value -> 'validation',
        pg_catalog.sha256(pg_catalog.convert_to(
            iam_profile_validation_canonical_v1(field.value -> 'validation'), 'UTF8'
        )), v_now, field.value ->> 'key', field.value ->> 'logical_type',
        field.value ->> 'cardinality', (field.value ->> 'required')::boolean,
        field.value ->> 'classification', field.value ->> 'normalization_profile',
        field.value ->> 'state', iam_profile_semantic_sha256_v1(
            (field.value ->> 'id')::uuid, p_resource_kind, field.value ->> 'key',
            field.value ->> 'logical_type', field.value ->> 'cardinality',
            (field.value ->> 'required')::boolean, field.value ->> 'classification',
            field.value ->> 'normalization_profile'
        )
    FROM pg_catalog.jsonb_array_elements(p_definition -> 'fields') AS field(value);
    v_definition_sha256 := iam_profile_definition_sha256_v1(p_schema_id);
    IF v_definition_sha256 IS DISTINCT FROM p_definition_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile schema definition hash is inconsistent';
    END IF;
    UPDATE iam_profile_schema_versions
    SET definition_sha256 = v_definition_sha256, updated_at = v_now,
        revision = revision + 1
    WHERE id = p_schema_id AND state = 'draft';
    UPDATE iam_profile_schema_versions
    SET state = 'retired', retired_at = v_now, updated_at = v_now,
        revision = revision + 1
    WHERE id = v_active_id AND state = 'active';
    UPDATE iam_profile_schema_versions
    SET state = 'active', activated_at = v_now, updated_at = v_now,
        revision = revision + 1
    WHERE id = p_schema_id AND state = 'draft'
    RETURNING revision INTO v_revision;
    IF v_revision IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM profile schema activation failed';
    END IF;
    RETURN v_revision;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_profile_schema_apply_v1(p_scope_schema name, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid, p_retire_field_id uuid, p_expected_field_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_schema_publish_v1(name, uuid, bytea, uuid, text, bigint, jsonb, bytea, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_schema_publish_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_clock bigint;
    v_revision bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF p_operation_id IS NULL OR p_schema_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile schema publish input is invalid';
    END IF;
    IF NOT iam_profile_actor_assert_v1(
        p_scope_schema, p_actor_id, p_manage_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile schema publish authority is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_id,
         v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.profile_schema.publish' OR
           v_receipt_request IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_schema_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM profile schema publish identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1,
        revision = revision + 1,
        updated_at = v_now
    WHERE singleton
    RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM authorization clock is unavailable';
    END IF;
    v_revision := iam_profile_schema_apply_v1(
        p_scope_schema, p_schema_id, p_resource_kind, p_version,
        p_definition, p_definition_sha256, p_expected_active_schema_id,
        NULL, NULL
    );
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.profile_schema.publish', p_request_sha256,
        v_clock, 'iam.profile_schema.published', p_schema_id, v_revision,
        p_definition_sha256, v_now
    );
    RETURN QUERY SELECT p_schema_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_schema_publish_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_schema_retire_v1(name, uuid, bytea, uuid, text, bigint, jsonb, bytea, uuid, uuid, bigint, bytea, integer, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_schema_retire_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid, p_field_id uuid, p_expected_field_revision bigint, p_reference_manifest_sha256 bytea, p_checked_owner_count integer, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_clock bigint;
    v_revision bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF p_operation_id IS NULL OR p_schema_id IS NULL OR p_field_id IS NULL OR
       p_expected_field_revision < 1 OR p_checked_owner_count < 1 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_reference_manifest_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile field retirement input is invalid';
    END IF;
    IF NOT iam_profile_actor_assert_v1(
        p_scope_schema, p_actor_id, p_manage_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile field retirement authority is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_id,
         v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.profile_schema.retire' OR
           v_receipt_request IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_schema_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM profile retirement identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1,
        revision = revision + 1,
        updated_at = v_now
    WHERE singleton
    RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM authorization clock is unavailable';
    END IF;
    INSERT INTO iam_profile_retirement_evidence (
        operation_id, resource_kind, field_id, field_revision,
        reference_manifest_sha256, checked_owner_count,
        live_reference_count, created_at
    ) VALUES (
        p_operation_id, p_resource_kind, p_field_id, p_expected_field_revision,
        p_reference_manifest_sha256, p_checked_owner_count, 0, v_now
    );
    v_revision := iam_profile_schema_apply_v1(
        p_scope_schema, p_schema_id, p_resource_kind, p_version,
        p_definition, p_definition_sha256, p_expected_active_schema_id,
        p_field_id, p_expected_field_revision
    );
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.profile_schema.retire', p_request_sha256,
        v_clock, 'iam.profile_schema.retired', p_schema_id, v_revision,
        p_definition_sha256, v_now
    );
    RETURN QUERY SELECT p_schema_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_schema_retire_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_schema_id uuid, p_resource_kind text, p_version bigint, p_definition jsonb, p_definition_sha256 bytea, p_expected_active_schema_id uuid, p_field_id uuid, p_expected_field_revision bigint, p_reference_manifest_sha256 bytea, p_checked_owner_count integer, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_profile_schema_snapshot_json_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_schema_snapshot_json_v1(p_schema_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_snapshot jsonb;
BEGIN
    SELECT pg_catalog.jsonb_build_object(
        'schema_id', schema_version.id,
        'resource_kind', schema_version.resource_kind,
        'version', schema_version.version,
        'state', CASE schema_version.state
            WHEN 'draft' THEN 'active' ELSE schema_version.state END,
        'definition_sha256', pg_catalog.encode(
            schema_version.definition_sha256, 'hex'
        ),
        'fields', COALESCE(
            pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
                'id', snapshot.field_id,
                'key', snapshot.field_key,
                'logical_type', snapshot.value_kind,
                'cardinality', snapshot.cardinality,
                'required', snapshot.required,
                'classification', snapshot.classification,
                'normalization_profile', snapshot.normalization_profile,
                'state', snapshot.field_state,
                'validation', snapshot.validation_schema,
                'validation_sha256', pg_catalog.encode(
                    snapshot.validation_sha256, 'hex'
                ),
                'semantic_sha256', pg_catalog.encode(
                    snapshot.semantic_sha256, 'hex'
                )
            ) ORDER BY snapshot.field_id) FILTER (
                WHERE snapshot.field_id IS NOT NULL
            ),
            '[]'::jsonb
        )
    ) INTO v_snapshot
    FROM iam_profile_schema_versions AS schema_version
    LEFT JOIN iam_profile_field_revisions AS snapshot
      ON snapshot.schema_version_id = schema_version.id
     AND snapshot.resource_kind = schema_version.resource_kind
    WHERE schema_version.id = p_schema_id
      AND schema_version.state IN ('draft', 'active', 'retired')
    GROUP BY schema_version.id, schema_version.resource_kind,
             schema_version.version, schema_version.state,
             schema_version.definition_sha256;
    RETURN v_snapshot;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_schema_snapshot_json_v1(p_schema_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_profile_semantic_sha256_v1(uuid, text, text, text, text, boolean, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_semantic_sha256_v1(p_field_id uuid, p_resource_kind text, p_field_key text, p_value_kind text, p_cardinality text, p_required boolean, p_classification text, p_normalization_profile text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_document text;
BEGIN
    v_document := '{"cardinality":' ||
        pg_catalog.to_jsonb(p_cardinality)::text ||
        ',"classification":' || pg_catalog.to_jsonb(p_classification)::text ||
        ',"contract":"harpy/iam-profile-field-semantic/v1"' ||
        ',"id":' || pg_catalog.to_jsonb(p_field_id::text)::text ||
        ',"key":' || pg_catalog.to_jsonb(p_field_key)::text ||
        ',"logical_type":' || pg_catalog.to_jsonb(p_value_kind)::text ||
        ',"normalization_profile":' ||
        pg_catalog.to_jsonb(p_normalization_profile)::text ||
        ',"required":' || pg_catalog.to_jsonb(p_required)::text ||
        ',"resource_kind":' || pg_catalog.to_jsonb(p_resource_kind)::text || '}';
    RETURN pg_catalog.sha256(pg_catalog.convert_to(v_document, 'UTF8'));
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_semantic_sha256_v1(p_field_id uuid, p_resource_kind text, p_field_key text, p_value_kind text, p_cardinality text, p_required boolean, p_classification text, p_normalization_profile text) OWNER TO harpy_owner;

--
-- Name: iam_profile_validation_canonical_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_validation_canonical_v1(p_validation jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF pg_catalog.jsonb_typeof(p_validation) IS DISTINCT FROM 'object' OR
       NOT (p_validation ? 'maximum_bytes') OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_object_keys(p_validation) AS present(key)
        WHERE present.key NOT IN (
            'decimal_precision', 'decimal_scale', 'enum_values',
            'integer_maximum', 'integer_minimum', 'maximum_bytes',
            'maximum_items'
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_validation_contract_guard',
            MESSAGE = 'IAM profile validation contract is invalid';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_each(p_validation) AS entry(key, value)
        WHERE (entry.key IN (
                'decimal_precision', 'decimal_scale',
                'maximum_bytes', 'maximum_items'
              ) AND pg_catalog.jsonb_typeof(entry.value) <> 'number')
           OR (entry.key IN ('integer_maximum', 'integer_minimum') AND
                pg_catalog.jsonb_typeof(entry.value) <> 'string')
           OR (entry.key = 'enum_values' AND (
                pg_catalog.jsonb_typeof(entry.value) <> 'array' OR EXISTS (
                    SELECT 1
                    FROM pg_catalog.jsonb_array_elements(entry.value)
                        AS member(value)
                    WHERE pg_catalog.jsonb_typeof(member.value) <> 'string'
                )
           ))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'iam_profile_validation_contract_guard',
            MESSAGE = 'IAM profile validation value type is invalid';
    END IF;
    RETURN (
        SELECT '{' || pg_catalog.string_agg(
            pg_catalog.to_jsonb(entry.key)::text || ':' || CASE
                WHEN entry.key = 'enum_values' THEN (
                    SELECT '[' || COALESCE(pg_catalog.string_agg(
                        member.value::text, ',' ORDER BY member.ordinal
                    ), '') || ']'
                    FROM pg_catalog.jsonb_array_elements(entry.value)
                        WITH ORDINALITY AS member(value, ordinal)
                )
                ELSE entry.value::text
            END,
            ',' ORDER BY entry.key
        ) || '}'
        FROM pg_catalog.jsonb_each(p_validation) AS entry(key, value)
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_validation_canonical_v1(p_validation jsonb) OWNER TO harpy_owner;

--
-- Name: iam_profile_worker_capability_commit_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_worker_capability_commit_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM iam_profile_backfill_worker_capabilities AS capability
        WHERE capability.backend_pid = NEW.backend_pid
          AND capability.transaction_id = NEW.transaction_id
          AND capability.plan_id = NEW.plan_id
          AND capability.resource_id = NEW.resource_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile worker capability was not consumed';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_worker_capability_commit_v1() OWNER TO harpy_owner;

--
-- Name: iam_profile_worker_capability_consume_v1(uuid, text, uuid, uuid, bigint, bytea, uuid, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_worker_capability_consume_v1(p_plan_id uuid, p_resource_kind text, p_resource_id uuid, p_actual_source_schema_id uuid, p_source_revision bigint, p_source_sha256 bytea, p_target_schema_id uuid, p_target_sha256 bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_consumed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_plan_id IS NULL OR
       p_resource_kind NOT IN ('user','organization','role') OR
       p_resource_id IS NULL OR p_actual_source_schema_id IS NULL OR
       p_source_revision < 1 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       p_target_schema_id IS NULL OR
       pg_catalog.octet_length(p_target_sha256) IS DISTINCT FROM 32 THEN
        RETURN false;
    END IF;
    DELETE FROM iam_profile_backfill_worker_capabilities AS capability
    WHERE capability.backend_pid = pg_catalog.pg_backend_pid()
      AND capability.transaction_id = pg_catalog.pg_current_xact_id()
      AND capability.plan_id = p_plan_id
      AND capability.resource_kind = p_resource_kind
      AND capability.resource_id = p_resource_id
      AND capability.actual_source_schema_id = p_actual_source_schema_id
      AND capability.source_revision = p_source_revision
      AND capability.source_sha256 = p_source_sha256
      AND capability.target_schema_id = p_target_schema_id
      AND capability.target_sha256 = p_target_sha256
    RETURNING true INTO v_consumed;
    RETURN coalesce(v_consumed, false);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_worker_capability_consume_v1(p_plan_id uuid, p_resource_kind text, p_resource_id uuid, p_actual_source_schema_id uuid, p_source_revision bigint, p_source_sha256 bytea, p_target_schema_id uuid, p_target_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_profile_worker_capability_mint_v1(name, uuid, uuid, uuid, integer, text, bytea, uuid, integer, uuid, uuid, bigint, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_worker_capability_mint_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_actual_source_schema_id uuid, p_source_revision bigint, p_source_sha256 bytea, p_target_sha256 bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_resource_kind text;
    v_source_version bigint;
    v_target_schema_id uuid;
    v_after_resource_id uuid;
    v_through_resource_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT iam_maintenance_claim_assert_v1(
           p_scope_schema, p_tenant_id, p_job_id, p_attempt_id,
           'iam.profile.backfill', p_payload_revision,
           p_payload_reference, p_payload_sha256
       ) OR p_plan_id IS NULL OR p_page_number < 1 OR
       p_resource_id IS NULL OR p_actual_source_schema_id IS NULL OR
       p_source_revision < 1 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_target_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM profile worker capability input is invalid';
    END IF;
    SELECT plan.resource_kind, source.version, plan.target_schema_id,
           page.after_resource_id, page.through_resource_id
    INTO v_resource_kind, v_source_version, v_target_schema_id,
         v_after_resource_id, v_through_resource_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_backfill_pages AS page ON page.plan_id = plan.id
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.id = p_plan_id AND plan.state IN ('planned','running')
      AND page.page_number = p_page_number AND page.job_id = p_job_id
      AND page.payload_reference = p_payload_reference
      AND page.payload_sha256 = p_payload_sha256 AND page.state = 'queued'
    FOR UPDATE OF plan, page, source, target;
    IF v_resource_kind IS NULL OR
       (v_after_resource_id IS NOT NULL AND
        p_resource_id <= v_after_resource_id) OR
       p_resource_id > v_through_resource_id OR NOT EXISTS (
           SELECT 1 FROM iam_profile_schema_versions AS actual
           WHERE actual.id = p_actual_source_schema_id
             AND actual.resource_kind = v_resource_kind
             AND actual.state IN ('active','retired')
             AND actual.version <= v_source_version
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM profile worker capability is stale';
    END IF;
    INSERT INTO iam_profile_backfill_worker_capabilities (
        backend_pid, transaction_id, plan_id, page_number, resource_kind,
        resource_id, actual_source_schema_id, source_revision, source_sha256,
        target_schema_id, target_sha256, created_at
    ) VALUES (
        pg_catalog.pg_backend_pid(), pg_catalog.pg_current_xact_id(),
        p_plan_id, p_page_number, v_resource_kind, p_resource_id,
        p_actual_source_schema_id, p_source_revision, p_source_sha256,
        v_target_schema_id, p_target_sha256,
        pg_catalog.transaction_timestamp()
    );
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_worker_capability_mint_v1(p_scope_schema name, p_tenant_id uuid, p_job_id uuid, p_attempt_id uuid, p_payload_revision integer, p_payload_reference text, p_payload_sha256 bytea, p_plan_id uuid, p_page_number integer, p_resource_id uuid, p_actual_source_schema_id uuid, p_source_revision bigint, p_source_sha256 bytea, p_target_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_profile_write_contract_read_v1(name, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_write_contract_read_v1(p_scope_schema name, p_resource_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_source_schema_id uuid;
    v_plan_id uuid;
    v_target_schema_id uuid;
    v_source jsonb;
    v_target jsonb;
    v_mappings jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile write contract scope is invalid';
    END IF;
    SELECT source.id INTO v_source_schema_id
    FROM iam_profile_schema_versions AS source
    WHERE source.resource_kind = p_resource_kind AND source.state = 'active'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM active profile write schema is unavailable';
    END IF;
    SELECT plan.id, plan.target_schema_id
    INTO v_plan_id, v_target_schema_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind
     AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind
     AND target.state = 'draft'
    WHERE plan.resource_kind = p_resource_kind
      AND plan.source_schema_id = v_source_schema_id
      AND plan.state IN ('planned', 'running', 'verified')
    FOR SHARE OF plan, source, target;
    v_source := iam_profile_schema_snapshot_json_v1(v_source_schema_id);
    IF v_source IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM source profile write contract is unavailable';
    END IF;
    IF v_plan_id IS NOT NULL THEN
        v_target := iam_profile_schema_snapshot_json_v1(v_target_schema_id);
        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'source_field_id', mapping.source_field_id,
                'target_field_id', mapping.target_field_id,
                'converter_kind', mapping.converter_kind,
                'semantic_sha256', pg_catalog.encode(
                    mapping.semantic_sha256, 'hex'
                )
            ) ORDER BY mapping.ordinal
        ), '[]'::jsonb)
        INTO v_mappings
        FROM iam_profile_backfill_mappings AS mapping
        WHERE mapping.plan_id = v_plan_id;
        IF v_target IS NULL OR pg_catalog.jsonb_array_length(v_mappings) < 1 THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'IAM target profile write contract is unavailable';
        END IF;
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'contract', 'harpy/iam-profile-write-contract/v1',
        'plan_id', v_plan_id,
        'source', v_source,
        'target', v_target,
        'mappings', COALESCE(v_mappings, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_write_contract_read_v1(p_scope_schema name, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: iam_profile_write_contract_read_v2(name, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_write_contract_read_v2(p_scope_schema name, p_resource_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_source_schema_id uuid;
    v_plan_id uuid;
    v_target_schema_id uuid;
    v_source jsonb;
    v_target jsonb;
    v_mappings jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile write contract scope is invalid';
    END IF;
    SELECT source.id INTO v_source_schema_id
    FROM iam_profile_schema_versions AS source
    WHERE source.resource_kind = p_resource_kind AND source.state = 'active'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM active profile write schema is unavailable';
    END IF;
    SELECT plan.id, plan.target_schema_id
    INTO v_plan_id, v_target_schema_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind AND source.state = 'active'
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind AND target.state = 'draft'
    WHERE plan.resource_kind = p_resource_kind
      AND plan.source_schema_id = v_source_schema_id
      AND (plan.state IN ('planned', 'running') OR
           (plan.recovery_of_plan_id IS NULL AND plan.state = 'verified'))
    FOR SHARE OF plan, source, target;
    IF v_plan_id IS NULL AND EXISTS (
        SELECT 1 FROM iam_profile_backfill_plans AS fenced
        JOIN iam_profile_schema_versions AS target
          ON target.id = fenced.target_schema_id
         AND target.resource_kind = fenced.resource_kind
         AND target.state = 'draft'
        WHERE fenced.resource_kind = p_resource_kind
          AND fenced.source_schema_id = v_source_schema_id
          AND fenced.state = 'fenced'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5741',
            MESSAGE = 'IAM profile domain is fenced pending recovery';
    END IF;
    v_source := iam_profile_schema_snapshot_json_v1(v_source_schema_id);
    IF v_source IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM source profile write contract is unavailable';
    END IF;
    IF v_plan_id IS NOT NULL THEN
        v_target := iam_profile_schema_snapshot_json_v1(v_target_schema_id);
        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'source_field_id', mapping.source_field_id,
                'target_field_id', mapping.target_field_id,
                'converter_kind', mapping.converter_kind,
                'semantic_sha256', pg_catalog.encode(
                    mapping.semantic_sha256, 'hex'
                )
            ) ORDER BY mapping.ordinal
        ), '[]'::jsonb)
        INTO v_mappings
        FROM iam_profile_backfill_mappings AS mapping
        WHERE mapping.plan_id = v_plan_id;
        IF v_target IS NULL OR pg_catalog.jsonb_array_length(v_mappings) < 1 THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'IAM target profile write contract is unavailable';
        END IF;
    END IF;
    RETURN pg_catalog.jsonb_build_object(
        'contract', 'harpy/iam-profile-write-contract/v1',
        'plan_id', v_plan_id,
        'source', v_source,
        'target', v_target,
        'mappings', COALESCE(v_mappings, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_write_contract_read_v2(p_scope_schema name, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: iam_profile_write_resource_read_v1(name, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_profile_write_resource_read_v1(p_scope_schema name, p_resource_kind text, p_resource_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user','organization','role') OR
       p_resource_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM profile write resource scope is invalid';
    END IF;
    IF p_resource_kind = 'user' THEN
        SELECT pg_catalog.jsonb_build_object(
            'schema_id', resource.profile_schema_version_id,
            'values', resource.profile_values,
            'sha256', pg_catalog.encode(resource.profile_sha256, 'hex'),
            'revision', resource.revision
        ) INTO v_document
        FROM iam_users AS resource WHERE resource.id = p_resource_id
        FOR UPDATE;
    ELSIF p_resource_kind = 'organization' THEN
        SELECT pg_catalog.jsonb_build_object(
            'schema_id', resource.profile_schema_version_id,
            'values', resource.profile_values,
            'sha256', pg_catalog.encode(resource.profile_sha256, 'hex'),
            'revision', resource.revision
        ) INTO v_document
        FROM iam_organizations AS resource WHERE resource.id = p_resource_id
        FOR UPDATE;
    ELSE
        SELECT pg_catalog.jsonb_build_object(
            'schema_id', resource.profile_schema_version_id,
            'values', resource.profile_values,
            'sha256', pg_catalog.encode(resource.profile_sha256, 'hex'),
            'revision', resource.revision
        ) INTO v_document
        FROM iam_roles AS resource WHERE resource.id = p_resource_id
        FOR UPDATE;
    END IF;
    IF v_document IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM profile write resource is unavailable';
    END IF;
    RETURN v_document;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_profile_write_resource_read_v1(p_scope_schema name, p_resource_kind text, p_resource_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_action_create_v1(name, uuid, bytea, uuid, text, text, text, boolean, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_action_create_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_action_key text, p_display_name text, p_description text, p_is_protected boolean, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_clock bigint; v_revision bigint; v_replayed boolean;
    v_count bigint; v_finished boolean;
BEGIN
    SELECT b.authorization_clock, b.result_revision, b.replayed
    INTO v_clock, v_revision, v_replayed FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.action.create', p_request_sha256,
        p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS b;
    IF v_replayed THEN RETURN QUERY SELECT p_id, v_revision, v_clock, true; RETURN; END IF;
    INSERT INTO iam_actions (
        id, action_key, display_name, description, is_protected, state,
        revision, created_at, updated_at, retired_at
    ) VALUES (
        p_id, p_action_key, p_display_name, p_description, p_is_protected,
        'active', 1, pg_catalog.transaction_timestamp(),
        pg_catalog.transaction_timestamp(), NULL
    );
    v_count := iam_rbac_bump_all_users_v1(v_clock);
    v_finished := iam_rbac_mutation_finish_v1(p_operation_id, 'iam.rbac.action.create',
        p_request_sha256, v_clock, 'iam.rbac.action.created', p_id, 1);
    RETURN QUERY SELECT p_id, 1::bigint, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_action_create_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_action_key text, p_display_name text, p_description text, p_is_protected boolean, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_action_get_v1(name, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_action_get_v1(p_scope_schema name, p_id uuid, p_actor_id uuid, p_required_permission_id uuid) RETURNS TABLE(id uuid, action_key text, display_name text, description text, is_protected boolean, state text, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT iam_rbac_read_assert_v1(p_scope_schema, p_actor_id, p_required_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM RBAC query denied';
    END IF;
    RETURN QUERY SELECT action.id, action.action_key, action.display_name,
        action.description, action.is_protected, action.state, action.revision
    FROM iam_actions AS action WHERE action.id = p_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_action_get_v1(p_scope_schema name, p_id uuid, p_actor_id uuid, p_required_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_action_list_v1(name, text, integer, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_action_list_v1(p_scope_schema name, p_state text, p_limit integer, p_actor_id uuid, p_required_permission_id uuid) RETURNS TABLE(id uuid, action_key text, display_name text, description text, is_protected boolean, state text, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit < 1 OR p_limit > 200 OR p_state NOT IN ('active','retired','all') THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'IAM RBAC action query is invalid';
    END IF;
    IF NOT iam_rbac_read_assert_v1(p_scope_schema, p_actor_id, p_required_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM RBAC query denied';
    END IF;
    RETURN QUERY SELECT action.id, action.action_key, action.display_name,
        action.description, action.is_protected, action.state, action.revision
    FROM iam_actions AS action WHERE p_state = 'all' OR action.state = p_state
    ORDER BY action.action_key, action.id LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_action_list_v1(p_scope_schema name, p_state text, p_limit integer, p_actor_id uuid, p_required_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_action_retire_v1(name, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_action_retire_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_clock bigint; v_revision bigint; v_replayed boolean; v_now timestamptz;
    v_count bigint; v_finished boolean;
BEGIN
    SELECT b.authorization_clock, b.result_revision, b.replayed
    INTO v_clock, v_revision, v_replayed FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.action.retire', p_request_sha256,
        p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS b;
    IF v_replayed THEN RETURN QUERY SELECT p_id, v_revision, v_clock, true; RETURN; END IF;
    v_now := pg_catalog.transaction_timestamp();
    UPDATE iam_actions SET state = 'retired', revision = revision + 1,
        updated_at = v_now, retired_at = v_now
    WHERE id = p_id AND state = 'active' AND revision = p_expected_revision
    RETURNING revision INTO v_revision;
    IF v_revision IS NULL THEN RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM RBAC action revision changed'; END IF;
    v_count := iam_rbac_bump_all_users_v1(v_clock);
    v_finished := iam_rbac_mutation_finish_v1(p_operation_id, 'iam.rbac.action.retire',
        p_request_sha256, v_clock, 'iam.rbac.action.retired', p_id, v_revision);
    RETURN QUERY SELECT p_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_action_retire_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_action_update_v1(name, uuid, bytea, uuid, text, text, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_action_update_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_display_name text, p_description text, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_clock bigint; v_revision bigint; v_replayed boolean;
    v_count bigint; v_finished boolean;
BEGIN
    SELECT b.authorization_clock, b.result_revision, b.replayed
    INTO v_clock, v_revision, v_replayed FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.action.update', p_request_sha256,
        p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS b;
    IF v_replayed THEN RETURN QUERY SELECT p_id, v_revision, v_clock, true; RETURN; END IF;
    UPDATE iam_actions SET display_name = p_display_name, description = p_description,
        revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
    WHERE id = p_id AND state = 'active' AND revision = p_expected_revision
    RETURNING revision INTO v_revision;
    IF v_revision IS NULL THEN RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM RBAC action revision changed'; END IF;
    v_count := iam_rbac_bump_all_users_v1(v_clock);
    v_finished := iam_rbac_mutation_finish_v1(p_operation_id, 'iam.rbac.action.update',
        p_request_sha256, v_clock, 'iam.rbac.action.updated', p_id, v_revision);
    RETURN QUERY SELECT p_id, v_revision, v_clock, false;
END;
$$;


