--
-- Name: iam_rbac_actor_assert_v1(name, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_actor_assert_v1(p_scope_schema name, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_status text;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM RBAC command scope is invalid';
    END IF;
    IF p_actor_id IS NULL OR p_required_permission_id IS NULL OR
       p_expected_token_version < 1 OR p_expected_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC command evidence is invalid';
    END IF;
    SELECT status, token_version, authorization_version
    INTO v_status, v_token_version, v_authorization_version
    FROM iam_users WHERE id = p_actor_id FOR UPDATE;
    IF NOT FOUND OR v_status IS DISTINCT FROM 'active' OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version OR
       NOT iam_user_has_rbac_evidence_v2(p_actor_id, p_required_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM RBAC command authority is denied';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_actor_assert_v1(p_scope_schema name, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_binding_grant_v1(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_binding_grant_v1(p_group_id uuid, p_target_kind text, p_target_id uuid, p_permission_id uuid, p_suggested_binding_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_binding_id uuid; v_state text; v_protected boolean;
    v_owned boolean; v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_suggested_binding_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM iam_permissions
        WHERE id = p_permission_id AND match_kind = 'exact' AND state = 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC assignment binding input is invalid';
    END IF;
    CASE p_target_kind
    WHEN 'USER' THEN
        SELECT id, state INTO v_binding_id, v_state
        FROM iam_user_permission_bindings
        WHERE user_id = p_target_id AND permission_id = p_permission_id
        FOR UPDATE;
    WHEN 'ROLE' THEN
        SELECT id, state INTO v_binding_id, v_state
        FROM iam_role_permission_bindings
        WHERE role_id = p_target_id AND permission_id = p_permission_id
        FOR UPDATE;
    WHEN 'ORGANIZATION' THEN
        SELECT id, state INTO v_binding_id, v_state
        FROM iam_organization_permission_bindings
        WHERE organization_id = p_target_id AND permission_id = p_permission_id
        FOR UPDATE;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC assignment target is invalid';
    END CASE;
    IF v_binding_id IS NOT NULL THEN
        SELECT true INTO v_owned FROM iam_rbac_assignment_members
        WHERE group_id = p_group_id AND binding_id = v_binding_id;
        IF v_owned IS DISTINCT FROM true THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM RBAC binding is owned outside the compatibility group';
        END IF;
        IF v_state = 'revoked' THEN
            CASE p_target_kind
            WHEN 'USER' THEN
                UPDATE iam_user_permission_bindings SET state = 'active',
                    revision = revision + 1, updated_at = v_now,
                    activated_at = v_now, revoked_at = NULL
                WHERE id = v_binding_id;
            WHEN 'ROLE' THEN
                UPDATE iam_role_permission_bindings SET state = 'active',
                    revision = revision + 1, updated_at = v_now,
                    activated_at = v_now, revoked_at = NULL
                WHERE id = v_binding_id;
            WHEN 'ORGANIZATION' THEN
                UPDATE iam_organization_permission_bindings SET state = 'active',
                    revision = revision + 1, updated_at = v_now,
                    activated_at = v_now, revoked_at = NULL
                WHERE id = v_binding_id;
            END CASE;
        END IF;
        RETURN v_binding_id;
    END IF;
    v_binding_id := p_suggested_binding_id;
    CASE p_target_kind
    WHEN 'USER' THEN
        INSERT INTO iam_user_permission_bindings (
            id, user_id, permission_id, permission_match_kind, state, revision,
            created_at, updated_at, activated_at, revoked_at
        ) VALUES (
            v_binding_id, p_target_id, p_permission_id, 'exact', 'active', 1,
            v_now, v_now, v_now, NULL
        );
    WHEN 'ROLE' THEN
        SELECT is_protected INTO v_protected FROM iam_roles
        WHERE id = p_target_id AND status = 'active';
        IF v_protected IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '42501',
                MESSAGE = 'IAM RBAC assignment role is unavailable';
        END IF;
        INSERT INTO iam_role_permission_bindings (
            id, role_id, role_is_protected, permission_id,
            permission_match_kind, state, revision,
            created_at, updated_at, activated_at, revoked_at
        ) VALUES (
            v_binding_id, p_target_id, v_protected, p_permission_id,
            'exact', 'active', 1, v_now, v_now, v_now, NULL
        );
    WHEN 'ORGANIZATION' THEN
        INSERT INTO iam_organization_permission_bindings (
            id, organization_id, permission_id, permission_match_kind,
            state, revision, created_at, updated_at, activated_at, revoked_at
        ) VALUES (
            v_binding_id, p_target_id, p_permission_id, 'exact',
            'active', 1, v_now, v_now, v_now, NULL
        );
    END CASE;
    RETURN v_binding_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_binding_grant_v1(p_group_id uuid, p_target_kind text, p_target_id uuid, p_permission_id uuid, p_suggested_binding_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_binding_revoke_v1(text, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_binding_revoke_v1(p_target_kind text, p_target_id uuid, p_permission_id uuid, p_binding_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count bigint; v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    CASE p_target_kind
    WHEN 'USER' THEN
        UPDATE iam_user_permission_bindings SET state = 'revoked',
            revision = revision + 1, updated_at = v_now, revoked_at = v_now
        WHERE id = p_binding_id AND user_id = p_target_id
          AND permission_id = p_permission_id AND state = 'active';
    WHEN 'ROLE' THEN
        UPDATE iam_role_permission_bindings SET state = 'revoked',
            revision = revision + 1, updated_at = v_now, revoked_at = v_now
        WHERE id = p_binding_id AND role_id = p_target_id
          AND permission_id = p_permission_id AND state = 'active';
    WHEN 'ORGANIZATION' THEN
        UPDATE iam_organization_permission_bindings SET state = 'revoked',
            revision = revision + 1, updated_at = v_now, revoked_at = v_now
        WHERE id = p_binding_id AND organization_id = p_target_id
          AND permission_id = p_permission_id AND state = 'active';
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC assignment target is invalid';
    END CASE;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM RBAC assignment binding changed';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_binding_revoke_v1(p_target_kind text, p_target_id uuid, p_permission_id uuid, p_binding_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_bump_target_v1(text, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_bump_target_v1(p_target_kind text, p_target_id uuid, p_clock bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    CASE p_target_kind
    WHEN 'USER' THEN
        RETURN iam_rbac_bump_user_v1(p_target_id, p_clock);
    WHEN 'ROLE' THEN
        RETURN iam_rbac_bump_role_users_v1(p_target_id, p_clock);
    WHEN 'ORGANIZATION' THEN
        RETURN iam_rbac_bump_organization_users_v1(p_target_id, p_clock);
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC assignment target is invalid';
    END CASE;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_bump_target_v1(p_target_kind text, p_target_id uuid, p_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_create_v1(name, uuid, bytea, uuid, uuid, text, uuid, jsonb, uuid, uuid, bigint, bigint, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_create_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_resource_id uuid, p_target_kind text, p_target_id uuid, p_items jsonb, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_step_up_purpose_sha256 bytea, p_step_up_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_clock bigint;
    v_revision bigint;
    v_replayed boolean;
    v_asserted boolean;
    v_permission_id uuid;
    v_binding_id uuid;
    v_bumped bigint;
    v_finished boolean;
    v_item_ordinal integer;
    v_item_action_id uuid;
    v_item_permission_id uuid;
    v_item_binding_id uuid;
    v_now timestamptz;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    SELECT begin_result.authorization_clock,
           begin_result.result_revision, begin_result.replayed
    INTO v_clock, v_revision, v_replayed
    FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.assignment.create',
        p_request_sha256, p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS begin_result;
    IF v_replayed THEN
        RETURN QUERY SELECT p_id, v_revision, v_clock, true;
        RETURN;
    END IF;
    v_asserted := iam_rbac_assignment_step_up_assert_v1(
        'iam.rbac.assignment.create', NULL, p_step_up_purpose_sha256,
        p_step_up_auth_time, p_amr_password, p_amr_webauthn, p_amr_totp
    );
    IF p_id IS NULL OR p_resource_id IS NULL OR p_target_id IS NULL OR
       NOT iam_rbac_assignment_target_active_v1(p_target_kind, p_target_id) OR
       NOT iam_rbac_assignment_items_valid_v1(p_items) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC assignment create input is invalid';
    END IF;
    INSERT INTO iam_rbac_assignment_groups (
        id, resource_id, target_kind, target_id, state, revision,
        created_at, updated_at, retired_at
    ) VALUES (
        p_id, p_resource_id, p_target_kind, p_target_id,
        'active', 1, v_now, v_now, NULL
    );
    FOR v_item_ordinal, v_item_action_id,
        v_item_permission_id, v_item_binding_id IN
        SELECT item.ordinal, item.action_id, item.permission_id, item.binding_id
        FROM pg_catalog.jsonb_to_recordset(p_items) AS item(
            ordinal integer, action_id uuid, permission_id uuid, binding_id uuid
        ) ORDER BY item.ordinal
    LOOP
        v_permission_id := iam_rbac_assignment_exact_permission_v1(
            p_resource_id, v_item_action_id, v_item_permission_id
        );
        v_binding_id := iam_rbac_assignment_binding_grant_v1(
            p_id, p_target_kind, p_target_id,
            v_permission_id, v_item_binding_id
        );
        INSERT INTO iam_rbac_assignment_members (
            group_id, group_revision, ordinal, action_id, permission_id,
            permission_match_kind, binding_id, state, created_at, revoked_at
        ) VALUES (
            p_id, 1, v_item_ordinal, v_item_action_id, v_permission_id,
            'exact', v_binding_id, 'active', v_now, NULL
        );
    END LOOP;
    v_revision := 1;
    v_bumped := iam_rbac_assignment_bump_target_v1(
        p_target_kind, p_target_id, v_clock
    );
    v_finished := iam_rbac_mutation_finish_v1(
        p_operation_id, 'iam.rbac.assignment.create', p_request_sha256,
        v_clock, 'iam.rbac.assignment.created', p_id, v_revision
    );
    RETURN QUERY SELECT p_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_create_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_resource_id uuid, p_target_kind text, p_target_id uuid, p_items jsonb, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_step_up_purpose_sha256 bytea, p_step_up_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_exact_permission_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_exact_permission_v1(p_resource_id uuid, p_action_id uuid, p_suggested_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_permission_id uuid;
    v_now timestamptz;
BEGIN
    IF p_suggested_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM iam_resources
        WHERE id = p_resource_id AND state = 'active'
    ) OR NOT EXISTS (
        SELECT 1 FROM iam_actions
        WHERE id = p_action_id AND state = 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC assignment catalog is invalid';
    END IF;
    SELECT id INTO v_permission_id FROM iam_permissions
    WHERE match_kind = 'exact' AND resource_id = p_resource_id
      AND action_id = p_action_id AND state = 'active';
    IF v_permission_id IS NOT NULL THEN
        RETURN v_permission_id;
    END IF;
    IF EXISTS (
        SELECT 1 FROM iam_permissions
        WHERE match_kind = 'exact' AND resource_id = p_resource_id
          AND action_id = p_action_id
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM RBAC exact permission is retired';
    END IF;
    v_now := pg_catalog.transaction_timestamp();
    INSERT INTO iam_permissions (
        id, match_kind, resource_id, action_id, is_protected, state,
        revision, created_at, updated_at, retired_at
    ) VALUES (
        p_suggested_id, 'exact', p_resource_id, p_action_id, false,
        'active', 1, v_now, v_now, NULL
    );
    RETURN p_suggested_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_exact_permission_v1(p_resource_id uuid, p_action_id uuid, p_suggested_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_items_valid_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_items_valid_v1(p_items jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_count integer;
    v_valid boolean;
BEGIN
    IF pg_catalog.jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
        RETURN false;
    END IF;
    v_count := pg_catalog.jsonb_array_length(p_items);
    IF v_count NOT BETWEEN 1 AND 100 THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.bool_and(
        pg_catalog.jsonb_typeof(item.value) = 'object' AND
        item.value ?& ARRAY['ordinal','action_id','permission_id','binding_id'] AND
        (SELECT pg_catalog.count(*) = 4
         FROM pg_catalog.jsonb_object_keys(item.value))
    ) INTO v_valid
    FROM pg_catalog.jsonb_array_elements(p_items) AS item(value);
    IF v_valid IS DISTINCT FROM true THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.count(*) = v_count AND
           pg_catalog.count(DISTINCT ordinal) = v_count AND
           pg_catalog.min(ordinal) = 1 AND pg_catalog.max(ordinal) = v_count
    INTO v_valid
    FROM pg_catalog.jsonb_to_recordset(p_items) AS item(ordinal integer);
    RETURN coalesce(v_valid, false);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_items_valid_v1(p_items jsonb) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_list_v1(name, text, uuid, integer, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_list_v1(p_scope_schema name, p_state text, p_after_id uuid, p_limit integer, p_actor_id uuid, p_required_permission_id uuid) RETURNS TABLE(id uuid, resource_id uuid, target_kind text, target_id uuid, state text, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, items jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit NOT BETWEEN 1 AND 200 OR
       p_state NOT IN ('active', 'retired', 'all') THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC assignment list input is invalid';
    END IF;
    IF NOT iam_rbac_read_assert_v1(
        p_scope_schema, p_actor_id, p_required_permission_id
    ) THEN
        RETURN;
    END IF;
    RETURN QUERY
    WITH page AS (
        SELECT assignment.*
        FROM iam_rbac_assignment_groups AS assignment
        WHERE (p_state = 'all' OR assignment.state = p_state)
          AND (p_after_id IS NULL OR assignment.id > p_after_id)
        ORDER BY assignment.id
        LIMIT p_limit
    )
    SELECT assignment.id, assignment.resource_id, assignment.target_kind,
           assignment.target_id, assignment.state, assignment.revision,
           assignment.created_at, assignment.updated_at,
           (
               SELECT pg_catalog.jsonb_agg(
                   pg_catalog.jsonb_build_object(
                       'ordinal', member.ordinal,
                       'action_id', member.action_id,
                       'permission_id', member.permission_id,
                       'binding_id', member.binding_id
                   ) ORDER BY member.ordinal
               )
               FROM iam_rbac_assignment_members AS member
               WHERE member.group_id = assignment.id
                 AND member.group_revision = (
                     SELECT pg_catalog.max(history.group_revision)
                     FROM iam_rbac_assignment_members AS history
                     WHERE history.group_id = assignment.id
                 )
           ) AS items
    FROM page AS assignment
    ORDER BY assignment.id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_list_v1(p_scope_schema name, p_state text, p_after_id uuid, p_limit integer, p_actor_id uuid, p_required_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_read_v1(name, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_read_v1(p_scope_schema name, p_id uuid, p_actor_id uuid, p_required_permission_id uuid) RETURNS TABLE(id uuid, resource_id uuid, target_kind text, target_id uuid, state text, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, items jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT iam_rbac_read_assert_v1(
        p_scope_schema, p_actor_id, p_required_permission_id
    ) THEN
        RETURN;
    END IF;
    RETURN QUERY
    SELECT assignment.id, assignment.resource_id, assignment.target_kind,
           assignment.target_id, assignment.state, assignment.revision,
           assignment.created_at, assignment.updated_at,
           (
               SELECT pg_catalog.jsonb_agg(
                   pg_catalog.jsonb_build_object(
                       'ordinal', member.ordinal,
                       'action_id', member.action_id,
                       'permission_id', member.permission_id,
                       'binding_id', member.binding_id
                   ) ORDER BY member.ordinal
               )
               FROM iam_rbac_assignment_members AS member
               WHERE member.group_id = assignment.id
                 AND member.group_revision = (
                     SELECT pg_catalog.max(history.group_revision)
                     FROM iam_rbac_assignment_members AS history
                     WHERE history.group_id = assignment.id
                 )
           ) AS items
    FROM iam_rbac_assignment_groups AS assignment
    WHERE assignment.id = p_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_read_v1(p_scope_schema name, p_id uuid, p_actor_id uuid, p_required_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_retire_v1(name, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_retire_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_step_up_purpose_sha256 bytea, p_step_up_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_clock bigint;
    v_revision bigint;
    v_replayed boolean;
    v_asserted boolean;
    v_target_kind text;
    v_target_id uuid;
    v_finished boolean;
    v_bumped bigint;
    v_member_permission_id uuid;
    v_member_binding_id uuid;
    v_now timestamptz;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    SELECT begin_result.authorization_clock,
           begin_result.result_revision, begin_result.replayed
    INTO v_clock, v_revision, v_replayed
    FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.assignment.retire',
        p_request_sha256, p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS begin_result;
    IF v_replayed THEN
        RETURN QUERY SELECT p_id, v_revision, v_clock, true;
        RETURN;
    END IF;
    v_asserted := iam_rbac_assignment_step_up_assert_v1(
        'iam.rbac.assignment.retire', p_id, p_step_up_purpose_sha256,
        p_step_up_auth_time, p_amr_password, p_amr_webauthn, p_amr_totp
    );
    SELECT target_kind, target_id, revision
    INTO v_target_kind, v_target_id, v_revision
    FROM iam_rbac_assignment_groups
    WHERE id = p_id AND state = 'active'
    FOR UPDATE;
    IF NOT FOUND OR v_revision IS DISTINCT FROM p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM RBAC assignment revision changed';
    END IF;
    FOR v_member_permission_id, v_member_binding_id IN
        SELECT permission_id, binding_id
        FROM iam_rbac_assignment_members
        WHERE group_id = p_id AND group_revision = v_revision
          AND state = 'active'
    LOOP
        v_finished := iam_rbac_assignment_binding_revoke_v1(
            v_target_kind, v_target_id,
            v_member_permission_id, v_member_binding_id
        );
    END LOOP;
    UPDATE iam_rbac_assignment_members
    SET state = 'revoked', revoked_at = v_now
    WHERE group_id = p_id AND group_revision = v_revision AND state = 'active';
    UPDATE iam_rbac_assignment_groups
    SET state = 'retired', revision = revision + 1,
        updated_at = v_now, retired_at = v_now
    WHERE id = p_id AND revision = v_revision
    RETURNING revision INTO v_revision;
    IF v_revision IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM RBAC assignment revision changed';
    END IF;
    v_bumped := iam_rbac_assignment_bump_target_v1(
        v_target_kind, v_target_id, v_clock
    );
    v_finished := iam_rbac_mutation_finish_v1(
        p_operation_id, 'iam.rbac.assignment.retire', p_request_sha256,
        v_clock, 'iam.rbac.assignment.retired', p_id, v_revision
    );
    RETURN QUERY SELECT p_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_retire_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_step_up_purpose_sha256 bytea, p_step_up_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_step_up_assert_v1(text, uuid, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_step_up_assert_v1(p_command_key text, p_target_id uuid, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF p_command_key NOT IN (
        'iam.rbac.assignment.create',
        'iam.rbac.assignment.update',
        'iam.rbac.assignment.retire'
    ) OR (p_command_key <> 'iam.rbac.assignment.create' AND p_target_id IS NULL) OR
       p_purpose_sha256 IS DISTINCT FROM
           iam_rbac_assignment_step_up_purpose_v1(p_command_key, p_target_id) OR
       p_auth_time IS NULL OR p_auth_time > v_now OR
       p_auth_time < v_now - INTERVAL '10 minutes' OR
       NOT (p_amr_password OR p_amr_webauthn OR p_amr_totp) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM RBAC assignment step-up evidence is denied';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_step_up_assert_v1(p_command_key text, p_target_id uuid, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_step_up_purpose_v1(text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_step_up_purpose_v1(p_command_key text, p_target_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    RETURN pg_catalog.sha256(pg_catalog.convert_to(
        'harpy/iam/rbac-step-up/v1|' || p_command_key || '|' ||
        CASE WHEN p_command_key = 'iam.rbac.assignment.create'
            THEN '' ELSE coalesce(p_target_id::text, '') END,
        'UTF8'
    ));
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_step_up_purpose_v1(p_command_key text, p_target_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_target_active_v1(text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_target_active_v1(p_target_kind text, p_target_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_active boolean;
BEGIN
    CASE p_target_kind
    WHEN 'USER' THEN
        SELECT true INTO v_active FROM iam_users
        WHERE id = p_target_id AND status = 'active';
    WHEN 'ROLE' THEN
        SELECT true INTO v_active FROM iam_roles
        WHERE id = p_target_id AND status = 'active';
    WHEN 'ORGANIZATION' THEN
        SELECT true INTO v_active FROM iam_organizations
        WHERE id = p_target_id AND status = 'active';
    ELSE
        v_active := false;
    END CASE;
    RETURN coalesce(v_active, false);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_target_active_v1(p_target_kind text, p_target_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_assignment_update_v1(name, uuid, bytea, uuid, uuid, text, uuid, jsonb, bigint, uuid, uuid, bigint, bigint, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_assignment_update_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_resource_id uuid, p_target_kind text, p_target_id uuid, p_items jsonb, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_step_up_purpose_sha256 bytea, p_step_up_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_clock bigint;
    v_revision bigint;
    v_replayed boolean;
    v_asserted boolean;
    v_old_resource_id uuid;
    v_old_target_kind text;
    v_old_target_id uuid;
    v_permission_id uuid;
    v_binding_id uuid;
    v_bumped bigint;
    v_finished boolean;
    v_old_action_id uuid;
    v_old_permission_id uuid;
    v_old_binding_id uuid;
    v_item_ordinal integer;
    v_item_action_id uuid;
    v_item_permission_id uuid;
    v_item_binding_id uuid;
    v_now timestamptz;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    SELECT begin_result.authorization_clock,
           begin_result.result_revision, begin_result.replayed
    INTO v_clock, v_revision, v_replayed
    FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.assignment.update',
        p_request_sha256, p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS begin_result;
    IF v_replayed THEN
        RETURN QUERY SELECT p_id, v_revision, v_clock, true;
        RETURN;
    END IF;
    v_asserted := iam_rbac_assignment_step_up_assert_v1(
        'iam.rbac.assignment.update', p_id, p_step_up_purpose_sha256,
        p_step_up_auth_time, p_amr_password, p_amr_webauthn, p_amr_totp
    );
    IF p_resource_id IS NULL OR p_target_id IS NULL OR
       NOT iam_rbac_assignment_target_active_v1(p_target_kind, p_target_id) OR
       NOT iam_rbac_assignment_items_valid_v1(p_items) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC assignment update input is invalid';
    END IF;
    SELECT resource_id, target_kind, target_id, revision
    INTO v_old_resource_id, v_old_target_kind, v_old_target_id, v_revision
    FROM iam_rbac_assignment_groups
    WHERE id = p_id AND state = 'active'
    FOR UPDATE;
    IF NOT FOUND OR v_revision IS DISTINCT FROM p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM RBAC assignment revision changed';
    END IF;
    FOR v_old_action_id, v_old_permission_id, v_old_binding_id IN
        SELECT member.action_id, member.permission_id, member.binding_id
        FROM iam_rbac_assignment_members AS member
        WHERE member.group_id = p_id
          AND member.group_revision = v_revision
          AND member.state = 'active'
    LOOP
        IF v_old_resource_id IS DISTINCT FROM p_resource_id OR
           v_old_target_kind IS DISTINCT FROM p_target_kind OR
           v_old_target_id IS DISTINCT FROM p_target_id OR
           NOT EXISTS (
               SELECT 1
               FROM pg_catalog.jsonb_to_recordset(p_items) AS item(action_id uuid)
               WHERE item.action_id = v_old_action_id
           ) THEN
            v_finished := iam_rbac_assignment_binding_revoke_v1(
                v_old_target_kind, v_old_target_id,
                v_old_permission_id, v_old_binding_id
            );
        END IF;
    END LOOP;
    UPDATE iam_rbac_assignment_members
    SET state = 'revoked', revoked_at = v_now
    WHERE group_id = p_id AND group_revision = v_revision AND state = 'active';
    UPDATE iam_rbac_assignment_groups
    SET resource_id = p_resource_id, target_kind = p_target_kind,
        target_id = p_target_id, revision = revision + 1, updated_at = v_now
    WHERE id = p_id AND revision = v_revision
    RETURNING revision INTO v_revision;
    IF v_revision IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM RBAC assignment revision changed';
    END IF;
    FOR v_item_ordinal, v_item_action_id,
        v_item_permission_id, v_item_binding_id IN
        SELECT item.ordinal, item.action_id, item.permission_id, item.binding_id
        FROM pg_catalog.jsonb_to_recordset(p_items) AS item(
            ordinal integer, action_id uuid, permission_id uuid, binding_id uuid
        ) ORDER BY item.ordinal
    LOOP
        v_permission_id := iam_rbac_assignment_exact_permission_v1(
            p_resource_id, v_item_action_id, v_item_permission_id
        );
        v_binding_id := iam_rbac_assignment_binding_grant_v1(
            p_id, p_target_kind, p_target_id,
            v_permission_id, v_item_binding_id
        );
        INSERT INTO iam_rbac_assignment_members (
            group_id, group_revision, ordinal, action_id, permission_id,
            permission_match_kind, binding_id, state, created_at, revoked_at
        ) VALUES (
            p_id, v_revision, v_item_ordinal, v_item_action_id, v_permission_id,
            'exact', v_binding_id, 'active', v_now, NULL
        );
    END LOOP;
    IF v_old_target_kind IS DISTINCT FROM p_target_kind OR
       v_old_target_id IS DISTINCT FROM p_target_id THEN
        v_bumped := iam_rbac_assignment_bump_target_v1(
            v_old_target_kind, v_old_target_id, v_clock
        );
    END IF;
    v_bumped := iam_rbac_assignment_bump_target_v1(
        p_target_kind, p_target_id, v_clock
    );
    v_finished := iam_rbac_mutation_finish_v1(
        p_operation_id, 'iam.rbac.assignment.update', p_request_sha256,
        v_clock, 'iam.rbac.assignment.updated', p_id, v_revision
    );
    RETURN QUERY SELECT p_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_assignment_update_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_resource_id uuid, p_target_kind text, p_target_id uuid, p_items jsonb, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_step_up_purpose_sha256 bytea, p_step_up_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_rbac_audit_write_v1(name, uuid, uuid, uuid, bytea, text, text, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_aggregate_id uuid, p_request_sha256 bytea, p_command_key text, p_result_code text, p_aggregate_revision bigint, p_authorization_clock bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_command text; v_request bytea; v_result text; v_aggregate uuid;
    v_revision bigint; v_clock bigint; v_actor_active boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM RBAC audit scope is invalid';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_code,
        receipt.result_id, receipt.result_revision, receipt.clock_value
    INTO v_command, v_request, v_result, v_aggregate, v_revision, v_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    SELECT true INTO v_actor_active FROM iam_users AS actor
    WHERE actor.id = p_actor_id AND actor.status = 'active';
    IF v_command IS DISTINCT FROM p_command_key OR v_request IS DISTINCT FROM p_request_sha256 OR
       v_result IS DISTINCT FROM p_result_code OR v_aggregate IS DISTINCT FROM p_aggregate_id OR
       v_revision IS DISTINCT FROM p_aggregate_revision OR
       v_clock IS DISTINCT FROM p_authorization_clock OR v_actor_active IS DISTINCT FROM true THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'IAM RBAC audit evidence is invalid';
    END IF;
    INSERT INTO iam_rbac_change_audit (
        operation_id, actor_id, aggregate_id, request_sha256, command_key,
        result_code, aggregate_revision, authorization_clock, recorded_at
    ) VALUES (p_operation_id, p_actor_id, p_aggregate_id, p_request_sha256,
        p_command_key, p_result_code, p_aggregate_revision, p_authorization_clock,
        pg_catalog.transaction_timestamp());
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_audit_write_v1(p_scope_schema name, p_operation_id uuid, p_actor_id uuid, p_aggregate_id uuid, p_request_sha256 bytea, p_command_key text, p_result_code text, p_aggregate_revision bigint, p_authorization_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_bump_all_users_v1(bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_bump_all_users_v1(p_clock bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
    UPDATE iam_users SET
        authorization_version = CASE WHEN authorization_version + 1 > p_clock
            THEN authorization_version + 1 ELSE p_clock END,
        revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
    WHERE status = 'active';
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_bump_all_users_v1(p_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_bump_organization_users_v1(uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_bump_organization_users_v1(p_organization_id uuid, p_clock bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
    UPDATE iam_users AS principal SET
        authorization_version = CASE WHEN principal.authorization_version + 1 > p_clock
            THEN principal.authorization_version + 1 ELSE p_clock END,
        revision = principal.revision + 1,
        updated_at = pg_catalog.transaction_timestamp()
    WHERE principal.status = 'active' AND principal.id IN (
        SELECT membership.user_id FROM iam_organization_memberships AS membership
        WHERE membership.organization_id = p_organization_id AND membership.state = 'active'
    );
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_bump_organization_users_v1(p_organization_id uuid, p_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_bump_role_users_v1(uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_bump_role_users_v1(p_role_id uuid, p_clock bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
    UPDATE iam_users AS principal SET
        authorization_version = CASE WHEN principal.authorization_version + 1 > p_clock
            THEN principal.authorization_version + 1 ELSE p_clock END,
        revision = principal.revision + 1,
        updated_at = pg_catalog.transaction_timestamp()
    WHERE principal.status = 'active' AND principal.id IN (
        SELECT assignment.user_id FROM iam_user_role_assignments AS assignment
        WHERE assignment.role_id = p_role_id AND assignment.state = 'active'
    );
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_bump_role_users_v1(p_role_id uuid, p_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_bump_user_v1(uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_bump_user_v1(p_user_id uuid, p_clock bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
    UPDATE iam_users SET
        authorization_version = CASE WHEN authorization_version + 1 > p_clock
            THEN authorization_version + 1 ELSE p_clock END,
        revision = revision + 1, updated_at = pg_catalog.transaction_timestamp()
    WHERE id = p_user_id AND status = 'active';
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'IAM RBAC user is unavailable';
    END IF;
    RETURN v_count;
END;
$$;


