--
-- Name: iam_rbac_effective_permissions_v1(name, text, uuid, integer, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_effective_permissions_v1(p_scope_schema name, p_target_kind text, p_target_id uuid, p_limit integer, p_actor_id uuid, p_required_permission_id uuid) RETURNS TABLE(permission_id uuid, match_kind text, resource_id uuid, resource_key text, action_id uuid, action_key text, source_kind text, source_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit NOT BETWEEN 1 AND 500 OR
       p_target_kind NOT IN ('USER', 'ROLE', 'ORGANIZATION') OR
       NOT iam_rbac_assignment_target_active_v1(p_target_kind, p_target_id) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM RBAC effective permission input is invalid';
    END IF;
    IF NOT iam_rbac_read_assert_v1(
        p_scope_schema, p_actor_id, p_required_permission_id
    ) THEN
        RETURN;
    END IF;
    RETURN QUERY
    WITH bindings AS (
        SELECT binding.permission_id, 'USER'::text AS source_kind,
               binding.user_id AS source_id
        FROM iam_user_permission_bindings AS binding
        WHERE p_target_kind = 'USER' AND binding.user_id = p_target_id
          AND binding.state = 'active'
        UNION ALL
        SELECT binding.permission_id, 'ROLE'::text, binding.role_id
        FROM iam_role_permission_bindings AS binding
        WHERE binding.state = 'active' AND (
            (p_target_kind = 'ROLE' AND binding.role_id = p_target_id) OR
            (p_target_kind = 'USER' AND EXISTS (
                SELECT 1 FROM iam_user_role_assignments AS membership
                WHERE membership.user_id = p_target_id
                  AND membership.role_id = binding.role_id
                  AND membership.state = 'active'
            ))
        )
        UNION ALL
        SELECT binding.permission_id, 'ORGANIZATION'::text,
               binding.organization_id
        FROM iam_organization_permission_bindings AS binding
        WHERE binding.state = 'active' AND (
            (p_target_kind = 'ORGANIZATION' AND
             binding.organization_id = p_target_id) OR
            (p_target_kind = 'USER' AND EXISTS (
                SELECT 1 FROM iam_organization_memberships AS membership
                WHERE membership.user_id = p_target_id
                  AND membership.organization_id = binding.organization_id
                  AND membership.state = 'active'
            ))
        )
    ), expanded AS (
        SELECT binding.permission_id, binding.source_kind, binding.source_id
        FROM bindings AS binding
        UNION
        SELECT implication.implied_permission_id,
               binding.source_kind, binding.source_id
        FROM bindings AS binding
        JOIN iam_permission_implications AS implication
          ON implication.source_permission_id = binding.permission_id
         AND implication.state = 'active'
    )
    SELECT permission.id, permission.match_kind,
           resource.id, coalesce(resource.resource_key, '*'),
           action.id, coalesce(action.action_key, '*'),
           expanded.source_kind, expanded.source_id
    FROM expanded
    JOIN iam_permissions AS permission
      ON permission.id = expanded.permission_id
     AND permission.state = 'active'
    LEFT JOIN iam_resources AS resource
      ON resource.id = permission.resource_id AND resource.state = 'active'
    LEFT JOIN iam_actions AS action
      ON action.id = permission.action_id AND action.state = 'active'
    WHERE (permission.resource_id IS NULL OR resource.id IS NOT NULL)
      AND (permission.action_id IS NULL OR action.id IS NOT NULL)
    ORDER BY coalesce(resource.resource_key, '*'),
             coalesce(action.action_key, '*'),
             expanded.source_kind, expanded.source_id, permission.id
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_effective_permissions_v1(p_scope_schema name, p_target_kind text, p_target_id uuid, p_limit integer, p_actor_id uuid, p_required_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_implication_create_v1(name, uuid, bytea, uuid, uuid, uuid, text, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_implication_create_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_source_permission_id uuid, p_implied_permission_id uuid, p_retirement_contract_key text, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_clock bigint; v_revision bigint; v_replayed boolean;
    v_count bigint; v_finished boolean; v_now timestamptz;
BEGIN
    SELECT b.authorization_clock, b.result_revision, b.replayed
    INTO v_clock, v_revision, v_replayed FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.implication.create', p_request_sha256,
        p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS b;
    IF v_replayed THEN RETURN QUERY SELECT p_id, v_revision, v_clock, true; RETURN; END IF;
    v_now := pg_catalog.transaction_timestamp();
    INSERT INTO iam_permission_implications (
        id, implication_kind, source_permission_id, source_match_kind,
        implied_permission_id, implied_match_kind, retirement_contract_key,
        state, hit_count, last_hit_at, retirement_receipt_id, revision,
        created_at, updated_at, retired_at
    ) VALUES (p_id, p_retirement_contract_key, p_source_permission_id, 'exact',
        p_implied_permission_id, 'exact', p_retirement_contract_key,
        'active', 0, NULL, NULL, 1, v_now, v_now, NULL);
    v_count := iam_rbac_bump_all_users_v1(v_clock);
    v_finished := iam_rbac_mutation_finish_v1(p_operation_id,
        'iam.rbac.implication.create', p_request_sha256, v_clock,
        'iam.rbac.implication.created', p_id, 1);
    RETURN QUERY SELECT p_id, 1::bigint, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_implication_create_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_source_permission_id uuid, p_implied_permission_id uuid, p_retirement_contract_key text, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_implication_get_v1(name, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_implication_get_v1(p_scope_schema name, p_id uuid, p_actor_id uuid, p_required_permission_id uuid) RETURNS TABLE(id uuid, source_permission_id uuid, implied_permission_id uuid, retirement_contract_key text, state text, hit_count bigint, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT iam_rbac_read_assert_v1(p_scope_schema, p_actor_id, p_required_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM RBAC query denied';
    END IF;
    RETURN QUERY SELECT edge.id, edge.source_permission_id, edge.implied_permission_id,
        edge.retirement_contract_key, edge.state, edge.hit_count, edge.revision
    FROM iam_permission_implications AS edge WHERE edge.id = p_id;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_implication_get_v1(p_scope_schema name, p_id uuid, p_actor_id uuid, p_required_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_implication_list_v1(name, text, integer, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_implication_list_v1(p_scope_schema name, p_state text, p_limit integer, p_actor_id uuid, p_required_permission_id uuid) RETURNS TABLE(id uuid, source_permission_id uuid, implied_permission_id uuid, retirement_contract_key text, state text, hit_count bigint, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_limit < 1 OR p_limit > 200 OR p_state NOT IN ('active','retired','all') THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'IAM RBAC implication query is invalid';
    END IF;
    IF NOT iam_rbac_read_assert_v1(p_scope_schema, p_actor_id, p_required_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'IAM RBAC query denied';
    END IF;
    RETURN QUERY SELECT edge.id, edge.source_permission_id, edge.implied_permission_id,
        edge.retirement_contract_key, edge.state, edge.hit_count, edge.revision
    FROM iam_permission_implications AS edge
    WHERE p_state = 'all' OR edge.state = p_state
    ORDER BY edge.retirement_contract_key, edge.id LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_implication_list_v1(p_scope_schema name, p_state text, p_limit integer, p_actor_id uuid, p_required_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_rbac_implication_record_hit_v1(name, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_implication_record_hit_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_clock bigint; v_revision bigint; v_replayed boolean; v_now timestamptz;
    v_finished boolean;
BEGIN
    SELECT b.authorization_clock, b.result_revision, b.replayed
    INTO v_clock, v_revision, v_replayed FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.implication.record_hit', p_request_sha256,
        p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS b;
    IF v_replayed THEN RETURN QUERY SELECT p_id, v_revision, v_clock, true; RETURN; END IF;
    v_now := pg_catalog.transaction_timestamp();
    UPDATE iam_permission_implications SET hit_count = hit_count + 1,
        last_hit_at = v_now, revision = revision + 1, updated_at = v_now
    WHERE id = p_id AND state = 'active' AND revision = p_expected_revision
    RETURNING revision INTO v_revision;
    IF v_revision IS NULL THEN RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM RBAC implication revision changed'; END IF;
    v_finished := iam_rbac_mutation_finish_v1(p_operation_id,
        'iam.rbac.implication.record_hit', p_request_sha256, v_clock,
        'iam.rbac.implication.hit_recorded', p_id, v_revision);
    RETURN QUERY SELECT p_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_rbac_implication_record_hit_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_rbac_implication_retire_v1(name, uuid, bytea, uuid, bigint, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_rbac_implication_retire_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_expected_revision bigint, p_retirement_receipt_id uuid, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_clock bigint; v_revision bigint; v_replayed boolean; v_now timestamptz;
    v_count bigint; v_finished boolean;
BEGIN
    IF p_retirement_receipt_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'IAM RBAC retirement receipt is required';
    END IF;
    SELECT b.authorization_clock, b.result_revision, b.replayed
    INTO v_clock, v_revision, v_replayed FROM iam_rbac_mutation_begin_v1(
        p_scope_schema, p_operation_id, 'iam.rbac.implication.retire', p_request_sha256,
        p_id, p_actor_id, p_required_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) AS b;
    IF v_replayed THEN RETURN QUERY SELECT p_id, v_revision, v_clock, true; RETURN; END IF;
    v_now := pg_catalog.transaction_timestamp();
    UPDATE iam_permission_implications SET state = 'retired',
        retirement_receipt_id = p_retirement_receipt_id, revision = revision + 1,
        updated_at = v_now, retired_at = v_now
    WHERE id = p_id AND state = 'active' AND revision = p_expected_revision
    RETURNING revision INTO v_revision;
    IF v_revision IS NULL THEN RAISE EXCEPTION USING ERRCODE = '40001',
        MESSAGE = 'IAM RBAC implication revision changed'; END IF;
    v_count := iam_rbac_bump_all_users_v1(v_clock);
    v_finished := iam_rbac_mutation_finish_v1(p_operation_id,
        'iam.rbac.implication.retire', p_request_sha256, v_clock,
        'iam.rbac.implication.retired', p_id, v_revision);
    RETURN QUERY SELECT p_id, v_revision, v_clock, false;
END;
$$;


