ALTER FUNCTION __tenant_schema__.iam_rbac_user_binding_revoke_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_id uuid, p_user_id uuid, p_permission_id uuid, p_expected_revision bigint, p_actor_id uuid, p_required_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_reauth_binding_sha256_v1(uuid, uuid, uuid, bigint, bigint, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reauth_binding_sha256_v1(p_tenant_id uuid, p_user_id uuid, p_session_id uuid, p_token_version bigint, p_authorization_version bigint, p_access_mode text, p_portal_binding_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_tenant_id IS NULL OR p_user_id IS NULL OR p_session_id IS NULL OR
       p_token_version OPERATOR(pg_catalog.<=) 0 OR
       p_authorization_version OPERATOR(pg_catalog.<=) 0 OR NOT (
           (p_access_mode IS NOT DISTINCT FROM 'operator_console' AND
            p_portal_binding_id IS NULL) OR
           (p_access_mode IS NOT DISTINCT FROM 'portal' AND
            p_portal_binding_id IS NOT NULL)
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM reauthentication binding input is invalid';
    END IF;
    RETURN pg_catalog.sha256(
        pg_catalog.convert_to('harpy:iam-reauth-session:v1', 'UTF8')
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.uuid_send(p_tenant_id)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.uuid_send(p_user_id)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.uuid_send(p_session_id)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.int8send(p_token_version)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.int8send(p_authorization_version)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.convert_to(p_access_mode, 'UTF8')
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||)
        pg_catalog.uuid_send(COALESCE(
            p_portal_binding_id,
            '00000000-0000-0000-0000-000000000000'::uuid
        )) OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reauth_binding_sha256_v1(p_tenant_id uuid, p_user_id uuid, p_session_id uuid, p_token_version bigint, p_authorization_version bigint, p_access_mode text, p_portal_binding_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_reauth_context_sha256_v1(uuid, uuid, uuid, bytea, bigint, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reauth_context_sha256_v1(p_tenant_id uuid, p_user_id uuid, p_session_id uuid, p_purpose_sha256 bytea, p_action_policy_version bigint, p_method text, p_origin_sha256 bytea) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_tenant_id IS NULL OR p_user_id IS NULL OR p_session_id IS NULL OR
       pg_catalog.octet_length(p_purpose_sha256) IS DISTINCT FROM 32 OR
       p_action_policy_version OPERATOR(pg_catalog.<=) 0 OR
       p_method NOT IN ('password_v1', 'webauthn_v1', 'totp_v1') OR
       pg_catalog.octet_length(p_origin_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM reauthentication context input is invalid';
    END IF;
    RETURN pg_catalog.sha256(
        pg_catalog.convert_to('harpy:iam-reauth-context:v1', 'UTF8')
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.uuid_send(p_tenant_id)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.uuid_send(p_user_id)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.uuid_send(p_session_id)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) p_purpose_sha256
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.int8send(p_action_policy_version)
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) pg_catalog.convert_to(p_method, 'UTF8')
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
        OPERATOR(pg_catalog.||) p_origin_sha256
        OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reauth_context_sha256_v1(p_tenant_id uuid, p_user_id uuid, p_session_id uuid, p_purpose_sha256 bytea, p_action_policy_version bigint, p_method text, p_origin_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_reauthentication_complete_v1(name, uuid, bytea, uuid, bigint, smallint, uuid, uuid, bigint, bigint, bigint, bigint, uuid, text, bigint, uuid, bigint, uuid, uuid, bigint, bigint, uuid, bigint, bigint, bigint, bigint, bytea, bytea, text, bigint, boolean, boolean, bigint, uuid, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reauthentication_complete_v1(p_scope_schema name, p_tenant_id uuid, p_scope_binding bytea, p_challenge_id uuid, p_expected_challenge_revision bigint, p_expected_attempt_count smallint, p_user_id uuid, p_session_id uuid, p_expected_user_revision bigint, p_expected_session_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_access_mode text, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_family_id uuid, p_token_id uuid, p_expected_family_revision bigint, p_expected_token_revision bigint, p_authenticator_id uuid, p_expected_authenticator_revision bigint, p_expected_subtype_revision bigint, p_expected_password_version bigint, p_expected_password_revision bigint, p_purpose_sha256 bytea, p_context_sha256 bytea, p_method text, p_webauthn_sign_count bigint, p_webauthn_backup_eligible boolean, p_webauthn_backup_state boolean, p_totp_time_step bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) RETURNS TABLE(issued_at timestamp with time zone, challenge_revision bigint, family_revision bigint, session_revision bigint, consumed_token_revision bigint, successor_token_revision bigint, locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone, successor_selector bytea, successor_revision bigint, successor_source_sha256 bytea, successor_state text, successor_issued_at timestamp with time zone, successor_projected_at timestamp with time zone, successor_family_expires_at timestamp with time zone, successor_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_challenge_state text;
    v_challenge_revision bigint;
    v_attempt_count smallint;
    v_challenge_user_id uuid;
    v_challenge_session_id uuid;
    v_challenge_authenticator_id uuid;
    v_challenge_method text;
    v_challenge_purpose bytea;
    v_challenge_context bytea;
    v_challenge_expires_at timestamptz;
    v_resolved text;
    v_proof_revision bigint;
    v_issued_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.octet_length(p_scope_binding) IS DISTINCT FROM 32 OR
       iam_reauth_binding_sha256_v1(
           p_tenant_id, p_user_id, p_session_id, p_expected_token_version,
           p_expected_authorization_version, p_access_mode,
           p_portal_binding_id
       ) IS DISTINCT FROM p_scope_binding OR
       pg_catalog.octet_length(p_purpose_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_context_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_successor_selector) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_successor_secret_hmac) IS DISTINCT FROM 32
       THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM reauthentication completion scope is invalid';
    END IF;
    SELECT challenge.state, challenge.revision, challenge.attempt_count,
           challenge.user_id, challenge.session_id,
           challenge.authenticator_id, challenge.proof_kind,
           challenge.step_up_purpose_sha256, challenge.context_sha256,
           challenge.expires_at
    INTO v_challenge_state, v_challenge_revision, v_attempt_count,
         v_challenge_user_id, v_challenge_session_id,
         v_challenge_authenticator_id, v_challenge_method,
         v_challenge_purpose, v_challenge_context, v_challenge_expires_at
    FROM iam_auth_challenges AS challenge
    WHERE challenge.id OPERATOR(pg_catalog.=) p_challenge_id
      AND challenge.purpose OPERATOR(pg_catalog.=) 'reauth_v1'
    FOR UPDATE;
    IF v_challenge_state IS DISTINCT FROM 'pending' OR
       v_challenge_revision IS DISTINCT FROM p_expected_challenge_revision OR
       v_attempt_count IS DISTINCT FROM p_expected_attempt_count OR
       v_challenge_user_id IS DISTINCT FROM p_user_id OR
       v_challenge_session_id IS DISTINCT FROM p_session_id OR
       v_challenge_authenticator_id IS DISTINCT FROM p_authenticator_id OR
       v_challenge_method IS DISTINCT FROM p_method OR
       v_challenge_purpose IS DISTINCT FROM p_purpose_sha256 OR
       v_challenge_context IS DISTINCT FROM p_context_sha256 OR
       v_challenge_expires_at OPERATOR(pg_catalog.<=) v_now THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication completion CAS is stale';
    END IF;
    v_resolved := iam_challenge_resolve_v1(
        p_scope_schema, p_challenge_id, p_expected_challenge_revision,
        p_expected_attempt_count, 'consume'
    );
    IF v_resolved IS DISTINCT FROM 'consumed' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication challenge was not consumed';
    END IF;
    v_proof_revision := iam_reauthentication_proof_apply_v1(
        p_scope_schema, p_user_id, p_method, p_authenticator_id,
        p_expected_authenticator_revision, p_expected_subtype_revision,
        p_expected_password_version, p_expected_password_revision,
        p_webauthn_sign_count, p_webauthn_backup_eligible,
        p_webauthn_backup_state, p_totp_time_step
    );
    SELECT rotated.issued_at, rotated.family_revision,
           rotated.session_revision, rotated.locator_selector,
           rotated.locator_expected_revision, rotated.locator_revision,
           rotated.locator_source_sha256, rotated.locator_state,
           rotated.locator_projected_at, rotated.locator_retain_until,
           rotated.successor_selector, rotated.successor_revision,
           rotated.successor_source_sha256, rotated.successor_state,
           rotated.successor_issued_at, rotated.successor_projected_at,
           rotated.successor_family_expires_at,
           rotated.successor_retain_until
    INTO v_issued_at, family_revision, session_revision, locator_selector,
         locator_expected_revision, locator_revision, locator_source_sha256,
         locator_state, locator_projected_at, locator_retain_until,
         successor_selector, successor_revision, successor_source_sha256,
         successor_state, successor_issued_at, successor_projected_at,
         successor_family_expires_at, successor_retain_until
    FROM iam_reauthentication_rotate_active_v1(
        p_scope_schema, p_token_id, p_family_id,
        p_expected_token_revision, p_expected_family_revision,
        p_session_id, p_expected_session_revision, p_user_id,
        p_expected_user_revision, p_expected_token_version,
        p_expected_authorization_version, p_access_mode_id,
        p_expected_access_mode_revision, p_portal_binding_id,
        p_expected_portal_binding_revision, p_successor_id,
        p_successor_selector, p_successor_hash_key_id,
        p_successor_secret_hmac, p_method, p_purpose_sha256
    ) AS rotated;
    challenge_revision := p_expected_challenge_revision
        OPERATOR(pg_catalog.+) 1;
    consumed_token_revision := locator_revision;
    successor_token_revision := successor_revision;
    issued_at := v_issued_at;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reauthentication_complete_v1(p_scope_schema name, p_tenant_id uuid, p_scope_binding bytea, p_challenge_id uuid, p_expected_challenge_revision bigint, p_expected_attempt_count smallint, p_user_id uuid, p_session_id uuid, p_expected_user_revision bigint, p_expected_session_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_access_mode text, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_family_id uuid, p_token_id uuid, p_expected_family_revision bigint, p_expected_token_revision bigint, p_authenticator_id uuid, p_expected_authenticator_revision bigint, p_expected_subtype_revision bigint, p_expected_password_version bigint, p_expected_password_revision bigint, p_purpose_sha256 bytea, p_context_sha256 bytea, p_method text, p_webauthn_sign_count bigint, p_webauthn_backup_eligible boolean, p_webauthn_backup_state boolean, p_totp_time_step bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_reauthentication_credential_v1(name, uuid, bytea, uuid, uuid, uuid, bigint, bigint, text, uuid, text, bytea, bigint, bytea, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reauthentication_credential_v1(p_scope_schema name, p_tenant_id uuid, p_scope_binding bytea, p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode text, p_portal_binding_id uuid, p_method text, p_purpose_sha256 bytea, p_action_policy_version bigint, p_origin_sha256 bytea, p_context_sha256 bytea) RETURNS TABLE(challenge_revision bigint, attempt_count smallint, challenge_state text, hmac_key_id text, challenge_hmac bytea, context_sha256 bytea, purpose_sha256 bytea, origin_sha256 bytea, action_policy_version bigint, expires_at timestamp with time zone, user_revision bigint, token_version bigint, authorization_version bigint, user_status text, identity_kind text, session_revision bigint, session_state text, session_absolute_expires_at timestamp with time zone, access_mode_id uuid, access_mode text, access_mode_state text, access_mode_revision bigint, portal_binding_id uuid, portal_binding_state text, portal_binding_revision bigint, family_id uuid, family_revision bigint, family_state text, family_absolute_expires_at timestamp with time zone, token_id uuid, token_revision bigint, token_state text, password_credential_version bigint, password_credential_revision bigint, password_algorithm text, password_salt bytea, password_tag bytea, password_memory_kib integer, password_iterations smallint, password_parallelism smallint, password_legacy_hash text, password_created_at timestamp with time zone, authenticator_id uuid, authenticator_state text, authenticator_kind text, authenticator_revision bigint, webauthn_credential_id bytea, webauthn_public_key_cose bytea, webauthn_rp_id text, webauthn_rp_id_sha256 bytea, webauthn_origin_policy_version bigint, webauthn_sign_count bigint, webauthn_backup_eligible boolean, webauthn_backup_state boolean, webauthn_uv_required boolean, webauthn_revision bigint, totp_profile text, totp_cipher_suite text, totp_kms_key_id text, totp_nonce bytea, totp_secret_ciphertext bytea, totp_authentication_tag bytea, totp_aad_sha256 bytea, totp_last_accepted_time_step bigint, totp_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_rows bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_challenge_id IS NULL OR p_user_id IS NULL OR p_session_id IS NULL OR
       pg_catalog.octet_length(p_scope_binding) IS DISTINCT FROM 32 OR
       iam_reauth_binding_sha256_v1(
           p_tenant_id, p_user_id, p_session_id, p_expected_token_version,
           p_expected_authorization_version, p_access_mode,
           p_portal_binding_id
       ) IS DISTINCT FROM p_scope_binding OR
       iam_reauth_context_sha256_v1(
           p_tenant_id, p_user_id, p_session_id, p_purpose_sha256,
           p_action_policy_version, p_method, p_origin_sha256
       ) IS DISTINCT FROM p_context_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM reauthentication credential evidence is invalid';
    END IF;
    RETURN QUERY
    SELECT challenge.revision, challenge.attempt_count, challenge.state,
           challenge.hmac_key_id, challenge.challenge_hmac,
           challenge.context_sha256, challenge.step_up_purpose_sha256,
           p_origin_sha256, challenge.action_policy_version,
           challenge.expires_at, principal.revision,
           principal.token_version, principal.authorization_version,
           principal.status, principal.identity_kind, session.revision,
           session.state, session.absolute_expires_at, access.id,
           session.access_mode, access.state, access.revision, binding.id,
           binding.state, binding.revision, family.id, family.revision,
           family.state, family.absolute_expires_at, token.id,
           token.revision, token.state, password.credential_version,
           password.revision, password.algorithm, password.salt,
           password.tag, password.memory_kib, password.iterations,
           password.parallelism, password.legacy_bcrypt_hash,
           password.created_at, authenticator.id, authenticator.state,
           authenticator.kind, authenticator.revision,
           webauthn.credential_id, webauthn.public_key_cose, webauthn.rp_id,
           webauthn.rp_id_sha256, webauthn.origin_policy_version,
           webauthn.sign_count, webauthn.backup_eligible,
           webauthn.backup_state, webauthn.uv_required, webauthn.revision,
           totp.profile, totp.cipher_suite, totp.kms_key_id, totp.nonce,
           totp.secret_ciphertext, totp.authentication_tag, totp.aad_sha256,
           totp.last_accepted_time_step, totp.revision
    FROM iam_auth_challenges AS challenge
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) challenge.user_id
    JOIN iam_sessions AS session
      ON session.id OPERATOR(pg_catalog.=) challenge.session_id
     AND session.user_id OPERATOR(pg_catalog.=) principal.id
    JOIN iam_user_access_modes AS access
      ON access.id OPERATOR(pg_catalog.=) session.access_mode_id
     AND access.user_id OPERATOR(pg_catalog.=) principal.id
     AND access.mode OPERATOR(pg_catalog.=) session.access_mode
    JOIN iam_refresh_families AS family
      ON family.session_id OPERATOR(pg_catalog.=) session.id
     AND family.user_id OPERATOR(pg_catalog.=) principal.id
    JOIN iam_refresh_tokens AS token
      ON token.family_id OPERATOR(pg_catalog.=) family.id
     AND token.state OPERATOR(pg_catalog.=) 'active'
    LEFT JOIN iam_portal_subject_bindings AS binding
      ON binding.id OPERATOR(pg_catalog.=) session.portal_binding_id
     AND binding.user_id OPERATOR(pg_catalog.=) principal.id
     AND binding.access_mode_id OPERATOR(pg_catalog.=) access.id
    LEFT JOIN iam_password_credentials AS password
      ON password.user_id OPERATOR(pg_catalog.=) principal.id
     AND challenge.proof_kind OPERATOR(pg_catalog.=) 'password_v1'
    LEFT JOIN iam_authenticators AS authenticator
      ON authenticator.id OPERATOR(pg_catalog.=) challenge.authenticator_id
     AND authenticator.user_id OPERATOR(pg_catalog.=) principal.id
     AND authenticator.kind OPERATOR(pg_catalog.=) challenge.authenticator_kind
    LEFT JOIN iam_webauthn_credentials AS webauthn
      ON webauthn.authenticator_id OPERATOR(pg_catalog.=) authenticator.id
     AND challenge.proof_kind OPERATOR(pg_catalog.=) 'webauthn_v1'
    LEFT JOIN iam_totp_authenticators AS totp
      ON totp.authenticator_id OPERATOR(pg_catalog.=) authenticator.id
     AND challenge.proof_kind OPERATOR(pg_catalog.=) 'totp_v1'
    WHERE challenge.id OPERATOR(pg_catalog.=) p_challenge_id
      AND challenge.user_id OPERATOR(pg_catalog.=) p_user_id
      AND challenge.session_id OPERATOR(pg_catalog.=) p_session_id
      AND challenge.purpose OPERATOR(pg_catalog.=) 'reauth_v1'
      AND challenge.proof_kind OPERATOR(pg_catalog.=) p_method
      AND challenge.context_sha256 OPERATOR(pg_catalog.=) p_context_sha256
      AND challenge.step_up_purpose_sha256 OPERATOR(pg_catalog.=)
          p_purpose_sha256
      AND challenge.action_policy_version OPERATOR(pg_catalog.=)
          p_action_policy_version
      AND principal.token_version OPERATOR(pg_catalog.=)
          p_expected_token_version
      AND principal.authorization_version OPERATOR(pg_catalog.=)
          p_expected_authorization_version
      AND session.access_mode OPERATOR(pg_catalog.=) p_access_mode
      AND session.portal_binding_id IS NOT DISTINCT FROM p_portal_binding_id
      AND ((p_method OPERATOR(pg_catalog.=) 'webauthn_v1' AND
            challenge.origin_sha256 OPERATOR(pg_catalog.=) p_origin_sha256) OR
           (p_method OPERATOR(pg_catalog.<>) 'webauthn_v1' AND
            challenge.origin_sha256 IS NULL));
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows OPERATOR(pg_catalog.>) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '21000',
            MESSAGE = 'IAM reauthentication credential is ambiguous';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reauthentication_credential_v1(p_scope_schema name, p_tenant_id uuid, p_scope_binding bytea, p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode text, p_portal_binding_id uuid, p_method text, p_purpose_sha256 bytea, p_action_policy_version bigint, p_origin_sha256 bytea, p_context_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_reauthentication_proof_apply_v1(name, uuid, text, uuid, bigint, bigint, bigint, bigint, bigint, boolean, boolean, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reauthentication_proof_apply_v1(p_scope_schema name, p_user_id uuid, p_method text, p_authenticator_id uuid, p_expected_authenticator_revision bigint, p_expected_subtype_revision bigint, p_expected_password_version bigint, p_expected_password_revision bigint, p_webauthn_sign_count bigint, p_webauthn_backup_eligible boolean, p_webauthn_backup_state boolean, p_totp_time_step bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_authenticator_state text;
    v_authenticator_revision bigint;
    v_subtype_revision bigint;
    v_sign_count bigint;
    v_backup_eligible boolean;
    v_last_time_step bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_user_id IS NULL OR
       p_method NOT IN ('password_v1', 'webauthn_v1', 'totp_v1') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM reauthentication proof scope is invalid';
    END IF;
    IF p_method OPERATOR(pg_catalog.=) 'password_v1' THEN
        IF p_authenticator_id IS NOT NULL OR
           p_expected_password_version OPERATOR(pg_catalog.<=) 0 OR
           p_expected_password_revision OPERATOR(pg_catalog.<=) 0 THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'IAM password proof evidence is invalid';
        END IF;
        UPDATE iam_password_credentials
        SET last_used_at = v_now, updated_at = v_now,
            revision = revision OPERATOR(pg_catalog.+) 1
        WHERE user_id OPERATOR(pg_catalog.=) p_user_id
          AND state OPERATOR(pg_catalog.=) 'active'
          AND algorithm OPERATOR(pg_catalog.=) 'argon2id_v1'
          AND credential_version OPERATOR(pg_catalog.=)
              p_expected_password_version
          AND revision OPERATOR(pg_catalog.=) p_expected_password_revision;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM password proof CAS is stale';
        END IF;
        RETURN p_expected_password_revision OPERATOR(pg_catalog.+) 1;
    END IF;
    SELECT authenticator.state, authenticator.revision
    INTO v_authenticator_state, v_authenticator_revision
    FROM iam_authenticators AS authenticator
    WHERE authenticator.id OPERATOR(pg_catalog.=) p_authenticator_id
      AND authenticator.user_id OPERATOR(pg_catalog.=) p_user_id
      AND authenticator.kind OPERATOR(pg_catalog.=) p_method
    FOR UPDATE;
    IF v_authenticator_state IS DISTINCT FROM 'active' OR
       v_authenticator_revision IS DISTINCT FROM
           p_expected_authenticator_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM authenticator proof CAS is stale';
    END IF;
    IF p_method OPERATOR(pg_catalog.=) 'webauthn_v1' THEN
        SELECT credential.revision, credential.sign_count,
               credential.backup_eligible
        INTO v_subtype_revision, v_sign_count, v_backup_eligible
        FROM iam_webauthn_credentials AS credential
        WHERE credential.authenticator_id OPERATOR(pg_catalog.=)
            p_authenticator_id
        FOR UPDATE;
        IF v_subtype_revision IS DISTINCT FROM p_expected_subtype_revision OR
           p_webauthn_sign_count OPERATOR(pg_catalog.<) 0 OR
           p_webauthn_backup_eligible IS DISTINCT FROM v_backup_eligible OR
           (p_webauthn_backup_state AND NOT p_webauthn_backup_eligible) OR
           (v_sign_count OPERATOR(pg_catalog.>) 0 AND
            p_webauthn_sign_count OPERATOR(pg_catalog.>) 0 AND
            p_webauthn_sign_count OPERATOR(pg_catalog.<=) v_sign_count AND
            NOT (v_backup_eligible AND p_webauthn_backup_state)) THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM WebAuthn proof CAS is stale';
        END IF;
        UPDATE iam_webauthn_credentials
        SET sign_count = CASE
                WHEN p_webauthn_sign_count OPERATOR(pg_catalog.>) sign_count
                THEN p_webauthn_sign_count ELSE sign_count END,
            backup_state = p_webauthn_backup_state, updated_at = v_now,
            revision = revision OPERATOR(pg_catalog.+) 1
        WHERE authenticator_id OPERATOR(pg_catalog.=) p_authenticator_id;
    ELSE
        SELECT totp.revision, totp.last_accepted_time_step
        INTO v_subtype_revision, v_last_time_step
        FROM iam_totp_authenticators AS totp
        WHERE totp.authenticator_id OPERATOR(pg_catalog.=) p_authenticator_id
          AND totp.profile OPERATOR(pg_catalog.=) 'totp_sha256_6_30_v1'
          AND totp.verified_at IS NOT NULL
        FOR UPDATE;
        IF v_subtype_revision IS DISTINCT FROM p_expected_subtype_revision OR
           p_totp_time_step OPERATOR(pg_catalog.<) 0 OR
           (v_last_time_step IS NOT NULL AND
            p_totp_time_step OPERATOR(pg_catalog.<=) v_last_time_step) THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM TOTP proof CAS is stale';
        END IF;
        UPDATE iam_totp_authenticators
        SET last_accepted_time_step = p_totp_time_step, updated_at = v_now,
            revision = revision OPERATOR(pg_catalog.+) 1
        WHERE authenticator_id OPERATOR(pg_catalog.=) p_authenticator_id;
    END IF;
    UPDATE iam_authenticators
    SET last_used_at = v_now, updated_at = v_now,
        revision = revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_authenticator_id
      AND revision OPERATOR(pg_catalog.=) p_expected_authenticator_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM authenticator proof update is stale';
    END IF;
    RETURN p_expected_authenticator_revision OPERATOR(pg_catalog.+) 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reauthentication_proof_apply_v1(p_scope_schema name, p_user_id uuid, p_method text, p_authenticator_id uuid, p_expected_authenticator_revision bigint, p_expected_subtype_revision bigint, p_expected_password_version bigint, p_expected_password_revision bigint, p_webauthn_sign_count bigint, p_webauthn_backup_eligible boolean, p_webauthn_backup_state boolean, p_totp_time_step bigint) OWNER TO harpy_owner;

--
-- Name: iam_reauthentication_reject_v1(name, uuid, bigint, smallint, uuid, bigint, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reauthentication_reject_v1(p_scope_schema name, p_challenge_id uuid, p_expected_revision bigint, p_expected_attempt_count smallint, p_authenticator_id uuid, p_expected_authenticator_revision bigint, p_quarantine_authenticator boolean, p_expire boolean) RETURNS TABLE(state text, revision bigint, attempt_count smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_authenticator_id uuid;
    v_authenticator_state text;
    v_authenticator_revision bigint;
    v_disposition text;
    v_resolved text;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_challenge_id IS NULL OR p_expected_revision OPERATOR(pg_catalog.<=) 0 OR
       p_expected_attempt_count NOT BETWEEN 0 AND 4 OR
       p_quarantine_authenticator IS NULL OR p_expire IS NULL OR
       (p_quarantine_authenticator AND (
           p_authenticator_id IS NULL OR
           p_expected_authenticator_revision OPERATOR(pg_catalog.<=) 0
       )) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM reauthentication rejection evidence is invalid';
    END IF;
    SELECT challenge.authenticator_id
    INTO v_authenticator_id
    FROM iam_auth_challenges AS challenge
    WHERE challenge.id OPERATOR(pg_catalog.=) p_challenge_id
      AND challenge.purpose OPERATOR(pg_catalog.=) 'reauth_v1'
    FOR UPDATE;
    IF NOT FOUND OR (p_quarantine_authenticator AND
        v_authenticator_id IS DISTINCT FROM p_authenticator_id) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication rejection CAS is stale';
    END IF;
    IF p_quarantine_authenticator THEN
        SELECT authenticator.state, authenticator.revision
        INTO v_authenticator_state, v_authenticator_revision
        FROM iam_authenticators AS authenticator
        WHERE authenticator.id OPERATOR(pg_catalog.=) p_authenticator_id
        FOR UPDATE;
    END IF;
    IF p_quarantine_authenticator AND (
        v_authenticator_state IS DISTINCT FROM 'active' OR
        v_authenticator_revision IS DISTINCT FROM
            p_expected_authenticator_revision
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication rejection CAS is stale';
    END IF;
    v_disposition := CASE WHEN p_expire THEN 'expire' ELSE 'reject' END;
    v_resolved := iam_challenge_resolve_v1(
        p_scope_schema, p_challenge_id, p_expected_revision,
        p_expected_attempt_count, v_disposition
    );
    IF p_quarantine_authenticator THEN
        UPDATE iam_authenticators
        SET state = 'compromised', compromised_at = v_now,
            updated_at = v_now,
            revision = p_expected_authenticator_revision
                OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_authenticator_id
          AND state OPERATOR(pg_catalog.=) 'active'
          AND revision OPERATOR(pg_catalog.=)
              p_expected_authenticator_revision;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM authenticator quarantine CAS is stale';
        END IF;
    END IF;
    RETURN QUERY
    SELECT challenge.state, challenge.revision, challenge.attempt_count
    FROM iam_auth_challenges AS challenge
    WHERE challenge.id OPERATOR(pg_catalog.=) p_challenge_id
      AND challenge.state OPERATOR(pg_catalog.=) v_resolved;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reauthentication_reject_v1(p_scope_schema name, p_challenge_id uuid, p_expected_revision bigint, p_expected_attempt_count smallint, p_authenticator_id uuid, p_expected_authenticator_revision bigint, p_quarantine_authenticator boolean, p_expire boolean) OWNER TO harpy_owner;

--
-- Name: iam_reauthentication_rotate_active_v1(name, uuid, uuid, bigint, bigint, uuid, bigint, uuid, bigint, bigint, bigint, uuid, bigint, uuid, bigint, uuid, bytea, text, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reauthentication_rotate_active_v1(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea, p_method text, p_purpose_sha256 bytea) RETURNS TABLE(issued_at timestamp with time zone, family_revision bigint, session_revision bigint, locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone, successor_selector bytea, successor_revision bigint, successor_source_sha256 bytea, successor_state text, successor_issued_at timestamp with time zone, successor_projected_at timestamp with time zone, successor_family_expires_at timestamp with time zone, successor_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_decision text;
    v_sequence bigint;
    v_selector bytea;
    v_secret_hmac bytea;
    v_rotation_sequence bigint;
    v_absolute_expires_at timestamptz;
    v_retain_until timestamptz;
    v_idle_expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_successor_id IS NULL OR
       p_method NOT IN ('password_v1', 'webauthn_v1', 'totp_v1') OR
       pg_catalog.octet_length(p_purpose_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_successor_selector) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_successor_secret_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM reauthentication rotation input is invalid';
    END IF;
    v_decision := iam_refresh_decide_v2(
        p_scope_schema, p_token_id, p_family_id,
        p_expected_token_revision, p_expected_family_revision,
        p_session_id, p_expected_session_revision, p_user_id,
        p_expected_user_revision, p_expected_token_version,
        p_expected_authorization_version, p_access_mode_id,
        p_expected_access_mode_revision, p_portal_binding_id,
        p_expected_portal_binding_revision
    );
    IF v_decision IS DISTINCT FROM 'rotate' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication rotation state is stale';
    END IF;
    SELECT token.sequence, token.selector, token.secret_hmac,
           family.rotation_sequence, family.absolute_expires_at,
           family.retain_until
    INTO STRICT v_sequence, v_selector, v_secret_hmac,
         v_rotation_sequence, v_absolute_expires_at, v_retain_until
    FROM iam_refresh_tokens AS token
    JOIN iam_refresh_families AS family
      ON family.id OPERATOR(pg_catalog.=) token.family_id
    JOIN iam_sessions AS session
      ON session.id OPERATOR(pg_catalog.=) family.session_id
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
      AND family.id OPERATOR(pg_catalog.=) p_family_id
      AND session.id OPERATOR(pg_catalog.=) p_session_id;
    IF v_rotation_sequence IS DISTINCT FROM
       v_sequence OPERATOR(pg_catalog.-) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication rotation sequence is stale';
    END IF;
    v_idle_expires_at := LEAST(
        v_now OPERATOR(pg_catalog.+) INTERVAL '30 days',
        v_absolute_expires_at
    );
    UPDATE iam_refresh_tokens
    SET state = 'consumed', consumed_at = v_now, updated_at = v_now,
        revision = p_expected_token_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_token_id
      AND family_id OPERATOR(pg_catalog.=) p_family_id
      AND state OPERATOR(pg_catalog.=) 'active'
      AND revision OPERATOR(pg_catalog.=) p_expected_token_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication token CAS is stale';
    END IF;
    INSERT INTO iam_refresh_tokens (
        id, family_id, family_absolute_expires_at, parent_id, parent_sequence,
        selector, hash_key_id, secret_hmac, sequence, auth_time, acr,
        amr_password, amr_webauthn, amr_totp, amr_recovery,
        step_up_purpose_sha256, state, revision, issued_at, updated_at,
        idle_expires_at, consumed_at, revoked_at, expired_at, retain_until
    ) VALUES (
        p_successor_id, p_family_id, v_absolute_expires_at,
        p_token_id, v_sequence, p_successor_selector,
        p_successor_hash_key_id, p_successor_secret_hmac,
        v_sequence OPERATOR(pg_catalog.+) 1, v_now, 'step_up',
        p_method OPERATOR(pg_catalog.=) 'password_v1',
        p_method OPERATOR(pg_catalog.=) 'webauthn_v1',
        p_method OPERATOR(pg_catalog.=) 'totp_v1', false,
        p_purpose_sha256, 'active', 1, v_now, v_now,
        v_idle_expires_at, NULL, NULL, NULL, v_retain_until
    );
    UPDATE iam_refresh_families
    SET rotation_sequence = v_rotation_sequence OPERATOR(pg_catalog.+) 1,
        updated_at = v_now,
        revision = p_expected_family_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_family_id
      AND state OPERATOR(pg_catalog.=) 'active'
      AND revision OPERATOR(pg_catalog.=) p_expected_family_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication family CAS is stale';
    END IF;
    UPDATE iam_sessions
    SET last_seen_at = v_now, updated_at = v_now,
        revision = p_expected_session_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_session_id
      AND state OPERATOR(pg_catalog.=) 'active'
      AND revision OPERATOR(pg_catalog.=) p_expected_session_revision;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication session CAS is stale';
    END IF;
    issued_at := v_now;
    family_revision := p_expected_family_revision OPERATOR(pg_catalog.+) 1;
    session_revision := p_expected_session_revision OPERATOR(pg_catalog.+) 1;
    locator_selector := v_selector;
    locator_expected_revision := p_expected_token_revision;
    locator_revision := p_expected_token_revision OPERATOR(pg_catalog.+) 1;
    locator_state := 'consumed';
    locator_projected_at := v_now;
    locator_retain_until := v_retain_until;
    locator_source_sha256 := iam_refresh_locator_source_sha256_v1(
        p_token_id, p_family_id, v_selector, locator_revision,
        locator_state, v_secret_hmac
    );
    successor_selector := p_successor_selector;
    successor_revision := 1;
    successor_state := 'active';
    successor_issued_at := v_now;
    successor_projected_at := v_now;
    successor_family_expires_at := v_absolute_expires_at;
    successor_retain_until := v_retain_until;
    successor_source_sha256 := iam_refresh_locator_source_sha256_v1(
        p_successor_id, p_family_id, p_successor_selector,
        successor_revision, successor_state, p_successor_secret_hmac
    );
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reauthentication_rotate_active_v1(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea, p_method text, p_purpose_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_reauthentication_start_v1(name, uuid, bytea, uuid, uuid, uuid, bigint, bigint, text, uuid, text, uuid, text, bytea, bytea, bytea, bigint, bytea, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reauthentication_start_v1(p_scope_schema name, p_tenant_id uuid, p_scope_binding bytea, p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode text, p_portal_binding_id uuid, p_method text, p_authenticator_id uuid, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_purpose_sha256 bytea, p_action_policy_version bigint, p_origin_sha256 bytea, p_require_phishing_resistant boolean) RETURNS TABLE(revision bigint, issued_at timestamp with time zone, expires_at timestamp with time zone, credential_id bytea, rp_id text, user_verification_required boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_session_id uuid;
    v_authenticator_kind text;
    v_origin_policy_version bigint;
    v_rp_id_sha256 bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_challenge_id IS NULL OR p_user_id IS NULL OR p_session_id IS NULL OR
       pg_catalog.octet_length(p_scope_binding) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_challenge_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_context_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_purpose_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_origin_sha256) IS DISTINCT FROM 32 OR
       p_method NOT IN ('password_v1', 'webauthn_v1', 'totp_v1') OR
       (p_require_phishing_resistant AND
        p_method IS DISTINCT FROM 'webauthn_v1') OR
       iam_reauth_binding_sha256_v1(
           p_tenant_id, p_user_id, p_session_id, p_expected_token_version,
           p_expected_authorization_version, p_access_mode,
           p_portal_binding_id
       ) IS DISTINCT FROM p_scope_binding OR
       iam_reauth_context_sha256_v1(
           p_tenant_id, p_user_id, p_session_id, p_purpose_sha256,
           p_action_policy_version, p_method, p_origin_sha256
       ) IS DISTINCT FROM p_context_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM reauthentication start evidence is invalid';
    END IF;
    SELECT session.id INTO v_session_id
    FROM iam_sessions AS session
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) session.user_id
    JOIN iam_user_access_modes AS access
      ON access.id OPERATOR(pg_catalog.=) session.access_mode_id
     AND access.user_id OPERATOR(pg_catalog.=) principal.id
     AND access.mode OPERATOR(pg_catalog.=) session.access_mode
    JOIN iam_refresh_families AS family
      ON family.session_id OPERATOR(pg_catalog.=) session.id
    JOIN iam_refresh_tokens AS token
      ON token.family_id OPERATOR(pg_catalog.=) family.id
     AND token.state OPERATOR(pg_catalog.=) 'active'
    LEFT JOIN iam_portal_subject_bindings AS binding
      ON binding.id OPERATOR(pg_catalog.=) session.portal_binding_id
     AND binding.user_id OPERATOR(pg_catalog.=) principal.id
     AND binding.access_mode_id OPERATOR(pg_catalog.=) access.id
    WHERE session.id OPERATOR(pg_catalog.=) p_session_id
      AND principal.id OPERATOR(pg_catalog.=) p_user_id
      AND principal.status OPERATOR(pg_catalog.=) 'active'
      AND principal.identity_kind OPERATOR(pg_catalog.=) 'human'
      AND principal.token_version OPERATOR(pg_catalog.=)
          p_expected_token_version
      AND principal.authorization_version OPERATOR(pg_catalog.=)
          p_expected_authorization_version
      AND session.state OPERATOR(pg_catalog.=) 'active'
      AND session.access_mode OPERATOR(pg_catalog.=) p_access_mode
      AND session.portal_binding_id IS NOT DISTINCT FROM p_portal_binding_id
      AND access.state OPERATOR(pg_catalog.=) 'active'
      AND family.state OPERATOR(pg_catalog.=) 'active'
      AND session.absolute_expires_at OPERATOR(pg_catalog.>) v_now
      AND family.absolute_expires_at OPERATOR(pg_catalog.>) v_now
      AND token.idle_expires_at OPERATOR(pg_catalog.>) v_now
      AND ((p_access_mode OPERATOR(pg_catalog.=) 'operator_console' AND
            binding.id IS NULL) OR
           (p_access_mode OPERATOR(pg_catalog.=) 'portal' AND
            binding.state OPERATOR(pg_catalog.=) 'active'));
    IF v_session_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM reauthentication start context is stale';
    END IF;
    IF p_method OPERATOR(pg_catalog.=) 'password_v1' THEN
        IF p_authenticator_id IS NOT NULL OR NOT EXISTS (
            SELECT 1 FROM iam_password_credentials AS password
            WHERE password.user_id OPERATOR(pg_catalog.=) p_user_id
              AND password.state OPERATOR(pg_catalog.=) 'active'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM password reauthentication is unavailable';
        END IF;
    ELSIF p_method OPERATOR(pg_catalog.=) 'webauthn_v1' THEN
        SELECT authenticator.kind, webauthn.origin_policy_version,
               webauthn.rp_id_sha256, webauthn.credential_id,
               webauthn.rp_id, webauthn.uv_required
        INTO v_authenticator_kind, v_origin_policy_version,
             v_rp_id_sha256, credential_id, rp_id,
             user_verification_required
        FROM iam_authenticators AS authenticator
        JOIN iam_webauthn_credentials AS webauthn
          ON webauthn.authenticator_id OPERATOR(pg_catalog.=) authenticator.id
        WHERE authenticator.id OPERATOR(pg_catalog.=) p_authenticator_id
          AND authenticator.user_id OPERATOR(pg_catalog.=) p_user_id
          AND authenticator.kind OPERATOR(pg_catalog.=) 'webauthn_v1'
          AND authenticator.state OPERATOR(pg_catalog.=) 'active'
          AND webauthn.rp_id_sha256 OPERATOR(pg_catalog.=)
              pg_catalog.sha256(pg_catalog.convert_to(webauthn.rp_id, 'UTF8'));
        IF v_authenticator_kind IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM WebAuthn reauthentication is unavailable';
        END IF;
    ELSE
        SELECT authenticator.kind INTO v_authenticator_kind
        FROM iam_authenticators AS authenticator
        JOIN iam_totp_authenticators AS totp
          ON totp.authenticator_id OPERATOR(pg_catalog.=) authenticator.id
        WHERE authenticator.id OPERATOR(pg_catalog.=) p_authenticator_id
          AND authenticator.user_id OPERATOR(pg_catalog.=) p_user_id
          AND authenticator.kind OPERATOR(pg_catalog.=) 'totp_v1'
          AND authenticator.state OPERATOR(pg_catalog.=) 'active'
          AND totp.profile OPERATOR(pg_catalog.=) 'totp_sha256_6_30_v1'
          AND totp.verified_at IS NOT NULL;
        IF v_authenticator_kind IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'IAM TOTP reauthentication is unavailable';
        END IF;
    END IF;
    issued_at := v_now;
    expires_at := v_now OPERATOR(pg_catalog.+) INTERVAL '5 minutes';
    revision := 1;
    INSERT INTO iam_auth_challenges (
        id, user_id, session_id, authenticator_id, authenticator_kind,
        purpose, proof_kind, hash_profile, hmac_key_id, challenge_hmac,
        context_sha256, step_up_purpose_sha256, origin_policy_version,
        action_policy_version, rp_id_sha256, origin_sha256,
        user_verification_required, state, attempt_count, revision,
        issued_at, expires_at, terminal_at, purge_after, created_at, updated_at
    ) VALUES (
        p_challenge_id, p_user_id, p_session_id, p_authenticator_id,
        v_authenticator_kind, 'reauth_v1', p_method, 'hmac_sha256_v1',
        p_hmac_key_id, p_challenge_hmac, p_context_sha256,
        p_purpose_sha256, v_origin_policy_version, p_action_policy_version,
        v_rp_id_sha256, CASE WHEN p_method = 'webauthn_v1'
            THEN p_origin_sha256 END, user_verification_required,
        'pending', 0, 1, v_now, expires_at, NULL,
        expires_at OPERATOR(pg_catalog.+) INTERVAL '24 hours', v_now, v_now
    );
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reauthentication_start_v1(p_scope_schema name, p_tenant_id uuid, p_scope_binding bytea, p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode text, p_portal_binding_id uuid, p_method text, p_authenticator_id uuid, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_purpose_sha256 bytea, p_action_policy_version bigint, p_origin_sha256 bytea, p_require_phishing_resistant boolean) OWNER TO harpy_owner;

--
-- Name: iam_reconcile_restored_identity_v1(uuid, uuid, uuid, uuid, uuid, bytea, bytea, bytea, bigint, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_reconcile_restored_identity_v1(p_restore_operation_id uuid, p_environment_id uuid, p_recovery_set_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_security_epoch bytea, p_restore_receipt_sha256 bytea, p_protected_head_sha256 bytea, p_custody_generation bigint, p_custody_result_sha256 bytea, p_occurred_at timestamp with time zone) RETURNS TABLE(invalidation_counts jsonb, invalidation_sha256 bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_existing iam_restored_identity_receipts%ROWTYPE;
v_sessions bigint; v_families bigint; v_tokens bigint;
v_passwords bigint; v_authenticators bigint; v_actions bigint;
v_grants bigint; v_counts jsonb; v_digest bytea;
BEGIN
    v_sessions:=0; v_families:=0; v_tokens:=0; v_passwords:=0;
    v_authenticators:=0; v_actions:=0; v_grants:=0;
    IF p_restore_operation_id IS NULL OR p_environment_id IS NULL OR p_recovery_set_id IS NULL OR
       p_owner_user_id IS NULL OR p_anchor_id IS NULL OR pg_catalog.octet_length(p_security_epoch)<>32 OR
       pg_catalog.octet_length(p_restore_receipt_sha256)<>32 OR
       pg_catalog.octet_length(p_protected_head_sha256)<>32 OR p_custody_generation<1 OR
       pg_catalog.octet_length(p_custody_result_sha256)<>32 OR NOT EXISTS (
           SELECT 1 FROM iam_users WHERE id=p_owner_user_id AND status='active'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='restored IAM identity input is invalid';
    END IF;
    SELECT * INTO v_existing FROM iam_restored_identity_receipts
     WHERE restore_operation_id=p_restore_operation_id;
    IF FOUND THEN
        IF v_existing.environment_id<>p_environment_id OR
           v_existing.recovery_set_id<>p_recovery_set_id OR
           v_existing.owner_user_id<>p_owner_user_id OR v_existing.anchor_id<>p_anchor_id OR
           v_existing.security_epoch<>p_security_epoch OR
           v_existing.restore_receipt_sha256<>p_restore_receipt_sha256 OR
           v_existing.protected_head_sha256<>p_protected_head_sha256 OR
           v_existing.custody_generation<>p_custody_generation OR
           v_existing.custody_result_sha256<>p_custody_result_sha256 THEN
		    RETURN QUERY SELECT v_existing.invalidation_counts,
		        v_existing.invalidation_sha256,false;
		    RETURN;
        END IF;
        RETURN QUERY SELECT v_existing.invalidation_counts,v_existing.invalidation_sha256,true;
        RETURN;
    END IF;
    UPDATE iam_sessions SET state='revoked',revision=revision+1,updated_at=p_occurred_at,
        revoked_at=p_occurred_at,retain_until=GREATEST(retain_until,p_occurred_at+INTERVAL '30 days')
     WHERE state='active'; GET DIAGNOSTICS v_sessions=ROW_COUNT;
    UPDATE iam_refresh_families SET state='revoked',revoke_reason='restore_recovery',
        revision=revision+1,updated_at=p_occurred_at,revoked_at=p_occurred_at
     WHERE state='active'; GET DIAGNOSTICS v_families=ROW_COUNT;
    UPDATE iam_refresh_tokens SET state='revoked',revision=revision+1,
        updated_at=p_occurred_at,revoked_at=p_occurred_at
     WHERE state='active'; GET DIAGNOSTICS v_tokens=ROW_COUNT;
    UPDATE iam_password_credentials SET state='disabled',credential_version=credential_version+1,
        revision=revision+1,updated_at=p_occurred_at,invalidated_at=p_occurred_at
     WHERE state IN ('active','reset_required'); GET DIAGNOSTICS v_passwords=ROW_COUNT;
    UPDATE iam_authenticators SET state='renewal_required',revision=revision+1,
        updated_at=p_occurred_at,renewal_required_at=p_occurred_at
     WHERE state='active'; GET DIAGNOSTICS v_authenticators=ROW_COUNT;
    UPDATE iam_recovery_codes SET state='revoked',revision=revision+1,updated_at=p_occurred_at,
        revoked_at=p_occurred_at,purge_after=p_occurred_at+INTERVAL '30 days' WHERE state='active';
    UPDATE iam_auth_challenges SET state='cancelled',revision=revision+1,updated_at=p_occurred_at,
        terminal_at=p_occurred_at,purge_after=GREATEST(purge_after,p_occurred_at+INTERVAL '24 hours')
     WHERE state='pending';
    UPDATE iam_one_time_tokens SET state='revoked',revision=revision+1,updated_at=p_occurred_at,
        revoked_at=p_occurred_at,purge_after=GREATEST(purge_after,p_occurred_at+INTERVAL '24 hours')
     WHERE state='pending'; GET DIAGNOSTICS v_actions=ROW_COUNT;
    UPDATE iam_invitations SET state='revoked',revision=revision+1,updated_at=p_occurred_at,
        revoked_at=p_occurred_at WHERE state='pending';
    UPDATE iam_initial_admin_setups SET state='revoked',revision=revision+1,revoked_at=p_occurred_at
     WHERE state='pending';
    UPDATE iam_user_role_assignments SET state='suspended',revision=revision+1,updated_at=p_occurred_at
     WHERE state='active' AND user_id<>p_owner_user_id; GET DIAGNOSTICS v_grants=ROW_COUNT;
    UPDATE iam_user_permission_bindings SET state='revoked',revision=revision+1,
        updated_at=p_occurred_at,revoked_at=p_occurred_at
     WHERE state='active' AND user_id<>p_owner_user_id;
    UPDATE iam_role_permission_bindings AS binding SET state='revoked',revision=binding.revision+1,
        updated_at=p_occurred_at,revoked_at=p_occurred_at FROM iam_roles AS role
     WHERE binding.role_id=role.id AND binding.state='active' AND NOT role.is_protected;
    UPDATE iam_organization_permission_bindings SET state='revoked',revision=revision+1,
        updated_at=p_occurred_at,revoked_at=p_occurred_at WHERE state='active';
    UPDATE iam_capability_grants SET state='revoked',revision=revision+1,
        updated_at=p_occurred_at,revoked_at=p_occurred_at WHERE state='active';
    UPDATE iam_users SET token_version=token_version+1,authorization_version=authorization_version+1,
        revision=revision+1,updated_at=p_occurred_at;
    UPDATE iam_authorization_clock SET clock_value=clock_value+1,revision=revision+1,
        updated_at=p_occurred_at WHERE singleton;
    v_counts:=pg_catalog.jsonb_build_object('sessions',v_sessions,'refresh_families',v_families,
        'refresh_tokens',v_tokens,'passwords',v_passwords,'authenticators',v_authenticators,
        'action_tokens',v_actions,'delegable_grants',v_grants);
    v_digest:=pg_catalog.sha256(pg_catalog.convert_to(v_counts::text,'UTF8'));
    INSERT INTO iam_restored_identity_receipts VALUES (p_restore_operation_id,p_environment_id,
        p_recovery_set_id,p_owner_user_id,p_anchor_id,p_security_epoch,p_restore_receipt_sha256,
        p_protected_head_sha256,p_custody_generation,p_custody_result_sha256,v_counts,v_digest,p_occurred_at);
    RETURN QUERY SELECT v_counts,v_digest,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_reconcile_restored_identity_v1(p_restore_operation_id uuid, p_environment_id uuid, p_recovery_set_id uuid, p_owner_user_id uuid, p_anchor_id uuid, p_security_epoch bytea, p_restore_receipt_sha256 bytea, p_protected_head_sha256 bytea, p_custody_generation bigint, p_custody_result_sha256 bytea, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_recovery_codes_issue_v1(name, uuid, uuid, bytea, uuid, uuid, text, jsonb, text, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_recovery_codes_issue_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_user_id uuid, p_display_label text, p_codes jsonb, p_hmac_key_id text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_count integer;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF pg_catalog.jsonb_typeof(p_codes) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    v_count := pg_catalog.jsonb_array_length(p_codes);
    IF p_authenticator_id IS NULL OR p_user_id IS NULL OR
       v_count NOT BETWEEN 8 AND 16 OR
       p_hmac_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema::text) OR
       EXISTS (
          SELECT 1
          FROM pg_catalog.jsonb_array_elements(p_codes) AS code(value)
          WHERE pg_catalog.jsonb_typeof(code.value) <> 'object'
             OR (SELECT pg_catalog.count(*) FROM
                    pg_catalog.jsonb_object_keys(code.value)) <> 2
             OR NOT (code.value ? 'id' AND code.value ? 'hmac_sha256')
             OR code.value->>'id' !~
                '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
             OR code.value->>'hmac_sha256' !~ '^[0-9a-f]{64}$'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.recovery_codes.issue',
        p_request_sha256, p_authenticator_id
    );
    IF FOUND THEN RETURN; END IF;
    IF p_user_id <> p_actor_id OR NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    PERFORM 1 FROM iam_users AS subject
    WHERE subject.id = p_user_id AND subject.status = 'active' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '23503'; END IF;
    UPDATE iam_recovery_codes SET state = 'revoked', revoked_at = v_now,
        purge_after = v_now + INTERVAL '30 days',
        revision = revision + 1, updated_at = v_now
    WHERE user_id = p_user_id AND state = 'active';
    UPDATE iam_authenticators SET state = 'retired', retired_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = p_user_id AND kind = 'recovery_set_v1'
      AND state <> 'retired';
    INSERT INTO iam_authenticators (
        id, user_id, kind, display_label, state, revision,
        created_at, updated_at, activated_at
    ) VALUES (
        p_authenticator_id, p_user_id, 'recovery_set_v1', p_display_label,
        'active', 1, v_now, v_now, v_now
    );
    INSERT INTO iam_recovery_codes (
        id, authenticator_id, user_id, authenticator_kind, position,
        hash_profile, hmac_key_id, code_hmac, state, revision,
        created_at, updated_at
    )
    SELECT (code.value->>'id')::uuid, p_authenticator_id, p_user_id,
        'recovery_set_v1', code.code_ordinal::smallint,
        'hmac_sha256_v1', p_hmac_key_id,
        pg_catalog.decode(code.value->>'hmac_sha256', 'hex'),
        'active', 1, v_now, v_now
    FROM pg_catalog.jsonb_array_elements(p_codes)
      WITH ORDINALITY AS code(value, code_ordinal);
    UPDATE iam_sessions SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = p_user_id AND state = 'active';
    UPDATE iam_refresh_families SET state = 'revoked',
        revoke_reason = 'recovery_codes_rotated', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = p_user_id AND state = 'active';
    UPDATE iam_refresh_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE family_id IN (
        SELECT id FROM iam_refresh_families WHERE user_id = p_user_id
    ) AND state = 'active';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.recovery_codes.issue', p_request_sha256,
        p_authenticator_id, p_user_id, 1, 'actor_tenant', p_actor_id,
        'recovery_set', true, true
    ) AS result;
    RETURN QUERY SELECT p_authenticator_id, p_user_id, 1::bigint,
        v_token_version, v_authorization_version, false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_recovery_codes_issue_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_user_id uuid, p_display_label text, p_codes jsonb, p_hmac_key_id text, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_recovery_codes_list_v1(name, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_recovery_codes_list_v1(p_scope_schema name, p_user_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(authenticator_id uuid, authenticator_revision bigint, code_id uuid, code_position smallint, state text, created_at timestamp with time zone, consumed_at timestamp with time zone, revoked_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_user_id IS NULL OR p_user_id <> p_actor_id OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY
    SELECT authenticator.id, authenticator.revision, code.id,
        code.position, code.state, code.created_at,
        code.consumed_at, code.revoked_at
    FROM iam_authenticators AS authenticator
    JOIN iam_recovery_codes AS code
      ON code.authenticator_id = authenticator.id
     AND code.user_id = authenticator.user_id
    WHERE authenticator.user_id = p_user_id
      AND authenticator.kind = 'recovery_set_v1'
      AND authenticator.state <> 'retired'
    ORDER BY code.position ASC;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_recovery_codes_list_v1(p_scope_schema name, p_user_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_recovery_consume_v1(name, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_recovery_consume_v1(p_scope_schema name, p_recovery_code_id uuid, p_expected_revision bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_code_state text;
    v_code_revision bigint;
    v_authenticator_id uuid;
    v_authenticator_state text;
    v_authenticator_revision bigint;
    v_user_id uuid;
    v_user_revision bigint;
    v_token_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM recovery consume scope is invalid';
    END IF;
    SELECT code.state, code.revision, code.authenticator_id,
           authenticator.state, authenticator.revision, code.user_id,
           principal.revision, principal.token_version
    INTO v_code_state, v_code_revision, v_authenticator_id,
         v_authenticator_state, v_authenticator_revision, v_user_id,
         v_user_revision, v_token_version
    FROM iam_recovery_codes AS code
    JOIN iam_authenticators AS authenticator
      ON authenticator.id OPERATOR(pg_catalog.=) code.authenticator_id
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) code.user_id
    WHERE code.id OPERATOR(pg_catalog.=) p_recovery_code_id
    FOR UPDATE OF principal, authenticator, code;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM recovery code is unknown';
    END IF;
    IF v_code_state IS DISTINCT FROM 'active' OR
       v_code_revision IS DISTINCT FROM p_expected_revision OR
       v_authenticator_state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM recovery consume CAS is stale';
    END IF;
    UPDATE iam_recovery_codes
    SET state = 'consumed', consumed_at = v_now,
        purge_after = v_now OPERATOR(pg_catalog.+) INTERVAL '30 days',
        updated_at = v_now,
        revision = v_code_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_recovery_code_id;
    UPDATE iam_authenticators
    SET state = 'renewal_required', renewal_required_at = v_now,
        updated_at = v_now,
        revision = v_authenticator_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) v_authenticator_id;
    UPDATE iam_users
    SET token_version = v_token_version OPERATOR(pg_catalog.+) 1,
        updated_at = v_now,
        revision = v_user_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) v_user_id;
    RETURN v_token_version OPERATOR(pg_catalog.+) 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_recovery_consume_v1(p_scope_schema name, p_recovery_code_id uuid, p_expected_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_recovery_consume_v2(name, bytea, text, bytea, uuid, bigint, uuid, bigint, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_recovery_consume_v2(p_scope_schema name, p_scope_binding bytea, p_hmac_key_id text, p_code_hmac bytea, p_code_id uuid, p_expected_code_revision bigint, p_authenticator_id uuid, p_expected_authenticator_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_code_revision bigint;
    v_authenticator_revision bigint;
    v_user_revision bigint;
    v_token_version bigint;
    v_code_state text;
    v_authenticator_state text;
    v_user_status text;
    v_identity_kind text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.octet_length(p_scope_binding) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_code_hmac) IS DISTINCT FROM 32 OR
       p_scope_binding IS DISTINCT FROM p_code_hmac THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM recovery consume scope is invalid';
    END IF;
    SELECT code.revision, authenticator.revision, principal.revision,
           principal.token_version, code.state, authenticator.state,
           principal.status, principal.identity_kind
    INTO v_code_revision, v_authenticator_revision, v_user_revision,
         v_token_version, v_code_state, v_authenticator_state,
         v_user_status, v_identity_kind
    FROM iam_recovery_codes AS code
    JOIN iam_authenticators AS authenticator
      ON authenticator.id OPERATOR(pg_catalog.=) code.authenticator_id
     AND authenticator.user_id OPERATOR(pg_catalog.=) code.user_id
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) code.user_id
    WHERE code.id OPERATOR(pg_catalog.=) p_code_id
      AND code.authenticator_id OPERATOR(pg_catalog.=) p_authenticator_id
      AND code.user_id OPERATOR(pg_catalog.=) p_user_id
      AND code.hmac_key_id OPERATOR(pg_catalog.=) p_hmac_key_id
      AND code.code_hmac OPERATOR(pg_catalog.=) p_code_hmac
    FOR UPDATE OF code, authenticator, principal;
    IF NOT FOUND OR v_code_revision IS DISTINCT FROM
           p_expected_code_revision OR
       v_authenticator_revision IS DISTINCT FROM
           p_expected_authenticator_revision OR
       v_user_revision IS DISTINCT FROM p_expected_user_revision OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_code_state IS DISTINCT FROM 'active' OR
       v_authenticator_state IS DISTINCT FROM 'active' OR
       v_user_status IS DISTINCT FROM 'active' OR
       v_identity_kind IS DISTINCT FROM 'human' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM recovery consume CAS is stale';
    END IF;
    RETURN iam_recovery_consume_v1(
        p_scope_schema, p_code_id, p_expected_code_revision
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_recovery_consume_v2(p_scope_schema name, p_scope_binding bytea, p_hmac_key_id text, p_code_hmac bytea, p_code_id uuid, p_expected_code_revision bigint, p_authenticator_id uuid, p_expected_authenticator_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_recovery_credential_v1(name, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_recovery_credential_v1(p_scope_schema name, p_scope_binding bytea, p_hmac_key_id text, p_code_hmac bytea) RETURNS TABLE(code_id uuid, authenticator_id uuid, user_id uuid, code_revision bigint, authenticator_revision bigint, user_revision bigint, token_version bigint, code_state text, authenticator_state text, user_status text, identity_kind text, hmac_key_id text, code_hmac bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_rows bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.octet_length(p_scope_binding) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_code_hmac) IS DISTINCT FROM 32 OR
       p_scope_binding IS DISTINCT FROM p_code_hmac OR
       p_hmac_key_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM recovery credential scope is invalid';
    END IF;
    RETURN QUERY
    SELECT code.id, code.authenticator_id, code.user_id, code.revision,
           authenticator.revision, principal.revision,
           principal.token_version, code.state, authenticator.state,
           principal.status, principal.identity_kind, code.hmac_key_id,
           code.code_hmac
    FROM iam_recovery_codes AS code
    JOIN iam_authenticators AS authenticator
      ON authenticator.id OPERATOR(pg_catalog.=) code.authenticator_id
     AND authenticator.user_id OPERATOR(pg_catalog.=) code.user_id
     AND authenticator.kind OPERATOR(pg_catalog.=) 'recovery_set_v1'
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) code.user_id
    WHERE code.hmac_key_id OPERATOR(pg_catalog.=) p_hmac_key_id
      AND code.code_hmac OPERATOR(pg_catalog.=) p_code_hmac;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows OPERATOR(pg_catalog.>) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '21000',
            MESSAGE = 'IAM recovery credential is ambiguous';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_recovery_credential_v1(p_scope_schema name, p_scope_binding bytea, p_hmac_key_id text, p_code_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_refresh_credential_v1(name, uuid, uuid, bytea, bigint, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_credential_v1(p_scope_schema name, p_source_token_id uuid, p_source_family_id uuid, p_selector bytea, p_source_revision bigint, p_source_sha256 bytea) RETURNS TABLE(token_id uuid, token_revision bigint, token_state text, family_id uuid, family_revision bigint, family_state text, session_id uuid, session_revision bigint, session_state text, user_id uuid, user_revision bigint, user_status text, identity_kind text, token_version bigint, authorization_version bigint, access_mode_id uuid, access_mode text, access_mode_state text, access_mode_revision bigint, portal_binding_id uuid, portal_binding_state text, portal_binding_revision bigint, hash_key_id text, secret_hmac bytea, sequence bigint, auth_time timestamp with time zone, acr text, amr_password boolean, amr_webauthn boolean, amr_totp boolean, amr_recovery boolean, step_up_purpose_sha256 bytea, idle_expires_at timestamp with time zone, absolute_expires_at timestamp with time zone, retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_source_token_id IS NULL OR p_source_family_id IS NULL OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       p_source_revision OPERATOR(pg_catalog.<=) 0 OR
       pg_catalog.octet_length(p_source_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh credential scope is invalid';
    END IF;
    RETURN QUERY
    SELECT token.id, token.revision, token.state,
           family.id, family.revision, family.state,
           session.id, session.revision, session.state,
           principal.id, principal.revision, principal.status,
           principal.identity_kind, principal.token_version,
           principal.authorization_version, access.id, session.access_mode,
           access.state, access.revision, session.portal_binding_id,
           binding.state, binding.revision, token.hash_key_id, token.secret_hmac,
           token.sequence, token.auth_time, token.acr,
           token.amr_password, token.amr_webauthn, token.amr_totp,
           token.amr_recovery, token.step_up_purpose_sha256,
           token.idle_expires_at, family.absolute_expires_at,
           token.retain_until
    FROM iam_refresh_tokens AS token
    JOIN iam_refresh_families AS family
      ON family.id OPERATOR(pg_catalog.=) token.family_id
    JOIN iam_sessions AS session
      ON session.id OPERATOR(pg_catalog.=) family.session_id
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) family.user_id
    JOIN iam_user_access_modes AS access
      ON access.id OPERATOR(pg_catalog.=) session.access_mode_id
     AND access.user_id OPERATOR(pg_catalog.=) principal.id
     AND access.mode OPERATOR(pg_catalog.=) session.access_mode
    LEFT JOIN iam_portal_subject_bindings AS binding
      ON binding.id OPERATOR(pg_catalog.=) session.portal_binding_id
     AND binding.user_id OPERATOR(pg_catalog.=) principal.id
     AND binding.access_mode_id OPERATOR(pg_catalog.=) session.access_mode_id
    WHERE token.id OPERATOR(pg_catalog.=) p_source_token_id
      AND token.family_id OPERATOR(pg_catalog.=) p_source_family_id
      AND family.id OPERATOR(pg_catalog.=) p_source_family_id
      AND token.selector OPERATOR(pg_catalog.=) p_selector
      AND token.revision OPERATOR(pg_catalog.=) p_source_revision
      AND token.secret_hmac OPERATOR(pg_catalog.=) p_source_sha256
      AND family.user_id OPERATOR(pg_catalog.=) principal.id;
END;
$$;


