--
-- Name: iam_refresh_credential_v3(name, uuid, uuid, bytea, bigint, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_credential_v3(p_scope_schema name, p_source_token_id uuid, p_source_family_id uuid, p_selector bytea, p_source_revision bigint, p_source_sha256 bytea) RETURNS TABLE(token_id uuid, token_revision bigint, token_state text, family_id uuid, family_revision bigint, family_state text, session_id uuid, session_revision bigint, session_state text, user_id uuid, user_revision bigint, user_status text, identity_kind text, token_version bigint, authorization_version bigint, access_mode_id uuid, access_mode text, access_mode_state text, access_mode_revision bigint, portal_binding_id uuid, portal_binding_state text, portal_binding_revision bigint, hash_key_id text, secret_hmac bytea, sequence bigint, auth_time timestamp with time zone, acr text, amr_password boolean, amr_webauthn boolean, amr_totp boolean, amr_recovery boolean, step_up_purpose_sha256 bytea, idle_expires_at timestamp with time zone, absolute_expires_at timestamp with time zone, retain_until timestamp with time zone, platform_authorization_clock bigint, security_epoch bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT credential.*, context.platform_clock, token.security_epoch
    FROM iam_refresh_credential_v2(
        p_scope_schema, p_source_token_id, p_source_family_id,
        p_selector, p_source_revision, p_source_sha256
    ) AS credential
    JOIN iam_refresh_tokens AS token ON token.id = credential.token_id
    JOIN iam_refresh_families AS family ON family.id = credential.family_id
    JOIN iam_sessions AS session ON session.id = credential.session_id
    CROSS JOIN iam_platform_session_context_v1(
        p_scope_schema, credential.user_id, credential.token_version,
        credential.authorization_version
    ) AS context
    WHERE token.security_epoch = family.security_epoch
      AND family.security_epoch = session.security_epoch
      AND session.security_epoch = iam_security_epoch_current_v1(p_scope_schema);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_credential_v3(p_scope_schema name, p_source_token_id uuid, p_source_family_id uuid, p_selector bytea, p_source_revision bigint, p_source_sha256 bytea) OWNER TO harpy_owner;

--
-- Name: iam_refresh_decide_v2(name, uuid, uuid, bigint, bigint, uuid, bigint, uuid, bigint, bigint, bigint, uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_decide_v2(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_token_state text;
    v_token_revision bigint;
    v_token_sequence bigint;
    v_token_issued_at timestamptz;
    v_token_updated_at timestamptz;
    v_idle_expires_at timestamptz;
    v_family_state text;
    v_family_revision bigint;
    v_rotation_sequence bigint;
    v_family_expires_at timestamptz;
    v_family_updated_at timestamptz;
    v_session_state text;
    v_session_revision bigint;
    v_session_expires_at timestamptz;
    v_session_updated_at timestamptz;
    v_access_mode text;
    v_portal_binding_id uuid;
    v_user_status text;
    v_identity_kind text;
    v_user_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_user_updated_at timestamptz;
    v_access_state text;
    v_access_revision bigint;
    v_access_updated_at timestamptz;
    v_binding_state text;
    v_binding_revision bigint;
    v_binding_updated_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_token_id IS NULL OR p_family_id IS NULL OR p_session_id IS NULL OR
       p_user_id IS NULL OR p_access_mode_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh decision scope is invalid';
    END IF;
    SELECT token.state, token.revision, token.sequence, token.issued_at,
           token.updated_at, token.idle_expires_at,
           family.state, family.revision, family.rotation_sequence,
           family.absolute_expires_at, family.updated_at,
           session.state, session.revision, session.absolute_expires_at,
           session.updated_at, session.access_mode, session.portal_binding_id,
           principal.status, principal.identity_kind, principal.revision,
           principal.token_version, principal.authorization_version,
           principal.updated_at, access.state, access.revision, access.updated_at
    INTO v_token_state, v_token_revision, v_token_sequence, v_token_issued_at,
         v_token_updated_at, v_idle_expires_at,
         v_family_state, v_family_revision, v_rotation_sequence,
         v_family_expires_at, v_family_updated_at,
         v_session_state, v_session_revision, v_session_expires_at,
         v_session_updated_at, v_access_mode, v_portal_binding_id,
         v_user_status, v_identity_kind, v_user_revision,
         v_token_version, v_authorization_version, v_user_updated_at,
         v_access_state, v_access_revision, v_access_updated_at
    FROM iam_refresh_tokens AS token
    JOIN iam_refresh_families AS family
      ON family.id OPERATOR(pg_catalog.=) token.family_id
    JOIN iam_sessions AS session
      ON session.id OPERATOR(pg_catalog.=) family.session_id
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) family.user_id
    JOIN iam_user_access_modes AS access
      ON access.id OPERATOR(pg_catalog.=) session.access_mode_id
     AND access.user_id OPERATOR(pg_catalog.=) principal.id
     AND access.mode OPERATOR(pg_catalog.=) session.access_mode
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
      AND family.id OPERATOR(pg_catalog.=) p_family_id
      AND session.id OPERATOR(pg_catalog.=) p_session_id
      AND principal.id OPERATOR(pg_catalog.=) p_user_id
      AND access.id OPERATOR(pg_catalog.=) p_access_mode_id
    FOR UPDATE OF principal, access, session, family, token;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM refresh decision subject is unavailable';
    END IF;
    IF v_portal_binding_id IS NOT NULL THEN
        SELECT binding.state, binding.revision, binding.updated_at
        INTO v_binding_state, v_binding_revision, v_binding_updated_at
        FROM iam_portal_subject_bindings AS binding
        WHERE binding.id OPERATOR(pg_catalog.=) v_portal_binding_id
          AND binding.user_id OPERATOR(pg_catalog.=) p_user_id
          AND binding.access_mode_id OPERATOR(pg_catalog.=) p_access_mode_id
        FOR UPDATE;
    END IF;
    IF v_token_revision IS DISTINCT FROM p_expected_token_revision OR
       v_family_revision IS DISTINCT FROM p_expected_family_revision OR
       v_session_revision IS DISTINCT FROM p_expected_session_revision OR
       v_user_revision IS DISTINCT FROM p_expected_user_revision OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version OR
       v_access_revision IS DISTINCT FROM p_expected_access_mode_revision OR
       v_portal_binding_id IS DISTINCT FROM p_portal_binding_id OR
       v_binding_revision IS DISTINCT FROM p_expected_portal_binding_revision OR
       v_now OPERATOR(pg_catalog.<) GREATEST(
           v_token_updated_at, v_family_updated_at, v_session_updated_at,
           v_user_updated_at, v_access_updated_at, v_binding_updated_at
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM refresh decision CAS is stale';
    END IF;
    IF v_token_state IS NOT DISTINCT FROM 'consumed' THEN
        IF v_family_state IS NOT DISTINCT FROM 'active' THEN
            RETURN 'reused';
        END IF;
        RETURN 'rejected';
    END IF;
    IF v_token_state IS DISTINCT FROM 'active' OR
       v_family_state IS DISTINCT FROM 'active' OR
       v_session_state IS DISTINCT FROM 'active' OR
       v_user_status IS DISTINCT FROM 'active' OR
       v_identity_kind IS DISTINCT FROM 'human' OR
       v_access_state IS DISTINCT FROM 'active' OR NOT (
           (v_access_mode IS NOT DISTINCT FROM 'operator_console' AND
            v_portal_binding_id IS NULL) OR
           (v_access_mode IS NOT DISTINCT FROM 'portal' AND
            v_binding_state IS NOT DISTINCT FROM 'active')
       ) THEN
        RETURN 'rejected';
    END IF;
    IF v_now OPERATOR(pg_catalog.>=) v_idle_expires_at OR
       v_now OPERATOR(pg_catalog.>=) v_family_expires_at OR
       v_now OPERATOR(pg_catalog.>=) v_session_expires_at THEN
        RETURN 'expired';
    END IF;
    IF v_now OPERATOR(pg_catalog.<=) v_token_issued_at OR
       v_rotation_sequence IS DISTINCT FROM
           v_token_sequence OPERATOR(pg_catalog.-) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM refresh decision sequence is stale';
    END IF;
    RETURN 'rotate';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_decide_v2(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_refresh_expire_v2(name, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_expire_v2(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_session_id uuid) RETURNS TABLE(locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_selector bytea;
    v_secret_hmac bytea;
    v_revision bigint;
    v_idle_expires_at timestamptz;
    v_updated_at timestamptz;
    v_retain_until timestamptz;
    v_family_expires_at timestamptz;
    v_session_expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh expiry scope is invalid';
    END IF;
    SELECT token.selector, token.secret_hmac, token.revision,
           token.idle_expires_at, token.updated_at, token.retain_until,
           family.absolute_expires_at, session.absolute_expires_at
    INTO v_selector, v_secret_hmac, v_revision, v_idle_expires_at,
         v_updated_at, v_retain_until, v_family_expires_at,
         v_session_expires_at
    FROM iam_refresh_tokens AS token
    JOIN iam_refresh_families AS family
      ON family.id OPERATOR(pg_catalog.=) token.family_id
    JOIN iam_sessions AS session
      ON session.id OPERATOR(pg_catalog.=) family.session_id
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
      AND family.id OPERATOR(pg_catalog.=) p_family_id
      AND session.id OPERATOR(pg_catalog.=) p_session_id;
    IF NOT FOUND OR v_now OPERATOR(pg_catalog.<) v_idle_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM refresh expiry state is stale';
    END IF;
    UPDATE iam_refresh_tokens
    SET state = 'expired', expired_at = v_idle_expires_at,
        updated_at = GREATEST(v_updated_at, v_now),
        revision = v_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_token_id
      AND state OPERATOR(pg_catalog.=) 'active';
    locator_selector := v_selector;
    locator_expected_revision := v_revision;
    locator_revision := v_revision OPERATOR(pg_catalog.+) 1;
    locator_source_sha256 := v_secret_hmac;
    locator_state := 'expired';
    locator_projected_at := GREATEST(v_updated_at, v_now);
    locator_retain_until := v_retain_until;
    IF v_now OPERATOR(pg_catalog.>=) v_family_expires_at THEN
        UPDATE iam_refresh_families
        SET state = 'expired', expired_at = absolute_expires_at,
            updated_at = GREATEST(updated_at, v_now),
            revision = revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_family_id
          AND state OPERATOR(pg_catalog.=) 'active';
    END IF;
    IF v_now OPERATOR(pg_catalog.>=) v_session_expires_at THEN
        UPDATE iam_sessions
        SET state = 'expired', expired_at = absolute_expires_at,
            updated_at = GREATEST(updated_at, v_now),
            revision = revision OPERATOR(pg_catalog.+) 1
        WHERE id OPERATOR(pg_catalog.=) p_session_id
          AND state OPERATOR(pg_catalog.=) 'active';
    END IF;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_expire_v2(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_session_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_refresh_locator_source_sha256_v1(uuid, uuid, bytea, bigint, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_locator_source_sha256_v1(p_token_id uuid, p_family_id uuid, p_selector bytea, p_revision bigint, p_state text, p_secret_hmac bytea) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF p_token_id IS NOT DISTINCT FROM
           '00000000-0000-0000-0000-000000000000'::uuid OR
       p_family_id IS NOT DISTINCT FROM
           '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       p_revision OPERATOR(pg_catalog.<=) 0 OR
       p_state NOT IN ('active', 'consumed', 'revoked', 'expired') OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM refresh locator source input is invalid';
    END IF;
    RETURN pg_catalog.sha256(
        pg_catalog.convert_to(
            'harpy:iam-refresh-locator-source:v1', 'UTF8'
        ) OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
          OPERATOR(pg_catalog.||) pg_catalog.uuid_send(p_token_id)
          OPERATOR(pg_catalog.||) pg_catalog.uuid_send(p_family_id)
          OPERATOR(pg_catalog.||) p_selector
          OPERATOR(pg_catalog.||) pg_catalog.int8send(p_revision)
          OPERATOR(pg_catalog.||) pg_catalog.convert_to(p_state, 'UTF8')
          OPERATOR(pg_catalog.||) pg_catalog.decode('00', 'hex')
          OPERATOR(pg_catalog.||) p_secret_hmac
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_locator_source_sha256_v1(p_token_id uuid, p_family_id uuid, p_selector bytea, p_revision bigint, p_state text, p_secret_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_refresh_reuse_v2(name, uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_reuse_v2(p_scope_schema name, p_family_id uuid, p_session_id uuid, p_user_id uuid) RETURNS TABLE(locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_successor_id uuid;
    v_selector bytea;
    v_secret_hmac bytea;
    v_revision bigint;
    v_updated_at timestamptz;
    v_retain_until timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh reuse scope is invalid';
    END IF;
    SELECT token.id, token.selector, token.secret_hmac, token.revision,
           token.updated_at, token.retain_until
    INTO v_successor_id, v_selector, v_secret_hmac, v_revision,
         v_updated_at, v_retain_until
    FROM iam_refresh_tokens AS token
    WHERE token.family_id OPERATOR(pg_catalog.=) p_family_id
      AND token.state OPERATOR(pg_catalog.=) 'active'
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM refresh reuse successor is unavailable';
    END IF;
    UPDATE iam_refresh_tokens
        SET state = 'revoked',
            revoked_at = GREATEST(v_updated_at, v_now),
            updated_at = GREATEST(v_updated_at, v_now),
            revision = v_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) v_successor_id;
    locator_selector := v_selector;
    locator_expected_revision := v_revision;
    locator_revision := v_revision OPERATOR(pg_catalog.+) 1;
    locator_source_sha256 := v_secret_hmac;
    locator_state := 'revoked';
    locator_projected_at := GREATEST(v_updated_at, v_now);
    locator_retain_until := v_retain_until;
    UPDATE iam_refresh_families
    SET state = 'compromised', revoke_reason = 'reuse_detected',
        compromised_at = GREATEST(updated_at, v_now),
        updated_at = GREATEST(updated_at, v_now),
        revision = revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_family_id
      AND user_id OPERATOR(pg_catalog.=) p_user_id
      AND session_id OPERATOR(pg_catalog.=) p_session_id
      AND state OPERATOR(pg_catalog.=) 'active';
    UPDATE iam_sessions
    SET state = 'revoked',
        revoked_at = GREATEST(updated_at, v_now),
        updated_at = GREATEST(updated_at, v_now),
        revision = revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_session_id
      AND user_id OPERATOR(pg_catalog.=) p_user_id
      AND state OPERATOR(pg_catalog.=) 'active';
    UPDATE iam_users
    SET token_version = token_version OPERATOR(pg_catalog.+) 1,
        updated_at = GREATEST(updated_at, v_now),
        revision = revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_user_id;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_reuse_v2(p_scope_schema name, p_family_id uuid, p_session_id uuid, p_user_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_refresh_rotate_active_v2(name, uuid, uuid, uuid, uuid, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_rotate_active_v2(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_session_id uuid, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) RETURNS TABLE(issued_at timestamp with time zone, locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone, successor_selector bytea, successor_revision bigint, successor_source_sha256 bytea, successor_state text, successor_issued_at timestamp with time zone, successor_projected_at timestamp with time zone, successor_family_expires_at timestamp with time zone, successor_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_token_revision bigint;
    v_sequence bigint;
    v_selector bytea;
    v_secret_hmac bytea;
    v_auth_time timestamptz;
    v_acr text;
    v_amr_password boolean;
    v_amr_webauthn boolean;
    v_amr_totp boolean;
    v_amr_recovery boolean;
    v_step_up_sha256 bytea;
    v_family_revision bigint;
    v_rotation_sequence bigint;
    v_absolute_expires_at timestamptz;
    v_session_revision bigint;
    v_retain_until timestamptz;
    v_idle_expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_successor_id IS NULL OR
       pg_catalog.octet_length(p_successor_selector) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_successor_secret_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM active refresh rotation input is invalid';
    END IF;
    SELECT token.revision, token.sequence, token.selector,
           token.secret_hmac, token.auth_time, token.acr,
           token.amr_password, token.amr_webauthn, token.amr_totp,
           token.amr_recovery, token.step_up_purpose_sha256,
           family.revision, family.rotation_sequence,
           family.absolute_expires_at, family.retain_until,
           session.revision
    INTO v_token_revision, v_sequence, v_selector, v_secret_hmac,
         v_auth_time, v_acr, v_amr_password, v_amr_webauthn,
         v_amr_totp, v_amr_recovery, v_step_up_sha256,
         v_family_revision, v_rotation_sequence, v_absolute_expires_at,
         v_retain_until, v_session_revision
    FROM iam_refresh_tokens AS token
    JOIN iam_refresh_families AS family
      ON family.id OPERATOR(pg_catalog.=) token.family_id
    JOIN iam_sessions AS session
      ON session.id OPERATOR(pg_catalog.=) family.session_id
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
      AND family.id OPERATOR(pg_catalog.=) p_family_id
      AND session.id OPERATOR(pg_catalog.=) p_session_id
      AND token.state OPERATOR(pg_catalog.=) 'active'
      AND family.state OPERATOR(pg_catalog.=) 'active'
      AND session.state OPERATOR(pg_catalog.=) 'active';
    IF NOT FOUND OR v_rotation_sequence IS DISTINCT FROM
           v_sequence OPERATOR(pg_catalog.-) 1 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM active refresh rotation state is stale';
    END IF;
    v_idle_expires_at := LEAST(
        v_now OPERATOR(pg_catalog.+) INTERVAL '30 days',
        v_absolute_expires_at
    );
    UPDATE iam_refresh_tokens
    SET state = 'consumed', consumed_at = v_now, updated_at = v_now,
        revision = v_token_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_token_id;
    INSERT INTO iam_refresh_tokens (
        id, family_id, family_absolute_expires_at, parent_id, parent_sequence,
        selector, hash_key_id, secret_hmac, sequence, auth_time, acr,
        amr_password, amr_webauthn, amr_totp, amr_recovery,
        step_up_purpose_sha256, state, revision, issued_at, updated_at,
        idle_expires_at, consumed_at, revoked_at, expired_at, retain_until
    ) VALUES (
        p_successor_id, p_family_id, v_absolute_expires_at,
        p_token_id, v_sequence, p_successor_selector,
        p_successor_hash_key_id, p_successor_secret_hmac,
        v_sequence OPERATOR(pg_catalog.+) 1, v_auth_time, v_acr,
        v_amr_password, v_amr_webauthn, v_amr_totp, v_amr_recovery,
        v_step_up_sha256, 'active', 1, v_now, v_now,
        v_idle_expires_at, NULL, NULL, NULL, v_retain_until
    );
    UPDATE iam_refresh_families
    SET rotation_sequence = v_rotation_sequence OPERATOR(pg_catalog.+) 1,
        updated_at = v_now,
        revision = v_family_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_family_id;
    UPDATE iam_sessions
    SET last_seen_at = v_now, updated_at = v_now,
        revision = v_session_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_session_id;
    issued_at := v_now;
    locator_selector := v_selector;
    locator_expected_revision := v_token_revision;
    locator_revision := v_token_revision OPERATOR(pg_catalog.+) 1;
    locator_source_sha256 := v_secret_hmac;
    locator_state := 'consumed';
    locator_projected_at := v_now;
    locator_retain_until := v_retain_until;
    successor_selector := p_successor_selector;
    successor_revision := 1;
    successor_source_sha256 := p_successor_secret_hmac;
    successor_state := 'active';
    successor_issued_at := v_now;
    successor_projected_at := v_now;
    successor_family_expires_at := v_absolute_expires_at;
    successor_retain_until := v_retain_until;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_rotate_active_v2(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_session_id uuid, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_refresh_rotate_v1(name, uuid, bigint, uuid, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_rotate_v1(p_scope_schema name, p_token_id uuid, p_expected_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_token_state text;
    v_token_revision bigint;
    v_sequence bigint;
    v_parent_issued_at timestamptz;
    v_family_id uuid;
    v_family_state text;
    v_family_revision bigint;
    v_family_expires_at timestamptz;
    v_session_id uuid;
    v_session_state text;
    v_session_revision bigint;
    v_user_id uuid;
    v_user_revision bigint;
    v_idle_expires_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh rotation scope is invalid';
    END IF;
    SELECT token.state, token.revision, token.sequence, token.issued_at,
           family.id, family.state, family.revision,
           family.absolute_expires_at, family.session_id,
           session.state, session.revision, family.user_id, principal.revision
    INTO v_token_state, v_token_revision, v_sequence, v_parent_issued_at,
         v_family_id, v_family_state, v_family_revision,
         v_family_expires_at, v_session_id,
         v_session_state, v_session_revision, v_user_id, v_user_revision
    FROM iam_refresh_tokens AS token
    JOIN iam_refresh_families AS family
      ON family.id OPERATOR(pg_catalog.=) token.family_id
    JOIN iam_sessions AS session
      ON session.id OPERATOR(pg_catalog.=) family.session_id
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) family.user_id
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
    FOR UPDATE OF principal, session, family, token;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'IAM refresh token is unknown';
    END IF;
    IF v_token_state IS DISTINCT FROM 'active' THEN
        IF v_token_state IS NOT DISTINCT FROM 'consumed' AND
           v_family_state IS NOT DISTINCT FROM 'active' THEN
            UPDATE iam_refresh_tokens
            SET state = 'revoked',
                revoked_at = CASE
                    WHEN updated_at OPERATOR(pg_catalog.>) v_now
                        THEN updated_at ELSE v_now
                END,
                updated_at = CASE
                    WHEN updated_at OPERATOR(pg_catalog.>) v_now
                        THEN updated_at ELSE v_now
                END,
                revision = revision OPERATOR(pg_catalog.+) 1
            WHERE family_id OPERATOR(pg_catalog.=) v_family_id
              AND state OPERATOR(pg_catalog.=) 'active';
            UPDATE iam_refresh_families
            SET state = 'compromised', revoke_reason = 'reuse_detected',
                compromised_at = CASE
                    WHEN updated_at OPERATOR(pg_catalog.>) v_now
                        THEN updated_at ELSE v_now
                END,
                updated_at = CASE
                    WHEN updated_at OPERATOR(pg_catalog.>) v_now
                        THEN updated_at ELSE v_now
                END,
                revision = v_family_revision OPERATOR(pg_catalog.+) 1
            WHERE id OPERATOR(pg_catalog.=) v_family_id;
            IF v_session_state IS NOT DISTINCT FROM 'active' THEN
                UPDATE iam_sessions
                SET state = 'revoked',
                    revoked_at = CASE
                        WHEN updated_at OPERATOR(pg_catalog.>) v_now
                            THEN updated_at ELSE v_now
                    END,
                    updated_at = CASE
                        WHEN updated_at OPERATOR(pg_catalog.>) v_now
                            THEN updated_at ELSE v_now
                    END,
                    revision = v_session_revision OPERATOR(pg_catalog.+) 1
                WHERE id OPERATOR(pg_catalog.=) v_session_id;
            END IF;
            UPDATE iam_users
            SET token_version = token_version OPERATOR(pg_catalog.+) 1,
                updated_at = CASE
                    WHEN updated_at OPERATOR(pg_catalog.>) v_now
                        THEN updated_at ELSE v_now
                END,
                revision = v_user_revision OPERATOR(pg_catalog.+) 1
            WHERE id OPERATOR(pg_catalog.=) v_user_id;
        END IF;
        IF v_token_state IS NOT DISTINCT FROM 'expired' THEN
            RETURN 'expired';
        END IF;
        RETURN 'reused';
    END IF;
    IF v_token_revision IS DISTINCT FROM p_expected_revision OR
       v_family_state IS DISTINCT FROM 'active' OR
       v_session_state IS DISTINCT FROM 'active' OR
       v_now OPERATOR(pg_catalog.<=) v_parent_issued_at OR
       v_now OPERATOR(pg_catalog.>=) v_family_expires_at THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM refresh rotation CAS is stale';
    END IF;
    v_idle_expires_at := v_now OPERATOR(pg_catalog.+) INTERVAL '30 days';
    IF v_idle_expires_at OPERATOR(pg_catalog.>) v_family_expires_at THEN
        v_idle_expires_at := v_family_expires_at;
    END IF;
    UPDATE iam_refresh_tokens
    SET state = 'consumed', consumed_at = v_now, updated_at = v_now,
        revision = v_token_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_token_id;
    INSERT INTO iam_refresh_tokens (
        id, family_id, family_absolute_expires_at, parent_id, parent_sequence,
        selector, hash_key_id, secret_hmac, sequence, auth_time, acr,
        amr_password, amr_webauthn, amr_totp, amr_recovery,
        step_up_purpose_sha256, state, revision, issued_at, updated_at,
        idle_expires_at, consumed_at, revoked_at, expired_at, retain_until
    )
    SELECT p_successor_id, token.family_id, token.family_absolute_expires_at,
           token.id, token.sequence, p_successor_selector,
           p_successor_hash_key_id, p_successor_secret_hmac,
           token.sequence OPERATOR(pg_catalog.+) 1,
           token.auth_time, token.acr, token.amr_password,
           token.amr_webauthn, token.amr_totp, token.amr_recovery,
           token.step_up_purpose_sha256, 'active', 1, v_now, v_now,
           v_idle_expires_at, NULL, NULL, NULL, token.retain_until
    FROM iam_refresh_tokens AS token
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id;
    UPDATE iam_refresh_families
    SET rotation_sequence = v_sequence OPERATOR(pg_catalog.+) 1,
        updated_at = v_now,
        revision = v_family_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) v_family_id;
    UPDATE iam_sessions
    SET last_seen_at = v_now, updated_at = v_now,
        revision = v_session_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) v_session_id;
    RETURN 'rotated';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_rotate_v1(p_scope_schema name, p_token_id uuid, p_expected_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_refresh_rotate_v2(name, uuid, uuid, bigint, bigint, uuid, bigint, uuid, bigint, bigint, bigint, uuid, bigint, uuid, bigint, uuid, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_rotate_v2(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) RETURNS TABLE(outcome text, issued_at timestamp with time zone, locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone, successor_selector bytea, successor_revision bigint, successor_source_sha256 bytea, successor_state text, successor_issued_at timestamp with time zone, successor_projected_at timestamp with time zone, successor_family_expires_at timestamp with time zone, successor_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_decision text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_successor_id IS NULL OR
       pg_catalog.octet_length(p_successor_selector) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_successor_secret_hmac) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM refresh rotation scope is invalid';
    END IF;
    v_decision := iam_refresh_decide_v2(
        p_scope_schema, p_token_id, p_family_id,
        p_expected_token_revision, p_expected_family_revision,
        p_session_id, p_expected_session_revision,
        p_user_id, p_expected_user_revision, p_expected_token_version,
        p_expected_authorization_version, p_access_mode_id,
        p_expected_access_mode_revision, p_portal_binding_id,
        p_expected_portal_binding_revision
    );
    IF v_decision IS NOT DISTINCT FROM 'reused' THEN
        SELECT reuse.locator_selector, reuse.locator_expected_revision,
               reuse.locator_revision, reuse.locator_source_sha256,
               reuse.locator_state, reuse.locator_projected_at,
               reuse.locator_retain_until
        INTO locator_selector, locator_expected_revision, locator_revision,
             locator_source_sha256, locator_state, locator_projected_at,
             locator_retain_until
        FROM iam_refresh_reuse_v2(
            p_scope_schema, p_family_id, p_session_id, p_user_id
        ) AS reuse;
        outcome := 'reused';
        RETURN NEXT;
        RETURN;
    END IF;
    IF v_decision IS NOT DISTINCT FROM 'expired' THEN
        SELECT expiry.locator_selector, expiry.locator_expected_revision,
               expiry.locator_revision, expiry.locator_source_sha256,
               expiry.locator_state, expiry.locator_projected_at,
               expiry.locator_retain_until
        INTO locator_selector, locator_expected_revision, locator_revision,
             locator_source_sha256, locator_state, locator_projected_at,
             locator_retain_until
        FROM iam_refresh_expire_v2(
            p_scope_schema, p_token_id, p_family_id, p_session_id
        ) AS expiry;
        outcome := 'expired';
        RETURN NEXT;
        RETURN;
    END IF;
    IF v_decision IS DISTINCT FROM 'rotate' THEN
        outcome := 'rejected';
        RETURN NEXT;
        RETURN;
    END IF;
    SELECT active.issued_at, active.locator_selector,
           active.locator_expected_revision, active.locator_revision,
           active.locator_source_sha256, active.locator_state,
           active.locator_projected_at, active.locator_retain_until,
           active.successor_selector, active.successor_revision,
           active.successor_source_sha256, active.successor_state,
           active.successor_issued_at, active.successor_projected_at,
           active.successor_family_expires_at, active.successor_retain_until
    INTO issued_at, locator_selector, locator_expected_revision,
         locator_revision, locator_source_sha256, locator_state,
         locator_projected_at, locator_retain_until, successor_selector,
         successor_revision, successor_source_sha256, successor_state,
         successor_issued_at, successor_projected_at,
         successor_family_expires_at, successor_retain_until
    FROM iam_refresh_rotate_active_v2(
        p_scope_schema, p_token_id, p_family_id, p_session_id,
        p_successor_id, p_successor_selector, p_successor_hash_key_id,
        p_successor_secret_hmac
    ) AS active;
    outcome := 'rotated';
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_rotate_v2(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_refresh_rotate_v3(name, uuid, uuid, bigint, bigint, uuid, bigint, uuid, bigint, bigint, bigint, uuid, bigint, uuid, bigint, uuid, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_rotate_v3(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) RETURNS TABLE(outcome text, issued_at timestamp with time zone, locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone, successor_selector bytea, successor_revision bigint, successor_source_sha256 bytea, successor_state text, successor_issued_at timestamp with time zone, successor_projected_at timestamp with time zone, successor_family_expires_at timestamp with time zone, successor_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    SELECT rotated.outcome, rotated.issued_at, rotated.locator_selector,
           rotated.locator_expected_revision, rotated.locator_revision,
           rotated.locator_source_sha256, rotated.locator_state,
           rotated.locator_projected_at, rotated.locator_retain_until,
           rotated.successor_selector, rotated.successor_revision,
           rotated.successor_source_sha256, rotated.successor_state,
           rotated.successor_issued_at, rotated.successor_projected_at,
           rotated.successor_family_expires_at,
           rotated.successor_retain_until
    INTO STRICT outcome, issued_at, locator_selector,
         locator_expected_revision, locator_revision, locator_source_sha256,
         locator_state, locator_projected_at, locator_retain_until,
         successor_selector, successor_revision, successor_source_sha256,
         successor_state, successor_issued_at, successor_projected_at,
         successor_family_expires_at, successor_retain_until
    FROM iam_refresh_rotate_v2(
        p_scope_schema, p_token_id, p_family_id,
        p_expected_token_revision, p_expected_family_revision,
        p_session_id, p_expected_session_revision,
        p_user_id, p_expected_user_revision, p_expected_token_version,
        p_expected_authorization_version, p_access_mode_id,
        p_expected_access_mode_revision, p_portal_binding_id,
        p_expected_portal_binding_revision, p_successor_id,
        p_successor_selector, p_successor_hash_key_id,
        p_successor_secret_hmac
    ) AS rotated;
    IF locator_selector IS NOT NULL THEN
        SELECT iam_refresh_locator_source_sha256_v1(
            token.id, token.family_id, token.selector,
            token.revision, token.state, token.secret_hmac
        ) INTO STRICT locator_source_sha256
        FROM iam_refresh_tokens AS token
        WHERE token.selector OPERATOR(pg_catalog.=) locator_selector
          AND token.revision OPERATOR(pg_catalog.=) locator_revision
          AND token.state OPERATOR(pg_catalog.=) locator_state;
    END IF;
    IF successor_selector IS NOT NULL THEN
        SELECT iam_refresh_locator_source_sha256_v1(
            token.id, token.family_id, token.selector,
            token.revision, token.state, token.secret_hmac
        ) INTO STRICT successor_source_sha256
        FROM iam_refresh_tokens AS token
        WHERE token.selector OPERATOR(pg_catalog.=) successor_selector
          AND token.revision OPERATOR(pg_catalog.=) successor_revision
          AND token.state OPERATOR(pg_catalog.=) successor_state;
    END IF;
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_refresh_rotate_v3(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_refresh_rotate_v4(name, uuid, uuid, bigint, bigint, uuid, bigint, uuid, bigint, bigint, bigint, uuid, bigint, uuid, bigint, uuid, bytea, text, bytea, bigint, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_refresh_rotate_v4(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_successor_id uuid, p_successor_selector bytea, p_successor_hash_key_id text, p_successor_secret_hmac bytea, p_expected_platform_clock bigint, p_expected_security_epoch bytea) RETURNS TABLE(outcome text, issued_at timestamp with time zone, locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone, successor_selector bytea, successor_revision bigint, successor_source_sha256 bytea, successor_state text, successor_issued_at timestamp with time zone, successor_projected_at timestamp with time zone, successor_family_expires_at timestamp with time zone, successor_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_platform_clock bigint;
BEGIN
    IF p_expected_platform_clock < 0 OR
       pg_catalog.octet_length(p_expected_security_epoch) IS DISTINCT FROM 32 OR
       p_expected_security_epoch IS DISTINCT FROM
           iam_security_epoch_current_v1(p_scope_schema) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM refresh security evidence is stale';
    END IF;
    SELECT context.platform_clock INTO STRICT v_platform_clock
    FROM iam_platform_session_context_v1(
        p_scope_schema, p_user_id, p_expected_token_version,
        p_expected_authorization_version
    ) AS context;
    IF v_platform_clock IS DISTINCT FROM p_expected_platform_clock OR
       NOT EXISTS (
           SELECT 1 FROM iam_refresh_tokens AS token
           JOIN iam_refresh_families AS family ON family.id = token.family_id
           JOIN iam_sessions AS session ON session.id = family.session_id
           WHERE token.id = p_token_id AND family.id = p_family_id
             AND session.id = p_session_id
             AND token.security_epoch = p_expected_security_epoch
             AND family.security_epoch = p_expected_security_epoch
             AND session.security_epoch = p_expected_security_epoch
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM refresh security evidence is stale';
    END IF;
    RETURN QUERY SELECT * FROM iam_refresh_rotate_v3(
        p_scope_schema, p_token_id, p_family_id,
        p_expected_token_revision, p_expected_family_revision,
        p_session_id, p_expected_session_revision, p_user_id,
        p_expected_user_revision, p_expected_token_version,
