CREATE FUNCTION __tenant_schema__.iam_rest_query_actor_versions_v1(p_scope_schema name, p_actor_id uuid) RETURNS TABLE(token_version bigint, authorization_version bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_actor_id IS NULL THEN
