--
-- Name: iam_security_epoch_assert_v1(name, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_security_epoch_assert_v1(p_scope_schema name, p_expected_security_epoch bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.octet_length(p_expected_security_epoch) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM security epoch assertion input is invalid';
    END IF;
    IF p_expected_security_epoch IS DISTINCT FROM
       iam_security_epoch_current_v1(p_scope_schema) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM security epoch evidence is stale';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_security_epoch_assert_v1(p_scope_schema name, p_expected_security_epoch bytea) OWNER TO harpy_owner;

--
-- Name: iam_security_epoch_current_v1(name); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_security_epoch_current_v1(p_scope_schema name) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_epoch bytea;
BEGIN
    IF p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM security epoch scope is invalid';
    END IF;
    SELECT platform.iam_security_epoch_for_tenant_v1(identity.tenant_id)
    INTO v_epoch
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton;
    IF pg_catalog.octet_length(v_epoch) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM security epoch is unavailable';
    END IF;
    RETURN v_epoch;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_security_epoch_current_v1(p_scope_schema name) OWNER TO harpy_owner;

--
-- Name: iam_self_profile_read_v1(name, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_self_profile_read_v1(p_scope_schema name, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, email text, status text, revision bigint, created_at timestamp with time zone, updated_at timestamp with time zone, roles jsonb, organizations jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_actor_id IS NULL OR p_expected_token_version < 1 OR
       p_expected_authorization_version < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM self profile read scope is invalid';
    END IF;
    PERFORM 1 FROM iam_users AS actor
    WHERE actor.id = p_actor_id
      AND actor.status = 'active'
      AND actor.token_version = p_expected_token_version
      AND actor.authorization_version = p_expected_authorization_version;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM self profile read authority is denied';
    END IF;
    RETURN QUERY
    SELECT actor.id, identifier.display_value, actor.status, actor.revision,
           actor.created_at, actor.updated_at,
           COALESCE((
               SELECT pg_catalog.jsonb_agg(
                   pg_catalog.jsonb_build_object(
                       'id', role.id, 'name', role.name
                   ) ORDER BY role.id
               )
               FROM iam_user_role_assignments AS assignment
               JOIN iam_roles AS role ON role.id = assignment.role_id
               WHERE assignment.user_id = actor.id
                 AND assignment.state = 'active'
                 AND role.status = 'active'
           ), '[]'::jsonb),
           COALESCE((
               SELECT pg_catalog.jsonb_agg(
                   pg_catalog.jsonb_build_object(
                       'id', organization.id,
                       'name', organization.name,
                       'slug', organization.slug
                   ) ORDER BY organization.id
               )
               FROM iam_organization_memberships AS membership
               JOIN iam_organizations AS organization
                 ON organization.id = membership.organization_id
               WHERE membership.user_id = actor.id
                 AND membership.state = 'active'
                 AND organization.status = 'active'
           ), '[]'::jsonb)
    FROM iam_users AS actor
    JOIN iam_user_identifiers AS identifier
      ON identifier.user_id = actor.id
     AND identifier.kind = 'email_v1'
     AND identifier.state = 'active'
    WHERE actor.id = p_actor_id
      AND actor.status = 'active'
      AND actor.token_version = p_expected_token_version
      AND actor.authorization_version = p_expected_authorization_version;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P5404',
            MESSAGE = 'IAM self profile is unavailable';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_self_profile_read_v1(p_scope_schema name, p_actor_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_self_profile_update_v1(name, uuid, bytea, uuid, uuid, uuid, bytea, bytea, bigint, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_self_profile_update_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_source_schema_id uuid, p_target_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_expected_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_values jsonb;
    v_current_schema_id uuid;
    v_current_revision bigint;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_clock bigint;
    v_revision bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_operation_id IS NULL OR p_actor_id IS NULL OR
       p_expected_source_schema_id IS NULL OR p_target_schema_id IS NULL OR
       p_expected_revision < 1 OR p_expected_token_version < 1 OR
       p_expected_authorization_version < 1 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_profile_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_profile_document) > 1048576 OR
       pg_catalog.sha256(p_profile_document) IS DISTINCT FROM p_profile_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM self profile update input is invalid';
    END IF;
    SELECT actor.profile_schema_version_id, actor.revision
    INTO v_current_schema_id, v_current_revision
    FROM iam_users AS actor
    WHERE actor.id = p_actor_id
      AND actor.status = 'active'
      AND actor.token_version = p_expected_token_version
      AND actor.authorization_version = p_expected_authorization_version
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM self profile update authority is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_id,
         v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id = p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.identity.user.update' OR
           v_receipt_request IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_actor_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM self profile operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    IF v_current_schema_id IS DISTINCT FROM p_expected_source_schema_id OR
       v_current_revision IS DISTINCT FROM p_expected_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM self profile compare-and-swap failed';
    END IF;
    v_values := iam_identity_profile_assert_v1(
        'user', p_target_schema_id, p_profile_document, p_profile_sha256
    );
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1,
        revision = revision + 1,
        updated_at = v_now
    WHERE singleton
    RETURNING clock_value INTO v_clock;
    UPDATE iam_users
    SET profile_schema_version_id = p_target_schema_id,
        profile_values = v_values,
        profile_sha256 = p_profile_sha256,
        revision = revision + 1,
        updated_at = v_now
    WHERE id = p_actor_id AND revision = p_expected_revision
    RETURNING revision INTO v_revision;
    IF v_clock IS NULL OR v_revision IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM self profile update compare-and-swap failed';
    END IF;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.identity.user.update', p_request_sha256,
        v_clock, 'iam.identity.user.update.succeeded', p_actor_id, v_revision,
        p_profile_sha256, v_now
    );
    RETURN QUERY SELECT p_actor_id, v_revision, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_self_profile_update_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_expected_source_schema_id uuid, p_target_schema_id uuid, p_profile_document bytea, p_profile_sha256 bytea, p_expected_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

