--
-- Name: iam_service_principal_actor_assert_v1(name, uuid, uuid, bigint, bigint, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_service_principal_actor_assert_v1(p_scope_schema name, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_state text;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM service principal command scope is invalid';
    END IF;
    IF p_actor_id IS NULL OR p_manage_permission_id IS NULL OR
       p_expected_token_version < 1 OR p_expected_authorization_version < 1 OR
       pg_catalog.octet_length(p_purpose_sha256) IS DISTINCT FROM 32 OR
       p_auth_time IS NULL OR p_auth_time > v_now OR
       p_auth_time < v_now - INTERVAL '10 minutes' OR
       NOT (p_amr_password OR p_amr_webauthn OR p_amr_totp) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM service principal command evidence is invalid';
    END IF;
    SELECT actor.status, actor.token_version, actor.authorization_version
    INTO v_state, v_token_version, v_authorization_version
    FROM iam_users AS actor
    WHERE actor.id OPERATOR(pg_catalog.=) p_actor_id
    FOR UPDATE;
    IF NOT FOUND OR v_state IS DISTINCT FROM 'active' OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_authorization_version IS DISTINCT FROM p_expected_authorization_version OR
       NOT iam_user_has_permission_v1(p_actor_id, p_manage_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM service principal command authority is denied';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_service_principal_actor_assert_v1(p_scope_schema name, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_service_principal_create_v1(name, uuid, bytea, uuid, text, text, uuid, uuid, bigint, bigint, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_service_principal_create_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_principal_id uuid, p_principal_key text, p_display_name text, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_clock bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF p_operation_id IS NULL OR p_principal_id IS NULL OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM service principal create input is invalid';
    END IF;
    IF NOT iam_service_principal_actor_assert_v1(
        p_scope_schema, p_actor_id, p_manage_permission_id,
        p_expected_token_version, p_expected_authorization_version,
        p_purpose_sha256, p_auth_time,
        p_amr_password, p_amr_webauthn, p_amr_totp
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM service principal command authority is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_id,
         v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM 'iam.service_principal.create' OR
           v_receipt_request IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_principal_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM service principal operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1,
        revision = revision + 1,
        updated_at = v_now
    WHERE singleton
    RETURNING clock_value INTO v_clock;
    IF v_clock IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM authorization clock is unavailable';
    END IF;
    INSERT INTO iam_service_principals (
        id, principal_key, kind, display_name, state,
        authorization_version, revision, created_at, updated_at
    ) VALUES (
        p_principal_id, p_principal_key, 'workflow', p_display_name, 'active',
        v_clock, 1, v_now, v_now
    );
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, 'iam.service_principal.create', p_request_sha256,
        v_clock, 'iam.service_principal.created', p_principal_id, 1,
        p_request_sha256, v_now
    );
    RETURN QUERY SELECT p_principal_id, 1::bigint, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_service_principal_create_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_principal_id uuid, p_principal_key text, p_display_name text, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_service_principal_state_v1(name, uuid, bytea, uuid, bigint, text, uuid, uuid, bigint, bigint, bytea, timestamp with time zone, boolean, boolean, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_service_principal_state_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_principal_id uuid, p_expected_revision bigint, p_target_state text, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) RETURNS TABLE(result_id uuid, result_revision bigint, authorization_clock bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz;
    v_state text;
    v_revision bigint;
    v_command text;
    v_code text;
    v_receipt_command text;
    v_receipt_request bytea;
    v_receipt_id uuid;
    v_receipt_revision bigint;
    v_receipt_clock bigint;
    v_clock bigint;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    IF p_operation_id IS NULL OR p_principal_id IS NULL OR
       p_expected_revision < 1 OR
       p_target_state NOT IN ('active', 'disabled', 'retired') OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM service principal state input is invalid';
    END IF;
    v_command := CASE p_target_state
        WHEN 'active' THEN 'iam.service_principal.enable'
        WHEN 'disabled' THEN 'iam.service_principal.disable'
        ELSE 'iam.service_principal.retire'
    END;
    v_code := CASE p_target_state
        WHEN 'active' THEN 'iam.service_principal.enabled'
        WHEN 'disabled' THEN 'iam.service_principal.disabled'
        ELSE 'iam.service_principal.retired'
    END;
    IF NOT iam_service_principal_actor_assert_v1(
        p_scope_schema, p_actor_id, p_manage_permission_id,
        p_expected_token_version, p_expected_authorization_version,
        p_purpose_sha256, p_auth_time,
        p_amr_password, p_amr_webauthn, p_amr_totp
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM service principal command authority is denied';
    END IF;
    SELECT receipt.command_key, receipt.request_sha256, receipt.result_id,
           receipt.result_revision, receipt.clock_value
    INTO v_receipt_command, v_receipt_request, v_receipt_id,
         v_receipt_revision, v_receipt_clock
    FROM iam_authorization_operation_receipts AS receipt
    WHERE receipt.operation_id OPERATOR(pg_catalog.=) p_operation_id;
    IF FOUND THEN
        IF v_receipt_command IS DISTINCT FROM v_command OR
           v_receipt_request IS DISTINCT FROM p_request_sha256 OR
           v_receipt_id IS DISTINCT FROM p_principal_id THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'IAM service principal operation identity was reused';
        END IF;
        RETURN QUERY SELECT v_receipt_id, v_receipt_revision,
            v_receipt_clock, true;
        RETURN;
    END IF;
    SELECT principal.state, principal.revision
    INTO v_state, v_revision
    FROM iam_service_principals AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_principal_id
    FOR UPDATE;
    IF NOT FOUND OR v_revision IS DISTINCT FROM p_expected_revision OR
       NOT (
           (v_state = 'active' AND p_target_state IN ('disabled', 'retired')) OR
           (v_state = 'disabled' AND p_target_state IN ('active', 'retired'))
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM service principal state CAS is stale';
    END IF;
    IF p_target_state = 'retired' AND EXISTS (
        SELECT 1 FROM iam_capability_grants AS grant_head
        WHERE grant_head.principal_id = p_principal_id
          AND grant_head.state = 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23503',
            MESSAGE = 'IAM service principal has active capability grants';
    END IF;
    UPDATE iam_authorization_clock
    SET clock_value = clock_value + 1,
        revision = revision + 1,
        updated_at = v_now
    WHERE singleton
    RETURNING clock_value INTO v_clock;
    UPDATE iam_service_principals
    SET state = p_target_state,
        authorization_version = v_clock,
        revision = v_revision + 1,
        updated_at = v_now,
        disabled_at = CASE
            WHEN p_target_state = 'active' THEN NULL
            WHEN p_target_state = 'disabled' THEN v_now
            ELSE disabled_at
        END,
        retired_at = CASE WHEN p_target_state = 'retired' THEN v_now ELSE NULL END
    WHERE id = p_principal_id;
    INSERT INTO iam_authorization_operation_receipts (
        operation_id, command_key, request_sha256, clock_value,
        result_code, result_id, result_revision, result_sha256, created_at
    ) VALUES (
        p_operation_id, v_command, p_request_sha256, v_clock,
        v_code, p_principal_id, v_revision + 1, p_request_sha256, v_now
    );
    RETURN QUERY SELECT p_principal_id, v_revision + 1, v_clock, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_service_principal_state_v1(p_scope_schema name, p_operation_id uuid, p_request_sha256 bytea, p_principal_id uuid, p_expected_revision bigint, p_target_state text, p_actor_id uuid, p_manage_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_purpose_sha256 bytea, p_auth_time timestamp with time zone, p_amr_password boolean, p_amr_webauthn boolean, p_amr_totp boolean) OWNER TO harpy_owner;

--
-- Name: iam_session_issue_v1(name, uuid, bigint, bigint, bigint, uuid, text, bigint, uuid, bigint, uuid, text, text, text, text, bytea, uuid, uuid, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_session_issue_v1(p_scope_schema name, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_access_mode text, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_session_id uuid, p_device_kind text, p_browser_family text, p_os_family text, p_ip_hmac_key_id text, p_ip_hmac bytea, p_family_id uuid, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea) RETURNS TABLE(session_revision bigint, family_revision bigint, token_revision bigint, issued_at timestamp with time zone, idle_expires_at timestamp with time zone, absolute_expires_at timestamp with time zone, retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_absolute_expires_at timestamptz;
    v_idle_expires_at timestamptz;
    v_token_retain_until timestamptz;
    v_user_status text;
    v_identity_kind text;
    v_user_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_user_updated_at timestamptz;
    v_access_state text;
    v_access_revision bigint;
    v_access_updated_at timestamptz;
    v_binding_id uuid;
    v_binding_state text;
    v_binding_revision bigint;
    v_binding_updated_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM session issue scope is invalid';
    END IF;
    IF p_user_id IS NOT DISTINCT FROM
           '00000000-0000-0000-0000-000000000000'::uuid OR
       p_access_mode_id IS NOT DISTINCT FROM
           '00000000-0000-0000-0000-000000000000'::uuid OR
       p_session_id IS NOT DISTINCT FROM
           '00000000-0000-0000-0000-000000000000'::uuid OR
       p_family_id IS NOT DISTINCT FROM
           '00000000-0000-0000-0000-000000000000'::uuid OR
       p_token_id IS NOT DISTINCT FROM
           '00000000-0000-0000-0000-000000000000'::uuid OR
       pg_catalog.octet_length(p_ip_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_selector) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_secret_hmac) IS DISTINCT FROM 32 OR
       NOT (
           (p_access_mode IS NOT DISTINCT FROM 'operator_console' AND
            p_portal_binding_id IS NULL AND
            p_expected_portal_binding_revision IS NULL) OR
           (p_access_mode IS NOT DISTINCT FROM 'portal' AND
            p_portal_binding_id IS NOT NULL AND
            p_expected_portal_binding_revision OPERATOR(pg_catalog.>) 0)
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM session issue input is invalid';
    END IF;
    SELECT principal.status, principal.identity_kind, principal.revision,
           principal.token_version, principal.authorization_version,
           principal.updated_at
    INTO v_user_status, v_identity_kind, v_user_revision,
         v_token_version, v_authorization_version, v_user_updated_at
    FROM iam_users AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_user_id
    FOR UPDATE;
    SELECT access.state, access.revision, access.updated_at
    INTO v_access_state, v_access_revision, v_access_updated_at
    FROM iam_user_access_modes AS access
    WHERE access.id OPERATOR(pg_catalog.=) p_access_mode_id
      AND access.user_id OPERATOR(pg_catalog.=) p_user_id
      AND access.mode OPERATOR(pg_catalog.=) p_access_mode
    FOR UPDATE;
    IF p_access_mode IS NOT DISTINCT FROM 'portal' THEN
        SELECT binding.id, binding.state, binding.revision, binding.updated_at
        INTO v_binding_id, v_binding_state, v_binding_revision,
             v_binding_updated_at
        FROM iam_portal_subject_bindings AS binding
        WHERE binding.id OPERATOR(pg_catalog.=) p_portal_binding_id
          AND binding.user_id OPERATOR(pg_catalog.=) p_user_id
          AND binding.access_mode_id OPERATOR(pg_catalog.=) p_access_mode_id
        FOR UPDATE;
    END IF;
    IF v_user_status IS NULL OR v_access_state IS NULL OR
       v_user_status IS DISTINCT FROM 'active' OR
       v_identity_kind IS DISTINCT FROM 'human' OR
       v_access_state IS DISTINCT FROM 'active' OR
       v_user_revision IS DISTINCT FROM p_expected_user_revision OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       v_authorization_version IS DISTINCT FROM
           p_expected_authorization_version OR
       v_access_revision IS DISTINCT FROM p_expected_access_mode_revision OR
       (p_access_mode IS NOT DISTINCT FROM 'portal' AND (
           v_binding_id IS NULL OR v_binding_state IS DISTINCT FROM 'active' OR
           v_binding_revision IS DISTINCT FROM
               p_expected_portal_binding_revision
       )) OR
       v_now OPERATOR(pg_catalog.<) v_user_updated_at OR
       v_now OPERATOR(pg_catalog.<) v_access_updated_at OR
       (v_binding_id IS NOT NULL AND
        v_now OPERATOR(pg_catalog.<) v_binding_updated_at) THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM session issue CAS is stale';
    END IF;
    v_absolute_expires_at := v_now OPERATOR(pg_catalog.+) INTERVAL '90 days';
    v_idle_expires_at := v_now OPERATOR(pg_catalog.+) INTERVAL '30 days';
    v_token_retain_until :=
        v_absolute_expires_at OPERATOR(pg_catalog.+) INTERVAL '24 hours';
    INSERT INTO iam_sessions (
        id, user_id, access_mode_id, access_mode, portal_binding_id, state,
        device_kind, browser_family, os_family, ip_hmac_key_id, ip_hmac,
        revision, created_at, updated_at, last_seen_at, absolute_expires_at,
        revoked_at, expired_at, retain_until
    ) VALUES (
        p_session_id, p_user_id, p_access_mode_id, p_access_mode,
        p_portal_binding_id, 'active', p_device_kind, p_browser_family,
        p_os_family, p_ip_hmac_key_id, p_ip_hmac, 1, v_now, v_now, v_now,
        v_absolute_expires_at, NULL, NULL,
        v_absolute_expires_at OPERATOR(pg_catalog.+) INTERVAL '30 days'
    );
    INSERT INTO iam_refresh_families (
        id, user_id, session_id, state, rotation_sequence, revoke_reason,
        revision, created_at, updated_at, absolute_expires_at,
        revoked_at, compromised_at, expired_at, retain_until
    ) VALUES (
        p_family_id, p_user_id, p_session_id, 'active', 0, NULL,
        1, v_now, v_now, v_absolute_expires_at,
        NULL, NULL, NULL, v_token_retain_until
    );
    INSERT INTO iam_refresh_tokens (
        id, family_id, family_absolute_expires_at, parent_id, parent_sequence,
        selector, hash_key_id, secret_hmac, sequence, auth_time, acr,
        amr_password, amr_webauthn, amr_totp, amr_recovery,
        step_up_purpose_sha256, state, revision, issued_at, updated_at,
        idle_expires_at, consumed_at, revoked_at, expired_at, retain_until
    ) VALUES (
        p_token_id, p_family_id, v_absolute_expires_at, NULL, NULL,
        p_selector, p_hash_key_id, p_secret_hmac, 1, v_now, 'login',
        true, false, false, false, NULL, 'active', 1, v_now, v_now,
        v_idle_expires_at, NULL, NULL, NULL, v_token_retain_until
    );
    RETURN QUERY SELECT 1::bigint, 1::bigint, 1::bigint, v_now,
        v_idle_expires_at, v_absolute_expires_at, v_token_retain_until;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_session_issue_v1(p_scope_schema name, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_access_mode text, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_session_id uuid, p_device_kind text, p_browser_family text, p_os_family text, p_ip_hmac_key_id text, p_ip_hmac bytea, p_family_id uuid, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_session_issue_v2(name, uuid, bigint, bigint, bigint, uuid, text, bigint, uuid, bigint, uuid, text, text, text, text, bytea, uuid, uuid, bytea, text, bytea); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_session_issue_v2(p_scope_schema name, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_access_mode text, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_session_id uuid, p_device_kind text, p_browser_family text, p_os_family text, p_ip_hmac_key_id text, p_ip_hmac bytea, p_family_id uuid, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea) RETURNS TABLE(session_revision bigint, family_revision bigint, token_revision bigint, issued_at timestamp with time zone, idle_expires_at timestamp with time zone, absolute_expires_at timestamp with time zone, retain_until timestamp with time zone, platform_authorization_clock bigint, security_epoch bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    SELECT issued.session_revision, issued.family_revision,
           issued.token_revision, issued.issued_at,
           issued.idle_expires_at, issued.absolute_expires_at,
           issued.retain_until
    INTO STRICT session_revision, family_revision, token_revision,
         issued_at, idle_expires_at, absolute_expires_at, retain_until
    FROM iam_session_issue_v1(
        p_scope_schema, p_user_id, p_expected_user_revision,
        p_expected_token_version, p_expected_authorization_version,
        p_access_mode_id, p_access_mode, p_expected_access_mode_revision,
        p_portal_binding_id, p_expected_portal_binding_revision, p_session_id,
        p_device_kind, p_browser_family, p_os_family, p_ip_hmac_key_id,
        p_ip_hmac, p_family_id, p_token_id, p_selector, p_hash_key_id,
        p_secret_hmac
    ) AS issued;
    SELECT context.platform_clock INTO STRICT platform_authorization_clock
    FROM iam_platform_session_context_v1(
        p_scope_schema, p_user_id, p_expected_token_version,
        p_expected_authorization_version
    ) AS context;
    SELECT session.security_epoch INTO STRICT security_epoch
    FROM iam_sessions AS session
    JOIN iam_refresh_families AS family ON family.session_id = session.id
    JOIN iam_refresh_tokens AS token ON token.family_id = family.id
    WHERE session.id = p_session_id AND family.id = p_family_id
      AND token.id = p_token_id
      AND session.security_epoch = family.security_epoch
      AND family.security_epoch = token.security_epoch
      AND token.security_epoch = iam_security_epoch_current_v1(p_scope_schema);
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_session_issue_v2(p_scope_schema name, p_user_id uuid, p_expected_user_revision bigint, p_expected_token_version bigint, p_expected_authorization_version bigint, p_access_mode_id uuid, p_access_mode text, p_expected_access_mode_revision bigint, p_portal_binding_id uuid, p_expected_portal_binding_revision bigint, p_session_id uuid, p_device_kind text, p_browser_family text, p_os_family text, p_ip_hmac_key_id text, p_ip_hmac bytea, p_family_id uuid, p_token_id uuid, p_selector bytea, p_hash_key_id text, p_secret_hmac bytea) OWNER TO harpy_owner;

--
-- Name: iam_session_list_v1(name, uuid, uuid, uuid, bigint, bigint, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_session_list_v1(p_scope_schema name, p_user_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_limit integer, p_after_last_seen_at timestamp with time zone, p_after_id uuid) RETURNS TABLE(session_id uuid, access_mode text, portal_binding_id uuid, device_kind text, browser_family text, os_family text, revision bigint, created_at timestamp with time zone, last_seen_at timestamp with time zone, absolute_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_user_id IS NULL OR p_user_id <> p_actor_id OR
       p_limit NOT BETWEEN 1 AND 100 OR
       ((p_after_last_seen_at IS NULL) <> (p_after_id IS NULL)) OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY
    SELECT session.id, session.access_mode, session.portal_binding_id,
        session.device_kind, session.browser_family, session.os_family,
        session.revision, session.created_at, session.last_seen_at,
        session.absolute_expires_at
    FROM iam_sessions AS session
    WHERE session.user_id = p_user_id AND session.state = 'active'
      AND session.absolute_expires_at > pg_catalog.transaction_timestamp()
      AND (p_after_last_seen_at IS NULL OR
          (session.last_seen_at, session.id) <
          (p_after_last_seen_at, p_after_id))
    ORDER BY session.last_seen_at DESC, session.id DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_session_list_v1(p_scope_schema name, p_user_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_limit integer, p_after_last_seen_at timestamp with time zone, p_after_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_session_revoke_all_v1(name, uuid, uuid, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_session_revoke_all_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_actor_id IS NULL OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.session.revoke_all',
        p_request_sha256, p_actor_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT subject.revision INTO v_user_revision
    FROM iam_users AS subject
    WHERE subject.id = p_actor_id AND subject.status = 'active' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '23503'; END IF;
    UPDATE iam_sessions SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = p_actor_id AND state = 'active';
    UPDATE iam_refresh_families SET state = 'revoked',
        revoke_reason = 'all_sessions_revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE user_id = p_actor_id AND state = 'active';
    UPDATE iam_refresh_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE family_id IN (
        SELECT id FROM iam_refresh_families WHERE user_id = p_actor_id
    ) AND state = 'active';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.session.revoke_all', p_request_sha256,
        p_actor_id, p_actor_id, v_user_revision,
        'actor_tenant', p_actor_id, 'session_set', true, true
    ) AS result;
    RETURN QUERY SELECT p_actor_id, p_actor_id, v_user_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_session_revoke_all_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_session_revoke_one_v1(name, uuid, uuid, bytea, uuid, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_session_revoke_one_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_session_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_session_id IS NULL OR p_expected_revision < 1 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.session.revoke_one',
        p_request_sha256, p_session_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    UPDATE iam_sessions AS session SET state = 'revoked', revoked_at = v_now,
        revision = session.revision + 1, updated_at = v_now
    WHERE session.id = p_session_id AND session.user_id = p_actor_id
      AND session.state = 'active' AND session.revision = p_expected_revision
    RETURNING session.user_id, session.revision INTO v_user_id, v_revision;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '40001'; END IF;
    UPDATE iam_refresh_families SET state = 'revoked',
        revoke_reason = 'session_revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE session_id = p_session_id AND state = 'active';
    UPDATE iam_refresh_tokens SET state = 'revoked', revoked_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE family_id IN (
        SELECT id FROM iam_refresh_families WHERE session_id = p_session_id
    ) AND state = 'active';
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.session.revoke_one', p_request_sha256,
        p_session_id, v_user_id, v_revision,
        'actor_tenant', p_actor_id, 'session', false, false
    ) AS result;
    RETURN QUERY SELECT p_session_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_session_revoke_one_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_session_id uuid, p_expected_revision bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_session_revoke_v1(name, uuid, uuid, bigint, bigint, uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_session_revoke_v1(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint) RETURNS TABLE(outcome text, locator_selector bytea, locator_expected_revision bigint, locator_revision bigint, locator_source_sha256 bytea, locator_state text, locator_projected_at timestamp with time zone, locator_retain_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_now timestamptz := pg_catalog.transaction_timestamp();
    v_token_state text;
    v_token_revision bigint;
    v_family_state text;
    v_family_revision bigint;
    v_session_state text;
    v_session_revision bigint;
    v_user_revision bigint;
    v_secret_hmac bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_token_id IS NULL OR p_family_id IS NULL OR p_session_id IS NULL OR
       p_user_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM session revoke scope is invalid';
    END IF;
    SELECT token.state, token.revision, token.selector, token.secret_hmac,
           token.retain_until, family.state, family.revision,
           session.state, session.revision, principal.revision
    INTO v_token_state, v_token_revision, locator_selector, v_secret_hmac,
         locator_retain_until, v_family_state, v_family_revision,
         v_session_state, v_session_revision, v_user_revision
    FROM iam_refresh_tokens AS token
    JOIN iam_refresh_families AS family
      ON family.id OPERATOR(pg_catalog.=) token.family_id
    JOIN iam_sessions AS session
      ON session.id OPERATOR(pg_catalog.=) family.session_id
    JOIN iam_users AS principal
      ON principal.id OPERATOR(pg_catalog.=) family.user_id
    WHERE token.id OPERATOR(pg_catalog.=) p_token_id
      AND token.family_id OPERATOR(pg_catalog.=) p_family_id
      AND family.id OPERATOR(pg_catalog.=) p_family_id
      AND session.id OPERATOR(pg_catalog.=) p_session_id
      AND principal.id OPERATOR(pg_catalog.=) p_user_id
    FOR UPDATE OF token, family, session, principal;
    IF NOT FOUND OR v_token_revision IS DISTINCT FROM
           p_expected_token_revision OR
       v_family_revision IS DISTINCT FROM p_expected_family_revision OR
       v_session_revision IS DISTINCT FROM p_expected_session_revision OR
       v_user_revision IS DISTINCT FROM p_expected_user_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM session revoke CAS is stale';
    END IF;
    IF v_token_state IS DISTINCT FROM 'active' THEN
        outcome := 'terminal';
        locator_selector := NULL;
        locator_retain_until := NULL;
        RETURN NEXT;
        RETURN;
    END IF;
    IF v_family_state IS DISTINCT FROM 'active' OR
       v_session_state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'IAM session revoke family is stale';
    END IF;
    UPDATE iam_refresh_tokens
    SET state = 'revoked', revoked_at = v_now, updated_at = v_now,
        revision = v_token_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_token_id;
    UPDATE iam_refresh_families
    SET state = 'revoked', revoke_reason = 'logout', revoked_at = v_now,
        updated_at = v_now,
        revision = v_family_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_family_id;
    UPDATE iam_sessions
    SET state = 'revoked', revoked_at = v_now, updated_at = v_now,
        revision = v_session_revision OPERATOR(pg_catalog.+) 1
    WHERE id OPERATOR(pg_catalog.=) p_session_id;
    outcome := 'revoked';
    locator_expected_revision := v_token_revision;
    locator_revision := v_token_revision OPERATOR(pg_catalog.+) 1;
    locator_state := 'revoked';
    locator_projected_at := v_now;
    locator_source_sha256 := iam_refresh_locator_source_sha256_v1(
        p_token_id, p_family_id, locator_selector, locator_revision,
        locator_state, v_secret_hmac
    );
    RETURN NEXT;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_session_revoke_v1(p_scope_schema name, p_token_id uuid, p_family_id uuid, p_expected_token_revision bigint, p_expected_family_revision bigint, p_session_id uuid, p_expected_session_revision bigint, p_user_id uuid, p_expected_user_revision bigint) OWNER TO harpy_owner;

--
-- Name: iam_system_import_source_cleanup_claim_v1(name, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_import_source_cleanup_claim_v1(p_scope_schema name, p_tenant_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) RETURNS TABLE(source_id uuid, actor_id uuid, resource_kind text, object_key text, object_version text, cleanup_attempt integer, lease_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_source iam_system_import_sources%ROWTYPE;
    v_request iam_system_record_imports%ROWTYPE;
    v_job_state text;
    v_job_completed_at timestamptz;
    v_eligible boolean;
BEGIN
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    IF p_tenant_id IS NULL OR v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       pg_catalog.uuid_extract_version(p_lease_owner) IS DISTINCT FROM 7 OR
       NOT pg_catalog.isfinite(p_observed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM import source cleanup claim is invalid';
    END IF;
    FOR v_source IN
        SELECT source.*
        FROM iam_system_import_sources AS source
        WHERE source.tenant_id=p_tenant_id
          AND source.state IN ('ready','claimed')
          AND ((source.cleanup_state='waiting' AND
                source.cleanup_next_at<=p_observed_at) OR
               (source.cleanup_state='running' AND
                source.cleanup_lease_until<=p_observed_at))
        ORDER BY source.cleanup_next_at,source.source_id
        FOR UPDATE SKIP LOCKED
        LIMIT 32
    LOOP
        v_eligible:=false;
        IF v_source.state='ready' THEN
            v_eligible:=v_source.delete_after<=p_observed_at;
        ELSE
            SELECT request.* INTO STRICT v_request
            FROM iam_system_record_imports AS request
            WHERE request.import_id=v_source.claimed_import_id
              AND request.source_id=v_source.source_id
              AND request.tenant_id=p_tenant_id
              AND request.actor_id=v_source.actor_id
              AND request.resource_kind=v_source.resource_kind;
            SELECT job.job_state,job.completed_at
            INTO v_job_state,v_job_completed_at
            FROM platform.platform_async_iam_import_cleanup_read_v1(
                p_tenant_id,v_request.import_id,v_request.job_id,
                v_request.resource_kind
            ) AS job;
            IF v_job_state NOT IN ('queued','running','succeeded','dead','cancelled') OR
               (v_job_state IN ('succeeded','dead','cancelled') AND
                v_job_completed_at IS NULL) OR
               (v_job_state='succeeded' AND v_request.state<>'completed') THEN
                RAISE EXCEPTION USING ERRCODE='P6047',
                    MESSAGE='IAM import source cleanup state is inconsistent';
            END IF;
            v_eligible:=v_job_state IN ('succeeded','dead','cancelled');
        END IF;
        IF NOT v_eligible THEN
            UPDATE iam_system_import_sources
            SET cleanup_state='waiting',
                cleanup_next_at=p_observed_at+interval '1 minute',
                cleanup_lease_owner=NULL,cleanup_lease_until=NULL
            WHERE iam_system_import_sources.source_id=v_source.source_id;
            CONTINUE;
        END IF;
        RETURN QUERY
        UPDATE iam_system_import_sources AS claimed
        SET cleanup_state='running',cleanup_attempts=claimed.cleanup_attempts+1,
            cleanup_lease_owner=p_lease_owner,
            cleanup_lease_generation=claimed.cleanup_lease_generation+1,
            cleanup_lease_until=p_observed_at+interval '60 seconds',
            cleanup_next_at=p_observed_at
        WHERE claimed.source_id=v_source.source_id
        RETURNING claimed.source_id,claimed.actor_id,claimed.resource_kind,
                  claimed.object_key,claimed.object_version,
                  claimed.cleanup_attempts,claimed.cleanup_lease_generation;
        RETURN;
    END LOOP;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_import_source_cleanup_claim_v1(p_scope_schema name, p_tenant_id uuid, p_lease_owner uuid, p_observed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_import_source_cleanup_complete_v1(name, uuid, uuid, uuid, text, text, text, uuid, bigint, text, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_import_source_cleanup_complete_v1(p_scope_schema name, p_tenant_id uuid, p_source_id uuid, p_actor_id uuid, p_resource_kind text, p_object_key text, p_object_version text, p_lease_owner uuid, p_lease_generation bigint, p_provider_request_id text, p_delete_response_sha256 bytea, p_absence_probe_sha256 bytea, p_verified_absent_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_source iam_system_import_sources%ROWTYPE;
BEGIN
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    IF p_tenant_id IS NULL OR p_actor_id IS NULL OR
       pg_catalog.uuid_extract_version(p_source_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner) IS DISTINCT FROM 7 OR
       p_lease_generation<1 OR v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('users','roles','organizations') OR
       p_object_key IS DISTINCT FROM 'iam-system-import-sources/v1/'||
           p_source_id::text||'/1.fcart' OR
       pg_catalog.octet_length(p_object_version) NOT BETWEEN 1 AND 512 OR
       p_provider_request_id IS NULL OR
       pg_catalog.octet_length(p_provider_request_id) NOT BETWEEN 1 AND 256 OR
       p_delete_response_sha256 IS NULL OR p_absence_probe_sha256 IS NULL OR
       pg_catalog.octet_length(p_delete_response_sha256)<>32 OR
       pg_catalog.octet_length(p_absence_probe_sha256)<>32 OR
       NOT pg_catalog.isfinite(p_verified_absent_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM import source cleanup completion is invalid';
    END IF;
    SELECT source.* INTO v_source
    FROM iam_system_import_sources AS source
    WHERE source.source_id=p_source_id AND source.tenant_id=p_tenant_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import source was not found';
    END IF;
    IF v_source.actor_id IS DISTINCT FROM p_actor_id OR
       v_source.resource_kind IS DISTINCT FROM p_resource_kind OR
       v_source.object_key IS DISTINCT FROM p_object_key OR
       v_source.object_version IS DISTINCT FROM p_object_version THEN
        RAISE EXCEPTION USING ERRCODE='P6049',
            MESSAGE='IAM import source cleanup identity differs';
    END IF;
    IF v_source.state='deleted' THEN
        IF v_source.delete_provider_request_id IS DISTINCT FROM p_provider_request_id OR
           v_source.delete_response_sha256 IS DISTINCT FROM p_delete_response_sha256 OR
           v_source.absence_probe_sha256 IS DISTINCT FROM p_absence_probe_sha256 OR
           v_source.verified_absent_at IS DISTINCT FROM p_verified_absent_at THEN
            RAISE EXCEPTION USING ERRCODE='P6049',
                MESSAGE='IAM import source cleanup receipt differs';
        END IF;
        RETURN true;
    END IF;
    IF v_source.state NOT IN ('ready','claimed') OR
       v_source.cleanup_state<>'running' OR
       v_source.cleanup_lease_owner IS DISTINCT FROM p_lease_owner OR
       v_source.cleanup_lease_generation IS DISTINCT FROM p_lease_generation THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM import source cleanup lease is stale';
    END IF;
    UPDATE iam_system_import_sources
    SET state='deleted',deleted_at=p_verified_absent_at,
        delete_provider_request_id=p_provider_request_id,
        delete_response_sha256=p_delete_response_sha256,
        absence_probe_sha256=p_absence_probe_sha256,
        verified_absent_at=p_verified_absent_at
    WHERE source_id=p_source_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_import_source_cleanup_complete_v1(p_scope_schema name, p_tenant_id uuid, p_source_id uuid, p_actor_id uuid, p_resource_kind text, p_object_key text, p_object_version text, p_lease_owner uuid, p_lease_generation bigint, p_provider_request_id text, p_delete_response_sha256 bytea, p_absence_probe_sha256 bytea, p_verified_absent_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_import_source_cleanup_retry_v1(name, uuid, uuid, uuid, bigint, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_import_source_cleanup_retry_v1(p_scope_schema name, p_tenant_id uuid, p_source_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_error_code text, p_observed_at timestamp with time zone, p_retry_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_source iam_system_import_sources%ROWTYPE;
BEGIN
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    IF p_tenant_id IS NULL OR
       pg_catalog.uuid_extract_version(p_source_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner) IS DISTINCT FROM 7 OR
       p_lease_generation<1 OR p_error_code IS NULL OR
       v_tenant_id IS DISTINCT FROM p_tenant_id OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_error_code NOT IN (
           'SOURCE_DELETE_OUTCOME_UNKNOWN','SOURCE_DELETE_UNAVAILABLE'
       ) OR NOT pg_catalog.isfinite(p_observed_at) OR
       NOT pg_catalog.isfinite(p_retry_at) OR p_retry_at<p_observed_at OR
       p_retry_at>p_observed_at+interval '15 minutes' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM import source cleanup retry is invalid';
    END IF;
    SELECT source.* INTO v_source
    FROM iam_system_import_sources AS source
    WHERE source.source_id=p_source_id AND source.tenant_id=p_tenant_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import source was not found';
    END IF;
    IF v_source.state='deleted' THEN
        RETURN true;
    END IF;
    IF v_source.state NOT IN ('ready','claimed') OR
       v_source.cleanup_state<>'running' OR
       v_source.cleanup_lease_owner IS DISTINCT FROM p_lease_owner OR
       v_source.cleanup_lease_generation IS DISTINCT FROM p_lease_generation THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM import source cleanup lease is stale';
    END IF;
    UPDATE iam_system_import_sources
    SET cleanup_state='waiting',cleanup_next_at=p_retry_at,
        cleanup_lease_owner=NULL,cleanup_lease_until=NULL,
        cleanup_last_error_code=p_error_code
    WHERE source_id=p_source_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_import_source_cleanup_retry_v1(p_scope_schema name, p_tenant_id uuid, p_source_id uuid, p_lease_owner uuid, p_lease_generation bigint, p_error_code text, p_observed_at timestamp with time zone, p_retry_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_import_source_cleanup_sync_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_import_source_cleanup_sync_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        NEW.cleanup_state:='waiting';
        NEW.cleanup_attempts:=0;
        NEW.cleanup_next_at:=NEW.delete_after;
        NEW.cleanup_lease_owner:=NULL;
        NEW.cleanup_lease_generation:=0;
        NEW.cleanup_lease_until:=NULL;
        NEW.cleanup_last_error_code:=NULL;
    ELSIF NEW.state='claimed' AND OLD.state='ready' THEN
        NEW.cleanup_state:='waiting';
        NEW.cleanup_next_at:=NEW.claimed_at;
        NEW.cleanup_lease_owner:=NULL;
        NEW.cleanup_lease_until:=NULL;
        NEW.cleanup_last_error_code:=NULL;
    ELSIF NEW.state='deleted' AND OLD.state<>'deleted' THEN
        NEW.cleanup_state:='succeeded';
        NEW.cleanup_next_at:=NEW.verified_absent_at;
        NEW.cleanup_lease_owner:=NULL;
        NEW.cleanup_lease_until:=NULL;
        NEW.cleanup_last_error_code:=NULL;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_import_source_cleanup_sync_v1() OWNER TO harpy_owner;

--
-- Name: iam_system_import_source_register_v1(name, uuid, uuid, uuid, text, bigint, bigint, bytea, text, text, text, bytea, bytea, bigint, bytea, bigint, text, bytea, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_import_source_register_v1(p_scope_schema name, p_source_id uuid, p_receipt_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_idempotency_sha256 bytea, p_format text, p_object_key text, p_object_version text, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_ciphertext_bytes bigint, p_plaintext_sha256 bytea, p_plaintext_bytes bigint, p_key_id text, p_wrapped_dek bytea, p_wrap_nonce bytea, p_provider_request_id text, p_uploaded_at timestamp with time zone) RETURNS TABLE(source_id uuid, resource_kind text, format text, plaintext_bytes bigint, plaintext_sha256 bytea, uploaded_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_existing iam_system_import_sources%ROWTYPE;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',
        p_token_version,p_authorization_version,true
    ) THEN NULL; END IF;
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('iam-transfer-source:'||p_actor_id::text,6103)
    );
    SELECT source.* INTO v_existing
    FROM iam_system_import_sources AS source
    WHERE source.actor_id=p_actor_id
      AND source.resource_kind=p_resource_kind
      AND source.idempotency_key_sha256=p_idempotency_sha256;
    IF FOUND THEN
        IF v_existing.tenant_id IS DISTINCT FROM v_tenant_id OR
           v_existing.format IS DISTINCT FROM p_format OR
           v_existing.object_key IS DISTINCT FROM p_object_key OR
           v_existing.object_version IS DISTINCT FROM p_object_version OR
           v_existing.header_sha256 IS DISTINCT FROM p_header_sha256 OR
           v_existing.ciphertext_sha256 IS DISTINCT FROM p_ciphertext_sha256 OR
           v_existing.ciphertext_bytes IS DISTINCT FROM p_ciphertext_bytes OR
           v_existing.plaintext_sha256 IS DISTINCT FROM p_plaintext_sha256 OR
           v_existing.plaintext_bytes IS DISTINCT FROM p_plaintext_bytes OR
           v_existing.key_id IS DISTINCT FROM p_key_id OR
           v_existing.wrapped_dek IS DISTINCT FROM p_wrapped_dek OR
           v_existing.wrap_nonce IS DISTINCT FROM p_wrap_nonce OR
           v_existing.provider_request_id IS DISTINCT FROM p_provider_request_id THEN
            RAISE EXCEPTION USING ERRCODE='P6102',
                MESSAGE='IAM import source idempotency conflicts';
        END IF;
        RETURN QUERY SELECT v_existing.source_id,v_existing.resource_kind,
            v_existing.format,v_existing.plaintext_bytes,
            v_existing.plaintext_sha256,v_existing.uploaded_at,true;
        RETURN;
    END IF;
    INSERT INTO iam_system_import_sources(
        source_id,tenant_id,idempotency_receipt_id,resource_kind,actor_id,
        idempotency_key_sha256,format,object_key,object_version,header_sha256,
        ciphertext_sha256,ciphertext_bytes,plaintext_sha256,plaintext_bytes,
        key_id,wrapped_dek,wrap_nonce,provider_request_id,uploaded_at,delete_after
    ) VALUES(
        p_source_id,v_tenant_id,p_receipt_id,p_resource_kind,p_actor_id,
        p_idempotency_sha256,p_format,p_object_key,p_object_version,p_header_sha256,
        p_ciphertext_sha256,p_ciphertext_bytes,p_plaintext_sha256,p_plaintext_bytes,
        p_key_id,p_wrapped_dek,p_wrap_nonce,p_provider_request_id,p_uploaded_at,
        p_uploaded_at+interval '24 hours'
    );
    RETURN QUERY SELECT p_source_id,p_resource_kind,p_format,p_plaintext_bytes,
        p_plaintext_sha256,p_uploaded_at,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_import_source_register_v1(p_scope_schema name, p_source_id uuid, p_receipt_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_idempotency_sha256 bytea, p_format text, p_object_key text, p_object_version text, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_ciphertext_bytes bigint, p_plaintext_sha256 bytea, p_plaintext_bytes bigint, p_key_id text, p_wrapped_dek bytea, p_wrap_nonce bytea, p_provider_request_id text, p_uploaded_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_import_source_register_v2(name, uuid, uuid, uuid, text, bigint, bigint, bytea, text, text, text, bytea, bytea, bigint, bytea, bigint, text, bytea, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_import_source_register_v2(p_scope_schema name, p_source_id uuid, p_receipt_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_idempotency_sha256 bytea, p_format text, p_object_key text, p_object_version text, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_ciphertext_bytes bigint, p_plaintext_sha256 bytea, p_plaintext_bytes bigint, p_key_id text, p_wrapped_dek bytea, p_wrap_nonce bytea, p_provider_request_id text, p_uploaded_at timestamp with time zone) RETURNS TABLE(source_id uuid, resource_kind text, format text, plaintext_bytes bigint, plaintext_sha256 bytea, uploaded_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_existing iam_system_import_sources%ROWTYPE;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',
        p_token_version,p_authorization_version,true
    ) THEN NULL; END IF;
    IF pg_catalog.uuid_extract_version(p_source_id)<>7 OR
       pg_catalog.uuid_extract_version(p_receipt_id)<>7 OR
       pg_catalog.octet_length(p_idempotency_sha256)<>32 OR
       p_format NOT IN ('csv','jsonl') OR
       p_object_key IS DISTINCT FROM
         'iam-system-import-sources/v1/'||p_source_id::text||'/1.fcart' OR
       pg_catalog.octet_length(p_object_version) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_header_sha256)<>32 OR
       pg_catalog.octet_length(p_ciphertext_sha256)<>32 OR
       p_ciphertext_bytes NOT BETWEEN 1 AND 538968064 OR
       pg_catalog.octet_length(p_plaintext_sha256)<>32 OR
       p_plaintext_bytes NOT BETWEEN 1 AND 536870912 OR
       pg_catalog.octet_length(p_key_id) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_wrapped_dek) NOT BETWEEN 32 AND 1024 OR
       pg_catalog.octet_length(p_wrap_nonce)<>12 OR
       pg_catalog.octet_length(p_provider_request_id) NOT BETWEEN 1 AND 256 OR
       NOT pg_catalog.isfinite(p_uploaded_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM import source evidence is invalid';
    END IF;
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'iam-transfer-source:'||v_tenant_id::text||':'||p_actor_id::text,6103
        )
    );
    SELECT source.* INTO v_existing
    FROM iam_system_import_sources AS source
    WHERE source.actor_id=p_actor_id
      AND source.resource_kind=p_resource_kind
      AND source.idempotency_key_sha256=p_idempotency_sha256;
    IF FOUND THEN
        IF v_existing.state='deleted' OR
           v_existing.delete_after<=pg_catalog.transaction_timestamp() THEN
            RAISE EXCEPTION USING ERRCODE='P6103',
                MESSAGE='IAM import source idempotency receipt expired';
        END IF;
        IF v_existing.tenant_id IS DISTINCT FROM v_tenant_id OR
           v_existing.format IS DISTINCT FROM p_format OR
           v_existing.plaintext_sha256 IS DISTINCT FROM p_plaintext_sha256 OR
           v_existing.plaintext_bytes IS DISTINCT FROM p_plaintext_bytes THEN
            RAISE EXCEPTION USING ERRCODE='P6102',
                MESSAGE='IAM import source idempotency conflicts';
        END IF;
        RETURN QUERY SELECT v_existing.source_id,v_existing.resource_kind,
            v_existing.format,v_existing.plaintext_bytes,
            v_existing.plaintext_sha256,v_existing.uploaded_at,true;
        RETURN;
    END IF;
    INSERT INTO iam_system_import_sources(
        source_id,tenant_id,idempotency_receipt_id,resource_kind,actor_id,
        idempotency_key_sha256,format,object_key,object_version,header_sha256,
        ciphertext_sha256,ciphertext_bytes,plaintext_sha256,plaintext_bytes,
        key_id,wrapped_dek,wrap_nonce,provider_request_id,uploaded_at,delete_after
    ) VALUES(
        p_source_id,v_tenant_id,p_receipt_id,p_resource_kind,p_actor_id,
        p_idempotency_sha256,p_format,p_object_key,p_object_version,p_header_sha256,
        p_ciphertext_sha256,p_ciphertext_bytes,p_plaintext_sha256,p_plaintext_bytes,
        p_key_id,p_wrapped_dek,p_wrap_nonce,p_provider_request_id,p_uploaded_at,
        p_uploaded_at+interval '24 hours'
    );
    RETURN QUERY SELECT p_source_id,p_resource_kind,p_format,p_plaintext_bytes,
        p_plaintext_sha256,p_uploaded_at,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_import_source_register_v2(p_scope_schema name, p_source_id uuid, p_receipt_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_idempotency_sha256 bytea, p_format text, p_object_key text, p_object_version text, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_ciphertext_bytes bigint, p_plaintext_sha256 bytea, p_plaintext_bytes bigint, p_key_id text, p_wrapped_dek bytea, p_wrap_nonce bytea, p_provider_request_id text, p_uploaded_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_import_source_storage_guard_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_import_source_storage_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS DISTINCT FROM 'UPDATE' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM import source storage is immutable';
    END IF;
    IF pg_catalog.to_jsonb(NEW)-ARRAY[
           'state','claimed_import_id','claimed_at','deleted_at',
           'delete_provider_request_id','delete_response_sha256',
           'absence_probe_sha256','verified_absent_at','cleanup_state',
           'cleanup_attempts','cleanup_next_at','cleanup_lease_owner',
           'cleanup_lease_generation','cleanup_lease_until',
           'cleanup_last_error_code'
       ]::text[] IS DISTINCT FROM pg_catalog.to_jsonb(OLD)-ARRAY[
           'state','claimed_import_id','claimed_at','deleted_at',
           'delete_provider_request_id','delete_response_sha256',
           'absence_probe_sha256','verified_absent_at','cleanup_state',
           'cleanup_attempts','cleanup_next_at','cleanup_lease_owner',
           'cleanup_lease_generation','cleanup_lease_until',
           'cleanup_last_error_code'
       ]::text[] THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM import source immutable fields differ';
    END IF;
    IF (OLD.state='ready' AND OLD.cleanup_state='waiting' AND
        NEW.state='claimed' AND
        pg_catalog.uuid_extract_version(NEW.claimed_import_id)=7 AND
        NEW.claimed_at IS NOT NULL) OR
       (OLD.state=NEW.state AND NEW.state IN ('ready','claimed') AND
        OLD.cleanup_state IN ('waiting','running') AND
        NEW.cleanup_state='running' AND
        NEW.cleanup_attempts=OLD.cleanup_attempts+1 AND
        NEW.cleanup_lease_generation=OLD.cleanup_lease_generation+1 AND
        pg_catalog.uuid_extract_version(NEW.cleanup_lease_owner)=7 AND
        NEW.cleanup_lease_until>NEW.cleanup_next_at) OR
       (OLD.state=NEW.state AND NEW.state IN ('ready','claimed') AND
        OLD.cleanup_state IN ('waiting','running') AND NEW.cleanup_state='waiting' AND
        NEW.cleanup_attempts=OLD.cleanup_attempts AND
        NEW.cleanup_lease_generation=OLD.cleanup_lease_generation AND
        NEW.cleanup_lease_owner IS NULL AND NEW.cleanup_lease_until IS NULL AND
        NEW.cleanup_next_at>=OLD.cleanup_next_at) OR
       (OLD.state IN ('ready','claimed') AND NEW.state='deleted' AND
        NEW.deleted_at IS NOT NULL AND NEW.delete_provider_request_id IS NOT NULL AND
        NEW.delete_response_sha256 IS NOT NULL AND
        NEW.absence_probe_sha256 IS NOT NULL AND NEW.verified_absent_at IS NOT NULL) THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE='P6048',
        MESSAGE='IAM import source transition is immutable';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_import_source_storage_guard_v1() OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_cancel_v1(name, uuid, uuid, text, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_cancel_v1(p_scope_schema name, p_export_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_now timestamp with time zone) RETURNS TABLE(export_id uuid, job_id uuid, resource_kind text, format text, state text, processed_rows bigint, plaintext_bytes bigint, created_at timestamp with time zone, ready_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export iam_system_record_exports%ROWTYPE;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'export',
        p_token_version,p_authorization_version,true
    ) THEN NULL; END IF;
    SELECT request.* INTO v_export
    FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.actor_id=p_actor_id
      AND request.resource_kind=p_resource_kind
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='IAM export is unavailable';
    END IF;
    IF v_export.state IN ('waiting','running') THEN
        UPDATE iam_system_record_exports SET state='cancelled',completed_at=p_now
        WHERE iam_system_record_exports.export_id=p_export_id;
        UPDATE iam_system_transfer_admissions
        SET state='released',tenant_run_slot=NULL,principal_wait_slot=NULL,
            released_at=p_now
        WHERE transfer_kind='export' AND transfer_id=p_export_id
          AND state IN ('waiting','running');
        v_export.state := 'cancelled';
    ELSIF v_export.state<>'cancelled' THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='IAM export cannot be cancelled';
    END IF;
    RETURN QUERY SELECT v_export.export_id,v_export.job_id,
        v_export.resource_kind,v_export.format,v_export.state,
        v_export.processed_rows,v_export.plaintext_bytes,v_export.created_at,
        v_export.ready_at,v_export.expires_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_cancel_v1(p_scope_schema name, p_export_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_content_v1(name, uuid, uuid, text, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_content_v1(p_scope_schema name, p_export_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_now timestamp with time zone) RETURNS TABLE(export_id uuid, job_id uuid, resource_kind text, format text, state text, processed_rows bigint, plaintext_bytes bigint, created_at timestamp with time zone, ready_at timestamp with time zone, expires_at timestamp with time zone, object_key text, object_version text, header_sha256 bytea, ciphertext_sha256 bytea, ciphertext_bytes bigint, key_id text, wrapped_dek bytea, wrap_nonce bytea, attempt_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export iam_system_record_exports%ROWTYPE;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'export',
        p_token_version,p_authorization_version,false
    ) THEN NULL; END IF;
    SELECT request.* INTO v_export
    FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.actor_id=p_actor_id
      AND request.resource_kind=p_resource_kind;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='IAM export is unavailable';
    END IF;
    IF v_export.state='expired' OR
       (v_export.state='ready' AND v_export.expires_at<=p_now) THEN
        RAISE EXCEPTION USING ERRCODE='P6103',
            MESSAGE='IAM export artifact expired';
    END IF;
    IF v_export.state<>'ready' THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='IAM export artifact is not ready';
    END IF;
    RETURN QUERY SELECT v_export.export_id,v_export.job_id,
        v_export.resource_kind,v_export.format,v_export.state,
        v_export.processed_rows,v_export.plaintext_bytes,v_export.created_at,
        v_export.ready_at,v_export.expires_at,v_export.object_key,
        v_export.object_version,v_export.header_sha256,
        v_export.ciphertext_sha256,v_export.ciphertext_bytes,v_export.key_id,
        v_export.wrapped_dek,v_export.wrap_nonce,v_export.attempt_generation;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_content_v1(p_scope_schema name, p_export_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_read_v1(name, uuid, uuid, text, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_read_v1(p_scope_schema name, p_export_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint) RETURNS TABLE(export_id uuid, job_id uuid, resource_kind text, format text, state text, processed_rows bigint, plaintext_bytes bigint, created_at timestamp with time zone, ready_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'export',
        p_token_version,p_authorization_version,false
    ) THEN NULL; END IF;
    RETURN QUERY
    SELECT request.export_id,request.job_id,request.resource_kind,request.format,
        request.state,request.processed_rows,request.plaintext_bytes,
        request.created_at,request.ready_at,request.expires_at
    FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.actor_id=p_actor_id
      AND request.resource_kind=p_resource_kind;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_read_v1(p_scope_schema name, p_export_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_reconcile_claim_v1(name, uuid, uuid, uuid, uuid, uuid, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_reconcile_claim_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text) RETURNS TABLE(claimed boolean, actor_id uuid, original_job_id uuid, token_version bigint, authorization_version bigint, catalog_version_id uuid, catalog_sha256 bytea, query_document bytea, query_sha256 bytea, format text, original_attempt_generation bigint, original_effect_id uuid, original_effect_receipt_id uuid, original_lease_owner_id uuid, object_key text, original_request_sha256 bytea, original_started_at timestamp with time zone, key_id text, header_sha256 bytea, ciphertext_sha256 bytea, ciphertext_bytes bigint, wrapped_dek bytea, wrap_nonce bytea, observation_effect_id uuid, observation_receipt_id uuid, observation_request_sha256 bytea, observation_started_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_effect_id uuid;
    v_receipt_id uuid;
    v_request_sha bytea;
    v_started_at timestamptz;
    v_replayed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       p_lease_generation NOT BETWEEN 1 AND 8 OR
       p_resource_kind NOT IN ('users','roles','organizations') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export reconciliation claim authority is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.resource_kind=p_resource_kind
      AND request.reconciliation_job_id=p_job_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation owner is unavailable';
    END IF;
    IF v_request.reconciliation_state IN ('resolved_sealed','resolved_missing','parked')
       THEN
        RETURN QUERY SELECT false,NULL::uuid,NULL::uuid,NULL::bigint,NULL::bigint,
            NULL::uuid,NULL::bytea,NULL::bytea,NULL::bytea,NULL::text,NULL::bigint,
            NULL::uuid,NULL::uuid,NULL::uuid,NULL::text,NULL::bytea,NULL::timestamptz,
            NULL::text,NULL::bytea,NULL::bytea,NULL::bigint,NULL::bytea,NULL::bytea,
            NULL::uuid,NULL::uuid,NULL::bytea,NULL::timestamptz;
        RETURN;
    END IF;
    IF v_request.state<>'outcome_unknown' OR
       pg_catalog.uuid_extract_version(v_request.effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(v_request.outcome_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(v_request.effect_lease_owner_id) IS DISTINCT FROM 7 OR
       v_request.reconciliation_state NOT IN ('queued','retry_wait','running') OR
       (v_request.reconciliation_attempt_generation IS NOT NULL AND
        v_request.reconciliation_attempt_generation>p_lease_generation) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation owner state conflicts';
    END IF;
    IF v_request.reconciliation_state='running' AND
       v_request.reconciliation_attempt_generation=p_lease_generation THEN
        v_effect_id := v_request.reconciliation_effect_id;
        v_receipt_id := v_request.reconciliation_receipt_id;
        v_request_sha := v_request.reconciliation_request_sha256;
        v_started_at := v_request.reconciliation_started_at;
    ELSE
        v_effect_id := p_attempt_id;
        v_receipt_id := pg_catalog.uuidv7();
        v_request_sha := pg_catalog.sha256(
            pg_catalog.convert_to(
                'iam.system-export.reconciliation.v1','UTF8')||
            pg_catalog.decode('00','hex')||pg_catalog.uuid_send(v_request.effect_id)||
            v_request.effect_request_sha256||v_request.ciphertext_sha256||
            v_request.header_sha256||
            pg_catalog.int8send(pg_catalog.octet_length(
                pg_catalog.convert_to(v_request.effect_object_key,'UTF8')))||
            pg_catalog.convert_to(v_request.effect_object_key,'UTF8')||
            pg_catalog.int8send(v_request.ciphertext_bytes));
        v_started_at := pg_catalog.clock_timestamp();
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_effect_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,v_effect_id,v_receipt_id,
        v_request_sha,v_started_at
    ) INTO v_replayed;
    IF v_replayed IS DISTINCT FROM (
        v_request.reconciliation_state='running' AND
        v_request.reconciliation_attempt_generation=p_lease_generation
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation platform replay conflicts';
    END IF;
    UPDATE iam_system_record_exports SET reconciliation_state='running',
        reconciliation_attempt_generation=p_lease_generation,
        reconciliation_effect_id=v_effect_id,reconciliation_receipt_id=v_receipt_id,
        reconciliation_request_sha256=v_request_sha,
        reconciliation_started_at=v_started_at,reconciliation_observed_at=NULL,
        reconciliation_next_at=NULL,reconciliation_code=NULL
    WHERE export_id=p_export_id;
    RETURN QUERY SELECT true,v_request.actor_id,v_request.job_id,
        v_request.token_version,v_request.authorization_version,
        v_request.catalog_version_id,v_request.catalog_sha256,
        v_request.query_document,v_request.query_sha256,v_request.format,
        v_request.attempt_generation,v_request.effect_id,v_request.outcome_receipt_id,
        v_request.effect_lease_owner_id,v_request.effect_object_key,
        v_request.effect_request_sha256,v_request.effect_started_at,v_request.key_id,
        v_request.header_sha256,v_request.ciphertext_sha256,
        v_request.ciphertext_bytes,v_request.wrapped_dek,v_request.wrap_nonce,
        v_effect_id,v_receipt_id,v_request_sha,v_started_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_reconcile_claim_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_reconcile_expired_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_reconcile_expired_v1(p_scope_schema name, p_tenant_id uuid) RETURNS TABLE(recovered boolean, resolution text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_export_id uuid;
    v_request iam_system_record_exports%ROWTYPE;
    v_job platform.jobs%ROWTYPE;
    v_attempt platform.job_attempts%ROWTYPE;
    v_now timestamptz;
    v_recovered_at timestamptz;
    v_retry_at timestamptz;
    v_code text;
    v_current boolean;
    v_replayed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export expired reconciliation authority is invalid';
    END IF;
    v_now := pg_catalog.clock_timestamp();
    SELECT request.export_id INTO v_export_id
    FROM iam_system_record_exports AS request
    JOIN platform.jobs AS job ON job.id=request.reconciliation_job_id
    JOIN platform.job_attempts AS attempt
      ON attempt.job_id=job.id AND attempt.attempt=job.attempts
     AND attempt.lease_generation=job.lease_generation
     AND attempt.lease_owner_id=job.lease_owner_id
    WHERE request.tenant_id=p_tenant_id AND request.state='outcome_unknown'
      AND request.reconciliation_state='running'
      AND request.reconciliation_attempt_generation=job.lease_generation
      AND request.reconciliation_effect_id=attempt.effect_id
      AND pg_catalog.encode(request.reconciliation_request_sha256,'hex')=
          attempt.effect_request_sha256
      AND request.reconciliation_started_at=attempt.effect_started_at
      AND request.reconciliation_receipt_id IS NOT NULL
      AND job.tenant_id=p_tenant_id AND job.scope_kind='tenant'
      AND job.scope_id=p_tenant_id AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=8 AND job.state='running'
      AND job.lease_until<=v_now AND attempt.finished_at IS NULL
      AND attempt.effect_receipt_id IS NULL
    ORDER BY job.lease_until,request.export_id
    LIMIT 1;
    IF NOT FOUND THEN
        RETURN QUERY SELECT false,NULL::text;
        RETURN;
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=v_export_id AND request.tenant_id=p_tenant_id
      AND request.state='outcome_unknown'
      AND request.reconciliation_state='running' FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT false,NULL::text;
        RETURN;
    END IF;
    SELECT job.* INTO v_job
    FROM platform.jobs AS job
    WHERE job.id=v_request.reconciliation_job_id AND job.tenant_id=p_tenant_id
      AND job.scope_kind='tenant' AND job.scope_id=p_tenant_id
      AND job.authority_group_id='iam_system_resources'
      AND job.authority_domain='iam' AND job.writer_origin='v2'
      AND job.kind='iam.system-resource.export-reconcile'
      AND job.payload_revision=1 AND job.effect_class='external'
      AND job.max_attempts=8 AND job.state='running'
      AND job.lease_generation=v_request.reconciliation_attempt_generation
      AND job.lease_until<=pg_catalog.clock_timestamp()
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT false,NULL::text;
        RETURN;
    END IF;
    SELECT attempt.* INTO v_attempt FROM platform.job_attempts AS attempt
    WHERE attempt.job_id=v_job.id AND attempt.attempt=v_job.attempts
      AND attempt.lease_generation=v_job.lease_generation
      AND attempt.lease_owner_id=v_job.lease_owner_id
      AND attempt.effect_id=v_request.reconciliation_effect_id
      AND attempt.effect_request_sha256=
          pg_catalog.encode(v_request.reconciliation_request_sha256,'hex')
      AND attempt.effect_started_at=v_request.reconciliation_started_at
      AND attempt.finished_at IS NULL AND attempt.effect_receipt_id IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
        RETURN QUERY SELECT false,NULL::text;
        RETURN;
    END IF;
    SELECT EXISTS(
        SELECT 1 FROM platform.cutover_groups AS group_row
        JOIN platform.domain_cutovers AS domain_row
          ON domain_row.scope_kind=group_row.scope_kind
         AND domain_row.scope_id=group_row.scope_id
        WHERE group_row.scope_kind=v_job.scope_kind
          AND group_row.scope_id=v_job.scope_id
          AND group_row.group_id=v_job.authority_group_id
          AND group_row.generation=v_job.authority_group_generation
          AND group_row.state='v2' AND group_row.writer='v2'
          AND domain_row.domain=v_job.authority_domain
          AND domain_row.generation=v_job.cutover_generation
          AND domain_row.state='v2' AND domain_row.writer='v2'
    ) INTO v_current;
    v_recovered_at := GREATEST(pg_catalog.clock_timestamp(),
        v_job.updated_at+interval '1 microsecond',v_job.lease_until,
        v_request.reconciliation_started_at);
    IF v_current AND v_job.lease_generation<8 THEN
        v_code := 'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN';
        v_retry_at := v_recovered_at + LEAST(
            interval '5 seconds' * pg_catalog.power(
                2::double precision,
                (v_job.lease_generation-1)::double precision),
            interval '15 minutes')*pg_catalog.random();
    ELSE
        v_code := 'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED';
        v_retry_at := NULL;
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_expired_v1(
        p_tenant_id,v_request.export_id,v_job.id,v_attempt.attempt_id,
        v_job.lease_owner_id,v_job.lease_generation,v_request.resource_kind,
        v_request.reconciliation_effect_id,v_request.reconciliation_receipt_id,
        v_request.reconciliation_request_sha256,
        v_request.reconciliation_started_at,v_recovered_at,v_retry_at,v_code
    ) INTO v_replayed;
    UPDATE iam_system_record_exports SET
        reconciliation_state=CASE WHEN v_retry_at IS NULL
            THEN 'parked' ELSE 'retry_wait' END,
        reconciliation_observed_at=v_recovered_at,
        reconciliation_next_at=v_retry_at,reconciliation_code=v_code,
        metadata_retain_until=GREATEST(
            metadata_retain_until,v_recovered_at+interval '366 days')
    WHERE export_id=v_request.export_id;
    RETURN QUERY SELECT true,CASE WHEN v_retry_at IS NULL
        THEN 'parked' ELSE 'requeued' END;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_reconcile_expired_v1(p_scope_schema name, p_tenant_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_reconcile_missing_v1(name, uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, timestamp with time zone, text, bytea, timestamp with time zone, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_reconcile_missing_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_observation_effect_id uuid, p_observation_receipt_id uuid, p_observation_request_sha256 bytea, p_observation_started_at timestamp with time zone, p_observation_provider_request_id text, p_observation_result_sha256 bytea, p_checked_at timestamp with time zone, p_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_replayed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR p_resource_kind NOT IN ('users','roles','organizations') OR
       pg_catalog.uuid_extract_version(p_observation_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_observation_receipt_id) IS DISTINCT FROM 7 OR
       p_observation_effect_id=p_observation_receipt_id OR
       pg_catalog.octet_length(p_observation_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_observation_provider_request_id) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_observation_result_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_observation_started_at) OR
       NOT pg_catalog.isfinite(p_checked_at) OR
       p_checked_at<p_observation_started_at OR
       p_code<>'IAM_SYSTEM_EXPORT_ARTIFACT_MISSING' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export missing reconciliation authority is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.resource_kind=p_resource_kind
      AND request.reconciliation_job_id=p_job_id
      AND request.reconciliation_attempt_generation=p_lease_generation
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export missing reconciliation owner is stale';
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_missing_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,p_observation_effect_id,
        p_observation_receipt_id,p_observation_request_sha256,
        p_observation_result_sha256,p_observation_provider_request_id,p_checked_at
    ) INTO v_replayed;
    IF v_replayed THEN
        IF v_request.state='failed' AND v_request.failure_code=p_code AND
           v_request.reconciliation_state='resolved_missing' AND
           v_request.reconciliation_effect_id=p_observation_effect_id AND
           v_request.reconciliation_receipt_id=p_observation_receipt_id AND
           v_request.reconciliation_request_sha256=p_observation_request_sha256 AND
           v_request.reconciliation_started_at=p_observation_started_at AND
           v_request.reconciliation_observed_at=p_checked_at AND
           v_request.reconciliation_code=p_code AND
           v_request.effect_receipt_id IS NULL AND
           v_request.outcome_receipt_id IS NULL AND
           v_request.object_key IS NULL AND v_request.object_version IS NULL AND
           v_request.provider_request_id IS NULL AND
           v_request.effect_result_sha256 IS NULL AND
           v_request.effect_completed_at IS NULL THEN RETURN true; END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export missing owner replay differs';
    END IF;
    IF v_request.state<>'outcome_unknown' OR
       v_request.reconciliation_state<>'running' OR
       v_request.reconciliation_effect_id<>p_observation_effect_id OR
       v_request.reconciliation_receipt_id<>p_observation_receipt_id OR
       v_request.reconciliation_request_sha256<>p_observation_request_sha256 OR
       v_request.reconciliation_started_at<>p_observation_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export missing owner evidence conflicts';
    END IF;
    UPDATE iam_system_record_exports SET state='failed',failure_code=p_code,
        object_key=NULL,object_version=NULL,provider_request_id=NULL,
        effect_receipt_id=NULL,outcome_receipt_id=NULL,
        effect_result_sha256=NULL,effect_completed_at=NULL,
        ready_at=NULL,expires_at=NULL,completed_at=p_checked_at,
        reconciliation_state='resolved_missing',
        reconciliation_observed_at=p_checked_at,reconciliation_next_at=NULL,
        reconciliation_code=p_code,
        metadata_retain_until=GREATEST(
            metadata_retain_until,p_checked_at+interval '366 days')
    WHERE export_id=p_export_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_reconcile_missing_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_observation_effect_id uuid, p_observation_receipt_id uuid, p_observation_request_sha256 bytea, p_observation_started_at timestamp with time zone, p_observation_provider_request_id text, p_observation_result_sha256 bytea, p_checked_at timestamp with time zone, p_code text) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_reconcile_park_v1(name, uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, timestamp with time zone, bytea, timestamp with time zone, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_reconcile_park_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_observation_effect_id uuid, p_observation_receipt_id uuid, p_observation_request_sha256 bytea, p_observation_started_at timestamp with time zone, p_failure_sha256 bytea, p_observed_at timestamp with time zone, p_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_expected_failure bytea;
    v_replayed boolean;
BEGIN
    v_expected_failure := pg_catalog.sha256(
        pg_catalog.convert_to(
            'iam.system-export.reconciliation-failure.v1','UTF8') ||
        pg_catalog.decode('00','hex') || pg_catalog.uuid_send(p_job_id) ||
        pg_catalog.uuid_send(p_observation_effect_id) ||
        pg_catalog.int8send(pg_catalog.octet_length(
            pg_catalog.convert_to(p_code,'UTF8'))::bigint) ||
        pg_catalog.convert_to(p_code,'UTF8') ||
        pg_catalog.int8send(p_lease_generation));
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR p_resource_kind NOT IN ('users','roles','organizations') OR
       p_lease_generation<>8 OR
       pg_catalog.uuid_extract_version(p_observation_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_observation_receipt_id) IS DISTINCT FROM 7 OR
       p_observation_effect_id=p_observation_receipt_id OR
       pg_catalog.octet_length(p_observation_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_failure_sha256) IS DISTINCT FROM 32 OR
       p_failure_sha256<>v_expected_failure OR
       NOT pg_catalog.isfinite(p_observation_started_at) OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       p_observed_at<p_observation_started_at OR
       p_code<>'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_PARKED' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export reconciliation park authority is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.resource_kind=p_resource_kind
      AND request.reconciliation_job_id=p_job_id
      AND request.reconciliation_attempt_generation=p_lease_generation
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export reconciliation park owner is stale';
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_park_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,p_observation_effect_id,
        p_observation_receipt_id,p_observation_request_sha256,p_failure_sha256,
        p_observed_at
    ) INTO v_replayed;
    IF v_replayed THEN
        IF v_request.state='outcome_unknown' AND
           v_request.reconciliation_state='parked' AND
           v_request.reconciliation_effect_id=p_observation_effect_id AND
           v_request.reconciliation_receipt_id=p_observation_receipt_id AND
           v_request.reconciliation_request_sha256=p_observation_request_sha256 AND
           v_request.reconciliation_started_at=p_observation_started_at AND
           v_request.reconciliation_observed_at=p_observed_at AND
           v_request.reconciliation_next_at IS NULL AND
           v_request.reconciliation_code=p_code THEN RETURN true; END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation park replay differs';
    END IF;
    IF v_request.state<>'outcome_unknown' OR
       v_request.reconciliation_state<>'running' OR
       v_request.reconciliation_effect_id<>p_observation_effect_id OR
       v_request.reconciliation_receipt_id<>p_observation_receipt_id OR
       v_request.reconciliation_request_sha256<>p_observation_request_sha256 OR
       v_request.reconciliation_started_at<>p_observation_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation park evidence conflicts';
    END IF;
    UPDATE iam_system_record_exports SET reconciliation_state='parked',
        reconciliation_observed_at=p_observed_at,reconciliation_next_at=NULL,
        reconciliation_code=p_code,
        metadata_retain_until=GREATEST(
            metadata_retain_until,p_observed_at+interval '366 days')
    WHERE export_id=p_export_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_reconcile_park_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_observation_effect_id uuid, p_observation_receipt_id uuid, p_observation_request_sha256 bytea, p_observation_started_at timestamp with time zone, p_failure_sha256 bytea, p_observed_at timestamp with time zone, p_code text) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_reconcile_retry_v1(name, uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, timestamp with time zone, bytea, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_reconcile_retry_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_observation_effect_id uuid, p_observation_receipt_id uuid, p_observation_request_sha256 bytea, p_observation_started_at timestamp with time zone, p_failure_sha256 bytea, p_observed_at timestamp with time zone, p_retry_at timestamp with time zone, p_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_expected_failure bytea;
    v_replayed boolean;
BEGIN
    v_expected_failure := pg_catalog.sha256(
        pg_catalog.convert_to(
            'iam.system-export.reconciliation-failure.v1','UTF8') ||
        pg_catalog.decode('00','hex') || pg_catalog.uuid_send(p_job_id) ||
        pg_catalog.uuid_send(p_observation_effect_id) ||
        pg_catalog.int8send(pg_catalog.octet_length(
            pg_catalog.convert_to(p_code,'UTF8'))::bigint) ||
        pg_catalog.convert_to(p_code,'UTF8') ||
        pg_catalog.int8send(p_lease_generation));
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR p_resource_kind NOT IN ('users','roles','organizations') OR
       p_lease_generation NOT BETWEEN 1 AND 7 OR
       pg_catalog.uuid_extract_version(p_observation_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_observation_receipt_id) IS DISTINCT FROM 7 OR
       p_observation_effect_id=p_observation_receipt_id OR
       pg_catalog.octet_length(p_observation_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_failure_sha256) IS DISTINCT FROM 32 OR
       p_failure_sha256<>v_expected_failure OR
       NOT pg_catalog.isfinite(p_observation_started_at) OR
       NOT pg_catalog.isfinite(p_observed_at) OR
       NOT pg_catalog.isfinite(p_retry_at) OR
       p_observed_at<p_observation_started_at OR p_retry_at<p_observed_at OR
       p_retry_at>p_observed_at+interval '15 minutes' OR
       p_code<>'IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILIATION_UNKNOWN' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export reconciliation retry authority is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.resource_kind=p_resource_kind
      AND request.reconciliation_job_id=p_job_id
      AND request.reconciliation_attempt_generation=p_lease_generation
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export reconciliation retry owner is stale';
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_retry_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,p_observation_effect_id,
        p_observation_receipt_id,p_observation_request_sha256,p_failure_sha256,
        p_observed_at,p_retry_at
    ) INTO v_replayed;
    IF v_replayed THEN
        IF v_request.state='outcome_unknown' AND
           v_request.reconciliation_state='retry_wait' AND
           v_request.reconciliation_effect_id=p_observation_effect_id AND
           v_request.reconciliation_receipt_id=p_observation_receipt_id AND
           v_request.reconciliation_request_sha256=p_observation_request_sha256 AND
           v_request.reconciliation_started_at=p_observation_started_at AND
           v_request.reconciliation_observed_at=p_observed_at AND
           v_request.reconciliation_next_at=p_retry_at AND
           v_request.reconciliation_code=p_code THEN RETURN true; END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation retry replay differs';
    END IF;
    IF v_request.state<>'outcome_unknown' OR
       v_request.reconciliation_state<>'running' OR
       v_request.reconciliation_effect_id<>p_observation_effect_id OR
       v_request.reconciliation_receipt_id<>p_observation_receipt_id OR
       v_request.reconciliation_request_sha256<>p_observation_request_sha256 OR
       v_request.reconciliation_started_at<>p_observation_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export reconciliation retry evidence conflicts';
    END IF;
    UPDATE iam_system_record_exports SET reconciliation_state='retry_wait',
        reconciliation_observed_at=p_observed_at,
        reconciliation_next_at=p_retry_at,reconciliation_code=p_code,
        metadata_retain_until=GREATEST(
            metadata_retain_until,p_observed_at+interval '366 days')
    WHERE export_id=p_export_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_reconcile_retry_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_observation_effect_id uuid, p_observation_receipt_id uuid, p_observation_request_sha256 bytea, p_observation_started_at timestamp with time zone, p_failure_sha256 bytea, p_observed_at timestamp with time zone, p_retry_at timestamp with time zone, p_code text) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_reconcile_sealed_v1(name, uuid, uuid, uuid, uuid, uuid, bigint, text, uuid, uuid, bytea, timestamp with time zone, text, text, text, text, uuid, uuid, bytea, bytea, bytea, bytea, bigint, bytea, bytea, bigint, timestamp with time zone, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_reconcile_sealed_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_observation_effect_id uuid, p_observation_receipt_id uuid, p_observation_request_sha256 bytea, p_observation_started_at timestamp with time zone, p_object_key text, p_object_version text, p_key_id text, p_artifact_provider_request_id text, p_original_effect_id uuid, p_original_receipt_id uuid, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_original_request_sha256 bytea, p_artifact_result_sha256 bytea, p_ciphertext_bytes bigint, p_wrapped_dek bytea, p_wrap_nonce bytea, p_original_attempt_generation bigint, p_artifact_sealed_at timestamp with time zone, p_observation_provider_request_id text, p_observation_result_sha256 bytea, p_checked_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_replayed boolean;
    v_ready_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR p_resource_kind NOT IN ('users','roles','organizations') OR
       pg_catalog.uuid_extract_version(p_observation_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_observation_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_original_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_original_receipt_id) IS DISTINCT FROM 7 OR
       pg_catalog.octet_length(p_observation_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_object_key) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_object_version) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_key_id) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_artifact_provider_request_id) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_header_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_ciphertext_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_original_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_artifact_result_sha256) IS DISTINCT FROM 32 OR
       p_ciphertext_bytes NOT BETWEEN 1 AND 2148532224 OR
       pg_catalog.octet_length(p_wrapped_dek) NOT BETWEEN 32 AND 1024 OR
       pg_catalog.octet_length(p_wrap_nonce) IS DISTINCT FROM 12 OR
       pg_catalog.octet_length(p_observation_provider_request_id) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_observation_result_sha256) IS DISTINCT FROM 32 OR
       p_original_attempt_generation<1 OR
       NOT pg_catalog.isfinite(p_observation_started_at) OR
       NOT pg_catalog.isfinite(p_artifact_sealed_at) OR
       NOT pg_catalog.isfinite(p_checked_at) OR p_checked_at<p_artifact_sealed_at THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export sealed reconciliation authority is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.resource_kind=p_resource_kind
      AND request.reconciliation_job_id=p_job_id
      AND request.reconciliation_attempt_generation=p_lease_generation
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export sealed reconciliation owner is stale';
    END IF;
    SELECT platform.platform_async_iam_export_reconcile_sealed_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,p_observation_effect_id,
        p_observation_receipt_id,p_observation_request_sha256,
        p_observation_result_sha256,p_observation_provider_request_id,p_checked_at,
        v_request.job_id,p_original_effect_id,p_original_receipt_id,
        p_original_request_sha256,p_artifact_result_sha256,
        p_artifact_provider_request_id,p_artifact_sealed_at
    ) INTO v_replayed;
    IF v_replayed THEN
        IF v_request.state='ready' AND
           v_request.reconciliation_state='resolved_sealed' AND
           v_request.object_key=p_object_key AND
           v_request.object_version=p_object_version AND v_request.key_id=p_key_id AND
           v_request.provider_request_id=p_artifact_provider_request_id AND
           v_request.effect_id=p_original_effect_id AND
           v_request.effect_receipt_id=p_original_receipt_id AND
           v_request.header_sha256=p_header_sha256 AND
           v_request.ciphertext_sha256=p_ciphertext_sha256 AND
           v_request.effect_request_sha256=p_original_request_sha256 AND
           v_request.effect_result_sha256=p_artifact_result_sha256 AND
           v_request.ciphertext_bytes=p_ciphertext_bytes AND
           v_request.wrapped_dek=p_wrapped_dek AND v_request.wrap_nonce=p_wrap_nonce AND
           v_request.attempt_generation=p_original_attempt_generation AND
           v_request.effect_completed_at=p_artifact_sealed_at AND
           v_request.reconciliation_observed_at=p_checked_at THEN RETURN true; END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export sealed owner replay differs';
    END IF;
    IF v_request.state<>'outcome_unknown' OR
       v_request.reconciliation_state<>'running' OR
       v_request.reconciliation_effect_id<>p_observation_effect_id OR
       v_request.reconciliation_receipt_id<>p_observation_receipt_id OR
       v_request.reconciliation_request_sha256<>p_observation_request_sha256 OR
       v_request.reconciliation_started_at<>p_observation_started_at OR
       v_request.effect_id<>p_original_effect_id OR
       v_request.outcome_receipt_id<>p_original_receipt_id OR
       v_request.effect_object_key<>p_object_key OR
       v_request.effect_request_sha256<>p_original_request_sha256 OR
       v_request.key_id<>p_key_id OR v_request.header_sha256<>p_header_sha256 OR
       v_request.ciphertext_sha256<>p_ciphertext_sha256 OR
       v_request.ciphertext_bytes<>p_ciphertext_bytes OR
       v_request.wrapped_dek<>p_wrapped_dek OR v_request.wrap_nonce<>p_wrap_nonce OR
       v_request.attempt_generation<>p_original_attempt_generation OR
       p_checked_at<p_observation_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export sealed owner evidence conflicts';
    END IF;
    v_ready_at := GREATEST(p_artifact_sealed_at,v_request.started_at,
        v_request.effect_started_at);
    UPDATE iam_system_record_exports SET state='ready',failure_code=NULL,
        object_key=p_object_key,object_version=p_object_version,key_id=p_key_id,
        provider_request_id=p_artifact_provider_request_id,
        header_sha256=p_header_sha256,ciphertext_sha256=p_ciphertext_sha256,
        ciphertext_bytes=p_ciphertext_bytes,wrapped_dek=p_wrapped_dek,
        wrap_nonce=p_wrap_nonce,effect_receipt_id=p_original_receipt_id,
        outcome_receipt_id=NULL,effect_result_sha256=p_artifact_result_sha256,
        effect_completed_at=p_artifact_sealed_at,ready_at=v_ready_at,
        expires_at=v_ready_at+interval '24 hours',completed_at=p_checked_at,
        reconciliation_state='resolved_sealed',
        reconciliation_observed_at=p_checked_at,reconciliation_next_at=NULL,
        reconciliation_code='IAM_SYSTEM_EXPORT_ARTIFACT_RECONCILED',
        metadata_retain_until=GREATEST(
            metadata_retain_until,p_checked_at+interval '91 days')
    WHERE export_id=p_export_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_reconcile_sealed_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_observation_effect_id uuid, p_observation_receipt_id uuid, p_observation_request_sha256 bytea, p_observation_started_at timestamp with time zone, p_object_key text, p_object_version text, p_key_id text, p_artifact_provider_request_id text, p_original_effect_id uuid, p_original_receipt_id uuid, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_original_request_sha256 bytea, p_artifact_result_sha256 bytea, p_ciphertext_bytes bigint, p_wrapped_dek bytea, p_wrap_nonce bytea, p_original_attempt_generation bigint, p_artifact_sealed_at timestamp with time zone, p_observation_provider_request_id text, p_observation_result_sha256 bytea, p_checked_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_submit_v1(name, uuid, uuid, uuid, uuid, text, bigint, bigint, bigint, uuid, bytea, bytea, bytea, bytea, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_submit_v1(p_scope_schema name, p_export_id uuid, p_job_id uuid, p_receipt_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_catalog_version_id uuid, p_catalog_sha256 bytea, p_query_document bytea, p_query_sha256 bytea, p_request_sha256 bytea, p_idempotency_sha256 bytea, p_format text, p_created_at timestamp with time zone) RETURNS TABLE(export_id uuid, job_id uuid, resource_kind text, format text, state text, processed_rows bigint, plaintext_bytes bigint, created_at timestamp with time zone, ready_at timestamp with time zone, expires_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_slot smallint;
    v_existing iam_system_record_exports%ROWTYPE;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'export',
        p_token_version,p_authorization_version,true
    ) THEN NULL; END IF;
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('iam-transfer-submit:'||p_actor_id::text,6103)
    );
    SELECT request.* INTO v_existing
    FROM iam_system_record_exports AS request
    WHERE request.actor_id=p_actor_id
      AND request.resource_kind=p_resource_kind
      AND request.idempotency_key_sha256=p_idempotency_sha256;
    IF FOUND THEN
        IF v_existing.tenant_id IS DISTINCT FROM v_tenant_id OR
           v_existing.token_version IS DISTINCT FROM p_token_version OR
           v_existing.authorization_version IS DISTINCT FROM p_authorization_version OR
           v_existing.authorization_clock IS DISTINCT FROM p_authorization_clock OR
           v_existing.catalog_version_id IS DISTINCT FROM p_catalog_version_id OR
           v_existing.catalog_sha256 IS DISTINCT FROM p_catalog_sha256 OR
           v_existing.query_document IS DISTINCT FROM p_query_document OR
           v_existing.query_sha256 IS DISTINCT FROM p_query_sha256 OR
           v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.format IS DISTINCT FROM p_format THEN
            RAISE EXCEPTION USING ERRCODE='P6102',
                MESSAGE='IAM export idempotency conflicts';
        END IF;
        RETURN QUERY SELECT v_existing.export_id,v_existing.job_id,
            v_existing.resource_kind,v_existing.format,v_existing.state,
            v_existing.processed_rows,v_existing.plaintext_bytes,
            v_existing.created_at,v_existing.ready_at,v_existing.expires_at,true;
        RETURN;
    END IF;
    SELECT slot::smallint INTO v_slot
    FROM pg_catalog.generate_series(1,5) AS candidate(slot)
    WHERE NOT EXISTS(
        SELECT 1 FROM iam_system_transfer_admissions AS admission
        WHERE admission.actor_id=p_actor_id AND admission.state='waiting'
          AND admission.principal_wait_slot=candidate.slot
    ) ORDER BY slot LIMIT 1;
    IF v_slot IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6101',
            MESSAGE='IAM transfer waiting capacity exhausted';
    END IF;
    INSERT INTO iam_system_record_exports(
        export_id,tenant_id,job_id,idempotency_receipt_id,resource_kind,actor_id,
        token_version,authorization_version,authorization_clock,catalog_version_id,
        catalog_sha256,query_document,query_sha256,request_sha256,
        idempotency_key_sha256,format,created_at,metadata_retain_until
    ) VALUES(
        p_export_id,v_tenant_id,p_job_id,p_receipt_id,p_resource_kind,p_actor_id,
        p_token_version,p_authorization_version,p_authorization_clock,
        p_catalog_version_id,p_catalog_sha256,p_query_document,p_query_sha256,
        p_request_sha256,p_idempotency_sha256,p_format,p_created_at,
        p_created_at+interval '90 days'
    );
    INSERT INTO iam_system_transfer_admissions(
        transfer_kind,transfer_id,tenant_id,actor_id,state,
        principal_wait_slot,admitted_at
    ) VALUES('export',p_export_id,v_tenant_id,p_actor_id,'waiting',v_slot,p_created_at);
    RETURN QUERY SELECT p_export_id,p_job_id,p_resource_kind,p_format,
        'waiting'::text,0::bigint,0::bigint,p_created_at,
        NULL::timestamptz,NULL::timestamptz,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_submit_v1(p_scope_schema name, p_export_id uuid, p_job_id uuid, p_receipt_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_catalog_version_id uuid, p_catalog_sha256 bytea, p_query_document bytea, p_query_sha256 bytea, p_request_sha256 bytea, p_idempotency_sha256 bytea, p_format text, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_worker_checkpoint_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_worker_checkpoint_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_processed_rows bigint, p_plaintext_bytes bigint, p_checked_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_cancelled boolean;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'export',p_token_version,
        p_authorization_version,true
    ) THEN NULL; END IF;
    IF p_tenant_id IS DISTINCT FROM (
        SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
    ) OR p_processed_rows NOT BETWEEN 0 AND 1000000 OR
       p_plaintext_bytes NOT BETWEEN 0 AND 2147483648 OR
       NOT pg_catalog.isfinite(p_checked_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export checkpoint is invalid';
    END IF;
    SELECT platform.platform_async_iam_export_current_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM export cancellation was requested';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.actor_id=p_actor_id AND request.job_id=p_job_id
      AND request.resource_kind=p_resource_kind
      AND request.token_version=p_token_version
      AND request.authorization_version=p_authorization_version
    FOR UPDATE;
    IF NOT FOUND OR v_request.state<>'running' OR
       v_request.attempt_generation<>p_lease_generation OR
       p_processed_rows<v_request.processed_rows OR
       p_plaintext_bytes<v_request.plaintext_bytes OR
       p_checked_at<v_request.started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export checkpoint lease is stale';
    END IF;
    UPDATE iam_system_record_exports SET processed_rows=p_processed_rows,
        plaintext_bytes=p_plaintext_bytes WHERE export_id=p_export_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_worker_checkpoint_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_processed_rows bigint, p_plaintext_bytes bigint, p_checked_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_worker_claim_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_worker_claim_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint) RETURNS TABLE(state text, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_cancelled boolean;
    v_slot smallint;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'export',p_token_version,
        p_authorization_version,true
    ) THEN NULL; END IF;
    IF p_tenant_id IS DISTINCT FROM (
        SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
    ) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export worker tenant is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.actor_id=p_actor_id AND request.job_id=p_job_id
      AND request.resource_kind=p_resource_kind
      AND request.token_version=p_token_version
      AND request.authorization_version=p_authorization_version
    FOR UPDATE;
    IF NOT FOUND OR v_request.state NOT IN ('waiting','running') THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM export worker request is unavailable';
    END IF;
    SELECT platform.platform_async_iam_export_current_lease_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled OR v_request.state='cancelled' THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM export cancellation was requested';
    END IF;
    IF v_request.state='running' AND
       v_request.attempt_generation=p_lease_generation THEN
        IF NOT EXISTS(
            SELECT 1 FROM iam_system_transfer_admissions AS admission
            WHERE admission.transfer_kind='export'
              AND admission.transfer_id=p_export_id
              AND admission.tenant_id=p_tenant_id AND admission.state='running'
              AND admission.tenant_run_slot BETWEEN 1 AND 2
        ) THEN
            RAISE EXCEPTION USING ERRCODE='P6044',
                MESSAGE='IAM export running admission is invalid';
        END IF;
        RETURN QUERY SELECT 'running'::text,true;
        RETURN;
    END IF;
    IF v_request.attempt_generation IS NOT NULL AND
       v_request.attempt_generation>=p_lease_generation THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM export attempt generation is stale';
    END IF;
    IF v_request.state='waiting' THEN
        SELECT slot::smallint INTO v_slot
        FROM pg_catalog.generate_series(1,2) AS candidate(slot)
        WHERE NOT EXISTS(
            SELECT 1 FROM iam_system_transfer_admissions AS admission
            WHERE admission.tenant_id=p_tenant_id AND admission.state='running'
              AND admission.tenant_run_slot=candidate.slot
        ) ORDER BY slot LIMIT 1;
        IF v_slot IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6101',
                MESSAGE='IAM export tenant run capacity exhausted';
        END IF;
        UPDATE iam_system_transfer_admissions SET state='running',
            tenant_run_slot=v_slot,principal_wait_slot=NULL
        WHERE transfer_kind='export' AND transfer_id=p_export_id
          AND tenant_id=p_tenant_id AND actor_id=p_actor_id AND state='waiting';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6044',
                MESSAGE='IAM export admission was not found';
        END IF;
    END IF;
    UPDATE iam_system_record_exports SET state='running',
        started_at=COALESCE(started_at,pg_catalog.transaction_timestamp()),
        attempt_generation=p_lease_generation,failure_code=NULL,
        effect_id=NULL,effect_lease_owner_id=NULL,effect_object_key=NULL,
        effect_request_sha256=NULL,
        effect_started_at=NULL,effect_receipt_id=NULL,provider_request_id=NULL,
        effect_result_sha256=NULL,effect_completed_at=NULL,outcome_receipt_id=NULL
    WHERE export_id=p_export_id;
    RETURN QUERY SELECT 'running'::text,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_worker_claim_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_worker_complete_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, bigint, bigint, timestamp with time zone, text, text, text, text, uuid, uuid, bytea, bytea, bytea, bytea, bigint, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_worker_complete_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_processed_rows bigint, p_plaintext_bytes bigint, p_checked_at timestamp with time zone, p_object_key text, p_object_version text, p_key_id text, p_provider_request_id text, p_effect_id uuid, p_effect_receipt_id uuid, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_request_sha256 bytea, p_result_sha256 bytea, p_ciphertext_bytes bigint, p_wrapped_dek bytea, p_wrap_nonce bytea, p_sealed_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_replayed boolean;
BEGIN
    IF p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR p_processed_rows NOT BETWEEN 0 AND 1000000 OR
       p_plaintext_bytes NOT BETWEEN 0 AND 2147483648 OR
       pg_catalog.octet_length(p_object_key) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_object_version) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_key_id) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_provider_request_id) NOT BETWEEN 1 AND 512 OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_id=p_effect_receipt_id OR
       pg_catalog.octet_length(p_header_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_ciphertext_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
       p_ciphertext_bytes NOT BETWEEN 1 AND 2148532224 OR
       pg_catalog.octet_length(p_wrapped_dek) NOT BETWEEN 32 AND 1024 OR
       pg_catalog.octet_length(p_wrap_nonce) IS DISTINCT FROM 12 OR
       NOT pg_catalog.isfinite(p_checked_at) OR NOT pg_catalog.isfinite(p_sealed_at) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export completion is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.actor_id=p_actor_id AND request.job_id=p_job_id
      AND request.resource_kind=p_resource_kind
      AND request.token_version=p_token_version
      AND request.authorization_version=p_authorization_version
    FOR UPDATE;
    IF NOT FOUND OR v_request.attempt_generation<>p_lease_generation THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export completion owner is stale';
    END IF;
    IF v_request.state='ready' THEN
        SELECT platform.platform_async_iam_export_succeed_v1(
            p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
            p_lease_generation,p_resource_kind,p_effect_id,p_effect_receipt_id,
            p_request_sha256,p_result_sha256,p_provider_request_id,p_sealed_at
        ) INTO v_replayed;
        IF v_replayed AND v_request.processed_rows=p_processed_rows AND
           v_request.plaintext_bytes=p_plaintext_bytes AND
           v_request.object_key=p_object_key AND
           v_request.object_version=p_object_version AND v_request.key_id=p_key_id AND
           v_request.provider_request_id=p_provider_request_id AND
           v_request.effect_id=p_effect_id AND
           v_request.effect_receipt_id=p_effect_receipt_id AND
           v_request.header_sha256=p_header_sha256 AND
           v_request.ciphertext_sha256=p_ciphertext_sha256 AND
           v_request.effect_request_sha256=p_request_sha256 AND
           v_request.effect_result_sha256=p_result_sha256 AND
           v_request.ciphertext_bytes=p_ciphertext_bytes AND
           v_request.wrapped_dek=p_wrapped_dek AND
           v_request.wrap_nonce=p_wrap_nonce AND v_request.ready_at=p_sealed_at THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export completion replay differs';
    END IF;
    IF v_request.state<>'running' OR
       v_request.effect_id IS DISTINCT FROM p_effect_id OR
       v_request.effect_receipt_id IS DISTINCT FROM p_effect_receipt_id OR
       v_request.effect_object_key IS DISTINCT FROM p_object_key OR
       v_request.effect_request_sha256 IS DISTINCT FROM p_request_sha256 OR
       v_request.key_id IS DISTINCT FROM p_key_id OR
       v_request.header_sha256 IS DISTINCT FROM p_header_sha256 OR
       v_request.ciphertext_sha256 IS DISTINCT FROM p_ciphertext_sha256 OR
       v_request.ciphertext_bytes IS DISTINCT FROM p_ciphertext_bytes OR
       v_request.wrapped_dek IS DISTINCT FROM p_wrapped_dek OR
       v_request.wrap_nonce IS DISTINCT FROM p_wrap_nonce OR
       p_processed_rows<v_request.processed_rows OR
       p_plaintext_bytes<v_request.plaintext_bytes OR
       p_checked_at<v_request.started_at OR p_sealed_at<p_checked_at OR
       p_sealed_at<v_request.effect_started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export completion evidence conflicts';
    END IF;
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'export',p_token_version,
        p_authorization_version,true
    ) THEN NULL; END IF;
    SELECT platform.platform_async_iam_export_succeed_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,p_effect_id,p_effect_receipt_id,
        p_request_sha256,p_result_sha256,p_provider_request_id,p_sealed_at
    ) INTO v_replayed;
    IF v_replayed THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export platform completion conflicts';
    END IF;
    UPDATE iam_system_transfer_admissions SET state='released',
        tenant_run_slot=NULL,principal_wait_slot=NULL,released_at=p_sealed_at
    WHERE transfer_kind='export' AND transfer_id=p_export_id
      AND tenant_id=p_tenant_id AND actor_id=p_actor_id AND state='running';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export running admission is unavailable';
    END IF;
    UPDATE iam_system_record_exports SET state='ready',failure_code=NULL,
        processed_rows=p_processed_rows,plaintext_bytes=p_plaintext_bytes,
        object_key=p_object_key,object_version=p_object_version,key_id=p_key_id,
        provider_request_id=p_provider_request_id,header_sha256=p_header_sha256,
        ciphertext_sha256=p_ciphertext_sha256,ciphertext_bytes=p_ciphertext_bytes,
        wrapped_dek=p_wrapped_dek,wrap_nonce=p_wrap_nonce,
        effect_result_sha256=p_result_sha256,effect_completed_at=p_sealed_at,
        ready_at=p_sealed_at,
        expires_at=p_sealed_at+interval '24 hours',completed_at=p_sealed_at
    WHERE export_id=p_export_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_worker_complete_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_processed_rows bigint, p_plaintext_bytes bigint, p_checked_at timestamp with time zone, p_object_key text, p_object_version text, p_key_id text, p_provider_request_id text, p_effect_id uuid, p_effect_receipt_id uuid, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_request_sha256 bytea, p_result_sha256 bytea, p_ciphertext_bytes bigint, p_wrapped_dek bytea, p_wrap_nonce bytea, p_sealed_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_worker_effect_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, uuid, uuid, text, text, bytea, bytea, bigint, bytea, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_worker_effect_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_effect_id uuid, p_effect_receipt_id uuid, p_object_key text, p_key_id text, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_ciphertext_bytes bigint, p_wrapped_dek bytea, p_wrap_nonce bytea, p_request_sha256 bytea, p_started_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_replayed boolean;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'export',p_token_version,
        p_authorization_version,true
    ) THEN NULL; END IF;
    IF p_tenant_id IS DISTINCT FROM (
        SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
    ) OR pg_catalog.uuid_extract_version(p_effect_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_receipt_id=p_effect_id OR
       pg_catalog.octet_length(p_object_key) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_key_id) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_header_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_ciphertext_sha256) IS DISTINCT FROM 32 OR
       p_ciphertext_bytes NOT BETWEEN 1 AND 2148532224 OR
       pg_catalog.octet_length(p_wrapped_dek) NOT BETWEEN 32 AND 1024 OR
       pg_catalog.octet_length(p_wrap_nonce) IS DISTINCT FROM 12 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_started_at) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export effect authority is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.actor_id=p_actor_id AND request.job_id=p_job_id
      AND request.resource_kind=p_resource_kind
      AND request.token_version=p_token_version
      AND request.authorization_version=p_authorization_version
    FOR UPDATE;
    IF NOT FOUND OR v_request.state<>'running' OR
       v_request.attempt_generation<>p_lease_generation THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export effect owner is stale';
    END IF;
    SELECT platform.platform_async_iam_export_effect_start_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,p_effect_id,p_effect_receipt_id,
        p_request_sha256,p_started_at
    ) INTO v_replayed;
    IF v_request.effect_started_at IS NOT NULL THEN
        IF v_replayed AND v_request.effect_id=p_effect_id AND
           v_request.effect_lease_owner_id=p_lease_owner_id AND
           v_request.effect_receipt_id=p_effect_receipt_id AND
           v_request.effect_object_key=p_object_key AND
           v_request.key_id=p_key_id AND
           v_request.header_sha256=p_header_sha256 AND
           v_request.ciphertext_sha256=p_ciphertext_sha256 AND
           v_request.ciphertext_bytes=p_ciphertext_bytes AND
           v_request.wrapped_dek=p_wrapped_dek AND
           v_request.wrap_nonce=p_wrap_nonce AND
           v_request.effect_request_sha256=p_request_sha256 AND
           v_request.effect_started_at=p_started_at THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export effect replay differs';
    END IF;
    IF v_replayed OR p_effect_id<>p_attempt_id OR
       p_started_at<v_request.started_at THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export effect state conflicts';
    END IF;
    UPDATE iam_system_record_exports SET effect_id=p_effect_id,
        effect_lease_owner_id=p_lease_owner_id,
        effect_receipt_id=p_effect_receipt_id,effect_object_key=p_object_key,
        key_id=p_key_id,header_sha256=p_header_sha256,
        ciphertext_sha256=p_ciphertext_sha256,ciphertext_bytes=p_ciphertext_bytes,
        wrapped_dek=p_wrapped_dek,wrap_nonce=p_wrap_nonce,
        effect_request_sha256=p_request_sha256,effect_started_at=p_started_at
    WHERE export_id=p_export_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_worker_effect_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_effect_id uuid, p_effect_receipt_id uuid, p_object_key text, p_key_id text, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_ciphertext_bytes bigint, p_wrapped_dek bytea, p_wrap_nonce bytea, p_request_sha256 bytea, p_started_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_worker_finish_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_worker_finish_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_state text, p_code text, p_finished_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_target_state text;
    v_failure_class text;
    v_digest bytea;
    v_replayed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR p_resource_kind NOT IN ('users','roles','organizations') OR
       p_state NOT IN ('failed','cancelled') OR
       p_code !~ '^[A-Z][A-Z0-9_]{1,63}$' OR
       NOT pg_catalog.isfinite(p_finished_at) OR
       (p_state='cancelled' AND p_code<>'IAM_SYSTEM_EXPORT_CANCELLED') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export finish authority is invalid';
    END IF;
    v_target_state := p_state;
    v_failure_class := CASE
        WHEN p_state='cancelled' THEN 'cancelled'
        WHEN p_code='IAM_SYSTEM_EXPORT_DEPENDENCY_UNAVAILABLE' THEN 'transient'
        WHEN p_code='IAM_SYSTEM_EXPORT_STATE_CONFLICT' THEN 'conflict'
        ELSE 'permanent'
    END;
    IF v_failure_class='transient' AND p_lease_generation<>3 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM export transient failure is not terminal';
    END IF;
    v_digest := pg_catalog.sha256(pg_catalog.convert_to(p_code,'UTF8'));
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.actor_id=p_actor_id AND request.job_id=p_job_id
      AND request.resource_kind=p_resource_kind
      AND request.token_version=p_token_version
      AND request.authorization_version=p_authorization_version
      AND request.attempt_generation=p_lease_generation
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export finish owner is stale';
    END IF;
    SELECT platform.platform_async_iam_export_finish_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,v_failure_class,p_code,v_digest,
        p_finished_at
    ) INTO v_replayed;
    IF v_replayed THEN
        IF v_request.state=v_target_state AND v_request.failure_code=p_code AND
           v_request.completed_at=p_finished_at AND
           v_request.effect_receipt_id IS NULL THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export finish replay differs';
    END IF;
    IF (v_target_state='failed' AND v_request.state<>'running') OR
       (v_target_state='cancelled' AND v_request.state NOT IN ('running','cancelled')) OR
       p_finished_at<v_request.started_at OR
       (v_request.effect_started_at IS NOT NULL AND
        p_finished_at<v_request.effect_started_at) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export finish state conflicts';
    END IF;
    UPDATE iam_system_transfer_admissions SET state='released',
        tenant_run_slot=NULL,principal_wait_slot=NULL,released_at=p_finished_at
    WHERE transfer_kind='export' AND transfer_id=p_export_id
      AND tenant_id=p_tenant_id AND actor_id=p_actor_id AND state='running';
    IF NOT FOUND AND NOT EXISTS(
        SELECT 1 FROM iam_system_transfer_admissions AS admission
        WHERE admission.transfer_kind='export' AND admission.transfer_id=p_export_id
          AND admission.tenant_id=p_tenant_id AND admission.actor_id=p_actor_id
          AND admission.state='released'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export finish admission is unavailable';
    END IF;
    UPDATE iam_system_record_exports SET state=v_target_state,
        failure_code=p_code,object_key=NULL,object_version=NULL,
        header_sha256=NULL,ciphertext_sha256=NULL,ciphertext_bytes=NULL,
        key_id=NULL,wrapped_dek=NULL,wrap_nonce=NULL,effect_receipt_id=NULL,
        provider_request_id=NULL,effect_result_sha256=NULL,
        effect_completed_at=NULL,outcome_receipt_id=NULL,ready_at=NULL,expires_at=NULL,
        completed_at=p_finished_at,metadata_retain_until=GREATEST(
            metadata_retain_until,p_finished_at+CASE WHEN v_target_state='failed'
                THEN interval '366 days' ELSE interval '91 days' END)
    WHERE export_id=p_export_id;
    RETURN false;
END;
$_$;


