--
-- Name: iam_system_record_export_worker_load_v1(name, uuid, uuid, uuid, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_worker_load_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_resource_kind text) RETURNS TABLE(actor_id uuid, token_version bigint, authorization_version bigint, catalog_version_id uuid, catalog_sha256 bytea, query_document bytea, query_sha256 bytea, format text, state text, attempt_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
BEGIN
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       v_tenant_id IS DISTINCT FROM p_tenant_id OR
       pg_catalog.uuid_extract_version(p_export_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       p_resource_kind NOT IN ('users','roles','organizations') THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export worker load scope is invalid';
    END IF;
    RETURN QUERY
    SELECT request.actor_id,request.token_version,
        request.authorization_version,request.catalog_version_id,
        request.catalog_sha256,request.query_document,request.query_sha256,
        request.format,request.state,request.attempt_generation
    FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.job_id=p_job_id AND request.resource_kind=p_resource_kind;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM export worker request was not found';
    END IF;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_worker_load_v1(p_scope_schema name, p_tenant_id uuid, p_export_id uuid, p_job_id uuid, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: iam_system_record_export_worker_unknown_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, uuid, uuid, text, text, bytea, bytea, bigint, bytea, bytea, bytea, timestamp with time zone, boolean, text, text, bytea, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_export_worker_unknown_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_effect_id uuid, p_effect_receipt_id uuid, p_object_key text, p_key_id text, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_ciphertext_bytes bigint, p_wrapped_dek bytea, p_wrap_nonce bytea, p_request_sha256 bytea, p_started_at timestamp with time zone, p_artifact_known boolean, p_object_version text, p_provider_request_id text, p_result_sha256 bytea, p_sealed_at timestamp with time zone, p_unknown_at timestamp with time zone, p_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_exports%ROWTYPE;
    v_replayed boolean;
    v_reconciliation_job_id uuid;
    v_enqueue_replayed boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR p_resource_kind NOT IN ('users','roles','organizations') OR
       pg_catalog.uuid_extract_version(p_effect_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_effect_receipt_id) IS DISTINCT FROM 7 OR
       p_effect_id=p_effect_receipt_id OR
       pg_catalog.octet_length(p_object_key) NOT BETWEEN 1 AND 512 OR
       pg_catalog.octet_length(p_key_id) NOT BETWEEN 1 AND 128 OR
       pg_catalog.octet_length(p_header_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_ciphertext_sha256) IS DISTINCT FROM 32 OR
       p_ciphertext_bytes NOT BETWEEN 1 AND 2148532224 OR
       pg_catalog.octet_length(p_wrapped_dek) NOT BETWEEN 32 AND 1024 OR
       pg_catalog.octet_length(p_wrap_nonce) IS DISTINCT FROM 12 OR
       pg_catalog.octet_length(p_request_sha256) IS DISTINCT FROM 32 OR
       NOT pg_catalog.isfinite(p_started_at) OR
       NOT pg_catalog.isfinite(p_unknown_at) OR p_unknown_at<p_started_at OR
       p_code<>'JOB_OUTCOME_UNKNOWN' OR p_artifact_known IS NULL OR
       (p_artifact_known AND (
           pg_catalog.octet_length(p_object_version) NOT BETWEEN 1 AND 512 OR
           pg_catalog.octet_length(p_provider_request_id) NOT BETWEEN 1 AND 512 OR
           pg_catalog.octet_length(p_result_sha256) IS DISTINCT FROM 32 OR
           NOT pg_catalog.isfinite(p_sealed_at) OR p_sealed_at<p_started_at OR
           p_unknown_at<p_sealed_at)) OR
       (NOT p_artifact_known AND (p_object_version IS NOT NULL OR
           p_provider_request_id IS NOT NULL OR p_result_sha256 IS NOT NULL OR
           p_sealed_at IS NOT NULL)) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM export unknown authority is invalid';
    END IF;
    SELECT request.* INTO v_request FROM iam_system_record_exports AS request
    WHERE request.export_id=p_export_id AND request.tenant_id=p_tenant_id
      AND request.actor_id=p_actor_id AND request.job_id=p_job_id
      AND request.resource_kind=p_resource_kind
      AND request.token_version=p_token_version
      AND request.authorization_version=p_authorization_version
      AND request.attempt_generation=p_lease_generation
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6047',
            MESSAGE='IAM export unknown owner is stale';
    END IF;
    SELECT platform.platform_async_iam_export_unknown_v1(
        p_tenant_id,p_export_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind,p_effect_id,p_request_sha256,p_unknown_at
    ) INTO v_replayed;
    SELECT enqueued.job_id,enqueued.replayed
    INTO v_reconciliation_job_id,v_enqueue_replayed
    FROM platform.platform_async_iam_export_reconcile_enqueue_v1(
        p_tenant_id,p_export_id,p_job_id,p_resource_kind,p_unknown_at
    ) AS enqueued;
    IF v_replayed THEN
        IF v_request.state='outcome_unknown' AND
           v_request.failure_code='JOB_OUTCOME_UNKNOWN' AND
           v_request.effect_id=p_effect_id AND
           v_request.effect_lease_owner_id=p_lease_owner_id AND
           v_request.outcome_receipt_id=p_effect_receipt_id AND
           v_request.effect_object_key=p_object_key AND
           v_request.effect_request_sha256=p_request_sha256 AND
           v_request.effect_started_at=p_started_at AND
           v_request.key_id=p_key_id AND v_request.header_sha256=p_header_sha256 AND
           v_request.ciphertext_sha256=p_ciphertext_sha256 AND
           v_request.ciphertext_bytes=p_ciphertext_bytes AND
           v_request.wrapped_dek=p_wrapped_dek AND v_request.wrap_nonce=p_wrap_nonce AND
           v_request.completed_at=p_unknown_at AND
           v_request.reconciliation_job_id=v_reconciliation_job_id AND
           v_enqueue_replayed AND
           ((NOT p_artifact_known AND v_request.object_key IS NULL AND
             v_request.object_version IS NULL AND v_request.provider_request_id IS NULL AND
             v_request.effect_result_sha256 IS NULL AND
             v_request.effect_completed_at IS NULL) OR
            (p_artifact_known AND v_request.object_key=p_object_key AND
             v_request.object_version=p_object_version AND
             v_request.provider_request_id=p_provider_request_id AND
             v_request.effect_result_sha256=p_result_sha256 AND
             v_request.effect_completed_at=p_sealed_at)) THEN
            RETURN true;
        END IF;
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export unknown replay differs';
    END IF;
    IF v_request.state NOT IN ('running','cancelled') OR
       v_request.effect_id IS DISTINCT FROM p_effect_id OR
       v_request.effect_lease_owner_id IS DISTINCT FROM p_lease_owner_id OR
       v_request.effect_receipt_id IS DISTINCT FROM p_effect_receipt_id OR
       v_request.effect_object_key IS DISTINCT FROM p_object_key OR
       v_request.effect_request_sha256 IS DISTINCT FROM p_request_sha256 OR
       v_request.effect_started_at IS DISTINCT FROM p_started_at OR
       v_request.key_id IS DISTINCT FROM p_key_id OR
       v_request.header_sha256 IS DISTINCT FROM p_header_sha256 OR
       v_request.ciphertext_sha256 IS DISTINCT FROM p_ciphertext_sha256 OR
       v_request.ciphertext_bytes IS DISTINCT FROM p_ciphertext_bytes OR
       v_request.wrapped_dek IS DISTINCT FROM p_wrapped_dek OR
       v_request.wrap_nonce IS DISTINCT FROM p_wrap_nonce THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export unknown evidence conflicts';
    END IF;
    UPDATE iam_system_transfer_admissions SET state='released',
        tenant_run_slot=NULL,principal_wait_slot=NULL,released_at=p_unknown_at
    WHERE transfer_kind='export' AND transfer_id=p_export_id
      AND tenant_id=p_tenant_id AND actor_id=p_actor_id AND state='running';
    IF NOT FOUND AND NOT EXISTS(
        SELECT 1 FROM iam_system_transfer_admissions AS admission
        WHERE admission.transfer_kind='export' AND admission.transfer_id=p_export_id
          AND admission.tenant_id=p_tenant_id AND admission.actor_id=p_actor_id
          AND admission.state='released'
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6048',
            MESSAGE='IAM export unknown admission is unavailable';
    END IF;
    UPDATE iam_system_record_exports SET state='outcome_unknown',
        failure_code='JOB_OUTCOME_UNKNOWN',effect_receipt_id=NULL,
        outcome_receipt_id=p_effect_receipt_id,
        object_key=CASE WHEN p_artifact_known THEN p_object_key END,
        object_version=CASE WHEN p_artifact_known THEN p_object_version END,
        provider_request_id=CASE WHEN p_artifact_known THEN p_provider_request_id END,
        effect_result_sha256=CASE WHEN p_artifact_known THEN p_result_sha256 END,
        effect_completed_at=CASE WHEN p_artifact_known THEN p_sealed_at END,
        ready_at=NULL,expires_at=NULL,completed_at=p_unknown_at,
        reconciliation_job_id=v_reconciliation_job_id,
        reconciliation_state='queued',reconciliation_attempt_generation=NULL,
        reconciliation_effect_id=NULL,reconciliation_receipt_id=NULL,
        reconciliation_request_sha256=NULL,reconciliation_started_at=NULL,
        reconciliation_observed_at=NULL,reconciliation_next_at=NULL,
        reconciliation_code=NULL,
        metadata_retain_until=GREATEST(
            metadata_retain_until,p_unknown_at+interval '366 days')
    WHERE export_id=p_export_id;
    RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_export_worker_unknown_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_export_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_effect_id uuid, p_effect_receipt_id uuid, p_object_key text, p_key_id text, p_header_sha256 bytea, p_ciphertext_sha256 bytea, p_ciphertext_bytes bigint, p_wrapped_dek bytea, p_wrap_nonce bytea, p_request_sha256 bytea, p_started_at timestamp with time zone, p_artifact_known boolean, p_object_version text, p_provider_request_id text, p_result_sha256 bytea, p_sealed_at timestamp with time zone, p_unknown_at timestamp with time zone, p_code text) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_cancel_v1(name, uuid, uuid, text, bigint, bigint, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_cancel_v1(p_scope_schema name, p_import_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_now timestamp with time zone) RETURNS TABLE(import_id uuid, job_id uuid, resource_kind text, state text, processed_rows bigint, created_rows bigint, updated_rows bigint, skipped_rows bigint, rejected_rows bigint, created_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_import iam_system_record_imports%ROWTYPE;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',
        p_token_version,p_authorization_version,true
    ) THEN NULL; END IF;
    SELECT request.* INTO v_import
    FROM iam_system_record_imports AS request
    WHERE request.import_id=p_import_id AND request.actor_id=p_actor_id
      AND request.resource_kind=p_resource_kind
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='IAM import is unavailable';
    END IF;
    IF v_import.state IN ('waiting','running') THEN
        UPDATE iam_system_record_imports SET state='cancelled',completed_at=p_now
        WHERE iam_system_record_imports.import_id=p_import_id;
        UPDATE iam_system_transfer_admissions
        SET state='released',tenant_run_slot=NULL,principal_wait_slot=NULL,
            released_at=p_now
        WHERE transfer_kind='import' AND transfer_id=p_import_id
          AND state IN ('waiting','running');
        v_import.state := 'cancelled';
        v_import.completed_at := p_now;
    ELSIF v_import.state<>'cancelled' THEN
        RAISE EXCEPTION USING ERRCODE='P6102',
            MESSAGE='IAM import cannot be cancelled';
    END IF;
    RETURN QUERY SELECT v_import.import_id,v_import.job_id,
        v_import.resource_kind,v_import.state,v_import.processed_rows,
        v_import.created_rows,v_import.updated_rows,v_import.skipped_rows,
        v_import.rejected_rows,v_import.created_at,v_import.completed_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_cancel_v1(p_scope_schema name, p_import_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_read_v1(name, uuid, uuid, text, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_read_v1(p_scope_schema name, p_import_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint) RETURNS TABLE(import_id uuid, job_id uuid, resource_kind text, state text, processed_rows bigint, created_rows bigint, updated_rows bigint, skipped_rows bigint, rejected_rows bigint, created_at timestamp with time zone, completed_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',
        p_token_version,p_authorization_version,false
    ) THEN NULL; END IF;
    RETURN QUERY
    SELECT request.import_id,request.job_id,request.resource_kind,request.state,
        request.processed_rows,request.created_rows,request.updated_rows,
        request.skipped_rows,request.rejected_rows,request.created_at,
        request.completed_at
    FROM iam_system_record_imports AS request
    WHERE request.import_id=p_import_id AND request.actor_id=p_actor_id
      AND request.resource_kind=p_resource_kind;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_read_v1(p_scope_schema name, p_import_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_receipts_v1(name, uuid, uuid, text, bigint, bigint, bigint, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_receipts_v1(p_scope_schema name, p_import_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_after_row bigint, p_limit integer) RETURNS TABLE(row_index bigint, outcome text, owner_kind text, owner_id uuid, error_code text, source_sha256 bytea, result_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_import_exists boolean;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',
        p_token_version,p_authorization_version,false
    ) THEN NULL; END IF;
    IF p_after_row NOT BETWEEN 0 AND 1000000 OR
       p_limit NOT BETWEEN 1 AND 101 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM import receipt page is invalid';
    END IF;
    SELECT EXISTS(
        SELECT 1 FROM iam_system_record_imports AS request
        WHERE request.import_id=p_import_id AND request.actor_id=p_actor_id
          AND request.resource_kind=p_resource_kind
    ) INTO v_import_exists;
    IF NOT v_import_exists THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='IAM import is unavailable';
    END IF;
    RETURN QUERY
    SELECT receipt.row_index,receipt.outcome,receipt.owner_kind,
        receipt.owner_id,receipt.error_code,receipt.source_sha256,
        receipt.result_sha256
    FROM iam_system_import_row_receipts AS receipt
    WHERE receipt.import_id=p_import_id AND receipt.row_index>p_after_row
    ORDER BY receipt.row_index
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_receipts_v1(p_scope_schema name, p_import_id uuid, p_actor_id uuid, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_after_row bigint, p_limit integer) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_submit_v1(name, uuid, uuid, uuid, uuid, text, uuid, bigint, bigint, bigint, uuid, bytea, bytea, bytea, bytea, text, bytea, bytea, integer, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_submit_v1(p_scope_schema name, p_import_id uuid, p_job_id uuid, p_receipt_id uuid, p_actor_id uuid, p_resource_kind text, p_source_id uuid, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_catalog_version_id uuid, p_catalog_sha256 bytea, p_identity_manifest_sha256 bytea, p_request_sha256 bytea, p_idempotency_sha256 bytea, p_duplicate_action text, p_mapping_document bytea, p_mapping_sha256 bytea, p_field_count integer, p_created_at timestamp with time zone) RETURNS TABLE(import_id uuid, job_id uuid, resource_kind text, state text, processed_rows bigint, created_rows bigint, updated_rows bigint, skipped_rows bigint, rejected_rows bigint, created_at timestamp with time zone, completed_at timestamp with time zone, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_slot smallint;
    v_existing iam_system_record_imports%ROWTYPE;
    v_source iam_system_import_sources%ROWTYPE;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',
        p_token_version,p_authorization_version,true
    ) THEN NULL; END IF;
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('iam-transfer-submit:'||p_actor_id::text,6103)
    );
    SELECT request.* INTO v_existing
    FROM iam_system_record_imports AS request
    WHERE request.actor_id=p_actor_id
      AND request.resource_kind=p_resource_kind
      AND request.idempotency_key_sha256=p_idempotency_sha256;
    IF FOUND THEN
        IF v_existing.tenant_id IS DISTINCT FROM v_tenant_id OR
           v_existing.source_id IS DISTINCT FROM p_source_id OR
           v_existing.token_version IS DISTINCT FROM p_token_version OR
           v_existing.authorization_version IS DISTINCT FROM p_authorization_version OR
           v_existing.authorization_clock IS DISTINCT FROM p_authorization_clock OR
           v_existing.catalog_version_id IS DISTINCT FROM p_catalog_version_id OR
           v_existing.catalog_sha256 IS DISTINCT FROM p_catalog_sha256 OR
           v_existing.identity_manifest_sha256 IS DISTINCT FROM p_identity_manifest_sha256 OR
           v_existing.request_sha256 IS DISTINCT FROM p_request_sha256 OR
           v_existing.duplicate_action IS DISTINCT FROM p_duplicate_action OR
           v_existing.mapping_document IS DISTINCT FROM p_mapping_document OR
           v_existing.mapping_sha256 IS DISTINCT FROM p_mapping_sha256 OR
           v_existing.field_count IS DISTINCT FROM p_field_count THEN
            RAISE EXCEPTION USING ERRCODE='P6102',
                MESSAGE='IAM import idempotency conflicts';
        END IF;
        RETURN QUERY SELECT v_existing.import_id,v_existing.job_id,
            v_existing.resource_kind,v_existing.state,v_existing.processed_rows,
            v_existing.created_rows,v_existing.updated_rows,v_existing.skipped_rows,
            v_existing.rejected_rows,v_existing.created_at,v_existing.completed_at,true;
        RETURN;
    END IF;
    SELECT source.* INTO v_source
    FROM iam_system_import_sources AS source
    WHERE source.source_id=p_source_id AND source.tenant_id=v_tenant_id
      AND source.actor_id=p_actor_id AND source.resource_kind=p_resource_kind
      AND source.state='ready' AND source.delete_after>p_created_at
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P0002',
            MESSAGE='IAM import source is unavailable';
    END IF;
    SELECT slot::smallint INTO v_slot
    FROM pg_catalog.generate_series(1,5) AS candidate(slot)
    WHERE NOT EXISTS(
        SELECT 1 FROM iam_system_transfer_admissions AS admission
        WHERE admission.actor_id=p_actor_id AND admission.state='waiting'
          AND admission.principal_wait_slot=candidate.slot
    ) ORDER BY slot LIMIT 1;
    IF v_slot IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='P6101',
            MESSAGE='IAM transfer waiting capacity exhausted';
    END IF;
    INSERT INTO iam_system_record_imports(
        import_id,tenant_id,job_id,idempotency_receipt_id,resource_kind,actor_id,
        source_id,token_version,authorization_version,authorization_clock,
        catalog_version_id,catalog_sha256,identity_manifest_sha256,request_sha256,
        idempotency_key_sha256,duplicate_action,mapping_document,mapping_sha256,
        field_count,created_at,metadata_retain_until
    ) VALUES(
        p_import_id,v_tenant_id,p_job_id,p_receipt_id,p_resource_kind,p_actor_id,
        p_source_id,p_token_version,p_authorization_version,p_authorization_clock,
        p_catalog_version_id,p_catalog_sha256,p_identity_manifest_sha256,
        p_request_sha256,p_idempotency_sha256,p_duplicate_action,p_mapping_document,
        p_mapping_sha256,p_field_count,p_created_at,p_created_at+interval '90 days'
    );
    UPDATE iam_system_import_sources SET state='claimed',
        claimed_import_id=p_import_id,claimed_at=p_created_at
    WHERE source_id=p_source_id AND state='ready';
    INSERT INTO iam_system_transfer_admissions(
        transfer_kind,transfer_id,tenant_id,actor_id,state,
        principal_wait_slot,admitted_at
    ) VALUES('import',p_import_id,v_tenant_id,p_actor_id,'waiting',v_slot,p_created_at);
    RETURN QUERY SELECT p_import_id,p_job_id,p_resource_kind,'waiting'::text,
        0::bigint,0::bigint,0::bigint,0::bigint,0::bigint,p_created_at,
        NULL::timestamptz,false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_submit_v1(p_scope_schema name, p_import_id uuid, p_job_id uuid, p_receipt_id uuid, p_actor_id uuid, p_resource_kind text, p_source_id uuid, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_catalog_version_id uuid, p_catalog_sha256 bytea, p_identity_manifest_sha256 bytea, p_request_sha256 bytea, p_idempotency_sha256 bytea, p_duplicate_action text, p_mapping_document bytea, p_mapping_sha256 bytea, p_field_count integer, p_created_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_worker_claim_v1(name, uuid, uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_worker_claim_v1(p_scope_schema name, p_tenant_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) RETURNS TABLE(actor_id uuid, resource_kind text, authorization_version bigint, duplicate_action text, mapping_document bytea, next_row_index bigint, processed_rows bigint, source_id uuid, source_format text, object_key text, object_version text, header_sha256 bytea, ciphertext_sha256 bytea, ciphertext_bytes bigint, plaintext_sha256 bytea, plaintext_bytes bigint, key_id text, wrapped_dek bytea, wrap_nonce bytea, provider_request_id text, uploaded_at timestamp with time zone, finished boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_tenant_id uuid;
    v_request iam_system_record_imports%ROWTYPE;
    v_source iam_system_import_sources%ROWTYPE;
    v_cancelled boolean;
    v_slot smallint;
BEGIN
    SELECT identity.tenant_id INTO STRICT v_tenant_id
    FROM tenancy_schema_identity AS identity
    WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema();
    IF p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       v_tenant_id IS DISTINCT FROM p_tenant_id OR
       pg_catalog.uuid_extract_version(p_import_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_job_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_attempt_id) IS DISTINCT FROM 7 OR
       pg_catalog.uuid_extract_version(p_lease_owner_id) IS DISTINCT FROM 7 OR
       p_lease_generation NOT BETWEEN 1 AND 8 THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM import worker claim scope is invalid';
    END IF;
    SELECT request.* INTO v_request
    FROM iam_system_record_imports AS request
    WHERE request.import_id=p_import_id AND request.tenant_id=p_tenant_id
      AND request.job_id=p_job_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import worker request was not found';
    END IF;
    SELECT platform.platform_async_iam_import_current_lease_v1(
        p_tenant_id,p_import_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,v_request.resource_kind
    ) INTO v_cancelled;
    IF v_cancelled OR v_request.state='cancelled' THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM import cancellation was requested';
    END IF;
    IF v_request.state NOT IN ('waiting','running','completed') THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import is not executable';
    END IF;
    SELECT source.* INTO STRICT v_source
    FROM iam_system_import_sources AS source
    WHERE source.source_id=v_request.source_id
      AND source.tenant_id=p_tenant_id
      AND source.actor_id=v_request.actor_id
      AND source.resource_kind=v_request.resource_kind
      AND source.claimed_import_id=p_import_id AND source.state='claimed'
    FOR SHARE;
    IF v_request.state='waiting' THEN
        SELECT slot::smallint INTO v_slot
        FROM pg_catalog.generate_series(1,2) AS candidate(slot)
        WHERE NOT EXISTS(
            SELECT 1 FROM iam_system_transfer_admissions AS admission
            WHERE admission.tenant_id=p_tenant_id AND admission.state='running'
              AND admission.tenant_run_slot=candidate.slot
        ) ORDER BY slot LIMIT 1;
        IF v_slot IS NULL THEN
            RAISE EXCEPTION USING ERRCODE='P6101',
                MESSAGE='IAM import tenant run capacity exhausted';
        END IF;
        UPDATE iam_system_transfer_admissions
        SET state='running',tenant_run_slot=v_slot,principal_wait_slot=NULL
        WHERE transfer_kind='import' AND transfer_id=p_import_id
          AND tenant_id=p_tenant_id AND actor_id=v_request.actor_id
          AND state='waiting';
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE='P6044',
                MESSAGE='IAM import admission was not found';
        END IF;
        UPDATE iam_system_record_imports
        SET state='running',started_at=COALESCE(started_at,transaction_timestamp())
        WHERE import_id=p_import_id;
        v_request.state := 'running';
    ELSIF v_request.state='running' AND NOT EXISTS(
        SELECT 1 FROM iam_system_transfer_admissions AS admission
        WHERE admission.transfer_kind='import' AND admission.transfer_id=p_import_id
          AND admission.tenant_id=p_tenant_id AND admission.state='running'
          AND admission.tenant_run_slot BETWEEN 1 AND 2
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import running admission is invalid';
    END IF;
    RETURN QUERY SELECT v_request.actor_id,v_request.resource_kind,
        v_request.authorization_version,v_request.duplicate_action,
        v_request.mapping_document,v_request.next_row_index,
        v_request.processed_rows,v_source.source_id,v_source.format,
        v_source.object_key,v_source.object_version,v_source.header_sha256,
        v_source.ciphertext_sha256,v_source.ciphertext_bytes,
        v_source.plaintext_sha256,v_source.plaintext_bytes,v_source.key_id,
        v_source.wrapped_dek,v_source.wrap_nonce,v_source.provider_request_id,
        v_source.uploaded_at,v_request.state='completed';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_worker_claim_v1(p_scope_schema name, p_tenant_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_worker_claim_v2(name, uuid, uuid, uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_worker_claim_v2(p_scope_schema name, p_tenant_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) RETURNS TABLE(actor_id uuid, resource_kind text, authorization_version bigint, duplicate_action text, mapping_document bytea, next_row_index bigint, processed_rows bigint, source_id uuid, source_format text, object_key text, object_version text, header_sha256 bytea, ciphertext_sha256 bytea, ciphertext_bytes bigint, plaintext_sha256 bytea, plaintext_bytes bigint, key_id text, wrapped_dek bytea, wrap_nonce bytea, provider_request_id text, uploaded_at timestamp with time zone, finished boolean, catalog_version_id uuid, catalog_sha256 bytea, identity_manifest_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_actor_id uuid;
    v_resource_kind text;
    v_authorization_version bigint;
    v_duplicate_action text;
    v_mapping_document bytea;
    v_next_row_index bigint;
    v_processed_rows bigint;
    v_source_id uuid;
    v_source_format text;
    v_object_key text;
    v_object_version text;
    v_header_sha256 bytea;
    v_ciphertext_sha256 bytea;
    v_ciphertext_bytes bigint;
    v_plaintext_sha256 bytea;
    v_plaintext_bytes bigint;
    v_key_id text;
    v_wrapped_dek bytea;
    v_wrap_nonce bytea;
    v_provider_request_id text;
    v_uploaded_at timestamptz;
    v_finished boolean;
    v_catalog_version_id uuid;
    v_catalog_sha256 bytea;
    v_identity_manifest_sha256 bytea;
BEGIN
    SELECT claim_result.actor_id,claim_result.resource_kind,
           claim_result.authorization_version,claim_result.duplicate_action,
           claim_result.mapping_document,claim_result.next_row_index,
           claim_result.processed_rows,claim_result.source_id,
           claim_result.source_format,claim_result.object_key,
           claim_result.object_version,claim_result.header_sha256,
           claim_result.ciphertext_sha256,claim_result.ciphertext_bytes,
           claim_result.plaintext_sha256,claim_result.plaintext_bytes,
           claim_result.key_id,claim_result.wrapped_dek,
           claim_result.wrap_nonce,claim_result.provider_request_id,
           claim_result.uploaded_at,claim_result.finished
    INTO STRICT v_actor_id,v_resource_kind,v_authorization_version,
                v_duplicate_action,v_mapping_document,v_next_row_index,
                v_processed_rows,v_source_id,v_source_format,v_object_key,
                v_object_version,v_header_sha256,v_ciphertext_sha256,
                v_ciphertext_bytes,v_plaintext_sha256,v_plaintext_bytes,
                v_key_id,v_wrapped_dek,v_wrap_nonce,v_provider_request_id,
                v_uploaded_at,v_finished
    FROM iam_system_record_import_worker_claim_v1(
        p_scope_schema,p_tenant_id,p_import_id,p_job_id,p_attempt_id,
        p_lease_owner_id,p_lease_generation
    ) AS claim_result;

    SELECT request.catalog_version_id,request.catalog_sha256,
           request.identity_manifest_sha256
    INTO STRICT v_catalog_version_id,v_catalog_sha256,
                v_identity_manifest_sha256
    FROM iam_system_record_imports AS request
    WHERE request.import_id=p_import_id
      AND request.tenant_id=p_tenant_id
      AND request.job_id=p_job_id
      AND request.actor_id=v_actor_id
      AND request.resource_kind=v_resource_kind;

    RETURN QUERY SELECT
        v_actor_id,v_resource_kind,v_authorization_version,v_duplicate_action,
        v_mapping_document,v_next_row_index,v_processed_rows,v_source_id,
        v_source_format,v_object_key,v_object_version,v_header_sha256,
        v_ciphertext_sha256,v_ciphertext_bytes,v_plaintext_sha256,
        v_plaintext_bytes,v_key_id,v_wrapped_dek,v_wrap_nonce,
        v_provider_request_id,v_uploaded_at,v_finished,v_catalog_version_id,
        v_catalog_sha256,v_identity_manifest_sha256;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_worker_claim_v2(p_scope_schema name, p_tenant_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_worker_commit_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, jsonb, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_worker_commit_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_receipts jsonb, p_source_bytes bigint) RETURNS TABLE(next_row_index bigint, processed_rows bigint, created_rows bigint, updated_rows bigint, skipped_rows bigint, rejected_rows bigint, decompressed_bytes bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_request iam_system_record_imports%ROWTYPE;
    v_cancelled boolean;
    v_count integer;
    v_created integer;
    v_updated integer;
    v_skipped integer;
    v_rejected integer;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',p_token_version,
        p_authorization_version,true
    ) THEN NULL; END IF;
    IF p_tenant_id IS DISTINCT FROM (
        SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
    ) OR pg_catalog.jsonb_typeof(p_receipts) IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(p_receipts) NOT BETWEEN 1 AND 1000 OR
       pg_catalog.octet_length(p_receipts::text) > 1048576 OR
       p_source_bytes NOT BETWEEN 2 AND 1073741824 OR EXISTS(
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_receipts) AS item
           WHERE pg_catalog.jsonb_typeof(item) IS DISTINCT FROM 'object'
              OR (SELECT pg_catalog.count(*)
                  FROM pg_catalog.jsonb_object_keys(item)) <> 8
              OR NOT item ?& ARRAY['row_index','outcome','owner_kind','owner_id',
                  'owner_revision','error_code','source_sha256','result_sha256']
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM import worker commit document is invalid';
    END IF;
    SELECT platform.platform_async_iam_import_current_lease_v1(
        p_tenant_id,p_import_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM import cancellation was requested';
    END IF;
    SELECT request.* INTO v_request
    FROM iam_system_record_imports AS request
    WHERE request.import_id=p_import_id AND request.tenant_id=p_tenant_id
      AND request.actor_id=p_actor_id AND request.job_id=p_job_id
      AND request.resource_kind=p_resource_kind
      AND request.authorization_version=p_authorization_version
    FOR UPDATE;
    IF NOT FOUND OR v_request.state IS DISTINCT FROM 'running' THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import worker request is not running';
    END IF;
    WITH decoded AS (
        SELECT * FROM pg_catalog.jsonb_to_recordset(p_receipts) AS receipt(
            row_index bigint,outcome text,owner_kind text,owner_id uuid,
            owner_revision bigint,error_code text,source_sha256 text,
            result_sha256 text
        )
    )
    SELECT pg_catalog.count(*)::integer,
        pg_catalog.count(*) FILTER(WHERE outcome='created')::integer,
        pg_catalog.count(*) FILTER(WHERE outcome='updated')::integer,
        pg_catalog.count(*) FILTER(WHERE outcome='skipped')::integer,
        pg_catalog.count(*) FILTER(WHERE outcome='rejected')::integer
    INTO v_count,v_created,v_updated,v_skipped,v_rejected
    FROM decoded
    HAVING pg_catalog.count(*)=pg_catalog.count(DISTINCT row_index)
       AND pg_catalog.min(row_index)=v_request.next_row_index
       AND pg_catalog.max(row_index)=v_request.next_row_index+
           pg_catalog.count(*)-1
       AND pg_catalog.bool_and(row_index BETWEEN 1 AND 1000000)
       AND pg_catalog.bool_and(source_sha256 ~ '^[0-9a-f]{64}$')
       AND pg_catalog.bool_and(result_sha256 ~ '^[0-9a-f]{64}$')
       AND pg_catalog.bool_and(
           (outcome IN ('created','updated') AND
            owner_kind IN ('record','invitation') AND owner_id IS NOT NULL AND
            owner_revision BETWEEN 1 AND 9007199254740991 AND error_code IS NULL)
           OR (outcome='skipped' AND owner_kind IS NULL AND owner_id IS NULL AND
               owner_revision IS NULL AND error_code IS NULL)
           OR (outcome='rejected' AND owner_kind IS NULL AND owner_id IS NULL AND
               owner_revision IS NULL AND error_code ~ '^[A-Z][A-Z0-9_]{1,63}$')
       )
       AND pg_catalog.bool_and(result_sha256=pg_catalog.encode(
           pg_catalog.sha256(pg_catalog.convert_to(
               'iam.system-transfer.receipt-result.v1'||pg_catalog.chr(0)||
               outcome||pg_catalog.chr(0)||COALESCE(owner_kind,'')||
               pg_catalog.chr(0)||COALESCE(owner_id::text,
                   '00000000-0000-0000-0000-000000000000')||
               pg_catalog.chr(0)||COALESCE(owner_revision,0)::text||
               pg_catalog.chr(0)||COALESCE(error_code,''),'UTF8'
           )),'hex'
       ));
    IF v_count IS NULL OR v_request.processed_rows+v_count>1000000 OR
       v_request.rejected_rows+v_rejected>10000 OR
       v_request.decompressed_bytes+p_source_bytes>2147483648 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM import worker commit exceeds bounded progress';
    END IF;
    INSERT INTO iam_system_import_row_receipts(
        import_id,job_id,row_index,outcome,owner_kind,owner_id,error_code,
        source_sha256,result_sha256,owner_revision,committed_at
    )
    SELECT p_import_id,p_job_id,receipt.row_index,receipt.outcome,
        receipt.owner_kind,receipt.owner_id,receipt.error_code,
        pg_catalog.decode(receipt.source_sha256,'hex'),
        pg_catalog.decode(receipt.result_sha256,'hex'),receipt.owner_revision,
        pg_catalog.transaction_timestamp()
    FROM pg_catalog.jsonb_to_recordset(p_receipts) AS receipt(
        row_index bigint,outcome text,owner_kind text,owner_id uuid,
        owner_revision bigint,error_code text,source_sha256 text,result_sha256 text
    ) ORDER BY receipt.row_index;
    UPDATE iam_system_record_imports AS request
    SET next_row_index=request.next_row_index+v_count,
        processed_rows=request.processed_rows+v_count,
        created_rows=request.created_rows+v_created,
        updated_rows=request.updated_rows+v_updated,
        skipped_rows=request.skipped_rows+v_skipped,
        rejected_rows=request.rejected_rows+v_rejected,
        decompressed_bytes=request.decompressed_bytes+p_source_bytes
    WHERE request.import_id=p_import_id
    RETURNING request.* INTO v_request;
    RETURN QUERY SELECT v_request.next_row_index,v_request.processed_rows,
        v_request.created_rows,v_request.updated_rows,v_request.skipped_rows,
        v_request.rejected_rows,v_request.decompressed_bytes;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_worker_commit_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_receipts jsonb, p_source_bytes bigint) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_worker_finish_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_worker_finish_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_success boolean) RETURNS TABLE(state text, processed_rows bigint, created_rows bigint, updated_rows bigint, skipped_rows bigint, rejected_rows bigint, decompressed_bytes bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_request iam_system_record_imports%ROWTYPE;
    v_cancelled boolean;
    v_target_state text;
BEGIN
    IF p_scope_schema::text IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS DISTINCT FROM (
           SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
       ) OR p_resource_kind NOT IN ('users','roles','organizations') OR
       p_actor_id IS NULL OR p_authorization_version<1 OR p_success IS NULL OR
       (p_success AND p_token_version<1) OR
       (NOT p_success AND p_token_version<>0) THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM import worker finish scope is invalid';
    END IF;
    SELECT platform.platform_async_iam_import_current_lease_v1(
        p_tenant_id,p_import_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM import cancellation was requested';
    END IF;
    SELECT request.* INTO v_request
    FROM iam_system_record_imports AS request
    WHERE request.import_id=p_import_id AND request.tenant_id=p_tenant_id
      AND request.job_id=p_job_id AND request.resource_kind=p_resource_kind
      AND request.actor_id=p_actor_id
      AND request.authorization_version=p_authorization_version
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import worker request was not found';
    END IF;
    v_target_state := CASE WHEN p_success THEN 'completed' ELSE 'failed' END;
    IF p_success AND NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',p_token_version,
        p_authorization_version,true
    ) THEN NULL; END IF;
    IF v_request.state=v_target_state THEN
        RETURN QUERY SELECT v_request.state,v_request.processed_rows,
            v_request.created_rows,v_request.updated_rows,v_request.skipped_rows,
            v_request.rejected_rows,v_request.decompressed_bytes;
        RETURN;
    END IF;
    IF (p_success AND v_request.state<>'running') OR
       (NOT p_success AND v_request.state NOT IN ('waiting','running')) THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import worker terminal transition is invalid';
    END IF;
    UPDATE iam_system_transfer_admissions AS admission
    SET state='released',tenant_run_slot=NULL,principal_wait_slot=NULL,
        released_at=pg_catalog.transaction_timestamp()
    WHERE admission.transfer_kind='import' AND admission.transfer_id=p_import_id
      AND admission.tenant_id=p_tenant_id AND admission.state IN ('waiting','running');
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import worker admission was not found';
    END IF;
    UPDATE iam_system_record_imports AS request
    SET state=v_target_state,
        completed_at=pg_catalog.transaction_timestamp()
    WHERE request.import_id=p_import_id
    RETURNING request.* INTO v_request;
    RETURN QUERY SELECT v_request.state,v_request.processed_rows,
        v_request.created_rows,v_request.updated_rows,v_request.skipped_rows,
        v_request.rejected_rows,v_request.decompressed_bytes;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_worker_finish_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_success boolean) OWNER TO harpy_owner;

--
-- Name: iam_system_record_import_worker_receipts_v1(name, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, bigint, bigint, bigint[]); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_record_import_worker_receipts_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_row_indexes bigint[]) RETURNS TABLE(row_index bigint, outcome text, owner_kind text, owner_id uuid, owner_revision bigint, error_code text, source_sha256 bytea, result_sha256 bytea)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_cancelled boolean;
BEGIN
    IF NOT iam_system_transfer_assert_v1(
        p_scope_schema,p_actor_id,p_resource_kind,'import',p_token_version,
        p_authorization_version,true
    ) THEN NULL; END IF;
    IF p_tenant_id IS DISTINCT FROM (
        SELECT identity.tenant_id FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.schema_name=pg_catalog.current_schema()
    ) OR pg_catalog.cardinality(p_row_indexes) NOT BETWEEN 1 AND 1000 OR
       EXISTS(
           SELECT 1 FROM pg_catalog.unnest(p_row_indexes) AS wanted(row_index)
           WHERE wanted.row_index NOT BETWEEN 1 AND 1000000
       ) OR (
           SELECT pg_catalog.count(*) FROM pg_catalog.unnest(p_row_indexes)
       ) IS DISTINCT FROM (
           SELECT pg_catalog.count(DISTINCT wanted.row_index)
           FROM pg_catalog.unnest(p_row_indexes) AS wanted(row_index)
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='IAM import worker receipt request is invalid';
    END IF;
    SELECT platform.platform_async_iam_import_current_lease_v1(
        p_tenant_id,p_import_id,p_job_id,p_attempt_id,p_lease_owner_id,
        p_lease_generation,p_resource_kind
    ) INTO v_cancelled;
    IF v_cancelled THEN
        RAISE EXCEPTION USING ERRCODE='P6046',
            MESSAGE='IAM import cancellation was requested';
    END IF;
    IF NOT EXISTS(
        SELECT 1 FROM iam_system_record_imports AS request
        WHERE request.import_id=p_import_id AND request.tenant_id=p_tenant_id
          AND request.actor_id=p_actor_id AND request.job_id=p_job_id
          AND request.resource_kind=p_resource_kind
          AND request.authorization_version=p_authorization_version
          AND request.state IN ('running','completed')
    ) THEN
        RAISE EXCEPTION USING ERRCODE='P6044',
            MESSAGE='IAM import worker request is unavailable';
    END IF;
    RETURN QUERY
    SELECT receipt.row_index,receipt.outcome,receipt.owner_kind,
        receipt.owner_id,receipt.owner_revision,receipt.error_code,
        receipt.source_sha256,receipt.result_sha256
    FROM iam_system_import_row_receipts AS receipt
    WHERE receipt.import_id=p_import_id
      AND receipt.job_id=p_job_id
      AND receipt.row_index=ANY(p_row_indexes)
    ORDER BY receipt.row_index;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_record_import_worker_receipts_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_import_id uuid, p_job_id uuid, p_attempt_id uuid, p_lease_owner_id uuid, p_lease_generation bigint, p_resource_kind text, p_token_version bigint, p_authorization_version bigint, p_row_indexes bigint[]) OWNER TO harpy_owner;

--
-- Name: iam_system_transfer_assert_v1(name, uuid, text, text, bigint, bigint, boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_system_transfer_assert_v1(p_scope_schema name, p_actor_id uuid, p_resource_kind text, p_action text, p_token_version bigint, p_authorization_version bigint, p_command boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_permission_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('users','roles','organizations') OR
       p_action NOT IN ('import','export') OR p_command IS NULL THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='IAM system transfer authority is invalid';
    END IF;
    SELECT permission.id INTO STRICT v_permission_id
    FROM iam_permissions AS permission
    JOIN iam_resources AS resource ON resource.id=permission.resource_id
    JOIN iam_actions AS action ON action.id=permission.action_id
    WHERE resource.resource_key='iam.'||p_resource_kind
      AND resource.owner_domain='iam' AND resource.state='active'
      AND action.action_key=p_action AND action.state='active'
      AND permission.match_kind='exact' AND permission.is_protected
      AND permission.state='active';
    IF p_command THEN
        RETURN iam_identity_actor_assert_v1(
            p_scope_schema,p_actor_id,v_permission_id,
            p_token_version,p_authorization_version
        );
    END IF;
    RETURN iam_identity_query_assert_v1(
        p_scope_schema,p_actor_id,v_permission_id,
        p_token_version,p_authorization_version
    );
EXCEPTION WHEN NO_DATA_FOUND OR TOO_MANY_ROWS THEN
    RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='IAM system transfer authority is unavailable';
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_system_transfer_assert_v1(p_scope_schema name, p_actor_id uuid, p_resource_kind text, p_action text, p_token_version bigint, p_authorization_version bigint, p_command boolean) OWNER TO harpy_owner;

--
-- Name: iam_totp_enrollment_complete_v1(name, uuid, uuid, bytea, uuid, uuid, text, bytea, bytea, bigint, bigint, bigint, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_totp_enrollment_complete_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_challenge_id uuid, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_expected_authenticator_revision bigint, p_expected_challenge_revision bigint, p_accepted_time_step bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_current_step bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    v_current_step := pg_catalog.floor(
        pg_catalog.date_part('epoch', v_now) / 30
    )::bigint;
    IF p_authenticator_id IS NULL OR p_challenge_id IS NULL OR
       p_expected_authenticator_revision < 1 OR p_expected_challenge_revision < 1 OR
       p_accepted_time_step NOT BETWEEN v_current_step - 1 AND v_current_step + 1 OR
       pg_catalog.octet_length(p_challenge_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_context_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.totp_enrollment.complete',
        p_request_sha256, p_authenticator_id
    );
    IF FOUND THEN RETURN; END IF;
    IF p_actor_id IS NULL OR NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT authenticator.user_id INTO v_user_id
    FROM iam_authenticators AS authenticator
    WHERE authenticator.id = p_authenticator_id
      AND authenticator.user_id = p_actor_id
      AND authenticator.kind = 'totp_v1'
      AND authenticator.state = 'pending'
      AND authenticator.revision = p_expected_authenticator_revision
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '40001'; END IF;
    PERFORM 1 FROM iam_auth_challenges AS challenge
    WHERE challenge.id = p_challenge_id
      AND challenge.user_id = v_user_id
      AND challenge.authenticator_id = p_authenticator_id
      AND challenge.purpose = 'totp_enroll_v1'
      AND challenge.state = 'pending'
      AND challenge.revision = p_expected_challenge_revision
      AND challenge.expires_at > v_now
      AND challenge.hmac_key_id = p_hmac_key_id
      AND challenge.challenge_hmac = p_challenge_hmac
      AND challenge.context_sha256 = p_context_sha256
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '28000'; END IF;
    UPDATE iam_totp_authenticators SET verified_at = v_now,
        last_accepted_time_step = p_accepted_time_step,
        revision = revision + 1, updated_at = v_now
    WHERE authenticator_id = p_authenticator_id
      AND verified_at IS NULL AND enrollment_expires_at > v_now;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '40001'; END IF;
    UPDATE iam_auth_challenges SET state = 'consumed', terminal_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = p_challenge_id;
    UPDATE iam_authenticators SET state = 'active', activated_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = p_authenticator_id RETURNING revision INTO v_revision;
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.totp_enrollment.complete', p_request_sha256,
        p_authenticator_id, v_user_id, v_revision,
        'actor_tenant', p_actor_id, 'authenticator', true, true
    ) AS result;
    RETURN QUERY SELECT p_authenticator_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_totp_enrollment_complete_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_challenge_id uuid, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_expected_authenticator_revision bigint, p_expected_challenge_revision bigint, p_accepted_time_step bigint, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_totp_enrollment_read_v1(name, uuid, uuid, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_totp_enrollment_read_v1(p_scope_schema name, p_authenticator_id uuid, p_challenge_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(user_id uuid, kms_key_id text, nonce bytea, secret_ciphertext bytea, authentication_tag bytea, aad_sha256 bytea, authenticator_revision bigint, challenge_hmac_key_id text, challenge_hmac bytea, context_sha256 bytea, challenge_revision bigint, enrollment_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF p_authenticator_id IS NULL OR p_challenge_id IS NULL OR
       NOT iam_identity_actor_assert_v1(
          p_scope_schema, p_actor_id, p_permission_id,
          p_expected_token_version, p_expected_authorization_version
       ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    RETURN QUERY
    SELECT authenticator.user_id, totp.kms_key_id, totp.nonce,
        totp.secret_ciphertext, totp.authentication_tag, totp.aad_sha256,
        authenticator.revision, challenge.hmac_key_id,
        challenge.challenge_hmac, challenge.context_sha256,
        challenge.revision, totp.enrollment_expires_at
    FROM iam_authenticators AS authenticator
    JOIN iam_totp_authenticators AS totp
      ON totp.authenticator_id = authenticator.id
     AND totp.user_id = authenticator.user_id
    JOIN iam_auth_challenges AS challenge
      ON challenge.id = p_challenge_id
     AND challenge.authenticator_id = authenticator.id
     AND challenge.user_id = authenticator.user_id
    WHERE authenticator.id = p_authenticator_id
      AND authenticator.user_id = p_actor_id
      AND authenticator.kind = 'totp_v1'
      AND authenticator.state = 'pending'
      AND challenge.purpose = 'totp_enroll_v1'
      AND challenge.state = 'pending'
      AND challenge.expires_at > pg_catalog.transaction_timestamp()
      AND totp.enrollment_expires_at > pg_catalog.transaction_timestamp();
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_totp_enrollment_read_v1(p_scope_schema name, p_authenticator_id uuid, p_challenge_id uuid, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_totp_enrollment_start_v1(name, uuid, uuid, bytea, uuid, uuid, uuid, uuid, text, text, bytea, bytea, bytea, bytea, text, bytea, bytea, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_totp_enrollment_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_display_label text, p_kms_key_id text, p_nonce bytea, p_secret_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_authenticator_id IS NULL OR p_challenge_id IS NULL OR
       p_user_id IS NULL OR p_session_id IS NULL OR
       pg_catalog.octet_length(p_nonce) IS DISTINCT FROM 12 OR
       pg_catalog.octet_length(p_secret_ciphertext) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_authentication_tag) IS DISTINCT FROM 16 OR
       pg_catalog.octet_length(p_aad_sha256) IS DISTINCT FROM 32 OR
       p_hmac_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_challenge_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_context_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.totp_enrollment.start',
        p_request_sha256, p_authenticator_id
    );
    IF FOUND THEN RETURN; END IF;
    IF p_user_id <> p_actor_id OR NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM iam_sessions AS session
        WHERE session.id = p_session_id AND session.user_id = p_user_id
          AND session.state = 'active' AND session.absolute_expires_at > v_now
        FOR UPDATE
    ) THEN RAISE EXCEPTION USING ERRCODE = '28000'; END IF;
    INSERT INTO iam_authenticators (
        id, user_id, kind, display_label, state, revision, created_at, updated_at
    ) VALUES (
        p_authenticator_id, p_user_id, 'totp_v1', p_display_label,
        'pending', 1, v_now, v_now
    );
    INSERT INTO iam_totp_authenticators (
        authenticator_id, user_id, authenticator_kind, profile, cipher_suite,
        kms_key_id, nonce, secret_ciphertext, authentication_tag, aad_sha256,
        enrollment_expires_at, revision, created_at, updated_at
    ) VALUES (
        p_authenticator_id, p_user_id, 'totp_v1', 'totp_sha256_6_30_v1',
        'aes_256_gcm_v1', p_kms_key_id, p_nonce, p_secret_ciphertext,
        p_authentication_tag, p_aad_sha256, v_now + INTERVAL '10 minutes',
        1, v_now, v_now
    );
    INSERT INTO iam_auth_challenges (
        id, user_id, session_id, authenticator_id, authenticator_kind,
        purpose, proof_kind, hash_profile, hmac_key_id, challenge_hmac,
        context_sha256, state, attempt_count, revision, issued_at, expires_at,
        purge_after, created_at, updated_at
    ) VALUES (
        p_challenge_id, p_user_id, p_session_id, p_authenticator_id, 'totp_v1',
        'totp_enroll_v1', 'totp_v1', 'hmac_sha256_v1', p_hmac_key_id,
        p_challenge_hmac, p_context_sha256, 'pending', 0, 1, v_now,
        v_now + INTERVAL '5 minutes', v_now + INTERVAL '1 day 5 minutes',
        v_now, v_now
    );
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.totp_enrollment.start', p_request_sha256,
        p_authenticator_id, p_user_id, 1, 'actor_tenant', p_actor_id,
        'authenticator', false, false
    ) AS result;
    RETURN QUERY SELECT p_authenticator_id, p_user_id, 1::bigint,
        v_token_version, v_authorization_version, false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_totp_enrollment_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_display_label text, p_kms_key_id text, p_nonce bytea, p_secret_ciphertext bytea, p_authentication_tag bytea, p_aad_sha256 bytea, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_user_has_permission_v1(uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_user_has_permission_v1(p_user_id uuid, p_permission_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
RETURN (WITH target AS (
    SELECT permission.id, permission.resource_id, permission.action_id
    FROM iam_permissions AS permission
    JOIN iam_resources AS resource ON resource.id = permission.resource_id
    JOIN iam_actions AS action ON action.id = permission.action_id
    WHERE permission.id OPERATOR(pg_catalog.=) p_permission_id
      AND permission.match_kind OPERATOR(pg_catalog.=) 'exact'
      AND permission.state OPERATOR(pg_catalog.=) 'active'
      AND resource.state OPERATOR(pg_catalog.=) 'active'
      AND action.state OPERATOR(pg_catalog.=) 'active'
), relevant AS (
    SELECT target.id FROM target
    UNION
    SELECT implication.source_permission_id
    FROM iam_permission_implications AS implication
    JOIN target ON target.id = implication.implied_permission_id
    WHERE implication.state OPERATOR(pg_catalog.=) 'active'
    UNION
    SELECT permission.id
    FROM iam_permissions AS permission
    JOIN target ON target.resource_id = permission.resource_id
    WHERE permission.match_kind OPERATOR(pg_catalog.=) 'resource_all_actions'
      AND permission.state OPERATOR(pg_catalog.=) 'active'
    UNION
    SELECT permission.id FROM iam_permissions AS permission
    WHERE permission.match_kind OPERATOR(pg_catalog.=) 'tenant_all'
      AND permission.state OPERATOR(pg_catalog.=) 'active'
), direct_allow AS (
    SELECT binding.id
    FROM iam_user_permission_bindings AS binding
    JOIN relevant ON relevant.id = binding.permission_id
    JOIN iam_permissions AS permission ON permission.id = binding.permission_id
    LEFT JOIN iam_resources AS resource ON resource.id = permission.resource_id
    LEFT JOIN iam_actions AS action ON action.id = permission.action_id
    WHERE binding.user_id OPERATOR(pg_catalog.=) p_user_id
      AND binding.state OPERATOR(pg_catalog.=) 'active'
      AND permission.state OPERATOR(pg_catalog.=) 'active'
      AND (resource.id IS NULL OR resource.state OPERATOR(pg_catalog.=) 'active')
      AND (action.id IS NULL OR action.state OPERATOR(pg_catalog.=) 'active')
), role_allow AS (
    SELECT binding.id
    FROM iam_user_role_assignments AS assignment
    JOIN iam_roles AS role ON role.id = assignment.role_id
    JOIN iam_role_permission_bindings AS binding ON binding.role_id = role.id
    JOIN relevant ON relevant.id = binding.permission_id
    JOIN iam_permissions AS permission ON permission.id = binding.permission_id
    LEFT JOIN iam_organization_memberships AS membership
        ON membership.id = assignment.membership_id
    LEFT JOIN iam_organizations AS organization
        ON organization.id = assignment.organization_id
    LEFT JOIN iam_protected_admin_policies AS policy ON policy.role_id = role.id
    WHERE assignment.user_id OPERATOR(pg_catalog.=) p_user_id
      AND assignment.state OPERATOR(pg_catalog.=) 'active'
      AND role.status OPERATOR(pg_catalog.=) 'active'
      AND binding.state OPERATOR(pg_catalog.=) 'active'
      AND permission.state OPERATOR(pg_catalog.=) 'active'
      AND (
          role.scope_kind OPERATOR(pg_catalog.=) 'tenant' OR
          (role.scope_kind OPERATOR(pg_catalog.=) 'organization' AND
              membership.state OPERATOR(pg_catalog.=) 'active' AND
              organization.status OPERATOR(pg_catalog.=) 'active')
      )
      AND (
          permission.match_kind OPERATOR(pg_catalog.=) 'exact' OR
          (permission.match_kind OPERATOR(pg_catalog.=) 'resource_all_actions' AND
              role.is_protected AND policy.policy_state OPERATOR(pg_catalog.=) 'active') OR
          (permission.match_kind OPERATOR(pg_catalog.=) 'tenant_all' AND
              role.is_protected AND policy.policy_state OPERATOR(pg_catalog.=) 'active' AND
              policy.tenant_all_permission_id = permission.id AND
              policy.role_permission_binding_id = binding.id)
      )
), organization_allow AS (
    SELECT binding.id
    FROM iam_organization_memberships AS membership
    JOIN iam_organizations AS organization ON organization.id = membership.organization_id
    JOIN iam_organization_permission_bindings AS binding
        ON binding.organization_id = organization.id
    JOIN relevant ON relevant.id = binding.permission_id
    JOIN iam_permissions AS permission ON permission.id = binding.permission_id
    WHERE membership.user_id OPERATOR(pg_catalog.=) p_user_id
      AND membership.state OPERATOR(pg_catalog.=) 'active'
      AND organization.status OPERATOR(pg_catalog.=) 'active'
      AND binding.state OPERATOR(pg_catalog.=) 'active'
      AND permission.state OPERATOR(pg_catalog.=) 'active'
)
SELECT EXISTS (
    SELECT 1 FROM iam_users AS principal
    WHERE principal.id OPERATOR(pg_catalog.=) p_user_id
      AND principal.status OPERATOR(pg_catalog.=) 'active'
) AND EXISTS (SELECT 1 FROM target) AND (
    EXISTS (SELECT 1 FROM direct_allow) OR
    EXISTS (SELECT 1 FROM role_allow) OR
    EXISTS (SELECT 1 FROM organization_allow)
));
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_user_has_permission_v1(p_user_id uuid, p_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_user_has_rbac_evidence_v2(uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_user_has_rbac_evidence_v2(p_user_id uuid, p_permission_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF iam_user_has_permission_v1(p_user_id, p_permission_id) THEN
        RETURN true;
    END IF;

    RETURN EXISTS (
        SELECT 1
        FROM iam_permissions AS permission
        JOIN iam_role_permission_bindings AS binding
          ON binding.permission_id = permission.id
        JOIN iam_roles AS role ON role.id = binding.role_id
        JOIN iam_user_role_assignments AS assignment ON assignment.role_id = role.id
        JOIN iam_users AS principal ON principal.id = assignment.user_id
        JOIN iam_protected_admin_policies AS policy ON policy.role_id = role.id
        LEFT JOIN iam_resources AS resource ON resource.id = permission.resource_id
        WHERE principal.id = p_user_id
          AND principal.status = 'active'
          AND permission.id = p_permission_id
          AND permission.is_protected
          AND permission.state = 'active'
          AND binding.state = 'active'
          AND assignment.state = 'active'
          AND role.is_protected
          AND role.status = 'active'
          AND role.scope_kind = 'tenant'
          AND policy.policy_state = 'active'
          AND (
              (
                  permission.match_kind = 'resource_all_actions'
                  AND permission.resource_id IS NOT NULL
                  AND permission.action_id IS NULL
                  AND resource.state = 'active'
              )
              OR
              (
                  permission.match_kind = 'tenant_all'
                  AND permission.resource_id IS NULL
                  AND permission.action_id IS NULL
                  AND policy.tenant_all_permission_id = permission.id
                  AND policy.role_permission_binding_id = binding.id
              )
          )
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_user_has_rbac_evidence_v2(p_user_id uuid, p_permission_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_assertion_authority_v1(name, uuid, uuid, bigint, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_actor_assertion_authority_v1(p_scope_schema name, p_subject_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_authorization_clock bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_clock bigint;
    v_policy_epoch bigint;
    v_status text;
    v_token_version bigint;
    v_authorization_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v1_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 actor assertion scope is invalid';
    END IF;
    IF p_subject_id IS NULL OR p_permission_id IS NULL OR
       p_expected_token_version < 1 OR p_expected_authorization_version < 1 OR
       p_expected_authorization_clock < 0 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 actor assertion evidence is invalid';
    END IF;
    SELECT clock_value INTO v_clock
    FROM iam_authorization_clock WHERE singleton FOR SHARE;
    IF NOT FOUND OR v_clock IS DISTINCT FROM p_expected_authorization_clock THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 actor assertion clock is stale';
    END IF;
    SELECT authorization_epoch INTO v_policy_epoch
    FROM iam_protected_admin_policies WHERE singleton FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 actor assertion policy is unavailable';
    END IF;
    SELECT status, token_version, authorization_version
    INTO v_status, v_token_version, v_authorization_version
    FROM iam_users WHERE id = p_subject_id FOR UPDATE;
    IF NOT FOUND OR v_status IS DISTINCT FROM 'active' OR
       v_token_version IS DISTINCT FROM p_expected_token_version OR
       GREATEST(v_authorization_version, v_policy_epoch)
           IS DISTINCT FROM p_expected_authorization_version OR
       NOT iam_user_has_rbac_evidence_v2(p_subject_id, p_permission_id) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 actor assertion authority is denied';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_actor_assertion_authority_v1(p_scope_schema name, p_subject_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint, p_expected_authorization_clock bigint) OWNER TO harpy_owner;

--
-- Name: iam_v1_actor_assertion_consume_v1(name, uuid, uuid, uuid, uuid, text, text, text, bytea, bytea, bigint, bigint, bigint, bigint, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_actor_assertion_consume_v1(p_scope_schema name, p_tenant_id uuid, p_jti uuid, p_subject_id uuid, p_permission_id uuid, p_target_domain text, p_audience text, p_key_id text, p_permission_decision_sha256 bytea, p_target_binding_sha256 bytea, p_iam_group_generation bigint, p_iam_generation bigint, p_target_generation bigint, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_issued_at bigint, p_expires_at bigint) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
	    v_authorized boolean;
    v_consumed_at timestamptz;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v1_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 actor assertion consume scope is invalid';
    END IF;
    v_authorized := iam_v1_actor_assertion_authority_v1(
        p_scope_schema, p_subject_id, p_permission_id,
        p_token_version, p_authorization_version, p_authorization_clock
    );
    IF NOT v_authorized THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 actor assertion authority is denied';
    END IF;
    SELECT platform.iam_v1_actor_assertion_consume_v1(
        p_tenant_id, p_scope_schema, p_jti, p_subject_id, p_permission_id,
        p_target_domain, p_audience, p_key_id, p_permission_decision_sha256,
        p_target_binding_sha256, p_iam_group_generation, p_iam_generation,
        p_target_generation, p_token_version, p_authorization_version,
        p_authorization_clock, p_issued_at, p_expires_at
    ) INTO STRICT v_consumed_at;
    RETURN v_consumed_at;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_actor_assertion_consume_v1(p_scope_schema name, p_tenant_id uuid, p_jti uuid, p_subject_id uuid, p_permission_id uuid, p_target_domain text, p_audience text, p_key_id text, p_permission_decision_sha256 bytea, p_target_binding_sha256 bytea, p_iam_group_generation bigint, p_iam_generation bigint, p_target_generation bigint, p_token_version bigint, p_authorization_version bigint, p_authorization_clock bigint, p_issued_at bigint, p_expires_at bigint) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_access_record_matches_v1(text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_access_record_matches_v1(p_target_table text, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_match boolean;
BEGIN
    CASE p_target_table
    WHEN 'iam_resources' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_resources, p_record))
        INTO v_match FROM iam_resources AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_actions' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_actions, p_record))
        INTO v_match FROM iam_actions AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_permissions' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_permissions, p_record))
        INTO v_match FROM iam_permissions AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_user_permission_bindings' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_user_permission_bindings, p_record))
        INTO v_match FROM iam_user_permission_bindings AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_role_permission_bindings' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_role_permission_bindings, p_record))
        INTO v_match FROM iam_role_permission_bindings AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_organization_permission_bindings' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_organization_permission_bindings, p_record))
        INTO v_match FROM iam_organization_permission_bindings AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_authorization_clock' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_authorization_clock, p_record))
        INTO v_match FROM iam_authorization_clock AS actual
        WHERE actual.singleton = (p_record->>'singleton')::boolean;
    WHEN 'iam_protected_admin_policies' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_protected_admin_policies, p_record))
        INTO v_match FROM iam_protected_admin_policies AS actual
        WHERE actual.singleton = (p_record->>'singleton')::boolean;
    WHEN 'iam_permission_request_groups' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_permission_request_groups, p_record))
        INTO v_match FROM iam_permission_request_groups AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_permission_requests' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_permission_requests, p_record))
        INTO v_match FROM iam_permission_requests AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_invitations' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_invitations, p_record))
        INTO v_match FROM iam_invitations AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_one_time_tokens' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_one_time_tokens, p_record))
        INTO v_match FROM iam_one_time_tokens AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    ELSE
        RETURN false;
    END CASE;
    RETURN COALESCE(v_match, false);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_access_record_matches_v1(p_target_table text, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract_id text;
    v_procedure_oid bigint;
    v_procedure_signature text;
    v_expected_signature text;
    v_already_applied boolean;
    v_applied_count bigint;
    v_key_sha text;
    v_state_sha text;
    v_asserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 adoption composite principal denied';
    END IF;
    v_batch := iam_v1_adoption_batch_decode_v1(
        p_change_batch_bytes, p_batch_sha256, p_batch_bytes
    );
    v_asserted := iam_v1_adoption_batch_assert_v1(
        v_batch, p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_snapshot_name,
        p_snapshot_lsn, p_received_lsn, p_commit_lsn, p_final_lsn,
        p_source_xid, p_batch_ordinal, p_checkpoint_state, p_last_key
    );
    IF NOT v_asserted THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'IAM V1 adoption batch assertion failed';
    END IF;
    SELECT prepared.procedure_contract_id, prepared.procedure_oid,
        prepared.procedure_signature, prepared.already_applied,
        prepared.applied_count, prepared.key_state_sha256, prepared.state_sha256
    INTO STRICT v_contract_id, v_procedure_oid, v_procedure_signature,
        v_already_applied, v_applied_count, v_key_sha, v_state_sha
    FROM platform.cutover_prepare_batch_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_batch_ordinal,
        p_commit_lsn, p_source_xid, p_batch_sha256, p_lease_manifest_sha256
    ) AS prepared;
    v_expected_signature := pg_catalog.format(
        '%I.iam_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)',
        pg_catalog.current_schema()
    );
    IF v_contract_id IS DISTINCT FROM 'iam.v1_adoption.v1' OR
       v_procedure_oid IS DISTINCT FROM
           'iam_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure_signature IS DISTINCT FROM v_expected_signature THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'IAM V1 adoption procedure binding differs';
    END IF;
    IF v_already_applied THEN
        RETURN QUERY SELECT v_applied_count, v_key_sha, v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count, result.key_state_sha256, result.state_sha256
    INTO STRICT v_applied_count, v_key_sha, v_state_sha
    FROM iam_v1_adoption_apply_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_snapshot_lsn,
        p_received_lsn, p_commit_lsn, p_source_xid, p_batch_ordinal,
        v_batch, p_batch_sha256
    ) AS result;
    IF v_applied_count < 0 OR v_key_sha !~ '^[0-9a-f]{64}$' OR
       v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'IAM V1 adoption owner result is invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id, p_run_id, p_relation_ordinal, p_checkpoint_key,
        p_snapshot_name, p_snapshot_lsn, p_received_lsn, p_commit_lsn,
        p_final_lsn, p_source_xid, p_batch_ordinal, p_checkpoint_state,
        p_last_key, p_batch_sha256, p_batch_bytes, v_applied_count,
        v_key_sha, v_state_sha
    );
    RETURN QUERY SELECT v_applied_count, v_key_sha, v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_change jsonb;
    v_payload jsonb;
    v_rows bigint;
    v_applied bigint;
    v_key_sha text;
    v_state_sha text;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    v_applied := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind IS DISTINCT FROM 'tenant' OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR NOT EXISTS (
           SELECT 1 FROM iam_v1_adoption_runs AS run
           WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
             AND run.tenant_id = p_scope_id AND run.eligible
             AND run.state IN ('planned', 'copying')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 adoption apply authority or plan denied';
    END IF;
    FOR v_change IN
        SELECT value FROM pg_catalog.jsonb_array_elements(p_change_batch->'changes')
            WITH ORDINALITY AS item(value, position)
        ORDER BY position
    LOOP
        v_payload := COALESCE(v_change->'after', v_change->'before');
        INSERT INTO iam_v1_adoption_stage (
            operation_id, run_id, source_category, source_key,
            target_table, target_key, target_record, record_sha256,
            removed, source_xid, batch_ordinal, updated_at
        ) VALUES (
            p_operation_id, p_run_id, v_payload->>'source_category',
            v_payload->>'source_key', v_payload->>'target_table',
            v_payload->>'target_key', v_payload->'target_record',
            pg_catalog.sha256(pg_catalog.convert_to(
                (v_payload->'target_record')::text, 'UTF8'
            )),
            v_change->>'kind' = 'delete', p_source_xid, p_batch_ordinal, v_now
        )
        ON CONFLICT (operation_id, run_id, target_table, target_key) DO UPDATE
        SET source_category = EXCLUDED.source_category,
            source_key = EXCLUDED.source_key,
            target_record = EXCLUDED.target_record,
            record_sha256 = EXCLUDED.record_sha256,
            removed = EXCLUDED.removed,
            source_xid = EXCLUDED.source_xid,
            batch_ordinal = EXCLUDED.batch_ordinal,
            updated_at = EXCLUDED.updated_at
        WHERE iam_v1_adoption_stage.batch_ordinal < EXCLUDED.batch_ordinal;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        v_applied := v_applied + v_rows;
    END LOOP;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(
            stage.target_table || ':' || stage.target_key || ':' ||
            pg_catalog.encode(stage.record_sha256, 'hex') || ':' ||
            stage.removed::text, ',' ORDER BY stage.target_table, stage.target_key
        ), ''), 'UTF8'
    )), 'hex'), pg_catalog.count(*)
    INTO v_key_sha, v_rows
    FROM iam_v1_adoption_stage AS stage
    WHERE stage.operation_id = p_operation_id AND stage.run_id = p_run_id
      AND stage.source_category = p_checkpoint_key AND NOT stage.removed;
    UPDATE iam_v1_adoption_category_evidence
    SET staged_count = v_rows, staged_sha256 = pg_catalog.decode(v_key_sha, 'hex'),
        relation_ordinal = p_relation_ordinal, copy_state = p_change_batch->>'checkpoint_state',
        last_batch_ordinal = p_batch_ordinal, updated_at = v_now
    WHERE operation_id = p_operation_id AND run_id = p_run_id
      AND category = p_checkpoint_key
      AND (relation_ordinal IS NULL OR relation_ordinal = p_relation_ordinal)
      AND (last_batch_ordinal IS NULL OR last_batch_ordinal < p_batch_ordinal)
      AND CASE copy_state
          WHEN 'planned' THEN p_change_batch->>'checkpoint_state'
              IN ('initial_copy', 'delta', 'complete')
          WHEN 'initial_copy' THEN p_change_batch->>'checkpoint_state'
              IN ('delta', 'complete')
          WHEN 'delta' THEN p_change_batch->>'checkpoint_state'
              IN ('delta', 'complete')
          ELSE false
      END;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'IAM V1 adoption category checkpoint regressed';
    END IF;
    UPDATE iam_v1_adoption_runs
    SET state = 'copying', updated_at = v_now
    WHERE operation_id = p_operation_id AND run_id = p_run_id
      AND state IN ('planned', 'copying');
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(
            stage.target_table || ':' || stage.target_key || ':' ||
            pg_catalog.encode(stage.record_sha256, 'hex') || ':' ||
            stage.removed::text, ',' ORDER BY stage.target_table, stage.target_key
        ), ''), 'UTF8'
    )), 'hex')
    INTO v_state_sha
    FROM iam_v1_adoption_stage AS stage
    WHERE stage.operation_id = p_operation_id AND stage.run_id = p_run_id
      AND NOT stage.removed;
    RETURN QUERY SELECT v_applied, v_key_sha, v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_batch_assert_v1(jsonb, uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count integer;
BEGIN
    v_count := pg_catalog.jsonb_array_length(p_batch->'changes');
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 adoption batch evidence principal denied';
    END IF;
    IF p_scope_kind IS DISTINCT FROM 'tenant' OR
       p_scope_id IS NULL OR p_relation_ordinal NOT BETWEEN 1 AND 32767 OR
       p_checkpoint_key NOT IN (
           'organizations', 'roles', 'users', 'memberships', 'assignments',
           'identifiers', 'portal', 'credentials', 'resources', 'actions',
           'permissions', 'permission_requests', 'invitations', 'profiles', 'layouts'
       ) OR p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_checkpoint_state NOT IN ('initial_copy', 'delta', 'complete') OR
       (p_checkpoint_state = 'complete') IS DISTINCT FROM (p_final_lsn IS NOT NULL) OR
       (v_count = 0 AND p_checkpoint_state <> 'complete') OR
       (p_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (p_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       p_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (p_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       (p_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal OR
       p_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key OR
       p_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state OR
       p_batch->'last_key' IS DISTINCT FROM p_last_key OR
       p_batch->'source_position'->>'snapshot_name' IS DISTINCT FROM p_snapshot_name OR
       (p_batch->'source_position'->>'snapshot_lsn')::pg_lsn
           IS DISTINCT FROM p_snapshot_lsn OR
       (p_batch->'source_position'->>'received_lsn')::pg_lsn
           IS DISTINCT FROM p_received_lsn OR
       (p_batch->'source_position'->>'commit_lsn')::pg_lsn
           IS DISTINCT FROM p_commit_lsn OR
       (p_batch->'source_position'->>'final_lsn')::pg_lsn
           IS DISTINCT FROM p_final_lsn OR
       (p_batch->'source_position'->>'source_xid')::xid8
           IS DISTINCT FROM p_source_xid OR
       (p_batch->'source_position'->>'batch_ordinal')::integer
           IS DISTINCT FROM p_batch_ordinal OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change
           WHERE COALESCE(
               change->'after'->>'source_category',
               change->'before'->>'source_category'
           ) IS DISTINCT FROM p_checkpoint_key
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 adoption batch evidence differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_batch_decode_v1(bytea, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_actual_bytes bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 adoption batch principal denied';
    END IF;
    v_actual_bytes := pg_catalog.octet_length(p_change_batch_bytes);
    IF p_batch_bytes IS DISTINCT FROM v_actual_bytes OR
       v_actual_bytes NOT BETWEEN 2 AND 8388608 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes), 'hex')
           IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 adoption batch digest is invalid';
    END IF;
    v_batch := pg_catalog.convert_from(p_change_batch_bytes, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_batch) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch) AS key)
       IS DISTINCT FROM ARRAY[
           'changes', 'checkpoint_key', 'checkpoint_state', 'last_key',
           'operation_id', 'relation_ordinal', 'run_id', 'scope_id',
           'scope_kind', 'source_position'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'source_position') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch->'source_position') AS key)
       IS DISTINCT FROM ARRAY[
           'batch_ordinal', 'commit_lsn', 'final_lsn', 'received_lsn',
           'snapshot_lsn', 'snapshot_name', 'source_xid'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'changes') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_batch->'changes') > 1000 OR
       (pg_catalog.jsonb_typeof(v_batch->'last_key') NOT IN ('object', 'null')) OR
       v_batch->'last_key' = '{}'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 adoption batch envelope is invalid';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes')
             WITH ORDINALITY AS change(value, position)
        WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.array_agg(key ORDER BY key)
               FROM pg_catalog.jsonb_object_keys(change.value) AS key)
              IS DISTINCT FROM ARRAY['after','before','key','kind','ordinal']::text[]
           OR (change.value->>'ordinal')::integer IS DISTINCT FROM change.position::integer
           OR change.value->>'kind' NOT IN ('insert', 'update', 'delete')
           OR pg_catalog.jsonb_typeof(change.value->'key') IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.array_agg(key ORDER BY key)
               FROM pg_catalog.jsonb_object_keys(change.value->'key') AS key)
              IS DISTINCT FROM ARRAY[
                  'source_category','source_key','target_key','target_table'
              ]::text[]
           OR change.value->'key' @> '{"source_category":"","source_key":"","target_key":"","target_table":""}'::jsonb
           OR (change.value->>'kind' = 'insert' AND (
                  change.value->'before' <> 'null'::jsonb OR
                  NOT iam_v1_adoption_target_record_valid_v1(
                      change.value->'key', change.value->'after'
                  )))
           OR (change.value->>'kind' = 'update' AND (
                  NOT iam_v1_adoption_target_record_valid_v1(
                      change.value->'key', change.value->'before'
                  ) OR NOT iam_v1_adoption_target_record_valid_v1(
                      change.value->'key', change.value->'after'
                  )))
           OR (change.value->>'kind' = 'delete' AND (
                  change.value->'after' <> 'null'::jsonb OR
                  NOT iam_v1_adoption_target_record_valid_v1(
                      change.value->'key', change.value->'before'
                  )))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 adoption batch change is invalid';
    END IF;
    RETURN v_batch;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_identity_record_matches_v1(text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_identity_record_matches_v1(p_target_table text, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_match boolean;
BEGIN
    CASE p_target_table
    WHEN 'iam_profile_schema_versions' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_profile_schema_versions, p_record))
        INTO v_match FROM iam_profile_schema_versions AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_profile_fields' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_profile_fields, p_record))
        INTO v_match FROM iam_profile_fields AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_profile_field_revisions' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_profile_field_revisions, p_record))
        INTO v_match FROM iam_profile_field_revisions AS actual
        WHERE actual.schema_version_id = (p_record->>'schema_version_id')::uuid
          AND actual.field_id = (p_record->>'field_id')::uuid;
    WHEN 'iam_organizations' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_organizations, p_record))
        INTO v_match FROM iam_organizations AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_users' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_users, p_record))
        INTO v_match FROM iam_users AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_user_identifiers' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_user_identifiers, p_record))
        INTO v_match FROM iam_user_identifiers AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_password_credentials' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_password_credentials, p_record))
        INTO v_match FROM iam_password_credentials AS actual
        WHERE actual.user_id = (p_record->>'user_id')::uuid;
    WHEN 'iam_organization_memberships' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_organization_memberships, p_record))
        INTO v_match FROM iam_organization_memberships AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_roles' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_roles, p_record))
        INTO v_match FROM iam_roles AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_user_role_assignments' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_user_role_assignments, p_record))
        INTO v_match FROM iam_user_role_assignments AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_user_access_modes' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_user_access_modes, p_record))
        INTO v_match FROM iam_user_access_modes AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_portal_subject_bindings' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_portal_subject_bindings, p_record))
        INTO v_match FROM iam_portal_subject_bindings AS actual
        WHERE actual.id = (p_record->>'id')::uuid;
    WHEN 'iam_portal_access_setups' THEN
        SELECT pg_catalog.to_jsonb(actual) =
               pg_catalog.to_jsonb(pg_catalog.jsonb_populate_record(
                   NULL::iam_portal_access_setups, p_record))
        INTO v_match FROM iam_portal_access_setups AS actual
        WHERE actual.binding_id = (p_record->>'binding_id')::uuid;
    ELSE
        RETURN false;
    END CASE;
    RETURN COALESCE(v_match, false);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_identity_record_matches_v1(p_target_table text, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_plan_register_v1(name, uuid, uuid, uuid, bytea, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_plan_register_v1(p_scope_schema name, p_operation_id uuid, p_run_id uuid, p_tenant_id uuid, p_plan_bytes bytea, p_plan_sha256 text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_plan jsonb;
    v_now timestamptz := pg_catalog.clock_timestamp();
    v_issue_count integer;
    v_eligible boolean;
    v_existing bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 adoption plan principal or scope denied';
    END IF;
    IF p_operation_id IS NULL OR p_run_id IS NULL OR p_tenant_id IS NULL OR
       p_plan_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.octet_length(p_plan_bytes) NOT BETWEEN 2 AND 8388608 OR
       pg_catalog.encode(pg_catalog.sha256(p_plan_bytes), 'hex')
           IS DISTINCT FROM p_plan_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 adoption plan evidence is invalid';
    END IF;
    v_plan := pg_catalog.convert_from(p_plan_bytes, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_plan) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_plan) AS key)
       IS DISTINCT FROM ARRAY[
           'categories', 'contract_version', 'eligible', 'issues',
           'mapping_sha256', 'source_sha256', 'tenant_id'
       ]::text[] OR
       v_plan->>'contract_version'
           IS DISTINCT FROM 'harpy/iam-v1-adoption-plan/v1' OR
       (v_plan->>'tenant_id')::uuid IS DISTINCT FROM p_tenant_id OR
       v_plan->>'mapping_sha256' !~ '^[0-9a-f]{64}$' OR
       v_plan->>'source_sha256' !~ '^[0-9a-f]{64}$' OR
       pg_catalog.jsonb_typeof(v_plan->'categories') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_typeof(v_plan->'issues') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 adoption plan contract is invalid';
    END IF;
    IF pg_catalog.jsonb_array_length(v_plan->'categories') <> 15 OR
       (SELECT pg_catalog.array_agg(value->>'category' ORDER BY value->>'category')
        FROM pg_catalog.jsonb_array_elements(v_plan->'categories') AS value)
       IS DISTINCT FROM ARRAY[
           'actions', 'assignments', 'credentials', 'identifiers', 'invitations',
           'layouts', 'memberships', 'organizations', 'permission_requests',
           'permissions', 'portal', 'profiles', 'resources', 'roles', 'users'
       ]::text[] OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(v_plan->'categories') AS value
           WHERE (SELECT pg_catalog.array_agg(key ORDER BY key)
                  FROM pg_catalog.jsonb_object_keys(value) AS key)
                 IS DISTINCT FROM ARRAY['category','root_sha256','row_count']::text[]
              OR (value->>'row_count')::bigint < 0
              OR value->>'root_sha256' !~ '^[0-9a-f]{64}$'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 adoption category evidence is invalid';
    END IF;
    v_issue_count := pg_catalog.jsonb_array_length(v_plan->'issues');
    v_eligible := (v_plan->>'eligible')::boolean;
    IF v_eligible IS DISTINCT FROM (v_issue_count = 0) OR EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_plan->'issues') AS value
        WHERE (SELECT pg_catalog.array_agg(key ORDER BY key)
               FROM pg_catalog.jsonb_object_keys(value) AS key)
              IS DISTINCT FROM ARRAY['category','code','source_key']::text[]
           OR value->>'category' = '' OR value->>'code' = ''
           OR pg_catalog.char_length(value->>'source_key') > 512
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM V1 adoption issue evidence is invalid';
    END IF;
    SELECT plan_sha256 INTO v_existing FROM iam_v1_adoption_runs
    WHERE operation_id = p_operation_id AND run_id = p_run_id FOR UPDATE;
    IF FOUND THEN
        IF v_existing IS DISTINCT FROM pg_catalog.decode(p_plan_sha256, 'hex') THEN
            RAISE EXCEPTION USING ERRCODE = '22000',
                MESSAGE = 'IAM V1 adoption plan identity was reused';
        END IF;
        RETURN (SELECT state FROM iam_v1_adoption_runs
                WHERE operation_id = p_operation_id AND run_id = p_run_id);
    END IF;
    INSERT INTO iam_v1_adoption_runs (
        operation_id, run_id, tenant_id, contract_version, source_sha256,
        mapping_sha256, plan_sha256, state, eligible, issue_count, created_at, updated_at
    ) VALUES (
        p_operation_id, p_run_id, p_tenant_id, v_plan->>'contract_version',
        pg_catalog.decode(v_plan->>'source_sha256', 'hex'),
        pg_catalog.decode(v_plan->>'mapping_sha256', 'hex'),
        pg_catalog.decode(p_plan_sha256, 'hex'),
        CASE WHEN v_eligible THEN 'planned' ELSE 'blocked' END,
        v_eligible, v_issue_count, v_now, v_now
    );
    INSERT INTO iam_v1_adoption_category_evidence (
        operation_id, run_id, category, source_count, source_sha256, updated_at
    )
    SELECT p_operation_id, p_run_id, value->>'category',
        (value->>'row_count')::bigint,
        pg_catalog.decode(value->>'root_sha256', 'hex'), v_now
    FROM pg_catalog.jsonb_array_elements(v_plan->'categories') AS value;
    INSERT INTO iam_v1_adoption_issues (
        operation_id, run_id, ordinal, code, category, source_key, created_at
    )
    SELECT p_operation_id, p_run_id, position::integer, value->>'code',
        value->>'category', value->>'source_key', v_now
    FROM pg_catalog.jsonb_array_elements(v_plan->'issues')
        WITH ORDINALITY AS issue(value, position);
    RETURN CASE WHEN v_eligible THEN 'planned' ELSE 'blocked' END;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_plan_register_v1(p_scope_schema name, p_operation_id uuid, p_run_id uuid, p_tenant_id uuid, p_plan_bytes bytea, p_plan_sha256 text) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_project_access_record_v1(text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_project_access_record_v1(p_target_table text, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    CASE p_target_table
    WHEN 'iam_resources' THEN
        INSERT INTO iam_resources
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_resources, p_record)).*;
    WHEN 'iam_actions' THEN
        INSERT INTO iam_actions
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_actions, p_record)).*;
    WHEN 'iam_permissions' THEN
        INSERT INTO iam_permissions
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_permissions, p_record)).*;
    WHEN 'iam_user_permission_bindings' THEN
        INSERT INTO iam_user_permission_bindings
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_user_permission_bindings, p_record)).*;
    WHEN 'iam_role_permission_bindings' THEN
        INSERT INTO iam_role_permission_bindings
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_role_permission_bindings, p_record)).*;
    WHEN 'iam_organization_permission_bindings' THEN
        INSERT INTO iam_organization_permission_bindings
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_organization_permission_bindings, p_record)).*;
    WHEN 'iam_authorization_clock' THEN
        INSERT INTO iam_authorization_clock
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_authorization_clock, p_record)).*;
    WHEN 'iam_protected_admin_policies' THEN
        INSERT INTO iam_protected_admin_policies
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_protected_admin_policies, p_record)).*;
    WHEN 'iam_permission_request_groups' THEN
        INSERT INTO iam_permission_request_groups
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_permission_request_groups, p_record)).*;
    WHEN 'iam_permission_requests' THEN
        INSERT INTO iam_permission_requests
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_permission_requests, p_record)).*;
    WHEN 'iam_invitations' THEN
        INSERT INTO iam_invitations
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_invitations, p_record)).*;
    WHEN 'iam_one_time_tokens' THEN
        INSERT INTO iam_one_time_tokens
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_one_time_tokens, p_record)).*;
    ELSE
        RETURN false;
    END CASE;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_project_access_record_v1(p_target_table text, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_project_identity_record_v1(text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_project_identity_record_v1(p_target_table text, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    CASE p_target_table
    WHEN 'iam_profile_schema_versions' THEN
        INSERT INTO iam_profile_schema_versions
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_profile_schema_versions, p_record)).*;
    WHEN 'iam_profile_fields' THEN
        INSERT INTO iam_profile_fields
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_profile_fields, p_record)).*;
    WHEN 'iam_profile_field_revisions' THEN
        INSERT INTO iam_profile_field_revisions
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_profile_field_revisions, p_record)).*;
    WHEN 'iam_organizations' THEN
        INSERT INTO iam_organizations
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_organizations, p_record)).*;
    WHEN 'iam_users' THEN
        INSERT INTO iam_users
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_users, p_record)).*;
    WHEN 'iam_user_identifiers' THEN
        INSERT INTO iam_user_identifiers
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_user_identifiers, p_record)).*;
    WHEN 'iam_password_credentials' THEN
        INSERT INTO iam_password_credentials
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_password_credentials, p_record)).*;
    WHEN 'iam_organization_memberships' THEN
        INSERT INTO iam_organization_memberships
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_organization_memberships, p_record)).*;
    WHEN 'iam_roles' THEN
        INSERT INTO iam_roles
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_roles, p_record)).*;
    WHEN 'iam_user_role_assignments' THEN
        INSERT INTO iam_user_role_assignments
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_user_role_assignments, p_record)).*;
    WHEN 'iam_user_access_modes' THEN
        INSERT INTO iam_user_access_modes
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_user_access_modes, p_record)).*;
    WHEN 'iam_portal_subject_bindings' THEN
        INSERT INTO iam_portal_subject_bindings
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_portal_subject_bindings, p_record)).*;
    WHEN 'iam_portal_access_setups' THEN
        INSERT INTO iam_portal_access_setups
        SELECT (pg_catalog.jsonb_populate_record(NULL::iam_portal_access_setups, p_record)).*;
    ELSE
        RETURN false;
    END CASE;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_project_identity_record_v1(p_target_table text, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_project_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_project_v1(p_scope_schema name, p_operation_id uuid, p_run_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_target_table text;
    v_target_record jsonb;
    v_handled boolean;
    v_projected bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    v_projected := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT EXISTS (
           SELECT 1 FROM iam_v1_adoption_runs AS run
           WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
             AND run.eligible AND run.state = 'copying'
           FOR UPDATE
       ) OR EXISTS (
           SELECT 1 FROM iam_v1_adoption_category_evidence AS evidence
           WHERE evidence.operation_id = p_operation_id AND evidence.run_id = p_run_id
             AND evidence.category <> 'layouts' AND evidence.copy_state <> 'complete'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 adoption projection authority or readiness denied';
    END IF;
    FOR v_target_table, v_target_record IN
        SELECT stage.target_table, stage.target_record
        FROM iam_v1_adoption_stage AS stage
        WHERE stage.operation_id = p_operation_id AND stage.run_id = p_run_id
          AND NOT stage.removed
        ORDER BY CASE stage.target_table
            WHEN 'iam_profile_schema_versions' THEN 10
            WHEN 'iam_profile_fields' THEN 20
            WHEN 'iam_profile_field_revisions' THEN 30
            WHEN 'iam_organizations' THEN 40
            WHEN 'iam_users' THEN 50
            WHEN 'iam_user_identifiers' THEN 60
            WHEN 'iam_password_credentials' THEN 70
            WHEN 'iam_organization_memberships' THEN 80
            WHEN 'iam_roles' THEN 90
            WHEN 'iam_user_role_assignments' THEN 100
            WHEN 'iam_user_access_modes' THEN 110
            WHEN 'iam_portal_subject_bindings' THEN 120
            WHEN 'iam_portal_access_setups' THEN 130
            WHEN 'iam_resources' THEN 140
            WHEN 'iam_actions' THEN 150
            WHEN 'iam_permissions' THEN 160
            WHEN 'iam_user_permission_bindings' THEN 170
            WHEN 'iam_role_permission_bindings' THEN 180
            WHEN 'iam_organization_permission_bindings' THEN 190
            WHEN 'iam_authorization_clock' THEN 200
            WHEN 'iam_protected_admin_policies' THEN 210
            WHEN 'iam_permission_request_groups' THEN 220
            WHEN 'iam_permission_requests' THEN 230
            WHEN 'iam_invitations' THEN 240
            WHEN 'iam_one_time_tokens' THEN 250
        END, stage.target_key
    LOOP
        v_handled := iam_v1_adoption_project_identity_record_v1(
            v_target_table, v_target_record
        );
        IF NOT v_handled THEN
            v_handled := iam_v1_adoption_project_access_record_v1(
                v_target_table, v_target_record
            );
        END IF;
        IF NOT v_handled THEN
            RAISE EXCEPTION USING ERRCODE = '22023',
                MESSAGE = 'IAM V1 adoption projection target is unsupported';
        END IF;
        v_projected := v_projected + 1;
    END LOOP;
    UPDATE iam_v1_adoption_runs
    SET state = 'projected', projected_at = v_now, updated_at = v_now
    WHERE operation_id = p_operation_id AND run_id = p_run_id AND state = 'copying';
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'IAM V1 adoption projection state raced';
    END IF;
    RETURN v_projected;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_project_v1(p_scope_schema name, p_operation_id uuid, p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_target_record_valid_v1(jsonb, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_target_record_valid_v1(p_key jsonb, p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN
        pg_catalog.jsonb_typeof(p_value) = 'object' AND
        (SELECT pg_catalog.array_agg(key ORDER BY key)
         FROM pg_catalog.jsonb_object_keys(p_value) AS key)
        = ARRAY[
            'source_category','source_key','target_key','target_record','target_table'
        ]::text[] AND
        p_value - 'target_record' = p_key AND
        pg_catalog.jsonb_typeof(p_value->'target_record') = 'object' AND
        p_value->'target_record' <> '{}'::jsonb AND
        pg_catalog.octet_length((p_value->'target_record')::text) <= 1048576;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_target_record_valid_v1(p_key jsonb, p_value jsonb) OWNER TO harpy_owner;

--
-- Name: iam_v1_adoption_verify_v1(name, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_v1_adoption_verify_v1(p_scope_schema name, p_operation_id uuid, p_run_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_target_table text;
    v_target_record jsonb;
    v_matches boolean;
    v_verified bigint;
    v_state_sha text;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    v_verified := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       NOT EXISTS (
           SELECT 1 FROM iam_v1_adoption_runs AS run
           WHERE run.operation_id = p_operation_id AND run.run_id = p_run_id
             AND run.eligible AND run.state = 'projected'
           FOR UPDATE
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM V1 adoption verification authority or state denied';
    END IF;
    FOR v_target_table, v_target_record IN
        SELECT stage.target_table, stage.target_record
        FROM iam_v1_adoption_stage AS stage
        WHERE stage.operation_id = p_operation_id AND stage.run_id = p_run_id
          AND NOT stage.removed
        ORDER BY stage.target_table, stage.target_key
    LOOP
        v_matches := iam_v1_adoption_identity_record_matches_v1(
            v_target_table, v_target_record
        );
        IF NOT v_matches THEN
            v_matches := iam_v1_adoption_access_record_matches_v1(
                v_target_table, v_target_record
            );
        END IF;
        IF NOT v_matches THEN
            RAISE EXCEPTION USING ERRCODE = '22000',
                MESSAGE = 'IAM V1 adoption target parity differs';
        END IF;
        v_verified := v_verified + 1;
    END LOOP;
    IF v_verified IS DISTINCT FROM (
        SELECT pg_catalog.count(*) FROM iam_v1_adoption_stage AS stage
        WHERE stage.operation_id = p_operation_id AND stage.run_id = p_run_id
          AND NOT stage.removed
    ) OR EXISTS (
        SELECT 1 FROM iam_v1_adoption_category_evidence AS evidence
        WHERE evidence.operation_id = p_operation_id AND evidence.run_id = p_run_id
          AND evidence.category <> 'layouts'
          AND (evidence.copy_state <> 'complete' OR
               evidence.staged_count IS NULL OR evidence.staged_sha256 IS NULL)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'IAM V1 adoption category parity is incomplete';
    END IF;
    UPDATE iam_v1_adoption_category_evidence
    SET target_count = staged_count, target_sha256 = staged_sha256, updated_at = v_now
    WHERE operation_id = p_operation_id AND run_id = p_run_id
      AND category <> 'layouts' AND copy_state = 'complete';
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        pg_catalog.string_agg(
            evidence.category || ':' || evidence.target_count::text || ':' ||
            pg_catalog.encode(evidence.target_sha256, 'hex'),
            ',' ORDER BY evidence.category
        ), 'UTF8'
    )), 'hex')
    INTO STRICT v_state_sha
    FROM iam_v1_adoption_category_evidence AS evidence
    WHERE evidence.operation_id = p_operation_id AND evidence.run_id = p_run_id
      AND evidence.category <> 'layouts';
    UPDATE iam_v1_adoption_runs
    SET state = 'verified', verified_at = v_now, updated_at = v_now
    WHERE operation_id = p_operation_id AND run_id = p_run_id
      AND state = 'projected';
    IF NOT FOUND OR v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'IAM V1 adoption verification state raced';
    END IF;
    RETURN v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_v1_adoption_verify_v1(p_scope_schema name, p_operation_id uuid, p_run_id uuid) OWNER TO harpy_owner;

--
-- Name: iam_verify_profile_preconversion_commit_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_verify_profile_preconversion_commit_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_target_schema_id uuid;
    v_current_schema_id uuid;
    v_current_revision bigint;
    v_current_sha256 bytea;
BEGIN
    SELECT plan.target_schema_id INTO v_target_schema_id
    FROM iam_profile_backfill_plans AS plan
    JOIN iam_profile_backfill_pages AS page
      ON page.plan_id = plan.id AND page.page_number = NEW.page_number
    JOIN iam_profile_schema_versions AS actual
      ON actual.id = NEW.actual_source_schema_id
     AND actual.resource_kind = NEW.resource_kind
     AND actual.state IN ('active','retired')
    JOIN iam_profile_schema_versions AS source
      ON source.id = plan.source_schema_id
     AND source.resource_kind = plan.resource_kind
     AND actual.version <= source.version
    JOIN iam_profile_schema_versions AS target
      ON target.id = plan.target_schema_id
     AND target.resource_kind = plan.resource_kind
     AND target.state = 'draft'
    WHERE plan.id = NEW.plan_id
      AND plan.resource_kind = NEW.resource_kind
      AND plan.state IN ('planned','running')
      AND (page.after_resource_id IS NULL OR
           NEW.resource_id > page.after_resource_id)
      AND NEW.resource_id <= page.through_resource_id;
    IF NEW.resource_kind = 'user' THEN
        SELECT resource.profile_schema_version_id, resource.revision,
               resource.profile_sha256
        INTO v_current_schema_id, v_current_revision, v_current_sha256
        FROM iam_users AS resource WHERE resource.id = NEW.resource_id;
    ELSIF NEW.resource_kind = 'organization' THEN
        SELECT resource.profile_schema_version_id, resource.revision,
               resource.profile_sha256
        INTO v_current_schema_id, v_current_revision, v_current_sha256
        FROM iam_organizations AS resource WHERE resource.id = NEW.resource_id;
    ELSIF NEW.resource_kind = 'role' THEN
        SELECT resource.profile_schema_version_id, resource.revision,
               resource.profile_sha256
        INTO v_current_schema_id, v_current_revision, v_current_sha256
        FROM iam_roles AS resource WHERE resource.id = NEW.resource_id;
    END IF;
    IF v_target_schema_id IS NULL OR
       v_current_schema_id IS DISTINCT FROM v_target_schema_id OR
       v_current_revision < NEW.first_target_revision OR
       (v_current_revision = NEW.first_target_revision AND
        v_current_sha256 IS DISTINCT FROM NEW.first_target_sha256) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'IAM profile preconversion did not commit its target write';
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_verify_profile_preconversion_commit_v1() OWNER TO harpy_owner;

--
-- Name: iam_webauthn_enrollment_complete_v1(name, uuid, uuid, bytea, uuid, uuid, text, bytea, bytea, bytea, bytea, text, bytea, bigint, uuid, bigint, boolean, boolean, boolean, boolean, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_webauthn_enrollment_complete_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_challenge_id uuid, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_credential_id bytea, p_public_key_cose bytea, p_rp_id text, p_rp_id_sha256 bytea, p_origin_policy_version bigint, p_aaguid uuid, p_sign_count bigint, p_backup_eligible boolean, p_backup_state boolean, p_discoverable boolean, p_uv_required boolean, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_user_id uuid;
    v_challenge_state text;
    v_challenge_expires_at timestamptz;
    v_challenge_rp_id_sha256 bytea;
    v_challenge_origin_policy_version bigint;
    v_challenge_uv_required boolean;
    v_revision bigint;
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_authenticator_id IS NULL OR p_challenge_id IS NULL OR p_aaguid IS NULL OR
       pg_catalog.octet_length(p_challenge_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_context_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_credential_id) NOT BETWEEN 1 AND 1024 OR
       pg_catalog.octet_length(p_public_key_cose) NOT BETWEEN 1 AND 4096 OR
       pg_catalog.sha256(pg_catalog.convert_to(p_rp_id, 'UTF8'))
          IS DISTINCT FROM p_rp_id_sha256 OR p_origin_policy_version < 1 OR
       p_sign_count < 0 OR (p_backup_state AND NOT p_backup_eligible) OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.webauthn_enrollment.complete',
        p_request_sha256, p_authenticator_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    SELECT challenge.user_id, challenge.state, challenge.expires_at,
        challenge.rp_id_sha256, challenge.origin_policy_version,
        challenge.user_verification_required
    INTO v_user_id, v_challenge_state, v_challenge_expires_at,
        v_challenge_rp_id_sha256, v_challenge_origin_policy_version,
        v_challenge_uv_required
    FROM iam_auth_challenges AS challenge
    WHERE challenge.id = p_challenge_id
      AND challenge.authenticator_id = p_authenticator_id
      AND challenge.purpose = 'webauthn_register_v1'
      AND challenge.hmac_key_id = p_hmac_key_id
      AND challenge.challenge_hmac = p_challenge_hmac
      AND challenge.context_sha256 = p_context_sha256 FOR UPDATE;
    IF NOT FOUND OR v_challenge_state <> 'pending' OR
       v_challenge_expires_at <= v_now OR
       v_challenge_rp_id_sha256 <> p_rp_id_sha256 OR
       v_challenge_origin_policy_version <> p_origin_policy_version OR
       v_challenge_uv_required <> p_uv_required THEN
        RAISE EXCEPTION USING ERRCODE = '28000';
    END IF;
    PERFORM 1 FROM iam_authenticators AS authenticator
    WHERE authenticator.id = p_authenticator_id
      AND authenticator.user_id = v_user_id
      AND authenticator.kind = 'webauthn_v1' AND authenticator.state = 'pending'
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '40001'; END IF;
    INSERT INTO iam_webauthn_credentials (
        authenticator_id, user_id, authenticator_kind, credential_id,
        public_key_cose, rp_id, rp_id_sha256, origin_policy_version,
        aaguid, sign_count, backup_eligible, backup_state, discoverable,
        uv_required, revision, created_at, updated_at
    ) VALUES (
        p_authenticator_id, v_user_id, 'webauthn_v1',
        p_credential_id, p_public_key_cose, p_rp_id, p_rp_id_sha256,
        p_origin_policy_version, p_aaguid, p_sign_count, p_backup_eligible,
        p_backup_state, p_discoverable, p_uv_required, 1, v_now, v_now
    );
    UPDATE iam_auth_challenges SET state = 'consumed', terminal_at = v_now,
        revision = revision + 1, updated_at = v_now WHERE id = p_challenge_id;
    UPDATE iam_authenticators SET state = 'active', activated_at = v_now,
        revision = revision + 1, updated_at = v_now
    WHERE id = p_authenticator_id RETURNING revision INTO v_revision;
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.webauthn_enrollment.complete', p_request_sha256,
        p_authenticator_id, v_user_id, v_revision,
        'actor_tenant', p_actor_id, 'authenticator', true, true
    ) AS result;
    RETURN QUERY SELECT p_authenticator_id, v_user_id, v_revision,
        v_token_version, v_authorization_version, false;
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_webauthn_enrollment_complete_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_challenge_id uuid, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_credential_id bytea, p_public_key_cose bytea, p_rp_id text, p_rp_id_sha256 bytea, p_origin_policy_version bigint, p_aaguid uuid, p_sign_count bigint, p_backup_eligible boolean, p_backup_state boolean, p_discoverable boolean, p_uv_required boolean, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_webauthn_enrollment_start_v1(name, uuid, uuid, bytea, uuid, uuid, uuid, uuid, text, text, bytea, bytea, bigint, bytea, bytea, boolean, uuid, uuid, bigint, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_webauthn_enrollment_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_display_label text, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_origin_policy_version bigint, p_rp_id_sha256 bytea, p_origin_sha256 bytea, p_uv_required boolean, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) RETURNS TABLE(result_id uuid, subject_user_id uuid, result_revision bigint, token_version bigint, authorization_version bigint, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_token_version bigint;
    v_authorization_version bigint;
    v_now timestamptz := pg_catalog.transaction_timestamp();
BEGIN
    IF p_authenticator_id IS NULL OR p_challenge_id IS NULL OR p_user_id IS NULL OR
       p_session_id IS NULL OR p_origin_policy_version < 1 OR
       p_hmac_key_id !~ '^[a-z0-9][a-z0-9._-]{0,127}$' OR
       pg_catalog.octet_length(p_challenge_hmac) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_context_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_rp_id_sha256) IS DISTINCT FROM 32 OR
       pg_catalog.octet_length(p_origin_sha256) IS DISTINCT FROM 32 OR
       NOT EXISTS (SELECT 1 FROM platform.tenants AS tenant
          WHERE tenant.id = p_tenant_id AND
                tenant.schema_name = p_scope_schema::text) THEN
        RAISE EXCEPTION USING ERRCODE = '22023';
    END IF;
    RETURN QUERY SELECT * FROM iam_lifecycle_replay_v1(
        p_operation_id, 'iam.webauthn_enrollment.start',
        p_request_sha256, p_authenticator_id
    );
    IF FOUND THEN RETURN; END IF;
    IF NOT iam_identity_actor_assert_v1(
        p_scope_schema, p_actor_id, p_permission_id,
        p_expected_token_version, p_expected_authorization_version
    ) THEN RAISE EXCEPTION USING ERRCODE = '42501'; END IF;
    IF NOT EXISTS (SELECT 1 FROM iam_sessions AS session
        WHERE session.id = p_session_id AND session.user_id = p_user_id
          AND session.state = 'active' AND session.absolute_expires_at > v_now
        FOR UPDATE) THEN RAISE EXCEPTION USING ERRCODE = '28000'; END IF;
    INSERT INTO iam_authenticators (
        id, user_id, kind, display_label, state, revision, created_at, updated_at
    ) VALUES (
        p_authenticator_id, p_user_id, 'webauthn_v1', p_display_label,
        'pending', 1, v_now, v_now
    );
    INSERT INTO iam_auth_challenges (
        id, user_id, session_id, authenticator_id, authenticator_kind,
        purpose, proof_kind, hash_profile, hmac_key_id, challenge_hmac,
        context_sha256, origin_policy_version, rp_id_sha256, origin_sha256,
        user_verification_required, state, attempt_count, revision,
        issued_at, expires_at, purge_after, created_at, updated_at
    ) VALUES (
        p_challenge_id, p_user_id, p_session_id, p_authenticator_id,
        'webauthn_v1', 'webauthn_register_v1', 'webauthn_v1',
        'hmac_sha256_v1', p_hmac_key_id, p_challenge_hmac,
        p_context_sha256, p_origin_policy_version, p_rp_id_sha256,
        p_origin_sha256, p_uv_required, 'pending', 0, 1,
        v_now, v_now + INTERVAL '5 minutes',
        v_now + INTERVAL '1 day 5 minutes', v_now, v_now
    );
    SELECT result.token_version, result.authorization_version
    INTO STRICT v_token_version, v_authorization_version
    FROM iam_lifecycle_record_v1(
        p_operation_id, 'iam.webauthn_enrollment.start', p_request_sha256,
        p_authenticator_id, p_user_id, 1, 'actor_tenant', p_actor_id,
        'authenticator', false, false
    ) AS result;
    RETURN QUERY SELECT p_authenticator_id, p_user_id, 1::bigint,
        v_token_version, v_authorization_version, false;
END;
$_$;


ALTER FUNCTION __tenant_schema__.iam_webauthn_enrollment_start_v1(p_scope_schema name, p_tenant_id uuid, p_operation_id uuid, p_request_sha256 bytea, p_authenticator_id uuid, p_challenge_id uuid, p_user_id uuid, p_session_id uuid, p_display_label text, p_hmac_key_id text, p_challenge_hmac bytea, p_context_sha256 bytea, p_origin_policy_version bigint, p_rp_id_sha256 bytea, p_origin_sha256 bytea, p_uv_required boolean, p_actor_id uuid, p_permission_id uuid, p_expected_token_version bigint, p_expected_authorization_version bigint) OWNER TO harpy_owner;

--
-- Name: iam_work_available_users_v1(name, uuid, uuid, text, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_work_available_users_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_search text, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_evidence jsonb;
BEGIN
    IF p_search IS NULL OR pg_catalog.char_length(p_search) > 200 OR
       p_limit NOT BETWEEN 1 AND 50 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'IAM Work directory input is invalid';
    END IF;
    SELECT actor_principals INTO v_evidence
    FROM iam_work_principal_evidence_v1(
        p_scope_schema, p_tenant_id, p_actor_id, 'USER', p_actor_id
    );
    IF v_evidence IS NULL OR NOT EXISTS (
        SELECT 1
        FROM iam_users AS actor
        JOIN iam_user_access_modes AS access_mode
          ON access_mode.user_id = actor.id
         AND access_mode.mode = 'operator_console'
         AND access_mode.state = 'active'
        WHERE actor.id = p_actor_id AND actor.status = 'active'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM Work directory actor is invalid';
    END IF;
    RETURN COALESCE((
        WITH users AS (
            SELECT subject.id,
                COALESCE(identifier.display_value, '') AS email,
                COALESCE(profile.first_name, profile.display_name, '') AS first_name,
                COALESCE(profile.last_name, '') AS last_name,
                COALESCE(profile.avatar, '') AS avatar
            FROM iam_users AS subject
            LEFT JOIN LATERAL (
                SELECT value.display_value
                FROM iam_user_identifiers AS value
                WHERE value.user_id = subject.id AND value.kind = 'email_v1'
                  AND value.state = 'active'
                ORDER BY value.updated_at DESC, value.id LIMIT 1
            ) AS identifier ON true
            LEFT JOIN LATERAL (
                SELECT
                    pg_catalog.max(subject.profile_values ->> field.field_id::text)
                        FILTER (WHERE field.field_key = 'first_name') AS first_name,
                    pg_catalog.max(subject.profile_values ->> field.field_id::text)
                        FILTER (WHERE field.field_key = 'last_name') AS last_name,
                    pg_catalog.max(subject.profile_values ->> field.field_id::text)
                        FILTER (WHERE field.field_key = 'display_name') AS display_name,
                    pg_catalog.max(subject.profile_values ->> field.field_id::text)
                        FILTER (WHERE field.field_key = 'avatar') AS avatar
                FROM iam_profile_field_revisions AS field
                WHERE field.schema_version_id = subject.profile_schema_version_id
                  AND field.resource_kind = 'user' AND field.field_state = 'active'
                  AND field.field_key IN ('first_name','last_name','display_name','avatar')
            ) AS profile ON true
            WHERE subject.status = 'active'
        ), filtered AS (
            SELECT users.* FROM users
            WHERE p_search = '' OR pg_catalog.lower(users.email) LIKE
                    '%' || pg_catalog.lower(p_search) || '%' OR
                pg_catalog.lower(users.first_name) LIKE
                    '%' || pg_catalog.lower(p_search) || '%' OR
                pg_catalog.lower(users.last_name) LIKE
                    '%' || pg_catalog.lower(p_search) || '%'
            ORDER BY users.first_name, users.last_name, users.email, users.id
            LIMIT p_limit
        )
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'id', filtered.id, 'email', filtered.email,
            'first_name', filtered.first_name, 'last_name', filtered.last_name,
            'avatar', filtered.avatar
        ) ORDER BY filtered.first_name, filtered.last_name, filtered.email, filtered.id)
        FROM filtered
    ), '[]'::jsonb);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_work_available_users_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_search text, p_limit integer) OWNER TO harpy_owner;

--
-- Name: iam_work_principal_evidence_v1(name, uuid, uuid, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.iam_work_principal_evidence_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_target_kind text, p_target_id uuid) RETURNS TABLE(actor_principals jsonb, authorization_clock bigint, target_exists boolean, target_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_iam_generation bigint;
    v_work_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_tenant_id IS NULL OR p_actor_id IS NULL OR p_target_id IS NULL OR
       p_target_kind NOT IN ('USER', 'ROLE', 'ORGANIZATION') OR
       NOT EXISTS (
           SELECT 1 FROM tenancy_schema_identity AS identity_row
           WHERE identity_row.singleton AND identity_row.tenant_id = p_tenant_id
             AND identity_row.schema_name = p_scope_schema::text
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'IAM Work principal evidence scope is invalid';
    END IF;

    SELECT authority.generation INTO v_iam_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
      AND authority.domain = 'iam'
      AND authority.state = 'v2' AND authority.writer = 'v2';
    SELECT authority.generation INTO v_work_generation
    FROM platform.domain_cutovers AS authority
    WHERE authority.scope_kind = 'tenant' AND authority.scope_id = p_tenant_id
      AND authority.domain = 'work'
      AND authority.state = 'v2' AND authority.writer = 'v2';
    IF v_iam_generation IS NULL OR v_iam_generation < 1 OR
       v_work_generation IS NULL OR v_work_generation < 1 OR
       NOT EXISTS (
           SELECT 1 FROM platform.cutover_group_members AS member
           WHERE member.scope_kind = 'tenant' AND member.scope_id = p_tenant_id
             AND member.group_id = 'work' AND member.ordinal = 1
             AND member.domain = 'work'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = 'P5701',
            MESSAGE = 'IAM Work principal evidence authority is unavailable';
    END IF;

    RETURN QUERY
    WITH actor AS (
        SELECT principal.id
        FROM iam_users AS principal
        WHERE principal.id = p_actor_id AND principal.status = 'active'
          AND EXISTS (
              SELECT 1
              FROM iam_user_access_modes AS access_mode
              WHERE access_mode.user_id = principal.id
                AND access_mode.mode = 'operator_console'
                AND access_mode.state = 'active'
          )
    ), principals AS (
        SELECT 'USER'::text AS kind, actor.id, user_row.revision
        FROM actor JOIN iam_users AS user_row ON user_row.id = actor.id
        UNION ALL
        SELECT 'ROLE', role.id,
            GREATEST(role.revision, assignment.revision,
                COALESCE(membership.revision, 0), COALESCE(organization.revision, 0))
        FROM actor
        JOIN iam_user_role_assignments AS assignment
          ON assignment.user_id = actor.id AND assignment.state = 'active'
        JOIN iam_roles AS role ON role.id = assignment.role_id AND role.status = 'active'
        LEFT JOIN iam_organization_memberships AS membership
          ON membership.id = assignment.membership_id AND membership.state = 'active'
        LEFT JOIN iam_organizations AS organization
          ON organization.id = assignment.organization_id AND organization.status = 'active'
        WHERE assignment.role_scope_kind = 'tenant' OR
              (membership.id IS NOT NULL AND organization.id IS NOT NULL)
        UNION ALL
        SELECT 'ORGANIZATION', organization.id,
            GREATEST(organization.revision, membership.revision)
        FROM actor
        JOIN iam_organization_memberships AS membership
          ON membership.user_id = actor.id AND membership.state = 'active'
        JOIN iam_organizations AS organization
          ON organization.id = membership.organization_id
         AND organization.status = 'active'
    ), target AS (
        SELECT user_row.revision
        FROM iam_users AS user_row
        WHERE p_target_kind = 'USER' AND user_row.id = p_target_id
          AND user_row.status = 'active'
        UNION ALL
        SELECT role.revision FROM iam_roles AS role
        WHERE p_target_kind = 'ROLE' AND role.id = p_target_id
          AND role.status = 'active'
        UNION ALL
        SELECT organization.revision FROM iam_organizations AS organization
        WHERE p_target_kind = 'ORGANIZATION' AND organization.id = p_target_id
          AND organization.status = 'active'
    )
    SELECT COALESCE((
        SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'kind', kind, 'id', id, 'revision', revision
        ) ORDER BY kind, id) FROM principals
    ), '[]'::jsonb),
    COALESCE((SELECT clock_value FROM iam_authorization_clock WHERE singleton), -1),
    EXISTS (SELECT 1 FROM target),
    COALESCE((SELECT revision FROM target), -1);
END;
$$;


ALTER FUNCTION __tenant_schema__.iam_work_principal_evidence_v1(p_scope_schema name, p_tenant_id uuid, p_actor_id uuid, p_target_kind text, p_target_id uuid) OWNER TO harpy_owner;

--
-- Name: notifications_retention_purge_attempts_v1(timestamp with time zone, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_retention_purge_attempts_v1(p_now timestamp with time zone, p_limit integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
WITH candidates AS MATERIALIZED (
    SELECT id FROM notifications_delivery_attempts
    WHERE pg_catalog.isfinite(p_now) AND p_limit BETWEEN 1 AND 500
      AND finished_at <= p_now - interval '90 days'
    ORDER BY finished_at, id FOR UPDATE SKIP LOCKED LIMIT p_limit
), purged AS (
    DELETE FROM notifications_delivery_attempts AS attempt
    USING candidates WHERE attempt.id = candidates.id RETURNING attempt.id
)
SELECT pg_catalog.count(*) INTO v_count FROM purged;
RETURN v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_retention_purge_attempts_v1(p_now timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: notifications_retention_purge_deliveries_v1(timestamp with time zone, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_retention_purge_deliveries_v1(p_now timestamp with time zone, p_limit integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
WITH candidates AS MATERIALIZED (
    SELECT delivery.id
    FROM notifications_deliveries AS delivery
    JOIN notifications_messages AS message ON message.id = delivery.message_id
    WHERE pg_catalog.isfinite(p_now) AND p_limit BETWEEN 1 AND 500
      AND message.purged_at <= p_now - interval '365 days'
      AND NOT EXISTS (
          SELECT 1 FROM notifications_effect_receipts AS effect
          WHERE effect.message_id = message.id
      )
      AND NOT EXISTS (
          SELECT 1 FROM notifications_delivery_attempts AS attempt
          WHERE attempt.delivery_id = delivery.id
      )
      AND NOT EXISTS (
          SELECT 1 FROM notifications_delivery_receipts AS receipt
          WHERE receipt.delivery_id = delivery.id
      )
    ORDER BY message.purged_at, delivery.id
    FOR UPDATE OF delivery SKIP LOCKED LIMIT p_limit
), purged AS (
    DELETE FROM notifications_deliveries AS delivery
    USING candidates WHERE delivery.id = candidates.id RETURNING delivery.id
)
SELECT pg_catalog.count(*) INTO v_count FROM purged;
RETURN v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_retention_purge_deliveries_v1(p_now timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

--
-- Name: notifications_retention_purge_effects_v1(timestamp with time zone, integer); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_retention_purge_effects_v1(p_now timestamp with time zone, p_limit integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_count bigint;
BEGIN
WITH candidates AS MATERIALIZED (
    SELECT producer, effect_key_hash, recipient_id
    FROM notifications_effect_receipts
    WHERE pg_catalog.isfinite(p_now) AND p_limit BETWEEN 1 AND 500
      AND retain_until <= p_now
    ORDER BY retain_until, producer, effect_key_hash, recipient_id
    FOR UPDATE SKIP LOCKED LIMIT p_limit
), purged AS (
    DELETE FROM notifications_effect_receipts AS receipt USING candidates
    WHERE receipt.producer = candidates.producer
      AND receipt.effect_key_hash = candidates.effect_key_hash
      AND receipt.recipient_id = candidates.recipient_id
    RETURNING receipt.message_id
)
SELECT pg_catalog.count(*) INTO v_count FROM purged;
RETURN v_count;
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_retention_purge_effects_v1(p_now timestamp with time zone, p_limit integer) OWNER TO harpy_owner;

