--
-- Name: notifications_v1_adoption_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract_id text;
    v_procedure_oid bigint;
    v_procedure_signature text;
    v_expected_signature text;
    v_already_applied boolean;
    v_applied_count bigint;
    v_key_sha text;
    v_state_sha text;
    v_projected_sha text;
    v_asserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 adoption composite principal denied';
    END IF;
    v_batch := notifications_v1_adoption_batch_decode_v1(
        p_change_batch_bytes,p_batch_sha256,p_batch_bytes
    );
    v_asserted := notifications_v1_adoption_batch_assert_v1(
        v_batch,p_operation_id,p_run_id,p_scope_kind,p_scope_id,
        p_relation_ordinal,p_checkpoint_key,p_snapshot_name,
        p_snapshot_lsn,p_received_lsn,p_commit_lsn,p_final_lsn,
        p_source_xid,p_batch_ordinal,p_checkpoint_state,p_last_key
    );
    IF NOT v_asserted THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='Notifications V1 adoption batch assertion failed';
    END IF;
    SELECT prepared.procedure_contract_id,prepared.procedure_oid,
        prepared.procedure_signature,prepared.already_applied,
        prepared.applied_count,prepared.key_state_sha256,prepared.state_sha256
    INTO STRICT v_contract_id,v_procedure_oid,v_procedure_signature,
        v_already_applied,v_applied_count,v_key_sha,v_state_sha
    FROM platform.cutover_prepare_batch_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,
        p_relation_ordinal,p_checkpoint_key,p_batch_ordinal,
        p_commit_lsn,p_source_xid,p_batch_sha256,p_lease_manifest_sha256
    ) AS prepared;
    v_expected_signature := pg_catalog.format(
        '%I.notifications_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)',
        pg_catalog.current_schema()
    );
    IF v_contract_id IS DISTINCT FROM 'notifications.v1_adoption.v1' OR
       v_procedure_oid IS DISTINCT FROM
           'notifications_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure_signature IS DISTINCT FROM v_expected_signature THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 adoption procedure binding differs';
    END IF;
    IF v_already_applied THEN
        RETURN QUERY SELECT v_applied_count,v_key_sha,v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count,result.key_state_sha256,result.state_sha256
    INTO STRICT v_applied_count,v_key_sha,v_state_sha
    FROM notifications_v1_adoption_apply_v1(
        p_operation_id,p_run_id,p_scope_kind,p_scope_id,
        p_relation_ordinal,p_checkpoint_key,p_snapshot_lsn,p_received_lsn,
        p_commit_lsn,p_source_xid,p_batch_ordinal,v_batch,p_batch_sha256
    ) AS result;
    IF v_applied_count<0 OR v_key_sha !~ '^[0-9a-f]{64}$' OR
       v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='22000',
            MESSAGE='Notifications V1 adoption owner result is invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id,p_run_id,p_relation_ordinal,p_checkpoint_key,
        p_snapshot_name,p_snapshot_lsn,p_received_lsn,p_commit_lsn,
        p_final_lsn,p_source_xid,p_batch_ordinal,p_checkpoint_state,
        p_last_key,p_batch_sha256,p_batch_bytes,v_applied_count,
        v_key_sha,v_state_sha
    );
    IF p_checkpoint_state='complete' AND NOT EXISTS (
        SELECT 1
        FROM platform.cutover_operation_checkpoint_keys AS expected
        LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint
          ON checkpoint.operation_id=expected.operation_id
         AND checkpoint.run_id=expected.run_id
         AND checkpoint.relation_ordinal=expected.relation_ordinal
         AND checkpoint.checkpoint_key=expected.checkpoint_key
         AND checkpoint.state='complete'
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
          AND checkpoint.operation_id IS NULL
    ) THEN
        v_projected_sha := notifications_v1_adoption_project_v1(
            p_operation_id,p_run_id,p_scope_id
        );
        IF v_projected_sha IS DISTINCT FROM v_state_sha THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Notifications V1 adoption projected digest differs';
        END IF;
    END IF;
    RETURN QUERY SELECT v_applied_count,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_change jsonb;
    v_payload jsonb;
    v_manifest text;
    v_rows bigint;
    v_applied bigint;
    v_key_sha text;
    v_state_sha text;
    v_now timestamptz;
BEGIN
    v_applied := 0;
    v_now := pg_catalog.transaction_timestamp();
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind IS DISTINCT FROM 'tenant' OR
       p_checkpoint_key IS DISTINCT FROM 'notification' OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 adoption apply principal denied';
    END IF;
    SELECT operation.lease_manifest_sha256 INTO STRICT v_manifest
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind=p_scope_kind AND operation.scope_id=p_scope_id
      AND operation.group_id='notifications' AND operation.domain='notifications'
      AND operation.state IN ('planned','copying','shadow','quiescing')
    FOR SHARE;
    FOR v_change IN
        SELECT value FROM pg_catalog.jsonb_array_elements(p_change_batch->'changes')
            WITH ORDINALITY AS item(value,position) ORDER BY position
    LOOP
        v_payload := CASE v_change->>'kind'
            WHEN 'delete' THEN v_change->'before' ELSE v_change->'after'
        END;
        INSERT INTO notifications_v1_adoption_stage (
            operation_id,run_id,source_kind,source_identity,source_sha256,
            target_kind,target_identity,target_id,target_sha256,target_record,
            removed,source_xid,commit_lsn,batch_ordinal,change_ordinal,recorded_at
        ) VALUES (
            p_operation_id,p_run_id,v_payload->>'source_kind',
            v_payload->>'source_identity',
            pg_catalog.decode(v_payload->>'source_sha256','hex'),
            v_payload->>'target_kind',v_payload->>'target_identity',
            (v_payload->>'target_id')::uuid,
            pg_catalog.sha256(pg_catalog.convert_to(
                (v_payload->'target_record')::text,'UTF8'
            )),v_payload->'target_record',v_change->>'kind'='delete',
            p_source_xid,p_commit_lsn,p_batch_ordinal,
            (v_change->>'ordinal')::integer,v_now
        )
        ON CONFLICT (operation_id,run_id,target_kind,target_identity) DO UPDATE
        SET source_kind=EXCLUDED.source_kind,
            source_identity=EXCLUDED.source_identity,
            source_sha256=EXCLUDED.source_sha256,target_id=EXCLUDED.target_id,
            target_sha256=EXCLUDED.target_sha256,target_record=EXCLUDED.target_record,
            removed=EXCLUDED.removed,source_xid=EXCLUDED.source_xid,
            commit_lsn=EXCLUDED.commit_lsn,batch_ordinal=EXCLUDED.batch_ordinal,
            change_ordinal=EXCLUDED.change_ordinal,recorded_at=EXCLUDED.recorded_at
        WHERE (notifications_v1_adoption_stage.batch_ordinal,
               notifications_v1_adoption_stage.change_ordinal)
            < (EXCLUDED.batch_ordinal,EXCLUDED.change_ordinal);
        GET DIAGNOSTICS v_rows=ROW_COUNT;
        IF v_rows IS DISTINCT FROM 1::bigint THEN
            RAISE EXCEPTION USING ERRCODE='55000',
                MESSAGE='Notifications V1 adoption target checkpoint regressed';
        END IF;
        v_applied := v_applied+1;
        INSERT INTO platform.applied_change_receipts (
            receipt_id,operation_id,run_id,manifest_sha256,source_xid,
            source_commit_lsn,relation_ordinal,change_ordinal,checkpoint_key,
            mutation_kind,mutation_sha256,applied_at
        ) VALUES (
            pg_catalog.gen_random_uuid(),p_operation_id,p_run_id,v_manifest,
            p_source_xid,p_commit_lsn,p_relation_ordinal,
            (((p_batch_ordinal-1)::bigint*1000)+v_applied)::integer,
            p_checkpoint_key,v_change->>'kind',
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                p_batch_sha256||':'||v_change::text,'UTF8'
            )),'hex'),v_now
        );
    END LOOP;
    IF EXISTS (
        SELECT 1 FROM notifications_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
          AND NOT stage.removed
        GROUP BY stage.source_identity
        HAVING pg_catalog.count(DISTINCT stage.source_sha256)<>1
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 adoption source digest differs';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(stage.target_kind||':'||
            stage.target_identity||':'||pg_catalog.encode(stage.target_sha256,'hex'),
            ',' ORDER BY stage.target_kind,stage.target_identity),''),'UTF8'
    )),'hex') INTO v_key_sha
    FROM notifications_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed;
    v_state_sha := v_key_sha;
    RETURN QUERY SELECT v_applied,v_key_sha,v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_batch_assert_v1(jsonb, uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count integer;
BEGIN
    v_count := pg_catalog.jsonb_array_length(p_batch->'changes');
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 adoption evidence principal denied';
    END IF;
    IF p_scope_kind IS DISTINCT FROM 'tenant' OR p_scope_id IS NULL OR
       p_relation_ordinal NOT BETWEEN 1 AND 32767 OR
       p_checkpoint_key IS DISTINCT FROM 'notification' OR
       p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_checkpoint_state NOT IN ('initial_copy','delta','complete') OR
       (p_checkpoint_state='complete') IS DISTINCT FROM (p_final_lsn IS NOT NULL) OR
       (v_count=0 AND (
           p_checkpoint_state<>'complete' OR p_final_lsn IS DISTINCT FROM p_commit_lsn
       )) OR NOT EXISTS (
           SELECT 1 FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.tenant_id=p_scope_id
             AND identity.schema_name=pg_catalog.current_schema()
             AND identity.origin='v1_adopted'
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_operations AS operation
           WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
             AND operation.scope_kind=p_scope_kind AND operation.scope_id=p_scope_id
             AND operation.group_id='notifications' AND operation.domain='notifications'
             AND operation.state IN ('planned','copying','shadow','quiescing')
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_operation_checkpoint_keys AS expected
           WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
             AND expected.relation_ordinal=p_relation_ordinal
             AND expected.checkpoint_key=p_checkpoint_key
       ) OR (p_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (p_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       p_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (p_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       (p_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal OR
       p_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key OR
       p_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state OR
       p_batch->'last_key' IS DISTINCT FROM p_last_key OR
       p_batch->'source_position'->>'snapshot_name' IS DISTINCT FROM p_snapshot_name OR
       (p_batch->'source_position'->>'snapshot_lsn')::pg_lsn
           IS DISTINCT FROM p_snapshot_lsn OR
       (p_batch->'source_position'->>'received_lsn')::pg_lsn
           IS DISTINCT FROM p_received_lsn OR
       (p_batch->'source_position'->>'commit_lsn')::pg_lsn
           IS DISTINCT FROM p_commit_lsn OR
       (p_batch->'source_position'->>'final_lsn')::pg_lsn
           IS DISTINCT FROM p_final_lsn OR
       (p_batch->'source_position'->>'source_xid')::xid8 IS DISTINCT FROM p_source_xid OR
       (p_batch->'source_position'->>'batch_ordinal')::integer
           IS DISTINCT FROM p_batch_ordinal OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change
           WHERE COALESCE(change->'after'->>'source_kind',
                          change->'before'->>'source_kind')<>'notification'
       ) OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change
           GROUP BY COALESCE(change->'after'->>'source_identity',
                             change->'before'->>'source_identity')
           HAVING pg_catalog.count(DISTINCT COALESCE(
               change->'after'->>'source_sha256',change->'before'->>'source_sha256'
           ))<>1
       ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Notifications V1 adoption batch evidence differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_batch_decode_v1(bytea, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_actual_bytes bigint;
    v_change_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 adoption batch principal denied';
    END IF;
    v_actual_bytes := pg_catalog.octet_length(p_change_batch_bytes);
    IF p_batch_bytes IS DISTINCT FROM v_actual_bytes OR
       v_actual_bytes NOT BETWEEN 2 AND 8388608 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes),'hex')
           IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Notifications V1 adoption batch digest is invalid';
    END IF;
    v_batch := pg_catalog.convert_from(p_change_batch_bytes,'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_batch) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch) AS key)
       IS DISTINCT FROM ARRAY[
           'changes','checkpoint_key','checkpoint_state','last_key',
           'operation_id','relation_ordinal','run_id','scope_id',
           'scope_kind','source_position'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'source_position') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch->'source_position') AS key)
       IS DISTINCT FROM ARRAY[
           'batch_ordinal','commit_lsn','final_lsn','received_lsn',
           'snapshot_lsn','snapshot_name','source_xid'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'changes') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_batch->'changes') > 1000 OR
       pg_catalog.jsonb_typeof(v_batch->'last_key') NOT IN ('object','null') OR
       v_batch->'last_key'='{}'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Notifications V1 adoption batch envelope is invalid';
    END IF;
    v_change_count := pg_catalog.jsonb_array_length(v_batch->'changes');
    IF (SELECT pg_catalog.count(DISTINCT change.value->'key')
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes') AS change(value))
       IS DISTINCT FROM v_change_count::bigint OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes')
             WITH ORDINALITY AS change(value,position)
        WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.array_agg(key ORDER BY key)
               FROM pg_catalog.jsonb_object_keys(change.value) AS key)
              IS DISTINCT FROM ARRAY['after','before','key','kind','ordinal']::text[]
           OR (change.value->>'ordinal')::integer IS DISTINCT FROM change.position::integer
           OR change.value->>'kind' NOT IN ('insert','update','delete')
           OR (change.value->>'kind'='insert' AND (
                  change.value->'before'<>'null'::jsonb OR
                  NOT notifications_v1_adoption_value_valid_v1(
                      change.value->'key',change.value->'after'
                  )))
           OR (change.value->>'kind'='update' AND (
                  NOT notifications_v1_adoption_value_valid_v1(
                      change.value->'key',change.value->'before'
                  ) OR NOT notifications_v1_adoption_value_valid_v1(
                      change.value->'key',change.value->'after'
                  )))
           OR (change.value->>'kind'='delete' AND (
                  change.value->'after'<>'null'::jsonb OR
                  NOT notifications_v1_adoption_value_valid_v1(
                      change.value->'key',change.value->'before'
                  )))
    ) THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='Notifications V1 adoption batch change is invalid';
    END IF;
    RETURN v_batch;
END;
$_$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_bridge_disabled_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_bridge_disabled_v1(p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_writer text;
    v_lifecycle text;
    v_generation bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 bridge guard principal denied';
    END IF;
    SELECT authority.writer,authority.lifecycle_state,authority.generation
    INTO STRICT v_writer,v_lifecycle,v_generation
    FROM notifications_writer_authority AS authority
    WHERE authority.singleton FOR UPDATE;
    IF (v_writer='v1' AND v_lifecycle='writable') OR
       EXISTS (SELECT 1 FROM notifications_migration_intents) OR
       EXISTS (SELECT 1 FROM notifications_migration_receipts) OR
       EXISTS (
           SELECT 1 FROM notifications_compatibility_hits AS hit
           WHERE hit.contract_name='notification_intent_bridge_v1'
       ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 bridge is disabled: signed mTLS receipt contract missing';
    END IF;
    RETURN pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy/notifications/v1-bridge-disabled/v1:'||p_scope_id::text||':'||
        v_writer||':'||
        v_lifecycle||':'||v_generation::text||
        ':missing-signed-mtls-stable-effect-receipt-contract','UTF8'
    )),'hex');
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_bridge_disabled_v1(p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_legacy_evidence_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_legacy_evidence_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_operation_created timestamptz;
    v_zero_since timestamptz;
    v_state text;
    v_hit_count bigint;
    v_revision bigint;
    v_tenant_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 legacy evidence principal denied';
    END IF;
    SELECT operation.created_at INTO STRICT v_operation_created
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='notifications' AND operation.domain='notifications';
    SELECT retirement.zero_hit_since,retirement.state,
        retirement.hit_count,retirement.revision
    INTO STRICT v_zero_since,v_state,v_hit_count,v_revision
    FROM platform.contract_retirements AS retirement
    WHERE retirement.contract_key='notifications_actor_stream_v1'
      AND retirement.owner_module='notifications' AND retirement.domain='notifications'
      AND retirement.remaining_scope_count=0;
    IF v_state NOT IN ('eligible','retired') OR v_zero_since IS NULL OR
       v_zero_since>v_operation_created OR EXISTS (
        SELECT 1 FROM notifications_compatibility_hits AS hit
        WHERE hit.contract_name='notifications_actor_stream_v1'
          AND hit.occurred_at>=v_zero_since
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 legacy connection evidence is not quiet';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
        pg_catalog.string_agg(pg_catalog.to_jsonb(hit)::text,',' ORDER BY
            hit.occurred_at,hit.id),''),'UTF8')),'hex') INTO v_tenant_sha
    FROM notifications_compatibility_hits AS hit
    WHERE hit.contract_name='notifications_actor_stream_v1';
    RETURN pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy/notifications/v1-legacy-evidence/v1:'||p_operation_id::text||':'||
        p_run_id::text||':'||p_scope_id::text||':'||v_state||':'||v_revision::text||':'||
        v_hit_count::text||':'||v_zero_since::text||':'||v_tenant_sha,
        'UTF8'
    )),'hex');
END;
$$;


