ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_project_receipt_v1(p_record jsonb) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_project_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_project_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_kind text;
    v_stage notifications_v1_adoption_stage%ROWTYPE;
    v_final_lsn pg_lsn;
    v_generation bigint;
    v_source_count bigint;
    v_target_count bigint;
    v_actual_count bigint;
    v_source_sha text;
    v_target_sha text;
    v_queue_sha text;
    v_provider_sha text;
    v_legacy_sha text;
    v_bridge_sha text;
    v_receipt_sha text;
    v_rows bigint;
    v_now timestamptz;
BEGIN
    v_now := pg_catalog.transaction_timestamp();
    v_final_lsn := notifications_v1_adoption_projection_ready_v1(
        p_operation_id,p_run_id,p_scope_id
    );
    SELECT operation.cutover_generation INTO STRICT v_generation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id;
    FOREACH v_kind IN ARRAY ARRAY[
        'message','effect','delivery','attempt','receipt'
    ]::text[]
    LOOP
        FOR v_stage IN
            SELECT stage.* FROM notifications_v1_adoption_stage AS stage
            WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
              AND stage.target_kind=v_kind AND NOT stage.removed
            ORDER BY stage.target_identity
        LOOP
            CASE v_kind
                WHEN 'message' THEN
                    PERFORM notifications_v1_adoption_project_message_v1(
                        v_stage.target_record
                    );
                WHEN 'effect' THEN
                    PERFORM notifications_v1_adoption_project_effect_v1(
                        v_stage.target_record
                    );
                WHEN 'delivery' THEN
                    PERFORM notifications_v1_adoption_project_delivery_v1(
                        v_stage.target_record
                    );
                WHEN 'attempt' THEN
                    PERFORM notifications_v1_adoption_project_attempt_v1(
                        v_stage.target_record
                    );
                WHEN 'receipt' THEN
                    PERFORM notifications_v1_adoption_project_receipt_v1(
                        v_stage.target_record
                    );
            END CASE;
        END LOOP;
    END LOOP;
    IF EXISTS (
        SELECT 1 FROM notifications_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
          AND NOT stage.removed AND (
            stage.target_kind='message' AND NOT EXISTS (
                SELECT 1 FROM notifications_messages AS target
                WHERE target.id=stage.target_id
                  AND pg_catalog.to_jsonb(target)=stage.target_record
            ) OR stage.target_kind='effect' AND NOT EXISTS (
                SELECT 1 FROM notifications_effect_receipts AS target
                WHERE target.message_id=stage.target_id
                  AND pg_catalog.to_jsonb(target)=stage.target_record
            ) OR stage.target_kind='delivery' AND NOT EXISTS (
                SELECT 1 FROM notifications_deliveries AS target
                WHERE target.id=stage.target_id
                  AND pg_catalog.to_jsonb(target)=stage.target_record
            ) OR stage.target_kind='attempt' AND NOT EXISTS (
                SELECT 1 FROM notifications_delivery_attempts AS target
                WHERE target.id=stage.target_id
                  AND pg_catalog.to_jsonb(target)=stage.target_record
            ) OR stage.target_kind='receipt' AND NOT EXISTS (
                SELECT 1 FROM notifications_delivery_receipts AS target
                WHERE target.id=stage.target_id
                  AND pg_catalog.to_jsonb(target)=stage.target_record
            )
          )
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 projected target differs from signed source';
    END IF;
    SELECT pg_catalog.count(*),pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
            source_identity||':'||source_sha256,',' ORDER BY source_identity),''),'UTF8'
        )),'hex') INTO v_source_count,v_source_sha
    FROM (
        SELECT stage.source_identity,
            pg_catalog.min(pg_catalog.encode(stage.source_sha256,'hex')) AS source_sha256
        FROM notifications_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
          AND NOT stage.removed GROUP BY stage.source_identity
    ) AS source;
    SELECT pg_catalog.count(*),pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
            stage.target_kind||':'||stage.target_identity||':'||
            pg_catalog.encode(stage.target_sha256,'hex'),',' ORDER BY
            stage.target_kind,stage.target_identity),''),'UTF8')),'hex')
    INTO v_target_count,v_target_sha
    FROM notifications_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed;
    SELECT (SELECT pg_catalog.count(*) FROM notifications_messages)+
        (SELECT pg_catalog.count(*) FROM notifications_effect_receipts)+
        (SELECT pg_catalog.count(*) FROM notifications_deliveries)+
        (SELECT pg_catalog.count(*) FROM notifications_delivery_attempts)+
        (SELECT pg_catalog.count(*) FROM notifications_delivery_receipts)
    INTO v_actual_count;
    IF v_actual_count IS DISTINCT FROM v_target_count THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 projected target count differs';
    END IF;
    v_queue_sha := notifications_v1_adoption_queue_evidence_v1(
        p_operation_id,p_run_id,p_scope_id
    );
    v_provider_sha := notifications_v1_adoption_provider_evidence_v1(p_scope_id);
    v_legacy_sha := notifications_v1_adoption_legacy_evidence_v1(
        p_operation_id,p_run_id,p_scope_id
    );
    v_bridge_sha := notifications_v1_adoption_bridge_disabled_v1(p_scope_id);
    v_receipt_sha := pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy/notifications/v1-cutover-receipt/v1:'||p_operation_id::text||':'||
        p_run_id::text||':'||p_scope_id::text||':'||v_generation::text||':'||
        v_source_count::text||':'||v_target_count::text||':'||v_source_sha||':'||
        v_target_sha||':'||v_queue_sha||':'||v_provider_sha||':'||v_legacy_sha||':'||
        v_bridge_sha||':'||v_final_lsn::text,'UTF8'
    )),'hex');
    INSERT INTO notifications_v1_cutover_receipts(
        operation_id,run_id,tenant_id,cutover_generation,source_count,target_count,
        source_root_sha256,target_root_sha256,queue_evidence_sha256,
        provider_evidence_sha256,legacy_evidence_sha256,bridge_state,final_lsn,
        projected_at,receipt_sha256
    ) VALUES (
        p_operation_id,p_run_id,p_scope_id,v_generation,v_source_count,v_target_count,
        v_source_sha,v_target_sha,v_queue_sha,v_provider_sha,v_legacy_sha,
        'disabled_missing_signed_mtls_contract',v_final_lsn,v_now,v_receipt_sha
    );
    UPDATE notifications_writer_authority SET writer='v2',lifecycle_state='writable',
        generation=v_generation,row_version=row_version+1,updated_at=v_now
    WHERE singleton AND generation<v_generation AND (
        writer='unassigned' AND lifecycle_state='bootstrap' OR
        writer='v1' AND lifecycle_state IN ('quiescing','fenced')
    );
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 writer authority switch differs';
    END IF;
    RETURN v_target_sha;
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_project_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_projection_ready_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_projection_ready_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS pg_lsn
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_expected bigint;
    v_complete bigint;
    v_final_count bigint;
    v_final_lsn pg_lsn;
    v_existing bigint;
    v_assert text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 projection principal denied';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.tenant_id=p_scope_id
          AND identity.schema_name=pg_catalog.current_schema()
          AND identity.origin='v1_adopted'
    ) OR NOT EXISTS (
        SELECT 1 FROM platform.cutover_operations AS operation
        WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
          AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
          AND operation.group_id='notifications' AND operation.domain='notifications'
          AND operation.state IN ('planned','copying','shadow','quiescing')
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 projection authority is not ready';
    END IF;
    SELECT pg_catalog.count(*) INTO v_expected
    FROM platform.cutover_operation_checkpoint_keys AS expected
    WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
      AND expected.checkpoint_key='notification';
    SELECT pg_catalog.count(*),pg_catalog.count(DISTINCT checkpoint.final_lsn::text)
    INTO v_complete,v_final_count
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id
      AND checkpoint.state='complete' AND checkpoint.final_lsn IS NOT NULL;
    IF v_expected IS DISTINCT FROM 1::bigint OR
       (SELECT pg_catalog.count(*)
        FROM platform.cutover_operation_checkpoint_keys AS expected
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id)
       IS DISTINCT FROM 1::bigint OR v_complete IS DISTINCT FROM v_expected OR
       v_final_count IS DISTINCT FROM 1::bigint OR EXISTS (
        SELECT 1
        FROM platform.cutover_operation_checkpoint_keys AS expected
        LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint
          ON checkpoint.operation_id=expected.operation_id
         AND checkpoint.run_id=expected.run_id
         AND checkpoint.relation_ordinal=expected.relation_ordinal
         AND checkpoint.checkpoint_key=expected.checkpoint_key
         AND checkpoint.state='complete'
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
          AND checkpoint.operation_id IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 projection checkpoint is incomplete';
    END IF;
    SELECT checkpoint.final_lsn INTO STRICT v_final_lsn
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id
    LIMIT 1;
    IF EXISTS (
        SELECT 1 FROM (
            SELECT stage.source_identity
            FROM notifications_v1_adoption_stage AS stage
            WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
              AND NOT stage.removed GROUP BY stage.source_identity
        ) AS source
        WHERE (SELECT pg_catalog.count(*)
               FROM notifications_v1_adoption_stage AS primary_row
               WHERE primary_row.operation_id=p_operation_id
                 AND primary_row.run_id=p_run_id AND NOT primary_row.removed
                 AND primary_row.source_identity=source.source_identity
                 AND primary_row.target_kind='message')<>1
           OR (SELECT pg_catalog.count(*)
               FROM notifications_v1_adoption_stage AS effect_row
               WHERE effect_row.operation_id=p_operation_id
                 AND effect_row.run_id=p_run_id AND NOT effect_row.removed
                 AND effect_row.source_identity=source.source_identity
                 AND effect_row.target_kind='effect')<>1
           OR (SELECT pg_catalog.count(*)
               FROM notifications_v1_adoption_stage AS delivery_row
               WHERE delivery_row.operation_id=p_operation_id
                 AND delivery_row.run_id=p_run_id AND NOT delivery_row.removed
                 AND delivery_row.source_identity=source.source_identity
                 AND delivery_row.target_kind='delivery')
              <>(SELECT pg_catalog.count(*)
                 FROM notifications_v1_adoption_stage AS attempt_row
                 WHERE attempt_row.operation_id=p_operation_id
                   AND attempt_row.run_id=p_run_id AND NOT attempt_row.removed
                   AND attempt_row.source_identity=source.source_identity
                   AND attempt_row.target_kind='attempt')
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 source-target mapping is incomplete';
    END IF;
    SELECT (SELECT pg_catalog.count(*) FROM notifications_inbox_counters)+
        (SELECT pg_catalog.count(*) FROM notifications_messages)+
        (SELECT pg_catalog.count(*) FROM notifications_effect_receipts)+
        (SELECT pg_catalog.count(*) FROM notifications_deliveries)+
        (SELECT pg_catalog.count(*) FROM notifications_delivery_attempts)+
        (SELECT pg_catalog.count(*) FROM notifications_delivery_receipts)+
        (SELECT pg_catalog.count(*) FROM notifications_v1_cutover_receipts)
    INTO v_existing;
    IF v_existing<>0 THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 inactive target is not empty';
    END IF;
    v_assert := notifications_v1_adoption_queue_evidence_v1(
        p_operation_id,p_run_id,p_scope_id
    );
    v_assert := notifications_v1_adoption_legacy_evidence_v1(
        p_operation_id,p_run_id,p_scope_id
    );
    v_assert := notifications_v1_adoption_bridge_disabled_v1(p_scope_id);
    RETURN v_final_lsn;
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_projection_ready_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_provider_evidence_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_provider_evidence_v1(p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_delivery_sha text;
    v_attempt_sha text;
    v_receipt_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 provider evidence principal denied';
    END IF;
    IF EXISTS (
        SELECT 1 FROM notifications_deliveries AS delivery
        WHERE delivery.state IN ('pending','sending') OR delivery.outcome_unknown
           OR delivery.lease_owner<>'' OR delivery.lease_until IS NOT NULL
    ) OR EXISTS (
        SELECT 1 FROM notifications_effect_receipts AS effect
        WHERE effect.outcome IN ('pending','outcome_unknown')
    ) OR EXISTS (
        SELECT 1 FROM notifications_deliveries AS delivery
        WHERE NOT EXISTS (
            SELECT 1 FROM notifications_delivery_attempts AS attempt
            WHERE attempt.delivery_id=delivery.id
        ) OR (SELECT pg_catalog.count(*)
              FROM notifications_delivery_attempts AS attempt
              WHERE attempt.delivery_id=delivery.id)<>delivery.attempt::bigint
          OR (SELECT pg_catalog.max(attempt.attempt_number)
              FROM notifications_delivery_attempts AS attempt
              WHERE attempt.delivery_id=delivery.id) IS DISTINCT FROM delivery.attempt
    ) OR EXISTS (
        SELECT 1 FROM notifications_deliveries AS delivery
        WHERE delivery.state='accepted' AND NOT EXISTS (
            SELECT 1 FROM notifications_delivery_attempts AS attempt
            WHERE attempt.delivery_id=delivery.id
              AND attempt.response_class='legacy_v1_accepted'
        )
    ) OR EXISTS (
        SELECT 1 FROM notifications_deliveries AS delivery
        WHERE delivery.state IN ('delivered','bounced') AND NOT EXISTS (
            SELECT 1 FROM notifications_delivery_receipts AS receipt
            WHERE receipt.delivery_id=delivery.id
              AND receipt.outcome=delivery.state
              AND receipt.signature_key_id NOT LIKE 'legacy%'
        )
    ) THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 provider receipt evidence is incomplete';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
        pg_catalog.string_agg(pg_catalog.to_jsonb(delivery)::text,',' ORDER BY delivery.id),
        ''),'UTF8')),'hex') INTO v_delivery_sha FROM notifications_deliveries AS delivery;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
        pg_catalog.string_agg(pg_catalog.to_jsonb(attempt)::text,',' ORDER BY attempt.id),
        ''),'UTF8')),'hex') INTO v_attempt_sha
    FROM notifications_delivery_attempts AS attempt;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
        pg_catalog.string_agg(pg_catalog.to_jsonb(receipt)::text,',' ORDER BY receipt.id),
        ''),'UTF8')),'hex') INTO v_receipt_sha
    FROM notifications_delivery_receipts AS receipt;
    RETURN pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy/notifications/v1-provider-evidence/v1:'||p_scope_id::text||':'||
        v_delivery_sha||':'||v_attempt_sha||':'||v_receipt_sha,
        'UTF8'
    )),'hex');
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_provider_evidence_v1(p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_queue_evidence_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_queue_evidence_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_generation bigint;
    v_async_run uuid;
    v_inventory text;
    v_acceptance text;
    v_zero text;
    v_zero_inventory text;
    v_expected_items bigint;
    v_items bigint;
    v_dispositions bigint;
    v_expected_enqueue smallint;
    v_expected_scheduler smallint;
    v_expected_consumer smallint;
    v_enqueue bigint;
    v_scheduler bigint;
    v_consumer bigint;
    v_disposition_sha text;
    v_fence_sha text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE='42501',
            MESSAGE='Notifications V1 queue evidence principal denied';
    END IF;
    SELECT operation.cutover_generation INTO STRICT v_generation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='notifications' AND operation.domain='notifications';
    SELECT adoption.run_id,adoption.inventory_sha256,adoption.acceptance_sha256,
        adoption.item_count,adoption.expected_enqueue_fences,
        adoption.expected_scheduler_fences,adoption.expected_consumer_fences
    INTO STRICT v_async_run,v_inventory,v_acceptance,v_expected_items,
        v_expected_enqueue,v_expected_scheduler,v_expected_consumer
    FROM platform.async_v1_adoption_runs AS adoption
    WHERE adoption.scope_kind='tenant' AND adoption.scope_id=p_scope_id
      AND adoption.domain='notifications' AND adoption.group_id='notifications'
      AND adoption.target_generation=v_generation AND adoption.state='accepted';
    SELECT zero.receipt_sha256,zero.inventory_sha256
    INTO STRICT v_zero,v_zero_inventory
    FROM platform.async_v1_zero_inventory_receipts AS zero
    WHERE zero.run_id=v_async_run AND zero.queue_count=0 AND zero.timer_count=0
      AND zero.future_count=0 AND zero.running_count=0;
    SELECT pg_catalog.count(*) INTO v_items
    FROM platform.async_v1_adoption_items AS item WHERE item.run_id=v_async_run;
    SELECT pg_catalog.count(*),pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
            disposition.receipt_sha256,',' ORDER BY disposition.inventory_class,
            disposition.source_name,disposition.source_item_id),''),'UTF8'
        )),'hex')
    INTO v_dispositions,v_disposition_sha
    FROM platform.async_v1_adoption_dispositions AS disposition
    WHERE disposition.run_id=v_async_run;
    SELECT pg_catalog.count(*) FILTER (WHERE fence.fence_kind='enqueue'),
        pg_catalog.count(*) FILTER (WHERE fence.fence_kind='scheduler'),
        pg_catalog.count(*) FILTER (WHERE fence.fence_kind='consumer'),
        pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(COALESCE(
            pg_catalog.string_agg(fence.receipt_sha256,',' ORDER BY fence.fence_kind,
                fence.component_name),''),'UTF8')),'hex')
    INTO v_enqueue,v_scheduler,v_consumer,v_fence_sha
    FROM platform.async_v1_restart_fence_receipts AS fence
    WHERE fence.run_id=v_async_run;
    IF v_zero_inventory IS DISTINCT FROM v_inventory OR
       v_items IS DISTINCT FROM v_expected_items OR
       v_dispositions IS DISTINCT FROM v_expected_items OR
       v_enqueue IS DISTINCT FROM v_expected_enqueue::bigint OR
       v_scheduler IS DISTINCT FROM v_expected_scheduler::bigint OR
       v_consumer IS DISTINCT FROM v_expected_consumer::bigint THEN
        RAISE EXCEPTION USING ERRCODE='55000',
            MESSAGE='Notifications V1 queue adoption evidence differs';
    END IF;
    RETURN pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        'harpy/notifications/v1-queue-evidence/v1:'||p_operation_id::text||':'||
        p_run_id::text||':'||v_async_run::text||':'||v_generation::text||':'||
        v_inventory||':'||v_acceptance||':'||v_zero||':'||v_disposition_sha||':'||
        v_fence_sha||':'||v_expected_items::text,'UTF8'
    )),'hex');
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_queue_evidence_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_target_record_valid_v1(text, text, uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_target_record_valid_v1(p_target_kind text, p_target_identity text, p_target_id uuid, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_relation oid;
    v_identity text;
    v_target_id text;
    v_semantic boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' OR
       p_record = '{}'::jsonb OR pg_catalog.octet_length(p_record::text) > 1048576 OR
       p_target_id = '00000000-0000-0000-0000-000000000000'::uuid THEN
        RETURN false;
    END IF;
    v_relation := CASE p_target_kind
        WHEN 'message' THEN 'notifications_messages'::regclass::oid
        WHEN 'effect' THEN 'notifications_effect_receipts'::regclass::oid
        WHEN 'delivery' THEN 'notifications_deliveries'::regclass::oid
        WHEN 'attempt' THEN 'notifications_delivery_attempts'::regclass::oid
        WHEN 'receipt' THEN 'notifications_delivery_receipts'::regclass::oid
        ELSE NULL
    END;
    IF v_relation IS NULL THEN
        RETURN false;
    END IF;
    v_identity := CASE p_target_kind
        WHEN 'message' THEN p_record->>'id'
        WHEN 'effect' THEN p_record->>'message_id'
        WHEN 'delivery' THEN p_record->>'id'
        WHEN 'attempt' THEN p_record->>'id'
        WHEN 'receipt' THEN p_record->>'id'
    END;
    v_target_id := CASE p_target_kind
        WHEN 'effect' THEN p_record->>'message_id'
        ELSE p_record->>'id'
    END;
    v_semantic := CASE p_target_kind
        WHEN 'message' THEN
            p_record->>'producer'='legacy_v1' AND
            p_record->>'template_version_id'=
                '12000000-0000-4000-8000-000000000002' AND
            p_record->>'template_kind'='plain_text' AND p_record->>'locale'='tr' AND
            p_record->>'row_version'='1' AND p_record->>'dismissed_at' IS NULL AND
            p_record->>'purged_at' IS NULL
        WHEN 'effect' THEN
            p_record->>'producer'='legacy_v1' AND p_record->>'outcome'='created' AND
            p_record->>'legacy_receipt_reference'=
                'v1:notifications:'||(p_record->>'message_id')
        WHEN 'delivery' THEN
            p_record->>'provider_config_version_id' IS NULL AND
            p_record->>'channel'='email' AND p_record->>'state'='accepted' AND
            p_record->>'attempt'='1' AND p_record->>'maximum_attempts'='8' AND
            p_record->>'lease_owner'='' AND p_record->>'lease_generation'='1' AND
            p_record->>'lease_until' IS NULL AND p_record->>'outcome_code'='V1_ACCEPTED' AND
            p_record->>'outcome_unknown'='false' AND p_record->>'mandatory'='false' AND
            p_record->>'row_version'='2'
        WHEN 'attempt' THEN
            p_record->>'attempt_number'='1' AND p_record->>'lease_generation'='1' AND
            p_record->>'provider_kind'='smtp' AND
            p_record->>'response_class'='legacy_v1_accepted' AND
            p_record->>'status_code'='' AND p_record->>'error_code'='V1_ACCEPTED' AND
            p_record->>'started_at'=p_record->>'finished_at'
        WHEN 'receipt' THEN
            pg_catalog.octet_length(p_record->>'signature_key_id') BETWEEN 1 AND 256 AND
            p_record->>'signature_key_id' NOT LIKE 'legacy%' AND
            p_record->>'outcome' IN ('delivered','bounced','complained')
        ELSE false
    END;
    RETURN v_semantic AND
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_record) AS key)
       IS NOT DISTINCT FROM
       (SELECT pg_catalog.array_agg(attribute.attname::text ORDER BY attribute.attname::text)
        FROM pg_catalog.pg_attribute AS attribute
        WHERE attribute.attrelid=v_relation AND attribute.attnum>0
          AND NOT attribute.attisdropped)
       AND v_identity IS NOT DISTINCT FROM p_target_identity
       AND v_target_id IS NOT DISTINCT FROM p_target_id::text;
END;
$$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_target_record_valid_v1(p_target_kind text, p_target_identity text, p_target_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: notifications_v1_adoption_value_valid_v1(jsonb, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.notifications_v1_adoption_value_valid_v1(p_key jsonb, p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_target_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.jsonb_typeof(p_key) IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(p_value) IS DISTINCT FROM 'object' THEN
        RETURN false;
    END IF;
    IF (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_key) AS key) IS DISTINCT FROM ARRAY[
           'source_identity','source_kind','target_identity','target_kind'
       ]::text[] OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(p_value) AS key) IS DISTINCT FROM ARRAY[
           'source_identity','source_kind','source_sha256','target_id',
           'target_identity','target_kind','target_record'
       ]::text[] OR
       p_value->>'source_identity' IS DISTINCT FROM p_key->>'source_identity' OR
       p_value->>'source_kind' IS DISTINCT FROM p_key->>'source_kind' OR
       p_value->>'target_identity' IS DISTINCT FROM p_key->>'target_identity' OR
       p_value->>'target_kind' IS DISTINCT FROM p_key->>'target_kind' OR
       p_value->>'source_kind' IS DISTINCT FROM 'notification' OR
       p_value->>'target_kind' NOT IN ('message','effect','delivery','attempt','receipt') OR
       pg_catalog.octet_length(p_value->>'source_identity') NOT BETWEEN 1 AND 512 OR
       p_value->>'source_identity' OPERATOR(pg_catalog.~) '[[:cntrl:]]' OR
       pg_catalog.octet_length(p_value->>'target_identity') NOT BETWEEN 1 AND 1024 OR
       p_value->>'target_identity' OPERATOR(pg_catalog.~) '[[:cntrl:]]' OR
       p_value->>'source_sha256' !~ '^[0-9a-f]{64}$' THEN
        RETURN false;
    END IF;
    BEGIN
        v_target_id := (p_value->>'target_id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        RETURN false;
    END;
    RETURN notifications_v1_adoption_target_record_valid_v1(
        p_value->>'target_kind',p_value->>'target_identity',
        v_target_id,p_value->'target_record'
    );
END;
$_$;


ALTER FUNCTION __tenant_schema__.notifications_v1_adoption_value_valid_v1(p_key jsonb, p_value jsonb) OWNER TO harpy_owner;

