--
-- Name: system_resource_layout_canonical_json_v1(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_canonical_json_v1(p_value jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_kind text;
    v_result text;
BEGIN
    v_kind := pg_catalog.jsonb_typeof(p_value);
    IF v_kind = 'object' THEN
        SELECT '{' || COALESCE(pg_catalog.string_agg(
            pg_catalog.to_json(entry.key)::text || ':' ||
            system_resource_layout_canonical_json_v1(entry.value),
            ',' ORDER BY entry.key COLLATE "C"
        ), '') || '}'
        INTO v_result
        FROM pg_catalog.jsonb_each(p_value) AS entry(key, value);
        RETURN v_result;
    ELSIF v_kind = 'array' THEN
        SELECT '[' || COALESCE(pg_catalog.string_agg(
            system_resource_layout_canonical_json_v1(entry.value),
            ',' ORDER BY entry.ordinality
        ), '') || ']'
        INTO v_result
        FROM pg_catalog.jsonb_array_elements(p_value)
            WITH ORDINALITY AS entry(value, ordinality);
        RETURN v_result;
    ELSIF v_kind IN ('string', 'number', 'boolean', 'null') THEN
        RETURN p_value::text;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '22023',
        MESSAGE = 'system resource layout canonical JSON input is invalid';
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_canonical_json_v1(p_value jsonb) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_compile_curated_v1(uuid, timestamp with time zone, text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_compile_curated_v1(p_revision_id uuid, p_created_at timestamp with time zone, p_definition_json text, p_catalog_json text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_definition jsonb;
    v_catalog jsonb;
    v_surface jsonb;
    v_section jsonb;
    v_field jsonb;
    v_kind text;
    v_field_id text;
    v_mode text;
    v_interaction text;
    v_widget text;
    v_fields jsonb;
    v_surfaces jsonb;
    v_surface_translations jsonb;
    v_section_translations jsonb;
    v_seed text;
BEGIN
    v_definition := p_definition_json::jsonb;
    v_catalog := p_catalog_json::jsonb;
    v_surfaces := '[]'::jsonb;
    v_seed := p_revision_id::text;
    IF p_revision_id IS NULL OR p_created_at IS NULL
       OR v_definition ->> 'contract' <> 'harpy/system-resource-layout/v2'
       OR v_catalog ->> 'contract' <> 'forms-presentation-field-catalog.v1' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'system resource curated compiler input is invalid';
    END IF;
    FOR v_surface IN
        SELECT value FROM pg_catalog.jsonb_array_elements(
            v_definition -> 'surfaces'
        )
    LOOP
        v_kind := v_surface ->> 'kind';
        v_section := v_surface -> 'sections' -> 0;
        v_fields := '[]'::jsonb;
        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'label', translation.value ->> 'label',
                'locale', translation.value ->> 'locale'
            ) ORDER BY translation.value ->> 'locale'
        ), '[]'::jsonb)
        INTO v_surface_translations
        FROM pg_catalog.jsonb_array_elements(
            v_surface -> 'translations'
        ) AS translation(value);
        SELECT COALESCE(pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'label', translation.value ->> 'label',
                'locale', translation.value ->> 'locale'
            ) ORDER BY translation.value ->> 'locale'
        ), '[]'::jsonb)
        INTO v_section_translations
        FROM pg_catalog.jsonb_array_elements(
            v_section -> 'translations'
        ) AS translation(value);
        FOR v_field IN
            SELECT value FROM pg_catalog.jsonb_array_elements(
                v_section -> 'fields'
            ) ORDER BY (value ->> 'order')::bigint, value ->> 'field_id'
        LOOP
            v_field_id := v_field ->> 'field_id';
            SELECT field.value ->> 'mode' INTO v_mode
            FROM pg_catalog.jsonb_array_elements(
                v_catalog -> 'fields'
            ) AS field(value)
            WHERE field.value ->> 'id' = v_field_id;
            IF v_mode IS NULL THEN
                RAISE EXCEPTION USING ERRCODE = '23514',
                    MESSAGE = 'system resource curated field is outside catalog';
            END IF;
            v_interaction := v_field ->> 'interaction';
            IF (v_kind IN ('record_detail','record_list','record_filter')
                OR v_mode = 'read_only') AND v_interaction <> 'disabled' THEN
                v_interaction := 'read_only';
            END IF;
            v_widget := CASE
                WHEN v_kind IN ('record_detail','record_list','record_filter')
                    THEN 'auto'
                ELSE v_field ->> 'widget'
            END;
            v_fields := v_fields || pg_catalog.jsonb_build_array(
                pg_catalog.jsonb_build_object(
                    'field_id',v_field_id,
                    'id',system_resource_layout_deterministic_uuid_v7_v1(
                        v_seed,v_kind || ':field:' || v_field_id,p_created_at
                    )::text,
                    'interaction',v_interaction,'kind','field','span',1,
                    'translations',(
                        SELECT COALESCE(pg_catalog.jsonb_agg(
                            pg_catalog.jsonb_build_object(
                                'label', translation.value ->> 'label',
                                'locale', translation.value ->> 'locale'
                            ) ORDER BY translation.value ->> 'locale'
                        ), '[]'::jsonb)
                        FROM pg_catalog.jsonb_array_elements(
                            v_field -> 'translations'
                        ) AS translation(value)
                    ),
                    'widget',v_widget
                )
            );
        END LOOP;
        v_surfaces := v_surfaces || pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object(
                'id',system_resource_layout_deterministic_uuid_v7_v1(
                    v_seed,v_kind || ':surface',p_created_at
                )::text,
                'kind',v_kind,
                'root',pg_catalog.jsonb_build_object(
                    'children',pg_catalog.jsonb_build_array(
                        pg_catalog.jsonb_build_object(
                            'children',v_fields,
                            'id',system_resource_layout_deterministic_uuid_v7_v1(
                                v_seed,v_kind || ':section:' ||
                                (v_section ->> 'id'),p_created_at
                            )::text,
                            'kind','container','span',1,
                            'translations',v_section_translations,
                            'variant','section'
                        )
                    ),
                    'id',system_resource_layout_deterministic_uuid_v7_v1(
                        v_seed,v_kind || ':root',p_created_at
                    )::text,
                    'kind','container','span',1,
                    'translations','[]'::jsonb,'variant','stack'
                ),
                'translations',v_surface_translations
            )
        );
    END LOOP;
    RETURN system_resource_layout_canonical_json_v1(
        pg_catalog.jsonb_build_object(
            'default_locale','en','locales',pg_catalog.jsonb_build_array('en','tr'),
            'registry_contract','forms-presentation-registry.v1',
            'surfaces',v_surfaces
        )
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_compile_curated_v1(p_revision_id uuid, p_created_at timestamp with time zone, p_definition_json text, p_catalog_json text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_create_v1(name, uuid, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_create_v1(p_scope_schema name, p_revision_id uuid, p_resource_kind text, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_resource_kind NOT IN ('user', 'organization', 'role')
       OR p_revision_id =
          '00000000-0000-0000-0000-000000000000'::uuid
       OR p_now IS NULL
       OR NOT system_resource_layout_definition_valid_v1(p_definition_json)
       OR pg_catalog.octet_length(p_definition_sha256) <> 32
       OR p_definition_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_definition_json, 'UTF8')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_create_contract_guard',
            MESSAGE = 'system resource layout create contract is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:system_resource_layout:' ||
        pg_catalog.current_schema() || ':' || p_resource_kind, 0
    ));
    SELECT COALESCE(pg_catalog.max(revision.version), 0) + 1
    INTO v_version
    FROM system_resource_layout_revisions AS revision
    WHERE revision.resource_kind = p_resource_kind;
    INSERT INTO system_resource_layout_revisions (
        id, resource_kind, version, state, definition_json,
        definition_sha256, created_at, updated_at, published_at,
        row_revision
    ) VALUES (
        p_revision_id, p_resource_kind, v_version, 'draft',
        p_definition_json, p_definition_sha256, p_now, p_now, NULL, 1
    );
    RETURN system_resource_layout_revision_json_v1(p_revision_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_create_v1(p_scope_schema name, p_revision_id uuid, p_resource_kind text, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_create_v2(name, uuid, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_create_v2(p_scope_schema name, p_revision_id uuid, p_resource_kind text, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_resource_kind NOT IN ('user', 'organization', 'role')
       OR p_revision_id = '00000000-0000-0000-0000-000000000000'::uuid
       OR p_now IS NULL
       OR NOT system_resource_layout_definition_valid_v2(p_definition_json)
       OR pg_catalog.octet_length(p_definition_sha256) <> 32
       OR p_definition_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_definition_json, 'UTF8')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_create_v2_contract_guard',
            MESSAGE = 'system resource layout v2 create contract is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:system_resource_layout:' ||
        pg_catalog.current_schema() || ':' || p_resource_kind, 0
    ));
    SELECT COALESCE(pg_catalog.max(revision.version), 0) + 1
    INTO v_version
    FROM system_resource_layout_revisions AS revision
    WHERE revision.resource_kind = p_resource_kind;
    INSERT INTO system_resource_layout_revisions (
        id, resource_kind, version, state, definition_json,
        definition_sha256, created_at, updated_at, published_at, row_revision
    ) VALUES (
        p_revision_id, p_resource_kind, v_version, 'draft', p_definition_json,
        p_definition_sha256, p_now, p_now, NULL, 1
    );
    RETURN system_resource_layout_revision_json_v1(p_revision_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_create_v2(p_scope_schema name, p_revision_id uuid, p_resource_kind text, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_create_v3(name, uuid, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_create_v3(p_scope_schema name, p_revision_id uuid, p_resource_kind text, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing_definition_json text;
    v_existing_definition_sha256 bytea;
    v_existing_resource_kind text;
    v_version bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_resource_kind NOT IN ('user', 'organization', 'role')
       OR pg_catalog.uuid_extract_version(p_revision_id) IS DISTINCT FROM 7
       OR p_now IS NULL
       OR NOT system_resource_layout_definition_valid_v2(p_definition_json)
       OR pg_catalog.octet_length(p_definition_sha256) <> 32
       OR p_definition_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_definition_json, 'UTF8')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_create_v3_contract_guard',
            MESSAGE = 'system resource layout v3 create contract is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'harpy:system_resource_layout:' ||
        pg_catalog.current_schema() || ':' || p_resource_kind, 0
    ));
    SELECT revision.resource_kind, revision.definition_json,
           revision.definition_sha256
    INTO v_existing_resource_kind, v_existing_definition_json,
         v_existing_definition_sha256
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing_resource_kind IS DISTINCT FROM p_resource_kind
           OR v_existing_definition_json IS DISTINCT FROM p_definition_json
           OR v_existing_definition_sha256 IS DISTINCT FROM p_definition_sha256 THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'system resource layout create identity conflicts';
        END IF;
        RETURN system_resource_layout_revision_json_v1(p_revision_id);
    END IF;
    SELECT COALESCE(pg_catalog.max(revision.version), 0) + 1
    INTO v_version
    FROM system_resource_layout_revisions AS revision
    WHERE revision.resource_kind = p_resource_kind;
    INSERT INTO system_resource_layout_revisions (
        id, resource_kind, version, state, definition_json,
        definition_sha256, created_at, updated_at, published_at, row_revision
    ) VALUES (
        p_revision_id, p_resource_kind, v_version, 'draft', p_definition_json,
        p_definition_sha256, p_now, p_now, NULL, 1
    );
    RETURN system_resource_layout_revision_json_v1(p_revision_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_create_v3(p_scope_schema name, p_revision_id uuid, p_resource_kind text, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_curated_definition_v1(text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_curated_definition_v1(p_resource_kind text, p_catalog_json text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_catalog jsonb;
    v_surface text;
    v_allowed jsonb;
    v_fields jsonb;
    v_surfaces jsonb;
    v_en text;
    v_tr text;
BEGIN
    v_catalog := p_catalog_json::jsonb;
    v_surfaces := '[]'::jsonb;
    IF p_resource_kind NOT IN ('user','organization','role')
       OR v_catalog ->> 'contract' <> 'forms-presentation-field-catalog.v1'
       OR pg_catalog.jsonb_typeof(v_catalog -> 'fields') <> 'array' THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'system resource curated definition input is invalid';
    END IF;
    FOREACH v_surface IN ARRAY ARRAY[
        'record_create','record_update','record_detail',
        'record_list','record_filter'
    ] LOOP
        v_allowed := CASE p_resource_kind || ':' || v_surface
        WHEN 'user:record_create' THEN pg_catalog.to_jsonb(ARRAY[
            'a1000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000003',
            'a1000000-0000-4000-8000-000000000007','a1000000-0000-4000-8000-000000000006'])
        WHEN 'user:record_update' THEN pg_catalog.to_jsonb(ARRAY[
            'a1000000-0000-4000-8000-000000000007','a1000000-0000-4000-8000-000000000006'])
        WHEN 'user:record_detail' THEN pg_catalog.to_jsonb(ARRAY[
            'a1000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000004',
            'a1000000-0000-4000-8000-000000000005','a1000000-0000-4000-8000-000000000007',
            'a1000000-0000-4000-8000-000000000006','a1000000-0000-4000-8000-00000000000a',
            'a1000000-0000-4000-8000-00000000000b'])
        WHEN 'user:record_list' THEN pg_catalog.to_jsonb(ARRAY[
            'a1000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000004',
            'a1000000-0000-4000-8000-000000000005','a1000000-0000-4000-8000-000000000007',
            'a1000000-0000-4000-8000-000000000006','a1000000-0000-4000-8000-00000000000a'])
        WHEN 'user:record_filter' THEN pg_catalog.to_jsonb(ARRAY[
            'a1000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000004',
            'a1000000-0000-4000-8000-000000000005'])
        WHEN 'role:record_create' THEN pg_catalog.to_jsonb(ARRAY[
            'b1000000-0000-4000-8000-000000000005','b1000000-0000-4000-8000-000000000006',
            'b1000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000004'])
        WHEN 'role:record_update' THEN pg_catalog.to_jsonb(ARRAY[
            'b1000000-0000-4000-8000-000000000005','b1000000-0000-4000-8000-000000000006',
            'b1000000-0000-4000-8000-000000000009'])
        WHEN 'role:record_detail' THEN pg_catalog.to_jsonb(ARRAY[
            'b1000000-0000-4000-8000-000000000005','b1000000-0000-4000-8000-000000000006',
            'b1000000-0000-4000-8000-000000000007','b1000000-0000-4000-8000-000000000002',
            'b1000000-0000-4000-8000-000000000004','b1000000-0000-4000-8000-000000000008',
            'b1000000-0000-4000-8000-000000000009',
            'b1000000-0000-4000-8000-00000000000d','b1000000-0000-4000-8000-00000000000e'])
        WHEN 'role:record_list' THEN pg_catalog.to_jsonb(ARRAY[
            'b1000000-0000-4000-8000-000000000005','b1000000-0000-4000-8000-000000000006',
            'b1000000-0000-4000-8000-000000000007','b1000000-0000-4000-8000-000000000002',
            'b1000000-0000-4000-8000-000000000004','b1000000-0000-4000-8000-000000000008',
            'b1000000-0000-4000-8000-000000000009',
            'b1000000-0000-4000-8000-00000000000d'])
        WHEN 'role:record_filter' THEN pg_catalog.to_jsonb(ARRAY[
            'b1000000-0000-4000-8000-000000000005','b1000000-0000-4000-8000-000000000007',
            'b1000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000008',
            'b1000000-0000-4000-8000-000000000009'])
        WHEN 'organization:record_create' THEN pg_catalog.to_jsonb(ARRAY[
            'c1000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000003',
            'c1000000-0000-4000-8000-000000000005'])
        WHEN 'organization:record_update' THEN pg_catalog.to_jsonb(ARRAY[
            'c1000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000003',
            'c1000000-0000-4000-8000-000000000005'])
        WHEN 'organization:record_detail' THEN pg_catalog.to_jsonb(ARRAY[
            'c1000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000003',
            'c1000000-0000-4000-8000-000000000004','c1000000-0000-4000-8000-000000000005',
            'c1000000-0000-4000-8000-00000000000c','c1000000-0000-4000-8000-00000000000a',
            'c1000000-0000-4000-8000-00000000000b'])
        WHEN 'organization:record_list' THEN pg_catalog.to_jsonb(ARRAY[
            'c1000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000003',
            'c1000000-0000-4000-8000-000000000004','c1000000-0000-4000-8000-000000000005',
            'c1000000-0000-4000-8000-00000000000c','c1000000-0000-4000-8000-00000000000a'])
        ELSE pg_catalog.to_jsonb(ARRAY[
            'c1000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000003',
            'c1000000-0000-4000-8000-000000000004']) END;
        WITH allowed AS (
            SELECT allowed.value AS id, allowed.ordinality AS allowed_order
            FROM pg_catalog.jsonb_array_elements_text(v_allowed)
                WITH ORDINALITY AS allowed(value, ordinality)
        ), selected AS (
            SELECT field.value ->> 'id' AS id,
                   CASE WHEN p_resource_kind = 'user' AND
                       field.value ->> 'id' NOT LIKE 'a1000000-%'
                       THEN 0 ELSE 1 END AS group_order,
                   allowed.allowed_order
            FROM pg_catalog.jsonb_array_elements(v_catalog -> 'fields') AS field(value)
            LEFT JOIN allowed ON allowed.id = field.value ->> 'id'
            WHERE allowed.id IS NOT NULL
               OR p_resource_kind = 'user' AND field.value ->> 'id' NOT LIKE 'a1000000-%'
        ), ordered AS (
            SELECT id, pg_catalog.row_number() OVER (
                ORDER BY group_order, allowed_order NULLS FIRST, id
            ) - 1 AS field_order FROM selected
        )
        SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
            'field_id', id, 'interaction', 'auto', 'order', field_order,
            'translations', pg_catalog.jsonb_build_array(
                pg_catalog.jsonb_build_object('help','','label',
                    system_resource_layout_default_field_label_v1(id,'en'),'locale','en'),
                pg_catalog.jsonb_build_object('help','','label',
                    system_resource_layout_default_field_label_v1(id,'tr'),'locale','tr')
            ), 'widget', 'auto'
        ) ORDER BY field_order), '[]'::jsonb) INTO v_fields FROM ordered;
        IF pg_catalog.jsonb_array_length(v_fields) = 0 THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                MESSAGE = 'system resource curated surface has no fields';
        END IF;
        v_en := CASE v_surface WHEN 'record_create' THEN 'Create'
            WHEN 'record_update' THEN 'Update' WHEN 'record_detail' THEN 'Details'
            WHEN 'record_list' THEN 'List' ELSE 'Filters' END;
        v_tr := CASE v_surface WHEN 'record_create' THEN 'Oluştur'
            WHEN 'record_update' THEN 'Güncelle' WHEN 'record_detail' THEN 'Ayrıntılar'
            WHEN 'record_list' THEN 'Liste' ELSE 'Filtreler' END;
        v_surfaces := v_surfaces || pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object('kind',v_surface,'sections',
                pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
                    'fields',v_fields,'id','00000000-0000-4000-8000-000000000001',
                    'order',0,'translations',pg_catalog.jsonb_build_array(
                        pg_catalog.jsonb_build_object('help','','label','Fields','locale','en'),
                        pg_catalog.jsonb_build_object('help','','label','Alanlar','locale','tr')))),
                'translations',pg_catalog.jsonb_build_array(
                    pg_catalog.jsonb_build_object('help','','label',v_en,'locale','en'),
                    pg_catalog.jsonb_build_object('help','','label',v_tr,'locale','tr'))));
    END LOOP;
    RETURN system_resource_layout_canonical_json_v1(
        pg_catalog.jsonb_build_object(
            'contract','harpy/system-resource-layout/v2','surfaces',v_surfaces
        )
    );
END;
$$;


