ALTER FUNCTION __tenant_schema__.system_resource_layout_curated_definition_v2(p_resource_kind text, p_catalog_json text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_curated_predecessor_valid_v1(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_curated_predecessor_valid_v1(p_resource_kind text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_publication system_resource_layout_publications%ROWTYPE;
    v_revision system_resource_layout_revisions%ROWTYPE;
    v_definition text; v_presentation text;
BEGIN
    IF p_resource_kind NOT IN ('user','organization','role')
       OR (SELECT pg_catalog.count(*) FROM
           system_resource_layout_installation_baselines)<>1 THEN
        RETURN false;
    END IF;
    SELECT publication.* INTO v_publication
      FROM system_resource_layout_publications AS publication
     WHERE publication.resource_kind=p_resource_kind;
    IF NOT FOUND OR v_publication.generation<>2
       OR v_publication.catalog_contract<>
          'forms-presentation-field-catalog.v1'
       OR v_publication.presentation_contract<>'forms-presentation.v1'
       OR v_publication.compiler_version<>
          'system-resource-presentation-compiler.v2'
       OR v_publication.catalog_sha256 IS DISTINCT FROM pg_catalog.sha256(
          pg_catalog.convert_to(v_publication.catalog_json,'UTF8'))
       OR v_publication.presentation_sha256 IS DISTINCT FROM pg_catalog.sha256(
          pg_catalog.convert_to(v_publication.presentation_json,'UTF8'))
       OR NOT system_resource_layout_installation_catalog_valid_v2(
          p_resource_kind,v_publication.catalog_json) THEN RETURN false; END IF;
    SELECT revision.* INTO v_revision
      FROM system_resource_layout_revisions AS revision
     WHERE revision.id=v_publication.revision_id;
    IF NOT FOUND OR v_revision.resource_kind<>p_resource_kind
       OR v_revision.state<>'published' OR v_revision.row_revision<>2
       OR v_revision.definition_sha256 IS DISTINCT FROM pg_catalog.sha256(
          pg_catalog.convert_to(v_revision.definition_json,'UTF8'))
       OR v_publication.source_definition_sha256 IS DISTINCT FROM
          v_revision.definition_sha256 THEN RETURN false; END IF;
    v_definition:=system_resource_layout_curated_definition_v1(
        p_resource_kind,v_publication.catalog_json);
    IF v_revision.definition_json IS DISTINCT FROM v_definition THEN
        RETURN false;
    END IF;
    v_presentation:=system_resource_layout_compile_curated_v1(
        v_revision.id,v_revision.created_at,v_definition,
        v_publication.catalog_json);
    RETURN v_publication.presentation_json IS NOT DISTINCT FROM v_presentation;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_curated_predecessor_valid_v1(p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_curated_successor_catalog_v1(text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_curated_successor_catalog_v1(p_resource_kind text, p_catalog_json text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_catalog jsonb; v_fields jsonb;
BEGIN
    IF NOT system_resource_layout_installation_catalog_valid_v2(
        p_resource_kind,p_catalog_json) THEN
        RAISE EXCEPTION USING ERRCODE='23514',
            MESSAGE='system resource curated predecessor catalog is invalid';
    END IF;
    IF p_resource_kind <> 'organization' THEN RETURN p_catalog_json; END IF;
    v_catalog:=p_catalog_json::jsonb;
    WITH expanded AS (
        SELECT field.value FROM pg_catalog.jsonb_array_elements(
            v_catalog->'fields') AS field(value)
        UNION ALL
        SELECT pg_catalog.jsonb_build_object(
            'id','c1000000-0000-4000-8000-00000000000c',
            'mode','editable','type_id','uuid_list',
            'value_profile','uuid_list_v1')
    )
    SELECT pg_catalog.jsonb_agg(value ORDER BY value->>'id')
      INTO v_fields FROM expanded;
    v_catalog:=pg_catalog.jsonb_set(v_catalog,'{fields}',v_fields,false);
    RETURN system_resource_layout_canonical_json_v1(v_catalog);
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_curated_successor_catalog_v1(p_resource_kind text, p_catalog_json text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_default_field_label_v1(text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_default_field_label_v1(p_field_id text, p_locale text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
RETURN COALESCE(
    (SELECT CASE WHEN p_locale = 'tr' THEN label.tr ELSE label.en END
     FROM (VALUES
        ('a1000000-0000-4000-8000-000000000002','Email','E-posta'),
        ('a1000000-0000-4000-8000-000000000003','Portal identifier','Portal kimliği'),
        ('a1000000-0000-4000-8000-000000000004','Status','Durum'),
        ('a1000000-0000-4000-8000-000000000005','Identity kind','Kimlik türü'),
        ('a1000000-0000-4000-8000-000000000006','Roles','Roller'),
        ('a1000000-0000-4000-8000-000000000007','Organizations','Organizasyonlar'),
        ('a1000000-0000-4000-8000-00000000000a','Created at','Oluşturulma zamanı'),
        ('a1000000-0000-4000-8000-00000000000b','Updated at','Güncellenme zamanı'),
        ('b1000000-0000-4000-8000-000000000002','Scope','Kapsam'),
        ('b1000000-0000-4000-8000-000000000004','Organization','Organizasyon'),
        ('b1000000-0000-4000-8000-000000000005','Name','Ad'),
        ('b1000000-0000-4000-8000-000000000006','Description','Açıklama'),
        ('b1000000-0000-4000-8000-000000000007','Status','Durum'),
        ('b1000000-0000-4000-8000-000000000008','Protected','Korumalı'),
        ('b1000000-0000-4000-8000-000000000009','Default role','Varsayılan rol'),
        ('b1000000-0000-4000-8000-00000000000d','Created at','Oluşturulma zamanı'),
        ('b1000000-0000-4000-8000-00000000000e','Updated at','Güncellenme zamanı'),
        ('c1000000-0000-4000-8000-000000000002','Name','Ad'),
        ('c1000000-0000-4000-8000-000000000003','Slug','Kısa ad'),
        ('c1000000-0000-4000-8000-000000000004','Status','Durum'),
        ('c1000000-0000-4000-8000-000000000005','Parent organization','Üst organizasyon'),
        ('c1000000-0000-4000-8000-00000000000a','Created at','Oluşturulma zamanı'),
        ('c1000000-0000-4000-8000-00000000000b','Updated at','Güncellenme zamanı'),
        ('c1000000-0000-4000-8000-00000000000c','Owners','Sahipler')
     ) AS label(id,en,tr) WHERE label.id = p_field_id),
    CASE WHEN p_locale = 'tr' THEN 'Görünen ad' ELSE 'Display name' END
);
END;
$$;


