CREATE FUNCTION __tenant_schema__.system_resource_layout_definition_supported_v2(p_definition text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    RETURN system_resource_layout_definition_valid_v1(p_definition)
