ALTER FUNCTION __tenant_schema__.system_resource_layout_definition_supported_v2(p_definition text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_definition_valid_v1(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_definition_valid_v1(p_definition text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    v_document jsonb;
BEGIN
    BEGIN
        v_document := p_definition::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RETURN false;
    END;
    IF pg_catalog.jsonb_typeof(v_document) IS DISTINCT FROM 'object'
       OR (SELECT pg_catalog.count(*) FROM
           pg_catalog.jsonb_object_keys(v_document)) <> 2
       OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_object_keys(v_document) AS root(key)
           WHERE root.key NOT IN ('contract', 'sections')
       )
       OR v_document ->> 'contract' IS DISTINCT FROM
          'harpy/system-resource-layout/v1'
       OR pg_catalog.jsonb_typeof(v_document -> 'sections') <> 'array'
       OR pg_catalog.jsonb_array_length(v_document -> 'sections') > 64 THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_document -> 'sections')
            AS section(value)
        WHERE pg_catalog.jsonb_typeof(section.value) <> 'object'
           OR (SELECT pg_catalog.count(*) FROM
               pg_catalog.jsonb_object_keys(section.value)) <> 4
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(section.value) AS present(key)
                WHERE present.key NOT IN ('fields', 'id', 'order', 'translations')
           )
           OR pg_catalog.jsonb_typeof(section.value -> 'id') <> 'string'
           OR section.value ->> 'id' !~
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR section.value ->> 'id' =
              '00000000-0000-0000-0000-000000000000'
           OR pg_catalog.jsonb_typeof(section.value -> 'order') <> 'number'
           OR section.value ->> 'order' !~ '^(0|[1-9][0-9]{0,8})$'
           OR pg_catalog.jsonb_typeof(section.value -> 'fields') <> 'array'
           OR pg_catalog.jsonb_typeof(section.value -> 'translations') <> 'array'
           OR pg_catalog.jsonb_array_length(section.value -> 'translations') > 32
    ) THEN
        RETURN false;
    END IF;
    IF (SELECT pg_catalog.count(*)
        FROM pg_catalog.jsonb_array_elements(v_document -> 'sections') AS section
        CROSS JOIN pg_catalog.jsonb_array_elements(
            section.value -> 'fields'
        )) > 512 OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_document -> 'sections')
            AS section(value)
        CROSS JOIN pg_catalog.jsonb_array_elements(
            section.value -> 'fields'
        ) AS field(value)
        WHERE pg_catalog.jsonb_typeof(field.value) <> 'object'
           OR (SELECT pg_catalog.count(*) FROM
               pg_catalog.jsonb_object_keys(field.value)) <> 4
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(field.value) AS present(key)
                WHERE present.key NOT IN (
                    'field_id', 'order', 'translations', 'widget'
                )
           )
           OR pg_catalog.jsonb_typeof(field.value -> 'field_id') <> 'string'
           OR field.value ->> 'field_id' !~
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR field.value ->> 'field_id' =
              '00000000-0000-0000-0000-000000000000'
           OR pg_catalog.jsonb_typeof(field.value -> 'order') <> 'number'
           OR field.value ->> 'order' !~ '^(0|[1-9][0-9]{0,8})$'
           OR pg_catalog.jsonb_typeof(field.value -> 'widget') <> 'string'
           OR field.value ->> 'widget' NOT IN (
                'auto', 'text', 'textarea', 'number', 'toggle',
                'select', 'date', 'datetime', 'json'
           )
           OR pg_catalog.jsonb_typeof(field.value -> 'translations') <> 'array'
           OR pg_catalog.jsonb_array_length(field.value -> 'translations') > 32
    ) THEN
        RETURN false;
    END IF;
    IF EXISTS (
        WITH translations AS (
            SELECT translation.value
            FROM pg_catalog.jsonb_array_elements(v_document -> 'sections')
                AS section(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(
                section.value -> 'translations'
            ) AS translation(value)
            UNION ALL
            SELECT translation.value
            FROM pg_catalog.jsonb_array_elements(v_document -> 'sections')
                AS section(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(
                section.value -> 'fields'
            ) AS field(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(
                field.value -> 'translations'
            ) AS translation(value)
        )
        SELECT 1 FROM translations
        WHERE pg_catalog.jsonb_typeof(value) <> 'object'
           OR (SELECT pg_catalog.count(*) FROM
               pg_catalog.jsonb_object_keys(value)) <> 3
           OR EXISTS (
                SELECT 1 FROM pg_catalog.jsonb_object_keys(value) AS present(key)
                WHERE present.key NOT IN ('help', 'label', 'locale')
           )
           OR pg_catalog.jsonb_typeof(value -> 'help') <> 'string'
           OR pg_catalog.jsonb_typeof(value -> 'label') <> 'string'
           OR pg_catalog.jsonb_typeof(value -> 'locale') <> 'string'
           OR value ->> 'locale' !~
              '^[a-z]{2,3}(-[A-Z][a-z]{3})?(-([A-Z]{2}|[0-9]{3}))?$'
           OR pg_catalog.char_length(value ->> 'label') NOT BETWEEN 1 AND 200
           OR pg_catalog.char_length(value ->> 'help') > 1000
           OR value ->> 'label' ~ '[[:cntrl:]]'
           OR value ->> 'help' ~ '[[:cntrl:]]'
    ) THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT section.value ->> 'id'
        FROM pg_catalog.jsonb_array_elements(v_document -> 'sections') AS section
        GROUP BY section.value ->> 'id' HAVING pg_catalog.count(*) > 1
    ) OR EXISTS (
        SELECT section.value ->> 'order'
        FROM pg_catalog.jsonb_array_elements(v_document -> 'sections') AS section
        GROUP BY section.value ->> 'order' HAVING pg_catalog.count(*) > 1
    ) OR EXISTS (
        SELECT field.value ->> 'field_id'
        FROM pg_catalog.jsonb_array_elements(v_document -> 'sections') AS section
        CROSS JOIN pg_catalog.jsonb_array_elements(
            section.value -> 'fields'
        ) AS field
        GROUP BY field.value ->> 'field_id' HAVING pg_catalog.count(*) > 1
    ) OR EXISTS (
        SELECT section.value ->> 'id', field.value ->> 'order'
        FROM pg_catalog.jsonb_array_elements(v_document -> 'sections') AS section
        CROSS JOIN pg_catalog.jsonb_array_elements(
            section.value -> 'fields'
        ) AS field
        GROUP BY section.value ->> 'id', field.value ->> 'order'
        HAVING pg_catalog.count(*) > 1
    ) THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_definition_valid_v1(p_definition text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_definition_valid_v2(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_definition_valid_v2(p_definition text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    BEGIN
        v_document := p_definition::jsonb;
        IF pg_catalog.jsonb_typeof(v_document) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.count(*)
               FROM pg_catalog.jsonb_object_keys(v_document)) <> 2
           OR EXISTS (
                SELECT 1 FROM pg_catalog.jsonb_object_keys(v_document) AS present(key)
                WHERE present.key NOT IN ('contract', 'surfaces')
           )
           OR v_document ->> 'contract' IS DISTINCT FROM
              'harpy/system-resource-layout/v2'
           OR pg_catalog.jsonb_typeof(v_document -> 'surfaces') IS DISTINCT FROM 'array'
        THEN
            RETURN false;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RETURN false;
    END;
    IF pg_catalog.jsonb_array_length(v_document -> 'surfaces') NOT BETWEEN 5 AND 6
    THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_document -> 'surfaces')
            WITH ORDINALITY AS surface(value, position)
        WHERE pg_catalog.jsonb_typeof(surface.value) IS DISTINCT FROM 'object'
    ) THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_document -> 'surfaces')
            WITH ORDINALITY AS surface(value, position)
        WHERE (SELECT pg_catalog.count(*)
               FROM pg_catalog.jsonb_object_keys(surface.value)) <> 3
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(surface.value) AS present(key)
                WHERE present.key NOT IN ('kind', 'sections', 'translations')
           )
           OR pg_catalog.jsonb_typeof(surface.value -> 'kind') IS DISTINCT FROM 'string'
           OR surface.value ->> 'kind' IS DISTINCT FROM CASE surface.position
                WHEN 1 THEN 'record_create'
                WHEN 2 THEN 'record_update'
                WHEN 3 THEN 'record_detail'
                WHEN 4 THEN 'record_list'
                WHEN 5 THEN 'record_filter'
                WHEN 6 THEN 'print'
                ELSE ''
              END
           OR pg_catalog.jsonb_typeof(surface.value -> 'sections') IS DISTINCT FROM 'array'
           OR pg_catalog.jsonb_typeof(surface.value -> 'translations') IS DISTINCT FROM 'array'
    ) THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_document -> 'surfaces') AS surface(value)
        WHERE NOT system_resource_layout_translations_valid_v2(
                surface.value -> 'translations'
              )
           OR NOT system_resource_layout_sections_valid_v2(
                surface.value -> 'sections'
              )
    ) THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_definition_valid_v2(p_definition text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_delete_v1(name, uuid, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_delete_v1(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_state text;
    v_row_revision bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_expected_row_revision < 1 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_delete_contract_guard',
            MESSAGE = 'system resource layout delete contract is invalid';
    END IF;
    SELECT revision.state, revision.row_revision
    INTO v_state, v_row_revision
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    IF v_state IS DISTINCT FROM 'draft'
       OR v_row_revision IS DISTINCT FROM p_expected_row_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource layout revision conflicts';
    END IF;
    DELETE FROM system_resource_layout_revisions
    WHERE id = p_revision_id;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_delete_v1(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_deterministic_uuid_v7_v1(text, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_deterministic_uuid_v7_v1(p_seed text, p_path text, p_occurred_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_milliseconds bigint;
    v_digest bytea;
    v_value bytea;
    v_hex text;
BEGIN
    IF p_seed IS NULL OR p_seed = '' OR p_path IS NULL OR p_path = ''
       OR p_occurred_at IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'system resource layout deterministic identity is invalid';
    END IF;
    v_milliseconds := pg_catalog.floor(
        pg_catalog.date_part('epoch', p_occurred_at) * 1000
    )::bigint;
    IF v_milliseconds < 0 OR v_milliseconds >= 281474976710656 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'system resource layout deterministic time is invalid';
    END IF;
    v_digest := pg_catalog.sha256(
        pg_catalog.convert_to(p_seed, 'UTF8') ||
        pg_catalog.decode('00', 'hex') ||
        pg_catalog.convert_to(p_path, 'UTF8')
    );
    v_value := substring(
        pg_catalog.int8send(v_milliseconds) FROM 3 FOR 6
    ) || substring(v_digest FROM 1 FOR 10);
    v_value := pg_catalog.set_byte(
        v_value, 6, (pg_catalog.get_byte(v_value, 6) & 15) | 112
    );
    v_value := pg_catalog.set_byte(
        v_value, 8, (pg_catalog.get_byte(v_value, 8) & 63) | 128
    );
    v_hex := pg_catalog.encode(v_value, 'hex');
    RETURN (
        substring(v_hex FROM 1 FOR 8) || '-' ||
        substring(v_hex FROM 9 FOR 4) || '-' ||
        substring(v_hex FROM 13 FOR 4) || '-' ||
        substring(v_hex FROM 17 FOR 4) || '-' ||
        substring(v_hex FROM 21 FOR 12)
    )::uuid;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_deterministic_uuid_v7_v1(p_seed text, p_path text, p_occurred_at timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_field_ids_v2(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_field_ids_v2(p_definition text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
    v_result jsonb;
BEGIN
    IF NOT system_resource_layout_definition_supported_v2(p_definition) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_field_ids_v2_contract_guard',
            MESSAGE = 'system resource layout definition is invalid';
    END IF;
    v_document := p_definition::jsonb;
    IF v_document ->> 'contract' = 'harpy/system-resource-layout/v1' THEN
        SELECT COALESCE(
            pg_catalog.jsonb_agg(pg_catalog.to_jsonb(source.field_id)
                ORDER BY source.field_id),
            '[]'::jsonb
        ) INTO v_result
        FROM (
            SELECT DISTINCT field.value ->> 'field_id' AS field_id
            FROM pg_catalog.jsonb_array_elements(v_document -> 'sections')
                AS section(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields')
                AS field(value)
        ) AS source;
    ELSE
        SELECT COALESCE(
            pg_catalog.jsonb_agg(pg_catalog.to_jsonb(source.field_id)
                ORDER BY source.field_id),
            '[]'::jsonb
        ) INTO v_result
        FROM (
            SELECT DISTINCT field.value ->> 'field_id' AS field_id
            FROM pg_catalog.jsonb_array_elements(v_document -> 'surfaces')
                AS surface(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(surface.value -> 'sections')
                AS section(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields')
                AS field(value)
        ) AS source;
    END IF;
    RETURN v_result;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_field_ids_v2(p_definition text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_field_reference_evidence_v1(name, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_field_reference_evidence_v1(p_scope_schema name, p_resource_kind text, p_field_id uuid) RETURNS TABLE(live_reference_count bigint, manifest_sha256 bytea, checked_owner_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count bigint;
    v_manifest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() OR
       p_resource_kind NOT IN ('user', 'organization', 'role') OR
       p_field_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource layout reference scope is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_field_id::text, 8501)
    );
    SELECT pg_catalog.count(*)
    INTO v_count
    FROM system_resource_layout_publications AS publication
    JOIN system_resource_layout_revisions AS revision
      ON revision.id = publication.revision_id
    CROSS JOIN pg_catalog.jsonb_array_elements(
        revision.definition_json::jsonb -> 'sections'
    ) AS section(value)
    CROSS JOIN pg_catalog.jsonb_array_elements(
        section.value -> 'fields'
    ) AS field(value)
    WHERE publication.resource_kind = p_resource_kind
      AND revision.state = 'published'
      AND field.value ->> 'field_id' = p_field_id::text;
    v_manifest := '{"checked_owner_count":1' ||
        ',"contract":"harpy/system-resource-layout-reference/v1"' ||
        ',"field_id":' || pg_catalog.to_jsonb(p_field_id::text)::text ||
        ',"live_reference_count":' || v_count::text ||
        ',"resource_kind":' || pg_catalog.to_jsonb(p_resource_kind)::text || '}';
    RETURN QUERY SELECT v_count,
        pg_catalog.sha256(pg_catalog.convert_to(v_manifest, 'UTF8')), 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_field_reference_evidence_v1(p_scope_schema name, p_resource_kind text, p_field_id uuid) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_field_reference_evidence_v2(name, text, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_field_reference_evidence_v2(p_scope_schema name, p_resource_kind text, p_field_id uuid) RETURNS TABLE(live_reference_count bigint, manifest_sha256 bytea, checked_owner_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count bigint;
    v_manifest text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_resource_kind NOT IN ('user', 'organization', 'role')
       OR p_field_id IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource layout reference scope is invalid';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(p_field_id::text, 8501)
    );
    SELECT pg_catalog.count(*)
    INTO v_count
    FROM system_resource_layout_publications AS publication
    JOIN system_resource_layout_revisions AS revision
      ON revision.id = publication.revision_id
    WHERE publication.resource_kind = p_resource_kind
      AND revision.state = 'published'
      AND system_resource_layout_field_ids_v2(revision.definition_json)
          ? p_field_id::text;
    v_manifest := '{"checked_owner_count":1' ||
        ',"contract":"harpy/system-resource-layout-reference/v1"' ||
        ',"field_id":' || pg_catalog.to_jsonb(p_field_id::text)::text ||
        ',"live_reference_count":' || v_count::text ||
        ',"resource_kind":' || pg_catalog.to_jsonb(p_resource_kind)::text || '}';
    RETURN QUERY SELECT v_count,
        pg_catalog.sha256(pg_catalog.convert_to(v_manifest, 'UTF8')), 1;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_field_reference_evidence_v2(p_scope_schema name, p_resource_kind text, p_field_id uuid) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_get_v1(name, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_get_v1(p_scope_schema name, p_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema() THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource layout get scope is invalid';
    END IF;
    v_document := system_resource_layout_revision_json_v1(p_revision_id);
    IF v_document IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    RETURN v_document;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_get_v1(p_scope_schema name, p_revision_id uuid) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_guard_publication_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_guard_publication_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_state text;
    v_resource text;
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'DELETE'
       OR TG_OP IS NOT DISTINCT FROM 'TRUNCATE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            CONSTRAINT = 'system_resource_layout_publications_lifecycle_guard',
            MESSAGE = 'system resource layout publication cannot be removed';
    END IF;
    SELECT revision.state, revision.resource_kind
    INTO v_state, v_resource
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = NEW.revision_id
    FOR KEY SHARE;
    IF NOT FOUND OR v_state IS DISTINCT FROM 'published'
       OR v_resource IS DISTINCT FROM NEW.resource_kind THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publications_target_guard',
            MESSAGE = 'system resource layout publication target is invalid';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.generation IS DISTINCT FROM 1
           OR NEW.updated_at IS DISTINCT FROM NEW.created_at THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                CONSTRAINT = 'system_resource_layout_publications_lifecycle_guard',
                MESSAGE = 'system resource layout publication must begin at one';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP IS DISTINCT FROM 'UPDATE'
       OR NEW.resource_kind IS DISTINCT FROM OLD.resource_kind
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.generation IS DISTINCT FROM OLD.generation + 1
       OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publications_lifecycle_guard',
            MESSAGE = 'system resource layout publication update is invalid';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_guard_publication_v1() OWNER TO harpy_owner;

--
-- Name: system_resource_layout_guard_revision_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_guard_revision_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP IS NOT DISTINCT FROM 'TRUNCATE' THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'system resource layout revisions cannot be truncated';
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'INSERT' THEN
        IF NEW.state IS DISTINCT FROM 'draft'
           OR NEW.published_at IS NOT NULL
           OR NEW.row_revision IS DISTINCT FROM 1
           OR NEW.updated_at IS DISTINCT FROM NEW.created_at THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                CONSTRAINT = 'system_resource_layout_revisions_lifecycle_guard',
                MESSAGE = 'system resource layout revision must begin as draft';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP IS NOT DISTINCT FROM 'DELETE' THEN
        IF OLD.state IS DISTINCT FROM 'draft' THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                CONSTRAINT = 'system_resource_layout_revisions_lifecycle_guard',
                MESSAGE = 'published system resource layout is immutable';
        END IF;
        RETURN OLD;
    END IF;
    IF TG_OP IS DISTINCT FROM 'UPDATE'
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.resource_kind IS DISTINCT FROM OLD.resource_kind
       OR NEW.version IS DISTINCT FROM OLD.version
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.row_revision IS DISTINCT FROM OLD.row_revision + 1
       OR NEW.updated_at < OLD.updated_at
       OR OLD.state IS DISTINCT FROM 'draft' THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_revisions_lifecycle_guard',
            MESSAGE = 'system resource layout revision transition is forbidden';
    END IF;
    IF NEW.state IS NOT DISTINCT FROM 'draft'
       AND NEW.published_at IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW.state IS NOT DISTINCT FROM 'published'
       AND NEW.published_at IS NOT NULL
       AND NEW.definition_json IS NOT DISTINCT FROM OLD.definition_json
       AND NEW.definition_sha256 IS NOT DISTINCT FROM OLD.definition_sha256 THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE = '23514',
        CONSTRAINT = 'system_resource_layout_revisions_lifecycle_guard',
        MESSAGE = 'system resource layout publish transition is invalid';
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_guard_revision_v1() OWNER TO harpy_owner;

--
-- Name: system_resource_layout_installation_assert_v2(uuid, uuid, name); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_installation_assert_v2(p_operation_id uuid, p_tenant_id uuid, p_schema_name name) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_environment_id uuid;
    v_operation_kind text;
BEGIN
    SELECT operation.environment_id, operation.operation_kind
    INTO v_environment_id, v_operation_kind
    FROM platform.tenancy_onboarding_operations AS operation
    WHERE operation.operation_id = p_operation_id;
    IF NOT FOUND OR NOT platform.tenancy_activation_step_context_assert_v1(
        p_operation_id, 'systemresources.initialize_tenant_baseline',
        v_environment_id, p_tenant_id, p_schema_name, v_operation_kind
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource installation capability required';
    END IF;
    PERFORM 1
    FROM platform.tenancy_activation_facts AS fact
    JOIN platform.tenants AS tenant ON tenant.id = fact.tenant_id
    WHERE fact.operation_id = p_operation_id
      AND fact.tenant_id = p_tenant_id
      AND tenant.schema_name = p_schema_name
      AND tenant.status = 'ACTIVE'
      AND tenant.deleted_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource installation target conflicts';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_installation_assert_v2(p_operation_id uuid, p_tenant_id uuid, p_schema_name name) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_installation_baseline_evidence_valid_v1(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_installation_baseline_evidence_valid_v1(p_contract text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
RETURN p_contract IS NOT DISTINCT FROM
    'installation-baseline-evidence.v1'
AND NOT EXISTS (
    SELECT 1
    FROM system_resource_layout_installation_baselines AS baseline
    CROSS JOIN (VALUES ('user'),('organization'),('role')) AS expected(kind)
    LEFT JOIN system_resource_layout_publications AS publication
      ON publication.resource_kind = expected.kind
    LEFT JOIN system_resource_layout_revisions AS revision
      ON revision.id = CASE expected.kind
         WHEN 'user' THEN baseline.user_revision_id
         WHEN 'organization' THEN baseline.organization_revision_id
         ELSE baseline.role_revision_id END
    WHERE publication.resource_kind IS NULL
       OR publication.generation = 1 AND (
          publication.revision_id IS DISTINCT FROM revision.id
       OR revision.resource_kind IS DISTINCT FROM expected.kind
       OR revision.state IS DISTINCT FROM 'published'
       OR publication.catalog_contract IS DISTINCT FROM
          'forms-presentation-field-catalog.v1'
       OR publication.presentation_contract IS DISTINCT FROM
          'forms-presentation.v1'
       OR publication.compiler_version IS DISTINCT FROM
          'system-resource-presentation-compiler.v2'
       OR revision.definition_json::jsonb ->> 'contract' IS DISTINCT FROM
          'harpy/system-resource-layout/v2'
       OR publication.catalog_sha256 IS DISTINCT FROM pg_catalog.sha256(
          pg_catalog.convert_to(publication.catalog_json, 'UTF8'))
       OR publication.presentation_sha256 IS DISTINCT FROM pg_catalog.sha256(
          pg_catalog.convert_to(publication.presentation_json, 'UTF8'))
       OR revision.definition_sha256 IS DISTINCT FROM pg_catalog.sha256(
          pg_catalog.convert_to(revision.definition_json, 'UTF8'))
       OR publication.source_definition_sha256 IS DISTINCT FROM
          revision.definition_sha256
       OR NOT system_resource_layout_installation_catalog_valid_v1(
          expected.kind, publication.catalog_json))
) AND NOT EXISTS (
    SELECT 1
    FROM system_resource_layout_installation_baselines AS baseline
    JOIN system_resource_layout_publications AS users
      ON users.resource_kind = 'user'
    JOIN system_resource_layout_publications AS organizations
      ON organizations.resource_kind = 'organization'
    JOIN system_resource_layout_publications AS roles
      ON roles.resource_kind = 'role'
    WHERE users.generation = 1
      AND organizations.generation = 1
      AND roles.generation = 1
      AND baseline.baseline_sha256 IS DISTINCT FROM pg_catalog.sha256(
          pg_catalog.uuid_send(baseline.operation_id) ||
          pg_catalog.uuid_send(baseline.tenant_id) ||
          pg_catalog.uuid_send(baseline.user_revision_id) ||
          users.catalog_sha256 || users.presentation_sha256 ||
          pg_catalog.uuid_send(baseline.organization_revision_id) ||
          organizations.catalog_sha256 || organizations.presentation_sha256 ||
          pg_catalog.uuid_send(baseline.role_revision_id) ||
          roles.catalog_sha256 || roles.presentation_sha256)
);
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_installation_baseline_evidence_valid_v1(p_contract text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_installation_baseline_evidence_valid_v2(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_installation_baseline_evidence_valid_v2(p_contract text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
SELECT p_contract IS NOT DISTINCT FROM 'installation-baseline-evidence.v1'
AND (SELECT pg_catalog.count(*) FROM system_resource_layout_installation_baselines)=1 AND (SELECT pg_catalog.count(*) FROM system_resource_layout_publications)=3
AND NOT EXISTS (
 SELECT 1 FROM system_resource_layout_installation_baselines baseline
 CROSS JOIN (VALUES('user'),('organization'),('role')) expected(kind)
 LEFT JOIN system_resource_layout_publications publication
   ON publication.resource_kind=expected.kind
 LEFT JOIN system_resource_layout_revisions revision
   ON revision.id=CASE expected.kind WHEN 'user' THEN baseline.user_revision_id
      WHEN 'organization' THEN baseline.organization_revision_id
      ELSE baseline.role_revision_id END
 WHERE publication.resource_kind IS NULL OR publication.generation=1 AND (
       publication.revision_id IS DISTINCT FROM revision.id
    OR revision.resource_kind IS DISTINCT FROM expected.kind
    OR revision.state IS DISTINCT FROM 'published'
    OR publication.catalog_contract IS DISTINCT FROM 'forms-presentation-field-catalog.v1'
    OR publication.presentation_contract IS DISTINCT FROM 'forms-presentation.v1'
    OR publication.compiler_version IS DISTINCT FROM 'system-resource-presentation-compiler.v2'
    OR revision.definition_json::jsonb->>'contract' IS DISTINCT FROM
       'harpy/system-resource-layout/v2'
    OR publication.catalog_sha256 IS DISTINCT FROM pg_catalog.sha256(
       pg_catalog.convert_to(publication.catalog_json,'UTF8'))
    OR publication.presentation_sha256 IS DISTINCT FROM pg_catalog.sha256(
       pg_catalog.convert_to(publication.presentation_json,'UTF8'))
    OR revision.definition_sha256 IS DISTINCT FROM pg_catalog.sha256(
       pg_catalog.convert_to(revision.definition_json,'UTF8'))
    OR publication.source_definition_sha256 IS DISTINCT FROM revision.definition_sha256
    OR NOT system_resource_layout_installation_catalog_valid_v2(
       expected.kind,publication.catalog_json))
) AND NOT EXISTS (
 SELECT 1 FROM system_resource_layout_installation_baselines baseline
 JOIN system_resource_layout_publications users ON users.resource_kind='user'
 JOIN system_resource_layout_publications organizations ON organizations.resource_kind='organization'
 JOIN system_resource_layout_publications roles ON roles.resource_kind='role'
 WHERE users.generation=1 AND organizations.generation=1 AND roles.generation=1
 AND baseline.baseline_sha256 IS DISTINCT FROM pg_catalog.sha256(
   pg_catalog.uuid_send(baseline.operation_id)||pg_catalog.uuid_send(baseline.tenant_id)||
   pg_catalog.uuid_send(baseline.user_revision_id)||
   users.catalog_sha256||users.presentation_sha256||
   pg_catalog.uuid_send(baseline.organization_revision_id)||
   organizations.catalog_sha256||organizations.presentation_sha256||
   pg_catalog.uuid_send(baseline.role_revision_id)||
   roles.catalog_sha256||roles.presentation_sha256)
);
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_installation_baseline_evidence_valid_v2(p_contract text) OWNER TO harpy_owner;

