ALTER FUNCTION __tenant_schema__.system_resource_layout_installation_baseline_guard_v1() OWNER TO harpy_owner;

--
-- Name: system_resource_layout_installation_catalog_valid_v1(text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_installation_catalog_valid_v1(p_resource_kind text, p_catalog_json text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_catalog jsonb;
    v_prefix text;
    v_static_count integer;
    v_ids jsonb;
    v_types jsonb;
    v_editable jsonb;
    v_unique bigint;
    v_invalid bigint;
BEGIN
    IF p_resource_kind NOT IN ('user','organization','role') THEN
        RETURN false;
    END IF;
    v_catalog := p_catalog_json::jsonb;
    v_prefix := CASE p_resource_kind WHEN 'user' THEN 'a1000000-'
        WHEN 'role' THEN 'b1000000-' ELSE 'c1000000-' END;
    v_static_count := CASE p_resource_kind
        WHEN 'user' THEN 11 WHEN 'role' THEN 14 ELSE 11 END;
    SELECT pg_catalog.jsonb_agg(
        v_prefix || '0000-4000-8000-' ||
        pg_catalog.lpad(pg_catalog.to_hex(series.number), 12, '0')
        ORDER BY series.number
    ) INTO v_ids
    FROM pg_catalog.generate_series(1, v_static_count) AS series(number);
    v_types := CASE p_resource_kind
        WHEN 'user' THEN
            '["uuid","text","text","enum","enum","uuid_list","uuid_list","uuid","integer","timestamp","timestamp"]'::jsonb
        WHEN 'role' THEN
            '["uuid","enum","uuid","relation","text","text","enum","boolean","boolean","uuid_list","uuid","integer","timestamp","timestamp"]'::jsonb
        ELSE
            '["uuid","text","text","enum","relation","uuid_list","uuid_list","uuid","integer","timestamp","timestamp"]'::jsonb
        END;
    v_editable := '["user:002","user:006","user:007","role:002","role:003","role:004","role:005","role:006","role:009","organization:002","organization:003","organization:005"]'::jsonb;
    IF v_catalog IS NULL
       OR v_catalog ->> 'contract' IS DISTINCT FROM
          'forms-presentation-field-catalog.v1'
       OR pg_catalog.jsonb_typeof(v_catalog -> 'fields') <> 'array'
       OR (SELECT pg_catalog.count(*)
           FROM pg_catalog.jsonb_object_keys(v_catalog)) <> 2
       OR pg_catalog.jsonb_array_length(v_catalog -> 'fields') <>
          v_static_count + 1 THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.count(DISTINCT item.id),
           pg_catalog.count(*) FILTER (WHERE
               (SELECT pg_catalog.count(*)
                FROM pg_catalog.jsonb_object_keys(item.value)) <> 4
            OR (item.ordinality <= v_static_count
                AND item.id IS DISTINCT FROM
                    v_ids ->> (item.ordinality::integer - 1))
            OR (item.ordinality = v_static_count + 1
                AND (item.id LIKE v_prefix || '%'
                     OR item.id !~
                       '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'))
            OR item.value ->> 'type_id' IS DISTINCT FROM
                CASE WHEN item.ordinality = v_static_count + 1 THEN 'text'
                ELSE v_types ->> (item.ordinality::integer - 1) END
            OR item.value ->> 'value_profile' IS DISTINCT FROM
                CASE item.value ->> 'type_id'
                WHEN 'text' THEN 'text_nfc_v1'
                WHEN 'uuid' THEN 'uuid_rfc4122_lower_v1'
                WHEN 'enum' THEN 'enum_code_v1'
                WHEN 'uuid_list' THEN 'uuid_list_v1'
                WHEN 'integer' THEN 'integer_base10_v1'
                WHEN 'timestamp' THEN 'timestamp_utc_microsecond_v1'
                WHEN 'relation' THEN 'relation_uuid_v1'
                WHEN 'boolean' THEN 'boolean_v1' END
            OR item.value ->> 'mode' IS DISTINCT FROM
                CASE WHEN item.ordinality = v_static_count + 1
                       OR v_editable ? (
                           p_resource_kind || ':' ||
                           pg_catalog.right(item.id, 3)
                       )
                THEN 'editable' ELSE 'read_only' END)
    INTO v_unique, v_invalid
    FROM (
        SELECT field.value, field.value ->> 'id' AS id, field.ordinality
        FROM pg_catalog.jsonb_array_elements(v_catalog -> 'fields')
            WITH ORDINALITY AS field(value, ordinality)
    ) AS item;
    RETURN v_unique = v_static_count + 1 AND v_invalid = 0;
END;
$_$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_installation_catalog_valid_v1(p_resource_kind text, p_catalog_json text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_installation_catalog_valid_v2(text, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_installation_catalog_valid_v2(p_resource_kind text, p_catalog_json text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_catalog jsonb; v_prefix text; v_static_count integer; v_types jsonb;
    v_editable jsonb := '["user:002","user:006","user:007","role:002","role:003","role:004","role:005","role:006","role:009","organization:002","organization:003","organization:005"]';
    v_unique bigint; v_invalid bigint; v_static bigint; v_custom bigint;
BEGIN
    IF p_resource_kind NOT IN ('user','organization','role') THEN RETURN false; END IF;
    BEGIN
        v_catalog := p_catalog_json::jsonb;
    EXCEPTION WHEN OTHERS THEN RETURN false;
    END;
    v_prefix := CASE p_resource_kind WHEN 'user' THEN 'a1000000-' WHEN 'role' THEN 'b1000000-' ELSE 'c1000000-' END;
    v_static_count := CASE p_resource_kind WHEN 'role' THEN 14 ELSE 11 END;
    v_types := CASE p_resource_kind
        WHEN 'user' THEN '["uuid","text","text","enum","enum","uuid_list","uuid_list","uuid","integer","timestamp","timestamp"]'
        WHEN 'role' THEN '["uuid","enum","uuid","relation","text","text","enum","boolean","boolean","uuid_list","uuid","integer","timestamp","timestamp"]'
        ELSE '["uuid","text","text","enum","relation","uuid_list","uuid_list","uuid","integer","timestamp","timestamp"]'
        END;
    IF v_catalog IS NULL OR v_catalog->>'contract' IS DISTINCT FROM
       'forms-presentation-field-catalog.v1'
       OR pg_catalog.jsonb_typeof(v_catalog->'fields') IS DISTINCT FROM 'array'
       OR (SELECT pg_catalog.count(*) FROM
           pg_catalog.jsonb_object_keys(v_catalog)) <> 2
       OR pg_catalog.jsonb_array_length(v_catalog->'fields') <>
          v_static_count + 1 THEN RETURN false; END IF;
    WITH expected AS (
        SELECT v_prefix || '0000-4000-8000-' ||
               pg_catalog.lpad(pg_catalog.to_hex(number),12,'0') AS id,
               v_types->>(number-1) AS type_id
        FROM pg_catalog.generate_series(1,v_static_count) AS series(number)
    ), actual AS (
        SELECT field.value, field.value->>'id' AS id, expected.type_id
        FROM pg_catalog.jsonb_array_elements(v_catalog->'fields') AS field(value)
        LEFT JOIN expected ON expected.id = field.value->>'id'
    )
    SELECT pg_catalog.count(DISTINCT id),
           pg_catalog.count(*) FILTER (WHERE id IS NULL
             OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(value))<>4
             OR type_id IS NULL AND (
                id LIKE v_prefix||'%'
                OR id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                OR value->>'type_id' IS DISTINCT FROM 'text'
                OR value->>'value_profile' IS DISTINCT FROM 'text_nfc_v1'
                OR value->>'mode' IS DISTINCT FROM 'editable')
             OR type_id IS NOT NULL AND (
                value->>'type_id' IS DISTINCT FROM type_id
                OR value->>'value_profile' IS DISTINCT FROM CASE type_id
                   WHEN 'text' THEN 'text_nfc_v1'
                   WHEN 'uuid' THEN 'uuid_rfc4122_lower_v1'
                   WHEN 'enum' THEN 'enum_code_v1'
                   WHEN 'uuid_list' THEN 'uuid_list_v1'
                   WHEN 'integer' THEN 'integer_base10_v1'
                   WHEN 'timestamp' THEN 'timestamp_utc_microsecond_v1'
                   WHEN 'relation' THEN 'relation_uuid_v1'
                   WHEN 'boolean' THEN 'boolean_v1' END
                OR value->>'mode' IS DISTINCT FROM CASE
                   WHEN v_editable ? (p_resource_kind||':'||
                     pg_catalog.right(id,3)) THEN 'editable'
                   ELSE 'read_only' END)),
           pg_catalog.count(*) FILTER (WHERE type_id IS NOT NULL),
           pg_catalog.count(*) FILTER (WHERE type_id IS NULL)
    INTO v_unique,v_invalid,v_static,v_custom FROM actual;
    RETURN v_unique = v_static_count + 1 AND v_invalid = 0
       AND v_static = v_static_count AND v_custom = 1;
END;
$_$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_installation_catalog_valid_v2(p_resource_kind text, p_catalog_json text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_installation_record_v1(uuid, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_installation_record_v1(p_operation_id uuid, p_tenant_id uuid, p_user_revision_id uuid, p_organization_revision_id uuid, p_role_revision_id uuid, p_now timestamp with time zone) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_existing system_resource_layout_installation_baselines%ROWTYPE;
    v_user_catalog bytea;
    v_user_presentation bytea;
    v_organization_catalog bytea;
    v_organization_presentation bytea;
    v_role_catalog bytea;
    v_role_presentation bytea;
    v_digest bytea;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource installation baseline denied';
    END IF;
    SELECT publication.catalog_sha256, publication.presentation_sha256
    INTO v_user_catalog, v_user_presentation
    FROM system_resource_layout_publications AS publication
    WHERE publication.resource_kind = 'user'
      AND publication.revision_id = p_user_revision_id
      AND publication.catalog_sha256 IS NOT NULL
      AND publication.presentation_sha256 IS NOT NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'user installation layout is not published';
    END IF;
    SELECT publication.catalog_sha256, publication.presentation_sha256
    INTO v_organization_catalog, v_organization_presentation
    FROM system_resource_layout_publications AS publication
    WHERE publication.resource_kind = 'organization'
      AND publication.revision_id = p_organization_revision_id
      AND publication.catalog_sha256 IS NOT NULL
      AND publication.presentation_sha256 IS NOT NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'organization installation layout is not published';
    END IF;
    SELECT publication.catalog_sha256, publication.presentation_sha256
    INTO v_role_catalog, v_role_presentation
    FROM system_resource_layout_publications AS publication
    WHERE publication.resource_kind = 'role'
      AND publication.revision_id = p_role_revision_id
      AND publication.catalog_sha256 IS NOT NULL
      AND publication.presentation_sha256 IS NOT NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            MESSAGE = 'role installation layout is not published';
    END IF;
    v_digest := pg_catalog.sha256(
        pg_catalog.uuid_send(p_operation_id) || pg_catalog.uuid_send(p_tenant_id) ||
        pg_catalog.uuid_send(p_user_revision_id) || v_user_catalog || v_user_presentation ||
        pg_catalog.uuid_send(p_organization_revision_id) || v_organization_catalog ||
        v_organization_presentation || pg_catalog.uuid_send(p_role_revision_id) ||
        v_role_catalog || v_role_presentation
    );
    SELECT * INTO v_existing
    FROM system_resource_layout_installation_baselines AS baseline
    WHERE baseline.operation_id = p_operation_id
    FOR UPDATE;
    IF FOUND THEN
        IF v_existing.tenant_id IS DISTINCT FROM p_tenant_id
           OR v_existing.user_revision_id IS DISTINCT FROM p_user_revision_id
           OR v_existing.organization_revision_id IS DISTINCT FROM p_organization_revision_id
           OR v_existing.role_revision_id IS DISTINCT FROM p_role_revision_id
           OR v_existing.baseline_sha256 IS DISTINCT FROM v_digest THEN
            RAISE EXCEPTION USING ERRCODE = '23505',
                MESSAGE = 'system resource installation replay conflicts';
        END IF;
        RETURN v_digest;
    END IF;
    INSERT INTO system_resource_layout_installation_baselines (
        operation_id, tenant_id, user_revision_id, organization_revision_id,
        role_revision_id, baseline_sha256, initialized_at
    ) VALUES (
        p_operation_id, p_tenant_id, p_user_revision_id, p_organization_revision_id,
        p_role_revision_id, v_digest, p_now
    );
    RETURN v_digest;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_installation_record_v1(p_operation_id uuid, p_tenant_id uuid, p_user_revision_id uuid, p_organization_revision_id uuid, p_role_revision_id uuid, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_installation_record_v2(uuid, uuid, uuid, uuid, uuid, timestamp with time zone, name); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_installation_record_v2(p_operation_id uuid, p_tenant_id uuid, p_user_revision_id uuid, p_organization_revision_id uuid, p_role_revision_id uuid, p_now timestamp with time zone, p_schema_name name) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_digest bytea;
BEGIN
    PERFORM system_resource_layout_installation_assert_v2(
        p_operation_id, p_tenant_id, p_schema_name
    );
    v_digest := system_resource_layout_installation_record_v1(
        p_operation_id, p_tenant_id, p_user_revision_id,
        p_organization_revision_id, p_role_revision_id, p_now
    );
    IF NOT platform.tenancy_activation_step_consume_v1(
        p_operation_id, 'systemresources.initialize_tenant_baseline'
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource installation capability consume failed';
    END IF;
    RETURN v_digest;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_installation_record_v2(p_operation_id uuid, p_tenant_id uuid, p_user_revision_id uuid, p_organization_revision_id uuid, p_role_revision_id uuid, p_now timestamp with time zone, p_schema_name name) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_list_v1(name, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_list_v1(p_scope_schema name, p_resource_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource layout list scope is invalid';
    END IF;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            system_resource_layout_revision_json_v1(revision.id)
            ORDER BY revision.version
        ),
        '[]'::jsonb
    )
    INTO v_document
    FROM system_resource_layout_revisions AS revision
    WHERE revision.resource_kind = p_resource_kind;
    RETURN v_document;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_list_v1(p_scope_schema name, p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_publication_json_v2(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_publication_json_v2(p_resource_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    IF CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource layout publication read is invalid';
    END IF;
    SELECT pg_catalog.jsonb_build_object(
        'revision', system_resource_layout_revision_json_v1(publication.revision_id),
        'generation', publication.generation,
        'source_definition_sha256', pg_catalog.encode(
            publication.source_definition_sha256, 'hex'
        ),
        'compiler_version', publication.compiler_version,
        'catalog_contract', publication.catalog_contract,
        'catalog_json', publication.catalog_json,
        'catalog_sha256', pg_catalog.encode(publication.catalog_sha256, 'hex'),
        'presentation_contract', publication.presentation_contract,
        'presentation_json', publication.presentation_json,
        'presentation_sha256', pg_catalog.encode(
            publication.presentation_sha256, 'hex'
        )
    )
    INTO v_document
    FROM system_resource_layout_publications AS publication
    WHERE publication.resource_kind = p_resource_kind;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'published system resource layout was not found';
    END IF;
    RETURN v_document;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_publication_json_v2(p_resource_kind text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_publish_v1(name, uuid, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_publish_v1(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_catalog_json text, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_catalog_document jsonb;
    v_catalog_ids jsonb;
    v_definition text;
    v_field_ids jsonb;
    v_resource_kind text;
    v_row_revision bigint;
    v_state text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_expected_row_revision < 1
       OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_contract_guard',
            MESSAGE = 'system resource layout publish contract is invalid';
    END IF;
    BEGIN
        v_catalog_document := p_catalog_json::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_catalog_guard',
            MESSAGE = 'system resource layout catalog is invalid';
    END;
    IF pg_catalog.jsonb_typeof(v_catalog_document) <> 'array'
       OR pg_catalog.jsonb_array_length(v_catalog_document) > 512
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_catalog_document) AS field(value)
            WHERE pg_catalog.jsonb_typeof(field.value) <> 'string'
               OR field.value #>> '{}' !~
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
               OR field.value #>> '{}' =
                  '00000000-0000-0000-0000-000000000000'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_catalog_guard',
            MESSAGE = 'system resource layout catalog is invalid';
    END IF;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(field.value ORDER BY field.value #>> '{}'),
        '[]'::jsonb
    )
    INTO v_catalog_ids
    FROM pg_catalog.jsonb_array_elements(v_catalog_document) AS field(value);
    IF pg_catalog.jsonb_array_length(v_catalog_ids) IS DISTINCT FROM (
        SELECT pg_catalog.count(DISTINCT catalog.value #>> '{}')
        FROM pg_catalog.jsonb_array_elements(v_catalog_ids) AS catalog(value)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_catalog_guard',
            MESSAGE = 'system resource layout catalog contains duplicates';
    END IF;
    SELECT revision.state, revision.row_revision, revision.resource_kind,
           revision.definition_json
    INTO v_state, v_row_revision, v_resource_kind, v_definition
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    IF v_state IS DISTINCT FROM 'draft'
       OR v_row_revision IS DISTINCT FROM p_expected_row_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource layout revision conflicts';
    END IF;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            field.value -> 'field_id'
            ORDER BY field.value ->> 'field_id'
        ),
        '[]'::jsonb
    )
    INTO v_field_ids
    FROM pg_catalog.jsonb_array_elements(
        v_definition::jsonb -> 'sections'
    ) AS section(value)
    CROSS JOIN pg_catalog.jsonb_array_elements(
        section.value -> 'fields'
    ) AS field(value);
    IF v_field_ids IS DISTINCT FROM v_catalog_ids THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_field_guard',
            MESSAGE = 'system resource layout fields do not match IAM catalog';
    END IF;
    UPDATE system_resource_layout_revisions
    SET state = 'published', published_at = p_now,
        updated_at = p_now, row_revision = row_revision + 1
    WHERE id = p_revision_id;
    INSERT INTO system_resource_layout_publications (
        resource_kind, revision_id, generation, created_at, updated_at
    ) VALUES (
        v_resource_kind, p_revision_id, 1, p_now, p_now
    )
    ON CONFLICT (resource_kind) DO UPDATE
    SET revision_id = EXCLUDED.revision_id,
        generation = system_resource_layout_publications.generation + 1,
        updated_at = EXCLUDED.updated_at;
    RETURN system_resource_layout_revision_json_v1(p_revision_id);
END;
$_$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_publish_v1(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_catalog_json text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_publish_v2(name, uuid, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_publish_v2(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_catalog_json text, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_catalog_document jsonb;
    v_catalog_ids jsonb;
    v_active_catalog jsonb;
    v_active_ids jsonb;
    v_definition text;
    v_field_ids jsonb;
    v_resource_kind text;
    v_row_revision bigint;
    v_state text;
    v_lock_id text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_expected_row_revision < 1 OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_contract_guard',
            MESSAGE = 'system resource layout publish contract is invalid';
    END IF;
    BEGIN
        v_catalog_document := p_catalog_json::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_catalog_guard',
            MESSAGE = 'system resource layout catalog is invalid';
    END;
    IF pg_catalog.jsonb_typeof(v_catalog_document) <> 'array'
       OR pg_catalog.jsonb_array_length(v_catalog_document) > 512
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_catalog_document) AS field(value)
            WHERE pg_catalog.jsonb_typeof(field.value) <> 'string'
               OR field.value #>> '{}' !~
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
               OR field.value #>> '{}' =
                  '00000000-0000-0000-0000-000000000000'
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_catalog_guard',
            MESSAGE = 'system resource layout catalog is invalid';
    END IF;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(field.value ORDER BY field.value #>> '{}'),
        '[]'::jsonb
    ) INTO v_catalog_ids
    FROM pg_catalog.jsonb_array_elements(v_catalog_document) AS field(value);
    IF pg_catalog.jsonb_array_length(v_catalog_ids) IS DISTINCT FROM (
        SELECT pg_catalog.count(DISTINCT catalog.value #>> '{}')
        FROM pg_catalog.jsonb_array_elements(v_catalog_ids) AS catalog(value)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_catalog_guard',
            MESSAGE = 'system resource layout catalog contains duplicates';
    END IF;
    SELECT revision.state, revision.row_revision, revision.resource_kind,
           revision.definition_json
    INTO v_state, v_row_revision, v_resource_kind, v_definition
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    IF v_state IS DISTINCT FROM 'draft'
       OR v_row_revision IS DISTINCT FROM p_expected_row_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource layout revision conflicts';
    END IF;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(
            field.value -> 'field_id' ORDER BY field.value ->> 'field_id'
        ),
        '[]'::jsonb
    ) INTO v_field_ids
    FROM pg_catalog.jsonb_array_elements(
        v_definition::jsonb -> 'sections'
    ) AS section(value)
    CROSS JOIN pg_catalog.jsonb_array_elements(
        section.value -> 'fields'
    ) AS field(value);
    FOR v_lock_id IN
        SELECT referenced.field_id
        FROM (
            SELECT field.value ->> 'field_id' AS field_id
            FROM pg_catalog.jsonb_array_elements(
                v_definition::jsonb -> 'sections'
            ) AS section(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(
                section.value -> 'fields'
            ) AS field(value)
            UNION
            SELECT field.value ->> 'field_id'
            FROM system_resource_layout_publications AS publication
            JOIN system_resource_layout_revisions AS published
              ON published.id = publication.revision_id
            CROSS JOIN pg_catalog.jsonb_array_elements(
                published.definition_json::jsonb -> 'sections'
            ) AS section(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(
                section.value -> 'fields'
            ) AS field(value)
            WHERE publication.resource_kind = v_resource_kind
        ) AS referenced
        ORDER BY referenced.field_id
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(v_lock_id, 8501)
        );
    END LOOP;
    v_active_catalog := iam_profile_active_catalog_read_v1(
        p_scope_schema, v_resource_kind
    );
    SELECT COALESCE(
        pg_catalog.jsonb_agg(field.value -> 'id' ORDER BY field.value ->> 'id'),
        '[]'::jsonb
    ) INTO v_active_ids
    FROM pg_catalog.jsonb_array_elements(
        v_active_catalog -> 'fields'
    ) AS field(value)
    WHERE field.value ->> 'state' = 'active';
    IF v_active_catalog IS NULL OR v_catalog_ids IS DISTINCT FROM v_active_ids OR
       EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_field_ids) AS field(value)
            WHERE NOT v_catalog_ids ? (field.value #>> '{}')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_field_guard',
            MESSAGE = 'system resource layout fields are outside the active IAM catalog';
    END IF;
    UPDATE system_resource_layout_revisions
    SET state = 'published', published_at = p_now,
        updated_at = p_now, row_revision = row_revision + 1
    WHERE id = p_revision_id;
    INSERT INTO system_resource_layout_publications (
        resource_kind, revision_id, generation, created_at, updated_at
    ) VALUES (
        v_resource_kind, p_revision_id, 1, p_now, p_now
    )
    ON CONFLICT (resource_kind) DO UPDATE
    SET revision_id = EXCLUDED.revision_id,
        generation = system_resource_layout_publications.generation + 1,
        updated_at = EXCLUDED.updated_at;
    RETURN system_resource_layout_revision_json_v1(p_revision_id);
END;
$_$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_publish_v2(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_catalog_json text, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_publish_v3(name, uuid, bigint, bytea, text, text, text, bytea, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_publish_v3(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_source_definition_sha256 bytea, p_compiler_version text, p_catalog_contract text, p_catalog_json text, p_catalog_sha256 bytea, p_presentation_contract text, p_presentation_json text, p_presentation_sha256 bytea, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_catalog jsonb;
    v_catalog_ids jsonb;
    v_definition text;
    v_definition_sha256 bytea;
    v_field_ids jsonb;
    v_lock_id text;
    v_presentation jsonb;
    v_resource_kind text;
    v_row_revision bigint;
    v_state text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_revision_id IS NULL OR p_expected_row_revision < 1 OR p_now IS NULL
       OR p_compiler_version IS DISTINCT FROM
            'system-resource-presentation-compiler.v1'
       OR p_catalog_contract IS DISTINCT FROM
            'forms-presentation-field-catalog.v1'
       OR p_presentation_contract IS DISTINCT FROM 'forms-presentation.v1'
       OR pg_catalog.octet_length(p_source_definition_sha256) <> 32
       OR pg_catalog.octet_length(p_catalog_sha256) <> 32
       OR pg_catalog.octet_length(p_presentation_sha256) <> 32
       OR p_catalog_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_catalog_json, 'UTF8')
       )
       OR p_presentation_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_presentation_json, 'UTF8')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v3_contract_guard',
            MESSAGE = 'system resource presentation publish contract is invalid';
    END IF;
    BEGIN
        v_catalog := p_catalog_json::jsonb;
        v_presentation := p_presentation_json::jsonb;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v3_document_guard',
            MESSAGE = 'system resource presentation document is invalid';
    END;
    IF pg_catalog.jsonb_typeof(v_catalog) <> 'object'
       OR v_catalog ->> 'contract' IS DISTINCT FROM p_catalog_contract
       OR pg_catalog.jsonb_typeof(v_catalog -> 'fields') <> 'array'
       OR pg_catalog.jsonb_array_length(v_catalog -> 'fields') > 500
       OR pg_catalog.jsonb_typeof(v_presentation) <> 'object'
       OR v_presentation ->> 'registry_contract' IS DISTINCT FROM
            'forms-presentation-registry.v1'
       OR EXISTS (
            SELECT 1
            FROM pg_catalog.jsonb_array_elements(v_catalog -> 'fields') AS field(value)
            WHERE pg_catalog.jsonb_typeof(field.value) <> 'object'
               OR field.value ->> 'id' !~
                  '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
               OR field.value ->> 'id' = '00000000-0000-0000-0000-000000000000'
               OR field.value ->> 'mode' NOT IN ('editable', 'read_only')
               OR COALESCE(field.value ->> 'type_id', '') = ''
               OR COALESCE(field.value ->> 'value_profile', '') = ''
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v3_document_guard',
            MESSAGE = 'system resource presentation document is invalid';
    END IF;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(field.value -> 'id' ORDER BY field.value ->> 'id'),
        '[]'::jsonb
    ) INTO v_catalog_ids
    FROM pg_catalog.jsonb_array_elements(v_catalog -> 'fields') AS field(value);
    IF pg_catalog.jsonb_array_length(v_catalog_ids) IS DISTINCT FROM (
        SELECT pg_catalog.count(DISTINCT field.value #>> '{}')
        FROM pg_catalog.jsonb_array_elements(v_catalog_ids) AS field(value)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v3_document_guard',
            MESSAGE = 'system resource presentation catalog contains duplicates';
    END IF;
    SELECT revision.state, revision.row_revision, revision.resource_kind,
           revision.definition_json, revision.definition_sha256
    INTO v_state, v_row_revision, v_resource_kind,
         v_definition, v_definition_sha256
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    IF v_state IS DISTINCT FROM 'draft'
       OR v_row_revision IS DISTINCT FROM p_expected_row_revision
       OR v_definition_sha256 IS DISTINCT FROM p_source_definition_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource layout revision conflicts';
    END IF;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(field.value -> 'field_id' ORDER BY field.value ->> 'field_id'),
        '[]'::jsonb
    ) INTO v_field_ids
    FROM pg_catalog.jsonb_array_elements(v_definition::jsonb -> 'sections') section(value)
    CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields') field(value);
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_field_ids) field(value)
        WHERE NOT v_catalog_ids ? (field.value #>> '{}')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v3_field_guard',
            MESSAGE = 'system resource layout fields are outside the supplied catalog';
    END IF;
    FOR v_lock_id IN
        SELECT referenced.field_id FROM (
            SELECT field.value ->> 'field_id' AS field_id
            FROM pg_catalog.jsonb_array_elements(v_definition::jsonb -> 'sections') section(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields') field(value)
            UNION
            SELECT field.value ->> 'field_id'
            FROM system_resource_layout_publications publication
            JOIN system_resource_layout_revisions published
              ON published.id = publication.revision_id
            CROSS JOIN pg_catalog.jsonb_array_elements(published.definition_json::jsonb -> 'sections') section(value)
            CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields') field(value)
            WHERE publication.resource_kind = v_resource_kind
        ) referenced ORDER BY referenced.field_id
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(v_lock_id, 8501)
        );
    END LOOP;
    UPDATE system_resource_layout_revisions
    SET state = 'published', published_at = p_now,
        updated_at = p_now, row_revision = row_revision + 1
    WHERE id = p_revision_id;
    INSERT INTO system_resource_layout_publications (
        resource_kind, revision_id, generation, created_at, updated_at,
        source_definition_sha256, compiler_version, catalog_contract,
        catalog_json, catalog_sha256, presentation_contract,
        presentation_json, presentation_sha256
    ) VALUES (
        v_resource_kind, p_revision_id, 1, p_now, p_now,
        p_source_definition_sha256, p_compiler_version, p_catalog_contract,
        p_catalog_json, p_catalog_sha256, p_presentation_contract,
        p_presentation_json, p_presentation_sha256
    ) ON CONFLICT (resource_kind) DO UPDATE SET
        revision_id = EXCLUDED.revision_id,
        generation = system_resource_layout_publications.generation + 1,
        updated_at = EXCLUDED.updated_at,
        source_definition_sha256 = EXCLUDED.source_definition_sha256,
        compiler_version = EXCLUDED.compiler_version,
        catalog_contract = EXCLUDED.catalog_contract,
        catalog_json = EXCLUDED.catalog_json,
        catalog_sha256 = EXCLUDED.catalog_sha256,
        presentation_contract = EXCLUDED.presentation_contract,
        presentation_json = EXCLUDED.presentation_json,
        presentation_sha256 = EXCLUDED.presentation_sha256;
    RETURN system_resource_layout_publication_json_v2(v_resource_kind);
END;
$_$;


