--
-- Name: system_resource_layout_publish_v4(name, uuid, bigint, bytea, text, text, text, bytea, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_publish_v4(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_source_definition_sha256 bytea, p_compiler_version text, p_catalog_contract text, p_catalog_json text, p_catalog_sha256 bytea, p_presentation_contract text, p_presentation_json text, p_presentation_sha256 bytea, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_catalog jsonb;
    v_catalog_ids jsonb;
    v_contract text;
    v_definition text;
    v_definition_sha256 bytea;
    v_field_ids jsonb;
    v_lock_id text;
    v_presentation jsonb;
    v_resource_kind text;
    v_row_revision bigint;
    v_state text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_revision_id IS NULL OR p_expected_row_revision < 1 OR p_now IS NULL
       OR p_compiler_version NOT IN (
            'system-resource-presentation-compiler.v1',
            'system-resource-presentation-compiler.v2'
       )
       OR p_catalog_contract IS DISTINCT FROM
            'forms-presentation-field-catalog.v1'
       OR p_presentation_contract IS DISTINCT FROM 'forms-presentation.v1'
       OR pg_catalog.octet_length(p_source_definition_sha256) <> 32
       OR pg_catalog.octet_length(p_catalog_sha256) <> 32
       OR pg_catalog.octet_length(p_presentation_sha256) <> 32
       OR p_catalog_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_catalog_json, 'UTF8')
       )
       OR p_presentation_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_presentation_json, 'UTF8')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v4_contract_guard',
            MESSAGE = 'system resource presentation publish contract is invalid';
    END IF;
    BEGIN
        v_catalog := p_catalog_json::jsonb;
        v_presentation := p_presentation_json::jsonb;
        IF pg_catalog.jsonb_typeof(v_catalog) IS DISTINCT FROM 'object'
           OR v_catalog ->> 'contract' IS DISTINCT FROM p_catalog_contract
           OR pg_catalog.jsonb_typeof(v_catalog -> 'fields') IS DISTINCT FROM 'array'
           OR pg_catalog.jsonb_array_length(v_catalog -> 'fields') > 500
           OR pg_catalog.jsonb_typeof(v_presentation) IS DISTINCT FROM 'object'
           OR v_presentation ->> 'registry_contract' IS DISTINCT FROM
                'forms-presentation-registry.v1'
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_array_elements(v_catalog -> 'fields')
                    AS field(value)
                WHERE pg_catalog.jsonb_typeof(field.value) IS DISTINCT FROM 'object'
                   OR field.value ->> 'id' !~
                      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
                   OR field.value ->> 'id' =
                      '00000000-0000-0000-0000-000000000000'
                   OR field.value ->> 'mode' NOT IN ('editable', 'read_only')
                   OR COALESCE(field.value ->> 'type_id', '') = ''
                   OR COALESCE(field.value ->> 'value_profile', '') = ''
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '23514',
                CONSTRAINT = 'system_resource_layout_publish_v4_document_guard',
                MESSAGE = 'system resource presentation document is invalid';
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v4_document_guard',
            MESSAGE = 'system resource presentation document is invalid';
    END;
    SELECT COALESCE(
        pg_catalog.jsonb_agg(field.value -> 'id' ORDER BY field.value ->> 'id'),
        '[]'::jsonb
    ) INTO v_catalog_ids
    FROM pg_catalog.jsonb_array_elements(v_catalog -> 'fields') AS field(value);
    IF pg_catalog.jsonb_array_length(v_catalog_ids) IS DISTINCT FROM (
        SELECT pg_catalog.count(DISTINCT field.value #>> '{}')
        FROM pg_catalog.jsonb_array_elements(v_catalog_ids) AS field(value)
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v4_document_guard',
            MESSAGE = 'system resource presentation catalog contains duplicates';
    END IF;
    SELECT revision.state, revision.row_revision, revision.resource_kind,
           revision.definition_json, revision.definition_sha256
    INTO v_state, v_row_revision, v_resource_kind,
         v_definition, v_definition_sha256
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    IF v_state IS DISTINCT FROM 'draft'
       OR v_row_revision IS DISTINCT FROM p_expected_row_revision
       OR v_definition_sha256 IS DISTINCT FROM p_source_definition_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource layout revision conflicts';
    END IF;
    v_contract := v_definition::jsonb ->> 'contract';
    IF (v_contract = 'harpy/system-resource-layout/v1' AND
        p_compiler_version <> 'system-resource-presentation-compiler.v1')
       OR (v_contract = 'harpy/system-resource-layout/v2' AND
           p_compiler_version <> 'system-resource-presentation-compiler.v2') THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v4_compiler_guard',
            MESSAGE = 'system resource layout compiler does not match definition';
    END IF;
    v_field_ids := system_resource_layout_field_ids_v2(v_definition);
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(v_field_ids) AS field(value)
        WHERE NOT v_catalog_ids ? (field.value #>> '{}')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v4_field_guard',
            MESSAGE = 'system resource layout fields are outside the supplied catalog';
    END IF;
    FOR v_lock_id IN
        SELECT DISTINCT referenced.field_id FROM (
            SELECT field.value #>> '{}' AS field_id
            FROM pg_catalog.jsonb_array_elements(v_field_ids) AS field(value)
            UNION ALL
            SELECT field.value #>> '{}'
            FROM system_resource_layout_publications AS publication
            JOIN system_resource_layout_revisions AS published
              ON published.id = publication.revision_id
            CROSS JOIN pg_catalog.jsonb_array_elements(
                system_resource_layout_field_ids_v2(published.definition_json)
            ) AS field(value)
            WHERE publication.resource_kind = v_resource_kind
        ) AS referenced ORDER BY referenced.field_id
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(v_lock_id, 8501)
        );
    END LOOP;
    UPDATE system_resource_layout_revisions
    SET state = 'published', published_at = p_now,
        updated_at = p_now, row_revision = row_revision + 1
    WHERE id = p_revision_id;
    INSERT INTO system_resource_layout_publications (
        resource_kind, revision_id, generation, created_at, updated_at,
        source_definition_sha256, compiler_version, catalog_contract,
        catalog_json, catalog_sha256, presentation_contract,
        presentation_json, presentation_sha256
    ) VALUES (
        v_resource_kind, p_revision_id, 1, p_now, p_now,
        p_source_definition_sha256, p_compiler_version, p_catalog_contract,
        p_catalog_json, p_catalog_sha256, p_presentation_contract,
        p_presentation_json, p_presentation_sha256
    ) ON CONFLICT (resource_kind) DO UPDATE SET
        revision_id = EXCLUDED.revision_id,
        generation = system_resource_layout_publications.generation + 1,
        updated_at = EXCLUDED.updated_at,
        source_definition_sha256 = EXCLUDED.source_definition_sha256,
        compiler_version = EXCLUDED.compiler_version,
        catalog_contract = EXCLUDED.catalog_contract,
        catalog_json = EXCLUDED.catalog_json,
        catalog_sha256 = EXCLUDED.catalog_sha256,
        presentation_contract = EXCLUDED.presentation_contract,
        presentation_json = EXCLUDED.presentation_json,
        presentation_sha256 = EXCLUDED.presentation_sha256;
    RETURN system_resource_layout_publication_json_v2(v_resource_kind);
END;
$_$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_publish_v4(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_source_definition_sha256 bytea, p_compiler_version text, p_catalog_contract text, p_catalog_json text, p_catalog_sha256 bytea, p_presentation_contract text, p_presentation_json text, p_presentation_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_publish_v5(name, uuid, bigint, bytea, text, text, text, bytea, text, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_publish_v5(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_source_definition_sha256 bytea, p_compiler_version text, p_catalog_contract text, p_catalog_json text, p_catalog_sha256 bytea, p_presentation_contract text, p_presentation_json text, p_presentation_sha256 bytea, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_resource_kind text;
    v_row_revision bigint;
    v_state text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_revision_id IS NULL OR p_expected_row_revision < 1
       OR p_expected_row_revision = 9223372036854775807 OR p_now IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_publish_v5_contract_guard',
            MESSAGE = 'system resource layout v5 publish contract is invalid';
    END IF;
    SELECT revision.state, revision.row_revision, revision.resource_kind
    INTO v_state, v_row_revision, v_resource_kind
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    IF v_state = 'published' THEN
        IF v_row_revision IS DISTINCT FROM p_expected_row_revision + 1
           OR NOT EXISTS (
                SELECT 1
                FROM system_resource_layout_publications AS publication
                WHERE publication.resource_kind = v_resource_kind
                  AND publication.revision_id = p_revision_id
                  AND publication.source_definition_sha256 = p_source_definition_sha256
                  AND publication.compiler_version = p_compiler_version
                  AND publication.catalog_contract = p_catalog_contract
                  AND publication.catalog_json = p_catalog_json
                  AND publication.catalog_sha256 = p_catalog_sha256
                  AND publication.presentation_contract = p_presentation_contract
                  AND publication.presentation_json = p_presentation_json
                  AND publication.presentation_sha256 = p_presentation_sha256
           ) THEN
            RAISE EXCEPTION USING ERRCODE = '40001',
                MESSAGE = 'system resource layout publication replay conflicts';
        END IF;
        RETURN system_resource_layout_publication_json_v2(v_resource_kind);
    END IF;
    IF v_state IS DISTINCT FROM 'draft'
       OR v_row_revision IS DISTINCT FROM p_expected_row_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource layout revision conflicts';
    END IF;
    RETURN system_resource_layout_publish_v4(
        p_scope_schema, p_revision_id, p_expected_row_revision,
        p_source_definition_sha256, p_compiler_version,
        p_catalog_contract, p_catalog_json, p_catalog_sha256,
        p_presentation_contract, p_presentation_json,
        p_presentation_sha256, p_now
    );
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_publish_v5(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_source_definition_sha256 bytea, p_compiler_version text, p_catalog_contract text, p_catalog_json text, p_catalog_sha256 bytea, p_presentation_contract text, p_presentation_json text, p_presentation_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_repair_curated_defaults_v3(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_repair_curated_defaults_v3(p_successor_contract text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_current system_resource_layout_publications%ROWTYPE;
    v_revision system_resource_layout_revisions%ROWTYPE;
    v_baseline_revision_id uuid;
    v_revision_id uuid; v_created_at timestamptz; v_catalog text;
    v_definition text; v_presentation text; v_definition_sha bytea;
    v_presentation_sha bytea; v_catalog_sha bytea;
    v_next_version bigint; v_changed bigint:=0;
BEGIN
    IF p_successor_contract IS DISTINCT FROM
       'curated-system-resource-parity-successor.v2' THEN
        RAISE EXCEPTION USING ERRCODE='22023',
            MESSAGE='system resource curated parity contract is invalid';
    END IF;
    IF (SELECT pg_catalog.count(*) FROM
        system_resource_layout_installation_baselines)=0 THEN RETURN 0; END IF;
    FOR v_current IN
        SELECT publication.* FROM system_resource_layout_publications AS publication
        WHERE publication.generation=2 ORDER BY publication.resource_kind
    LOOP
        SELECT revision.* INTO STRICT v_revision
          FROM system_resource_layout_revisions AS revision
         WHERE revision.id=v_current.revision_id;
        IF NOT system_resource_layout_curated_predecessor_valid_v1(
            v_current.resource_kind) THEN
            SELECT CASE v_current.resource_kind
                WHEN 'user' THEN baseline.user_revision_id
                WHEN 'organization' THEN baseline.organization_revision_id
                ELSE baseline.role_revision_id END
              INTO STRICT v_baseline_revision_id
              FROM system_resource_layout_installation_baselines AS baseline;
            IF v_revision.id=system_resource_layout_deterministic_uuid_v7_v1(
                v_baseline_revision_id::text,
                'curated-installation-default-successor.v1',
                v_revision.created_at) THEN
                RAISE EXCEPTION USING ERRCODE='23514',
                    MESSAGE='system resource curated predecessor is invalid';
            END IF;
            CONTINUE;
        END IF;
        v_created_at:=greatest(
            v_current.updated_at,v_revision.created_at)+INTERVAL '1 microsecond';
        v_revision_id:=system_resource_layout_deterministic_uuid_v7_v1(
            v_current.revision_id::text,p_successor_contract,v_created_at);
        v_catalog:=system_resource_layout_curated_successor_catalog_v1(
            v_current.resource_kind,v_current.catalog_json);
        v_catalog_sha:=pg_catalog.sha256(pg_catalog.convert_to(v_catalog,'UTF8'));
        v_definition:=system_resource_layout_curated_definition_v2(
            v_current.resource_kind,v_catalog);
        v_definition_sha:=pg_catalog.sha256(
            pg_catalog.convert_to(v_definition,'UTF8'));
        v_presentation:=system_resource_layout_compile_curated_v1(
            v_revision_id,v_created_at,v_definition,v_catalog);
        v_presentation_sha:=pg_catalog.sha256(
            pg_catalog.convert_to(v_presentation,'UTF8'));
        SELECT COALESCE(pg_catalog.max(revision.version),0)+1
          INTO v_next_version FROM system_resource_layout_revisions AS revision
         WHERE revision.resource_kind=v_current.resource_kind;
        INSERT INTO system_resource_layout_revisions
            (id,resource_kind,version,state,definition_json,definition_sha256,
             created_at,updated_at,published_at,row_revision)
        VALUES(v_revision_id,v_current.resource_kind,v_next_version,'draft',
            v_definition,v_definition_sha,v_created_at,v_created_at,NULL,1);
        UPDATE system_resource_layout_revisions AS revision SET state='published',
            published_at=v_created_at,updated_at=v_created_at,row_revision=2
         WHERE revision.id=v_revision_id AND revision.state='draft'
           AND revision.row_revision=1;
        IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='system resource curated parity revision conflicted'; END IF;
        UPDATE system_resource_layout_publications AS publication
           SET revision_id=v_revision_id,generation=v_current.generation+1,
               updated_at=v_created_at,source_definition_sha256=v_definition_sha,
               compiler_version='system-resource-presentation-compiler.v2',
               catalog_json=v_catalog,catalog_sha256=v_catalog_sha,
               presentation_json=v_presentation,
               presentation_sha256=v_presentation_sha
         WHERE publication.resource_kind=v_current.resource_kind
           AND publication.revision_id=v_current.revision_id
           AND publication.generation=v_current.generation;
        IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',
            MESSAGE='system resource curated parity publication conflicted'; END IF;
        v_changed:=v_changed+1;
    END LOOP;
    RETURN v_changed;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_repair_curated_defaults_v3(p_successor_contract text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_repair_installation_defaults_v2(text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_repair_installation_defaults_v2(p_successor_contract text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    current_record system_resource_layout_publications%ROWTYPE;
    v_revision_id uuid; v_created_at timestamptz; v_definition text;
    v_presentation text; v_definition_sha bytea; v_presentation_sha bytea;
    v_next_version bigint; v_changed bigint := 0;
BEGIN
 IF p_successor_contract IS DISTINCT FROM 'curated-installation-default-successor.v1' THEN
  RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='system resource successor contract is invalid';
 END IF;
 IF (SELECT pg_catalog.count(*) FROM system_resource_layout_installation_baselines)=0 THEN RETURN 0; END IF;
 IF NOT system_resource_layout_installation_baseline_evidence_valid_v2(
    'installation-baseline-evidence.v1') THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='system resource installation baseline evidence is invalid';
 END IF;
 FOR current_record IN SELECT publication.* FROM
  system_resource_layout_publications publication
  JOIN system_resource_layout_installation_baselines baseline
   ON publication.revision_id=CASE publication.resource_kind
    WHEN 'user' THEN baseline.user_revision_id
    WHEN 'organization' THEN baseline.organization_revision_id
    ELSE baseline.role_revision_id END
  WHERE publication.generation=1 ORDER BY publication.resource_kind
 LOOP
  SELECT greatest(current_record.updated_at,revision.created_at)+INTERVAL '1 microsecond'
   INTO v_created_at FROM system_resource_layout_revisions AS revision
   WHERE revision.id=current_record.revision_id;
  v_revision_id:=system_resource_layout_deterministic_uuid_v7_v1(
   current_record.revision_id::text,p_successor_contract,v_created_at);
  v_definition:=system_resource_layout_curated_definition_v1(
   current_record.resource_kind,current_record.catalog_json);
  v_definition_sha:=pg_catalog.sha256(pg_catalog.convert_to(v_definition,'UTF8'));
  v_presentation:=system_resource_layout_compile_curated_v1(
   v_revision_id,v_created_at,v_definition,current_record.catalog_json);
  v_presentation_sha:=pg_catalog.sha256(pg_catalog.convert_to(v_presentation,'UTF8'));
  SELECT COALESCE(pg_catalog.max(revision.version),0)+1 INTO v_next_version
    FROM system_resource_layout_revisions AS revision
   WHERE revision.resource_kind=current_record.resource_kind;
  INSERT INTO system_resource_layout_revisions
   (id,resource_kind,version,state,definition_json,definition_sha256,
    created_at,updated_at,published_at,row_revision)
  VALUES(v_revision_id,current_record.resource_kind,v_next_version,'draft',
   v_definition,v_definition_sha,v_created_at,v_created_at,NULL,1);
  UPDATE system_resource_layout_revisions AS revision SET state='published',
   published_at=v_created_at,updated_at=v_created_at,row_revision=2
   WHERE revision.id=v_revision_id AND revision.state='draft'
    AND revision.row_revision=1;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='system resource curated successor publish conflicted'; END IF;
  UPDATE system_resource_layout_publications AS publication
   SET revision_id=v_revision_id,
   generation=current_record.generation+1,updated_at=v_created_at,
   source_definition_sha256=v_definition_sha,
   compiler_version='system-resource-presentation-compiler.v2',
   catalog_json=current_record.catalog_json,
   catalog_sha256=current_record.catalog_sha256,
   presentation_json=v_presentation,presentation_sha256=v_presentation_sha
   WHERE publication.resource_kind=current_record.resource_kind
    AND publication.revision_id=current_record.revision_id
    AND publication.generation=current_record.generation;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',
   MESSAGE='system resource curated publication conflicted'; END IF;
  v_changed:=v_changed+1;
 END LOOP;
 RETURN v_changed;
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_repair_installation_defaults_v2(p_successor_contract text) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_resolve_v1(name, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_resolve_v1(p_scope_schema name, p_resource_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_revision_id uuid;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_resource_kind NOT IN ('user', 'organization', 'role') THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'system resource layout resolve scope is invalid';
    END IF;
    SELECT publication.revision_id
    INTO v_revision_id
    FROM system_resource_layout_publications AS publication
    WHERE publication.resource_kind = p_resource_kind;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'published system resource layout was not found';
    END IF;
    RETURN system_resource_layout_revision_json_v1(v_revision_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_resolve_v1(p_scope_schema name, p_resource_kind text) OWNER TO harpy_owner;

