--
-- Name: system_resource_layout_revision_json_v1(uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_revision_json_v1(p_revision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_document jsonb;
BEGIN
    SELECT pg_catalog.jsonb_build_object(
        'id', revision.id,
        'resource_kind', revision.resource_kind,
        'version', revision.version,
        'state', revision.state,
        'definition', revision.definition_json::jsonb,
        'definition_sha256', pg_catalog.encode(
            revision.definition_sha256, 'hex'
        ),
        'created_at', revision.created_at,
        'updated_at', revision.updated_at,
        'published_at', revision.published_at,
        'row_revision', revision.row_revision
    )
    INTO v_document
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id;
    RETURN v_document;
END;
$$;


