--
-- Name: system_resource_layout_sections_valid_v2(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_sections_valid_v2(p_sections jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
BEGIN
    IF pg_catalog.jsonb_typeof(p_sections) IS DISTINCT FROM 'array' THEN
        RETURN false;
    END IF;
    IF pg_catalog.jsonb_array_length(p_sections) > 64 THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_sections)
            WITH ORDINALITY AS section(value, position)
        WHERE pg_catalog.jsonb_typeof(section.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.count(*)
               FROM pg_catalog.jsonb_object_keys(section.value)) <> 4
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(section.value) AS present(key)
                WHERE present.key NOT IN ('fields', 'id', 'order', 'translations')
           )
           OR pg_catalog.jsonb_typeof(section.value -> 'id') IS DISTINCT FROM 'string'
           OR section.value ->> 'id' !~
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR section.value ->> 'id' = '00000000-0000-0000-0000-000000000000'
           OR pg_catalog.jsonb_typeof(section.value -> 'order') IS DISTINCT FROM 'number'
           OR section.value ->> 'order' IS DISTINCT FROM
              (section.position - 1)::text
           OR pg_catalog.jsonb_typeof(section.value -> 'fields') IS DISTINCT FROM 'array'
           OR pg_catalog.jsonb_typeof(section.value -> 'translations') IS DISTINCT FROM 'array'
    ) THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_catalog.jsonb_array_elements(p_sections) AS section(value)
        WHERE NOT system_resource_layout_translations_valid_v2(
            section.value -> 'translations'
        )
    ) THEN
        RETURN false;
    END IF;
    IF (SELECT pg_catalog.count(*)
        FROM pg_catalog.jsonb_array_elements(p_sections) AS section(value)
        CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields')) > 512 THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_sections) AS section(value)
        CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields')
            WITH ORDINALITY AS field(value, position)
        WHERE pg_catalog.jsonb_typeof(field.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.count(*)
               FROM pg_catalog.jsonb_object_keys(field.value)) <> 5
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(field.value) AS present(key)
                WHERE present.key NOT IN (
                    'field_id', 'interaction', 'order', 'translations', 'widget'
                )
           )
           OR pg_catalog.jsonb_typeof(field.value -> 'field_id') IS DISTINCT FROM 'string'
           OR field.value ->> 'field_id' !~
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
           OR field.value ->> 'field_id' = '00000000-0000-0000-0000-000000000000'
           OR pg_catalog.jsonb_typeof(field.value -> 'interaction') IS DISTINCT FROM 'string'
           OR field.value ->> 'interaction' NOT IN ('auto', 'read_only', 'disabled')
           OR pg_catalog.jsonb_typeof(field.value -> 'order') IS DISTINCT FROM 'number'
           OR field.value ->> 'order' IS DISTINCT FROM (field.position - 1)::text
           OR pg_catalog.jsonb_typeof(field.value -> 'translations') IS DISTINCT FROM 'array'
           OR pg_catalog.jsonb_typeof(field.value -> 'widget') IS DISTINCT FROM 'string'
           OR field.value ->> 'widget' NOT IN (
                'auto', 'checkbox', 'date', 'datetime', 'document_selector',
                'document_uploader', 'email', 'json', 'lookup', 'multi_select',
                'number', 'password', 'radio', 'select', 'telephone', 'text',
                'textarea', 'time', 'toggle', 'url'
           )
    ) THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_sections) AS section(value)
        CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields')
            AS field(value)
        WHERE NOT system_resource_layout_translations_valid_v2(
            field.value -> 'translations'
        )
    ) OR EXISTS (
        SELECT section.value ->> 'id'
        FROM pg_catalog.jsonb_array_elements(p_sections) AS section(value)
        GROUP BY section.value ->> 'id' HAVING pg_catalog.count(*) > 1
    ) OR EXISTS (
        SELECT field.value ->> 'field_id'
        FROM pg_catalog.jsonb_array_elements(p_sections) AS section(value)
        CROSS JOIN pg_catalog.jsonb_array_elements(section.value -> 'fields')
            AS field(value)
        GROUP BY field.value ->> 'field_id' HAVING pg_catalog.count(*) > 1
    ) THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_sections_valid_v2(p_sections jsonb) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_translations_valid_v2(jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_translations_valid_v2(p_translations jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
    IF pg_catalog.jsonb_typeof(p_translations) IS DISTINCT FROM 'array' THEN
        RETURN false;
    END IF;
    IF pg_catalog.jsonb_array_length(p_translations) > 32 THEN
        RETURN false;
    END IF;
    IF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(p_translations) AS item(value)
        WHERE pg_catalog.jsonb_typeof(item.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.count(*)
               FROM pg_catalog.jsonb_object_keys(item.value)) <> 3
           OR EXISTS (
                SELECT 1
                FROM pg_catalog.jsonb_object_keys(item.value) AS present(key)
                WHERE present.key NOT IN ('help', 'label', 'locale')
           )
           OR pg_catalog.jsonb_typeof(item.value -> 'help') IS DISTINCT FROM 'string'
           OR pg_catalog.jsonb_typeof(item.value -> 'label') IS DISTINCT FROM 'string'
           OR pg_catalog.jsonb_typeof(item.value -> 'locale') IS DISTINCT FROM 'string'
           OR item.value ->> 'locale' !~
              '^[a-z]{2,3}(-[A-Z][a-z]{3})?(-([A-Z]{2}|[0-9]{3}))?$'
           OR pg_catalog.char_length(item.value ->> 'label') NOT BETWEEN 1 AND 200
           OR pg_catalog.char_length(item.value ->> 'help') > 1000
           OR item.value ->> 'label' ~ '[[:cntrl:]]'
           OR item.value ->> 'help' ~ '[[:cntrl:]]'
    ) OR EXISTS (
        SELECT item.value ->> 'locale'
        FROM pg_catalog.jsonb_array_elements(p_translations) AS item(value)
        GROUP BY item.value ->> 'locale'
        HAVING pg_catalog.count(*) > 1
    ) OR p_translations IS DISTINCT FROM COALESCE(
        (SELECT pg_catalog.jsonb_agg(item.value ORDER BY item.value ->> 'locale')
         FROM pg_catalog.jsonb_array_elements(p_translations) AS item(value)),
        '[]'::jsonb
    ) THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$_$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_translations_valid_v2(p_translations jsonb) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_update_v1(name, uuid, bigint, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_update_v1(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_state text;
    v_row_revision bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_expected_row_revision < 1
       OR p_now IS NULL
       OR NOT system_resource_layout_definition_valid_v1(p_definition_json)
       OR pg_catalog.octet_length(p_definition_sha256) <> 32
       OR p_definition_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_definition_json, 'UTF8')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_update_contract_guard',
            MESSAGE = 'system resource layout update contract is invalid';
    END IF;
    SELECT revision.state, revision.row_revision
    INTO v_state, v_row_revision
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    IF v_state IS DISTINCT FROM 'draft'
       OR v_row_revision IS DISTINCT FROM p_expected_row_revision THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource layout revision conflicts';
    END IF;
    UPDATE system_resource_layout_revisions
    SET definition_json = p_definition_json,
        definition_sha256 = p_definition_sha256,
        updated_at = p_now,
        row_revision = row_revision + 1
    WHERE id = p_revision_id;
    RETURN system_resource_layout_revision_json_v1(p_revision_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_update_v1(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

--
-- Name: system_resource_layout_update_v2(name, uuid, bigint, text, bytea, timestamp with time zone); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.system_resource_layout_update_v2(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_contract text;
    v_row_revision bigint;
    v_state text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'
       OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR p_scope_schema IS DISTINCT FROM pg_catalog.current_schema()
       OR p_expected_row_revision < 1 OR p_now IS NULL
       OR NOT system_resource_layout_definition_valid_v2(p_definition_json)
       OR pg_catalog.octet_length(p_definition_sha256) <> 32
       OR p_definition_sha256 IS DISTINCT FROM pg_catalog.sha256(
            pg_catalog.convert_to(p_definition_json, 'UTF8')
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
            CONSTRAINT = 'system_resource_layout_update_v2_contract_guard',
            MESSAGE = 'system resource layout v2 update contract is invalid';
    END IF;
    SELECT revision.state, revision.row_revision,
           revision.definition_json::jsonb ->> 'contract'
    INTO v_state, v_row_revision, v_contract
    FROM system_resource_layout_revisions AS revision
    WHERE revision.id = p_revision_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002',
            MESSAGE = 'system resource layout revision was not found';
    END IF;
    IF v_state IS DISTINCT FROM 'draft'
       OR v_row_revision IS DISTINCT FROM p_expected_row_revision
       OR v_contract IS DISTINCT FROM 'harpy/system-resource-layout/v2' THEN
        RAISE EXCEPTION USING ERRCODE = '40001',
            MESSAGE = 'system resource layout revision conflicts';
    END IF;
    UPDATE system_resource_layout_revisions
    SET definition_json = p_definition_json,
        definition_sha256 = p_definition_sha256,
        updated_at = p_now,
        row_revision = row_revision + 1
    WHERE id = p_revision_id;
    RETURN system_resource_layout_revision_json_v1(p_revision_id);
END;
$$;


ALTER FUNCTION __tenant_schema__.system_resource_layout_update_v2(p_scope_schema name, p_revision_id uuid, p_expected_row_revision bigint, p_definition_json text, p_definition_sha256 bytea, p_now timestamp with time zone) OWNER TO harpy_owner;

