--
-- Name: work_guard_board_column_limit_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_guard_board_column_limit_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE total bigint;
BEGIN
    PERFORM 1 FROM work_boards WHERE id = NEW.board_id FOR UPDATE;
    SELECT count(*) INTO total FROM work_board_columns WHERE board_id = NEW.board_id;
    IF total >= 100 THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'WORK_BOARD_LIMIT_EXCEEDED';
    END IF;
    RETURN NEW;
END;
$$;


