--
-- Name: work_guard_comment_mutation_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_guard_comment_mutation_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'WORK_COMMENT_IMMUTABLE';
    END IF;
    IF OLD.state <> 'VISIBLE' OR NEW.state <> 'REDACTED'
       OR NEW.body <> '' OR NEW.redaction_kind IS NULL OR NEW.redacted_by IS NULL
       OR NEW.redacted_at IS NULL OR NEW.row_version <> OLD.row_version + 1
       OR (NEW.id, NEW.board_id, NEW.task_id, NEW.author_id, NEW.created_at)
          IS DISTINCT FROM
          (OLD.id, OLD.board_id, OLD.task_id, OLD.author_id, OLD.created_at) THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'WORK_COMMENT_IMMUTABLE';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_guard_comment_mutation_v1() OWNER TO harpy_owner;

--
-- Name: work_guard_last_user_admin_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_guard_last_user_admin_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE remaining bigint;
BEGIN
    IF OLD.active AND OLD.principal_kind = 'USER' AND OLD.board_role = 'ADMIN'
       AND (TG_OP = 'DELETE' OR NOT NEW.active OR NEW.principal_kind <> 'USER'
            OR NEW.board_role <> 'ADMIN') THEN
        PERFORM 1 FROM work_boards WHERE id = OLD.board_id FOR UPDATE;
        SELECT count(*) INTO remaining FROM work_board_memberships
         WHERE board_id = OLD.board_id AND active AND principal_kind = 'USER'
           AND board_role = 'ADMIN' AND id <> OLD.id;
        IF remaining = 0 THEN
            RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'WORK_LAST_USER_ADMIN';
        END IF;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_guard_last_user_admin_v1() OWNER TO harpy_owner;

