--
-- Name: work_guard_task_board_limit_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_guard_task_board_limit_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE column_board uuid; column_total bigint; board_total bigint;
BEGIN
    PERFORM 1 FROM work_boards WHERE id = NEW.board_id FOR UPDATE;
    SELECT board_id INTO column_board FROM work_board_columns
        WHERE id = NEW.column_id FOR UPDATE;
    IF column_board IS DISTINCT FROM NEW.board_id THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'WORK_CROSS_BOARD_REFERENCE';
    END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT count(*) INTO column_total FROM work_tasks
            WHERE column_id = NEW.column_id AND deleted_at IS NULL;
        SELECT count(*) INTO board_total FROM work_tasks
            WHERE board_id = NEW.board_id AND deleted_at IS NULL;
    ELSE
        IF OLD.column_id IS DISTINCT FROM NEW.column_id THEN
            SELECT count(*) INTO column_total FROM work_tasks
                WHERE column_id = NEW.column_id AND deleted_at IS NULL;
        END IF;
        IF OLD.board_id IS DISTINCT FROM NEW.board_id THEN
            SELECT count(*) INTO board_total FROM work_tasks
                WHERE board_id = NEW.board_id AND deleted_at IS NULL;
        END IF;
    END IF;
    IF column_total >= 10000 OR board_total >= 50000 THEN
        RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'WORK_BOARD_LIMIT_EXCEEDED';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_guard_task_board_limit_v1() OWNER TO harpy_owner;

--
-- Name: work_projection_principals_valid_v1(text[], boolean); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_projection_principals_valid_v1(p_principals text[], p_visible boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
BEGIN
    RETURN p_principals IS NOT NULL
       AND pg_catalog.cardinality(p_principals) <= 100
       AND (NOT p_visible OR pg_catalog.cardinality(p_principals) BETWEEN 1 AND 100)
       AND pg_catalog.array_position(p_principals, NULL) IS NULL
       AND NOT EXISTS (SELECT 1 FROM pg_catalog.unnest(p_principals) AS principal(value)
           WHERE principal.value !~ '^(USER|ROLE|ORGANIZATION):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
       AND pg_catalog.cardinality(p_principals) =
           (SELECT pg_catalog.count(DISTINCT principal.value)
            FROM pg_catalog.unnest(p_principals) AS principal(value));
END;
$_$;


ALTER FUNCTION __tenant_schema__.work_projection_principals_valid_v1(p_principals text[], p_visible boolean) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_apply_and_record_v1(uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb, bytea, text, bigint, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_contract_id text;
    v_procedure_oid bigint;
    v_procedure_signature text;
    v_expected_signature text;
    v_already_applied boolean;
    v_applied_count bigint;
    v_key_sha text;
    v_state_sha text;
    v_projected_sha text;
    v_asserted boolean;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Work V1 adoption composite principal denied';
    END IF;
    v_batch := work_v1_adoption_batch_decode_v1(
        p_change_batch_bytes, p_batch_sha256, p_batch_bytes
    );
    v_asserted := work_v1_adoption_batch_assert_v1(
        v_batch, p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_snapshot_name,
        p_snapshot_lsn, p_received_lsn, p_commit_lsn, p_final_lsn,
        p_source_xid, p_batch_ordinal, p_checkpoint_state, p_last_key
    );
    IF NOT v_asserted THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'Work V1 adoption batch assertion failed';
    END IF;
    SELECT prepared.procedure_contract_id, prepared.procedure_oid,
        prepared.procedure_signature, prepared.already_applied,
        prepared.applied_count, prepared.key_state_sha256,
        prepared.state_sha256
    INTO STRICT v_contract_id, v_procedure_oid, v_procedure_signature,
        v_already_applied, v_applied_count, v_key_sha, v_state_sha
    FROM platform.cutover_prepare_batch_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_batch_ordinal,
        p_commit_lsn, p_source_xid, p_batch_sha256,
        p_lease_manifest_sha256
    ) AS prepared;
    v_expected_signature := pg_catalog.format(
        '%I.work_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)',
        pg_catalog.current_schema()
    );
    IF v_contract_id IS DISTINCT FROM 'work.v1_adoption.v1' OR
       v_procedure_oid IS DISTINCT FROM
           'work_v1_adoption_apply_v1(uuid,uuid,text,uuid,smallint,text,pg_lsn,pg_lsn,pg_lsn,xid8,integer,jsonb,text)'::regprocedure::oid OR
       v_procedure_signature IS DISTINCT FROM v_expected_signature THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 adoption procedure binding differs';
    END IF;
    IF v_already_applied THEN
        RETURN QUERY SELECT v_applied_count, v_key_sha, v_state_sha;
        RETURN;
    END IF;
    SELECT result.applied_count, result.key_state_sha256,
        result.state_sha256
    INTO STRICT v_applied_count, v_key_sha, v_state_sha
    FROM work_v1_adoption_apply_v1(
        p_operation_id, p_run_id, p_scope_kind, p_scope_id,
        p_relation_ordinal, p_checkpoint_key, p_snapshot_lsn,
        p_received_lsn, p_commit_lsn, p_source_xid, p_batch_ordinal,
        v_batch, p_batch_sha256
    ) AS result;
    IF v_applied_count < 0 OR v_key_sha !~ '^[0-9a-f]{64}$' OR
       v_state_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '22000',
            MESSAGE = 'Work V1 adoption owner result is invalid';
    END IF;
    PERFORM platform.cutover_record_batch_v1(
        p_operation_id, p_run_id, p_relation_ordinal, p_checkpoint_key,
        p_snapshot_name, p_snapshot_lsn, p_received_lsn, p_commit_lsn,
        p_final_lsn, p_source_xid, p_batch_ordinal, p_checkpoint_state,
        p_last_key, p_batch_sha256, p_batch_bytes, v_applied_count,
        v_key_sha, v_state_sha
    );
    IF p_checkpoint_state='complete' AND NOT EXISTS (
        SELECT 1
        FROM platform.cutover_operation_checkpoint_keys AS expected
        LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint
          ON checkpoint.operation_id=expected.operation_id
         AND checkpoint.run_id=expected.run_id
         AND checkpoint.relation_ordinal=expected.relation_ordinal
         AND checkpoint.checkpoint_key=expected.checkpoint_key
         AND checkpoint.state='complete'
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
          AND checkpoint.operation_id IS NULL
    ) THEN
        v_projected_sha := work_v1_adoption_project_v1(
            p_operation_id, p_run_id, p_scope_id
        );
        IF v_projected_sha IS DISTINCT FROM v_state_sha THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'Work V1 adoption projected digest differs';
        END IF;
    END IF;
    RETURN QUERY SELECT v_applied_count, v_key_sha, v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_apply_and_record_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb, p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint, p_lease_manifest_sha256 text) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_apply_v1(uuid, uuid, text, uuid, smallint, text, pg_lsn, pg_lsn, pg_lsn, xid8, integer, jsonb, text); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) RETURNS TABLE(applied_count bigint, key_state_sha256 text, state_sha256 text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_change jsonb;
    v_payload jsonb;
    v_generation bigint;
    v_manifest text;
    v_lease_manifest text;
    v_rows bigint;
    v_applied bigint;
    v_key_sha text;
    v_state_sha text;
    v_now timestamptz := pg_catalog.clock_timestamp();
BEGIN
    v_applied := 0;
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       p_scope_kind IS DISTINCT FROM 'tenant' OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Work V1 adoption apply principal denied';
    END IF;
    SELECT operation.cutover_generation, operation.transform_manifest_sha256,
        operation.lease_manifest_sha256
    INTO STRICT v_generation, v_manifest, v_lease_manifest
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id = p_operation_id AND operation.run_id = p_run_id
      AND operation.scope_kind = p_scope_kind AND operation.scope_id = p_scope_id
      AND operation.group_id = 'work' AND operation.domain = 'work'
      AND operation.state IN ('planned','copying','shadow','quiescing')
    FOR SHARE;
    INSERT INTO work_adoption_runs (
        run_id, cutover_generation, manifest_sha256, transform_version, state,
        source_count, target_count, created_at, updated_at
    ) VALUES (
        p_run_id, v_generation, pg_catalog.decode(v_manifest, 'hex'),
        'work_adoption_v1', 'COPYING', 0, 0, v_now, v_now
    )
    ON CONFLICT (run_id) DO UPDATE SET updated_at = EXCLUDED.updated_at
    WHERE work_adoption_runs.cutover_generation = EXCLUDED.cutover_generation
      AND work_adoption_runs.manifest_sha256 = EXCLUDED.manifest_sha256
      AND work_adoption_runs.transform_version = EXCLUDED.transform_version
      AND work_adoption_runs.state IN ('INVENTORY','COPYING','RECONCILING');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 adoption run binding differs';
    END IF;
    FOR v_change IN
        SELECT value FROM pg_catalog.jsonb_array_elements(p_change_batch->'changes')
            WITH ORDINALITY AS item(value, position)
        ORDER BY position
    LOOP
        v_payload := CASE v_change->>'kind'
            WHEN 'delete' THEN v_change->'before' ELSE v_change->'after'
        END;
        INSERT INTO work_v1_adoption_stage (
            operation_id, run_id, source_kind, source_id, target_kind, target_id,
            source_sha256, target_sha256, target_record, removed, source_xid,
            commit_lsn, batch_ordinal, change_ordinal, updated_at
        ) VALUES (
            p_operation_id, p_run_id, v_payload->>'source_kind',
            (v_payload->>'source_id')::uuid, v_payload->>'target_kind',
            (v_payload->>'target_id')::uuid,
            pg_catalog.decode(v_payload->>'source_sha256', 'hex'),
            pg_catalog.sha256(pg_catalog.convert_to(
                (v_payload->'target_record')::text, 'UTF8'
            )),
            v_payload->'target_record', v_change->>'kind' = 'delete',
            p_source_xid, p_commit_lsn, p_batch_ordinal,
            (v_change->>'ordinal')::integer, v_now
        )
        ON CONFLICT (operation_id, run_id, target_kind, target_id) DO UPDATE
        SET source_kind = EXCLUDED.source_kind, source_id = EXCLUDED.source_id,
            source_sha256 = EXCLUDED.source_sha256,
            target_sha256 = EXCLUDED.target_sha256,
            target_record = EXCLUDED.target_record, removed = EXCLUDED.removed,
            source_xid = EXCLUDED.source_xid, commit_lsn = EXCLUDED.commit_lsn,
            batch_ordinal = EXCLUDED.batch_ordinal,
            change_ordinal = EXCLUDED.change_ordinal, updated_at = EXCLUDED.updated_at
        WHERE (work_v1_adoption_stage.batch_ordinal,
               work_v1_adoption_stage.change_ordinal)
            < (EXCLUDED.batch_ordinal, EXCLUDED.change_ordinal);
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows IS DISTINCT FROM 1::bigint THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'Work V1 adoption target checkpoint regressed';
        END IF;
        v_applied := v_applied + 1;
        INSERT INTO platform.applied_change_receipts (
            receipt_id, operation_id, run_id, manifest_sha256, source_xid,
            source_commit_lsn, relation_ordinal, change_ordinal, checkpoint_key,
            mutation_kind, mutation_sha256, applied_at
        ) VALUES (
            pg_catalog.gen_random_uuid(), p_operation_id, p_run_id,
            v_lease_manifest, p_source_xid, p_commit_lsn, p_relation_ordinal,
            (((p_batch_ordinal - 1)::bigint * 1000) + v_applied)::integer,
            p_checkpoint_key, v_change->>'kind',
            pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
                p_batch_sha256 || ':' || v_applied::text, 'UTF8'
            )), 'hex'), v_now
        );
    END LOOP;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(
            stage.target_kind || ':' || stage.target_id::text || ':' ||
            pg_catalog.encode(stage.target_sha256, 'hex'),
            ',' ORDER BY stage.target_kind, stage.target_id
        ), ''), 'UTF8'
    )), 'hex')
    INTO v_key_sha
    FROM work_v1_adoption_stage AS stage
    WHERE stage.operation_id = p_operation_id AND stage.run_id = p_run_id
      AND stage.source_kind = p_checkpoint_key AND NOT stage.removed;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(
            stage.target_kind || ':' || stage.target_id::text || ':' ||
            pg_catalog.encode(stage.target_sha256, 'hex'),
            ',' ORDER BY stage.target_kind, stage.target_id
        ), ''), 'UTF8'
    )), 'hex')
    INTO v_state_sha
    FROM work_v1_adoption_stage AS stage
    WHERE stage.operation_id = p_operation_id AND stage.run_id = p_run_id
      AND NOT stage.removed;
    RETURN QUERY SELECT v_applied, v_key_sha, v_state_sha;
END;
$_$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_apply_v1(p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_change_batch jsonb, p_batch_sha256 text) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_batch_assert_v1(jsonb, uuid, uuid, text, uuid, smallint, text, text, pg_lsn, pg_lsn, pg_lsn, pg_lsn, xid8, integer, text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_count integer;
BEGIN
    v_count := pg_catalog.jsonb_array_length(p_batch->'changes');
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Work V1 adoption evidence principal denied';
    END IF;
    IF p_scope_kind IS DISTINCT FROM 'tenant' OR p_scope_id IS NULL OR
       p_relation_ordinal NOT BETWEEN 1 AND 32767 OR
       p_checkpoint_key NOT IN (
           'task_boards','task_board_columns','board_members','board_tasks',
           'board_task_comments','calendar_events'
       ) OR p_batch_ordinal NOT BETWEEN 1 AND 2147483 OR
       p_checkpoint_state NOT IN ('initial_copy','delta','complete') OR
       (p_checkpoint_state = 'complete') IS DISTINCT FROM (p_final_lsn IS NOT NULL) OR
       (v_count = 0 AND (
           p_checkpoint_state <> 'complete' OR
           p_final_lsn IS DISTINCT FROM p_commit_lsn
       )) OR
       NOT EXISTS (
           SELECT 1 FROM tenancy_schema_identity AS identity
           WHERE identity.singleton AND identity.tenant_id = p_scope_id
       ) OR NOT EXISTS (
           SELECT 1 FROM platform.cutover_operations AS operation
           WHERE operation.operation_id = p_operation_id
             AND operation.run_id = p_run_id
             AND operation.scope_kind = p_scope_kind
             AND operation.scope_id = p_scope_id
             AND operation.group_id = 'work' AND operation.domain = 'work'
             AND operation.state IN ('planned','copying','shadow','quiescing')
       ) OR (p_batch->>'operation_id')::uuid IS DISTINCT FROM p_operation_id OR
       (p_batch->>'run_id')::uuid IS DISTINCT FROM p_run_id OR
       p_batch->>'scope_kind' IS DISTINCT FROM p_scope_kind OR
       (p_batch->>'scope_id')::uuid IS DISTINCT FROM p_scope_id OR
       (p_batch->>'relation_ordinal')::smallint IS DISTINCT FROM p_relation_ordinal OR
       p_batch->>'checkpoint_key' IS DISTINCT FROM p_checkpoint_key OR
       p_batch->>'checkpoint_state' IS DISTINCT FROM p_checkpoint_state OR
       p_batch->'last_key' IS DISTINCT FROM p_last_key OR
       p_batch->'source_position'->>'snapshot_name' IS DISTINCT FROM p_snapshot_name OR
       (p_batch->'source_position'->>'snapshot_lsn')::pg_lsn
           IS DISTINCT FROM p_snapshot_lsn OR
       (p_batch->'source_position'->>'received_lsn')::pg_lsn
           IS DISTINCT FROM p_received_lsn OR
       (p_batch->'source_position'->>'commit_lsn')::pg_lsn
           IS DISTINCT FROM p_commit_lsn OR
       (p_batch->'source_position'->>'final_lsn')::pg_lsn
           IS DISTINCT FROM p_final_lsn OR
       (p_batch->'source_position'->>'source_xid')::xid8
           IS DISTINCT FROM p_source_xid OR
       (p_batch->'source_position'->>'batch_ordinal')::integer
           IS DISTINCT FROM p_batch_ordinal OR EXISTS (
           SELECT 1 FROM pg_catalog.jsonb_array_elements(p_batch->'changes') AS change
           WHERE COALESCE(
               change->'after'->>'source_kind',
               change->'before'->>'source_kind'
           ) IS DISTINCT FROM p_checkpoint_key
       ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Work V1 adoption batch evidence differs';
    END IF;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_batch_assert_v1(p_batch jsonb, p_operation_id uuid, p_run_id uuid, p_scope_kind text, p_scope_id uuid, p_relation_ordinal smallint, p_checkpoint_key text, p_snapshot_name text, p_snapshot_lsn pg_lsn, p_received_lsn pg_lsn, p_commit_lsn pg_lsn, p_final_lsn pg_lsn, p_source_xid xid8, p_batch_ordinal integer, p_checkpoint_state text, p_last_key jsonb) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_batch_decode_v1(bytea, text, bigint); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_batch jsonb;
    v_actual_bytes bigint;
    v_change_count integer;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Work V1 adoption batch principal denied';
    END IF;
    v_actual_bytes := pg_catalog.octet_length(p_change_batch_bytes);
    IF p_batch_bytes IS DISTINCT FROM v_actual_bytes OR
       v_actual_bytes NOT BETWEEN 2 AND 8388608 OR
       p_batch_sha256 !~ '^[0-9a-f]{64}$' OR
       pg_catalog.encode(pg_catalog.sha256(p_change_batch_bytes), 'hex')
           IS DISTINCT FROM p_batch_sha256 THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Work V1 adoption batch digest is invalid';
    END IF;
    v_batch := pg_catalog.convert_from(p_change_batch_bytes, 'UTF8')::jsonb;
    IF pg_catalog.jsonb_typeof(v_batch) IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch) AS key)
       IS DISTINCT FROM ARRAY[
           'changes','checkpoint_key','checkpoint_state','last_key',
           'operation_id','relation_ordinal','run_id','scope_id',
           'scope_kind','source_position'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'source_position') IS DISTINCT FROM 'object' OR
       (SELECT pg_catalog.array_agg(key ORDER BY key)
        FROM pg_catalog.jsonb_object_keys(v_batch->'source_position') AS key)
       IS DISTINCT FROM ARRAY[
           'batch_ordinal','commit_lsn','final_lsn','received_lsn',
           'snapshot_lsn','snapshot_name','source_xid'
       ]::text[] OR
       pg_catalog.jsonb_typeof(v_batch->'changes') IS DISTINCT FROM 'array' OR
       pg_catalog.jsonb_array_length(v_batch->'changes') > 1000 OR
       pg_catalog.jsonb_typeof(v_batch->'last_key') NOT IN ('object','null') OR
       v_batch->'last_key' = '{}'::jsonb THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Work V1 adoption batch envelope is invalid';
    END IF;
    v_change_count := pg_catalog.jsonb_array_length(v_batch->'changes');
    IF (SELECT pg_catalog.count(DISTINCT change.value->'key')
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes') AS change(value))
       IS DISTINCT FROM v_change_count::bigint OR EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_batch->'changes')
             WITH ORDINALITY AS change(value, position)
        WHERE pg_catalog.jsonb_typeof(change.value) IS DISTINCT FROM 'object'
           OR (SELECT pg_catalog.array_agg(key ORDER BY key)
               FROM pg_catalog.jsonb_object_keys(change.value) AS key)
              IS DISTINCT FROM ARRAY['after','before','key','kind','ordinal']::text[]
           OR (change.value->>'ordinal')::integer IS DISTINCT FROM change.position::integer
           OR change.value->>'kind' NOT IN ('insert','update','delete')
           OR (change.value->>'kind' = 'insert' AND (
                  change.value->'before' <> 'null'::jsonb OR
                  NOT work_v1_adoption_value_valid_v1(
                      change.value->'key', change.value->'after'
                  )))
           OR (change.value->>'kind' = 'update' AND (
                  NOT work_v1_adoption_value_valid_v1(
                      change.value->'key', change.value->'before'
                  ) OR NOT work_v1_adoption_value_valid_v1(
                      change.value->'key', change.value->'after'
                  )))
           OR (change.value->>'kind' = 'delete' AND (
                  change.value->'after' <> 'null'::jsonb OR
                  NOT work_v1_adoption_value_valid_v1(
                      change.value->'key', change.value->'before'
                  )))
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Work V1 adoption batch change is invalid';
    END IF;
    RETURN v_batch;
END;
$_$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_batch_decode_v1(p_change_batch_bytes bytea, p_batch_sha256 text, p_batch_bytes bigint) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_document_valid_v1(text, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_document_valid_v1(p_target_kind text, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_keys text; v_expected text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR pg_catalog.jsonb_typeof(p_record) IS DISTINCT FROM 'object' OR p_record='{}'::jsonb THEN RETURN false; END IF;
    SELECT pg_catalog.string_agg(key,',' ORDER BY key) INTO v_keys
      FROM pg_catalog.jsonb_object_keys(p_record) AS key;
    v_expected := CASE p_target_kind
      WHEN 'BOARD' THEN 'ArchivedAt,CreatedAt,CreatorID,Description,Lifecycle,Name,UpdatedAt'
      WHEN 'COLUMN' THEN 'BoardID,CreatedAt,Name,Position,Status,UpdatedAt'
      WHEN 'MEMBERSHIP' THEN 'BoardID,CreatedAt,PrincipalID,PrincipalKind,Role,UpdatedAt'
      WHEN 'TASK' THEN 'BoardID,CancelledAt,ColumnID,CompletedAt,CreatedAt,CreatorID,DeletedAt,Description,DueAt,FormFilter,IsRecurring,Kind,Position,Priority,RecurrenceEnd,RecurrenceRule,StartsAt,Status,Title,UpdatedAt'
      WHEN 'ASSIGNEE' THEN 'PrincipalID,PrincipalKind,TaskID' WHEN 'LABEL' THEN 'BoardID,Color,Name'
      WHEN 'TASK_LABEL' THEN 'LabelID,TaskID' WHEN 'CHECKLIST' THEN 'Completed,Position,TaskID,Text'
      WHEN 'COMMENT' THEN 'AuthorID,BoardID,Body,CreatedAt,RedactedAt,RedactedBy,RedactionKind,RedactionReason,State,TaskID'
      WHEN 'CALENDAR' THEN 'Audience,BoardID,CreatedAt,DeletedAt,Description,EndDate,EndsAt,OrganizationID,OwnerID,StartDate,StartsAt,Timezone,Title,UpdatedAt'
      WHEN 'RECURRENCE' THEN 'DTStart,EventID,HorizonEnd,RRULE,TZDBVersion,Timezone'
      WHEN 'FORM_LINK' THEN 'FormID,PermissionRevision,ReferenceEpoch,ResourceID,ResourceKind,VersionID'
      WHEN 'WORKFLOW_PROJECTION' THEN 'DueAt,PermissionRevision,Revision,SourceID,Summary,VersionID,VisibleToPrincipals'
      ELSE NULL END;
    IF v_keys IS DISTINCT FROM v_expected THEN RETURN false; END IF;
    IF p_target_kind = 'TASK' THEN
        RETURN pg_catalog.jsonb_typeof(p_record->'IsRecurring') = 'boolean'
           AND pg_catalog.jsonb_typeof(p_record->'RecurrenceRule') = 'string'
           AND pg_catalog.jsonb_typeof(p_record->'RecurrenceEnd') IN ('string','null')
           AND pg_catalog.char_length(p_record->>'RecurrenceRule') <= 50
           AND pg_catalog.octet_length((p_record->'FormFilter')::text) <= 128000;
    END IF;
    IF p_target_kind IS DISTINCT FROM 'WORKFLOW_PROJECTION' THEN RETURN true; END IF;
    IF pg_catalog.jsonb_typeof(p_record->'VisibleToPrincipals') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
    RETURN work_projection_principals_valid_v1(ARRAY(SELECT value
      FROM pg_catalog.jsonb_array_elements_text(p_record->'VisibleToPrincipals') AS principal(value)
      ORDER BY value),true);
EXCEPTION WHEN invalid_parameter_value OR data_exception THEN RETURN false;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_document_valid_v1(p_target_kind text, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_inbox_visibility_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_inbox_visibility_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_matches bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR CURRENT_USER IS DISTINCT FROM 'harpy_owner'
       OR NEW.source_owner IS DISTINCT FROM 'WORKFLOW' THEN RETURN NEW; END IF;
    SELECT pg_catalog.array_agg(principal.value ORDER BY principal.value),
           pg_catalog.count(DISTINCT stage.run_id) INTO NEW.visible_to_principals,v_matches
      FROM work_v1_adoption_stage AS stage JOIN work_adoption_runs AS run ON run.run_id=stage.run_id
      CROSS JOIN pg_catalog.jsonb_array_elements_text(stage.target_record->'VisibleToPrincipals') AS principal(value)
     WHERE stage.target_kind='WORKFLOW_PROJECTION' AND stage.target_id=NEW.id AND NOT stage.removed
       AND run.state IN ('COPYING','RECONCILING') AND stage.target_record->>'SourceID'=NEW.source_id::text
       AND stage.target_record->>'VersionID'=NEW.source_version_id::text
       AND (stage.target_record->>'Revision')::bigint=NEW.source_revision
       AND (stage.target_record->>'PermissionRevision')::bigint=NEW.permission_revision
       AND stage.target_record->>'Summary'=NEW.summary
       AND (stage.target_record->>'DueAt')::timestamptz IS NOT DISTINCT FROM NEW.due_at;
    IF v_matches IS DISTINCT FROM 1::bigint OR NOT work_projection_principals_valid_v1(NEW.visible_to_principals,true) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Work V1 workflow projection visibility denied'; END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_inbox_visibility_v1() OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_project_board_v1(text, uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_project_board_v1(p_target_kind text, p_target_id uuid, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       NOT work_v1_adoption_document_valid_v1(p_target_kind, p_record) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Work V1 board projection denied';
    END IF;
    CASE p_target_kind
    WHEN 'BOARD' THEN
        INSERT INTO work_boards (
            id, creator_user_id, name, description, lifecycle_state,
            reference_epoch, row_version, created_at, updated_at, archived_at
        ) VALUES (
            p_target_id, (p_record->>'CreatorID')::uuid, p_record->>'Name',
            p_record->>'Description', p_record->>'Lifecycle', 1, 1,
            (p_record->>'CreatedAt')::timestamptz,
            (p_record->>'UpdatedAt')::timestamptz,
            (p_record->>'ArchivedAt')::timestamptz
        )
        ON CONFLICT (id) DO UPDATE SET
            creator_user_id=EXCLUDED.creator_user_id, name=EXCLUDED.name,
            description=EXCLUDED.description,
            lifecycle_state=EXCLUDED.lifecycle_state,
            created_at=EXCLUDED.created_at, updated_at=EXCLUDED.updated_at,
            archived_at=EXCLUDED.archived_at;
    WHEN 'COLUMN' THEN
        INSERT INTO work_board_columns (
            id, board_id, name, status_category, position, row_version,
            created_at, updated_at
        ) VALUES (
            p_target_id, (p_record->>'BoardID')::uuid, p_record->>'Name',
            p_record->>'Status', (p_record->>'Position')::bigint, 1,
            (p_record->>'CreatedAt')::timestamptz,
            (p_record->>'UpdatedAt')::timestamptz
        )
        ON CONFLICT (id) DO UPDATE SET
            board_id=EXCLUDED.board_id, name=EXCLUDED.name,
            status_category=EXCLUDED.status_category, position=EXCLUDED.position,
            created_at=EXCLUDED.created_at, updated_at=EXCLUDED.updated_at;
    WHEN 'MEMBERSHIP' THEN
        INSERT INTO work_board_memberships (
            id, board_id, principal_kind, principal_id, board_role, active,
            row_version, created_at, updated_at, deactivated_at
        ) VALUES (
            p_target_id, (p_record->>'BoardID')::uuid,
            p_record->>'PrincipalKind', (p_record->>'PrincipalID')::uuid,
            p_record->>'Role', true, 1,
            (p_record->>'CreatedAt')::timestamptz,
            (p_record->>'UpdatedAt')::timestamptz, NULL
        )
        ON CONFLICT (id) DO UPDATE SET
            board_id=EXCLUDED.board_id,
            principal_kind=EXCLUDED.principal_kind,
            principal_id=EXCLUDED.principal_id,
            board_role=EXCLUDED.board_role, active=true,
            created_at=EXCLUDED.created_at, updated_at=EXCLUDED.updated_at,
            deactivated_at=NULL;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Work V1 board projection kind is invalid';
    END CASE;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_project_board_v1(p_target_kind text, p_target_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_project_collaboration_v1(text, uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_project_collaboration_v1(p_target_kind text, p_target_id uuid, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       NOT work_v1_adoption_document_valid_v1(p_target_kind, p_record) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Work V1 collaboration projection denied';
    END IF;
    CASE p_target_kind
    WHEN 'COMMENT' THEN
        INSERT INTO work_comments (
            id, board_id, task_id, author_id, body, state, redaction_kind,
            redacted_by, redaction_reason, row_version, created_at, redacted_at
        ) VALUES (
            p_target_id, (p_record->>'BoardID')::uuid,
            (p_record->>'TaskID')::uuid, (p_record->>'AuthorID')::uuid,
            p_record->>'Body', p_record->>'State',
            NULLIF(p_record->>'RedactionKind',''),
            NULLIF(p_record->>'RedactedBy','')::uuid,
            NULLIF(p_record->>'RedactionReason',''), 1,
            (p_record->>'CreatedAt')::timestamptz,
            (p_record->>'RedactedAt')::timestamptz
        );
    WHEN 'CALENDAR' THEN
        INSERT INTO work_calendar_events (
            id, owner_id, audience, board_id, organization_id, title,
            description, starts_at, ends_at, start_date, end_date,
            timezone_name, generated, edited, live_reference_count, legal_hold,
            row_version, deleted_at, created_at, updated_at
        ) VALUES (
            p_target_id, (p_record->>'OwnerID')::uuid, p_record->>'Audience',
            NULLIF(p_record->>'BoardID','')::uuid,
            NULLIF(p_record->>'OrganizationID','')::uuid,
            p_record->>'Title', p_record->>'Description',
            (p_record->>'StartsAt')::timestamptz,
            (p_record->>'EndsAt')::timestamptz,
            NULLIF(p_record->>'StartDate','')::date,
            NULLIF(p_record->>'EndDate','')::date,
            p_record->>'Timezone', false, false, 0, false, 1,
            (p_record->>'DeletedAt')::timestamptz,
            (p_record->>'CreatedAt')::timestamptz,
            (p_record->>'UpdatedAt')::timestamptz
        )
        ON CONFLICT (id) DO UPDATE SET
            owner_id=EXCLUDED.owner_id, audience=EXCLUDED.audience,
            board_id=EXCLUDED.board_id,
            organization_id=EXCLUDED.organization_id, title=EXCLUDED.title,
            description=EXCLUDED.description, starts_at=EXCLUDED.starts_at,
            ends_at=EXCLUDED.ends_at, start_date=EXCLUDED.start_date,
            end_date=EXCLUDED.end_date, timezone_name=EXCLUDED.timezone_name,
            deleted_at=EXCLUDED.deleted_at, created_at=EXCLUDED.created_at,
            updated_at=EXCLUDED.updated_at;
    WHEN 'RECURRENCE' THEN
        INSERT INTO work_recurrence_rules (
            id, owner_event_id, current_revision, lifecycle_state, row_version,
            created_at, updated_at
        ) VALUES (
            p_target_id, (p_record->>'EventID')::uuid, 1, 'ACTIVE', 1,
            transaction_timestamp(), transaction_timestamp()
        )
        ON CONFLICT (id) DO UPDATE SET
            owner_event_id=EXCLUDED.owner_event_id, current_revision=1,
            lifecycle_state='ACTIVE', updated_at=EXCLUDED.updated_at;
        INSERT INTO work_recurrence_rule_revisions (
            rule_id, revision, contract_version, dtstart, timezone_name,
            tzdb_version, rrule, exdates, effective_from, created_at
        ) VALUES (
            p_target_id, 1, 'work_rrule_v1', p_record->>'DTStart',
            p_record->>'Timezone', p_record->>'TZDBVersion',
            p_record->>'RRULE', ARRAY[]::text[],
            pg_catalog.to_timestamp(
                p_record->>'DTStart', 'YYYYMMDD"T"HH24MISS'
            ), transaction_timestamp()
        )
        ON CONFLICT (rule_id, revision) DO NOTHING;
        IF NOT EXISTS (
            SELECT 1 FROM work_recurrence_rule_revisions AS revision
            WHERE revision.rule_id=p_target_id AND revision.revision=1
              AND revision.dtstart=p_record->>'DTStart'
              AND revision.timezone_name=p_record->>'Timezone'
              AND revision.tzdb_version=p_record->>'TZDBVersion'
              AND revision.rrule=p_record->>'RRULE'
        ) THEN
            RAISE EXCEPTION USING ERRCODE = '55000',
                MESSAGE = 'Work V1 recurrence projection differs';
        END IF;
    WHEN 'WORKFLOW_PROJECTION' THEN
        INSERT INTO work_inbox_items (
            id, source_owner, source_kind, source_id, source_version_id,
            source_revision, permission_revision, event_sequence, summary,
            due_at, state, updated_at
        ) VALUES (
            p_target_id, 'WORKFLOW', 'HUMAN_TASK',
            (p_record->>'SourceID')::uuid, (p_record->>'VersionID')::uuid,
            (p_record->>'Revision')::bigint,
            (p_record->>'PermissionRevision')::bigint,
            (p_record->>'Revision')::bigint, p_record->>'Summary',
            (p_record->>'DueAt')::timestamptz,
            'VISIBLE', transaction_timestamp()
        )
        ON CONFLICT (id) DO UPDATE SET
            source_version_id=EXCLUDED.source_version_id,
            source_revision=EXCLUDED.source_revision,
            permission_revision=EXCLUDED.permission_revision,
            event_sequence=EXCLUDED.event_sequence,
            summary=EXCLUDED.summary, due_at=EXCLUDED.due_at,
            state='VISIBLE', updated_at=EXCLUDED.updated_at;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Work V1 collaboration projection kind is invalid';
    END CASE;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_project_collaboration_v1(p_target_kind text, p_target_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_project_task_v1(text, uuid, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_project_task_v1(p_target_kind text, p_target_id uuid, p_record jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       NOT work_v1_adoption_document_valid_v1(p_target_kind, p_record) THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Work V1 task projection denied';
    END IF;
    CASE p_target_kind
    WHEN 'TASK' THEN
        INSERT INTO work_tasks (
            id, board_id, column_id, task_kind, status_category, title,
            description, position, row_version, due_at, completed_at,
            cancelled_at, deleted_at, created_at, updated_at
        ) VALUES (
            p_target_id, (p_record->>'BoardID')::uuid,
            (p_record->>'ColumnID')::uuid, p_record->>'Kind',
            p_record->>'Status', p_record->>'Title', p_record->>'Description',
            (p_record->>'Position')::bigint, 1,
            (p_record->>'DueAt')::timestamptz,
            (p_record->>'CompletedAt')::timestamptz,
            (p_record->>'CancelledAt')::timestamptz,
            (p_record->>'DeletedAt')::timestamptz,
            (p_record->>'CreatedAt')::timestamptz,
            (p_record->>'UpdatedAt')::timestamptz
        )
        ON CONFLICT (id) DO UPDATE SET
            board_id=EXCLUDED.board_id, column_id=EXCLUDED.column_id,
            task_kind=EXCLUDED.task_kind,
            status_category=EXCLUDED.status_category, title=EXCLUDED.title,
            description=EXCLUDED.description, position=EXCLUDED.position,
            due_at=EXCLUDED.due_at, completed_at=EXCLUDED.completed_at,
            cancelled_at=EXCLUDED.cancelled_at, deleted_at=EXCLUDED.deleted_at,
            created_at=EXCLUDED.created_at, updated_at=EXCLUDED.updated_at;
    WHEN 'ASSIGNEE' THEN
        INSERT INTO work_task_assignees (
            task_id, principal_kind, principal_id, active, removed_at,
            created_at, updated_at
        ) VALUES (
            (p_record->>'TaskID')::uuid, p_record->>'PrincipalKind',
            (p_record->>'PrincipalID')::uuid, true, NULL,
            transaction_timestamp(), transaction_timestamp()
        )
        ON CONFLICT (task_id, principal_kind, principal_id) DO UPDATE SET
            active=true, removed_at=NULL, updated_at=EXCLUDED.updated_at;
    WHEN 'LABEL' THEN
        INSERT INTO work_labels (
            id, board_id, name, color, row_version, deleted_at,
            created_at, updated_at
        ) VALUES (
            p_target_id, (p_record->>'BoardID')::uuid, p_record->>'Name',
            p_record->>'Color', 1, NULL,
            transaction_timestamp(), transaction_timestamp()
        )
        ON CONFLICT (id) DO UPDATE SET
            board_id=EXCLUDED.board_id, name=EXCLUDED.name,
            color=EXCLUDED.color, deleted_at=NULL,
            updated_at=EXCLUDED.updated_at;
    WHEN 'TASK_LABEL' THEN
        INSERT INTO work_task_labels (
            task_id, label_id, active, removed_at, created_at, updated_at
        ) VALUES (
            (p_record->>'TaskID')::uuid, (p_record->>'LabelID')::uuid,
            true, NULL, transaction_timestamp(), transaction_timestamp()
        )
        ON CONFLICT (task_id, label_id) DO UPDATE SET
            active=true, removed_at=NULL, updated_at=EXCLUDED.updated_at;
    WHEN 'CHECKLIST' THEN
        INSERT INTO work_checklist_items (
            id, task_id, item_text, completed, position, row_version,
            deleted_at, created_at, updated_at
        ) VALUES (
            p_target_id, (p_record->>'TaskID')::uuid, p_record->>'Text',
            (p_record->>'Completed')::boolean,
            (p_record->>'Position')::bigint, 1, NULL,
            transaction_timestamp(), transaction_timestamp()
        )
        ON CONFLICT (id) DO UPDATE SET
            task_id=EXCLUDED.task_id, item_text=EXCLUDED.item_text,
            completed=EXCLUDED.completed, position=EXCLUDED.position,
            deleted_at=NULL, updated_at=EXCLUDED.updated_at;
    WHEN 'FORM_LINK' THEN
        INSERT INTO work_resource_links (
            id, work_resource_kind, work_resource_id, target_owner,
            target_kind, target_id, target_version_id, usage,
            target_reference_epoch, permission_revision, state, row_version,
            created_at, released_at
        ) VALUES (
            p_target_id, p_record->>'ResourceKind',
            (p_record->>'ResourceID')::uuid, 'FORMS', 'FORM',
            (p_record->>'FormID')::uuid, (p_record->>'VersionID')::uuid,
            'SCHEMA', (p_record->>'ReferenceEpoch')::bigint,
            (p_record->>'PermissionRevision')::bigint,
            'ACTIVE', 1, transaction_timestamp(), NULL
        )
        ON CONFLICT (id) DO UPDATE SET
            target_id=EXCLUDED.target_id,
            target_version_id=EXCLUDED.target_version_id,
            target_reference_epoch=EXCLUDED.target_reference_epoch,
            permission_revision=EXCLUDED.permission_revision,
            state='ACTIVE', released_at=NULL;
    ELSE
        RAISE EXCEPTION USING ERRCODE = '22023',
            MESSAGE = 'Work V1 task projection kind is invalid';
    END CASE;
    RETURN true;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_project_task_v1(p_target_kind text, p_target_id uuid, p_record jsonb) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_project_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_project_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_kind text;
    v_stage work_v1_adoption_stage%ROWTYPE;
    v_final_lsn pg_lsn;
    v_source_count bigint;
    v_source_identity_count bigint;
    v_target_count bigint;
    v_source_sha text;
    v_target_sha text;
    v_manifest bytea;
    v_acceptance bytea;
    v_actor uuid;
    v_generation bigint;
    v_rows bigint;
BEGIN
    v_target_count := 0;
    v_final_lsn := work_v1_adoption_projection_ready_v1(
        p_operation_id, p_run_id, p_scope_id
    );
    SELECT operation.lease_owner, operation.cutover_generation
    INTO STRICT v_actor, v_generation
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id;
    FOREACH v_kind IN ARRAY ARRAY[
        'BOARD','COLUMN','MEMBERSHIP','TASK','LABEL','ASSIGNEE',
        'TASK_LABEL','CHECKLIST','COMMENT','CALENDAR','RECURRENCE',
        'FORM_LINK','WORKFLOW_PROJECTION'
    ]::text[]
    LOOP
        FOR v_stage IN
            SELECT stage.*
            FROM work_v1_adoption_stage AS stage
            WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
              AND stage.target_kind=v_kind AND NOT stage.removed
            ORDER BY stage.target_id
        LOOP
            IF v_kind IN ('BOARD','COLUMN','MEMBERSHIP') THEN
                PERFORM work_v1_adoption_project_board_v1(
                    v_stage.target_kind, v_stage.target_id, v_stage.target_record
                );
            ELSIF v_kind IN (
                'TASK','LABEL','ASSIGNEE','TASK_LABEL','CHECKLIST','FORM_LINK'
            ) THEN
                PERFORM work_v1_adoption_project_task_v1(
                    v_stage.target_kind, v_stage.target_id, v_stage.target_record
                );
            ELSE
                PERFORM work_v1_adoption_project_collaboration_v1(
                    v_stage.target_kind, v_stage.target_id, v_stage.target_record
                );
            END IF;
            v_target_count := v_target_count + 1;
        END LOOP;
    END LOOP;
    SELECT pg_catalog.count(*),
        pg_catalog.count(DISTINCT (source.source_kind, source.source_id)),
        pg_catalog.encode(pg_catalog.sha256(
        pg_catalog.convert_to(COALESCE(pg_catalog.string_agg(
            source.source_kind || ':' || source.source_id::text || ':' ||
            pg_catalog.encode(source.source_sha256, 'hex'),
            ',' ORDER BY source.source_kind, source.source_id
        ), ''), 'UTF8')
    ), 'hex')
    INTO v_source_count, v_source_identity_count, v_source_sha
    FROM (
        SELECT DISTINCT stage.source_kind, stage.source_id, stage.source_sha256
        FROM work_v1_adoption_stage AS stage
        WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
    ) AS source;
    IF v_source_count IS DISTINCT FROM v_source_identity_count THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 source identity digest differs';
    END IF;
    SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(
        COALESCE(pg_catalog.string_agg(
            stage.target_kind || ':' || stage.target_id::text || ':' ||
            pg_catalog.encode(stage.target_sha256, 'hex'),
            ',' ORDER BY stage.target_kind, stage.target_id
        ), ''), 'UTF8'
    )), 'hex')
    INTO v_target_sha
    FROM work_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed;
    INSERT INTO work_adoption_objects (
        run_id, source_kind, source_id, target_kind, target_id,
        source_sha256, target_sha256, applied_lsn, state, issue_code, updated_at
    )
    SELECT p_run_id, stage.source_kind, stage.source_id, stage.target_kind,
        stage.target_id, stage.source_sha256, stage.target_sha256,
        v_final_lsn, 'MATCHED', NULL, transaction_timestamp()
    FROM work_v1_adoption_stage AS stage
    WHERE stage.operation_id=p_operation_id AND stage.run_id=p_run_id
      AND NOT stage.removed
    ORDER BY stage.source_kind, stage.source_id, stage.target_kind, stage.target_id
    ON CONFLICT (run_id, source_kind, source_id, target_kind, target_id) DO UPDATE
    SET source_sha256=EXCLUDED.source_sha256,
        target_sha256=EXCLUDED.target_sha256,
        applied_lsn=EXCLUDED.applied_lsn, state='MATCHED',
        issue_code=NULL, updated_at=EXCLUDED.updated_at
    WHERE work_adoption_objects.source_sha256=EXCLUDED.source_sha256
      AND work_adoption_objects.target_sha256=EXCLUDED.target_sha256;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows IS DISTINCT FROM v_target_count THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 adoption object reconciliation differs';
    END IF;
    SELECT run.manifest_sha256 INTO STRICT v_manifest
    FROM work_adoption_runs AS run
    WHERE run.run_id=p_run_id AND run.cutover_generation=v_generation
    FOR UPDATE;
    v_acceptance := pg_catalog.sha256(
        v_manifest || pg_catalog.decode(v_source_sha, 'hex') ||
        pg_catalog.decode(v_target_sha, 'hex')
    );
    UPDATE work_adoption_runs
    SET state='ACCEPTED', source_count=v_source_count,
        target_count=v_target_count,
        source_sha256=pg_catalog.decode(v_source_sha, 'hex'),
        target_sha256=pg_catalog.decode(v_target_sha, 'hex'),
        final_lsn=v_final_lsn, applied_lsn=v_final_lsn,
        acceptance_sha256=v_acceptance, updated_at=transaction_timestamp()
    WHERE run_id=p_run_id AND cutover_generation=v_generation
      AND state IN ('COPYING','RECONCILING');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 adoption acceptance state differs';
    END IF;
    UPDATE work_v1_writer_fence
    SET state='V2_FENCED', run_id=p_run_id, generation=v_generation,
        reverse_reconciliation_id=NULL, updated_by=v_actor,
        updated_at=transaction_timestamp()
    WHERE singleton AND state='V1_ACTIVE';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows IS DISTINCT FROM 1::bigint THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 writer fence differs';
    END IF;
    RETURN v_target_sha;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_project_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_projection_ready_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_projection_ready_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) RETURNS pg_lsn
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE
    v_expected bigint;
    v_complete bigint;
    v_final_count bigint;
    v_final_lsn pg_lsn;
    v_existing bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RAISE EXCEPTION USING ERRCODE = '42501',
            MESSAGE = 'Work V1 projection readiness principal denied';
    END IF;
    PERFORM 1
    FROM platform.cutover_operations AS operation
    WHERE operation.operation_id=p_operation_id AND operation.run_id=p_run_id
      AND operation.scope_kind='tenant' AND operation.scope_id=p_scope_id
      AND operation.group_id='work' AND operation.domain='work'
      AND operation.state='quiescing'
    FOR SHARE;
    IF NOT FOUND OR NOT EXISTS (
        SELECT 1 FROM tenancy_schema_identity AS identity
        WHERE identity.singleton AND identity.tenant_id=p_scope_id
          AND identity.origin='v1_adopted'
    ) OR NOT EXISTS (
        SELECT 1 FROM work_adoption_runs AS run
        WHERE run.run_id=p_run_id AND run.state IN ('COPYING','RECONCILING')
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 projection authority is not ready';
    END IF;
    SELECT pg_catalog.count(*) INTO v_expected
    FROM platform.cutover_operation_checkpoint_keys AS expected
    WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id;
    SELECT pg_catalog.count(*), pg_catalog.count(DISTINCT checkpoint.final_lsn::text)
    INTO v_complete, v_final_count
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id
      AND checkpoint.state='complete' AND checkpoint.final_lsn IS NOT NULL;
    IF v_expected < 1 OR v_complete IS DISTINCT FROM v_expected OR
       v_final_count IS DISTINCT FROM 1::bigint OR EXISTS (
        SELECT 1
        FROM platform.cutover_operation_checkpoint_keys AS expected
        LEFT JOIN platform.cutover_copy_checkpoints AS checkpoint
          ON checkpoint.operation_id=expected.operation_id
         AND checkpoint.run_id=expected.run_id
         AND checkpoint.relation_ordinal=expected.relation_ordinal
         AND checkpoint.checkpoint_key=expected.checkpoint_key
         AND checkpoint.state='complete'
        WHERE expected.operation_id=p_operation_id AND expected.run_id=p_run_id
          AND checkpoint.operation_id IS NULL
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 projection checkpoints are incomplete';
    END IF;
    SELECT checkpoint.final_lsn INTO STRICT v_final_lsn
    FROM platform.cutover_copy_checkpoints AS checkpoint
    WHERE checkpoint.operation_id=p_operation_id AND checkpoint.run_id=p_run_id
    ORDER BY checkpoint.relation_ordinal, checkpoint.checkpoint_key
    LIMIT 1;
    SELECT
        (SELECT pg_catalog.count(*) FROM work_boards) +
        (SELECT pg_catalog.count(*) FROM work_board_columns) +
        (SELECT pg_catalog.count(*) FROM work_board_memberships) +
        (SELECT pg_catalog.count(*) FROM work_tasks) +
        (SELECT pg_catalog.count(*) FROM work_task_assignees) +
        (SELECT pg_catalog.count(*) FROM work_labels) +
        (SELECT pg_catalog.count(*) FROM work_task_labels) +
        (SELECT pg_catalog.count(*) FROM work_checklist_items) +
        (SELECT pg_catalog.count(*) FROM work_comments) +
        (SELECT pg_catalog.count(*) FROM work_calendar_events) +
        (SELECT pg_catalog.count(*) FROM work_recurrence_rules) +
        (SELECT pg_catalog.count(*) FROM work_resource_links) +
        (SELECT pg_catalog.count(*) FROM work_inbox_items)
    INTO v_existing;
    IF v_existing <> 0 THEN
        RAISE EXCEPTION USING ERRCODE = '55000',
            MESSAGE = 'Work V1 inactive target is not empty';
    END IF;
    RETURN v_final_lsn;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_projection_ready_v1(p_operation_id uuid, p_run_id uuid, p_scope_id uuid) OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_task_metadata_v1(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_task_metadata_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_record jsonb; v_matches bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RETURN NEW;
    END IF;
    SELECT pg_catalog.jsonb_agg(stage.target_record ORDER BY stage.run_id)->0,
           pg_catalog.count(*) INTO v_record,v_matches
      FROM work_v1_adoption_stage AS stage
      JOIN work_adoption_runs AS run ON run.run_id=stage.run_id
     WHERE stage.target_kind='TASK' AND stage.target_id=NEW.id AND NOT stage.removed
       AND run.state IN ('COPYING','RECONCILING');
    IF v_matches IS DISTINCT FROM 1::bigint OR NOT work_v1_adoption_document_valid_v1('TASK',v_record) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Work V1 task metadata evidence denied';
    END IF;
    INSERT INTO work_task_compatibility_metadata (
        task_id,is_recurring,recurrence_rule,recurrence_end,form_filter,created_at,updated_at
    ) VALUES (NEW.id,(v_record->>'IsRecurring')::boolean,v_record->>'RecurrenceRule',
        (v_record->>'RecurrenceEnd')::timestamptz,
        NULLIF(v_record->'FormFilter','null'::jsonb),NEW.created_at,NEW.updated_at)
    ON CONFLICT (task_id) DO UPDATE SET is_recurring=EXCLUDED.is_recurring,
        recurrence_rule=EXCLUDED.recurrence_rule,recurrence_end=EXCLUDED.recurrence_end,
        form_filter=EXCLUDED.form_filter,created_at=EXCLUDED.created_at,updated_at=EXCLUDED.updated_at;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_task_metadata_v1() OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_task_values_v2(); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_task_values_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $$
DECLARE v_record jsonb; v_matches bigint;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR CURRENT_USER IS DISTINCT FROM 'harpy_owner' THEN
        RETURN NEW;
    END IF;
    SELECT pg_catalog.jsonb_agg(stage.target_record ORDER BY stage.run_id)->0,
           pg_catalog.count(*) INTO v_record,v_matches
      FROM work_v1_adoption_stage AS stage
      JOIN work_adoption_runs AS run ON run.run_id=stage.run_id
     WHERE stage.target_kind='TASK' AND stage.target_id=NEW.id AND NOT stage.removed
       AND run.state IN ('COPYING','RECONCILING');
    IF v_matches IS DISTINCT FROM 1::bigint OR NOT work_v1_adoption_document_valid_v1('TASK',v_record) THEN
        RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Work V1 task compatibility evidence denied';
    END IF;
    NEW.creator_user_id=(v_record->>'CreatorID')::uuid;
    NEW.priority=v_record->>'Priority';
    NEW.starts_at=(v_record->>'StartsAt')::timestamptz;
    RETURN NEW;
END;
$$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_task_values_v2() OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_value_valid_v1(jsonb, jsonb); Type: FUNCTION; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE FUNCTION __tenant_schema__.work_v1_adoption_value_valid_v1(p_key jsonb, p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO '__tenant_schema__', 'pg_catalog'
    AS $_$
DECLARE
    v_key_fields text;
    v_value_fields text;
BEGIN
    IF SESSION_USER IS DISTINCT FROM 'harpy_adopter' OR
       CURRENT_USER IS DISTINCT FROM 'harpy_owner' OR
       pg_catalog.jsonb_typeof(p_key) IS DISTINCT FROM 'object' OR
       pg_catalog.jsonb_typeof(p_value) IS DISTINCT FROM 'object' THEN
        RETURN false;
    END IF;
    SELECT pg_catalog.string_agg(key, ',' ORDER BY key) INTO v_key_fields
    FROM pg_catalog.jsonb_object_keys(p_key) AS key;
    SELECT pg_catalog.string_agg(key, ',' ORDER BY key) INTO v_value_fields
    FROM pg_catalog.jsonb_object_keys(p_value) AS key;
    IF v_key_fields IS DISTINCT FROM
           'source_id,source_kind,target_id,target_kind' OR
       v_value_fields IS DISTINCT FROM
           'source_id,source_kind,source_sha256,target_id,target_kind,target_record' OR
       p_value->>'source_id' IS DISTINCT FROM p_key->>'source_id' OR
       p_value->>'source_kind' IS DISTINCT FROM p_key->>'source_kind' OR
       p_value->>'target_id' IS DISTINCT FROM p_key->>'target_id' OR
       p_value->>'target_kind' IS DISTINCT FROM p_key->>'target_kind' OR
       p_value->>'source_sha256' !~ '^[0-9a-f]{64}$' OR
       p_value->>'source_kind' NOT IN (
           'task_boards','task_board_columns','board_members','board_tasks',
           'board_task_comments','calendar_events'
       ) OR p_value->>'target_kind' NOT IN (
           'BOARD','COLUMN','MEMBERSHIP','TASK','ASSIGNEE','LABEL','TASK_LABEL',
           'CHECKLIST','COMMENT','CALENDAR','RECURRENCE','FORM_LINK',
           'WORKFLOW_PROJECTION'
       ) THEN
        RETURN false;
    END IF;
    BEGIN
        PERFORM (p_value->>'source_id')::uuid, (p_value->>'target_id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        RETURN false;
    END;
    RETURN work_v1_adoption_document_valid_v1(
        p_value->>'target_kind', p_value->'target_record'
    );
END;
$_$;


ALTER FUNCTION __tenant_schema__.work_v1_adoption_value_valid_v1(p_key jsonb, p_value jsonb) OWNER TO harpy_owner;

