    CONSTRAINT analytics_capability_tokens_shape_check CHECK (((octet_length(token_sha256) = 32) AND isfinite(issued_at) AND isfinite(expires_at) AND (expires_at > issued_at) AND ((expires_at - issued_at) <= '30 days'::interval) AND ((revoked_at IS NULL) OR (isfinite(revoked_at) AND (revoked_at >= issued_at)))))
);


