    CONSTRAINT catalog_purge_authorities_v2_authority_sha256_check CHECK ((authority_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT catalog_purge_authorities_v2_backup_sha256_check CHECK ((backup_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT catalog_purge_authorities_v2_backup_state_check CHECK ((backup_state = 'READY'::text)),
    CONSTRAINT catalog_purge_authorities_v2_check CHECK (((actor_id = requested_by) AND (requested_by <> approved_by))),
    CONSTRAINT catalog_purge_authorities_v2_check1 CHECK ((confirmation_slug = package_slug)),
    CONSTRAINT catalog_purge_authorities_v2_check2 CHECK ((step_up_authenticated_at <= requested_at)),
    CONSTRAINT catalog_purge_authorities_v2_check3 CHECK ((step_up_authenticated_at >= (requested_at - '00:10:00'::interval))),
    CONSTRAINT catalog_purge_authorities_v2_check4 CHECK ((approval_step_up_at <= approved_at)),
    CONSTRAINT catalog_purge_authorities_v2_check5 CHECK ((approval_step_up_at >= (approved_at - '00:10:00'::interval))),
    CONSTRAINT catalog_purge_authorities_v2_check6 CHECK (((approved_at <= requested_at) AND (requested_at <= approval_expires_at))),
    CONSTRAINT catalog_purge_authorities_v2_check7 CHECK ((cooling_until >= (requested_at + '24:00:00'::interval))),
    CONSTRAINT catalog_purge_authorities_v2_cooling_until_check CHECK ((date_trunc('microseconds'::text, cooling_until) = cooling_until)),
    CONSTRAINT catalog_purge_authorities_v2_idempotency_key_check CHECK ((idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{7,127}$'::text)),
    CONSTRAINT catalog_purge_authorities_v2_package_id_check CHECK ((package_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT catalog_purge_authorities_v2_package_slug_check CHECK ((package_slug ~ '^[a-z][a-z0-9-]{1,62}$'::text)),
    CONSTRAINT catalog_purge_authorities_v2_reason_check CHECK (((length(reason) >= 1) AND (length(reason) <= 1024))),
    CONSTRAINT catalog_purge_authorities_v2_reference_epoch_check CHECK ((reference_epoch > 0)),
    CONSTRAINT catalog_purge_authorities_v2_requested_at_check CHECK ((date_trunc('microseconds'::text, requested_at) = requested_at)),
    CONSTRAINT catalog_purge_authorities_v2_step_up_authenticated_at_check CHECK ((date_trunc('microseconds'::text, step_up_authenticated_at) = step_up_authenticated_at)),
    CONSTRAINT catalog_purge_authorities_v2_tenant_id_check CHECK ((tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid)),
    CONSTRAINT catalog_purge_authority_iam_v3_check CHECK ((((authorization_token_version IS NULL) AND (authorization_version IS NULL) AND (authorization_clock IS NULL) AND (authorization_permission_id IS NULL) AND (authorization_evidence_sha256 IS NULL) AND (step_up_purpose_sha256 IS NULL)) OR ((authorization_token_version > 0) AND (authorization_version > 0) AND (authorization_clock > 0) AND (authorization_permission_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (authorization_evidence_sha256 ~ '^[0-9a-f]{64}$'::text) AND (step_up_purpose_sha256 ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT catalog_purge_authority_package_id_nonzero CHECK (((package_id IS NOT NULL) AND (package_id <> '00000000-0000-0000-0000-000000000000'::uuid)))
);


