    cipher_format text,
    CONSTRAINT documents_archives_artifact_plaintext_bytes_check CHECK (((artifact_plaintext_bytes IS NULL) OR (artifact_plaintext_bytes > 0))),
    CONSTRAINT documents_archives_artifact_sha256_check CHECK (((artifact_sha256 IS NULL) OR (octet_length(artifact_sha256) = 32))),
    CONSTRAINT documents_archives_authorization_revision_check CHECK ((authorization_revision > 0)),
    CONSTRAINT documents_archives_check1 CHECK ((((lifecycle_state = 'PURGED'::text) AND (delete_receipt_sha256 IS NOT NULL) AND (purged_at IS NOT NULL)) OR (lifecycle_state <> 'PURGED'::text))),
    CONSTRAINT documents_archives_cipher_format_check CHECK (((cipher_format IS NULL) OR (cipher_format = 'FCDOC1'::text))),
    CONSTRAINT documents_archives_cipher_ready_check CHECK ((((lifecycle_state = ANY (ARRAY['PENDING'::text, 'CANCELLED'::text])) AND (((artifact_plaintext_bytes IS NULL) AND (ciphertext_sha256 IS NULL) AND (cipher_format IS NULL)) OR ((artifact_plaintext_bytes IS NOT NULL) AND (ciphertext_sha256 IS NOT NULL) AND (cipher_format = 'FCDOC1'::text)))) OR ((lifecycle_state = ANY (ARRAY['READY'::text, 'EXPIRED'::text, 'PURGED'::text])) AND (artifact_plaintext_bytes IS NOT NULL) AND (ciphertext_sha256 IS NOT NULL) AND (cipher_format = 'FCDOC1'::text)))),
    CONSTRAINT documents_archives_ciphertext_bytes_check CHECK (((ciphertext_bytes IS NULL) OR (ciphertext_bytes > 0))),
    CONSTRAINT documents_archives_ciphertext_sha256_check CHECK (((ciphertext_sha256 IS NULL) OR (octet_length(ciphertext_sha256) = 32))),
    CONSTRAINT documents_archives_delete_receipt_sha256_check CHECK (((delete_receipt_sha256 IS NULL) OR (octet_length(delete_receipt_sha256) = 32))),
    CONSTRAINT documents_archives_entries_sha256_check CHECK (((entries_sha256 IS NULL) OR (octet_length(entries_sha256) = 32))),
    CONSTRAINT documents_archives_entry_count_check CHECK (((entry_count >= 0) AND (entry_count <= 10000))),
    CONSTRAINT documents_archives_key_id_check CHECK (((key_id IS NULL) OR (key_id ~ '^[a-z0-9][a-z0-9_.-]{0,63}$'::text))),
    CONSTRAINT documents_archives_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['PENDING'::text, 'CANCELLED'::text, 'READY'::text, 'EXPIRED'::text, 'PURGED'::text]))),
    CONSTRAINT documents_archives_object_generation_check CHECK (((object_generation IS NULL) OR (object_generation > 0))),
    CONSTRAINT documents_archives_object_key_check CHECK (((object_key IS NULL) OR ((octet_length(object_key) >= 1) AND (octet_length(object_key) <= 1024)))),
    CONSTRAINT documents_archives_object_version_check CHECK (((object_version IS NULL) OR ((octet_length(object_version) >= 1) AND (octet_length(object_version) <= 1024)))),
    CONSTRAINT documents_archives_plaintext_bytes_check CHECK (((plaintext_bytes >= 0) AND (plaintext_bytes <= '10737418240'::bigint))),
    CONSTRAINT documents_archives_recovery_ready_check CHECK ((((lifecycle_state = ANY (ARRAY['PENDING'::text, 'CANCELLED'::text])) AND (ready_at IS NULL) AND (expires_at IS NULL)) OR ((lifecycle_state = ANY (ARRAY['READY'::text, 'EXPIRED'::text, 'PURGED'::text])) AND (entry_count > 0) AND (entries_sha256 IS NOT NULL) AND (ciphertext_bytes IS NOT NULL) AND (artifact_sha256 IS NOT NULL) AND (object_key IS NOT NULL) AND (object_version IS NOT NULL) AND (object_generation IS NOT NULL) AND (key_id IS NOT NULL) AND (wrapped_dek IS NOT NULL) AND (ready_at IS NOT NULL) AND (expires_at = (ready_at + '24:00:00'::interval))))),
    CONSTRAINT documents_archives_request_document_check CHECK (((octet_length(request_document) >= 2) AND (octet_length(request_document) <= 65536))),
    CONSTRAINT documents_archives_request_sha256_check CHECK ((octet_length(request_sha256) = 32)),
    CONSTRAINT documents_archives_wrapped_dek_check CHECK (((wrapped_dek IS NULL) OR ((octet_length(wrapped_dek) >= 115) AND (octet_length(wrapped_dek) <= 256))))
);


