    CONSTRAINT documents_format_releases_decoder_sha256_check CHECK ((octet_length(decoder_sha256) = 32)),
    CONSTRAINT documents_format_releases_format_id_check CHECK ((format_id ~ '^FCDOC[0-9]+$'::text)),
    CONSTRAINT documents_format_releases_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['CURRENT'::text, 'RETAINED'::text, 'RETIRED'::text]))),
    CONSTRAINT documents_format_releases_reference_count_check CHECK ((reference_count >= 0)),
    CONSTRAINT documents_format_releases_retirement_evidence_sha256_check CHECK (((retirement_evidence_sha256 IS NULL) OR (octet_length(retirement_evidence_sha256) = 32)))
);


