--
-- Name: documents_items; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.documents_items (
    id uuid NOT NULL,
    folder_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    current_version_id uuid,
    lifecycle_state text NOT NULL,
    resume_state text,
    row_version bigint NOT NULL,
    trashed_at timestamp with time zone,
    retention_ends_at timestamp with time zone,
    purge_requested_at timestamp with time zone,
    purge_starts_at timestamp with time zone,
    purge_reason text,
    purged_at timestamp with time zone,
    tombstone_until timestamp with time zone,
    purge_evidence_sha256 bytea,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    reference_epoch bigint DEFAULT 1 NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    tags jsonb DEFAULT '[]'::jsonb NOT NULL,
    CONSTRAINT documents_items_check CHECK ((isfinite(created_at) AND isfinite(updated_at))),
    CONSTRAINT documents_items_check1 CHECK ((((lifecycle_state = 'ACTIVE'::text) AND (trashed_at IS NULL) AND (retention_ends_at IS NULL)) OR (lifecycle_state <> 'ACTIVE'::text))),
    CONSTRAINT documents_items_check2 CHECK ((((lifecycle_state = 'TRASHED'::text) AND (trashed_at IS NOT NULL) AND (retention_ends_at > trashed_at)) OR (lifecycle_state <> 'TRASHED'::text))),
    CONSTRAINT documents_items_check3 CHECK ((((lifecycle_state = 'PURGE_COOLING'::text) AND (resume_state IS NOT NULL) AND (purge_requested_at IS NOT NULL) AND (purge_starts_at > purge_requested_at)) OR (lifecycle_state <> 'PURGE_COOLING'::text))),
    CONSTRAINT documents_items_check4 CHECK ((((lifecycle_state = 'PURGED'::text) AND (current_version_id IS NULL) AND (purged_at IS NOT NULL) AND (tombstone_until > purged_at) AND (purge_evidence_sha256 IS NOT NULL)) OR (lifecycle_state <> 'PURGED'::text))),
    CONSTRAINT documents_items_description_check CHECK ((octet_length(description) <= 4096)),
    CONSTRAINT documents_items_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['ACTIVE'::text, 'TRASHED'::text, 'PURGE_COOLING'::text, 'PURGING'::text, 'PURGED'::text]))),
    CONSTRAINT documents_items_purge_evidence_sha256_check CHECK (((purge_evidence_sha256 IS NULL) OR (octet_length(purge_evidence_sha256) = 32))),
    CONSTRAINT documents_items_purge_reason_check CHECK (((purge_reason IS NULL) OR ((octet_length(purge_reason) >= 3) AND (octet_length(purge_reason) <= 2048)))),
    CONSTRAINT documents_items_reference_epoch_check CHECK ((reference_epoch > 0)),
    CONSTRAINT documents_items_resume_state_check CHECK ((resume_state = ANY (ARRAY['ACTIVE'::text, 'TRASHED'::text]))),
    CONSTRAINT documents_items_row_version_check CHECK ((row_version > 0)),
    CONSTRAINT documents_items_tags_check CHECK (((jsonb_typeof(tags) = 'array'::text) AND (octet_length((tags)::text) <= 2048)))
);


