-- Name: documents_knowledge_file_leases; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.documents_knowledge_file_leases (
    lease_id uuid NOT NULL,
    upload_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    item_id uuid NOT NULL,
    version_id uuid NOT NULL,
    reference_id uuid,
    source_id uuid,
    expected_plaintext_bytes bigint CONSTRAINT documents_knowledge_file_leas_expected_plaintext_bytes_not_null NOT NULL,
    expected_plaintext_sha256 bytea CONSTRAINT documents_knowledge_file_lea_expected_plaintext_sha256_not_null NOT NULL,
    filename text NOT NULL,
    declared_mime text NOT NULL,
    detected_mime text,
    scan_signature_revision text,
    scanned_at timestamp with time zone,
    lifecycle_state text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    adopted_at timestamp with time zone,
    released_at timestamp with time zone,
    expired_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT documents_knowledge_file_leases_check CHECK ((lease_id = upload_id)),
    CONSTRAINT documents_knowledge_file_leases_check1 CHECK ((isfinite(expires_at) AND isfinite(created_at) AND isfinite(updated_at))),
    CONSTRAINT documents_knowledge_file_leases_check2 CHECK ((((detected_mime IS NULL) = (scan_signature_revision IS NULL)) AND ((detected_mime IS NULL) = (scanned_at IS NULL)))),
    CONSTRAINT documents_knowledge_file_leases_check3 CHECK (((reference_id IS NULL) = (source_id IS NULL))),
    CONSTRAINT documents_knowledge_file_leases_check4 CHECK ((((lifecycle_state = 'PENDING'::text) AND (detected_mime IS NULL) AND (reference_id IS NULL) AND (adopted_at IS NULL) AND (released_at IS NULL) AND (expired_at IS NULL)) OR ((lifecycle_state = 'STAGED'::text) AND (detected_mime IS NOT NULL) AND (reference_id IS NULL) AND (adopted_at IS NULL) AND (released_at IS NULL) AND (expired_at IS NULL)) OR ((lifecycle_state = 'ADOPTED'::text) AND (detected_mime IS NOT NULL) AND (reference_id IS NOT NULL) AND (adopted_at IS NOT NULL) AND (released_at IS NULL) AND (expired_at IS NULL)) OR ((lifecycle_state = 'RELEASED'::text) AND (detected_mime IS NOT NULL) AND (reference_id IS NOT NULL) AND (adopted_at IS NOT NULL) AND (released_at IS NOT NULL) AND (expired_at IS NULL)) OR ((lifecycle_state = 'EXPIRED'::text) AND (reference_id IS NULL) AND (adopted_at IS NULL) AND (released_at IS NULL) AND (expired_at IS NOT NULL)))),
    CONSTRAINT documents_knowledge_file_leases_declared_mime_check CHECK (((octet_length(declared_mime) >= 1) AND (octet_length(declared_mime) <= 255))),
    CONSTRAINT documents_knowledge_file_leases_expected_plaintext_bytes_check CHECK (((expected_plaintext_bytes >= 1) AND (expected_plaintext_bytes <= 20971520))),
    CONSTRAINT documents_knowledge_file_leases_expected_plaintext_sha256_check CHECK ((octet_length(expected_plaintext_sha256) = 32)),
    CONSTRAINT documents_knowledge_file_leases_filename_check CHECK (((octet_length(filename) >= 1) AND (octet_length(filename) <= 255))),
    CONSTRAINT documents_knowledge_file_leases_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['PENDING'::text, 'STAGED'::text, 'ADOPTED'::text, 'RELEASED'::text, 'EXPIRED'::text])))
);


