    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT documents_upload_attempts_attempt_generation_check CHECK ((attempt_generation > 0)),
    CONSTRAINT documents_upload_attempts_check CHECK ((((lifecycle_state = ANY (ARRAY['RECEIVING'::text, 'FAILED'::text])) AND (object_key IS NULL) AND (object_version IS NULL) AND (object_generation IS NULL) AND (plaintext_bytes IS NULL) AND (ciphertext_bytes IS NULL) AND (plaintext_sha256 IS NULL) AND (ciphertext_sha256 IS NULL) AND (detected_mime IS NULL) AND (file_kind IS NULL) AND (key_id IS NULL) AND (wrapped_dek IS NULL) AND (scan_signature_revision IS NULL) AND (scanned_at IS NULL)) OR ((lifecycle_state = ANY (ARRAY['EFFECT_RECORDED'::text, 'FINALIZED'::text])) AND (object_key IS NOT NULL) AND (object_version IS NOT NULL) AND (object_generation > 0) AND (plaintext_bytes > 0) AND (ciphertext_bytes > plaintext_bytes) AND (octet_length(plaintext_sha256) = 32) AND (octet_length(ciphertext_sha256) = 32) AND (key_id IS NOT NULL) AND (wrapped_dek IS NOT NULL) AND (detected_mime IS NOT NULL) AND (file_kind IS NOT NULL) AND (scan_signature_revision IS NOT NULL) AND (scanned_at IS NOT NULL)) OR ((lifecycle_state = ANY (ARRAY['CLEANUP_PENDING'::text, 'CLEANED'::text])) AND (object_key IS NOT NULL) AND (object_version IS NOT NULL) AND (object_generation > 0) AND (plaintext_bytes > 0) AND (ciphertext_bytes > plaintext_bytes)))),
    CONSTRAINT documents_upload_attempts_check1 CHECK (((lifecycle_state = ANY (ARRAY['CLEANUP_PENDING'::text, 'CLEANED'::text])) = (cleanup_deletion_id IS NOT NULL))),
    CONSTRAINT documents_upload_attempts_check2 CHECK (((lifecycle_state = 'CLEANED'::text) = ((cleanup_receipt_sha256 IS NOT NULL) AND (octet_length(cleanup_receipt_sha256) = 32)))),
    CONSTRAINT documents_upload_attempts_lifecycle_state_check CHECK ((lifecycle_state = ANY (ARRAY['RECEIVING'::text, 'FAILED'::text, 'EFFECT_RECORDED'::text, 'FINALIZED'::text, 'CLEANUP_PENDING'::text, 'CLEANED'::text])))
);


