-- Name: iam_auth_challenges; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.iam_auth_challenges (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    session_id uuid,
    authenticator_id uuid,
    authenticator_kind text,
    purpose text NOT NULL,
    proof_kind text NOT NULL,
    hash_profile text NOT NULL,
    hmac_key_id text NOT NULL COLLATE pg_catalog."C",
    challenge_hmac bytea NOT NULL,
    context_sha256 bytea NOT NULL,
    step_up_purpose_sha256 bytea,
    origin_policy_version bigint,
    action_policy_version bigint,
    rp_id_sha256 bytea,
    origin_sha256 bytea,
    user_verification_required boolean,
    state text NOT NULL,
    attempt_count smallint NOT NULL,
    revision bigint NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    terminal_at timestamp with time zone,
    purge_after timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    security_epoch bytea DEFAULT __tenant_schema__.iam_security_epoch_current_v1("current_schema"()) NOT NULL,
    CONSTRAINT iam_auth_challenges_attempt_check CHECK (((attempt_count >= 0) AND (attempt_count <= 5))),
    CONSTRAINT iam_auth_challenges_hash_profile_check CHECK ((hash_profile = 'hmac_sha256_v1'::text)),
    CONSTRAINT iam_auth_challenges_lifecycle_check CHECK ((((state = 'pending'::text) AND (attempt_count < 5) AND (terminal_at IS NULL)) OR ((state = 'consumed'::text) AND (terminal_at IS NOT NULL) AND (terminal_at <= expires_at)) OR ((state = 'failed'::text) AND (attempt_count = 5) AND (terminal_at IS NOT NULL) AND (terminal_at <= expires_at)) OR ((state = 'expired'::text) AND (terminal_at IS NOT NULL) AND (terminal_at >= expires_at)) OR ((state = 'cancelled'::text) AND (terminal_at IS NOT NULL)))),
    CONSTRAINT iam_auth_challenges_origin_context_check CHECK ((((proof_kind = 'webauthn_v1'::text) AND (origin_policy_version IS NOT NULL) AND (origin_policy_version > 0) AND (rp_id_sha256 IS NOT NULL) AND (origin_sha256 IS NOT NULL) AND (octet_length(rp_id_sha256) = 32) AND (octet_length(origin_sha256) = 32) AND (user_verification_required IS NOT NULL)) OR ((proof_kind = ANY (ARRAY['password_v1'::text, 'totp_v1'::text])) AND (origin_policy_version IS NULL) AND (rp_id_sha256 IS NULL) AND (origin_sha256 IS NULL) AND (user_verification_required IS NULL)))),
    CONSTRAINT iam_auth_challenges_proof_check CHECK ((proof_kind = ANY (ARRAY['password_v1'::text, 'webauthn_v1'::text, 'totp_v1'::text]))),
    CONSTRAINT iam_auth_challenges_purpose_check CHECK ((purpose = ANY (ARRAY['webauthn_register_v1'::text, 'webauthn_authenticate_v1'::text, 'totp_enroll_v1'::text, 'reauth_v1'::text]))),
    CONSTRAINT iam_auth_challenges_purpose_shape_check CHECK ((((purpose = 'webauthn_register_v1'::text) AND (proof_kind = 'webauthn_v1'::text) AND (session_id IS NOT NULL) AND (authenticator_id IS NOT NULL) AND (authenticator_kind = 'webauthn_v1'::text) AND (step_up_purpose_sha256 IS NULL) AND (action_policy_version IS NULL)) OR ((purpose = 'webauthn_authenticate_v1'::text) AND (proof_kind = 'webauthn_v1'::text) AND (authenticator_id IS NOT NULL) AND (authenticator_kind = 'webauthn_v1'::text) AND (step_up_purpose_sha256 IS NULL) AND (action_policy_version IS NULL)) OR ((purpose = 'totp_enroll_v1'::text) AND (proof_kind = 'totp_v1'::text) AND (session_id IS NOT NULL) AND (authenticator_id IS NOT NULL) AND (authenticator_kind = 'totp_v1'::text) AND (step_up_purpose_sha256 IS NULL) AND (action_policy_version IS NULL)) OR ((purpose = 'reauth_v1'::text) AND (session_id IS NOT NULL) AND (step_up_purpose_sha256 IS NOT NULL) AND (octet_length(step_up_purpose_sha256) = 32) AND (action_policy_version IS NOT NULL) AND (action_policy_version > 0) AND (((proof_kind = 'password_v1'::text) AND (authenticator_id IS NULL) AND (authenticator_kind IS NULL)) OR ((proof_kind = ANY (ARRAY['webauthn_v1'::text, 'totp_v1'::text])) AND (authenticator_id IS NOT NULL) AND (authenticator_kind = proof_kind)))))),
    CONSTRAINT iam_auth_challenges_revision_check CHECK ((revision > 0)),
    CONSTRAINT iam_auth_challenges_secret_check CHECK ((__tenant_schema__.iam_hmac_key_id_valid_v1(hmac_key_id) AND (octet_length(challenge_hmac) = 32) AND (octet_length(context_sha256) = 32))),
    CONSTRAINT iam_auth_challenges_security_epoch_ck CHECK ((octet_length(security_epoch) = 32)),
    CONSTRAINT iam_auth_challenges_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'consumed'::text, 'failed'::text, 'expired'::text, 'cancelled'::text]))),
    CONSTRAINT iam_auth_challenges_time_check CHECK (((updated_at >= created_at) AND (issued_at >= created_at) AND (issued_at <= updated_at) AND (expires_at > issued_at) AND (expires_at <= (issued_at + '00:05:00'::interval)) AND ((terminal_at IS NULL) OR ((terminal_at >= issued_at) AND (terminal_at <= updated_at))) AND (purge_after >= (GREATEST(expires_at, COALESCE(terminal_at, expires_at)) + '24:00:00'::interval))))
);


