--
-- Name: iam_authenticators; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.iam_authenticators (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    display_label text NOT NULL,
    state text NOT NULL,
    revision bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    activated_at timestamp with time zone,
    last_used_at timestamp with time zone,
    suspended_at timestamp with time zone,
    compromised_at timestamp with time zone,
    renewal_required_at timestamp with time zone,
    retired_at timestamp with time zone,
    CONSTRAINT iam_authenticators_kind_check CHECK ((kind = ANY (ARRAY['webauthn_v1'::text, 'totp_v1'::text, 'recovery_set_v1'::text]))),
    CONSTRAINT iam_authenticators_label_check CHECK ((((char_length(display_label) >= 1) AND (char_length(display_label) <= 100)) AND (display_label = btrim(display_label)))),
    CONSTRAINT iam_authenticators_lifecycle_check CHECK ((((state = 'pending'::text) AND (activated_at IS NULL) AND (suspended_at IS NULL) AND (compromised_at IS NULL) AND (renewal_required_at IS NULL) AND (retired_at IS NULL)) OR ((state = 'active'::text) AND (activated_at IS NOT NULL) AND (suspended_at IS NULL) AND (compromised_at IS NULL) AND (renewal_required_at IS NULL) AND (retired_at IS NULL)) OR ((state = 'suspended'::text) AND (suspended_at IS NOT NULL) AND (compromised_at IS NULL) AND (renewal_required_at IS NULL) AND (retired_at IS NULL)) OR ((state = 'compromised'::text) AND (compromised_at IS NOT NULL) AND (suspended_at IS NULL) AND (renewal_required_at IS NULL) AND (retired_at IS NULL)) OR ((state = 'renewal_required'::text) AND (activated_at IS NOT NULL) AND (renewal_required_at IS NOT NULL) AND (suspended_at IS NULL) AND (compromised_at IS NULL) AND (retired_at IS NULL)) OR ((state = 'retired'::text) AND (retired_at IS NOT NULL) AND ((suspended_at IS NULL) OR (retired_at >= suspended_at)) AND ((compromised_at IS NULL) OR (retired_at >= compromised_at)) AND ((renewal_required_at IS NULL) OR (retired_at >= renewal_required_at))))),
    CONSTRAINT iam_authenticators_revision_check CHECK ((revision > 0)),
    CONSTRAINT iam_authenticators_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'active'::text, 'suspended'::text, 'compromised'::text, 'renewal_required'::text, 'retired'::text]))),
    CONSTRAINT iam_authenticators_timestamp_check CHECK (((updated_at >= created_at) AND ((activated_at IS NULL) OR ((activated_at >= created_at) AND (activated_at <= updated_at))) AND ((last_used_at IS NULL) OR ((activated_at IS NOT NULL) AND (last_used_at >= activated_at) AND (last_used_at <= updated_at))) AND ((suspended_at IS NULL) OR ((suspended_at >= COALESCE(activated_at, created_at)) AND (suspended_at <= updated_at))) AND ((compromised_at IS NULL) OR ((compromised_at >= COALESCE(activated_at, created_at)) AND (compromised_at <= updated_at))) AND ((renewal_required_at IS NULL) OR ((activated_at IS NOT NULL) AND (renewal_required_at >= activated_at) AND (renewal_required_at <= updated_at))) AND ((retired_at IS NULL) OR ((retired_at >= created_at) AND (retired_at <= updated_at)))))
);


