    updated_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    revoked_at timestamp with time zone,
    expired_at timestamp with time zone,
    purge_after timestamp with time zone NOT NULL,
    security_epoch bytea DEFAULT __tenant_schema__.iam_security_epoch_current_v1("current_schema"()) NOT NULL,
    CONSTRAINT iam_one_time_tokens_counter_check CHECK ((((attempt_count >= 0) AND (attempt_count <= 5)) AND (revision > 0))),
    CONSTRAINT iam_one_time_tokens_lifecycle_check CHECK ((((state = 'pending'::text) AND (attempt_count < 5) AND (consumed_at IS NULL) AND (revoked_at IS NULL) AND (expired_at IS NULL)) OR ((state = 'consumed'::text) AND (consumed_at IS NOT NULL) AND (revoked_at IS NULL) AND (expired_at IS NULL)) OR ((state = 'revoked'::text) AND (consumed_at IS NULL) AND (revoked_at IS NOT NULL) AND (expired_at IS NULL)) OR ((state = 'expired'::text) AND (consumed_at IS NULL) AND (revoked_at IS NULL) AND (expired_at = expires_at)))),
    CONSTRAINT iam_one_time_tokens_purpose_check CHECK ((purpose = ANY (ARRAY['password_reset_v1'::text, 'email_verification_v1'::text, 'portal_setup_v1'::text, 'invitation_accept_v1'::text, 'initial_admin_setup.v1'::text]))),
    CONSTRAINT iam_one_time_tokens_secret_check CHECK (((octet_length(selector) = 16) AND __tenant_schema__.iam_hmac_key_id_valid_v1(hash_key_id) AND (octet_length(secret_hmac) = 32) AND (octet_length(binding_sha256) = 32))),
    CONSTRAINT iam_one_time_tokens_security_epoch_ck CHECK ((octet_length(security_epoch) = 32)),
    CONSTRAINT iam_one_time_tokens_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'consumed'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT iam_one_time_tokens_subject_shape_check CHECK ((((purpose = ANY (ARRAY['password_reset_v1'::text, 'email_verification_v1'::text, 'initial_admin_setup.v1'::text])) AND (identifier_kind = 'email_v1'::text) AND (identifier_revision > 0) AND (user_id IS NOT NULL) AND (identifier_id IS NOT NULL) AND (invitation_id IS NULL) AND (invitation_expires_at IS NULL) AND (invitation_revision IS NULL) AND (portal_binding_id IS NULL) AND (portal_setup_revision IS NULL)) OR ((purpose = 'portal_setup_v1'::text) AND (identifier_kind = 'portal_v1'::text) AND (identifier_revision > 0) AND (user_id IS NOT NULL) AND (identifier_id IS NOT NULL) AND (invitation_id IS NULL) AND (invitation_expires_at IS NULL) AND (invitation_revision IS NULL) AND (portal_binding_id IS NOT NULL) AND (portal_setup_revision > 0)) OR ((purpose = 'invitation_accept_v1'::text) AND (user_id IS NULL) AND (identifier_id IS NULL) AND (identifier_kind IS NULL) AND (identifier_revision IS NULL) AND (invitation_id IS NOT NULL) AND (invitation_expires_at IS NOT NULL) AND (invitation_revision > 0) AND (portal_binding_id IS NULL) AND (portal_setup_revision IS NULL)))),
    CONSTRAINT iam_one_time_tokens_time_check CHECK (((updated_at >= created_at) AND ((consumed_at IS NULL) OR ((consumed_at >= created_at) AND (consumed_at <= expires_at) AND (consumed_at <= updated_at))) AND ((revoked_at IS NULL) OR ((revoked_at >= created_at) AND (revoked_at <= updated_at))) AND ((expired_at IS NULL) OR (expired_at <= updated_at)) AND (purge_after >= (GREATEST(expires_at, COALESCE(consumed_at, expires_at), COALESCE(revoked_at, expires_at), COALESCE(expired_at, expires_at)) + '24:00:00'::interval)))),
    CONSTRAINT iam_one_time_tokens_ttl_check CHECK ((((purpose = ANY (ARRAY['password_reset_v1'::text, 'portal_setup_v1'::text])) AND (expires_at = (created_at + '01:00:00'::interval))) OR ((purpose = ANY (ARRAY['email_verification_v1'::text, 'initial_admin_setup.v1'::text])) AND (expires_at = (created_at + '24:00:00'::interval))) OR ((purpose = 'invitation_accept_v1'::text) AND (expires_at = invitation_expires_at) AND (created_at < expires_at))))
);


