    CONSTRAINT iam_password_credentials_invalidation_check CHECK ((((state = ANY (ARRAY['active'::text, 'reset_required'::text])) AND (invalidated_at IS NULL)) OR ((state = ANY (ARRAY['disabled'::text, 'compromised'::text])) AND (invalidated_at IS NOT NULL)))),
    CONSTRAINT iam_password_credentials_revision_check CHECK ((revision > 0)),
    CONSTRAINT iam_password_credentials_shape_check CHECK ((((algorithm = 'argon2id_v1'::text) AND (salt IS NOT NULL) AND (tag IS NOT NULL) AND (memory_kib IS NOT NULL) AND (iterations IS NOT NULL) AND (parallelism IS NOT NULL) AND (octet_length(salt) = 16) AND (octet_length(tag) = 32) AND (memory_kib = 65536) AND (iterations = 3) AND (parallelism = 4) AND (legacy_bcrypt_hash IS NULL) AND (legacy_retired_by_job_id IS NULL) AND (NOT upgrade_required)) OR ((algorithm = 'bcrypt_v1_adopted'::text) AND (salt IS NULL) AND (tag IS NULL) AND (memory_kib IS NULL) AND (iterations IS NULL) AND (parallelism IS NULL) AND (legacy_bcrypt_hash IS NOT NULL) AND (legacy_retired_by_job_id IS NULL) AND (char_length(legacy_bcrypt_hash) = 60) AND (legacy_bcrypt_hash ~ '^\$2[aby]\$(0[4-9]|[12][0-9]|3[01])\$[./A-Za-z0-9]{53}$'::text) AND upgrade_required) OR ((algorithm = 'legacy_bcrypt_retired_v1'::text) AND (state = 'reset_required'::text) AND (salt IS NULL) AND (tag IS NULL) AND (memory_kib IS NULL) AND (iterations IS NULL) AND (parallelism IS NULL) AND (legacy_bcrypt_hash IS NULL) AND (legacy_retired_by_job_id IS NOT NULL) AND upgrade_required))),
    CONSTRAINT iam_password_credentials_state_check CHECK ((state = ANY (ARRAY['active'::text, 'reset_required'::text, 'disabled'::text, 'compromised'::text]))),
    CONSTRAINT iam_password_credentials_timestamp_order_check CHECK (((updated_at >= created_at) AND ((last_used_at IS NULL) OR (last_used_at >= created_at)) AND ((invalidated_at IS NULL) OR (invalidated_at >= created_at)))),
    CONSTRAINT iam_password_credentials_version_check CHECK ((credential_version > 0))
);


