    rolling_sha256 bytea NOT NULL,
    last_page_number integer,
    revision bigint NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT iam_profile_backfill_checkpoints_count_check CHECK (((completed_pages >= 0) AND (converted_count >= 0) AND (error_count >= 0) AND (revision > 0) AND (((completed_pages = 0) AND (last_page_number IS NULL)) OR ((completed_pages > 0) AND (last_page_number = completed_pages))))),
    CONSTRAINT iam_profile_backfill_checkpoints_digest_check CHECK ((octet_length(rolling_sha256) = 32))
);


