    expected_target_sha256 bytea NOT NULL,
    state text NOT NULL,
    converted_count integer NOT NULL,
    error_count integer NOT NULL,
    result_sha256 bytea,
    completed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT iam_profile_backfill_pages_digest_check CHECK (((octet_length(source_sha256) = 32) AND (octet_length(expected_target_sha256) = 32) AND ((result_sha256 IS NULL) OR (octet_length(result_sha256) = 32)))),
    CONSTRAINT iam_profile_backfill_pages_number_check CHECK (((page_number > 0) AND ((expected_count >= 0) AND (expected_count <= 250)))),
    CONSTRAINT iam_profile_backfill_pages_range_check CHECK (((through_resource_id IS NOT NULL) AND ((after_resource_id IS NULL) OR (after_resource_id < through_resource_id)))),
    CONSTRAINT iam_profile_backfill_pages_reference_check CHECK ((((octet_length(payload_reference) >= 1) AND (octet_length(payload_reference) <= 1024)) AND (octet_length(payload_sha256) = 32) AND (sha256(convert_to(payload_reference, 'UTF8'::name)) = payload_sha256))),
    CONSTRAINT iam_profile_backfill_pages_result_check CHECK (((converted_count >= 0) AND (error_count >= 0) AND ((converted_count + error_count) <= expected_count) AND (((state = 'queued'::text) AND (converted_count = 0) AND (error_count = 0) AND (result_sha256 IS NULL) AND (completed_at IS NULL)) OR ((state = ANY (ARRAY['completed'::text, 'fenced'::text])) AND (result_sha256 IS NOT NULL) AND (completed_at IS NOT NULL))))),
    CONSTRAINT iam_profile_backfill_pages_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'completed'::text, 'fenced'::text])))
);


