--
-- Name: iam_profile_backfill_plans; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.iam_profile_backfill_plans (
    id uuid NOT NULL,
    resource_kind text NOT NULL,
    source_schema_id uuid NOT NULL,
    target_schema_id uuid NOT NULL,
    converter_version text NOT NULL COLLATE pg_catalog."C",
    plan_sha256 bytea NOT NULL,
    source_count bigint NOT NULL,
    expected_source_sha256 bytea NOT NULL,
    expected_target_sha256 bytea NOT NULL,
    page_size integer NOT NULL,
    page_count integer NOT NULL,
    state text NOT NULL,
    activated_at timestamp with time zone,
    fenced_at timestamp with time zone,
    revision bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    recovery_of_plan_id uuid,
    recovery_root_plan_id uuid,
    recovery_sequence bigint,
    parent_plan_sha256 bytea,
    target_definition_sha256 bytea,
    inherited_target_count bigint,
    inherited_target_sha256 bytea,
    remaining_source_count bigint,
    remaining_source_sha256 bytea,
    expected_remaining_target_sha256 bytea,
    initial_rolling_sha256 bytea,
    CONSTRAINT iam_profile_backfill_plans_converter_check CHECK ((converter_version = 'typed_map_v1'::text)),
    CONSTRAINT iam_profile_backfill_plans_digest_check CHECK (((octet_length(plan_sha256) = 32) AND (octet_length(expected_source_sha256) = 32) AND (octet_length(expected_target_sha256) = 32))),
    CONSTRAINT iam_profile_backfill_plans_identity_check CHECK ((source_schema_id <> target_schema_id)),
    CONSTRAINT iam_profile_backfill_plans_lifecycle_check CHECK ((((state = ANY (ARRAY['planned'::text, 'running'::text, 'verified'::text])) AND (activated_at IS NULL) AND (fenced_at IS NULL)) OR ((state = 'activated'::text) AND (activated_at IS NOT NULL) AND (fenced_at IS NULL)) OR ((state = 'fenced'::text) AND (activated_at IS NULL) AND (fenced_at IS NOT NULL)))),
    CONSTRAINT iam_profile_backfill_plans_page_check CHECK (((source_count >= 0) AND ((page_size >= 1) AND (page_size <= 250)) AND (revision > 0) AND (((recovery_of_plan_id IS NULL) AND (page_count >= 1)) OR ((recovery_of_plan_id IS NOT NULL) AND (page_count >= 0))))),
    CONSTRAINT iam_profile_backfill_plans_recovery_count_check CHECK (((recovery_of_plan_id IS NULL) OR ((inherited_target_count >= 0) AND (remaining_source_count >= 0) AND (source_count = remaining_source_count) AND (expected_source_sha256 = remaining_source_sha256) AND (expected_target_sha256 = expected_remaining_target_sha256) AND (((remaining_source_count = 0) AND (page_count = 0) AND (remaining_source_sha256 = sha256('\x'::bytea)) AND (expected_remaining_target_sha256 = initial_rolling_sha256)) OR ((remaining_source_count > 0) AND ((page_count >= 1) AND (page_count <= 65536))))))),
    CONSTRAINT iam_profile_backfill_plans_recovery_digest_check CHECK (((recovery_of_plan_id IS NULL) OR ((octet_length(parent_plan_sha256) = 32) AND (octet_length(target_definition_sha256) = 32) AND (octet_length(inherited_target_sha256) = 32) AND (octet_length(remaining_source_sha256) = 32) AND (octet_length(expected_remaining_target_sha256) = 32) AND (octet_length(initial_rolling_sha256) = 32)))),
    CONSTRAINT iam_profile_backfill_plans_recovery_identity_check CHECK (((recovery_of_plan_id IS NULL) OR ((recovery_of_plan_id <> id) AND (recovery_root_plan_id <> id) AND (recovery_sequence > 0)))),
    CONSTRAINT iam_profile_backfill_plans_recovery_presence_check CHECK ((((recovery_of_plan_id IS NULL) AND (recovery_root_plan_id IS NULL) AND (recovery_sequence IS NULL) AND (parent_plan_sha256 IS NULL) AND (target_definition_sha256 IS NULL) AND (inherited_target_count IS NULL) AND (inherited_target_sha256 IS NULL) AND (remaining_source_count IS NULL) AND (remaining_source_sha256 IS NULL) AND (expected_remaining_target_sha256 IS NULL) AND (initial_rolling_sha256 IS NULL)) OR ((recovery_of_plan_id IS NOT NULL) AND (recovery_root_plan_id IS NOT NULL) AND (recovery_sequence IS NOT NULL) AND (parent_plan_sha256 IS NOT NULL) AND (target_definition_sha256 IS NOT NULL) AND (inherited_target_count IS NOT NULL) AND (inherited_target_sha256 IS NOT NULL) AND (remaining_source_count IS NOT NULL) AND (remaining_source_sha256 IS NOT NULL) AND (expected_remaining_target_sha256 IS NOT NULL) AND (initial_rolling_sha256 IS NOT NULL)))),
    CONSTRAINT iam_profile_backfill_plans_resource_check CHECK ((resource_kind = ANY (ARRAY['user'::text, 'organization'::text, 'role'::text]))),
    CONSTRAINT iam_profile_backfill_plans_state_check CHECK ((state = ANY (ARRAY['planned'::text, 'running'::text, 'verified'::text, 'activated'::text, 'fenced'::text]))),
    CONSTRAINT iam_profile_backfill_plans_time_check CHECK (((updated_at >= created_at) AND ((activated_at IS NULL) OR (activated_at >= created_at)) AND ((fenced_at IS NULL) OR (fenced_at >= created_at))))
);


ALTER TABLE __tenant_schema__.iam_profile_backfill_plans OWNER TO harpy_owner;

