    CONSTRAINT iam_profile_field_revisions_value_kind_check CHECK ((value_kind = ANY (ARRAY['string'::text, 'integer'::text, 'decimal'::text, 'boolean'::text, 'date'::text, 'timestamp'::text, 'uuid'::text, 'enum'::text, 'json'::text])))
);


