--
-- Name: iam_profile_recovery_resources_v1; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.iam_profile_recovery_resources_v1 AS
 SELECT 'user'::text AS resource_kind,
    usr.id AS resource_id,
    usr.profile_schema_version_id AS schema_version_id,
    usr.revision AS resource_revision,
    usr.profile_values,
    usr.profile_sha256
   FROM __tenant_schema__.iam_users usr
UNION ALL
 SELECT 'organization'::text AS resource_kind,
    organization.id AS resource_id,
    organization.profile_schema_version_id AS schema_version_id,
    organization.revision AS resource_revision,
    organization.profile_values,
    organization.profile_sha256
   FROM __tenant_schema__.iam_organizations organization
UNION ALL
 SELECT 'role'::text AS resource_kind,
    role.id AS resource_id,
    role.profile_schema_version_id AS schema_version_id,
    role.revision AS resource_revision,
    role.profile_values,
    role.profile_sha256
   FROM __tenant_schema__.iam_roles role;


ALTER VIEW __tenant_schema__.iam_profile_recovery_resources_v1 OWNER TO harpy_owner;

