    CONSTRAINT iam_profile_schema_versions_timestamp_order_check CHECK (((updated_at >= created_at) AND ((activated_at IS NULL) OR (activated_at >= created_at)) AND ((retired_at IS NULL) OR (retired_at >= updated_at)))),
    CONSTRAINT iam_profile_schema_versions_version_check CHECK ((version > 0))
);


