    user_id uuid NOT NULL,
    authenticator_kind text NOT NULL,
    "position" smallint NOT NULL,
    hash_profile text NOT NULL,
    hmac_key_id text NOT NULL COLLATE pg_catalog."C",
    code_hmac bytea NOT NULL,
    state text NOT NULL,
    revision bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    revoked_at timestamp with time zone,
    purge_after timestamp with time zone,
    CONSTRAINT iam_recovery_codes_hash_profile_check CHECK ((hash_profile = 'hmac_sha256_v1'::text)),
    CONSTRAINT iam_recovery_codes_hmac_check CHECK ((octet_length(code_hmac) = 32)),
    CONSTRAINT iam_recovery_codes_hmac_key_id_check CHECK (__tenant_schema__.iam_hmac_key_id_valid_v1(hmac_key_id)),
    CONSTRAINT iam_recovery_codes_kind_check CHECK ((authenticator_kind = 'recovery_set_v1'::text)),
    CONSTRAINT iam_recovery_codes_lifecycle_check CHECK ((((state = 'active'::text) AND (consumed_at IS NULL) AND (revoked_at IS NULL) AND (purge_after IS NULL)) OR ((state = 'consumed'::text) AND (consumed_at IS NOT NULL) AND (revoked_at IS NULL) AND (purge_after IS NOT NULL) AND (purge_after = (consumed_at + '30 days'::interval))) OR ((state = 'revoked'::text) AND (consumed_at IS NULL) AND (revoked_at IS NOT NULL) AND (purge_after IS NOT NULL) AND (purge_after = (revoked_at + '30 days'::interval))))),
    CONSTRAINT iam_recovery_codes_position_check CHECK ((("position" >= 1) AND ("position" <= 32))),
    CONSTRAINT iam_recovery_codes_revision_check CHECK ((revision > 0)),
    CONSTRAINT iam_recovery_codes_state_check CHECK ((state = ANY (ARRAY['active'::text, 'consumed'::text, 'revoked'::text]))),
    CONSTRAINT iam_recovery_codes_timestamp_check CHECK (((updated_at >= created_at) AND ((consumed_at IS NULL) OR ((consumed_at >= created_at) AND (consumed_at <= updated_at))) AND ((revoked_at IS NULL) OR ((revoked_at >= created_at) AND (revoked_at <= updated_at)))))
);


