--
-- Name: iam_refresh_families; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.iam_refresh_families (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    session_id uuid NOT NULL,
    state text NOT NULL,
    rotation_sequence bigint NOT NULL,
    revoke_reason text COLLATE pg_catalog."C",
    revision bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    absolute_expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    compromised_at timestamp with time zone,
    expired_at timestamp with time zone,
    retain_until timestamp with time zone NOT NULL,
    security_epoch bytea DEFAULT __tenant_schema__.iam_security_epoch_current_v1("current_schema"()) NOT NULL,
    CONSTRAINT iam_refresh_families_counter_check CHECK (((rotation_sequence >= 0) AND (revision > 0))),
    CONSTRAINT iam_refresh_families_lifecycle_check CHECK ((((state = 'active'::text) AND (revoke_reason IS NULL) AND (revoked_at IS NULL) AND (compromised_at IS NULL) AND (expired_at IS NULL)) OR ((state = 'revoked'::text) AND (revoke_reason IS NOT NULL) AND (revoked_at IS NOT NULL) AND (compromised_at IS NULL) AND (expired_at IS NULL)) OR ((state = 'compromised'::text) AND (revoke_reason IS NOT NULL) AND (revoked_at IS NULL) AND (compromised_at IS NOT NULL) AND (expired_at IS NULL)) OR ((state = 'expired'::text) AND (revoke_reason IS NULL) AND (revoked_at IS NULL) AND (compromised_at IS NULL) AND (expired_at = absolute_expires_at)))),
    CONSTRAINT iam_refresh_families_reason_check CHECK (((revoke_reason IS NULL) OR (((char_length(revoke_reason) >= 1) AND (char_length(revoke_reason) <= 64)) AND (revoke_reason ~ '^[a-z0-9][a-z0-9._-]*$'::text)))),
    CONSTRAINT iam_refresh_families_security_epoch_ck CHECK ((octet_length(security_epoch) = 32)),
    CONSTRAINT iam_refresh_families_state_check CHECK ((state = ANY (ARRAY['active'::text, 'revoked'::text, 'compromised'::text, 'expired'::text]))),
    CONSTRAINT iam_refresh_families_time_check CHECK (((updated_at >= created_at) AND (absolute_expires_at = (created_at + '90 days'::interval)) AND ((revoked_at IS NULL) OR ((revoked_at >= created_at) AND (revoked_at <= updated_at))) AND ((compromised_at IS NULL) OR ((compromised_at >= created_at) AND (compromised_at <= updated_at))) AND ((expired_at IS NULL) OR (expired_at <= updated_at)) AND (retain_until >= (absolute_expires_at + '24:00:00'::interval))))
);


ALTER TABLE __tenant_schema__.iam_refresh_families OWNER TO harpy_owner;

--
-- Name: iam_refresh_tokens; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.iam_refresh_tokens (
    id uuid NOT NULL,
    family_id uuid NOT NULL,
    family_absolute_expires_at timestamp with time zone NOT NULL,
    parent_id uuid,
    parent_sequence bigint,
    selector bytea NOT NULL,
    hash_key_id text NOT NULL COLLATE pg_catalog."C",
    secret_hmac bytea NOT NULL,
    sequence bigint NOT NULL,
    auth_time timestamp with time zone NOT NULL,
    acr text NOT NULL,
    amr_password boolean NOT NULL,
    amr_webauthn boolean NOT NULL,
    amr_totp boolean NOT NULL,
    amr_recovery boolean NOT NULL,
    step_up_purpose_sha256 bytea,
    state text NOT NULL,
    revision bigint NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    idle_expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    revoked_at timestamp with time zone,
    expired_at timestamp with time zone,
    retain_until timestamp with time zone NOT NULL,
    security_epoch bytea DEFAULT __tenant_schema__.iam_security_epoch_current_v1("current_schema"()) NOT NULL,
    CONSTRAINT iam_refresh_tokens_auth_context_check CHECK (((acr = ANY (ARRAY['login'::text, 'mfa'::text, 'step_up'::text])) AND (amr_password OR amr_webauthn OR amr_totp OR amr_recovery) AND (((acr = ANY (ARRAY['login'::text, 'mfa'::text])) AND (step_up_purpose_sha256 IS NULL)) OR ((acr = 'step_up'::text) AND (NOT amr_recovery) AND (amr_password OR amr_webauthn OR amr_totp) AND (step_up_purpose_sha256 IS NOT NULL) AND (octet_length(step_up_purpose_sha256) = 32))))),
    CONSTRAINT iam_refresh_tokens_lifecycle_check CHECK ((((state = 'active'::text) AND (consumed_at IS NULL) AND (revoked_at IS NULL) AND (expired_at IS NULL)) OR ((state = 'consumed'::text) AND (consumed_at IS NOT NULL) AND (revoked_at IS NULL) AND (expired_at IS NULL)) OR ((state = 'revoked'::text) AND (consumed_at IS NULL) AND (revoked_at IS NOT NULL) AND (expired_at IS NULL)) OR ((state = 'expired'::text) AND (consumed_at IS NULL) AND (revoked_at IS NULL) AND (expired_at = idle_expires_at)))),
    CONSTRAINT iam_refresh_tokens_parent_check CHECK ((((sequence = 1) AND (parent_id IS NULL) AND (parent_sequence IS NULL)) OR ((sequence > 1) AND (parent_id IS NOT NULL) AND (parent_sequence IS NOT NULL) AND (parent_id <> id) AND (sequence = (parent_sequence + 1))))),
    CONSTRAINT iam_refresh_tokens_revision_check CHECK (((sequence > 0) AND (revision > 0))),
    CONSTRAINT iam_refresh_tokens_secret_check CHECK (((octet_length(selector) = 16) AND __tenant_schema__.iam_hmac_key_id_valid_v1(hash_key_id) AND (octet_length(secret_hmac) = 32))),
    CONSTRAINT iam_refresh_tokens_security_epoch_ck CHECK ((octet_length(security_epoch) = 32)),
    CONSTRAINT iam_refresh_tokens_state_check CHECK ((state = ANY (ARRAY['active'::text, 'consumed'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT iam_refresh_tokens_time_check CHECK (((updated_at >= issued_at) AND (auth_time <= issued_at) AND (family_absolute_expires_at > issued_at) AND (idle_expires_at > issued_at) AND (idle_expires_at <= (issued_at + '30 days'::interval)) AND (idle_expires_at <= family_absolute_expires_at) AND ((consumed_at IS NULL) OR ((consumed_at >= issued_at) AND (consumed_at <= updated_at))) AND ((revoked_at IS NULL) OR ((revoked_at >= issued_at) AND (revoked_at <= updated_at))) AND ((expired_at IS NULL) OR (expired_at <= updated_at)) AND (retain_until >= (family_absolute_expires_at + '24:00:00'::interval))))
);


ALTER TABLE __tenant_schema__.iam_refresh_tokens OWNER TO harpy_owner;

--
-- Name: iam_resources; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
