    CONSTRAINT iam_resources_kind_check CHECK ((((char_length(resource_kind) >= 1) AND (char_length(resource_kind) <= 100)) AND (resource_kind ~ '^[a-z][a-z0-9_]*$'::text))),
    CONSTRAINT iam_resources_owner_domain_check CHECK ((((char_length(owner_domain) >= 1) AND (char_length(owner_domain) <= 100)) AND (owner_domain ~ '^[a-z][a-z0-9_]*$'::text))),
    CONSTRAINT iam_resources_platform_scope_ck CHECK ((resource_key !~ '^platform\.'::text)),
