           FROM __tenant_schema__.iam_organization_memberships membership
          WHERE ((membership.organization_id = organization.id) AND (membership.state = 'active'::text))), ARRAY[]::uuid[]) AS user_ids,
    COALESCE(( SELECT array_agg(role.id ORDER BY role.id) AS array_agg
           FROM __tenant_schema__.iam_roles role
          WHERE ((role.organization_id = organization.id) AND (role.status = 'active'::text))), ARRAY[]::uuid[]) AS role_ids,
    profile_schema_version_id,
    profile_values,
    revision,
    created_at,
    updated_at,
    "normalize"(casefold(("normalize"(name, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS name_folded,
    "normalize"(casefold(("normalize"(slug, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS slug_folded,
    COALESCE(( SELECT array_agg(membership.user_id ORDER BY membership.user_id) AS array_agg
           FROM __tenant_schema__.iam_organization_memberships membership
          WHERE ((membership.organization_id = organization.id) AND (membership.membership_kind = 'owner'::text) AND (membership.state = 'active'::text))), ARRAY[]::uuid[]) AS owner_ids
   FROM __tenant_schema__.iam_organizations organization
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


