-- Name: iam_rest_query_roles_v2; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.iam_rest_query_roles_v2 AS
 SELECT id,
    scope_kind,
    scope_id,
    organization_id,
    name,
    description,
    status,
    is_protected,
    is_default,
    COALESCE(( SELECT array_agg(assignment.user_id ORDER BY assignment.user_id) AS array_agg
           FROM __tenant_schema__.iam_user_role_assignments assignment
          WHERE ((assignment.role_id = role.id) AND (assignment.state = 'active'::text))), ARRAY[]::uuid[]) AS user_ids,
    profile_schema_version_id,
    profile_values,
    revision,
    created_at,
    updated_at,
    "normalize"(casefold(("normalize"(name, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS name_folded,
    "normalize"(casefold(("normalize"(description, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS description_folded
   FROM __tenant_schema__.iam_roles role
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


