-- Name: iam_user_identifiers; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.iam_user_identifiers (
    id uuid NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    display_value text NOT NULL,
    normalized_value text NOT NULL COLLATE pg_catalog."C",
    normalized_sha256 bytea NOT NULL,
    state text NOT NULL,
    revision bigint NOT NULL,
    verified_at timestamp with time zone,
    activated_at timestamp with time zone,
    tombstoned_at timestamp with time zone,
    cooldown_until timestamp with time zone,
    retired_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT iam_user_identifiers_display_check CHECK (((char_length(display_value) >= 1) AND (char_length(display_value) <= 320))),
    CONSTRAINT iam_user_identifiers_kind_check CHECK ((kind = ANY (ARRAY['email_v1'::text, 'portal_v1'::text]))),
    CONSTRAINT iam_user_identifiers_lifecycle_check CHECK ((((state = 'pending'::text) AND (verified_at IS NULL) AND (activated_at IS NULL) AND (tombstoned_at IS NULL) AND (cooldown_until IS NULL) AND (retired_at IS NULL)) OR ((state = 'verified'::text) AND (verified_at IS NOT NULL) AND (verified_at >= created_at) AND (activated_at IS NULL) AND (tombstoned_at IS NULL) AND (cooldown_until IS NULL) AND (retired_at IS NULL)) OR ((state = 'active'::text) AND (verified_at IS NOT NULL) AND (activated_at IS NOT NULL) AND (verified_at >= created_at) AND (activated_at >= verified_at) AND (tombstoned_at IS NULL) AND (cooldown_until IS NULL) AND (retired_at IS NULL)) OR ((state = 'tombstoned'::text) AND (verified_at IS NOT NULL) AND (activated_at IS NOT NULL) AND (tombstoned_at IS NOT NULL) AND (cooldown_until IS NOT NULL) AND (verified_at >= created_at) AND (activated_at >= verified_at) AND (tombstoned_at >= activated_at) AND (cooldown_until = (tombstoned_at + '30 days'::interval)) AND (retired_at IS NULL)) OR ((state = 'retired'::text) AND (verified_at IS NOT NULL) AND (activated_at IS NOT NULL) AND (tombstoned_at IS NOT NULL) AND (cooldown_until IS NOT NULL) AND (retired_at IS NOT NULL) AND (verified_at >= created_at) AND (activated_at >= verified_at) AND (tombstoned_at >= activated_at) AND (cooldown_until = (tombstoned_at + '30 days'::interval)) AND (retired_at >= cooldown_until)))),
    CONSTRAINT iam_user_identifiers_normalized_check CHECK ((((kind = 'email_v1'::text) AND ((octet_length(normalized_value) >= 3) AND (octet_length(normalized_value) <= 254))) OR ((kind = 'portal_v1'::text) AND ((char_length(normalized_value) >= 1) AND (char_length(normalized_value) <= 100))))),
    CONSTRAINT iam_user_identifiers_normalized_sha256_check CHECK ((octet_length(normalized_sha256) = 32)),
    CONSTRAINT iam_user_identifiers_revision_check CHECK ((revision > 0)),
    CONSTRAINT iam_user_identifiers_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'verified'::text, 'active'::text, 'tombstoned'::text, 'retired'::text]))),
    CONSTRAINT iam_user_identifiers_timestamp_order_check CHECK ((updated_at >= created_at))
);


