--
-- Name: iam_rest_query_users_v1; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.iam_rest_query_users_v1 AS
 SELECT id,
    ( SELECT identifier.display_value
           FROM __tenant_schema__.iam_user_identifiers identifier
          WHERE ((identifier.user_id = principal.id) AND (identifier.kind = 'email_v1'::text) AND (identifier.state = 'active'::text))) AS email,
    ( SELECT identifier.display_value
           FROM __tenant_schema__.iam_user_identifiers identifier
          WHERE ((identifier.user_id = principal.id) AND (identifier.kind = 'portal_v1'::text) AND (identifier.state = 'active'::text))) AS portal_identifier,
    status,
    identity_kind,
    COALESCE(( SELECT array_agg(assignment.role_id ORDER BY assignment.role_id) AS array_agg
           FROM __tenant_schema__.iam_user_role_assignments assignment
          WHERE ((assignment.user_id = principal.id) AND (assignment.state = 'active'::text))), ARRAY[]::uuid[]) AS role_ids,
    COALESCE(( SELECT array_agg(membership.organization_id ORDER BY membership.organization_id) AS array_agg
           FROM __tenant_schema__.iam_organization_memberships membership
          WHERE ((membership.user_id = principal.id) AND (membership.state = 'active'::text))), ARRAY[]::uuid[]) AS organization_ids,
    profile_schema_version_id,
    profile_values,
    revision,
    created_at,
    updated_at
   FROM __tenant_schema__.iam_users principal
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW __tenant_schema__.iam_rest_query_users_v1 OWNER TO harpy_owner;

--
-- Name: iam_rest_query_users_v2; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.iam_rest_query_users_v2 AS
 SELECT principal.id,
    ( SELECT identifier.display_value
           FROM __tenant_schema__.iam_user_identifiers identifier
          WHERE ((identifier.user_id = principal.id) AND (identifier.kind = 'email_v1'::text) AND (identifier.state = 'active'::text))) AS email,
    ( SELECT identifier.display_value
           FROM __tenant_schema__.iam_user_identifiers identifier
          WHERE ((identifier.user_id = principal.id) AND (identifier.kind = 'portal_v1'::text) AND (identifier.state = 'active'::text))) AS portal_identifier,
    principal.status,
    principal.identity_kind,
    COALESCE(( SELECT array_agg(assignment.role_id ORDER BY assignment.role_id) AS array_agg
           FROM __tenant_schema__.iam_user_role_assignments assignment
          WHERE ((assignment.user_id = principal.id) AND (assignment.state = 'active'::text))), ARRAY[]::uuid[]) AS role_ids,
    COALESCE(( SELECT array_agg(membership.organization_id ORDER BY membership.organization_id) AS array_agg
           FROM __tenant_schema__.iam_organization_memberships membership
          WHERE ((membership.user_id = principal.id) AND (membership.state = 'active'::text))), ARRAY[]::uuid[]) AS organization_ids,
    principal.profile_schema_version_id,
    principal.profile_values,
    principal.revision,
    principal.created_at,
    principal.updated_at,
    "normalize"(profile_display.value, 'NFC'::text) AS display_name,
    "normalize"(casefold(("normalize"(profile_display.value, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS display_name_folded
   FROM (__tenant_schema__.iam_users principal
     LEFT JOIN LATERAL ( SELECT COALESCE(NULLIF((principal.profile_values ->> (profile_field.id)::text), ''::text), NULLIF((principal.profile_values ->> 'display_name'::text), ''::text)) AS value
           FROM __tenant_schema__.iam_profile_fields profile_field
          WHERE ((profile_field.resource_kind = 'user'::text) AND (profile_field.field_key = 'display_name'::text) AND (profile_field.value_kind = 'string'::text) AND (profile_field.cardinality = 'single'::text) AND (profile_field.classification = 'public'::text) AND (profile_field.state = 'active'::text))) profile_display ON (true))
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW __tenant_schema__.iam_rest_query_users_v2 OWNER TO harpy_owner;

