    CONSTRAINT iam_service_principals_key_check CHECK ((((char_length(principal_key) >= 3) AND (char_length(principal_key) <= 100)) AND (principal_key ~ '^[a-z][a-z0-9]*([._-][a-z0-9]+)*$'::text))),
