    CONSTRAINT iam_sessions_lifecycle_check CHECK ((((state = 'active'::text) AND (revoked_at IS NULL) AND (expired_at IS NULL)) OR ((state = 'revoked'::text) AND (revoked_at IS NOT NULL) AND (expired_at IS NULL)) OR ((state = 'expired'::text) AND (revoked_at IS NULL) AND (expired_at = absolute_expires_at)))),
    CONSTRAINT iam_sessions_revision_check CHECK ((revision > 0)),
    CONSTRAINT iam_sessions_security_epoch_ck CHECK ((octet_length(security_epoch) = 32)),
    CONSTRAINT iam_sessions_state_check CHECK ((state = ANY (ARRAY['active'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT iam_sessions_surface_check CHECK ((((access_mode = 'operator_console'::text) AND (portal_binding_id IS NULL)) OR ((access_mode = 'portal'::text) AND (portal_binding_id IS NOT NULL)))),
