--
-- Name: iam_system_import_sources; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.iam_system_import_sources (
    source_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    idempotency_receipt_id uuid NOT NULL,
    resource_kind text NOT NULL,
    actor_id uuid NOT NULL,
    idempotency_key_sha256 bytea NOT NULL,
    format text NOT NULL,
    object_key text NOT NULL,
    object_version text NOT NULL,
    header_sha256 bytea NOT NULL,
    ciphertext_sha256 bytea NOT NULL,
    ciphertext_bytes bigint NOT NULL,
    plaintext_sha256 bytea NOT NULL,
    plaintext_bytes bigint NOT NULL,
    key_id text NOT NULL,
    wrapped_dek bytea NOT NULL,
    wrap_nonce bytea NOT NULL,
    provider_request_id text NOT NULL,
    uploaded_at timestamp with time zone NOT NULL,
    state text DEFAULT 'ready'::text NOT NULL,
    claimed_import_id uuid,
    claimed_at timestamp with time zone,
    delete_after timestamp with time zone NOT NULL,
    deleted_at timestamp with time zone,
    delete_provider_request_id text,
    delete_response_sha256 bytea,
    absence_probe_sha256 bytea,
    verified_absent_at timestamp with time zone,
    cleanup_state text DEFAULT 'waiting'::text NOT NULL,
    cleanup_attempts integer DEFAULT 0 NOT NULL,
    cleanup_next_at timestamp with time zone NOT NULL,
    cleanup_lease_owner uuid,
    cleanup_lease_generation bigint DEFAULT 0 NOT NULL,
    cleanup_lease_until timestamp with time zone,
    cleanup_last_error_code text,
    CONSTRAINT iam_system_import_sources_cleanup_check CHECK ((((cleanup_attempts >= 0) AND (cleanup_attempts <= 2147483647)) AND (cleanup_lease_generation >= 0) AND isfinite(cleanup_next_at) AND ((cleanup_last_error_code IS NULL) OR (cleanup_last_error_code = ANY (ARRAY['SOURCE_DELETE_OUTCOME_UNKNOWN'::text, 'SOURCE_DELETE_UNAVAILABLE'::text]))) AND (((state = 'deleted'::text) AND (cleanup_state = 'succeeded'::text) AND (cleanup_lease_owner IS NULL) AND (cleanup_lease_until IS NULL)) OR ((state = ANY (ARRAY['ready'::text, 'claimed'::text])) AND (cleanup_state = 'waiting'::text) AND (cleanup_lease_owner IS NULL) AND (cleanup_lease_until IS NULL)) OR ((state = ANY (ARRAY['ready'::text, 'claimed'::text])) AND (cleanup_state = 'running'::text) AND (cleanup_attempts > 0) AND (cleanup_lease_generation > 0) AND (uuid_extract_version(cleanup_lease_owner) = 7) AND (cleanup_lease_until IS NOT NULL) AND isfinite(cleanup_lease_until))))),
    CONSTRAINT iam_system_import_sources_identity_check CHECK (((uuid_extract_version(source_id) = 7) AND (uuid_extract_version(idempotency_receipt_id) = 7) AND (tenant_id <> '00000000-0000-0000-0000-000000000000'::uuid) AND (actor_id <> '00000000-0000-0000-0000-000000000000'::uuid))),
    CONSTRAINT iam_system_import_sources_object_check CHECK (((resource_kind = ANY (ARRAY['users'::text, 'roles'::text, 'organizations'::text])) AND (octet_length(idempotency_key_sha256) = 32) AND (format = ANY (ARRAY['csv'::text, 'jsonl'::text])) AND ((octet_length(object_key) >= 1) AND (octet_length(object_key) <= 512)) AND ((octet_length(object_version) >= 1) AND (octet_length(object_version) <= 512)) AND (octet_length(header_sha256) = 32) AND (octet_length(ciphertext_sha256) = 32) AND ((ciphertext_bytes >= 1) AND (ciphertext_bytes <= 538968064)) AND (octet_length(plaintext_sha256) = 32) AND ((plaintext_bytes >= 1) AND (plaintext_bytes <= 536870912)) AND ((octet_length(key_id) >= 1) AND (octet_length(key_id) <= 128)) AND ((octet_length(wrapped_dek) >= 32) AND (octet_length(wrapped_dek) <= 1024)) AND (octet_length(wrap_nonce) = 12) AND ((octet_length(provider_request_id) >= 1) AND (octet_length(provider_request_id) <= 256)))),
    CONSTRAINT iam_system_import_sources_state_check CHECK ((((state = 'ready'::text) AND (claimed_import_id IS NULL) AND (claimed_at IS NULL) AND (deleted_at IS NULL) AND (delete_provider_request_id IS NULL) AND (delete_response_sha256 IS NULL) AND (absence_probe_sha256 IS NULL) AND (verified_absent_at IS NULL)) OR ((state = 'claimed'::text) AND (uuid_extract_version(claimed_import_id) = 7) AND (claimed_at IS NOT NULL) AND (deleted_at IS NULL) AND (delete_provider_request_id IS NULL) AND (delete_response_sha256 IS NULL) AND (absence_probe_sha256 IS NULL) AND (verified_absent_at IS NULL)) OR ((state = 'deleted'::text) AND (deleted_at IS NOT NULL) AND ((octet_length(delete_provider_request_id) >= 1) AND (octet_length(delete_provider_request_id) <= 256)) AND (octet_length(delete_response_sha256) = 32) AND (octet_length(absence_probe_sha256) = 32) AND (verified_absent_at IS NOT NULL)))),
    CONSTRAINT iam_system_import_sources_time_check CHECK ((isfinite(uploaded_at) AND (delete_after = (uploaded_at + '24:00:00'::interval)) AND ((claimed_at IS NULL) OR (claimed_at >= uploaded_at)) AND ((deleted_at IS NULL) OR (deleted_at >= uploaded_at)) AND ((verified_absent_at IS NULL) OR (isfinite(verified_absent_at) AND (verified_absent_at = deleted_at)))))
);


