--
-- Name: work_query_board_visibility_v1; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.work_query_board_visibility_v1 AS
 SELECT board_id,
    array_agg(DISTINCT ((principal_kind || ':'::text) || (principal_id)::text) ORDER BY ((principal_kind || ':'::text) || (principal_id)::text)) AS visibility_principals
   FROM __tenant_schema__.work_board_memberships membership
  WHERE active
  GROUP BY board_id;


ALTER VIEW __tenant_schema__.work_query_board_visibility_v1 OWNER TO harpy_owner;

