    board_id uuid NOT NULL,
    column_id uuid NOT NULL,
    task_kind text NOT NULL,
    status_category text NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    "position" bigint NOT NULL,
    row_version bigint NOT NULL,
    due_at timestamp with time zone,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    deleted_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    creator_user_id uuid NOT NULL,
    priority text DEFAULT 'MEDIUM'::text NOT NULL,
    starts_at timestamp with time zone,
    CONSTRAINT work_tasks_check CHECK (((status_category = 'DONE'::text) = (completed_at IS NOT NULL))),
    CONSTRAINT work_tasks_check1 CHECK (((status_category = 'CANCELLED'::text) = (cancelled_at IS NOT NULL))),
    CONSTRAINT work_tasks_description_check CHECK ((octet_length(description) <= 64000)),
    CONSTRAINT work_tasks_position_check CHECK (("position" > 0)),
    CONSTRAINT work_tasks_priority_check CHECK ((priority = ANY (ARRAY['LOW'::text, 'MEDIUM'::text, 'HIGH'::text, 'URGENT'::text]))),
    CONSTRAINT work_tasks_row_version_check CHECK ((row_version > 0)),
    CONSTRAINT work_tasks_status_category_check CHECK ((status_category = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'IN_REVIEW'::text, 'DONE'::text, 'CANCELLED'::text]))),
    CONSTRAINT work_tasks_task_kind_check CHECK ((task_kind = ANY (ARRAY['CUSTOM'::text, 'FORM_FILL'::text, 'FORM_REVIEW'::text]))),
    CONSTRAINT work_tasks_title_check CHECK (((octet_length(title) >= 1) AND (octet_length(title) <= 1200)))
);


ALTER TABLE __tenant_schema__.work_tasks OWNER TO harpy_owner;

--
-- Name: work_board_query_v1; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.work_board_query_v1 AS
 SELECT board.id,
    board.name,
    "normalize"(casefold(("normalize"(board.name, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS name_folded,
    board.description,
    board.creator_user_id AS creator_id,
    board.lifecycle_state AS lifecycle,
    board.row_version,
    ( SELECT count(*) AS count
           FROM __tenant_schema__.work_tasks task
          WHERE ((task.board_id = board.id) AND (task.deleted_at IS NULL))) AS task_count,
    ( SELECT count(*) AS count
           FROM __tenant_schema__.work_board_memberships member_row
          WHERE ((member_row.board_id = board.id) AND member_row.active)) AS member_count,
    board.created_at,
    board.updated_at,
    visibility.visibility_principals
   FROM (__tenant_schema__.work_boards board
     JOIN __tenant_schema__.work_query_board_visibility_v1 visibility ON ((visibility.board_id = board.id)))
  WHERE ((NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW __tenant_schema__.work_board_query_v1 OWNER TO harpy_owner;

