    color text DEFAULT '#64748b'::text NOT NULL,
    CONSTRAINT work_calendar_events_audience_check CHECK ((audience = ANY (ARRAY['PRIVATE'::text, 'BOARD'::text, 'ORGANIZATION'::text]))),
    CONSTRAINT work_calendar_events_check CHECK ((((starts_at IS NOT NULL) AND (ends_at > starts_at) AND (start_date IS NULL) AND (end_date IS NULL)) OR ((starts_at IS NULL) AND (ends_at IS NULL) AND (start_date IS NOT NULL) AND (end_date > start_date)))),
    CONSTRAINT work_calendar_events_check1 CHECK ((((audience = 'PRIVATE'::text) AND (board_id IS NULL) AND (organization_id IS NULL)) OR ((audience = 'BOARD'::text) AND (board_id IS NOT NULL) AND (organization_id IS NULL)) OR ((audience = 'ORGANIZATION'::text) AND (board_id IS NULL) AND (organization_id IS NOT NULL)))),
    CONSTRAINT work_calendar_events_check2 CHECK ((((NOT generated) AND (rule_id IS NULL) AND (rule_revision IS NULL) AND (occurrence_start IS NULL) AND (tzdb_version IS NULL) AND (generated_state IS NULL)) OR (generated AND (rule_id IS NOT NULL) AND (rule_revision IS NOT NULL) AND (occurrence_start IS NOT NULL) AND (tzdb_version IS NOT NULL) AND (generated_state IS NOT NULL)))),
    CONSTRAINT work_calendar_events_color_check CHECK ((color ~ '^#[0-9a-f]{6}$'::text)),
    CONSTRAINT work_calendar_events_description_check CHECK ((octet_length(description) <= 64000)),
    CONSTRAINT work_calendar_events_generated_state_check CHECK ((generated_state = ANY (ARRAY['ACTIVE'::text, 'CANCELLED'::text, 'CONTENT_PURGED'::text]))),
    CONSTRAINT work_calendar_events_live_reference_count_check CHECK ((live_reference_count >= 0)),
    CONSTRAINT work_calendar_events_row_version_check CHECK ((row_version > 0)),
    CONSTRAINT work_calendar_events_title_check CHECK (((octet_length(title) >= 1) AND (octet_length(title) <= 1200)))
);


ALTER TABLE __tenant_schema__.work_calendar_events OWNER TO harpy_owner;

--
-- Name: work_calendar_event_query_v1; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.work_calendar_event_query_v1 AS
 SELECT event.id,
    event.owner_id,
    event.audience,
    event.board_id,
    event.organization_id,
    event.title,
    "normalize"(casefold(("normalize"(event.title, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS title_folded,
    event.description,
    event.color,
    event.starts_at,
    event.ends_at,
    event.start_date,
    event.end_date,
    event.timezone_name AS timezone,
    event.generated,
    event.row_version,
    event.created_at,
    event.updated_at,
        CASE event.audience
            WHEN 'PRIVATE'::text THEN ARRAY[('USER:'::text || (event.owner_id)::text)]
            WHEN 'ORGANIZATION'::text THEN ARRAY[('ORGANIZATION:'::text || (event.organization_id)::text)]
            ELSE COALESCE(visibility.visibility_principals, ARRAY[]::text[])
        END AS visibility_principals
   FROM (__tenant_schema__.work_calendar_events event
     LEFT JOIN __tenant_schema__.work_query_board_visibility_v1 visibility ON ((visibility.board_id = event.board_id)))
  WHERE ((event.deleted_at IS NULL) AND (NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW __tenant_schema__.work_calendar_event_query_v1 OWNER TO harpy_owner;

