    CONSTRAINT work_calendar_items_event_sequence_check CHECK ((event_sequence > 0)),
    CONSTRAINT work_calendar_items_permission_revision_check CHECK ((permission_revision > 0)),
    CONSTRAINT work_calendar_items_source_owner_check CHECK ((source_owner = ANY (ARRAY['WORK'::text, 'WORKFLOW'::text, 'FORMS'::text]))),
    CONSTRAINT work_calendar_items_source_revision_check CHECK ((source_revision > 0)),
    CONSTRAINT work_calendar_items_state_check CHECK ((state = ANY (ARRAY['VISIBLE'::text, 'STALE'::text, 'REVOKED'::text]))),
    CONSTRAINT work_calendar_items_summary_check CHECK ((octet_length(summary) <= 2000)),
    CONSTRAINT work_calendar_visibility_principals_check CHECK (__tenant_schema__.work_projection_principals_valid_v1(visible_to_principals, (state = 'VISIBLE'::text)))
);


