--
-- Name: work_inbox_query_v1; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.work_inbox_query_v1 AS
 SELECT task.id,
    'WORK'::text AS source_owner,
    'TASK'::text AS source_kind,
    task.id AS source_id,
    task.id AS source_version_id,
    task.row_version AS source_revision,
    (0)::bigint AS permission_revision,
    task.title AS summary,
    "normalize"(casefold(("normalize"(task.title, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS summary_folded,
    task.due_at,
    task.board_id,
    task.status_category AS status,
    task.priority,
    task.updated_at,
    assignee.visibility_principals,
    board_visibility.visibility_principals AS context_principals
   FROM ((__tenant_schema__.work_tasks task
     JOIN __tenant_schema__.work_query_board_visibility_v1 board_visibility ON ((board_visibility.board_id = task.board_id)))
     JOIN LATERAL ( SELECT array_agg(((assignee_row.principal_kind || ':'::text) || (assignee_row.principal_id)::text) ORDER BY assignee_row.principal_kind, assignee_row.principal_id) AS visibility_principals
           FROM __tenant_schema__.work_task_assignees assignee_row
          WHERE ((assignee_row.task_id = task.id) AND assignee_row.active)) assignee ON ((cardinality(assignee.visibility_principals) > 0)))
  WHERE ((task.deleted_at IS NULL) AND (NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)))
UNION ALL
 SELECT item.id,
    item.source_owner,
    item.source_kind,
    item.source_id,
    item.source_version_id,
    item.source_revision,
    item.permission_revision,
    item.summary,
    "normalize"(casefold(("normalize"(item.summary, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS summary_folded,
    item.due_at,
    NULL::uuid AS board_id,
    NULL::text AS status,
    NULL::text AS priority,
    item.updated_at,
    item.visible_to_principals AS visibility_principals,
    item.visible_to_principals AS context_principals
   FROM __tenant_schema__.work_inbox_items item
  WHERE ((item.state = 'VISIBLE'::text) AND (NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW __tenant_schema__.work_inbox_query_v1 OWNER TO harpy_owner;

--
-- Name: work_calendar_query_v1; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.work_calendar_query_v1 AS
 SELECT inbox.id,
    inbox.source_owner,
    inbox.source_kind,
    inbox.source_id,
    inbox.source_version_id,
    inbox.source_revision,
    inbox.permission_revision,
    inbox.summary,
    inbox.summary_folded,
    inbox.due_at,
    inbox.board_id,
    inbox.status,
    inbox.priority,
    inbox.updated_at,
    inbox.visibility_principals,
    inbox.context_principals,
    'TASK_DEADLINE'::text AS item_kind,
    inbox.due_at AS starts_at,
    NULL::timestamp with time zone AS ends_at,
    NULL::date AS start_date,
    NULL::date AS end_date
   FROM __tenant_schema__.work_inbox_query_v1 inbox
  WHERE ((inbox.source_owner = 'WORK'::text) AND (inbox.due_at IS NOT NULL))
UNION ALL
 SELECT event.id,
    'WORK'::text AS source_owner,
    'CALENDAR_EVENT'::text AS source_kind,
    event.id AS source_id,
    event.id AS source_version_id,
    event.row_version AS source_revision,
    (0)::bigint AS permission_revision,
    event.title AS summary,
    event.title_folded AS summary_folded,
    NULL::timestamp with time zone AS due_at,
    event.board_id,
    NULL::text AS status,
    NULL::text AS priority,
    event.updated_at,
    event.visibility_principals,
    event.visibility_principals AS context_principals,
    'CALENDAR_EVENT'::text AS item_kind,
    event.starts_at,
    event.ends_at,
    event.start_date,
    event.end_date
   FROM __tenant_schema__.work_calendar_event_query_v1 event
UNION ALL
 SELECT item.id,
    item.source_owner,
    item.source_kind,
    item.source_id,
    item.source_version_id,
    item.source_revision,
    item.permission_revision,
    item.summary,
    "normalize"(casefold(("normalize"(item.summary, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS summary_folded,
    NULL::timestamp with time zone AS due_at,
    NULL::uuid AS board_id,
    NULL::text AS status,
    NULL::text AS priority,
    item.updated_at,
    item.visible_to_principals AS visibility_principals,
    item.visible_to_principals AS context_principals,
    'PROJECTION'::text AS item_kind,
    item.starts_at,
    item.ends_at,
    item.start_date,
    item.end_date
   FROM __tenant_schema__.work_calendar_items item
  WHERE ((item.state = 'VISIBLE'::text) AND (NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW __tenant_schema__.work_calendar_query_v1 OWNER TO harpy_owner;

