    blocker_count bigint NOT NULL,
    blocker_sha256 bytea NOT NULL,
    cooling_until timestamp with time zone NOT NULL,
    destructive_started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT work_purge_operations_blocker_count_check CHECK ((blocker_count >= 0)),
    CONSTRAINT work_purge_operations_blocker_sha256_check CHECK ((octet_length(blocker_sha256) = 32)),
    CONSTRAINT work_purge_operations_expected_reference_epoch_check CHECK ((expected_reference_epoch > 0)),
    CONSTRAINT work_purge_operations_reason_check CHECK (((octet_length(reason) >= 1) AND (octet_length(reason) <= 4000))),
    CONSTRAINT work_purge_operations_state_check CHECK ((state = ANY (ARRAY['COOLING'::text, 'CANCELLED'::text, 'EXECUTING'::text, 'SUCCEEDED'::text, 'FAILED'::text])))
);


