    approved_by uuid,
    created_at timestamp with time zone NOT NULL,
    decided_at timestamp with time zone,
    CONSTRAINT work_reverse_reconciliations_check CHECK ((requested_by IS DISTINCT FROM approved_by)),
    CONSTRAINT work_reverse_reconciliations_check1 CHECK ((((state = 'PENDING'::text) AND (approved_by IS NULL) AND (decided_at IS NULL)) OR ((state <> 'PENDING'::text) AND (approved_by IS NOT NULL) AND (decided_at IS NOT NULL)))),
    CONSTRAINT work_reverse_reconciliations_source_count_check CHECK ((source_count >= 0)),
    CONSTRAINT work_reverse_reconciliations_source_generation_check CHECK ((source_generation > 0)),
    CONSTRAINT work_reverse_reconciliations_source_sha256_check CHECK ((octet_length(source_sha256) = 32)),
    CONSTRAINT work_reverse_reconciliations_state_check CHECK ((state = ANY (ARRAY['PENDING'::text, 'ACCEPTED'::text, 'REJECTED'::text]))),
    CONSTRAINT work_reverse_reconciliations_target_count_check CHECK ((target_count >= 0)),
    CONSTRAINT work_reverse_reconciliations_target_generation_check CHECK ((target_generation > 0)),
    CONSTRAINT work_reverse_reconciliations_target_sha256_check CHECK ((octet_length(target_sha256) = 32))
);


