--
-- Name: work_task_query_v1; Type: VIEW; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE VIEW __tenant_schema__.work_task_query_v1 AS
 SELECT task.id,
    task.board_id,
    task.column_id,
    task.title,
    "normalize"(casefold(("normalize"(task.title, 'NFC'::text) COLLATE pg_unicode_fast)), 'NFC'::text) AS title_folded,
    task.description,
    task.task_kind AS kind,
    task.status_category AS status,
    task.priority,
    task.creator_user_id AS creator_id,
    task."position",
    task.row_version,
    task.starts_at,
    task.due_at,
    task.created_at,
    task.updated_at,
    visibility.visibility_principals
   FROM (__tenant_schema__.work_tasks task
     JOIN __tenant_schema__.work_query_board_visibility_v1 visibility ON ((visibility.board_id = task.board_id)))
  WHERE ((task.deleted_at IS NULL) AND (NOT (SESSION_USER IS DISTINCT FROM 'harpy_v2_runtime'::name)) AND (NOT (CURRENT_USER IS DISTINCT FROM 'harpy_runtime'::name)));


ALTER VIEW __tenant_schema__.work_task_query_v1 OWNER TO harpy_owner;

--
-- Name: work_v1_adoption_stage; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.work_v1_adoption_stage (
    operation_id uuid NOT NULL,
    run_id uuid NOT NULL,
    source_kind text NOT NULL,
    source_id uuid NOT NULL,
    target_kind text NOT NULL,
    target_id uuid NOT NULL,
    source_sha256 bytea NOT NULL,
    target_sha256 bytea NOT NULL,
    target_record jsonb NOT NULL,
    removed boolean NOT NULL,
    source_xid xid8 NOT NULL,
    commit_lsn pg_lsn NOT NULL,
    batch_ordinal integer NOT NULL,
    change_ordinal integer NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT work_v1_adoption_stage_batch_ordinal_check CHECK (((batch_ordinal >= 1) AND (batch_ordinal <= 2147483))),
    CONSTRAINT work_v1_adoption_stage_change_ordinal_check CHECK (((change_ordinal >= 1) AND (change_ordinal <= 1000))),
    CONSTRAINT work_v1_adoption_stage_source_kind_check CHECK ((source_kind = ANY (ARRAY['task_boards'::text, 'task_board_columns'::text, 'board_members'::text, 'board_tasks'::text, 'board_task_comments'::text, 'calendar_events'::text]))),
    CONSTRAINT work_v1_adoption_stage_source_sha256_check CHECK ((octet_length(source_sha256) = 32)),
    CONSTRAINT work_v1_adoption_stage_target_digest_check CHECK ((target_sha256 = sha256(convert_to((target_record)::text, 'UTF8'::name)))),
    CONSTRAINT work_v1_adoption_stage_target_kind_check CHECK ((target_kind = ANY (ARRAY['BOARD'::text, 'COLUMN'::text, 'MEMBERSHIP'::text, 'TASK'::text, 'ASSIGNEE'::text, 'LABEL'::text, 'TASK_LABEL'::text, 'CHECKLIST'::text, 'COMMENT'::text, 'CALENDAR'::text, 'RECURRENCE'::text, 'FORM_LINK'::text, 'WORKFLOW_PROJECTION'::text]))),
    CONSTRAINT work_v1_adoption_stage_target_record_check CHECK ((jsonb_typeof(target_record) = 'object'::text)),
    CONSTRAINT work_v1_adoption_stage_target_sha256_check CHECK ((octet_length(target_sha256) = 32))
);


ALTER TABLE __tenant_schema__.work_v1_adoption_stage OWNER TO harpy_owner;

--
-- Name: work_v1_writer_fence; Type: TABLE; Schema: __tenant_schema__; Owner: harpy_owner
--

CREATE TABLE __tenant_schema__.work_v1_writer_fence (
    singleton boolean NOT NULL,
    state text NOT NULL,
    run_id uuid,
    generation bigint,
    reverse_reconciliation_id uuid,
    updated_by uuid,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT work_v1_writer_fence_check CHECK ((((state = 'V1_ACTIVE'::text) AND (run_id IS NULL) AND (generation IS NULL) AND (reverse_reconciliation_id IS NULL) AND (updated_by IS NULL)) OR ((state = 'V2_FENCED'::text) AND (run_id IS NOT NULL) AND (generation IS NOT NULL) AND (reverse_reconciliation_id IS NULL) AND (updated_by IS NOT NULL)) OR ((state = 'V1_REOPENED'::text) AND (run_id IS NOT NULL) AND (generation IS NOT NULL) AND (reverse_reconciliation_id IS NOT NULL) AND (updated_by IS NOT NULL)) OR ((state = 'RETIRED'::text) AND (run_id IS NOT NULL) AND (generation IS NOT NULL) AND (reverse_reconciliation_id IS NULL) AND (updated_by IS NOT NULL)))),
    CONSTRAINT work_v1_writer_fence_generation_check CHECK (((generation IS NULL) OR (generation > 0))),
    CONSTRAINT work_v1_writer_fence_singleton_check CHECK (singleton),
    CONSTRAINT work_v1_writer_fence_state_check CHECK ((state = ANY (ARRAY['V1_ACTIVE'::text, 'V2_FENCED'::text, 'V1_REOPENED'::text, 'RETIRED'::text])))
);


ALTER TABLE __tenant_schema__.work_v1_writer_fence OWNER TO harpy_owner;

